def check_untracked_renders_use_source_fingerprints():
    """A host that stops committing its renders (doc_html RENDERS_TRACKED =
    False) cannot judge a page by the render's own hash: a render carries
    its build time and differs on every build (2026-10-04). The ledger then
    records a fingerprint of the sources. Both directions: a rebuild with
    the same sources stays published; a source edit makes the page
    unpublished."""
    import json as _json, tempfile
    sys.path.insert(0, str(ROOT / 'tools'))
    try:
        import doc_html as dh
    finally:
        sys.path.pop(0)
    name = 'untracked renders are judged by their sources, not their own hash'
    tmp = pathlib.Path(tempfile.mkdtemp())
    (tmp / 'a.md').write_text('# A\n')
    (tmp / 'a.html').write_text('<p>built at 1</p>')
    led = tmp / 'shared.json'
    saved = {k: getattr(dh, k) for k in ('ROOT', 'RENDER_LEDGER', 'THREAD_LEDGER', 'RENDERS_TRACKED',
             '_current_branch', '_default_branch', '_changed_vs_base', '_render_units')}
    cases = []
    try:
        dh.ROOT, dh.RENDER_LEDGER, dh.THREAD_LEDGER = tmp, str(led), None
        dh.RENDERS_TRACKED = False
        dh._current_branch = lambda: 'main'
        dh._default_branch = lambda: 'main'
        dh._changed_vs_base = lambda: set()
        dh._render_units = lambda: [('a.html', ['a.md'], 'https://shared.example/a')]
        import io, contextlib
        with contextlib.redirect_stdout(io.StringIO()):
            dh.record_published(['a.html'], trunk=True)
        rec = _json.loads(led.read_text()).get('a.html')
        cases.append(('the ledger records the source fingerprint, not the render hash',
                      rec == dh._fingerprint(['a.md']) and rec != dh._sha256(tmp / 'a.html')))
        (tmp / 'a.html').write_text('<p>built at 2</p>')
        cases.append(('a rebuild from the same sources stays published',
                      dh.stale(trunk=True)[1] == []))
        (tmp / 'a.md').write_text('# A, edited\n')
        (tmp / 'a.html').write_text('<p>built at 3</p>')
        cases.append(('a source edit makes the page unpublished',
                      [r for r, _u in dh.stale(trunk=True)[1]] == ['a.html']))
    finally:
        for k, v in saved.items():
            setattr(dh, k, v)
        shutil.rmtree(tmp, ignore_errors=True)
    failed = [n for n, ok in cases if not ok]
    check(f'{name} ({len(cases)} stated cases)', not failed, '; '.join(failed))


def check_update_deletes_a_shipped_voice_md():
    """An update deletes a root VOICE.md that is still the shipped template
    (comments aside) and drops its process/manifest.json entry, and asks for
    a conversion only when it carries real edits (2026-10-01: a consumer's
    unchanged VOICE.md became a practice file of `<undecided>` sections, and
    its leftover manifest entry failed practice_audit at staging)."""
    import tempfile
    import precedent_update as pu
    cases = []
    tmp = pathlib.Path(tempfile.mkdtemp(prefix='shipped-voice-'))
    rev = subprocess.run(['git', '-C', str(ROOT), 'rev-parse', 'HEAD'],
                         capture_output=True, text=True).stdout.strip()
    shipped = subprocess.run(['git', '-C', str(ROOT), 'show',
                              '41594ce8:templates/VOICE.md.template'],
                             capture_output=True, text=True).stdout
    try:
        if not shipped:
            cases.append(('this clone has the 2026-08-16 VOICE.md template '
                          '(a shallow clone needs --unshallow)', False, ''))
            raise RuntimeError('no history')
        env = dict(os.environ, GIT_AUTHOR_NAME='t', GIT_AUTHOR_EMAIL='t@t',
                   GIT_COMMITTER_NAME='t', GIT_COMMITTER_EMAIL='t@t')

        def repo(name, voice):
            r = tmp / name
            (r / 'process').mkdir(parents=True)
            (r / 'VOICE.md').write_text(voice, encoding='utf-8')
            (r / 'process' / 'manifest.json').write_text(json.dumps({'entries': [
                {'practice': 'voice', 'local_path': 'VOICE.md'},
                {'practice': 'other', 'local_path': 'X.md'}]}), encoding='utf-8')
            subprocess.run(['git', 'init', '-q', str(r)], env=env)
            subprocess.run(['git', '-C', str(r), 'add', '-A'], env=env)
            subprocess.run(['git', '-C', str(r), 'commit', '-qm', 'i'], env=env)
            return r
        # The install wrote the template without its header comment.
        body = pu._HTML_COMMENT.sub('', shipped).lstrip()
        same = repo('same', body)
        left = pu.legacy_root_docs(same, rev)
        entries = json.loads((same / 'process' / 'manifest.json').read_text())['entries']
        cases.append(('an unchanged VOICE.md is deleted, not left to convert',
                      not (same / 'VOICE.md').exists() and left == [], str(left)))
        cases.append(('...and its manifest entry goes, the rest stay',
                      [e['practice'] for e in entries] == ['other'], str(entries)))
        edited = repo('edited', body.replace('a sharp colleague typing quickly',
                                             'a calm, formal narrator'))
        left = pu.legacy_root_docs(edited, rev)
        cases.append(('an edited VOICE.md is kept and asked to be converted',
                      (edited / 'VOICE.md').exists()
                      and any(o == 'VOICE.md' and 'convert' in w for o, w in left),
                      str(left)))
    except RuntimeError:
        pass
    finally:
        shutil.rmtree(tmp, ignore_errors=True)
    bad = [(c[0], c[2]) for c in cases if not c[1]]
    check(f'an update deletes a shipped, unchanged VOICE.md and asks to convert '
          f'only real edits ({len(cases)} stated cases)', not bad,
          '; '.join(f"{n} -- {d[:300]}" for n, d in bad))


def check_practice_set_workflows_converge():
    """A practice set's refresh removes a workflow nobody approved, keeps one
    the person approved, and asks only when genuinely in doubt: a file that
    runs something nothing local runs is held, and the session is told to
    ask keep or delete (2026-10-01). Before, a set "ran its own on purpose"
    and a leftover there was never cleared (Morgan: solve it "in the
    update, not just this file but others"; "Ask if genuinely in doubt")."""
    import contextlib, io, shutil, tempfile, hashlib
    sys.path.insert(0, str(ROOT / 'tools'))
    import precedent_vendor_engine as pve
    tmp = pathlib.Path(tempfile.mkdtemp(prefix='set-converge-'))
    cases = [('a practice set\'s CI converges', 'source' in pve.CI_CONVERGES_KINDS, '')]
    try:
        dest = tmp / 'set'
        wfs = dest / '.github' / 'workflows'
        wfs.mkdir(parents=True)
        git = lambda *a: subprocess.run(['git', '-C', str(dest), *a],
                                        capture_output=True, text=True)
        git('init', '-q')
        git('config', 'user.name', 'Test')
        git('config', 'user.email', 'test@example.com')
        left = wfs / 'leftover.yml'
        left.write_text('on: push\njobs:\n  x:\n    runs-on: ubuntu-latest\n'
                        '    steps:\n      - uses: actions/checkout@v4\n', encoding='utf-8')
        kept = wfs / 'button.yml'
        kept.write_text('on: workflow_dispatch\njobs:\n  x:\n    runs-on: ubuntu-latest\n'
                        '    steps:\n      - uses: actions/checkout@v4\n', encoding='utf-8')
        (dest / 'precedent.json').write_text(json.dumps({'github_ci_approved': {
            '.github/workflows/button.yml': {
                'sha256': hashlib.sha256(kept.read_bytes()).hexdigest(),
                'approved_by': 'Dana, 2026-09-25: "keep the button"'}}}), encoding='utf-8')
        git('add', '-A')
        git('commit', '-q', '-m', 'seed\n\nSession: none available (test)')
        pve._LEFT_FOR_YOU.clear()
        with contextlib.redirect_stdout(io.StringIO()):
            removed = pve._remove_unapproved_workflows(dest, {}, 'source', None)
        cases.append(('a set\'s unapproved workflow is removed by the refresh',
                      not left.exists() and '.github/workflows/leftover.yml' in removed,
                      repr(removed)))
        cases.append(('...and one the person approved in their own words is kept '
                      '(their answer, once asked)', kept.exists(), repr(removed)))
        # Genuinely in doubt: it runs something the set's own checks do not.
        # Held, and the session is told to ask (2026-10-01).
        own = wfs / 'own.yml'
        wfs.mkdir(parents=True, exist_ok=True)
        own.write_text('on: push\njobs:\n  x:\n    runs-on: ubuntu-latest\n'
                       '    steps:\n      - run: python3 tools/zz_only_here.py\n',
                       encoding='utf-8')
        git('add', '-A')
        git('commit', '-q', '-m', 'own\n\nSession: none available (test)')
        pve._LEFT_FOR_YOU.clear()
        with contextlib.redirect_stdout(io.StringIO()):
            removed = pve._remove_unapproved_workflows(dest, {}, 'source', None)
        said = ' '.join(str(x) for x in pve._LEFT_FOR_YOU)
        cases.append(('a workflow running something nothing local runs is kept, '
                      'and the session is told to ask the person',
                      own.exists() and 'ASK THE PERSON' in said, said[:300]))
        pve._KEPT_LOUD.clear()
    finally:
        pve._LEFT_FOR_YOU.clear()
        shutil.rmtree(tmp, ignore_errors=True)
    bad = [(c[0], c[2]) for c in cases if not c[1]]
    check(f'a practice set\'s workflows converge, asking only when in doubt '
          f'({len(cases)} stated cases)',
          not bad, '; '.join(f"{n} -- {d[:300]}" for n, d in bad))


def check_worktree_snapshot_needs_no_git_identity():
    """_ref_including_worktree() snapshots a dirty tree with no git identity
    anywhere -- empty $HOME, no global or system config -- the shape of the
    isolated --as-ci run and of GitHub's runner (2026-09-30: a full check
    failed with "Author identity unknown" and named no test)."""
    import tempfile
    cases = []
    tmp = pathlib.Path(tempfile.mkdtemp(prefix='snapshot-identity-'))
    saved = {k: os.environ.get(k) for k in ('HOME', 'GIT_CONFIG_NOSYSTEM',
                                              'GIT_CONFIG_GLOBAL', 'GIT_AUTHOR_NAME',
                                              'GIT_AUTHOR_EMAIL', 'GIT_COMMITTER_NAME',
                                              'GIT_COMMITTER_EMAIL', 'EMAIL')}
    try:
        repo = tmp / 'r'
        repo.mkdir()
        env = dict(os.environ, GIT_AUTHOR_NAME='t', GIT_AUTHOR_EMAIL='t@t',
                   GIT_COMMITTER_NAME='t', GIT_COMMITTER_EMAIL='t@t')
        subprocess.run(['git', 'init', '-q', str(repo)], env=env)
        (repo / 'a.txt').write_text('one\n', encoding='utf-8')
        subprocess.run(['git', '-C', str(repo), 'add', '-A'], env=env)
        subprocess.run(['git', '-C', str(repo), '-c', 'user.name=t', '-c',
                        'user.email=t@t', 'commit', '-qm', 'base'], env=env)
        (repo / 'b.txt').write_text('new\n', encoding='utf-8')
        os.environ.update(HOME=str(tmp / 'empty-home'), GIT_CONFIG_NOSYSTEM='1',
                          GIT_CONFIG_GLOBAL=os.devnull)
        for k in ('GIT_AUTHOR_NAME', 'GIT_AUTHOR_EMAIL', 'GIT_COMMITTER_NAME',
                  'GIT_COMMITTER_EMAIL', 'EMAIL'):
            os.environ.pop(k, None)
        try:
            ref = _ref_including_worktree(repo)
            ok, det = True, ref
        except SystemExit as e:
            ok, det = False, str(e)
        cases.append(('a dirty tree is snapshotted with no identity configured',
                      ok, det[-200:]))
        if ok:
            listed = subprocess.run(['git', '-C', str(repo), 'ls-tree', '--name-only',
                                     ref], capture_output=True, text=True).stdout.split()
            cases.append(('...and the snapshot holds the new file',
                          'b.txt' in listed, str(listed)))
    finally:
        for k, v in saved.items():
            if v is None:
                os.environ.pop(k, None)
            else:
                os.environ[k] = v
        shutil.rmtree(tmp, ignore_errors=True)
    # ...and when a shard does fail, the push check's report names it.
    import precedent_push_check as ppc
    out = ['  SHARD FAILED (exit 1)', '  last 20 line(s) of its stderr:',
           '      SKIP (filtered out by PRECEDENT_CHECK_ONLY/SKIP): check_x',
           '    verify_harness FAIL: could not create a scratch commit: why',
           '    *** Please tell me who you are.']
    found = ppc._finding_lines(out)
    cases.append(('the push check\'s report picks a failed shard and its reason',
                  out[0] in found and out[3] in found and out[2] not in found,
                  str(found), ))
    bad = [(c[0], c[2]) for c in cases if not c[1]]
    check(f'the working-tree snapshot needs no git identity ({len(cases)} stated cases)',
          not bad, '; '.join(f"{n} -- {d}" for n, d in bad))


def check_workflow_growth_needs_the_persons_words():
    """ci-workflow-approved, everywhere: a change that makes a workflow or a
    workflow template run more -- a new event, branch, type, schedule or
    job, or a narrowing filter dropped -- is refused until the person's
    words are pinned to its content; a fix that adds no CI work passes
    (Morgan, 2026-09-30: permission is for adding workflows or CI minutes,
    and "we clearly shouldn't have broken workflows"). Until then nothing
    pinned BestPractice's own templates at all."""
    import tempfile, hashlib
    import precedent_check as pc
    cases = []
    base = ('on:\n  pull_request:\n    branches: [main]\n    types: [opened]\n'
            '  push:\n    branches: [main]\n'
            'jobs:\n  check:\n    runs-on: ubuntu-latest\n    steps:\n'
            '      - run: python3 tools/x.py\n')
    for name, after, grows in (
            ('a fixed path in a step', base.replace('tools/x.py', 'tools/y.py'), False),
            ('a comment', '# why\n' + base, False),
            ('a branch added', base.replace('branches: [main]\n    types',
                                            'branches: [main, dev]\n    types'), True),
            ('a type added', base.replace('[opened]', '[opened, synchronize]'), True),
            ('a push filter dropped', base.replace('  push:\n    branches: [main]\n',
                                                   '  push:\n'), True),
            ('a schedule added', base.replace('  push:\n', '  schedule:\n    - cron: "0 3 * * *"\n  push:\n'), True),
            ('a job added', base + '  more:\n    runs-on: ubuntu-latest\n', True),
            ('an event removed', base.replace('  push:\n    branches: [main]\n', ''), False)):
        got = pc._workflow_growth(base, after)
        cases.append((f'{name}: {"grows" if grows else "adds no CI work"}',
                      bool(got) == grows, str(got)))
    cases.append(('a new workflow is all growth', bool(pc._workflow_growth(None, base)), ''))

    tmp = pathlib.Path(tempfile.mkdtemp(prefix='workflow-growth-'))
    try:
        repo = tmp / 'proj'
        (repo / 'tools').mkdir(parents=True)
        for f in list((ROOT / 'tools').glob('*.py')) + list((ROOT / 'tools').glob('*.json')):
            shutil.copy(f, repo / 'tools' / f.name)
        up = repo / 'process' / 'upstream'
        (up / 'practices').mkdir(parents=True)
        shutil.copy(ROOT / 'practices' / 'ci-workflow-approved.md', up / 'practices')
        cfg = {'sources': [{'level': 'universal', 'name': 'precedent',
                            'path': 'process/upstream'}]}
        (repo / 'precedent.json').write_text(json.dumps(cfg), encoding='utf-8')
        tpl = repo / 'templates' / 'github-actions' / 'w.yml.template'
        tpl.parent.mkdir(parents=True)
        tpl.write_text(base, encoding='utf-8')
        env = dict(os.environ, GIT_AUTHOR_NAME='t', GIT_AUTHOR_EMAIL='t@t',
                   GIT_COMMITTER_NAME='t', GIT_COMMITTER_EMAIL='t@t')

        def g(*a):
            return subprocess.run(['git', '-C', str(repo), *a], capture_output=True,
                                  text=True, env=env)

        def run():
            r = subprocess.run([sys.executable, 'tools/precedent_check.py', '--only',
                                'ci-workflow-approved'], cwd=str(repo),
                               capture_output=True, text=True, env=env, timeout=300)
            return r.returncode, r.stdout + r.stderr
        g('init', '-q', '-b', 'main'); g('add', '-A'); g('commit', '-qm', 'base')
        g('update-ref', 'refs/remotes/origin/main', 'HEAD')
        g('symbolic-ref', 'refs/remotes/origin/HEAD', 'refs/remotes/origin/main')
        g('checkout', '-q', '-b', 'work')
        tpl.write_text(base.replace('tools/x.py', 'tools/y.py'), encoding='utf-8')
        g('commit', '-qam', 'fix a path')
        rc, out = run()
        cases.append(('a template fix that adds no CI work passes', rc == 0, out[-300:]))
        tpl.write_text(base + '  more:\n    runs-on: ubuntu-latest\n', encoding='utf-8')
        g('commit', '-qam', 'add a job')
        rc, out = run()
        cases.append(('a template given a new job is refused, naming it',
                      rc == 1 and 'job:more' in out, out[-400:]))
        cfg['github_ci_approved'] = {'templates/github-actions/w.yml.template': {
            'sha256': hashlib.sha256(tpl.read_bytes()).hexdigest(),
            'approved_by': 'Dana, 2026-09-30: "yes, add the second job"'}}
        (repo / 'precedent.json').write_text(json.dumps(cfg), encoding='utf-8')
        g('commit', '-qam', 'approved')
        rc, out = run()
        cases.append(('...and passes once the person\'s words are pinned to it',
                      rc == 0, out[-300:]))
    finally:
        shutil.rmtree(tmp, ignore_errors=True)
    bad = [(c[0], c[2]) for c in cases if not c[1]]
    check(f'a workflow change that adds CI work needs the person\'s words, and a '
          f'fix does not ({len(cases)} stated cases)', not bad,
          '; '.join(f"{n} -- {d[:300]}" for n, d in bad))


def check_todo_migrate_refuses_a_subdirectory():
    """todo_migrate.py writes only into the repository root's todo/.

    2026-10-01, from a consumer's Update Vendors: `--repo docs` wrote 33
    items under docs/todo/, which build_todo_index.py and every check never
    read, and they sat invisible for 13 days. A --repo below the root is
    refused before anything is written; the root itself still migrates."""
    import tempfile
    tmp = pathlib.Path(tempfile.mkdtemp(prefix='todo-migrate-root-'))
    cases = []
    try:
        repo = tmp / 'proj'
        (repo / 'docs').mkdir(parents=True)
        subprocess.run(['git', 'init', '-q', str(repo)], capture_output=True)
        (repo / 'docs' / 'TODO.md').write_text(
            '# TODO\n\n- **An item** -- something to do.\n', encoding='utf-8')
        r = subprocess.run([sys.executable, str(ROOT / 'tools' / 'todo_migrate.py'),
                            '--repo', str(repo / 'docs'), '--source', 'todo.md',
                            '--apply'], capture_output=True, text=True, timeout=120)
        cases.append(('a --repo below the repository root is refused',
                      r.returncode != 0 and 'not the repository root' in
                      (r.stdout + r.stderr), (r.stdout + r.stderr)[-300:]))
        cases.append(('...and writes nothing',
                      not (repo / 'docs' / 'todo').exists(), ''))
    finally:
        shutil.rmtree(tmp, ignore_errors=True)
    bad = [(n, d) for n, ok, d in cases if not ok]
    check(f'todo_migrate.py refuses to write items below the repository root '
          f'({len(cases)} stated cases)', not bad,
          '; '.join(f'{n}: {d}' for n, d in bad))


def check_docs_name_no_path_this_repo_removed():
    """change-updates-its-docs: a live document naming a path this repo's
    history deleted is refused, in plain text and as a link to this repo's
    own branch; history is left alone (2026-09-30: a session found a section
    describing a retired workflow and left it, as "a doc fix, not a broken
    path"). A path this repo never had -- a consumer's layout, another
    repo's file -- is never flagged."""
    import tempfile
    cases = []
    tmp = pathlib.Path(tempfile.mkdtemp(prefix='removed-paths-'))
    gone = 'docs/old/guide.md'
    try:
        repo = tmp / 'proj'
        (repo / 'tools').mkdir(parents=True)
        for f in list((ROOT / 'tools').glob('*.py')) + list((ROOT / 'tools').glob('*.json')):
            shutil.copy(f, repo / 'tools' / f.name)
        up = repo / 'process' / 'upstream'
        (up / 'practices').mkdir(parents=True)
        shutil.copy(ROOT / 'practices' / 'change-updates-its-docs.md', up / 'practices')
        (repo / 'precedent.json').write_text(json.dumps({
            'sources': [{'level': 'universal', 'name': 'precedent',
                         'path': 'process/upstream'}]}), encoding='utf-8')
        (repo / gone).parent.mkdir(parents=True)
        (repo / gone).write_text('old\n', encoding='utf-8')
        files = {
            'README.md': f'Read `{gone}` first.\n',
            'docs/link.md': f'[guide](https://github.com/acme/widget/blob/main/{gone})\n',
            'docs/other-repo.md': f'[theirs](https://github.com/else/where/blob/main/{gone})\n',
            'docs/retired.md': f'`{gone}` (retired 2026-09-01) is gone.\n',
            'docs/story.md': f'# X\n## Story\nWe read `{gone}`.\n',
            'docs/plan.md': f'---\nkind: plan\nstatus: closed\n---\nEdit `{gone}`.\n',
            'docs/consumer.md': 'A consumer keeps `local/practices/x.md`.\n',
            # The sentence says it, wrapped onto the next line (2026-10-01).
            'docs/wrapped.md': f'The checker that lived in `{gone}`\nwas retired on 2026-09-01.\n',
            # ...but a NEXT sentence that says "was" excuses nothing.
            'docs/adjacent.md': f'Read `{gone}` first.\nThis was a fine design.\n',
        }
        for rel, text in files.items():
            (repo / rel).parent.mkdir(parents=True, exist_ok=True)
            (repo / rel).write_text(text, encoding='utf-8')
        env = dict(os.environ, GIT_AUTHOR_NAME='t', GIT_AUTHOR_EMAIL='t@t',
                   GIT_COMMITTER_NAME='t', GIT_COMMITTER_EMAIL='t@t')

        def g(*a):
            return subprocess.run(['git', '-C', str(repo), *a], capture_output=True,
                                  text=True, env=env)

        def run():
            r = subprocess.run([sys.executable, 'tools/precedent_check.py', '--only',
                                'change-updates-its-docs'], cwd=str(repo),
                               capture_output=True, text=True, env=env, timeout=300)
            return r.returncode, r.stdout + r.stderr
        g('init', '-q', '-b', 'main'); g('add', '-A'); g('commit', '-qm', 'base')
        g('remote', 'add', 'origin', 'https://github.com/acme/widget')
        rc, out = run()
        cases.append(('nothing deleted yet: nothing to judge', rc == 0
                      and 'README.md:1' not in out, out[-300:]))
        g('rm', '-q', gone); g('commit', '-qm', 'delete the guide')
        rc, out = run()
        cases.append(('a live document naming the deleted path is refused',
                      rc == 1 and 'README.md:1' in out, out[-400:]))
        cases.append(('...and so is a link to it on this repo\'s own branch',
                      'docs/link.md:1' in out, out[-400:]))
        for rel, why in (('docs/other-repo.md', 'the same path in another repo'),
                         ('docs/retired.md', 'a line that says it was retired'),
                         ('docs/story.md', 'a Story section'),
                         ('docs/plan.md', 'a closed document'),
                         ('docs/consumer.md', 'a path this repo never had'),
                         ('docs/wrapped.md', 'a sentence wrapped so "retired" is '
                                             'on the next line')):
            cases.append((f'{why} is left alone', rel not in out, out[-400:]))
        cases.append(('a "was" in the next sentence excuses nothing',
                      'docs/adjacent.md:1' in out, out[-400:]))
    finally:
        shutil.rmtree(tmp, ignore_errors=True)
    bad = [(c[0], c[2]) for c in cases if not c[1]]
    check(f'a live document naming a path this repo removed is refused, and '
          f'history is not ({len(cases)} stated cases)', not bad,
          '; '.join(f"{n} -- {d[:300]}" for n, d in bad))


def check_loader_caps_unmeasured_without_a_declared_source():
    """loader-within-caps says COULD NOT VERIFY, never a violation and never a
    pass, where a declared source is not on disk (2026-09-30).

    A consumer's GitHub test runs on a bare checkout, with none of the
    sibling practice sets it declares. `build_views.py --budgets` only reads,
    but it fell through to the refusal meant for WRITING a block from an
    incomplete set, so the test failed on every private consumer that
    declares a shared set. Nothing caught it here: BestPractice is public,
    so its own loader block leaves every private source out and never needs
    one on disk. A throwaway private consumer, run through the real tools."""
    import tempfile
    cases = []
    tmp = pathlib.Path(tempfile.mkdtemp(prefix='caps-unmeasured-'))
    try:
        c = tmp / 'consumer'
        (c / 'tools').mkdir(parents=True)
        for f in list((ROOT / 'tools').glob('*.py')) + list((ROOT / 'tools').glob('*.json')):
            shutil.copy(f, c / 'tools' / f.name)
        shutil.copytree(ROOT / 'practices', c / 'up' / 'practices')
        (c / 'precedent.json').write_text(json.dumps({'visibility': 'private', 'sources': [
            {'level': 'universal', 'name': 'precedent', 'path': 'up'},
            {'level': 'shared', 'name': 'precedent-shared-missing',
             'path': '../precedent-shared-missing'}]}), encoding='utf-8')
        (c / 'AGENTS.md').write_text('# Notes\n\n<!-- BEGIN GENERATED: precedent-loader -->\n'
                                     '<!-- END GENERATED -->\n', encoding='utf-8')
        env = dict(os.environ, GIT_AUTHOR_NAME='t', GIT_AUTHOR_EMAIL='t@t',
                   GIT_COMMITTER_NAME='t', GIT_COMMITTER_EMAIL='t@t')
        subprocess.run(['git', 'init', '-q'], cwd=c, env=env)
        subprocess.run(['git', 'add', '-A'], cwd=c, env=env)
        subprocess.run(['git', 'commit', '-qm', 'x'], cwd=c, env=env)
        r = subprocess.run([sys.executable, 'tools/build_views.py', '--budgets',
                            '--agents-only'], cwd=c, capture_output=True, text=True,
                           timeout=300)
        cases.append(('--budgets only reads: exit 0 and says it measured nothing',
                      r.returncode == 0 and 'budgets NOT VERIFIED' in r.stdout,
                      (r.stdout + r.stderr)[-300:]))
        r = subprocess.run([sys.executable, 'tools/precedent_check.py', '--only',
                            'loader-within-caps'], cwd=c, capture_output=True,
                           text=True, timeout=300)
        out = r.stdout + r.stderr
        cases.append(('loader-within-caps is not violated', '0 violated' in out, out[-400:]))
        cases.append(('...and says COULD NOT VERIFY, not a pass',
                      'COULD NOT VERIFY  loader-within-caps' in out, out[-400:]))
    finally:
        shutil.rmtree(tmp, ignore_errors=True)
    bad = [(c[0], c[2]) for c in cases if not c[1]]
    check(f'loader-within-caps cannot verify without a declared source, and says so '
          f'({len(cases)} stated cases)', not bad,
          '; '.join(f"{n} -- {d[:300]}" for n, d in bad))


def check_received_hooks_and_moved_engine_files():
    """A consumer's vendored hooks count as received, and a mirrored engine
    file that lives on in its own tools/ is moved, not gone (2026-09-30).

    Found in a real consumer after an Update Vendors that crossed the
    catalogue copy leaving tools/ out: the push check's rename-updates-links
    asked it to repoint `process/upstream/tools/precedent_push_check.py` in
    two vendored hooks (which the next refresh overwrites) and in its own
    tools/bootstrap.sh (template text naming a guarded fallback). Nothing
    caught it upstream because received_owners() was only ever tested on
    tools/ files, and rename-updates-links only on this repo's own layout.

    A throwaway consumer, run through precedent_check.py itself. CONTROL: a
    README naming a mirrored tool that has NO copy in tools/ is still
    reported, so the quiet cases come from the fix, not a blind check."""
    import tempfile
    import precedent_practice_refs as ppr
    cases = []
    tmp = pathlib.Path(tempfile.mkdtemp(prefix='received-hooks-'))
    try:
        repo = tmp / 'consumer'
        (repo / 'tools').mkdir(parents=True)
        for f in (ROOT / 'tools').glob('*.py'):
            shutil.copy(f, repo / 'tools' / f.name)
        (repo / 'tools' / 'ENGINE_MANIFEST.json').write_text(json.dumps({
            'kind': 'consumer', 'files': ['precedent_push_check.py'],
            'hook_files': ['push-check-gate.sh'],
            'engine_paths': {'bootstrap/commit-identity.sh': 'x'},
            'ci_workflow_files': ['.github/workflows/light-check.yml']}), encoding='utf-8')
        (repo / 'precedent.json').write_text(json.dumps({'sources': {'precedent': {
            'level': 'universal', 'name': 'precedent', 'path': 'process/upstream'}}}),
            encoding='utf-8')
        up = repo / 'process' / 'upstream' / 'tools'
        up.mkdir(parents=True)
        (up.parent / 'practices').mkdir()
        shutil.copy(ROOT / 'practices' / 'rename-updates-links.md',
                    up.parent / 'practices' / 'rename-updates-links.md')
        (up / 'precedent_push_check.py').write_text('# mirrored\n', encoding='utf-8')
        (up / 'gone_tool.py').write_text('# mirrored, no copy in tools/\n', encoding='utf-8')
        fallback = ('for c in tools/precedent_push_check.py '
                    'process/upstream/tools/precedent_push_check.py; do :; done\n')
        (repo / '.claude' / 'hooks').mkdir(parents=True)
        (repo / '.claude' / 'hooks' / 'push-check-gate.sh').write_text(fallback, encoding='utf-8')
        (repo / 'tools' / 'bootstrap.sh').write_text(fallback, encoding='utf-8')
        # ...but an unguarded call in a script of the repo's own is a step
        # that stops running (2026-10-01).
        (repo / 'tools' / 'steps.sh').write_text(
            'python3 process/upstream/tools/precedent_push_check.py\n', encoding='utf-8')
        (repo / 'README.md').write_text('See process/upstream/tools/gone_tool.py.\n',
                                        encoding='utf-8')
        # A command, not a fallback (2026-10-01, from a consumer's Update
        # Vendors): it fails "No such file" once the mirror is gone.
        (repo / 'AGENTS.md').write_text(
            'Before pushing, run `python3 process/upstream/tools/precedent_push_check.py`.\n',
            encoding='utf-8')
        (repo / '.claude' / 'settings.json').write_text(json.dumps({'permissions': {
            'allow': ['Bash(python3 process/upstream/tools/precedent_push_check.py:*)']}},
            indent=2) + '\n', encoding='utf-8')
        owners = ppr.received_owners(repo)
        cases.append(('a vendored hook is received',
                      ppr.received_owner('.claude/hooks/push-check-gate.sh', owners)
                      == 'the vendored engine', str(owners.get('.claude/hooks/push-check-gate.sh'))))
        cases.append(('a declared engine path is received',
                      ppr.received_owner('bootstrap/commit-identity.sh', owners) is not None, ''))
        cases.append(('a CI workflow is not, so ci-workflow-approved still judges it',
                      ppr.received_owner('.github/workflows/light-check.yml', owners) is None, ''))
        cases.append(('tools/bootstrap.sh stays the repo\'s own',
                      ppr.received_owner('tools/bootstrap.sh', owners) is None, ''))

        env = dict(os.environ, GIT_AUTHOR_NAME='t', GIT_AUTHOR_EMAIL='t@t',
                   GIT_COMMITTER_NAME='t', GIT_COMMITTER_EMAIL='t@t')

        def g(*a):
            return subprocess.run(['git', '-C', str(repo), *a], capture_output=True,
                                  text=True, env=env)
        g('init', '-q', '-b', 'main'); g('add', '-A'); g('commit', '-qm', 'base')
        g('update-ref', 'refs/remotes/origin/main', 'HEAD')
        g('symbolic-ref', 'refs/remotes/origin/HEAD', 'refs/remotes/origin/main')
        g('checkout', '-q', '-b', 'update-vendors')
        g('rm', '-rq', 'process/upstream/tools'); g('commit', '-qm', 'the hop')
        r = subprocess.run([sys.executable, 'tools/precedent_check.py', '--only',
                            'rename-updates-links'], cwd=str(repo), capture_output=True,
                           text=True, env=env, timeout=300)
        out = r.stdout + r.stderr
        cases.append(('the vendored hook\'s fallback is not a finding',
                      '.claude/hooks/push-check-gate.sh' not in out, out[-500:]))
        cases.append(('nor is tools/bootstrap.sh\'s, since tools/ carries the file',
                      'tools/bootstrap.sh:' not in out, out[-500:]))
        cases.append(('CONTROL: a mirrored tool with no copy in tools/ is still reported',
                      'README.md:1' in out and 'gone_tool.py' in out, out[-500:]))
        cases.append(('an AGENTS.md command naming the moved file is reported, '
                      'with where it is now',
                      'AGENTS.md:1' in out and 'is at tools/precedent_push_check.py now'
                      in out, out[-800:]))
        cases.append(('...and so is a .claude/settings.json allowlist entry',
                      '.claude/settings.json:' in out, out[-800:]))
        cases.append(('...and an unguarded call in the repo\'s own shell script',
                      'tools/steps.sh:1' in out, out[-800:]))
    finally:
        shutil.rmtree(tmp, ignore_errors=True)
    bad = [(c[0], c[2]) for c in cases if not c[1]]
    check(f'vendored hooks are received, and an engine file moved to tools/ '
          f'is not gone ({len(cases)} stated cases)',
          not bad, '; '.join(f"{n} -- {d[:400]}" for n, d in bad))


def check_whats_new_log_mechanics():
    """tools/precedent_whats_new.py, the mechanics behind "What's new?"
    (practice: whats-new, 2026-09-30).

    A throwaway repository with main's history on chosen days (UTC, the
    repo's declared zone): a day with a change, an empty day, a day whose
    only commit touches the log itself, and a day that adds a document.
    Stated cases: the first run lists exactly the two real days, newest
    document named, and names the quiet ones; an entry's heading carries
    its weekday, --check flags an entry not in the shape (heading, opening
    line, a bold key phrase per bullet), and headline case leaves the
    slug alone; --mark covers them and a second run lists none; a day
    that has not finished cannot be marked; the later of this checkout's
    log and main's is read; an entry naming an approval is flagged; the
    log never ships to another project."""
    import datetime as _dt, tempfile
    import precedent_whats_new as pwn
    import checkin as _ck
    cases = []
    tmp = pathlib.Path(tempfile.mkdtemp(prefix='whats-new-'))
    today = _dt.date(2026, 9, 10)
    try:
        origin, repo = tmp / 'origin.git', tmp / 'repo'

        def g(cwd, *a, when=None):
            env = dict(os.environ, GIT_AUTHOR_NAME='t', GIT_AUTHOR_EMAIL='t@t',
                       GIT_COMMITTER_NAME='t', GIT_COMMITTER_EMAIL='t@t')
            if when:
                env['GIT_AUTHOR_DATE'] = env['GIT_COMMITTER_DATE'] = when
            return subprocess.run(['git', '-C', str(cwd), *a], capture_output=True,
                                  text=True, env=env).stdout.strip()

        def commit(rel, text, msg, when):
            p = repo / rel
            p.parent.mkdir(parents=True, exist_ok=True)
            p.write_text(text, encoding='utf-8')
            g(repo, 'add', '-A'); g(repo, 'commit', '-qm', msg, when=when)

        g(tmp, 'init', '-q', '--bare', '-b', 'main', str(origin))
        g(tmp, 'init', '-q', '-b', 'main', str(repo))
        g(repo, 'remote', 'add', 'origin', str(origin))
        (repo / 'precedent.json').write_text('{"fallback_timezone": "UTC"}\n',
                                             encoding='utf-8')
        commit('a.txt', '0', 'before the window', '2026-08-01T12:00:00Z')
        commit('a.txt', '1', 'Faster start-up', '2026-09-05T12:00:00Z')
        # 2026-09-06: nothing.
        commit('WHATS_NEW.md', '# What\'s new\n', 'Log only', '2026-09-07T12:00:00Z')
        commit('docs/PHILOSOPHY.md', 'why\n', 'A new philosophy note', '2026-09-08T12:00:00Z')
        g(repo, 'push', '-q', 'origin', 'main')
        g(repo, 'fetch', '-q', 'origin')

        _tz, through, days = pwn.missing_days(repo, today=today)
        got = [d.isoformat() for d, _ in days]
        cases.append(('the first run lists only the days main changed, the log\'s own '
                      'commit left out', got == ['2026-09-05', '2026-09-08'], str(got)))
        _tz, _t, back = pwn.missing_days(repo, today=today, since=_dt.date(2026, 8, 1))
        got_back = [d.isoformat() for d, _ in back]
        cases.append(('--since backfills a first run from the day it names',
                      got_back == ['2026-08-01', '2026-09-05', '2026-09-08'], str(got_back)))
        _tz, _t, _active, quiet = pwn.scan_days(repo, today=today)
        got_quiet = [d.isoformat() for d in quiet]
        cases.append(('a quiet day, and one whose only change is the log, is named '
                      'as quiet rather than dropped silently',
                      got_quiet == ['2026-09-03', '2026-09-04', '2026-09-06',
                                    '2026-09-07', '2026-09-09'], str(got_quiet)))
        cases.append(('a heading carries its weekday',
                      pwn.heading_for(_dt.date(2026, 9, 30), 'a-slug')
                      == '## Wednesday 2026-09-30: a-slug',
                      pwn.heading_for(_dt.date(2026, 9, 30), 'a-slug')))
        good = (f'## Wednesday 2026-09-30: safer-merges\n\n{pwn.HEADLINE}\n\n'
                f'- **A change** (a name)\n')
        old = '## 2026-09-30\n\n**A summary of the bullets.**\n\n- A change\n'
        wrong_day = good.replace('Wednesday', 'Tuesday')
        no_line = good.replace(pwn.HEADLINE, '**Merges got safer.**')
        no_bold = good.replace('**A change**', 'A change')
        backticked = good.replace('safer-merges', '`safer-merges`')
        mid_bold = good.replace('**A change** (a name)', 'A **change** (a name)')
        cases.append(('an entry in the shape passes, and the old shape, a wrong '
                      'weekday, a summary headline, a bullet with no bold key '
                      'phrase, one whose bold is mid-sentence and a backticked '
                      'slug are each flagged',
                      pwn.shape_problems(good) == []
                      and len(pwn.shape_problems(old)) == 3
                      and len(pwn.shape_problems(wrong_day)) == 1
                      and len(pwn.shape_problems(no_line)) == 1
                      and len(pwn.shape_problems(no_bold)) == 1
                      and len(pwn.shape_problems(backticked)) == 1
                      and len(pwn.shape_problems(mid_bold)) == 1,
                      str([pwn.shape_problems(t) for t in
                           (good, old, wrong_day, no_line, no_bold, backticked,
                            mid_bold)])))
        import title_case as _tc
        kept = _tc.title_case('Wednesday 2026-09-30: safer-merges')
        compound = _tc.title_case('a lock-in for safer-merges')
        cases.append(('headline case leaves a dated heading\'s slug alone, and '
                      'still capitalizes a compound elsewhere',
                      kept == 'Wednesday 2026-09-30: safer-merges'
                      and compound == 'A Lock-In for Safer-Merges',
                      f'{kept!r} {compound!r}'))
        added = dict((d.isoformat(), ch['added']) for d, ch in days).get('2026-09-08', [])
        cases.append(('a day\'s new document is listed', 'docs/PHILOSOPHY.md' in added,
                      str(added)))
        ok, msg = pwn.mark(repo, _dt.date(2026, 9, 8), today=today)
        _tz, through, days = pwn.missing_days(repo, today=today)
        cases.append(('--mark covers them, and a second run lists none',
                      ok and through == _dt.date(2026, 9, 8) and days == [],
                      f'{msg} {through} {days}'))
        ok, msg = pwn.mark(repo, today, today=today)
        cases.append(('a day that has not finished cannot be marked', not ok, msg))
        # main's log is ahead of this checkout's: the later one is read.
        (repo / 'WHATS_NEW.md').write_text('---\nchecked_through: 2026-09-09\n---\n',
                                           encoding='utf-8')
        g(repo, 'commit', '-qam', 'log', when='2026-09-10T01:00:00Z')
        g(repo, 'push', '-q', 'origin', 'main'); g(repo, 'fetch', '-q', 'origin')
        g(repo, 'reset', '-q', '--hard', 'HEAD~1')
        _text, later = pwn.read_state(repo)
        cases.append(('the later of this checkout\'s log and main\'s is read',
                      later == _dt.date(2026, 9, 9), str(later)))
        hits = pwn.approval_lines('---\nchecked_through: 2026-09-09\n---\n'
                                  '## 2026-09-09\n- Faster start-up (approved by M)\n'
                                  '- Shorter instructions (about 800 tokens)\n')
        cases.append(('an entry naming an approval is flagged, and only it',
                      [n for n, _ in hits] == [5], str(hits)))
        # The reply check's declared pairing, read from reply_check.json
        # itself: a reply showing the log opens with the log's link.
        import re as _re
        decl = [r for r in json.loads((ROOT / 'reply_check.json').read_text(
            encoding='utf-8')) if r.get('practice') == 'whats-new']
        pair = (decl[0].get('require_paired_with') or [{}])[0] if decl else {}

        def refused(reply):
            return bool(_re.search(pair.get('if_matches', '(?!)'), reply, _re.I | _re.M)
                        and not _re.search(pair.get('must_also_match', ''), reply,
                                           _re.I | _re.M))
        linked = ('**The log:** [WHATS_NEW.md](https://x/WHATS_NEW.md). Check '
                  'here daily.\n\n' + pwn.HEADLINE + '\n')
        late = 'Wrote one day.\n\n' + linked
        cases.append(('a reply showing the log is refused unless its first line '
                      'carries the log\'s link; one that does not show it is '
                      'untouched',
                      bool(pair) and not refused(linked) and refused(late)
                      and not refused('Nothing about the log here.\n'),
                      str(pair)[:200]))
        rule = _ck.vendoring_rule('WHATS_NEW.md')
        cases.append(('a project\'s log never ships to another project',
                      bool(rule) and rule[1] is False, str(rule)))
    finally:
        shutil.rmtree(tmp, ignore_errors=True)
    bad = [(c[0], c[2]) for c in cases if not c[1]]
    check(f'the What\'s new log lists the days it lacks, and only those '
          f'({len(cases)} stated cases)',
          not bad, '; '.join(f"{n} -- {d[:300]}" for n, d in bad))


def check_freshness_covers_every_declared_source():
    """precedent_engine_freshness reports one row per way a DECLARED source
    is reached -- the engine manifest, a vendored tree's manifest, a live
    sibling clone -- and says BEHIND for each the moment its upstream
    moves, silence under --quiet while all are current, and NOT VERIFIED
    (never current) for one it cannot reach. Planted end to end
    (practice: checks-plant-their-state): the first version read one
    manifest, so a consumer's second shared set had no freshness check on
    either of its halves and nothing said so (2026-09-23).
    """
    import io, shutil, tempfile
    sys.path.insert(0, str(ROOT / 'tools'))
    import precedent_engine_freshness as pef

    def git(cwd, *args):
        r = subprocess.run(['git', '-C', str(cwd), *args],
                           capture_output=True, text=True)
        if r.returncode != 0:
            raise RuntimeError(f"git {' '.join(args)}: {r.stderr.strip()}")
        return r.stdout.strip()

    def mkupstream(path, seed):
        path.mkdir()
        git(path, 'init', '-q', '-b', 'main')
        git(path, 'config', 'user.email', 'harness@example.com')
        git(path, 'config', 'user.name', 'harness')
        (path / seed).write_text('v1\n', encoding='utf-8')
        git(path, 'add', '-A')
        git(path, 'commit', '-qm', 'first')
        return git(path, 'rev-parse', 'HEAD')

    def advance(path, seed):
        (path / seed).write_text('v2\n', encoding='utf-8')
        git(path, 'add', '-A')
        git(path, 'commit', '-qm', 'second')

    tmp = pathlib.Path(tempfile.mkdtemp(prefix='precedent-freshness-'))
    saved_env = os.environ.get(pef.USER_CONFIG_ENV)
    try:
        # Two upstreams: the engine's origin and one shared set.
        engine_up = tmp / 'engine-upstream'
        set_up = tmp / 'set-upstream'
        engine_tip = mkupstream(engine_up, 'tools_marker.txt')
        set_tip = mkupstream(set_up, 'practices_marker.txt')
        # The consumer: engine manifest, universal manifest, the set's code
        # manifest, the set's live clone beside it, and a repo-local source.
        consumer = tmp / 'consumer'
        (consumer / 'tools').mkdir(parents=True)
        (consumer / 'process').mkdir()
        (consumer / 'local' / 'practices').mkdir(parents=True)
        set_clone = tmp / 'set'
        git(tmp, 'clone', '-q', str(set_up), str(set_clone))
        (consumer / 'precedent.json').write_text(json.dumps({
            'format_version': 1,
            'sources': [
                {'level': 'universal', 'name': 'precedent',
                 'path': 'process/upstream'},
                {'level': 'shared', 'name': 'set', 'path': '../set',
                 'repo': 'set'},
                {'level': 'repo-local', 'name': 'local', 'path': 'local'},
            ]}), encoding='utf-8')
        (consumer / 'tools' / 'ENGINE_MANIFEST.json').write_text(json.dumps({
            'format_version': 1, 'kind': 'consumer',
            'source_repo': str(engine_up), 'source_branch': 'main',
            'source_commit': engine_tip, 'files': []}), encoding='utf-8')
        (consumer / 'process' / 'manifest.json').write_text(json.dumps({
            'upstream': {'repo': str(engine_up), 'branch': 'main',
                         'commit': engine_tip,
                         'vendored_at': 'process/upstream'}}), encoding='utf-8')
        (consumer / 'process' / 'manifest_set.json').write_text(json.dumps({
            'upstream': {'repo': str(set_up), 'branch': 'main',
                         'commit': set_tip, 'vendored_at': 'process/set'}}),
            encoding='utf-8')
        # No individual set for this planted person.
        os.environ[pef.USER_CONFIG_ENV] = str(tmp / 'no-such-config.json')

        rows = pef.collect_targets(consumer)
        kinds = sorted(r['kind'] for r in rows)

        quiet_before = io.StringIO()
        pef.report(consumer, quiet=True, out=quiet_before)
        full_before = io.StringIO()
        pef.report(consumer, quiet=False, out=full_before)

        advance(engine_up, 'tools_marker.txt')
        advance(set_up, 'practices_marker.txt')
        quiet_after = io.StringIO()
        pef.report(consumer, quiet=True, out=quiet_after)
        after = quiet_after.getvalue()

        # A clone that catches up WHILE the run is going is judged on what it
        # holds when its row is printed (2026-10-06: a consumer's session
        # start called three clones BEHIND that were current minutes later).
        # The stand-in for upstream_tip fast-forwards the live clone as it is
        # asked, after the rows were read -- the race, made deterministic.
        real_tip = pef.upstream_tip

        def tip_and_catch_up(url, branch, clone=None):
            got = real_tip(url, branch, clone=clone)
            if str(url) == str(set_up):
                git(set_clone, 'pull', '-q', '--ff-only')
            return got
        pef.upstream_tip = tip_and_catch_up
        try:
            caught = io.StringIO()
            pef.report(consumer, quiet=True, out=caught)
        finally:
            pef.upstream_tip = real_tip
        caught_up = caught.getvalue()

        # An unreachable source: declared, vendored manifest points nowhere.
        (consumer / 'process' / 'manifest_set.json').write_text(json.dumps({
            'upstream': {'repo': str(tmp / 'gone'), 'branch': 'main',
                         'commit': set_tip, 'vendored_at': 'process/set'}}),
            encoding='utf-8')
        full_unreachable = io.StringIO()
        pef.report(consumer, quiet=False, out=full_unreachable)
        unreachable = full_unreachable.getvalue()

        cases = [
            ('four rows: engine, universal vendored, set vendored, set live '
             '(repo-local skipped)', kinds == ['engine', 'live', 'vendored', 'vendored']),
            ('--quiet says nothing while every source is current',
             quiet_before.getvalue() == ''),
            ('the full run says current for each of the four',
             full_before.getvalue().count('freshness: current --') == 4),
            ('the engine row reads BEHIND once its upstream moves',
             'ENGINE BEHIND UPSTREAM: vendored engine (tools/)' in after),
            ('the universal vendored tree reads BEHIND',
             'BEHIND UPSTREAM: precedent (universal) vendored at process/upstream' in after),
            ('the shared set\'s vendored code reads BEHIND',
             'BEHIND UPSTREAM: set (shared) vendored at process/set' in after),
            ('the shared set\'s live clone reads BEHIND and names the refresh '
             'that brings it current, never a bare pull (engine output a '
             'refresh leaves there makes that pull refuse, 2026-09-30)',
             'BEHIND UPSTREAM: set (shared) live clone at' in after
             and f'--apply --path {set_clone}' in after
             and 'pull --ff-only' not in after),
            ('the notice names Update Vendors once',
             after.count('"Update Vendors"') == 1),
            ('a live clone that caught up while the run went is not called '
             'BEHIND (the control is the BEHIND row above, read without it)',
             'live clone at' not in caught_up
             and 'BEHIND UPSTREAM: set (shared) vendored at process/set' in caught_up),
            ('an unreachable upstream is NOT VERIFIED, not current',
             'NOT VERIFIED -- set (shared) vendored at process/set' in unreachable
             and 'current -- set (shared) vendored' not in unreachable),
        ]
        ok = all(passed for _, passed in cases)
        for name, passed in cases:
            if not passed:
                print(f"  freshness did NOT behave as stated: {name}")
        if not ok:
            print('  --- quiet after upstream moved ---')
            print(after)
        check(f'precedent_engine_freshness covers every declared source '
              f'({len(cases)} stated cases)', ok)
    finally:
        if saved_env is None:
            os.environ.pop(pef.USER_CONFIG_ENV, None)
        else:
            os.environ[pef.USER_CONFIG_ENV] = saved_env
        shutil.rmtree(tmp, ignore_errors=True)


def check_visibility_audit_reads_the_blocklist_as_patterns():
    """The stale-entry half of very_deep_check's visibility audit, repaired.

    THE BUG THIS PINS DOWN was silent and was caused by an unrelated fix.
    That audit reported "this name is on the blocklist but the repository is
    now PUBLIC" by comparing `name.lower() in blocked`, where `blocked` was
    each blocklist line with `\\b` stripped off both ends -- exact string
    equality, correct for as long as every entry was a whole repository name.
    The 2026-09-07 stem rewrite turned every entry into a truncated head plus
    a suffix match, after which equality matched nothing and that half of the
    audit reported a clean sweep it had not performed.

    Asserted through the same reader the push gate uses, so the two cannot
    drift in how they interpret a line."""
    sys.path.insert(0, str(ROOT / 'tools'))
    import leak_gate as _lg
    import tempfile

    with tempfile.TemporaryDirectory() as td:
        bl = pathlib.Path(td) / 'blocklist.txt'
        bl.write_text('\\bquillon[\\w-]*\n\\bkestrel\\b\n', encoding='utf-8')
        pats = _lg._parse_blocklist(bl)

        def covered(name):
            return any(p.search(name) for p in pats)

        def _old_reading_matches(name, path):
            blocked = {re.sub(r'^\\b|\\b$', '', line.strip()).lower()
                       for line in path.read_text(encoding='utf-8').splitlines()
                       if line.strip() and not line.strip().startswith('#')}
            return name.lower() in blocked

        cases = [
            ('a stem matches the full name it was truncated from',
             covered('QuillonNotes')),
            ('a stem matches a name DERIVED from the repo -- the 2026-09-07 '
             'case', covered('quillon-local')),
            # The negative control is the OLD logic, run for real rather
            # than described: strip the anchors, lowercase, compare for
            # equality. It must MISS the name the new reading catches, or
            # this check is not testing the repair.
            ('the string comparison this replaced misses that name, which is '
             'what made the regression invisible',
             not _old_reading_matches('QuillonNotes', bl)),
            ('an unrelated name is not matched', not covered('Kestrelwood')),
            ('a whole-name entry still matches its own name, so repairing '
             'this did not break the entries that were already right',
             covered('Kestrel')),
        ]
        ok = all(passed for _, passed in cases)
        for name, passed in cases:
            if not passed:
                print(f"  blocklist pattern reading did NOT behave as stated: {name}")
        check(f'the visibility audit reads blocklist entries as patterns, so a '
              f'stem entry is still recognised ({len(cases)} stated cases)', ok)


def check_practice_audit_loader():
    """practice_audit.py's check 5, stated as cases (practice:
    checkable-gets-checked). A consumer installed the classic way on
    2026-09-22 -- process/upstream/ vendored, no loader over it -- took an
    update the next day with this audit passing, and its sessions then
    described every practice as "a vendored copy, not something this repo
    adopted". The audit now fails on a vendored catalogue nothing loads,
    and passes once the repo declares a universal source AND carries the
    generated loader block; --loader-notice says the same thing at session
    start and never fails."""
    import shutil, tempfile

    tmp = pathlib.Path(tempfile.mkdtemp(prefix='precedent-auditloader-'))
    try:
        def make(name, catalogue=True, universal=False, block=False,
                 engine=True):
            repo = tmp / name
            tools_dir = repo / 'process' / 'upstream' / 'tools'
            tools_dir.mkdir(parents=True)
            shutil.copy(ROOT / 'tools' / 'practice_audit.py', tools_dir / 'practice_audit.py')
            shutil.copy(ROOT / 'tools' / 'generated_blocks.py', tools_dir / 'generated_blocks.py')
            if catalogue:
                (repo / 'process' / 'upstream' / 'practices').mkdir()
                (repo / 'process' / 'upstream' / 'practices' / 'x.md').write_text(
                    'a practice\n', encoding='utf-8')
            (repo / 'process' / 'manifest.json').write_text(json.dumps({
                'upstream': {'vendored_at': 'process/upstream', 'scrub_blocklist': None},
                'entries': []}), encoding='utf-8')
            sources = {'local': {'level': 'repo-local', 'name': 'local', 'path': 'local'}}
            if universal:
                sources['precedent'] = {'level': 'universal', 'name': 'precedent',
                                        'path': 'process/upstream'}
            (repo / 'precedent.json').write_text(json.dumps(
                {'format_version': 1, 'sources': sources}), encoding='utf-8')
            (repo / 'AGENTS.md').write_text(
                '# notes\n' + ('<!-- BEGIN GENERATED: precedent-loader -->\n'
                               '<!-- END GENERATED -->\n' if block else ''),
                encoding='utf-8')
            if engine:
                (repo / 'tools').mkdir(exist_ok=True)
                (repo / 'tools' / 'ENGINE_MANIFEST.json').write_text(
                    '{}\n', encoding='utf-8')
            subprocess.run(['git', 'init', '-q', str(repo)], check=True)
            return repo

        def run(repo, *extra):
            r = subprocess.run(
                [sys.executable, str(repo / 'process' / 'upstream' / 'tools' / 'practice_audit.py'),
                 *extra], capture_output=True, text=True, cwd=str(repo))
            return r.returncode, r.stdout + r.stderr

        classic = make('classic')
        half = make('half', universal=True)
        loaded = make('loaded', universal=True, block=True)
        pack = make('pack', catalogue=False)
        rc_c, out_c = run(classic)
        rc_h, out_h = run(half)
        rc_l, out_l = run(loaded)
        rc_p, out_p = run(pack)
        rc_n, out_n = run(classic, '--loader-notice')
        rc_nl, out_nl = run(loaded, '--loader-notice')
        # Check 8 (2026-09-24): loaded, but the engine never vendored at
        # tools/ -- the migration stopped before its step 7.
        noengine = make('noengine', universal=True, block=True, engine=False)
        rc_e, out_e = run(noengine)
        rc_en, out_en = run(noengine, '--loader-notice')
        cases = [
            ('a classic install (catalogue vendored, no universal source, no '
             'block) FAILS', rc_c == 1 and 'LOADER:' in out_c),
            ('and the failure names the migration',
             'MIGRATING_EXISTING_INSTALLS.md' in out_c),
            ('a universal source without the generated block still FAILS',
             rc_h == 1 and 'loader block' in out_h),
            ('a universal source plus the block passes check 5',
             rc_l == 0 and 'LOADER:' not in out_l),
            ('a pack-only layer (no catalogue vendored) is not held to it',
             rc_p == 0 and 'LOADER:' not in out_p),
            ('--loader-notice speaks on a classic install and exits 0',
             rc_n == 0 and 'NOT RUNNING' in out_n),
            ('--loader-notice is silent where the loader runs',
             rc_nl == 0 and out_nl.strip() == ''),
            ('check 8: the loader runs but tools/ENGINE_MANIFEST.json is '
             'missing -- FAILS and names the migration',
             rc_e == 1 and 'ENGINE:' in out_e
             and 'MIGRATING_EXISTING_INSTALLS' in out_e),
            ('and --loader-notice says so, still exiting 0',
             rc_en == 0 and 'NEVER VENDORED' in out_en),
            ('NEGATIVE: the same install WITH the manifest is not flagged',
             'ENGINE:' not in out_l),
        ]
        for name, passed in cases:
            if not passed:
                print(f"  practice_audit check 5 did NOT behave as stated: {name}")
        check(f"practice_audit fails a vendored catalogue nothing loads "
              f"({len(cases)} stated cases)", all(ok for _, ok in cases))
    finally:
        shutil.rmtree(tmp, ignore_errors=True)


def check_practice_audit_declined():
    """practice_audit.py's check 6, stated as cases (practice:
    current-rule-governs). A consumer declined upstream's merge-keyword
    practice at one sync as a "duplicate"; upstream replaced it with a
    broader rule, and two later syncs carried the decline forward unread,
    so a session refused a command the rule in force authorized
    (2026-09-24). A "declined" entry now records the upstream file's hash
    as it stood when the decision was made, and the audit fails once the
    file moves until somebody decides again."""
    import hashlib, shutil, tempfile

    tmp = pathlib.Path(tempfile.mkdtemp(prefix='precedent-auditdeclined-'))
    try:
        repo = tmp / 'repo'
        up = repo / 'process' / 'upstream'
        (up / 'tools').mkdir(parents=True)
        (up / 'practices').mkdir()
        shutil.copy(ROOT / 'tools' / 'practice_audit.py', up / 'tools' / 'practice_audit.py')
        shutil.copy(ROOT / 'tools' / 'generated_blocks.py', up / 'tools' / 'generated_blocks.py')
        old = up / 'practices' / 'old-rule.md'
        gone = up / 'practices' / 'gone-rule.md'
        old.write_text('---\nslug: old-rule\nstatus: active\n---\n## Rule\nnarrow\n',
                       encoding='utf-8')
        gone.write_text('---\nslug: gone-rule\nstatus: active\n---\n', encoding='utf-8')
        h = lambda f: hashlib.sha256(f.read_bytes()).hexdigest()
        manifest = repo / 'process' / 'manifest.json'
        manifest.write_text(json.dumps({
            'upstream': {'vendored_at': 'process/upstream', 'scrub_blocklist': None},
            'entries': [
                {'practice': 'old-rule', 'upstream_path': 'practices/old-rule.md',
                 'local_path': None, 'status': 'declined',
                 'declined_upstream_sha256': h(old), 'notes': 'duplicate of a personal rule'},
            ]}), encoding='utf-8')
        (repo / 'precedent.json').write_text(json.dumps({'format_version': 1, 'sources': {
            'precedent': {'level': 'universal', 'name': 'precedent', 'path': 'process/upstream'}}}),
            encoding='utf-8')
        (repo / 'AGENTS.md').write_text('<!-- BEGIN GENERATED: precedent-loader -->\n'
                                        '<!-- END GENERATED -->\n', encoding='utf-8')
        # A migrated install: the engine is vendored at tools/ (check 8).
        (repo / 'tools').mkdir(exist_ok=True)
        (repo / 'tools' / 'ENGINE_MANIFEST.json').write_text('{}\n', encoding='utf-8')
        subprocess.run(['git', 'init', '-q', str(repo)], check=True)

        def run(*extra):
            r = subprocess.run([sys.executable, str(up / 'tools' / 'practice_audit.py'), *extra],
                               capture_output=True, text=True, cwd=str(repo))
            return r.returncode, r.stdout + r.stderr

        def entries():
            return {e['practice']: e for e in
                    json.loads(manifest.read_text(encoding='utf-8'))['entries']}

        rc_fresh, out_fresh = run()
        # Called from the SOURCE clone's module, as precedent_update.py
        # --repo does through checkin.py: the tree is the consumer's.
        spec = importlib.util.spec_from_file_location(
            'source_practice_audit', ROOT / 'tools' / 'practice_audit.py')
        source_audit = importlib.util.module_from_spec(spec)
        spec.loader.exec_module(source_audit)
        from_source = source_audit.stale_declines(manifest)
        # Upstream moves on: the declined file is deduplicated into a successor.
        old.write_text('---\nslug: old-rule\nstatus: deduplicated\nin_force_at: new-rule\n'
                       '---\n## Rule\nnarrow\n', encoding='utf-8')
        (up / 'practices' / 'new-rule.md').write_text(
            '---\nslug: new-rule\nstatus: active\nsupersedes:  ["old-rule"]\n---\n',
            encoding='utf-8')
        rc_moved, out_moved = run()
        hash_before = entries()['old-rule']['declined_upstream_sha256']
        run('--update-baseline')
        hash_after_baseline = entries()['old-rule']['declined_upstream_sha256']
        rc_re, out_re = run('--redecide', 'old-rule')
        rc_after, out_after = run()
        # A decline with no hash, and one whose file is gone.
        m = json.loads(manifest.read_text(encoding='utf-8'))
        m['entries'].append({'practice': 'unhashed', 'upstream_path': 'practices/gone-rule.md',
                             'local_path': None, 'status': 'declined', 'notes': 'x'})
        manifest.write_text(json.dumps(m), encoding='utf-8')
        rc_nohash, out_nohash = run()
        gone.unlink()
        rc_gone, out_gone = run()
        # Check 7: a decline written as prose is warned about, and only
        # outside the generated block.
        (repo / 'AGENTS.md').write_text(
            'We declined the merge-keyword practice as a duplicate.\n'
            'The personal pack wins on conflict.\n'
            '<!-- BEGIN GENERATED: precedent-loader -->\n'
            'this duplicate of something is generated text\n'
            '<!-- END GENERATED -->\n', encoding='utf-8')
        _rc_prose, out_prose = run()
        cases = [
            ('a decline made against the current upstream file passes',
             rc_fresh == 0 and 'declined OK' in out_fresh),
            ('run from the source clone, a consumer decline reads the consumer tree',
             from_source == []),
            ('the upstream file changing since the decline FAILS',
             rc_moved == 1 and 'DECLINED: [upstream:old-rule]' in out_moved),
            ('and the failure names where the rule lives now and what replaced it',
             'in force at new-rule' in out_moved and 'superseded by new-rule' in out_moved),
            ('--update-baseline never re-baselines a decline',
             hash_after_baseline == hash_before),
            ('--redecide records the current hash and exits 0',
             rc_re == 0 and entries()['old-rule']['declined_upstream_sha256'] == h(old)),
            ('after --redecide the audit passes again', rc_after == 0),
            ('a decline with no recorded hash FAILS',
             rc_nohash == 1 and 'no declined_upstream_sha256' in out_nohash),
            ('a decline whose upstream file is gone FAILS',
             rc_gone == 1 and 'no longer in the vendored tree' in out_gone),
            ('check 7 warns on a prose decline and a blanket precedence clause',
             'AGENTS.md:1 reads like a decline' in out_prose
             and 'AGENTS.md:2 reads like a decline' in out_prose),
            ('check 7 skips the generated loader block',
             'AGENTS.md:4' not in out_prose),
        ]
        for name, passed in cases:
            if not passed:
                print(f"  practice_audit check 6 did NOT behave as stated: {name}")
        check(f"practice_audit fails a decline the upstream file has moved past "
              f"({len(cases)} stated cases)", all(ok for _, ok in cases))
    finally:
        shutil.rmtree(tmp, ignore_errors=True)


def check_practice_audit_fires():
    """practice_audit.py's --update-baseline, stated as cases against a
    throwaway manifest (practice: mistakes-become-rules).

    Regression case, found in the wild via a dependent repo's check-in
    (the project's own prior notes repository, 2026-09-04): a 'diverged' manifest entry
    marks a file as a deliberate, permanent customization that must never
    be proposed for export -- the whole point of the status. Before this
    fix, --update-baseline read ANY hash mismatch against the recorded
    local_sha256 as "the local file changed, so the divergence must be
    resolved" and silently flipped 'diverged' to 'synced' -- even when the
    mismatch was really just a stale baseline already wrong in the
    manifest, with the file itself untouched. Nothing in the tool's output
    named the flip, so it was invisible short of hand-diffing the manifest.
    A repo carrying a diverged entry could lose that marking on the next
    routine --update-baseline run for an unrelated reason, and a later
    check-in (INSTALL.md §4) could then propose the customization for
    export with nothing downstream able to tell "genuinely synced" apart
    from "flipped by this bug".

    Asserts the fix from outside the tool: run --update-baseline as a
    subprocess against a scratch manifest and read the entries back."""
    import shutil, tempfile

    tmp = pathlib.Path(tempfile.mkdtemp(prefix='precedent-practiceaudit-'))
    try:
        repo = tmp / 'repo'
        tools_dir = repo / 'process' / 'upstream' / 'tools'
        tools_dir.mkdir(parents=True)
        shutil.copy(ROOT / 'tools' / 'practice_audit.py', tools_dir / 'practice_audit.py')
        shutil.copy(ROOT / 'tools' / 'generated_blocks.py', tools_dir / 'generated_blocks.py')
        (repo / 'process' / 'upstream').mkdir(exist_ok=True)
        (repo / 'local').mkdir()
        (repo / 'local' / 'diverged.md').write_text('customized on purpose\n', encoding='utf-8')
        (repo / 'local' / 'synced.md').write_text('vendored as-is\n', encoding='utf-8')
        manifest = repo / 'process' / 'manifest.json'

        def write_manifest():
            manifest.write_text(json.dumps({
                'upstream': {'vendored_at': 'process/upstream', 'scrub_blocklist': None},
                'entries': [
                    {'practice': 'diverged_one', 'local_path': 'local/diverged.md',
                     'status': 'diverged', 'granularity': 'file',
                     'local_sha256': 'stale-hash-not-a-real-sha', 'notes': 'never export'},
                    {'practice': 'synced_one', 'local_path': 'local/synced.md',
                     'status': 'synced', 'granularity': 'file',
                     'local_sha256': 'stale-hash-not-a-real-sha', 'notes': ''},
                ],
            }, indent=2), encoding='utf-8')

        def run_update():
            r = subprocess.run(
                [sys.executable, str(tools_dir / 'practice_audit.py'),
                 '--update-baseline', '--manifest', str(manifest)],
                capture_output=True, text=True, cwd=str(repo))
            entries = json.loads(manifest.read_text(encoding='utf-8'))['entries']
            return r, {e['practice']: e for e in entries}

        write_manifest()
        before = json.loads(manifest.read_text(encoding='utf-8'))['entries']
        before_hash = {e['practice']: e['local_sha256'] for e in before}
        result, after = run_update()

        cases = [
            ("a 'diverged' entry's status is untouched by a stale-baseline "
             "re-run", after['diverged_one']['status'] == 'diverged'),
            ("a 'diverged' entry's hash IS re-baselined (the fix narrows the bug, "
             "it doesn't stop the hash update)",
             after['diverged_one']['local_sha256'] != before_hash['diverged_one']),
            ("a 'synced' entry re-baselining still stays 'synced' (unchanged "
             "behaviour)", after['synced_one']['status'] == 'synced'),
            ("the diverged re-baseline is named in the output, not silent",
             "was 'diverged'" in result.stdout),
        ]

        ok = all(passed for _, passed in cases)
        for name, passed in cases:
            if not passed:
                print(f"  practice_audit --update-baseline did NOT behave as stated: {name}")
        check(f"practice_audit --update-baseline fires ({len(cases)} stated cases: "
              f"'diverged' status survives a hash-only re-baseline)", ok)
    finally:
        shutil.rmtree(tmp, ignore_errors=True)


def check_source_precedence():
    """Four sources resolved by a consumer repo, and the precedence rules
    asserted as stated cases (PRACTICE_ENGINE_PLAN.md, phase-3 done-when: "a
    consumer repo resolves all three and precedence is tested" -- extended
    2026-09-03 to a fourth source, repo-local, and to the reordered
    precedence team > repo-local > individual > universal; see
    spec/SOURCES.md for why the order changed).

    WHY THE FIXTURE IS BUILT IN A TEMPORARY DIRECTORY AND NOT COMMITTED.
    Levels are repositories, not directories. A committed fixture holding a
    team- or individual-shaped tree inside Precedent is exactly the shortcut
    the plan forbids and the leak gate refuses by path -- and a check whose
    setup requires switching off another check is a check that ends up
    switching it off. The fixture practices below are invented, and exist
    only for the length of this function.

    EACH CASE IS A RULE FROM THE PLAN, NOT A RESTATEMENT OF THE RESOLVER.
    They are written from "Precedence, and the One Case Where the Individual
    Does Not Win" and from "One Individual Set per Person": what SHOULD
    happen, so the check disagrees with the resolver when the resolver is
    wrong rather than agreeing with it by construction."""
    import shutil, tempfile

    def practice(d, slug, *, level_note, severity='default', overrides='null',
                 status='active'):
        (d / 'practices').mkdir(parents=True, exist_ok=True)
        (d / 'practices' / f'{slug}.md').write_text(
            f"---\nslug:        {slug}\ntitle:       {slug}\n"
            f"tier:        on-demand\nseverity:    {severity}\n"
            f'applies_to:  ["**"]\noccasion:    "a fixture occasion"\n'
            f'index_clause: "a fixture clause"\nchecked_by:  null\n'
            f"defines:     []\nstatus:      {status}\nsupersedes:  []\n"
            f"overrides:   {overrides}\nadded:       null\n"
            f'approved_by: "fixture"\n---\n'
            f"## Rule\n{level_note}\n\n## Detail\n\n## Why\n\n"
            f"## Story\n\n## Install\n", encoding='utf-8')

    tmp = pathlib.Path(tempfile.mkdtemp(prefix='precedent-resolve-'))
    try:
        consumer = tmp / 'a-project'
        universal, team, individual = tmp / 'u', tmp / 't', tmp / 'i'
        (consumer).mkdir()

        # repo-local practices live at the FIXED subdirectory `local`
        # (precedent_resolve.py now requires exactly `path: "local"` for
        # any repo-local source -- see load_config's own docstring) --
        # `practice(consumer / 'local', ...)` writes to
        # consumer/local/practices/, which is exactly what a repo-local
        # source declared at `path: "local"` resolves against.
        consumer_local = consumer / 'local'
        practice(universal, 'shared-slug', level_note='universal wins nothing')
        practice(universal, 'shared-slug-2', level_note='universal wins nothing here either')
        practice(universal, 'universal-only', level_note='only here')
        practice(universal, 'house-style', level_note='what we ship',
                 severity='blocking')
        practice(universal, 'retired-one', level_note='gone', status='retired')
        practice(team, 'shared-slug', level_note='team beats everything, '
                 'even repo-local')
        practice(team, 'team-only', level_note='only here')
        practice(consumer_local, 'shared-slug', level_note='repo-local beats '
                 'individual and universal, but not team')
        practice(consumer_local, 'shared-slug-2', level_note='repo-local beats '
                 'individual and universal here too, and team is not in '
                 'play for this slug at all')
        practice(consumer_local, 'repo-local-only', level_note='only here')
        practice(consumer_local, 'house-style', level_note='a repo-local attempt '
                 'at the same slug the blocking universal practice holds')
        practice(individual, 'shared-slug', level_note='individual beats '
                 'universal, loses to repo-local and team')
        practice(individual, 'shared-slug-2', level_note='individual beats '
                 'universal, loses to repo-local')
        practice(individual, 'individual-only', level_note='only here')
        practice(individual, 'client-tone', level_note='an individual '
                 'practice that must survive a team override attempt',
                 severity='blocking')
        practice(team, 'team-formal-tone', level_note='team tries to '
                 'override the individual\'s blocking client-tone',
                 overrides='client-tone')
        practice(universal, 'old-universal-name', level_note='the universal '
                 'practice an individual practice renames')
        practice(individual, 'my-own-name', level_note='replaces '
                 'old-universal-name', overrides='old-universal-name')
        # A practice whose OWN slug is blocked, that ALSO names an unrelated
        # slug in `overrides:`. Regression fixture for a real bug: the
        # resolver used to process a practice's own-slug collision and its
        # `overrides:` target as independent loop iterations, so a refused
        # own-slug collision did not stop the SAME practice's `overrides:`
        # from still deleting its target -- a practice that was never
        # activated still "shadowed" something, and the report claimed a
        # practice was doing the shadowing that was, in fact, never in force.
        practice(universal, 'client-tone-2', level_note='blocking, unrelated '
                 'to the override target below', severity='blocking')
        practice(universal, 'legacy-note-format', level_note='an unrelated '
                 'universal practice the blocked shared practice tries to '
                 'retire')
        practice(team, 'client-tone-2', level_note='refused: collides with '
                 'a blocking universal practice under its OWN slug',
                 overrides='legacy-note-format')

        (consumer / 'precedent.json').write_text(json.dumps({
            'format_version': 1,
            'sources': [{'level': 'universal', 'name': 'precedent',
                         'path': str(universal)},
                        {'level': 'team', 'name': 'precedent-team-fixture',
                         'path': str(team)},
                        {'level': 'repo-local', 'name': 'local',
                         'path': 'local'}]}), encoding='utf-8')
        user_cfg = tmp / 'user.json'
        user_cfg.write_text(json.dumps({
            'format_version': 1,
            'individual': {'name': 'precedent-individual',
                           'path': str(individual)}}), encoding='utf-8')

        def run(*extra):
            r = subprocess.run(
                [sys.executable, str(ROOT / 'tools' / 'precedent_resolve.py'),
                 '--repo', str(consumer), '--user-config', str(user_cfg),
                 '--json', *extra],
                capture_output=True, text=True)
            return r.returncode, r.stdout, r.stderr

        rc, out, _err = run()
        if rc != 0:
            check('source precedence (four sources resolved by a consumer repo)',
                  False, f'precedent_resolve.py exited {rc}')
            return
        data = json.loads(out)
        by_slug = {p['slug']: p for p in data['practices']}
        cases = []

        # all four sources are actually in play
        cases.append(('all four sources resolve',
                      {s['level'] for s in data['sources']}
                      == {'universal', 'shared', 'individual', 'repo-local'}))
        # precedence: team > repo-local > individual > universal, on a slug
        # defined at all four
        cases.append(('team beats repo-local beats individual beats '
                      'universal on a slug defined at all four',
                      by_slug.get('shared-slug', {}).get('level') == 'shared'))
        # isolate repo-local's own rank: a slug defined at repo-local,
        # individual and universal, but NOT team, must resolve to repo-local
        cases.append(('repo-local beats individual and universal when team '
                      'is not in play for that slug',
                      by_slug.get('shared-slug-2', {}).get('level') == 'repo-local'))
        # everything unique to a level survives
        for slug, level in (('universal-only', 'universal'),
                            ('individual-only', 'individual'),
                            ('team-only', 'shared'),
                            ('repo-local-only', 'repo-local')):
            cases.append((f'{slug} survives from {level}',
                          by_slug.get(slug, {}).get('level') == level))
        # blocking protects a LOWER-ranked practice from a HIGHER one, not
        # just "team or universal" -- a blocking universal practice survives
        # against team, individual and repo-local all reusing its slug
        cases.append(('a blocking universal practice is not overridden by '
                      'anything above it', by_slug.get('house-style', {}).get('level')
                      == 'universal'))
        # and a blocking INDIVIDUAL practice survives against team, which
        # ranks above individual and would otherwise win by plain precedence
        cases.append(('a blocking individual practice is not overridden by '
                      'a higher-ranked team `overrides:` attempt',
                      by_slug.get('client-tone', {}).get('level') == 'individual'))
        cases.append(('the refusal is reported, not silent',
                      {b['slug'] for b in data['blocked']}
                      == {'house-style', 'client-tone', 'client-tone-2'}))
        # `overrides:` naming a differently-named lower slug: the named
        # practice leaves the set, and the one naming it enters. Without a
        # non-blocking case here, deleting the whole `overrides:` branch still
        # passed -- the two blocking cases pass either way, because a refused
        # override and an ignored one look identical from outside.
        cases.append(('an `overrides:` removes the lower practice it names',
                      'old-universal-name' not in by_slug))
        cases.append(('and the practice doing the overriding enters the set',
                      by_slug.get('my-own-name', {}).get('level') == 'individual'))
        cases.append(('the override is reported',
                      any(s['slug'] == 'old-universal-name' for s in data['overridden'])))
        cases.append(('an overriding practice still enters the set itself '
                      'even when its override attempt is refused by blocking',
                      'team-formal-tone' in by_slug))
        # lifecycle: a retired practice is resolvable but not in force
        cases.append(('a retired practice is not in force',
                      'retired-one' not in by_slug))

        # a practice refused on its OWN slug must not act on `overrides:` --
        # the target of its override must survive untouched, and the report
        # must not credit a never-activated practice with shadowing anything
        cases.append(('a practice blocked on its own slug does not enter '
                      'the resolved set',
                      by_slug.get('client-tone-2', {}).get('level') == 'universal'))
        cases.append(("that same practice's `overrides:` target is left "
                      "alone, since the practice naming it was never "
                      "activated",
                      by_slug.get('legacy-note-format', {}).get('level')
                      == 'universal'))
        cases.append(('and the target is not reported as overridden by a '
                      'practice that was refused',
                      not any(s['slug'] == 'legacy-note-format'
                              for s in data['overridden'])))

        # two same-level practices claiming the same `overrides:` target must
        # fail loudly, not silently drop the second collision. Regression for
        # a real bug: the first same-level practice to process deletes its
        # target from `resolved`, so a second same-level practice naming the
        # same target found `resolved.get(ov)` already None and its override
        # intent vanished with no error and no trace in either practice's
        # `--explain` output. PRACTICE_ENGINE_PLAN.md is explicit this must
        # fail loudly: "the resolver fails loudly if two same-level practices
        # claim one slug."
        collision = tmp / 'collision-project'
        collision.mkdir()
        coll_universal, coll_team = tmp / 'cu', tmp / 'ct'
        practice(coll_universal, 'shared-target',
                 level_note='the contested universal practice')
        practice(coll_team, 'claim-one', level_note='first shared practice',
                 overrides='shared-target')
        practice(coll_team, 'claim-two', level_note='second shared practice',
                 overrides='shared-target')
        (collision / 'precedent.json').write_text(json.dumps({
            'format_version': 1,
            'sources': [{'level': 'universal', 'name': 'precedent',
                         'path': str(coll_universal)},
                        {'level': 'team', 'name': 'precedent-team-fixture',
                         'path': str(coll_team)}]}), encoding='utf-8')
        r_coll = subprocess.run(
            [sys.executable, str(ROOT / 'tools' / 'precedent_resolve.py'),
             '--repo', str(collision)],
            capture_output=True, text=True)
        cases.append(("two same-level practices naming one `overrides:` "
                       "target fail loudly instead of silently dropping the "
                       "second",
                       r_coll.returncode == 1 and 'cannot both claim' in
                       (r_coll.stdout + r_coll.stderr)))

        # a shared repo may not name someone's individual set
        leaky = tmp / 'leaky-project'
        leaky.mkdir()
        (leaky / 'precedent.json').write_text(json.dumps({
            'format_version': 1,
            'sources': [{'level': 'individual', 'name': 'precedent-individual',
                         'path': str(individual)}]}), encoding='utf-8')
        r = subprocess.run(
            [sys.executable, str(ROOT / 'tools' / 'precedent_resolve.py'),
             '--repo', str(leaky), '--user-config', str(user_cfg)],
            capture_output=True, text=True)
        cases.append(('a shared repo declaring an individual source is refused',
                      r.returncode == 1 and 'individual source' in
                      (r.stdout + r.stderr)))

        # a repo-local source whose path is NOT exactly "local" is refused --
        # the level only means anything if a repo cannot point it at
        # someone else's tree, or at any name of its own choosing, and call
        # that "local"
        elsewhere = tmp / 'elsewhere-project'
        elsewhere.mkdir()
        (elsewhere / 'precedent.json').write_text(json.dumps({
            'format_version': 1,
            'sources': [{'level': 'repo-local', 'name': 'not-actually-local',
                         'path': str(team)}]}), encoding='utf-8')
        r_el = subprocess.run(
            [sys.executable, str(ROOT / 'tools' / 'precedent_resolve.py'),
             '--repo', str(elsewhere)],
            capture_output=True, text=True)
        cases.append(('a repo-local source whose path is someone else\'s '
                      'tree entirely is refused',
                      r_el.returncode == 1 and 'repo-local source' in
                      (r_el.stdout + r_el.stderr)))

        # a repo-local source at the bare repo root ("." -- the path that
        # silently lost its own hand-authored content to
        # precedent_materialize.py before this was a hard rule) is refused
        bare_root = tmp / 'bare-root-project'
        bare_root.mkdir()
        (bare_root / 'precedent.json').write_text(json.dumps({
            'format_version': 1,
            'sources': [{'level': 'repo-local', 'name': 'bare-root-local',
                         'path': '.'}]}), encoding='utf-8')
        r_br = subprocess.run(
            [sys.executable, str(ROOT / 'tools' / 'precedent_resolve.py'),
             '--repo', str(bare_root)],
            capture_output=True, text=True)
        cases.append(('a repo-local source at the bare repo root (".") is '
                      'refused', r_br.returncode == 1 and 'must resolve to '
                      'exactly "local"' in (r_br.stdout + r_br.stderr)))

        # a repo-local source at some OTHER in-repo subdirectory name (not
        # "local") is refused too -- an in-repo path is necessary but not
        # sufficient; the whole point is that the name is the SAME across
        # every Precedent repo, not merely "somewhere safe"
        other_name = tmp / 'other-name-project'
        other_name.mkdir()
        (other_name / 'precedent.json').write_text(json.dumps({
            'format_version': 1,
            'sources': [{'level': 'repo-local', 'name': 'oddly-named',
                         'path': 'repo-local-stuff'}]}), encoding='utf-8')
        r_on = subprocess.run(
            [sys.executable, str(ROOT / 'tools' / 'precedent_resolve.py'),
             '--repo', str(other_name)],
            capture_output=True, text=True)
        cases.append(('a repo-local source at an in-repo but non-"local" '
                      'subdirectory name is refused too',
                      r_on.returncode == 1 and 'must resolve to exactly '
                      '"local"' in (r_on.stdout + r_on.stderr)))

        # but a path that's merely a DIFFERENT SPELLING of "local" -- a
        # trailing slash, or a "./" prefix -- is accepted, not refused: the
        # rule is about the resolved directory, not the literal string. A
        # real bug found testing the strict-string-equality version of this
        # check, fixed by normalizing with posixpath.normpath before
        # comparing.
        for slug_variant in ('local/', './local'):
            spelling = tmp / f'spelling-{slug_variant.replace("/", "-").replace(".", "")}'
            spelling.mkdir()
            (spelling / 'local' / 'practices').mkdir(parents=True)
            (spelling / 'precedent.json').write_text(json.dumps({
                'format_version': 1,
                'sources': [{'level': 'repo-local', 'name': 'local',
                             'path': slug_variant}]}), encoding='utf-8')
            r_sp = subprocess.run(
                [sys.executable, str(ROOT / 'tools' / 'precedent_resolve.py'),
                 '--repo', str(spelling)],
                capture_output=True, text=True)
            cases.append((f'a repo-local path spelled {slug_variant!r} -- the '
                          'same directory as "local", just written '
                          'differently -- is accepted, not refused',
                          r_sp.returncode == 0))

        # degrade gracefully: the individual set is gone (a fresh cloud session)
        shutil.rmtree(individual)
        rc2, out2, err2 = run()
        data2 = json.loads(out2) if rc2 == 0 else {}
        cases.append(('a missing individual set degrades instead of failing',
                      rc2 == 0))
        cases.append(('and says so rather than pretending it was applied',
                      'individual' in err2 and 'not in force' in err2))
        cases.append(('and the team, universal and repo-local practices '
                      'still resolve',
                      {p['slug'] for p in data2.get('practices', [])}
                      >= {'team-only', 'universal-only', 'repo-local-only'}))
        cases.append(('--strict makes a missing source fatal',
                      run('--strict')[0] == 1))

        # --- two sources at the SAME level claiming one slug -------------
        # Nothing orders them, so the winner would be whichever the config
        # lists second. Until 2026-09-06 that is exactly what happened, and
        # it was reported as an ordinary `overridden:` notice on stderr --
        # indistinguishable from a legitimate higher-level override. The
        # plan's own rule is that the resolver fails loudly here.
        two_teams = tmp / 'two-teams'
        (two_teams).mkdir()
        t_a, t_b = tmp / 'precedent-team-a', tmp / 'precedent-team-b'
        practice(t_a, 'shared', level_note='Team A version.')
        practice(t_b, 'shared', level_note='Team B version.')
        practice(t_b, 'b-only', level_note='Only in B.')
        (two_teams / 'precedent.json').write_text(json.dumps({
            'format_version': 1,
            'sources': [{'level': 'team', 'name': 'precedent-team-a', 'path': str(t_a)},
                        {'level': 'team', 'name': 'precedent-team-b', 'path': str(t_b)}]}),
            encoding='utf-8')
        r_two = subprocess.run(
            [sys.executable, str(ROOT / 'tools' / 'precedent_resolve.py'),
             '--repo', str(two_teams)], capture_output=True, text=True)
        out_two = r_two.stdout + r_two.stderr
        cases.append(('two shared-level sources defining one slug is a loud '
                      'failure, not a silent last-one-wins',
                      r_two.returncode == 1 and 'shared' in out_two
                      and 'same level' in out_two))

        # ...and two shared sources that DON'T collide still resolve fine --
        # the rule must not have turned "more than one shared source" into an
        # error by itself.
        (t_a / 'practices' / 'shared.md').unlink()
        practice(t_a, 'a-only', level_note='Only in A.')
        r_ok = subprocess.run(
            [sys.executable, str(ROOT / 'tools' / 'precedent_resolve.py'),
             '--repo', str(two_teams), '--json'], capture_output=True, text=True)
        slugs_ok = ({p['slug'] for p in json.loads(r_ok.stdout).get('practices', [])}
                    if r_ok.returncode == 0 else set())
        cases.append(('two non-colliding shared sources still resolve together',
                      r_ok.returncode == 0 and {'a-only', 'b-only', 'shared'} <= slugs_ok))

        ok = all(passed for _, passed in cases)
        for name, passed in cases:
            if not passed:
                print(f"  precedence did NOT behave as stated: {name}")
        check(f'source precedence ({len(cases)} stated cases: a consumer repo '
              f'resolves universal + team + individual + repo-local, blocking '
              f'wins over precedence, a missing set degrades)', ok)
    finally:
        shutil.rmtree(tmp, ignore_errors=True)


def check_cross_source_resident_budget():
    """The resident-block cap has to hold across ALL resolved sources, not
    just this repo's own practices/ directory (spec/PRIVATE_SETS_BRIEF.md,
    "One open gap to report back, not to solve there": build_views.py's
    RESIDENT_BUDGET_TOKENS only ever saw this repo's practices/, and
    precedent_resolve.py had no resident/budget logic at all -- a shared set
    marking several practices resident, on top of an individual set doing
    the same, could push a real session's resident block well past the cap
    with nothing objecting).

    THREE DIRECTIONS, ALL SYNTHETIC -- and that is the fix, not a detail.
    Until 2026-09-11 direction 1 ran `precedent_resolve.py --repo <this
    repo>`, which resolves whatever private sources the CONTAINER has
    attached. So the check's result depended on the machine: green where the
    sets were missing, red where they were attached and their own combined
    resident block went over the cap. It failed that way for most of a day,
    and the failure it printed -- "this repo's own resolved set was wrongly
    flagged over budget" -- was wrong twice over: the flag was correct, and
    the set being measured was not this repo's. The same
    [fixture-owns-its-state] shape as the three instances in AGENTS.md's
    gotchas, one level out.

    What replaced it measures the MECHANISM, which is all a harness can own:
    this repo as a single declared source stays clean; a single source over
    the cap is still flagged (so direction 1 is not vacuous); and a
    multi-source combination over the cap is refused. A real combination
    going over is not this check's business -- it is content in somebody's
    private set, reported by `precedent_resolve.py` exiting 1 and enforced by
    `build_views.py` refusing to write an over-budget block, which is a
    harder stop than a harness line. session-load-budget's own Rule says the
    reduction is the owner's to choose, never a session's."""
    import shutil, tempfile
    tmp = pathlib.Path(tempfile.mkdtemp(prefix='precedent-budget-'))
    try:
        def _consumer(name, sources):
            d = tmp / name
            d.mkdir(parents=True, exist_ok=True)
            (d / 'precedent.json').write_text(json.dumps(
                {'format_version': 1, 'sources': sources}), encoding='utf-8')
            return d

        def _resolve(repo):
            rc, out, err = _run([sys.executable, str(ROOT / 'tools' /
                                 'precedent_resolve.py'), '--repo', str(repo),
                                 '--json'])
            return rc, (json.loads(out) if out else {}), err

        def _resident_source(dirname, slug, words):
            d = tmp / dirname / 'practices'
            d.mkdir(parents=True, exist_ok=True)
            (d.parent / 'practices' / f'{slug}.md').write_text(
                f"---\nslug:        {slug}\ntitle:       Fixture\n"
                "tier:        resident\nseverity:    default\n"
                'applies_to:  ["**"]\noccasion:    null\ngates:       []\n'
                'index_clause: "n/a"\nchecked_by:  null\ndefines:     []\n'
                "status:      active\nsupersedes:  []\noverrides:   null\n"
                'added:       null\napproved_by: "fixture"\n---\n'
                f"## Rule\n{' '.join(['word'] * words)}\n\n## Why\n\n"
                "## Story\n\n## Install\n", encoding='utf-8')
            return (tmp / dirname)

        # direction 1: THIS REPO as the only declared source -- named
        # explicitly, so the container's own attached sources cannot change
        # the answer.
        rc, data, _err = _resolve(_consumer('alone', [
            {'level': 'universal', 'name': 'precedent', 'path': str(ROOT)}]))
        clean_ok = rc == 0 and not data.get('resident', {}).get('over_budget', True)

        # direction 1's control: a SINGLE source over the cap is flagged, so
        # the pass above means "under budget", not "this code never flags".
        rc1b, data1b, _e1b = _resolve(_consumer('single-over', [
            {'level': 'universal', 'name': 'precedent',
             'path': str(_resident_source('huge-universal', 'huge-alone', 1800))}]))
        single_over_ok = (rc1b == 1
                          and data1b.get('resident', {}).get('over_budget') is True)

        # direction 2: a synthetic shared source with an oversized resident
        # Rule, stacked on top of this repo's own resident practices, must
        # push the combined figure over budget and be refused
        consumer = tmp / 'consumer'
        team = tmp / 'team'
        (consumer).mkdir()
        (team / 'practices').mkdir(parents=True)
        big_rule = ' '.join(['word'] * 1500)  # ~1950 approx-tokens alone
        (team / 'practices' / 'huge-resident.md').write_text(
            "---\nslug:        huge-resident\ntitle:       Huge\n"
            "tier:        resident\nseverity:    default\n"
            'applies_to:  ["**"]\noccasion:    null\ngates:       []\n'
            'index_clause: "n/a"\nchecked_by:  null\ndefines:     []\n'
            "status:      active\nsupersedes:  []\noverrides:   null\n"
            'added:       null\napproved_by: "fixture"\n---\n'
            f"## Rule\n{big_rule}\n\n## Why\n\n## Story\n\n## Install\n",
            encoding='utf-8')
        (consumer / 'precedent.json').write_text(json.dumps({
            'format_version': 1,
            'sources': [{'level': 'universal', 'name': 'precedent',
                         'path': str(ROOT)},
                        {'level': 'team', 'name': 'precedent-team-fixture',
                         'path': str(team)}]}), encoding='utf-8')
        rc2, out2, err2 = _run([sys.executable, str(ROOT / 'tools' /
                                'precedent_resolve.py'), '--repo', str(consumer),
                                '--json'])
        over_data = json.loads(out2) if out2 else {}
        over_ok = (rc2 == 1
                   and over_data.get('resident', {}).get('over_budget') is True
                   and 'huge-resident' in {p['slug'] for p in
                                           over_data.get('resident', {}).get('practices', [])}
                   and 'cross-source cap' in err2)

        ok = clean_ok and single_over_ok and over_ok
        if not clean_ok:
            print("  this repo declared as the ONLY source was flagged over "
                  "budget -- this repo's own resident block, nothing else")
        if not single_over_ok:
            print("  a single source over the cap was NOT flagged, so "
                  "direction 1 proves nothing")
        if not over_ok:
            print("  a synthetic multi-source set built to exceed the budget "
                  "was NOT refused")
        check('cross-source resident budget (this repo as the only declared '
              'source stays clean; a single source over the cap is flagged; a '
              'synthetic team+universal combination over the 2,000-token cap '
              'is refused -- all three synthetic, so the container\'s own '
              'attached sources cannot change the result)', ok)
    finally:
        shutil.rmtree(tmp, ignore_errors=True)


def _run(cmd):
    r = subprocess.run(cmd, capture_output=True, text=True)
    return r.returncode, r.stdout, r.stderr


EXAMPLE_SET = ROOT / 'documentation' / 'examples' / 'practice-set'


MANDATORY_SECTIONS = ('rule', 'why', 'story', 'install')  # 'detail' is optional


def check_practice_sections_present():
    """Every REAL practice file carries all four mandatory sections
    (## Detail is legitimately optional -- only some practices carry one).

    WHY THIS EXISTS SEPARATELY FROM check_example_set's identical-looking
    check. That check only ever ran against documentation/examples/practice-set/. For the
    52 phase-1-converted practices, a missing section usually gets caught
    anyway by the word-multiset content-preservation checks, because the
    corrupted text is not what PRACTICES.md's frozen original said. But
    those checks have nothing to compare against for a practice with no
    `source_practice_number` -- exactly the plan's own stated path forward
    (a new practice minted post-conversion, e.g. checkable-gets-checked).
    A single accidental trailing space on a heading
    (split_practices.py's section regex) used to silently merge that whole
    section into the one before it, with no error anywhere in the harness,
    for any practice minted this way. This closes that for the real
    catalogue, not just the shipped example."""
    ok = True
    for f in sorted(PRACTICES_DIR.glob('*.md')):
        try:
            fm, sections = sp._read_practice_file(f)
        except sp.PracticeFileError:
            continue  # a parse failure is check_all_practices_parse's job
        missing = [s for s in MANDATORY_SECTIONS if s not in sections]
        if missing:
            ok = False
            print(f"  {f.name}: missing section(s) {', '.join(missing)} -- a "
                  f"heading with trailing whitespace, or one silently merged "
                  f"into the section before it, produces exactly this")
    check('every practice file carries all mandatory sections (## Rule, '
          '## Why, ## Story, ## Install -- ## Detail is optional)', ok)


def check_doc_lint_fires():
    """doc_lint.py gates every push (AGENTS.md's "Two check levels") and had
    NEVER been given a direct unit test of its own internals -- this repo's
    own checkable-gets-checked convention, applied to the tool that
    enforces it on everyone else. Plants two regressions a 2026-09-01
    deep-check audit found and fixed, plus the clean-input and still-caught
    counterparts check_leak_gate_fires()'s family always pairs a fix with
    (a check that fires on everything is as useless as one that fires on
    nothing).

    1. Cross-line strikethrough: renders_del() used to test one PHYSICAL
       LINE at a time, but GFM strikethrough can open on one line and close
       on a later one within the same paragraph. GitHub renders the whole
       span as one <del>; the old per-line test never saw it, since neither
       half alone contains a matching pair of tildes.
    2. check_residue()'s "this is just a link to the record doc" allow-list
       only recognized `_record.md`/`_diligence.md`, not the four other
       record-doc suffixes is_record_doc() (and RECORD_NAME_RE) already
       treat as record docs -- so a line that was legitimately just a link
       to thing_decision.md (etc.) was falsely flagged as residue."""
    import shutil, tempfile
    tmp = pathlib.Path(tempfile.mkdtemp(prefix='precedent-doclint-'))
    cases = []
    real_root = dl.ROOT
    try:
        dl.ROOT = tmp

        (tmp / 'cross.md').write_text(
            "This is ~begin unwanted strike\nstrike end~ still here\n",
            encoding='utf-8')
        strikes, *_ = dl.check_file('cross.md', fix=False, known=None)
        cases.append(('a strikethrough span across two lines is caught',
                      bool(strikes)))

        (tmp / 'same.md').write_text("a rate of ~50~ items exactly\n",
                                     encoding='utf-8')
        strikes2, *_ = dl.check_file('same.md', fix=False, known=None)
        cases.append(('a same-line strikethrough is still caught (the '
                       'original, non-regressed case)', bool(strikes2)))

        (tmp / 'clean.md').write_text(
            "Nothing strange here.\n\nAnother clean paragraph.\n",
            encoding='utf-8')
        strikes3, *_ = dl.check_file('clean.md', fix=False, known=None)
        cases.append(('clean prose with no tildes is not flagged',
                      not strikes3))

        (tmp / 'linked.md').write_text(
            "See the [user decision](thing_decision.md) for why.\n",
            encoding='utf-8')
        residue = dl.check_residue('linked.md')
        cases.append(('a link to a *_decision.md record is not flagged as '
                       'residue', not residue))

        (tmp / 'flagged.md').write_text("[verify: headcount] later.\n",
                                        encoding='utf-8')
        residue2 = dl.check_residue('flagged.md')
        cases.append(('a genuine verify-later flag is still caught',
                      bool(residue2)))

        # 2026-10-01, a consumer's published pages: the same leaks written
        # as prose passed the bracketed patterns and reached readers. Each
        # line below has the shape of one that leaked (the words are made
        # up); each must fire, and the plain prose beside them must not.
        leaked = [
            "unit prices carried from memory, rough, until checked.",
            "The vendor figures stay rough until checked against sources.",
            "and the second warehouse, which the next revision opens with.",
            "every figure checked against search-engine snippets of the page.",
            "the export case is open. The record carries the rest.",
        ]
        for n, line in enumerate(leaked):
            (tmp / f'prose{n}.md').write_text(line + "\n", encoding='utf-8')
            cases.append((f'a prose verify-later or record note is caught: '
                          f'{line[:40]}...',
                          bool(dl.check_residue(f'prose{n}.md'))))
        (tmp / 'prose-clean.md').write_text(
            "The craft revisits the site on the next pass; the pilot recalled "
            "the checklist and the tail fin was checked.\n", encoding='utf-8')
        cases.append(('plain prose near those words is not residue',
                      not dl.check_residue('prose-clean.md')))

        # REF_RE's `[^`]+` swallows a whole command line, so a backticked
        # invocation counted as an unlinked file reference -- 177 of 2,323
        # findings in this tree on 2026-09-21, none of them fixable by a
        # link. It mattered because --strict promotes this class to a
        # failure. Both halves here: the command must stop being a finding
        # AND the bare filename beside it must still be one.
        (tmp / 'command.md').write_text(
            "Run `python3 tools/doc_lint.py` before pushing.\n"
            "One file per trap, at `gotchas/gotcha-<date>-<slug>.md`, and "
            "the catalogue is `practices/*.md`.\n"
            "The rule lives in practices/very-deep-check.md, named "
            "`very-deep-check.md`.\n",
            encoding='utf-8')
        _s, cmd_unlinked, *_ = dl.check_file('command.md', fix=False, known=None)
        cases.append(('a backticked COMMAND, a glob and a <placeholder> are '
                      'not unlinked file references, while a bare filename '
                      'in the same document still is',
                      [r for _i, r in cmd_unlinked] == ['very-deep-check.md']))

        # Deep-check regression case: seen_acr used to be recorded only on
        # the VIOLATION branch (inside the `if ... f'({tok})' not in clean`
        # block), so a term correctly glossed on first use never actually
        # marked the acronym as seen -- a second, later BARE mention of the
        # same term still got flagged, defeating "expand on first use"
        # entirely for any document that used a glossed acronym twice.
        (tmp / 'glossed-twice.md').write_text(
            "Uses the pull request (PR) flow. Later, another PR lands.\n",
            encoding='utf-8')
        _s, _u, glossed_twice, *_ = dl.check_file('glossed-twice.md', fix=False, known=set())
        cases.append(("an acronym glossed on first use is not re-flagged on "
                      "a later bare mention in the same document",
                      not glossed_twice))

        (tmp / 'never-glossed.md').write_text(
            "Uses the ZQX flow. Later, another ZQX lands.\n", encoding='utf-8')
        _s, _u, never_glossed, *_ = dl.check_file('never-glossed.md', fix=False, known=set())
        cases.append(('an acronym never glossed at all is still caught '
                      '(the baseline case, not regressed by the fix above)',
                      bool(never_glossed)))

        # 2026-09-02 deep-check finding: a hyphenated filename used as its own
        # link label (the doc-references-are-links convention: `[docs-team/
        # BUSINESS-MODEL-CONCEPTS.md](docs-team/BUSINESS-MODEL-CONCEPTS.md)`)
        # split into spurious ALL-CAPS fragments at each hyphen (MODEL), since
        # _decontent only ever stripped the `](target)` half and left the
        # repeated filename label scannable. AI and AGENTS -- generic,
        # non-project-specific terms this repo's own AGENTS.md and its
        # AI-assistant boilerplate use constantly -- were never in the
        # stoplist either, so any repo's README carrying that boilerplate
        # warned on every doc_lint run.
        (tmp / 'selflink.md').write_text(
            "See [docs-team/BUSINESS-MODEL-CONCEPTS.md]"
            "(docs-team/BUSINESS-MODEL-CONCEPTS.md) for the full analysis.\n",
            encoding='utf-8')
        _s, _u, selflink_flagged, *_ = dl.check_file('selflink.md', fix=False, known=set())
        cases.append(('a hyphenated filename fragment used as its own '
                      'self-referential link label is not flagged',
                      not selflink_flagged))

        (tmp / 'reallink.md').write_text(
            "See the [ZQX report](file.md) for details.\n", encoding='utf-8')
        _s, _u, reallink_flagged, *_ = dl.check_file('reallink.md', fix=False, known=set())
        cases.append(('a real acronym inside a descriptive (non-self-'
                      'referential) link label is still caught',
                      bool(reallink_flagged)))

        (tmp / 'stoplist.md').write_text(
            "This repo's AGENTS.md tells AI assistants what to do.\n",
            encoding='utf-8')
        _s, _u, stoplist_flagged, *_ = dl.check_file(
            'stoplist.md', fix=False, known=set(dl.ACRONYM_STOP))
        cases.append(('AI and AGENTS -- generic, non-project-specific terms '
                      '-- are in the acronym stoplist and not flagged',
                      not stoplist_flagged))

        # An ALL-CAPS filename stem is a file reference, not an acronym --
        # and neither is a document naming itself in its own title. Both
        # were standing, unfixable warnings (LEDGER.md, SETUP.md's own
        # heading); the second one could only be cleared by the one person
        # who cannot clear it, the person editing that file.
        # --- the corpus rule: an initialism has no ordinary lowercase form,
        # a shouted word does. Decided from the repo's own prose, not from a
        # hand-maintained English wordlist -- a first pass at the
        # 101-warning problem added about forty such words by hand, which is
        # a list that grows forever and is wrong the first time somebody
        # shouts a word nobody thought of.
        (tmp / 'corpus_a.md').write_text(
            "We only do this before the end. only, before, end, only, before.\n"
            "The zqx index is never written in lowercase anywhere.\n".replace('zqx', 'ZZZ'),
            encoding='utf-8')
        (tmp / 'corpus_b.md').write_text(
            "You must ONLY do this BEFORE the END, per the ZQX index.\n",
            encoding='utf-8')
        dl._corpus_cache = None
        dl.corpus_word_forms()
        cases.append(('the corpus classifies a shouted English word as a word '
                      '(it appears in lowercase in the same corpus)',
                      all(dl.looks_like_a_word(w) for w in ('ONLY', 'BEFORE', 'END'))))
        cases.append(('and classifies a real initialism as an acronym (no '
                      'lowercase form anywhere in the corpus)',
                      not dl.looks_like_a_word('ZQX')))
        _s, _u, corpus_flagged, *_ = dl.check_file('corpus_b.md', fix=False, known=set())
        flagged = {tok for _i, tok in corpus_flagged}
        cases.append(('so the scan flags the initialism and leaves the shouted '
                      'words alone, with no wordlist involved',
                      'ZQX' in flagged and not ({'ONLY', 'BEFORE', 'END'} & flagged)))
        dl._corpus_cache = None

        (tmp / 'stems.md').write_text(
            "The ledger is [templates/harness/LEDGER.md](../t/LEDGER.md).\n",
            encoding='utf-8')
        _s, _u, stem_flagged, *_ = dl.check_file('stems.md', fix=False, known=set())
        cases.append(('an ALL-CAPS filename stem (LEDGER.md) is not '
                      'reported as an unglossed acronym', not stem_flagged))

        (tmp / 'SETUP.md').write_text("# SETUP - guided install\n", encoding='utf-8')
        _s, _u, selfname_flagged, *_ = dl.check_file('SETUP.md', fix=False, known=set())
        cases.append(("a document naming itself in its own title is not "
                      "reported as an unglossed acronym", not selfname_flagged))

        # 2026-09-19: precedent-team-writing's create-word-doc.md tripped the
        # acronym scan the moment a consumer repo first vendored it -- "found
        # via Part II, verified on MS Word desktop macOS 16.78.3" read "II"
        # as a brand-new unglossed acronym, on a file the consumer neither
        # wrote nor can edit (same shape as the blockquote case above:
        # acronyms-glossary gates on what a change ADDS, so a brand-new
        # vendored file has every token in it read as new). "II" is a roman
        # numeral, not an acronym -- nothing to gloss. "MS" in the same line
        # is a different case, deliberately NOT engine-exempted: it is a
        # real, ambiguous acronym (Microsoft here, but also Multiple
        # Sclerosis, Mississippi...) that this document already has a
        # convention for glossing inline ("Office Open XML (OOXML)"
        # elsewhere in the same file) -- so the scan is still expected to
        # catch it, and the fix for that line is at the source, not here.
        (tmp / 'numeral.md').write_text(
            "Found via Part II, verified on MS Word desktop.\n", encoding='utf-8')
        _s, _u, numeral_flagged, *_ = dl.check_file(
            'numeral.md', fix=False, known=set(dl.ACRONYM_STOP))
        flagged = {tok for _i, tok in numeral_flagged}
        cases.append(('a roman numeral ("Part II") is not reported as an '
                      'unglossed acronym, while a real, unglossed acronym '
                      '("MS") right beside it still is',
                      'II' not in flagged and 'MS' in flagged))
        cases.append(('the roman-numeral check is a grammar, not a stoplist '
                      '-- ZQX (a real, never-glossed acronym) does not '
                      'read as one',
                      not dl.looks_like_roman_numeral('ZQX')
                      and dl.looks_like_roman_numeral('II')))

        # --- broken relative links (check 7) -------------------------------
        # 96 links in this repo resolved to nothing before this check
        # existed; the largest group was practices/*.md written with
        # root-relative targets from a file one directory down.
        (tmp / 'tools').mkdir(exist_ok=True)
        (tmp / 'tools' / 'real.py').write_text('x\n', encoding='utf-8')
        (tmp / 'practices').mkdir(exist_ok=True)
        (tmp / 'practices' / 'p.md').write_text(
            "# Top\n"
            "Root-relative from a subdirectory: [a](tools/real.py).\n"
            "Correct: [b](../tools/real.py).\n"
            "In a code span, a value not a reference: `[c](tools/gone.py)`.\n"
            "```\n[d](tools/gone.py)\n```\n"
            "External: [e](https://example.com/x) and anchor [f](#top).\n",
            encoding='utf-8')
        dl._anchor_cache.clear()
        broken = dl.check_broken_links('practices/p.md')
        cases.append(('a root-relative link from a subdirectory is caught '
                      'as broken',
                      broken == [(2, 'tools/real.py', 'no such file')]))
        cases.append(('a correct ../ link, a link inside a code span, a link '
                      'inside a fenced block, an external URL and a bare '
                      'anchor that resolves are all left alone',
                      [t for _i, t, _w in broken] == ['tools/real.py']))

        (tmp / 'templates').mkdir(exist_ok=True)
        (tmp / 'templates' / 'README.md').write_text(
            "The engine lands at [tools/](tools/) when instantiated.\n",
            encoding='utf-8')
        cases.append(('templates/ is exempt -- its links name files in the '
                      'repo the template is instantiated INTO',
                      dl.check_broken_links('templates/README.md') == []))

        # ...but only for the PATH half. A fragment on a target that
        # resolves to a real file HERE is checked even under templates/:
        # the 2026-09-11 dead anchor in templates/document-project/README.md
        # survived a heading rename because the whole file returned [].
        # The control asserts WHICH failure, not merely that one happened
        # (practice: control-asserts-which-failure).
        (tmp / 'guide.md').write_text("# Install Into a Dependent Repo\n",
                                      encoding='utf-8')
        (tmp / 'templates' / 'anchored.md').write_text(
            "Live: [a](../guide.md#install-into-a-dependent-repo).\n"
            "Dead: [b](../guide.md#installing-into-a-repo-that-already-has-one).\n"
            "Still exempt: [c](tools/lands-there-later.py).\n",
            encoding='utf-8')
        dl._anchor_cache.clear()
        anchored = dl.check_broken_links('templates/anchored.md')
        cases.append(("a dead #fragment under templates/ IS caught, while a "
                      "live one and a path naming the instantiated tree are "
                      "not",
                      anchored == [(2, '../guide.md#installing-into-a-repo-'
                                       'that-already-has-one',
                                    'no heading makes #installing-into-a-repo-'
                                    'that-already-has-one in guide.md')]))
    finally:
        dl.ROOT = real_root
        shutil.rmtree(tmp, ignore_errors=True)

    ok = all(passed for _, passed in cases)
    for name, passed in cases:
        if not passed:
            print(f"  doc_lint did NOT behave as stated: {name}")
    check(f'doc_lint fires ({len(cases)} stated cases: cross-line and '
          f'same-line strikethrough, clean prose stays clean, a '
          f'*_decision.md link is not residue, a real verify-later flag is '
          f'still caught, a glossed acronym stays clean on reuse while an '
          f'unglossed one is still caught, a filename stem and a document '
          f'naming itself are not acronyms, the corpus rule tells a shouted '
          f'English word from a real initialism with no wordlist, and a '
          f'broken relative link is '
          f'caught while a correct one, a code span, a fenced block, a URL, '
          f'an anchor and a templates/ PATH are not -- though a dead '
          f'#fragment under templates/ is, and a backticked command, glob '
          f'or placeholder is not an unlinked reference while a bare '
          f'filename still is)', ok)


def check_doc_lint_strict_refuses_the_gate_scope():
    """--strict is the very-deep-check sweep and must never become the gate
    that was withdrawn on 2026-09-21 (practice: very-deep-check).

    The withdrawn version promoted doc_lint's warning classes to gating on
    the CHANGED-FILE scope, and refused a one-line edit over 111 warnings
    that predated it. What keeps the rebuilt flag from drifting back is one
    refusal in main(), and a refusal nothing tests is a refusal somebody
    deletes as dead code.

    Asserts the guard's own words, not just a non-zero exit
    (control-asserts-which-failure): doc_lint has three exit-2 paths and a
    bare returncode check cannot tell them apart.
    And the negative control runs the SAME argv without --strict, so a
    refusal that had become unconditional would show up as the clean case
    going red rather than as two passing tests."""
    script = ROOT / 'tools' / 'doc_lint.py'

    def run(*argv):
        r = subprocess.run([sys.executable, str(script), *argv],
                           cwd=str(ROOT), capture_output=True, text=True,
                           timeout=300)
        return r.returncode, (r.stdout or '') + (r.stderr or '')

    cases = []
    rc, out = run('--strict')
    cases.append(('--strict with no scope is refused, in its own words',
                  rc == 2 and '--strict needs a scope' in out
                  and 'not a gate' in out))
    rc, out = run('--bogus')
    cases.append(('an unknown option is refused rather than ignored',
                  rc == 2 and 'unknown option(s): --bogus' in out))
    # Negative control: the refusal is conditional on --strict. Without it,
    # the same scopeless invocation is the ordinary changed-files gate and
    # must not print the refusal at all.
    rc, out = run()
    cases.append(('the same scopeless run WITHOUT --strict is not refused '
                  '(the guard is conditional, not blanket)',
                  '--strict needs a scope' not in out and rc != 2))

    ok = all(passed for _, passed in cases)
    for name, passed in cases:
        if not passed:
            print(f"  doc_lint --strict did NOT behave as stated: {name}")
    check(f'doc_lint --strict refuses the withdrawn gate scope '
          f'({len(cases)} stated cases)', ok)


def check_practice_heading_parsing():
    """A DIRECT unit test of split_practices._parse_practice_text against
    synthetic malformed headings, since check_practice_sections_present only
    scans the real, currently-committed practices/*.md tree -- it can only
    catch a malformed heading that happens to exist right now, never prove
    the parser handles one correctly in general.

    Two stated cases, from the fix's own history: trailing whitespace on a
    heading (the original bug: "## Detail " silently merged the whole
    section into the one before it) must still parse correctly, and a
    heading with the wrong CASE ("## detail" for the one optional section)
    must fail LOUDLY rather than reproduce the identical silent merge one
    character over -- which check_practice_sections_present cannot catch for
    exactly this section, since MANDATORY_SECTIONS deliberately excludes
    'detail' as legitimately optional."""
    def body(detail_heading):
        return (
            "---\nslug: fixture\ntitle: fixture\ntier: on-demand\n"
            "severity: default\napplies_to: [\"**\"]\nchecked_by: null\n"
            "defines: []\nstatus: active\nsupersedes: []\noverrides: null\n"
            "added: null\napproved_by: fixture\n---\n"
            "## Rule\nThe rule text.\n\n"
            f"{detail_heading}\nDetail text that must not leak into Rule.\n\n"
            "## Why\nWhy text.\n\n## Story\nStory text.\n\n"
            "## Install\nInstall text.\n")

    cases = []

    # A tab, not just a trailing space, must still be tolerated.
    fm, sections = sp._parse_practice_text(body("## Detail\t"))
    cases.append(('a tab after the heading name still parses correctly',
                  sections.get('rule', '').strip() == 'The rule text.'
                  and sections.get('detail', '').strip()
                  == 'Detail text that must not leak into Rule.'))

    # The bug this check exists to close: a case typo on the one OPTIONAL
    # section must not silently merge into ## Rule -- it must be refused.
    try:
        sp._parse_practice_text(body("## detail"))
        cases.append(('a case typo on `## detail` is refused, not silently '
                       'merged into `## Rule`', False))
    except sp.PracticeFileError as e:
        cases.append(('a case typo on `## detail` is refused, not silently '
                       'merged into `## Rule`', 'detail' in str(e).lower()))

    # A real sub-heading at a DIFFERENT level (### inside a section body)
    # must not be mistaken for a malformed section marker.
    fm, sections = sp._parse_practice_text(body(
        "## Detail\n\n### A sub-heading some Detail sections use"))
    cases.append(('a `###` sub-heading inside a section body is left alone',
                  'sub-heading' in sections.get('detail', '')))

    ok = all(passed for _, passed in cases)
    for name, passed in cases:
        if not passed:
            print(f"  practice heading parsing did NOT behave as stated: {name}")
    check(f'practice section heading parsing ({len(cases)} stated cases: '
          f'whitespace tolerated, a case typo refused loudly, a deeper '
          f'sub-heading left alone)', ok)


# Widened from the original `^\*\*(\d{4}-\d{2}-\d{2}) — ` (bold date, then
# exactly an em dash with a space each side, nothing else) after a
# 2026-09-01 audit constructed plausible near-future variants -- a colon
# instead of the em-dash, an en-dash, a double-hyphen, an unbolded date, a
# leading list marker or checkbox -- and found every one silently invisible
# to `entries()` below: a non-matching entry is not merely miscounted, it
# is DROPPED from the text entirely if it sits above the first recognized
# match, which is exactly where a new entry lands under this section's own
# newest-first convention. This still cannot recognize a violation with NO
# date-like structure at all (unfixable by any regex); it substantially
# narrows the gap for the plausible near-term reformattings a human or an
# agent might actually type.
AMENDMENT_ENTRY_RE = re.compile(
    r'^\s*(?:[-*]\s+)?(?:\[[ xX]\]\s+)?\*{0,2}(\d{4}-\d{2}-\d{2})\*{0,2}'
    r'\s*(?:[:—–]|--)\s*', re.M)
# A bare substring test ('decisions/' anywhere in the entry) exempted any
# entry that merely MENTIONED the word, including "not yet migrated to
# decisions/, still keeping every word inline" -- prose about NOT having a
# record, exempted as if it were one. Requires an actual file reference.
DECISIONS_LINK_RE = re.compile(r'decisions/[\w.-]+\.md')
DECISION_LENGTH_WORDS = 120
PLAN_MD = ROOT / 'spec' / 'PRACTICE_ENGINE_PLAN.md'


def _decision_records_violations(root):
    """The check's actual logic, taking a repo root so
    check_decision_records_not_inline_fires() can exercise it against
    scratch git repositories instead of only ever running once, for real,
    against this repo's own tree. Returns (status, ok, detail): status is
    'na' (detail is the not-applicable reason) or 'checked' (detail is the
    list of violation message strings; ok is False if that list is
    non-empty).

    WHY THE COMPARISON BASE IS THE MERGE-BASE WITH @{upstream}, NOT HEAD.
    The original version gated on `git status --porcelain` being non-empty
    and compared disk content against HEAD -- so it only ever looked at
    UNCOMMITTED changes. The moment a violating amendment is committed --
    the normal state for reviewing any already-pushed branch or PR, which
    AGENTS.md itself describes as the modal review path here -- the
    porcelain check comes back empty, the function returned early with
    "was not changed", and the violation was never inspected at all.
    Confirmed live: an identical inline entry passed as UNCOMMITTED and
    silently reported not-applicable the instant it was committed, no
    diagnostic. Comparing against the upstream merge-base instead of HEAD
    also correctly covers every commit this branch has added since it
    diverged, not just the most recent one -- HEAD~1 would have missed an
    earlier commit in a multi-commit push. Falls back to HEAD when there is
    no configured upstream (a fresh checkout with no remote, a detached
    HEAD) -- narrower, but still covers the case the original check did."""
    plan_md = root / 'spec' / 'PRACTICE_ENGINE_PLAN.md'
    if not plan_md.exists():
        return 'na', True, 'PRACTICE_ENGINE_PLAN.md does not exist here'

    up = subprocess.run(['git', 'rev-parse', '--abbrev-ref',
                         '--symbolic-full-name', '@{upstream}'],
                        cwd=str(root), capture_output=True, text=True)
    base_ref = 'HEAD'
    if up.returncode == 0:
        mb = subprocess.run(['git', 'merge-base', 'HEAD', up.stdout.strip()],
                            cwd=str(root), capture_output=True, text=True)
        if mb.returncode == 0 and mb.stdout.strip():
            base_ref = mb.stdout.strip()

    new_text = plan_md.read_text(encoding='utf-8', errors='ignore')
    old_result = subprocess.run(
        ['git', 'show', f'{base_ref}:spec/PRACTICE_ENGINE_PLAN.md'],
        cwd=str(root), capture_output=True, text=True)
    old_text = old_result.stdout if old_result.returncode == 0 else ''

    if new_text == old_text:
        return 'na', True, ('PRACTICE_ENGINE_PLAN.md has not changed '
                            f'relative to {base_ref[:9]}')

    def amendments_section(text):
        """This check is about ONE section's own growth pattern
        ("Amendments Since Approval"), not the whole document -- found the
        hard way, planting a Deferred-section edit and watching it get
        swept into a single 800+-word "entry" that actually ran from the
        Amendments section's last 2026-08-31 item all the way past Settled
        Since Draft v1 into Deferred, because nothing in either of those
        later sections happens to open a line with a bold date and the
        unscoped regex kept matching across the boundary. Scoping to the
        section between its own heading and the next top-level "## " is
        what the check was always meant to measure."""
        m = re.search(r'^## Amendments Since Approval\s*$', text, re.M)
        if not m:
            return ''
        rest = text[m.end():]
        end = re.search(r'^## ', rest, re.M)
        return rest[:end.start()] if end else rest

    old_section = amendments_section(old_text)
    new_section = amendments_section(new_text)
    if new_section == old_section:
        return 'na', True, ('the Amendments Since Approval section has not '
                            f'changed relative to {base_ref[:9]}')

    def entries(text):
        starts = [m.start() for m in AMENDMENT_ENTRY_RE.finditer(text)]
        if not starts:
            return []
        starts.append(len(text))
        return [text[a:b].strip() for a, b in zip(starts, starts[1:])]

    old_entries = set(entries(old_section))
    ok = True
    messages = []
    for entry in entries(new_section):
        if entry in old_entries:
            continue          # unchanged -- not this diff's to judge
        if DECISIONS_LINK_RE.search(entry):
            continue           # already points at a real record
        words = len(entry.split())
        if words > DECISION_LENGTH_WORDS:
            ok = False
            first_line = entry.splitlines()[0][:80]
            messages.append(
                f"PRACTICE_ENGINE_PLAN.md: a new amendment entry runs "
                f"{words} words with no decisions/*.md link ({first_line!r}"
                f"...) -- split the reasoning into a decisions/<date>-"
                f"<slug>.md record and leave a short pointer here instead")
    return 'checked', ok, messages


def check_decision_records_not_inline():
    """PRACTICE_ENGINE_PLAN.md is the one document AGENTS.md tells every
    session to read "first, in full" -- and its own "Amendments Since
    Approval" section grew from 56,675 to 108,557+ bytes across phases 0-4,
    almost entirely as accumulating dated decision write-ups. This is the
    exact failure pattern that motivated this whole rewrite (RPP's
    AGENTS.md: 29,443 -> 71,059 bytes in three days), happening to the plan
    itself, and it went unnoticed until a 2026-09-01 deep-check audit found
    it. decisions/README.md instantiates the mechanism
    PRACTICE_ENGINE_PLAN.md's own "Where Decisions and History Live"
    already specified but nothing had ever built: `decisions/<date>-
    <slug>.md`, never loaded automatically. This check is what makes it
    stick -- a NEW amendment entry over DECISION_LENGTH_WORDS with no
    decisions/*.md link fails, so growing the plan the old way costs a
    build failure, not just a note nobody reads. It is deliberately NOT
    registered as a `checked_by` in tools/precedent_check.py: it is not a
    property of any cataloged practice, and registering it there would
    inflate ENFORCEMENT.md's "N of 54 practices carry a checked_by" count
    with a phantom row that no practices/*.md file backs -- found the hard
    way, by doing exactly that and watching computed-numbers-in-scripts
    correctly reject the resulting drift in spec/ENFORCEMENT.md's generated
    block. Only judges entries NEW relative to the upstream merge-base --
    the plan's own existing amendment history, which is what motivated this
    check, is not retroactively flagged; see decisions/README.md. See
    _decision_records_violations()'s docstring for why the comparison base
    is the upstream merge-base rather than HEAD or the working tree."""
    status, ok, detail = _decision_records_violations(ROOT)
    if status == 'na':
        not_applicable('decision records not inline', detail)
        return
    for msg in detail:
        print(f"  {msg}")
    check('new plan amendments stay short or point at a decisions/ record '
          '(PRACTICE_ENGINE_PLAN.md must not regrow the way it just did)', ok)


def check_decision_records_not_inline_fires():
    """Direct test of _decision_records_violations() against scratch git
    repositories -- a real gap this repo's own audit found: nothing had
    ever planted a violation and watched this check catch it, the exact
    discipline check_leak_gate_fires()/check_precedent_check_fires() apply
    to everything else. Not registered under tools/precedent_check.py (see
    check_decision_records_not_inline's own docstring for why), so this is
    its equivalent -- named _fires to match that family's convention."""
    import shutil, tempfile

    def git(cwd, *args, check_rc=True):
        r = subprocess.run(['git', '-C', str(cwd), *args],
                           capture_output=True, text=True)
        if check_rc and r.returncode != 0:
            raise RuntimeError(f"git {' '.join(args)}: {r.stderr.strip()}")
        return r.stdout.strip()

    tmp = pathlib.Path(tempfile.mkdtemp(prefix='precedent-decisionrec-'))
    cases = []
    try:
        def scratch(name, text):
            repo = tmp / name
            repo.mkdir()
            git(repo, 'init', '-q')
            git(repo, 'config', 'user.email', 'harness@example.com')
            git(repo, 'config', 'user.name', 'harness')
            (repo / 'spec').mkdir()
            (repo / 'spec' / 'PRACTICE_ENGINE_PLAN.md').write_text(
                text, encoding='utf-8')
            git(repo, 'add', '-A')
            git(repo, 'commit', '-qm', 'base')
            bare = tmp / (name + '.git')
            subprocess.run(['git', 'init', '--bare', '-q', str(bare)],
                           capture_output=True, text=True)
            git(repo, 'remote', 'add', 'origin', str(bare))
            git(repo, 'push', '-q', '-u', 'origin', 'HEAD:refs/heads/main')
            git(repo, 'branch', '--set-upstream-to=origin/main', check_rc=False)
            return repo

        base_text = ("# Plan\n\n## Amendments Since Approval\n\n"
                    "**2026-09-01 — v1, first.** Short.\n")
        long_entry = ' '.join(['word'] * 150)

        r1 = scratch('clean', base_text)
        status, ok, _detail = _decision_records_violations(r1)
        cases.append(('a clean, unchanged plan is not applicable', status == 'na'))

        # The invocation-scope bug: the old version only ever looked at
        # UNCOMMITTED changes (`git status --porcelain`). Here the violation
        # is fully committed, which used to report "not changed" and never
        # inspect the content at all.
        r2 = scratch('committed-violation', base_text)
        (r2 / 'spec' / 'PRACTICE_ENGINE_PLAN.md').write_text(
            base_text + f"\n**2026-09-02 — v2, a long one.** {long_entry}\n",
            encoding='utf-8')
        git(r2, 'add', '-A'); git(r2, 'commit', '-qm', 'inline amendment')
        status, ok, _detail = _decision_records_violations(r2)
        cases.append(('a committed (not just staged/uncommitted) inline '
                       'violation is caught', status == 'checked' and not ok))

        # A format variant (colon instead of the exact em-dash-with-spaces)
        # must still be recognized as an entry boundary. Placed ABOVE the
        # existing entry, matching this section's own newest-first
        # convention -- the shape in which the old regex made a
        # non-matching entry invisible entirely, not merely miscounted.
        r3 = scratch('colon-variant', base_text)
        (r3 / 'spec' / 'PRACTICE_ENGINE_PLAN.md').write_text(
            f"# Plan\n\n## Amendments Since Approval\n\n"
            f"**2026-09-02:** {long_entry}\n\n"
            f"**2026-09-01 — v1, first.** Short.\n", encoding='utf-8')
        git(r3, 'add', '-A'); git(r3, 'commit', '-qm', 'colon variant')
        status, ok, _detail = _decision_records_violations(r3)
        cases.append(('a colon-separated date variant is recognized as an '
                       'entry, not silently dropped',
                      status == 'checked' and not ok))

        # A bare mention of the word "decisions/" in prose, with no actual
        # file reference, must not exempt an otherwise-violating entry.
        r4 = scratch('bare-mention', base_text)
        (r4 / 'spec' / 'PRACTICE_ENGINE_PLAN.md').write_text(
            base_text + f"\n**2026-09-02 — v2, not migrated.** {long_entry} "
            f"not yet migrated to decisions/, still keeping every word "
            f"inline.\n", encoding='utf-8')
        git(r4, 'add', '-A'); git(r4, 'commit', '-qm', 'bare mention')
        status, ok, _detail = _decision_records_violations(r4)
        cases.append(('a bare mention of "decisions/" with no real link '
                       'does not exempt a long inline entry',
                      status == 'checked' and not ok))

        # A REAL decisions/*.md reference does exempt it -- the check must
        # not simply fail on every long entry regardless of content.
        r5 = scratch('real-link', base_text)
        (r5 / 'spec' / 'PRACTICE_ENGINE_PLAN.md').write_text(
            base_text + f"\n**2026-09-02 — v2, migrated.** {long_entry} see "
            f"decisions/2026-09-02-migrated.md for the reasoning.\n",
            encoding='utf-8')
        git(r5, 'add', '-A'); git(r5, 'commit', '-qm', 'real link')
        status, ok, _detail = _decision_records_violations(r5)
        cases.append(('a real decisions/*.md link exempts an otherwise-long '
                       'entry', status == 'checked' and ok))

        ok_all = all(passed for _, passed in cases)
        for name, passed in cases:
            if not passed:
                print(f"  decision records check did NOT behave as stated: {name}")
        check(f'decision records not inline fires ({len(cases)} stated '
              f'cases: committed -- not just uncommitted -- violations are '
              f'caught, a format-variant date entry is still recognized, a '
              f'bare "decisions/" mention does not exempt an entry)', ok_all)
    finally:
        shutil.rmtree(tmp, ignore_errors=True)


def check_catalogue_anchors():
    """tools/catalogue_stats.py's own ANCHORS list -- prose sentences
    elsewhere that restate a figure the script computes -- is checked by
    catalogue_stats.py's own `main()`, but nothing ever called it as part
    of this repo's actual gate suite. Found by a 2026-09-01 deep-check
    audit as the reason PRACTICE_ENGINE_PLAN.md could carry a stale "8"
    for months after spec/PRACTICE_FORMAT.md was corrected to 7, with an
    explicit note about the correction, the same day: the mechanism built
    specifically to catch this drift existed and worked, but was never
    wired to anything that runs automatically. This wires it in."""
    passes, fails = cs.check_anchors()
    for f in fails:
        print(f"  {f}")
    check(f'catalogue anchors ({len(passes) + len(fails)} stated figures: a '
          f'prose sentence citing a script-derived number must still agree '
          f'with what the script computes)', not fails)


def check_all_workflows_disclosed():
    """Every EXISTING GitHub Actions workflow file is named in
    GITHUB_ACTIONS.md -- not just newly-added ones.

    WHY THIS IS SEPARATE FROM `github-setup-disclosed`
    (tools/precedent_check.py). That check enforces the practice on a
    CHANGE: it fires on ctx.added_files() in the diff being checked, so a
    workflow merged before the practice existed to catch it -- exactly what
    happened to leak-gate.yml, found undisclosed by a 2026-09-01 deep-check
    audit -- is permanently invisible to it. Once a workflow file is
    committed, it can never again appear as "added." This check asks the
    tree-wide question instead: for every .yml/.yaml file that exists RIGHT
    NOW in .github/workflows/, is its name mentioned anywhere in
    GITHUB_ACTIONS.md? It complements the change-scoped check rather than
    replacing it -- this one runs every time regardless of what changed,
    which is what actually closes the gap the change-scoped check leaves
    open."""
    workflows_dir = ROOT / '.github' / 'workflows'
    if not workflows_dir.is_dir():
        not_applicable('all workflows disclosed', 'no .github/workflows/ directory')
        return
    doc_path = ROOT / 'documentation' / 'GITHUB_ACTIONS.md'
    if not doc_path.exists():
        check('all workflows disclosed', False,
              'no documentation/GITHUB_ACTIONS.md exists to disclose any workflow in')
        return
    doc = doc_path.read_text(encoding='utf-8', errors='ignore')
    ok = True
    for f in sorted(workflows_dir.glob('*.y*ml')):
        if f.name not in doc:
            ok = False
            print(f"  {f.name} exists in .github/workflows/ but is not named "
                  f"anywhere in GITHUB_ACTIONS.md")
    check('all workflows disclosed (every file in .github/workflows/ is '
          'named in GITHUB_ACTIONS.md)', ok)


def check_example_set():
    """The shipped example set is real, parseable, and resolvable.

    The plan ships an example set so an adopter can see what a personal set
    looks like without being shown a real one. An example that has quietly
    stopped matching the format is worse than none: it is the first thing
    someone copies. So it is held to the same parser the catalogue uses, and
    it is actually resolved -- if `overrides:` or the section list changes
    underneath it, this fails rather than the example silently teaching the
    old shape."""
    if not EXAMPLE_SET.is_dir():
        not_applicable('example practice set',
                       f'{EXAMPLE_SET.relative_to(ROOT)} does not exist')
        return
    ok = True
    files = sorted((EXAMPLE_SET / 'practices').glob('*.md'))
    if not files:
        check('example practice set', False, 'the example set holds no practices')
        return
    for f in files:
        try:
            fm, sections = sp._read_practice_file(f)
        except sp.PracticeFileError as e:
            ok = False
            print(f"  {e}")
            continue
        if fm.get('slug') != f.stem:
            ok = False
            print(f"  {f.name}: frontmatter slug {fm.get('slug')!r} does not match "
                  f"the filename")
        missing = [s for s in SECTION_ORDER if s not in sections]
        if missing:
            ok = False
            print(f"  {f.name}: missing section(s) {', '.join(missing)} -- an "
                  f"example that has drifted from the format teaches the wrong "
                  f"shape to whoever copies it")
        if not (sections.get('rule') or '').strip():
            ok = False
            print(f"  {f.name}: empty ## Rule")

    # And it must actually resolve, as somebody's individual set, against
    # this repo's universal catalogue.
    import shutil, tempfile
    tmp = pathlib.Path(tempfile.mkdtemp(prefix='precedent-example-'))
    try:
        cfg = tmp / 'user.json'
        cfg.write_text(json.dumps({'format_version': 1, 'individual': {
            'name': 'precedent-individual', 'path': str(EXAMPLE_SET)}}),
            encoding='utf-8')
        r = subprocess.run(
            [sys.executable, str(ROOT / 'tools' / 'precedent_resolve.py'),
             '--user-config', str(cfg), '--json'], capture_output=True, text=True)
        if r.returncode != 0:
            ok = False
            print(f"  the example set does not resolve: "
                  f"{(r.stdout + r.stderr).strip().splitlines()[-1:]}")
        else:
            data = json.loads(r.stdout)
            levels = {p['slug']: p['level'] for p in data['practices']}
            if not any(l == 'individual' for l in levels.values()):
                ok = False
                print("  the example set resolved but contributed no practices")
            # its one `overrides:` must still land on a universal practice that
            # exists -- an override naming a slug nobody has is a no-op that
            # looks like a working example.
            if not data['overridden']:
                ok = False
                print("  the example set's `overrides:` did not override anything "
                      "-- it names a universal slug that no longer exists")
    finally:
        shutil.rmtree(tmp, ignore_errors=True)
    check(f'example practice set ({len(files)} practices parse, match the '
          f'format, and resolve as an individual source)', ok)


def check_build_views_refuses_a_long_index_clause():
    """build_views.py refuses an on-demand index_clause over the limit that
    this repo wrote or changed, and only that one.

    2026-09-26: a clause was extended to 81 characters and build_views
    rendered it silently; only this harness knew the limit, and a push to
    pre-staging does not run it. The writer finds out from the tool it
    runs. Three states: an over-long clause the base already had passes
    (practice sets carry older ones), the same file edited is refused, and
    a consumer, whose practices/ is materialized from other sources, is
    never refused."""
    import tempfile
    n = bv.INDEX_CLAUSE_MAX + 1
    long_clause = 'x' * n

    def git(cwd, *a):
        env = dict(os.environ, PRECEDENT_ALLOW_ANY_AUTHOR='1')
        return subprocess.run(['git', '-C', str(cwd), *a],
                              capture_output=True, text=True, env=env)

    cases = []
    with tempfile.TemporaryDirectory() as td:
        root = pathlib.Path(td)
        git(root, 'init', '-q', '-b', 'main')
        (root / 'practices').mkdir()
        f = root / 'practices' / 'p.md'
        f.write_text(f'---\nindex_clause: "{long_clause}"\n---\n',
                     encoding='utf-8')
        (root / 'precedent.json').write_text('{"base_branch": "main"}\n',
                                             encoding='utf-8')
        # A practice set: a repo that authors the practices it ships.
        (root / 'tools').mkdir()
        (root / 'tools' / 'ENGINE_MANIFEST.json').write_text(
            '{"kind": "source"}', encoding='utf-8')
        git(root, 'add', '-A')
        git(root, '-c', 'user.email=f@x', '-c', 'user.name=f', 'commit', '-qm', 'a')
        git(root, 'update-ref', 'refs/remotes/origin/main', 'HEAD')
        fm = {'tier': 'on-demand', 'index_clause': long_clause}
        practices = [(fm, {}, f)]
        cases.append(('an over-long clause the base branch already had is '
                      'not refused', bv.over_long_index_clauses(practices, root) == []))
        edited = long_clause + 'y'
        f.write_text(f'---\nindex_clause: "{edited}"\n---\n', encoding='utf-8')
        got = bv.over_long_index_clauses(
            [({'tier': 'on-demand', 'index_clause': edited}, {}, f)], root)
        cases.append((f'the same clause edited is refused, with its length '
                      f'(got {got!r})', got == [(f, n + 1)]))
        # doc_lint asks the same question at the commit the clause is
        # written in (2026-10-02: a practice set's over-long clause was
        # committed and pushed, and refused only at the Debut).
        body = lambda c: (f'---\nslug: p\ntier: on-demand\nindex_clause: "{c}"\n'
                          f'---\n\n## Rule\n\nDo it.\n')
        saved_root = dl.ROOT
        try:
            dl.ROOT = root
            f.write_text(body(long_clause), encoding='utf-8')
            git(root, 'add', '-A')
            git(root, '-c', 'user.email=f@x', '-c', 'user.name=f', 'commit', '-qm', 'b')
            git(root, 'update-ref', 'refs/remotes/origin/main', 'HEAD')
            untouched = dl.check_index_clause('practices/p.md')
            f.write_text(body(edited), encoding='utf-8')
            refused = dl.check_index_clause('practices/p.md')
        finally:
            dl.ROOT = saved_root
        cases.append(('doc_lint, at the commit: an over-long clause the base '
                      'already had passes, the same clause edited is refused '
                      f'with its length (got {untouched!r} / {refused!r})',
                      untouched is None and bool(refused) and str(n + 1) in refused))
        (root / 'tools' / 'ENGINE_MANIFEST.json').write_text(
            '{"kind": "consumer"}', encoding='utf-8')
        cases.append(('a consumer is never refused -- its practices are '
                      'other sources\' to fix',
                      bv.over_long_index_clauses(
                          [({'tier': 'on-demand', 'index_clause': edited}, {}, f)],
                          root) == []))
    failed = [c for c, ok in cases if not ok]
    check(f'build_views refuses a long index_clause the writer just wrote '
          f'({len(cases)} stated cases)', not failed, '; '.join(failed))


# (path, glob, expected) -- the semantics `applies_to` is written against.
# This table exists because the path-triggered channel shipped with a bare
# fnmatch.fnmatch(path, glob), under which "**/*.md" silently never matched
# a top-level file, and NOTHING in the harness noticed: the behavioral
# replay's "independent" cross-check re-derived matches with the same
# fnmatch call, so it agreed with the bug on every commit and reported 0
# misses. A cross-check against a second copy of the same rule is not a
# check. Stating the intended semantics as literal cases is.
GLOB_CASES = [
    # a root-level file is at depth zero -- "**/" must match zero segments
    ('AGENTS.md',                          '**/*.md',                          True),
    ('README.md',                          '**/*.md',                          True),
    ('docs/guide.md',                      '**/*.md',                          True),
    ('a/b/c/deep.md',                      '**/*.md',                          True),
    ('notes.txt',                          '**/*.md',                          False),
    ('docs/notes.txt',                     '**/*.md',                          False),
    # the same file, spelled three ways, must give one answer
    ('./AGENTS.md',                        '**/*.md',                          True),
    (str(ROOT / 'AGENTS.md'),              '**/*.md',                          True),
    # a single * does not cross a directory separator
    ('docs/guide.md',                      '*.md',                             False),
    ('guide.md',                           '*.md',                             True),
    ('a/b.md',                             'a/*.md',                           True),
    ('a/b/c.md',                           'a/*.md',                           False),
    ('a/b/c.md',                           'a/**/*.md',                        True),
    ('a/c.md',                             'a/**/*.md',                        True),
    # "dir/**" is everything INSIDE dir, not dir itself
    ('process/upstream/tools/x.py',        'process/upstream/**',              True),
    ('process/upstream/x.py',              'process/upstream/**',              True),
    ('process/upstream',                   'process/upstream/**',              False),
    ('process/upstreamish/x.py',           'process/upstream/**',              False),
    # a literal path is a literal path
    ('.github/pull_request_template.md',   '.github/pull_request_template.md', True),
    ('docs/.github/pull_request_template.md',
                                           '.github/pull_request_template.md', False),
    ('README.md',                          'README.md',                        True),
    ('docs/README.md',                     'README.md',                        False),
    # "**" alone matches anything (filtered out of the path channel, but the
    # matcher still has to be right about it)
    ('anything/at/all.py',                 '**',                               True),
    ('top.py',                             '**',                               True),
]


def check_glob_semantics():
    ok = True
    for path, glob, expected in GLOB_CASES:
        got = pp.path_matches(path, glob)
        if got != expected:
            ok = False
            print(f"  {path!r} vs {glob!r}: expected {expected}, got {got}")
    check(f'path-glob semantics ({len(GLOB_CASES)} stated cases: `**` crosses "/", '
          f'`*` does not, paths normalize to repo-root-relative)', ok)


def check_symlinked_root_path_matching():
    """A path reached through a symlinked route to the repo root (a
    symlinked workspace, a Docker bind mount) must normalize the same as
    the real path. Regression case: normalize_path() used to compare only
    against ROOT's OWN resolved spelling, so a symlinked absolute path fell
    through untouched and an exact-filename glob (README.md, used by real
    practices) silently stopped matching -- no error, just a routing miss
    an ordinary session would never think to suspect."""
    import tempfile
    link = pathlib.Path(tempfile.mkdtemp(prefix='precedent-symlink-')) / 'repo-link'
    try:
        link.symlink_to(ROOT)
        exact = pp.path_matches(str(link / 'README.md'), 'README.md')
        broad = pp.path_matches(str(link / 'README.md'), '**/*.md')
        cases = [('exact-filename and broad globs match the same as the '
                  'real path', exact and broad)]

        # A relative symlink -- not just an absolute one -- must resolve the
        # same way. pathlib.Path.resolve() genuinely handles a relative
        # symlink target, but nothing had ever exercised that path here.
        rel_dir = link.parent / 'rel-repo-link'
        rel_target = os.path.relpath(ROOT, link.parent)
        rel_dir.symlink_to(rel_target)
        cases.append(('a RELATIVE symlinked repo root matches the same as '
                      'the real path',
                      pp.path_matches(str(rel_dir / 'README.md'), 'README.md')
                      and pp.path_matches(str(rel_dir / 'README.md'), '**/*.md')))
        rel_dir.unlink()

        # A symlink LOOP must degrade, not crash. normalize_path() used to
        # call pathlib.Path.resolve() unguarded, which raises RuntimeError
        # on a loop (a -> b -> a) -- an uncaught exception that would take
        # down every caller (the PreToolUse hook, behavioral_replay.py) for
        # a path that merely happens to contain a loop somewhere in it,
        # rather than falling through the way an unresolvable path already
        # does elsewhere in this function.
        loop_a, loop_b = link.parent / 'loop-a', link.parent / 'loop-b'
        loop_b.symlink_to(loop_a)
        loop_a.symlink_to(loop_b)
        try:
            pp.path_matches(str(loop_a / 'README.md'), '**/*.md')
            loop_ok = True
        except Exception as e:
            loop_ok = False
            print(f"  a symlink loop raised instead of degrading: {e!r}")
        cases.append(('a symlink loop degrades instead of crashing', loop_ok))
        loop_a.unlink(missing_ok=True)
        loop_b.unlink(missing_ok=True)

        ok = all(passed for _, passed in cases)
        for name, passed in cases:
            if not passed:
                print(f"  symlinked-root path matching did NOT behave as "
                      f"stated: {name}")
        check(f'symlinked repo root ({len(cases)} stated cases: absolute, '
              f'relative, and a symlink loop)', ok)
    finally:
        link.unlink(missing_ok=True)
        link.parent.rmdir()


def check_map_reads_each_tools_own_summary():
    """MAP.md's engine table is read from each tool's own docstring, never
    from a hand-typed table inside the generator (spec/GENERATED_FILES_PLAN.md
    step 1; Morgan, 2026-10-03: generated files are never hand-edited, a
    change goes into their sources). The failures that matter: a tool's row
    that does not follow its file, a new tool missing from the map, and the
    hand table coming back."""
    import importlib.util as _ilu, tempfile, shutil as _shutil
    name = 'MAP.md reads each tool\'s own summary line'
    src = ROOT / 'tools' / 'build_views.py'
    if not src.exists():
        not_applicable(name, 'tools/build_views.py is absent')
        return
    cases = []
    with tempfile.TemporaryDirectory() as td:
        tools = pathlib.Path(td) / 'tools'
        tools.mkdir()
        for f in ('build_views.py', 'split_practices.py', 'summary_text.py'):
            _shutil.copy2(ROOT / 'tools' / f, tools / f)
        (tools / 'zz_fixture_tool.py').write_text(
            '"""Says what the fixture tool is, on one line\n\nLonger text.\n"""\n',
            encoding='utf-8')
        spec = _ilu.spec_from_file_location('_bv_summary_fixture', tools / 'build_views.py')
        bv = _ilu.module_from_spec(spec)
        sys.path.insert(0, str(tools))
        try:
            spec.loader.exec_module(bv)
            out = bv.render_map_md([])
            cases.append(('a tool\'s row is the first line of its own docstring',
                          '| [tools/zz_fixture_tool.py](tools/zz_fixture_tool.py) | '
                          'Says what the fixture tool is, on one line |' in out))
            (tools / 'zz_fixture_tool.py').write_text(
                '"""Says something new\n"""\n', encoding='utf-8')
            out = bv.render_map_md([])
            cases.append(('editing the tool\'s docstring changes its row, with '
                          'nothing else to edit', '| Says something new |' in out))
            (tools / 'zz_fixture_tool.py').write_text('x = 1\n', encoding='utf-8')
            try:
                bv.render_map_md([])
                stopped = ''
            except SystemExit as e:
                stopped = str(e)
            cases.append(('a tool with no docstring stops the build, naming the '
                          'file to describe', 'tools/zz_fixture_tool.py' in stopped
                          and 'no module docstring' in stopped))
            cases.append(('the hand-typed table is gone from the generator',
                          not hasattr(bv, 'TOOLS_DESCRIPTIONS')))
            # Only the engine's own repository may call its map Precedent's
            # own; a set's or a consumer's map describes that repository.
            here = pathlib.Path(td) / 'elsewhere'
            (here / 'tools').mkdir(parents=True)
            (here / 'tools' / 'ENGINE_MANIFEST.json').write_text('{}', encoding='utf-8')
            (tools / 'zz_fixture_tool.py').write_text('"""A tool\n"""\n', encoding='utf-8')
            cases.append(('a map outside the engine\'s own repository introduces '
                          'that repository, not Precedent',
                          "Precedent's own repo map" not in bv.render_map_md([], root=here)
                          and "This repository's map" in bv.render_map_md([], root=here)
                          and "Precedent's own repo map" in bv.render_map_md([], root=td)))
        finally:
            sys.path.pop(0)
    real = sorted(p.name for p in (ROOT / 'tools').glob('*.py'))
    sys.path.insert(0, str(ROOT / 'tools'))
    try:
        import build_views as _bv
        undescribed = [n for n in real if not _bv.tool_summary(ROOT / 'tools' / n)]
    finally:
        sys.path.pop(0)
    cases.append(('every tool here has a summary line', not undescribed))
    failed = [n for n, ok in cases if not ok]
    check(f'{name} ({len(cases)} stated cases)', not failed,
          '; '.join(failed) + (f' -- undescribed: {undescribed}' if undescribed else ''))


def check_where_things_are_from_one_source():
    """WHERE_THINGS_ARE.md and AGENTS.md's short table are both generated
    from where_things_are.json (spec/GENERATED_FILES_PLAN.md step 2; Morgan,
    2026-10-03: a copy cites its original or is generated from one source).
    The failures that matter: the two tables disagreeing again, a row
    pointing at a path that does not exist, and a short table out of order
    or missing its pointer to the full page."""
    import json as _json, tempfile
    name = 'WHERE_THINGS_ARE.md and AGENTS.md\'s short table come from one source'
    sys.path.insert(0, str(ROOT / 'tools'))
    try:
        import build_views as bv
    finally:
        sys.path.pop(0)
    if not hasattr(bv, 'render_where_things_are'):
        not_applicable(name, 'this engine predates where_things_are.json')
        return
    cases = []
    with tempfile.TemporaryDirectory() as td:
        root = pathlib.Path(td)
        (root / 'here.md').write_text('x\n', encoding='utf-8')
        src = {'intro': ['Intro line.'], 'rows': [
            {'looking_for': 'Second quick', 'go_to': '[here.md](here.md)', 'quick': 2},
            {'looking_for': 'Full page only', 'go_to': '[here.md](here.md#a)'},
            {'looking_for': 'First quick', 'go_to': '[out](https://example.com)', 'quick': 1}]}
        (root / bv.WHERE_SOURCE).write_text(_json.dumps(src), encoding='utf-8')
        data = bv._where_source(root)
        page = bv.render_where_things_are(data)
        cases.append(('the full page carries every row, labelled as generated',
                      page.startswith('---\ngenerated_by: tools/build_views.py')
                      and all(f"| {r['looking_for']} |" in page for r in src['rows'])))
        agents = (f'before\n{bv.QUICK_BEGIN}\nstale hand row\n{bv.QUICK_END}\nafter\n')
        out = bv.splice_quick_index(agents, data)
        body = out[out.index(bv.QUICK_BEGIN):out.index(bv.QUICK_END)]
        cases.append(('the short table carries only the quick rows, in their '
                      'order, then the pointer to the full page',
                      'stale hand row' not in body and 'Full page only' not in body
                      and body.index('First quick') < body.index('Second quick')
                      < body.index('Anything else — the full index')
                      and out.startswith('before\n') and out.endswith('after\n')))
        try:
            bv.splice_quick_index('no markers\n', data)
            said = ''
        except SystemExit as e:
            said = str(e)
        cases.append(('a source with nowhere to write the short table stops the '
                      'build and says so', 'markers' in said))
        src['rows'].append({'looking_for': 'Moved away', 'go_to': '[gone](gone/file.md)'})
        (root / bv.WHERE_SOURCE).write_text(_json.dumps(src), encoding='utf-8')
        try:
            bv._where_source(root)
            said = ''
        except SystemExit as e:
            said = str(e)
        cases.append(('a row linking to a path that does not exist stops the '
                      'build, naming the row', 'gone/file.md' in said
                      and 'Moved away' in said))
    real = ROOT / bv.WHERE_SOURCE
    if real.is_file():
        agents = (ROOT / 'AGENTS.md').read_text(encoding='utf-8')
        page = (ROOT / bv.WHERE_PAGE).read_text(encoding='utf-8')
        short = agents[agents.index(bv.QUICK_BEGIN):agents.index(bv.QUICK_END)]
        rows = [l for l in short.splitlines() if l.startswith('| ')
                and not l.startswith(('| Looking', '| Anything else'))]
        cases.append(('here, every row of AGENTS.md\'s short table is in the full '
                      'page word for word', rows and all(r in page for r in rows)))
        reg = _json.loads((ROOT / 'tools' / 'generated_files.json').read_text(encoding='utf-8'))
        paths = {(e.get('path'), e.get('part')) for e in reg.get('files', [])}
        cases.append(('both are in the list of generated files',
                      (bv.WHERE_PAGE, None) in paths
                      and ('AGENTS.md', bv.QUICK_BEGIN) in paths))
    failed = [n for n, ok in cases if not ok]
    check(f'{name} ({len(cases)} stated cases)', not failed, '; '.join(failed))


def check_commit_rebuild_runs_outside_the_hook_git_env():
    """The commit-time rebuild runs its commands without the git hook's
    GIT_DIR/GIT_INDEX_FILE (2026-10-04). Inside the hook those point every
    git command at the repository being committed, so a rebuild that asks
    another repository's clone a question got this one's answer: a practice
    set's AGENTS.md came out with the person's individual practices inlined,
    and every set's Update Vendors failed its push check on it. Its own
    staging keeps the hook's index."""
    import tempfile, shutil
    name = 'the commit-time rebuild runs outside the git hook environment'
    sys.path.insert(0, str(ROOT / 'tools'))
    try:
        import precedent_regenerate as rg
    finally:
        sys.path.pop(0)
    tmp = pathlib.Path(tempfile.mkdtemp(prefix='regen-hook-env-'))
    env = dict(os.environ, GIT_AUTHOR_NAME='F', GIT_AUTHOR_EMAIL='f@x',
               GIT_COMMITTER_NAME='F', GIT_COMMITTER_EMAIL='f@x',
               GIT_CONFIG_GLOBAL=os.devnull)
    for k in ('GIT_DIR', 'GIT_INDEX_FILE', 'GIT_WORK_TREE', 'GIT_PREFIX',
              'GIT_COMMON_DIR'):
        env.pop(k, None)
    hook_vars = ('GIT_DIR', 'GIT_INDEX_FILE', 'GIT_WORK_TREE', 'GIT_PREFIX',
                 'GIT_COMMON_DIR')
    cases = []
    saved = {k: os.environ.get(k) for k in hook_vars}
    try:
        repo, other = tmp / 'repo', tmp / 'other'
        for d in (repo, other):
            subprocess.run(['git', 'init', '-q', str(d)], env=env, check=True)
        (repo / 'src.txt').write_text('x\n', encoding='utf-8')
        cmd = (f'python3 -c "import subprocess,pathlib;pathlib.Path(\'out.txt\')'
               f'.write_text(subprocess.run([\'git\',\'-C\',r\'{other}\','
               f'\'rev-parse\',\'--absolute-git-dir\'],capture_output=True,'
               f'text=True).stdout)"')
        subprocess.run(['git', '-C', str(repo), 'add', 'src.txt'], env=env, check=True)
        # The hook's environment, as git sets it for pre-commit.
        os.environ['GIT_DIR'] = str(repo / '.git')
        os.environ['GIT_INDEX_FILE'] = str(repo / '.git' / 'index')
        staged = rg.regenerate(repo, [{'path': 'out.txt', 'regenerate': cmd,
                                       'inputs': ['src.txt']}], say=lambda m: None)
        got = (repo / 'out.txt').read_text(encoding='utf-8').strip() \
            if (repo / 'out.txt').is_file() else ''
        cases.append(('a rebuild asking ANOTHER repository gets that repository\'s '
                      'answer, not the one being committed',
                      got == str((other / '.git').resolve()), got))
        idx = subprocess.run(['git', '-C', str(repo), 'diff', '--cached', '--name-only'],
                             env=env, capture_output=True, text=True).stdout.split()
        cases.append(('...and what it rewrote is staged into the commit\'s index',
                      'out.txt' in idx and 'out.txt' in staged, f'{idx} {staged}'))
    except (OSError, subprocess.CalledProcessError) as e:
        cases.append((f'fixture could not be built ({e})', False, ''))
    finally:
        for k, v in saved.items():
            if v is None:
                os.environ.pop(k, None)
            else:
                os.environ[k] = v
        shutil.rmtree(tmp, ignore_errors=True)
    failed = [f'{n} -- {d}' for n, ok, d in cases if not ok]
    check(f'{name} ({len(cases)} stated cases)', not failed, '; '.join(failed))


def check_commit_rebuilds_generated_files():
    """The commit backstop rebuilds the generated files whose inputs a commit
    touches and stages them (spec/GENERATED_FILES_PLAN.md step 3; Morgan,
    2026-10-03: generated files are auto-updated as their sources change).
    The failures that matter: a stale generated file committed with no one
    noticing; a rebuild that sweeps unstaged work into the commit or
    overwrites it unrecoverably (practice: repair-cannot-discard-work); a
    fixer that blocks a commit; and running what cannot be rebuilt offline."""
    import json as _json, tempfile, shutil as _shutil
    name = 'a commit rebuilds and stages the generated files its sources feed'
    tool = ROOT / 'tools' / 'precedent_regenerate.py'
    hook_src = ROOT / '.claude' / 'hooks' / 'commit-identity.sh'
    if not tool.exists() or not hook_src.exists():
        not_applicable(name, 'tools/precedent_regenerate.py or the commit hook is absent')
        return
    cases = []
    with tempfile.TemporaryDirectory() as td:
        tmp = pathlib.Path(td)
        work = tmp / 'work'
        (work / 'tools').mkdir(parents=True)
        env = dict(os.environ, PRECEDENT_ALLOW_ANY_AUTHOR='1',
                   GIT_AUTHOR_NAME='T', GIT_AUTHOR_EMAIL='t@example.com',
                   GIT_COMMITTER_NAME='T', GIT_COMMITTER_EMAIL='t@example.com',
                   GIT_CONFIG_GLOBAL=str(tmp / 'gitconfig'), HOME=str(tmp))

        def git(*a):
            return subprocess.run(['git', '-C', str(work), *a],
                                  capture_output=True, text=True, env=env)
        git('init', '-q', '-b', 'main')
        _shutil.copy2(tool, work / 'tools' / 'precedent_regenerate.py')
        # A generator that writes OUT.md from src/*.txt and leaves a mark
        # each time it runs; one that always fails; one that must never run.
        (work / 'tools' / 'gen.py').write_text(
            'import pathlib\n'
            'pathlib.Path("RAN").write_text("x")\n'
            'parts = sorted(pathlib.Path("src").glob("*.txt"))\n'
            'pathlib.Path("OUT.md").write_text("".join(p.read_text() for p in parts))\n',
            encoding='utf-8')
        (work / 'tools' / 'snap.py').write_text(
            'import pathlib\npathlib.Path("SNAP_RAN").write_text("x")\n', encoding='utf-8')
        (work / 'src').mkdir()
        (work / 'src' / 'a.txt').write_text('a\n', encoding='utf-8')
        (work / 'OUT.md').write_text('a\n', encoding='utf-8')
        (work / 'SNAP.md').write_text('snapshot\n', encoding='utf-8')
        (work / 'tools' / 'generated_files.json').write_text(_json.dumps({'files': [
            {'path': 'OUT.md', 'generated_by': 'tools/gen.py', 'edit_instead': 'src/*.txt',
             'regenerate': 'python3 tools/gen.py', 'check': ['tools/gen.py']},
            {'path': 'SNAP.md', 'generated_by': 'tools/snap.py', 'edit_instead': None,
             'regenerate': 'python3 tools/snap.py', 'check': None}]}), encoding='utf-8')
        (work / '.gitignore').write_text('RAN\nSNAP_RAN\n', encoding='utf-8')
        git('add', '-A')
        git('commit', '-q', '-m', 'init')
        # The real hook's fixer block, cut from commit-identity.sh, as this
        # fixture's own pre-commit hook.
        text = hook_src.read_text(encoding='utf-8')
        start = text.index("# The engine's own commit-time fixer")
        end = text.index('esac', start) + len('esac')
        block = text[start:end].replace('\\$', '$')
        hooks = tmp / 'hooks'
        hooks.mkdir()
        (hooks / 'pre-commit').write_text('#!/bin/sh\n' + block + '\nexit 0\n', encoding='utf-8')
        (hooks / 'pre-commit').chmod(0o755)
        git('config', 'core.hooksPath', str(hooks))

        def commit(msg):
            r = git('commit', '-q', '-m', msg)
            return r.returncode, r.stdout + r.stderr

        # 1. A source changes; the generated file is rebuilt and in the commit.
        (work / 'src' / 'b.txt').write_text('b\n', encoding='utf-8')
        git('add', 'src/b.txt')
        rc, out = commit('add a source')
        shown = git('show', 'HEAD:OUT.md').stdout
        cases.append(('a commit touching a source carries the rebuilt generated '
                      'file, and says so', rc == 0 and shown == 'a\nb\n'
                      and 'rebuilt and staged OUT.md' in out))
        # 2. Nothing the generator reads: it does not run.
        (work / 'RAN').unlink()
        (work / 'notes.txt').write_text('n\n', encoding='utf-8')
        git('add', 'notes.txt')
        rc, out = commit('unrelated')
        cases.append(('an unrelated commit runs no generator', rc == 0
                      and not (work / 'RAN').exists()))
        # Its own generator changes, which would make any other entry due.
        (work / 'tools' / 'snap.py').write_text(
            'import pathlib\npathlib.Path("SNAP_RAN").write_text("y")\n', encoding='utf-8')
        git('add', 'tools/snap.py')
        rc, out = commit('touch the snapshot generator')
        cases.append(('an entry nothing offline can rebuild never runs, even when '
                      'its own generator changes', rc == 0
                      and not (work / 'SNAP_RAN').exists()))
        # 3. Unstaged changes of the session's own in the generated file:
        # rebuilt, NOT staged, and said.
        (work / 'OUT.md').write_text('a\nb\nmy unstaged note\n', encoding='utf-8')
        (work / 'src' / 'c.txt').write_text('c\n', encoding='utf-8')
        git('add', 'src/c.txt')
        rc, out = commit('source with unstaged generated edits')
        cases.append(('a generated file with unstaged changes is not swept into '
                      'the commit, and the commit says so',
                      rc == 0 and 'NOT added to this commit' in out
                      and git('show', 'HEAD:OUT.md').stdout == 'a\nb\n'))
        git('checkout', '-q', '--', 'OUT.md')
        # 4. A staged hand edit to the generated file, then a source change:
        # rebuilt and committed, and the hand edit kept, not lost.
        (work / 'OUT.md').write_text('hand edit\n', encoding='utf-8')
        (work / 'src' / 'd.txt').write_text('d\n', encoding='utf-8')
        git('add', 'OUT.md', 'src/d.txt')
        rc, out = commit('hand edit plus source')
        kept = work / '.git' / 'precedent-regenerate' / 'OUT.md'
        cases.append(('a hand edit the rebuild replaces is kept, said, and the '
                      'commit carries the rebuilt file', rc == 0
                      and kept.is_file() and kept.read_text() == 'hand edit\n'
                      and 'is kept at' in out
                      and git('show', 'HEAD:OUT.md').stdout == 'a\nb\nc\nd\n'))
        # 4b. A generated block inside a hand-written document (doc_sync.py's
        # kind) is refreshed when a commit touches what its script reads, and
        # a document with unstaged changes of its own is not swept in.
        (work / 'tools' / 'doc_sync.py').write_text(
            'import pathlib, sys\n'
            'n = len(list(pathlib.Path("src").glob("*.txt")))\n'
            'p = pathlib.Path("BLOCKS.md")\n'
            'new = f"Sources: <!--gen:n-->{n}<!--/gen:n-->\\n" + p.read_text().split("\\n", 1)[1]\n'
            'if "--write" in sys.argv and new != p.read_text():\n'
            '    p.write_text(new); print("[doc_sync] WROTE BLOCKS.md [n]")\n',
            encoding='utf-8')
        (work / 'BLOCKS.md').write_text('Sources: <!--gen:n-->0<!--/gen:n-->\nHand text.\n',
                                        encoding='utf-8')
        git('add', 'tools/doc_sync.py', 'BLOCKS.md')
        git('commit', '-q', '-m', 'a document with a generated block')
        cases.append(('a generated block inside a document is refreshed and committed '
                      'with the change that moved it',
                      git('show', 'HEAD:BLOCKS.md').stdout.startswith(
                          'Sources: <!--gen:n-->4<!--/gen:n-->')))
        (work / 'BLOCKS.md').write_text(
            (work / 'BLOCKS.md').read_text(encoding='utf-8') + 'My unstaged edit.\n',
            encoding='utf-8')
        (work / 'src' / 'f.txt').write_text('f\n', encoding='utf-8')
        (work / 'tools' / 'gen.py').write_text(
            'import pathlib\n'
            'parts = sorted(pathlib.Path("src").glob("*.txt"))\n'
            'pathlib.Path("OUT.md").write_text("".join(p.read_text() for p in parts))\n',
            encoding='utf-8')
        git('add', 'src/f.txt', 'tools/gen.py')
        rc, out = commit('a source, with an unstaged edit in the document')
        cases.append(('...but a document with unstaged changes of its own is not '
                      'swept into the commit, and it says so',
                      rc == 0 and 'Hand text.\n' == git('show', 'HEAD:BLOCKS.md').stdout.split('\n', 1)[1]
                      and 'blocks in BLOCKS.md' in out and 'NOT added' in out))
        git('checkout', '-q', '--', 'BLOCKS.md')
        # 5. A generator that fails never blocks the commit.
        (work / 'tools' / 'gen.py').write_text('raise SystemExit(3)\n', encoding='utf-8')
        (work / 'src' / 'e.txt').write_text('e\n', encoding='utf-8')
        git('add', 'tools/gen.py', 'src/e.txt')
        rc, out = commit('a broken generator')
        cases.append(('a failing generator never blocks the commit, and says '
                      'what failed', rc == 0 and 'failed' in out))
    failed = [n for n, ok in cases if not ok]
    check(f'{name} ({len(cases)} stated cases)', not failed, '; '.join(failed))


def check_no_duplication_refuses_a_sets_copy_of_a_universal_rule():
    """A practice set may not carry an active copy of a practice its declared
    universal source has active; it adds to it in a practice of its own
    (Morgan, 2026-10-06: "rules should not be repeated, but supporting repos
    can have additions for them"). Planted end to end in a fixture set
    beside a fixture universal: the copy is refused, naming the way out; an
    addition under its own slug, a deduplicated copy and a retired set all
    pass."""
    import shutil as _sh
    import tempfile as _tf
    def prac(slug, status):
        return (f'---\nslug: {slug}\ntitle: T\ntier: on-demand\nseverity: default\n'
                f'applies_to: ["**"]\noccasion: "x"\ndefines: []\nstatus: {status}\n'
                f'---\n## Rule\nx\n\n## Why\nx\n\n## Story\nx\n\n## Install\nx\n')
    cases = []
    with _tf.TemporaryDirectory() as td:
        base = pathlib.Path(td)
        uni = base / 'uni'
        (uni / 'practices').mkdir(parents=True)
        (uni / 'practices' / 'shared-rule.md').write_text(prac('shared-rule', 'active'), encoding='utf-8')
        (uni / 'precedent-source.json').write_text(json.dumps({'level': 'universal', 'name': 'precedent'}), encoding='utf-8')
        st = base / 'set'
        (st / 'practices').mkdir(parents=True)
        _sh.copytree(ROOT / 'tools', st / 'tools', ignore=_sh.ignore_patterns('__pycache__'))
        # What makes a repository a practice SOURCE to the engine: the kind
        # its vendored engine's manifest declares (_publishes_practices).
        (st / 'tools' / 'ENGINE_MANIFEST.json').write_text(json.dumps(
            {'format_version': 1, 'kind': 'source', 'files': []}), encoding='utf-8')
        (st / 'precedent.json').write_text(json.dumps({'sources': [
            {'level': 'universal', 'name': 'precedent', 'path': '../uni'}]}), encoding='utf-8')
        meta = {'level': 'shared', 'name': 'set'}
        (st / 'precedent-source.json').write_text(json.dumps(meta), encoding='utf-8')
        (st / 'practices' / 'shared-rule-on-set.md').write_text(prac('shared-rule-on-set', 'active'), encoding='utf-8')

        def run():
            r = subprocess.run([sys.executable, 'tools/precedent_check.py', '--only',
                                'no-duplication'], cwd=st, capture_output=True, text=True,
                               env=dict(os.environ, PRECEDENT_USER_CONFIG=str(base / 'none.json')))
            return r.stdout + r.stderr
        out = run()
        cases.append(('an addition under its own slug passes', ' 0 violated' in out and '1 passed' in out))
        (st / 'practices' / 'shared-rule.md').write_text(prac('shared-rule', 'active'), encoding='utf-8')
        out = run()
        cases.append(('an active copy of a universal rule is refused, naming the way out',
                      ' 1 violated' in out and 'practices/shared-rule.md' in out
                      and 'add' in out and 'deduplicated' in out))
        (st / 'practices' / 'shared-rule.md').write_text(prac('shared-rule', 'deduplicated'), encoding='utf-8')
        out = run()
        cases.append(('a deduplicated copy passes', ' 0 violated' in out))
        (st / 'practices' / 'shared-rule.md').write_text(prac('shared-rule', 'active'), encoding='utf-8')
        (st / 'precedent-source.json').write_text(json.dumps(dict(meta, retired={'date': '2026-10-06'})), encoding='utf-8')
        out = run()
        cases.append(('a retired set is passed over', ' 0 violated' in out and 'retired' in out))
    failed = [n for n, ok in cases if not ok]
    check(f'no-duplication refuses a set\'s copy of a universal rule ({len(cases)} '
          f'stated cases)', not failed, '; '.join(failed))


def check_sync_does_not_call_a_held_back_check_an_orphan():
    """A sync names as orphaned only a check no practice file claims. A check
    whose own source's practice file names it in `checked_by` -- a rule that
    source keeps out of force on purpose, as a deduplicated copy whose check
    still runs in its own repository -- is not vendored and not reported.
    Reported from a consumer, 2026-10-06: every sync listed the individual
    set's three such checks as orphans."""
    import contextlib, io, tempfile as _tf
    sys.path.insert(0, str(ROOT / 'tools'))
    try:
        import precedent_materialize as pm
    finally:
        sys.path.pop(0)
    cases = []
    with _tf.TemporaryDirectory() as td:
        src = pathlib.Path(td) / 'set'
        (src / 'tools' / 'checks' / 'tests').mkdir(parents=True)
        (src / 'practices').mkdir()
        for stem in ('kept', 'lost'):
            (src / 'tools' / 'checks' / f'check_{stem}.py').write_text('x = 1\n', encoding='utf-8')
            (src / 'tools' / 'checks' / 'tests' / f'test_{stem}.sh').write_text('true\n', encoding='utf-8')
        (src / 'practices' / 'kept.md').write_text(
            '---\nslug: kept\nchecked_by:  tools/checks/check_kept.py\n'
            'status:      deduplicated\n---\n## Rule\nx\n', encoding='utf-8')
        err = io.StringIO()
        with contextlib.redirect_stderr(err):
            plan = pm._plan_checks([{'name': 'set', 'path': str(src), 'level': 'shared'}],
                                   {'practices': {}})
        note = [l for l in err.getvalue().splitlines() if 'no practice in force' in l]
        note = note[0] if note else ''
        cases.append(('a check no practice file claims is still reported',
                      'check_lost.py' in note and 'test_lost.sh' in note))
        cases.append(('a check its own source\'s practice file claims is not',
                      'check_kept.py' not in note and 'test_kept.sh' not in note))
        cases.append(('...and neither is vendored here',
                      not any(name in ('check_kept.py', 'check_lost.py')
                              for _r, name, _s, _d in plan)))
    failed = [n for n, ok in cases if not ok]
    check(f'a sync does not call a held-back check an orphan ({len(cases)} '
          f'stated cases)', not failed, '; '.join(failed))


def check_update_drops_the_dead_blank_blocklist_link():
    """Update Vendors drops the retired install pack's dead link to
    personal/README.md#blank-blocklist from a repository's process/ files,
    keeping the sentence, exactly as a consumer fixed its own by hand
    (2026-10-06). The same text with no link, and the link in a file
    outside process/, are left alone."""
    import tempfile as _tf
    import precedent_update as pu
    line = ("# Left blank at install ([`blank-blocklist`](personal/README.md"
            "#blank-blocklist)): Morgan doesn't use the\n")
    cases = []
    with _tf.TemporaryDirectory() as td:
        repo = pathlib.Path(td)
        (repo / 'process').mkdir()
        f = repo / 'process' / 'scrub_blocklist.txt'
        f.write_text('# head\n' + line + 'word\n', encoding='utf-8')
        other = repo / 'README.md'
        other.write_text(line, encoding='utf-8')
        fixed = pu.drop_dead_blank_blocklist_link(repo)
        cases.append(('the link is dropped and the sentence kept',
                      fixed == ['process/scrub_blocklist.txt'] and
                      f.read_text(encoding='utf-8') ==
                      "# head\n# Left blank at install: Morgan doesn't use the\nword\n"))
        cases.append(('a second run changes nothing',
                      pu.drop_dead_blank_blocklist_link(repo) == []))
        cases.append(('a file outside process/ is not touched',
                      other.read_text(encoding='utf-8') == line))
    failed = [n for n, ok in cases if not ok]
    check(f'Update Vendors drops the dead blank-blocklist link ({len(cases)} '
          f'stated cases)', not failed, '; '.join(failed))


def check_session_start_charges_brought_sets_to_the_person():
    """The session-start check holds the sets a person brings to that
    person's `brought_sets_tokens` budget, never to the repository's ceiling,
    as the full check's session-load-budget already did (2026-10-03).
    Reported from a consumer, 2026-10-06: its ceiling, set before the ladder
    started arriving by `brings`, failed a guarantee at every session start.
    Planted with stand-ins for the share and the budget."""
    sys.path.insert(0, str(ROOT / 'tools'))
    try:
        import precedent_session_check as psc
        import precedent_session_practices as psp
    finally:
        sys.path.pop(0)
    saved = (psp.brought_share, psp.brought_budget)
    cases = []
    try:
        psp.brought_share = lambda repo=None: (600, ['precedent-shared-ladder'])
        psp.brought_budget = lambda repo=None: (700, '/ind')
        n, note, over = psc._charge_brought_share(1500)
        cases.append(('the brought share leaves the repository\'s count',
                      n == 900 and 'which you bring' in note and over is None))
        psp.brought_budget = lambda repo=None: (500, '/ind')
        n, note, over = psc._charge_brought_share(1500)
        cases.append(('over the person\'s own budget, that is what is reported',
                      n == 900 and over and 'brought_sets_tokens' in over))
        psp.brought_budget = lambda repo=None: (None, '/ind')
        n, note, over = psc._charge_brought_share(1500)
        cases.append(('no budget declared: charged to the repository, as before',
                      n == 1500 and note == '' and over is None))
        psp.brought_share = lambda repo=None: (0, [])
        psp.brought_budget = lambda repo=None: (700, '/ind')
        cases.append(('nothing brought: unchanged',
                      psc._charge_brought_share(1500) == (1500, '', None)))
    finally:
        psp.brought_share, psp.brought_budget = saved
    failed = [nm for nm, ok in cases if not ok]
    check(f'the session-start check charges brought sets to the person '
          f'({len(cases)} stated cases)', not failed, '; '.join(failed))


def check_update_seeds_the_session_load_registry():
    """Update Vendors gives a repository with no
    tools/session_load_budgets.json one seeded at today's sizes, so the
    session-load-budget check binds there instead of skipping on every run
    (Alex, 2026-10-04: "If it is already a best practice, why didn't we
    adopt?" -- a consumer's instructions file had grown to about 38,000
    tokens behind a skip). Both directions: an existing registry, however
    small, is never touched, and a second run writes nothing. A registry it
    seeds carries baseline approvals; one that existed without them is named
    in the report, never filled in (2026-10-06)."""
    import tempfile
    import precedent_update as pu
    name = 'Update Vendors seeds a missing session-load registry'
    cases = []
    with tempfile.TemporaryDirectory() as td:
        repo = pathlib.Path(td)
        (repo / 'CLAUDE.md').write_text('word ' * 4000, encoding='utf-8')
        (repo / 'AGENTS.md').write_text('word ' * 300, encoding='utf-8')
        seeded = pu.ensure_session_load_registry(repo)
        reg = json.loads((repo / 'tools' / 'session_load_budgets.json')
                         .read_text(encoding='utf-8'))
        s = reg.get('surfaces', {})
        cases.append(('both surfaces are declared, each ceiling at or above '
                      'what it measures', set(s) == {'CLAUDE.md', 'AGENTS.md'}
                      and all(s[k]['ceiling'] >= (seeded[k] or 0) for k in s)))
        cases.append(('the early-warning floor is on', reg.get('headroom_floor_pct') == 5))
        cases.append(('it says it was seeded at Update Vendors',
                      'Update Vendors' in s['CLAUDE.md'].get('_note', '')))
        ap = reg.get('approved_budgets') or {}
        cases.append(('a registry it seeds carries a baseline approval for every '
                      'budget, so budget-within-approval binds from the start '
                      '(2026-10-06)', bool(ap) and all(
                          e.get('strength') == 'baseline' and isinstance(e.get('max'), int)
                          and 'Update Vendors' in e.get('approved_by', '')
                          for e in ap.values())))
        cases.append(('...and the report then names no approval gap',
                      pu.approval_gap(repo) is None))
        cases.append(('...each at the number in force in THIS repo, never the '
                      'engine clone\'s own (2026-10-06: a consumer was seeded '
                      'with BestPractice\'s numbers, and its first check refused '
                      'all of them as unapproved raises)',
                      (ap.get('surfaces/CLAUDE.md') or {}).get('max')
                      == s['CLAUDE.md']['ceiling']))
        before = (repo / 'tools' / 'session_load_budgets.json').read_bytes()
        again = pu.ensure_session_load_registry(repo)
        cases.append(('a second run writes nothing', again is None and before ==
                      (repo / 'tools' / 'session_load_budgets.json').read_bytes()))
    with tempfile.TemporaryDirectory() as td:
        repo = pathlib.Path(td)
        (repo / 'tools').mkdir()
        mine = '{"surfaces": {"CLAUDE.md": {"ceiling": 10}}}\n'
        (repo / 'tools' / 'session_load_budgets.json').write_text(mine, encoding='utf-8')
        (repo / 'CLAUDE.md').write_text('word ' * 4000, encoding='utf-8')
        cases.append(('an existing registry is never touched, even one over its ceiling',
                      pu.ensure_session_load_registry(repo) is None and
                      (repo / 'tools' / 'session_load_budgets.json').read_text(
                          encoding='utf-8') == mine))
        gap = pu.approval_gap(repo) or ''
        cases.append(('an existing registry with no approved_budgets is named in '
                      'the report, never filled in (a hand-made raise would be '
                      'recorded as approved)', 'no approved_budgets' in gap
                      and 'baseline' in gap and (repo / 'tools' /
                      'session_load_budgets.json').read_text(encoding='utf-8') == mine))
    failed = [n for n, ok in cases if not ok]
    check(f'{name} ({len(cases)} stated cases)', not failed, '; '.join(failed))

def check_source_directory_splits_and_assembles():
    """MAP.source.md and GLOSSARY.source.md may live as directories, one
    file per heading and per table row, so two branches that each add a row
    add two files and never conflict (build_views.py, THE SOURCE AS A
    DIRECTORY; Alex, 2026-10-04). What can go wrong is all loss or drift:
    a split that changes a word, a row added between two others that lands
    in the wrong place, a heading inside a code fence taken for a section,
    a repository holding both forms with nobody told, a commit to the
    directory that does not rebuild the view, and a view that stops
    carrying the repository's own text."""
    import tempfile, fnmatch
    import precedent_migrate_views as mv
    name = 'a source directory splits and assembles word for word'
    cases = []
    text = ('# Repository map\n\nIntro line.\n\n'
            '## Layout\n\nWhat lives where.\n\n| Path | What |\n|---|---|\n'
            '| `a/` | first |\n| `b/` | second |\n| `c/` | third |\n\nAfter the table.\n\n'
            '## Notes\n\n```\n## not a heading\n```\n\nPlain.\n')
    entries = mv.split_entries(text)
    with tempfile.TemporaryDirectory() as td:
        d = pathlib.Path(td) / 'MAP.source'
        for rel, content in entries.items():
            (d / rel).parent.mkdir(parents=True, exist_ok=True)
            (d / rel).write_text(content, encoding='utf-8')
        cases.append(('the split reassembles to the same text, exactly',
                      bv.assemble_source_dir(d) == text.strip('\n')))
        sec = [r for r in entries if r.endswith('/' + bv.SECTION_HEAD)]
        cases.append(('the table section is split into head, rows and tail',
                      len(sec) == 1 and sum(1 for r in entries if r.startswith(
                          sec[0].split('/')[0] + '/')) == 5))
        cases.append(('a heading inside a code fence is not a section',
                      not any('not-a-heading' in r for r in entries)))
        secdir = d / sec[0].split('/')[0]
        (secdir / '0015-ab.md').write_text('| `ab/` | between |\n', encoding='utf-8')
        out = bv.assemble_source_dir(d)
        cases.append(('a row added as 0015- lands between rows 0010- and 0020-',
                      out.index('`a/`') < out.index('`ab/`') < out.index('`b/`')))
        cases.append(('the directory counts as the source',
                      bv.has_own_source(td, 'MAP.source.md')
                      and bv.own_source_label(td, 'MAP.source.md') == 'MAP.source/'))
        (pathlib.Path(td) / 'MAP.source.md').write_text('x\n', encoding='utf-8')
        try:
            bv.own_source_path(td, 'MAP.source.md')
            both = False
        except SystemExit:
            both = True
        cases.append(('holding both the file and the directory is refused', both))
    entry = next(e for e in json.loads((ROOT / 'tools' / 'generated_files.json')
                                       .read_text(encoding='utf-8'))['files']
                 if e.get('path') == 'MAP.md' and not e.get('part'))
    cases.append(('a commit to a row file rebuilds MAP.md',
                  any(fnmatch.fnmatch('MAP.source/0020-layout/0015-ab.md', g)
                      for g in entry['inputs'])))
    # End to end: a repository's one-file source split, then its view rebuilt.
    with tempfile.TemporaryDirectory() as td:
        repo = pathlib.Path(td) / 'consumer'
        (repo / 'practices').mkdir(parents=True)
        (repo / 'practices' / 'zz-fixture.md').write_text(
            '---\nslug:        zz-fixture\ntitle:       A fixture practice\n'
            'tier:        on-demand\nseverity:    default\napplies_to:  ["fixture/**"]\n'
            'occasion:    "fixture"\ngates:       []\nindex_clause: "fixture"\n'
            'checked_by:  null\ndefines:     ["Fixture Term"]\nstatus:      active\n'
            'in_force_at: null\nsupersedes:  []\noverrides:   null\nadded:       "2026-10-04"\n'
            'approved_by: "Fixture, 2026-10-04"\n---\n\n## Rule\nDo it.\n\n## Why\nBecause.\n\n'
            '## Story\nOnce.\n', encoding='utf-8')
        (repo / 'AGENTS.md').write_text(
            '# Agents\n\n<!-- BEGIN GENERATED: precedent-loader -->\n'
            '<!-- END GENERATED -->\n', encoding='utf-8')
        (repo / 'MAP.source.md').write_text(text, encoding='utf-8')
        subprocess.run([sys.executable, str(ROOT / 'tools' / 'build_views.py'), '--repo',
                        str(repo), '--views-only'], capture_output=True, text=True)
        before = (repo / 'MAP.md').read_text(encoding='utf-8') if (repo / 'MAP.md').exists() else ''
        r = subprocess.run([sys.executable, str(ROOT / 'tools' / 'precedent_migrate_views.py'),
                            '--repo', str(repo), '--split'], capture_output=True, text=True)
        after = (repo / 'MAP.md').read_text(encoding='utf-8') if (repo / 'MAP.md').exists() else ''
        strip_label = lambda t: t.split('\n---\n', 1)[-1]
        cases.append(('--split replaces the file with the directory',
                      r.returncode == 0 and (repo / 'MAP.source').is_dir()
                      and not (repo / 'MAP.source.md').exists()))
        cases.append(('...and the rebuilt view carries the same text',
                      bool(before) and strip_label(before) == strip_label(after)
                      and 'Intro line.' in after and '`c/`' in after))
    failed = [n for n, ok in cases if not ok]
    check(f'{name} ({len(cases)} stated cases)', not failed, '; '.join(failed))

def check_migrate_views_keeps_every_word():
    """precedent_migrate_views.py moves a hand-written MAP.md and GLOSSARY.md
    into MAP.source.md and GLOSSARY.source.md and generates both from then
    on (spec/GENERATED_FILES_PLAN.md step 5; Morgan, 2026-10-03). The
    failures that matter are all losses: a word of the repository's own text
    missing after regeneration, a failed migration that leaves things half
    changed (practice: repair-cannot-discard-work), a view a vendor update
    already overwrote that cannot be brought back, and a second run that
    disturbs a migrated repository."""
    import tempfile, json as _json
    name = 'migrating the views keeps every word a repository wrote'
    tool = ROOT / 'tools' / 'precedent_migrate_views.py'
    if not tool.exists():
        not_applicable(name, 'tools/precedent_migrate_views.py is absent')
        return
    cases = []
    with tempfile.TemporaryDirectory() as td:
        repo = pathlib.Path(td) / 'consumer'
        (repo / 'practices').mkdir(parents=True)
        env = dict(os.environ, PRECEDENT_ALLOW_ANY_AUTHOR='1',
                   GIT_AUTHOR_NAME='T', GIT_AUTHOR_EMAIL='t@example.com',
                   GIT_COMMITTER_NAME='T', GIT_COMMITTER_EMAIL='t@example.com',
                   GIT_CONFIG_GLOBAL=str(pathlib.Path(td) / 'gitconfig'),
                   PRECEDENT_USER_CONFIG=str(pathlib.Path(td) / 'none.json'))

        def git(*a):
            return subprocess.run(['git', '-C', str(repo), *a], capture_output=True,
                                  text=True, env=env)

        def migrate(*a):
            r = subprocess.run([sys.executable, str(tool), '--repo', str(repo), *a],
                               capture_output=True, text=True, env=env)
            return r.returncode, r.stdout + r.stderr
        (repo / 'practices' / 'zz-fixture.md').write_text(
            '---\nslug:        zz-fixture\ntitle:       A fixture practice\n'
            'tier:        on-demand\nseverity:    default\napplies_to:  ["fixture/**"]\n'
            'occasion:    "fixture"\ngates:       []\nindex_clause: "fixture"\n'
            'checked_by:  null\ndefines:     ["Fixture Term"]\nstatus:      active\n'
            'in_force_at: null\nsupersedes:  []\noverrides:   null\nadded:       "2026-10-03"\n'
            'approved_by: "Fixture, 2026-10-03"\n---\n\n## Rule\nDo it.\n\n## Why\nBecause.\n\n'
            '## Story\nOnce.\n', encoding='utf-8')
        (repo / 'AGENTS.md').write_text(
            '# Agents\n\n<!-- BEGIN GENERATED: precedent-loader -->\n'
            '<!-- END GENERATED -->\n', encoding='utf-8')
        hand_map = ('<!-- Last updated: 2026-09-30 by Someone, to version 7 -->\n'
                    '# Repository map\n\nOur one deliverable is [THE_THING.md](THE_THING.md).\n\n'
                    '## Known consumers\n\n| Repo | Since |\n|---|---|\n| a/b | 2026-09-01 |\n')
        hand_glossary = '# Canonical names\n\n## Our names\n\n| Name | Meaning |\n|---|---|\n| HVR | Human voice rules |\n'
        (repo / 'MAP.md').write_text(hand_map, encoding='utf-8')
        (repo / 'GLOSSARY.md').write_text(hand_glossary, encoding='utf-8')
        (repo / 'todo').mkdir()
        (repo / 'todo' / 'TODO.md').write_text(
            '---\ngenerated_by: tools/build_todo_index.py\nedit_instead: "todo/todo-*.md"\n'
            'note: "Generated."\n---\n# TODO\n', encoding='utf-8')
        (repo / 'process' / 'upstream').mkdir(parents=True)
        (repo / 'process' / 'upstream' / 'GLOSSARY.md').write_text(
            '---\ngenerated_by: tools/build_views.py\nedit_instead: "x"\n---\n# Upstream\n',
            encoding='utf-8')
        agents_before = (repo / 'AGENTS.md').read_text(encoding='utf-8')
        git('init', '-q', '-b', 'main')
        git('add', '-A')
        git('commit', '-q', '-m', 'hand-written views')
        first = git('rev-parse', 'HEAD').stdout.strip()

        rc, out = migrate('--check')
        cases.append(('--check says what it would do and changes nothing',
                      rc == 0 and 'would move MAP.md into MAP.source.md' in out
                      and not (repo / 'MAP.source.md').exists()
                      and (repo / 'MAP.md').read_text(encoding='utf-8') == hand_map))
        rc, out = migrate()
        m = (repo / 'MAP.md').read_text(encoding='utf-8')
        g = (repo / 'GLOSSARY.md').read_text(encoding='utf-8')
        cases.append(('each hand-written view moves into its source byte for byte',
                      rc == 0 and (repo / 'MAP.source.md').read_text(encoding='utf-8') == hand_map
                      and (repo / 'GLOSSARY.source.md').read_text(encoding='utf-8') == hand_glossary))
        cases.append(('...and the generated map carries every word of it, then the '
                      'catalogue, labelled as generated from the source',
                      m.startswith('---\ngenerated_by: tools/build_views.py')
                      and 'MAP.source.md' in m.split('---', 2)[1]
                      and hand_map.rstrip('\n') in m
                      and m.index(hand_map.rstrip('\n')) < m.index('## The practice catalogue')
                      and '[zz-fixture](practices/zz-fixture.md)' in m))
        cases.append(('...and the generated glossary carries its own names, then '
                      'the names the practices define',
                      hand_glossary.rstrip('\n') in g and '| Fixture Term |' in g))
        reg = _json.loads((repo / 'tools' / 'generated_files.json').read_text(encoding='utf-8'))
        cases.append(('...and both are in the repository\'s own list, with their '
                      'sources as inputs, beside every other file that says it is '
                      'generated, read from its own label -- never a vendored copy of '
                      'another repository\'s',
                      {e['path']: e['edit_instead'] for e in reg['files']}
                      == {'MAP.md': 'MAP.source.md', 'GLOSSARY.md': 'GLOSSARY.source.md',
                          'todo/TODO.md': 'todo/todo-*.md'}))
        cases.append(('...and AGENTS.md is never touched: its loader block is the '
                      'view sync\'s to write',
                      (repo / 'AGENTS.md').read_text(encoding='utf-8') == agents_before))
        before = m
        rc, out = migrate()
        cases.append(('a second run finds nothing to do and changes nothing',
                      rc == 0 and 'nothing to migrate' in out
                      and (repo / 'MAP.md').read_text(encoding='utf-8') == before))
        (repo / 'MAP.source.md').write_text(hand_map + '\nA new line.\n', encoding='utf-8')
        subprocess.run([sys.executable, str(ROOT / 'tools' / 'build_views.py'),
                        '--repo', str(repo)], capture_output=True, text=True, env=env)
        cases.append(('afterwards the map follows its source',
                      'A new line.' in (repo / 'MAP.md').read_text(encoding='utf-8')))

        # A view a vendor update already overwrote: brought back from the
        # commit the person names.
        git('add', '-A')
        git('commit', '-q', '-m', 'migrated')
        (repo / 'MAP.source.md').unlink()
        git('commit', '-q', '-am', 'lose the source, as an overwrite did')
        rc, out = migrate('--restore-map-from', first)
        cases.append(('--restore-map-from brings back the hand-written map from '
                      'the named commit', rc == 0
                      and (repo / 'MAP.source.md').read_text(encoding='utf-8') == hand_map))
        rc, out = migrate('--restore-map-from', 'HEAD')
        cases.append(('...never restores over a source that already exists',
                      rc != 0 and 'already exists' in out
                      and (repo / 'MAP.source.md').read_text(encoding='utf-8') == hand_map))
        (repo / 'MAP.source.md').unlink()
        rc, out = migrate('--restore-map-from', 'HEAD')
        cases.append(('...and refuses a commit where the map was already generated',
                      rc != 0 and 'already generated' in out
                      and not (repo / 'MAP.source.md').exists()))

        # A migration that cannot keep the text leaves nothing changed.
        (repo / 'MAP.source.md').unlink(missing_ok=True)
        (repo / 'GLOSSARY.source.md').unlink(missing_ok=True)
        (repo / 'MAP.md').write_text(hand_map, encoding='utf-8')
        (repo / 'GLOSSARY.md').write_text(hand_glossary, encoding='utf-8')
        (repo / 'AGENTS.md').write_text('# Agents, with no loader markers\n', encoding='utf-8')
        rc, out = migrate()
        cases.append(('a migration that cannot regenerate puts everything back and '
                      'says so', rc == 1 and 'REFUSED' in out
                      and not (repo / 'MAP.source.md').exists()
                      and not (repo / 'GLOSSARY.source.md').exists()
                      and (repo / 'MAP.md').read_text(encoding='utf-8') == hand_map
                      and (repo / 'GLOSSARY.md').read_text(encoding='utf-8') == hand_glossary))

        # Views a vendor update already overwrote, with no source file and no
        # list: nothing to migrate, but the list is still written, or a commit
        # that adds a source never rebuilds the view. Found 2026-10-03 in a
        # real consumer whose map and glossary were overwritten on 2026-09-15.
        (repo / 'AGENTS.md').write_text(agents_before, encoding='utf-8')
        (repo / 'MAP.md').write_text(
            '---\ngenerated_by: tools/build_views.py\nedit_instead: "practices/*.md"\n'
            '---\n# Repository map\n', encoding='utf-8')
        (repo / 'GLOSSARY.md').write_text(
            '---\ngenerated_by: tools/build_views.py\nedit_instead: "practices/*.md"\n'
            '---\n# Canonical names\n', encoding='utf-8')
        (repo / 'tools' / 'generated_files.json').unlink(missing_ok=True)
        rc, out = migrate()
        lst = repo / 'tools' / 'generated_files.json'
        listed = ({e['path']: e.get('edit_instead') for e in
                   _json.loads(lst.read_text(encoding='utf-8'))['files']}
                  if lst.is_file() else {})
        cases.append(('views already generated, with no source and no list: each '
                      'gets an empty source, as a fresh install would, and the list '
                      'names both',
                      rc == 0 and 'nothing to migrate' in out
                      and listed.get('MAP.md') == 'MAP.source.md'
                      and listed.get('GLOSSARY.md') == 'GLOSSARY.source.md'
                      and (repo / 'MAP.source.md').is_file()
                      and (repo / 'MAP.source.md').read_text(encoding='utf-8') == ''
                      and (repo / 'GLOSSARY.source.md').is_file()
                      and (repo / 'GLOSSARY.source.md').read_text(encoding='utf-8') == ''))
        cases.append(('...and each view now names its source, with AGENTS.md untouched',
                      'MAP.source.md' in (repo / 'MAP.md').read_text(encoding='utf-8')
                      .split('---', 2)[1]
                      and 'GLOSSARY.source.md' in (repo / 'GLOSSARY.md')
                      .read_text(encoding='utf-8').split('---', 2)[1]
                      and (repo / 'AGENTS.md').read_text(encoding='utf-8') == agents_before))

        # A hand-written map and no glossary at all: the migration makes no
        # glossary, and the list names nothing that is not there. Found
        # 2026-10-03 in a consumer whose glossary lives in docs/: it came out
        # with a new root GLOSSARY.md and a list pointing at a missing
        # GLOSSARY.source.md, which generated-files-registered refused.
        for f in ('MAP.source.md', 'GLOSSARY.source.md', 'GLOSSARY.md'):
            (repo / f).unlink(missing_ok=True)
        (repo / 'tools' / 'generated_files.json').unlink(missing_ok=True)
        (repo / 'MAP.md').write_text(hand_map, encoding='utf-8')
        rc, out = migrate()
        listed = ({e['path']: e.get('edit_instead') for e in
                   _json.loads(lst.read_text(encoding='utf-8'))['files']}
                  if lst.is_file() else {})
        cases.append(('a repository with no glossary gets none, and its list names '
                      'only the map and its real source',
                      rc == 0 and not (repo / 'GLOSSARY.md').exists()
                      and not (repo / 'GLOSSARY.source.md').exists()
                      and listed.get('MAP.md') == 'MAP.source.md'
                      and 'GLOSSARY.md' not in listed))
        # ...and no later rebuild makes one either: the commit backstop runs
        # build_views --views-only whenever MAP.source.md changes, and it
        # wrote a root GLOSSARY.md each time, untracked, in that consumer.
        subprocess.run([sys.executable, str(ROOT / 'tools' / 'build_views.py'),
                        '--repo', str(repo), '--views-only'],
                       capture_output=True, text=True, env=env)
        cases.append(('...and a later views-only rebuild does not create one either',
                      not (repo / 'GLOSSARY.md').exists()
                      and (repo / 'MAP.md').is_file()))
    failed = [n for n, ok in cases if not ok]
    check(f'{name} ({len(cases)} stated cases)', not failed, '; '.join(failed))


def check_stale_view_names_its_real_cause():
    """The view sync's check names why a generated MAP.md or GLOSSARY.md is
    stale, and only the view that is. build_views.py prints the drift on
    stdout and, for a person who brings a set, a notice on stderr after it;
    the sync quoted the last line of both together, so a hand edit to MAP.md
    was reported as the brought-set notice, against both views. Found
    2026-10-03 rehearsing a consumer's push check after Update Vendors."""
    import tempfile
    name = 'a stale generated view is reported with its own cause, and only that view'
    sys.path.insert(0, str(ROOT / 'tools'))
    try:
        import precedent_sync_views as sv
    finally:
        sys.path.pop(0)
    if not hasattr(sv, '_refresh_generated_views'):
        not_applicable(name, 'precedent_sync_views has no _refresh_generated_views')
        return
    header = '---\ngenerated_by: tools/build_views.py\nedit_instead: "x"\n---\n# View\n'
    real_run = sv.subprocess.run
    with tempfile.TemporaryDirectory() as td:
        repo = pathlib.Path(td)
        (repo / 'MAP.md').write_text(header, encoding='utf-8')
        (repo / 'GLOSSARY.md').write_text(header, encoding='utf-8')
        sv.subprocess.run = lambda *a, **k: subprocess.CompletedProcess(
            a[0] if a else [], 1,
            stdout='build_views --check FAIL: hand-edited or stale, drifted from '
                   'regeneration: MAP.md\n',
            stderr='build_views: precedent-shared-ladder deferred to '
                   '.precedent/SESSION_PRACTICES.md -- brought by the person working '
                   'here, not declared by this repository.\n')
        try:
            got = ' '.join(sv._refresh_generated_views(repo, check=True))
        finally:
            sv.subprocess.run = real_run
    check(name, 'hand-edited or stale' in got and 'MAP.md' in got
          and 'deferred' not in got and 'GLOSSARY.md' not in got, got)


def check_tracked_views_read_the_same_whoever_regenerates():
    """The standing instruction in a tracked AGENTS.md points at
    .precedent/SESSION_PRACTICES.md only when a source THIS REPOSITORY
    declares is deferred there, never because the person regenerating it
    brings a set of their own. Found 2026-10-03 on a real consumer's copy:
    counting a brought set wrote the pointer for whoever brings one, so
    build_views.py and the view sync disagreed and the repository's full
    check failed for every such person after an engine update."""
    name = 'a tracked view reads the same whoever regenerates it'
    sys.path.insert(0, str(ROOT / 'tools'))
    try:
        import build_views as bv
    finally:
        sys.path.pop(0)
    import tempfile
    cases = []
    real = bv.sources_for_tracked_block
    with tempfile.TemporaryDirectory() as td:
        root = pathlib.Path(td)
        (root / 'precedent.json').write_text('{"sources": []}', encoding='utf-8')
        try:
            bv.sources_for_tracked_block = lambda r, d: (
                [], [{'name': 'precedent-shared-ladder', 'brought': True}], [])
            only_brought = bv.defers_any_source(root)
            bv.sources_for_tracked_block = lambda r, d: (
                [], [{'name': 'precedent-shared-ladder', 'brought': True},
                     {'name': 'precedent-shared-writing'}], [])
            declared_too = bv.defers_any_source(root)
        finally:
            bv.sources_for_tracked_block = real
    cases.append(('a set only the person brings does not put the pointer in a '
                  'tracked file', only_brought is False))
    cases.append(('...while a source the repository declares and defers still does',
                  declared_too is True))
    failed = [n for n, ok in cases if not ok]
    check(f'{name} ({len(cases)} stated cases)', not failed, '; '.join(failed))


def check_stale_views_say_why_and_stop_at_the_push():
    """A repository's generated views going stale because a practice source
    changed is said with its cause and its command, and stops the push to
    pre-staging, not only the Debut (2026-10-03: a reduction pass retired
    practices in the shared sets, a consumer was never re-synced, and the
    full check's message sent its session after missing sources). The
    failures that matter: a stale view that passes the basic tier, a message
    that does not name the cause, and a check that fails a push only because
    a source is not cloned here."""
    import tempfile, json as _json
    name = 'stale generated views say why, and stop at the push'
    tool = ROOT / 'tools' / 'precedent_sync_views.py'
    cases = []
    with tempfile.TemporaryDirectory() as td:
        tmp = pathlib.Path(td)
        universal, consumer = tmp / 'u', tmp / 'consumer'
        (universal / 'practices').mkdir(parents=True)
        def practice(slug, rule):
            (universal / 'practices' / f'{slug}.md').write_text(
                f'---\nslug: {slug}\ntitle: Fixture\ntier: resident\nseverity: default\n'
                f'applies_to: ["**"]\noccasion: "x"\ngates: []\nindex_clause: "x"\n'
                f'checked_by: null\ndefines: []\nstatus: active\nsupersedes: []\n'
                f'overrides: null\nadded: null\napproved_by: "x"\nsource_practice_number: null\n'
                f'---\n## Rule\n{rule}\n\n## Why\nx\n\n## Story\nx\n\n## Install\nx\n',
                encoding='utf-8')
        practice('uni-fixture', 'A universal fixture rule.')
        consumer.mkdir()
        (consumer / 'precedent.json').write_text(_json.dumps({
            'visibility': 'private',
            'sources': [{'level': 'universal', 'name': 'precedent', 'path': str(universal)}]}),
            encoding='utf-8')
        (consumer / 'AGENTS.md').write_text('# fixture\n\n<!-- BEGIN GENERATED: precedent-loader -->\n'
                                            '<!-- END GENERATED -->\n', encoding='utf-8')
        user_cfg = tmp / 'none.json'

        def run(*extra):
            r = subprocess.run([sys.executable, str(tool), '--repo', str(consumer),
                                '--user-config', str(user_cfg), *extra],
                               capture_output=True, text=True)
            return r.returncode, r.stdout + r.stderr
        run()
        rc, out = run('--check')
        cases.append(('right after a sync, the check passes', rc == 0))
        practice('uni-fixture', 'The same rule, reworded upstream.')
        rc, out = run('--check')
        cases.append(('a source that changed since the sync fails the check, naming '
                      'the cause and the command',
                      rc != 0 and 'practice source this repository declares changed' in out
                      and 'Fix: python3 tools/precedent_sync_views.py --repo .' in out))
        import shutil as _shutil
        _shutil.rmtree(universal)
        rc, out = run('--check', '--skip-unresolved')
        cases.append(('...while a source that is not here at all is said and skipped '
                      'when asked, never read as stale views',
                      rc == 0 and 'SKIPPED' in out and 'could not be resolved' in out))
        rc, out = run('--check')
        cases.append(('...and without --skip-unresolved it still fails, saying first '
                      'that a source is missing, so the differences are not read as '
                      'stale views', rc != 0 and 'did not resolve here' in out))
    sys.path.insert(0, str(ROOT / 'tools'))
    try:
        import precedent_push_check as _ppc
    finally:
        sys.path.pop(0)
    step = [s for s in _ppc.PUSH_CHECKS['consumer'] if s[0] == 'views_sync']
    cases.append(('a repository that uses Precedent runs the check at the basic '
                  'tier, skipping sources it cannot reach',
                  'views_sync' in _ppc.BASIC_CHECKS and step
                  and '--skip-unresolved' in step[0][1]))
    failed = [n for n, ok in cases if not ok]
    check(f'{name} ({len(cases)} stated cases)', not failed, '; '.join(failed))


def check_stale_freshness_also_says_delete_it():
    """PRECEDENT_FRESHNESS_ALSO, not needed since 2026-09-30, is told to be
    deleted rather than given a new value when every entry names a practice
    set or a retired precedent-team-* path, and Update Vendors' rename step
    says so too (reported 2026-10-03: the session check warned at every turn
    about the old team paths and offered a corrected value). An entry naming
    a repository nothing declares still keeps the variable worth having."""
    import tempfile
    name = 'a stale PRECEDENT_FRESHNESS_ALSO is told to be deleted'
    sys.path.insert(0, str(ROOT / 'tools'))
    try:
        import precedent_session_check as psc
        import precedent_update as pu
    finally:
        sys.path.pop(0)
    cases = []
    saved = os.environ.get('PRECEDENT_FRESHNESS_ALSO')

    def row(value):
        os.environ['PRECEDENT_FRESHNESS_ALSO'] = value
        return [r for r in psc.checks() if r[0].startswith('PRECEDENT_FRESHNESS_ALSO')][0]
    try:
        with tempfile.TemporaryDirectory() as td:
            tmp = pathlib.Path(td)
            pset = tmp / 'precedent-shared-fixture'
            pset.mkdir()
            (pset / 'precedent-source.json').write_text('{}', encoding='utf-8')
            other = tmp / 'some-project'
            (other / '.git').mkdir(parents=True)
            r = row(f'{tmp}/precedent-team-fixture=main;{pset}=main')
            cases.append(('old team paths plus a practice set: warned, and told to '
                          'delete the variable, never given a new value',
                          r[1] is False and 'Delete PRECEDENT_FRESHNESS_ALSO' in r[2]
                          and 'do not replace it' in r[2] and 'Set it to' not in r[2]))
            r = row(f'{pset}=main')
            cases.append(('only practice sets: not a warning, but said to be unneeded',
                          r[1] is True and 'not needed' in r[2]))
            r = row(f'{other}=main')
            cases.append(('a repository nothing declares keeps the variable worth '
                          'having', r[1] is True and 'Delete' not in r[2]))
            os.environ['PRECEDENT_FRESHNESS_ALSO'] = f'{tmp}/precedent-team-fixture=main'
            rep = pu.Report()
            pu.renamed_sources_step(tmp, rep, '')
            cases.append(('Update Vendors\' rename step notes the stale variable, to '
                          'delete, without holding up the update',
                          any(n == 'environment' and 'delete it' in o for n, o in rep.steps)
                          and not rep.left))
    finally:
        if saved is None:
            os.environ.pop('PRECEDENT_FRESHNESS_ALSO', None)
        else:
            os.environ['PRECEDENT_FRESHNESS_ALSO'] = saved
    failed = [n for n, ok in cases if not ok]
    check(f'{name} ({len(cases)} stated cases)', not failed, '; '.join(failed))


def check_generated_views_regenerate():
    # "hand-editing a generated view fails a check" (Sequence row 2, done-when).
    # Runs build_views.py --check as a real subprocess, not an in-process
    # import-and-call: bv.build_loader_block() can sys.exit() (over the
    # resident token budget, or missing BEGIN/END markers), which is a clean
    # process exit but would be an uncaught SystemExit escaping straight
    # through this function if called in-process, taking the whole harness
    # down with a raw traceback instead of a reported FAIL line.
    result = subprocess.run([sys.executable, str(ROOT / 'tools' / 'build_views.py'), '--check'],
                             capture_output=True, text=True)
    ok = result.returncode == 0
    detail = (result.stdout + result.stderr).strip() if not ok else ''
    check('generated views regenerate byte-identically (AGENTS.md loader block, MAP.md, GLOSSARY.md)',
          ok, detail)


def check_resident_rule_links_are_placed_for_the_block():
    """A resident practice's Rule links are repointed for the file the block
    lands in, and an unplaceable one is said out loud instead of mangled.

    THE INCIDENT (2026-09-11). A `tier: resident` practice's ## Rule is
    copied verbatim into the loader block, which lands in AGENTS.md at the
    repository ROOT -- while the Rule was written in practices/, one
    directory down. An individual set's new practice carried the only link
    in the whole resident block, `[audience-register](audience-register.md)`,
    and it reached a consuming repo as a hard doc_lint BROKEN RELATIVE LINK
    inside a generated region no session there is allowed to edit. It was
    patched at the source by dropping the markup, which holds by convention
    only.

    Four behaviours, and the last two are the ones that keep the fix from
    being worse than the bug: a link that cannot be placed is LEFT as its
    author wrote it, never turned into an absolute URL that would name a
    private repository, and never into a machine-specific path out of the
    tree (practice: control-asserts-which-failure -- each case asserts the
    text produced, not merely that something happened)."""
    import shutil, tempfile
    sys.path.insert(0, str(ROOT / 'tools'))
    import build_views as bv

    tmp = pathlib.Path(tempfile.mkdtemp(prefix='precedent-rulelinks-'))
    cases = []
    try:
        repo = tmp / 'repo'
        (repo / 'practices').mkdir(parents=True)
        (repo / 'tools' / 'checks').mkdir(parents=True)
        (repo / 'tools' / 'checks' / 'check_x.py').write_text('x\n', encoding='utf-8')
        (repo / 'practices' / 'sibling.md').write_text('y\n', encoding='utf-8')
        rule = ("See [a](sibling.md), [b](../tools/checks/check_x.py), "
                "[c](https://example.com/x), [d](#rule) and [e](gone.md).")
        placed, unplaced = bv._place_rule_links(
            rule, repo / 'practices' / 'p.md', repo)
        cases.append(('a sibling practice citation is repointed at '
                      'practices/ for a block rendered at the repo root',
                      '[a](practices/sibling.md)' in placed))
        cases.append(("a practice's own check script is repointed at "
                      'tools/checks/, and an absolute URL and a bare '
                      'fragment are untouched',
                      '[b](tools/checks/check_x.py)' in placed
                      and '[c](https://example.com/x)' in placed
                      and '[d](#rule)' in placed))
        cases.append(('a link to a file that is not there is left exactly as '
                      'written, and reported as unplaceable',
                      '[e](gone.md)' in placed and unplaced == ['gone.md']))

        # A Rule that SHOWS a reader what a link looks like is exactly the
        # practice that would carry one, and rewriting it would edit the
        # prose this file only relays. doc_lint skips both regions for the
        # same reason.
        literal = ("Prose [a](sibling.md), a span `[b](sibling.md)`, and\n"
                   "```\n[c](sibling.md)\n```\nthen [d](sibling.md).")
        placed_lit, _ = bv._place_rule_links(
            literal, repo / 'practices' / 'p.md', repo)
        cases.append(('a link inside a code span or a fenced block is left '
                      'alone, while the prose links around it are placed',
                      placed_lit.count('(practices/sibling.md)') == 2
                      and '`[b](sibling.md)`' in placed_lit
                      and '\n[c](sibling.md)\n' in placed_lit))

        # Rendered one directory DOWN (.precedent/SESSION_PRACTICES.md), a
        # link out of practices/ legitimately climbs -- so "starts with .."
        # is not the test, and this is the case that proves it is not.
        placed_down, _ = bv._place_rule_links(
            rule, repo / 'practices' / 'p.md', repo / '.precedent', repo)
        cases.append(('a block rendered below the repo root gets ../ links, '
                      'not a refusal',
                      '[a](../practices/sibling.md)' in placed_down
                      and '[b](../tools/checks/check_x.py)' in placed_down))

        # THE PRIVACY CASE. A team or individual practice resolves from a
        # clone outside the consuming repo, where no relative link reaches.
        outside = tmp / 'precedent-individual'
        (outside / 'practices').mkdir(parents=True)
        (outside / 'practices' / 'sibling.md').write_text('y\n', encoding='utf-8')
        placed_out, unplaced_out = bv._place_rule_links(
            "See [a](sibling.md).", outside / 'practices' / 'p.md',
            repo / '.precedent', repo)
        cases.append(('a practice resolved from a source clone OUTSIDE the '
                      'repo is left as written -- no absolute URL naming the '
                      'source, no path out of the tree',
                      placed_out == "See [a](sibling.md)."
                      and unplaced_out == ['sibling.md']
                      and str(outside) not in placed_out))
    finally:
        shutil.rmtree(tmp, ignore_errors=True)

    ok = all(passed for _, passed in cases)
    for name, passed in cases:
        if not passed:
            print(f"  build_views did NOT place a resident Rule's links as "
                  f"stated: {name}")
    check(f"a resident Rule's relative links are placed for the block's own "
          f"directory ({len(cases)} stated cases, including the two "
          f"unplaceable shapes)", ok)


def check_source_names_detects_a_rename():
    """precedent_source_names.py -- a declared source repository that has been
    RENAMED is reported, and a name it could not check is never reported as
    current.

    THE INCIDENT (2026-09-11). A shared source was renamed on GitHub. A
    consuming repo went on declaring, cloning, attaching and materializing
    under the old name with every check green, for an unknown number of
    sessions, because GitHub redirects a renamed repository indefinitely:
    clone succeeds, ls-remote succeeds, the sibling clone resolves, the
    practices materialize correctly. It surfaced because a person recognised
    a name he had retired.

    THE REDIRECT PATH, ADDED 2026-09-14. The incident above was reported by
    a person, not by the tool: run against the real renamed repository the
    tool answered UNVERIFIED, because GitHub's 301 points at the numeric-ID
    form (`/repositories/1352494938`) and the session proxy refuses it, so
    the tool caught the error and said it could not check. A redirect is
    conclusive on its own -- a repository still called that does not
    redirect -- so it is now RENAMED whether or not the new name can be
    read, and `--check` fails on it.

    THE API CALL IS STUBBED HERE AND MEASURED ELSEWHERE. A harness case may
    not depend on the network, and no renamed repository is reachable from a
    hosted session anyway -- api.github.com answers 403 for every repo the
    session has not attached. What the stub cannot prove was measured live
    on 2026-09-11 against `alex137/bestpractice`: the API's response BODY
    carries the canonical `full_name` (`alex137/BestPractice`) whatever
    spelling was asked for, which is why this reads the body and never the
    status code or the final URL. The tool reported SPELLING on that run.

    The UNVERIFIED case is the one that matters most (practice:
    fail-gracefully): "could not check" and "checked, the name is current"
    must never render the same, so each case asserts the printed verdict,
    not merely that something was printed (practice:
    control-asserts-which-failure)."""
    import io, shutil, tempfile, urllib.error, urllib.request
    sys.path.insert(0, str(ROOT / 'tools'))
    import precedent_source_names as psn

    tmp = pathlib.Path(tempfile.mkdtemp(prefix='precedent-names-'))
    cases = []
    real_api = psn.api_full_name
    try:
        consumer = tmp / 'consumer'
        consumer.mkdir()
        clone = tmp / 'precedent-team-fixture'
        clone.mkdir()
        subprocess.run(['git', 'init', '-q', str(clone)], capture_output=True)
        subprocess.run(['git', '-C', str(clone), 'remote', 'add', 'origin',
                        'https://github.com/example/precedent-team-fixture'],
                       capture_output=True)
        (consumer / 'precedent.json').write_text(json.dumps({
            'visibility': 'private',
            'sources': [{'level': 'team', 'name': 'precedent-team-fixture',
                         'path': '../precedent-team-fixture'}]}),
            encoding='utf-8')

        # The fixture OWNS its user config. Without this it inherits the
        # machine's real individual source and grades that too, which is
        # how the first run of this case reported two rows where it
        # asserted one (practice: fixture-owns-its-state).
        user_cfg = tmp / 'user.json'
        user_cfg.write_text(json.dumps({}), encoding='utf-8')

        def run_with(stub):
            psn.api_full_name = stub
            rows = psn.assess(str(consumer), user_config=str(user_cfg))
            buf = io.StringIO()
            psn.report(rows, out=buf)
            return rows, buf.getvalue()

        rows, out = run_with(lambda o, n, env=None:
                             ('example/precedent-team-repo-maintenance', None, False))
        cases.append(('a renamed source is reported as RENAMED, naming both '
                      'the name this repo fetches and the one GitHub uses now',
                      [r['verdict'] for r in rows] == ['RENAMED']
                      and 'example/precedent-team-fixture' in out
                      and 'example/precedent-team-repo-maintenance' in out,
                      out))

        rows, out = run_with(lambda o, n, env=None:
                             ('example/precedent-team-fixture', None, False))
        cases.append(('an unrenamed source is OK, and the summary counts zero '
                      'renamed and zero unchecked',
                      [r['verdict'] for r in rows] == ['OK']
                      and '0 renamed, 0 NOT checked' in out, out))

        rows, out = run_with(lambda o, n, env=None:
                             (None, 'GitHub answered HTTP 403: not enabled', False))
        cases.append(('a source whose name could NOT be checked is UNVERIFIED '
                      'with the reason, never OK, and the summary says an '
                      'unchecked source is not a passing one',
                      [r['verdict'] for r in rows] == ['UNVERIFIED']
                      and 'HTTP 403' in out
                      and '1 NOT checked' in out
                      and 'an unchecked source is not a passing one' in out,
                      out))

        # A NAME THE SESSION READ FROM list_repos (2026-10-01, from a
        # consumer's Update Vendors): the auto-mode classifier refused the
        # push attach that lets the API answer, and list_repos had already
        # given each repository's current full_name. Supplied with
        # --canonical, it settles the name where the API could not.
        psn.api_full_name = (lambda o, n, env=None:
                             (None, 'GitHub answered HTTP 403: not enabled', False))

        def verdicts(canonical):
            return [r['verdict'] for r in psn.assess(
                str(consumer), user_config=str(user_cfg), canonical=canonical)]
        cases.append(('an unreachable API with the name listed exactly by '
                      '--canonical is OK',
                      verdicts(['example/precedent-team-fixture']) == ['OK'], ''))
        cases.append(('...listed in another case, SPELLING',
                      verdicts(['Example/Precedent-Team-Fixture']) == ['SPELLING'], ''))
        cases.append(('...not listed at all, still UNVERIFIED -- the list cannot '
                      'tell a rename from a repository out of reach',
                      verdicts(['example/precedent-team-other']) == ['UNVERIFIED'], ''))
        psn.api_full_name = (lambda o, n, env=None:
                             ('example/precedent-team-repo-maintenance', None, False))
        cases.append(('where the API answers, its answer wins over --canonical',
                      verdicts(['example/precedent-team-fixture']) == ['RENAMED'], ''))
        r = subprocess.run([sys.executable, str(ROOT / 'tools' / 'precedent_source_names.py'),
                            '--repo', str(consumer), '--user-config', str(user_cfg),
                            '--canonical', 'example/precedent-team-fixture'],
                           capture_output=True, text=True, timeout=120,
                           env=dict(os.environ, https_proxy='http://127.0.0.1:9',
                                    HTTPS_PROXY='http://127.0.0.1:9',
                                    GITHUB_TOKEN='', GH_TOKEN=''))
        cases.append(('the command line takes --canonical OWNER/NAME',
                      r.returncode == 0 and 'OK' in r.stdout
                      and 'precedent-team-fixture' in r.stdout,
                      (r.stdout + r.stderr)[-300:]))

        # THE REDIRECT, which is the case this tool exists for and the one
        # it got wrong until 2026-09-14. GitHub answers 301 for a renamed
        # repository, `urlopen` followed it by default, the Location is the
        # numeric-ID form, and a session proxy refuses that form -- so the
        # tool caught an HTTPError and said "could not check" about the one
        # input that is conclusive on its own. Both halves are stated: the
        # verdict must be RENAMED even when the new name cannot be read, and
        # the detail must not pretend to know a name it never got.
        class _FakeOpener:
            def __init__(self, second=None):
                self.calls = 0
                self.second = second

            def open(self, req, timeout=None):
                self.calls += 1
                if self.calls == 1 or self.second is None:
                    raise urllib.error.HTTPError(
                        'https://api.github.com/repos/example/old-name', 301,
                        'Moved Permanently',
                        {'Location': 'https://api.github.com/repositories/1352494938'},
                        io.BytesIO(b'{}'))
                return io.BytesIO(json.dumps(self.second).encode('utf-8'))

        # The two cases below exercise the REAL api_full_name, so the stub
        # the run_with cases above installed has to come off first -- leaving
        # it on measures the stub (practice: fixture-owns-its-state).
        psn.api_full_name = real_api
        real_build = urllib.request.build_opener
        try:
            fake = _FakeOpener()
            urllib.request.build_opener = lambda *a, **k: fake
            full, why, renamed = psn.api_full_name('example', 'old-name')
            cases.append(('a 301 whose Location cannot be read is still a '
                          'rename: renamed is True, no name is invented, and '
                          'the detail says how to read the current one',
                          (full, renamed) == (None, True)
                          and 'is NOT what this repository is called' in (why or '')
                          and '1352494938' in (why or '')
                          and 'github.com/example/old-name' in (why or ''),
                          why or ''))

            fake2 = _FakeOpener(second={'full_name': 'example/new-name'})
            urllib.request.build_opener = lambda *a, **k: fake2
            full, why, renamed = psn.api_full_name('example', 'old-name')
            cases.append(('a 301 whose Location CAN be read reports the new '
                          'name, and still as a rename',
                          (full, why, renamed) == ('example/new-name', None, True),
                          str((full, why, renamed))))
        finally:
            urllib.request.build_opener = real_build

        # And the verdict the redirect produces has to survive into the
        # report: a row with no `current` name used to render UNVERIFIED
        # unconditionally, which is exactly the bug.
        rows, out = run_with(lambda o, n, env=None:
                             (None, 'that name is a redirect', True))
        cases.append(('a source whose rename was proven by a redirect is '
                      'RENAMED in the report and counts against --check, not '
                      'UNVERIFIED',
                      [r['verdict'] for r in rows] == ['RENAMED']
                      and '1 renamed' in out, out))

        # A case difference is not a rename: git does not care, and reporting
        # it as one would cry wolf on every clone URL a tool lowercased.
        rows, out = run_with(lambda o, n, env=None:
                             ('example/Precedent-Team-Fixture', None, False))
        cases.append(('a name differing only in case is SPELLING, not RENAMED',
                      [r['verdict'] for r in rows] == ['SPELLING'], out))

        # THE OFFLINE HALF, which costs no network and nothing else prints.
        subprocess.run(['git', '-C', str(clone), 'remote', 'set-url', 'origin',
                        'https://github.com/example/something-else'],
                       capture_output=True)
        rows, out = run_with(lambda o, n, env=None:
                             ('example/something-else', None, False))
        cases.append(('the declared name disagreeing with the clone\'s own '
                      'remote is reported as DRIFT even when the API says the '
                      'repository is current',
                      'DRIFT' in out and rows[0]['verdict'] == 'OK', out))

        # A remote this tool has no API for is UNVERIFIED, not OK -- guessing
        # an API for an unknown host answers from the wrong server.
        subprocess.run(['git', '-C', str(clone), 'remote', 'set-url', 'origin',
                        'https://git.example.com/example/precedent-team-fixture'],
                       capture_output=True)
        rows, out = run_with(lambda o, n, env=None:
                             (None, 'should not be called', False))
        cases.append(('a source on a non-github host is UNVERIFIED, not OK',
                      [r['verdict'] for r in rows] == ['UNVERIFIED']
                      and 'github.com' in out, out))

        # THE SECRET. A tokenised remote URL is parsed rather than skipped,
        # and the token is not what comes back out.
        # Assembled rather than written out: the leak gate reads
        # `<anything>@github.com` as an email address, correctly, and a
        # fixture is not worth a false hit on every run.
        tokenised = ('https://x-access-token:ghp_NOTAREALTOKEN' + '@'
                     + 'github.com/example/a-repo.git')
        owner, name = psn.parse_remote(tokenised)
        cases.append(('a remote carrying a credential is parsed, and the '
                      'credential is not in what comes back',
                      (owner, name) == ('example', 'a-repo')))
    finally:
        psn.api_full_name = real_api
        shutil.rmtree(tmp, ignore_errors=True)

    bad = [(c[0], c[2] if len(c) > 2 else '') for c in cases if not c[1]]
    check(f'precedent_source_names.py reports a renamed source and never '
          f'reports an unchecked one as current ({len(cases)} stated cases: '
          f'renamed, unrenamed, unverified, a 301 whose new name cannot be '
          f'read, a 301 whose new name can, that redirect surviving into the '
          f'report, case-only, declared-vs-remote drift, a non-github host, '
          f'and a tokenised remote URL)',
          not bad, '; '.join(f"{n}: {d}" for n, d in bad))


def check_owned_paths_previews_the_boundary():
    """precedent_owned_paths.py names every touched owned path with its
    owner, says the rest is the contributor's, and never reads a missing
    CODEOWNERS as a clean change.

    The tool is spec/CONTRIBUTOR_ACCESS.md's finding 6 (2026-09-14): the
    contributor cannot see the CODEOWNERS line, so the session says before
    the pull request what will wait for review. Each case asserts the words
    the tool prints for THAT case, not that something was printed (practice:
    control-asserts-which-failure); the no-CODEOWNERS case is the one that
    matters most, since a boundary that is missing must not render as a
    change that is clean (practice: fail-gracefully)."""
    import contextlib, io, shutil, tempfile
    sys.path.insert(0, str(ROOT / 'tools'))
    import precedent_owned_paths as pop

    tmp = pathlib.Path(tempfile.mkdtemp(prefix='precedent-owned-'))
    cases = []

    def git(*args):
        return subprocess.run(['git', '-C', str(tmp), '-c', 'user.name=fixture',
                               '-c', 'user.email=fixture@example.com', *args],
                              capture_output=True, text=True)

    try:
        git('init', '-q')
        git('checkout', '-q', '-b', 'main')
        (tmp / '.github').mkdir()
        (tmp / 'docs').mkdir()
        (tmp / '.github' / 'CODEOWNERS').write_text(
            '/.github/ @maint\n/settings.md @maint\n*.secret @maint @other\n'
            '/docs/generated/ @maint\n/docs/generated/free.md\n', encoding='utf-8')
        (tmp / 'docs' / 'hello.md').write_text('hi\n', encoding='utf-8')
        (tmp / 'settings.md').write_text('s\n', encoding='utf-8')
        (tmp / 'precedent.json').write_text('{"base_branch": "main"}', encoding='utf-8')
        git('add', '-A')
        git('commit', '-q', '-m', 'init')
        git('checkout', '-q', '-b', 'work')
        (tmp / 'docs' / 'hello.md').write_text('hi\nmore\n', encoding='utf-8')
        (tmp / 'settings.md').write_text('s\nx\n', encoding='utf-8')
        (tmp / 'docs' / 'key.secret').write_text('k\n', encoding='utf-8')
        (tmp / 'docs' / 'generated').mkdir()
        (tmp / 'docs' / 'generated' / 'free.md').write_text('f\n', encoding='utf-8')
        (tmp / 'docs' / 'generated' / 'index.md').write_text('i\n', encoding='utf-8')
        git('add', '-A')
        git('commit', '-q', '-m', 'work')

        r = pop.assess(tmp, base='main')
        owned = {p: (o, pat) for p, o, pat in r['owned']}
        cases.append(('an owned path is named with its owner and the rule that owns it',
                      owned.get('settings.md') == (['@maint'], '/settings.md'), str(owned)))
        cases.append(('a basename pattern owns a file at any depth, with every listed owner',
                      owned.get('docs/key.secret') == (['@maint', '@other'], '*.secret'), str(owned)))
        cases.append(('a directory pattern owns what is under it',
                      'docs/generated/index.md' in owned, str(owned)))
        cases.append(('the LAST matching rule wins, so a later line with no owner frees a file',
                      'docs/generated/free.md' in r['free'], str(r['free'])))
        cases.append(('an unowned document is reported free',
                      'docs/hello.md' in r['free'], str(r['free'])))
        words = pop.plain_words(r)
        cases.append(('the sentence names who has to look and which files, and offers the split',
                      '@maint and @other have to look' in words and 'settings.md' in words
                      and 'yours to merge' in words and 'go in on their own now' in words, words))
        out = io.StringIO()
        with contextlib.redirect_stdout(out):
            code = pop.main(['--repo', str(tmp), '--base', 'main', '--check'])
        cases.append(('--check exits 1 when an owned path is touched, and the report names it',
                      code == 1 and 'OWNED  settings.md' in out.getvalue(), out.getvalue()))

        # A docs-only change: the sentence says it is theirs, and --check passes.
        git('checkout', '-q', 'main')
        git('checkout', '-q', '-b', 'docs-only')
        (tmp / 'docs' / 'hello.md').write_text('hi\nz\n', encoding='utf-8')
        git('commit', '-q', '-am', 'docs')
        r = pop.assess(tmp, base='main')
        words = pop.plain_words(r)
        cases.append(('a documents-only change is reported as the contributor\'s to merge',
                      not r['owned'] and 'yours to merge' in words
                      and 'nothing here needs anyone else' in words, words))
        out = io.StringIO()
        with contextlib.redirect_stdout(out):
            code = pop.main(['--repo', str(tmp), '--base', 'main', '--check'])
        cases.append(('--check exits 0 on a documents-only change', code == 0, out.getvalue()))

        # An uncommitted edit is in the preview too.
        (tmp / 'settings.md').write_text('s\nuncommitted\n', encoding='utf-8')
        r = pop.assess(tmp, base='main')
        cases.append(('an uncommitted edit to an owned path is in the preview',
                      any(p == 'settings.md' for p, _, _ in r['owned']), str(r['owned'])))
        git('checkout', '-q', '--', 'settings.md')

        # No base ref: the preview says so instead of reporting a clean change.
        r = pop.assess(tmp, base='no-such-ref')
        cases.append(('an unresolvable base is said out loud, never read as clean',
                      r['base'] is None and 'no base ref resolved' in r['note']
                      and 'NOT in this preview' in r['note'], r['note']))

        # A pattern the tool cannot match is reported, not skipped.
        (tmp / '.github' / 'CODEOWNERS').write_text('/settings.md @maint\n!/never.md @x\n',
                                                     encoding='utf-8')
        r = pop.assess(tmp, base='main')
        out = io.StringIO()
        with contextlib.redirect_stdout(out):
            pop.report(r)
        cases.append(('an untranslatable pattern is reported by line, never silently skipped',
                      r['untranslatable'] == [('!/never.md', 2)]
                      and "pattern '!/never.md' is not one this tool can match" in out.getvalue(),
                      out.getvalue()))

        # THE ONE THAT MATTERS: no CODEOWNERS is NO BOUNDARY, not a clean change.
        (tmp / '.github' / 'CODEOWNERS').unlink()
        r = pop.assess(tmp, base='main')
        out = io.StringIO()
        with contextlib.redirect_stdout(out):
            pop.report(r)
        cases.append(('a missing CODEOWNERS is reported as NO BOUNDARY, never as a clean change',
                      r['codeowners'] is None and 'NO BOUNDARY' in out.getvalue()
                      and 'boundary is missing, not that the change is clean' in out.getvalue(),
                      out.getvalue()))
    finally:
        shutil.rmtree(tmp, ignore_errors=True)

    bad = [(c[0], c[2] if len(c) > 2 else '') for c in cases if not c[1]]
    check(f'precedent_owned_paths.py previews the CODEOWNERS boundary in the '
          f'contributor\'s words ({len(cases)} stated cases: owner named, basename '
          f'pattern, directory pattern, last-match-wins, free file, the sentence, '
          f'--check red, docs-only sentence, --check green, uncommitted edit, '
          f'unresolvable base, untranslatable pattern, no CODEOWNERS)',
          not bad, '; '.join(f"{n}: {d}" for n, d in bad))


def check_boundary_check_never_passes_unread():
    """precedent_boundary_check.py reports PASS only for protection shaped
    the way the plan needs, FAIL for each way it can be wrong, and
    UNVERIFIED -- never PASS -- when it could not ask GitHub.

    The tool is spec/CONTRIBUTOR_ACCESS.md's finding 5 (2026-09-14): a
    forgotten branch-protection step leaves Write as unrestricted write
    with nothing saying so. The API call is stubbed -- a harness case may
    not depend on the network, and no protected repository is reachable
    from a hosted session anyway. Each verdict asserts its own printed
    words (practice: control-asserts-which-failure); the token never
    appears in what is printed, and the fixture owns every environment
    variable the tool reads (practice: fixture-owns-its-state)."""
    import contextlib, io, shutil, tempfile
    sys.path.insert(0, str(ROOT / 'tools'))
    import precedent_boundary_check as pbc

    tmp = pathlib.Path(tempfile.mkdtemp(prefix='precedent-boundary-'))
    cases = []
    # Assembled so the leak gate does not read `<anything>@github.com` as an
    # address; the value is what must NOT come back out.
    token = 'ghp_NOTAREALTOKEN' + 'x' * 8
    env_with = {'GITHUB_TOKEN': token}
    calls = []

    def stub(status, body):
        def fetch(owner, name, branch, tok):
            calls.append((owner, name, branch, tok))
            return status, body
        return fetch

    good = {'required_pull_request_reviews': {'require_code_owner_reviews': True,
                                              'required_approving_review_count': 0},
            'enforce_admins': {'enabled': True}}

    def run(env, fetch, branch=None):
        out = io.StringIO()
        with contextlib.redirect_stdout(out):
            r = pbc.assess(tmp, branch=branch, env=env, fetch=fetch)
            pbc.report(r)
        return r, out.getvalue()

    try:
        subprocess.run(['git', 'init', '-q', str(tmp)], capture_output=True)
        subprocess.run(['git', '-C', str(tmp), 'remote', 'add', 'origin',
                        'https://github.com/example/doc-project.git'], capture_output=True)
        (tmp / '.github').mkdir()
        (tmp / '.github' / 'CODEOWNERS').write_text('/.github/ @maint\n', encoding='utf-8')
        (tmp / 'precedent.json').write_text('{"base_branch": "trunk"}', encoding='utf-8')

        r, out = run({}, stub(200, good))
        cases.append(('no token is UNVERIFIED and says which variables to set, and GitHub is not called',
                      r['verdict'] == 'UNVERIFIED' and 'no token in the environment' in out
                      and 'UNVERIFIED is not a pass' in out and not calls, out))

        r, out = run(env_with, stub(200, good))
        cases.append(('protection shaped as the plan needs, plus CODEOWNERS in the tree, is PASS',
                      r['verdict'] == 'PASS' and 'boundary-check: PASS' in out
                      and 'merge their own documents and nothing else' in out, out))
        cases.append(('the declared base branch is what gets asked about, and the token is passed',
                      calls and calls[-1][:3] == ('example', 'doc-project', 'trunk')
                      and calls[-1][3] == token, str(calls)))
        cases.append(('the token is never printed', token not in out, out))

        r, out = run(env_with, stub(200, good), branch='other')
        cases.append(('--branch overrides the declared base', calls[-1][2] == 'other', str(calls[-1])))

        r, out = run(env_with, stub(404, {'message': 'Branch not protected'}))
        cases.append(('an unprotected base branch is FAIL and says what to turn on',
                      r['verdict'] == 'FAIL' and 'NOT protected' in out
                      and 'require review from code owners' in out, out))

        r, out = run(env_with, stub(403, {'message': 'Upgrade to GitHub Pro or make this repository public to enable this feature.'}))
        cases.append(('protection unavailable on the plan is FAIL, not UNVERIFIED -- it is an answer',
                      r['verdict'] == 'FAIL' and 'not available on this repository\'s plan' in out, out))

        r, out = run(env_with, stub(403, {'message': 'Resource not accessible by integration'}))
        cases.append(('a 403 that is a refusal to answer is UNVERIFIED and names the scope needed',
                      r['verdict'] == 'UNVERIFIED' and 'administration read' in out, out))

        r, out = run(env_with, stub(401, {'message': 'Bad credentials'}))
        cases.append(('a refused token is UNVERIFIED', r['verdict'] == 'UNVERIFIED'
                      and 'refused the token (401)' in out, out))

        r, out = run(env_with, stub(None, 'timed out'))
        cases.append(('an unreachable network is UNVERIFIED with the error',
                      r['verdict'] == 'UNVERIFIED' and 'could not reach GitHub: timed out' in out, out))

        body = {'required_pull_request_reviews': {'require_code_owner_reviews': True,
                                                  'required_approving_review_count': 1}}
        r, out = run(env_with, stub(200, body))
        cases.append(('required approvals above 0 is FAIL and names the bottleneck',
                      r['verdict'] == 'FAIL' and 'required approvals is 1, not 0' in out, out))

        body = {'required_pull_request_reviews': {'require_code_owner_reviews': False,
                                                  'required_approving_review_count': 0}}
        r, out = run(env_with, stub(200, body))
        cases.append(('code-owner review not required is FAIL',
                      r['verdict'] == 'FAIL' and 'review from code owners is not required' in out, out))

        r, out = run(env_with, stub(200, {'enforce_admins': {'enabled': False}}))
        cases.append(('no pull-request requirement is FAIL, and admin bypass is a note beside it',
                      r['verdict'] == 'FAIL' and 'a pull request is not required' in out
                      and 'note: administrators can bypass' in out, out))

        (tmp / '.github' / 'CODEOWNERS').unlink()
        r, out = run(env_with, stub(200, good))
        cases.append(('good protection with no CODEOWNERS in the tree is FAIL',
                      r['verdict'] == 'FAIL' and 'no CODEOWNERS file in the tree' in out
                      and r['codeowners'] is None, out))

        subprocess.run(['git', '-C', str(tmp), 'remote', 'set-url', 'origin',
                        'https://git.example.com/example/doc-project.git'], capture_output=True)
        before = len(calls)
        r, out = run(env_with, stub(200, good))
        cases.append(('a non-github remote is UNVERIFIED and GitHub is not asked',
                      r['verdict'] == 'UNVERIFIED' and 'not a github.com remote' in out
                      and len(calls) == before, out))

        # main() --check: UNVERIFIED and FAIL exit 1, PASS exits 0. The module's
        # fetch and the process environment are both owned here and restored.
        subprocess.run(['git', '-C', str(tmp), 'remote', 'set-url', 'origin',
                        'https://github.com/example/doc-project.git'], capture_output=True)
        (tmp / '.github' / 'CODEOWNERS').write_text('/.github/ @maint\n', encoding='utf-8')
        real_fetch = pbc.fetch_protection
        saved = {k: os.environ.get(k) for k in ('PRECEDENT_GITHUB_TOKEN', 'GITHUB_TOKEN', 'GH_TOKEN')}
        try:
            for k in saved:
                os.environ.pop(k, None)
            pbc.fetch_protection = stub(200, good)
            out = io.StringIO()
            with contextlib.redirect_stdout(out):
                code = pbc.main(['--repo', str(tmp), '--check'])
            cases.append(('--check exits 1 on UNVERIFIED (no token), and 0 without --check',
                          code == 1 and 'UNVERIFIED' in out.getvalue(), out.getvalue()))
            with contextlib.redirect_stdout(io.StringIO()):
                code0 = pbc.main(['--repo', str(tmp)])
            cases.append(('without --check an UNVERIFIED run exits 0', code0 == 0, str(code0)))
            os.environ['GITHUB_TOKEN'] = token
            with contextlib.redirect_stdout(io.StringIO()):
                code = pbc.main(['--repo', str(tmp), '--check'])
            cases.append(('--check exits 0 on PASS', code == 0, str(code)))
            pbc.fetch_protection = stub(404, {'message': 'Branch not protected'})
            with contextlib.redirect_stdout(io.StringIO()):
                code = pbc.main(['--repo', str(tmp)])
            cases.append(('a FAIL exits 1 with or without --check', code == 1, str(code)))
        finally:
            pbc.fetch_protection = real_fetch
            for k, v in saved.items():
                if v is None:
                    os.environ.pop(k, None)
                else:
                    os.environ[k] = v
    finally:
        shutil.rmtree(tmp, ignore_errors=True)

    bad = [(c[0], c[2] if len(c) > 2 else '') for c in cases if not c[1]]
    check(f'precedent_boundary_check.py passes only protection shaped as the plan '
          f'needs and never reads "could not look" as a pass ({len(cases)} stated '
          f'cases: no token, PASS, declared branch, token unprinted, --branch, '
          f'unprotected, plan, refused 403, 401, network, approvals, no code-owner '
          f'review, no PR requirement, no CODEOWNERS, non-github remote, and the '
          f'four exit codes)',
          not bad, '; '.join(f"{n}: {d}" for n, d in bad))


def check_very_deep_check_boundary_audit_reads_the_setting():
    """very_deep_check.py's CONTRIBUTOR BOUNDARY section reports a stale
    generated CODEOWNERS as a finding, a repo with no registry as drawing no
    boundary, and GitHub's answer -- or its absence -- in its own words.

    Added 2026-09-14 with the section (practice: very-deep-check, pass 2:
    a boundary is a setting, not a document). The API is stubbed at the
    module boundary of precedent_boundary_check, and each case asserts the
    printed row for that case (practice: control-asserts-which-failure);
    the fixture owns the three token variables the tool reads
    (practice: fixture-owns-its-state)."""
    import contextlib, io, shutil, tempfile
    sys.path.insert(0, str(ROOT / 'tools'))
    import very_deep_check as vdc
    import precedent_boundary_check as pbc
    import build_codeowners as bco

    tmp = pathlib.Path(tempfile.mkdtemp(prefix='precedent-vdc-boundary-'))
    cases = []
    real_fetch = pbc.fetch_protection
    saved = {k: os.environ.get(k) for k in ('PRECEDENT_GITHUB_TOKEN', 'GITHUB_TOKEN', 'GH_TOKEN')}
    good = {'required_pull_request_reviews': {'require_code_owner_reviews': True,
                                              'required_approving_review_count': 0},
            'enforce_admins': {'enabled': True}}
    try:
        for k in saved:
            os.environ.pop(k, None)
        project = tmp / 'project'
        project.mkdir()
        subprocess.run(['git', 'init', '-q', str(project)], capture_output=True)
        subprocess.run(['git', '-C', str(project), 'remote', 'add', 'origin',
                        'https://github.com/example/doc-project.git'], capture_output=True)
        (project / 'precedent.json').write_text(json.dumps({
            'base_branch': 'main',
            'maintainers': [{'name': 'M', 'github': 'maint'}],
            'owned_paths': [{'path': '/.github/', 'why': 'workflows'}]}), encoding='utf-8')
        bare = tmp / 'bare'
        bare.mkdir()
        (bare / 'precedent.json').write_text('{"base_branch": "main"}', encoding='utf-8')
        sources = [{'level': 'team', 'name': 'fixture-team', 'path': str(bare)}]

        def run(root, skip_api=False):
            out = io.StringIO()
            f, n = vdc.boundary_audit(root, sources, skip_api=skip_api, out=out)
            return f, n, out.getvalue()

        f, n, out = run(project)
        cases.append(('a project whose registry has no generated CODEOWNERS yet is a finding',
                      any('does not exist' in x for x in f) and 'FINDING' in out, out))
        cases.append(('a repo with no registry is reported as drawing no boundary, never as clean',
                      'draws no boundary' in out and not any('fixture-team' in x for x in f), out))

        with contextlib.redirect_stdout(io.StringIO()):
            bco.main(check_only=False, root=project)
        (project / '.github' / 'CODEOWNERS').write_text('/.github/ @someone-else\n', encoding='utf-8')
        f, n, out = run(project, skip_api=True)
        cases.append(('a hand-edited CODEOWNERS is a finding naming the mismatch',
                      any('does not match' in x for x in f), out))
        cases.append(('--skip-liveness leaves protection unasked and says so as a note, not a pass',
                      any('not asked' in x for x in n) and 'not asked' in out, out))

        with contextlib.redirect_stdout(io.StringIO()):
            bco.main(check_only=False, root=project)
        f, n, out = run(project)
        cases.append(('a current CODEOWNERS with no token is UNVERIFIED -- a note, never a finding',
                      not f and any('UNVERIFIED' in x for x in n) and 'not a pass' in ''.join(n), out))

        os.environ['GITHUB_TOKEN'] = 'ghp_NOTAREALTOKEN' + 'y' * 8
        pbc.fetch_protection = lambda o, nm, b, tok: (200, good)
        f, n, out = run(project)
        cases.append(('protection on and CODEOWNERS current is a PASS row with no finding',
                      not f and 'PASS' in out and 'shaped as the plan needs' in out, out))
        pbc.fetch_protection = lambda o, nm, b, tok: (404, {'message': 'Branch not protected'})
        f, n, out = run(project)
        cases.append(('an unprotected base branch is a finding naming it',
                      any('NOT protected' in x for x in f), out))
    finally:
        pbc.fetch_protection = real_fetch
        for k, v in saved.items():
            if v is None:
                os.environ.pop(k, None)
            else:
                os.environ[k] = v
        shutil.rmtree(tmp, ignore_errors=True)

    bad = [(c[0], c[2] if len(c) > 2 else '') for c in cases if not c[1]]
    check(f'very_deep_check.py\'s CONTRIBUTOR BOUNDARY reads the setting, not the '
          f'document ({len(cases)} stated cases: missing file, no registry, '
          f'hand-edited file, --skip-liveness, no token, PASS, unprotected)',
          not bad, '; '.join(f"{n}: {d[:300]}" for n, d in bad))


def check_build_views_summary_matches_what_it_wrote():
    """build_views.py's summary line reports the block it actually wrote.

    THE INCIDENT (2026-09-07). The summary re-derived its figures with a
    second build_loader_block() call, from the single-source catalogue,
    while the block itself had been built from the multi-source resolve. A
    run printed "resident 7/69 practices" and wrote a file whose own header
    said "7 of 72" -- the artifact was right and the line a session reads to
    confirm the run was wrong, which is the worse half to have wrong. It
    surfaced only because a merge happened to add repo-local practices and
    somebody read both numbers in the same minute.

    Runs against a COPY: this is a real write run, not --check, because the
    disagreement lived between what was printed and what was written and
    only a write produces both.
    """
    import tempfile, shutil
    tmp = pathlib.Path(tempfile.mkdtemp(prefix='precedent-summary-'))
    try:
        repo = tmp / 'repo'
        shutil.copytree(ROOT, repo, ignore=shutil.ignore_patterns(
            '.git', '__pycache__', '*.pyc', 'prompts'))
        r = subprocess.run(
            [sys.executable, str(repo / 'tools' / 'build_views.py')],
            capture_output=True, text=True, cwd=str(repo))
        if r.returncode != 0:
            check('build_views summary reports the block it wrote', False,
                  f'build_views exited {r.returncode}: '
                  f'{(r.stdout + r.stderr).strip()[:300]}')
            return
        m_out = re.search(r'resident (\d+)/(\d+) practices, ~(\d+) tokens',
                          r.stdout)
        header = (repo / 'AGENTS.md').read_text(encoding='utf-8')
        m_file = re.search(
            r'## Resident block \(~(\d+) of \d+ token budget, '
            r'(\d+) of (\d+) practices', header)
        if not m_out or not m_file:
            check('build_views summary reports the block it wrote', False,
                  f'could not parse both figures (stdout matched: '
                  f'{bool(m_out)}, AGENTS.md matched: {bool(m_file)})')
            return
        printed = (int(m_out.group(1)), int(m_out.group(2)), int(m_out.group(3)))
        written = (int(m_file.group(2)), int(m_file.group(3)), int(m_file.group(1)))
        check('build_views summary reports the block it wrote '
              '(resident, total and token count all match AGENTS.md)',
              printed == written,
              f'printed {printed}, wrote {written}')
    finally:
        shutil.rmtree(tmp, ignore_errors=True)


def check_legacy_status_migration():
    """A practice written under the OLD status vocabulary can be classified,
    and cannot be classified by guessing.

    THE GAP THIS CLOSES. `status: retired` used to mean two different things
    -- a redundant copy of a rule still fully in force elsewhere, and a rule
    withdrawn everywhere -- and a legacy record does not say which. The
    records are in the private practice sets; BestPractice's own catalogue
    never had one, which is exactly why nothing here would otherwise
    exercise this. So the fixtures below reproduce both real cases:

      bestpractice-sync   the surviving copy has the SAME slug, in another
                          source -- mechanically determinable.
      header-caps         the surviving rule is `headline-capitalization`
                          at universal -- a RENAMED successor, which nothing
                          mechanical connects to it. Must come back
                          UNDETERMINED rather than guessed.

    The second is the one that matters. A migration willing to guess at a
    renamed successor would re-introduce precisely the resemblance-based
    reasoning the whole status rename removes."""
    import tempfile, shutil
    sys.path.insert(0, str(ROOT / 'tools'))
    import precedent_migrate_status as pms

    tmp = pathlib.Path(tempfile.mkdtemp(prefix='precedent-legacy-'))
    cases = []
    try:
        src = (ROOT / 'practices' / 'verify-postcondition.md').read_text(encoding='utf-8')

        def make(root, slug, status='active', story=None, legacy=False):
            d = tmp / root / 'practices'
            d.mkdir(parents=True, exist_ok=True)
            x = re.sub(r'^slug:(\s+)\S+$', rf'slug:\g<1>{slug}', src, count=1, flags=re.M)
            x = re.sub(r'^status:(\s+)active$', rf'status:\g<1>{status}', x, count=1, flags=re.M)
            if legacy:                       # the field did not exist yet
                x = re.sub(r'^in_force_at: null\n', '', x, count=1, flags=re.M)
            if story is not None:
                x = re.sub(r'(?s)## Story\n.*?\n## Install',
                           f'## Story\n{story}\n\n## Install', x, count=1)
            (d / f'{slug}.md').write_text(x, encoding='utf-8')
            return d / f'{slug}.md'

        team_sync = make('team', 'bestpractice-sync', 'retired',
                         'Moved to the individual set.', legacy=True)
        team_caps = make('team', 'header-caps', 'retired',
                         'The universal catalogue carries this now.', legacy=True)
        make('individual', 'bestpractice-sync')
        make('universal', 'headline-capitalization')
        against = [str(tmp / 'individual'), str(tmp / 'universal')]

        recs = pms.legacy_records(tmp / 'team' / 'practices')
        cases.append(('a legacy record (non-active, no in_force_at) is found',
                      {fm.get('slug') for _f, fm, _s in recs}
                      == {'bestpractice-sync', 'header-caps'}))

        live = pms.active_slugs(against)
        cases.append(('only ACTIVE slugs count as a surviving copy',
                      'bestpractice-sync' in live and 'headline-capitalization' in live))

        # report-only must never write
        before = team_sync.read_text(encoding='utf-8')
        rc = pms.report(str(tmp / 'team'), against, {}, False)
        cases.append(('report-only leaves every file untouched',
                      team_sync.read_text(encoding='utf-8') == before))
        cases.append(('report-only exits non-zero while legacy records remain',
                      rc == 1))

        # the renamed successor must NOT be guessed
        rc = pms.report(str(tmp / 'team'), against, {}, True)
        caps_after = team_caps.read_text(encoding='utf-8')
        cases.append(('a RENAMED successor is left UNDETERMINED, not guessed -- '
                      'guessing here is the resemblance reasoning the rename removes',
                      'status:      retired' in caps_after
                      and 'in_force_at' not in caps_after))
        sync_after = team_sync.read_text(encoding='utf-8')
        cases.append(('...while the same-slug case IS migrated, to deduplicated',
                      'status:      deduplicated' in sync_after
                      and 'in_force_at: bestpractice-sync' in sync_after))

        # an explicitly named target that is not in force is refused
        pms.report(str(tmp / 'team'), against, {'header-caps': 'no-such-slug'}, True)
        cases.append(('an in_force_at: target that is not active anywhere is refused',
                      'no-such-slug' not in team_caps.read_text(encoding='utf-8')))

        # a real retirement needs a Story
        make('team2', 'storyless', 'retired', '', legacy=True)
        pms.report(str(tmp / 'team2'), against, {'storyless': 'none'}, True)
        cases.append(('--set ...=none is refused without a ## Story saying why',
                      'status:      retired' in
                      (tmp / 'team2' / 'practices' / 'storyless.md').read_text(encoding='utf-8')
                      and 'in_force_at' not in
                      (tmp / 'team2' / 'practices' / 'storyless.md').read_text(encoding='utf-8')))

        # the named target lands, and the result satisfies the contract
        pms.report(str(tmp / 'team'), against,
                   {'header-caps': 'headline-capitalization'}, True)
        fm, sections = sp._read_practice_file(team_caps)
        import build_views as _bv
        cases.append(('an explicitly named successor migrates cleanly',
                      _bv.practice_status(fm) == 'deduplicated'
                      and _bv._json_str(fm.get('in_force_at', '')) == 'headline-capitalization'))
        cases.append(('...and the migrated file satisfies the status contract',
                      _bv.status_contract_violation(
                          fm, sections, {'headline-capitalization'}.__contains__) is None))
        cases.append(('the migration is idempotent -- a second run finds nothing',
                      pms.report(str(tmp / 'team'), against, {}, False) == 0))

        # the rewriter must not touch a body line that merely starts "status:"
        body_trap = make('team3', 'body-trap', 'retired',
                         'status: active is a line of prose here.', legacy=True)
        pms.report(str(tmp / 'team3'), against, {'body-trap': 'engine'}, True)
        after = body_trap.read_text(encoding='utf-8')
        cases.append(('a body line beginning "status:" is not rewritten -- only '
                      'the frontmatter block is touched',
                      'status: active is a' in after
                      and 'status:      deduplicated' in after))
    finally:
        shutil.rmtree(tmp, ignore_errors=True)

    bad = [n for n, ok in cases if not ok]
    check(f'a legacy status record can be migrated, and a renamed successor '
          f'is never guessed ({len(cases)} stated cases)', not bad, '; '.join(bad))


def check_default_blocklist_runs_the_vocabulary_layer():
    """The vocabulary layer runs on every invocation, against a real list.

    THE GAP THIS CLOSES (2026-09-06). The vocabulary layer was skipped
    entirely whenever PRECEDENT_LEAK_BLOCKLIST was unset -- which is every
    continuous-integration run and every fresh clone. So the code path that
    loads patterns, compiles them and scans with them was exercised only by
    this harness, never by an actual gate run, and the gate reported PARTIAL
    forever. A mechanism that only ever runs in its own tests is one nobody
    finds out is broken.

    THE SPLIT THAT MAKES A COMMITTED LIST HONEST. The private blocklist
    holds SECRET words, and one committed to a public repo publishes the
    terms it exists to protect -- load_blocklist still refuses a private
    list located inside this repository. The DEFAULT list holds only
    publishable terms, so committing it costs nothing and it makes the layer
    real. The two are merged, and the gate says which halves ran: a clean
    scan against publishable terms is not evidence that no private word is
    present, and that sentence had to survive the change or this would just
    be the old silence with better wording."""
    import base64 as _b64
    sys.path.insert(0, str(ROOT / 'tools'))
    import leak_gate as lg

    # Both probes are base64 in the source for the same reason the gate's own
    # blocklist file is exempt from its own scan: this file IS scanned, so a
    # literal here fails the gate on its own test fixture. Reproduced while
    # writing it -- the derived-form probe below was a plain string and the
    # gate correctly refused the tree, which is the check working.
    word = _b64.b64decode('ZnVjaw==').decode()
    derived_probe = _b64.b64decode('d2hhdCBhIGJ1bmNoIG9mIGFzc2hvbGVz').decode()
    # A HOME of its own, for the reason spelled out in check_leak_gate_fires:
    # with the variable unset the gate reads the individual set named in
    # ~/.config/precedent/config.json, and this check's whole subject is what
    # happens when NOTHING is configured. Inheriting the container's real HOME
    # would quietly configure it (practice: fixture-owns-its-state).
    import tempfile as _tf
    _scratch_home = _tf.mkdtemp(prefix='precedent-defaultbl-home-')
    env_clean = {k: v for k, v in os.environ.items() if k != 'PRECEDENT_LEAK_BLOCKLIST'}
    env_clean['HOME'] = _scratch_home

    def gate(*args, env=None, cwd=None):
        # --structural-only always, because that is exactly what this check is
        # about: whether the DEFAULT blocklist makes the vocabulary layer run
        # at all. Since 2026-09-08 a bare invocation in this repo refuses
        # instead, because precedent.json declares a private source and no
        # private list is set here -- correct for a person about to push,
        # wrong for a fixture asking about the other half. Naming the half is
        # the fixture owning its own state rather than inheriting a default
        # that changed underneath it (practice: fixture-owns-its-state).
        return subprocess.run([sys.executable, str(ROOT / 'tools' / 'leak_gate.py'),
                               '--structural-only', *args],
                              capture_output=True, text=True, env=env or env_clean,
                              cwd=str(cwd or ROOT))

    # In-process calls read os.environ, not the env_clean handed to
    # subprocesses -- so the same absence has to be owned here too, or
    # load_blocklist() discovers the container's real individual set and
    # `private_configured` comes back True in a check whose subject is the
    # state where nothing is configured.
    #
    # Neighbours count as configuration too (2026-10-04). Since 2026-10-01
    # load_blocklist also reads the leak-blocklist.txt of every repository
    # checked out beside this one, so a clone with a practice set beside it
    # came back `private_configured` and this check failed or passed by
    # where the clone sat on disk -- red in the main clone of a session with
    # its sets attached, green in a scratch worktree. "Nothing configured"
    # means no neighbours either.
    def _unconfigured(fn):
        _saved = os.environ.get('HOME')
        _saved_neighbours = lg.discovered_neighbour_blocklists
        os.environ['HOME'] = _scratch_home
        os.environ.pop('PRECEDENT_LEAK_BLOCKLIST', None)
        lg.discovered_neighbour_blocklists = lambda root=None: []
        try:
            return fn()
        finally:
            lg.discovered_neighbour_blocklists = _saved_neighbours
            if _saved is None:
                os.environ.pop('HOME', None)
            else:
                os.environ['HOME'] = _saved

    pats, source, private_configured = _unconfigured(lg.load_blocklist)
    cases = [
        ('the default blocklist is applied with no environment variable set',
         len(pats) > 0 and not private_configured),
        ('the banned word is caught by it',
         any(p.search(f'a {word}ing line') for p in pats)),
        ('...including derived forms', any(p.search(derived_probe) for p in pats)),
        ('...without the Scunthorpe problem -- word boundaries, not substrings',
         not any(p.search('Scunthorpe assessment bass classic') for p in pats)),
    ]

    r = gate()
    cases.append(('a clean tree now reports OK rather than PARTIAL -- the layer '
                  'ran, so "did not run" is no longer a reachable state',
                  r.returncode == 0 and 'leak gate OK' in r.stdout
                  and 'PARTIAL' not in r.stdout))
    cases.append(('...while still saying the PRIVATE half did not run -- a clean '
                  'scan against publishable terms is not evidence about private '
                  'ones, and that had to survive the change',
                  'private half' in r.stdout and 'PRECEDENT_LEAK_BLOCKLIST' in r.stdout))

    cases.append(('the blocklist file is exempt from its own scan -- a list of '
                  'banned words necessarily contains them, and scanning it would '
                  'hard-fail the gate on its own list',
                  not lg.is_texty('tools/leak-blocklist.default.txt')
                  and lg.is_texty('tools/leak_gate.py')))

    # The two planted files below go in a throwaway worktree, never in ROOT.
    # --as-ci runs its shards side by side in ONE checkout, and a file
    # planted in ROOT was visible to every other shard for as long as this
    # gate ran: a shard that snapshotted the tree in that window
    # (_ref_including_worktree) found it dirty and had to commit it, which
    # with --isolated's empty $HOME has no identity and fails the run.
    # Found 2026-10-01: two isolated runs out of two lost a shard to
    # ZZ_leakprobe_fixture.md once a change shifted the shards' timing.
    _wt_dir = _tf.mkdtemp(prefix='precedent-leakprobe-')
    wt = pathlib.Path(_wt_dir) / 'wt'
    subprocess.run(['git', '-C', str(ROOT), 'worktree', 'add', '-q', '--detach',
                    str(wt), _ref_including_worktree(ROOT)], capture_output=True)

    def gate_wt(env=None):
        return subprocess.run([sys.executable, str(wt / 'tools' / 'leak_gate.py'),
                               '--structural-only'],
                              capture_output=True, text=True, env=env or env_clean,
                              cwd=str(wt))

    # It genuinely blocks a push, not merely matches in a unit test.
    probe = wt / 'ZZ_leakprobe_fixture.md'
    probe.write_text(f'# Fixture\n\nThis {word}ing line must be caught.\n',
                     encoding='utf-8')
    r = gate_wt()
    cases.append(('a planted instance FAILS the whole gate, not just a regex',
                  r.returncode == 1 and 'LEAK' in r.stdout))
    probe.unlink(missing_ok=True)

    # A private list is merged with the default, never replaces it.
    import tempfile
    with tempfile.TemporaryDirectory() as td:
        priv = pathlib.Path(td) / 'private.txt'
        priv.write_text('acme-corp-secret-codename\n', encoding='utf-8')
        os.environ['PRECEDENT_LEAK_BLOCKLIST'] = str(priv)  # wins over discovery
        # Neighbours stay out of the count, as in _unconfigured: the
        # arithmetic below is the default plus this one list, nothing else.
        _saved_neighbours = lg.discovered_neighbour_blocklists
        lg.discovered_neighbour_blocklists = lambda root=None: []
        try:
            merged, src, configured = lg.load_blocklist()
        finally:
            lg.discovered_neighbour_blocklists = _saved_neighbours
            os.environ.pop('PRECEDENT_LEAK_BLOCKLIST', None)
        cases.append(('a private list is MERGED with the default, never replaces '
                      'it -- configuring one must not silently drop the other',
                      configured and len(merged) == len(pats) + 1
                      and any(p.search('acme-corp-secret-codename') for p in merged)
                      and any(p.search(f'{word}ing') for p in merged)))

    # A private list inside the repo is still refused -- the guard that makes
    # the whole split safe.
    inside = wt / 'ZZ_inside_blocklist.txt'
    try:
        inside.write_text('secret-term\n', encoding='utf-8')
        r = gate_wt(env={**env_clean, 'PRECEDENT_LEAK_BLOCKLIST': str(inside)})
        cases.append(('a PRIVATE blocklist located inside this repo is still '
                      'refused -- the guard that makes a committed default safe '
                      'is that only the default may live here',
                      r.returncode == 1 and 'INSIDE' in (r.stdout + r.stderr)))
    finally:
        subprocess.run(['git', '-C', str(ROOT), 'worktree', 'remove', '--force',
                        str(wt)], capture_output=True)
        import shutil as _sh
        _sh.rmtree(_wt_dir, ignore_errors=True)

    bad = [n for n, ok in cases if not ok]
    check(f'the default blocklist makes the vocabulary layer actually run, and '
          f'the private half stays external ({len(cases)} stated cases)',
          not bad, '; '.join(bad))


def check_move_dedupe_stub_names_the_slug_alone():
    """A deduplicated stub written by tools/precedent_move.py says the rule
    is in force under its slug, and names no set as where it is in force.

    WHY (very deep check, 2026-10-05, pass 3). The stub used to end "the
    rule is in force there as `<slug>`", "there" being the destination set.
    When repo-maintenance and working-style folded into universal, every
    stub that pointed at them kept saying so, and each sentence became
    false while nothing broke: lookup is by slug. The dated "Moved to ...
    on <date>" line before it is history and keeps the destination."""
    import shutil, tempfile

    tmp = pathlib.Path(tempfile.mkdtemp(prefix='precedent-move-stub-'))
    env = _move_fixture_env(tmp)
    cases = []

    def run(args):
        return subprocess.run([sys.executable, *args], cwd=str(ROOT),
                              capture_output=True, text=True, env=env)

    try:
        tool = str(ROOT / 'tools' / 'precedent_move.py')
        boot = str(ROOT / 'tools' / 'precedent_bootstrap_source.py')
        team = tmp / 'precedent-shared-zzfold'
        r = run([boot, '--level', 'team', '--name', 'precedent-shared-zzfold',
                 '--dest', str(team), '--approver', 'Fixture Approver:fixture-gh'])
        cases.append(('the fixture set bootstraps', r.returncode == 0,
                      (r.stdout + r.stderr)[-400:]))
        (team / 'practices' / 'zz-stub.md').write_text(
            _move_fixture_practice('zz-stub'), encoding='utf-8')
        clone = tmp / 'precedent-clone'
        (clone / 'practices').mkdir(parents=True)
        r = run([tool, '--slug', 'zz-stub', '--from', 'team', '--from-path', str(team),
                 '--to', 'universal', '--to-path', str(clone),
                 '--approved-by', 'Fixture Approver'])
        cases.append(('team -> universal drafts', r.returncode == 0,
                      (r.stdout + r.stderr)[-400:]))
        r = run([tool, '--slug', 'zz-stub', '--from', 'team', '--from-path', str(team),
                 '--to', 'universal', '--to-path', str(clone),
                 '--approved-by', 'Fixture Approver', '--dedupe-only'])
        text = (team / 'practices' / 'zz-stub.md').read_text(encoding='utf-8')
        tail = text.split('This copy is deduplicated', 1)[-1].split('\n', 1)[0]
        cases.append(('--dedupe-only writes the deduplicated stub',
                      r.returncode == 0 and 'status:      deduplicated' in text,
                      (r.stdout + r.stderr)[-400:]))
        cases.append(('the stub says the rule is in force under its slug',
                      'the rule stays in force under its slug, `zz-stub`' in tail,
                      tail))
        cases.append(('the stub names no set as where the rule is in force',
                      'in force there' not in text and 'precedent-clone' not in tail
                      and 'universal' not in tail, tail))
        cases.append(('the dated move line before it still names where it went',
                      'Moved to the universal set' in text, text[-500:]))
    finally:
        shutil.rmtree(tmp, ignore_errors=True)

    failed = [c for c in cases if not c[1]]
    check(f'a deduplicated stub names the slug alone, never a set that may '
          f'later fold ({len(cases)} stated cases)', not failed,
          '; '.join(f'{n}: {d}' for n, _ok, d in failed))


def check_orphan_scan_reads_who_claims_a_script():
    """The very deep check's ORPHANS section names a check script whose
    practice is gone. It went by filename alone, so a script named for an
    older slug read as an orphan while its practice's `checked_by` named it
    and the same run executed it (very deep check, 2026-10-05). A script is
    owned when a practice's `checked_by` or its own `# practice:` line names
    a practice that exists; only a script nothing claims is reported."""
    import shutil as _sh
    import tempfile as _tf
    sys.path.insert(0, str(ROOT / 'tools'))
    import very_deep_check as _vdc
    fx = pathlib.Path(_tf.mkdtemp(prefix='vh-orphan-'))
    cases = []
    try:
        (fx / 'practices').mkdir()
        (fx / 'tools' / 'checks').mkdir(parents=True)
        (fx / 'practices' / 'new-name.md').write_text(
            '---\nslug: new-name\nchecked_by: tools/checks/check_by_field.py\n---\n',
            encoding='utf-8')
        checks = fx / 'tools' / 'checks'
        (checks / 'check_by_field.py').write_text('print(1)\n', encoding='utf-8')
        (checks / 'check_by_header.py').write_text(
            '# practice: new-name\nprint(1)\n', encoding='utf-8')
        (checks / 'check_header_names_a_ghost.py').write_text(
            '# practice: gone-name\nprint(1)\n', encoding='utf-8')
        (checks / 'check_nobody.py').write_text('print(1)\n', encoding='utf-8')
        out = ' '.join(_vdc._orphan_scan(fx))
        cases.append(('a script a practice\'s checked_by names is not an orphan',
                      'check_by_field.py' not in out))
        cases.append(('a script whose own header names an existing practice is '
                      'not an orphan', 'check_by_header.py' not in out))
        cases.append(('a header naming a practice that does not exist is still '
                      'an orphan', 'check_header_names_a_ghost.py' in out))
        cases.append(('a script nothing claims is an orphan',
                      'check_nobody.py' in out))
    finally:
        _sh.rmtree(fx, ignore_errors=True)
    bad = [n for n, ok in cases if not ok]
    check(f'the orphan scan reads who claims a check script '
          f'({len(cases)} stated cases)', not bad, '; '.join(bad))


def check_session_trailer_check_ships_with_the_engine():
    """The commit-trailer check is the engine's own, not a shared set's.

    Until 2026-10-06 check_session_trailer.py lived only in the
    repository-maintenance set, so folding that set away would have stopped
    every repository checking trailers, silently (very deep check,
    2026-10-05). Morgan, 2026-10-06: the link back to the session goes on
    every commit, except where there is none to give -- a person committing
    without an AI assistant, or a link hidden from the session -- and then
    the trailer says so. Planted, against the engine's own copy run on a
    fixture repository: a commit with no trailer fires; `Session:`,
    `Claude-Session:` and an explicit `Session: none available (...)` pass;
    a commit origin already has is not judged again."""
    import shutil as _sh
    import tempfile as _tf
    script = ROOT / 'tools' / 'checks' / 'check_session_trailer.py'
    cases = []
    fx = pathlib.Path(_tf.mkdtemp(prefix='vh-trailer-'))
    env = dict(os.environ, GIT_AUTHOR_NAME='F', GIT_AUTHOR_EMAIL='f@example.com',
               GIT_COMMITTER_NAME='F', GIT_COMMITTER_EMAIL='f@example.com',
               GIT_CONFIG_GLOBAL=os.devnull, GIT_CONFIG_NOSYSTEM='1',
               PRECEDENT_ALLOW_ANY_AUTHOR='1')
    env.pop('PRECEDENT_CHECK_RANGE', None)

    def git(*args):
        return subprocess.run(['git', '-C', str(repo), *args], env=env,
                              capture_output=True, text=True)

    def check_says():
        r = subprocess.run([sys.executable, str(script)], cwd=str(repo),
                           env=dict(env, PRECEDENT_CHECK_ROOT=str(repo)),
                           capture_output=True, text=True)
        return r.returncode

    def commit(name, message):
        (repo / name).write_text(name, encoding='utf-8')
        git('add', name)
        git('commit', '-qm', message)

    try:
        cases.append(('the check ships in the engine\'s own tools/checks/',
                      script.is_file()))
        origin = fx / 'origin.git'
        subprocess.run(['git', 'init', '-q', '--bare', str(origin)], env=env)
        repo = fx / 'repo'
        subprocess.run(['git', 'init', '-q', '-b', 'main', str(repo)], env=env)
        git('remote', 'add', 'origin', str(origin))
        commit('a', 'first\n\nSession: https://claude.ai/code/session_x')
        git('push', '-q', 'origin', 'main')
        commit('b', 'no trailer at all')
        cases.append(('a commit with no trailer fires', check_says() == 1))
        git('commit', '-q', '--amend', '-m',
            'by hand\n\nSession: none available (committed without an AI assistant)')
        cases.append(('an explicit "none available" trailer passes -- the '
                      'exception Morgan named', check_says() == 0))
        git('commit', '-q', '--amend', '-m',
            'from Claude Code\n\nClaude-Session: https://claude.ai/code/session_y')
        cases.append(('Claude-Session: passes', check_says() == 0))
        git('commit', '-q', '--amend', '-m', 'no trailer again')
        git('push', '-q', 'origin', 'main')
        cases.append(('a commit origin already has is not judged again',
                      check_says() == 0))
    finally:
        _sh.rmtree(fx, ignore_errors=True)
    bad = [n for n, ok in cases if not ok]
    check(f'the commit-trailer check ships with the engine and judges what a '
          f'push carries ({len(cases)} stated cases)', not bad, '; '.join(bad))


def check_bot_authored_commits_are_warned_where_no_person_is_declared():
    """The commit-author check's bot half judges a pull request's commits in
    CI, where nobody is declared (2026-10-06).

    Five commits authored `noreply@anthropic.com` at +0000 reached
    BestPractice's main on 2026-10-02 through a pull request merged on
    GitHub. The check that should have refused them reads only commits on no
    remote, and stands down where no identity is declared -- both true of
    every GitHub Actions runner -- so nothing ever judged them.

    The fixture is a runner's state: git's global identity is the bot, no
    PRECEDENT_COMMIT_*, no user config, and a pull-request branch already on
    the remote, carrying one bot commit. THE CONTROLS: the same branch with
    the bot commit re-authored passes the bot half and still SKIPS the whole
    check with the identity half's own wording, so the stand-down is real and
    the bot address is what fails; and the default scope over the pushed
    branch sees nothing, which is why CI passes a range
    (practice: control-asserts-which-failure)."""
    import tempfile, json as _json, shutil as _shutil
    name = ('Commit author: a bot-authored commit in a pull request\'s range '
            'is WARNED about, never refused, where no person is declared')
    script = ROOT / 'tools' / 'checks' / 'check_commit_author.py'
    need = [script, ROOT / 'tools' / 'precedent_session_check.py',
            ROOT / 'tools' / 'precedent_identity.py']
    absent = [str(p.relative_to(ROOT)) for p in need if not p.exists()]
    if absent:
        not_applicable(name, f'not in this tree: {absent}')
        return
    cases = []
    with tempfile.TemporaryDirectory() as td:
        tmp = pathlib.Path(td)
        ambient, _person, person_git = _engine_commit_env(tmp)
        bot_git = dict(person_git, GIT_AUTHOR_NAME='Claude',
                       GIT_AUTHOR_EMAIL='noreply@anthropic.com')
        bare, work = tmp / 'origin.git', tmp / 'work'
        (work / 'tools' / 'checks').mkdir(parents=True)
        for p in need:
            dest = work / p.relative_to(ROOT)
            _shutil.copy2(p, dest)

        def git(*args, env=person_git, cwd=work):
            return subprocess.run(['git', '-C', str(cwd), *args],
                                  capture_output=True, text=True, env=env)

        def commit(msg, env=person_git):
            return git('commit', '-q', '--allow-empty', '-m',
                       f'{msg}\n\nSession: none available (fixture)', env=env)

        def run(*args, rng=None):
            env = dict(ambient)
            if rng:
                env['PRECEDENT_CHECK_RANGE'] = rng
            p = subprocess.run([sys.executable, str(work / 'tools' / 'checks'
                                                    / script.name), *args],
                               cwd=str(work), capture_output=True, text=True,
                               env=env)
            return p.returncode, p.stdout + p.stderr

        git('init', '-q', '--bare', str(bare), cwd=tmp)
        git('init', '-q', '-b', 'main')
        git('remote', 'add', 'origin', str(bare))
        git('add', '-A')
        commit('the base')
        git('push', '-q', 'origin', 'main')
        git('checkout', '-q', '-b', 'pr')
        commit('a person\'s change')
        commit('a change the harness authored', env=bot_git)
        bot_sha = git('rev-parse', 'HEAD').stdout.strip()
        commit('another person\'s change')
        # On the remote, as a pull request's branch is by the time CI runs.
        git('push', '-q', 'origin', 'pr')
        rng = 'origin/main..HEAD'

        rc, out = run('--bot-authors-only', '--range', rng)
        cases.append((f'--bot-authors-only over the pull request\'s range '
                      f'warns about the bot commit and does not refuse it -- '
                      f'an emergency fallback (Morgan, 2026-10-06) '
                      f'(rc={rc}, {out[:200]!r})',
                      rc == 0 and 'WARNING' in out and bot_sha[:12] in out
                      and 'noreply@anthropic.com' in out))
        rc, out = run(rng=rng)
        cases.append((f'the whole check, with nobody declared and '
                      f'PRECEDENT_CHECK_RANGE set, warns too rather than '
                      f'standing down silently (rc={rc}, {out[:200]!r})',
                      rc == 0 and 'WARNING' in out and bot_sha[:12] in out))
        rc, out = run('--bot-authors-only')
        cases.append((f'control: the default scope over the pushed branch '
                      f'reads nothing -- why CI passes the range (rc={rc})',
                      rc == 0))

        cfg = work / 'precedent.json'
        cfg.write_text(_json.dumps({'grandfathered_commit_shas': [
            {'sha': bot_sha, 'note': 'fixture: published before the check'}]}),
            encoding='utf-8')
        rc, out = run('--bot-authors-only', '--range', rng)
        cases.append((f'a grandfathered bot commit is exempt, without a '
                      f'warning (rc={rc}, {out[:200]!r})',
                      rc == 0 and 'WARNING' not in out))
        cfg.unlink()

        # THE CONTROL: the same branch, the bot commit re-authored.
        git('reset', '-q', '--hard', 'HEAD~2')
        commit('a change the harness authored, re-authored')
        commit('another person\'s change')
        rc, out = run('--bot-authors-only', '--range', rng)
        cases.append((f'control: re-authored, the bot half passes (rc={rc}, '
                      f'{out[:200]!r})', rc == 0))
        rc, out = run(rng=rng)
        cases.append((f'control: re-authored, the whole check still stands '
                      f'down in its own words (rc={rc}, {out[:200]!r})',
                      rc == 2 and 'no identity is declared' in out))
    failed = [n for n, ok in cases if not ok]
    check(f'{name} ({len(cases)} stated cases)', not failed, '; '.join(failed))


def check_harness_drops_inherited_git_repository_variables():
    """A harness started under `git bisect run`, from a linked worktree,
    leaves the repository it was started in alone (2026-10-06).

    On 2026-10-01 a session bisected with a harness check as the test, from
    a linked worktree. `git bisect run` exports GIT_DIR, every fixture
    inherited it, and the fixture's `git init --bare` re-initialised the
    worktree's git directory as bare: `core.bare = true` in the main clone's
    shared config, and the fixture's commits on the worktree's HEAD
    (gotchas/gotcha-2026-10-01-a-harness-check-run-in-a-linked-worktree-
    turns-the-main-clone-bare.md).

    The fixture is a throwaway repository with a linked worktree, and a
    child process carrying GIT_DIR exactly as `git bisect run` sets it there,
    which then does what fixtures do: `git init --bare`, `git init`, a
    commit. THE CONTROL: the same child without importing this module does
    turn the main clone bare and moves the worktree's HEAD, so the fixture
    reproduces the trap and the import is what stops it
    (practice: control-asserts-which-failure)."""
    import tempfile
    name = ('the harness drops an inherited GIT_DIR, so a run under `git '
            'bisect run` in a linked worktree leaves the main clone alone')
    child = (
        'import os, subprocess, sys\n'
        'if sys.argv[2] == "import":\n'
        '    sys.path.insert(0, sys.argv[3]); import verify_harness\n'
        't = sys.argv[1]\n'
        'def g(*a, cwd=None):\n'
        '    subprocess.run(["git", *a], cwd=cwd, capture_output=True)\n'
        'g("init", "-q", "--bare", t + "/origin.git")\n'
        'g("init", "-q", t + "/proj")\n'
        'open(t + "/proj/f.txt", "w").write("fixture\\n")\n'
        'g("add", "-A", cwd=t + "/proj")\n'
        # Its own author: importing this module drops GIT_AUTHOR_*, and a
        # runner with an empty $HOME has no user.name to fall back on.
        'g("-c", "user.name=F", "-c", "user.email=f@example.com", "commit",\n'
        '  "-qm", "installed, catalogue vendored", cwd=t + "/proj")\n')
    cases = []
    with tempfile.TemporaryDirectory() as td:
        tmp = pathlib.Path(td)
        env = {k: v for k, v in os.environ.items()
               if k not in GIT_REPOSITORY_ENV_VARS}
        env.update(GIT_AUTHOR_NAME='F', GIT_AUTHOR_EMAIL='f@example.com',
                   GIT_COMMITTER_NAME='F', GIT_COMMITTER_EMAIL='f@example.com')

        def git(*args, cwd):
            return subprocess.run(['git', '-C', str(cwd), *args], env=env,
                                  capture_output=True, text=True).stdout.strip()

        def attempt(label, mode):
            main, linked = tmp / label / 'main', tmp / label / 'linked'
            main.mkdir(parents=True)
            git('init', '-q', '-b', 'main', cwd=main)
            git('commit', '-q', '--allow-empty', '-m',
                'base\n\nSession: none available (fixture)', cwd=main)
            git('worktree', 'add', '-q', '--detach', str(linked), 'HEAD',
                cwd=main)
            head = git('rev-parse', 'HEAD', cwd=linked)
            gitdir = git('rev-parse', '--absolute-git-dir', cwd=linked)
            work = tmp / label / 'fixture'
            work.mkdir()
            subprocess.run([sys.executable, '-c', child, str(work), mode,
                            str(ROOT / 'tools')],
                           cwd=str(linked), env=dict(env, GIT_DIR=gitdir),
                           capture_output=True, text=True)
            return (git('config', '--get', 'core.bare', cwd=main) == 'true',
                    git('rev-parse', 'HEAD', cwd=linked) != head,
                    (work / 'origin.git' / 'HEAD').is_file()
                    and bool(git('rev-parse', '-q', '--verify', 'HEAD',
                                 cwd=work / 'proj')))

        bare, moved, own = attempt('control', 'plain')
        cases.append((f'control: without the harness, the inherited GIT_DIR '
                      f'turns the main clone bare (bare={bare}) and moves the '
                      f'worktree\'s HEAD (moved={moved})', bare and moved))
        bare, moved, own = attempt('harness', 'import')
        cases.append((f'with the harness imported the main clone stays a work '
                      f'tree (bare={bare})', not bare))
        cases.append((f'...the worktree\'s HEAD does not move (moved={moved})',
                      not moved))
        cases.append((f'...and the fixture\'s repositories are its own '
                      f'(own={own})', own))
    failed = [n for n, ok in cases if not ok]
    check(f'{name} ({len(cases)} stated cases)', not failed, '; '.join(failed))


def check_retired_sets_are_dropped_only_when_nothing_is_lost():
    """Update Vendors and the very deep check drop a declared set that says it
    is retired, or that GitHub reports archived -- and only when every active
    rule it holds is in force in another declared source (Morgan,
    2026-10-06, option C). A set GitHub merely cannot find is never dropped:
    that is also what lost access looks like. Planted on a fixture
    repository with a universal source and three sets."""
    import inspect
    import shutil as _sh
    import tempfile as _tf
    sys.path.insert(0, str(ROOT / 'tools'))
    import precedent_vendor_engine as _pve
    import precedent_update as _pu
    import very_deep_check as _vdc
    fx = pathlib.Path(_tf.mkdtemp(prefix='vh-retired-'))
    cases = []

    def practice(where, slug):
        d = fx / where / 'practices'
        d.mkdir(parents=True, exist_ok=True)
        (d / f'{slug}.md').write_text(f'---\nslug: {slug}\nstatus: active\n---\n',
                                      encoding='utf-8')

    def manifest(where, retired=None):
        data = {'name': where}
        if retired is not None:
            data['retired'] = retired
        (fx / where / 'precedent-source.json').write_text(json.dumps(data),
                                                          encoding='utf-8')
    try:
        (fx / 'repo').mkdir()
        practice('uni', 'kept-rule')
        practice('folded', 'kept-rule')
        practice('orphaning', 'only-here')
        practice('live', 'live-rule')
        manifest('folded', {'date': '2026-10-06', 'folded_into': ['universal']})
        manifest('orphaning', True)
        manifest('live')
        cfg = ('{\n  "format_version": 1,\n  "_note": "kept as written",\n'
               '  "sources": [\n'
               '    {"level": "universal", "name": "uni", "path": "../uni"},\n'
               '    {"level": "shared", "name": "folded", "path": "../folded"},\n'
               '    {"level": "shared", "name": "orphaning", "path": "../orphaning"},\n'
               '    {"level": "shared", "name": "live", "path": "../live"}\n'
               '  ]\n}\n')
        pj = fx / 'repo' / 'precedent.json'
        pj.write_text(cfg, encoding='utf-8')
        dropped, kept = _pve.drop_retired_sources(fx / 'repo', apply=False)
        cases.append(('a dry run writes nothing', pj.read_text(encoding='utf-8') == cfg))
        dropped, kept = _pve.drop_retired_sources(fx / 'repo')
        names = [s['name'] for s in json.loads(pj.read_text(encoding='utf-8'))['sources']]
        cases.append(('a set that says it is retired, whose rules universal '
                      'carries, is dropped', 'folded' not in names
                      and [d[0] for d in dropped] == ['folded']))
        cases.append(('a retired set holding a rule nothing else carries is '
                      'kept, and the rule is named',
                      'orphaning' in names and kept
                      and kept[0][0] == 'orphaning' and kept[0][3] == ['only-here']))
        cases.append(('a set that says nothing is left alone', 'live' in names))
        cases.append(('the file keeps its own comments and layout',
                      '"_note": "kept as written"' in pj.read_text(encoding='utf-8')))
        practice('uni', 'live-rule')
        dropped, _k = _pve.drop_retired_sources(fx / 'repo', archived={'live'})
        names = [s['name'] for s in json.loads(pj.read_text(encoding='utf-8'))['sources']]
        cases.append(('a set GitHub reports archived is dropped once its rules '
                      'are carried -- here the last entry in the list',
                      'live' not in names and pj.read_text(encoding='utf-8').count('{') == 3))
        # Two retired sets cannot vouch for each other's rule.
        practice('twin-a', 'shared-only')
        practice('twin-b', 'shared-only')
        manifest('twin-a', True)
        manifest('twin-b', True)
        pj2 = fx / 'repo2' / 'precedent.json'
        pj2.parent.mkdir()
        pj2.write_text(json.dumps({'sources': [
            {'level': 'universal', 'name': 'uni', 'path': '../uni'},
            {'level': 'shared', 'name': 'twin-a', 'path': '../twin-a'},
            {'level': 'shared', 'name': 'twin-b', 'path': '../twin-b'}]}),
            encoding='utf-8')
        d2, k2 = _pve.drop_retired_sources(fx / 'repo2', apply=False)
        cases.append(('two retired sets holding the same rule do not vouch for '
                      'each other: both are kept', not d2 and len(k2) == 2))
        cases.append(('archived_declared_sources never turns an unanswered '
                      'question into "archived"',
                      'Not Found' in inspect.getsource(_pve.archived_declared_sources)
                      and "archived.add(name)" in inspect.getsource(
                          _pve.archived_declared_sources)))
        cases.append(('Update Vendors runs the drop', 'retired_sources_step(repo, rep)'
                      in inspect.getsource(_pu.update)))
        cases.append(('the very deep check reports it and writes nothing',
                      'RETIRED SETS' in inspect.getsource(_vdc)
                      and 'ARCHIVED_SOURCES, apply=False' in inspect.getsource(_vdc)))
    finally:
        _sh.rmtree(fx, ignore_errors=True)
    bad = [n for n, ok in cases if not ok]
    check(f'a retired or archived set is dropped only when no rule is lost '
          f'({len(cases)} stated cases)', not bad, '; '.join(bad))


def check_generated_files_candidates_are_repo_rooted_claims():
    """The very deep check's GENERATED FILES section asks the session to
    judge tracked files a tool may write that tools/generated_files.json
    does not list. It matched a basename written under ANY directory and
    the bare word "generated", so six hand-kept files came back every run
    (very deep check, 2026-10-05, pass 2). It now counts a write only at the
    file's full path in this repo, a heading only when it claims to be
    generated, and honours the registry's not_generated verdicts."""
    import shutil as _sh
    import tempfile as _tf
    sys.path.insert(0, str(ROOT / 'tools'))
    import very_deep_check as _vdc
    fx = pathlib.Path(_tf.mkdtemp(prefix='vh-genfiles-'))
    cases = []
    try:
        def put(rel, text):
            (fx / rel).parent.mkdir(parents=True, exist_ok=True)
            (fx / rel).write_text(text, encoding='utf-8')
        put('tools/writer.py',
            "def seed(dest):\n"
            "    (dest / 'out' / 'budgets.json').write_text('{}')\n"
            "def fixture(out):\n"
            "    (out / 'settings.json').write_text('{}')\n"
            "def mine(ROOT):\n"
            "    (ROOT / 'out' / 'built.json').write_text('{}')\n"
            "def judged(ROOT):\n"
            "    (ROOT / 'kept.json').write_text('{}')\n")
        put('out/budgets.json', '{}\n')
        put('settings.json', '{}\n')
        put('out/built.json', '{}\n')
        put('kept.json', '{}\n')
        put('docs/slide.md', '# Method\n\nOffice formats are generated outputs.\n')
        put('docs/view.md', '# A view\n\nGenerated by tools/x.py -- do not hand-edit.\n')
        put('tools/generated_files.json', json.dumps({
            'files': [],
            'not_generated': [
                {'path': 'kept.json', 'reason': 'hand-kept; a key is set in place'},
                {'path': 'gone.json', 'reason': 'was hand-kept'}]}))
        subprocess.run(['git', 'init', '-q', str(fx)], check=True)
        subprocess.run(['git', '-C', str(fx), 'add', '-A'], check=True)
        got = dict(_vdc.unlisted_generated_candidates(fx))
        cases.append(('a same-named file a tool writes under another '
                      'directory is not a candidate',
                      'out/budgets.json' not in got and 'settings.json' not in got))
        cases.append(('a write at the full path in this repo is',
                      'out/built.json' in got))
        cases.append(('the bare word "generated" is not a claim',
                      'docs/slide.md' not in got))
        cases.append(('"generated by ... do not hand-edit" is',
                      'docs/view.md' in got))
        cases.append(('a not_generated verdict is honoured',
                      'kept.json' not in got))
        cases.append(('a not_generated entry for a file that is gone comes back',
                      'gone.json' in got))
        reg = json.loads((ROOT / 'tools' / 'generated_files.json').read_text(encoding='utf-8'))
        seeded = {e.get('path'): e.get('reason') for e in reg.get('not_generated') or []}
        cases.append(('this repo records the six judged hand-kept files, each with a reason',
                      all(seeded.get(p) for p in (
                          '.claude/settings.json', 'precedent.json',
                          'tools/routing_scope.json', 'tools/session_load_budgets.json',
                          'deck/sample/slides/04_working_method.md',
                          'spec/GENERATED_FILES_PLAN.md'))))
    finally:
        _sh.rmtree(fx, ignore_errors=True)
    bad = [n for n, ok in cases if not ok]
    check(f'GENERATED FILES asks only about repo-rooted writes and real '
          f'claims, and honours not_generated ({len(cases)} stated cases)',
          not bad, '; '.join(bad))


def check_incident_coverage_reads_what_the_gotcha_names():
    """The very deep check's INCIDENT COVERAGE searched tools/ and
    practices/ for each gotcha's slug, and nothing else. Most gotchas name
    their own planted case in their Fix and no tool names the gotcha back,
    so they read as cited by nothing (very deep check, 2026-10-05, pass 2:
    nine of twelve). It now reads the check_ names a Fix gives and confirms
    each is a planted case, reports one that does not exist, credits a case
    that exercises a mechanism the Fix names, and counts a written
    "Prevention: nothing mechanical, deliberately, because ..." as an
    answer."""
    import shutil as _sh
    import tempfile as _tf
    sys.path.insert(0, str(ROOT / 'tools'))
    import very_deep_check as _vdc
    fx = pathlib.Path(_tf.mkdtemp(prefix='vh-incidents-'))
    cases = []
    try:
        (fx / 'tools' / 'checks').mkdir(parents=True)
        (fx / 'gotchas').mkdir()
        (fx / 'tools' / 'verify_harness.py').write_text(
            'def check_real_case():\n    pass\n\n'
            'def check_other_case():\n    engine_is_newer(1)\n', encoding='utf-8')
        (fx / 'tools' / 'checks' / 'check_some_script.py').write_text('', encoding='utf-8')

        def gotcha(slug, fix, story=''):
            (fx / 'gotchas' / f'{slug}.md').write_text(
                f'---\nslug: {slug}\nstatus: live\nnoted: 2026-10-01\n---\n'
                f'## Symptom\n\nx\n\n## Story\n\n{story or "x"}\n\n## Fix\n\n{fix}\n',
                encoding='utf-8')
        gotcha('gotcha-a-named', 'Planted case `check_real_case`.')
        gotcha('gotcha-b-missing', 'Planted case `check_gone_case`.')
        gotcha('gotcha-c-script', 'Refused by `check_some_script`.')
        gotcha('gotcha-d-written', 'By hand.\n\n**Prevention: nothing mechanical, '
                                   'deliberately**, because the\nfix is a '
                                   'person\'s setting.')
        gotcha('gotcha-e-mechanism', 'The refresh asks `engine_is_newer` now.')
        gotcha('gotcha-f-story-only', 'By hand.', story='Written `*check_foo()`.')
        gotcha('gotcha-g-nothing', 'By hand.')
        _s, rows, note = _vdc._incident_coverage(fx, since='2026-09-01')
        got = {r[1]: (r[4] if len(r) > 4 else {}) for r in rows}
        cases.append(('every gotcha filed since is a row', not note and len(got) == 7))
        cases.append(('a check_ name the Fix gives is a planted case',
                      got.get('gotcha-a-named', {}).get('cases') == ['check_real_case']))
        cases.append(('a check_ name nothing defines is a finding',
                      got.get('gotcha-b-missing', {}).get('missing') == ['check_gone_case']))
        cases.append(('a check script under tools/checks/ is named as one',
                      got.get('gotcha-c-script', {}).get('scripts') == ['check_some_script']))
        cases.append(('a written Prevention: answer is read',
                      (got.get('gotcha-d-written', {}).get('written') or '')
                      .startswith('nothing mechanical, deliberately')))
        cases.append(('a case exercising a mechanism the Fix names is credited',
                      got.get('gotcha-e-mechanism', {}).get('exercised')
                      == [('check_other_case', 'engine_is_newer')]))
        cases.append(('code quoted in a Story names no case',
                      not got.get('gotcha-f-story-only', {}).get('missing')))
        g = got.get('gotcha-g-nothing', {})
        cases.append(('a gotcha with none of these has nothing to show',
                      bool(g) and not any(g.values())))
        real = {r[1]: (r[4] if len(r) > 4 else {})
                for r in _vdc._incident_coverage(ROOT, since='2026-09-28')[1]}
        cases.append(('the two gotchas with no mechanical prevention say so, '
                      'and why', all(
                          (real.get(s) or {}).get('written', '') or ''
                          for s in ('gotcha-2026-09-30-auto-mode-refuses-a-bare-'
                                    'promote-into-main-as-a-production',
                                    'gotcha-2026-09-28-stale-shallow-entries-for-'
                                    'deleted-branches-survive-unshallow'))))
    finally:
        _sh.rmtree(fx, ignore_errors=True)
    bad = [n for n, ok in cases if not ok]
    check(f'INCIDENT COVERAGE reads the planted case and the Prevention answer '
          f'a gotcha gives ({len(cases)} stated cases)', not bad, '; '.join(bad))


def check_upholds_is_a_listed_field():
    """`upholds:` is a field the practice format lists, so a practice carrying
    it raises no warning. A project repository linked its practices to its
    risk page with it before the format listed it, and every check warned
    (Morgan, 2026-10-06: "we want to eliminate warnings"). A field the
    format still does not list goes on warning, so the case is not a
    blanket pass."""
    sys.path.insert(0, str(ROOT / 'tools'))
    import frontmatter_yaml as _fy
    base = ('---\nslug: x\ntitle: X\ntier: on-demand\nseverity: default\n'
            'defines: []\n{extra}status: active\n---\n## Rule\nx\n')
    with_upholds = base.format(extra='upholds: ["spec/RISK.md"]\n')
    with_unknown = base.format(extra='zz_not_a_field: 1\n')
    cases = [
        ('a practice carrying upholds: lists no unknown field',
         not _fy.unlisted_fields(with_upholds)),
        ('...and is in field order', not _fy.field_order_problem(with_upholds)),
        ('a field the format does not list is still reported',
         bool(_fy.unlisted_fields(with_unknown))),
        ('the format spec lists it',
         'upholds:' in (ROOT / 'spec' / 'PRACTICE_FORMAT.md').read_text(encoding='utf-8')),
    ]
    # A repository's OWN fields (2026-10-06): declared in precedent.json, never
    # reported, sorted after the spec's fields; a declared name the spec
    # lists is ignored, so the spec's meaning wins.
    import tempfile as _tf
    with _tf.TemporaryDirectory() as td:
        repo = pathlib.Path(td)
        (repo / 'precedent.json').write_text(json.dumps(
            {'own_frontmatter_fields': ['zz_not_a_field', 'status']}), encoding='utf-8')
        own = _fy.own_fields(repo)
        cases += [
            ('a field precedent.json declares as its own is not reported',
             own == ('zz_not_a_field',) and not _fy.unlisted_fields(with_unknown, own)),
            ('...and sorts after every listed field without a complaint',
             not _fy.field_order_problem(base.format(extra='').replace(
                 'status: active\n', 'status: active\nzz_not_a_field: 1\n'))),
            ('...while one it does not declare is still reported',
             bool(_fy.unlisted_fields(with_unknown.replace('zz_not_a_field', 'zz_other'), own))),
            ('a repository with no precedent.json declares nothing',
             _fy.own_fields(repo / 'nowhere') == ()),
        ]
    bad = [n for n, ok in cases if not ok]
    check(f'upholds: is a listed practice field, and a repository may declare '
          f'its own ({len(cases)} stated cases)', not bad, '; '.join(bad))


def check_consumer_engine_carries_what_its_checks_import():
    """A consumer's precedent_check.py imports doc_lifecycle for
    document-status-header and speculation-is-marked, and the module was on
    neither engine list, so both checks reported SKIPPED in every installed
    repo while the practices were in force (very deep check, 2026-10-05,
    pass 1). Every engine module precedent_check.py imports is now on the
    consumer list, and an installed consumer runs the check for real."""
    import re as _re
    import shutil as _sh
    import tempfile as _tf
    sys.path.insert(0, str(ROOT / 'tools'))
    import precedent_vendor_engine as _pve
    src = (ROOT / 'tools' / 'precedent_check.py').read_text(encoding='utf-8')
    mods = (set(_re.findall(r'^\s*import (\w+)', src, _re.M))
            | set(_re.findall(r'^\s*from (\w+) import', src, _re.M)))
    local = sorted(m for m in mods if (ROOT / 'tools' / f'{m}.py').is_file())
    missing = [m for m in local if f'{m}.py' not in _pve.CONSUMER_ENGINE_FILES]
    cases = [(f'every engine module precedent_check.py imports is vendored '
              f'to a consumer (missing: {", ".join(missing) or "none"})',
              not missing)]
    fx = pathlib.Path(_tf.mkdtemp(prefix='vh-doclife-'))
    try:
        subprocess.run(['git', 'init', '-q', '-b', 'main', str(fx)], check=True)
        subprocess.run([sys.executable, str(ROOT / 'tools' / 'precedent_install.py'),
                        str(fx), '--project-name', 'Fixture'],
                       capture_output=True, text=True)
        (fx / 'spec').mkdir()
        (fx / 'spec' / 'PLAN.md').write_text(
            '---\ntitle: "Plan"\nkind: reference\nstatus: current\n'
            'opened: 2026-10-06\nsupersedes: []\naudience: session\n'
            'summary: "a plan"\n---\n# Plan\n\nText.\n', encoding='utf-8')
        (fx / 'spec' / 'OTHER.md').write_text('# Other\n\nNo header.\n',
                                              encoding='utf-8')
        r = subprocess.run([sys.executable, 'tools/precedent_check.py',
                            '--only', 'document-status-header'], cwd=str(fx),
                           capture_output=True, text=True)
        out = r.stdout + r.stderr
        cases.append(('an installed consumer runs document-status-header instead '
                      'of skipping it', 'did not import' not in out
                      and 'SKIPPED' not in out))
        cases.append(('...and it finds the unstamped document',
                      'spec/OTHER.md' in out))
    finally:
        _sh.rmtree(fx, ignore_errors=True)
    bad = [n for n, ok in cases if not ok]
    check(f'a consumer\'s engine carries every module its checks import '
          f'({len(cases)} stated cases)', not bad, '; '.join(bad))


