def check_update_hands_the_engine_refresh_the_followed_tip():
    """Update Vendors runs the engine refresh with the CONSUMER's own engine
    copy, and an older copy resolves the branch it was written to follow: a
    beta-era consumer's first update vendored from precedent-beta-v01 and
    reported `refreshed from precedent-beta-v01 @ ...` under `source: main`
    (very deep check, 2026-10-05, pass 1). The update now always hands the
    refresh the tip it read, and reports the leg that landed there. An
    engine recorded ahead of the tip is still left to the refresh's own
    no-rollback guard."""
    import contextlib
    import io
    import tempfile
    pu, pve, _pr = _update_tools()
    tmp = pathlib.Path(tempfile.mkdtemp(prefix='vh-update-tip-'))
    env = dict(os.environ, GIT_AUTHOR_NAME='F', GIT_AUTHOR_EMAIL='f@example.com',
               GIT_COMMITTER_NAME='F', GIT_COMMITTER_EMAIL='f@example.com',
               GIT_CONFIG_GLOBAL=os.devnull, GIT_CONFIG_NOSYSTEM='1',
               PRECEDENT_ALLOW_ANY_AUTHOR='1')

    def git(cwd, *args):
        return subprocess.run(['git', '-C', str(cwd), *args], env=env,
                              capture_output=True, text=True)
    tip = git(ROOT, 'rev-parse', 'HEAD').stdout.strip()
    older = git(ROOT, 'rev-parse', 'HEAD~1').stdout.strip()
    saved_run = pu.run
    cases = []

    def planted(name, recorded, beta):
        # An engine copy that behaves like a beta-era one: given no
        # --from-ref it vendors `beta`, the integration branch's commit.
        repo = tmp / name
        (repo / 'tools').mkdir(parents=True)
        (repo / 'tools' / pve.MANIFEST_NAME).write_text(json.dumps({
            'source_commit': recorded, 'kind': 'consumer', 'files': []}),
            encoding='utf-8')
        argv_file = tmp / f'{name}-argv.json'
        (repo / 'tools' / 'precedent_vendor_engine.py').write_text(
            'import json, pathlib, sys\n'
            f'open({str(argv_file)!r}, "w").write(json.dumps(sys.argv[1:]))\n'
            'a = sys.argv[1:]\n'
            'ref = a[a.index("--from-ref") + 1] if "--from-ref" in a else None\n'
            f'got = ref or {beta!r}\n'
            'm = pathlib.Path(__file__).with_name("ENGINE_MANIFEST.json")\n'
            'd = json.loads(m.read_text()); d["source_commit"] = got\n'
            'm.write_text(json.dumps(d))\n'
            'print("precedent_vendor_engine refresh OK (consumer): 3 file(s) "\n'
            '      "refreshed from " + (ref or "precedent-beta-v01") + " @ " + got[:12]\n'
            f'      + " (was {recorded[:12]})")\n',
            encoding='utf-8')
        git(tmp, 'init', '-q', '-b', 'main', str(repo))
        git(repo, 'add', '-A')
        git(repo, 'commit', '-qm', 'installed\n\nSession: none available (fixture)')
        return repo, argv_file

    def run_update(repo, followed_tip):
        def fetchless(argv, cwd):
            if argv[:1] == ['git'] and 'fetch' in argv:
                return 0, ''
            if argv[:1] == ['git'] and 'rev-parse' in argv \
                    and argv[-1] == f'origin/{pve.SOURCE_BRANCH}':
                return 0, followed_tip + '\n'
            return saved_run(argv, cwd)
        pu.run = fetchless
        out = io.StringIO()
        try:
            with contextlib.redirect_stdout(out), contextlib.redirect_stderr(io.StringIO()):
                pu.update(repo, skip_check=True)
        finally:
            pu.run = saved_run
        return out.getvalue()

    try:
        repo, argv_file = planted('beta-era', older, '0' * 40)
        text = run_update(repo, tip)
        argv = json.loads(argv_file.read_text()) if argv_file.is_file() else []
        cases.append(('a repo following main hands its own engine refresh the '
                      'tip of main', argv[-2:] == ['--from-ref', tip], str(argv)))
        landed = json.loads((repo / 'tools' / pve.MANIFEST_NAME)
                            .read_text(encoding='utf-8')).get('source_commit')
        cases.append(('...so the engine lands on main, not the integration branch',
                      landed == tip, str(landed)))
        cases.append(('...and the report names main, never the branch the old '
                      'copy would have read',
                      f'refreshed from {pve.SOURCE_BRANCH} @ {tip[:12]}' in text
                      and 'precedent-beta-v01' not in text, text[-1500:]))
        two_legs = ('precedent_vendor_engine refresh OK (consumer): 3 file(s) '
                    f'refreshed from precedent-beta-v01 @ {"b" * 12} (was 1)\n'
                    'precedent_vendor_engine refresh OK (consumer): 3 file(s) '
                    f'refreshed from {tip} @ {tip[:12]} (was 1)\n')
        try:
            shown = pu.engine_summary('\n'.join(reversed(two_legs.splitlines())),
                                      None, follow='main', tip=tip)
        except TypeError as e:
            shown = f'engine_summary takes no tip: {e}'
        cases.append(('the report shows the leg that landed on the tip, whatever '
                      'order the passes print in',
                      shown.startswith(f'3 file(s) refreshed from main @ {tip[:12]}'),
                      shown))
        ahead, argv_file = planted('ahead', tip, '0' * 40)
        run_update(ahead, older)
        argv = json.loads(argv_file.read_text()) if argv_file.is_file() else []
        cases.append(('an engine recorded ahead of the tip is not told to roll '
                      'back: no --from-ref', bool(argv) and '--from-ref' not in argv,
                      str(argv)))
    finally:
        pu.run = saved_run
        shutil.rmtree(tmp, ignore_errors=True)
    bad = [(n, d) for n, ok, d in cases if not ok]
    check(f'Update Vendors refreshes the engine from the tip it read '
          f'({len(cases)} stated cases)', not bad,
          '; '.join(f'{n}: {d}' for n, d in bad))


def check_refresh_never_says_nothing_to_do_after_removing_a_file():
    """A refresh whose recorded commit already matches still removes an
    engine file the kind no longer includes, and then said "engine already
    current ... nothing to do" right under the line reporting the deletion
    (very deep check, 2026-10-05, pass 1). The line now says what this pass
    did. The fixture is an installed consumer whose manifest records one
    more engine file than the kind includes, refreshed at its own commit."""
    import hashlib as _hl
    import shutil as _sh
    import tempfile as _tf
    sys.path.insert(0, str(ROOT / 'tools'))
    import precedent_vendor_engine as _pve
    fx = pathlib.Path(_tf.mkdtemp(prefix='vh-orphan-msg-'))
    env = dict(os.environ, GIT_AUTHOR_NAME='F', GIT_AUTHOR_EMAIL='f@example.com',
               GIT_COMMITTER_NAME='F', GIT_COMMITTER_EMAIL='f@example.com',
               PRECEDENT_ALLOW_ANY_AUTHOR='1')

    def sh(*args):
        r = subprocess.run(list(args), cwd=str(fx), env=env,
                           capture_output=True, text=True)
        return r.stdout + r.stderr

    def commit(msg):
        sh('git', 'add', '-A')
        sh('git', 'commit', '-qm', f'{msg}\n\nSession: none available (fixture)')
    cases = []
    try:
        sh('git', 'init', '-q', '-b', 'main')
        sh(sys.executable, str(ROOT / 'tools' / 'precedent_install.py'), str(fx),
           '--project-name', 'Fixture')
        commit('installed')
        recorded = json.loads((fx / 'tools' / _pve.MANIFEST_NAME)
                              .read_text(encoding='utf-8'))['source_commit']
        refresh = (sys.executable, 'tools/precedent_vendor_engine.py', 'refresh',
                   str(ROOT), '--from-ref', recorded)
        sh(*refresh)                      # converge whatever the install left
        commit('converged')
        m = fx / 'tools' / _pve.MANIFEST_NAME
        d = json.loads(m.read_text(encoding='utf-8'))
        old = fx / 'tools' / 'retired_tool.py'
        old.write_text('"""A tool upstream no longer ships."""\n', encoding='utf-8')
        d['files'].append('retired_tool.py')
        d.setdefault('sha256', {})['retired_tool.py'] = _hl.sha256(
            old.read_bytes()).hexdigest()
        m.write_text(json.dumps(d, indent=2) + '\n', encoding='utf-8')
        commit('a file the kind no longer includes')
        out = sh(*refresh)
        cases.append(('the refresh removes the file', not old.exists()
                      and 'removed 1 vendored engine file' in out, out[-800:]))
        current = [l for l in out.splitlines() if 'already current with' in l]
        cases.append(('...on the already-current path', bool(current), out[-800:]))
        cases.append(('...and its closing line says so, never "nothing to do"',
                      bool(current) and 'nothing to do' not in current[-1]
                      and 'removed' in current[-1], str(current)))
    finally:
        _sh.rmtree(fx, ignore_errors=True)
    bad = [(n, x) for n, ok, x in cases if not ok]
    check(f'a refresh that removed an engine file never says nothing was done '
          f'({len(cases)} stated cases)', not bad,
          '; '.join(f'{n}: {x}' for n, x in bad))


def check_fresh_install_links_its_file_names():
    """A fresh install failed its own link convention: INSTALL.md section 0
    step 8's lint of the instantiated files listed 18 file names written
    without a link -- in the loader AGENTS.md, MAP and local-practice
    templates -- while the installer said the light check passed, because
    the lint reports them as warnings and exits 0 (very deep check,
    2026-10-05, pass 1). The templates now link them, and the installer
    counts any such name outside a generated block as a failed light
    check. The generated block is the generator's text, not a template's."""
    import inspect
    import shutil as _sh
    import tempfile as _tf
    sys.path.insert(0, str(ROOT / 'tools'))
    import generated_blocks as _gb
    import precedent_install as _pi
    fx = pathlib.Path(_tf.mkdtemp(prefix='vh-install-links-'))
    cases = []
    try:
        proj = fx / 'proj'
        proj.mkdir()
        subprocess.run(['git', 'init', '-q', '-b', 'main', str(proj)], check=True)
        r = subprocess.run([sys.executable, str(ROOT / 'tools' / 'precedent_install.py'),
                            str(proj), '--project-name', 'Fixture'],
                           capture_output=True, text=True)
        step8 = ['AGENTS.md', 'MAP.md', 'TODO.md', 'GLOSSARY.md',
                 'GETTING_STARTED.md', 'local/practices/project-voice.md',
                 'local/practices/project-visual-identity.md', 'README.md',
                 'MAP.source.md', 'practices/project-voice.md',
                 'practices/project-visual-identity.md']
        lint = subprocess.run([sys.executable, 'tools/doc_lint.py', *step8],
                              cwd=str(proj), capture_output=True, text=True)
        outside = []
        for line in lint.stdout.splitlines():
            m = re.match(r'^\s+(\S+?):(\d+): `[^`]+` is not a link$', line)
            if not m:
                continue
            mask = _gb.mask((proj / m.group(1)).read_text(encoding='utf-8'))
            n = int(m.group(2))
            if not (n - 1 < len(mask) and mask[n - 1]):
                outside.append(line.strip())
        cases.append(('section 0 step 8\'s lint finds no unlinked file name the '
                      'templates wrote', lint.returncode == 0 and not outside,
                      '; '.join(outside) or lint.stdout[-600:]))
        cases.append(('...and the installer\'s own light check passes',
                      'the light check on the written files: OK' in r.stdout,
                      r.stdout[-600:]))
        # The installer's light check counts a template's unlinked name and
        # leaves the generated block's alone.
        probe = fx / 'probe'
        probe.mkdir()
        (probe / 'A.md').write_text(
            'See `B.md` here.\n'
            '<!-- BEGIN GENERATED: precedent-loader -->\n'
            'Generated `C.md` text.\n'
            '<!-- END GENERATED -->\n', encoding='utf-8')
        fake = ('UNLINKED FILE REFERENCES — 2 (warning; link the ones you touched):\n'
                '  A.md:1: `B.md` is not a link\n'
                '  A.md:3: `C.md` is not a link\n')
        counter = getattr(_pi, '_unlinked_outside_generated', None)
        got = counter(probe, fake) if counter else None
        cases.append(('the installer counts an unlinked name a template wrote, '
                      'and not one in the generated block',
                      got == ['A.md:1: `B.md` is not a link'], str(got)))
        cases.append(('...and a counted one fails its light check',
                      counter is not None and 'not unlinked' in
                      inspect.getsource(_pi.install), ''))
    finally:
        _sh.rmtree(fx, ignore_errors=True)
    bad = [(n, x) for n, ok, x in cases if not ok]
    check(f'a fresh install links the file names its templates write '
          f'({len(cases)} stated cases)', not bad,
          '; '.join(f'{n}: {x}' for n, x in bad))


def check_debut_waits_for_an_open_produce_pull_request():
    """A move from pre-staging into staging waits while a pull request into
    main from a to-main- copy of staging is open (2026-10-06: a second Debut
    ran while a Produce pull request waited on its GitHub test, the copy
    went out of date, and the Produce had to be made again). Planted with a
    stand-in for the GitHub call: an open to-main- pull request holds, with
    the remedy; one from another branch, none at all, or GitHub unreachable
    does not; and promote() asks before a pre-staging move."""
    import inspect
    import tempfile as _tf
    sys.path.insert(0, str(ROOT / 'tools'))
    try:
        import precedent_branches as _pb
    finally:
        sys.path.pop(0)

    class _GH:
        def __init__(self, answer):
            self.answer, self.asked = answer, []

        def call(self, path, cache=True, **_kw):
            self.asked.append(path)
            return self.answer, None

    cases = []
    with _tf.TemporaryDirectory() as td:
        repo = pathlib.Path(td) / 'repo'
        subprocess.run(['git', 'init', '-q', str(repo)], check=True)
        subprocess.run(['git', '-C', str(repo), 'remote', 'add', 'origin',
                        'https://github.com/example/repo.git'], check=True)
        gh = _GH([{'number': 913, 'head': {'ref': 'to-main-20261006T093345-0300'}}])
        why = _pb.produce_waiting_hold(repo, gh=gh) or ''
        cases.append(('an open to-main- pull request into main holds the move, '
                      'naming it and the remedy',
                      '#913' in why and 'NOT PROMOTED' in why
                      and '--wait-main-test' in why))
        cases.append(('...asking GitHub for open pull requests into main only',
                      any('state=open' in a and 'base=main' in a for a in gh.asked)))
        cases.append(('an open pull request from another branch does not hold',
                      _pb.produce_waiting_hold(repo, gh=_GH([
                          {'number': 5, 'head': {'ref': 'claude/x'}}])) is None))
        cases.append(('no open pull request does not hold',
                      _pb.produce_waiting_hold(repo, gh=_GH([])) is None))
        cases.append(('GitHub unreachable does not hold (the merge check still '
                      'refuses a stale copy)',
                      _pb.produce_waiting_hold(repo, gh=_GH(None)) is None))
    src = inspect.getsource(_pb.promote)
    cases.append(('promote() asks before moving pre-staging into staging',
                  'produce_waiting_hold(root)' in src
                  and src.index('if step == STAGING:') < src.index('produce_waiting_hold(root)')))
    failed = [n for n, ok in cases if not ok]
    check(f'a Debut waits for an open Produce pull request ({len(cases)} stated cases)',
          not failed, '; '.join(failed))


def check_retired_set_takes_only_its_retirement():
    """A push to a set whose precedent-source.json says it is retired is
    refused when it changes anything that does not retire it (Morgan,
    2026-10-06: "you should not make edits to them unless the edits relate
    to their deprecation or graceful deprecation"). Planted on a fixture
    set: README, a rule moved to `status: deduplicated`, a deletion and the
    todo index pass; a rule edited while still active and an edited check
    script are refused; the person's own words in PRECEDENT_RETIRED_SET_EDIT
    let one through; the same edit in a set that is not retired passes;
    commits origin already has are not judged. A Promote in a retired set
    is refused too (Morgan, 2026-10-06: "not edit nor promote nor touch"),
    with the same way through."""
    import tempfile as _tf
    sys.path.insert(0, str(ROOT / 'tools'))
    try:
        import precedent_push_check as _ppc
    finally:
        sys.path.pop(0)
    cases = []
    fx = pathlib.Path(_tf.mkdtemp(prefix='vh-retired-set-'))
    env = dict(os.environ, GIT_CONFIG_GLOBAL=os.devnull, GIT_CONFIG_NOSYSTEM='1')
    ident = ['-c', 'user.name=F', '-c', 'user.email=f@example.com']

    def git(repo, *args):
        return subprocess.run(['git', '-C', str(repo), *args], env=env,
                              capture_output=True, text=True)

    def build(retired):
        repo = fx / ('retired' if retired else 'live')
        (repo / 'practices').mkdir(parents=True)
        (repo / 'tools' / 'checks').mkdir(parents=True)
        src = {'name': 'precedent-shared-x'}
        if retired:
            src['retired'] = {'date': '2026-10-06', 'folded_into': ['universal']}
        (repo / 'precedent-source.json').write_text(json.dumps(src), encoding='utf-8')
        (repo / 'README.md').write_text('# x\n', encoding='utf-8')
        (repo / 'practices' / 'a-rule.md').write_text(
            '---\nslug: a-rule\nstatus: active\n---\n## Rule\nOld.\n', encoding='utf-8')
        (repo / 'tools' / 'checks' / 'check_a.py').write_text('x = 1\n', encoding='utf-8')
        git(repo, 'init', '-q')
        git(repo, 'add', '-A')
        git(repo, *ident, 'commit', '-qm', 'baseline')
        git(repo, 'update-ref', 'refs/remotes/origin/main', 'HEAD')
        return repo

    def attempt(repo, edit, override=''):
        git(repo, 'reset', '-q', '--hard', 'refs/remotes/origin/main')
        edit(repo)
        git(repo, 'add', '-A')
        git(repo, *ident, 'commit', '-qm', 'an edit')
        e = {'PRECEDENT_RETIRED_SET_EDIT': override} if override else {}
        return _ppc._retired_set_refusal(repo, env=e)

    def w(rel, text):
        def write(r):
            (r / rel).parent.mkdir(parents=True, exist_ok=True)
            (r / rel).write_text(text, encoding='utf-8')
        return write

    try:
        retired, live = build(True), build(False)
        cases.append(('nothing pushed yet: no refusal',
                      _ppc._retired_set_refusal(retired, env={}) is None))
        cases.append(('the README saying it is retired passes',
                      attempt(retired, w('README.md', '# x\n\nRetired.\n')) is None))
        cases.append(('a rule moved to status: deduplicated passes',
                      attempt(retired, w('practices/a-rule.md',
                              '---\nslug: a-rule\nstatus: deduplicated\n---\n')) is None))
        cases.append(('deleting a check script passes',
                      attempt(retired, lambda r: (r / 'tools' / 'checks'
                                                  / 'check_a.py').unlink()) is None))
        cases.append(('the todo index passes',
                      attempt(retired, w('todo/TODO.md', '# todo\n')) is None))
        why = attempt(retired, w('practices/a-rule.md',
                      '---\nslug: a-rule\nstatus: active\n---\n## Rule\nNew.\n'))
        cases.append(('a rule edited while still active is refused',
                      bool(why) and 'practices/a-rule.md' in why))
        cases.append(('...and the refusal says where the change belongs',
                      'where the rule lives now' in (why or '')))
        cases.append(('an edited check script is refused',
                      bool(attempt(retired, w('tools/checks/check_a.py', 'x = 2\n')))))
        cases.append(('the person\'s own words let one through',
                      attempt(retired, w('tools/checks/check_a.py', 'x = 3\n'),
                              override='Morgan: fix check_a') is None))
        cases.append(('the same edit in a set that is not retired passes',
                      attempt(live, w('tools/checks/check_a.py', 'x = 2\n')) is None))
        git(retired, 'reset', '-q', '--hard', 'refs/remotes/origin/main')
        w('tools/checks/check_a.py', 'x = 4\n')(retired)
        git(retired, 'add', '-A')
        git(retired, *ident, 'commit', '-qm', 'already on origin')
        git(retired, 'update-ref', 'refs/remotes/origin/main', 'HEAD')
        cases.append(('an edit origin already has is not judged again',
                      _ppc._retired_set_refusal(retired, env={}) is None))
        sys.path.insert(0, str(ROOT / 'tools'))
        try:
            import precedent_branches as _pb
        finally:
            sys.path.pop(0)
        said = []
        rc = _pb.promote(retired, say=said.append)
        cases.append(('a Promote in a retired set is refused and moves nothing '
                      f'(rc={rc})', rc == 1 and any('NOT PROMOTED' in l
                                                     for l in said)))
        cases.append(('...naming the practice',
                      any('retired-set-takes-only-its-retirement' in l
                          for l in said)))
        cases.append(('the person\'s own words let a Promote through',
                      _pb.retired_set_hold(retired, env={
                          'PRECEDENT_RETIRED_SET_EDIT': 'Morgan: promote it'})
                      is None))
        cases.append(('a set that is not retired is not held',
                      _pb.retired_set_hold(live, env={}) is None))
        # The retirement Booked on pre-staging only, the clone on main: still
        # retired to both guards (2026-10-06: both real sets were exactly so).
        base = git(live, 'rev-parse', 'HEAD').stdout.strip()
        w('precedent-source.json', json.dumps({
            'name': 'precedent-shared-x',
            'retired': {'date': '2026-10-06', 'folded_into': ['universal']}}))(live)
        git(live, 'add', '-A')
        git(live, *ident, 'commit', '-qm', 'retire it, on pre-staging')
        git(live, 'update-ref', 'refs/remotes/origin/pre-staging', 'HEAD')
        git(live, 'reset', '-q', '--hard', base)
        cases.append(('a retirement only on origin/pre-staging still holds a '
                      'Promote from a clone on main',
                      bool(_pb.retired_set_hold(live, env={}))))
        w('tools/checks/check_a.py', 'x = 9\n')(live)
        git(live, 'add', '-A')
        git(live, *ident, 'commit', '-qm', 'an edit on main')
        cases.append(('...and refuses a push that edits it',
                      bool(_ppc._retired_set_refusal(live, env={}))))
    finally:
        shutil.rmtree(fx, ignore_errors=True)
    failed = [n for n, ok in cases if not ok]
    check(f'a retired set takes only its retirement ({len(cases)} stated cases)',
          not failed, '; '.join(failed))


def check_push_refuses_a_hand_made_session_branch_name():
    """A push that creates a session branch whose name
    tools/precedent_branch_name.py did not make is refused, naming the
    rename. Morgan, 2026-10-06: "how can we make sure that you always use the
    new format for temporary branches?" -- a session and its agents had typed
    date-and-topic names that lead back to no session. Planted: the tool's
    own names (and its clash form) pass; the harness-given name passes; a
    hand-typed name is refused, end to end through precedent_push_check; a
    branch origin already has is not judged again; a tier branch is not a
    session branch."""
    import shutil as _sh
    import tempfile as _tf
    sys.path.insert(0, str(ROOT / 'tools'))
    import precedent_branch_name as _bn
    cases = []
    tail = 'ab1cd'
    cases.append(('a name the tool builds passes',
                  _bn.name_refusal(_bn.build(['some', 'work'], tail=tail)[0],
                                   tail=tail) is None))
    cases.append(('the tool\'s clash form passes',
                  _bn.name_refusal('claude/2026-10-06-some-work-ab1cd-x9y8z',
                                   tail=tail) is None))
    cases.append(('a harness-given name passes',
                  _bn.name_refusal('claude/peaceful-ritchie-3u31td', tail=tail) is None))
    cases.append(('a hand-typed date-and-topic name is refused',
                  bool(_bn.name_refusal('claude/2026-10-06-vdc-fixes', tail=tail))))
    cases.append(('a name ending in another session\'s id is refused',
                  bool(_bn.name_refusal('claude/2026-10-06-some-work-zzzzz', tail=tail))))
    cases.append(('a tier branch is not judged',
                  _bn.name_refusal('pre-staging', tail=tail) is None))
    fx = pathlib.Path(_tf.mkdtemp(prefix='vh-branchname-'))
    env = dict(os.environ, GIT_CONFIG_GLOBAL=os.devnull, GIT_CONFIG_NOSYSTEM='1',
               CLAUDE_CODE_REMOTE_SESSION_ID='cse_' + 'x' * 20 + tail)
    try:
        repo = fx / 'repo'
        shutil.copytree(ROOT / 'tools', repo / 'tools',
                        ignore=shutil.ignore_patterns('__pycache__'))
        subprocess.run(['git', 'init', '-q', str(repo)], env=env, check=True)
        sys.path.insert(0, str(ROOT / 'tools'))
        import precedent_push_check as _ppc

        def refused(cmd):
            saved = dict(os.environ)
            os.environ.update(env)
            try:
                return _ppc._branch_name_refusal(repo, ['--gate', '--push-command', cmd])
            finally:
                os.environ.clear()
                os.environ.update(saved)
        cases.append(('end to end: a push creating a hand-named branch is refused',
                      bool(refused('origin HEAD:refs/heads/claude/2026-10-06-vdc-fixes'))))
        cases.append(('...and the refusal names the rename command',
                      'precedent_branch_name.py' in (refused(
                          'origin HEAD:refs/heads/claude/2026-10-06-vdc-fixes') or '')))
        cases.append(('end to end: a tool-made name is let through',
                      refused(f'origin HEAD:refs/heads/claude/2026-10-06-some-work-{tail}') is None))
        subprocess.run(['git', '-C', str(repo), 'update-ref',
                        'refs/remotes/origin/claude/2026-10-06-vdc-fixes',
                        subprocess.run(['git', '-C', str(repo), 'hash-object', '-t',
                                        'commit', '--stdin', '-w'], input=b'tree '
                                       + subprocess.run(['git', '-C', str(repo),
                                                         'hash-object', '-t', 'tree',
                                                         '-w', '--stdin'], input=b'',
                                                        capture_output=True).stdout.strip()
                                       + b'\nauthor a <a@b> 0 +0000\ncommitter a <a@b> 0 +0000\n\nx\n',
                                       capture_output=True).stdout.strip().decode()],
                       env=env, capture_output=True)
        cases.append(('a branch origin already has is not judged again',
                      refused('origin HEAD:refs/heads/claude/2026-10-06-vdc-fixes') is None))
    finally:
        _sh.rmtree(fx, ignore_errors=True)
    bad = [n for n, ok in cases if not ok]
    check(f'a push refuses a hand-made session branch name ({len(cases)} stated cases)',
          not bad, '; '.join(bad))


def check_fix_sweep_copy_keeps_its_neighbours():
    """The very deep check's fix sweep runs each new detector against a COPY
    of every repo in force. A check that looks beside the repo for a source
    cloned there (the ladder set an individual set brings) found nothing
    beside a bare temporary copy, so the ladder-words check reported the
    individual set in violation of a rule it is exempt from (very deep
    check, 2026-10-05). The copy now sits beside links to the real repo's
    siblings, and cleaning it up must never reach through those links."""
    import shutil as _sh
    import tempfile as _tf
    sys.path.insert(0, str(ROOT / 'tools'))
    import very_deep_check as _vdc
    fx = pathlib.Path(_tf.mkdtemp(prefix='vh-sweep-'))
    cases = []
    try:
        (fx / 'me').mkdir()
        (fx / 'neighbour').mkdir()
        (fx / 'neighbour' / 'keep.txt').write_text('x', encoding='utf-8')
        (fx / 'a-file').write_text('x', encoding='utf-8')
        scratch = fx / 'scratch'
        scratch.mkdir()
        _vdc._link_siblings(fx / 'me', scratch)
        link = scratch / 'neighbour'
        cases.append(('a sibling directory is linked beside the copy',
                      link.is_symlink() and (link / 'keep.txt').is_file()))
        cases.append(('the repo itself is not linked -- the copy takes its place',
                      not (scratch / 'me').exists()))
        cases.append(('a plain file beside the repo is not linked',
                      not (scratch / 'a-file').exists()))
        _sh.rmtree(scratch, ignore_errors=True)
        cases.append(('cleaning up the copy leaves the real sibling untouched',
                      (fx / 'neighbour' / 'keep.txt').is_file()))
    finally:
        _sh.rmtree(fx, ignore_errors=True)
    bad = [n for n, ok in cases if not ok]
    check(f'the fix sweep\'s copy of a repo sees that repo\'s neighbours '
          f'({len(cases)} stated cases)', not bad, '; '.join(bad))


def check_session_practices_load_without_publishing():
    """The team and individual practices reach a session here, and cannot
    reach a commit.

    THE PROBLEM (spec/PRELAUNCH_AUDIT.md, 2026-09-06). precedent.json
    declares more sources than the committed AGENTS.md carries, and 43 of
    the 114 practices in force reached no loading channel at all -- a
    session was never shown the team's or the person's own rules while the
    config said they bind the work.

    WHY THE OBVIOUS FIX IS WRONG HERE. Rendering the resolved multi-source
    set into AGENTS.md would publish private practice text, in a PUBLIC
    repo, on the commit that added the feature. The constraint is on
    COMMITTING that text, not on LOADING it -- so it is generated at session
    start into .precedent/, which is gitignored.

    The two properties that make that safe are asserted together here,
    because either alone is worthless: the file must actually carry the
    other sources' practices, AND it must be impossible to commit."""
    import tempfile, shutil, json as _json
    sys.path.insert(0, str(ROOT / 'tools'))
    import precedent_session_practices as psp

    cases = []
    tmp = pathlib.Path(tempfile.mkdtemp(prefix='precedent-session-'))
    try:
        # A repo declaring universal (itself) + a shared source.
        repo = tmp / 'repo'
        (repo / 'practices').mkdir(parents=True)
        team = tmp / 'team' / 'practices'
        team.mkdir(parents=True)
        src = (ROOT / 'practices' / 'verify-postcondition.md').read_text(encoding='utf-8')

        def mk(dest, slug, occasion):
            x = re.sub(r'^slug:(\s+)\S+$', rf'slug:\g<1>{slug}', src, count=1, flags=re.M)
            x = re.sub(r'^occasion:.*$', f'occasion:    {_json.dumps(occasion)}',
                       x, count=1, flags=re.M)
            (dest / f'{slug}.md').write_text(x, encoding='utf-8')

        mk(repo / 'practices', 'universal-one', 'doing universal work')
        mk(team, 'team-only-rule', 'committing work in this repo')
        (repo / 'precedent.json').write_text(_json.dumps({
            'format_version': 1, 'visibility': 'public',
            'sources': [{'level': 'universal', 'name': 'precedent', 'path': '.'},
                        {'level': 'team', 'name': 'precedent-team-repo-maintenance',
                         'path': str(tmp / 'team')}]}), encoding='utf-8')

        extra, levels, notes = psp.collect(str(repo))
        slugs = {fm['slug'] for fm, _s, _f in extra}
        cases.append(("a shared source's practice IS collected for the session",
                      'team-only-rule' in slugs))
        cases.append(('...and the universal one is NOT duplicated -- it is already '
                      'in the committed AGENTS.md, and repeating it would double '
                      'every session\'s resident block',
                      'universal-one' not in slugs))
        cases.append(('the level is carried, so the block can say where a rule came from',
                      levels.get('team-only-rule') == 'shared'))

        text = psp.render(extra, levels, notes)
        cases.append(('the rendered block names the shared practice',
                      'team-only-rule' in text))
        cases.append(('...and warns, in the file itself, never to commit it',
                      'Never commit it' in text))

        # An unreachable source is NAMED, not silently dropped.
        (repo / 'precedent.json').write_text(_json.dumps({
            'format_version': 1, 'visibility': 'public',
            'sources': [{'level': 'universal', 'name': 'precedent', 'path': '.'},
                        {'level': 'team', 'name': 'precedent-team-repo-maintenance',
                         'path': str(tmp / 'no-such-dir')}]}), encoding='utf-8')
        _extra, _levels, notes2 = psp.collect(str(repo))
        # notes are (kind, text) since 2026-09-13 -- the tag is what keeps a
        # DEFERRED source out of the "did not resolve" heading, so assert the
        # tag as well as the name. `in n` on a bare tuple tests membership of
        # an element, not substring, so the old form silently stopped
        # asserting anything the moment the tag landed.
        cases.append(('an unresolved source is NAMED in the output -- "unreachable" '
                      'and "that source has no rules" must not look the same',
                      any('precedent-team-repo-maintenance' in txt
                          for _k, txt in notes2)))
        cases.append(('...and it is TAGGED unresolved, so it renders under the '
                      'failure heading rather than the deferral one',
                      any(k == 'unresolved'
                          and 'precedent-team-repo-maintenance' in txt
                          for k, txt in notes2)))
        _rendered = psp.render(_extra, _levels, notes2)
        cases.append(('...and the file still renders rather than failing',
                      'did not resolve' in _rendered))
        _deferred_only = psp.render(_extra, _levels,
                                    [('deferred', 'precedent deferred to it')])
        cases.append(('a DEFERRED source is not filed under "did not resolve" '
                      '-- both kinds shared one heading until 2026-09-13, so a '
                      'set was told its working sources had failed',
                      'did not resolve' not in _deferred_only
                      and ('resolved' in _deferred_only
                           or 'precedent deferred to it' in _deferred_only)))

        # WHAT THE FILE SAYS ABOUT THE REPO IT IS IN HAS TO BE TRUE. The
        # header explains why the file is untracked, and until 2026-09-14
        # every CONSUMER got "this repository is public" -- measured in a
        # private repo whose precedent.json declares `visibility: private`,
        # where a session opening the file read a false claim about the
        # repository it was working in. A practice set was already carved
        # out for exactly this reason; a private consumer had not been.
        pub = psp.render(_extra, _levels, [], repo=str(repo))
        cases.append(('a PUBLIC consumer still says so -- the reason is true '
                      'there and is what makes the instruction land',
                      'this repository is public' in pub))
        priv = tmp / 'private-repo'
        priv.mkdir()
        (priv / 'precedent.json').write_text(_json.dumps({
            'format_version': 1, 'visibility': 'private',
            'sources': [{'level': 'universal', 'name': 'precedent',
                         'path': '.'}]}), encoding='utf-8')
        privtxt = psp.render(_extra, _levels, [], repo=str(priv))
        cases.append(('a PRIVATE consumer is never told its repository is '
                      'public, and still gets a reason and the same '
                      '"never commit it" instruction',
                      'this repository is public' not in privtxt
                      and 'goes stale' in privtxt
                      and 'Never commit it' in privtxt))
        # An ABSENT visibility keeps reading as public, matching
        # build_views.visibility_is_declared -- this file must not
        # contradict the tree it is generated beside.
        nov = tmp / 'undeclared-repo'
        nov.mkdir()
        (nov / 'precedent.json').write_text(_json.dumps({
            'format_version': 1,
            'sources': [{'level': 'universal', 'name': 'precedent',
                         'path': '.'}]}), encoding='utf-8')
        cases.append(('an UNDECLARED visibility still reads as public here, '
                      'as it does everywhere else in the engine',
                      'this repository is public'
                      in psp.render(_extra, _levels, [], repo=str(nov))))
    finally:
        shutil.rmtree(tmp, ignore_errors=True)

    # A SET THAT IS NOT STALE STILL GETS REPAIRED, and all three repairs
    # happen together. Both halves were wrong for one afternoon: the wiring
    # and ignore repairs sat inside apply_to(), which runs over the STALE sets
    # only, so a set already current got neither -- and _repairable() did not
    # look for either, so such a set appeared on no list at all. Separately,
    # hook-INSTALL and WIRING were reached by different paths, so one --apply
    # wired a hook into SessionStart and left the file absent: a
    # declared-but-missing hook, which the harness reports as nothing.
    # Reported by the set it happened in.
    rtmp = pathlib.Path(tempfile.mkdtemp(prefix='precedent-repair-'))
    try:
        import json as _j
        import precedent_refresh_sources as _rs
        import precedent_bootstrap_source as _bs3
        st = rtmp / 'set'
        (st / '.claude' / 'hooks').mkdir(parents=True)
        (st / '.claude' / 'settings.json').write_text(_j.dumps({'hooks': {
            'SessionStart': [{'hooks': [{'type': 'command', 'command':
                '$CLAUDE_PROJECT_DIR/.claude/hooks/'
                + _bs3.INDIVIDUAL_SOURCE_HOOK}]}]}}, indent=2), encoding='utf-8')
        entry = {'repo': str(st), 'hooks': {'missing': []}, 'stale': False}
        found = _rs._repairable(entry)
        cases.append(('a set that is NOT stale but is missing the wiring reads '
                      'as repairable -- apply_to() only walks the stale ones, '
                      'so this list is the only way such a set is reached',
                      any(_bs3.UNIVERSAL_CATALOGUE_HOOK in m for m in found)))
        cases.append(('...and a missing `.precedent/` ignore line does too',
                      any('.precedent/' in m for m in found)))
        ok, _msg = _rs.repair_hooks(st)
        wired = _bs3.UNIVERSAL_CATALOGUE_HOOK in ' '.join(_bs3._wired_commands(st))
        present = (st / '.claude' / 'hooks'
                   / _bs3.UNIVERSAL_CATALOGUE_HOOK).is_file()
        cases.append(('one repair pass installs the hook FILE and wires it and '
                      'writes the ignore line -- a hook wired but absent is one '
                      'the harness reports as nothing at all',
                      ok and wired and present
                      and '.precedent/' in (st / '.gitignore').read_text()))
    finally:
        shutil.rmtree(rtmp, ignore_errors=True)

    # THE WIRING IS REPAIRABLE BY A TOOL, which is the whole reason nobody
    # has to edit .claude/settings.json by hand. The harness refuses a SESSION
    # hand-editing that file; it does not refuse a vendored tool writing a
    # hook the engine ships, and a person was sent to a GitHub web form for
    # three turns before anybody tested the difference.
    wtmp = pathlib.Path(tempfile.mkdtemp(prefix='precedent-wire-'))
    try:
        import json as _json
        import precedent_bootstrap_source as _bs2
        ws = wtmp / 'set' / '.claude'
        ws.mkdir(parents=True)
        (ws / 'settings.json').write_text(_json.dumps({'hooks': {'SessionStart': [
            {'hooks': [{'type': 'command',
                        'command': '$CLAUDE_PROJECT_DIR/.claude/hooks/'
                                   + _bs2.INDIVIDUAL_SOURCE_HOOK},
                       {'type': 'command',
                        'command': '$CLAUDE_PROJECT_DIR/.claude/hooks/'
                                   'freshness-guard.sh session-start main'}]}]}},
            indent=2), encoding='utf-8')
        _p, changed = _bs2.ensure_hook_wired(wtmp / 'set',
                                             _bs2.UNIVERSAL_CATALOGUE_HOOK)
        cmds = [e['command'] for g in _json.loads(_p.read_text())['hooks']['SessionStart']
                for e in g['hooks']]
        cases.append(('an unwired set gets the catalogue hook written into its '
                      'settings.json by a TOOL -- no person, no hand edit',
                      changed and any(_bs2.UNIVERSAL_CATALOGUE_HOOK in c
                                      for c in cmds)))
        cases.append(('...placed AFTER the individual-source hook, because the '
                      'first writes the config the second resolves against',
                      cmds.index(next(c for c in cmds
                                      if _bs2.UNIVERSAL_CATALOGUE_HOOK in c))
                      == cmds.index(next(c for c in cmds
                                         if _bs2.INDIVIDUAL_SOURCE_HOOK in c)) + 1))
        before = _p.read_text()
        _p2, again = _bs2.ensure_hook_wired(wtmp / 'set',
                                            _bs2.UNIVERSAL_CATALOGUE_HOOK)
        cases.append(('...and re-running leaves the file byte-identical -- a '
                      'repair that runs every session start must not append '
                      'a duplicate each time',
                      not again and _p2.read_text() == before))
        bad = wtmp / 'broken' / '.claude'
        bad.mkdir(parents=True)
        (bad / 'settings.json').write_text('{not json', encoding='utf-8')
        _p3, ch3 = _bs2.ensure_hook_wired(wtmp / 'broken',
                                          _bs2.UNIVERSAL_CATALOGUE_HOOK)
        cases.append(('a settings.json that does not parse is LEFT ALONE -- '
                      'rewriting one somebody hand-edited and broke would '
                      'destroy their work',
                      not ch3 and _p3.read_text() == '{not json'))
    finally:
        shutil.rmtree(wtmp, ignore_errors=True)

    # A SET'S OWN PRACTICES ARE NEVER DEFERRED INTO ITS OWN SESSION FILE,
    # however the source that names them was resolved. Two clones of one
    # repository is the real case -- an individual source resolves through an
    # absolute path in ~/.config/precedent/config.json, which routinely names
    # a SECOND clone -- and until 2026-09-13 the own-tree test compared paths,
    # so a set saw its own practices as somebody else's tree and rendered them
    # twice: once from the tracked block, once from the session file. Reported
    # by the set it happened in.
    dup = pathlib.Path(tempfile.mkdtemp(prefix='precedent-samerepo-'))
    try:
        a, b = dup / 'a', dup / 'b'
        for d in (a, b):
            d.mkdir()
            subprocess.run(['git', 'init', '-q', str(d)], check=False)
        for d, url in ((a, 'https://github.com/acct/precedent-individual.git'),
                       (b, 'HTTPS://github.com/acct/precedent-individual/')):
            subprocess.run(['git', '-C', str(d), 'remote', 'add', 'origin', url],
                           check=False)
        cases.append(('two clones of one repository read as the SAME repository '
                      '-- a .git suffix, a trailing slash and case are not '
                      'differences',
                      bv._same_repository(a, b)))
        c = dup / 'c'
        c.mkdir()
        subprocess.run(['git', 'init', '-q', str(c)], check=False)
        subprocess.run(['git', '-C', str(c), 'remote', 'add', 'origin',
                        'https://github.com/acct/something-else.git'], check=False)
        cases.append(('...and two clones of DIFFERENT repositories do not -- the '
                      'test must still separate a real other tree',
                      not bv._same_repository(a, c)))
        d_no_remote = dup / 'd'
        d_no_remote.mkdir()
        cases.append(('a directory with no remote falls back to the path test '
                      'rather than matching everything',
                      bv._same_repository(d_no_remote, d_no_remote)
                      and not bv._same_repository(d_no_remote, a)))
        # A git-tracked SUBDIRECTORY with no .git of its own -- what
        # process/upstream/ is in a consumer that vendors this catalogue as
        # plain files rather than a submodule (practice-export-loop). `git -C
        # <subdir> remote get-url origin` does not stop at the subdirectory;
        # it walks up to the ENCLOSING repo and answers with ITS origin, so
        # before the repo-root check the subdir wrongly read as its
        # enclosing repo's own top-level checkout. Reported against a real
        # vendored tree, 2026-09-15.
        e = dup / 'e'
        e.mkdir()
        subprocess.run(['git', 'init', '-q', str(e)], check=False)
        subprocess.run(['git', '-C', str(e), 'remote', 'add', 'origin',
                        'https://github.com/acct/consumer-repo.git'], check=False)
        e_vendored = e / 'process' / 'upstream'
        e_vendored.mkdir(parents=True)
        cases.append(("a git-tracked subdirectory with no .git of its own is "
                      "never mistaken for its enclosing repository's own "
                      "top-level checkout, even though its `origin` resolves "
                      "to the enclosing repo's",
                      not bv._same_repository(e_vendored, e)))
    finally:
        shutil.rmtree(dup, ignore_errors=True)

    # THE SAFETY PROPERTY. Asserted against this repo's real .gitignore and
    # real git, not against a fixture: the whole design rests on this file
    # being uncommittable, and a fixture could pass while the real repo leaks.
    r = subprocess.run(['git', '-C', str(ROOT), 'check-ignore',
                        '.precedent/SESSION_PRACTICES.md'],
                       capture_output=True, text=True)
    cases.append(('.precedent/ is gitignored in THIS repo -- the private text '
                  'cannot reach a commit, which is the only reason loading it '
                  'here is safe at all', r.returncode == 0))
    r = subprocess.run(['git', '-C', str(ROOT), 'ls-files', '--error-unmatch',
                        '.precedent/SESSION_PRACTICES.md'],
                       capture_output=True, text=True)
    cases.append(('...and no such file is tracked right now', r.returncode != 0))

    # The pointer a session actually follows must be in the committed block.
    agents = (ROOT / 'AGENTS.md').read_text(encoding='utf-8')
    cases.append(('AGENTS.md tells a session the file exists -- a generated file '
                  'nothing points at is one nobody reads',
                  '.precedent/SESSION_PRACTICES.md' in agents))

    # Never fatal: it runs from a session-start hook under `set -e`.
    r = subprocess.run([sys.executable, str(ROOT / 'tools' / 'precedent_session_practices.py'),
                        '--repo', str(tmp / 'gone')], capture_output=True, text=True)
    cases.append(('it exits 0 even pointed at a directory that does not exist -- a '
                  'session that fails to START because an optional practice file '
                  'could not be written is far worse than one missing it',
                  r.returncode == 0))

    # THE INTEGRATION PROPERTY, and the one this nearly got wrong. The
    # tracked loader block now renders every declared source EXCEPT the
    # private levels in a public repo. So this file must carry exactly that
    # complement -- no more (duplicating what the block already has) and no
    # less (the gap reopening in silence). Both sides read
    # build_views.PRIVATE_LEVELS and build_views.repo_is_public, and the
    # pointer in the standing instruction is keyed off the same test: an
    # earlier version keyed it off "was this rendered single-source", which
    # stopped being true the moment a public repo rendered multi-source, and
    # the pointer silently vanished from AGENTS.md.
    sys.path.insert(0, str(ROOT / 'tools'))
    import build_views as _bv
    cases.append(('this repo declares visibility: public, so its tracked block '
                  'omits the private levels and something else must carry them',
                  _bv.repo_is_public(ROOT)))
    cases.append(('the levels this file carries are exactly the ones the block '
                  'omits -- one definition, so the two cannot disagree about '
                  'which practices a session is otherwise never shown',
                  psp.__dict__.get('bv').PRIVATE_LEVELS is _bv.PRIVATE_LEVELS))
    block_text = (ROOT / 'AGENTS.md').read_text(encoding='utf-8')
    cases.append(('no private level appears in the committed block',
                  '(team)' not in block_text.split('END GENERATED')[0]
                  and '(individual)' not in block_text.split('END GENERATED')[0]))

    # AND THE REACHABILITY CHECK MUST KNOW IT. Loading them is half the job:
    # if `layered-practice-packs` still reports them unreachable, the gap
    # reads as open, and the next session weighs publishing private text or
    # leaving the rules unloaded against a channel that already exists.
    # Found 2026-09-06 exactly that way -- by testing the claim, not
    # assuming it.
    import tempfile as _tf, shutil as _sh, json as _js
    import precedent_check as _pc
    fx = pathlib.Path(_tf.mkdtemp(prefix='precedent-fifth-'))
    try:
        repo = fx / 'repo'
        (repo / 'practices').mkdir(parents=True)
        (repo / 'tools').mkdir(parents=True)
        (repo / '.claude' / 'hooks').mkdir(parents=True)
        tsrc = fx / 'team' / 'practices'
        tsrc.mkdir(parents=True)
        base = (ROOT / 'practices' / 'verify-postcondition.md').read_text(encoding='utf-8')
        x = re.sub(r'^slug:(\s+)\S+$', r'slug:\g<1>team-unreachable', base, count=1, flags=re.M)
        x = re.sub(r'^gates:.*$', 'gates:       []', x, count=1, flags=re.M)
        x = re.sub(r'^checked_by:.*$', 'checked_by:  null', x, count=1, flags=re.M)
        (tsrc / 'team-unreachable.md').write_text(x, encoding='utf-8')
        (repo / 'AGENTS.md').write_text('# nothing names it\n', encoding='utf-8')
        (repo / 'precedent.json').write_text(_js.dumps({
            'format_version': 1, 'visibility': 'public',
            'sources': [{'level': 'universal', 'name': 'precedent', 'path': '.'},
                        {'level': 'team', 'name': 'precedent-team-repo-maintenance',
                         'path': str(fx / 'team')}]}), encoding='utf-8')
        _sh.copy(ROOT / 'tools' / 'precedent_session_practices.py', repo / 'tools')
        hook = repo / '.claude' / 'hooks' / 'session-start.sh'

        def findings():
            # The fixture owns who is working here: nobody. The real person's
            # individual set, and every set it brings, would otherwise add
            # their own findings to the count (2026-10-02).
            saved, saved_cfg = _pc.ROOT, os.environ.get('PRECEDENT_USER_CONFIG')
            _pc.ROOT = repo
            os.environ['PRECEDENT_USER_CONFIG'] = str(fx / 'no-user-config.json')
            try:
                return len(_pc._practice_is_reachable(None) or [])
            finally:
                _pc.ROOT = saved
                if saved_cfg is None:
                    os.environ.pop('PRECEDENT_USER_CONFIG', None)
                else:
                    os.environ['PRECEDENT_USER_CONFIG'] = saved_cfg

        hook.write_text('#!/bin/bash\n# no loader here\n', encoding='utf-8')
        cases.append(('with the session channel NOT wired, a private-level '
                      'practice is still reported unreachable -- the channel is '
                      'never assumed', findings() == 1))
        hook.write_text('#!/bin/bash\npython3 tools/precedent_session_practices.py\n',
                        encoding='utf-8')
        cases.append(('...and once the hook invokes it, the same practice counts '
                      'as reachable, so the gap stops reading as open',
                      findings() == 0))
        hook.write_text('#!/bin/bash\nbash tools/bootstrap.sh\n', encoding='utf-8')
        (repo / 'tools' / 'bootstrap.sh').write_text(
            '#!/bin/bash\n# no loader here either\n', encoding='utf-8')
        cases.append(('a hook that runs tools/bootstrap.sh is not wired when '
                      'bootstrap.sh does not run the tool', findings() == 1))
        (repo / 'tools' / 'bootstrap.sh').write_text(
            '#!/bin/bash\npython3 tools/precedent_session_practices.py\n',
            encoding='utf-8')
        cases.append(('...and is wired once bootstrap.sh runs it -- the shipped '
                      'consumer hook does exactly this, and every fresh install '
                      'read as unwired until 2026-10-05', findings() == 0))
        (repo / 'tools' / 'precedent_session_practices.py').unlink()
        cases.append(('...and removing the tool reopens it, even with the hook '
                      'still calling it -- both halves are required',
                      findings() == 1))
    finally:
        _sh.rmtree(fx, ignore_errors=True)

    bad = [n for n, ok in cases if not ok]
    check(f'the team and individual practices reach a session without reaching a '
          f'commit ({len(cases)} stated cases)', not bad, '; '.join(bad))


def check_not_binding_cannot_be_abused():
    """A repo can say "in force at its source, does not bind here" -- and
    cannot use that to quietly switch a rule off.

    THE GAP THIS CLOSES (TODO's `unreachable-practices`, opened by
    spec/PRELAUNCH_AUDIT.md). 43 of 114 practices in force in this repo were
    reachable by no loading channel. Running the source-supplied checks
    against the tree showed the answer is not "turn them all on": some pass,
    some report real findings, and some report things this repo cannot act
    on because the practice is about a DIFFERENT KIND OF REPOSITORY. The
    system had no vocabulary for that, so silence was doing the job, and a
    forgotten rule and a deliberately-inapplicable one looked identical.

    THE RISK, WHICH IS THE WHOLE REASON THIS CHECK EXISTS. An exemption list
    is a mechanism for opting out of rules. Left unguarded it is strictly
    worse than the silence it replaces, because it launders "I did not want
    to" into a recorded decision. So the guards are the feature, and each is
    asserted here with a negative control:

      a reason is mandatory     an exemption nobody argued for is the same
                                silence, with a config entry on top
      blocking cannot be exempt the same rule the resolver already applies
                                to precedence: a blocking practice is
                                exactly the one no downstream repo may
                                switch off
      stale exemptions surface  one naming a slug nothing puts in force is
                                a typo (and the rule it meant to exempt is
                                still unexplained) or outlived its practice
      malformed fails loudly    a list that silently ignores its own bad
                                entries is a way to opt out by typo
    """
    import tempfile, shutil, json as _json
    sys.path.insert(0, str(ROOT / 'tools'))
    import precedent_resolve as pr

    tmp = pathlib.Path(tempfile.mkdtemp(prefix='precedent-notbinding-'))
    cases = []
    try:
        def cfg(obj):
            (tmp / 'precedent.json').write_text(_json.dumps(obj), encoding='utf-8')

        base = {"format_version": 1,
                "sources": [{"level": "universal", "name": "u", "path": "."}]}

        cfg(base)
        cases.append(('a repo with no `not_binding` key reads as no exemptions',
                      pr.load_not_binding(tmp) == {}))

        cfg({**base, "not_binding": [
            {"slug": "commit-author", "reason": "about a repo one person authors alone"}]})
        cases.append(('a well-formed exemption is read, reason and all',
                      pr.load_not_binding(tmp) ==
                      {"commit-author": "about a repo one person authors alone"}))

        def refuses(obj):
            cfg(obj)
            try:
                pr.load_not_binding(tmp)
                return False
            except pr.NotBindingError:
                return True
            except Exception:
                return False

        cases.append(('an exemption with NO reason is refused -- the guard is '
                      'that opting out is argued, never merely declared',
                      refuses({**base, "not_binding": [{"slug": "x"}]})))
        cases.append(('...and an empty/whitespace reason counts as none',
                      refuses({**base, "not_binding": [{"slug": "x", "reason": "   "}]})))
        cases.append(('an exemption with no slug is refused',
                      refuses({**base, "not_binding": [{"reason": "because"}]})))
        cases.append(('a `not_binding` that is not a list is refused',
                      refuses({**base, "not_binding": {"x": "y"}})))
        cases.append(('a non-object entry is refused',
                      refuses({**base, "not_binding": ["commit-author"]})))

        # Through the REAL check function, with its ROOT pointed at a
        # fixture repo. Driven in-process rather than by subprocess because
        # precedent_check.ROOT comes from `git rev-parse --show-toplevel`,
        # not from an environment variable -- PRECEDENT_CHECK_ROOT steers the
        # source-supplied check SCRIPTS, not this module.
        import precedent_check as pc
        reachable = pc._practice_is_reachable

        def run_check(not_binding, severity='default', slug='fx-unreachable'):
            repo = tmp / 'repo'
            shutil.rmtree(repo, ignore_errors=True)
            (repo / 'practices').mkdir(parents=True)
            src = (ROOT / 'practices' / 'verify-postcondition.md').read_text(encoding='utf-8')
            x = re.sub(r'^slug:(\s+)\S+$', rf'slug:\g<1>{slug}', src, count=1, flags=re.M)
            x = re.sub(r'^severity:(\s+)\S+$', rf'severity:\g<1>{severity}', x, count=1, flags=re.M)
            x = re.sub(r'^occasion:.*$', 'occasion:    null', x, count=1, flags=re.M)
            x = re.sub(r'^gates:.*$', 'gates:       []', x, count=1, flags=re.M)
            x = re.sub(r'^checked_by:.*$', 'checked_by:  null', x, count=1, flags=re.M)
            (repo / 'practices' / f'{slug}.md').write_text(x, encoding='utf-8')
            (repo / 'AGENTS.md').write_text('# nothing names it\n', encoding='utf-8')
            # `name` is fixed by level (spec/SOURCE_NAMING.md) -- the resolver
            # refuses anything else, which this fixture found the hard way.
            (repo / 'precedent.json').write_text(_json.dumps(
                {"format_version": 1,
                 "sources": [{"level": "universal", "name": "precedent", "path": "."}],
                 **({"not_binding": not_binding} if not_binding is not None else {})}),
                encoding='utf-8')
            saved = pc.ROOT
            pc.ROOT = repo
            try:
                return ' | '.join(str(getattr(f, 'detail', f)) for f in (reachable(None) or []))
            finally:
                pc.ROOT = saved

        out = run_check(None)
        cases.append(('an unreachable practice IS reported when nothing exempts it',
                      'fx-unreachable' in out))

        out = run_check([{"slug": "fx-unreachable", "reason": "different kind of repo"}])
        cases.append(('...and stops being reported once exempted, with a reason',
                      'fx-unreachable' not in out))

        out = run_check([{"slug": "fx-unreachable", "reason": "inconvenient"}],
                        severity='blocking')
        cases.append(('a `severity: blocking` practice CANNOT be exempted -- the '
                      'one rule a downstream repo may never switch off',
                      'blocking' in out and 'fx-unreachable' in out))

        out = run_check([{"slug": "no-such-practice-anywhere", "reason": "x"},
                         {"slug": "fx-unreachable", "reason": "different kind of repo"}])
        cases.append(('a STALE exemption naming a slug nothing puts in force is '
                      'reported -- a typo must not silently exempt nothing',
                      'no-such-practice-anywhere' in out))
    finally:
        shutil.rmtree(tmp, ignore_errors=True)

    bad = [n for n, ok in cases if not ok]
    check(f'`not_binding` states what a repo is not bound by, and cannot be '
          f'used to switch a rule off quietly ({len(cases)} stated cases)',
          not bad, '; '.join(bad))


def check_codeowners_check_is_a_check():
    """`build_codeowners.py --check` verifies without writing, and its output
    is a function of its source rather than of when it ran.

    TWO DEFECTS, both found 2026-09-06 by a caller trying to VERIFY that
    CODEOWNERS was current and instead dirtying the tree mid-PR:

      1. `--check` was not a flag at all. main() ignored argv, so the flag
         fell through and the tool WROTE -- a checker that answers "is this
         current?" by making it current cannot return a wrong answer, and
         cannot return a useful one. Same shape as verify-postcondition's
         own rule one level up: the check reported success by causing the
         state it was asked to confirm.
      2. The header stamped `git rev-parse HEAD`, so regenerating produced a
         diff after EVERY commit whether or not approvers changed. A derived
         file must be a function of its SOURCE; stamped with the time it was
         built, "is it current?" has no stable answer.

    BestPractice has no approvers.json -- it is not a shared set -- so none of
    this is exercised by the tree, and that is exactly why it went unnoticed
    while the tool was private to one shared set. The fixture supplies one.
    Now that build_codeowners.py is in ENGINE_FILES, every source set the
    bootstrap creates inherits whichever behavior this has."""
    import tempfile, shutil
    tmp = pathlib.Path(tempfile.mkdtemp(prefix='precedent-codeowners-'))
    cases = []
    try:
        (tmp / 'tools').mkdir()
        shutil.copy(ROOT / 'tools' / 'build_codeowners.py', tmp / 'tools')
        approvers = tmp / 'approvers.json'
        codeowners = tmp / 'CODEOWNERS'
        approvers.write_text(
            '{"approvers": [{"name": "A", "github": "a"}, '
            '{"name": "B", "github": "b"}]}', encoding='utf-8')

        def run(*args):
            return subprocess.run(
                [sys.executable, str(tmp / 'tools' / 'build_codeowners.py'), *args],
                capture_output=True, text=True)

        r = run('--check')
        cases.append(('--check on a missing CODEOWNERS fails', r.returncode == 1))
        cases.append(('...and does NOT create it -- a checker that repairs is '
                      'a builder, and the caller cannot tell the two apart '
                      'afterwards', not codeowners.exists()))

        cases.append(('a plain run writes it', run().returncode == 0 and codeowners.is_file()))
        first = codeowners.read_bytes()
        cases.append(('--check on a current file passes', run('--check').returncode == 0))
        cases.append(('...having written nothing', codeowners.read_bytes() == first))

        run()
        cases.append(('regeneration is byte-identical when approvers.json is '
                      'unchanged -- the HEAD-sha churn that made every check '
                      'a false positive is gone', codeowners.read_bytes() == first))

        codeowners.write_bytes(first + b'# hand edit\n')
        cases.append(('a hand-edited CODEOWNERS is detected', run('--check').returncode == 1))

        run()
        approvers.write_text(
            '{"approvers": [{"name": "A", "github": "a"}]}', encoding='utf-8')
        cases.append(('a changed approver list is detected',
                      run('--check').returncode == 1))

        run()
        stable = codeowners.read_bytes()
        r = run('--chekc')
        cases.append(('a MISSPELLED flag is refused, not silently treated as '
                      '"no arguments" -- that fall-through is defect 1, and '
                      'doing the destructive thing on a typo is how it hid',
                      r.returncode != 0 and codeowners.read_bytes() == stable))

        approvers.unlink()
        cases.append(('an individual set (no approvers.json) exits 0 with a '
                      'note rather than failing', run('--check').returncode == 0))
    finally:
        shutil.rmtree(tmp, ignore_errors=True)

    bad = [n for n, ok in cases if not ok]
    check(f'build_codeowners --check verifies without writing, and its output '
          f'depends on its source not its build time ({len(cases)} stated cases)',
          not bad, '; '.join(bad))


def check_status_contract():
    """A practice that is not `active` must say where its rule went.

    THE INCIDENT (2026-09-06). `status: retired` recorded that a rule stopped
    applying here but never whether anything replaced it. The forwarding
    address lived only as English prose in `## Story`, which no tool reads, so
    "deduplicated safely" and "dropped and forgotten" were indistinguishable to
    every check in the system. A routine per-commit check was dropped on the
    authority of an unrelated occasional one -- the two rules resembled each
    other, and resemblance was accepted as coverage. Nothing failed, because
    nothing could: no check had anything to compare.

    The vocabulary is the fix, and this is what gives it teeth
    (spec/PRACTICE_FORMAT.md, "Status"):

      active         no forwarding address; the rule applies here.
      deduplicated   the COPY is redundant; `in_force_at:` names a slug that
                     must RESOLVE IN FORCE, or `engine`.
      retired        wanted nowhere; `in_force_at: none` and a real ## Story.

    WHAT THIS CHECK REFUSES TO CLAIM. "Resolves in force" is only answerable
    against the actually-declared sources. When any of them is unreachable --
    a sibling clone this session does not have -- the resolved set is
    incomplete, and a "does not resolve" verdict would be an artifact of the
    missing checkout rather than a finding. In that case this degrades to the
    SHAPE check (a forwarding address is present and well-formed) and says so
    in its own name, rather than reporting a weaker check as the stronger
    one."""
    import tempfile, shutil
    sys.path.insert(0, str(ROOT / 'tools'))
    import build_views as _bv
    import precedent_resolve as _pr

    # --- can we resolve for real this run? --------------------------------
    slug_in_force, resolution = None, 'shape only'
    try:
        sources = _pr.load_config(str(ROOT))
        res = _pr.resolve(sources)
        if res['missing']:
            gone = ', '.join(m['name'] for m in res['missing'])
            resolution = f'shape only -- source(s) unreachable this run: {gone}'
        else:
            in_force = set(res['practices'])
            slug_in_force = in_force.__contains__
            resolution = f'resolved against {len(sources)} source(s)'
    except Exception as e:                                # noqa: BLE001
        resolution = f'shape only -- sources unresolvable ({type(e).__name__}: {e})'

    # --- 1. every practice file in every source this repo owns -------------
    violations, scanned = [], 0
    dirs = [ROOT / 'practices']
    local = ROOT / 'local' / 'practices'
    if local.is_dir():
        dirs.append(local)
    for d in dirs:
        for f in sorted(d.glob('*.md')):
            try:
                fm, sections = sp._read_practice_file(f)
            except sp.PracticeFileError:
                continue
            scanned += 1
            v = _bv.status_contract_violation(fm, sections, slug_in_force)
            if v:
                violations.append(f"{f.relative_to(ROOT)}: {v}")
    check(f'status contract holds for every practice in this repo '
          f'({scanned} scanned, {resolution})',
          not violations, '; '.join(violations[:8]))

    # --- 2. the contract actually refuses each way of getting it wrong -----
    # BestPractice's own catalogue is 100% active, so without these the check
    # above passes vacuously and would go on passing if the validator were
    # gutted. Each case is a rule from the table in this docstring.
    def fm_of(status, in_force_at=None):
        d = {'status': status}
        if in_force_at is not None:
            d['in_force_at'] = in_force_at
        return d

    story = {'story': 'It stopped mattering when we dropped the tool.'}
    live = {'header-caps'}.__contains__
    cases = [
        ('an active practice with a forwarding address is contradictory',
         _bv.status_contract_violation(fm_of('active', 'header-caps')) is not None),
        ('an ordinary active practice is clean',
         _bv.status_contract_violation(fm_of('active')) is None),
        ('deduplicated with no in_force_at is refused -- this is exactly the '
         '"dropped and forgotten" case that used to be indistinguishable',
         _bv.status_contract_violation(fm_of('deduplicated')) is not None),
        ('deduplicated pointing at a slug that IS in force is accepted',
         _bv.status_contract_violation(fm_of('deduplicated', 'header-caps'),
                                       slug_in_force=live) is None),
        ('deduplicated pointing at a slug that is NOT in force is refused -- '
         'a surviving copy that is itself gone is not a surviving copy',
         _bv.status_contract_violation(fm_of('deduplicated', 'deep-check'),
                                       slug_in_force=live) is not None),
        ('deduplicated with in_force_at: engine is accepted -- the successor '
         'is code, not a slug',
         _bv.status_contract_violation(fm_of('deduplicated', 'engine'),
                                       slug_in_force=live) is None),
        ('deduplicated with in_force_at: none is refused -- in force nowhere '
         'is retirement, and needs retirement\'s evidence',
         _bv.status_contract_violation(fm_of('deduplicated', 'none')) is not None),
        ('retired pointing at a live slug is refused -- if the rule survives '
         'there, it was deduplicated',
         _bv.status_contract_violation(fm_of('retired', 'header-caps'), story,
                                       slug_in_force=live) is not None),
        ('retired with in_force_at: none and a real Story is accepted',
         _bv.status_contract_violation(fm_of('retired', 'none'), story) is None),
        ('retired with an empty Story is refused -- the one status no '
         'mechanism can verify must say why in prose',
         _bv.status_contract_violation(fm_of('retired', 'none'), {'story': ''})
         is not None),
        ('an unrecognized status is reported rather than waved through',
         _bv.status_contract_violation(fm_of('superseded', 'header-caps'))
         is not None),
        ('...and is NOT in force, so an unknown status fails closed',
         not _bv.is_in_force(fm_of('superseded'))),
    ]
    bad = [n for n, ok in cases if not ok]
    check(f'the status contract refuses each way of getting it wrong '
          f'({len(cases)} stated cases)', not bad, '; '.join(bad))

    # --- 3. the new word is wired to the FILTER, not just to the validator --
    # A status can be spelled correctly in the spec, validated correctly here,
    # and still be loaded into every session if the loader's own predicate
    # never learned it. That is the shape of the original defect, so it gets
    # its own end-to-end case rather than being assumed from case 2.
    tmp = pathlib.Path(tempfile.mkdtemp(prefix='precedent-dedup-'))
    try:
        (tmp / 'practices').mkdir()
        src = ROOT / 'practices'
        (tmp / 'practices' / 'repo-is-memory.md').write_text(
            (src / 'repo-is-memory.md').read_text(encoding='utf-8'), encoding='utf-8')
        dedup = (src / 'verify-postcondition.md').read_text(encoding='utf-8')
        dedup = re.sub(r'^status:(\s+)active$', r'status:\1deduplicated', dedup,
                       count=1, flags=re.M)
        dedup = re.sub(r'^in_force_at: null$', 'in_force_at: repo-is-memory',
                       dedup, count=1, flags=re.M)
        if 'deduplicated' not in dedup or 'in_force_at: repo-is-memory' not in dedup:
            raise RuntimeError('fixture did not actually become deduplicated')
        (tmp / 'practices' / 'verify-postcondition.md').write_text(dedup, encoding='utf-8')
        (tmp / 'AGENTS.md').write_text(
            '<!-- BEGIN GENERATED: precedent-loader -->\n<!-- END GENERATED -->\n',
            encoding='utf-8')
        r = subprocess.run(
            [sys.executable, str(ROOT / 'tools' / 'build_views.py'),
             '--repo', str(tmp), '--agents-only'], capture_output=True, text=True)
        rendered = (tmp / 'AGENTS.md').read_text(encoding='utf-8')
        e2e = [
            ('a deduplicated practice is absent from the generated loader block',
             r.returncode == 0 and 'verify-postcondition' not in rendered),
            ('the active practice beside it is still emitted',
             'repo-is-memory' in rendered),
            ('the drop is announced by status name, not silently',
             'verify-postcondition' in r.stderr and 'deduplicated' in r.stderr),
        ]
        # ...and `precedent show` MARKS it rather than refusing, because a
        # session naming a slug explicitly is asking "what happened to this?"
        s = subprocess.run(
            [sys.executable, str(ROOT / 'tools' / 'precedent_show.py'),
             'verify-postcondition', '--repo', str(tmp)],
            capture_output=True, text=True)
        e2e += [
            ('precedent show still resolves the slug rather than refusing it',
             s.returncode == 0),
            ('...and marks it NOT IN FORCE, naming where the rule lives now',
             'NOT IN FORCE' in s.stdout and 'repo-is-memory' in s.stdout),
            ('...with the marking ABOVE the rule text, so a session that '
             'stops reading early cannot take it as current',
             'NOT IN FORCE' in s.stdout.split('\n\n')[0]),
        ]
        bad_e2e = [n for n, ok in e2e if not ok]
        check(f'the deduplicated status is honored by the loading channels, '
              f'not merely spelled correctly ({len(e2e)} stated cases)',
              not bad_e2e,
              '; '.join(bad_e2e) + f' || build_views: {r.stdout}{r.stderr} '
              f'|| show: {s.stdout}{s.stderr}')
    finally:
        shutil.rmtree(tmp, ignore_errors=True)


def check_scope_field_is_legal_and_matches_this_spec():
    """`scope:` is a real filter, and the spec's list of what carries it is
    the list, not a description of one.

    THE INCIDENT (2026-09-22). spec/PRACTICE_FORMAT.md's `scope` section
    named four practices as tagged `engine-dev`. The tree carried three,
    and not the same three: `cross-source-rollout` had been tagged on
    2026-09-15 by a classification sweep that never touched this paragraph,
    and `very-deep-check` and `full-practice-audit` were deliberately
    UNTAGGED on 2026-09-21 because each declares a standing `command:` and
    `engine-dev` withholds the practice from a consuming repo -- the
    incident `vocabulary-reaches-the-consumer` is registered for. A deep
    check read the tree against the stale paragraph, and filed a considered
    decision as silent drift: the proposal that came out of it was to
    revert both files, which `vocabulary-reaches-the-consumer` refuses.
    Measured before writing this, by making the change and running it.

    So the expensive failure was not a bad VALUE. It was a documented list
    and a tree disagreeing with nothing to notice, and the cost was a
    session's work spent proposing a revert of a one-day-old decision.

    WHAT THIS CANNOT DO, said plainly. It cannot catch a practice somebody
    MEANT to scope and did not. `scope: null` is dropped by the one null
    policy in split_practices.parse_frontmatter_fields, for every field in
    both formats, so `scope: null` and no `scope:` line are the same input
    to every consumer in the engine and nothing downstream can recover the
    difference. Authoring the list in the spec and comparing it here is the
    answer to that, and it is why part 3 below is the part that matters.
    """
    sys.path.insert(0, str(ROOT / 'tools'))
    import build_views as _bv

    cases = []

    # --- 1. every declared scope is one of the two legal values -----------
    dirs = [(ROOT / 'practices', False)]
    local = ROOT / 'local' / 'practices'
    if local.is_dir():
        dirs.append((local, True))
    scanned, tagged = 0, set()
    for d, repo_local in dirs:
        for f in sorted(d.glob('*.md')):
            try:
                fm, _sections = sp._read_practice_file(f)
            except sp.PracticeFileError:
                continue
            scanned += 1
            v = _bv.scope_violation(fm, repo_local=repo_local)
            cases.append((f'{f.relative_to(ROOT)}: scope is legal',
                          v is None, v or ''))
            if not repo_local and _bv._is_engine_dev_scoped(fm):
                tagged.add(fm.get('slug', f.stem).strip())

    # --- 2. the spec's own list, read out of the paragraph that claims it --
    # Anchored on the authored lead-in. A reworded paragraph fails HERE,
    # loudly, rather than quietly finding no links and declaring the tree
    # empty-and-agreeing -- which is the shape of vacuous pass this whole
    # check exists to stop (practice: scripts-assert-properties).
    spec = (ROOT / 'spec' / 'PRACTICE_FORMAT.md').read_text(encoding='utf-8')
    anchor = '**Tagged\n`engine-dev` today:**'
    named = None
    if anchor in spec:
        para = spec.split(anchor, 1)[1].split('\n\n', 1)[0]
        named = set(re.findall(r'\]\(\.\./practices/([a-z0-9-]+)\.md\)', para))
    cases.append(('spec/PRACTICE_FORMAT.md still carries the authored '
                  '`Tagged engine-dev today:` list this check reads',
                  bool(named), 'anchor or links not found -- reword the '
                  'paragraph and this check goes blind, so it fails instead'))

    if named:
        cases.append(('the tree\'s engine-dev practices are exactly the ones '
                      'that paragraph names', named == tagged,
                      f'spec names {sorted(named)}, tree carries '
                      f'{sorted(tagged)}'))

    # --- 3. and it refuses each way of getting it wrong --------------------
    # Without these, parts 1 and 2 pass vacuously on a clean tree and would
    # go on passing if the validator were gutted (practice:
    # checkable-gets-checked -- wire it in with a firing test).
    planted = [
        ({'slug': 'x', 'scope': 'adopter'}, False,
         'a value that is neither legal'),
        ({'slug': 'x', 'scope': 'engine_dev'}, False,
         'the underscore spelling of the legal one'),
        ({'slug': 'x', 'scope': 'any-adopter'}, False, 'the explicit default'),
        ({'slug': 'x', 'scope': 'engine-dev'}, False, 'the other legal value'),
        ({'slug': 'x'}, False, 'an absent field'),
    ]
    for fm, repo_local, what in planted:
        got = _bv.scope_violation(fm, repo_local=repo_local)
        want_violation = fm.get('scope') not in (None, 'any-adopter',
                                                 'engine-dev')
        cases.append((f'planted: {what} is '
                      f'{"refused" if want_violation else "accepted"}',
                      bool(got) == want_violation, repr(got)))

    cases.append(('planted: a repo-local practice declaring engine-dev is '
                  'flagged as redundant',
                  bool(_bv.scope_violation({'slug': 'x',
                                            'scope': 'engine-dev'},
                                           repo_local=True)), ''))
    cases.append(('planted: a repo-local practice declaring any-adopter is '
                  'not flagged -- only engine-dev is the redundant one',
                  _bv.scope_violation({'slug': 'x', 'scope': 'any-adopter'},
                                      repo_local=True) is None, ''))

    # And the list comparison itself, on a doctored spec paragraph: it must
    # report a name the tree does not carry, not shrug.
    doctored = {'routing-audit', 'a-practice-that-is-not-there'}
    cases.append(('planted: a spec list naming a practice the tree does not '
                  'carry is a mismatch', doctored != tagged, ''))

    bad = [(n, d) for n, ok, d in cases if not ok]
    return (not bad, f'{len(cases)} stated cases',
            '; '.join(f'{n}: {d}' for n, d in bad))


def check_retired_practices_leave_the_views():
    """A practice that is not in force must not be in the loader block.

    build_views.py never read `status:` at all -- not in load_practices, not
    in the loader-block build, nowhere -- so a retired practice went on being
    emitted into AGENTS.md, MAP.md and GLOSSARY.md exactly like an active
    one. precedent_resolve.py had it right and printed `not in force`; the
    two channels disagreed, and the one a session actually loads was the
    wrong one.

    BestPractice's own catalogue has no retired practice, which is precisely
    why nothing here caught it: found 2026-09-06 in a private shared set whose
    generated AGENTS.md listed all three of its retired practices, one of
    them retired that same day. So this case supplies a retired practice of
    its own rather than relying on the tree having one."""
    import tempfile, shutil
    cases = []
    tmp = pathlib.Path(tempfile.mkdtemp(prefix='precedent-retired-'))
    try:
        (tmp / 'practices').mkdir()
        src = ROOT / 'practices'
        active = (src / 'repo-is-memory.md').read_text(encoding='utf-8')
        (tmp / 'practices' / 'repo-is-memory.md').write_text(active, encoding='utf-8')
        retired = (src / 'verify-postcondition.md').read_text(encoding='utf-8')
        retired = re.sub(r'^status:(\s+)active$', r'status:\1retired', retired,
                         count=1, flags=re.M)
        if 'status:      retired' not in retired and 'status: retired' not in retired:
            raise RuntimeError('fixture did not actually become retired')
        (tmp / 'practices' / 'verify-postcondition.md').write_text(retired, encoding='utf-8')
        (tmp / 'AGENTS.md').write_text(
            '<!-- BEGIN GENERATED: precedent-loader -->\n<!-- END GENERATED -->\n',
            encoding='utf-8')

        r = subprocess.run(
            [sys.executable, str(ROOT / 'tools' / 'build_views.py'),
             '--repo', str(tmp), '--agents-only'],
            capture_output=True, text=True)
        rendered = (tmp / 'AGENTS.md').read_text(encoding='utf-8')
        cases.append(('a retired practice is absent from the generated loader '
                      'block -- retirement is not cosmetic',
                      r.returncode == 0 and 'verify-postcondition' not in rendered,
                      r.stdout + r.stderr + '\n---\n' + rendered))
        cases.append(('an active practice in the same directory is still '
                      'emitted -- the filter drops the retired one, not the '
                      'catalogue', 'repo-is-memory' in rendered, rendered))
        cases.append(('the drop is announced, not silent -- a retirement that '
                      'vanishes without a word is the same failure one size '
                      'down',
                      'verify-postcondition' in r.stderr and 'retired' in r.stderr,
                      r.stdout + r.stderr))

        sys.path.insert(0, str(ROOT / 'tools'))
        import build_views as _bv
        import precedent_resolve as _pr
        cases.append(('the loader and the resolver share one definition of '
                      '"in force", so they cannot drift apart again',
                      _pr.IN_FORCE_STATUS is _bv.IN_FORCE_STATUS,
                      f'{_pr.IN_FORCE_STATUS!r} vs {_bv.IN_FORCE_STATUS!r}'))
    finally:
        shutil.rmtree(tmp, ignore_errors=True)

    bad = [(c[0], c[2]) for c in cases if not c[1]]
    check(f'a retired practice leaves the generated views ({len(cases)} '
          f'stated cases)', not bad,
          '; '.join(f"{n} -- {d[:600]}" for n, d in bad))


def check_resident_subset(files):
    # Phase 1's always-loaded set was every practice, unconditionally (no
    # tier existed yet). The post-migration resident set must be a STRICT
    # subset of that -- i.e. fewer than all of them, and within the token
    # budget build_views.py enforces at build time (a build over budget
    # already exits nonzero there; this check additionally confirms the
    # curation actually happened rather than defaulting everything resident).
    resident = [stem for stem, (fm, _s, _f) in files.items() if fm.get('tier') == 'resident']
    ok = 0 < len(resident) < len(files)
    check('resident subset (curated resident tier is a strict, non-empty subset of all practices)',
          ok, f"{len(resident)} of {len(files)} practices are resident")


def check_behavioral_replay():
    # Runs tools/behavioral_replay.py for real (not a canned number). It
    # prints a "REPLAY_STATUS: OK|MISMATCH|DEGRADED" marker line: OK means
    # precedent_paths.py's output matched an independent re-derivation on
    # every replayed commit (the mechanical channel has no bugs against real
    # history); MISMATCH is a real defect; DEGRADED means this clone doesn't
    # have enough commit history for a meaningful replay (a fresh shallow
    # clone, most commonly) -- an environment precondition, not a loader
    # defect, so it is reported as not-yet-applicable rather than pass or
    # fail. The script's own stdout states plainly what a PASS here does and
    # does not prove about the plan's premise (see its docstring); this
    # check only gates on the part of that which is a pass/fail fact.
    result = subprocess.run([sys.executable, str(ROOT / 'tools' / 'behavioral_replay.py')],
                             capture_output=True, text=True)
    status_line = next((l for l in result.stdout.splitlines() if l.startswith('REPLAY_STATUS:')), '')
    detail = (result.stdout + result.stderr).strip()
    name = ('behavioral replay (path-triggered channel matches an independent re-derivation '
            'across this repo\'s own commit history; see `python3 tools/behavioral_replay.py` '
            'for the full measured report, including what it does NOT prove)')
    if 'DEGRADED' in status_line:
        not_applicable(name, status_line.split('REPLAY_STATUS: ', 1)[-1])
    elif result.returncode == 0 and 'OK' in status_line:
        check(name, True)
    else:
        check(name, False, detail.splitlines()[-1] if detail else 'no REPLAY_STATUS line printed')


HARNESS_ROTATION_BUCKETS = 10

def _deep_assertion_slugs():
    """-> slugs whose planted output a later assertion reads back.

    Read out of this file's own text. A case that is skipped must
    not leave `planted['<slug>']` missing for code that indexes it
    directly, and the set of such slugs is exactly what a regex
    over the source can answer without anyone maintaining a list.
    """
    try:
        src = pathlib.Path(__file__).read_text(encoding='utf-8')
    except OSError:               # practice: fail-gracefully
        return None               # unknown -> caller runs everything
    found = set()
    for m in re.finditer(r"planted\['([A-Za-z0-9-]+)'\]", src):
        found.add(m.group(1)[:-len('-clean')]
                  if m.group(1).endswith('-clean') else m.group(1))
    return found

# THE TWO SHAPES CI RUNS, and the one a local session never does.
# .github/workflows/deep-check.yml splits this suite across two jobs on
# these variables, because check_precedent_check_fires is about half the
# runtime (spec/VERIFY_HARNESS_PERFORMANCE.md). A plain local run sets
# neither, so the whole filter path -- every behaviour that depends on a
# check being replaced by a stand-in -- is code no local run executes.
#
# That gap hid a crash on 2026-09-21: the full local suite reported
# 244 passed, 0 failed while BOTH sharded CI jobs died before their first
# verdict (gotcha-2026-09-21-a-green-local-verify-harness-run-does-not-mean-
# green-ci). `--as-ci` is how a session runs what CI will run, in one
# command, and check_as_ci_shards_match_the_workflow below keeps this table
# from drifting away from the workflow it mirrors.
CI_SHARDS = (
    ('heavy -- check_precedent_check_fires only, every planted case',
     {'PRECEDENT_CHECK_ONLY': 'check_precedent_check_fires',
      'PRECEDENT_HARNESS_ALL': '1'}),
    ('rest -- everything except that one',
     {'PRECEDENT_CHECK_SKIP': 'check_precedent_check_fires'}),
)


# The line prefixes that start a verdict (check() and not_applicable()); a
# FAIL's text runs until the next one.
_VERDICT_STARTS = ('PASS:', 'FAIL:', 'N/A:')


def _fail_blocks(stdout, cap=40):
    """-> [[line, ...]] each FAIL: verdict with the lines of its failure text
    that follow it, up to the next verdict, at most `cap` lines each.
    A failure text that runs over several lines kept only its first until
    2026-09-30: "an update that deletes a vendored file upstream dropped
    ends DONE" failed once in a full run, with its cause cut off, then
    passed four times in a row and the cause was never found."""
    blocks, cur = [], None
    for line in stdout.splitlines():
        if line.startswith(_VERDICT_STARTS):
            cur = [line] if line.startswith('FAIL:') else None
            if cur is not None:
                blocks.append(cur)
        elif cur is not None:
            if len(cur) < cap:
                cur.append(line)
            elif len(cur) == cap:
                cur.append('... (cut at 40 lines)')
    return blocks


def _shard_failure_detail(proc, tail_lines=20):
    """-> [str] what a failed shard says about WHY: every `FAIL:` verdict it
    printed, then the last `tail_lines` lines of its stderr. Until
    2026-09-28 a failed shard printed `SHARD FAILED (exit 1)` and nothing
    else, so the reason -- a named failing case, or a traceback that killed
    the shard before its first verdict -- meant rerunning four minutes of
    suite to find out."""
    out = []
    fails = _fail_blocks(proc.stdout or '')
    if fails:
        out.append(f'  {len(fails)} failing case(s):')
        for block in fails:
            out += [f'    {l}' for l in block]
    err = [l for l in (proc.stderr or '').splitlines() if l.strip()]
    if err:
        out.append(f'  last {min(tail_lines, len(err))} line(s) of its stderr:')
        out += [f'    {l}' for l in err[-tail_lines:]]
    if not out:
        out.append('  it printed no FAIL: line and nothing on stderr')
    return out


def _as_ci_runs(jobs, names=None):
    """-> [(label, env_extra)]: the processes `--as-ci` starts side by side.

    CI_SHARDS as they are, except that the one shard run by SKIP (CI's
    "rest") is cut into enough parts to fill `jobs` processes. Each part
    still runs by PRECEDENT_CHECK_SKIP -- the shard's own filter path, the
    half a plain local run never executes -- skipping the heavy check and
    every name the other parts take. Names are dealt round-robin in sorted
    order, so every check runs in exactly one process.

    Safe to split because no check calls another and none takes another's
    result (both verified over the whole file, 2026-09-30): a check sees the
    same arguments in a part as in the whole shard."""
    if names is None:
        names = sorted(n for n, v in globals().items()
                       if n.startswith('check_') and callable(v))
    skip_shards = [s for s in CI_SHARDS if 'PRECEDENT_CHECK_SKIP' in s[1]]
    parts = max(1, jobs - (len(CI_SHARDS) - len(skip_shards)))
    if len(skip_shards) != 1 or parts == 1:
        return list(CI_SHARDS)
    label, env_extra = skip_shards[0]
    base_skip = set(env_extra['PRECEDENT_CHECK_SKIP'].split(','))
    rest = [n for n in names if n not in base_skip]
    dealt = [rest[i::parts] for i in range(parts)]
    out = []
    for s in CI_SHARDS:
        if s is not skip_shards[0]:
            out.append(s)
            continue
        for i, mine in enumerate(dealt):
            others = [n for n in rest if n not in set(mine)]
            out.append((f'{label} (part {i + 1} of {parts}, {len(mine)} checks)',
                        {**env_extra, 'PRECEDENT_CHECK_SKIP':
                         ','.join(sorted(base_skip) + others)}))
    return out


def _bare_all_runs_in_parallel(argv, environ):
    """-> True when this invocation is a bare `--all`, which run_as_ci runs
    across the cores: no filter of its own, and not asked to stay serial."""
    return ('--all' in argv
            and not environ.get('PRECEDENT_CHECK_ONLY')
            and not environ.get('PRECEDENT_CHECK_SKIP')
            and environ.get('PRECEDENT_HARNESS_SERIAL') != '1')


def check_bare_all_runs_across_the_cores():
    """A bare `--all` is dispatched to run_as_ci with every planted case
    (2026-10-06: one process took about 31 minutes where the same set side
    by side takes about 11), and a shard, a filtered run, or an explicit
    serial run is not -- so nothing recurses and profiling stays possible."""
    import inspect
    cases = [
        ('a bare --all runs in parallel',
         _bare_all_runs_in_parallel(['--all'], {})),
        ('a shard process (no --all) does not',
         not _bare_all_runs_in_parallel([], {'PRECEDENT_HARNESS_ALL': '1'})),
        ('--all with PRECEDENT_CHECK_ONLY keeps its filter, in one process',
         not _bare_all_runs_in_parallel(['--all'],
                                        {'PRECEDENT_CHECK_ONLY': 'check_x'})),
        ('--all with PRECEDENT_CHECK_SKIP keeps its filter, in one process',
         not _bare_all_runs_in_parallel(['--all'],
                                        {'PRECEDENT_CHECK_SKIP': 'check_x'})),
        ('PRECEDENT_HARNESS_SERIAL=1 keeps the one-process run',
         not _bare_all_runs_in_parallel(['--all'],
                                        {'PRECEDENT_HARNESS_SERIAL': '1'})),
    ]
    src = inspect.getsource(run_as_ci)
    cases.append(('every_case gives each process PRECEDENT_HARNESS_ALL=1',
                  "env['PRECEDENT_HARNESS_ALL'] = '1'" in src
                  and 'if every_case:' in src))
    main_src = pathlib.Path(__file__).read_text(encoding='utf-8')
    cases.append(('the entry point dispatches it',
                  'sys.exit(run_as_ci(every_case=True))' in main_src))
    failed = [n for n, ok in cases if not ok]
    check(f'a bare --all runs across the cores ({len(cases)} stated cases)',
          not failed, '; '.join(failed))


def run_as_ci(every_case=False):
    """-> exit status. Run this suite the two ways CI runs it, side by side.

    every_case: give every process PRECEDENT_HARNESS_ALL=1, which is what a
    bare `--all` asks for (see the bottom of this file).

    NOT the same work twice: the shards PARTITION the suite. Until
    2026-09-30 they ran one after the other, and the rest shard ran its
    three hundred-odd checks on one core, so a four-core session paid
    about sixteen minutes, mostly waiting (a landing check ran five times
    in one afternoon). Now every shard starts at once, and the rest shard
    is dealt into parts to fill PRECEDENT_AS_CI_JOBS processes (default:
    the machine's cores, at most four) -- _as_ci_runs() says how.
    PRECEDENT_AS_CI_JOBS=1 is the old serial run.

    IT REPRODUCES CI'S COMMAND SHAPE, NOT CI'S ENVIRONMENT, and the
    difference is worth stating because over-promising here would repeat
    the exact failure this exists to fix. A local session resolves private
    practice sources that CI has no credential for, so a check keyed to one
    of them can fail here and pass there -- and the reverse, a check that
    needs something only CI has, would fail here for the same reason.
    Green under --as-ci means the shard SHAPE is not what breaks; it does
    not mean CI will be green."""
    import tempfile
    try:
        jobs = int(os.environ.get('PRECEDENT_AS_CI_JOBS') or 0)
    except ValueError:
        jobs = 0
    jobs = jobs or min(4, os.cpu_count() or 1)
    runs = _as_ci_runs(jobs)
    tmp = pathlib.Path(tempfile.mkdtemp(prefix='precedent-as-ci-'))
    started = []
    t0 = time.monotonic()
    for i, (label, env_extra) in enumerate(runs):
        env = dict(os.environ)
        # Each shard gets a clean slate of BOTH variables, so a session that
        # already has one exported does not silently skew a shard.
        env.pop('PRECEDENT_CHECK_ONLY', None)
        env.pop('PRECEDENT_CHECK_SKIP', None)
        env.pop('PRECEDENT_HARNESS_ALL', None)
        env.update(env_extra)
        if every_case:
            env['PRECEDENT_HARNESS_ALL'] = '1'
        # Files, not pipes: a shard that fills a pipe nobody reads yet stalls.
        out, err = open(tmp / f'{i}.out', 'w+'), open(tmp / f'{i}.err', 'w+')
        proc = subprocess.Popen([sys.executable, str(pathlib.Path(__file__))],
                                env=env, stdout=out, stderr=err, text=True)
        started.append((label, proc, out, err))
    print(f'--as-ci: {len(started)} shard process(es) started side by side',
          flush=True)
    while True:
        running = [p for _l, p, _o, _e in started if p.poll() is None]
        if not running:
            break
        try:
            running[0].wait(timeout=30)
        except subprocess.TimeoutExpired:
            print(f'  -- {len(started) - len(running)} of {len(started)} shard '
                  f'process(es) done, {time.monotonic() - t0:.0f}s elapsed',
                  flush=True)
    failed = []
    for label, proc, out, err in started:
        out.seek(0)
        err.seek(0)
        done = subprocess.CompletedProcess(proc.args, proc.returncode,
                                           out.read(), err.read())
        out.close()
        err.close()
        print(f'\n=== shard: {label} ===', flush=True)
        # 'planted cases ran' is the heavy shard's statement of what it
        # selected; the very deep check quotes it as evidence that every
        # case ran.
        tail = [l for l in done.stdout.splitlines()
                if 'passed,' in l or l.startswith('  - ')
                or 'planted cases ran' in l]
        for line in tail[-12:]:
            print(line)
        if done.returncode != 0:
            failed.append(label)
            print(f'  SHARD FAILED (exit {done.returncode})')
            for line in _shard_failure_detail(done):
                print(line)
    shutil.rmtree(tmp, ignore_errors=True)
    wall = time.monotonic() - t0
    if failed:
        print(f'\n--as-ci: {len(failed)} of {len(started)} shard process(es) '
              f'failed in {wall:.0f}s: {"; ".join(failed)}')
        return 1
    print(f'\n--as-ci: all {len(started)} shard process(es) green in '
          f'{wall:.0f}s -- this is what CI will run.')
    return 0


# What GitHub's runner does not have, and a session's machine does. Unset in
# the isolated run; see run_as_ci_isolated().
ISOLATION_UNSET = ('PRECEDENT_GIT_TOKEN', 'PRECEDENT_SOURCE_BASE_URL',
                   'PRECEDENT_INDIVIDUAL_REPO', 'CLAUDE_PROJECT_DIR')


def _isolated_env(base, home):
    """-> the environment the isolated run gives the harness: `base` with
    every PRECEDENT_* and GIT_* variable and ISOLATION_UNSET removed, $HOME
    an empty directory, no user-level config, the runner's UTC clock, and
    git refusing every transport but a local file. The last one is not
    GitHub's -- its runner has a network -- but a self-heal that clones a
    source from the network would put the missing sibling right back, and
    the run would quietly stop matching the runner it stands in for."""
    env = {k: v for k, v in base.items()
           if not k.startswith(('PRECEDENT_', 'GIT_')) and k not in ISOLATION_UNSET}
    env.update(HOME=str(home), TZ='UTC',
               PRECEDENT_USER_CONFIG=str(pathlib.Path(home) / '.no-user-config.json'),
               GIT_ALLOW_PROTOCOL='file', GIT_TERMINAL_PROMPT='0',
               GIT_CONFIG_NOSYSTEM='1')
    return env


def _new_entries(parent, before):
    """-> sorted names in `parent` that were not in `before`."""
    return sorted(set(p.name for p in pathlib.Path(parent).iterdir()) - set(before))


def _carry_uncommitted(src, dst):
    """-> how many uncommitted paths of `src` were written into the clone
    `dst` (0 when there were none), or None when they could not be.

    The copy used to be committed work only, while every other step of the
    full check reads the working tree. Run before a commit, the harness
    then judged the commit BEFORE the change and the rest judged the
    change: on 2026-10-01 a new check with no planted case (whats-new) went
    green in the full check and was refused by the merge gate's quick one,
    which reads the files. Tracked edits travel as a binary diff against
    HEAD; untracked files that are not ignored are copied as they are."""
    import shutil
    diff = subprocess.run(['git', '-C', str(src), 'diff', 'HEAD', '--binary'],
                          capture_output=True)
    if diff.returncode != 0:
        return None
    n = 0
    if diff.stdout.strip():
        r = subprocess.run(['git', '-C', str(dst), 'apply', '--binary',
                            '--whitespace=nowarn', '-'], input=diff.stdout,
                           capture_output=True)
        if r.returncode != 0:
            return None
        names = subprocess.run(['git', '-C', str(src), 'diff', 'HEAD',
                                '--name-only'], capture_output=True, text=True)
        n += len(names.stdout.split())
    extra = subprocess.run(['git', '-C', str(src), 'ls-files', '--others',
                            '--exclude-standard', '-z'], capture_output=True)
    for rel in [x for x in extra.stdout.decode('utf-8', 'replace').split('\0') if x]:
        target = pathlib.Path(dst) / rel
        target.parent.mkdir(parents=True, exist_ok=True)
        try:
            shutil.copy2(pathlib.Path(src) / rel, target)
        except OSError:
            return None
        n += 1
    return n


def run_as_ci_isolated():
    """-> exit status. --as-ci, from a copy of this commit laid out the way
    GitHub's runner lays it out, then the not-applicable slice again here.

    WHY. On 2026-09-29 the full local check passed and GitHub's deep-check
    failed: build_views sized a set's occasion cap from the universal source
    cloned BESIDE it, and the runner has no sibling clones, so universal
    measured 0. --as-ci reproduces CI's command shape and never its
    environment (run_as_ci's docstring); this is the environment half.

    THE COPY. A clone of HEAD in a temporary directory whose parent holds
    nothing else, with this checkout's remote-tracking refs and origin URL
    (actions/checkout's fetch-depth: 0 gives the runner every branch), run
    under _isolated_env(): an empty $HOME, no user config, no source token,
    UTC. The checkout's uncommitted changes are carried into it
    (_carry_uncommitted), so it judges what the rest of the check judges;
    a commit pushed later is what the runner checks out.

    THE SECOND RUN. A test that needs what only this machine has -- a
    private source, a sibling clone -- goes not-applicable in the copy.
    Those functions (not_applicable() records them) run once more here, in
    the ordinary environment, so the pair covers everything the plain
    --as-ci covered, plus what the runner would see.

    AFTERWARDS the copy's parent must still hold only the copy: anything
    new there is a sibling some step fetched, and the run is reported as
    no longer isolated rather than passed."""
    import shutil, tempfile
    work = pathlib.Path(tempfile.mkdtemp(prefix='precedent-isolated-'))
    t0 = time.monotonic()
    try:
        parent, home = work / 'work', work / 'home'
        parent.mkdir()
        home.mkdir()
        repo = parent / ROOT.name
        r = subprocess.run(['git', 'clone', '--quiet', '--no-checkout', str(ROOT),
                            str(repo)], capture_output=True, text=True)
        if r.returncode != 0:
            print(f'--as-ci --isolated: could not copy this checkout: '
                  f'{r.stderr.strip()}')
            return 1
        head = subprocess.run(['git', '-C', str(ROOT), 'rev-parse', 'HEAD'],
                              capture_output=True, text=True).stdout.strip()
        url = subprocess.run(['git', '-C', str(ROOT), 'remote', 'get-url',
                              'origin'], capture_output=True, text=True).stdout.strip()
        for args in (['fetch', '--quiet', str(ROOT),
                      '+refs/remotes/origin/*:refs/remotes/origin/*'],
                     ['checkout', '--quiet', '--detach', head]):
            subprocess.run(['git', '-C', str(repo), *args], capture_output=True)
        if url:
            subprocess.run(['git', '-C', str(repo), 'remote', 'set-url',
                            'origin', url], capture_output=True)
        carried = _carry_uncommitted(ROOT, repo)
        if carried is None:
            print('--as-ci --isolated: could not carry this checkout\'s '
                  'uncommitted changes into the copy, so it would test the '
                  'last commit instead of them. Commit, then run it again.')
            return 1
        before = [p.name for p in parent.iterdir()]
        na_file = work / 'not-applicable.txt'
        env = _isolated_env(os.environ, home)
        env['PRECEDENT_NA_FUNCTIONS_FILE'] = str(na_file)
        print(f'=== isolated: {repo} at {head[:12]}'
              + (f' plus {carried} uncommitted path(s) from this checkout'
                 if carried else '')
              + ' (no siblings, empty $HOME, no source token, UTC) ===',
              flush=True)
        rc = subprocess.run([sys.executable, 'tools/verify_harness.py',
                             '--as-ci'], cwd=repo, env=env).returncode
        grown = _new_entries(parent, before)
        t1 = time.monotonic()
        slice_ = sorted(set(na_file.read_text(encoding='utf-8').split())
                        if na_file.is_file() else set())
        print(f'\n--as-ci --isolated: {"green" if rc == 0 else "FAILED"} in '
              f'{(t1 - t0) / 60:.1f} min; {len(slice_)} function(s) were not '
              f'applicable there' + (f': {", ".join(slice_)}' if slice_ else ''),
              flush=True)
        if grown:
            print(f'--as-ci --isolated: NOT ISOLATED -- the run added '
                  f'{", ".join(grown)} beside the copy, so it no longer '
                  f'matches a runner with no sibling clones. Find the step '
                  f'that fetched it and stop it fetching there.')
            return 1
        rc2 = 0
        if slice_:
            env2 = dict(os.environ)
            for k in ('PRECEDENT_CHECK_SKIP', 'PRECEDENT_NA_FUNCTIONS_FILE'):
                env2.pop(k, None)
            env2.update(PRECEDENT_CHECK_ONLY=','.join(slice_),
                        PRECEDENT_HARNESS_ALL='1')
            print('\n=== here, the not-applicable slice ===', flush=True)
            rc2 = subprocess.run([sys.executable, str(pathlib.Path(__file__))],
                                 env=env2).returncode
            print(f'--as-ci --isolated: the slice was '
                  f'{"green" if rc2 == 0 else "FAILED"} in '
                  f'{(time.monotonic() - t1) / 60:.1f} min', flush=True)
        return 1 if rc or rc2 else 0
    finally:
        shutil.rmtree(work, ignore_errors=True)


def check_isolated_copy_carries_uncommitted_changes():
    """The isolated harness judges what the rest of the full check judges.

    2026-10-01: a full check run before a commit went green while the
    commit it was about to make added a check with no planted case. The
    isolated copy was a clone of HEAD, so the harness judged the commit
    before the change; reproduced on that commit, committed, the same run
    fails with "untested: ['whats-new']". _carry_uncommitted now writes the
    checkout's uncommitted state into the copy. The rule under test: a
    tracked edit, a deletion and an untracked file reach the copy, an
    ignored file does not, and a clean checkout carries nothing. Driven
    against a throwaway repository (a whole planted --as-ci run costs
    about nine minutes)."""
    import tempfile
    cases = []
    with tempfile.TemporaryDirectory() as td:
        tmp = pathlib.Path(td)
        env = _stale_ref_fixture_env(tmp)
        src, dst = tmp / 'src', tmp / 'dst'

        def git(repo, *a):
            return subprocess.run(['git', '-C', str(repo), *a],
                                  capture_output=True, text=True, env=env)
        subprocess.run(['git', 'init', '-q', '-b', 'main', str(src)],
                       capture_output=True, env=env)
        (src / 'kept.py').write_text('A = 1\n', encoding='utf-8')
        (src / 'gone.py').write_text('B = 1\n', encoding='utf-8')
        (src / '.gitignore').write_text('scratch/\n', encoding='utf-8')
        git(src, 'add', '-A')
        git(src, 'commit', '-qm', 'base')

        def copy():
            import shutil
            shutil.rmtree(dst, ignore_errors=True)
            subprocess.run(['git', 'clone', '-q', str(src), str(dst)],
                           capture_output=True, env=env)
            return _carry_uncommitted(src, dst)
        cases.append(('a clean checkout carries nothing', copy() == 0, ''))
        (src / 'kept.py').write_text('A = 2\n', encoding='utf-8')
        (src / 'gone.py').unlink()
        (src / 'new_check.py').write_text('C = 3\n', encoding='utf-8')
        (src / 'scratch').mkdir()
        (src / 'scratch' / 'notes.txt').write_text('x', encoding='utf-8')
        n = copy()
        cases.append(('the edit, the deletion and the new file are counted',
                      n == 3, repr(n)))
        cases.append(('the tracked edit reaches the copy',
                      (dst / 'kept.py').read_text(encoding='utf-8') == 'A = 2\n', ''))
        cases.append(('the deletion reaches the copy',
                      not (dst / 'gone.py').exists(), ''))
        cases.append(('the untracked file reaches the copy',
                      (dst / 'new_check.py').is_file(), ''))
        cases.append(('an ignored file does not',
                      not (dst / 'scratch').exists(), ''))
    bad = [(n_, d) for n_, ok, d in cases if not ok]
    check(f'the isolated harness copy carries the checkout\'s uncommitted '
          f'changes ({len(cases)} stated cases)', not bad,
          '; '.join(f'{n_}: {d}' for n_, d in bad))


def check_isolated_run_matches_the_runner():
    """_isolated_env() and _new_entries(), which decide whether the isolated
    run looks like GitHub's runner and whether it stayed that way. Pure
    functions, so this is cheap: the run itself is minutes, and is what the
    full check at staging executes."""
    import tempfile
    base = {'PATH': '/bin', 'HOME': '/root', 'TZ': 'America/Argentina/Buenos_Aires',
            'PRECEDENT_GIT_TOKEN': 't', 'PRECEDENT_SOURCE_BASE_URL': 'u',
            'PRECEDENT_INDIVIDUAL_REPO': 'r', 'PRECEDENT_COMMIT_NAME': 'n',
            'PRECEDENT_CHECK_ONLY': 'x', 'GIT_AUTHOR_NAME': 'a',
            'CLAUDE_PROJECT_DIR': '/p'}
    env = _isolated_env(base, '/tmp/empty-home')
    cases = [
        ('no source token, base URL or individual repo',
         not {'PRECEDENT_GIT_TOKEN', 'PRECEDENT_SOURCE_BASE_URL',
              'PRECEDENT_INDIVIDUAL_REPO'} & set(env)),
        ('no PRECEDENT_* or GIT_* variable leaks through except the ones set',
         {k for k in env if k.startswith(('PRECEDENT_', 'GIT_'))} ==
         {'PRECEDENT_USER_CONFIG', 'GIT_ALLOW_PROTOCOL', 'GIT_TERMINAL_PROMPT',
          'GIT_CONFIG_NOSYSTEM'}),
        ('an empty $HOME and a user config that does not exist',
         env['HOME'] == '/tmp/empty-home' and
         env['PRECEDENT_USER_CONFIG'].startswith('/tmp/empty-home/')),
        ('the runner\'s clock, UTC', env['TZ'] == 'UTC'),
        ('git may not fetch over a network', env['GIT_ALLOW_PROTOCOL'] == 'file'),
        ('PATH is kept', env['PATH'] == '/bin'),
        ('the base environment is not changed', base['TZ'] != 'UTC'),
    ]
    with tempfile.TemporaryDirectory() as td:
        (pathlib.Path(td) / 'BestPractice').mkdir()
        before = ['BestPractice']
        quiet = _new_entries(td, before)
        (pathlib.Path(td) / 'BestPractice-clone').mkdir()
        cases += [('nothing new beside the copy reads as isolated', quiet == []),
                  ('a sibling that appeared is named',
                   _new_entries(td, before) == ['BestPractice-clone'])]
    failed = [n for n, ok in cases if not ok]
    check(f'the isolated --as-ci run looks like GitHub\'s runner '
          f'({len(cases)} stated cases)', not failed, '; '.join(failed))


def check_as_ci_shards_match_the_workflow():
    """CI_SHARDS above must be what .github/workflows/deep-check.yml sets.

    A local command that claims to run "what CI runs" and has drifted from
    the workflow is worse than not having one: it returns green with
    authority. So the table is asserted against the workflow's own env
    blocks rather than trusted."""
    wf = ROOT / '.github' / 'workflows' / 'deep-check.yml'
    if not wf.is_file():
        not_applicable('the --as-ci shard table matches the workflow',
                       'no .github/workflows/deep-check.yml here')
        return
    body = wf.read_text(encoding='utf-8')
    cases = []
    for label, env_extra in CI_SHARDS:
        for var, value in env_extra.items():
            # The workflow writes `VAR: value` or `VAR: "value"`.
            present = (f'{var}: {value}' in body
                       or f'{var}: "{value}"' in body)
            cases.append((f'{var}={value} ({label.split(" --")[0]})',
                          present, ''))
    # And the other direction: a shard variable the workflow sets that this
    # table does not know about would mean CI runs a shape --as-ci cannot.
    declared = {v for _l, e in CI_SHARDS for v in e}
    for var in ('PRECEDENT_CHECK_ONLY', 'PRECEDENT_CHECK_SKIP'):
        cases.append((f'{var} appears in the workflow and in CI_SHARDS',
                      (var in body) == (var in declared), ''))
    bad = [c[0] for c in cases if not c[1]]
    check(f'the --as-ci shard table matches the workflow '
          f'({len(cases)} stated cases)',
          not bad, '; '.join(bad))


def _selected_case_slugs(all_slugs, touched=None, count=None, forced=None):
    """-> (set of slugs to run, one-line reason). Never raises: a
    selector that cannot decide runs everything, because the failure
    of a scheduler must not be silently less coverage.

    `touched` and `count` are normally read from git. They are parameters
    so this is testable without a fixture repository: a scheduler whose
    behaviour can only be observed by running the thing it schedules is a
    scheduler nobody can check, and this one decides how much of the push
    gate actually executes.

    `forced` is the same argument one level up, and it was added the day it
    bit. It normally reads the process's own `--all` / PRECEDENT_HARNESS_ALL,
    which is right for a real run and WRONG for the self-test below: that
    test asserts the selector NARROWS on an ordinary docs change, so on a
    run invoked with --all it was measuring the flag instead of the rule and
    failing 72/72. Found 2026-09-21, by the very deep check's own new step 2
    -- which prescribes --all, ran it, and turned the suite red on its first
    outing. A scheduler that cannot be exercised in the state it is not
    currently in is the same untestable scheduler this signature already
    exists to avoid."""
    if forced is None:
        forced = ('--all' in sys.argv
                  or os.environ.get('PRECEDENT_HARNESS_ALL') == '1')
    if forced:
        return set(all_slugs), 'all (--all / PRECEDENT_HARNESS_ALL)'
    pinned = _deep_assertion_slugs()
    if pinned is None:
        return set(all_slugs), 'all (could not read this file to find deep assertions)'
    if touched is not None and count is not None:
        touched, count = set(touched), int(count)
    else:
        try:
            base = subprocess.run(
                ['git', 'merge-base', 'HEAD', 'origin/HEAD'],
                capture_output=True, text=True, cwd=str(ROOT)).stdout.strip()
            if not base:
                base = 'HEAD~1'
            touched = set(subprocess.run(
                ['git', 'diff', '--name-only', base, '--'],
                capture_output=True, text=True,
                cwd=str(ROOT)).stdout.split())
            count = int(subprocess.run(
                ['git', 'rev-list', '--count', 'HEAD'],
                capture_output=True, text=True,
                cwd=str(ROOT)).stdout.strip() or 0)
        except Exception:                                 # noqa: BLE001
            return set(all_slugs), 'all (the diff could not be read)'
    machinery = ('tools/precedent_check.py',
                 'tools/verify_harness.py')
    if any(f in touched for f in machinery) or any(
            f.startswith('tools/checks/') for f in touched):
        return set(all_slugs), 'all (this change touches the check machinery)'
    directly = {s for s in all_slugs
                if f'practices/{s}.md' in touched}
    rest = sorted(set(all_slugs) - directly - set(pinned))
    bucket = count % HARNESS_ROTATION_BUCKETS
    rot = {s for i, s in enumerate(rest)
           if i % HARNESS_ROTATION_BUCKETS == bucket}
    sel = directly | (set(pinned) & set(all_slugs)) | rot
    if not sel:
        # A BUCKET THAT SELECTED NOTHING RUNS EVERYTHING, and this is the
        # 2026-09-20 lesson ported rather than re-learned. That day
        # precedent_check.py's own rotation landed on a bucket where every
        # slug it picked was inapplicable to the repo, reported `0 passed`,
        # and CI's "refuse a run that checked nothing" backstop correctly
        # refused it -- on two real pull requests, in two different sets,
        # on commits with real passing coverage elsewhere in the catalogue
        # (_run_with_coverage_retry's own docstring has the full account).
        #
        # The shape here is different and safer: nine slugs are pinned in
        # every bucket, so the measured floor is 15 of 71 rather than
        # anything near zero, and a planted case has no SKIP path -- it
        # either asserts or fails loudly. But the floor is a PROPERTY of
        # today's pinned set, not a guarantee, and it would quietly weaken
        # the day nobody reads `planted[...]` back any more. So the empty
        # case is handled here instead of being left to arithmetic that
        # happens to hold.
        return set(all_slugs), ('all (the rotation slice came back empty -- '
                                'running everything rather than nothing)')
    return sel, (f'rotation bucket {bucket}/{HARNESS_ROTATION_BUCKETS}: '
                 f'{len(directly)} touched, {len(pinned & set(all_slugs))} pinned, '
                 f'{len(rot)} rotating')

def _registry_slugs():
    """-> sorted slugs precedent_check registers here. The selector
    needs the full set BEFORE the first case() runs, and the only
    authority on it is the registry itself -- the same module the
    untested-claim assertion at the end of this function loads, and
    for the same reason it calls register_materialized_checks()
    first: a source-supplied tools/checks/ script is not in CHECKS
    until it registers itself."""
    # `import importlib.util as _ilu`, NOT a bare
    # `importlib.util.…`: this function already contains a local
    # `import importlib.util` further down, which makes `importlib`
    # a local name for the WHOLE enclosing scope, so a reference up
    # here raises UnboundLocalError and the selector silently falls
    # back to running everything. Measured, not reasoned about --
    # the first run of this rotation reported "all (the registry
    # could not be read)" and took the full 81s.
    import importlib.util as _ilu
    try:
        _spec = _ilu.spec_from_file_location(
            '_pc_early', ROOT / 'tools' / 'precedent_check.py')
        _m = _ilu.module_from_spec(_spec)
        _spec.loader.exec_module(_m)
        _m.register_materialized_checks()
        return sorted(_m.CHECKS)
    except Exception:                                 # noqa: BLE001
        return []      # -> selector runs everything, by _selected below


@_without_session_id
def check_reply_gate_names_work_not_yet_landed():
    """Committed, pushed, and sitting on a branch nobody merges from is a
    state the stop hook cannot report and the person kept paying for.

    Morgan, 2026-09-21 (strength: decided): "if there are changes that are
    committed but NOT YET ON main/precedent-beta-v01/primary-branch-in-that-
    repo, then the Boildown section MUST MUST tell me that and recommend I
    do that, so I don't miss doing it."

    TWO THINGS ALREADY LOOKED AND NEITHER ANSWERS THIS. The stop hook
    refuses a turn ending with uncommitted or unpushed work -- but it fires
    AFTER the reply is composed, so it can only reject the turn and cost the
    reply twice, never put a line in the Boildown. And "pushed" is not the
    question: a feature branch can be pushed while the work sits where
    nothing merges from.

    So this runs in the reply gate, before the reply, and asks whether HEAD
    is ahead of the branch the repo actually lands work on -- `base_branch`
    from precedent.json, falling back to origin/HEAD.
    """
    import precedent_gate as pg
    import tempfile

    cases = []
    tmp = pathlib.Path(tempfile.mkdtemp(prefix='precedent-unlanded-'))
    try:
        up = tmp / 'up.git'
        subprocess.run(['git', 'init', '--bare', '-q', str(up)], check=True)
        repo = tmp / 'repo'
        subprocess.run(['git', 'init', '-q', '-b', 'trunk', str(repo)], check=True)

        def g(*a):
            return subprocess.run(['git', '-C', str(repo), *a],
                                  capture_output=True, text=True)
        g('config', 'user.name', 'Harness Fixture')
        # Assembled rather than written literally: the leak gate reads any
        # a@b as an email address and refuses the push, which it did to the
        # first version of this fixture. The address still has to be VALID
        # for `git commit` to accept it.
        g('config', 'user.email', 'fixture' + chr(64) + 'example.invalid')
        (repo / 'precedent.json').write_text(
            json.dumps({'base_branch': 'trunk', 'sources': []}), encoding='utf-8')
        (repo / 'a.txt').write_text('one\n', encoding='utf-8')
        g('add', '-A'); g('commit', '-qm', 'first')
        g('remote', 'add', 'origin', str(up))
        g('push', '-q', '-u', 'origin', 'trunk')

        cases.append(('on the base branch, with nothing ahead, it says nothing',
                      pg._unlanded_work(repo, siblings=False) == [], str(pg._unlanded_work(repo, siblings=False))))

        # A commit on a feature branch -- the exact shape that gets forgotten.
        g('switch', '-q', '-c', 'feature')
        (repo / 'b.txt').write_text('two\n', encoding='utf-8')
        g('add', '-A'); g('commit', '-qm', 'second')
        got = pg._unlanded_work(repo, siblings=False)
        cases.append(('a commit on a feature branch is reported',
                      len(got) == 1, str(got)))
        cases.append(('it names the branch it is NOT on, which is the '
                      'actionable half',
                      bool(got) and "'trunk'" in got[0], str(got)))
        cases.append(('it counts the commits', bool(got) and ' 1 commit' in got[0],
                      str(got)))

        # PUSHING THE FEATURE BRANCH CHANGES NOTHING -- that is the whole
        # point, and it is what the stop hook's "unpushed" test misses.
        g('push', '-q', '-u', 'origin', 'feature')
        after = pg._unlanded_work(repo, siblings=False)
        cases.append(('pushing the feature branch does NOT clear it -- pushed '
                      'is not landed', len(after) == 1, str(after)))

        # Merging it does.
        g('switch', '-q', 'trunk'); g('merge', '-q', 'feature')
        g('push', '-q', 'origin', 'trunk')
        cases.append(('merging into the base branch clears it',
                      pg._unlanded_work(repo, siblings=False) == [], str(pg._unlanded_work(repo, siblings=False))))

        # A SQUASH merge clears it too. The squashed commit on trunk is new,
        # so the branch's own commits never become its ancestors and
        # rev-list counts them ahead forever; this reported NOT YET LANDED
        # on every turn after a real squash merge, 2026-09-24. Two commits,
        # so no per-commit patch-id can match the squash.
        g('switch', '-q', '-c', 'squashed')
        (repo / 'c.txt').write_text('three\n', encoding='utf-8')
        g('add', '-A'); g('commit', '-qm', 'third')
        (repo / 'c.txt').write_text('three, revised\n', encoding='utf-8')
        g('add', '-A'); g('commit', '-qm', 'fourth')
        g('switch', '-q', 'trunk'); g('merge', '-q', '--squash', 'squashed')
        g('commit', '-qm', 'squash of squashed')
        g('push', '-q', 'origin', 'trunk')
        g('switch', '-q', 'squashed')
        got = pg._unlanded_work(repo, siblings=False)
        cases.append(('a squash-merged branch is not reported', got == [], str(got)))

        # The base moving on with someone else's work must not bring the
        # false report back -- a whole-tree comparison would.
        g('switch', '-q', 'trunk')
        (repo / 'd.txt').write_text('elsewhere\n', encoding='utf-8')
        g('add', '-A'); g('commit', '-qm', 'unrelated')
        g('push', '-q', 'origin', 'trunk')
        g('switch', '-q', 'squashed')
        got = pg._unlanded_work(repo, siblings=False)
        cases.append(('it stays cleared after the base moves on', got == [], str(got)))

        # And real work on top of the squashed branch is still reported.
        (repo / 'c.txt').write_text('three, revised again\n', encoding='utf-8')
        g('add', '-A'); g('commit', '-qm', 'fifth')
        got = pg._unlanded_work(repo, siblings=False)
        cases.append(('a real commit after the squash is still reported',
                      len(got) == 1 and "'trunk'" in got[0], str(got)))
        g('switch', '-q', 'trunk')

        # A repo with no precedent.json still works, via origin/HEAD.
        (repo / 'precedent.json').unlink()
        g('add', '-A'); g('commit', '-qm', 'drop config')
        g('push', '-q', 'origin', 'trunk')
        cases.append(('a repo with no precedent.json does not crash',
                      isinstance(pg._unlanded_work(repo, siblings=False), list), 'raised'))
    finally:
        shutil.rmtree(tmp, ignore_errors=True)

    bad = [(n, d) for n, ok, d in cases if not ok]
    return (not bad, f'{len(cases)} stated cases',
            '; '.join(f'{n}: {d}' for n, d in bad))


def check_a_source_set_ships_no_ci_workflow():
    """A practice source installs no CI workflow, and an existing set loses
    the ones it has on its next refresh.

    Morgan, 2026-09-21 (strength: decided), reading his own usage export:
    127 of 143 billed minutes that day -- 89% -- came from four practice
    sets running two workflows each, while twelve consuming repos cost 16
    minutes between them. practice: source-sets-run-no-ci.

    THE EMPTINESS IS THE MECHANISM, and that is what needs asserting.
    `_remove_retired_ci_workflow_files` sweeps whatever a kind no longer
    ships, but ONLY for a kind it recognises -- so `source` being PRESENT
    and EMPTY propagates the deletion, while deleting the key would stop
    the sweep and leave every installed workflow in place forever. The two
    cases are one character apart in the source and opposite in effect.
    """
    import precedent_vendor_engine as pve

    cases = []
    src = pve.CI_WORKFLOW_TEMPLATES.get('source', None)
    cases.append(('a source ships no CI workflow', src == (), repr(src)))
    cases.append(('`source` is still a RECOGNISED kind, so the sweep runs '
                  '(an absent key would silently strand every installed '
                  'workflow)', 'source' in pve.CI_WORKFLOW_TEMPLATES,
                  str(sorted(pve.CI_WORKFLOW_TEMPLATES))))

    # A CONSUMER IS NOT A SOURCE. It keeps its leak gate, because a fork's
    # pushes never fire `push` in the receiving repository -- the one case
    # a single-owner set does not have.
    con = {installed for _t, installed in
           pve.CI_WORKFLOW_TEMPLATES.get('consumer', ())}
    cases.append(('a consumer still ships its leak gate',
                  '.github/workflows/leak-gate.yml' in con, str(sorted(con))))

    # And the sweep itself: a manifest tracking both old workflows, under
    # kind `source`, must mark both superseded.
    import tempfile
    tmp = pathlib.Path(tempfile.mkdtemp(prefix='precedent-nocisrc-'))
    try:
        repo = tmp / 'repo'
        (repo / 'tools').mkdir(parents=True)
        (repo / '.github' / 'workflows').mkdir(parents=True)
        old = ['.github/workflows/precedent-check.yml',
               '.github/workflows/leak-gate.yml']
        hashes = {}
        for rel in old:
            (repo / rel).write_text('name: old\n', encoding='utf-8')
            hashes[rel] = pve._sha256(repo / rel)
        manifest = {'kind': 'source', 'ci_workflow_files': old,
                    'ci_workflows_sha256': hashes}
        (repo / 'tools' / pve.MANIFEST_NAME).write_text(
            json.dumps(manifest), encoding='utf-8')
        dropped = pve._remove_retired_ci_workflow_files(repo, manifest, 'source')
        cases.append(('refreshing a SOURCE drops both tracked workflows',
                      set(dropped) == set(old), str(sorted(dropped))))
        cases.append(('and deletes them from disk',
                      not any((repo / r).exists() for r in old),
                      str([r for r in old if (repo / r).exists()])))

        # The guard that must NOT sweep: an unrecognised kind.
        repo2 = tmp / 'repo2'
        (repo2 / 'tools').mkdir(parents=True)
        (repo2 / '.github' / 'workflows').mkdir(parents=True)
        for rel in old:
            (repo2 / rel).write_text('name: old\n', encoding='utf-8')
        m2 = {'kind': 'a-future-kind', 'ci_workflow_files': old,
              'ci_workflows_sha256': hashes}
        (repo2 / 'tools' / pve.MANIFEST_NAME).write_text(
            json.dumps(m2), encoding='utf-8')
        pve._remove_retired_ci_workflow_files(repo2, m2, 'a-future-kind')
        cases.append(('an UNRECOGNISED kind sweeps nothing -- a typo in '
                      'somebody else\'s manifest must not delete their CI',
                      all((repo2 / r).exists() for r in old),
                      str([r for r in old if not (repo2 / r).exists()])))
    finally:
        shutil.rmtree(tmp, ignore_errors=True)

    bad = [(n, d) for n, ok, d in cases if not ok]
    return (not bad, f'{len(cases)} stated cases',
            '; '.join(f'{n}: {d}' for n, d in bad))


def check_refresh_repoints_a_retired_catalogue_pin():
    """The engine refresh moves a consumer's catalogue pin off a retired
    branch by itself, so no session has to hand-edit the file that says
    which upstream branch the repo tracks.

    2026-09-27: a consumer update stopped with the engine on main and
    process/manifest.json still on precedent-beta-v01. The edit that finishes
    the update was held by Claude Code's permission check, and the person was
    asked to re-make the 2026-09-25 decision (practice:
    vendor-update-runbook, step 1). Every install on an old pin stops there.

    The negative controls carry the weight: a pin to any other branch is
    somebody's choice, and a manifest vendoring something other than
    BestPractice has its own branch names -- neither may be touched.
    """
    import inspect, tempfile
    import precedent_vendor_engine as pve

    cases = []
    tmp = pathlib.Path(tempfile.mkdtemp(prefix='precedent-catalogue-pin-'))

    def repo_with(name, upstream):
        repo = tmp / name
        (repo / 'process').mkdir(parents=True)
        (repo / 'process' / 'manifest.json').write_text(json.dumps(
            {'upstream': upstream, 'entries': []}, indent=2) + '\n',
            encoding='utf-8')
        return repo

    def pin(repo):
        return json.loads((repo / 'process' / 'manifest.json').read_text(
            encoding='utf-8'))['upstream']['branch']

    try:
        # Named here, not read from pve: an emptied list must fail this.
        for old in ('precedent-beta-v01', 'staging'):
            repo = repo_with(old, {'repo': 'https://github.com/alex137/BestPractice.git',
                                   'branch': old, 'commit': 'abc123'})
            wrote = pve.repoint_catalogue_pin(repo)
            m = json.loads((repo / 'process' / 'manifest.json').read_text(
                encoding='utf-8'))
            cases.append((f'a catalogue pinned to {old!r} is repointed to '
                          f'{pve.SOURCE_BRANCH!r}, nothing else in the '
                          f'manifest changes',
                          wrote is not None and pin(repo) == pve.SOURCE_BRANCH
                          and m['upstream']['commit'] == 'abc123'
                          and m['entries'] == [], json.dumps(m)))
            cases.append((f'a second run on the repointed {old!r} manifest '
                          f'writes nothing',
                          pve.repoint_catalogue_pin(repo) is None, pin(repo)))

        other = repo_with('other-branch', {'repo': 'https://github.com/alex137/BestPractice',
                                           'branch': 'some-feature'})
        cases.append(('a pin to any other branch is left alone',
                      pve.repoint_catalogue_pin(other) is None
                      and pin(other) == 'some-feature', pin(other)))

        foreign = repo_with('foreign', {'repo': 'https://github.com/someone/their-pack',
                                        'branch': 'staging'})
        cases.append(('`staging` in a manifest vendoring something other than '
                      'BestPractice is left alone',
                      pve.repoint_catalogue_pin(foreign) is None
                      and pin(foreign) == 'staging', pin(foreign)))

        cases.append(('a repo with no process/manifest.json is a no-op',
                      pve.repoint_catalogue_pin(tmp / 'nothing-here') is None, ''))

        # The call has to sit before refresh()'s already-current early exit:
        # the half-finished update this closes has an engine that is already
        # current, so a call placed only on the write path never runs there.
        src = inspect.getsource(pve.refresh)
        call, early = (src.find('repoint_catalogue_pin(ROOT)'),
                       src.find('already current with'))
        cases.append(('refresh() repoints before its already-current early exit',
                      -1 < call < early, f'call at {call}, early exit at {early}'))
    finally:
        shutil.rmtree(tmp, ignore_errors=True)

    bad = [(n, d) for n, ok, d in cases if not ok]
    return (not bad, f'{len(cases)} stated cases',
            '; '.join(f'{n}: {d}' for n, d in bad))


def check_upstream_branch_declaration_is_followed():
    """A consuming repo may follow `staging` instead of main by declaring
    `"upstream_branch": "staging"` in its precedent.json (2026-10-05); one
    that declares nothing, or a value off the list, follows SOURCE_BRANCH.

    Asserted end to end where it lands: followed_branch() itself, the
    catalogue pin moving to the declared branch and back again when the
    declaration goes, and the engine manifest recording the branch the
    repo follows. The negative controls are pre-staging -- seconds of
    checking, deliberately not followable -- and a pin to a feature branch,
    which stays somebody's own choice under either declaration.
    """
    import tempfile
    import precedent_vendor_engine as pve

    cases = []
    tmp = pathlib.Path(tempfile.mkdtemp(prefix='precedent-upstream-branch-'))

    def repo_with(name, declared=None, pin=None):
        repo = tmp / name
        (repo / 'process').mkdir(parents=True)
        (repo / 'tools').mkdir()
        decl = {} if declared is None else {'upstream_branch': declared}
        (repo / 'precedent.json').write_text(json.dumps(decl) + '\n',
                                             encoding='utf-8')
        if pin is not None:
            (repo / 'process' / 'manifest.json').write_text(json.dumps(
                {'upstream': {'repo': 'https://github.com/alex137/BestPractice',
                              'branch': pin, 'commit': 'abc123'},
                 'entries': []}, indent=2) + '\n', encoding='utf-8')
        return repo

    def pin(repo):
        return json.loads((repo / 'process' / 'manifest.json').read_text(
            encoding='utf-8'))['upstream']['branch']

    def declare(repo, value):
        decl = {} if value is None else {'upstream_branch': value}
        (repo / 'precedent.json').write_text(json.dumps(decl) + '\n',
                                             encoding='utf-8')

    try:
        plain = repo_with('plain')
        cases.append(('a repo that declares nothing follows main',
                      pve.followed_branch(plain) == 'main'
                      and pve.upstream_branch_problem(plain) is None,
                      pve.followed_branch(plain)))
        st = repo_with('staging', 'staging')
        cases.append(('a repo declaring staging follows staging',
                      pve.followed_branch(st) == 'staging'
                      and pve.upstream_branch_problem(st) is None,
                      pve.followed_branch(st)))
        pre = repo_with('pre', 'pre-staging')
        cases.append(('pre-staging is not followable: main, and the problem is said',
                      pve.followed_branch(pre) == 'main'
                      and 'pre-staging' in (pve.upstream_branch_problem(pre) or ''),
                      str(pve.upstream_branch_problem(pre))))
        cases.append(('a repo with no precedent.json follows main',
                      pve.followed_branch(tmp / 'nothing-here') == 'main', ''))

        moving = repo_with('moving', 'staging', pin='main')
        wrote = pve.repoint_catalogue_pin(moving)
        cases.append(('declaring staging moves a main catalogue pin to staging',
                      wrote is not None and pin(moving) == 'staging', pin(moving)))
        cases.append(('a second run writes nothing',
                      pve.repoint_catalogue_pin(moving) is None, pin(moving)))
        declare(moving, None)
        wrote = pve.repoint_catalogue_pin(moving)
        cases.append(('removing the declaration moves the pin back to main',
                      wrote is not None and pin(moving) == 'main', pin(moving)))

        feature = repo_with('feature', 'staging', pin='some-feature')
        cases.append(('a feature-branch pin is left alone under a staging declaration',
                      pve.repoint_catalogue_pin(feature) is None
                      and pin(feature) == 'some-feature', pin(feature)))

        engine = pathlib.Path(pve.__file__).resolve().parent
        out = repo_with('engine', 'staging')
        pve._write_engine_files(out / 'tools', engine, 'abc123',
                                kind=pve.DEFAULT_KIND)
        recorded = json.loads((out / 'tools' / pve.MANIFEST_NAME).read_text(
            encoding='utf-8')).get('source_branch')
        cases.append(('the engine manifest records the branch the repo follows',
                      recorded == 'staging', str(recorded)))
    finally:
        shutil.rmtree(tmp, ignore_errors=True)

    bad = [(n, d) for n, ok, d in cases if not ok]
    return (not bad, f'{len(cases)} stated cases',
            '; '.join(f'{n}: {d}' for n, d in bad))

def check_update_vendors_is_one_command():
    """tools/precedent_update.py runs Update Vendors end to end on a real
    consumer and ends in one of three outcomes, each asserted by its own
    words (practice: control-asserts-which-failure).

    The fixture is the state a consumer was really in on 2026-09-27: an
    engine vendored from main, a catalogue recorded against main, and a pin
    still naming precedent-beta-v01. That update stopped halfway on a hand
    edit and a question already answered (spec/ONE_COMMAND_UPDATE_PLAN.md).
    Here it must finish with nothing asked. The two LEFT FOR YOU cases are
    the controls that the tool does stop where a repo's own call is needed,
    and names the file.

    Owns its state (practice: fixture-owns-its-state): HOME and the user
    config are isolated, or this container's private sources resolve into
    the fixture and fail its view sync for reasons it never planted.
    """
    import tempfile
    tmp = pathlib.Path(tempfile.mkdtemp(prefix='precedent-update-'))
    cases = []
    ref = _ref_including_worktree(ROOT)
    env = {**os.environ, 'HOME': str(tmp / 'home'),
           'PRECEDENT_USER_CONFIG': str(tmp / 'no-user-config.json'),
           'GIT_AUTHOR_NAME': 't', 'GIT_AUTHOR_EMAIL': 't@t',
           'GIT_COMMITTER_NAME': 't', 'GIT_COMMITTER_EMAIL': 't@t'}
    (tmp / 'home').mkdir()

    def sh(*argv, cwd):
        r = subprocess.run(list(argv), cwd=str(cwd), env=env,
                           capture_output=True, text=True)
        return r.returncode, r.stdout + r.stderr

    def consumer(name, catalogue=True):
        repo = tmp / name
        repo.mkdir()
        sh('git', 'init', '-q', '-b', 'main', cwd=repo)
        (repo / 'precedent.json').write_text(json.dumps({
            'format_version': 1, 'visibility': 'private', 'base_branch': 'main',
            'sources': [{'level': 'universal', 'name': 'precedent',
                         'path': str(ROOT)}]}) + '\n', encoding='utf-8')
        (repo / 'AGENTS.md').write_text(
            f'# fixture\n\n{bv.BEGIN_MARKER}\n{bv.END_MARKER}\n', encoding='utf-8')
        sh(sys.executable, str(ROOT / 'tools' / 'precedent_vendor_engine.py'),
           'seed', str(repo), '--kind', 'consumer', cwd=repo)
        if catalogue:
            _rc, head = sh('git', 'rev-parse', f'origin/{pve_branch}', cwd=ROOT)
            (repo / 'process').mkdir()
            (repo / 'process' / 'manifest.json').write_text(json.dumps({
                'upstream': {'repo': 'https://github.com/alex137/BestPractice',
                             'vendored_at': 'process/upstream',
                             'branch': pve_branch, 'commit': head.strip()},
                'entries': []}, indent=2) + '\n', encoding='utf-8')
            checkin = [sys.executable, str(ROOT / 'tools' / 'checkin.py')]
            sh(*checkin, 'update', str(ROOT), '--repo', str(repo), '--force', cwd=repo)
            m = json.loads((repo / 'process' / 'manifest.json').read_text())
            # The commit the mirror actually copied, never `head` above:
            # update fetches origin/<branch> in ROOT first, so when main has
            # moved since this clone's last fetch the two differ, the
            # recorded commit no longer matches the vendored tree, and the
            # run below stops on a "local change" it never planted
            # (2026-09-29, while other windows were promoting into main).
            m['upstream']['commit'] = m['upstream'].get('synced_from', head.strip())
            m['upstream']['branch'] = 'precedent-beta-v01'   # the retired pin
            (repo / 'process' / 'manifest.json').write_text(
                json.dumps(m, indent=2) + '\n', encoding='utf-8')
        sh('git', 'add', '-A', cwd=repo)
        sh('git', 'commit', '-qm', 'installed', cwd=repo)
        # A remote without a push: record's carry check fetches origin.
        sh('git', 'clone', '-q', '--bare', str(repo), str(tmp / f'{name}.git'), cwd=tmp)
        sh('git', 'remote', 'add', 'origin', str(tmp / f'{name}.git'), cwd=repo)
        sh('git', 'fetch', '-q', 'origin', cwd=repo)
        return repo

    def update(repo, *extra):
        return sh(sys.executable, str(ROOT / 'tools' / 'precedent_update.py'),
                  '--repo', str(repo), '--from-ref', ref, '--skip-check', *extra,
                  cwd=repo)

    import precedent_vendor_engine as _pve
    pve_branch = _pve.SOURCE_BRANCH
    try:
        done = consumer('done')
        # The fixture's AGENTS.md is bare, so the first run rightly lists the
        # template's sections as this repo's call. Leaving them out is an
        # answer, and the refresh remembers it: the second run asks nothing.
        rc, out = update(done)
        cases.append(('the first run lists the template sections the repo lacks as '
                      'its own call: exit 1, LEFT FOR YOU',
                      rc == 1 and 'LEFT FOR YOU' in out and 'AGENTS.md "' in out,
                      out[-1500:]))
        rc, out = update(done)
        pin = json.loads((done / 'process' / 'manifest.json').read_text())[
            'upstream']['branch']
        cases.append(('an install on the retired pin finishes with nothing asked: '
                      'exit 0 and DONE', rc == 0 and 'DONE -- nothing left' in out,
                      out[-1500:]))
        # A repository with only main asked for no tiers: an update -- even
        # one run by a person on the ladder -- leaves it on main (Morgan,
        # 2026-10-02, strength: decided: "nothing creates tiers in a
        # repository that did not ask for them").
        landing = json.loads((done / 'precedent.json').read_text()).get('landing_branch')
        cases.append(('...its precedent.json, which named no landing branch, still '
                      'names none: the update gives a repository without tiers none',
                      landing is None, landing))
        _rc, heads = sh('git', 'ls-remote', '--heads', 'origin', cwd=done)
        cases.append(('...and origin, which had only main, still has only main',
                      'refs/heads/staging' not in heads
                      and 'refs/heads/pre-staging' not in heads, heads[-400:]))
        # A repository that does ask -- its landing_branch names a tier --
        # gets whichever tier branch origin is missing.
        _pj = json.loads((done / 'precedent.json').read_text())
        _pj['landing_branch'] = 'pre-staging'
        (done / 'precedent.json').write_text(json.dumps(_pj, indent=2) + '\n')
        sh('git', 'commit', '-qam', 'asks for tiers', cwd=done)
        update(done)
        _rc, heads = sh('git', 'ls-remote', '--heads', 'origin', cwd=done)
        cases.append(('...and once its precedent.json asks for tiers, the update '
                      'makes staging and pre-staging on origin',
                      'refs/heads/staging' in heads
                      and 'refs/heads/pre-staging' in heads, heads[-400:]))
        cases.append(('...its catalogue pin now names ' + pve_branch,
                      pin == pve_branch, pin))
        cases.append(('...and its loader views were regenerated',
                      'views: regenerated' in out and bv.BEGIN_MARKER in
                      (done / 'AGENTS.md').read_text() and
                      len((done / 'AGENTS.md').read_text()) > 200, out[-600:]))

        edited = consumer('edited-engine')
        with open(edited / 'tools' / 'precedent_show.py', 'a', encoding='utf-8') as f:
            f.write('# a local edit\n')
        rc, out = update(edited)
        cases.append(('a hand-edited engine file stops it: exit 1, LEFT FOR YOU, '
                      'naming the file', rc == 1 and 'LEFT FOR YOU' in out
                      and 'precedent_show.py' in out.split('LEFT FOR YOU', 1)[-1],
                      out[-1500:]))

        local = consumer('edited-catalogue')
        target = next(p for p in sorted((local / 'process' / 'upstream' / 'practices')
                                        .glob('*.md')))
        with open(target, 'a', encoding='utf-8') as f:
            f.write('\nA line this repo added.\n')
        rc, out = update(local)
        cases.append(('a local change in the vendored catalogue stops it: exit 1, '
                      'LEFT FOR YOU, naming the file',
                      rc == 1 and f'process/upstream/practices/{target.name}' in out,
                      out[-1500:]))

        # A practice SET renders MAP.md and GLOSSARY.md too, and its deep
        # check compares them to a fresh build. 2026-09-27: every set's
        # update failed that check on one MAP.md row for a new engine file,
        # because the views step ran only a consumer's sync tool.
        src = tmp / 'source-set'
        (src / 'practices').mkdir(parents=True)
        (src / 'practices' / 'fixture-rule.md').write_text(
            '---\nslug:        fixture-rule\ntitle:       A fixture rule\n'
            'tier:        on-demand\nseverity:    default\napplies_to:  []\n'
            'occasion:    "when a fixture needs a practice"\ngates:       []\n'
            'index_clause: "a fixture rule"\nchecked_by:  null\ndefines:     []\n'
            'command:     null\nstatus:      active\nin_force_at: null\n'
            'supersedes:  []\noverrides:   null\nadded:       "2026-09-27"\n---\n\n'
            '## Rule\nA fixture rule.\n\n## Detail\nNone.\n\n## Why\nA test.\n\n'
            '## Story\nNone.\n\n## Install\nNothing.\n', encoding='utf-8')
        (src / 'precedent.json').write_text(json.dumps(
            {'format_version': 1, 'base_branch': 'main',
             'visibility': 'public'}) + '\n', encoding='utf-8')
        (src / 'AGENTS.md').write_text(
            f'# fixture\n\n{bv.BEGIN_MARKER}\n{bv.END_MARKER}\n', encoding='utf-8')
        sh('git', 'init', '-q', '-b', 'main', cwd=src)
        sh(sys.executable, str(ROOT / 'tools' / 'precedent_vendor_engine.py'),
           'seed', str(src), '--kind', 'source', cwd=src)
        sh(sys.executable, 'tools/build_views.py', '--repo', '.', cwd=src)
        with open(src / 'MAP.md', 'a', encoding='utf-8') as f:
            f.write('| a row a newer engine would render differently |\n')
        sh('git', 'add', '-A', cwd=src)
        sh('git', 'commit', '-qm', 'installed, views stale', cwd=src)
        rc_before, _ = sh(sys.executable, 'tools/build_views.py', '--repo', '.',
                          '--check', cwd=src)
        rc, out = update(src)
        rc_after, check = sh(sys.executable, 'tools/build_views.py', '--repo', '.',
                             '--check', cwd=src)
        cases.append(("a practice set's stale MAP.md is rebuilt by the update, so "
                      "its deep check's view comparison passes",
                      rc_before != 0 and rc_after == 0 and rc == 0
                      and 'MAP.md' in out, (out + check)[-1500:]))

        bare = tmp / 'no-engine'
        bare.mkdir()
        rc, out = update(bare)
        cases.append(('a repo with no vendored engine is sent to the migration, '
                      'not updated', rc == 1 and 'this is a migration' in out, out[-600:]))

        # ...and a repo to be migrated still gets its branch tiers from here
        # (Morgan, 2026-09-27: "when migrating check for these and create them").
        classic = tmp / 'classic'
        classic.mkdir()
        sh('git', 'init', '-q', '-b', 'main', cwd=classic)
        (classic / 'README.md').write_text('# classic install\n', encoding='utf-8')
        sh('git', 'add', '-A', cwd=classic)
        sh('git', 'commit', '-qm', 'classic', cwd=classic)
        sh('git', 'clone', '-q', '--bare', str(classic), str(tmp / 'classic.git'), cwd=tmp)
        sh('git', 'remote', 'add', 'origin', str(tmp / 'classic.git'), cwd=classic)
        sh('git', 'fetch', '-q', 'origin', cwd=classic)
        rc, out = update(classic)
        _rc, heads = sh('git', 'ls-remote', '--heads', 'origin', cwd=classic)
        cases.append(('a repo still to be migrated is sent to the migration, and an '
                      'update gives it no tiers it did not ask for',
                      rc == 1 and 'this is a migration' in out
                      and 'refs/heads/staging' not in heads
                      and 'refs/heads/pre-staging' not in heads, (out + heads)[-800:]))

        rc, out = sh(sys.executable, str(ROOT / 'tools' / 'precedent_update.py'),
                     '--repo', str(ROOT), cwd=ROOT)
        cases.append(('--repo naming the BestPractice clone itself is refused',
                      rc == 2 and 'is this BestPractice clone itself' in out, out[-400:]))
    finally:
        shutil.rmtree(tmp, ignore_errors=True)

    bad = [(n, d) for n, ok, d in cases if not ok]
    return (not bad, f'{len(cases)} stated cases',
            '; '.join(f'{n}: {d}' for n, d in bad))


class _LocalEditsFixture:
    """Consumer-shaped fixtures for tools/precedent_local_edits.py, shared by
    the checks below (practice: fixture-owns-its-state): HOME, the user
    config and git identity are the fixture's own, so no private source of
    this container resolves into it.

    An "upstream change" is a commit object written into ROOT's object store
    on top of the commit a consumer was seeded from -- built with a scratch
    index, so no ref, index or file of ROOT moves -- and handed to
    precedent_update.py as --from-ref."""

    def __init__(self, prefix):
        import tempfile
        self.tmp = pathlib.Path(tempfile.mkdtemp(prefix=prefix))
        (self.tmp / 'home').mkdir()
        self.env = {**os.environ, 'HOME': str(self.tmp / 'home'),
                    'PRECEDENT_USER_CONFIG': str(self.tmp / 'no-user-config.json'),
                    'GIT_AUTHOR_NAME': 't', 'GIT_AUTHOR_EMAIL': 't@t',
                    'GIT_COMMITTER_NAME': 't', 'GIT_COMMITTER_EMAIL': 't@t'}
        self.env.pop('CLAUDE_CODE_REMOTE_SESSION_ID', None)
        self.env.pop('PRECEDENT_LEAK_BLOCKLIST', None)

    def sh(self, *argv, cwd, data=None):
        r = subprocess.run(list(argv), cwd=str(cwd), env=self.env,
                           capture_output=True, input=data)
        return r.returncode, (r.stdout + r.stderr).decode(errors='replace')

    def git(self, cwd, *argv):
        return self.sh('git', '-C', str(cwd), *argv, cwd=cwd)[1].strip()

    def consumer(self, name, precedent_extra=None):
        repo = self.tmp / name
        repo.mkdir()
        self.sh('git', 'init', '-q', '-b', 'main', cwd=repo)
        cfg = {'format_version': 1, 'visibility': 'private', 'base_branch': 'main',
               'sources': [{'level': 'universal', 'name': 'precedent',
                            'path': str(ROOT)}]}
        cfg.update(precedent_extra or {})
        (repo / 'precedent.json').write_text(json.dumps(cfg) + '\n', encoding='utf-8')
        (repo / 'AGENTS.md').write_text(
            f'# fixture\n\n{bv.BEGIN_MARKER}\n{bv.END_MARKER}\n', encoding='utf-8')
        self.sh(sys.executable, str(ROOT / 'tools' / 'precedent_vendor_engine.py'),
                'seed', str(repo), '--kind', 'consumer', cwd=repo)
        self.sh('git', 'add', '-A', cwd=repo)
        self.sh('git', 'commit', '-qm', 'installed', cwd=repo)
        bare = self.tmp / f'{name}.git'
        self.sh('git', 'clone', '-q', '--bare', str(repo), str(bare), cwd=self.tmp)
        self.sh('git', 'remote', 'add', 'origin', str(bare), cwd=repo)
        self.sh('git', 'fetch', '-q', 'origin', cwd=repo)
        return repo

    def seeded_from(self, repo):
        return json.loads((repo / 'tools' / 'ENGINE_MANIFEST.json')
                          .read_text(encoding='utf-8'))['source_commit']

    def upstream(self, base, changes):
        """-> a commit on top of `base` whose files `changes` replaces."""
        idx = self.tmp / 'scratch-index'
        e = {**self.env, 'GIT_INDEX_FILE': str(idx)}
        run = lambda *a, data=None: subprocess.run(
            ['git', '-C', str(ROOT), *a], env=e, capture_output=True, input=data)
        run('read-tree', base)
        for rel, data in changes.items():
            oid = run('hash-object', '-w', '--stdin', data=data).stdout.decode().strip()
            run('update-index', '--add', '--cacheinfo', f'100644,{oid},{rel}')
        tree = run('write-tree').stdout.decode().strip()
        idx.unlink()
        return run('commit-tree', tree, '-p', base, '-m',
                   'fixture upstream change').stdout.decode().strip()

    def update(self, repo, ref):
        return self.sh(sys.executable, str(ROOT / 'tools' / 'precedent_update.py'),
                       '--repo', str(repo), '--from-ref', ref, '--skip-check', cwd=repo)

    def commit(self, repo, message):
        self.sh('git', 'add', '-A', cwd=repo)
        self.sh('git', 'commit', '-qm', message, cwd=repo)
        return self.git(repo, 'log', '-1', '--format=%h')

    def close(self):
        shutil.rmtree(self.tmp, ignore_errors=True)


def _insert(data, text, at=3):
    lines = data.decode().splitlines(True)
    return ''.join(lines[:at] + [text] + lines[at:]).encode()


def _replace_line(data, text, at=3):
    lines = data.decode().splitlines(True)
    return ''.join(lines[:at] + [text] + lines[at + 1:]).encode()


def _section(out, title):
    """The lines of the LOCAL EDITS group titled `title`, joined."""
    block = out.split('LOCAL EDITS', 1)[-1] if 'LOCAL EDITS' in out else ''
    got, keep = [], False
    for line in block.splitlines():
        if line.startswith('  ') and not line.startswith('    '):
            keep = line.strip().startswith(title)
            continue
        if keep and line.startswith('    - '):
            got.append(line.strip())
        elif not line.startswith('    '):
            keep = False
    return '\n'.join(got)


def check_update_vendors_resolves_local_edits():
    """Update Vendors resolves a committed local edit to a vendored engine
    file instead of refusing over it (spec/LOCAL_EDITS_TO_RECEIVED_FILES_PLAN.md,
    2026-09-29), by comparing BASE (vendored from), LOCAL (committed here)
    and NEW (upstream now). One consumer holds one edited file per rule, so
    one update run shows every rule; separate runs cover a merge whose check
    fails, an uncommitted edit, a refresh that fails after the swap, and a
    journal a killed run left behind.

    Negative control (practice: control-asserts-which-failure), measured
    2026-09-29 against precedent_update.py and checkin.py as they were on
    pre-staging at c1dd37f5: every rule case fails -- the refresh refuses
    ("hand-edited since the last seed/refresh") and no LOCAL EDITS section
    is printed; the refresh-fails case passes there only because nothing was
    ever swapped, and the journal case fails because nothing replays one."""
    import hashlib
    fx = _LocalEditsFixture('precedent-local-edits-')
    cases = []
    sha = lambda b: hashlib.sha256(b).hexdigest()
    try:
        # --- one run, every rule ---------------------------------------------
        repo = fx.consumer('rules')
        seeded = fx.seeded_from(repo)
        t = repo / 'tools'
        base = {n: (t / n).read_bytes() for n in (
            'precedent_paths.py', 'precedent_show.py', 'precedent_gate.py',
            'build_views.py', 'precedent_resolve.py', 'precedent_branches.py')}
        local = {
            'precedent_paths.py': _insert(base['precedent_paths.py'], '# rule 1: a local fix\n'),
            'precedent_show.py': _insert(base['precedent_show.py'], '# rule 2: a local fix\n'),
            'precedent_gate.py': _replace_line(base['precedent_gate.py'], '# rule 3: the local line\n'),
            'build_views.py': _insert(base['build_views.py'], '# the same fix on both sides\n'),
            'precedent_resolve.py': _insert(base['precedent_resolve.py'], '# kept on purpose\n'),
            'precedent_branches.py': _insert(base['precedent_branches.py'], '# kept, pin now stale\n'),
        }
        new = {
            'precedent_show.py': base['precedent_show.py'] + b'\n# upstream: rule 2\n',
            'precedent_gate.py': _replace_line(base['precedent_gate.py'], '# rule 3: the upstream line\n'),
            'build_views.py': local['build_views.py'],
            'precedent_resolve.py': base['precedent_resolve.py'] + b'\n# upstream: kept\n',
            'precedent_branches.py': base['precedent_branches.py'] + b'\n# upstream: stale\n',
        }
        cfg = json.loads((repo / 'precedent.json').read_text(encoding='utf-8'))
        cfg['kept_template_divergences'] = {
            'tools/precedent_resolve.py': {
                'reason': 'this repo resolves sources its own way',
                'template_sha256': sha(new['precedent_resolve.py'])},
            'tools/precedent_branches.py': {
                'reason': 'this repo names its branches its own way',
                'template_sha256': sha(base['precedent_branches.py'])}}
        (repo / 'precedent.json').write_text(json.dumps(cfg) + '\n', encoding='utf-8')
        for n, data in local.items():
            (t / n).write_bytes(data)
        c_local = fx.commit(repo, 'local fixes to received engine files')
        ref = fx.upstream(seeded, {f'tools/{n}': d for n, d in new.items()})
        rc, out = fx.update(repo, ref)
        got = {n: (t / n).read_bytes() for n in local}
        cases.append(('the update resolves every committed edit and does not fail '
                      'on one', rc != 2 and 'hand-edited since the last seed' not in out
                      and 'LOCAL EDITS' in out, out[-2500:]))
        cases.append(('rule 1: upstream did not change it -- the local edit stays, '
                      'reported with the send command',
                      got['precedent_paths.py'] == local['precedent_paths.py']
                      and 'tools/precedent_paths.py' in _section(out, 'Still your local edit')
                      and 'precedent_local_edits.py send' in _section(out, 'Still your local edit'),
                      _section(out, 'Still your local edit') or out[-1500:]))
        cases.append(('rule 2: a clean merge keeps both changes, and says which '
                      'checks ran', b'# rule 2: a local fix' in got['precedent_show.py']
                      and b'# upstream: rule 2' in got['precedent_show.py']
                      and 'tools/precedent_show.py' in _section(out, 'Merged')
                      and 'compiles' in _section(out, 'Merged'),
                      _section(out, 'Merged') or out[-1500:]))
        cases.append(('rule 3: a conflict takes upstream\'s version and names the '
                      'commit holding the local one',
                      got['precedent_gate.py'] == new['precedent_gate.py']
                      and 'tools/precedent_gate.py' in _section(out, "Upstream's version taken")
                      and c_local in _section(out, "Upstream's version taken")
                      and 'same lines' in _section(out, "Upstream's version taken"),
                      _section(out, "Upstream's version taken") or out[-1500:]))
        cases.append(('upstream already carrying the change: the file matches '
                      'upstream, reported as nothing lost',
                      got['build_views.py'] == new['build_views.py']
                      and 'tools/build_views.py' in _section(out, 'Upstream now carries'),
                      _section(out, 'Upstream now carries') or out[-1500:]))
        cases.append(('rule 4: a file kept on purpose is never replaced, and its '
                      'reason is said',
                      got['precedent_resolve.py'] == local['precedent_resolve.py']
                      and 'resolves sources its own way' in _section(out, 'Kept on purpose'),
                      _section(out, 'Kept on purpose') or out[-1500:]))
        left = out.split('LEFT FOR YOU', 1)[-1] if 'LEFT FOR YOU' in out else ''
        cases.append(('rule 4 with a stale pin: still never replaced, and left for '
                      'the person with the hash to record',
                      got['precedent_branches.py'] == local['precedent_branches.py']
                      and 'tools/precedent_branches.py' in left
                      and sha(new['precedent_branches.py']) in left, left[-1500:]))

        # --- rule 2 whose check fails: every merged file back to NEW ---------
        repo = fx.consumer('failing-check')
        seeded = fx.seeded_from(repo)
        f = repo / 'tools' / 'precedent_show.py'
        b = f.read_bytes()
        f.write_bytes(_insert(b, '# rule 2: a local fix\n'))
        tests = repo / 'tools' / 'checks' / 'tests' / 'run_all.sh'
        tests.parent.mkdir(parents=True, exist_ok=True)
        tests.write_text('#!/usr/bin/env bash\n'
                         'if grep -q "local fix" tools/precedent_show.py && '
                         'grep -q "upstream: rule 2" tools/precedent_show.py; then\n'
                         '  echo "the merged file breaks a fixture test"; exit 1\nfi\n',
                         encoding='utf-8')
        fx.commit(repo, 'a local fix, and a test the merge will fail')
        up = b + b'\n# upstream: rule 2\n'
        rc, out = fx.update(repo, fx.upstream(seeded, {'tools/precedent_show.py': up}))
        taken = _section(out, "Upstream's version taken")
        cases.append(('rule 2 whose check fails falls back to upstream\'s version '
                      'and names the failed check', f.read_bytes() == up
                      and 'tools/precedent_show.py' in taken and 'run_all.sh' in taken
                      and 'merged cleanly as text' in taken, taken or out[-1500:]))

        # --- an uncommitted edit: nothing written -----------------------------
        repo = fx.consumer('uncommitted')
        seeded = fx.seeded_from(repo)
        f = repo / 'tools' / 'precedent_paths.py'
        edited = _insert(f.read_bytes(), '# not committed\n')
        f.write_bytes(edited)
        manifest = (repo / 'tools' / 'ENGINE_MANIFEST.json').read_bytes()
        rc, out = fx.update(repo, fx.upstream(seeded, {
            'tools/precedent_paths.py': f.read_bytes() + b'\n# upstream\n'}))
        cases.append(('an uncommitted edit stops the update with nothing written',
                      rc == 1 and 'not committed' in out
                      and 'tools/precedent_paths.py' in out.split('LEFT FOR YOU', 1)[-1]
                      and f.read_bytes() == edited
                      and (repo / 'tools' / 'ENGINE_MANIFEST.json').read_bytes() == manifest,
                      out[-1500:]))

        # --- the refresh fails after the swap: LOCAL back, byte for byte ------
        repo = fx.consumer('refresh-fails',
                           {'engine_paths': {'README.md': 'tools/precedent_gate.py'}})
        seeded = fx.seeded_from(repo)
        f = repo / 'tools' / 'precedent_show.py'
        edited = _insert(f.read_bytes(), '# a local fix\n')
        f.write_bytes(edited)
        fx.commit(repo, 'a local fix')
        rc, out = fx.update(repo, fx.upstream(seeded, {
            'tools/precedent_show.py': f.read_bytes() + b'\n# upstream\n'}))
        journal = pathlib.Path(fx.git(repo, 'rev-parse', '--absolute-git-dir')) / \
            'precedent-local-edits'
        cases.append(('a refresh that fails after the swap puts the local edit back '
                      'byte for byte, and leaves no journal',
                      rc == 2 and 'this engine already vendors this path' in out
                      and f.read_bytes() == edited and not journal.exists(),
                      out[-1500:]))

        # --- a journal a killed run left: replayed first ---------------------
        repo = fx.consumer('killed')
        seeded = fx.seeded_from(repo)
        f = repo / 'tools' / 'precedent_show.py'
        edited = _insert(f.read_bytes(), '# a local fix\n')
        f.write_bytes(edited)
        fx.commit(repo, 'a local fix')
        rc, out = fx.sh(sys.executable, '-c', (
            'import os, pathlib, sys\n'
            f'sys.path.insert(0, {str(ROOT / "tools")!r})\n'
            'import precedent_local_edits as le\n'
            f'repo = pathlib.Path({str(repo)!r})\n'
            'edits, _ = le.engine_edits(repo)\n'
            'le.Swap(repo, edits).__enter__()\n'
            'os._exit(9)\n'), cwd=repo)
        journal = pathlib.Path(fx.git(repo, 'rev-parse', '--absolute-git-dir')) / \
            'precedent-local-edits'
        swapped = f.read_bytes() != edited and journal.is_dir()
        rc, out = fx.update(repo, seeded)
        cases.append(('a journal left by a killed run is replayed first: the local '
                      'edit is back, and said', swapped
                      and 'put back your local tools/precedent_show.py' in out
                      and f.read_bytes() == edited and not journal.exists(),
                      out[-1500:]))
    finally:
        fx.close()
    bad = [(n, d) for n, ok, d in cases if not ok]
    return (not bad, f'{len(cases)} stated cases',
            '; '.join(f'{n}: {d}' for n, d in bad))


def check_update_rerun_after_failed_takes_its_own_output():
    """A rerun of Update Vendors after a FAILED one recognises what the
    failed run staged as its own output, puts it back and writes it again,
    instead of refusing it as "a vendored file edited here and not
    committed" (2026-10-02: a consumer's run failed its deep check with an
    engine file it had merged with the repo's committed local edit still
    staged, and the rerun the FAILED message asked for stopped on that very
    file). A staged file the person changed after the failure is still
    theirs, and still refused.

    Negative control, measured 2026-10-02 against staging at 1c2403f: the
    rerun stops with "not committed" naming tools/precedent_show.py, so the
    second case fails."""
    fx = _LocalEditsFixture('precedent-update-rerun-')
    cases = []

    def red_update(repo, ref):
        # The real update, with its closing check stubbed red, so the run
        # ends FAILED with its output staged exactly as a red check leaves it.
        return fx.sh(sys.executable, '-c', (
            'import sys\n'
            f'sys.path.insert(0, {str(ROOT / "tools")!r})\n'
            'import precedent_update as pu\n'
            'pu.judged_as_committed = lambda _r, _a: (1, "stubbed red check")\n'
            f'sys.exit(pu.main(["--repo", {str(repo)!r}, "--from-ref", {ref!r}]))\n'),
            cwd=repo)
    try:
        for name, touch in (('untouched', False), ('touched', True)):
            repo = fx.consumer(name)
            seeded = fx.seeded_from(repo)
            # Answer the bare fixture's first-run questions, so the run
            # below reaches its check rather than stopping short of it.
            fx.update(repo, seeded)
            fx.commit(repo, 'first update')
            f = repo / 'tools' / 'precedent_show.py'
            b = f.read_bytes()
            f.write_bytes(_insert(b, '# a local fix\n'))
            fx.commit(repo, 'a local fix to a received engine file')
            ref = fx.upstream(seeded, {'tools/precedent_show.py': b + b'\n# upstream\n'})
            rc, out = red_update(repo, ref)
            merged = f.read_bytes()
            if not touch:
                cases.append(('the first run ends FAILED on its check, with the merged '
                              'engine file staged', rc == 2 and 'FAILED' in out
                              and b'# a local fix' in merged and b'# upstream' in merged
                              and 'tools/precedent_show.py' in fx.git(
                                  repo, 'diff', '--cached', '--name-only'), out[-1500:]))
                rc, out = fx.update(repo, ref)
                cases.append(('the rerun takes that file as its own output and does not '
                              'refuse it', 'not committed' not in out and rc != 2
                              and 'earlier run' in out and f.read_bytes() == merged,
                              out[-1500:]))
            else:
                f.write_bytes(merged + b'# the person fixed something here\n')
                rc, out = fx.update(repo, ref)
                cases.append(('a staged file changed after the failure is the person\'s: '
                              'refused, and left as they wrote it',
                              rc == 1 and 'not committed' in out
                              and 'tools/precedent_show.py' in out.split('LEFT FOR YOU', 1)[-1]
                              and f.read_bytes().endswith(b'fixed something here\n'),
                              out[-1500:]))
    finally:
        fx.close()
    bad = [(n, d) for n, ok, d in cases if not ok]
    return (not bad, f'{len(cases)} stated cases',
            '; '.join(f'{n}: {d}' for n, d in bad))


def check_update_reports_every_blocker_before_the_slow_check():
    """Update Vendors reports every blocker it can find cheaply in one run
    and starts the slow check only when there are none (2026-10-02: a large
    consumer's run 1 spent half an hour on its full check, failed it, and
    only run 3 stopped on a template divergence known before run 1's check
    began). Two independent items left for the person: both named in one
    run, and the check never started. None left but the basic tier red: its
    findings reported, the full tier never started. Both green: the full
    tier runs. The check is stubbed, so each case is decided by what the
    stub was asked.

    Negative control, measured 2026-10-02 against staging at 1c2403f: the
    check runs with items left (the first case fails), and only the full
    tier is ever asked for (the second fails)."""
    import tempfile
    sys.path.insert(0, str(ROOT / 'tools'))
    try:
        import precedent_update as pu
    finally:
        sys.path.pop(0)
    tmp = pathlib.Path(tempfile.mkdtemp(prefix='precedent-update-blockers-'))
    cases = []
    real = pu.judged_as_committed, pu.pb.landing_branch, pu.pb.tier_for_branch
    try:
        repo = tmp / 'r'
        (repo / 'tools').mkdir(parents=True)
        subprocess.run(['git', 'init', '-q', '-b', 'main', str(repo)], capture_output=True)
        (repo / 'tools' / 'precedent_push_check.py').write_text('', encoding='utf-8')
        pu.pb.landing_branch = lambda _r, *a, **k: ('staging', 'fixture')
        pu.pb.tier_for_branch = lambda _r, _b, *a, **k: (pu.pb.FULL, 'fixture')
        asked = []

        def stub(red_tiers):
            def judged(_repo, argv):
                tier = argv[argv.index('--tier') + 1] if '--tier' in argv else 'full'
                asked.append(tier)
                return (1, f'{tier} finding') if tier in red_tiers else (0, 'green')
            return judged

        def run(red_tiers, left=()):
            asked.clear()
            pu.judged_as_committed = stub(red_tiers)
            rep = pu.Report()
            for what, why in left:
                rep.leave(what, why)
            import contextlib, io
            buf = io.StringIO()
            with contextlib.redirect_stdout(buf):
                rc = pu.closing_check(repo, rep)
            return rc, buf.getvalue()

        rc, out = run({'full'}, [('tools/bootstrap.sh', 'diverged from the template'),
                                 ('AGENTS.md "Session setup"', 'missing a template section')])
        left = out.split('LEFT FOR YOU', 1)[-1]
        cases.append(('two items left: both named in one run, and no check started',
                      rc == pu.LEFT and 'tools/bootstrap.sh' in left
                      and 'AGENTS.md "Session setup"' in left and asked == [],
                      (asked, out[-1200:])))
        rc, out = run({'basic', 'full'})
        cases.append(('none left, the basic tier red: its finding reported, the full '
                      'tier never started', rc == pu.FAILED and 'basic finding' in out
                      and asked == ['basic'], (asked, out[-1200:])))
        rc, out = run(set())
        cases.append(('none left, both green: the full tier runs after the basic',
                      rc == pu.DONE and asked == ['basic', 'full'], (asked, out[-1200:])))
    finally:
        pu.judged_as_committed, pu.pb.landing_branch, pu.pb.tier_for_branch = real
        shutil.rmtree(tmp, ignore_errors=True)
    bad = [(n, d) for n, ok, d in cases if not ok]
    return (not bad, f'{len(cases)} stated cases',
            '; '.join(f'{n}: {d}' for n, d in bad))


def check_gone_path_matcher_matches_one_regex_per_path():
    """change-updates-its-docs finds a removed path by a prefix lookup
    (precedent_check.gone_path_matcher) where it used to try one regex per
    removed path on every line -- five to ten minutes on a large consumer.
    The answer must be the same, line for line: the first path in sorted
    order that the line names on the same boundaries. Compared here with
    that old loop on a seeded fixture of paths and lines built to sit on
    every boundary (a longer path, a suffix, a prefix directory, a trailing
    dot or dash, a non-ASCII word, paths with characters outside a path
    run)."""
    import random
    sys.path.insert(0, str(ROOT / 'tools'))
    try:
        import precedent_check as pc
    finally:
        sys.path.pop(0)
    rnd = random.Random(7)
    words = ['practices', 'tools', 'spec', 'todo', 'x', 'a-b', 'v1', 'foo_bar', 'ü']

    def path():
        return ('/'.join(rnd.choice(words) for _ in range(rnd.randint(2, 4)))
                + rnd.choice(['.md', '.py', '', '.json', '.md.bak']))
    gone = {path() for _ in range(400)} | {'odd dir/x.md', 'a+b/c.md'}
    pool = sorted(gone)
    lines = []
    for _ in range(3000):
        toks = []
        for _ in range(rnd.randint(1, 10)):
            r = rnd.random()
            if r < 0.25:
                toks.append(rnd.choice(pool))
            elif r < 0.45:
                toks.append(rnd.choice(['', 'other/', '`', '(', 'x', '.', '-'])
                            + path() + rnd.choice(['', '.', '-x', '/', '`', ')', ',', '_']))
            else:
                toks.append(rnd.choice(words))
        lines.append(rnd.choice([' ', '', '/']).join(toks))
    lines += ['see odd dir/x.md here', 'a+b/c.md', 'xa+b/c.md', 'odd dir/x.mdz']
    pats = [(g, re.compile(r'(?<![\w./-])' + re.escape(g) + r'(?![\w-])')) for g in pool]
    want = [next((g for g, p in pats if p.search(l)), None) for l in lines]
    first = pc.gone_path_matcher(gone)
    got = [first(l) for l in lines]
    diff = [(l, w, g) for l, w, g in zip(lines, want, got) if w != g]
    hits = sum(1 for w in want if w)
    return (not diff and hits > 1000, f'{len(lines)} lines, {hits} with a hit, '
            f'{len(gone)} removed paths', f'{len(diff)} differ, first: {diff[:2]}')


def check_model_audit_changed_selects_only_what_a_change_reaches():
    """model_audit --changed audits only the models a change can reach: a
    manifest or blocklist change selects none, an engine no model loads
    selects none, the engine a shim loads by path selects the model behind
    that shim, and memo plumbing the host lists selects none (2026-10-02: a
    consumer's merges carried vendored engine files under tools/ that no
    model loads, and each re-audited all 59 of its models). The engine's
    own self-check builds the scratch repository and states the cases.

    Negative control, measured 2026-10-02: with the old rule (any .py
    changed under tools/ or process/ audits everything) the self-check
    fails on the unloaded engine and the path-loaded one."""
    r = subprocess.run([sys.executable, str(ROOT / 'tools' / 'model_audit.py'),
                        '--self-check'], capture_output=True, text=True, cwd=str(ROOT))
    out = r.stdout + r.stderr
    return (r.returncode == 0 and 'self-check OK' in out, 'model_audit --self-check',
            out[-1200:])


def check_merge_takes_the_vendor_update():
    """tools/precedent_merge_vendors.py, run at a merge, takes Update Vendors
    as a commit of its own when the update finishes, and takes everything it
    wrote back when it does not -- never blocking the merge, exit 0 every
    time (2026-10-02, Alex: "Can we set up a system so merge also does
    vendor updates?"). Each outcome is asserted by its own words and by the
    repository's state after it (practice: control-asserts-which-failure):

      - an upstream change, the update DONE: HEAD gains exactly one commit,
        it carries the change, and nothing is left staged or changed;
      - the update leaving calls for the person: HEAD unmoved, nothing left
        staged or changed, and the reason printed;
      - a tracked file changed and not committed: refused before anything
        runs, the person's edit untouched;
      - freshness saying nothing is behind: nothing runs at all.

    Negative control: before this tool existed the merge only printed the
    freshness notice, so every case fails for want of the file."""
    fx = _LocalEditsFixture('precedent-merge-vendors-')
    tool = ROOT / 'tools' / 'precedent_merge_vendors.py'
    cases = []

    def merge_vendors(repo, *extra):
        return fx.sh(sys.executable, str(tool), '--repo', str(repo), '--source',
                     str(ROOT), '--always', '--skip-check', *extra, cwd=repo)

    def clean(repo):
        return fx.git(repo, 'status', '--porcelain', '--untracked-files=no') == ''
    try:
        # --- DONE: committed on its own -------------------------------------
        repo = fx.consumer('done')
        seeded = fx.seeded_from(repo)
        fx.update(repo, seeded)          # answer the bare fixture's questions
        fx.commit(repo, 'first update')
        f = repo / 'tools' / 'precedent_show.py'
        up = f.read_bytes() + b'\n# upstream, taken at a merge\n'
        ref = fx.upstream(seeded, {'tools/precedent_show.py': up})
        head = fx.git(repo, 'rev-parse', 'HEAD')
        rc, out = merge_vendors(repo, '--from-ref', ref)
        parent = fx.git(repo, 'rev-parse', 'HEAD~1')
        msg = fx.git(repo, 'log', '-1', '--format=%B')
        cases.append(('an update that finishes is one commit of its own on top, '
                      'carrying the change, with nothing left over',
                      rc == 0 and 'VENDORS: updated, in commit' in out
                      and parent == head and f.read_bytes() == up and clean(repo)
                      and msg.startswith('Update Vendors at merge'),
                      out[-1500:]))

        # --- LEFT: everything taken back -------------------------------------
        repo = fx.consumer('left')     # bare AGENTS.md: the first run asks
        head = fx.git(repo, 'rev-parse', 'HEAD')
        rc, out = merge_vendors(repo, '--from-ref', fx.seeded_from(repo))
        cases.append(('an update that leaves calls for the person is taken back '
                      'whole, the reason printed, the merge not blocked',
                      rc == 0 and 'VENDORS: NOT TAKEN' in out and 'calls for the person' in out
                      and 'LEFT FOR YOU' in out
                      and fx.git(repo, 'rev-parse', 'HEAD') == head and clean(repo)
                      and fx.git(repo, 'diff', '--cached', '--name-only') == '',
                      out[-1500:]))

        # --- a person's uncommitted edit: refused, untouched -----------------
        repo = fx.consumer('dirty')
        readme = repo / 'AGENTS.md'
        mine = readme.read_text(encoding='utf-8') + '\nmy unfinished edit\n'
        readme.write_text(mine, encoding='utf-8')
        rc, out = merge_vendors(repo, '--from-ref', fx.seeded_from(repo))
        cases.append(('a tracked file changed and not committed: refused before '
                      'anything runs, the edit left as it was',
                      rc == 0 and 'NOT TAKEN' in out and 'Nothing was run' in out
                      and readme.read_text(encoding='utf-8') == mine, out[-800:]))

        # --- current: nothing runs -------------------------------------------
        rc, out = fx.sh(sys.executable, '-c', (
            'import sys\n'
            f'sys.path.insert(0, {str(ROOT / "tools")!r})\n'
            'import precedent_merge_vendors as mv\n'
            'mv.vendors_behind = lambda _r: ([], [])\n'
            'mv.refresh_views = lambda _r: print("VIEWS: asked")\n'
            'mv.subprocess.run = None  # running anything would raise\n'
            f'sys.exit(mv.run({str(repo)!r}))\n'), cwd=repo)
        cases.append(('nothing behind: says current and runs no update -- only '
                      'the views check, which has a test of its own',
                      rc == 0 and 'VENDORS: current' in out
                      and 'VIEWS: asked' in out, out[-800:]))
    finally:
        fx.close()
    bad = [(n, d) for n, ok, d in cases if not ok]
    return (not bad, f'{len(cases)} stated cases',
            '; '.join(f'{n}: {d}' for n, d in bad))


def check_update_vendors_resolves_a_catalogue_edit():
    """The same resolution for process/upstream/, a pre-2026-09-14 install's
    mirrored catalogue: a committed, pushed local edit to a vendored
    practice, where upstream changed the same file elsewhere, is merged, and
    `record` passes because its carry check skips exactly the file being
    resolved (checkin.py record --resolving).

    BASE is a commit object on top of origin/<source branch> whose copy of
    one practice lacks upstream's last line, so NEW (what checkin.py update
    mirrors) differs from BASE in exactly that file.

    Negative control, measured 2026-09-29: with pre-staging's c1dd37f5
    precedent_update.py the update refuses ("the vendored tree has local
    changes"); with --resolving removed from the record call, record is held
    by the carry check ("lines to lose")."""
    import precedent_vendor_engine as _pve
    branch = _pve.SOURCE_BRANCH
    head = subprocess.run(['git', '-C', str(ROOT), 'rev-parse', '--verify', '--quiet',
                           f'origin/{branch}'], capture_output=True, text=True).stdout.strip()
    if not head:
        not_applicable('Update Vendors resolves a local edit in process/upstream/',
                       f'this clone has no origin/{branch} for the catalogue to mirror')
        return
    fx = _LocalEditsFixture('precedent-local-edits-cat-')
    cases = []
    try:
        repo = fx.consumer('catalogue')
        seeded = fx.seeded_from(repo)
        # One commit for engine AND catalogue: precedent_update.py --from-ref
        # mirrors the catalogue at the ref too since 2026-10-03, so the
        # fixture is built on the commit the update will mirror.
        head = seeded
        practice = 'practices/verify-postcondition.md'
        upstream_text = subprocess.run(['git', '-C', str(ROOT), 'show',
                                        f'{head}:{practice}'], capture_output=True).stdout
        lines = upstream_text.decode().rstrip('\n').splitlines(True)
        base_text = ''.join(lines[:-1]).encode()
        base_commit = fx.upstream(head, {practice: base_text})
        (repo / 'process').mkdir()
        (repo / 'process' / 'manifest.json').write_text(json.dumps({
            'upstream': {'repo': 'https://github.com/alex137/BestPractice',
                         'vendored_at': 'process/upstream', 'branch': branch,
                         'commit': head}, 'entries': []}, indent=2) + '\n',
            encoding='utf-8')
        fx.sh(sys.executable, str(ROOT / 'tools' / 'checkin.py'), 'update', str(ROOT),
              '--repo', str(repo), '--force', '--from-ref', head, cwd=repo)
        m = json.loads((repo / 'process' / 'manifest.json').read_text(encoding='utf-8'))
        m['upstream']['commit'] = base_commit
        (repo / 'process' / 'manifest.json').write_text(json.dumps(m, indent=2) + '\n',
                                                        encoding='utf-8')
        f = repo / 'process' / 'upstream' / practice
        local = _insert(base_text, 'A line this repo added to fix a local bug.\n', at=16)
        f.write_bytes(local)
        fx.commit(repo, 'a local fix to a vendored practice')
        fx.sh('git', 'push', '-q', 'origin', 'HEAD:main', cwd=repo)
        rc, out = fx.update(repo, seeded)
        got = f.read_bytes()
        rec = json.loads((repo / 'process' / 'manifest.json').read_text(encoding='utf-8'))
        cases.append(('a committed local edit in process/upstream/ is merged with '
                      'upstream\'s change, not refused',
                      'refused' not in out.split('catalogue', 1)[-1][:200]
                      and b'A line this repo added' in got
                      and got.rstrip(b'\n').endswith(lines[-1].rstrip('\n').encode())
                      and f'process/upstream/{practice}' in _section(out, 'Merged'),
                      out[-2500:]))
        cases.append(('...and record passes, its carry check skipping only that file',
                      'catalogue record' in out and 'held' not in out
                      and rec['upstream']['commit'] == head, out[-1500:]))
    finally:
        fx.close()
    # Records its own verdict, so the not-applicable path above is said as
    # such and never counted as a pass.
    bad = [f'{n}: {d}' for n, ok, d in cases if not ok]
    check(f'Update Vendors resolves a committed local edit in process/upstream/ '
          f'({len(cases)} stated cases)', not bad, '; '.join(bad))


def check_local_edits_fetch_the_vendored_commit_from_upstream():
    """precedent_local_edits.py judges a consuming repository's edits to
    received files against the commit they were vendored from. Run from
    the consumer, that commit was never in the consumer's own history, so
    every file read "cannot judge" unless an upstream clone sat beside it
    (Alex, 2026-10-04: fold the vendor engines into the send/take loop).
    It now fetches that one commit from the upstream the manifest records.
    Both directions: with no upstream named, a missing commit is still
    reported missing, and a fetch creates no branch or tag."""
    import tempfile
    import precedent_local_edits as le
    name = 'local-edit status fetches the vendored-from commit from upstream'
    cases = []
    env = dict(os.environ, GIT_AUTHOR_NAME='T', GIT_AUTHOR_EMAIL='t@example.com',
               GIT_COMMITTER_NAME='T', GIT_COMMITTER_EMAIL='t@example.com')
    with tempfile.TemporaryDirectory() as td:
        up, mine = pathlib.Path(td) / 'up', pathlib.Path(td) / 'mine'
        for d in (up, mine):
            d.mkdir()
            subprocess.run(['git', 'init', '-q', '-b', 'main', str(d)], env=env)
        (up / 'a.py').write_text('x = 1\n', encoding='utf-8')
        subprocess.run(['git', '-C', str(up), 'add', '-A'], env=env)
        subprocess.run(['git', '-C', str(up), 'commit', '-qm', 'u'], env=env)
        sha = subprocess.run(['git', '-C', str(up), 'rev-parse', 'HEAD'],
                             capture_output=True, text=True).stdout.strip()
        (mine / 'b.py').write_text('y = 2\n', encoding='utf-8')
        subprocess.run(['git', '-C', str(mine), 'add', '-A'], env=env)
        subprocess.run(['git', '-C', str(mine), 'commit', '-qm', 'm'], env=env)
        refs_before = subprocess.run(['git', '-C', str(mine), 'for-each-ref'],
                                     capture_output=True, text=True).stdout
        cases.append(('with no upstream named, the missing commit is reported missing',
                      not le._has_commit(mine, sha)))
        cases.append(('with the recorded upstream, the commit is fetched',
                      le._has_commit(mine, sha, str(up))
                      and le._show(mine, sha, 'a.py') == b'x = 1\n'))
        cases.append(('...and the clone stays complete: never marked shallow',
                      not (mine / '.git' / 'shallow').exists()
                      and subprocess.run(['git', '-C', str(mine), 'rev-parse',
                                          '--is-shallow-repository'], capture_output=True,
                                         text=True).stdout.strip() == 'false'))
        cases.append(('...and no branch or tag is created',
                      subprocess.run(['git', '-C', str(mine), 'for-each-ref'],
                                     capture_output=True, text=True).stdout == refs_before))
    failed = [n for n, ok in cases if not ok]
    check(f'{name} ({len(cases)} stated cases)', not failed, '; '.join(failed))


def check_a_sync_deletion_is_not_a_local_edit():
    """precedent_local_edits.py reads a file upstream has and a consumer's
    copy lacks as the consumer's own deletion -- and every later update then
    "keeps" it out. A file removed by a vendor sync (the copy rules once
    left it out) or never shipped at all is upstream's doing, not the
    consumer's: a consumer went without 46 live gotchas for days after
    gotchas/ shipped again on 2026-10-01 (found 2026-10-04). Both
    directions: a deletion the consumer committed on its own still counts."""
    import tempfile
    import precedent_local_edits as le
    name = 'a deletion made by a vendor sync is not a local edit'
    env = dict(os.environ, GIT_AUTHOR_NAME='T', GIT_AUTHOR_EMAIL='t@example.com',
               GIT_COMMITTER_NAME='T', GIT_COMMITTER_EMAIL='t@example.com')
    cases = []
    with tempfile.TemporaryDirectory() as td:
        repo = pathlib.Path(td)
        g = lambda *a: subprocess.run(['git', '-C', str(repo), *a], env=env,
                                      capture_output=True, text=True)
        g('init', '-q', '-b', 'main')
        (repo / 'process' / 'upstream' / 'gotchas').mkdir(parents=True)
        man = repo / 'process' / 'manifest.json'
        man.write_text('{"upstream": {\n  "commit": "aaa"\n}}\n')
        for n in ('synced-away.md', 'mine-away.md'):
            (repo / 'process' / 'upstream' / 'gotchas' / n).write_text('x\n')
        g('add', '-A'); g('commit', '-qm', 'vendor at aaa')
        (repo / 'process' / 'upstream' / 'gotchas' / 'synced-away.md').unlink()
        man.write_text('{"upstream": {\n  "commit": "bbb"\n}}\n')
        g('add', '-A'); g('commit', '-qm', 'a sync whose rules left the file out')
        (repo / 'process' / 'upstream' / 'gotchas' / 'mine-away.md').unlink()
        g('add', '-A'); g('commit', '-qm', 'the consumer deletes one itself')
        rel = lambda n: f'process/upstream/gotchas/{n}'
        cases.append(('removed by a sync: not a local edit',
                      not le._deleted_here(repo, rel('synced-away.md'))))
        cases.append(('never shipped here: not a local edit',
                      not le._deleted_here(repo, rel('never-had.md'))))
        cases.append(('removed by the consumer: still a local edit',
                      le._deleted_here(repo, rel('mine-away.md'))))
        # checkin.py's own guard asks the same question through
        # local_changes(); it once counted the sync's deletion and refused
        # every update (found 2026-10-04, after the fix above).
        src = pathlib.Path(td) / 'source'
        s = lambda *a: subprocess.run(['git', '-C', str(src), *a], env=env,
                                      capture_output=True, text=True)
        (src / 'gotchas').mkdir(parents=True)
        for n in ('synced-away.md', 'mine-away.md'):
            (src / 'gotchas' / n).write_text('x\n')
        s('init', '-q', '-b', 'main'); s('add', '-A'); s('commit', '-qm', 'upstream')
        head = s('rev-parse', 'HEAD').stdout.strip()
        ck = le._checkin(repo)
        drift = [p.as_posix() for p in (ck.local_changes(src, head) or [])]
        cases.append(("checkin's guard: the consumer's deletion only",
                      drift == ['gotchas/mine-away.md']))
    failed = [n for n, ok in cases if not ok]
    check(f'{name} ({len(cases)} stated cases)', not failed, '; '.join(failed))


def check_send_carries_a_local_edit_upstream():
    """tools/precedent_local_edits.py send turns a consumer's committed edit
    to a received engine file into a branch in the owner's clone, merged
    three ways onto the owner's landing branch, scrubbed on both sides, and
    pushed -- never a pull request, never a merge
    (spec/LOCAL_EDITS_TO_RECEIVED_FILES_PLAN.md, part one, 2026-09-29).

    The owner is a full local clone of this repo whose origin is a bare
    repository in the fixture, so the push leaves nothing on the machine's
    real remotes. Its commits are authored as whoever this checkout's own
    identity resolves to, as a real clone's would be, so its basic tier
    judges the branch as it judges any other push.

    Negative control, measured 2026-09-29: with send's three-way merge
    replaced by a plain copy of the local file, the "not reverted" case
    fails; with consumer_scrub() returning nothing, the private-word case
    pushes the branch and fails (the owner's gate has never heard of the
    word -- which is the whole point of scrubbing on the consumer's side);
    the file did not exist before, so every case fails without it."""
    fx = _LocalEditsFixture('precedent-send-')
    cases = []
    tool = [sys.executable, str(ROOT / 'tools' / 'precedent_local_edits.py')]
    try:
        import precedent_identity
        who = precedent_identity.declared_identity(ROOT) or {}
    except Exception:                           # noqa: BLE001
        who = {}
    ident = {k: v for k, v in (
        ('GIT_AUTHOR_NAME', who.get('name')), ('GIT_AUTHOR_EMAIL', who.get('email')),
        ('GIT_COMMITTER_NAME', who.get('name')), ('GIT_COMMITTER_EMAIL', who.get('email'))) if v}
    try:
        repo = fx.consumer('secret-client-repo')
        seeded = fx.seeded_from(repo)
        f = repo / 'tools' / 'precedent_show.py'
        base = f.read_bytes()

        # The owner: its landing branch has moved on since the consumer
        # vendored, with a change to the same file.
        fx.env.update(ident)
        owner, bare = fx.tmp / 'owner', fx.tmp / 'owner.git'
        fx.sh('git', 'clone', '-q', '--no-local', str(ROOT), str(owner), cwd=fx.tmp)
        landing = fx.sh(sys.executable, 'tools/precedent_branches.py', '--landing',
                        cwd=owner)[1].split()[0]
        fx.sh('git', 'checkout', '-q', '-B', landing, seeded, cwd=owner)
        (owner / 'tools' / 'precedent_show.py').write_bytes(
            base + b'\n# upstream moved on since vendoring\n')
        fx.sh('git', 'commit', '-qam', 'upstream moved on', cwd=owner)
        fx.sh('git', 'clone', '-q', '--bare', str(owner), str(bare), cwd=fx.tmp)
        fx.sh('git', 'remote', 'set-url', 'origin', str(bare), cwd=owner)
        heads_before = fx.sh('git', 'ls-remote', '--heads', str(bare), cwd=fx.tmp)[1]
        # The owner is cloned from this checkout, so it starts on whatever
        # branch this checkout is on -- a local-edit/ branch itself when the
        # check runs on the branch send made (2026-10-04: the deep check of
        # such a branch failed here, counting its own branch as left behind).
        # Only a branch send leaves is a leftover.
        local_before = set(fx.git(owner, 'branch', '--list', 'local-edit/*').split())

        def send(consumer, why):
            return fx.sh(*tool, 'send', '--repo', str(consumer), '--owner-clone',
                         str(owner), '--why', why, cwd=consumer)

        def new_branches():
            now = fx.sh('git', 'ls-remote', '--heads', str(bare), cwd=fx.tmp)[1]
            # Only send's own branches: the owner's basic tier also shares its
            # check receipts on a branch of their own, which is not this.
            return [b for b in (l.split('\t')[1][len('refs/heads/'):]
                                for l in now.splitlines()
                                if l not in heads_before.splitlines())
                    if b.startswith('local-edit/')]

        # No edits: nothing happens, and it says so.
        rc, out = send(repo, 'nothing')
        cases.append(('a consumer with no edits does nothing and says so',
                      rc == 0 and 'nothing to send' in out and not new_branches(),
                      out[-800:]))

        # A leak-gate word in the edit: refused before anything is pushed.
        # base64, as this file's other probes are: the harness is itself
        # scanned by the gate, so the word cannot appear in it literally.
        import base64
        word = base64.b64decode('c2hpdA==').decode()
        f.write_bytes(_insert(base, f'# this {word} is a local fix\n'))
        fx.commit(repo, 'a local fix with a word the gate refuses')
        rc, out = send(repo, 'it crashed')
        leftover = set(fx.git(owner, 'branch', '--list', 'local-edit/*').split()) - local_before - {'*'}
        cases.append(('an edit carrying a leak-gate word is refused before '
                      'anything is pushed, and no branch is left behind',
                      rc == 2 and 'REFUSED before anything left this machine' in out
                      and not new_branches() and not leftover, out[-1500:]))

        # A word only THIS repo's own scrub list knows -- the owner's gate
        # has never heard of it, so only the consumer's side can stop it.
        (repo / 'process').mkdir(exist_ok=True)
        (repo / 'process' / 'scrub_blocklist.txt').write_text(
            'zanzibar-codename\n', encoding='utf-8')
        f.write_bytes(_insert(base, '# works around the zanzibar-codename import\n'))
        fx.commit(repo, 'a local fix naming a private word')
        rc, out = send(repo, 'it crashed')
        cases.append(('a word only this repo\'s scrub list knows is refused by '
                      'this repo\'s side, before anything is pushed',
                      rc == 2 and 'the scrub on this repo\'s side found' in out
                      and 'zanzibar-codename' in out and not new_branches(),
                      out[-1500:]))

        # The real case.
        f.write_bytes(_insert(base, '# a local fix for an empty slug\n'))
        fx.commit(repo, 'fix the show tool on an empty slug')
        rc, out = send(repo, 'precedent_show.py crashed on an empty slug')
        made = new_branches()
        branch = made[0] if len(made) == 1 else ''
        sent = fx.sh('git', '--git-dir', str(bare), 'show',
                     f'{branch}:tools/precedent_show.py', cwd=fx.tmp)[1] if branch else ''
        cases.append(('the branch appears upstream carrying the local change',
                      rc == 0 and branch.startswith('local-edit/')
                      and '# a local fix for an empty slug' in sent,
                      (out + '\n' + '\n'.join(made))[-2000:]))
        cases.append(('...merged onto the landing branch, so upstream\'s change '
                      'since vendoring is kept, not reverted',
                      '# upstream moved on since vendoring' in sent, sent[-400:]))
        cases.append(('...on a branch whose name does not carry the consumer\'s '
                      'name', bool(branch) and 'secret' not in branch
                      and 'client' not in branch, branch))
        cases.append(('...with a paste-ready prompt that asks for a test that '
                      'fails without the fix, and no merge or pull request',
                      'Paste into:' in out and 'a test that fails without the fix' in out
                      and 'No pull request' in out, out[-2000:]))
        cases.append(('...and the consumer\'s edit left in place, said so',
                      b'# a local fix for an empty slug' in f.read_bytes()
                      and 'Your local edit stays in place' in out, out[-800:]))
    finally:
        fx.close()
    bad = [(n, d) for n, ok, d in cases if not ok]
    return (not bad, f'{len(cases)} stated cases',
            '; '.join(f'{n}: {d}' for n, d in bad))


def check_update_vendors_resolves_hook_and_engine_path_edits():
    """The resolution covers every file the engine manifest records a hash
    for, not only tools/: a hook it vendored into .claude/hooks/ and a path
    precedent.json declares under engine_paths -- the same drift and the
    same refusal before 2026-09-29. (Raised by the parallel session that
    built the same resolution; CI workflows stay out, per
    ci-workflow-approved.) The hook case is a real install
    (precedent_install.py), which records its hooks by hash; hooks a
    source's adapter writes are that source's, and not the engine's to
    resolve.

    Negative control, measured 2026-09-29: with engine_edits() reading only
    _local_drift, as it did the first day, both edits stop the refresh
    ("hand-edited since the last seed/refresh") and neither case passes."""
    fx = _LocalEditsFixture('precedent-local-edits-hooks-')
    cases = []
    try:
        # A declared engine path.
        repo = fx.consumer('paths', {'engine_paths': {'SETUP.md': 'docs/SETUP.md'}})
        seeded = fx.seeded_from(repo)
        fx.update(repo, seeded)             # writes and records the path
        fx.commit(repo, 'declared path installed')
        s = repo / 'docs' / 'SETUP.md'
        sb = s.read_bytes() if s.is_file() else b''
        s.write_bytes(_insert(sb, 'A line this repo added.\n', at=2))
        fx.commit(repo, 'a local fix to a declared path')
        rc, out = fx.update(repo, fx.upstream(seeded, {
            'SETUP.md': sb + b'\nUpstream added this line.\n'}))
        sn = s.read_bytes()
        cases.append(('a committed edit to a path declared under engine_paths is '
                      'merged, not refused', bool(sb)
                      and 'hand-edited since the last seed' not in out
                      and b'A line this repo added.' in sn
                      and b'Upstream added this line.' in sn
                      and 'docs/SETUP.md' in _section(out, 'Merged'),
                      (_section(out, 'Merged') or out)[-2000:]))

        # A hook, in a real install.
        proj = fx.tmp / 'installed'
        fx.sh('git', 'init', '-q', '-b', 'main', str(proj), cwd=fx.tmp)
        (proj / 'README.md').write_text('# Notes\n', encoding='utf-8')
        fx.commit(proj, 'before')
        fx.sh(sys.executable, str(ROOT / 'tools' / 'precedent_install.py'), str(proj),
              '--project-name', 'Notes', cwd=ROOT)
        fx.commit(proj, 'installed')
        fx.sh('git', 'clone', '-q', '--bare', str(proj), str(fx.tmp / 'installed.git'),
              cwd=fx.tmp)
        fx.sh('git', 'remote', 'add', 'origin', str(fx.tmp / 'installed.git'), cwd=proj)
        fx.sh('git', 'fetch', '-q', 'origin', cwd=proj)
        m = json.loads((proj / 'tools' / 'ENGINE_MANIFEST.json').read_text(encoding='utf-8'))
        hook = next((n for n in sorted(m.get('hooks_sha256') or {})
                     if n.endswith('.sh')), None)
        cases.append(('the install records a hook by hash', bool(hook),
                      sorted(m.get('hooks_sha256') or {})))
        if hook:
            h = proj / '.claude' / 'hooks' / hook
            hb = h.read_bytes()
            h.write_bytes(_insert(hb, '# a local fix to this hook\n'))
            fx.commit(proj, 'a local fix to a hook')
            rc, out = fx.update(proj, fx.upstream(m['source_commit'], {
                f'templates/harness/claude-code/hooks/{hook}': hb + b'\n# upstream: hook\n'}))
            hn = h.read_bytes()
            cases.append(('a committed edit to a vendored hook is merged, not refused',
                          'hand-edited since the last seed' not in out
                          and b'# a local fix to this hook' in hn
                          and b'# upstream: hook' in hn
                          and f'.claude/hooks/{hook}' in _section(out, 'Merged'),
                          (_section(out, 'Merged') or out)[-2000:]))
    finally:
        fx.close()
    bad = [(n, d) for n, ok, d in cases if not ok]
    return (not bad, f'{len(cases)} stated cases',
            '; '.join(f'{n}: {d}' for n, d in bad))


def check_section0_catalogue_resolves_a_committed_edit():
    """A section 0 install's universal catalogue resolves a committed local
    edit when its own CATALOGUE_SYNC.json names the commit it was synced
    from -- that commit is BASE -- instead of refusing. Without that record
    there is no one BASE to merge with, and the existing cases in
    check_update_vendors_updates_a_section_0_catalogue and
    check_update_vendors_trusts_the_catalogues_own_sync_commit still expect
    the refusal (spec/LOCAL_EDITS_TO_RECEIVED_FILES_PLAN.md).

    Negative control, measured 2026-09-29: against vendor_universal_catalogue
    before this, both cases are refused ("carry local edits")."""
    sys.path.insert(0, str(ROOT / 'tools'))
    try:
        import precedent_update as pu
    finally:
        sys.path.pop(0)
    fx = _LocalEditsFixture('precedent-section0-edit-')
    env = _section0_fixture_env()
    cases = []
    try:
        head = subprocess.run(['git', '-C', str(ROOT), 'rev-parse', 'HEAD'],
                              capture_output=True, text=True).stdout.strip()
        base = subprocess.run(['git', '-C', str(ROOT), 'show',
                               f'{head}:practices/park-it.md'],
                              capture_output=True).stdout
        lines = base.decode().splitlines(True)
        after = next(i for i, l in enumerate(lines) if i and l.strip() == '---') + 2
        record = json.dumps({'source_commit': head}).encode()

        # Merge: this repo added a line near the top, upstream one at the end.
        rev = fx.upstream(head, {'practices/park-it.md': base + b'\nUpstream: end.\n'})
        d = _section0_repo(fx.tmp, {
            'practices/park-it.md': _insert(base, 'Mine: near the top.\n', at=after),
            'CATALOGUE_SYNC.json': record}, env)
        rep = pu.Report()
        ok = pu.vendor_universal_catalogue(d, rep, rev, rev)
        f = d / 'precedent' / 'universal' / 'practices' / 'park-it.md'
        got = f.read_bytes()
        cases.append(('a committed edit merges with upstream\'s change, not refused',
                      ok is True and not rep.left and b'Mine: near the top.' in got
                      and b'Upstream: end.' in got
                      and any(o == 'merged' for o, _r, _t in rep.edits),
                      (rep.left, rep.edits, rep.steps)))

        # Conflict: both changed the same line.
        rev = fx.upstream(head, {'practices/park-it.md':
                                 _replace_line(base, 'Upstream: this line.\n', at=after)})
        d = _section0_repo(fx.tmp, {
            'practices/park-it.md': _replace_line(base, 'Mine: this line.\n', at=after),
            'CATALOGUE_SYNC.json': record}, env)
        rep = pu.Report()
        ok = pu.vendor_universal_catalogue(d, rep, rev, rev)
        f = d / 'precedent' / 'universal' / 'practices' / 'park-it.md'
        took = [t for o, _r, t in rep.edits if o == 'took-upstream']
        cases.append(('a conflict takes upstream\'s version and names the commit '
                      'holding this repo\'s', ok is True and not rep.left
                      and b'Upstream: this line.' in f.read_bytes()
                      and took and 'git show' in took[0], (rep.left, rep.edits)))
    except (OSError, subprocess.CalledProcessError, StopIteration) as e:
        cases.append((f'fixture could not be built ({e})', False, ''))
    finally:
        fx.close()
    bad = [(n, d) for n, ok, d in cases if not ok]
    return (not bad, f'{len(cases)} stated cases',
            '; '.join(f'{n}: {d}' for n, d in bad))


def check_merge_is_judged_by_the_landing_check():
    """A merge the rules made is judged by the repo's own landing-tier check
    at Update Vendors' step 5, not only by its own compile and test run
    (precedent_update.check_with_merge_fallback, 2026-09-29): red with the
    merge in place and green without it, upstream's version stands and the
    report says why; red either way, the merge is put back, since it was
    not the cause. The check itself is stubbed here, so each branch is
    decided by the file's content alone.

    Negative control, measured 2026-09-29: with step 5 calling
    judged_as_committed() directly, as it did before, the merged file is
    never taken back and the first case fails."""
    import tempfile
    sys.path.insert(0, str(ROOT / 'tools'))
    try:
        import precedent_update as pu
    finally:
        sys.path.pop(0)
    tmp = pathlib.Path(tempfile.mkdtemp(prefix='precedent-merge-judged-'))
    cases = []
    real = pu.judged_as_committed
    try:
        repo = tmp / 'r'
        repo.mkdir()
        g = lambda *a: subprocess.run(['git', '-C', str(repo), *a],
                                      capture_output=True, text=True)
        g('init', '-q', '-b', 'main')
        g('config', 'user.email', 't@t'); g('config', 'user.name', 't')
        f = repo / 'tools' / 'x.py'
        f.parent.mkdir()
        f.write_text('mine = 1\n', encoding='utf-8')
        g('add', '-A'); g('commit', '-qm', 'local edit')
        merged, new = b'mine = 1\nMERGED = 1\n', b'theirs = 1\n'

        def run(red_when):
            f.write_bytes(merged)
            rep = pu.Report()
            rep.edits = [(pu.le.MERGED, 'tools/x.py', 'merged')]
            rep.merges = {'tools/x.py': (merged, new)}
            pu.judged_as_committed = lambda _r, _a: (
                (1, 'red') if red_when(f.read_bytes()) else (0, 'green'))
            rc, _out = pu.check_with_merge_fallback(repo, rep, [], 'check for pre-staging')
            return rc, rep

        rc, rep = run(lambda data: b'MERGED' in data)
        cases.append(('red with the merge and green without: upstream\'s version '
                      'stands, reported as rule 3 with the reason',
                      rc == 0 and f.read_bytes() == new
                      and rep.edits[0][0] == pu.le.TOOK_UPSTREAM
                      and 'failed with the merge in place' in rep.edits[0][2],
                      (rc, f.read_bytes(), rep.edits)))
        rc, rep = run(lambda data: True)
        cases.append(('red either way: the merge is put back and the failure '
                      'reported on it', rc == 1 and f.read_bytes() == merged
                      and rep.edits[0][0] == pu.le.MERGED
                      and any('not the cause' in o for _n, o in rep.steps),
                      (rc, f.read_bytes(), rep.steps)))
    finally:
        pu.judged_as_committed = real
        shutil.rmtree(tmp, ignore_errors=True)
    bad = [(n, d) for n, ok, d in cases if not ok]
    return (not bad, f'{len(cases)} stated cases',
            '; '.join(f'{n}: {d}' for n, d in bad))


def check_update_judges_the_committed_tree():
    """precedent_update's deep check judges the staged update as it will be
    committed, then leaves the index and working tree exactly as it found
    them (2026-09-27: a consumer's update failed its deep check twice on
    staged-only effects -- a change-scope check reading every materialized
    practice as the repo's own prose, and a shipped test cloning HEAD -- and
    passed the moment the same tree was committed)."""
    import tempfile
    sys.path.insert(0, str(ROOT / 'tools'))
    try:
        import precedent_update as pu
    finally:
        sys.path.pop(0)
    name = 'Update Vendors judges the staged update as committed, and undoes the commit'
    cases = []
    tmp = pathlib.Path(tempfile.mkdtemp(prefix='judged-as-committed-'))
    env_keep = {k: os.environ.get(k) for k in ('GIT_CONFIG_GLOBAL', 'GIT_AUTHOR_NAME',
                                                'GIT_AUTHOR_EMAIL', 'GIT_COMMITTER_NAME',
                                                'GIT_COMMITTER_EMAIL', 'PRECEDENT_ALLOW_ANY_AUTHOR')}
    os.environ.update({'GIT_CONFIG_GLOBAL': str(tmp / 'gitconfig'), 'GIT_AUTHOR_NAME': 't',
                       'GIT_AUTHOR_EMAIL': 't@t', 'GIT_COMMITTER_NAME': 't',
                       'GIT_COMMITTER_EMAIL': 't@t', 'PRECEDENT_ALLOW_ANY_AUTHOR': '1'})

    def git(*a):
        return subprocess.run(['git', '-C', str(repo), *a], capture_output=True, text=True)
    try:
        repo = tmp / 'r'
        subprocess.run(['git', 'init', '-q', '-b', 'main', str(repo)], capture_output=True)
        (repo / 'a.md').write_text('one\n', encoding='utf-8')
        (repo / 'b.md').write_text('keep\n', encoding='utf-8')
        git('add', '-A')
        git('commit', '-qm', 'base')
        head = git('rev-parse', 'HEAD').stdout.strip()
        (repo / 'a.md').write_text('two\n', encoding='utf-8')
        git('add', 'a.md')
        (repo / 'b.md').write_text('an unstaged edit\n', encoding='utf-8')
        probe = [sys.executable, '-c',
                 'import subprocess,sys;'
                 'g=lambda *a: subprocess.run(["git",*a],capture_output=True,text=True);'
                 'ok = g("show","HEAD:a.md").stdout=="two\\n" and '
                 'g("diff","--cached","--quiet").returncode==0;'
                 'sys.exit(0 if ok else 1)']
        rc, out = pu.judged_as_committed(repo, probe)
        cases.append(('the check sees the staged update committed, with nothing staged',
                      rc == 0, out[-400:]))
        cases.append(('...and afterwards HEAD is where it was, the update still staged, '
                      'the unstaged edit untouched',
                      git('rev-parse', 'HEAD').stdout.strip() == head
                      and git('diff', '--cached', '--name-only').stdout.split() == ['a.md']
                      and (repo / 'b.md').read_text() == 'an unstaged edit\n', ''))
        rc, out = pu.judged_as_committed(repo, [sys.executable, '-c', 'raise SystemExit(1)'])
        cases.append(('a red check is reported red, and the commit is still undone',
                      rc == 1 and git('rev-parse', 'HEAD').stdout.strip() == head
                      and git('diff', '--cached', '--name-only').stdout.split() == ['a.md'],
                      out[-400:]))
        hook = repo / '.git' / 'hooks' / 'pre-commit'
        hook.write_text('#!/bin/sh\necho refused-by-hook >&2\nexit 1\n', encoding='utf-8')
        hook.chmod(0o755)
        rc, out = pu.judged_as_committed(repo, [sys.executable, '-c', 'pass'])
        cases.append(("a commit the repo's hooks refuse is reported, never worked around",
                      rc != 0 and 'could not be committed' in out
                      and git('rev-parse', 'HEAD').stdout.strip() == head, out[-400:]))
        hook.unlink()
        git('reset', '-q')
        rc, out = pu.judged_as_committed(repo, [sys.executable, '-c', 'pass'])
        cases.append(('with nothing staged the check runs as it is, and nothing is committed',
                      rc == 0 and git('rev-parse', 'HEAD').stdout.strip() == head, out[-400:]))
    finally:
        for k, v in env_keep.items():
            if v is None:
                os.environ.pop(k, None)
            else:
                os.environ[k] = v
        shutil.rmtree(tmp, ignore_errors=True)
    failed = [f'{n}: {d}' for n, ok, d in cases if not ok]
    check(f'{name} ({len(cases)} stated cases)', not failed, '; '.join(failed))


def check_update_adopts_engine_written_ahead():
    """precedent_update stages, as its own, engine files a source refresh
    wrote before it ran -- but only when every one of them hashes to what
    the pinned manifest records (2026-09-27: on all four of Morgan's sets
    the refresh had already written the pinned engine, the update said
    "already current", left both files unstaged as someone else's, and
    reported DONE on an update that would have committed nothing)."""
    import hashlib
    import tempfile
    sys.path.insert(0, str(ROOT / 'tools'))
    try:
        import precedent_update as pu
    finally:
        sys.path.pop(0)
    name = 'Update Vendors adopts the pinned engine a refresh wrote ahead of it'
    cases = []
    tmp = pathlib.Path(tempfile.mkdtemp(prefix='adopt-engine-'))
    try:
        repo = tmp / 'r'
        (repo / 'tools').mkdir(parents=True)
        (repo / '.claude' / 'hooks').mkdir(parents=True)
        (repo / 'bootstrap').mkdir()
        files = {'tools/x.py': 'x = 1\n', '.claude/hooks/g.sh': 'exit 0\n',
                 'bootstrap/b.sh': 'true\n', 'tools/y.py': 'y = 1\n'}
        for rel, text in files.items():
            (repo / rel).write_text(text, encoding='utf-8')
        sha = lambda t: hashlib.sha256(t.encode()).hexdigest()
        pin = 'a' * 40

        def manifest(commit=pin, x=files['tools/x.py']):
            (repo / 'tools' / 'ENGINE_MANIFEST.json').write_text(json.dumps({
                'source_commit': commit,
                'sha256': {'x.py': sha(x), 'y.py': sha(files['tools/y.py'])},
                'hooks_sha256': {'g.sh': sha(files['.claude/hooks/g.sh'])},
                'engine_paths_sha256': {'bootstrap/b.sh': sha(files['bootstrap/b.sh'])},
            }), encoding='utf-8')
        m = 'tools/ENGINE_MANIFEST.json'
        before = {m, 'tools/x.py', '.claude/hooks/g.sh', 'bootstrap/b.sh', 'notes.md'}
        manifest()
        got = pu.adopt_engine_output(repo, before, pin)
        cases.append(('the manifest and every uncommitted file it tracks, matching its '
                      'hashes, are taken as the update\'s -- and nothing it does not track',
                      sorted(got) == sorted([m, 'tools/x.py', '.claude/hooks/g.sh',
                                             'bootstrap/b.sh']), got))
        manifest(x='x = 2\n')
        got = pu.adopt_engine_output(repo, before, pin)
        cases.append(('one file that differs from the manifest means nothing is taken',
                      got == [], got))
        manifest(commit='b' * 40)
        got = pu.adopt_engine_output(repo, before, pin)
        cases.append(('a manifest naming another commit than the pin is not the update\'s',
                      got == [], got))
        manifest()
        got = pu.adopt_engine_output(repo, before - {m}, pin)
        cases.append(('a committed manifest takes nothing: the refresh did not run ahead',
                      got == [], got))
    finally:
        shutil.rmtree(tmp, ignore_errors=True)
    failed = [f'{n}: {d}' for n, ok, d in cases if not ok]
    check(f'{name} ({len(cases)} stated cases)', not failed, '; '.join(failed))


def check_acronym_scan_skips_wrapped_code_spans():
    """doc_lint's acronym scan -- the one detector the acronyms-glossary gate
    shares -- skips a code span that wraps onto the next line, as it skips
    one on a single line (2026-09-28: `--changed-since HEAD --staged`,
    wrapped in vendor-update-runbook, failed a consuming repo's Update
    Vendors on HEAD). Both directions: prose around the span, a fenced
    block, and a paragraph break still end or bound it."""
    sys.path.insert(0, str(ROOT / 'tools'))
    try:
        import doc_lint as dl
    finally:
        sys.path.pop(0)
    name = 'the acronym scan skips code spans that wrap across lines'
    toks = lambda t: [tok for _i, tok in dl.scan_unglossed(t, set(), 'x.md')
                      if tok in ('QZXA', 'QZXB', 'QZXC', 'QZXD')]
    cases = [
        ('a span wrapping onto the next line hides its second half',
         toks('Run `tool --flag\nQZXA --staged` now.\n') == []),
        ('prose after the wrapped span is still scanned',
         toks('Run `tool --flag\nx --staged` then QZXB.\n') == ['QZXB']),
        ('a paragraph break ends a span, so the next paragraph is scanned',
         toks('An open ` tick.\n\nQZXC and a close ` tick.\n') == ['QZXC']),
        ('a fenced block is not joined to prose around it',
         toks('Open `\n```\ncode\n```\nQZXD` here.\n') == ['QZXD']),
        ('line numbers still point at the right line',
         [i for i, tok in dl.scan_unglossed('a `b\nc` d\nQZXA\n', set(), 'x.md')
          if tok == 'QZXA'] == [3]),
    ]
    failed = [n for n, ok in cases if not ok]
    check(f'{name} ({len(cases)} stated cases)', not failed, '; '.join(failed))


def check_lint_runs_the_hosts_shim():
    """A consumer configures doc_lint from a host shim, but the push check
    runs the engine file directly, so the consumer's settings never reached
    its gate (2026-10-04: a folder the consumer had exempted failed its
    push). A consumer names its shim in tools/doc_lint_host.json, and
    running the engine runs the shim. Both directions: with no host file
    the engine runs as itself."""
    import tempfile, shutil
    name = 'doc_lint hands off to the host shim a consumer names'
    env = dict(os.environ, GIT_AUTHOR_NAME='T', GIT_AUTHOR_EMAIL='t@example.com',
               GIT_COMMITTER_NAME='T', GIT_COMMITTER_EMAIL='t@example.com')
    cases = []
    with tempfile.TemporaryDirectory() as td:
        repo = pathlib.Path(td)
        subprocess.run(['git', 'init', '-q', '-b', 'main', str(repo)], env=env)
        (repo / 'tools').mkdir()
        for f in ('doc_lint.py', 'frontmatter_yaml.py', 'generated_blocks.py'):
            shutil.copy(ROOT / 'tools' / f, repo / 'tools' / f)
        (repo / 'tools' / 'ENGINE_MANIFEST.json').write_text('{}\n')
        (repo / 'host').mkdir()
        (repo / 'host' / 'lint_shim.py').write_text(
            'import sys\nprint("HOST SHIM RAN", sys.argv[1:])\nsys.exit(0)\n')
        run = lambda: subprocess.run([sys.executable, 'tools/doc_lint.py', '--all'],
                                     cwd=repo, capture_output=True, text=True, env=env)
        r = run()
        cases.append(('with no host file the engine runs as itself',
                      'HOST SHIM RAN' not in r.stdout))
        (repo / 'tools' / 'doc_lint_host.json').write_text('{"shim": "host/lint_shim.py"}\n')
        r = run()
        cases.append(('with a host file, running the engine runs the shim, with its arguments',
                      "HOST SHIM RAN ['--all']" in r.stdout and r.returncode == 0))
        (repo / 'tools' / 'doc_lint_host.json').write_text('{"shim": "host/missing.py"}\n')
        r = run()
        cases.append(('a host file naming a missing shim fails loudly',
                      r.returncode != 0 and 'does not exist' in (r.stdout + r.stderr)))
    failed = [n for n, ok in cases if not ok]
    check(f'{name} ({len(cases)} stated cases)', not failed, '; '.join(failed))


def check_lint_refuses_an_open_item_waiting_on_an_upstream_fix():
    """An open item about a fix in another repository has to link the pull
    request that makes it (practice: todo-is-a-handoff, 2026-10-06: in one
    consumer four such items sat for one to two weeks, each an hour's fix).
    doc_lint refuses one at the commit; it leaves alone the same item with a
    PR link, an item blocked on an outside quote, and a closed item."""
    import tempfile, shutil
    name = 'doc_lint refuses an open item waiting on an upstream fix'
    env = _fixture_git_env()
    head = ('---\nslug: {slug}\nkind: manual\nstatus: {status}\n'
            'blocked_on: {blocked}\nnoted: 2026-10-06\n---\n## What\n\n{body}\n')
    items = {
        'vendored-path': ('open', 'null', 'The check in tools/doc_lint.py '
                          'misreads a fence; needs a change upstream.', True),
        'with-pr-link': ('open', 'null', 'The check in tools/doc_lint.py '
                         'misreads a fence; fixed in '
                         'https://github.com/example/Engine/pull/12, waiting '
                         'on its review.', False),
        'outside-quote': ('open', 'vendor quotes from two cell makers',
                          'Needs source access to example.com for the '
                          'price sheet.', False),
        'closed': ('done', 'null', 'The check in tools/doc_lint.py misread '
                   'a fence.', False),
        'source-in-reason': ('open', 'push access to some-set', 'A rule '
                             'there is worded wrong.', True),
    }
    cases = []
    with tempfile.TemporaryDirectory() as td:
        repo = pathlib.Path(td) / 'consumer'
        (repo / 'tools').mkdir(parents=True)
        subprocess.run(['git', 'init', '-q', '-b', 'main', str(repo)], env=env)
        for f in ('doc_lint.py', 'frontmatter_yaml.py', 'generated_blocks.py',
                  'precedent_engine_freshness.py', 'precedent_resolve.py'):
            shutil.copy(ROOT / 'tools' / f, repo / 'tools' / f)
        (repo / 'tools' / 'ENGINE_MANIFEST.json').write_text(json.dumps(
            {'source_repo': 'https://github.com/example/Engine',
             'source_branch': 'main', 'source_commit': 'x',
             'files': ['doc_lint.py']}))
        (repo / 'precedent.json').write_text(json.dumps({'sources': [
            {'level': 'shared', 'name': 'some-set', 'path': '../some-set'}]}))
        (repo / 'todo').mkdir()
        for slug, (status, blocked, body, _fires) in items.items():
            (repo / 'todo' / f'todo-2026-10-06-{slug}.md').write_text(
                head.format(slug=slug, status=status, blocked=blocked, body=body))
        for slug, (_s, _b, _body, fires) in items.items():
            rel = f'todo/todo-2026-10-06-{slug}.md'
            r = subprocess.run([sys.executable, 'tools/doc_lint.py', rel],
                               cwd=repo, capture_output=True, text=True, env=env)
            fired = (r.returncode == 1 and 'WAITING ON AN UPSTREAM FIX' in r.stdout
                     and 'tools/upstream_fix.py' in r.stdout)
            quiet = r.returncode == 0 and 'UPSTREAM FIX' not in r.stdout
            cases.append((f'{slug}: {"fires" if fires else "passes"}',
                          fired if fires else quiet))
    failed = [n for n, ok in cases if not ok]
    check(f'{name} ({len(cases)} stated cases)', not failed, '; '.join(failed))


def check_upstream_fix_sets_up_the_fix_in_the_source():
    """tools/upstream_fix.py PATH, the one command the doc_lint finding above
    names: on a planted source repo, its clone and a consumer vendoring one
    file, it opens a branch in the clone off the landing branch, never edits
    the copy, refuses a file of the consumer's own and a dirty clone."""
    r = subprocess.run([sys.executable, str(ROOT / 'tools' / 'upstream_fix.py'),
                        '--self-check'], capture_output=True, text=True,
                       env=_fixture_git_env())
