def check_very_deep_check_finds_vendored_surplus():
    """very_deep_check.py's VENDORED SURPLUS helpers, planted both ways.
    Upstream: a file nothing else that ships names is UNNAMED, and one named
    by another shipped file, by import, or through its folder is not.
    Downstream: a consumer whose copy holds gotchas/ and a byte-identical
    second copy of its own tools/ file is reported for both; the same
    consumer after the copy is trimmed is quiet. The real case is
    2026-09-30's: a consumer's process/upstream/ held 543 files, the
    engine among them twice, and the section before this one checked only
    the checkout the run started in."""
    import tempfile
    sys.path.insert(0, str(ROOT / 'tools'))
    import very_deep_check as vdc
    cases = []
    d = pathlib.Path(tempfile.mkdtemp(prefix='precedent-surplus-'))
    try:
        up = d / 'up'
        for rel, text in {
                'tools/used.py': 'import helper\n',
                'tools/helper.py': 'X = 1\n',
                'tools/orphan.py': 'print("nobody runs me")\n',
                'templates/kit/deep/a.txt': 'a\n',
                'INSTALL.md': 'copy templates/kit/deep/ and run used.py\n',
                }.items():
            (up / rel).parent.mkdir(parents=True, exist_ok=True)
            (up / rel).write_text(text, encoding='utf-8')
        shipped = {rel: (rel, 'engine') for rel in
                   ('tools/used.py', 'tools/helper.py', 'tools/orphan.py',
                    'templates/kit/deep/a.txt', 'INSTALL.md')}
        unnamed = vdc._named_anywhere_else(shipped, up)
        cases.append(('only the file nothing names is UNNAMED',
                      unnamed == ['tools/orphan.py'], unnamed))

        body = 'def main():\n    return 0\n' * 20
        c = d / 'consumer'
        for rel, text in {
                'tools/checkin.py': body,
                'tools/ENGINE_MANIFEST.json': '{"kind": "consumer"}\n',
                'process/upstream/tools/checkin.py': body,
                'process/upstream/spec/PLAN.md': 'a plan\n',
                'process/upstream/practices/p.md': 'a rule\n',
                }.items():
            (c / rel).parent.mkdir(parents=True, exist_ok=True)
            (c / rel).write_text(text, encoding='utf-8')
        subprocess.run(['git', '-C', str(c), 'init', '-q'], capture_output=True)
        subprocess.run(['git', '-C', str(c), 'add', '-A'], capture_output=True)
        found = vdc._consumer_surplus(c)
        cases.append(('a consumer holding spec/ and a second tools/ copy '
                      'is reported for both',
                      len(found) == 2 and 'spec/ 1' in found[0]
                      and 'tools/ 1' in found[0]
                      and 'held twice' in found[1], found))
        subprocess.run(['git', '-C', str(c), 'rm', '-q', '-r', '-f',
                        'process/upstream/tools', 'process/upstream/spec'],
                       capture_output=True)
        found = vdc._consumer_surplus(c)
        cases.append(('the trimmed consumer is quiet', found == [], found))
        cases.append(('the consumer is found beside the checkout',
                      any(p.name == 'consumer' for _n, p in
                          vdc._consumers_in_session(up)), ''))
    finally:
        shutil.rmtree(d, ignore_errors=True)
    bad = [(n, det) for n, ok, det in cases if not ok]
    check('the very deep check names what a consumer receives that it has no '
          'use for, or holds twice',
          not bad, '; '.join(f'{n}: {det!r}' for n, det in bad))


def check_every_file_is_decided_by_a_vendoring_rule():
    """tools/checkin.py's VENDORING_RULES decide every file: a path in a new
    top-level place is UNDECIDED (no rule, left out of the copy), an
    exception inside a shipped folder wins over the folder, and this repo
    as it stands has no undecided file. Morgan, 2026-09-30: "make sure that
    *every new file* is evaluated to see if it should be vendored in or
    not"."""
    sys.path.insert(0, str(ROOT / 'tools'))
    import checkin
    cases = []
    rule = checkin.vendoring_rule('newplace/notes.md')
    cases.append(('a file in a new top-level place has no rule',
                  rule is None, rule))
    cases.append(('an undecided file stays out of the copy',
                  not checkin._in_copy('newplace/notes.md', carries_tools=True),
                  ''))
    rule = checkin.vendoring_rule('tools/verify_harness.py')
    cases.append(('the test suite stays, though tools/ ships',
                  rule is not None and rule[1] is False, rule))
    rule = checkin.vendoring_rule('practices/any-rule.md')
    cases.append(('a practice ships', rule is not None and rule[1], rule))
    r = subprocess.run([sys.executable, str(ROOT / 'tools' / 'precedent_check.py'),
                        '--only', 'vendoring-decided'],
                       capture_output=True, text=True, cwd=str(ROOT))
    cases.append(('this repo has no undecided file',
                  r.returncode == 0 and ' 0 violated' in r.stdout,
                  r.stdout[-300:] + r.stderr[-300:]))
    bad = [(n, det) for n, ok, det in cases if not ok]
    check('every file is decided by a vendoring rule: ships or stays, and a '
          'new place is undecided until someone writes the rule',
          not bad, '; '.join(f'{n}: {det!r}' for n, det in bad))


def check_show_loads_a_practice_from_a_declared_source():
    """precedent_show.py finds a practice that lives in a shared or an
    individual source the repo declares, labels its level as the gates do,
    and still fails loudly on a slug no source has (2026-09-30: the merge
    gate listed shared and individual practices by name, and this tool
    answered "unknown slug" for each). Fixture sources only, built here;
    never the real private sets."""
    import tempfile
    tmp = pathlib.Path(tempfile.mkdtemp(prefix='precedent-show-sources-'))
    cases = []
    try:
        def practice(d, slug, rule):
            (d / 'practices').mkdir(parents=True, exist_ok=True)
            (d / 'practices' / f'{slug}.md').write_text(
                f'---\nslug:        {slug}\ntitle:       {slug}\n'
                f'tier:        on-demand\nstatus:      active\n---\n'
                f'## Rule\n{rule}\n', encoding='utf-8')
        repo, shared, ind = tmp / 'repo', tmp / 'zzz-shared', tmp / 'zzz-individual'
        practice(repo, 'zzz-own-rule', 'The repo\'s own rule.')
        practice(shared, 'zzz-shared-rule', 'The shared set says this.')
        practice(ind, 'zzz-individual-rule', 'The individual set says this.')
        (repo / 'precedent.json').write_text(json.dumps({
            'format_version': 1, 'sources': [
                {'level': 'universal', 'name': 'precedent', 'path': '.'},
                {'level': 'shared', 'name': 'zzz-shared',
                 'path': '../zzz-shared'}]}), encoding='utf-8')
        cfg = tmp / 'user.json'
        cfg.write_text(json.dumps({'individual': {
            'name': 'zzz-individual', 'path': str(ind)}}), encoding='utf-8')
        env = dict(os.environ, PRECEDENT_USER_CONFIG=str(cfg))

        def show(*slugs):
            r = subprocess.run([sys.executable,
                                str(ROOT / 'tools' / 'precedent_show.py'),
                                '--repo', str(repo), *slugs],
                               capture_output=True, text=True, env=env)
            return r.returncode, r.stdout + r.stderr
        rc, out = show('zzz-shared-rule', 'zzz-individual-rule')
        cases.append(('a shared and an individual practice both load, each '
                      'labelled with its level',
                      rc == 0 and '### zzz-shared-rule (shared)' in out
                      and 'The shared set says this.' in out
                      and '### zzz-individual-rule (individual)' in out
                      and 'The individual set says this.' in out, out[-500:]))
        rc, out = show('zzz-own-rule')
        cases.append(("the repo's own practice still loads unlabelled",
                      rc == 0 and '### zzz-own-rule\n' in out, out[-300:]))
        rc, out = show('zzz-no-such-rule')
        cases.append(('a slug no source has still fails, by name',
                      rc != 0 and 'zzz-no-such-rule' in out, out[-300:]))
    finally:
        shutil.rmtree(tmp, ignore_errors=True)
    bad = [(n, det) for n, ok, det in cases if not ok]
    check('precedent_show.py loads a practice from a declared shared or '
          'individual source', not bad,
          '; '.join(f'{n}: {det!r}' for n, det in bad))


def check_session_file_warning_does_not_count_against_its_ceiling():
    """The over-target warning precedent_session_practices.py writes into
    .precedent/SESSION_PRACTICES.md is left out when the file is measured
    against its ceiling, by precedent_check.py and session_load_trend.py
    alike, and nothing else is. precedent-individual, 2026-09-30: 5,155
    tokens without the warning, 5,211 with it, against a 5,200 ceiling, so
    every Promote refused on a file only the warning pushed over."""
    import tempfile
    sys.path.insert(0, str(ROOT / 'tools'))
    import build_views as bv
    import precedent_session_practices as psp
    import precedent_check as pc
    import session_load_trend as slt
    rel = '.precedent/SESSION_PRACTICES.md'
    tmp = pathlib.Path(tempfile.mkdtemp(prefix='precedent-session-warning-'))
    cases = []
    try:
        (tmp / 'tools').mkdir()
        body = '# Practices in force here\n\n' + 'A rule a session reads. ' * 60 + '\n'
        n = bv._approx_tokens(body)
        (tmp / 'tools' / 'session_load_budgets.json').write_text(json.dumps(
            {'surfaces': {rel: {'target': n // 2, 'ceiling': n + 5}}}),
            encoding='utf-8')
        written = psp._with_target_warning(tmp, body)
        cases.append(('over target, the file carries the warning',
                      psp.TARGET_WARNING_MARK in written, written[:200]))
        cases.append(('and the warning alone takes it over its ceiling',
                      bv._approx_tokens(written) > n + 5,
                      bv._approx_tokens(written)))
        for name, measure in (('precedent_check', pc._as_measured),
                              ('session_load_trend', slt.as_measured)):
            got = measure(rel, written)
            cases.append((f'{name} measures it without the warning, exactly '
                          f'the content', got == body, got[:200]))
            cases.append((f'{name} leaves every other surface as it is',
                          measure('AGENTS.md', written) == written, ''))
    finally:
        shutil.rmtree(tmp, ignore_errors=True)
    bad = [(n_, det) for n_, ok, det in cases if not ok]
    check('the session file\'s over-target warning never counts against its '
          'ceiling', not bad, '; '.join(f'{n_}: {det!r}' for n_, det in bad))


def check_routing_audit_coverage():
    """routing_audit.py's coverage() -- the mechanical half of the routing
    audit (practices/routing-audit.md) -- against real practices already in
    the catalogue, not a synthetic fixture: PRACTICES_DIR is hardcoded in
    routing_audit.py (it reads the real tree, deliberately, the same way
    this file's own PRACTICES_DIR is), so the planted case is choosing real
    judgment-only practices with known narrow globs and asserting on their
    known, checkable behavior -- the checkable-gets-checked discipline
    applied to the routing audit's own tool, per spec/UNBUILT_PLAN_ITEMS.md
    ("Part 2"), which found this half had never actually been exercised.
    """
    import importlib.util
    spec = importlib.util.spec_from_file_location(
        '_ra', ROOT / 'tools' / 'routing_audit.py')
    ra = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(ra)

    practices = {slug: globs for slug, globs, _rule, _f in ra.judgment_only_practices()}
    problems = []

    def want(slug):
        if slug not in practices:
            problems.append(f"fixture practice {slug!r} is no longer judgment-only "
                            f"or no longer active -- pick a replacement fixture")
            return False
        return True

    # A narrow glob that should match: lead-with-what-it-is names README.md
    # explicitly (not '**').
    if want('lead-with-what-it-is'):
        hits = {slug for slug, _path in ra.coverage(['README.md'])}
        if 'lead-with-what-it-is' not in hits:
            problems.append("coverage(['README.md']) missed lead-with-what-it-is, "
                            "whose applies_to names README.md directly")

    # A file none of the narrow-glob fixtures should match -- catches a glob
    # implementation that over-matches (e.g. '**' leaking through, or a bad
    # path-matching call) as well as one that under-matches.
    unrelated_hits = {slug for slug, _path in ra.coverage(['tools/verify_harness.py'])}
    for slug in ('lead-with-what-it-is', 'pr-template-honest-gates', 'parallel-artifact-ledger'):
        if slug in practices and slug in unrelated_hits:
            problems.append(f"coverage(['tools/verify_harness.py']) false-positived "
                            f"on {slug}, whose applies_to does not match this path")

    # The practice's own stated design: applies_to: ['**'] carries no routing
    # signal (routing_audit.coverage() drops it deliberately -- "narrow = [g
    # for g in globs if g != '**']; if not narrow: continue") and must never
    # surface as a coverage hit for any file, even one everything matches.
    if want('registry-source-of-truth'):
        wildcard_hits = {slug for slug, _path in ra.coverage(['README.md', 'AGENTS.md'])}
        if 'registry-source-of-truth' in wildcard_hits:
            problems.append("coverage() surfaced registry-source-of-truth (applies_to: "
                            "['**']) as a hit -- '**' is not a routing signal and must "
                            "be excluded, per the tool's own docstring")

    # A glob scoped to a directory that does not include the probe file.
    if want('pr-template-honest-gates'):
        hits = {slug for slug, _path in ra.coverage(['.github/pull_request_template.md'])}
        if 'pr-template-honest-gates' not in hits:
            problems.append("coverage(['.github/pull_request_template.md']) missed "
                            "pr-template-honest-gates")

    check('routing audit coverage() matches narrow applies_to globs correctly, '
          'in both directions, and drops \'**\' as a non-signal (5 stated cases '
          'against real catalogue fixtures)',
          not problems, '; '.join(problems))


def check_parallel_artifact_ledger_fires():
    """precedent_check.py's parallel-artifact-ledger check (added 2026-09-05),
    stated cases against a scratch git repo -- checkable-gets-checked applied
    to the check the audit-judgment eval found missing (templates/harness/
    LEDGER.md existed with no audit backing its own closing claim that "any
    marked date without a complete ledger row fails").
    """
    import importlib.util, shutil, tempfile

    tmp = pathlib.Path(tempfile.mkdtemp(prefix='precedent-ledgercheck-'))
    try:
        member = tmp / 'templates' / 'harness' / 'claude-code'
        member.mkdir(parents=True)
        subprocess.run(['git', 'init', '-q'], cwd=tmp, check=True)
        subprocess.run(['git', 'config', 'user.email', 'harness@example.com'], cwd=tmp, check=True)
        subprocess.run(['git', 'config', 'user.name', 'harness'], cwd=tmp, check=True)
        (tmp / 'root.txt').write_text('root\n', encoding='utf-8')
        subprocess.run(['git', 'add', '-A'], cwd=tmp, check=True)
        subprocess.run(['git', 'commit', '-q', '-m', 'root'], cwd=tmp, check=True)
        # Two more commits, because the check excludes two kinds of
        # inception: the repo's own root commit, and the commit that
        # FIRST created a given member directory (TODO.md's
        # closed and pruned from TODO.md, was the `ledger-root-commit-exemption` item --
        # a family coming into existence has nothing for its other
        # members to have transferred from). So the commit under test has
        # to be the third: a real later CHANGE to an existing member.
        (member / 'hooks.txt').write_text('v1\n', encoding='utf-8')
        subprocess.run(['git', 'add', '-A'], cwd=tmp, check=True)
        subprocess.run(['git', 'commit', '-q', '-m', 'create the family'], cwd=tmp, check=True)
        inception_commit = subprocess.run(
            ['git', 'rev-parse', 'HEAD'], cwd=tmp, capture_output=True, text=True
        ).stdout.strip()
        (member / 'hooks.txt').write_text('v2\n', encoding='utf-8')
        subprocess.run(['git', 'add', '-A'], cwd=tmp, check=True)
        subprocess.run(['git', 'commit', '-q', '-m', 'change a member'], cwd=tmp, check=True)
        member_commit = subprocess.run(
            ['git', 'rev-parse', 'HEAD'], cwd=tmp, capture_output=True, text=True
        ).stdout.strip()

        ledger_dir = tmp / 'templates' / 'harness'
        ledger_path = ledger_dir / 'LEDGER.md'

        spec = importlib.util.spec_from_file_location(
            '_pc_ledger', ROOT / 'tools' / 'precedent_check.py')
        pc = importlib.util.module_from_spec(spec)
        spec.loader.exec_module(pc)
        pc.ROOT = tmp
        pc._git = lambda *args, cwd=None: subprocess.run(
            ['git', *args], cwd=str(cwd or tmp), capture_output=True, text=True)
        fn = pc.CHECKS['parallel-artifact-ledger']['fn']

        # A real dated row, not a bare hash on a line of its own: the check
        # credits a commit only when it is named in a ROW's `Originating
        # change` cell, so a fixture writing the hash loose in the file was
        # passing on the presence half's old whole-file match and stopped
        # meaning anything the moment that half was keyed on the cell
        # (2026-09-11).
        def _row(commit_hash):
            return (f'| 2026-01-01 | [`{commit_hash[:7]}`]'
                    f'(https://example.invalid/{commit_hash}) — planted '
                    f'| applied | n/a | n/a |\n')

        no_ledger = fn(None)
        ledger_path.write_text('no commit hashes here\n', encoding='utf-8')
        unreferenced = fn(None)
        ledger_path.write_text(_row(member_commit), encoding='utf-8')
        referenced = fn(None)
        # The distinction both halves now share: a commit named only in
        # another row's PROSE is a citation, not that row's own change, so
        # it is not ledgered. Without this case the presence half can slide
        # back to matching the whole file and nothing fails.
        ledger_path.write_text(
            '| 2026-01-01 | [`0000000`](https://example.invalid/0000000) — '
            f'planted | applied, same reason as the `{member_commit[:7]}` '
            'row | n/a | n/a |\n', encoding='utf-8')
        cited_only = fn(None)

        # A ledger naming ONLY the later change: the inception commit must
        # not be demanded. Before this exemption, f2078d6 -- the commit
        # that created all three real harness adapters, five weeks before
        # the ledger file existed -- failed every pull request's CI until
        # somebody hand-wrote a row saying "no transfer verdict
        # applicable".
        inception_exempt = [f for f in referenced
                            if inception_commit[:7] in str(f)]

        cases = [
            ("missing LEDGER.md is a finding", len(no_ledger) == 1),
            ("a member directory's own inception commit needs no row",
             not inception_exempt),
            ("a ledger with no reference to the commit is a finding",
             len(unreferenced) == 1),
            ("a ledger row naming the commit in its change cell clears "
             "the finding", referenced == []),
            ("a commit named only in another row's prose is NOT ledgered",
             len(cited_only) == 1),
        ]
        bad = [n for n, ok in cases if not ok]
        check(f"parallel-artifact-ledger check fires ({len(cases)} stated cases: "
              f"no ledger, ledger missing the commit, a row naming it in "
              f"its change cell, a prose citation not counting as a row, "
              f"a family's own inception commit needing no row)",
              not bad, '; '.join(bad))
    finally:
        shutil.rmtree(tmp, ignore_errors=True)


def check_loader_block_advertises_only_live_channels():
    """A generated loader block must not name a channel this source does not fill.

    2026-09-06, precedent-team-tms: that set deleted its bootstrap
    placeholder, leaving one resident practice and no on-demand ones. Its
    generated block still carried an occasion index rendering as an empty
    ``` ``` box, and a standing instruction telling every session to
    consult that index and to run four `precedent_gate.py` commands --
    ALL FOUR of which exit FAIL there, because no practice in that set
    registers a gate. The three sections and the four gate names were
    emitted unconditionally, so the block described the ENGINE's channels
    rather than the ones the SOURCE actually fills.

    Why this is worse than cosmetic, and why it earns a check rather than
    a careful reading: the standing instruction is the one part of the
    block that tells a session what to DO. A session that runs a command
    the block advertised and gets FAIL back learns that the block is
    decorative, and that lesson applies to the parts that were true.

    Fixture-driven on purpose. This repo's own catalogue fills every
    channel, so nothing here can exercise the empty states -- which is
    precisely why the defect survived in a vendored copy for as long as it
    did. Each case was verified by reverting the fix and watching it fail.
    """
    import importlib.util, shutil, tempfile

    def fixture(root, *, tier=None, gates='[]'):
        (root / 'practices').mkdir(parents=True, exist_ok=True)
        (root / 'tools').mkdir(parents=True, exist_ok=True)
        (root / 'AGENTS.md').write_text(
            '# fixture\n\n<!-- BEGIN GENERATED: precedent-loader -->\n'
            '<!-- END GENERATED -->\n', encoding='utf-8')
        if tier is not None:
            (root / 'practices' / 'only.md').write_text(
                f'---\nslug: only\ntitle: Only\ntier: {tier}\nseverity: default\n'
                f'applies_to: ["**"]\noccasion: "doing the only thing"\n'
                f'gates: {gates}\nindex_clause: "the only clause"\nchecked_by: null\n'
                f'defines: []\nstatus: active\nsupersedes: []\noverrides: null\n'
                f'added: 2026-09-06\napproved_by: "harness fixture"\n---\n'
                f'## Rule\nThe only rule.\n\n## Why\nx\n\n## Story\n\n## Install\nx\n',
                encoding='utf-8')
        return root

    def block_of(root):
        r = subprocess.run([sys.executable, str(ROOT / 'tools' / 'build_views.py'),
                            '--agents-only', '--repo', str(root)],
                           capture_output=True, text=True)
        if r.returncode != 0:
            return f'BUILD FAILED: {(r.stdout + r.stderr)[:200]}'
        text = (root / 'AGENTS.md').read_text(encoding='utf-8')
        return text.split('BEGIN GENERATED: precedent-loader -->', 1)[1] \
                   .split('<!-- END GENERATED', 1)[0]

    tmp = pathlib.Path(tempfile.mkdtemp(prefix='precedent-loader-empty-'))
    cases = []
    try:
        # (1) resident-only: precedent-team-tms's exact shape.
        b = block_of(fixture(tmp / 'resident_only', tier='resident'))
        cases.append(('a resident-only source gets no empty occasion index',
                      '## Occasion index' not in b, b.strip()[:160]))
        cases.append(('a resident-only source is not told to run a gate command '
                      'no practice registers',
                      'precedent_gate.py' not in b, b.strip()[:160]))
        cases.append(('a resident-only source is not told to consult an index '
                      'that does not exist',
                      'occasion index above' not in b, b.strip()[:160]))
        cases.append(('a resident-only source still gets its resident block',
                      '## Resident block' in b and 'The only rule.' in b, b.strip()[:160]))

        # (2) on-demand-only: the mirror image, an empty resident heading.
        b = block_of(fixture(tmp / 'ondemand_only', tier='on-demand'))
        cases.append(('an on-demand-only source gets no empty resident block heading',
                      '## Resident block' not in b, b.strip()[:160]))
        cases.append(('an on-demand-only source still gets its occasion index',
                      '## Occasion index' in b and 'the only clause' in b, b.strip()[:160]))

        # (3) no practices at all: a freshly bootstrapped source.
        b = block_of(fixture(tmp / 'empty'))
        cases.append(('a source with no practices says so, rather than emitting '
                      'three empty headings',
                      'no practices in force' in b and '## Standing instruction' not in b,
                      b.strip()[:160]))

        # (4) a live gate IS advertised -- the negative control for the three
        # "not advertised" cases above, which would all pass on a generator
        # that simply never mentioned a gate.
        b = block_of(fixture(tmp / 'gated', tier='on-demand', gates='["reply"]'))
        cases.append(('a source WITH a gated practice is told to run that gate',
                      'precedent_gate.py reply' in b, b.strip()[:160]))
        cases.append(('and is told only about that gate, not the whole vocabulary',
                      'merge|review' not in b and 'push' not in b, b.strip()[:160]))
    finally:
        shutil.rmtree(tmp, ignore_errors=True)

    bad = [(c[0], c[2] if len(c) > 2 else '') for c in cases if not c[1]]
    check(f'the generated loader block advertises only channels this source fills '
          f'({len(cases)} stated cases over four fixture shapes)',
          not bad,
          '; '.join(f"{n}{' (' + d + ')' if d else ''}" for n, d in bad))


def check_session_practices_drop_what_agents_md_carries():
    """The session-practices file leaves out wrapping its repo's AGENTS.md
    already carries word for word -- and ONLY that.

    2026-09-24, precedent-individual: universal promoted one practice to
    resident and the set's .precedent/SESSION_PRACTICES.md went to 5,266
    tokens against a 5,200 ceiling. None of the overflow was the set's own
    text, and a good part of it was not practice text at all: the standing
    instruction's first two sentences and the omitted-index note, both
    already in the tracked AGENTS.md the same session loads. build_loader_block
    now takes `carried` and drops a sentence it finds there. The cases pin
    both directions, because a drop that fires on a near-match would silently
    take an instruction away from a repo whose AGENTS.md says something else.
    """
    import shutil, tempfile
    import build_views as bv
    tmp = pathlib.Path(tempfile.mkdtemp(prefix='precedent-carried-'))
    cases = []
    try:
        pdir = tmp / 'practices'
        pdir.mkdir()
        for slug, gates, applies in (('spoken', '[]', '[]'),
                                     ('gated', '["reply"]', '["**"]')):
            (pdir / f'{slug}.md').write_text(
                f'---\nslug: {slug}\ntitle: T\ntier: on-demand\nseverity: default\n'
                f'applies_to: {applies}\noccasion: "a person says {slug}"\n'
                f'gates: {gates}\nindex_clause: "the {slug} clause"\nchecked_by: null\n'
                f'defines: []\nstatus: active\nsupersedes: []\noverrides: null\n'
                f'added: 2026-09-24\napproved_by: "harness fixture"\n---\n'
                f'## Rule\nR.\n\n## Why\nx\n\n## Story\n\n## Install\nx\n',
                encoding='utf-8')
        practices = bv.load_practices(pdir)
        full, _t, _c = bv.build_loader_block(practices, block_dir=tmp)
        instr = full.split('## Standing instruction', 1)[-1].split('<!--', 1)[0]
        note = next((l for l in full.splitlines()
                     if l.startswith('(More on-demand')), '')
        cases.append(('the fixture renders both pieces with nothing carried, so '
                      'the cases below test a drop and not an absence',
                      '## Standing instruction' in full and bool(note)))

        # Carried word for word, wrapped differently -- dropped.
        wrapped = '\n'.join(' '.join(instr.split()).replace('. ', '.\n')
                            .split('\n')) + '\n' + note.replace(' -- ', '\n-- ')
        b, _t, _c = bv.build_loader_block(practices, block_dir=tmp,
                                          carried=wrapped)
        cases.append(('a standing instruction AGENTS.md carries word for word '
                      '(however it wraps) is not repeated',
                      '## Standing instruction' not in b))
        cases.append(('...nor is the omitted-index note',
                      '(More on-demand' not in b))
        cases.append(('...while the practices themselves still render',
                      'the spoken clause' in b))

        # A DIFFERENT gate list: only the list is news.
        other = ' '.join(instr.split()).replace('precedent_gate.py reply',
                                                'precedent_gate.py merge')
        b, _t, _c = bv.build_loader_block(practices, block_dir=tmp,
                                          carried=other)
        tail = b.split('## Standing instruction', 1)[-1]
        cases.append(('where AGENTS.md names different gates, this block keeps '
                      'its own gate list and drops only the shared why',
                      'precedent_gate.py reply`.' in tail
                      and 'no path glob reaches those' not in tail
                      and 'Before starting work' not in tail))

        # Not carried at all -- nothing dropped.
        b, _t, _c = bv.build_loader_block(practices, block_dir=tmp,
                                          carried='# an AGENTS.md that says '
                                                  'something else entirely\n')
        cases.append(('a repo whose AGENTS.md lacks them keeps both, whole',
                      b == full))
    finally:
        shutil.rmtree(tmp, ignore_errors=True)
    bad = [c[0] for c in cases if not c[1]]
    check(f'the session-practices block drops only what AGENTS.md carries word '
          f'for word ({len(cases)} stated cases)', not bad, '; '.join(bad))


def check_source_sets_can_learn_they_are_stale():
    """A vendored source set must have some way to find out its engine is old.

    2026-09-06: `precedent-individual` and `precedent-team-tms` both sat at
    ef8b5d09 while this branch moved more than two hundred commits past it,
    and both were generating a loader block with a defect fixed upstream
    days earlier. Nothing was broken -- there was simply no channel through
    which "your copy is behind" could reach anyone. It surfaced because a
    session happened to have a clone attached and happened to run a check by
    hand.

    A CONSUMER repo never had this problem: it vendors process/upstream/ and
    its bootstrap runs a freshness check at session start. The asymmetry was
    the defect, and these cases assert the three channels that close it, so
    that removing any one of them fails here rather than going quiet for
    another two hundred commits.
    """
    cases = []

    # 1. No source template ships a scheduled workflow, and that is the
    #    decision, not an omission (2026-09-06). One was added here and
    #    pulled back out the same day: a cron job that phones a remote every
    #    week and opens pull requests is a real imposition on every adopter
    #    who inherits it, and a universal template is exactly the wrong place
    #    to make that choice for people. This case exists so the file cannot
    #    reappear here without someone deciding to put it back.
    #
    #    The 2026-09-06 comment here used to end "it lives at the individual
    #    level now, for whoever wants it". SUPERSEDED 2026-09-14: it lives
    #    nowhere. Morgan killed the weekly refresh outright -- "No weekly
    #    updates ... this is now really complex and deserves hand attention"
    #    -- after two scheduled runs produced two abandoned branches, a 100%
    #    report rate against a 0% landing rate. The replacement is a person
    #    saying "Update Vendors" by hand. So this assertion is no longer the
    #    narrow "not in a TEMPLATE" claim it was written as; it is now the
    #    universal one, and the individual-level copy it used to point at is
    #    being removed in the practice sets (not reachable from this repo).
    for level in ('individual', 'team'):
        wf = ROOT / 'templates' / f'practice-set-{level}' / '.github' / 'workflows' / 'engine-refresh.yml'
        cases.append((f'the {level} source template ships no scheduled workflow '
                      f'(no repository runs one, decided 2026-09-14)',
                      not wf.exists(), str(wf.relative_to(ROOT)) if wf.exists() else ''))

    # 2. The bootstrap tool warns when the clone it is seeding FROM is behind.
    bs = (ROOT / 'tools' / 'precedent_bootstrap_source.py').read_text(encoding='utf-8')
    cases.append(('bootstrap warns when seeding from a stale checkout',
                  '_warn_if_clone_is_stale' in bs and '_warn_if_clone_is_stale()' in bs, ''))

    # 3. A session working HERE is told about stale attached sources.
    tool = ROOT / 'tools' / 'precedent_refresh_sources.py'
    cases.append(('precedent_refresh_sources.py exists', tool.is_file(), ''))
    hook = (ROOT / '.claude' / 'hooks' / 'session-start.sh').read_text(encoding='utf-8')
    cases.append(('the session-start hook runs it',
                  'precedent_refresh_sources.py' in hook, ''))

    if tool.is_file():
        # Both directions, against real fixtures: a set recording this
        # checkout's own tip is current; one recording anything else is not.
        # Without the "current" case, a detector that called everything stale
        # would pass.
        import shutil, tempfile
        import importlib.util
        spec = importlib.util.spec_from_file_location('_prs', tool)
        prs = importlib.util.module_from_spec(spec)
        spec.loader.exec_module(prs)
        tip, _ref = prs.head_commit()
        tmp = pathlib.Path(tempfile.mkdtemp(prefix='precedent-staleness-'))
        try:
            def fake_set(name, commit):
                d = tmp / name
                (d / 'tools').mkdir(parents=True)
                (d / 'tools' / 'ENGINE_MANIFEST.json').write_text(
                    json.dumps({'format_version': 1, 'kind': 'source',
                                'source_commit': commit}), encoding='utf-8')
                return d
            if tip:
                current = fake_set('current-set', tip)
                stale = fake_set('stale-set', '0' * 40)
                # Refreshed in the working tree, older engine committed: the
                # state every set clone is in after a session-start refresh.
                held = fake_set('uncommitted-set', '1' * 40)
                for a in (['init', '-q', '-b', 'main'], ['add', '-A'],
                          ['-c', 'user.name=t', '-c', 'user.email=t@t',
                           'commit', '-qm', 'older engine']):
                    subprocess.run(['git', '-C', str(held), *a], capture_output=True)
                (held / 'tools' / 'ENGINE_MANIFEST.json').write_text(
                    json.dumps({'format_version': 1, 'kind': 'source',
                                'source_commit': tip}), encoding='utf-8')
                _t, _r, found = prs.survey([str(current), str(stale), str(held)])
                by = {e['repo'].name: e for e in found}
                cases.append(('a set recording this tip reports as current',
                              by.get('current-set', {}).get('stale') is False,
                              str(by.get('current-set'))))
                cases.append(('a set recording an older commit reports as STALE',
                              by.get('stale-set', {}).get('stale') is True,
                              str(by.get('stale-set'))))
                # The two hashes are BestPractice's, so the report names
                # BestPractice: beside a set's name, "origin/main is ..." read
                # as the set's own main (2026-09-30).
                import contextlib as _cl, io as _io
                real_survey = prs.survey
                prs.survey = lambda _extra: (tip, f'origin/{prs.SOURCE_BRANCH}',
                                             found)
                try:
                    buf = _io.StringIO()
                    with _cl.redirect_stdout(buf):
                        prs.main([])
                finally:
                    prs.survey = real_survey
                said = buf.getvalue()
                lines = [l for l in said.splitlines()
                         if l.strip().startswith(('STALE', 'ok'))
                         and ('current-set' in l or 'stale-set' in l)]
                cases.append(('each STALE and ok line names BestPractice as '
                              'the repo whose commits it compares',
                              len(lines) == 2 and all('BestPractice' in l
                                                      for l in lines),
                              said[-600:]))
                held_line = next((l for l in said.splitlines()
                                  if 'uncommitted-set' in l), '')
                cases.append(('a refreshed working tree over an older committed '
                              'engine says both, and how it lands: Update '
                              'Vendors in that set (2026-10-01)',
                              'working tree current' in held_line
                              and 'committed engine is 111111111111' in held_line
                              and 'only in this container' in held_line
                              and '"Update Vendors" in uncommitted-set' in held_line,
                              held_line))
                cur_line = next((l for l in said.splitlines()
                                 if 'current-set' in l and 'uncommitted' not in l), '')
                cases.append(('...and a clone with nothing committed to compare '
                              'says engine current, as before',
                              'engine current' in cur_line, cur_line))
            else:
                cases.append(('the staleness fixtures could run (needs '
                              f'origin/{prs.SOURCE_BRANCH} fetched)', False,
                              'branch not resolvable in this clone'))
        finally:
            shutil.rmtree(tmp, ignore_errors=True)

    bad = [(c[0], c[2] if len(c) > 2 else '') for c in cases if not c[1]]
    check(f'a vendored source set can learn its engine is stale '
          f'({len(cases)} stated cases: no templated cron, bootstrap warning, '
          f'attached-source detector)',
          not bad,
          '; '.join(f"{n}{' (' + d + ')' if d else ''}" for n, d in bad))


def _source_kind_engine_files():
    """-> (str, ...) the engine files precedent_vendor_engine.py vendors into
    a SOURCE set, plus routing_scope.json, which travels trimmed rather than
    by name in that list.

    READ FROM THE ENGINE, NOT RESTATED (practice: fixture-owns-its-state --
    the state a fixture owns includes which files a real source set gets;
    same reasoning as _consumer_engine_into above, which reads
    CONSUMER_ENGINE_FILES for exactly this reason). This was a hand-typed
    tuple until 2026-09-13, when precedent_source_bootstrap.py was promoted
    into ENGINE_FILES and the tuple went stale in the same commit -- the
    drift the comment ten lines above _consumer_engine_into warns about,
    repeated in the file that carries the warning."""
    sys.path.insert(0, str(ROOT / 'tools'))
    import precedent_vendor_engine as _pve
    return tuple(_pve.ENGINE_FILES) + ('routing_scope.json',)


def check_publisher_bound_checks_run_in_a_source_set():
    """A check about published practice content must fire in the repo that
    PUBLISHES it, and must still skip in a repo that merely consumes it.

    precedent_check.py gates every practice-backed check on
    `practices/<slug>.md` being present, which is right for a consumer -- a
    finding whose Rule the reader cannot print is one nobody can act on. A
    practice SOURCE set is the case that gate got wrong: its practices/
    holds its own practices only, it resolves no sources and materializes
    nothing into itself, so every other level's check skipped there
    permanently. Measured 2026-09-12 in a shared source: 12 passed, 42
    SKIPPED, all 42 that one cause.

    It had already cost something. A practice file in that set shipped a
    relative link to `tools/checks/tests/run_all.sh`, which materialization
    deliberately does not copy -- live in the publishing set, dead in every
    repository that received the catalogue. `practice-links-travel` is
    exactly the rule that catches it, and it was one of the 42. A CONSUMING
    repo found it, a sync late.

    `binds_publishers=True` on the registration is the fix. These cases
    assert it in both directions against a real fixture, planting that same
    link, so that a regression here fails rather than going quiet -- and
    they assert the MESSAGE, not merely a non-zero exit
    (practice: control-asserts-which-failure).
    """
    import tempfile
    cases = []

    src = ROOT / 'tools' / 'precedent_check.py'
    # 1. The flags are still set. Three checks earned this the hard way, each
    #    with its own incident in a comment beside it; dropping one silently
    #    puts the publishing repos back to unchecked.
    text = src.read_text(encoding='utf-8')
    #    Thirteen more joined them 2026-09-22, from the audit that read all
    #    44 skipped checks one at a time (spec/PUBLISHER_GATE_AUDIT.md). They
    #    are pinned by NAME rather than by counting flags in the file, so a
    #    flag moved off one check and onto another still fails here.
    for slug in ('practice-links-travel', 'catalogue-carries-stories',
                 'generated-artifact-provenance',
                 'cite-the-incident', 'source-naming', 'decision-strength',
                 'acronyms-glossary', 'doc-references-are-links',
                 'heading-outline', 'label-describes-content',
                 'docs-are-current-state', 'index-remembers-past',
                 'deliverables-look-like-output', 'no-version-suffix',
                 'filename-separator', 'technical-describes-people'):
        i = text.find(f"@check('{slug}'")
        nxt = text.find('@check(', i + 1) if i >= 0 else -1
        body = text[i:nxt] if i >= 0 and nxt > i else (text[i:] if i >= 0 else '')
        cases.append((f'{slug} is still registered binds_publishers=True',
                      'binds_publishers=True' in body, ''))

    # 2. THIS repo is not a publisher by this test and so is unaffected. It
    #    has no vendored-engine manifest at all -- it is the origin -- and a
    #    behaviour change here would be a change nobody asked for.
    r = subprocess.run([sys.executable, '-c',
                        'import sys; sys.path.insert(0, "tools"); '
                        'import precedent_check as pc; '
                        'print(pc._publishes_practices())'],
                       cwd=ROOT, capture_output=True, text=True)
    cases.append(('this repo does not read as a publisher (it is the origin, '
                  'and carries every practice file anyway)',
                  r.stdout.strip() == 'False', r.stdout.strip() + r.stderr[-200:]))

    tmp = pathlib.Path(tempfile.mkdtemp(prefix='publisher-bound-'))
    try:
        # A fixture that OWNS its state: its own git repo, its own declared
        # kind, its own practices/ tree. Nothing here is inherited from the
        # container or from any real source set on disk
        # (practice: fixture-owns-its-state).
        fx = tmp / 'set'
        (fx / 'tools').mkdir(parents=True)
        (fx / 'practices').mkdir()
        # The whole source-kind engine, not just the checker: the check under
        # test asks precedent_vendor_engine what travels, and a fixture
        # missing that module makes it report NotApplicable -- which reads as
        # a SKIPPED and would have been misread here as the gate still
        # blocking it. Found building this control.
        for name in _source_kind_engine_files():
            e = ROOT / 'tools' / name
            if e.is_file():
                shutil.copy(e, fx / 'tools' / name)
        shutil.copy(src, fx / 'tools' / 'precedent_check.py')
        (fx / 'precedent.json').write_text(json.dumps(
            {'format_version': 1, 'base_branch': 'main'}), encoding='utf-8')
        # The link that really shipped broken, in a practice this fixture owns.
        (fx / 'practices' / 'fixture-rule.md').write_text(
            '---\n'
            'slug:        fixture-rule\n'
            'title:       A fixture practice this set publishes\n'
            'tier:        on-demand\n'
            'severity:    default\n'
            'applies_to:  ["practices/*.md"]\n'
            'occasion:    "the fixture runs"\n'
            'gates:       []\n'
            'index_clause: "the fixture runs"\n'
            'checked_by:  null\n'
            'defines:     []\n'
            'status:      active\n'
            'supersedes:  []\n'
            'overrides:   null\n'
            'added:       2026-09-12\n'
            'approved_by: "fixture"\n'
            '---\n'
            '## Rule\nThe fixture practice says nothing in particular.\n\n'
            '## Story\nWritten for this control; no incident is claimed.\n',
            encoding='utf-8')

        def run_in_fixture(kind):
            (fx / 'tools' / 'ENGINE_MANIFEST.json').write_text(json.dumps({
                'kind': kind,
                'source_repo': 'https://github.com/example/upstream',
                'source_branch': 'main',
                'files': ['precedent_check.py'],
            }), encoding='utf-8')
            env = dict(os.environ, PRECEDENT_ALLOW_ANY_AUTHOR='1')
            return subprocess.run(
                [sys.executable, 'tools/precedent_check.py', '--only',
                 'practice-links-travel'],
                cwd=fx, capture_output=True, text=True, env=env)

        subprocess.run(['git', 'init', '-q'], cwd=fx, capture_output=True)

        # Clean first: a publisher whose links all travel must PASS, so a
        # green result here is not just the check failing to find the file.
        (fx / 'practices' / 'fixture-rule.md').write_text(
            (fx / 'practices' / 'fixture-rule.md').read_text(encoding='utf-8')
            + '\nA sibling link that does travel: [fixture-rule](fixture-rule.md).\n',
            encoding='utf-8')
        ok = run_in_fixture('source')
        cases.append(('a publisher with only travelling links PASSES (so the '
                      'firing case below is the planted link, not a no-op)',
                      'VIOLATION' not in ok.stdout and ok.returncode == 0,
                      ok.stdout[-300:] + ok.stderr[-200:]))

        # Now plant the shape that shipped: a relative link out of practices/
        # to a file materialization does not copy.
        (fx / 'practices' / 'fixture-rule.md').write_text(
            (fx / 'practices' / 'fixture-rule.md').read_text(encoding='utf-8')
            + '\nA driver link that does not: '
              '[`run_all.sh`](../tools/checks/tests/run_all.sh).\n',
            encoding='utf-8')

        pub = run_in_fixture('source')
        cases.append(('a PUBLISHER runs the check and fails on the planted link',
                      pub.returncode != 0 and 'VIOLATION' in pub.stdout,
                      f'rc={pub.returncode} ' + pub.stdout[-300:]))
        cases.append(('the finding names the file that does not travel',
                      'run_all.sh' in pub.stdout and 'does not travel' in pub.stdout,
                      pub.stdout[-300:]))
        # The Rule cannot be printed here, so it must say where the Rule IS.
        # Printing "(no practice file for ...)" instead would be the whole
        # design of the module -- the failure message is the rule -- quietly
        # failing at the one moment it is load-bearing.
        cases.append(('and says where the Rule lives, since this repo cannot '
                      'print it',
                      'practices/practice-links-travel.md' in pub.stdout
                      and 'no practice file for' not in pub.stdout,
                      pub.stdout[-400:]))

        con = run_in_fixture('consumer')
        cases.append(('a CONSUMER still skips it, planted link and all',
                      con.returncode == 0 and 'SKIPPED' in con.stdout,
                      f'rc={con.returncode} ' + con.stdout[-300:]))
        cases.append(('and says why it skipped, naming the absent practice file',
                      'not in force here' in con.stdout, con.stdout[-300:]))
    finally:
        shutil.rmtree(tmp, ignore_errors=True)

    bad = [(c[0], c[2] if len(c) > 2 else '') for c in cases if not c[1]]
    check(f'a check about published practices binds the publisher and still '
          f'skips a consumer ({len(cases)} stated cases, each asserting the '
          f'printed text)',
          not bad,
          '; '.join(f"{n}{' (' + d + ')' if d else ''}" for n, d in bad))


def check_practice_links_travel_skips_a_consumers_repo_local_practices():
    """A consumer's repo-local practice is never published, so
    practice-links-travel must not test its links -- and the repair it
    prints for a practice it DOES test must not be a URL into a repository
    that is not declared public.

    Found 2026-09-27 in a private consuming repository: after a vendor
    update its full check reported 20 working links in its own repo-local
    practices as dead, because the check kept every practice the committed
    MANIFEST.json did not attribute to ANOTHER source, and `repo-local` is
    not another source. Each finding advised an absolute URL into that
    private repository -- the disclosure the practice's own Rule forbids.

    One fixture, three runs, each asserting the printed text rather than an
    exit status alone (practice: control-asserts-which-failure):
      1. the repo-local practice with a working relative link is not
         reported;
      2. the SAME file, no longer named in the manifest (so this repository
         publishes it), IS reported -- which is what keeps case 1 from
         passing because the check never looked;
      3. that finding's repair is a backticked path under
         `visibility: private`, and a URL under `visibility: public`.
    """
    import tempfile
    cases = []
    tmp = pathlib.Path(tempfile.mkdtemp(prefix='links-travel-local-'))
    try:
        # A fixture that owns its state: its own git repo, manifest,
        # visibility and practices/ (practice: fixture-owns-its-state).
        fx = tmp / 'consumer'
        (fx / 'tools').mkdir(parents=True)
        (fx / 'practices').mkdir()
        (fx / 'content').mkdir()
        for name in _source_kind_engine_files():
            e = ROOT / 'tools' / name
            if e.is_file():
                shutil.copy(e, fx / 'tools' / name)
        shutil.copy(ROOT / 'tools' / 'precedent_check.py',
                    fx / 'tools' / 'precedent_check.py')
        # The consumer gate runs a practice-backed check only when its
        # practice file is here, as it is in every real consumer.
        shutil.copy(ROOT / 'practices' / 'practice-links-travel.md',
                    fx / 'practices' / 'practice-links-travel.md')
        (fx / 'content' / 'LIST.md').write_text('# List\n', encoding='utf-8')
        (fx / 'practices' / 'fixture-local.md').write_text(
            '---\nslug:        fixture-local\ntitle:       A repo-local rule\n'
            'tier:        on-demand\nseverity:    default\n'
            'applies_to:  ["content/*.md"]\noccasion:    "the fixture runs"\n'
            'gates:       []\nindex_clause: "the fixture runs"\n'
            'checked_by:  null\ndefines:     []\nstatus:      active\n'
            'supersedes:  []\noverrides:   null\nadded:       2026-09-27\n'
            'approved_by: "fixture"\n---\n'
            '## Rule\nAdd items to [the list](../content/LIST.md).\n\n'
            '## Story\nWritten for this control; no incident is claimed.\n',
            encoding='utf-8')
        (fx / 'tools' / 'ENGINE_MANIFEST.json').write_text(json.dumps({
            'kind': 'consumer',
            'source_repo': 'https://github.com/example/upstream',
            'source_branch': 'main',
            'files': ['precedent_check.py'],
        }), encoding='utf-8')
        subprocess.run(['git', 'init', '-q'], cwd=fx, capture_output=True)
        subprocess.run(['git', 'remote', 'add', 'origin',
                        'https://github.com/example/consumer.git'],
                       cwd=fx, capture_output=True)

        def run(local_level, visibility):
            entries = [{'slug': 'practice-links-travel', 'level': 'universal'}]
            if local_level:
                entries.append({'slug': 'fixture-local', 'level': local_level})
            (fx / 'MANIFEST.json').write_text(
                json.dumps({'practices': entries}), encoding='utf-8')
            (fx / 'precedent.json').write_text(json.dumps(
                {'format_version': 1, 'base_branch': 'main',
                 'visibility': visibility}), encoding='utf-8')
            env = dict(os.environ, PRECEDENT_ALLOW_ANY_AUTHOR='1')
            return subprocess.run(
                [sys.executable, 'tools/precedent_check.py', '--only',
                 'practice-links-travel'],
                cwd=fx, capture_output=True, text=True, env=env)

        local = run('repo-local', 'private')
        cases.append(('a consumer\'s repo-local practice with a working '
                      'relative link is not reported',
                      local.returncode == 0 and 'VIOLATION' not in local.stdout
                      and 'fixture-local.md:' not in local.stdout,
                      f'rc={local.returncode} ' + local.stdout[-400:]))
        cases.append(('and the skip says the repo-local practices were left '
                      'out because they are never published',
                      'repo-local source' in local.stdout
                      and 'never published' in local.stdout,
                      local.stdout[-400:]))

        pub = run(None, 'private')
        cases.append(('the same link in a practice this repository publishes '
                      'IS reported (so the case above is the guard, not a '
                      'check that never looked)',
                      pub.returncode != 0
                      and 'fixture-local.md:' in pub.stdout
                      and 'does not travel' in pub.stdout,
                      f'rc={pub.returncode} ' + pub.stdout[-400:]))
        cases.append(('under visibility: private the repair is the backticked '
                      'path, never a URL into this repository',
                      '`content/LIST.md`' in pub.stdout
                      and 'github.com/example/consumer' not in pub.stdout,
                      pub.stdout[-400:]))

        public = run(None, 'public')
        cases.append(('under visibility: public the repair is the absolute URL',
                      'https://github.com/example/consumer/blob/main/'
                      'content/LIST.md' in public.stdout,
                      public.stdout[-400:]))
    finally:
        shutil.rmtree(tmp, ignore_errors=True)

    bad = [(c[0], c[2] if len(c) > 2 else '') for c in cases if not c[1]]
    check(f'practice-links-travel skips a consumer\'s repo-local practices '
          f'and suggests a URL only in a public repository '
          f'({len(cases)} stated cases, each asserting the printed text)',
          not bad,
          '; '.join(f"{n}{' (' + d + ')' if d else ''}" for n, d in bad))


def check_gate_channel():
    """The gate channel, as stated cases against the real registry.

    A gate that loads nothing is the failure this channel is most prone to: a
    runbook step citing a gate nobody registered prints nothing and exits 0,
    which is indistinguishable from a gate that legitimately had nothing to
    say. Every case below was verified by breaking it -- an unknown gate name
    in a practice file, an emptied gate, a gate dropped from the vocabulary.
    """
    import importlib.util
    spec = importlib.util.spec_from_file_location(
        '_pg', ROOT / 'tools' / 'precedent_gate.py')
    pg = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(pg)

    vocab = pg.gate_vocabulary()
    by_gate = pg.practices_by_gate()
    cases = []

    cases.append(('the gate vocabulary is non-empty', bool(vocab)))

    declared = set()
    bad_names = []
    for f in sorted(PRACTICES_DIR.glob('*.md')):
        fm, _sections = sp._read_practice_file(f)
        try:
            gates = json.loads(fm.get('gates', '[]') or '[]')
        except json.JSONDecodeError:
            bad_names.append(f"{fm['slug']}: gates is not a JSON array")
            continue
        for g in gates:
            declared.add(g)
            if g not in vocab:
                bad_names.append(f"{fm['slug']} names unknown gate {g!r}")
    cases.append(('every gate a practice names is in the closed vocabulary',
                  not bad_names, '; '.join(bad_names[:4])))

    empty = [g for g in vocab if not by_gate.get(g)]
    cases.append(('no gate in the vocabulary is empty -- an empty gate is a step '
                  'that loads nothing and looks like it worked',
                  not empty, f"empty: {empty}" if empty else ''))

    unused = sorted(set(vocab) - declared)
    cases.append(('no gate is declared but unreachable', not unused,
                  f"declared with no practice: {unused}" if unused else ''))

    # the command itself, run as a subprocess -- the channel as a caller uses it
    # A practice another resolved source replaces (`overrides:`) is not in
    # force and is rightly left out -- present only where that source
    # resolves, as a person's individual set does beside this checkout.
    sys.path.insert(0, str(ROOT / 'tools'))
    import precedent_gate as _pg
    for g in sorted(vocab):
        r = subprocess.run([sys.executable, str(ROOT / 'tools' / 'precedent_gate.py'), g],
                           capture_output=True, text=True, cwd=str(ROOT))
        replaced = _pg.resolved_gate_practices(str(ROOT), g)[3]
        ok = r.returncode == 0 and all(s in r.stdout for s in by_gate[g]
                                       if s not in replaced)
        cases.append((f'`precedent_gate.py {g}` returns every practice registered to it', ok,
                      (r.stdout + r.stderr).strip()[:120] if not ok else ''))

    r = subprocess.run([sys.executable, str(ROOT / 'tools' / 'precedent_gate.py'), 'no-such-gate'],
                       capture_output=True, text=True, cwd=str(ROOT))
    cases.append(('an unknown gate fails loudly rather than printing nothing',
                  r.returncode != 0 and 'no gate named' in (r.stdout + r.stderr)))

    # the push gate must actually be wired, or it is a channel nobody reaches
    hook = ROOT / 'templates' / 'hooks' / 'pre-push'
    cases.append(('the push gate is wired into templates/hooks/pre-push',
                  hook.exists() and 'precedent_gate' in hook.read_text(errors='ignore')))

    # the reply gate must actually be wired too -- a 2026-09-04 gate audit
    # found it was not: routing_scope.json names this gate's moment as "the
    # stop hook", but the only stop-hook script any adapter ships never
    # called precedent_gate.py at all. Checked in both the template a
    # dependent repo installs and this repo's own instantiated copy, so
    # neither can drift back to cited-only without this case catching it.
    for stop_hook in (ROOT / 'templates' / 'harness' / 'claude-code' / 'hooks' / 'stop-reply-check.sh',
                      ROOT / '.claude' / 'hooks' / 'stop-reply-check.sh'):
        cases.append((f'the reply gate is wired into {stop_hook.relative_to(ROOT)}',
                      stop_hook.exists() and 'precedent_gate' in stop_hook.read_text(errors='ignore')))

    # 2026-09-13: the reply gate gained a second invocation point and a
    # blocking half, and both are wiring claims that can drift back to
    # cited-only exactly as the first one did.
    #
    # UserPromptSubmit is where the gate reaches the reply it is ABOUT. Stop
    # fires after the reply is composed and its output is not fed back to the
    # model on a clean exit, so the advisory print had never once reached the
    # turn it was meant to govern.
    for settings in (ROOT / 'templates' / 'harness' / 'claude-code' / 'settings.json',
                     ROOT / '.claude' / 'settings.json'):
        data = json.loads(settings.read_text(encoding='utf-8'))
        wired = [h.get('command', '') for blk in data.get('hooks', {}).get('UserPromptSubmit', [])
                 for h in blk.get('hooks', [])]
        cases.append((f'the reply gate is wired at UserPromptSubmit in '
                      f'{settings.relative_to(ROOT)}',
                      any('reply-gate.sh' in c for c in wired),
                      f'UserPromptSubmit wires {wired}'))
    for hook in (ROOT / 'templates' / 'harness' / 'claude-code' / 'hooks' / 'reply-gate.sh',
                 ROOT / '.claude' / 'hooks' / 'reply-gate.sh'):
        cases.append((f'{hook.relative_to(ROOT)} exists and is executable -- a '
                      f'hook a settings.json declares and disk does not have is '
                      f'the failure the harness reports as nothing at all',
                      hook.is_file() and os.access(hook, os.X_OK)))
    for stop_hook in (ROOT / 'templates' / 'harness' / 'claude-code' / 'hooks' / 'stop-reply-check.sh',
                      ROOT / '.claude' / 'hooks' / 'stop-reply-check.sh'):
        cases.append((f'the BLOCKING reply check is called from '
                      f'{stop_hook.relative_to(ROOT)}',
                      'precedent_reply_check' in stop_hook.read_text(errors='ignore')))

    # 2026-09-15: the Stop hook's own advisory print of the reply gate went
    # unbriefed for over a year -- `precedent_gate.py reply` with no
    # `--brief`, printing every reply-gate practice's full text on every
    # single Stop, unconditionally, on top of the SAME list reply-gate.sh
    # already prints in brief form at the START of the turn. Nothing above
    # caught it: 'precedent_gate' and 'precedent_reply_check' are both
    # substrings of the un-briefed call too. Found from a person describing
    # the result plainly -- a wall of text at the end of every session.
    for stop_hook in (ROOT / 'templates' / 'harness' / 'claude-code' / 'hooks' / 'stop-reply-check.sh',
                      ROOT / '.claude' / 'hooks' / 'stop-reply-check.sh'):
        cases.append((f'{stop_hook.relative_to(ROOT)} calls the reply gate '
                      f'--brief, not the full Rules, on every Stop',
                      'precedent_gate.py" reply --brief' in stop_hook.read_text(errors='ignore')))

    # --brief is the per-turn form, and its promise is that it is CHEAP. A
    # regression that printed full Rules there would not fail any case above.
    r_full = subprocess.run([sys.executable, str(ROOT / 'tools' / 'precedent_gate.py'), 'reply'],
                            capture_output=True, text=True, cwd=str(ROOT))
    r_brief = subprocess.run([sys.executable, str(ROOT / 'tools' / 'precedent_gate.py'),
                              'reply', '--brief'], capture_output=True, text=True, cwd=str(ROOT))
    cases.append(('`precedent_gate.py reply --brief` is much smaller than the '
                  'full gate -- it fires on every prompt',
                  r_brief.returncode == 0
                  and 0 < len(r_brief.stdout.split()) < len(r_full.stdout.split()) / 2,
                  f'{len(r_brief.stdout.split())} words vs {len(r_full.stdout.split())}'))

    # The session-guarantee reminder, added 2026-09-14. A session whose
    # SessionStart hooks never ran reads instructions it cannot satisfy, and
    # tools/precedent_session_check.py has been able to say so since
    # 2026-09-08 -- via AGENTS.md's banner, which a session can skip, and did
    # (record/GOTCHAS.md#g1). The gate is the route it cannot skip, so these
    # cases assert the PRINTED TEXT in both directions rather than the call
    # (practice: control-asserts-which-failure).
    spec_c = importlib.util.spec_from_file_location(
        '_psck', ROOT / 'tools' / 'precedent_session_check.py')
    psck = importlib.util.module_from_spec(spec_c)
    spec_c.loader.exec_module(psck)

    real_checks = psck.checks
    try:
        psck.checks = lambda offline=True: [
            ('a guarantee that holds', True, ''),
            ('a guarantee that does not', False, 'the effect is absent. More.'),
            ('a guarantee nobody could measure', None, 'undetermined'),
        ]
        block = psck.remind(prefix='precedent gate')
        cases.append(('remind() names the broken guarantee, its first sentence '
                      'and the full-report command',
                      'a guarantee that does not' in block
                      and 'the effect is absent' in block
                      and 'precedent_session_check.py' in block,
                      block[:120]))
        cases.append(('remind() stays silent about a guarantee that HOLDS and '
                      'about one nobody could measure -- a nag that fires on '
                      '"cannot tell" is a nag that gets ignored',
                      'a guarantee that holds' not in block
                      and 'nobody could measure' not in block, block[:120]))
        psck.checks = lambda offline=True: [('all fine', True, '')]
        cases.append(('remind() prints NOTHING when every guarantee is in '
                      'effect -- the control, and the normal case',
                      psck.remind() == '', repr(psck.remind())[:80]))
    finally:
        psck.checks = real_checks

    # ...and the gate actually carries it, asserted against whatever this
    # container's real state is, so the case is meaningful in both a healthy
    # session and a broken one.
    broken = psck.failing_guarantees()
    r_gate = subprocess.run([sys.executable, str(ROOT / 'tools' / 'precedent_gate.py'), 'push'],
                            capture_output=True, text=True, cwd=str(ROOT))
    said = 'SessionStart guarantee(s) NOT in effect' in r_gate.stdout
    cases.append(('a gate reports broken SessionStart guarantees, and says '
                  'nothing when there are none',
                  said == bool(broken),
                  f'{len(broken)} broken, gate {"did" if said else "did not"} say so'))

    bad = [(c[0], c[2] if len(c) > 2 else '') for c in cases if not c[1]]
    check(f'gate-triggered channel ({len(cases)} stated cases: closed vocabulary, '
          f'no empty gate, every gate resolves, unknown gates fail loudly, '
          f'push and reply actually wired, and a gate reports a session whose '
          f'SessionStart guarantees are down)',
          not bad,
          '; '.join(f"{n}{' (' + d + ')' if d else ''}" for n, d in bad))


def check_reply_gate_sees_every_source():
    """The gate channel must serve EVERY source, not just the repo's own tree.

    Until 2026-09-13 precedent_gate.py read exactly one directory --
    `<root>/practices/` -- so in any repo whose sources resolve as clones
    rather than through precedent_materialize.py, a team, individual or
    repo-local practice declaring `gates: ["reply"]` had no invocation point
    at all. Measured here that day: three individual practices about how a
    reply is written were registered to the reply gate and reached a session
    only through the occasion index, which fires only if the session
    recognises the occasion. A gate whose whole promise is reach-without-
    judgment kept that promise for one level and broke it for three.

    Every case is run against a fixture repo built here, owning all of its
    own state (practice: fixture-owns-its-state) -- no user config, no
    sibling clone, nothing inherited from the container -- and each is
    verified by its negative control: remove the second source and the same
    command must stop naming its practice."""
    import tempfile
    cases = []
    tmp = pathlib.Path(tempfile.mkdtemp(prefix='precedent-gate-sources-'))
    try:
        def practice(path, slug, clause):
            path.parent.mkdir(parents=True, exist_ok=True)
            path.write_text(
                f'---\nslug: {slug}\ntitle: {slug}\ntier: on-demand\n'
                f'severity: default\napplies_to: ["**"]\n'
                f'occasion: "a fixture"\ngates: ["reply"]\n'
                f'index_clause: "{clause}"\nchecked_by: null\ndefines: []\n'
                f'status: active\nsupersedes: []\noverrides: null\n'
                f'added: 2026-09-13\napproved_by: "harness, 2026-09-13"\n---\n'
                f'## Rule\nThe {slug} rule text.\n\n## Why\nx\n\n'
                f'## Story\nx\n\n## Install\nx\n', encoding='utf-8')

        fx = tmp / 'fixture'
        practice(fx / 'practices' / 'fixture-universal-reply.md',
                 'fixture-universal-reply', 'the universal one')
        practice(fx / 'local' / 'practices' / 'fixture-local-reply.md',
                 'fixture-local-reply', 'the repo-local one')
        (fx / 'tools').mkdir(parents=True, exist_ok=True)
        (fx / 'tools' / 'routing_scope.json').write_text(json.dumps(
            {'_note': [], 'practices': {},
             'gates': {'reply': 'ending a turn and writing the reply'}}),
            encoding='utf-8')

        def declare(*extra):
            (fx / 'precedent.json').write_text(json.dumps({
                'format_version': 1, 'base_branch': 'main', 'visibility': 'private',
                'sources': [{'level': 'universal', 'name': 'precedent', 'path': '.'}] + list(extra),
            }), encoding='utf-8')

        def gate(*args):
            return subprocess.run(
                [sys.executable, str(ROOT / 'tools' / 'precedent_gate.py'),
                 '--repo', str(fx), 'reply', *args],
                capture_output=True, text=True, cwd=str(tmp),
                env={**os.environ, 'PRECEDENT_USER_CONFIG': str(tmp / 'no-such-config.json')})

        declare({'level': 'repo-local', 'name': 'local', 'path': 'local'})
        r = gate()
        cases.append(('the reply gate names a practice from a NON-universal '
                      'source', 'fixture-local-reply' in r.stdout, r.stderr[:120]))
        cases.append(("...and still names the repo's own", 
                      'fixture-universal-reply' in r.stdout, r.stdout[:120]))
        cases.append(('a non-universal practice is labelled with its level, so '
                      'a session can see which source binds it',
                      'repo-local' in r.stdout))

        # the control: the same command, one source fewer
        declare()
        r2 = gate()
        cases.append(('the negative control: with the second source undeclared '
                      'the same command no longer names its practice',
                      'fixture-local-reply' not in r2.stdout
                      and 'fixture-universal-reply' in r2.stdout))

        # --- the BLOCKING half, against the same fixture ---
        bad = tmp / 'bad.md'
        bad.write_text('Some work.\n\n**What you need to do:** merge it.\n', encoding='utf-8')
        good = tmp / 'good.md'
        good.write_text('Some work.\n\n## Next Steps\n\n- **Merge it**\n\n'
                        'You can close this session.\n', encoding='utf-8')

        def replycheck(text):
            return subprocess.run(
                [sys.executable, str(ROOT / 'tools' / 'precedent_reply_check.py'),
                 '--repo', str(fx), '--text', str(text)],
                capture_output=True, text=True, cwd=str(tmp),
                env={**os.environ, 'PRECEDENT_USER_CONFIG': str(tmp / 'no-such-config.json')})

        # No source declares a reply_check.json yet: the engine must have NO
        # opinion of its own about how a reply ends. A universal engine that
        # shipped one person's closing convention would bind every adopter to
        # it (practice: rule-level-by-reach).
        declare({'level': 'repo-local', 'name': 'local', 'path': 'local'})
        r3 = replycheck(bad)
        cases.append(('with no reply_check.json declared, a reply breaking every '
                      'rule is NOT blocked -- the engine ships the mechanism, not '
                      'the requirement', r3.returncode == 0, r3.stderr[:160]))

        (fx / 'local' / 'reply_check.json').write_text(json.dumps({
            'practice': 'fixture-local-reply',
            'require_heading_matching': 'next step',
            'require_one_of': ['You can close this session',
                               "Don't close this session"],
        }), encoding='utf-8')

        r4 = replycheck(bad)
        # control-asserts-which-failure: a non-zero exit is not evidence. The
        # message has to name WHICH requirement the reply missed.
        cases.append(('a declared requirement blocks a reply that misses it',
                      r4.returncode == 2, f'exit {r4.returncode}'))
        cases.append(('...and names the missing HEADING specifically',
                      'MARKDOWN HEADING' in r4.stderr, r4.stderr[:160]))
        cases.append(('...and names the missing closing sentence specifically',
                      'close this session' in r4.stderr, r4.stderr[:160]))
        cases.append(('...and names the practice that required it',
                      'fixture-local-reply' in r4.stderr, r4.stderr[:160]))

        r5 = replycheck(good)
        cases.append(('a reply that meets the requirement is not blocked',
                      r5.returncode == 0, r5.stderr[:160]))

        # 2026-09-14: the block message has to say SENTENCE when only a
        # sentence is missing. A source revised its required closing sentence
        # that morning, so every reply already carrying the heading was
        # refused for the sentence alone -- and a message that asked for "the
        # missing closing section(s)" got a whole second `## Next Steps`
        # block written under the first. Morgan: *"you repeated the 'next
        # steps' section two times."* The two messages are asserted against
        # each other below, so neither can quietly become the other.
        has_heading = tmp / 'has-heading.md'
        has_heading.write_text('Some work.\n\n## Next Steps\n\n- **Merge it**\n\n'
                               'Nothing about the session either way.\n', encoding='utf-8')
        r7 = replycheck(has_heading)
        cases.append(('a reply with the heading but not the sentence is still '
                      'blocked', r7.returncode == 2, f'exit {r7.returncode}'))
        cases.append(('...and the block says the heading is already there and '
                      'must not be written again -- the whole point, since the '
                      'refused reply has already been shown',
                      'ALREADY CARRIES every closing heading' in r7.stderr
                      and 'Do NOT repeat the closing section' in r7.stderr,
                      r7.stderr[:240]))
        cases.append(('...and the per-requirement line says where the sentence '
                      'goes instead of implying a new section',
                      'do NOT write that section a second time' in r7.stderr,
                      r7.stderr[:240]))
        cases.append(('...and it does NOT ask for a closing SECTION, which is '
                      'the wording that produced the duplicate',
                      'closing section(s)' not in r7.stderr, r7.stderr[:240]))
        # The negative control for the case above: the same check on a reply
        # that really is missing the heading must still ask for the section,
        # so "closing section(s) is absent" is a real distinction and not a
        # string that left the file altogether.
        cases.append(('the control: a reply missing the HEADING is still asked '
                      'for the whole closing section',
                      'closing section(s)' in r4.stderr
                      and 'ALREADY CARRIES every closing heading' not in r4.stderr,
                      r4.stderr[:240]))

        # A blocking gate may never refuse a reply that FOLLOWED the rule, so
        # the apostrophe the terminal renders and the one a person types have
        # to be the same sentence to it.
        curly = tmp / 'curly.md'
        curly.write_text('Work.\n\n## Next steps\n\n- **x**\n\n'
                         'Don\u2019t close this session until you answer.\n', encoding='utf-8')
        r6 = replycheck(curly)
        cases.append(('a curly apostrophe is the same sentence as a typed one',
                      r6.returncode == 0, r6.stderr[:160]))

        # A turn with no prose (tool use only) has no closing line to check.
        empty = tmp / 'empty.md'
        empty.write_text('', encoding='utf-8')
        cases.append(('an empty reply is not blocked', replycheck(empty).returncode == 0))
    finally:
        shutil.rmtree(tmp, ignore_errors=True)

    bad_cases = [(c[0], c[2] if len(c) > 2 else '') for c in cases if not c[1]]
    check(f'the reply gate serves every source and its declared requirements '
          f'block ({len(cases)} stated cases, each with its control)',
          not bad_cases,
          '; '.join(f"{n}{' (' + d + ')' if d else ''}" for n, d in bad_cases))


def check_advisory_requirement_never_blocks():
    """`"advisory": true` on a reply_check.json requirement makes an unmet
    one detectable (--explain, and violations() for any programmatic
    caller) but never lets it refuse the turn -- unlike an ordinary
    requirement in the same file, which still does.

    Added 2026-09-17 alongside downgrading the-boildown's own archive and
    compact sentences to advisory (Morgan, direct instruction: "note these
    aren't binding, it's just recommendations"). practice:
    control-asserts-which-failure -- the positive case alone proves
    nothing; the negative control below is the same fixture with
    `advisory` removed, which must go back to blocking.
    """
    import tempfile
    tmp = pathlib.Path(tempfile.mkdtemp(prefix='precedent-advisory-'))
    cases = []
    try:
        fx = tmp / 'repo'
        (fx / 'practices').mkdir(parents=True)
        (fx / 'precedent.json').write_text(json.dumps({'sources': [
            {'level': 'universal', 'name': 'precedent', 'path': '.'}]}), encoding='utf-8')

        def declare(advisory):
            req = {'practice': 'fixture-advisory',
                   'require_heading_matching': 'fixture heading',
                   'require_one_of': ['fixture sentence one', 'fixture sentence two']}
            if advisory:
                req['advisory'] = True
            (fx / 'reply_check.json').write_text(json.dumps(req), encoding='utf-8')

        bad = tmp / 'bad.md'
        bad.write_text('## Fixture Heading\n\nNeither fixed sentence is here.\n',
                       encoding='utf-8')

        def replycheck():
            return subprocess.run(
                [sys.executable, str(ROOT / 'tools' / 'precedent_reply_check.py'),
                 '--repo', str(fx), '--text', str(bad)],
                capture_output=True, text=True, cwd=str(tmp),
                env={**os.environ, 'PRECEDENT_USER_CONFIG': str(tmp / 'no-such-config.json')})

        def explain():
            return subprocess.run(
                [sys.executable, str(ROOT / 'tools' / 'precedent_reply_check.py'),
                 '--repo', str(fx), '--explain'],
                capture_output=True, text=True, cwd=str(tmp),
                env={**os.environ, 'PRECEDENT_USER_CONFIG': str(tmp / 'no-such-config.json')})

        declare(advisory=True)
        r = replycheck()
        cases.append(('an advisory requirement does not block a reply that '
                      'misses its sentence', r.returncode == 0, f'exit {r.returncode}'))
        e = explain()
        cases.append(('--explain still names it, and marks it ADVISORY',
                      'ADVISORY' in e.stdout, e.stdout[:200]))

        # The negative control: same fixture, `advisory` removed -- must go
        # back to blocking, or the positive case above proves nothing.
        declare(advisory=False)
        r2 = replycheck()
        cases.append(('negative control: the same requirement without '
                      '"advisory" blocks the same reply',
                      r2.returncode == 2, f'exit {r2.returncode}'))
    finally:
        shutil.rmtree(tmp, ignore_errors=True)

    failed = [n for n, ok, *_ in cases if not ok]
    check(f'an advisory reply_check.json requirement is detected but never '
          f'blocks ({len(cases)} stated cases)', not failed, '; '.join(failed))


def check_contradiction_requirement_blocks():
    """`require_no_contradiction` catches a reply that asserts a fixed
    sentence AND, elsewhere in the same reply, a plain-language phrase that
    means the opposite -- "nothing blocking" beside "Don't archive this
    session", or a still-open/waiting-on-you phrase beside "You can archive
    this session".

    The incident: 2026-09-20, a reply's own bullets said "no open work is
    blocking either way" and then closed with "Don't archive this session"
    -- caught by the person, not by any check. This is the check.
    (practice: the-boildown, cite-the-incident)

    practice: control-asserts-which-failure -- each positive case asserts
    the guard's own "cannot both be true" message, not just a non-zero
    exit; the negative controls (the same text with only one half present)
    prove the match is on the PAIR, not on either phrase alone.
    """
    import tempfile
    tmp = pathlib.Path(tempfile.mkdtemp(prefix='precedent-contradiction-'))
    cases = []
    try:
        fx = tmp / 'repo'
        (fx / 'practices').mkdir(parents=True)
        (fx / 'precedent.json').write_text(json.dumps({'sources': [
            {'level': 'universal', 'name': 'precedent', 'path': '.'}]}), encoding='utf-8')
        (fx / 'reply_check.json').write_text(json.dumps([{
            'practice': 'fixture-contradiction',
            'require_no_contradiction': [
                {'if_says': "Don't archive this session",
                 'must_not_say_matching':
                     r'\bno[\w\s]{0,20}?blocking\b(?!\s+(?:there\b|on (?:it|that|this)\b|for (?:it|that|this)\b))|'
                     r'\bnothing[\w\s]{0,15}?(?:blocking|outstanding|pending|left to do)\b(?!\s+(?:there\b|on (?:it|that|this)\b|for (?:it|that|this)\b))'},
                {'if_says': 'You can archive this session',
                 'must_not_say_matching':
                     r'\bstill (?:open|pending|blocking|waiting)\b(?!\s+(?:there\b|on (?:it|that|this)\b|for (?:it|that|this)\b))|'
                     r'\bwaiting on (?:you|your)\b(?!\s+(?:there\b|on (?:it|that|this)\b|for (?:it|that|this)\b))|'
                     r'\bblocked on\b(?!\s+(?:there\b|on (?:it|that|this)\b|for (?:it|that|this)\b))|'
                     r'\bneeds? your (?:approval|input|answer|review)\b(?!\s+(?:there\b|on (?:it|that|this)\b|for (?:it|that|this)\b))|'
                     r'\bnot yet (?:pushed|merged|committed)\b(?!\s+(?:there\b|on (?:it|that|this)\b|for (?:it|that|this)\b))'},
            ],
        }]), encoding='utf-8')

        def write(name, text):
            p = tmp / name
            p.write_text(text, encoding='utf-8')
            return p

        def replycheck(path):
            return subprocess.run(
                [sys.executable, str(ROOT / 'tools' / 'precedent_reply_check.py'),
                 '--repo', str(fx), '--text', str(path)],
                capture_output=True, text=True, cwd=str(tmp),
                env={**os.environ, 'PRECEDENT_USER_CONFIG': str(tmp / 'no-such-config.json')})

        # Positive: the actual incident shape, reproduced verbatim in kind.
        bad1 = write('bad1.md',
                      '## The Boildown\n\n- Nothing further needed on this front.\n\n'
                      "Don't archive this session -- happy to keep going, but no "
                      'open work is blocking either way.\n')
        r1 = replycheck(bad1)
        cases.append(('the "no open work is blocking" + "don\'t archive" pair is '
                       'refused, naming the contradiction',
                       r1.returncode == 2 and 'cannot both be true' in r1.stderr,
                       r1.stderr[:200]))

        # Positive: the reverse pairing.
        bad2 = write('bad2.md',
                      '## The Boildown\n\n- The pull request is still open.\n\n'
                      'You can archive this session.\n')
        r2 = replycheck(bad2)
        cases.append(('the "still open" + "you can archive" pair is refused',
                       r2.returncode == 2 and 'cannot both be true' in r2.stderr,
                       r2.stderr[:200]))

        # Negative control 1: the archive sentence alone, no contradicting
        # phrase anywhere -- must pass, or the check is matching the
        # sentence by itself rather than the pair.
        clean1 = write('clean1.md',
                        "## The Boildown\n\nDon't archive this session -- PR #9 "
                        'is still waiting on your review.\n')
        r3 = replycheck(clean1)
        cases.append(("negative control: \"don't archive\" alone (with a "
                       'DIFFERENT, non-contradicting reason) is not blocked',
                       r3.returncode == 0, f'exit {r3.returncode}: {r3.stderr[:160]}'))

        # Negative control 2: the contradicting phrase alone, no fixed
        # sentence present -- must pass, since there is no pair to compare.
        clean2 = write('clean2.md',
                        '## The Boildown\n\nNothing blocking, work continues.\n')
        r4 = replycheck(clean2)
        cases.append(('negative control: the phrase alone with neither fixed '
                       'sentence present is not blocked',
                       r4.returncode == 0, f'exit {r4.returncode}: {r4.stderr[:160]}'))

        # The second incident, same day: this check's own first landing was
        # refused by itself -- the reply describing the new check quoted
        # both trigger phrases AND both contradiction patterns, in single
        # quotes, while explaining the fix. Citing a phrase as a string is
        # not asserting it; double-quoted citation is now exempt, single is
        # deliberately NOT (an apostrophe in "Don't" makes a single-quote
        # span delimiter unsafe -- see _strip_quoted_spans()'s docstring).
        meta_dq = write(
            'meta_dq.md',
            '## Boildown\n\nA reply asserting "Don\'t archive this session" can '
            'no longer also contain a "nothing blocking" phrase, and "You can '
            'archive this session" can no longer co-occur with a "still open" '
            'phrase.\n\nYou can archive this session -- the fix is pushed.\n')
        r5 = replycheck(meta_dq)
        cases.append(('a reply CITING both trigger phrases and both '
                       'contradiction patterns in double quotes, while its own '
                       'real (unquoted) verdict matches neither, is not blocked',
                       r5.returncode == 0, f'exit {r5.returncode}: {r5.stderr[:200]}'))

        # Same text, single quotes instead of double -- the documented
        # limitation, not exempt. Proves the double-quote convention is
        # actually load-bearing rather than the fix being unconditional.
        meta_sq = write(
            'meta_sq.md',
            "## Boildown\n\nA reply asserting 'Don't archive this session' can "
            "no longer also contain a 'nothing blocking' phrase, and 'You can "
            "archive this session' can no longer co-occur with a 'still open' "
            "phrase.\n\nYou can archive this session -- the fix is pushed.\n")
        r6 = replycheck(meta_sq)
        cases.append(('negative control: the same citation in SINGLE quotes is '
                       'still blocked -- double quotes are the documented '
                       'convention, not an unconditional exemption',
                       r6.returncode == 2 and 'cannot both be true' in r6.stderr,
                       f'exit {r6.returncode}: {r6.stderr[:200]}'))

        # The third incident, same day: the flat match has no notion of
        # scope, so a per-item "nothing left to do" inside one Boildown
        # bullet -- about a single closed PR -- read identically to a
        # whole-session claim. (practice: the-boildown, cite-the-incident)
        scoped1 = write(
            'scoped1.md',
            '## The Boildown\n\n- PR #165 merged, confirmed -- nothing left '
            'to do there.\n- The source add/drop question is still waiting '
            "on you -- that's what's outstanding.\n\nDon't archive this "
            'session.\n')
        r7 = replycheck(scoped1)
        cases.append(('scope exemption: "nothing left to do THERE", scoped '
                       "to one closed item, does not block \"don't archive "
                       'this session\" driven by a different, real open item',
                       r7.returncode == 0, f'exit {r7.returncode}: {r7.stderr[:200]}'))

        # Negative control: same wording, scope qualifier removed -- proves
        # the exemption is on the trailing qualifier, not on bullet-list
        # phrasing or the presence of a second, genuine open item.
        scoped1_bare = write(
            'scoped1_bare.md',
            '## The Boildown\n\n- PR #165 merged, confirmed -- nothing left '
            'to do.\n- The source add/drop question is still waiting on '
            "you -- that's what's outstanding.\n\nDon't archive this "
            'session.\n')
        r8 = replycheck(scoped1_bare)
        cases.append(('negative control: the same reply with the "there" '
                       'dropped is still blocked -- the exemption is on the '
                       'scope qualifier, not on any other feature of the text',
                       r8.returncode == 2 and 'cannot both be true' in r8.stderr,
                       f'exit {r8.returncode}: {r8.stderr[:200]}'))

        # Same scope exemption, the reverse pairing ("You can archive this
        # session" / "still open" etc.) -- the fix touches both patterns in
        # the entry, so both get their own positive/negative pair.
        scoped2 = write(
            'scoped2.md',
            '## The Boildown\n\n- The deploy step is still open on this, '
            'a separate, already-tracked cleanup with its own owner.\n\n'
            'You can archive this session.\n')
        r9 = replycheck(scoped2)
        cases.append(('scope exemption: "still open ON THIS", scoped to a '
                       'separate tracked item, does not block "you can '
                       'archive this session"',
                       r9.returncode == 0, f'exit {r9.returncode}: {r9.stderr[:200]}'))

        scoped2_bare = write(
            'scoped2_bare.md',
            '## The Boildown\n\n- The deploy step is still open, a '
            'separate, already-tracked cleanup with its own owner.\n\n'
            'You can archive this session.\n')
        r10 = replycheck(scoped2_bare)
        cases.append(('negative control: the same reply with "on this" '
                       'dropped is still blocked',
                       r10.returncode == 2 and 'cannot both be true' in r10.stderr,
                       f'exit {r10.returncode}: {r10.stderr[:200]}'))
    finally:
        shutil.rmtree(tmp, ignore_errors=True)

    bad_cases = [(c[0], c[2] if len(c) > 2 else '') for c in cases if not c[1]]
    check(f'require_no_contradiction refuses a reply asserting both halves of '
          f'the archive contradiction ({len(cases)} stated cases, each with its control)',
          not bad_cases,
          '; '.join(f"{n}{' (' + d + ')' if d else ''}" for n, d in bad_cases))


def check_reply_check_refuses_a_paste_block_that_lands_unauthorized():
    """A paste block that tells another session to land work on main
    carries the person's quoted approval, or the reply is refused.

    2026-10-01: two prompts a session wrote ended "Land it on staging per
    this repo's conventions", with no approval given; fence-block-for-paste
    passed both, since it checks where a block goes, not what it
    authorizes. Since 2026-10-02 the universal rule speaks of main, where
    work lands for a person off the ladder, and accepts any quoted approval;
    the tier branches and the quoted "Booked" are the ladder set's own copy
    of the rule (spec/LADDER_OPT_IN_PLAN.md D11). Driven against the rule
    as reply_check.json ships it (practice: prompt-please), both ways."""
    import precedent_reply_check as prc
    name = 'a paste block that lands on main needs a quoted approval'
    try:
        reqs = [r for r in json.loads((ROOT / 'reply_check.json').read_text(
            encoding='utf-8')) if r.get('require_in_fence_paired_with')]
    except (OSError, ValueError):
        reqs = []
    if not reqs:
        check(name, False, 'reply_check.json declares no require_in_fence_paired_with')
        return

    def fires(body, prose='Paste into: a new session rooted in x.\n'):
        text = prose + '```\n' + body + '\n```\n'
        return [v for v in prc.violations(text, reqs) if v['kind'] == 'in_fence_paired']
    must_fire = {
        'merge into main': 'When the checks pass, merge it into `main`.',
        'land it on main': "Do the work.\nLand it on main per this repo's conventions.",
        'a pull request into main': 'Open a pull request into main and merge it.',
    }
    clean = {
        "the person's quoted approval": 'Morgan, 2026-10-01: "Approved".\nOpen a pull request into main and merge it.',
        'a feature-branch ending': 'Build it on your feature branch, push it there, and stop.',
        'a negated line': 'Open no pull request and merge nothing into main.',
        'a shell command': 'git push -u origin main',
        'a tier branch, which off the ladder is not a landing':
            'Push it to pre-staging once it is green.',
    }
    cases = [(f'fires: {k}', bool(fires(b)), '') for k, b in must_fire.items()]
    cases += [(f'clean: {k}', not fires(b), str(fires(b))[:200]) for k, b in clean.items()]
    cases.append(("clean: the reply's own prose saying where work lands",
                  not fires('push it there and stop',
                            prose='Approved work lands on main.\nPaste into: x\n'), ''))
    bad = [(n, d) for n, ok, d in cases if not ok]
    check(f'{name} ({len(cases)} stated cases)', not bad,
          '; '.join(f'{n} {d}' for n, d in bad))


def check_reply_check_requires_a_destination_for_a_fence_block():
    """`require_paired_with` catches a reply that hands over a fenced block
    and never says where it goes.

    The incident: across 2026-09-20 and 21, Morgan asked roughly twenty
    times what session a block he had just been handed was for. Every one
    of those blocks was correctly fenced, because fence-block-for-paste
    already made the fence mandatory and said nothing about the address --
    the practice enforced the container and left out the destination.
    (practice: fence-block-for-paste, cite-the-incident)

    practice: control-asserts-which-failure -- the positive case asserts
    the guard's own message, and the two negatives prove BOTH escape routes
    work: naming a destination, and declaring the block to be output.
    """
    import tempfile
    tmp = pathlib.Path(tempfile.mkdtemp(prefix='precedent-paired-'))
    cases = []
    try:
        fx = tmp / 'repo'
        (fx / 'practices').mkdir(parents=True)
        (fx / 'precedent.json').write_text(json.dumps({'sources': [
            {'level': 'universal', 'name': 'precedent', 'path': '.'}]}),
            encoding='utf-8')
        # The gate REFUSES to print anything for a gate with no practices
        # registered to it ("an empty gate is a step that loads nothing and
        # looks like it worked"), so the fixture needs one -- otherwise the
        # print case below would pass or fail for a reason unrelated to
        # what it is testing (practice: fixture-owns-its-state).
        (fx / 'practices' / 'fixture-paired.md').write_text(
            '---\n'
            'slug:        fixture-paired\n'
            'title:       A fixture practice wired to the reply gate\n'
            'tier:        on-demand\n'
            'severity:    default\n'
            'applies_to:  []\n'
            'occasion:    "a fixture needs one practice on the reply gate"\n'
            'gates:       ["reply"]\n'
            'index_clause: "a fixture rule"\n'
            'checked_by:  null\n'
            'status:      active\n'
            'in_force_at: null\n'
            'supersedes:  []\n'
            'overrides:   null\n'
            'added:       null\n'
            'approved_by: null\n'
            '---\n\n## Rule\nA fixture rule, present so the reply gate has '
            'something registered to it.\n', encoding='utf-8')
        (fx / 'reply_check.json').write_text(json.dumps([{
            'practice': 'fixture-paired',
            'require_paired_with': [
                {'if_matches': r'^\s*```',
                 'must_also_match': r'(?:\*\*)?Paste into:|\bnot for pasting\b',
                 'why': 'say where it goes'},
            ],
        }]), encoding='utf-8')

        def write(name, text):
            q = tmp / name
            q.write_text(text, encoding='utf-8')
            return q

        def replycheck(path):
            return subprocess.run(
                [sys.executable, str(ROOT / 'tools' / 'precedent_reply_check.py'),
                 '--repo', str(fx), '--text', str(path)],
                capture_output=True, text=True, cwd=str(tmp),
                env={**os.environ,
                     'PRECEDENT_USER_CONFIG': str(tmp / 'no-such-config.json')})

        bad = write('bad.md', '## The Boildown\n\nHere it is.\n\n'
                              '```\nsome text\n```\n')
        r1 = replycheck(bad)
        cases.append(('a fence block with no destination is refused, naming '
                      'the requirement',
                      r1.returncode == 2 and 'nothing in it matches' in r1.stderr,
                      f'exit {r1.returncode}: {r1.stderr[:200]}'))

        good = write('good.md', '## The Boildown\n\n**Paste into:** the session '
                                'rooted in FooRepo.\n\n```\nsome text\n```\n')
        r2 = replycheck(good)
        cases.append(('negative control: a block WITH a named destination '
                      'passes',
                      r2.returncode == 0, f'exit {r2.returncode}: {r2.stderr[:160]}'))

        out = write('out.md', '## The Boildown\n\nMeasured, not for pasting:'
                              '\n\n```\noutput\n```\n')
        r3 = replycheck(out)
        cases.append(('negative control: a block declared output is not asked '
                      'for a destination',
                      r3.returncode == 0, f'exit {r3.returncode}: {r3.stderr[:160]}'))

        none = write('none.md', '## The Boildown\n\nNo fenced block anywhere.\n')
        r4 = replycheck(none)
        cases.append(('negative control: a reply with no fence block is '
                      'unaffected',
                      r4.returncode == 0, f'exit {r4.returncode}: {r4.stderr[:160]}'))

        # The pre-reply print must NAME it. A blocking requirement that is
        # enforced and never announced costs the person the reply twice --
        # the exact failure precedent_gate.py's own docstring records.
        r5 = subprocess.run(
            [sys.executable, str(ROOT / 'tools' / 'precedent_gate.py'),
             '--repo', str(fx), 'reply'],
            capture_output=True, text=True, cwd=str(tmp),
            env={**os.environ,
                 'PRECEDENT_USER_CONFIG': str(tmp / 'no-such-config.json')})
        cases.append(('the reply gate PRINTS this requirement before the reply',
                      'must ALSO match' in r5.stdout, r5.stdout[-200:]))
    finally:
        shutil.rmtree(tmp, ignore_errors=True)

    bad_cases = [(n, d) for n, ok, d in cases if not ok]
    return (not bad_cases, f'{len(cases)} stated cases',
            '; '.join(f'{n}: {d}' for n, d in bad_cases))


def check_reply_check_keeps_practice_ideas_at_the_close():
    """A reply offering practice ideas is refused unless it is the one that
    says the session can be archived, and the refusal says to add nothing --
    never to add the archive line to make the pair match.

    Morgan, 2026-10-05 (strength: decided): practice ideas come at the
    natural end of a conversation, not after every message.

    practice: control-asserts-which-failure -- the positive case asserts the
    pair's own repair text; the controls prove the closing reply passes and
    that prose merely mentioning practice ideas is not read as offering them.
    """
    import tempfile
    tmp = pathlib.Path(tempfile.mkdtemp(prefix='precedent-ideas-'))
    cases = []
    try:
        fx = tmp / 'repo'
        fx.mkdir()
        (fx / 'precedent.json').write_text(json.dumps({'sources': [
            {'level': 'universal', 'name': 'precedent', 'path': '.'}]}),
            encoding='utf-8')
        decl = [r for r in json.loads((ROOT / 'reply_check.json').read_text(
            encoding='utf-8')) if r.get('id') == 'practice-ideas-only-at-the-close']
        (fx / 'reply_check.json').write_text(json.dumps(decl), encoding='utf-8')

        def replycheck(name, text):
            q = tmp / name
            q.write_text(text, encoding='utf-8')
            return subprocess.run(
                [sys.executable, str(ROOT / 'tools' / 'precedent_reply_check.py'),
                 '--repo', str(fx), '--text', str(q)],
                capture_output=True, text=True, cwd=str(tmp),
                env={**os.environ,
                     'PRECEDENT_USER_CONFIG': str(tmp / 'no-such-config.json')})

        mid = ('Fixed.\n\n## Boildown\n- The work of this session is now on: '
               '`claude/x`.\n- Practice ideas:\n  - Run long checks in the '
               "background.\n- Don't archive this session.\n")
        r1 = replycheck('mid.md', mid)
        cases.append(('practice ideas mid-conversation are refused, and the '
                      'refusal asks for one withdrawing line, never the archive line',
                      r1.returncode == 2 and 'Output ONE line withdrawing them' in r1.stderr
                      and 'Output NOTHING' not in r1.stderr
                      and 'Do NOT add the archive line' in r1.stderr,
                      f'exit {r1.returncode}: {r1.stderr[:300]}'))

        for label in ('Content idea', 'Process idea'):
            r = replycheck(f'{label}.md', mid.replace('Practice ideas', label))
            cases.append((f'a "{label}:" mid-conversation is refused the same way',
                          r.returncode == 2 and 'Output ONE line withdrawing them'
                          in r.stderr, f'exit {r.returncode}: {r.stderr[:200]}'))

        close = mid.replace("- Don't archive this session.",
                            '- You can archive this session.')
        r2 = replycheck('close.md', close)
        cases.append(('negative control: the same ideas in the closing reply pass',
                      r2.returncode == 0, f'exit {r2.returncode}: {r2.stderr[:200]}'))

        prose = ('Practice ideas now come only at the close of a session.\n\n'
                 '## Boildown\n- The work of this session is now on: `x`.\n')
        r3 = replycheck('prose.md', prose)
        cases.append(('negative control: prose about practice ideas is not an offer',
                      r3.returncode == 0, f'exit {r3.returncode}: {r3.stderr[:200]}'))
    finally:
        shutil.rmtree(tmp, ignore_errors=True)

    bad_cases = [(n, d) for n, ok, d in cases if not ok]
    return (not bad_cases, f'{len(cases)} stated cases',
            '; '.join(f'{n}: {d}' for n, d in bad_cases))


def check_reply_check_refuses_a_repeated_boildown():
    """`require_section_not_repeated` refuses a Boildown whose every line says
    again what the previous reply's said, and nothing else.

    Morgan, 2026-10-05 (strength: decided): "a boildown with nothing should be
    one line", after three in a row repeated the same branch line and archive
    verdict around one new fact. The planted repeat is that day's own pair:
    the second rewords the first and adds nothing.

    practice: control-asserts-which-failure -- the positive case asserts the
    guard's own message and its say-nothing repair; the controls prove a new
    fact, a changed branch, the one-line form, a first reply and a missing
    transcript all pass.
    """
    import tempfile
    tmp = pathlib.Path(tempfile.mkdtemp(prefix='precedent-repeat-'))
    cases = []
    try:
        fx = tmp / 'repo'
        fx.mkdir()
        (fx / 'precedent.json').write_text(json.dumps({'sources': [
            {'level': 'universal', 'name': 'precedent', 'path': '.'}]}),
            encoding='utf-8')
        (fx / 'reply_check.json').write_text(json.dumps([{
            'practice': 'fixture-repeat',
            'require_section_not_repeated': {
                'heading': 'boildown',
                'one_line': '- The work of this session is now on: <x>, '
                            'unchanged since the last update.',
                'same_when_both_say': ["Don't archive this session",
                                       'You can archive this session']},
        }]), encoding='utf-8')

        def transcript(name, replies):
            path = tmp / name
            path.write_text('\n'.join(json.dumps({
                'type': 'assistant', 'message': {
                    'usage': {'input_tokens': 2},
                    'content': [{'type': 'text', 'text': r}]}})
                for r in replies) + '\n', encoding='utf-8')
            return path

        def run(path):
            return subprocess.run(
                [sys.executable, str(ROOT / 'tools' / 'precedent_reply_check.py'),
                 '--repo', str(fx)],
                input=json.dumps({'transcript_path': str(path)}),
                capture_output=True, text=True, cwd=str(tmp),
                env={**os.environ,
                     'PRECEDENT_USER_CONFIG': str(tmp / 'no-such-config.json')})

        first = ('Harness passed.\n\n## Boildown\n'
                 '- The work of this session is now on: `claude/x-btnxe` '
                 '(BestPractice), pushed but not landed.\n'
                 '- **Your call:** say "Booked" to land it on `pre-staging`. '
                 'My pick is yes.\n'
                 "- Don't archive this session. Archived now, the work never "
                 'lands.\n')
        again = ('That notice is the result I already reported.\n\n## Boildown\n'
                 '- The work of this session is now on: `claude/x-btnxe` '
                 '(BestPractice), pushed but not landed.\n'
                 '- Next is your "Booked" to land it on `pre-staging`.\n'
                 "- Don't archive this session. The work would stay on its "
                 'feature branch.\n')
        r1 = run(transcript('repeat.jsonl', [first, again]))
        cases.append(('a reworded Boildown with nothing new is refused, '
                      'asking for the one-line form and nothing more -- never '
                      'for nothing, which the harness does not accept',
                      r1.returncode == 2 and 'previous reply' in r1.stderr
                      and 'unchanged since the last update' in r1.stderr
                      and 'Output ONLY the one-line form' in r1.stderr
                      and 'Output NOTHING' not in r1.stderr,
                      f'exit {r1.returncode}: {r1.stderr[:300]}'))

        news = again.replace('- Next is your "Booked" to land it on `pre-staging`.',
                             '- The harness found a broken link, fixed in the '
                             'last commit.')
        r2 = run(transcript('news.jsonl', [first, news]))
        cases.append(('negative control: one new line makes it a real update',
                      r2.returncode == 0, f'exit {r2.returncode}: {r2.stderr[:200]}'))

        moved = again.replace('`claude/x-btnxe` (BestPractice), pushed but not '
                              'landed', '`pre-staging` (BestPractice), landed')
        moved = moved.replace("- Don't archive this session. The work would stay "
                              'on its feature branch.',
                              "- Don't archive this session. Staging still waits.")
        moved = moved.replace('- Next is your "Booked" to land it on `pre-staging`.',
                              '- Landed on `pre-staging`.')
        r3 = run(transcript('moved.jsonl', [first, moved]))
        cases.append(('negative control: a branch that changed is a change, '
                      'however alike the words',
                      r3.returncode == 0, f'exit {r3.returncode}: {r3.stderr[:200]}'))

        short = ('Same as before.\n\n## Boildown\n- The work of this session '
                 'is now on: `claude/x-btnxe`, unchanged since the last update.\n')
        r4 = run(transcript('short.jsonl', [first, short]))
        cases.append(('negative control: the one-line form passes',
                      r4.returncode == 0, f'exit {r4.returncode}: {r4.stderr[:200]}'))

        r5 = run(transcript('only.jsonl', [first]))
        cases.append(('negative control: a first Boildown has nothing to repeat',
                      r5.returncode == 0, f'exit {r5.returncode}: {r5.stderr[:200]}'))

        r6 = run(tmp / 'no-such-transcript.jsonl')
        cases.append(('negative control: no transcript, no refusal',
                      r6.returncode == 0, f'exit {r6.returncode}: {r6.stderr[:200]}'))
    finally:
        shutil.rmtree(tmp, ignore_errors=True)

    bad_cases = [(n, d) for n, ok, d in cases if not ok]
    return (not bad_cases, f'{len(cases)} stated cases',
            '; '.join(f'{n}: {d}' for n, d in bad_cases))


def check_reply_check_keeps_quiet_while_a_batch_runs():
    """`require_quiet_while_background_runs` refuses any prose on a turn a
    background job woke while another background command is still running,
    or that a Monitor's progress event woke; the batch reports once.

    Morgan, 2026-10-05 (strength: decided), after four Debuts run in sequence
    reported themselves one at a time, each with its own Boildown: a reply to
    a job finishing gets no Boildown unless the job is done, and a batch
    reports once. The planted transcripts use that day's shapes: the
    harness's own "Command running in background with ID" result, a
    notification as the turn's prompt, and one that ended mid-turn as an
    `attachment` row.

    practice: control-asserts-which-failure -- the positive cases assert the
    guard's own say-nothing repair; the controls prove the batch's final
    report still needs (and passes with) its Boildown, a failure may speak,
    a silent turn is not judged by the last turn's words, and printed text
    that merely quotes the started line starts nothing.
    """
    import tempfile
    tmp = pathlib.Path(tempfile.mkdtemp(prefix='precedent-quiet-'))
    cases = []
    try:
        fx = tmp / 'repo'
        fx.mkdir()
        (fx / 'precedent.json').write_text(json.dumps({'sources': [
            {'level': 'universal', 'name': 'precedent', 'path': '.'}]}),
            encoding='utf-8')
        (fx / 'reply_check.json').write_text(json.dumps([
            {'practice': 'fixture-quiet', 'require_heading_matching': 'boildown'},
            {'practice': 'fixture-quiet',
             'require_quiet_while_background_runs': {'why': 'reports once'}},
        ]), encoding='utf-8')

        def human(t):
            return {'type': 'user', 'origin': {'kind': 'human'},
                    'message': {'role': 'user', 'content': t}}

        def started(task_id, extra=''):
            return {'type': 'user', 'message': {'role': 'user', 'content': [
                {'type': 'tool_result', 'tool_use_id': 't-' + task_id,
                 'content': extra + 'Command running in background with ID: '
                            f'{task_id}. Output is being written to: x'}]}}

        def notice(task_id, status=None, summary='', event=''):
            body = f'<task-id>{task_id}</task-id>'
            body += f'<status>{status}</status>' if status else ''
            body += f'<summary>{summary}</summary>' if summary else ''
            body += f'<event>{event}</event>' if event else ''
            return f'<task-notification>\n{body}\n</task-notification>'

        def wake(text):
            return {'type': 'user', 'origin': {'kind': 'task-notification'},
                    'message': {'role': 'user', 'content': text}}

        def said(t):
            return {'type': 'assistant', 'message': {
                'usage': {'input_tokens': 2},
                'content': [{'type': 'text', 'text': t}] if t else
                           [{'type': 'tool_use', 'id': 'u', 'name': 'Bash',
                             'input': {}}]}}

        def transcript(name, rows):
            path = tmp / name
            path.write_text('\n'.join(json.dumps(r) for r in rows) + '\n',
                            encoding='utf-8')
            return path

        def run(path):
            return subprocess.run(
                [sys.executable, str(ROOT / 'tools' / 'precedent_reply_check.py'),
                 '--repo', str(fx)],
                input=json.dumps({'transcript_path': str(path)}),
                capture_output=True, text=True, cwd=str(tmp),
                env={**os.environ,
                     'PRECEDENT_USER_CONFIG': str(tmp / 'no-such-config.json')})

        report = ('Individual passed.\n\n## Boildown\n- The work of this '
                  'session is now on: `staging` (individual).\n')
        opening = [human('Debut all four'), said(''), started('aaa'),
                   started('bbb'), said('Both running.\n\n## Boildown\n- x\n')]
        done_ok = 'Background command "a" completed (exit code 0)'

        r1 = run(transcript('one-of-two.jsonl', opening + [
            wake(notice('aaa', 'completed', done_ok)), said(report)]))
        cases.append(('one job of two done: a report is refused, naming the '
                      'one still running and asking for one waiting line',
                      r1.returncode == 2 and 'bbb' in r1.stderr
                      and 'Output ONE line naming the wait' in r1.stderr
                      and 'Output NOTHING' not in r1.stderr,
                      f'exit {r1.returncode}: {r1.stderr[:300]}'))

        r2 = run(transcript('progress.jsonl', [
            human('watch it'), said('Watching.\n\n## Boildown\n- x\n'),
            wake(notice('mon', event='individual done: exit 0')),
            said('Individual passed.')]))
        cases.append(('a Monitor progress event, nothing else running: prose '
                      'is refused', r2.returncode == 2
                      and 'progress event' in r2.stderr,
                      f'exit {r2.returncode}: {r2.stderr[:300]}'))

        r3 = run(transcript('silent.jsonl', opening[:-1] + [
            said('Started, no closing section here.'),
            wake(notice('aaa', 'completed', done_ok)), said('')]))
        cases.append(('negative control: a silent wake passes, and is not '
                      'judged by the last turn\'s words',
                      r3.returncode == 0, f'exit {r3.returncode}: {r3.stderr[:200]}'))

        # One waiting line is what a quiet wake owes (2026-10-06): an empty
        # turn makes the harness ask for visible output.
        r3b = run(transcript('wait-line.jsonl', opening[:-1] + [
            said('Started, no closing section here.'),
            wake(notice('aaa', 'completed', done_ok)),
            said('(Waiting on bbb.)')]))
        cases.append(('one waiting line in parentheses passes on a quiet wake',
                      r3b.returncode == 0, f'exit {r3b.returncode}: {r3b.stderr[:200]}'))
        r3c = run(transcript('two-lines.jsonl', opening[:-1] + [
            said('Started, no closing section here.'),
            wake(notice('aaa', 'completed', done_ok)),
            said('(Waiting on bbb.)\nAlso, aaa passed.')]))
        cases.append(('...but a second line makes it a report, refused',
                      r3c.returncode == 2, f'exit {r3c.returncode}: {r3c.stderr[:200]}'))

        ended_mid_turn = {'type': 'attachment', 'attachment': {
            'type': 'queued_command',
            'prompt': notice('bbb', 'completed', done_ok)}}
        last = opening + [ended_mid_turn, wake(notice('aaa', 'completed', done_ok))]
        r4 = run(transcript('last-done.jsonl', last + [said(report)]))
        cases.append(('negative control: the last job done, the one report with '
                      'its Boildown passes (the other ended mid-turn)',
                      r4.returncode == 0, f'exit {r4.returncode}: {r4.stderr[:200]}'))

        r5 = run(transcript('last-done-bare.jsonl', last + [
            said('All four passed.')]))
        cases.append(('the batch\'s one report still needs its Boildown',
                      r5.returncode == 2 and 'HEADING' in r5.stderr,
                      f'exit {r5.returncode}: {r5.stderr[:200]}'))

        r6 = run(transcript('failed.jsonl', opening + [
            wake(notice('aaa', 'completed',
                        'Background command "a" completed (exit code 1)')),
            said(report)]))
        cases.append(('negative control: a wake reporting a failure may speak '
                      'while the batch runs', r6.returncode == 0,
                      f'exit {r6.returncode}: {r6.stderr[:200]}'))

        quoted = [human('show me'), said(''),
                  started('aaa'),
                  {'type': 'user', 'message': {'role': 'user', 'content': [
                      {'type': 'tool_result', 'tool_use_id': 'cat',
                       'content': 'log says: Command running in background '
                                  'with ID: zzz.'}]}},
                  said('Running.\n\n## Boildown\n- x\n'),
                  wake(notice('aaa', 'completed', done_ok)), said(report)]
        r7 = run(transcript('quoted.jsonl', quoted))
        cases.append(('negative control: printed text quoting the started line '
                      'starts no job', r7.returncode == 0,
                      f'exit {r7.returncode}: {r7.stderr[:200]}'))

        r8 = run(transcript('human.jsonl', opening + [
            human('how is it going?'), said('Still running.')]))
        cases.append(('a person\'s question mid-batch is answered as ever: '
                      'the Boildown is still required',
                      r8.returncode == 2 and 'HEADING' in r8.stderr,
                      f'exit {r8.returncode}: {r8.stderr[:200]}'))
    finally:
        shutil.rmtree(tmp, ignore_errors=True)

    bad_cases = [(n, d) for n, ok, d in cases if not ok]
    return (not bad_cases, f'{len(cases)} stated cases',
            '; '.join(f'{n}: {d}' for n, d in bad_cases))


def check_code_owners_only_practices_reach_only_code_owners():
    """A practice marked `visible_to: code-owners` reaches only a person the
    repository names as a code owner, and a stale-branch listing never names
    main, staging, pre-staging or an engine branch.

    Morgan, 2026-10-05 (strength: decided): rules about running a repository
    "should NOT be shown to a user who is NOT a CODEOWNER"; in doubt, hidden;
    and the branch list is "never pre-staging or staging".

    practice: control-asserts-which-failure -- each hidden case asserts the
    reason printed, and the controls prove an owner, an unmarked practice and
    a merged branch all still come through.
    """
    import tempfile
    tmp = pathlib.Path(tempfile.mkdtemp(prefix='precedent-audience-'))
    cases = []
    try:
        env = {**os.environ, 'PRECEDENT_USER_CONFIG': str(tmp / 'no-config.json')}
        env.pop('PRECEDENT_GITHUB_USER', None)
        env.pop('PRECEDENT_COMMIT_EMAIL', None)

        def audience(repo, user):
            e = dict(env)
            if user:
                e['PRECEDENT_GITHUB_USER'] = user
            r = subprocess.run([sys.executable, str(ROOT / 'tools' / 'precedent_audience.py'),
                                '--repo', str(repo)], capture_output=True, text=True, env=e)
            return r.stdout.strip()

        a = tmp / 'with-codeowners'
        (a / '.github').mkdir(parents=True)
        (a / '.github' / 'CODEOWNERS').write_text('*  @Owner-One @org/team\n', encoding='utf-8')
        cases.append(('a CODEOWNERS entry makes a code owner, whatever the case',
                      audience(a, 'owner-one').startswith('code owner:'), audience(a, 'owner-one')))
        cases.append(('someone CODEOWNERS does not name is not one',
                      audience(a, 'someone').startswith('not a code owner:'), audience(a, 'someone')))
        cases.append(('no username declared: hidden, and the fix named',
                      'add "github"' in audience(a, ''), audience(a, '')))
        b = tmp / 'with-maintainers'
        b.mkdir()
        (b / 'precedent.json').write_text(json.dumps(
            {'maintainers': [{'name': 'M', 'github': 'maint'}]}), encoding='utf-8')
        cases.append(("no CODEOWNERS: precedent.json's maintainers answer instead",
                      audience(b, 'maint').startswith('code owner:'), audience(b, 'maint')))
        # A commit-email override (as a cloud environment sets) still takes
        # the username from the person's own identity.json.
        ind = tmp / 'individual'
        ind.mkdir()
        (ind / 'identity.json').write_text(json.dumps(
            {'email': 'm@example.com', 'github': 'maint'}), encoding='utf-8')
        (tmp / 'config.json').write_text(json.dumps(
            {'individual': {'path': str(ind)}}), encoding='utf-8')
        e2 = dict(env, PRECEDENT_USER_CONFIG=str(tmp / 'config.json'),
                  PRECEDENT_COMMIT_EMAIL='m@example.com')
        r2 = subprocess.run([sys.executable, str(ROOT / 'tools' / 'precedent_audience.py'),
                             '--repo', str(b)], capture_output=True, text=True, env=e2)
        cases.append(('with a commit-email override, the username still comes '
                      'from identity.json', r2.stdout.startswith('code owner:'),
                      r2.stdout + r2.stderr))
        c = tmp / 'nobody'
        c.mkdir()
        cases.append(('no owners named anywhere: in doubt, hidden',
                      'names no code owners' in audience(c, 'maint'), audience(c, 'maint')))
        # Nothing declared, but a GitHub origin: the account that owns the
        # repository is its owner (2026-10-06: a consumer's only member was
        # refused the Produce rule because nothing named him).
        o = tmp / 'owned'
        o.mkdir()
        subprocess.run(['git', 'init', '-q', str(o)], capture_output=True)
        subprocess.run(['git', '-C', str(o), 'remote', 'add', 'origin',
                        'https://github.com/Repo-Owner/some-repo.git'],
                       capture_output=True)
        cases.append(("nothing declared: the GitHub origin's owner is a code owner",
                      audience(o, 'repo-owner').startswith('code owner:'),
                      audience(o, 'repo-owner')))
        cases.append(("...and someone else is still not one",
                      audience(o, 'someone').startswith('not a code owner:'),
                      audience(o, 'someone')))

        # precedent_show prints the marked practice to an owner only.
        (b / 'practices').mkdir()
        shutil.copy(ROOT / 'practices' / 'deep-check.md', b / 'practices')
        shutil.copy(ROOT / 'practices' / 'repo-is-memory.md', b / 'practices')

        def show(user, slug):
            e = dict(env, PRECEDENT_GITHUB_USER=user)
            return subprocess.run([sys.executable, str(ROOT / 'tools' / 'precedent_show.py'),
                                   '--repo', str(b), slug], capture_output=True,
                                  text=True, env=e).stdout
        cases.append(('precedent_show hides a marked practice from a stranger, saying why',
                      'code owners only' in show('stranger', 'deep-check'),
                      show('stranger', 'deep-check')[:200]))
        cases.append(('CONTROL: an owner reads it',
                      'code owners only' not in show('maint', 'deep-check')
                      and 'audit' in show('maint', 'deep-check'),
                      show('maint', 'deep-check')[:200]))
        cases.append(('CONTROL: an unmarked practice reaches everyone',
                      'code owners only' not in show('stranger', 'repo-is-memory'),
                      show('stranger', 'repo-is-memory')[:200]))

        # The stale-branch listing.
        sys.path.insert(0, str(ROOT / 'tools'))
        import precedent_stale_branches as sb
        genv = dict(os.environ, GIT_AUTHOR_NAME='t', GIT_AUTHOR_EMAIL='t@t',
                    GIT_COMMITTER_NAME='t', GIT_COMMITTER_EMAIL='t@t')
        origin, work = tmp / 'origin.git', tmp / 'work'

        def g(*a, cwd=work):
            return subprocess.run(['git', '-C', str(cwd), *a], capture_output=True,
                                  text=True, env=genv)
        subprocess.run(['git', 'init', '-q', '--bare', '-b', 'main', str(origin)],
                       capture_output=True)
        subprocess.run(['git', 'clone', '-q', str(origin), str(work)], capture_output=True)
        (work / 'a.txt').write_text('a\n'); g('add', '-A'); g('commit', '-qm', 'a')
        g('push', '-q', 'origin', 'HEAD:main')
        for b_ in ('staging', 'pre-staging', 'precedent-promote-lock', 'claude/done'):
            g('push', '-q', 'origin', f'HEAD:refs/heads/{b_}')
        g('checkout', '-q', '-b', 'claude/open')
        (work / 'b.txt').write_text('b\n'); g('add', '-A'); g('commit', '-qm', 'b')
        g('push', '-q', 'origin', 'claude/open')
        g('fetch', '-q', 'origin')
        listed = [b_ for b_, _d in (sb.stale_in(work) or [])]
        cases.append(('a branch already in main is listed', 'claude/done' in listed, listed))
        cases.append(('never main, staging, pre-staging or an engine branch',
                      not {'main', 'staging', 'pre-staging', 'precedent-promote-lock'} & set(listed),
                      listed))
        cases.append(('CONTROL: a branch with work main lacks is not listed',
                      'claude/open' not in listed, listed))
    finally:
        shutil.rmtree(tmp, ignore_errors=True)
    bad_cases = [(n, d) for n, ok, d in cases if not ok]
    return (not bad_cases, f'{len(cases)} stated cases',
            '; '.join(f'{n}: {d}' for n, d in bad_cases))


def check_reply_check_requires_the_boildown_first_line():
    """`require_first_item_under_heading` refuses a Boildown whose first
    bullet does not say where the work is.

    Morgan, 2026-09-29: the first bullet under The Boildown names the branch
    the session's work is on and the stage it finished, in every reply
    (practice: the-boildown).

    practice: control-asserts-which-failure -- the positive cases assert the
    guard's own message; the negatives prove the right line passes with or
    without bold, and that a reply with no heading is left to the heading
    check rather than reported twice.
    """
    import tempfile
    tmp = pathlib.Path(tempfile.mkdtemp(prefix='precedent-firstitem-'))
    cases = []
    try:
        fx = tmp / 'repo'
        fx.mkdir()
        (fx / 'precedent.json').write_text(json.dumps({'sources': [
            {'level': 'universal', 'name': 'precedent', 'path': '.'}]}),
            encoding='utf-8')
        (fx / 'reply_check.json').write_text(json.dumps([{
            'practice': 'fixture-first-item',
            'require_first_item_under_heading': {
                'heading': 'boildown',
                'matching': r'^\s*the work of this session is now on\s*:'},
        }]), encoding='utf-8')

        def replycheck(name, text):
            q = tmp / name
            q.write_text(text, encoding='utf-8')
            return subprocess.run(
                [sys.executable, str(ROOT / 'tools' / 'precedent_reply_check.py'),
                 '--repo', str(fx), '--text', str(q)],
                capture_output=True, text=True, cwd=str(tmp),
                env={**os.environ,
                     'PRECEDENT_USER_CONFIG': str(tmp / 'no-such-config.json')})

        r1 = replycheck('bad.md', 'Done.\n\n## The Boildown\n\n'
                                  '- **Your next steps.** Nothing.\n')
        cases.append(('a Boildown opening on another bullet is refused, naming '
                      'the requirement',
                      r1.returncode == 2 and 'first bullet' in r1.stderr,
                      f'exit {r1.returncode}: {r1.stderr[:200]}'))

        r2 = replycheck('prose.md', '## The Boildown\n\nSome prose first.\n\n'
                                    '- The work of this session is now on: x\n')
        cases.append(('a Boildown opening on prose, not a bullet, is refused',
                      r2.returncode == 2, f'exit {r2.returncode}'))

        r3 = replycheck('good.md', '## The Boildown\n\n- **The work of this '
                                   'session is now on:** `pre-staging` (you have '
                                   'finished step 3 of 5, Booked)\n- Next.\n')
        cases.append(('negative control: the bold first line passes',
                      r3.returncode == 0, f'exit {r3.returncode}: {r3.stderr[:160]}'))

        r4 = replycheck('plain.md', '## The Boildown\n\n- The work of this '
                                    'session is now on: no branch yet (you have '
                                    'finished step 1 of 5, Consider)\n')
        cases.append(('negative control: the plain first line passes',
                      r4.returncode == 0, f'exit {r4.returncode}: {r4.stderr[:160]}'))

        r5 = replycheck('none.md', 'No heading at all.\n')
        cases.append(('negative control: no heading is the heading check\'s '
                      'case, not this one',
                      r5.returncode == 0, f'exit {r5.returncode}: {r5.stderr[:160]}'))
    finally:
        shutil.rmtree(tmp, ignore_errors=True)

    bad_cases = [(n, d) for n, ok, d in cases if not ok]
    return (not bad_cases, f'{len(cases)} stated cases',
            '; '.join(f'{n}: {d}' for n, d in bad_cases))


def _beta_watermark_fixture(tmp, git, branch='staging'):
    """A bare origin, a seed clone to land commits through, and the WORK
    clone the tool runs in -- which is now the same repository the watermark
    lives in, so it needs a tools/ directory and a .gitignore carrying
    .precedent/, exactly as this repo has.

    -> (origin, seed, work, land) where land(text, author) puts one commit
    on origin authored by whoever you name."""
    origin = tmp / 'origin-bp'
    git(tmp, 'init', '-q', '--bare', '-b', branch, str(origin))
    seed = tmp / 'seed'
    git(tmp, 'clone', '-q', str(origin), str(seed))
    git(seed, 'config', 'user.email', 'harness@example.com')
    git(seed, 'config', 'user.name', 'harness')
    (seed / 'tools').mkdir()
    (seed / 'tools' / 'keep.txt').write_text('so tools/ exists\n', encoding='utf-8')
    (seed / '.gitignore').write_text('.precedent/\n', encoding='utf-8')

    def land(text, author):
        # The WORK clone pushes to this same origin now that the watermark
        # lives in its own repository, so the seed has to catch up first or
        # every land() after the first watermark commit is rejected.
        # Tolerant on the FIRST land, when origin carries no branch yet.
        if subprocess.run(['git', '-C', str(seed), 'fetch', '-q', 'origin',
                            branch], capture_output=True).returncode == 0:
            git(seed, 'reset', '-q', '--hard', f'origin/{branch}')
        (seed / 'f.txt').write_text(text, encoding='utf-8')
        git(seed, 'add', '-A')
        git(seed, 'commit', '-qm', text, author=author)
        git(seed, 'push', '-q', 'origin', branch)

    return origin, seed, land


def check_vocabulary_prefers_the_file_you_are_standing_on():
    """A practice defined both in this repo and in a resolved source is read
    from THIS repo's file, and the collision is named either way.

    THE HOUR IT COST, 2026-09-21. A session in a practice source removed a
    `command:` field, ran precedent_vocabulary.py to confirm the row was
    gone, and got the old row back. `cat` showed the edit. `git diff` showed
    the edit. The commit landed. Only the tool disagreed, and the natural
    reading of that is that you edited the wrong field or the frontmatter
    parse is fussy -- neither of which leaves a trace when you test it.

    `collect()` built one dict keyed by slug: local `practices/*.md` first,
    then everything the resolver returned, assigned with a bare
    `found[slug] = ...`. In a CONSUMING repo that precedence is right and
    the slugs never collide. In a repo that IS one of those sources, both
    halves are the same practice from two different checkouts and the local
    edit lost in silence.

    Planted rather than reproduced against the real disk, deliberately: the
    condition is a resolved source whose path is not the repo you are
    standing in, and whether any given container is in that state changes
    with its config. A check that only fires on a machine that happens to be
    misconfigured is a check that reports the weather.

    Four cases, and the two negative controls are the load-bearing ones: a
    slug that exists ONLY in the resolved source still comes from there
    (this is not "ignore the resolver"), and --resolved-view still reaches
    the old behaviour for a caller that wants it.
    """
    import shutil, tempfile
    sys.path.insert(0, str(ROOT / 'tools'))
    import precedent_vocabulary as pv

    def practice(slug, phrase, title):
        return (f'---\nslug:        {slug}\n'
                f'title:       {title}\n'
                'tier:        on-demand\nseverity:    default\n'
                'applies_to:  []\n'
                f'occasion:    "a fixture practice for {slug}"\n'
                'gates:       []\n'
                f'command:     {{"{phrase}": "a fixture command"}}\n'
                f'index_clause: "{phrase} -- a fixture"\n'
                'checked_by:  null\nstatus:      active\nin_force_at: null\n'
                'supersedes:  []\noverrides:   null\nadded:       null\n'
                'approved_by: null\n---\n\n## Rule\nA fixture rule.\n')

    tmp = pathlib.Path(tempfile.mkdtemp(prefix='vocab-shadow-'))
    try:
        # `other` stands in for the checkout the resolver reaches: same
        # slug, older text. `here` is the repo the tool runs in.
        other = tmp / 'other'
        (other / 'practices').mkdir(parents=True)
        (other / 'practices' / 'fixture-shadowed.md').write_text(
            practice('fixture-shadowed', 'Stale Phrase', 'A shadowed fixture'),
            encoding='utf-8')
        (other / 'practices' / 'fixture-resolved-only.md').write_text(
            practice('fixture-resolved-only', 'Resolved Only Phrase',
                      'Only in the resolved source'), encoding='utf-8')
        (other / 'precedent.json').write_text('{"sources": []}', encoding='utf-8')

        here = tmp / 'here'
        (here / 'practices').mkdir(parents=True)
        # The edit in front of you: same slug, different phrase.
        (here / 'practices' / 'fixture-shadowed.md').write_text(
            practice('fixture-shadowed', 'Live Phrase', 'A shadowed fixture'),
            encoding='utf-8')
        (here / 'precedent.json').write_text(json.dumps({'sources': [
            {'level': 'universal', 'name': 'precedent', 'path': '../other'}]}),
            encoding='utf-8')

        env_cfg = str(tmp / 'no-such-user-config.json')
        saved = os.environ.get('PRECEDENT_USER_CONFIG')
        os.environ['PRECEDENT_USER_CONFIG'] = env_cfg
        try:
            entries, notes = pv.collect(here)
            entries_rv, notes_rv = pv.collect(here, resolved_view=True)
        finally:
            if saved is None:
                os.environ.pop('PRECEDENT_USER_CONFIG', None)
            else:
                os.environ['PRECEDENT_USER_CONFIG'] = saved

        phrases = {e[0] for e in entries}
        phrases_rv = {e[0] for e in entries_rv}
        levels = {e[0]: (e[3], e[4]) for e in entries}

        cases = [
            ('the file you are standing on wins over a resolved copy of the '
             'same slug',
             'Live Phrase' in phrases and 'Stale Phrase' not in phrases,
             f'{sorted(phrases)}'),
            ('and the collision is NAMED, with both paths and the winner -- '
             'the silence was the whole defect',
             any('fixture-shadowed' in n and str(here) in n
                 and str(other) in n for n in notes), f'{notes}'),
            ('the local file keeps the RESOLVED label, since a local read '
             'cannot know which level it is standing in',
             levels.get('Live Phrase') == ('universal', 'precedent'),
             f'{levels.get("Live Phrase")}'),
            ('negative control: a slug only the resolver has still comes '
             'from there -- this is not "ignore the resolver"',
             'Resolved Only Phrase' in phrases, f'{sorted(phrases)}'),
            ('negative control: --resolved-view still reaches the old '
             'precedence for a caller that wants it',
             'Stale Phrase' in phrases_rv and 'Live Phrase' not in phrases_rv,
             f'{sorted(phrases_rv)}'),
            ('...and names the collision there too, pointing the other way',
             any('fixture-shadowed' in n for n in notes_rv), f'{notes_rv}'),
        ]
        ok = all(passed for _, passed, _ in cases)
        for name, passed, detail in cases:
            if not passed:
                print(f"  vocabulary precedence did NOT behave as stated: "
                      f"{name} [{detail}]")
        check(f'precedent_vocabulary reads the file you are standing on, and '
              f'names the collision ({len(cases)} stated cases)', ok)
    finally:
        shutil.rmtree(tmp, ignore_errors=True)


@_without_session_id
def check_archive_guard_refuses_work_left_on_a_feature_branch():
    """`require_landed_if_says` refuses the archive sentence while a feature
    branch holds work its repo has not landed, and accepts it once each such
    branch is named in a `**Branch disposition:** BRANCH -- drop` line
    (spec/FIVE_STAGES_AND_OUR_LANGUAGE_PLAN.md, step 7).

    Two halves, because they fail differently. The FINDER is run on a
    fixture repo with a real feature branch ahead of its landing branch, so
    the parse of precedent_gate's NOT YET LANDED line is tested against the
    line that function really prints. The VERDICT is run with the finder
    pinned, so the escape and its negative controls do not depend on
    whatever this machine's own clones happen to hold. Owns its state.
    """
    import tempfile
    sys.path.insert(0, str(ROOT / 'tools'))
    import precedent_reply_check as rc
    tmp = pathlib.Path(tempfile.mkdtemp(prefix='archive-guard-'))
    env = dict(os.environ, GIT_AUTHOR_NAME='Fixture', GIT_AUTHOR_EMAIL='f@example.com',
               GIT_COMMITTER_NAME='Fixture', GIT_COMMITTER_EMAIL='f@example.com')

    def git(*a, cwd):
        return subprocess.run(['git', *a], cwd=str(cwd), env=env,
                              capture_output=True, text=True)
    cases = []
    real = rc._stranded_branches
    try:
        origin = tmp / 'origin.git'
        git('init', '-q', '--bare', '-b', 'main', str(origin), cwd=tmp)
        repo = tmp / 'repo'
        git('clone', '-q', str(origin), str(repo), cwd=tmp)
        (repo / 'precedent.json').write_text('{"base_branch": "main"}\n', encoding='utf-8')
        git('add', '-A', cwd=repo); git('commit', '-qm', 'base', cwd=repo)
        git('push', '-q', 'origin', 'HEAD:main', cwd=repo)
        git('fetch', '-q', 'origin', cwd=repo)
        git('checkout', '-q', '-b', 'claude/fixture-abc123', cwd=repo)
        (repo / 'work.md').write_text('finished work\n', encoding='utf-8')
        git('add', '-A', cwd=repo); git('commit', '-qm', 'work', cwd=repo)

        found = rc._stranded_branches(str(repo), siblings=False)
        cases.append(('the finder reports a feature branch ahead of its landing branch',
                      ('this checkout', 'claude/fixture-abc123') in found, f'{found}'))
        git('checkout', '-q', 'main', cwd=repo)
        clean = rc._stranded_branches(str(repo), siblings=False)
        cases.append(('negative control: on the landing branch itself, nothing is stranded',
                      clean == [], f'{clean}'))

        rc._stranded_branches = lambda *a, **k: [('this checkout', 'claude/fixture-abc123')]
        req = [{'practice': 'ladder-required', '_source': 'individual/fixture',
                'require_landed_if_says': ['You can archive this session']}]
        kinds = lambda text: [v['kind'] for v in rc.violations(text, req)]
        cases += [
            ('the archive sentence is refused while work sits on a feature branch',
             'landed' in kinds('Done.\n\nYou can archive this session.'), ''),
            ('a **Branch disposition:** line naming that branch lets it through',
             'landed' not in kinds('**Branch disposition:** claude/fixture-abc123 -- '
                                   'drop (superseded)\n\nYou can archive this session.'), ''),
            ('negative control: a disposition naming a DIFFERENT branch does not',
             'landed' in kinds('**Branch disposition:** claude/other -- drop (x)\n\n'
                               'You can archive this session.'), ''),
            ('negative control: "Don\'t archive this session" is never refused by it',
             'landed' not in kinds("Don't archive this session."), ''),
        ]
    finally:
        rc._stranded_branches = real
        shutil.rmtree(tmp, ignore_errors=True)
    ok = all(passed for _, passed, _ in cases)
    for name, passed, detail in cases:
        if not passed:
            print(f"  archive guard did NOT behave as stated: {name} [{detail}]")
    check(f'the archive guard refuses work left on a feature branch, and '
          f'accepts a named drop ({len(cases)} stated cases)', ok)


def check_vocabulary_moves_a_word_to_our_language():
    """A `command:` phrase that is also a word in tools/our_language.json
    prints under "Our language", not among the commands, and the word list
    is read from that one registry (spec/FIVE_STAGES_AND_OUR_LANGUAGE_PLAN.md
    step 2).

    "Primary branch" and "Tier branch" name things, not actions -- Morgan,
    2026-09-27 and 2026-09-28, asked for both to sit with the words. The
    negative control is the load-bearing case: an ordinary command in the
    same fixture must still be listed, or the filter is just dropping rows.
    """
    import shutil, tempfile
    sys.path.insert(0, str(ROOT / 'tools'))
    import precedent_vocabulary as pv
    import our_language as ol

    def practice(slug, phrase):
        return (f'---\nslug:        {slug}\n'
                f'title:       A fixture for {slug}\n'
                'tier:        on-demand\nseverity:    default\n'
                'applies_to:  []\n'
                f'occasion:    "a fixture practice for {slug}"\n'
                'gates:       []\n'
                f'command:     {{"{phrase}": "a fixture gloss"}}\n'
                f'index_clause: "{phrase} -- a fixture"\n'
                'checked_by:  null\nstatus:      active\nin_force_at: null\n'
                'supersedes:  []\noverrides:   null\nadded:       null\n'
                'approved_by: null\n---\n\n## Rule\nA fixture rule.\n')

    tmp = pathlib.Path(tempfile.mkdtemp(prefix='vocab-words-'))
    try:
        (tmp / 'practices').mkdir(parents=True)
        (tmp / 'practices' / 'fixture-word.md').write_text(
            practice('fixture-word', 'Primary branch'), encoding='utf-8')
        (tmp / 'practices' / 'fixture-command.md').write_text(
            practice('fixture-command', 'Fixture Command'), encoding='utf-8')
        (tmp / 'precedent.json').write_text('{"sources": []}', encoding='utf-8')
        saved = os.environ.get('PRECEDENT_USER_CONFIG')
        os.environ['PRECEDENT_USER_CONFIG'] = str(tmp / 'no-such-config.json')
        try:
            entries, _notes = pv.collect(tmp)
        finally:
            if saved is None:
                os.environ.pop('PRECEDENT_USER_CONFIG', None)
            else:
                os.environ['PRECEDENT_USER_CONFIG'] = saved
        phrases = {e[0] for e in entries}
        word_list, word_note = pv.words()
        names = {w.lower() for w, _ in word_list}

        dup = tmp / 'dup.json'
        dup.write_text(json.dumps({'words': [
            {'word': 'x', 'meaning': 'one'}, {'word': 'X', 'meaning': 'two'}]}),
            encoding='utf-8')
        try:
            ol.load(dup)
            dup_refused = False
        except SystemExit:
            dup_refused = True

        cases = [
            ('a command phrase that is a word leaves the command list',
             'Primary branch' not in phrases, f'{sorted(phrases)}'),
            ('negative control: an ordinary command in the same fixture is '
             'still listed', 'Fixture Command' in phrases, f'{sorted(phrases)}'),
            ('the word list reads from the registry, with no error note',
             'primary branch' in names and word_note is None,
             f'{sorted(names)} {word_note}'),
            ('a word listed twice is refused rather than rendered twice',
             dup_refused, ''),
        ]
        ok = all(passed for _, passed, _ in cases)
        for name, passed, detail in cases:
            if not passed:
                print(f"  vocabulary word list did NOT behave as stated: "
                      f"{name} [{detail}]")
        check(f'precedent_vocabulary prints words under Our language, not as '
              f'commands ({len(cases)} stated cases)', ok)
    finally:
        shutil.rmtree(tmp, ignore_errors=True)


def check_beta_watermark_commits_only_when_it_actually_reports_something():
    """The watermark advances -- and writes a commit -- ONLY on a run that
    tells its person about a commit that is not theirs. A run with nothing
    to tell them writes nothing at all.

    THE DEFECT, 2026-09-22. `_write_watermark` and the commit sat ABOVE the
    `if not others` return in `check()`, so the path that reports nothing
    committed exactly like the path that reports somebody else's push.
    Measured on `precedent-beta-v01` the same day: 293 of the last 300
    commits are Morgan's own, 5 a session's, 2 Alex's -- so nearly every
    watermark commit ever written recorded a notice that was never given,
    against a registry whose own `_comment` says it "gates a notification
    with nothing left to do once it has been given". 32 of them across four
    days in one container, 13 on a single day, 8 still unpushed.

    NOT COMMITTING IS NOT ENOUGH, which is why the clean-tree case matters.
    Writing the file and skipping only the commit leaves the checkout dirty,
    and `.claude/hooks/freshness-guard.sh` refuses to fast-forward a dirty
    tree (`_dirty` there, `status --porcelain --untracked-files=no`) --
    trading a diverged checkout for a stuck one.

    The last case is the correctness the volume fix must not cost: a
    watermark left behind by a quiet run still finds the commit it never
    reported, because `others` is computed over `seen..head` and a watermark
    that stayed put simply widens that window.

    KEYED BY IDENTITY since the file moved into this repository on
    2026-09-22. Two people work this branch, and one shared row would have
    each of them consuming the other's notification, so the last case here
    asserts a second identity is told about commits the first already
    swallowed.
    """
    import shutil, tempfile
    sys.path.insert(0, str(ROOT / 'tools'))
    import precedent_beta_watermark_check as pbw

    MINE = 'watermark-owner@example.com'
    THEIRS = 'someone-else@example.com'

    def git(cwd, *args, author=None):
        env = dict(os.environ)
        if author:
            env['GIT_AUTHOR_EMAIL'] = env['GIT_COMMITTER_EMAIL'] = author
            env['GIT_AUTHOR_NAME'] = env['GIT_COMMITTER_NAME'] = author.split('@')[0]
        r = subprocess.run(['git', '-C', str(cwd), *args],
                           capture_output=True, text=True, env=env)
        if r.returncode != 0:
            raise RuntimeError(f"git {' '.join(args)}: {r.stderr.strip()}")
        return r.stdout.strip()

    # Identity resolves from PRECEDENT_COMMIT_* first, which is the cheapest
    # way to give a fixture repo a person without writing an identity.json
    # into it. Saved and restored so the real container's identity is not
    # disturbed.
    saved = {k: os.environ.get(k) for k in
             ('PRECEDENT_COMMIT_EMAIL', 'PRECEDENT_COMMIT_NAME',
              'PRECEDENT_COMMIT_TIMEZONE', 'PRECEDENT_USER_CONFIG')}
    tmp = pathlib.Path(tempfile.mkdtemp(prefix='beta-watermark-'))
    try:
        branch = 'staging'
        os.environ['PRECEDENT_COMMIT_EMAIL'] = MINE
        os.environ['PRECEDENT_COMMIT_NAME'] = 'Watermark Owner'
        os.environ['PRECEDENT_COMMIT_TIMEZONE'] = 'UTC'
        os.environ.pop('PRECEDENT_USER_CONFIG', None)

        origin, _seed, land = _beta_watermark_fixture(tmp, git, branch)
        land('c0', MINE)

        work = tmp / 'work'
        git(tmp, 'clone', '-q', str(origin), str(work))
        git(work, 'config', 'user.email', 'harness@example.com')
        git(work, 'config', 'user.name', 'harness')

        def run():
            # .claude/hooks/freshness-guard.sh fast-forwards the checkout
            # before the session-start hook fires, so the real sequence
            # never reaches check() with a checkout that is behind. A
            # fixture that skips it tests _can_push's refusal instead of
            # what this check is about.
            subprocess.run(['git', '-C', str(work), 'fetch', '-q', 'origin',
                            branch], capture_output=True)
            subprocess.run(['git', '-C', str(work), 'merge', '-q', '--ff-only',
                            f'origin/{branch}'], capture_output=True)
            return pbw.check(root=work, no_fetch=False, no_push=False)

        def landed():
            # Watermark commits alone: land() puts its own commits on the
            # same branch, so a bare count moves for reasons this check is
            # not about.
            subjects = git(origin, 'log', '--format=%s', branch).splitlines()
            return sum(1 for x in subjects if 'watermark' in x)

        def rows():
            wm = pbw._watermark_path(work)
            if not wm.is_file():
                return {}
            return json.loads(wm.read_text(encoding='utf-8')).get('seen_by') or {}

        def recorded(who='Watermark Owner'):
            key = pbw._identity_key({'name': who})
            return (rows().get(key) or {}).get('sha')

        # 1. First run for this identity baselines, and that is one commit.
        status_base, _l, alert_base = run()
        after_baseline = landed()
        baselined_at = recorded()

        # 2. The branch moves, all of it authored by the declared identity.
        land('c1', MINE)
        status_quiet, lines_quiet, alert_quiet = run()
        after_quiet = landed()
        porcelain_quiet = git(work, 'status', '--porcelain')
        # Captured HERE, not in the cases list below: the alert run that
        # follows writes the file, and a late read would show its value
        # while claiming to describe the quiet run.
        recorded_after_quiet = recorded()

        # 3. Somebody else pushes. Now there is something to tell them.
        land('c2', THEIRS)
        status_alert, _la, alert_alert = run()
        after_alert = landed()
        subject_alert = git(work, 'log', '-1', '--format=%s')

        # 4. A SECOND identity gets its OWN row. It baselines rather than
        #    alerting -- a person who has never been told anything has
        #    nothing to be told about -- and the first person's row must
        #    come through it untouched.
        mine_before_other = recorded('Watermark Owner')
        os.environ['PRECEDENT_COMMIT_EMAIL'] = THEIRS
        os.environ['PRECEDENT_COMMIT_NAME'] = 'Someone Else'
        land('c3', MINE)
        status_other, _lo, alert_other = run()
        os.environ['PRECEDENT_COMMIT_EMAIL'] = MINE
        os.environ['PRECEDENT_COMMIT_NAME'] = 'Watermark Owner'

        mine_now, theirs_now = recorded(), recorded('Someone Else')
        cases = [
            ('a first run for an identity baselines and commits once',
             status_base == 'ok' and alert_base is None
             and after_baseline == 1 and baselined_at is not None,
             f'{status_base} {after_baseline} {baselined_at}'),
            ('a branch move with nothing to report writes NO commit',
             after_quiet == after_baseline, f'{after_quiet} vs {after_baseline}'),
            ('...and leaves the checkout CLEAN, so the freshness guard can '
             'still fast-forward it', porcelain_quiet == '', porcelain_quiet),
            ('...and says so, rather than reporting an outcome it did not have',
             'nothing to tell you' in ' '.join(lines_quiet), ' '.join(lines_quiet)),
            ('...and leaves the recorded watermark where it was',
             recorded_after_quiet == baselined_at,
             f'{recorded_after_quiet} vs {baselined_at}'),
            ('the quiet run reports ok with no alert',
             status_quiet == 'ok' and alert_quiet is None, f'{status_quiet}'),
            ("somebody else's push IS reported, even though the quiet run "
             'left the watermark behind',
             status_alert == 'alert' and alert_alert is not None
             and 'someone-else' in alert_alert, f'{status_alert}'),
            ('...and that is the run that writes the commit',
             after_alert == after_quiet + 1
             and subject_alert.startswith(f'Advance {branch} watermark'),
             f'{after_alert} vs {after_quiet}: {subject_alert}'),
            ('a SECOND identity baselines rather than inheriting what the '
             'first was told', status_other == 'ok' and alert_other is None
             and recorded('Someone Else') is not None, f'{status_other} {alert_other}'),
            ('no row is keyed by an email address -- the leak gate refuses '
             'one anywhere in a tracked file, and this branch is public',
             all('@' not in k for k in rows()), f'{sorted(rows())}'),
            ('...and the two rows are kept apart -- one per person, never '
             'one for the file',
             mine_now == mine_before_other and theirs_now != mine_now,
             f'{mine_now} (was {mine_before_other}) vs {theirs_now}'),
        ]
        ok = all(passed for _, passed, _ in cases)
        for name, passed, detail in cases:
            if not passed:
                print(f"  beta watermark did NOT behave as stated: {name} [{detail}]")
        check(f'the beta-branch watermark commits only on a run that '
              f'actually reports something ({len(cases)} stated cases)', ok)
    finally:
        for k, v in saved.items():
            if v is None:
                os.environ.pop(k, None)
            else:
                os.environ[k] = v
        shutil.rmtree(tmp, ignore_errors=True)


def check_beta_watermark_never_writes_into_a_busy_or_unpushable_checkout():
    """The watermark is written only into a checkout that is idle AND can
    push. Anything else and the per-container note takes it instead, with
    the alert still delivered.

    WHY THE PROBE EXISTS. Until 2026-09-22 the watermark was committed into
    a DIFFERENT repository -- the individual source -- and from a session
    rooted here that push could not land: the git proxy serves fetches of
    that clone and refuses pushes on repository scope, measured with the
    credential helper present and the token in the environment. Eight
    unpushable commits piled up there. The file has since moved into this
    repository, which removes that particular wall and not the rule: a
    checkout that is offline, behind or diverged still cannot push.

    WHY THE IDLE GUARD EXISTS, and it is the hazard the move introduced.
    The write now lands in the very checkout the session is about to work
    in. A push from a session-start hook would carry whatever else sits
    ahead of origin, and a bare commit would sweep up anything already
    staged -- a hook publishing somebody's work in progress, or authoring a
    commit they were still composing. So history is written only into a
    checkout that is demonstrably idle, and the commit names its one path
    explicitly rather than trusting the index.

    The note is written only where git can be SHOWN to ignore it: an
    untracked file in a source clone is precisely the dirt that skips that
    clone's refresh and reads as work existing nowhere else. The last case
    is the repo that ignores nothing -- no note, and a line that says the
    alert will repeat rather than pretending otherwise.
    """
    import shutil, tempfile
    sys.path.insert(0, str(ROOT / 'tools'))
    import precedent_beta_watermark_check as pbw

    MINE = 'watermark-owner@example.com'
    THEIRS = 'someone-else@example.com'

    def git(cwd, *args, author=None):
        env = dict(os.environ)
        if author:
            env['GIT_AUTHOR_EMAIL'] = env['GIT_COMMITTER_EMAIL'] = author
            env['GIT_AUTHOR_NAME'] = env['GIT_COMMITTER_NAME'] = author.split('@')[0]
        r = subprocess.run(['git', '-C', str(cwd), *args],
                           capture_output=True, text=True, env=env)
        if r.returncode != 0:
            raise RuntimeError(f"git {' '.join(args)}: {r.stderr.strip()}")
        return r.stdout.strip()

    saved = {k: os.environ.get(k) for k in
             ('PRECEDENT_COMMIT_EMAIL', 'PRECEDENT_COMMIT_NAME',
              'PRECEDENT_COMMIT_TIMEZONE', 'PRECEDENT_USER_CONFIG')}
    tmp = pathlib.Path(tempfile.mkdtemp(prefix='beta-watermark-busy-'))
    try:
        branch = 'staging'
        os.environ['PRECEDENT_COMMIT_EMAIL'] = MINE
        os.environ['PRECEDENT_COMMIT_NAME'] = 'Watermark Owner'
        os.environ['PRECEDENT_COMMIT_TIMEZONE'] = 'UTC'
        os.environ.pop('PRECEDENT_USER_CONFIG', None)

        origin, _seed, land = _beta_watermark_fixture(tmp, git, branch)
        land('c0', MINE)
        work = tmp / 'work'
        git(tmp, 'clone', '-q', str(origin), str(work))
        git(work, 'config', 'user.email', 'harness@example.com')
        git(work, 'config', 'user.name', 'harness')

        def run(root=None):
            r = root or work
            subprocess.run(['git', '-C', str(r), 'fetch', '-q', 'origin',
                            branch], capture_output=True)
            subprocess.run(['git', '-C', str(r), 'merge', '-q', '--ff-only',
                            f'origin/{branch}'], capture_output=True)
            return pbw.check(root=r, no_fetch=False, no_push=False)

        def landed():
            # Watermark commits alone; land() adds its own to the same branch.
            subjects = git(origin, 'log', '--format=%s', branch).splitlines()
            return sum(1 for x in subjects if 'watermark' in x)

        run()                                     # baseline, idle and pushable
        baseline = landed()
        note_path = pbw._local_note_path(work)

        # --- the checkout is mid-work: a commit of its own, not yet pushed
        (work / 'session-work.txt').write_text('a session in progress\n',
                                                encoding='utf-8')
        git(work, 'add', 'session-work.txt')
        git(work, 'commit', '-qm', 'the session is working')
        quiet_before = pbw._is_quiet(work, branch)

        land('c1', THEIRS)
        status1, lines1, alert1 = run()
        cases = [
            ('_is_quiet says no when the checkout is ahead of origin',
             quiet_before is False, 'said yes'),
            ('the alert is still delivered from a busy checkout',
             status1 == 'alert' and alert1 is not None, f'{status1}'),
            ("and the session's own commit was NOT pushed by the hook",
             landed() == baseline, f'{landed()} vs {baseline}'),
            ('and no watermark commit was written either',
             git(work, 'log', '-1', '--format=%s') == 'the session is working',
             git(work, 'log', '-1', '--format=%s')),
            ('the head reported is recorded per-container instead',
             note_path.is_file()
             and json.loads(note_path.read_text(encoding='utf-8')
                             )['reported_head'] == git(work, 'rev-parse',
                                                        f'origin/{branch}'),
             'no note'),
            ('the note is invisible to git, so it is not dirt in its turn',
             git(work, 'status', '--porcelain') == '',
             git(work, 'status', '--porcelain')),
            ('and the line says nothing was written to the shared watermark',
             'mid-work or cannot push' in ' '.join(lines1), ' '.join(lines1)),
        ]

        # The note is the whole point: the same alert must not repeat here.
        status2, _l2, alert2 = run()
        cases.append(('the same alert does not repeat in this container',
                      status2 == 'ok' and alert2 is None, f'{status2} {alert2}'))

        # --- a STAGED file alone is enough to refuse, with nothing ahead
        git(work, 'fetch', '-q', 'origin', branch)
        git(work, 'merge', '-q', '--no-edit', f'origin/{branch}')
        git(work, 'push', '-q', 'origin', f'HEAD:{branch}')
        baseline = landed()
        (work / 'staged.txt').write_text('half an edit\n', encoding='utf-8')
        git(work, 'add', 'staged.txt')
        cases.append(('_is_quiet says no on a staged index alone, with '
                      'nothing ahead of origin',
                      pbw._is_quiet(work, branch) is False, 'said yes'))
        git(work, 'reset', '-q')
        (work / 'staged.txt').unlink()

        # --- idle, but the remote is out of reach
        reachable = git(work, 'remote', 'get-url', 'origin')
        git(work, 'remote', 'set-url', 'origin', str(tmp / 'no-such-remote'))
        cases.append(('the probe says no when the remote cannot be reached',
                      pbw._can_push(work) is False, 'probe said yes'))
        git(work, 'remote', 'set-url', 'origin', reachable)

        # --- idle and reachable: the shared watermark IS written and pushed
        land('c2', THEIRS)
        status3, _l3, alert3 = run()
        cases += [
            ('idle and pushable, the alert fires again',
             status3 == 'alert' and alert3 is not None, f'{status3}'),
            ('and NOW the shared watermark is committed and pushed',
             landed() == baseline + 1
             and int(git(work, 'rev-list', '--count', f'origin/{branch}..HEAD')) == 0,
             f'{landed()} vs {baseline}'),
            ('and the commit carries only the watermark file, never '
             'whatever happened to be staged',
             git(work, 'show', '--name-only', '--format=', 'HEAD').split()
             == [f'tools/{pbw.WATERMARK_FILENAME}'],
             git(work, 'show', '--name-only', '--format=', 'HEAD')),
        ]

        # --- level with origin/<branch> but on ANOTHER branch: no commit
        #     there, and its head does not move (2026-09-30: a resumed
        #     session on a merged feature branch got the watermark commit)
        git(work, 'checkout', '-q', '-b', 'claude/merged-feature')
        before_feature = git(work, 'rev-parse', 'HEAD')
        baseline = landed()
        land('c-feature', THEIRS)
        status4, lines4, alert4 = run()
        cases += [
            ('_is_quiet says no on another branch level with origin',
             pbw._is_quiet(work, branch) is False, 'said yes'),
            ('the alert is still delivered from the other branch',
             status4 == 'alert' and alert4 is not None, f'{status4}'),
            ('and the other branch gets no watermark commit',
             'watermark' not in git(work, 'log', '-1', '--format=%s'),
             git(work, 'log', '-1', '--format=%s')),
            ('and its head is only where the fast-forward put it',
             git(work, 'rev-parse', 'HEAD') == git(work, 'rev-parse', f'origin/{branch}')
             and landed() == baseline,
             f'{landed()} vs {baseline}'),
        ]
        git(work, 'checkout', '-q', branch)
        git(work, 'merge', '-q', '--ff-only', f'origin/{branch}')

        # --- a push that fails leaves no commit behind
        wm = pbw._watermark_path(work)
        head_before = git(work, 'rev-parse', 'HEAD')
        wm.write_text(wm.read_text(encoding='utf-8') + ' ', encoding='utf-8')
        git(work, 'remote', 'set-url', 'origin', str(tmp / 'no-such-remote'))
        said = pbw._commit_and_push(work, wm, 'Advance watermark (harness)', False, branch)
        git(work, 'remote', 'set-url', 'origin', reachable)
        cases += [
            ('a failed push takes its commit back',
             git(work, 'rev-parse', 'HEAD') == head_before and 'taken back' in said,
             said),
            ('and leaves the checkout clean',
             git(work, 'status', '--porcelain') == '',
             git(work, 'status', '--porcelain')),
        ]

        # --- a repo that ignores nothing gets no note, and is told so
        bare_work = tmp / 'bare-work'
        git(tmp, 'clone', '-q', str(origin), str(bare_work))
        git(bare_work, 'config', 'user.email', 'harness@example.com')
        git(bare_work, 'config', 'user.name', 'harness')
        (bare_work / '.gitignore').unlink()
        # Committing the removal also puts it ahead of origin, so it takes
        # the note path. Its remote stays REACHABLE on purpose: break that
        # and check() returns 'unknown' at the fetch and never reaches the
        # note this case is about.
        git(bare_work, 'commit', '-qam', 'drop the ignore file')
        land('c3', THEIRS)
        _s4, lines4, _a4 = run(root=bare_work)
        cases += [
            ('a repo that does not ignore the note gets none written',
             not (bare_work / '.precedent' / pbw.LOCAL_NOTE_FILENAME).exists(),
             'a note was written where git would see it'),
            ('...and the line says the alert will repeat, rather than '
             'implying it has been handled',
             'repeats next session' in ' '.join(lines4), ' '.join(lines4)),
        ]

        ok = all(passed for _, passed, _ in cases)
        for name, passed, detail in cases:
            if not passed:
                print(f"  beta watermark placement did NOT behave as stated: "
                      f"{name} [{detail}]")
        check(f'the beta-branch watermark never writes into a busy or '
              f'unpushable checkout ({len(cases)} stated cases)', ok)
    finally:
        for k, v in saved.items():
            if v is None:
                os.environ.pop(k, None)
            else:
                os.environ[k] = v
        shutil.rmtree(tmp, ignore_errors=True)


def check_gate_drops_a_practice_another_source_replaced():
    """precedent_gate.py seeds its list from this repo's own practices/, then
    lays resolution over it. A universal practice that an individual set
    replaces through `overrides:` is still a file here, and resolution no
    longer carries it, so it was listed as "level unknown -- this source did
    not resolve" on every reply gate, beside the rule that replaced it
    (2026-09-30). Planted: a universal catalogue with one reply-gate
    practice, and an individual set whose practice overrides it.
    Discriminating cases: the replacing practice is listed at its level; the
    replaced one is not listed at all; and with no override, the universal
    one is listed as before (the control)."""
    import shutil, subprocess, tempfile
    tmp = pathlib.Path(tempfile.mkdtemp(prefix='gate-override-'))
    cases = []
    try:
        repo, ind = tmp / 'repo', tmp / 'mine'
        shutil.copytree(ROOT / 'tools', repo / 'tools',
                        ignore=shutil.ignore_patterns('__pycache__'))
        (repo / 'practices').mkdir()
        (ind / 'practices').mkdir(parents=True)
        base = (ROOT / 'practices' / 'session-title-names-the-difference.md'
                ).read_text(encoding='utf-8')
        (repo / 'practices' / 'fixture-replaced.md').write_text(
            base.replace('slug:        session-title-names-the-difference',
                         'slug:        fixture-replaced'), encoding='utf-8')
        mine = (base.replace('slug:        session-title-names-the-difference',
                             'slug:        fixture-replacing'))
        (ind / 'practices' / 'fixture-replacing.md').write_text(
            mine, encoding='utf-8')
        (repo / 'precedent.json').write_text(json.dumps({'sources': [
            {'level': 'universal', 'name': 'precedent', 'path': '.'}]}),
            encoding='utf-8')
        cfg = tmp / 'config.json'
        cfg.write_text(json.dumps({'format_version': 1, 'individual': {
            'name': 'fixture-mine', 'path': str(ind)}}), encoding='utf-8')

        def gate():
            r = subprocess.run(
                [sys.executable, str(repo / 'tools' / 'precedent_gate.py'),
                 'reply'], capture_output=True, text=True, cwd=str(repo),
                env={**os.environ, 'PRECEDENT_USER_CONFIG': str(cfg),
                     'HOME': str(tmp)})
            return r.stdout + r.stderr

        out = gate()
        cases.append(('with no override, both are listed (the control)',
                      '### fixture-replaced (' in out and
                      '### fixture-replacing (individual/fixture-mine)' in out,
                      out[-400:]))
        (ind / 'practices' / 'fixture-replacing.md').write_text(
            mine.replace('overrides:   null', 'overrides:   fixture-replaced'),
            encoding='utf-8')
        out = gate()
        cases.append(('the replacing practice is listed at its own level',
                      '### fixture-replacing (individual/fixture-mine)' in out,
                      out[-400:]))
        cases.append(('THE CASE THIS EXISTS FOR: the replaced practice is not '
                      'listed, and nothing claims a source did not resolve',
                      '### fixture-replaced' not in out and
                      'did not resolve' not in out, out[-400:]))
    finally:
        shutil.rmtree(tmp, ignore_errors=True)
    bad = [(c[0], c[2]) for c in cases if not c[1]]
    check(f'the gate drops a practice another source replaced '
          f'({len(cases)} stated cases)',
          not bad, '; '.join(f"{n} -- {d[:300]}" for n, d in bad))


def check_container_check_lists_commands_still_running():
    """tools/precedent_container_safe.py lists every shell the session's
    agent started that is still running (2026-09-28: two wait loops ran five
    hours after their script finished, because `pgrep -f` matched the
    loop's own command line, while this tool called the container clean).
    Planted process tables, no real processes. Discriminating cases: the
    check's own ancestor shell, the agent's non-shell children and another
    person's terminal are never listed; with no agent above it, nothing is
    listed rather than guessed."""
    sys.path.insert(0, str(ROOT / 'tools'))
    import precedent_container_safe as pcs
    WRAP = ("/bin/bash -c source /root/.claude/shell-snapshots/s.sh && eval "
            "'until ! pgrep -f scratchpad/x/runcases.py >/dev/null; do sleep 5; "
            "done' < /dev/null && pwd -P")
    rows = [
        (1, 0, '06:00:00', '/sbin/init'),
        (100, 1, '06:00:00', '/opt/claude-code/bin/claude --output-format=stream-json'),
        (200, 100, '05:12:32', WRAP),
        (201, 200, '00:00:03', 'sleep 5'),
        (300, 100, '00:00:01', '/bin/bash -c python3 tools/precedent_container_safe.py'),
        (301, 300, '00:00:01', 'python3 tools/precedent_container_safe.py'),
        (400, 100, '06:00:00', 'node /opt/mcp/server.js'),
        (500, 1, '03:00:00', '-zsh'),
    ]
    cases = []
    got = pcs.still_running(rows, me=301)
    cases.append(('THE CASE THIS EXISTS FOR: the stray wait loop is listed, '
                  'with what it runs', [r['pid'] for r in got] == [200]
                  and 'pgrep -f scratchpad/x/runcases.py' in got[0]['command']
                  and got[0]['elapsed'] == '05:12:32', repr(got)))
    cases.append(('the shell running the check itself is never listed',
                  all(r['pid'] != 300 for r in got), repr(got)))
    cases.append(("the agent's own non-shell children and another terminal "
                  'are never listed', all(r['pid'] not in (400, 500) for r in got),
                  repr(got)))
    # A hook the harness fired for the same event is the agent's child too,
    # and is not the session's work (2026-09-30: freshness-guard.sh beside
    # the reply gate forbade the archive line). A real background command,
    # and a hook script the session itself ran in its own tool shell, still
    # are.
    hooks = rows + [
        (600, 100, '00:00:02', '/bin/sh -c $CLAUDE_PROJECT_DIR/.claude/hooks/'
                               'freshness-guard.sh user-prompt staging'),
        (601, 100, '00:00:01', '/bin/bash -c cd "${GEMINI_PROJECT_DIR:-.}" && '
                               'bash .claude/hooks/stop-git-check.sh'),
        (602, 100, '00:10:00', "/bin/bash -c source /root/.claude/shell-snapshots/"
                               "s.sh && eval 'sleep 600' < /dev/null && pwd -P"),
        (603, 100, '00:05:00', "/bin/bash -c source /root/.claude/shell-snapshots/"
                               "s.sh && eval 'bash .claude/hooks/push-check-gate.sh "
                               "&' < /dev/null && pwd -P"),
    ]
    got_h = [r['pid'] for r in pcs.still_running(hooks, me=301)]
    cases.append(('a hook fired beside the check, in any adapter\'s form, is '
                  'not listed', not {600, 601} & set(got_h), repr(got_h)))
    cases.append(('...while a real `sleep 600`, and a hook script the session '
                  'ran itself, still are', {200, 602, 603} <= set(got_h),
                  repr(got_h)))
    human = [(1, 0, '1:00', '/sbin/init'), (10, 1, '1:00', 'tmux'),
             (11, 10, '1:00', '-zsh'), (12, 11, '0:01', 'python3 x.py'),
             (13, 10, '1:00', '-zsh')]
    cases.append(("run from a person's own terminal, with no agent above it, "
                  'nothing is listed', pcs.still_running(human, me=12) == [],
                  repr(pcs.still_running(human, me=12))))
    bad = [(c[0], c[2]) for c in cases if not c[1]]
    check(f'the container check lists commands still running '
          f'({len(cases)} stated cases)',
          not bad, '; '.join(f"{n} -- {d[:300]}" for n, d in bad))


def check_archive_line_is_refused_when_the_container_holds_only_copy_work():
    """`require_container_safe_if_says` refuses a reply that tells the person
    they can archive while this container holds work that exists nowhere else.

    The incident (2026-09-22): a very deep check pushed its own eight commits,
    verified them on origin, and closed with the archive line. Six commits sat
    unpushed in ~/precedent-individual in the same container -- which archiving
    releases -- in a clone the session had never been working in. Morgan:
    *"if changes are done locally but not pushed to main or
    precedent-beta-v01 then never never recommend 'You can archive this
    session' (unless the work is intended to be lost!)"*.
    (practice: cite-the-incident)

    Two halves, both planted. The SCANNER is run against a container this test
    builds -- a repo with an untracked file, a repo whose commits are all on a
    remote -- so its verdict is not a reading of whatever the real disk happens
    to hold. The WIRING is run against a stub scanner placed beside a copy of
    precedent_reply_check.py, which is the only way to assert "a failing scan
    refuses the turn" and "a passing scan does not" without a real container in
    each state. The no-scanner case is planted too: an engine vendored before
    the scanner existed must block nothing.

    practice: control-asserts-which-failure -- every positive here has the
    negative that proves it is the scan doing the work.
    """
    import tempfile
    tmp = pathlib.Path(tempfile.mkdtemp(prefix='precedent-container-'))
    cases = []
    scanner = ROOT / 'tools' / 'precedent_container_safe.py'

    def git(repo, *args):
        return subprocess.run(['git', *args], cwd=str(repo),
                              capture_output=True, text=True)

    try:
        # --- half one: the scanner, against a planted container ------------
        dirty = tmp / 'dirty'
        dirty.mkdir()
        git(dirty, 'init', '-q', '-b', 'main')
        (dirty / 'keep.txt').write_text('work that is only here\n', encoding='utf-8')
        r = subprocess.run([sys.executable, str(scanner), '--only', str(dirty)],
                           capture_output=True, text=True)
        cases.append(('an untracked file in a checkout makes the container '
                      'unsafe, and the report names the checkout',
                      r.returncode == 1 and 'keep.txt' in r.stdout
                      and str(dirty) in r.stdout,
                      f'exit {r.returncode}: {r.stdout[:200]}'))

        # Committed but on no remote -- the case the 09-22 incident actually
        # was, and the one a `git status` in the right directory still misses.
        git(dirty, 'add', 'keep.txt')
        git(dirty, 'config', 'user.email', 'harness@example.com')
        git(dirty, 'config', 'user.name', 'Harness')
        git(dirty, 'commit', '-qm', 'planted')
        r2 = subprocess.run([sys.executable, str(scanner), '--only', str(dirty)],
                            capture_output=True, text=True)
        cases.append(('committing it is not enough -- a commit no remote can '
                      'reach still fails',
                      r2.returncode == 1 and 'commit(s) on no remote' in r2.stdout,
                      f'exit {r2.returncode}: {r2.stdout[:200]}'))

        # …and pushing it IS. The negative control that proves the check is
        # about reachability from a remote and not about the file existing.
        bare = tmp / 'origin.git'
        subprocess.run(['git', 'init', '-q', '--bare', str(bare)],
                       capture_output=True, text=True)
        git(dirty, 'remote', 'add', 'origin', str(bare))
        git(dirty, 'push', '-q', 'origin', 'main')
        r3 = subprocess.run([sys.executable, str(scanner), '--only', str(dirty)],
                            capture_output=True, text=True)
        cases.append(('negative control: once it is pushed, the same checkout '
                      'is safe',
                      r3.returncode == 0 and 'container safe' in r3.stdout,
                      f'exit {r3.returncode}: {r3.stdout[:200]}'))

        # --- half two: the wiring, against a stub scanner -------------------
        def engine(stub_rc):
            """A whole tools/ dir with the scanner swapped for a stub of a
            known exit code, or removed entirely when stub_rc is None.

            THE WHOLE DIRECTORY, not just precedent_reply_check.py. Copying
            that one file leaves it without precedent_resolve.py beside it,
            so it resolves NO sources, reads NO reply_check.json and exits 0
            on every input -- which every negative control here is also
            expecting. Three of the four wiring cases passed on that, and
            the positive one failed, which is how the whole check was found
            to have never run at all (2026-09-22).
            """
            d = tmp / f'engine{stub_rc}'
            shutil.copytree(ROOT / 'tools', d / 'tools')
            planted = d / 'tools' / 'precedent_container_safe.py'
            if stub_rc is None:
                planted.unlink(missing_ok=True)
            else:
                planted.write_text(
                    'import sys\n'
                    'print("PLANTED: ~/somewhere holds 6 commit(s) on no remote")\n'
                    f'sys.exit({stub_rc})\n', encoding='utf-8')
            return d / 'tools' / 'precedent_reply_check.py'

        fx = tmp / 'repo'
        (fx / 'practices').mkdir(parents=True)
        (fx / 'precedent.json').write_text(json.dumps({'sources': [
            {'level': 'universal', 'name': 'precedent', 'path': '.'}]}),
            encoding='utf-8')
        (fx / 'practices' / 'fixture-container.md').write_text(
            '---\n'
            'slug:        fixture-container\n'
            'title:       A fixture practice wired to the reply gate\n'
            'tier:        on-demand\n'
            'severity:    default\n'
            'applies_to:  []\n'
            'occasion:    "a fixture needs one practice on the reply gate"\n'
            'gates:       ["reply"]\n'
            'index_clause: "a fixture rule"\n'
            'checked_by:  null\n'
            'status:      active\n'
            'in_force_at: null\n'
            'supersedes:  []\n'
            'overrides:   null\n'
            'added:       null\n'
            'approved_by: null\n'
            '---\n\n## Rule\nA fixture rule, present so the reply gate has '
            'something registered to it.\n', encoding='utf-8')
        (fx / 'reply_check.json').write_text(json.dumps([{
            'practice': 'fixture-container',
            'require_container_safe_if_says': ['You can archive this session'],
        }]), encoding='utf-8')

        says = tmp / 'says.md'
        says.write_text('## The Boildown\n\nAll done.\n\n'
                        'You can archive this session.\n', encoding='utf-8')
        holds = tmp / 'holds.md'
        holds.write_text("## The Boildown\n\nPush it first.\n\n"
                         "Don't archive this session.\n", encoding='utf-8')

        def replycheck(engine_path, reply):
            return subprocess.run(
                [sys.executable, str(engine_path), '--repo', str(fx),
                 '--text', str(reply)],
                capture_output=True, text=True, cwd=str(tmp),
                env={**os.environ,
                     'PRECEDENT_USER_CONFIG': str(tmp / 'no-such-config.json')})

        unsafe_engine = engine(1)
        r4 = replycheck(unsafe_engine, says)
        cases.append(('the archive line is REFUSED when the scan fails, and '
                      'the refusal carries the scan\'s own report',
                      r4.returncode == 2 and 'PLANTED:' in r4.stderr,
                      f'exit {r4.returncode}: {r4.stderr[:250]}'))

        r5 = replycheck(unsafe_engine, holds)
        cases.append(('negative control: the same unsafe container does not '
                      'refuse a reply that says the OTHER line',
                      r5.returncode == 0, f'exit {r5.returncode}: {r5.stderr[:160]}'))

        safe_engine = engine(0)
        r6 = replycheck(safe_engine, says)
        cases.append(('negative control: a clean scan lets the archive line '
                      'through',
                      r6.returncode == 0, f'exit {r6.returncode}: {r6.stderr[:160]}'))

        r7 = replycheck(engine(None), says)
        cases.append(('an engine with no scanner beside it blocks NOTHING -- '
                      'an old vendor is not a broken reply',
                      r7.returncode == 0, f'exit {r7.returncode}: {r7.stderr[:160]}'))

        # The pre-reply print must carry the VERDICT, not just the rule:
        # a refusal the session was never warned about costs the reply twice.
        #
        # RUN AGAINST THE STUBBED ENGINES, not ROOT's. This called
        # ROOT/tools/precedent_gate.py, whose _container_report() scans the
        # REAL disk -- and the gate is deliberately silent when that scan
        # comes back clean, which its own comment says is the ordinary case.
        # So the assertion below held only while the machine running the
        # suite happened to be carrying unpushed work, and went red the
        # moment a session pushed its own. Found 2026-09-22 by a suite that
        # passed twice and then failed on the same commit, with the push in
        # between; measured both ways before this was rewritten. A check
        # that reads live disk state is not asserting the code's contract,
        # it is reporting the weather (practice: checks-plant-their-state,
        # whose Story is this incident and whose Install explains why it
        # carries no check of its own).
        def gate(engine_path):
            return subprocess.run(
                [sys.executable, str(engine_path.parent / 'precedent_gate.py'),
                 '--repo', str(fx), 'reply'],
                capture_output=True, text=True, cwd=str(tmp),
                env={**os.environ,
                     'PRECEDENT_USER_CONFIG': str(tmp / 'no-such-config.json')})

        r8 = gate(unsafe_engine)
        cases.append(('the reply gate names this requirement before the '
                      'reply, when the container is the unsafe one',
                      'You can archive this session' in r8.stdout,
                      r8.stdout[-250:]))

        r9 = gate(safe_engine)
        cases.append(('negative control: the gate is SILENT on a clean '
                      'container -- naming a requirement already met is the '
                      'noise its own comment declines to print',
                      'You can archive this session' not in r9.stdout,
                      r9.stdout[-250:]))
    finally:
        shutil.rmtree(tmp, ignore_errors=True)

    bad_cases = [(n, d) for n, ok, d in cases if not ok]
    return (not bad_cases, f'{len(cases)} stated cases',
            '; '.join(f'{n}: {d}' for n, d in bad_cases))


def check_compaction_offer_fires_on_context_growth():
    """The size-aware half of the reply check: a long session is REFUSED a
    reply that never says whether this is a cheap point to compact.

    The incident is practices/session-spend-follows-the-task.md's own Story.
    The rule was registered on the reply gate on 2026-09-13 and still did not
    fire once in the eleven hours after -- because the reply gate PRINTS, and
    printing happens after the reply it was meant to shape. Morgan, 2026-09-14:
    *"you never once recommended I compact a session - despite our updated
    rules."*

    Every case below owns its own transcript (practice: fixture-owns-its-state)
    -- a real session's JSONL would make the assertions depend on how long this
    container had been running.
    """
    import tempfile
    tmp = pathlib.Path(tempfile.mkdtemp(prefix='precedent-compact-'))
    cases = []
    try:
        fx = tmp / 'repo'
        (fx / 'practices').mkdir(parents=True)
        (fx / 'precedent.json').write_text(json.dumps({'sources': [
            {'level': 'universal', 'name': 'precedent', 'path': '.'}]}), encoding='utf-8')
        (fx / 'reply_check.json').write_text(json.dumps([{
            'practice': 'fixture-compaction',
            'require_one_of': ['This is a cheap point to compact',
                               'Not a cheap point to compact'],
            'require_when_context_grew_tokens': 100000,
        }]), encoding='utf-8')

        def transcript(name, turns):
            """turns: [(context_tokens, reply_text), ...], oldest first."""
            path = tmp / name
            lines = []
            for ctx, text in turns:
                lines.append(json.dumps({
                    'type': 'assistant',
                    'message': {
                        'usage': {'input_tokens': 2,
                                  'cache_creation_input_tokens': 0,
                                  'cache_read_input_tokens': max(ctx - 2, 0)},
                        'content': [{'type': 'text', 'text': text}],
                    }}))
            path.write_text('\n'.join(lines) + '\n', encoding='utf-8')
            return path

        def run(path):
            return subprocess.run(
                [sys.executable, str(ROOT / 'tools' / 'precedent_reply_check.py'),
                 '--repo', str(fx)],
                input=json.dumps({'transcript_path': str(path)}),
                capture_output=True, text=True, cwd=str(tmp),
                env={**os.environ,
                     'PRECEDENT_USER_CONFIG': str(tmp / 'no-such-config.json')})

        # A short session says nothing about compacting and is left alone.
        # This is the case that keeps the rule from becoming a nag: most
        # sessions never reach the threshold and must never see this message.
        short = run(transcript('short.jsonl', [
            (96000, 'Opening.'), (120000, 'Done. Nothing about compacting here.')]))
        cases.append(('a session that has grown less than the declared amount '
                      'is NOT blocked', short.returncode == 0, short.stderr[:200]))

        # The same reply, on a session that has grown past it.
        grown = run(transcript('grown.jsonl', [
            (96000, 'Opening.'), (150000, 'Middle.'),
            (205000, 'Done. Nothing about compacting here.')]))
        cases.append(('a session that HAS grown past it is blocked',
                      grown.returncode == 2, f'exit {grown.returncode}'))
        # control-asserts-which-failure: the exit code alone would pass even if
        # the block came from some other requirement entirely.
        cases.append(('...and the message names the sentence that is missing',
                      'cheap point to compact' in grown.stderr, grown.stderr[:200]))
        cases.append(('...and says how big the conversation actually is, since '
                      'the person is deciding against a number they cannot see',
                      '109,000' in grown.stderr or '≈109' in grown.stderr,
                      grown.stderr[:300]))

        # Both answers satisfy it. The honest negative matters as much as the
        # offer: mid-investigation the rule's own answer is to keep working,
        # and a check that accepted only the offer would push a session into
        # making one it does not mean.
        for phrase in ('This is a cheap point to compact if you want to.',
                       'Not a cheap point to compact -- we are mid-investigation.'):
            r = run(transcript('ok.jsonl', [
                (96000, 'Opening.'), (205000, f'Done. {phrase}')]))
            cases.append((f'a reply saying "{phrase[:28]}..." is not blocked',
                          r.returncode == 0, r.stderr[:200]))

        # Having said it once, the session is not asked again until the
        # conversation has grown another full increment.
        again = run(transcript('again.jsonl', [
            (96000, 'Opening.'),
            (205000, 'This is a cheap point to compact if you want to.'),
            (250000, 'More work. Nothing about compacting here.')]))
        cases.append(('after the offer is made, it is not demanded again until '
                      'the conversation has grown another increment',
                      again.returncode == 0, again.stderr[:200]))
        overdue = run(transcript('overdue.jsonl', [
            (96000, 'Opening.'),
            (205000, 'This is a cheap point to compact if you want to.'),
            (320000, 'Much more work. Nothing about compacting here.')]))
        cases.append(('...and IS demanded once it has',
                      overdue.returncode == 2, f'exit {overdue.returncode}'))

        # THE COMPACTION ITSELF. After one, the context drops and the
        # historical maximum does not, so a check reading the high-water mark
        # goes on demanding the offer from the one session that owes nothing.
        # The first draft of this did exactly that.
        # The offer is deliberately ABSENT before the compaction here: with one
        # present, both the buggy and the fixed reading come out silent, and
        # the case discriminates nothing.
        compacted = run(transcript('compacted.jsonl', [
            (96000, 'Opening.'),
            (240000, 'A long stretch of work, no offer made.'),
            (40000, 'Fresh after the compaction. Nothing about compacting here.')]))
        cases.append(('a session that has just been COMPACTED is not asked '
                      'again -- the check reads the latest context, not the '
                      'high-water mark', compacted.returncode == 0,
                      compacted.stderr[:200]))

        # A size condition nobody can evaluate must not block a reply.
        missing = run(tmp / 'no-such-transcript.jsonl')
        cases.append(('an unreadable transcript blocks nothing',
                      missing.returncode == 0, missing.stderr[:200]))
    finally:
        shutil.rmtree(tmp, ignore_errors=True)

    bad_cases = [(c[0], c[2] if len(c) > 2 else '') for c in cases if not c[1]]
    check(f'the compaction offer is demanded once a session has grown, and only '
          f'then ({len(cases)} stated cases)',
          not bad_cases,
          '; '.join(f"{n}{' (' + d + ')' if d else ''}" for n, d in bad_cases))


def check_compaction_offer_owed_printed_at_turn_start():
    """The turn-start reply gate says whether the compact offer is owed.

    2026-09-28: the Boildown's compact offer is advisory, and the stop hook
    drops an unmet advisory requirement without a word, while the turn-start
    print told sessions to leave the line out until the stop hook asked. A
    session ran from about 80,000 tokens to about 783,000 without one compact
    line. Morgan: "you have not told me ever to compact this session." The
    gate now reads the transcript reply-gate.sh passes it and prints the
    answer. Each case owns its transcript (practice: fixture-owns-its-state).
    """
    import tempfile
    tmp = pathlib.Path(tempfile.mkdtemp(prefix='precedent-compact-owed-'))
    cases = []
    try:
        fx = tmp / 'repo'
        (fx / 'practices').mkdir(parents=True)
        (fx / 'precedent.json').write_text(json.dumps({'sources': [
            {'level': 'universal', 'name': 'precedent', 'path': '.'}]}), encoding='utf-8')
        (fx / 'reply_check.json').write_text(json.dumps([{
            'practice': 'fixture-compaction',
            'require_one_of': ['Now is a good time to compact the session'],
            'require_when_context_grew_tokens': 100000,
            'advisory': True,
        }]), encoding='utf-8')
        subprocess.run(['git', 'init', '-q', str(fx)], capture_output=True)

        def transcript(name, turns):
            path = tmp / name
            path.write_text(''.join(json.dumps({
                'type': 'assistant',
                'message': {'usage': {'input_tokens': 2,
                                      'cache_creation_input_tokens': 0,
                                      'cache_read_input_tokens': max(c - 2, 0)},
                            'content': [{'type': 'text', 'text': t}]}}) + '\n'
                for c, t in turns), encoding='utf-8')
            return path

        def run(path):
            # Through the hook itself, so the payload-to-env hand-off is what
            # is tested, not only the gate's reading of the variable.
            hook = ROOT / 'templates' / 'harness' / 'claude-code' / 'hooks' / 'reply-gate.sh'
            (fx / 'tools').mkdir(exist_ok=True)
            for f in ROOT.joinpath('tools').glob('*.py'):
                dst = fx / 'tools' / f.name
                if not dst.exists():
                    dst.symlink_to(f)
            payload = json.dumps({'transcript_path': str(path)}) if path else ''
            return subprocess.run(
                ['bash', str(hook)], input=payload, capture_output=True,
                text=True, cwd=str(fx),
                env={**os.environ, 'CLAUDE_PROJECT_DIR': str(fx),
                     'PRECEDENT_USER_CONFIG': str(tmp / 'no-such-config.json')})

        owed = run(transcript('owed.jsonl', [
            (96000, 'Opening.'), (150000, 'Middle.'), (205000, 'Done.')]))
        cases.append(('a grown session is told the offer is OWED, with the '
                      'sentence to say', 'OWED IN THIS REPLY' in owed.stdout
                      and 'Now is a good time to compact the session' in owed.stdout,
                      owed.stdout[-400:]))
        short = run(transcript('short.jsonl', [(96000, 'Opening.'), (120000, 'Done.')]))
        cases.append(('a short session hears nothing about compacting',
                      'good time to compact' not in short.stdout, short.stdout[-400:]))
        said = run(transcript('said.jsonl', [
            (96000, 'Opening.'),
            (205000, 'Now is a good time to compact the session.'),
            (250000, 'More.')]))
        cases.append(('once said, it is not owed again until another increment',
                      'good time to compact' not in said.stdout, said.stdout[-400:]))
        blind = run(None)
        cases.append(('no transcript: it says it could not tell, and never '
                      'defers to the stop hook', 'could not be worked out'
                      in blind.stdout and 'stop hook is the thing'
                      not in blind.stdout, blind.stdout[-400:]))
        cases.append(('the hook exits 0 every time -- a non-zero '
                      'UserPromptSubmit exit eats the message',
                      all(r.returncode == 0 for r in (owed, short, said, blind)),
                      ''))
    finally:
        shutil.rmtree(tmp, ignore_errors=True)
    bad = [(n, d) for n, ok, d in cases if not ok]
    check(f'the turn-start gate says when the compact offer is owed '
          f'({len(cases)} stated cases)', not bad,
          '; '.join(f'{n} ({d})' for n, d in bad))


def check_killed_promote_releases_its_lock():
    """A Promote killed by SIGTERM still releases its lock.

    2026-09-28: a Promote run under a 590-second command limit was killed
    mid-check, and its claim on precedent-promote-lock sat on origin for the
    full stale window, so the same session's retry did nothing. try/finally
    never runs on SIGTERM unless something turns the signal into an
    exception. The fixture stubs everything around the lock: the step, the
    claim, and a run that blocks, so the only thing under test is whether
    the release still happens when the process is killed.
    """
    import tempfile
    tmp = pathlib.Path(tempfile.mkdtemp(prefix='precedent-lock-kill-'))
    cases = []
    try:
        marker = tmp / 'released'
        started = tmp / 'started'
        script = tmp / 'run.py'
        script.write_text(f"""
import sys, time, pathlib
sys.path.insert(0, {str(ROOT / 'tools')!r})
import precedent_branches as pb
pb.promotion_step = lambda root, to, work: (pb.STAGING, 'fixture')
pb.staging_branch = lambda root: pb.STAGING
pb.repo_has_tiers = lambda root: True
pb._drifted_from_above = lambda root: []
pb._lock_claim = lambda root, say: ('held', 'fixture-commit')
pb._lock_release = lambda root, held, say: pathlib.Path({str(marker)!r}).write_text(held)
def _run(root, say):
    pathlib.Path({str(started)!r}).write_text('1')
    time.sleep(60)
    return 0
pb._promote_unlocked = _run
sys.exit(pb.promote('.', say=lambda *a: None))
""", encoding='utf-8')
        for sig_name in ('SIGTERM', 'SIGHUP'):
            import signal as _signal
            for f in (marker, started):
                f.unlink(missing_ok=True)
            proc = subprocess.Popen([sys.executable, str(script)], cwd=str(tmp))
            deadline = time.time() + 20
            while not started.exists() and time.time() < deadline:
                time.sleep(0.05)
            proc.send_signal(getattr(_signal, sig_name))
            try:
                proc.wait(timeout=20)
            except subprocess.TimeoutExpired:
                proc.kill()
            cases.append((f'a Promote killed by {sig_name} mid-run releases '
                          f'the lock it holds',
                          marker.exists() and marker.read_text() == 'fixture-commit',
                          f'exit {proc.returncode}, released={marker.exists()}'))
            cases.append((f'...and exits non-zero, so nothing reads the kill '
                          f'as a finished Promote ({sig_name})',
                          proc.returncode not in (0, None), f'exit {proc.returncode}'))
    finally:
        shutil.rmtree(tmp, ignore_errors=True)
    bad = [(n, d) for n, ok, d in cases if not ok]
    check(f'a killed Promote releases its lock ({len(cases)} stated cases)',
          not bad, '; '.join(f'{n} ({d})' for n, d in bad))


def check_promote_names_a_binary_conflict():
    """A Promote whose merge conflicts on a binary file stops and names it.

    2026-10-05: a Debut in a repository that keeps Word files conflicted on
    one, and _generator_of read the file's index stage as UTF-8 text to look
    for a `generated_by:` header. A .docx is binary, so the Promote died
    with a UnicodeDecodeError traceback instead of saying which file
    conflicted. A binary file carries no header, so it counts as
    hand-written: the merge stops and the file is named.
    """
    import tempfile
    tmp = pathlib.Path(tempfile.mkdtemp(prefix='precedent-binary-conflict-'))
    cases = []
    try:
        r = tmp / 'r'
        r.mkdir()
        def git(*a):
            return subprocess.run(['git', '-C', str(r), *a], capture_output=True)
        git('init', '-q')
        git('config', 'user.email', 'fixture@example.com')
        git('config', 'user.name', 'fixture')
        doc = r / 'out.docx'
        doc.write_bytes(b'PK\x03\x04\x85\x00base')
        git('add', '.')
        git('commit', '-qm', 'base')
        git('checkout', '-qb', 'other')
        doc.write_bytes(b'PK\x03\x04\x85\x00theirs')
        git('commit', '-qam', 'theirs')
        git('checkout', '-q', '-')
        doc.write_bytes(b'PK\x03\x04\x85\x00ours')
        git('commit', '-qam', 'ours')
        merged = git('merge', '-q', 'other')
        cases.append(('the fixture merge really conflicts on the binary file',
                      merged.returncode != 0
                      and b'out.docx' in git('diff', '--name-only',
                                             '--diff-filter=U').stdout,
                      merged.stdout.decode(errors='replace')[-300:]))
        script = tmp / 'run.py'
        script.write_text(f"""
import sys
sys.path.insert(0, {str(ROOT / 'tools')!r})
import precedent_branches as pb
print(repr(pb._resolve_by_regenerating({str(r)!r}, say=lambda *a: None)))
""", encoding='utf-8')
        out = subprocess.run([sys.executable, str(script)], capture_output=True,
                             text=True)
        cases.append(('resolving it does not crash', out.returncode == 0
                      and 'Traceback' not in out.stderr, out.stderr[-500:]))
        cases.append(("...and reports the binary file as the hand-written "
                      "conflict that stops the merge",
                      out.stdout.strip() == "(False, ['out.docx'])",
                      out.stdout.strip()[-300:]))
    finally:
        shutil.rmtree(tmp, ignore_errors=True)
    bad = [(n, d) for n, ok, d in cases if not ok]
    check(f'a Promote names a binary merge conflict ({len(cases)} stated cases)',
          not bad, '; '.join(f'{n} ({d})' for n, d in bad))

def check_produce_sees_main_changes_staging_carries():
    """A red main whose tip changes nothing staging lacks does not hold Produce.

    2026-10-05: main's GitHub test went red on a Produce's own merge commit
    because its jobs never got a runner. main_test_holds_produce asked
    whether staging descends from main's tip, said "Debut first", and the
    Debut had nothing to take down -- a merge commit changes no file -- so
    the session went round in a circle. The hold now also lifts when
    staging already carries every change main's tip brings (and its tree
    passed the full local check). The control keeps the hold for a main
    tip that changes a file staging lacks.
    """
    import tempfile
    tmp = pathlib.Path(tempfile.mkdtemp(prefix='precedent-produce-carried-'))
    cases = []
    try:
        origin, r = tmp / 'origin.git', tmp / 'r'
        def git(*a, cwd=None):
            return subprocess.run(['git', *a], cwd=str(cwd or r),
                                  capture_output=True, text=True)
        git('init', '-q', '--bare', str(origin), cwd=tmp)
        git('clone', '-q', str(origin), str(r), cwd=tmp)
        git('config', 'user.email', 'fixture@example.com')
        git('config', 'user.name', 'fixture')
        (r / 'a.txt').write_text('one\n')
        git('add', '.')
        git('commit', '-qm', 'base')
        git('branch', '-M', 'main')
        git('checkout', '-qb', 'staging')
        (r / 'a.txt').write_text('two\n')
        git('commit', '-qam', 'work on staging')
        git('checkout', '-q', 'main')
        git('merge', '-q', '--no-ff', '-m', 'Merge pull request: Produce', 'staging')
        git('push', '-q', 'origin', 'main', 'staging')
        script = tmp / 'run.py'
        script.write_text(f"""
import sys
sys.path.insert(0, {str(ROOT / 'tools')!r})
import precedent_branches as pb
pb._gets_github_test = lambda root, b: True
pb.github_tests = lambda root, sha: ['deep-check.yml']
pb.github_test_state = lambda root, sha, tests, gh=None: ('failed', 'fixture')
pb.staging_branch = lambda root: 'staging'
pb._receipt = lambda root, sha: True
print(repr(pb.main_test_holds_produce({str(r)!r}, say=lambda *a: None)))
""", encoding='utf-8')
        def run():
            out = subprocess.run([sys.executable, str(script)], capture_output=True,
                                 text=True)
            return out.stdout.strip(), out.stderr[-400:]
        got, err = run()
        cases.append(("a main tip that is a no-change merge of staging does not "
                      "hold Produce", got == 'None', got or err))
        (r / 'b.txt').write_text('a change only main has\n')
        git('add', '.')
        git('commit', '-qm', 'direct push to main')
        git('push', '-q', 'origin', 'main')
        got, err = run()
        cases.append(("...and a main tip with a file change staging lacks still "
                      "holds it, naming Debut", 'Debut first' in got, got or err))
    finally:
        shutil.rmtree(tmp, ignore_errors=True)
    bad = [(n, d) for n, ok, d in cases if not ok]
    check(f'Produce sees main changes staging already carries ({len(cases)} '
          f'stated cases)', not bad, '; '.join(f'{n} ({d})' for n, d in bad))

def check_trivial_checkin_exempts_the_boildown_gate():
    """practices/the-boildown.md names one fixed template for a turn where
    nothing happened that is visible, or non-trivial, to the person --
    "Unchanged since the last update: <X>." -- and says that turn does not
    owe a fresh Boildown. Widened 2026-09-20 to cover any turn that shape
    fits, not only a scheduled wakeup or background-task notification --
    including one the stop hook itself forces, which is what prompted it:
    a practice-candidate false positive rechecking its own prior output
    produced two closing headings in a row with nothing between them.
    `precedent_reply_check.is_trivial_checkin()` is the mechanical half;
    this proves it actually exempts a reply from a real declared
    requirement, and the negative control proves an ordinary short reply
    that merely mentions the phrase in passing still has to carry one.
    """
    import tempfile
    tmp = pathlib.Path(tempfile.mkdtemp(prefix='precedent-trivial-checkin-'))
    cases = []
    try:
        fx = tmp / 'repo'
        (fx / 'practices').mkdir(parents=True)
        (fx / 'precedent.json').write_text(json.dumps({'sources': [
            {'level': 'universal', 'name': 'precedent', 'path': '.'}]}), encoding='utf-8')
        (fx / 'reply_check.json').write_text(json.dumps({
            'practice': 'fixture-trivial-checkin',
            'require_heading_matching': 'boildown',
            'require_one_of': ['You can archive this session',
                               "Don't archive this session"],
        }), encoding='utf-8')

        def replycheck(text_path):
            return subprocess.run(
                [sys.executable, str(ROOT / 'tools' / 'precedent_reply_check.py'),
                 '--repo', str(fx), '--text', str(text_path)],
                capture_output=True, text=True, cwd=str(tmp),
                env={**os.environ, 'PRECEDENT_USER_CONFIG': str(tmp / 'no-such-config.json')})

        trivial = tmp / 'trivial.md'
        trivial.write_text('Unchanged since the last update: still waiting '
                           'on your answer.\n', encoding='utf-8')
        r1 = replycheck(trivial)
        cases.append(('a reply opening with the fixed trivial-check-in '
                      'template is not blocked, though it carries neither '
                      'the declared heading nor the declared sentence',
                      r1.returncode == 0, r1.stderr[:200]))

        bold = tmp / 'bold.md'
        bold.write_text('**Unchanged since the last update:** still '
                        'waiting on your answer.\n', encoding='utf-8')
        r2 = replycheck(bold)
        cases.append(('...and the same holds when the lead phrase is bolded',
                      r2.returncode == 0, r2.stderr[:200]))

        # The negative control: a reply that merely mentions the phrase
        # partway through, rather than opening with it, is an ordinary reply
        # and still owes the real closing section. Without this, the case
        # above would prove nothing about the match being anchored.
        mid = tmp / 'mid.md'
        mid.write_text('Some work happened. Unchanged since the last '
                       'update: still waiting on your answer.\n', encoding='utf-8')
        r3 = replycheck(mid)
        cases.append(('the control: the same phrase appearing MID-REPLY, '
                      'not at the start, does not exempt anything -- this '
                      'is a literal template match, not a keyword scan',
                      r3.returncode == 2, f'exit {r3.returncode}'))
        cases.append(('...and the block names the missing heading, same as '
                      'any other ordinary reply',
                      'MARKDOWN HEADING' in r3.stderr, r3.stderr[:200]))
    finally:
        shutil.rmtree(tmp, ignore_errors=True)

    bad_cases = [(c[0], c[2] if len(c) > 2 else '') for c in cases if not c[1]]
    check(f'the fixed trivial-check-in template exempts a reply from the '
          f'Boildown gate, anchored to the start of the reply '
          f'({len(cases)} stated cases)',
          not bad_cases,
          '; '.join(f"{n}{' (' + d + ')' if d else ''}" for n, d in bad_cases))


def check_close_detect_counts_only_this_sessions_reverts():
    """The practice-candidate detector's revert signal is this session's own.

    Found 2026-09-30: signals() took every revert reachable from HEAD since
    the session started, so another session's revert, brought in by a merge
    from pre-staging, was reported as "work this session undid". Now only a
    commit carrying this session's trailer, on its own first-parent line,
    counts. Driven against a throwaway repository (practice:
    fixture-owns-its-state)."""
    import tempfile
    import precedent_close_detect as pcd
    cases = []
    saved = os.environ.get('CLAUDE_CODE_REMOTE_SESSION_ID')
    with tempfile.TemporaryDirectory() as td:
        repo = pathlib.Path(td)
        env = dict(os.environ, GIT_AUTHOR_NAME='t', GIT_AUTHOR_EMAIL='t@t',
                   GIT_COMMITTER_NAME='t', GIT_COMMITTER_EMAIL='t@t')

        def g(*a):
            return subprocess.run(['git', '-C', str(repo), *a],
                                  capture_output=True, text=True, env=env).stdout.strip()

        def commit(f, text, msg):
            (repo / f).write_text(text, encoding='utf-8')
            g('add', '-A'); g('commit', '-qm', msg)

        g('init', '-q', '-b', 'pre-staging')
        commit('a', '1', 'base')
        g('checkout', '-q', '-b', 'claude/mine')
        g('checkout', '-q', 'pre-staging')
        commit('b', '1', 'other work\n\nSession: https://claude.ai/code/session_OTHER')
        g('revert', '--no-edit', 'HEAD')
        g('commit', '-q', '--amend', '-m',
          'Revert "other work"\n\nSession: https://claude.ai/code/session_OTHER')
        g('checkout', '-q', 'claude/mine')
        commit('c', '1', 'mine\n\nSession: https://claude.ai/code/session_ME')
        g('merge', '-q', '--no-ff', '--no-edit', 'pre-staging')
        records = [{'timestamp': '2000-01-01T00:00:00Z', 'type': 'user'}]
        os.environ['CLAUDE_CODE_REMOTE_SESSION_ID'] = 'cse_ME'
        try:
            before = [d for n, d in pcd.signals(records, repo) if n == 'reverted-or-corrected']
            commit('c', '2', 'Revert my own change\n\nSession: https://claude.ai/code/session_ME')
            after = [d for n, d in pcd.signals(records, repo) if n == 'reverted-or-corrected']
        finally:
            if saved is None:
                os.environ.pop('CLAUDE_CODE_REMOTE_SESSION_ID', None)
            else:
                os.environ['CLAUDE_CODE_REMOTE_SESSION_ID'] = saved
        cases.append(('a revert merged in from another branch is not a signal',
                      before == [], str(before)))
        cases.append(("the session's own revert is",
                      len(after) == 1 and 'Revert my own change' in after[0], str(after)))
    failed = [f'{n} ({d})' for n, ok, d in cases if not ok]
    check(f'the close detector counts only this session\'s own reverts '
          f'({len(cases)} stated cases)', not failed, '; '.join(failed))


def check_close_detect_ignores_the_assistant_quoted_back():
    """The practice-candidate detector does not read the assistant's own
    sentences, quoted back by the person, as the person's instruction.

    2026-10-04, a consumer: the assistant wrote "Each one, from Sept 11 to
    Sept 25, has a single commit that never reached pre-staging."; the person
    pasted it in quotes and added "review those", and the close check
    reported "the person said: ... never reached ..." as an explicit
    instruction. CONTROL: a quote the assistant never wrote still fires, and
    so does the person's own unquoted rule."""
    import precedent_close_detect as pcd
    said = ('Here is what I found. Each one, from Sept 11 to Sept 25, has a '
            '**single commit** that never reached pre-staging. Nothing else.')

    def session(person):
        return [{'type': 'assistant', 'message': {'role': 'assistant',
                 'content': [{'type': 'text', 'text': said}]}},
                {'type': 'user', 'message': {'role': 'user', 'content': person}}]

    def fired(person):
        return [d for n, d in pcd.signals(session(person), ROOT)
                if n == 'explicit-instruction']
    quoted = ('"Each one, from Sept 11 to Sept 25, has a single commit that '
              'never reached pre-staging." review those')
    block = ('> Each one, from Sept 11 to Sept 25, has a single commit\n'
             '> that never reached pre-staging.\n\nreview those')
    cases = [
        ('the assistant\'s sentence quoted back is not the person\'s instruction',
         fired(quoted) == [], fired(quoted)),
        ('...nor as a > blockquote across lines', fired(block) == [], fired(block)),
        ('...and what the person typed around it is still read',
         'review those' in ' '.join(pcd.person_messages(session(quoted))), ''),
        ('CONTROL: a quote the assistant never wrote still fires',
         len(fired('\u201cNever merge into main without asking.\u201d Keep that.')) == 1,
         fired('\u201cNever merge into main without asking.\u201d Keep that.')),
        ('CONTROL: the person\'s own unquoted rule still fires',
         len(fired('Never push straight to main.')) == 1, fired('Never push straight to main.')),
    ]
    bad = [f'{n} ({d})' for n, ok, d in cases if not ok]
    return (not bad, f'{len(cases)} stated cases', '; '.join(bad))


def check_close_detection_fires_only_when_all_conditions_hold():
    """precedent_close_detect.py: the noticing end of the engine, and every
    one of its four conditions, each with the control that proves the
    condition is doing the work.

    Morgan, 2026-09-14, set all four: a merge happened, the reply closes as
    ready to archive, one per session, and the signal came from this
    session's own material. The failure this guards against is not a missed
    detection -- it is a hook that fires on ordinary sessions and trains
    everyone to ignore it.

    Every case owns its own transcript (practice: fixture-owns-its-state).
    """
    import tempfile
    tmp = pathlib.Path(tempfile.mkdtemp(prefix='precedent-close-'))
    cases = []
    try:
        fx = tmp / 'repo'
        (fx / 'practices').mkdir(parents=True)
        (fx / 'precedent.json').write_text(json.dumps({'sources': [
            {'level': 'universal', 'name': 'precedent', 'path': '.'}]}), encoding='utf-8')

        def transcript(name, turns):
            """turns: [('user'|'assistant'|'tool', payload), ...], oldest first.
            A 'tool' turn is an assistant turn carrying one Bash tool_use."""
            path = tmp / name
            lines = []
            for kind, payload in turns:
                if kind in ('user', 'summary'):
                    rec = {'type': 'user', 'timestamp': '2026-09-14T12:00:00Z',
                           'message': {'role': 'user',
                                       'content': [{'type': 'text', 'text': payload}]}}
                    if kind == 'summary':
                        rec['isCompactSummary'] = True
                elif kind == 'tool':
                    rec = {'type': 'assistant', 'timestamp': '2026-09-14T12:00:00Z',
                           'message': {'content': [
                               {'type': 'tool_use', 'name': 'Bash',
                                'input': {'command': payload}}]}}
                else:
                    rec = {'type': 'assistant', 'timestamp': '2026-09-14T12:00:00Z',
                           'message': {'content': [{'type': 'text', 'text': payload}]}}
                lines.append(json.dumps(rec))
            path.write_text('\n'.join(lines) + '\n', encoding='utf-8')
            return path

        def run(path):
            return subprocess.run(
                [sys.executable, str(ROOT / 'tools' / 'precedent_close_detect.py'),
                 '--repo', str(fx)],
                input=json.dumps({'transcript_path': str(path)}),
                capture_output=True, text=True, cwd=str(tmp),
                env={**os.environ,
                     'PRECEDENT_USER_CONFIG': str(tmp / 'no-such-config.json')})

        SAID = 'From now on always run the deep check before pushing.'
        MERGED = 'git merge --no-ff feature-branch'
        CLOSE = 'Done and merged.\n\n## Next Steps\n\n- **Nothing.**\n\nYou can archive this session.'
        full = [('user', SAID), ('tool', MERGED), ('assistant', CLOSE)]

        # The honest default, first: an engine with no declaration has no
        # opinion about anybody's closing convention (rule-level-by-reach).
        r0 = run(transcript('undeclared.jsonl', full))
        cases.append(('with no close_detect.json declared, nothing is detected '
                      'and nothing is blocked', r0.returncode == 0, r0.stderr[:200]))

        (fx / 'close_detect.json').write_text(json.dumps({
            'practice': 'fixture-close-detect',
            'archive_ready_one_of': ['You can archive this session'],
            'closing_heading_matching': 'next step',
            'candidate_marker': 'Practice candidate',
        }), encoding='utf-8')

        r1 = run(transcript('all.jsonl', full))
        cases.append(('all four conditions holding blocks the close',
                      r1.returncode == 2, f'exit {r1.returncode}: {r1.stderr[:200]}'))
        # control-asserts-which-failure: a non-zero exit is not evidence.
        cases.append(('...and the message names the signal it found',
                      'explicit-instruction' in r1.stderr, r1.stderr[:240]))
        cases.append(('...and quotes what he actually said, so the session '
                      'judges the evidence rather than the label',
                      'deep check before pushing' in r1.stderr, r1.stderr[:240]))
        cases.append(('...and says plainly that a one-off is a valid answer, '
                      'because a hook that only accepts a candidate manufactures '
                      'candidates', 'NOT A RULE' in r1.stderr, r1.stderr[:400]))
        cases.append(('...and names the practice that asked for it',
                      'fixture-close-detect' in r1.stderr, r1.stderr[:400]))

        # Condition 1: a merge. "If there wasn't, we were just talking."
        r2 = run(transcript('no-merge.jsonl',
                            [('user', SAID), ('assistant', CLOSE)]))
        cases.append(('a session that merged NOTHING is left alone, however '
                      'much it said', r2.returncode == 0, r2.stderr[:200]))
        # …and `git merge-base` is not a merge. The freshness guard runs one at
        # the start of every session, so a pattern that counts it reports a
        # merge on every session there has ever been.
        r3 = run(transcript('merge-base.jsonl',
                            [('user', SAID),
                             ('tool', 'git merge-base HEAD origin/main'),
                             ('assistant', CLOSE)]))
        cases.append(('`git merge-base` is not a merge -- the check that '
                      'separates the freshness guard from real work',
                      r3.returncode == 0, r3.stderr[:200]))

        # Condition 2: the session is closing as ready to archive. A session
        # still in flight is one somebody is working in.
        mid = 'Merged it.\n\n## Next Steps\n\n- **Keep going.**\n\nDon\'t archive this session.'
        r4 = run(transcript('mid.jsonl', [('user', SAID), ('tool', MERGED),
                                          ('assistant', mid)]))
        cases.append(('a session that is NOT ready to archive is never '
                      'interrupted with a suggestion', r4.returncode == 0,
                      r4.stderr[:200]))

        # Condition 3: the cap. One per session, not one per reply.
        spent = [('user', SAID), ('tool', MERGED),
                 ('assistant', 'Practice candidate: run the deep check first.'),
                 ('assistant', CLOSE)]
        r5 = run(transcript('spent.jsonl', spent))
        cases.append(('a session that already offered one is not asked again '
                      '-- the cap is per SESSION, not per reply',
                      r5.returncode == 0, r5.stderr[:200]))

        # Condition 4: there is actually something to offer. This is the case
        # that keeps the mechanism from becoming filler -- the ordinary
        # session, which is most of them.
        quiet = [('user', 'Can you fix the typo in the README?'),
                 ('tool', MERGED), ('assistant', CLOSE)]
        r6 = run(transcript('quiet.jsonl', quiet))
        cases.append(('an ordinary session with nothing to offer is silent, '
                      'and is not asked to SAY it found nothing either',
                      r6.returncode == 0, r6.stderr[:200]))

        # The engine's own injected text is written in exactly the standing-
        # rule phrasing the detector looks for, and it comes back through the
        # transcript as a `user` record. Reading those as the person's words
        # would fire this on every session forever.
        injected = [('user', '<system-reminder>\nnever guess; always read the '
                     'file first\n</system-reminder>'),
                    ('tool', MERGED), ('assistant', CLOSE)]
        r7 = run(transcript('injected.jsonl', injected))
        cases.append(("a hook's own injected rule text is not mistaken for "
                      'something the person said', r7.returncode == 0,
                      r7.stderr[:200]))

        # The summary a /compact writes comes back as a `user` record too,
        # flagged isCompactSummary, and restates the session's standing rules
        # in the phrasing the detector looks for (2026-09-30: five signals in
        # one session, none of them typed by the person).
        compacted = [('summary', 'Never push to main. Pick up the last task '
                      'as if the break never happened.'),
                     ('tool', MERGED), ('assistant', CLOSE)]
        r7b = run(transcript('compacted.jsonl', compacted))
        cases.append(("a compaction summary is not mistaken for something the "
                      'person said', r7b.returncode == 0, r7b.stderr[:200]))
        # Control: the same words, typed by the person, still fire.
        r7c = run(transcript('typed.jsonl', [('user', compacted[0][1])] +
                             compacted[1:]))
        cases.append(('...while the same words typed by the person still fire',
                      r7c.returncode == 2, f'exit {r7c.returncode}'))

        # A prompt another session seeded, and a pasted block, are that
        # session's words (2026-09-29: three signals from a pasted handoff,
        # reported as "the person said").
        rule = 'Never open a pull request, never merge.'
        seeded = [('user', 'Review this. Sent automatically by the session '
                   '"x" (session_1) -- https://claude.ai/code/session_1. '
                   'Nobody typed this.\n\n' + rule),
                  ('tool', MERGED), ('assistant', CLOSE)]
        r7d = run(transcript('seeded.jsonl', seeded))
        cases.append(("a prompt another session seeded is not mistaken for "
                      'something the person said', r7d.returncode == 0,
                      r7d.stderr[:200]))
        pasted = [('user', 'Thoughts on this?\n<pasted_content id="p1">\n'
                   + rule + '\n</pasted_content id="p1">'),
                  ('tool', MERGED), ('assistant', CLOSE)]
        r7e = run(transcript('pasted.jsonl', pasted))
        cases.append(('nor is text pasted in a <pasted_content> block',
                      r7e.returncode == 0, r7e.stderr[:200]))
        typed_around = [('user', rule + '\n<pasted_content id="p2">\nsome '
                         'notes\n</pasted_content id="p2">'),
                        ('tool', MERGED), ('assistant', CLOSE)]
        r7f = run(transcript('typed-around.jsonl', typed_around))
        cases.append(("...while the person's own words beside a paste still "
                      'fire', r7f.returncode == 2, f'exit {r7f.returncode}'))

        # A gate that blocks the same reply twice is a loop.
        r8 = subprocess.run(
            [sys.executable, str(ROOT / 'tools' / 'precedent_close_detect.py'),
             '--repo', str(fx)],
            input=json.dumps({'transcript_path': str(transcript('again.jsonl', full)),
                              'stop_hook_active': True}),
            capture_output=True, text=True, cwd=str(tmp),
            env={**os.environ,
                 'PRECEDENT_USER_CONFIG': str(tmp / 'no-such-config.json')})
        cases.append(('a turn this hook already blocked is not blocked twice',
                      r8.returncode == 0, r8.stderr[:200]))

        # Blindness never blocks.
        r9 = run(tmp / 'no-such-transcript.jsonl')
        cases.append(('an unreadable transcript blocks nothing',
                      r9.returncode == 0, r9.stderr[:200]))
    finally:
        shutil.rmtree(tmp, ignore_errors=True)

    bad_cases = [(c[0], c[2] if len(c) > 2 else '') for c in cases if not c[1]]
    check(f'close detection fires on all four conditions and on none of them '
          f'alone ({len(cases)} stated cases, each with its control)',
          not bad_cases,
          '; '.join(f"{n}{' (' + d + ')' if d else ''}" for n, d in bad_cases))


def check_loader_tools_are_repo_relocatable():
    """precedent_show.py, precedent_paths.py, precedent_gate.py and
    build_views.py used to compute their working root as `pathlib.Path(
    __file__).resolve().parents[1]` -- "whatever is two folders up from my
    own file" -- which is only correct when the script sits at exactly
    <repo>/tools/whatever.py. precedent_sync_views.py's own docstring
    already named this trap for anyone tempted to run these from inside a
    vendored process/upstream/tools/ mirror instead. Fixed to take --repo,
    keeping two notions of "root" apart that the old code conflated:
    where to find THIS SCRIPT's own sibling modules to import (tied to the
    script's own file location, never to --repo) versus which repo's
    content (practices/, AGENTS.md, ...) to actually operate on (--repo,
    defaulting to today's behavior when omitted). Each half gets its own
    case below, for every one of the four tools, rather than trusting that
    fixing one half didn't quietly break the other: running the real,
    in-place script from a cwd that is neither the repo root nor the
    script's own directory (sibling imports must still resolve), and
    running it with --repo pointed at a small fixture repo whose content
    exists nowhere else (the named repo's content must actually be what
    comes back, not a silent fallback to this repo's own)."""
    import shutil, tempfile

    tmp = pathlib.Path(tempfile.mkdtemp(prefix='precedent-relocation-'))
    elsewhere = pathlib.Path(tempfile.mkdtemp(prefix='precedent-elsewhere-cwd-'))
    cases = []
    try:
        fixture = tmp / 'fixture'
        (fixture / 'practices').mkdir(parents=True)
        (fixture / 'practices' / 'fixture-only-slug.md').write_text(
            '---\nslug: fixture-only-slug\ntitle: Fixture\ntier: on-demand\n'
            'severity: default\napplies_to: ["fixture-only/**"]\n'
            'occasion: "testing --repo relocation"\ngates: ["merge"]\n'
            # This fixture asserts the slug lands in the rendered block, so it
            # must declare its index line rather than inherit one: it carries a
            # real glob AND a gate, which is exactly the shape build_views now
            # omits from the occasion index (practice: fixture-owns-its-state).
            'index_required: true\n'
            'index_clause: "x"\nchecked_by: null\ndefines: []\nstatus: active\n'
            'supersedes: []\noverrides: null\nadded: 2026-09-05\n'
            'approved_by: "harness, 2026-09-05"\nsource_practice_number: null\n'
            '---\n## Rule\nA fixture-only rule text, present in no other repo.\n\n'
            '## Why\nx\n\n## Story\nx\n\n## Install\nx\n', encoding='utf-8')
        (fixture / 'tools').mkdir(parents=True)
        (fixture / 'tools' / 'routing_scope.json').write_text(
            json.dumps({'_note': [], 'practices': {}, 'gates': {'merge': 'merging a branch'}}),
            encoding='utf-8')
        (fixture / 'AGENTS.md').write_text(
            '# fixture\n\n<!-- BEGIN GENERATED: precedent-loader -->\n'
            '<!-- END GENERATED -->\n', encoding='utf-8')

        fixture_slug = 'fixture-only-slug'
        real_slug = sorted(PRACTICES_DIR.glob('*.md'))[0].stem
        original_agents_text = AGENTS_MD.read_text(encoding='utf-8')

        def run(tool, *args, cwd=None):
            r = subprocess.run([sys.executable, str(ROOT / 'tools' / tool), *args],
                               capture_output=True, text=True,
                               cwd=str(cwd) if cwd else None)
            return r.returncode, r.stdout + r.stderr

        # --- a different cwd, no --repo: sibling imports must still resolve,
        # and the unchanged default must still be THIS repo's own content --
        rc, out = run('precedent_show.py', real_slug, cwd=elsewhere)
        cases.append(("precedent_show.py from a different cwd, no --repo, resolves its "
                      "sibling import and shows THIS repo's own practice",
                      rc == 0 and f'### {real_slug}' in out, out[:200] if rc else ''))

        rc, out = run('precedent_paths.py', '--matches-only', 'AGENTS.md', cwd=elsewhere)
        cases.append(('precedent_paths.py from a different cwd, no --repo, resolves',
                      rc == 0, out[:200] if rc else ''))

        rc, out = run('precedent_gate.py', '--list', cwd=elsewhere)
        cases.append(('precedent_gate.py from a different cwd, no --repo, resolves',
                      rc == 0 and bool(out.strip()), out[:200] if rc else ''))

        rc, out = run('build_views.py', '--check', '--agents-only', cwd=elsewhere)
        cases.append(('build_views.py from a different cwd, no --repo, still checks '
                      'THIS repo unchanged', rc == 0, out[:200] if rc else ''))

        # --- --repo pointed at the fixture: each tool must read the NAMED
        # repo's content, not silently fall back to this repo's own --------
        rc, out = run('precedent_show.py', fixture_slug, '--repo', str(fixture))
        cases.append(("precedent_show.py --repo reads the named repo's own practice",
                      rc == 0 and 'fixture-only rule text' in out, out[:200]))

        rc, out = run('precedent_show.py', real_slug, '--repo', str(fixture))
        cases.append(("precedent_show.py --repo does NOT fall back to this repo's own practice",
                      rc != 0, '' if rc != 0 else out[:200]))

        rc, out = run('precedent_paths.py', '--repo', str(fixture), '--matches-only',
                      'fixture-only/thing.txt')
        cases.append(("precedent_paths.py --repo matches the named repo's own applies_to glob",
                      rc == 0 and fixture_slug in out, out[:200]))

        rc, out = run('precedent_gate.py', '--repo', str(fixture), 'merge')
        cases.append(("precedent_gate.py --repo loads the named repo's own gate-registered practice",
                      rc == 0 and fixture_slug in out, out[:200]))

        rc, out = run('build_views.py', '--repo', str(fixture), '--agents-only')
        fixture_agents_text = (fixture / 'AGENTS.md').read_text(encoding='utf-8')
        cases.append(("build_views.py --repo regenerates the named repo's own AGENTS.md",
                      rc == 0 and fixture_slug in fixture_agents_text, out[:200]))
        cases.append(("build_views.py --repo left THIS repo's own AGENTS.md untouched",
                      AGENTS_MD.read_text(encoding='utf-8') == original_agents_text))
    finally:
        shutil.rmtree(tmp, ignore_errors=True)
        shutil.rmtree(elsewhere, ignore_errors=True)

    bad = [(c[0], c[2] if len(c) > 2 else '') for c in cases if not c[1]]
    check(f'the four file-location-dependent loader tools take --repo '
          f'(precedent_show.py, precedent_paths.py, precedent_gate.py, build_views.py; '
          f'{len(cases)} stated cases: sibling imports resolve from a different cwd with '
          f"no --repo, and --repo relocates content without touching this repo's own)",
          not bad, '; '.join(f"{n}{' (' + d + ')' if d else ''}" for n, d in bad))


def check_materialize_bridges_loader():
    """tools/precedent_materialize.py — the deep-check session's own answer
    to spec/PHASE5_BRIEF.md's named gap: precedent_resolve.py is the only
    multi-source-aware tool; build_views.py/precedent_paths.py/
    precedent_gate.py/precedent_check.py all read a single local practices/
    directory. Proven for real (not just unit-tested here) against the two
    real private sets by that session; this harness case is the planted,
    repeatable version: two throwaway sources (one universal-shaped, one
    team-shaped) with a deliberate tools/checks/ filename collision AND a
    resident-budget overage, confirming both refuse, then a clean pair
    materializes and an unmodified build_views.py run against the output
    actually produces a resident block naming a practice from EACH source
    (not just proving files got copied)."""
    import shutil, subprocess, tempfile

    tmp = pathlib.Path(tempfile.mkdtemp(prefix='precedent-materialize-'))

    def write_practice(path, slug, rule, tier='on-demand', occasion='x',
                       checked_by='null'):
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_text(
            f'---\nslug: {slug}\ntitle: Fixture\ntier: {tier}\n'
            f'severity: default\napplies_to: ["**"]\noccasion: "{occasion}"\n'
            f'gates: []\nindex_clause: "x"\nchecked_by: {checked_by}\ndefines: []\n'
            f'status: active\nsupersedes: []\noverrides: null\n'
            f'added: 2026-09-02\napproved_by: "harness, 2026-09-02"\n'
            f'source_practice_number: null\n---\n## Rule\n{rule}\n\n'
            f'## Why\nx\n\n## Story\nx\n\n## Install\nx\n', encoding='utf-8')

    def write_check(path, body='VIOLATION: fixture\n'):
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_text(f'#!/usr/bin/env python3\nprint({body!r})\n', encoding='utf-8')

    cases = []
    try:
        uni, team = tmp / 'universal', tmp / 'team'
        # Both fixture practices CLAIM the same check filename, which is
        # what makes the collision below a real one: since 2026-09-06
        # materialize only vendors a script some resolved practice's
        # `checked_by` names, so an unclaimed pair would simply be dropped
        # and never collide.
        write_practice(uni / 'practices' / 'uni-fixture.md', 'uni-fixture',
                        'A universal fixture Rule.', tier='resident',
                        checked_by='"tools/checks/check_shared_name.py"')
        write_practice(team / 'practices' / 'team-fixture.md', 'team-fixture',
                        'A team fixture Rule.', tier='resident',
                        checked_by='"tools/checks/check_shared_name.py"')
        write_check(uni / 'tools' / 'checks' / 'check_shared_name.py')
        write_check(team / 'tools' / 'checks' / 'check_shared_name.py')
        write_check(uni / 'tools' / 'checks' / 'tests' / 'test_shared_name.sh',
                    body='fixture\n')
        # Claimed by nothing: a script whose practice was retired, or lost
        # its slug to a higher-precedence source. Must not be vendored --
        # precedent-team-repo-maintenance' retired `deep-check` shipped exactly
        # this into a consuming repo, where it registered under its own
        # filename and reported "not in force" forever.
        write_check(uni / 'tools' / 'checks' / 'check_orphan.py')
        write_check(uni / 'tools' / 'checks' / 'tests' / 'test_orphan.sh',
                    body='fixture\n')

        consumer = tmp / 'consumer'
        (consumer).mkdir()
        (consumer / 'precedent.json').write_text(json.dumps({
            'sources': [{'level': 'universal', 'name': 'precedent', 'path': str(uni)},
                        {'level': 'team', 'name': 'precedent-team-fixture', 'path': str(team)}]
        }), encoding='utf-8')

        materialize_tool = str(ROOT / 'tools' / 'precedent_materialize.py')

        def run(*extra):
            r = subprocess.run([sys.executable, materialize_tool, '--out', str(consumer),
                                 '--repo', str(consumer), *extra],
                                capture_output=True, text=True)
            return r.returncode, r.stdout + r.stderr

        # --- a tools/checks/ filename collision across sources refuses -----
        rc, out = run()
        cases.append(('a checks/ filename collision across two sources refuses',
                      rc == 1 and 'collision' in out))

        # --- a same-named copy in a source whose practice does NOT claim it
        # is left behind, never a collision (2026-09-23: the universal tree
        # began carrying its own copies of the individual set's commit
        # checks, and the first sync in a migrating consumer refused) -------
        write_practice(uni / 'practices' / 'uni-fixture.md', 'uni-fixture',
                        'A universal fixture Rule.', tier='resident')
        rc, out = run()
        cases.append(('a copy only ANOTHER source claims is left behind, not a '
                      'collision', rc == 0 and 'collision' not in out
                      and 'check_shared_name.py (precedent)' in out))
        cases.append(('and the claiming source\'s copy is the one vendored',
                      (consumer / 'tools' / 'checks' / 'check_shared_name.py').is_file()))
        write_practice(uni / 'practices' / 'uni-fixture.md', 'uni-fixture',
                        'A universal fixture Rule.', tier='resident',
                        checked_by='"tools/checks/check_shared_name.py"')

        # --- an over-budget combined resident set refuses -------------------
        (team / 'tools' / 'checks' / 'check_shared_name.py').unlink()
        huge_rule = ' '.join(['word'] * 2000)
        write_practice(team / 'practices' / 'huge-fixture.md', 'huge-fixture',
                        huge_rule, tier='resident')
        rc, out = run()
        cases.append(('an over-budget combined resident set refuses to materialize',
                      rc == 1 and 'over' in out and 'budget' in out))

        # --- a clean pair materializes, and an UNMODIFIED build_views.py run
        # against the output actually shows both sources' resident practices --
        (team / 'practices' / 'huge-fixture.md').unlink()
        rc, out = run()
        materialized_ok = (rc == 0 and (consumer / 'MANIFEST.json').exists()
                            and (consumer / 'practices' / 'uni-fixture.md').exists()
                            and (consumer / 'practices' / 'team-fixture.md').exists())

        # --- every MANIFEST.json path (practices AND checks) actually
        # resolves to a file on disk -- regression case for a doubled
        # tools/checks/checks/ segment in checks[].path entries -------------
        manifest_paths_ok = False
        manifest_paths_detail = ''
        if materialized_ok:
            manifest = json.loads((consumer / 'MANIFEST.json').read_text(encoding='utf-8'))
            entries = ([('practices', e['slug'], f"practices/{e['slug']}.md")
                        for e in manifest.get('practices', [])]
                       + [('checks', e['path'], e['path'])
                          for e in manifest.get('checks', [])])
            missing = [label for _, label, rel in entries if not (consumer / rel).exists()]
            manifest_paths_ok = not missing
            manifest_paths_detail = f"missing on disk: {missing}" if missing else ''
        cases.append(('every MANIFEST.json practices[]/checks[] path resolves to a '
                      'real file on disk', manifest_paths_ok, manifest_paths_detail))

        cases.append(("a check script no resolved practice's checked_by names "
                      "is not vendored, and neither is its test",
                      materialized_ok
                      and not (consumer / 'tools' / 'checks' / 'check_orphan.py').exists()
                      and not (consumer / 'tools' / 'checks' / 'tests' / 'test_orphan.sh').exists()))
        cases.append(('a claimed check script and its test ARE vendored',
                      materialized_ok
                      and (consumer / 'tools' / 'checks' / 'check_shared_name.py').exists()
                      and (consumer / 'tools' / 'checks' / 'tests' / 'test_shared_name.sh').exists()))

        (consumer / 'tools').mkdir(parents=True, exist_ok=True)
        # summary_text.py since 2026-09-25: build_views.py imports it at
        # module level, as it does split_practices.py.
        for f in ('build_views.py', 'split_practices.py', 'summary_text.py'):
            shutil.copyfile(ROOT / 'tools' / f, consumer / 'tools' / f)
        (consumer / 'AGENTS.md').write_text(
            '# fixture\n\n<!-- BEGIN GENERATED: precedent-loader -->\n'
            '<!-- END GENERATED -->\n', encoding='utf-8')
        r = subprocess.run([sys.executable, str(consumer / 'tools' / 'build_views.py')],
                            capture_output=True, text=True, cwd=str(consumer))
        agents_text = (consumer / 'AGENTS.md').read_text(encoding='utf-8') \
            if (consumer / 'AGENTS.md').exists() else ''
        cases.append(('a clean materialize + unmodified build_views.py run produces '
                      "a resident block naming BOTH sources' practices, not just one",
                      materialized_ok and r.returncode == 0
                      and 'uni-fixture' in agents_text and 'team-fixture' in agents_text))

        # --- the SAME scenario again, but run tools/build_views.py IN PLACE
        # (no copy) with --repo pointed at the fixture, instead of copying
        # the script into the fixture's own tools/ first. Before build_views
        # accepted --repo, this was the only way to test it against content
        # that isn't its own -- ROOT was always computed as two folders up
        # from wherever the running copy physically sat, so a script that
        # never moved could never be pointed elsewhere. This case is kept
        # ALONGSIDE the copy-based case above, not in place of it: a
        # consuming repo's own vendored copy (the documented, still-current
        # INSTALL.md model) is the copy-based shape, and a future vendored
        # engine invoked with --repo (this request's own stated motivation)
        # is this one -- both invocation styles have to keep working.
        (consumer / 'AGENTS.md').write_text(
            '# fixture\n\n<!-- BEGIN GENERATED: precedent-loader -->\n'
            '<!-- END GENERATED -->\n', encoding='utf-8')
        r2 = subprocess.run([sys.executable, str(ROOT / 'tools' / 'build_views.py'),
                              '--repo', str(consumer), '--agents-only'],
                             capture_output=True, text=True)
        agents_text2 = (consumer / 'AGENTS.md').read_text(encoding='utf-8') \
            if (consumer / 'AGENTS.md').exists() else ''
        cases.append(("the real, un-relocated build_views.py run with --repo (no copy) "
                      "produces a resident block naming BOTH sources' practices too",
                      materialized_ok and r2.returncode == 0
                      and 'uni-fixture' in agents_text2 and 'team-fixture' in agents_text2))
        # The GENERATED test driver. tools/checks/tests/run_all.sh is the one
        # file this tool writes rather than copies: every source ships its own,
        # so copying would force a winner, but `deep-check` requires the file to
        # exist -- so before 2026-09-06 no consuming repo could satisfy that
        # practice, and its far more useful half (each check has a test; no test
        # outlives its check) never ran, because the check returns early on the
        # missing file. Twelve properties, each with its own way of regressing:
        # four about the generated driver itself, then eight about the 2026-09-12
        # change that stopped REPORTING the replaced source copy as a dropped
        # file and started reporting the one thing a person can act on -- a
        # source driver that does not declare itself local.
        run_all = consumer / 'tools' / 'checks' / 'tests' / 'run_all.sh'
        run_all_text = run_all.read_text(encoding='utf-8') if run_all.is_file() else ''
        cases.append(('the test driver is generated into the consumer even though '
                      'no source file was copied for it',
                      materialized_ok and run_all.is_file()))
        # deep-check greps for this exact glob; a driver naming specific tests
        # would pass a bare existence test while silently skipping new ones.
        cases.append(('the generated driver globs test_*.sh rather than naming '
                      'tests, so it runs whatever THIS repo materialized',
                      'test_*.sh' in run_all_text))
        # An unrecorded file is indistinguishable from a hand-dropped orphan to
        # a consuming repo's own orphan detection, which reads MANIFEST.json.
        manifest_path = consumer / 'MANIFEST.json'
        recorded = []
        if manifest_path.is_file():
            recorded = [c for c in json.loads(
                manifest_path.read_text(encoding='utf-8')).get('checks', [])
                if c.get('path', '').endswith('tests/run_all.sh')]
        cases.append(('the generated driver is recorded in MANIFEST.json, so a '
                      "consumer's orphan detection does not read it as hand-dropped",
                      len(recorded) == 1))
        # A repo that materialized no tests leaves the glob unexpanded; without
        # the guard the driver runs a file literally named test_*.sh and reports
        # a failure that is really an empty set.
        empty_dir = tmp / 'empty-driver'
        empty_dir.mkdir(parents=True, exist_ok=True)
        (empty_dir / 'run_all.sh').write_text(run_all_text or 'exit 1\n', encoding='utf-8')
        r3 = subprocess.run(['bash', 'run_all.sh'], cwd=str(empty_dir),
                            capture_output=True, text=True)
        cases.append(('the generated driver exits 0 in a repo that materialized '
                      'no tests, rather than failing on the unexpanded glob',
                      bool(run_all_text) and r3.returncode == 0))

        # --- the source's OWN driver: replaced, not dropped, and asked to
        # say so. Before 2026-09-12 a source's run_all.sh fell into the
        # generic `skipped` bucket and printed "not a per-check file, not
        # vendored" on every sync forever -- true about the source's copy,
        # and read by more than one person as "so this repo has no driver",
        # which cost a cross-repo investigation to settle. The line is gone;
        # what replaced it names a source whose driver does not declare
        # itself local, and goes silent once the source declares. `helper.py`
        # is the control: a file that really WAS dropped must still report
        # under the old wording, or this change has simply muted a real
        # signal along with the misleading one. ---------------------------
        #
        # These two runs own their SOURCE SET, which the cases above do not
        # need to: precedent.json names two fixture sources, but the resolver
        # also picks up whatever individual source ~/.config/precedent names,
        # and this container's real one ships an undeclared driver. Left
        # inherited, the silence case can never pass no matter what the
        # fixture does -- it would be measuring this container, which is
        # practices/fixture-owns-its-state.md exactly. HOME is redirected to
        # a directory the fixture made; CLAUDE_CODE_REMOTE is dropped as well
        # because precedent_resolve's self-heal CLONES the individual source
        # into whatever HOME it is handed, but only in a hosted session, so
        # unsetting it is what keeps the fixture HOME actually empty.
        fixture_home = tmp / 'driver-home'
        fixture_home.mkdir(parents=True, exist_ok=True)
        iso_env = {k: v for k, v in os.environ.items()
                   if k != 'CLAUDE_CODE_REMOTE' and not k.startswith('PRECEDENT_')}
        iso_env['HOME'] = str(fixture_home)

        def run_isolated():
            r = subprocess.run([sys.executable, materialize_tool,
                                 '--out', str(consumer), '--repo', str(consumer)],
                                capture_output=True, text=True, env=iso_env)
            return r.returncode, r.stdout + r.stderr

        team_checks = team / 'tools' / 'checks'
        write_check(team_checks / 'helper.py')
        team_driver = team_checks / 'tests' / 'run_all.sh'
        team_driver.parent.mkdir(parents=True, exist_ok=True)
        team_driver.write_text('#!/bin/bash\n# a local driver\nexit 0\n',
                               encoding='utf-8')

        rc4, out4 = run_isolated()
        skip_line4 = next((ln for ln in out4.splitlines()
                           if 'not a per-check file, not vendored' in ln), '')
        marker = 'LOCAL DRIVER -- not shipped to consumers'
        cases.append(("a source driver that does not declare itself local warns, "
                      "naming that source",
                      'does not say so' in out4
                      and 'precedent-team-fixture' in out4))
        cases.append(('that warning states the remedy -- the exact marker line '
                      'to add -- rather than only naming the problem',
                      marker in out4))
        cases.append(('the undeclared driver still MATERIALIZES: it warns, it '
                      'does not fail, and the generated driver is still written',
                      rc4 == 0 and run_all.is_file()))
        cases.append(("a file that really was dropped still reports under the "
                      "existing 'not a per-check file, not vendored' wording",
                      'helper.py' in skip_line4))
        cases.append(('that wording no longer names run_all.sh, which is '
                      'replaced rather than dropped',
                      bool(skip_line4) and 'run_all.sh' not in skip_line4))

        team_driver.write_text(f'#!/bin/bash\n# {marker}\nexit 0\n',
                               encoding='utf-8')
        rc5, out5 = run_isolated()
        cases.append(('the warning goes SILENT once the source declares its '
                      'driver local -- silence is the compliance signal',
                      rc5 == 0 and 'does not say so' not in out5))
        cases.append(('the generated driver is still written for a source that '
                      'declares its own',
                      rc5 == 0 and run_all.is_file()))
        # If this fails, the silence case above was measuring this container's
        # own individual source rather than the fixture's two sources, and
        # every verdict either way is worthless.
        cases.append(('the isolated runs really did own their source set -- '
                      'nothing cloned an individual source into the fixture HOME',
                      not any(fixture_home.iterdir())))

    finally:
        shutil.rmtree(tmp, ignore_errors=True)

    bad = [(c[0], c[2] if len(c) > 2 else '') for c in cases if not c[1]]
    check(f'precedent_materialize.py bridges the loader ({len(cases)} stated cases: '
          f'a checks/ collision refuses, an over-budget combined set refuses, a clean '
          f"materialize feeds both a copied and an in-place --repo build_views.py "
          f"both sources' content, and the test driver is generated rather than "
          f'copied -- present, globbing, recorded in the manifest, exiting 0 '
          f'on an empty test set, and warning only about a source driver that '
          f'does not declare itself local, silently once it does)',
          not bad, '; '.join(f"{n}{' (' + d + ')' if d else ''}" for n, d in bad))


def check_shipped_tests_name_their_owner_and_fail_at_home():
    """A check test a practice source ships runs in every consuming
    repository, against that repository's tree -- and until 2026-09-25 a
    failing one there was nobody's. Sessions in consumers reported "fails on
    the base branch too, not this change" and moved on, and one test stayed
    red for days: it staged a fixture under vendor/ with a plain `git add`,
    which a consumer ignoring vendor/ refuses and its home source never did.

    Two halves, each with its own way of regressing:

    * the generated tools/checks/tests/run_all.sh names the source of every
      failing test, says a shipped one is that source's bug, and tells the
      repo-local and unknown cases apart -- and stays silent about owners
      when everything passes (the negative control);
    * tools/precedent_consumer_shape.py fails, at home, the test that passes
      in its home layout and not in a consumer's, passes the same test once
      it stages with `git add -f`, and is wired into a practice source's
      full push check."""
    import importlib.util, shutil, tempfile
    name = ('a shipped test names its owner when it fails in a consumer, '
            'and a home-only test fails at home')
    materialize_tool = ROOT / 'tools' / 'precedent_materialize.py'
    shape_tool = ROOT / 'tools' / 'precedent_consumer_shape.py'
    push_tool = ROOT / 'tools' / 'precedent_push_check.py'
    if not (materialize_tool.exists() and shape_tool.exists() and push_tool.exists()):
        not_applicable(name, 'precedent_materialize.py, precedent_consumer_shape.py '
                             'or precedent_push_check.py is absent')
        return

    def load(mod_name, path):
        spec = importlib.util.spec_from_file_location(mod_name, path)
        mod = importlib.util.module_from_spec(spec)
        spec.loader.exec_module(mod)
        return mod

    pm = load('_pm_owner', materialize_tool)
    pcs = load('_pcs_owner', shape_tool)
    ppc = load('_ppc_owner', push_tool)
    cases = []
    tmp = pathlib.Path(tempfile.mkdtemp(prefix='precedent-shipped-tests-'))
    # The fixture owns git's configuration: a machine's own global excludes
    # would otherwise decide whether the "passes at home" premise holds
    # (practice: fixture-owns-its-state).
    (tmp / 'gitconfig').write_text('', encoding='utf-8')
    env = {k: v for k, v in os.environ.items()
           if not k.startswith('GIT_CONFIG_')}
    env.update(GIT_CONFIG_GLOBAL=str(tmp / 'gitconfig'),
               GIT_CONFIG_NOSYSTEM='1', PRECEDENT_ALLOW_ANY_AUTHOR='1',
               GIT_AUTHOR_NAME='T', GIT_AUTHOR_EMAIL='t@example.com',
               GIT_COMMITTER_NAME='T', GIT_COMMITTER_EMAIL='t@example.com')

    def write_test(d, fname, body):
        d.mkdir(parents=True, exist_ok=True)
        (d / fname).write_text('#!/bin/bash\n' + body + '\n', encoding='utf-8')

    try:
        # --- half 1: the generated driver names the owner -----------------
        team, local = tmp / 'team', tmp / 'local-src'
        write_test(team / 'tools' / 'checks' / 'tests', 'test_bad.sh', 'exit 1')
        write_test(team / 'tools' / 'checks' / 'tests', 'test_good.sh', 'exit 0')
        write_test(local / 'tools' / 'checks' / 'tests', 'test_local_bad.sh', 'exit 1')
        sources = [{'name': 'precedent-team-fixture', 'level': 'shared',
                    'path': str(team)},
                   {'name': 'local', 'level': 'repo-local', 'path': str(local)}]
        plan = pm._plan_checks(sources, None)
        consumer_tests = tmp / 'consumer' / 'tools' / 'checks' / 'tests'
        consumer_tests.mkdir(parents=True)
        for rel_label, filename, _src, data in plan:
            if rel_label == 'checks/tests':
                (consumer_tests / filename).write_bytes(data)
        driver_text = (consumer_tests / 'run_all.sh').read_text(encoding='utf-8')
        # The table agrees with what the manifest records for each test: the
        # manifest's checks[] source comes from this same plan entry.
        table_ok = all(f"{fn}) owner={src};" in driver_text
                       for rel, fn, src, _d in plan
                       if rel == 'checks/tests' and fn != 'run_all.sh')
        cases.append(("the driver's owner table carries every materialized "
                      "test's source, as MANIFEST.json's checks[] records it",
                      table_ok))
        # A test nobody materialized: dropped in by hand, failing.
        write_test(consumer_tests, 'test_stray.sh', 'exit 1')
        r = subprocess.run(['bash', 'run_all.sh'], cwd=consumer_tests,
                           capture_output=True, text=True, env=env)
        out = r.stdout + r.stderr
        cases.append(('the driver still exits 1 when a test fails',
                      r.returncode == 1, f'exit {r.returncode}'))
        cases.append(('a failing shipped test is named with its source and level',
                      "FAILED: test_bad.sh -- shipped by source "
                      "'precedent-team-fixture' (shared level)" in out))
        cases.append(('the driver says a shipped failure is not to be recorded '
                      'as pre-existing',
                      'Never record it here as pre-existing' in out))
        cases.append(("a repo-local test's failure is this repo's own to fix",
                      "FAILED: test_local_bad.sh -- this repo's own repo-local "
                      "source (local/): fix it here" in out))
        cases.append(('a test no source shipped is called out as such, not '
                      'pinned on a source',
                      'FAILED: test_stray.sh -- no source shipped it' in out))
        cases.append(('a passing test is never named as failed',
                      'FAILED: test_good.sh' not in out))
        found = ppc._finding_lines(out.splitlines())
        cases.append(("the push check's finding extraction carries the owner "
                      "line, so a refused push shows whose test failed",
                      any("shipped by source 'precedent-team-fixture'" in l
                          for l in found)))
        # Negative control: nothing failing, nothing said about owners.
        for f in ('test_bad.sh', 'test_local_bad.sh', 'test_stray.sh'):
            (consumer_tests / f).unlink()
        r = subprocess.run(['bash', 'run_all.sh'], cwd=consumer_tests,
                           capture_output=True, text=True, env=env)
        cases.append(('all passing: exit 0 and no ownership summary at all',
                      r.returncode == 0 and 'who owns each' not in r.stdout
                      and 'pre-existing' not in r.stdout))

        # --- half 2: consumer-shaped run fails a home-only test at home ---
        def source_repo(label, add_cmd):
            d = tmp / label
            write_test(d / 'tools' / 'checks' / 'tests', 'test_plant.sh',
                       'set -e\ns="$(mktemp -d)"\ngit init -q "$s"\n'
                       'mkdir -p "$s/vendor"\necho x > "$s/vendor/THIRD_PARTY.md"\n'
                       f'git -C "$s" {add_cmd} vendor/THIRD_PARTY.md\n'
                       'rm -rf "$s"\necho ok')
            subprocess.run(['git', 'init', '-q', str(d)], env=env,
                           capture_output=True)
            return d

        plain = source_repo('src-plain-add', 'add')
        forced = source_repo('src-forced-add', 'add -f')
        home = subprocess.run(['bash', 'test_plant.sh'],
                              cwd=plain / 'tools' / 'checks' / 'tests',
                              capture_output=True, text=True, env=env)
        cases.append(('premise: the plain-add test passes in its home layout',
                      home.returncode == 0, (home.stdout + home.stderr)[-200:]))
        r = subprocess.run([sys.executable, str(shape_tool), '--repo', str(plain)],
                           capture_output=True, text=True, env=env)
        cases.append(('the consumer-shaped run fails it, naming the test and the '
                      'cause class',
                      r.returncode == 1 and 'FAILED: test_plant.sh -- fails in '
                      'a consumer-shaped copy of this repository' in r.stdout
                      and 'git add -f' in r.stdout,
                      f'exit {r.returncode}: {r.stdout[-300:]}'))
        r = subprocess.run([sys.executable, str(shape_tool), '--repo', str(forced)],
                           capture_output=True, text=True, env=env)
        cases.append(('the same test staging with `git add -f` passes the '
                      'consumer-shaped run',
                      r.returncode == 0 and 'all 1 passed' in r.stdout,
                      f'exit {r.returncode}: {r.stdout[-300:]}'))
        bare = tmp / 'no-tests'
        subprocess.run(['git', 'init', '-q', str(bare)], env=env, capture_output=True)
        r = subprocess.run([sys.executable, str(shape_tool), '--repo', str(bare)],
                           capture_output=True, text=True, env=env)
        cases.append(('a repo with no tests: exit 0, and it says there was '
                      'nothing to run',
                      r.returncode == 0 and 'nothing to run' in r.stdout))
        r = subprocess.run([sys.executable, str(shape_tool), '--repo',
                            str(tmp / 'team')], capture_output=True, text=True,
                           env=dict(env, GIT_CEILING_DIRECTORIES=str(tmp)))
        cases.append(('outside a git checkout: exit 2, said so',
                      r.returncode == 2 and 'not inside a git checkout' in r.stderr))
        base = {'GIT_CONFIG_COUNT': '1', 'GIT_CONFIG_KEY_0': 'a.b',
                'GIT_CONFIG_VALUE_0': 'c'}
        merged = pcs.consumer_env('/x/ignore', base=base)
        cases.append(('the ignores are appended to GIT_CONFIG_COUNT entries '
                      'already set, never replacing them',
                      merged.get('GIT_CONFIG_COUNT') == '2'
                      and merged.get('GIT_CONFIG_KEY_0') == 'a.b'
                      and merged.get('GIT_CONFIG_KEY_1') == 'core.excludesFile'
                      and merged.get('GIT_CONFIG_VALUE_1') == '/x/ignore'))

        names = {kind: [n for n, _a, _r in ppc.PUSH_CHECKS[kind]]
                 for kind in ppc.PUSH_CHECKS}
        cases.append(("a practice source's full push check runs the "
                      'consumer-shaped suite, right after its own',
                      'consumer_shape' in names['source']
                      and names['source'].index('consumer_shape')
                      == names['source'].index('deep_check') + 1
                      and 'consumer_shape' not in ppc.BASIC_CHECKS))
        cases.append(('it ships with the engine every kind vendors',
                      "'precedent_consumer_shape.py'" in
                      (ROOT / 'tools' / 'precedent_vendor_engine.py').read_text(
                          encoding='utf-8')))
    finally:
        shutil.rmtree(tmp, ignore_errors=True)

    bad = [(c[0], c[2] if len(c) > 2 else '') for c in cases if not c[1]]
    check(f'{name} ({len(cases)} stated cases)', not bad,
          '; '.join(f"{n}{' (' + d + ')' if d else ''}" for n, d in bad))


def check_materialize_carries_harness_adapters():
    """tools/precedent_materialize.py — a practice source's HARNESS ADAPTERS
    travel with it, the way its checks already do.

    Until 2026-09-12 a source's `bootstrap/*.sh` reached a consuming repo's
    `.claude/hooks/` by hand-copy, per each practice's own Install section, so
    a repo carrying a copy went silently behind the moment the source's script
    changed. Measured twice in two days: findings fixed upstream briefed as
    open defects in the source, because they were really about the consuming
    repo's stale copy; and a `commit-identity.sh` about five kilobytes behind
    its source with every local check green.

    Every case here is a behaviour something would silently lose: the file
    lands EXECUTABLE (a hook that is not is a hook the harness never runs),
    it is recorded in MANIFEST.json (an unrecorded file reads as hand-dropped
    to a consumer's own orphan detection), a hand-edit afterwards is a drift()
    finding, a destination collision across sources refuses like a checks/
    one, and `.claude/settings.json` is REFUSED as a destination -- that file
    carries each consumer's own base branch, and copying it would silently
    repoint the freshness guard at the wrong one."""
    import shutil, subprocess, tempfile

    tmp = pathlib.Path(tempfile.mkdtemp(prefix='precedent-adapters-'))
    cases = []
    try:
        uni, team, consumer = tmp / 'universal', tmp / 'team', tmp / 'consumer'
        for root, slug in ((uni, 'uni-fixture'), (team, 'team-fixture')):
            p = root / 'practices' / f'{slug}.md'
            p.parent.mkdir(parents=True, exist_ok=True)
            p.write_text(
                f'---\nslug: {slug}\ntitle: Fixture\ntier: on-demand\n'
                f'severity: default\napplies_to: ["**"]\noccasion: "x"\n'
                f'gates: []\nindex_clause: "x"\nchecked_by: null\ndefines: []\n'
                f'status: active\nsupersedes: []\noverrides: null\n'
                f'added: 2026-09-02\napproved_by: "harness, 2026-09-02"\n'
                f'source_practice_number: null\n---\n## Rule\nx\n\n'
                f'## Why\nx\n\n## Story\nx\n\n## Install\nx\n',
                encoding='utf-8')
            boot = root / 'bootstrap'
            boot.mkdir(parents=True, exist_ok=True)
            (boot / 'guard.sh').write_text('#!/bin/bash\necho v1\n', encoding='utf-8')
            os.chmod(boot / 'guard.sh', 0o755)

        def declare(root, adapters):
            (root / 'precedent.json').write_text(
                json.dumps({'format_version': 1, 'adapters': adapters}),
                encoding='utf-8')

        declare(uni, [{'from': 'bootstrap/guard.sh',
                       'to': '.claude/hooks/guard.sh'}])
        declare(team, [])
        consumer.mkdir()
        (consumer / 'precedent.json').write_text(json.dumps({
            'sources': [{'level': 'universal', 'name': 'precedent', 'path': str(uni)},
                        {'level': 'team', 'name': 'precedent-team-fixture',
                         'path': str(team)}]}), encoding='utf-8')

        # The fixture owns its HOME for the reason spelled out in
        # check_materialize_bridges_loader(): the resolver otherwise picks up
        # whatever individual source ~/.config/precedent names, and this
        # container's real one would then be declaring adapters into the
        # fixture consumer -- every verdict below would be about that source
        # instead (practices/fixture-owns-its-state.md).
        fixture_home = tmp / 'home'
        fixture_home.mkdir()
        env = {k: v for k, v in os.environ.items()
               if k != 'CLAUDE_CODE_REMOTE' and not k.startswith('PRECEDENT_')}
        env['HOME'] = str(fixture_home)
        tool = str(ROOT / 'tools' / 'precedent_materialize.py')

        def run():
            r = subprocess.run([sys.executable, tool, '--out', str(consumer),
                                '--repo', str(consumer)],
                               capture_output=True, text=True, env=env)
            return r.returncode, r.stdout + r.stderr

        installed = consumer / '.claude' / 'hooks' / 'guard.sh'
        rc, out = run()
        cases.append(('a declared harness adapter is installed at its declared '
                      'destination', rc == 0 and installed.is_file()))
        cases.append(('it lands EXECUTABLE -- a hook that is not is a hook the '
                      'harness silently never runs',
                      installed.is_file() and os.access(installed, os.X_OK)))
        # Every read below tolerates the file being absent: a regression in
        # the mechanism under test must report as named FAILING CASES, not as
        # a traceback that takes the whole harness run down before the later
        # refusal cases have even run (control-asserts-which-failure -- a
        # control proves a guard fires by what it SAYS, and a crash says
        # nothing about which of fifteen behaviours broke).
        mf = consumer / 'MANIFEST.json'
        manifest = (json.loads(mf.read_text(encoding='utf-8'))
                    if mf.is_file() else {})
        entry = [a for a in manifest.get('adapters', [])
                 if a.get('path') == '.claude/hooks/guard.sh']
        cases.append(('it is recorded in MANIFEST.json with its source and '
                      'hash, so it is a declared derived artifact rather than '
                      'a file a consumer reads as hand-dropped',
                      len(entry) == 1 and entry[0].get('source') == 'precedent'
                      and bool(entry[0].get('sha256_16'))))
        cases.append(('the fixture really owned its source set -- nothing '
                      'cloned an individual source into the fixture HOME',
                      not any(fixture_home.iterdir())))

        # --- a source that moves reaches the consumer on the next sync -----
        (uni / 'bootstrap' / 'guard.sh').write_text('#!/bin/bash\necho v2\n',
                                                    encoding='utf-8')
        rc, out = run()
        cases.append(('a change in the SOURCE reaches the consumer on the next '
                      'sync -- the whole point: no hand-copy step',
                      rc == 0 and installed.is_file()
                      and 'v2' in installed.read_text(encoding='utf-8')))
        cases.append(('and an ordinary update like that says nothing -- the '
                      'notice is for content this tree never recorded',
                      'REPLACED' not in out))

        # --- a hand-edit afterwards is drift, not silence ------------------
        installed.parent.mkdir(parents=True, exist_ok=True)
        installed.write_text('#!/bin/bash\necho hand edited\n', encoding='utf-8')
        sys.path.insert(0, str(ROOT / 'tools'))
        import precedent_resolve as _pr, precedent_materialize as _pm
        _home = os.environ.get('HOME')
        try:
            os.environ['HOME'] = str(fixture_home)
            srcs = _pr.load_config(str(consumer), None)
            found = _pm.drift(srcs, _pr.resolve(srcs), consumer)
        finally:
            if _home is not None:
                os.environ['HOME'] = _home
        cases.append(('a hand-edit to an installed adapter is reported by '
                      'drift() -- the audit half, which a mechanism that only '
                      'copies would still owe',
                      any('.claude/hooks/guard.sh differs' in x for x in found)))

        # --- adopting an unrecorded copy is loud ---------------------------
        rc, out = run()
        cases.append(('replacing content this tree never recorded as '
                      'materialized -- a hand-copy being adopted, or a local '
                      'edit reverted -- says so and names the file',
                      rc == 0 and 'REPLACED' in out
                      and '.claude/hooks/guard.sh' in out))

        # --- an adapter no source declares any more is reported, not deleted
        declare(uni, [])
        rc, out = run()
        cases.append(('an adapter no declared source publishes any more is '
                      'left in place and REPORTED -- `.claude/hooks/` is not '
                      "materialize()'s to empty, and the file may already be "
                      'wired into a settings.json this tool never reads',
                      rc == 0 and installed.is_file()
                      and 'no declared source publishes any more' in out))

        # --- refusals ------------------------------------------------------
        declare(uni, [{'from': 'bootstrap/guard.sh', 'to': '.claude/hooks/guard.sh'}])
        declare(team, [{'from': 'bootstrap/guard.sh', 'to': '.claude/hooks/guard.sh'}])
        rc, out = run()
        cases.append(('two sources installing to one destination refuses, the '
                      'same discipline a tools/checks/ filename collision gets',
                      rc == 1 and 'collision' in out))

        declare(team, [{'from': 'bootstrap/guard.sh', 'to': '.claude/settings.json'}])
        rc, out = run()
        cases.append(('.claude/settings.json is REFUSED as a destination -- it '
                      "carries each consumer's own base branch, and copying it "
                      'would silently repoint the freshness guard',
                      rc == 1 and 'does not travel' in out))

        declare(team, [{'from': 'bootstrap/guard.sh', 'to': '../escape.sh'}])
        rc, out = run()
        cases.append(('a destination walking out of the consuming repo with '
                      '".." refuses',
                      rc == 1 and 'walks above the consuming repo' in out))

        declare(team, [{'from': 'bootstrap/guard.sh',
                        'to': 'practices/guard.sh'}])
        rc, out = run()
        cases.append(("a destination inside materialize()'s own wiped "
                      'directories refuses -- the file would not survive its '
                      'own sync', rc == 1 and 'deletes and rewrites' in out))

        declare(team, [{'from': 'bootstrap/absent.sh', 'to': '.claude/hooks/absent.sh'}])
        rc, out = run()
        cases.append(('a declared adapter whose file is not in the source tree '
                      'WARNS and is skipped, never refuses -- the ordinary '
                      "cause is a stale clone of a repo the consumer does not "
                      'own',
                      rc == 0 and 'not in the source tree' in out
                      and not (consumer / '.claude' / 'hooks' / 'absent.sh').exists()))

        (team / 'precedent.json').write_text('{ not json', encoding='utf-8')
        rc, out = run()
        cases.append(("a source's unreadable precedent.json refuses rather "
                      'than silently reading as "publishes no adapters"',
                      rc == 1 and 'not readable JSON' in out))
    finally:
        shutil.rmtree(tmp, ignore_errors=True)

    bad = [c[0] for c in cases if not c[1]]
    check(f'precedent_materialize.py carries a source\'s harness adapters '
          f'({len(cases)} stated cases: installed executable and recorded in '
          f'the manifest, a source change reaching the consumer with no '
          f'hand-copy, a hand-edit reported by drift(), an unrecorded copy '
          f'adopted loudly and an ordinary update quietly, an undeclared one '
          f'reported rather than deleted, and five refusals -- destination '
          f'collision, settings.json, "..", a wiped directory, and an '
          f'unreadable source config)',
          not bad, '; '.join(bad))


def check_practice_ships_its_files():
    """practice: practice-carries-its-files -- a practice's `ships:` files
    reach every consumer, a publishing set is held to them at its own push,
    and a shipped test that reads a source-only tools/ file fails at home.

    THE INCIDENT (2026-09-26): create-word-doc's shipped test copies
    tools/create_word_doc.py, the materializer never delivered tools/
    scripts, and a consumer's deep check went red on a test nobody there
    could fix. Three mechanisms close it, and each has its own way to
    regress silently, so each is exercised in both directions here
    (practice: control-asserts-which-failure):

    * precedent_materialize.py delivers, records, drift-checks, honours a
      declared decline, and refuses the malformed and the colliding;
    * precedent_check.py's practice-carries-its-files fires in a source set
      on an undeclared dependency and on a declared file the set lacks, and
      is quiet once the declaration is right;
    * precedent_consumer_shape.py fails the test that reads a source-only
      file, passes it once the file is shipped, and leaves the source's own
      checkout untouched."""
    import shutil, tempfile

    tmp = pathlib.Path(tempfile.mkdtemp(prefix='precedent-ships-'))
    cases = []

    def practice(root, slug, ships=None, checked_by='null', body_link=''):
        p = root / 'practices' / f'{slug}.md'
        p.parent.mkdir(parents=True, exist_ok=True)
        ships_line = f'ships: {json.dumps(ships)}\n' if ships is not None else ''
        p.write_text(
            f'---\nslug: {slug}\ntitle: Fixture\ntier: on-demand\n'
            f'severity: default\napplies_to: ["**"]\noccasion: "x"\n'
            f'gates: []\nindex_clause: "x"\nchecked_by: {checked_by}\n'
            f'{ships_line}defines: []\nstatus: active\nsupersedes: []\n'
            f'overrides: null\nadded: 2026-09-26\n'
            f'approved_by: "harness, 2026-09-26"\n---\n## Rule\nx{body_link}\n\n'
            f'## Why\nx\n\n## Story\nx\n\n## Install\nx\n', encoding='utf-8')

    try:
        # --- delivery ------------------------------------------------------
        uni, team, consumer = tmp / 'universal', tmp / 'team', tmp / 'consumer'
        practice(uni, 'uni-fixture')
        practice(team, 'team-fixture', ships=['tools/helper.py'],
                 body_link=' Run [the helper](../tools/helper.py).')
        (team / 'tools').mkdir(parents=True)
        helper = team / 'tools' / 'helper.py'
        helper.write_text('print("v1")\n', encoding='utf-8')
        os.chmod(helper, 0o755)
        consumer.mkdir()

        def config(extra=None):
            d = {'sources': [
                {'level': 'universal', 'name': 'precedent', 'path': str(uni)},
                {'level': 'team', 'name': 'precedent-team-fixture',
                 'path': str(team)}]}
            d.update(extra or {})
            (consumer / 'precedent.json').write_text(json.dumps(d),
                                                     encoding='utf-8')
        config()
        fixture_home = tmp / 'home'
        fixture_home.mkdir()
        env = {k: v for k, v in os.environ.items()
               if k != 'CLAUDE_CODE_REMOTE' and not k.startswith('PRECEDENT_')}
        env['HOME'] = str(fixture_home)
        tool = str(ROOT / 'tools' / 'precedent_materialize.py')

        def run():
            r = subprocess.run([sys.executable, tool, '--out', str(consumer),
                                '--repo', str(consumer)],
                               capture_output=True, text=True, env=env)
            return r.returncode, r.stdout + r.stderr

        def manifest():
            mf = consumer / 'MANIFEST.json'
            return json.loads(mf.read_text(encoding='utf-8')) if mf.is_file() else {}

        def drift():
            sys.path.insert(0, str(ROOT / 'tools'))
            import precedent_resolve as _pr, precedent_materialize as _pm
            # The fixture owns the whole environment the resolver reads, not
            # only HOME: a PRECEDENT_* variable left in this process would
            # hand it this container's real individual source.
            saved = {k: v for k, v in os.environ.items()
                     if k == 'HOME' or k.startswith('PRECEDENT_')}
            try:
                for k in saved:
                    del os.environ[k]
                os.environ['HOME'] = str(fixture_home)
                # Named explicitly: the resolver fixed its default user
                # config path from the real HOME when it was first imported.
                user_cfg = tmp / 'user-config.json'
                user_cfg.write_text('{}', encoding='utf-8')
                srcs = _pr.load_config(str(consumer), str(user_cfg))
                return _pm.drift(srcs, _pr.resolve(srcs), consumer)
            finally:
                os.environ.pop('HOME', None)
                os.environ.update(saved)

        delivered = consumer / 'tools' / 'helper.py'

        # Every read and write of the delivered file tolerates its absence:
        # a regression in delivery must show up as named failing cases, not
        # a traceback (practice: control-asserts-which-failure).
        def text_of(path):
            return path.read_text(encoding='utf-8') if path.is_file() else ''

        def put(path, text):
            path.parent.mkdir(parents=True, exist_ok=True)
            path.write_text(text, encoding='utf-8')
        rc, out = run()
        cases.append(('a declared `ships:` file is delivered to the same path '
                      'in the consumer', rc == 0 and delivered.is_file(), out[-300:]))
        cases.append(('it keeps its executable bit',
                      delivered.is_file() and os.access(delivered, os.X_OK)))
        rows = [f for f in manifest().get('ships', [])
                if f.get('path') == 'tools/helper.py']
        cases.append(('it is recorded in MANIFEST.json with the practice and '
                      'source that ship it',
                      len(rows) == 1 and rows[0].get('practice') == 'team-fixture'
                      and rows[0].get('source') == 'precedent-team-fixture'))
        linked = consumer / 'practices' / 'team-fixture.md'
        cases.append(("the practice's relative link to the file it ships stays "
                      'relative -- the file is right there',
                      '](../tools/helper.py)' in text_of(linked)))
        cases.append(('a fresh sync reports no drift', drift() == []))

        helper.write_text('print("v2")\n', encoding='utf-8')
        rc, out = run()
        cases.append(("a change in the source reaches the consumer on the next "
                      'sync, quietly',
                      rc == 0 and 'v2' in text_of(delivered)
                      and 'REPLACED' not in out))

        put(delivered, 'print("hand edited")\n')
        cases.append(('a hand-edit to a delivered file is drift',
                      any('tools/helper.py differs' in x for x in drift())))
        rc, out = run()
        cases.append(('replacing an unrecorded copy says so, and names the way '
                      'to keep one', rc == 0 and 'REPLACED' in out
                      and 'tools/helper.py' in out and 'declined_ships' in out))

        # --- decline --------------------------------------------------------
        config({'declined_ships': {'tools/helper.py': 'we have our own'}})
        put(delivered, 'print("ours")\n')
        rc, out = run()
        declined = manifest().get('declined_ships', [])
        cases.append(('a declined file is left alone and the decline is '
                      'recorded with its reason',
                      rc == 0 and 'ours' in text_of(delivered)
                      and declined == [{'path': 'tools/helper.py',
                                        'slug': 'team-fixture',
                                        'reason': 'we have our own'}]))
        cases.append(('a declined file is not drift', drift() == []))
        config({'declined_ships': {'tools/helper.py': ''}})
        rc, out = run()
        cases.append(('a decline without a reason refuses',
                      rc == 1 and 'non-empty reason' in out))
        config({'declined_ships': {'tools/nothing.py': 'stale'}})
        rc, out = run()
        cases.append(('a decline naming nothing any practice ships warns as '
                      'stale', rc == 0 and 'the decline is stale' in out))
        config()
        run()

        # --- no longer shipped: reported, never deleted ---------------------
        practice(team, 'team-fixture', ships=[])
        rc, out = run()
        cases.append(('a file no practice ships any more is reported and left '
                      'in place', rc == 0 and delivered.is_file()
                      and 'no practice in force here ships any more' in out))
        cases.append(('a consumer that ships nothing carries no `ships` key '
                      'in its manifest (no churn for every other consumer)',
                      'ships' not in manifest()))

        # --- refusals -------------------------------------------------------
        practice(team, 'team-fixture', ships=['tools/helper.py'])
        practice(uni, 'uni-fixture', ships=['tools/helper.py'])
        (uni / 'tools').mkdir(exist_ok=True)
        (uni / 'tools' / 'helper.py').write_text('x\n', encoding='utf-8')
        rc, out = run()
        cases.append(('two sources shipping one destination refuses',
                      rc == 1 and 'destination collision' in out))
        practice(uni, 'uni-fixture')
        for bad, words in ((['tools/precedent_check.py'], 'is an engine file'),
                           (['tools/*.py'], 'is a glob'),
                           (['../escape.py'], 'walks above the repository'),
                           (['tools/checks/check_x.py'], 'travel already'),
                           ('"tools/helper.py"', 'must be a JSON list')):
            if isinstance(bad, str):
                p = team / 'practices' / 'team-fixture.md'
                practice(team, 'team-fixture', ships=[])
                p.write_text(p.read_text(encoding='utf-8').replace(
                    'ships: []', f'ships: {bad}'), encoding='utf-8')
            else:
                practice(team, 'team-fixture', ships=bad)
            rc, out = run()
            cases.append((f'`ships: {bad}` refuses ({words})',
                          rc == 1 and words in out, out[-200:]))
        practice(team, 'team-fixture', ships=['tools/absent.py'])
        rc, out = run()
        cases.append(('a declared file missing from its source warns and is '
                      'skipped', rc == 0 and 'NOT delivered' in out
                      and not (consumer / 'tools' / 'absent.py').exists()))
        cases.append(('the fixture owned its source set',
                      not any(fixture_home.iterdir())))

        # --- the source-side check -----------------------------------------
        src = tmp / 'set'
        src.mkdir()
        shutil.copytree(ROOT / 'tools', src / 'tools',
                        ignore=shutil.ignore_patterns('__pycache__', 'checks'))
        (src / 'tools' / 'ENGINE_MANIFEST.json').write_text(
            json.dumps({'kind': 'source', 'files': []}), encoding='utf-8')
        (src / 'tools' / 'own_tool.py').write_text('print(1)\n', encoding='utf-8')
        checks_dir = src / 'tools' / 'checks'
        (checks_dir / 'tests').mkdir(parents=True)
        (checks_dir / 'check_x.py').write_text('import sys\nsys.exit(0)\n',
                                               encoding='utf-8')
        (checks_dir / 'tests' / 'test_x.sh').write_text(
            '#!/bin/bash\nset -e\ncd "$(dirname "$0")/../../.."\n'
            'SET_ROOT="$(pwd)"\n'
            'if [ -f "$SET_ROOT/tools/probed.py" ]; then echo p; fi\n'
            'cp "$SET_ROOT/tools/own_tool.py" "$(mktemp -d)/"\n'
            'git -C "$SET_ROOT" status --porcelain -- tools | '
            '(! grep -q .)\necho ok\n', encoding='utf-8')
        practice(src, 'x-practice', checked_by='"tools/checks/check_x.py"')
        genv = dict(env, GIT_AUTHOR_NAME='T', GIT_AUTHOR_EMAIL='t@example.com',
                    GIT_COMMITTER_NAME='T', GIT_COMMITTER_EMAIL='t@example.com',
                    GIT_CONFIG_GLOBAL=str(tmp / 'gitconfig'),
                    GIT_CONFIG_NOSYSTEM='1')
        (tmp / 'gitconfig').write_text('', encoding='utf-8')
        for args in (['init', '-q'], ['add', '-A'], ['commit', '-qm', 'base']):
            subprocess.run(['git', '-C', str(src), *args], env=genv,
                           capture_output=True)

        def pcheck():
            r = subprocess.run([sys.executable, str(src / 'tools' / 'precedent_check.py'),
                                '--only', 'practice-carries-its-files'],
                               capture_output=True, text=True, cwd=str(src), env=genv)
            return r.returncode, r.stdout + r.stderr

        rc, out = pcheck()
        cases.append(('the check fires in a source set on a shipped test that '
                      'reads an undeclared source-only tools/ file, naming it',
                      rc == 1 and 'test_x.sh:6' in out
                      and '`tools/own_tool.py`, which is in this repository'
                      ' and reaches no consumer' in out, out[-400:]))
        cases.append(('a path the test probes first is not reported',
                      'tools/probed.py' not in out))
        practice(src, 'x-practice', checked_by='"tools/checks/check_x.py"',
                 ships=['tools/own_tool.py'])
        rc, out = pcheck()
        cases.append(('declaring it in `ships:` clears the check',
                      rc == 0 and '1 passed' in out, out[-300:]))
        practice(src, 'x-practice', checked_by='"tools/checks/check_x.py"',
                 ships=['tools/own_tool.py', 'tools/left_behind.py'])
        rc, out = pcheck()
        cases.append(('a `ships:` file the set does not carry fires -- the '
                      'moved-without-its-script case',
                      rc == 1 and 'ships `tools/left_behind.py`, which is not '
                      'in this repository' in out, out[-300:]))
        practice(src, 'x-practice', checked_by='"tools/checks/check_gone.py"',
                 ships=['tools/own_tool.py'])
        rc, out = pcheck()
        cases.append(('a checked_by script the set does not carry fires',
                      rc == 1 and 'checked_by names `tools/checks/check_gone.py`'
                      in out, out[-300:]))
        practice(src, 'x-practice', checked_by='"tools/checks/check_x.py"',
                 ships=['tools/own_tool.py'])

        # --- the consumer-shaped run -----------------------------------------
        shape = str(ROOT / 'tools' / 'precedent_consumer_shape.py')

        def shape_run():
            r = subprocess.run([sys.executable, shape, '--repo', str(src)],
                               capture_output=True, text=True, env=genv)
            return r.returncode, r.stdout + r.stderr

        rc, out = shape_run()
        cases.append(('with the file shipped, the consumer-shaped run passes, '
                      'and a git status in the copy is as clean as at home',
                      rc == 0 and 'all 1 passed' in out, out[-400:]))
        practice(src, 'x-practice', checked_by='"tools/checks/check_x.py"')
        rc, out = shape_run()
        cases.append(('undeclared, the consumer-shaped run fails the test and '
                      'lists the file the copy lacks',
                      rc == 1 and 'FAILED: test_x.sh' in out
                      and any('no consumer receives:' in l
                              and 'tools/own_tool.py' in l.split()
                              for l in out.splitlines()),
                      out[-400:]))
        cases.append(("the source's own checkout is untouched by the run",
                      (src / 'tools' / 'own_tool.py').is_file()
                      and subprocess.run(['git', '-C', str(src), 'status',
                                          '--porcelain', '-uno', '--', 'tools'],
                                         capture_output=True, text=True,
                                         env=genv).stdout == ''))
    finally:
        shutil.rmtree(tmp, ignore_errors=True)

    bad = [(c[0], c[2] if len(c) > 2 else '') for c in cases if not c[1]]
    check(f'a practice\'s `ships:` files travel, are held at the source, and '
          f'a home-only dependency fails at home ({len(cases)} stated cases)',
          not bad, '; '.join(f"{n}{' (' + d + ')' if d else ''}" for n, d in bad))


def check_show_flags_unreachable_materialized_source():
    """practices/verify-postcondition.md, applied to the READ side of the
    gap practices/session-bootstrap.md's Story records on the write side.
    A materialized practices/<slug>.md (tools/precedent_materialize.py's
    output, in a consumer repo resolving universal/team/individual/
    repo-local together) is whatever was on disk at the last successful
    materialize() run -- precedent_show.py reading it back proves nothing
    about whether the source that produced it is reachable THIS session.
    Before this, a session could get a clean, confident-looking Rule
    printout from a source that had silently dropped off, with nothing to
    tell that apart from a source genuinely still live -- exactly the
    false-confidence case the self-heal fix (tools/precedent_resolve.py)
    makes MORE likely to occur unnoticed, not less: a source can now fail
    to resolve in one particular session while a materialized tree from an
    earlier, working session still reads back clean.

    Six stated cases: a real individual source materialized and read while
    reachable (silent, no note); the same slug read again after that
    source's directory is removed (the note fires, naming the level and
    the materialize timestamp); a universal-sourced slug in the SAME
    materialized tree, whose source never leaves (stays silent throughout
    -- the check is source-specific, not a blanket flag on every slug once
    anything is missing); restoring the source and re-reading (silent
    again -- not sticky, re-checked every call); a plain SOURCE repo (this
    one) with no MANIFEST.json at all (never adds a note, regardless of
    slug); and multiple slugs in one call sourced differently (each gets
    its own independent verdict, matching precedent_show.py's own
    per-slug concatenation).

    EXTENDED 2026-09-06 (closed and pruned from TODO.md; was the `gate-and-paths-unreachable-source` item) to cover
    precedent_gate.py and precedent_paths.py too -- both read
    practices/*.md directly, the same way precedent_show.py itself used
    to, so the note above never reached a practice loaded through the
    gate-triggered or path-triggered channel. Closed by having both
    modules `import precedent_show as ps` and call its two helpers
    directly, NOT by a subprocess call to precedent_show.py (would mean
    re-parsing its own "### slug\\n<body>" stdout format back into
    structured data purely to recover a note this file can already print
    itself) and NOT by a second, copy-pasted implementation
    (engine-plus-host-shims: one mechanism, shared by import, the same
    discipline all three files already use for split_practices.py). Two
    more stated cases below reuse the same indiv/uni fixture with one
    added practice (gated + a narrow applies_to, so both channels can
    actually reach it), checked reachable and unreachable exactly like
    the show() cases above."""
    import shutil, subprocess, tempfile

    tmp = pathlib.Path(tempfile.mkdtemp(prefix='precedent-show-reachability-'))
    cases = []
    try:
        def write_practice(path, slug, rule, applies_to='["**"]', gates='[]'):
            path.parent.mkdir(parents=True, exist_ok=True)
            path.write_text(
                f'---\nslug: {slug}\ntitle: Fixture\ntier: on-demand\n'
                f'severity: default\napplies_to: {applies_to}\noccasion: "testing"\n'
                f'gates: {gates}\nindex_clause: "a harness fixture"\nchecked_by: null\n'
                f'defines: []\nstatus: active\nsupersedes: []\noverrides: null\n'
                f'added: null\napproved_by: "harness"\n---\n\n## Rule\n{rule}\n\n'
                f'## Detail\n\n## Why\n\n## Story\n\n## Install\n', encoding='utf-8')

        indiv = tmp / 'indiv-source'
        write_practice(indiv / 'practices' / 'show-fixture-individual.md',
                       'show-fixture-individual', 'The individual fixture Rule.')
        # Gated + narrow applies_to, so the SAME materialized fixture also
        # exercises precedent_gate.py and precedent_paths.py below -- both
        # read practices/*.md directly, same as precedent_show.py, and
        # the `gate-and-paths-unreachable-source` item (closed, pruned from TODO.md) named them as needing the identical reachability note.
        write_practice(indiv / 'practices' / 'show-fixture-individual-routed.md',
                       'show-fixture-individual-routed', 'The routed individual fixture Rule.',
                       applies_to='["fixture-only/*.md"]', gates='["push"]')
        uni = tmp / 'uni-source'
        write_practice(uni / 'practices' / 'show-fixture-universal.md',
                       'show-fixture-universal', 'The universal fixture Rule.')

        consumer = tmp / 'consumer'
        (consumer).mkdir()
        (consumer / 'precedent.json').write_text(json.dumps({
            'sources': [{'level': 'universal', 'name': 'precedent', 'path': str(uni)}]
        }), encoding='utf-8')
        user_config = tmp / 'user-config.json'
        user_config.write_text(json.dumps({
            'individual': {'name': 'precedent-individual', 'path': str(indiv)},
        }), encoding='utf-8')

        materialize_tool = str(ROOT / 'tools' / 'precedent_materialize.py')
        show_tool = str(ROOT / 'tools' / 'precedent_show.py')
        gate_tool = str(ROOT / 'tools' / 'precedent_gate.py')
        paths_tool = str(ROOT / 'tools' / 'precedent_paths.py')

        def materialize():
            r = subprocess.run([sys.executable, materialize_tool, '--out', str(consumer),
                               '--repo', str(consumer), '--user-config', str(user_config)],
                               capture_output=True, text=True)
            return r.returncode, r.stdout + r.stderr

        def show(*slugs):
            r = subprocess.run([sys.executable, show_tool, *slugs, '--repo', str(consumer)],
                               capture_output=True, text=True)
            return r.returncode, r.stdout + r.stderr

        def gate(name):
            r = subprocess.run([sys.executable, gate_tool, name, '--repo', str(consumer)],
                               capture_output=True, text=True)
            return r.returncode, r.stdout + r.stderr

        def paths(*p):
            r = subprocess.run([sys.executable, paths_tool, *p, '--repo', str(consumer)],
                               capture_output=True, text=True)
            return r.returncode, r.stdout + r.stderr

        rc, out = materialize()
        cases.append(('the two-source fixture materializes cleanly', rc == 0, out))

        rc, out = show('show-fixture-individual')
        cases.append(('reachable: an individual-sourced slug shows no note',
                      rc == 0 and 'NOT reachable' not in out
                      and 'The individual fixture Rule.' in out, out))

        rc, out = show('show-fixture-universal')
        cases.append(('a universal-sourced slug in the same materialized tree '
                      'shows no note either', rc == 0 and 'NOT reachable' not in out, out))

        rc, out = gate('push')
        cases.append(('reachable: precedent_gate.py shows no note for the '
                      'gated individual-sourced slug either',
                      rc == 0 and 'NOT reachable' not in out
                      and 'show-fixture-individual-routed' in out, out))

        rc, out = paths('fixture-only/x.md')
        cases.append(('reachable: precedent_paths.py shows no note for the '
                      'same slug matched by path',
                      rc == 0 and 'NOT reachable' not in out
                      and 'show-fixture-individual-routed' in out, out))

        shutil.move(str(indiv), str(tmp / 'indiv-source-hidden'))
        rc, out = show('show-fixture-individual')
        cases.append(('unreachable: the same individual-sourced slug now carries '
                      'a note naming its level',
                      rc == 0 and 'NOT reachable this session' in out
                      and '(source: individual,' in out, out))

        rc, out = show('show-fixture-universal')
        cases.append(('the universal-sourced slug is unaffected by the '
                      'individual source going missing -- the check is per-slug, '
                      'not a blanket flag', rc == 0 and 'NOT reachable' not in out, out))

        rc, out = gate('push')
        cases.append(('unreachable: precedent_gate.py now carries the note for '
                      'the gated individual-sourced slug (the `gate-and-paths-unreachable-source` item, closed and pruned from TODO.md)',
                      rc == 0 and 'NOT reachable this session' in out
                      and '(source: individual,' in out, out))

        rc, out = paths('fixture-only/x.md')
        cases.append(('unreachable: precedent_paths.py now carries the note for '
                      'the same slug matched by path (the `gate-and-paths-unreachable-source` item, closed and pruned from TODO.md)',
                      rc == 0 and 'NOT reachable this session' in out
                      and '(source: individual,' in out, out))

        rc, out = show('show-fixture-individual', 'show-fixture-universal')
        cases.append(('mixed in one call: each slug gets its own independent '
                      'verdict', rc == 0 and out.count('NOT reachable') == 1
                      and '### show-fixture-individual' in out
                      and '### show-fixture-universal' in out, out))

        shutil.move(str(tmp / 'indiv-source-hidden'), str(indiv))
        rc, out = show('show-fixture-individual')
        cases.append(('restored: the note is re-checked every call, not sticky',
                      rc == 0 and 'NOT reachable' not in out, out))

        # A plain SOURCE repo (no MANIFEST.json at all) never adds a note,
        # for any slug -- this repo's own tree is exactly that fixture.
        r = subprocess.run([sys.executable, show_tool, 'environment-gotchas'],
                           capture_output=True, text=True, cwd=str(ROOT))
        cases.append(('a plain source repo with no MANIFEST.json never adds a note',
                      r.returncode == 0 and 'NOT reachable' not in r.stdout, r.stdout + r.stderr))
    finally:
        shutil.rmtree(tmp, ignore_errors=True)

    bad = [(c[0], c[2]) for c in cases if not c[1]]
    check(f'precedent_show.py/precedent_gate.py/precedent_paths.py all flag a '
          f'materialized slug whose declared source is not reachable this session '
          f'({len(cases)} stated cases)',
          not bad,
          '; '.join(f"{n} -- {d[:800]}" for n, d in bad))


def check_sync_refuses_to_lose_a_recorded_practice():
    """A sync will not silently drop a rule the repository already published.

    The incident, 2026-09-07: promoting two practices out of a shared set into
    the universal catalogue left every consumer pinned before the promotion
    with them in NEITHER source, so its next sync deleted both. `--check`
    named them; a real sync rmtree's practices/ and says nothing.

    THE BASELINE IS THE COMMITTED MANIFEST, and that is the whole design. A
    first attempt compared the working tree against the plan and had to be
    reverted -- it fired on a public repo withholding by design, on a sync
    already carrying --allow-missing-sources, and on a fixture re-syncing
    after its sources changed. "The tree differs from the plan" is true
    constantly. "This repository committed a catalogue containing rule X and
    X is about to vanish" is narrow enough to refuse on. The four cases below
    are the four that distinction has to get right.
    """
    import tempfile, shutil
    sync_tool = str(ROOT / 'tools' / 'precedent_sync_views.py')

    def _repo(tmp, extra_source=True):
        repo, team = tmp / 'c', tmp / 'precedent-team-x'
        (repo / 'precedent' / 'universal').mkdir(parents=True)
        shutil.copytree(PRACTICES_DIR, repo / 'precedent' / 'universal' / 'practices')
        (team / 'practices').mkdir(parents=True)
        (team / 'practices' / 'team-x-rule.md').write_text(
            '---\nslug: team-x-rule\ntitle: The rig is used\n'
            'tier: on-demand\nseverity: default\napplies_to: ["**"]\n'
            'occasion: "changing firmware"\n'
            'index_clause: "use the rig"\nstatus: active\n---\n'
            '## Rule\nUse the rig.\n\n## Story\nIt drifted.\n', encoding='utf-8')
        # A SECOND practice, so removing the first does not empty the source.
        # An existing guard already refuses a source that went completely
        # empty ("a sync would quietly drop that whole catalogue"), and the
        # first version of this fixture tripped that one instead of the one
        # under test -- a fixture proving the wrong thing passes just as
        # confidently as one proving the right thing.
        (team / 'practices' / 'team-x-keeper.md').write_text(
            '---\nslug: team-x-keeper\ntitle: The bench is logged\n'
            'tier: on-demand\nseverity: default\napplies_to: ["**"]\n'
            'occasion: "logging bench time"\n'
            'index_clause: "log the bench"\nstatus: active\n---\n'
            '## Rule\nLog it.\n\n## Story\nIt was not logged.\n',
            encoding='utf-8')
        (repo / 'AGENTS.md').write_text(
            f'# C\n\n{bv.BEGIN_MARKER} -->\n{bv.END_MARKER} -->\n', encoding='utf-8')
        srcs = [{'level': 'universal', 'name': 'precedent',
                 'path': 'precedent/universal'}]
        if extra_source:
            srcs.append({'level': 'team', 'name': 'precedent-team-x',
                         'path': str(team)})
        (repo / 'precedent.json').write_text(json.dumps({
            'format_version': 1, 'base_branch': 'main',
            'visibility': 'private', 'sources': srcs}), encoding='utf-8')
        user = tmp / 'u.json'
        user.write_text(json.dumps({'format_version': 1}), encoding='utf-8')
        for c in (['init', '-q', '-b', 'main'],
                  ['config', 'user.email', 'harness@example.com'],
                  ['config', 'user.name', 'Harness']):
            subprocess.run(['git', '-C', str(repo)] + c, capture_output=True)
        return repo, team, user

    def _sync(repo, user, *flags):
        return subprocess.run(
            [sys.executable, sync_tool, '--repo', str(repo),
             '--user-config', str(user)] + list(flags),
            capture_output=True, text=True)

    def _commit(repo):
        subprocess.run(['git', '-C', str(repo), 'add', '-A'], capture_output=True)
        subprocess.run(['git', '-C', str(repo), 'commit', '-qm', 'catalogue'],
                       capture_output=True)

    cases = []
    with tempfile.TemporaryDirectory() as td:
        tmp = pathlib.Path(td)

        # 1. NO COMMITTED MANIFEST -- a fresh install has nothing to lose.
        repo, team, user = _repo(tmp)
        r = _sync(repo, user)
        cases.append(('a repo with no committed manifest syncs freely',
                      r.returncode == 0))

        # 2. The real case: publish a catalogue, then the source stops
        #    producing the rule while STILL being declared.
        _commit(repo)
        (team / 'practices' / 'team-x-rule.md').unlink()
        r = _sync(repo, user)
        cases.append(('a recorded practice vanishing from a still-declared '
                      'source REFUSES', r.returncode != 0))
        cases.append(('and it names the slug and its source',
                      'team-x-rule' in r.stderr and 'precedent-team-x' in r.stderr))
        cases.append(('and the practice file survives the refusal',
                      (repo / 'practices' / 'team-x-rule.md').exists()))

        # 3. --allow-removals is the deliberate override.
        r = _sync(repo, user, '--allow-removals')
        cases.append(('--allow-removals permits it',
                      r.returncode == 0
                      and not (repo / 'practices' / 'team-x-rule.md').exists()))

        # 4. DROPPING the source: refused too, since 2026-09-14. This used
        #    to assert returncode == 0 on the reasoning that a drop is a
        #    decision somebody just made -- and the matching is by NAME, so
        #    a RENAME is indistinguishable from a drop here and would have
        #    been written under the same reassuring message. Case 5 is the
        #    one that could not be told apart; this one is its twin.
        repo2, team2, user2 = _repo(tmp / 'b')
        _sync(repo2, user2); _commit(repo2)
        cfg = json.loads((repo2 / 'precedent.json').read_text())
        cfg['sources'] = [s for s in cfg['sources'] if s['level'] != 'team']
        (repo2 / 'precedent.json').write_text(json.dumps(cfg), encoding='utf-8')
        r = _sync(repo2, user2)
        cases.append(('an undeclared recorded source REFUSES rather than '
                      'deleting', r.returncode != 0))
        # practice: control-asserts-which-failure -- a non-zero exit proves
        # nothing about WHICH guard fired, and the fixture above can trip at
        # least two others. Assert the three states this message names.
        cases.append(('and the refusal names all three states it cannot '
                      'tell apart',
                      all(w in r.stderr for w in ('DROPPED', 'RENAMED',
                                                  'RETIRED'))))
        cases.append(('and it says which practices are at stake',
                      'team-x-rule' in r.stderr))
        cases.append(('and the practice files survive the refusal',
                      (repo2 / 'practices' / 'team-x-rule.md').exists()))
        r = _sync(repo2, user2, '--allow-removals')
        cases.append(('--allow-removals proceeds once you know which it is',
                      r.returncode == 0
                      and not (repo2 / 'practices' / 'team-x-rule.md').exists()))

        # 5. THE INCIDENT ITSELF, and it takes two changes to reproduce.
        #    A rename ALONE deletes nothing: the source still resolves and
        #    still produces the same slugs, so nothing is lost and the guard
        #    has no occasion to fire -- asserted below, because a fixture
        #    that cannot tell a safe rename from a dangerous one would make
        #    this whole case unfalsifiable. The damage needs a rename PLUS a
        #    practice that really does go: then the slug is lost, the
        #    recorded source name matches nothing, and before 2026-09-14
        #    that was written and reported as the person having dropped the
        #    source on purpose. The 2026-09-14 removals were correct only
        #    because the four practices were retired upstream as well.
        repo3, team3, user3 = _repo(tmp / 'c2')
        _sync(repo3, user3); _commit(repo3)
        cfg = json.loads((repo3 / 'precedent.json').read_text())
        for s in cfg['sources']:
            if s['level'] == 'team':
                s['name'] = 'precedent-team-x-renamed'
        (repo3 / 'precedent.json').write_text(json.dumps(cfg), encoding='utf-8')
        r = _sync(repo3, user3)
        cases.append(('a rename ALONE loses nothing and is not refused',
                      r.returncode == 0
                      and (repo3 / 'practices' / 'team-x-rule.md').exists()))
        _commit(repo3)
        (team3 / 'practices' / 'team-x-rule.md').unlink()
        r = _sync(repo3, user3)
        cases.append(('a rename PLUS a real removal refuses instead of '
                      'deleting under a dropped-source message',
                      r.returncode != 0))
        cases.append(('and the practice survives that refusal',
                      (repo3 / 'practices' / 'team-x-rule.md').exists()))

    failed = [n for n, ok in cases if not ok]
    check(f'a sync refuses to lose a practice the committed manifest records '
          f'({len(cases)} stated cases)', not failed, '; '.join(failed))


def check_doc_lifecycle_fires_and_clears():
    """tools/doc_lifecycle.py -- the document status header, checked.

    checkable-gets-checked requires a firing test, not merely a check that
    passes: plant each violation, prove it fails, remove it, prove the
    unplanted tree passes. Every case runs against a THROWAWAY tree, never
    against spec/ -- a check whose test mutates the repo it audits cannot be
    run twice.

    The `Last updated:` case is the one worth reading. A first version of
    the detector was `'Last updated:' in text`, and it fired on
    spec/DOCUMENT_LIFECYCLE.md -- the document that SPECIFIES this rule and
    necessarily quotes the string it forbids, five times. A check that
    fails the file explaining it teaches the first reader that the checker
    is broken, so the two cases below pin the distinction: a real HTML
    comment fails, the same text inside a code span does not.
    """
    import tempfile
    sys.path.insert(0, str(ROOT / 'tools'))
    import doc_lifecycle as dl

    GOOD = ('---\n'
            'title:         A Reference\n'
            'kind:          reference\n'
            'status:        current\n'
            'opened:        2026-09-07\n'
            'closed:        null\n'
            'superseded_by: null\n'
            'supersedes:    []\n'
            'audience:      session\n'
            'summary:       What the thing is.\n'
            '---\n\n# A Reference\n\nBody.\n')

    def _run(text, extra=None):
        """-> (findings, unstamped, stamped) for a one-file throwaway tree."""
        with tempfile.TemporaryDirectory() as td:
            root = pathlib.Path(td)
            (root / 'spec').mkdir()
            (root / 'spec' / 'D.md').write_text(text, encoding='utf-8')
            for name, body in (extra or {}).items():
                (root / 'spec' / name).write_text(body, encoding='utf-8')
            return dl.scan(root=root)

    def _fires(name, text, needle, extra=None):
        f, _, _ = _run(text, extra)
        return (name, bool(f) and any(needle in x for x in f))

    cases = [
        # The unplanted control comes FIRST: a test suite where every case
        # is a planted failure cannot tell a working check from one that
        # returns a finding for everything.
        ('the unplanted document passes', not _run(GOOD)[0]),
        ('and it counts as stamped', _run(GOOD)[2] == 1),

        _fires('an illegal status for the kind',
               GOOD.replace('status:        current', 'status:        open'),
               'is not legal for kind'),
        _fires('an unknown kind',
               GOOD.replace('kind:          reference', 'kind:          memo'),
               'is not one of'),
        _fires('a title that disagrees with the first heading',
               GOOD.replace('# A Reference', '# Something Else'),
               '!= first heading'),
        _fires('a missing required field',
               GOOD.replace('supersedes:    []\n', ''),
               'missing required field'),
        _fires('an unknown audience',
               GOOD.replace('audience:      session', 'audience:      everyone'),
               'audience'),
        _fires('an opened date that is not YYYY-MM-DD',
               GOOD.replace('opened:        2026-09-07', 'opened:        Sept 7'),
               'is not YYYY-MM-DD'),
        _fires('status closed with no closed date',
               GOOD.replace('kind:          reference', 'kind:          brief')
                   .replace('status:        current', 'status:        closed'),
               'no `closed:` date'),
        _fires('a closed date on a document that is not closed',
               GOOD.replace('closed:        null', 'closed:        2026-09-07'),
               'but status is'),
        _fires('status superseded with no successor',
               GOOD.replace('status:        current', 'status:        superseded'),
               'no `superseded_by:`'),
        _fires('a superseded_by that does not resolve',
               GOOD.replace('status:        current', 'status:        superseded')
                   .replace('superseded_by: null', 'superseded_by: spec/GONE.md'),
               'does not exist'),
        _fires('a summary that does not end in a period',
               GOOD.replace('summary:       What the thing is.',
                            'summary:       What the thing is'),
               'does not end in a period'),
        _fires('a real `Last updated:` comment on a reference',
               GOOD.replace('\n# A Reference',
                            '\n<!-- Last updated: 2026-09-07 -->\n\n# A Reference'),
               'Last updated'),
    ]

    # The false-positive controls: the rule's own text must not trip it.
    quoted = GOOD.replace('Body.',
                          'A file may not carry `<!-- Last updated: x -->`.')
    cases.append(('the same string inside a code span does NOT fire',
                  not _run(quoted)[0]))
    fenced = GOOD.replace('Body.', '```\n<!-- Last updated: x -->\n```')
    cases.append(('nor inside a fenced block', not _run(fenced)[0]))
    brief = (GOOD.replace('kind:          reference', 'kind:          brief')
                 .replace('status:        current', 'status:        open')
                 .replace('\n# A Reference',
                          '\n<!-- Last updated: 2026-09-07 -->\n\n# A Reference'))
    cases.append(('and a `brief`, whose subject IS the date, may carry one',
                  not _run(brief)[0]))

    # An unstamped file is reported but is not a finding, while the backfill
    # is in progress. Both halves matter: reported, and not fatal.
    f, un, st = _run(GOOD, extra={'U.md': '# Unstamped\n\nNo frontmatter.\n'})
    cases.append(('an unstamped document is reported', un == ['spec/U.md']))
    cases.append(('and is not itself a finding, pre-phase-2', not f))

    failed = [n for n, ok in cases if not ok]
    check(f'the document lifecycle check fires on each planted violation and '
          f'clears the unplanted tree ({len(cases)} stated cases)',
          not failed, '; '.join(failed))


def check_commit_identity_derives_declared_timezone():
    """The declared timezone reaches the SESSION, not just the refusal message.

    The pre-commit backstop refuses a commit whose offset contradicts a
    declared timezone, and tells the person to rerun under `TZ=...`. Correct,
    and on its own it is a chore with no end: a hook cannot export TZ into the
    shells a session runs later, so the remedy gets retyped on every commit
    forever. 2026-09-07 the person running such a session said so plainly --
    "I'd rather a permanent fix than my having to do that manually."

    So the hook derives `env.TZ` into .claude/settings.local.json, which the
    harness reads for the whole of the NEXT session. Four properties have to
    hold together, and the fixture must be hermetic to test any of them: an
    early version of this test set no PRECEDENT_USER_CONFIG, so the case for
    "no declared zone" resolved the real user config, found a real declared
    zone, and reported a failure against completely correct behaviour.
      1. a DECLARED zone is written; a GUESSED one never is (writing a guess
         would enforce something nobody said).
      2. identity.json stays the source of truth -- a stale TZ already in the
         file is re-derived, not respected (registry-source-of-truth).
      3. nothing else in the file is disturbed, and an unparseable one is left
         entirely alone rather than overwritten.
      4. the file is per-machine, so the hook warns when it is not gitignored.
    """
    import tempfile, json as _json
    hook = ROOT / '.claude' / 'hooks' / 'commit-identity.sh'
    if not hook.exists():
        not_applicable('commit-identity derives the declared timezone into '
                       'the session',
                       '.claude/hooks/commit-identity.sh is not present here')
        return

    env = dict(os.environ)
    # Hermetic: without this the hook resolves the REAL user config and the
    # "no zone declared" case silently becomes a "zone declared" case.
    env['PRECEDENT_USER_CONFIG'] = '/nonexistent/precedent-config.json'
    env.pop('PRECEDENT_COMMIT_TZ', None)
    # And HOME, or the hook writes the REAL ~/.gitconfig and the REAL global
    # hooks directory. It gained that behaviour on 2026-09-07 and this
    # fixture -- which declares Europe/Berlin -- promptly set this machine's
    # global identity to a test value and installed a Berlin-offset backstop,
    # which then refused the very commit landing the fix. A test that mutates
    # the environment it runs in is not a test.
    _home = tempfile.mkdtemp(prefix='ci-home-')
    env['HOME'] = _home
    # And the system clock, for the same reason and one step worse: this
    # fixture declares Europe/Berlin, and the hook now REPOINTS the machine's
    # zone file at a declared zone. Without this the harness would put the
    # container on Berlin time and every later commit in the session would be
    # refused by the backstop for an offset the harness itself caused.
    env['PRECEDENT_LOCALTIME'] = os.path.join(_home, 'localtime')

    def _repo(base, zone, settings=None, gitignore=None):
        base.mkdir(parents=True, exist_ok=True)
        subprocess.run(['git', '-C', str(base), 'init', '-q'],
                       capture_output=True)
        if zone:
            (base / 'identity.json').write_text(_json.dumps(
                {'name': 'T', 'email': 't@example.com', 'timezone': zone}),
                encoding='utf-8')
        if settings is not None:
            (base / '.claude').mkdir(exist_ok=True)
            (base / '.claude' / 'settings.local.json').write_text(
                settings, encoding='utf-8')
        if gitignore is not None:
            (base / '.gitignore').write_text(gitignore, encoding='utf-8')
        e = dict(env, CLAUDE_PROJECT_DIR=str(base))
        r = subprocess.run(['bash', str(hook)], capture_output=True,
                           text=True, env=e, timeout=120)
        return base / '.claude' / 'settings.local.json', r

    def _tz(f):
        try:
            return _json.loads(f.read_text(encoding='utf-8'))['env']['TZ']
        except Exception:
            return None

    cases = []
    with tempfile.TemporaryDirectory() as td:
        tmp = pathlib.Path(td)

        f, r = _repo(tmp / 'declared', 'America/Argentina/Buenos_Aires')
        cases.append(('a declared zone lands in settings.local.json',
                      _tz(f) == 'America/Argentina/Buenos_Aires'))
        cases.append(('and the hook still exits 0', r.returncode == 0))
        before = f.read_bytes()
        e = dict(env, CLAUDE_PROJECT_DIR=str(tmp / 'declared'))
        r2 = subprocess.run(['bash', str(hook)], capture_output=True,
                            text=True, env=e, timeout=120)
        cases.append(('a second run rewrites nothing', f.read_bytes() == before))
        cases.append(('and says nothing about it',
                      'settings.local.json' not in r2.stderr))

        # A person whose zone could not be resolved gets the DECLARED
        # FALLBACK written, not nothing. This assertion is the reverse of
        # what it was before 2026-09-09 (practice: timestamps-carry-offset):
        # writing nothing left the container on UTC, so every unidentified
        # person's commits and generated dates came out +0000 and could not
        # be ordered against anyone else's. The fallback is applied for that
        # reason and still never ENFORCED -- case 3 below holds that line.
        #
        # The expected value is DERIVED, never typed here. Typed, it is a
        # fourth copy of a constant that already lives in four places, and on
        # 2026-09-10 -- when the engine fallback moved off one person's zone
        # onto a generic one -- these two assertions were the only thing that
        # failed, because they were the copies nobody knew to change.
        f, r3 = _repo(tmp / 'guessed', None)
        cases.append((f'an unresolved zone still writes the declared fallback '
                      f'({_declared_fallback_tz()})',
                      _tz(f) == _declared_fallback_tz()))
        cases.append(('and says out loud that it is a fallback, not this '
                      "person's own zone",
                      'DECLARED FALLBACK' in r3.stderr))

        f, _ = _repo(tmp / 'existing', 'Europe/Berlin',
                     settings='{"env":{"OTHER":"keep"},'
                              '"permissions":{"allow":["Bash(ls)"]}}')
        try:
            d = _json.loads(f.read_text(encoding='utf-8'))
        except Exception:
            d = {}
        cases.append(('an existing file keeps its other keys',
                      d.get('env', {}).get('TZ') == 'Europe/Berlin'
                      and d.get('env', {}).get('OTHER') == 'keep'
                      and d.get('permissions', {}).get('allow') == ['Bash(ls)']))

        f, _ = _repo(tmp / 'stale', 'Europe/Berlin',
                     settings='{"env":{"TZ":"UTC"}}')
        cases.append(('a stale TZ is re-derived, not respected',
                      _tz(f) == 'Europe/Berlin'))

        f, _ = _repo(tmp / 'broken', 'Europe/Berlin', settings='not json at all')
        cases.append(('an unparseable settings file is left untouched',
                      f.read_text(encoding='utf-8') == 'not json at all'))

        _, r = _repo(tmp / 'ignored', 'Europe/Berlin',
                     gitignore='.claude/settings.local.json\n')
        cases.append(('no gitignore warning when the file IS ignored',
                      'NOT gitignored' not in r.stderr))
        _, r = _repo(tmp / 'notignored', 'Europe/Berlin')
        cases.append(('the gitignore warning fires when it is not',
                      'NOT gitignored' in r.stderr))

    failed = [n for n, ok in cases if not ok]
    check(f'commit-identity derives the declared timezone into the session '
          f'({len(cases)} stated cases)', not failed, '; '.join(failed))


def check_refresh_survives_an_upstream_rename():
    """A file removed upstream must not brick every consumer's refresh.

    `refresh` runs the consumer's OWN vendored copy of the vendoring tool,
    and that copy carries the file list it was vendored with. So the first
    refresh after upstream renames or drops an engine file asks git for a
    path that is genuinely gone. That used to be a hard exit:

      precedent_vendor_engine FAIL: precedent-beta-v01 @ <sha> has no
      tools/precedent_retire_path.py

    with no documented way forward -- the fix a consumer needs is inside the
    very file it cannot fetch. The tool's own comments already describe this
    shape for an ADDED file, where it merely stops one file short and the
    second pass converges; for a REMOVED file it was fatal. Reproduced
    2026-09-07 on a real consumer, renaming precedent_retire_path.py ->
    precedent_decommission.py.

    A missing source file is therefore a REMOVAL: skipped with a notice, and
    left out of the manifest rather than recorded as present. The second
    pass then runs the new list, which does not ask for it at all.

    THE ONE FILE THAT STAYS FATAL is the vendoring tool itself. It is what
    carries the corrected list, so without it there is no second pass and
    nothing to converge on -- and a missing one really does mean a broken
    ref rather than a removal. That distinction is the whole point of the
    case below: skipping everything would trade a loud failure for a silent
    one.
    """
    import tempfile, json as _json, shutil as _shutil, importlib
    vend = ROOT / 'tools' / 'precedent_vendor_engine.py'
    if not vend.exists():
        not_applicable('refresh survives an upstream rename',
                       'tools/precedent_vendor_engine.py is not present here')
        return

    env = dict(os.environ, PRECEDENT_ALLOW_ANY_AUTHOR='1')
    cases = []
    with tempfile.TemporaryDirectory() as td:
        tmp = pathlib.Path(td)

        # A throwaway "upstream" whose tools/ is MISSING one file the
        # consumer's list still asks for -- exactly what a rename leaves.
        up = tmp / 'upstream'
        (up / 'tools').mkdir(parents=True)
        _ve = importlib.import_module('precedent_vendor_engine')
        for name in sorted(set(_ve.KINDS['consumer']) | {'routing_scope.json'}):
            if name == 'precedent_show.py':
                continue                      # the "renamed away" file
            src = ROOT / 'tools' / name
            if src.is_file():
                _shutil.copy2(src, up / 'tools' / name)
        subprocess.run(['git', '-C', str(up), 'init', '-q'], capture_output=True)
        for c in (['config', 'user.email', 'h@example.com'],
                  ['config', 'user.name', 'H']):
            subprocess.run(['git', '-C', str(up)] + c, capture_output=True)
        subprocess.run(['git', '-C', str(up), 'add', '-A'], capture_output=True)
        subprocess.run(['git', '-C', str(up), 'commit', '-qm', 'upstream'],
                       capture_output=True, env=env)
        up_head = subprocess.run(['git', '-C', str(up), 'rev-parse', 'HEAD'],
                                 capture_output=True, text=True).stdout.strip()

        # A consumer seeded from THIS tree -- so its list still names the file
        # the upstream above no longer has.
        cons = tmp / 'consumer'
        cons.mkdir()
        subprocess.run(['git', '-C', str(cons), 'init', '-q'], capture_output=True)
        r = subprocess.run(
            [sys.executable, str(vend), 'seed', str(cons), '--kind', 'consumer'],
            capture_output=True, text=True, timeout=300, env=env)
        if r.returncode != 0:
            not_applicable('refresh survives an upstream rename',
                           'could not seed a consumer engine here')
            return
        _shutil.copy2(vend, cons / 'tools' / 'precedent_vendor_engine.py')

        r = subprocess.run(
            [sys.executable, str(cons / 'tools' / 'precedent_vendor_engine.py'),
             'refresh', str(up), '--force', '--from-ref', up_head],
            capture_output=True, text=True, timeout=600, cwd=str(cons), env=env)
        out = r.stdout + r.stderr
        cases.append(('a file removed upstream does not fail the refresh',
                      r.returncode == 0))
        cases.append(('and the run says the file was removed or renamed, '
                      'rather than reporting a broken clone',
                      'removed or renamed' in out))
        try:
            m = _json.loads((cons / 'tools' / 'ENGINE_MANIFEST.json')
                            .read_text(encoding='utf-8'))
        except (OSError, ValueError):
            m = {}
        cases.append(('the missing file is left OUT of the manifest, not '
                      'recorded as present',
                      'precedent_show.py' not in (m.get('files') or [])
                      and 'precedent_show.py' not in (m.get('sha256') or {})))
        cases.append(('every file the manifest DOES record exists on disk',
                      all((cons / 'tools' / f).is_file()
                          for f in (m.get('files') or []))))

        # THE MUST-STAY-FATAL CASE: the vendoring tool itself is gone.
        up2 = tmp / 'upstream-no-tool'
        _shutil.copytree(up, up2)
        (up2 / 'tools' / 'precedent_vendor_engine.py').unlink()
        subprocess.run(['git', '-C', str(up2), 'add', '-A'], capture_output=True)
        subprocess.run(['git', '-C', str(up2), 'commit', '-qm', 'drop the tool'],
                       capture_output=True, env=env)
        up2_head = subprocess.run(['git', '-C', str(up2), 'rev-parse', 'HEAD'],
                                  capture_output=True, text=True).stdout.strip()
        r2 = subprocess.run(
            [sys.executable, str(cons / 'tools' / 'precedent_vendor_engine.py'),
             'refresh', str(up2), '--force', '--from-ref', up2_head],
            capture_output=True, text=True, timeout=600, cwd=str(cons), env=env)
        out2 = r2.stdout + r2.stderr
        cases.append(('a missing VENDORING TOOL is still fatal -- there is no '
                      'corrected list to converge on', r2.returncode != 0))
        cases.append(('and says that, rather than calling it a removal',
                      'not a removal' in out2))

    failed = [n for n, ok in cases if not ok]
    check(f'a file removed upstream does not brick a consumer refresh '
          f'({len(cases)} stated cases)', not failed, '; '.join(failed))


def check_superseded_source_says_so():
    """A document that was the SOURCE for a generated replacement must say so.

    PRACTICES.md was the single-file catalogue phase 1 converted into
    practices/. The conversion landed 2026-08-31 and PRACTICES.md stopped
    being the catalogue that same day -- but nothing said so, and AGENTS.md's
    quick index went on pointing at it as "What each practice is and why".
    Twenty practices were minted over the next week; none appeared in it.
    Morgan found it while asking where a new index should live, 2026-09-07.

    NOTHING WAS BROKEN, WHICH IS THE POINT. check_source_coverage asks
    "does every practice in PRACTICES.md still have a file?" -- the MIGRATION
    direction, correct for the migration, and permanently green afterwards.
    The reverse question was never asked, and a practice minted after the
    conversion carries `source_practice_number: null` and is explicitly
    `continue`d, so it is invisible to the only check that reads both. A
    document can be a month out of date, still linked as authoritative, and
    every gate green.

    So the third state is what this refuses: **behind AND silent**. Either
    PRACTICES.md is current with the catalogue, or it declares itself
    superseded. It may not be neither. The banner is the cheap half -- a
    reader who opens the file learns in one line that it is frozen -- and
    this check is what stops a later session deleting the banner to tidy the
    file up, or "refreshing" the document without refreshing its content.

    Generalises past this one file: any repo doing a one-time conversion
    leaves its source behind, and the source is the thing everyone keeps
    linking.
    """
    cat = ROOT / 'PRACTICES.md'
    if not cat.is_file():
        not_applicable('a superseded conversion source says so',
                       'PRACTICES.md is not present here')
        return

    text = cat.read_text(encoding='utf-8')
    numbered = set(re.findall(r'^## (\d+)\.', text, re.M))

    minted_after = []
    for f in sorted((ROOT / 'practices').glob('*.md')):
        fm, _sections = sp._read_practice_file(f)
        num = fm.get('source_practice_number')
        if num is None or str(num).strip('"').strip("'") in ('', 'null'):
            minted_after.append(fm.get('slug', f.stem))

    behind = len(minted_after) > 0
    # "Declares itself superseded" means the machine-readable field, not a
    # sentence somebody hopes is read: kind/status frontmatter is the same
    # contract document-status-header applies under spec/ and record/.
    declared = bool(re.search(r'^status:\s*superseded\s*$', text, re.M))
    points_at_successor = bool(re.search(r'^superseded_by:\s*\S+', text, re.M))

    cases = [
        ('PRACTICES.md is either current with practices/ or declares '
         'status: superseded -- never behind and silent',
         (not behind) or declared),
        ('and when superseded, it names what replaced it',
         (not behind) or points_at_successor),
        ('the check can actually see the drift it is gating on -- a '
         'zero-drift reading would make this pass for the wrong reason',
         behind or len(numbered) >= len(list((ROOT / 'practices').glob('*.md')))),
    ]

    failed = [n for n, ok in cases if not ok]
    detail = '; '.join(failed)
    if failed and behind:
        detail += (f" [{len(minted_after)} practice(s) exist that PRACTICES.md "
                   f"has never carried, e.g. {', '.join(sorted(minted_after)[:3])}]")
    check(f'a superseded conversion source says so, rather than going stale '
          f'quietly ({len(cases)} stated cases)', not failed, detail)


def check_refresh_never_rolls_a_newer_engine_back():
    """A repo whose vendored engine came from a BestPractice commit the
    source branch does not contain is AHEAD, not stale: the refresh leaves
    it, and the session-start survey says AHEAD.

    2026-10-02: a practice set made from a working branch recorded that
    branch's commit. Every session start compared it with main only for
    equality, called it stale, and wrote main's older engine over it in the
    working tree, deleting files the set had committed."""
    import tempfile, io, contextlib
    import precedent_vendor_engine as pve
    import precedent_refresh_sources as prs
    cases = []
    env = dict(os.environ, PRECEDENT_ALLOW_ANY_AUTHOR='1',
               GIT_AUTHOR_NAME='f', GIT_AUTHOR_EMAIL='f@x',
               GIT_COMMITTER_NAME='f', GIT_COMMITTER_EMAIL='f@x')
    g = lambda cwd, *a: subprocess.run(['git', '-C', str(cwd), *a], env=env,
                                        capture_output=True, text=True).stdout.strip()
    with tempfile.TemporaryDirectory() as td:
        bp = pathlib.Path(td) / 'bp'
        bp.mkdir()
        g(bp, 'init', '-q', '-b', 'main')
        g(bp, 'commit', '-q', '--allow-empty', '-m', 'A')
        old = g(bp, 'rev-parse', 'HEAD')
        g(bp, 'switch', '-q', '-c', 'side')
        g(bp, 'commit', '-q', '--allow-empty', '-m', 'B')
        side = g(bp, 'rev-parse', 'HEAD')
        g(bp, 'switch', '-q', 'main')
        g(bp, 'commit', '-q', '--allow-empty', '-m', 'C')
        tip = g(bp, 'rev-parse', 'HEAD')
        cases.append(('an engine from a branch main does not contain is ahead',
                      pve.engine_is_ahead(bp, side, tip) is True))
        cases.append(('an engine from an older main commit is stale, not ahead',
                      pve.engine_is_ahead(bp, old, tip) is False))
        cases.append(('a commit the clone cannot place is not called ahead',
                      pve.engine_is_ahead(bp, 'f' * 40, tip) is False))

        # refresh() itself: told the source branch is at `tip`, a repo
        # recording `side` is left untouched, and says why.
        repo = pathlib.Path(td) / 'repo'
        (repo / 'tools').mkdir(parents=True)
        (repo / 'tools' / 'ENGINE_MANIFEST.json').write_text(json.dumps(
            {'kind': 'source', 'source_commit': side, 'files': {}}),
            encoding='utf-8')
        scratch = pathlib.Path(td) / 'engine'
        scratch.mkdir()
        saved = (pve.ROOT, pve._source_tools_at)
        out = io.StringIO()
        try:
            pve.ROOT = repo
            pve._source_tools_at = lambda clone, kind, ref=None, fetch=True: (tip, scratch)
            with contextlib.redirect_stdout(out):
                pve.refresh(bp)
        except SystemExit as e:
            out.write(f'[exited {e}]')
        except Exception as e:
            # Unguarded, it goes on to copy the empty scratch engine over
            # the repo's: that attempt is the rollback this case refuses.
            out.write(f'[went ahead with the copy: {type(e).__name__}: {e}]')
        finally:
            pve.ROOT, pve._source_tools_at = saved
        manifest = json.loads((repo / 'tools' / 'ENGINE_MANIFEST.json')
                              .read_text(encoding='utf-8'))
        cases.append(('refresh leaves a newer engine as it is, and says so',
                      'newer work, not older' in out.getvalue()
                      and manifest['source_commit'] == side
                      and sorted(p.name for p in (repo / 'tools').iterdir())
                      == ['ENGINE_MANIFEST.json'], out.getvalue()[-300:]))

        # The survey's question, asked of a BestPractice checkout.
        saved_root = prs.ROOT
        try:
            prs.ROOT = bp
            cases.append(("the session-start survey calls it ahead, and an "
                          "older one not",
                          prs._engine_ahead_of(side, tip) is True
                          and prs._engine_ahead_of(old, tip) is False))
        finally:
            prs.ROOT = saved_root
    bad = [c[0] + (f' -- {c[2]}' if len(c) > 2 else '') for c in cases if not c[1]]
    check(f'a refresh never rolls a newer engine back ({len(cases)} stated cases)',
          not bad, '; '.join(bad))


def check_seed_refuses_an_engine_main_lacks():
    """seed() and the bootstrap refuse to copy an engine from a commit main
    does not contain, before writing anything, unless told it is on
    purpose; told so, the manifest names the real branch beside a
    source_branch that still says what refresh follows.

    2026-10-02: a practice set made from a working branch recorded
    source_branch "main" over that branch's commit, and every session start
    rolled its engine back (check_refresh_never_rolls_a_newer_engine_back
    is the other half)."""
    import tempfile, io, contextlib
    import precedent_vendor_engine as pve
    import precedent_bootstrap_source as pbs
    cases = []
    env = dict(os.environ, GIT_AUTHOR_NAME='f', GIT_AUTHOR_EMAIL='f@x',
               GIT_COMMITTER_NAME='f', GIT_COMMITTER_EMAIL='f@x')
    g = lambda cwd, *a: subprocess.run(['git', '-C', str(cwd), *a], env=env,
                                        capture_output=True, text=True).stdout.strip()
    saved_env = os.environ.pop('PRECEDENT_SEED_OFF_MAIN', None)
    saved_off = pve.off_source_branch
    try:
        with tempfile.TemporaryDirectory() as td:
            bp = pathlib.Path(td) / 'bp'
            bp.mkdir()
            g(bp, 'init', '-q', '-b', 'main')
            g(bp, 'commit', '-q', '--allow-empty', '-m', 'A')
            old = g(bp, 'rev-parse', 'HEAD')
            g(bp, 'switch', '-q', '-c', 'feature-x')
            g(bp, 'commit', '-q', '--allow-empty', '-m', 'B')
            side = g(bp, 'rev-parse', 'HEAD')
            cases.append(('a commit main lacks is named by the branch it is on',
                          pve.off_source_branch(bp, side) == 'feature-x'))
            cases.append(('a commit main contains is not off main',
                          pve.off_source_branch(bp, old) is None))
            nomain = pathlib.Path(td) / 'nomain'
            nomain.mkdir()
            g(nomain, 'init', '-q', '-b', 'trunk')
            g(nomain, 'commit', '-q', '--allow-empty', '-m', 'A')
            cases.append(('with no main to ask, nothing is called off main',
                          pve.off_source_branch(nomain, g(nomain, 'rev-parse', 'HEAD'))
                          is None))

            pve.off_source_branch = lambda repo, commit: 'feature-x'
            dest = pathlib.Path(td) / 'refused'
            dest.mkdir()
            err = io.StringIO()
            try:
                with contextlib.redirect_stderr(err), contextlib.redirect_stdout(err):
                    pve.seed(dest, kind='consumer')
                refused = ''
            except SystemExit as e:
                refused = str(e)
            cases.append(('seed refuses it, naming the branch and --off-main, '
                          'and writes nothing',
                          'REFUSED' in refused and 'feature-x' in refused
                          and '--off-main' in refused and not any(dest.iterdir()),
                          refused[:200]))

            dest = pathlib.Path(td) / 'told'
            dest.mkdir()
            with contextlib.redirect_stderr(err), contextlib.redirect_stdout(err):
                pve.seed(dest, kind='consumer', off_main=True)
            m = json.loads((dest / 'tools' / 'ENGINE_MANIFEST.json')
                           .read_text(encoding='utf-8'))
            cases.append(('told --off-main, the manifest names the real branch '
                          'and keeps source_branch main',
                          m.get('source_branch') == pve.SOURCE_BRANCH
                          and m.get('seeded_from_branch') == 'feature-x', str(m)[:200]))

            bdest = pathlib.Path(td) / 'set'
            saved_warn = pbs._warn_if_clone_is_stale
            pbs._warn_if_clone_is_stale = lambda: None
            try:
                pbs.bootstrap('shared', 'precedent-shared-zz', bdest,
                              approvers=[{'name': 'A B', 'github': 'ab'}])
                why = ''
            except pbs.BootstrapRefused as e:
                why = str(e)
            finally:
                pbs._warn_if_clone_is_stale = saved_warn
            cases.append(('the bootstrap refuses it before creating the set',
                          'feature-x' in why and '--off-main true' in why
                          and not bdest.exists(), why[:200]))
    finally:
        pve.off_source_branch = saved_off
        if saved_env is not None:
            os.environ['PRECEDENT_SEED_OFF_MAIN'] = saved_env
    bad = [c[0] + (f' -- {c[2]}' if len(c) > 2 else '') for c in cases if not c[1]]
    check(f'seed refuses an engine main lacks, unless told ({len(cases)} stated cases)',
          not bad, '; '.join(bad))

def check_refresh_removes_dropped_engine_files():
    """A file dropped from the engine set leaves every consumer, not just this repo.

    refresh() only ever added and overwrote. Rename or drop a file from KINDS
    and every consumer that already had it kept it forever: the new manifest
    stops listing it, so nothing tracks it, nothing updates it, and no later
    reader can tell whether it still does something. That is the exact state
    decommission-deletes-files exists to prevent, produced by the tool that
    distributes that practice.

    Found 2026-09-07 costing the retirement->decommission rename: the tool
    being renamed is IN the consumer engine set, so the rename would have
    pushed the new name out and left the old one beside it in perpetuity --
    two repos that day, and every consumer created afterwards.

    Safety rests entirely on the manifest. Only files the PREVIOUS manifest
    recorded as vendored are candidates, so a consuming repo's own tools/
    cannot be touched whatever it is named -- that is the case this test
    spends a fixture on, because getting it wrong deletes somebody's work
    rather than merely leaving litter.

    And a hand-edited copy is KEPT and reported. _local_drift already refuses
    the whole refresh over one unless --force, so arriving here modified
    means somebody asked to overwrite -- which is not the same as asking to
    throw the edit away.
    """
    import tempfile, json as _json, shutil as _shutil
    vend = ROOT / 'tools' / 'precedent_vendor_engine.py'
    if not vend.exists():
        not_applicable('refresh removes dropped engine files',
                       'tools/precedent_vendor_engine.py is not present here')
        return

    env = dict(os.environ, PRECEDENT_ALLOW_ANY_AUTHOR='1')
    ref = _ref_including_worktree(ROOT)

    def _consumer(base):
        """Seed a real consumer engine from THIS working tree."""
        base.mkdir(parents=True)
        subprocess.run(['git', '-C', str(base), 'init', '-q'], capture_output=True)
        r = subprocess.run(
            [sys.executable, str(vend), 'seed', str(base), '--kind', 'consumer'],
            capture_output=True, text=True, timeout=300, env=env)
        if r.returncode != 0:
            return None
        # AND OVERWRITE THE SEEDED TOOL WITH THIS WORKING TREE'S. `seed`
        # vendors via git, so it copies the COMMITTED engine -- a fixture
        # built on it silently tests the code as it was before your change.
        # Cost this exact test three red cases before the cause was found,
        # and cost the rename-updates-links test the same thing an hour
        # earlier, which is why it is spelled out in both.
        _shutil.copy2(vend, base / 'tools' / 'precedent_vendor_engine.py')
        return base

    def _manifest(base):
        return _json.loads(
            (base / 'tools' / 'ENGINE_MANIFEST.json').read_text(encoding='utf-8'))

    cases = []
    with tempfile.TemporaryDirectory() as td:
        tmp = pathlib.Path(td)
        base = _consumer(tmp / 'consumer')
        if base is None:
            not_applicable('refresh removes dropped engine files',
                           'could not seed a consumer engine here')
            return

        m = _manifest(base)
        victim = 'precedent_show.py'
        cases.append(('the fixture starts with the file it will drop',
                      victim in (m.get('files') or [])
                      and (base / 'tools' / victim).is_file()))

        # A file the engine NEVER vendored, sitting in the same directory.
        # Nothing may touch this, ever.
        own = base / 'tools' / 'this_repos_own_tool.py'
        own.write_text('# not the engine\'s\n', encoding='utf-8')

        # Simulate the drop by rewriting the PREVIOUS manifest to claim one
        # more file than the current KINDS list has -- which is exactly the
        # shape a real rename leaves behind.
        extra = 'precedent_retired_name.py'
        (base / 'tools' / extra).write_text('# stale vendored tool\n', encoding='utf-8')
        m['files'] = list(m.get('files') or []) + [extra]
        m.setdefault('sha256', {})[extra] = hashlib.sha256(
            (base / 'tools' / extra).read_bytes()).hexdigest()
        (base / 'tools' / 'ENGINE_MANIFEST.json').write_text(
            _json.dumps(m, indent=2), encoding='utf-8')

        r = subprocess.run(
            [sys.executable, str(base / 'tools' / 'precedent_vendor_engine.py'),
             'refresh', str(ROOT), '--force', '--from-ref', ref],
            capture_output=True, text=True, timeout=600, cwd=str(base), env=env)
        out = r.stdout + r.stderr

        cases.append(('a file the current set no longer includes is deleted',
                      not (base / 'tools' / extra).exists()))
        cases.append(('and the run says which file went, and why it was safe',
                      extra in out and 'no longer includes' in out))
        cases.append(("a file the engine never vendored is UNTOUCHED -- the "
                      "manifest is what makes this safe", own.is_file()))
        cases.append(('a file still in the set survives',
                      (base / 'tools' / victim).is_file()))

        # NEGATIVE CONTROL on the hand-edit rule: a dropped file whose
        # content no longer matches what was vendored is kept, not deleted.
        base2 = _consumer(tmp / 'edited')
        if base2 is not None:
            m2 = _manifest(base2)
            (base2 / 'tools' / extra).write_text('# stale\n', encoding='utf-8')
            m2['files'] = list(m2.get('files') or []) + [extra]
            m2.setdefault('sha256', {})[extra] = 'deadbeef' * 8   # wrong on purpose
            (base2 / 'tools' / 'ENGINE_MANIFEST.json').write_text(
                _json.dumps(m2, indent=2), encoding='utf-8')
            r2 = subprocess.run(
                [sys.executable, str(base2 / 'tools' / 'precedent_vendor_engine.py'),
                 'refresh', str(ROOT), '--force', '--from-ref', ref],
                capture_output=True, text=True, timeout=600, cwd=str(base2), env=env)
            out2 = r2.stdout + r2.stderr
            cases.append(('a hand-edited dropped file is KEPT',
                          (base2 / 'tools' / extra).is_file()))
            cases.append(('and said so, rather than deleted silently',
                          'hand-edited' in out2))

        # END TO END for the legacy sweep (2026-09-24): refresh() itself
        # calls it, before the drift check, and closes with "Left for you".
        # check_legacy_leftovers_retired_by_content covers the cases; this
        # covers the wiring, which is what a real install runs.
        base3 = _consumer(tmp / 'legacy')
        if base3 is not None:
            _shutil.copy2(ROOT / 'tools' / 'precedent_decommission.py',
                          base3 / 'tools' / 'precedent_decommission.py')
            wf = base3 / '.github' / 'workflows'
            wf.mkdir(parents=True)
            (wf / 'bestpractice-upstream-sync.yml').write_text(
                'on:\n  workflow_dispatch:\njobs:\n  u:\n    steps:\n'
                '      - uses: anthropics/claude-code-action@v1\n',
                encoding='utf-8')
            (wf / 'bestpractice-docs.yml').write_text(
                'on:\n  workflow_dispatch:\njobs:\n  d:\n    steps:\n'
                '      - run: python3 tools/our_own.py\n', encoding='utf-8')
            genv = dict(env, GIT_AUTHOR_NAME='t', GIT_AUTHOR_EMAIL='harness@example.com',
                        GIT_COMMITTER_NAME='t', GIT_COMMITTER_EMAIL='harness@example.com')
            subprocess.run(['git', '-C', str(base3), 'add', '-A'],
                           capture_output=True, env=genv)
            subprocess.run(['git', '-C', str(base3), 'commit', '-qm', 'base'],
                           capture_output=True, env=genv)
            r3 = subprocess.run(
                [sys.executable, str(base3 / 'tools' / 'precedent_vendor_engine.py'),
                 'refresh', str(ROOT), '--force', '--from-ref', ref],
                capture_output=True, text=True, timeout=600, cwd=str(base3), env=env)
            out3 = r3.stdout + r3.stderr
            cases.append(('refresh itself retires a stock-shaped legacy '
                          'workflow no manifest ever tracked',
                          not (wf / 'bestpractice-upstream-sync.yml').exists()))
            # A consumer's CI converges to upstream since 2026-09-27, but a
            # workflow running something the local push check does not run
            # is kept until that moves there (CI_CONVERGES_KINDS).
            cases.append(('and keeps a same-name file of the repo\'s own '
                          'that runs a script the local check does not, '
                          'naming it under "Left for you"',
                          (wf / 'bestpractice-docs.yml').is_file()
                          and 'Left for you' in out3 and 'our_own.py' in out3))

    failed = [n for n, ok in cases if not ok]
    check(f'refresh removes engine files the set no longer includes, and only '
          f'those ({len(cases)} stated cases)', not failed, '; '.join(failed))



def check_decommission_skips_generated_files_and_prose():
    """THE INCIDENT (2026-09-28, a classic-layout migration rehearsal in a
    real consumer). Decommissioning `process/personal` could never reach
    CLEAR: the basename pass searched the bare word `personal` and matched
    ordinary English in the loader-generated AGENTS.md, the vendored engine
    (whose own docstring names `process/personal`) and every materialized
    practice -- 141 blockers, none of them the repo's to repoint, and the
    tool has no flag to skip one by design.

    Two fixes, each with its negative control, because the audit is only
    worth running while it still refuses a real reference:
      * a directory's basename is searched as `base/`, so prose no longer
        matches but `personal/README.md` in a hand-written doc still blocks;
      * files tools/ENGINE_MANIFEST.json (files, hook_files) or the
        materializer's MANIFEST.json record are reported, not scanned, while
        a hand-authored practice the manifest does not list still blocks."""
    import tempfile, shutil as _shutil, json as _json
    tool = ROOT / 'tools' / 'precedent_decommission.py'
    tmp = pathlib.Path(tempfile.mkdtemp(prefix='precedent-decom-gen-'))
    cases = []
    try:
        repo = tmp / 'consumer'
        genv = dict(os.environ, GIT_AUTHOR_NAME='t',
                    GIT_AUTHOR_EMAIL='harness@example.com',
                    GIT_COMMITTER_NAME='t',
                    GIT_COMMITTER_EMAIL='harness@example.com')

        def git(*a):
            return subprocess.run(['git', '-C', str(repo), *a],
                                  capture_output=True, text=True, env=genv)

        def w(rel, text):
            f = repo / rel
            f.parent.mkdir(parents=True, exist_ok=True)
            f.write_text(text, encoding='utf-8')

        repo.mkdir()
        git('init', '-q')
        w('process/personal/README.md', 'the retired personal pack\n')
        w('tools/engine_x.py',
          '"""Retires process/personal/README.md on refresh."""\n')
        w('.claude/hooks/h.sh', '# reads process/personal when present\n')
        w('tools/ENGINE_MANIFEST.json', _json.dumps(
            {'kind': 'consumer', 'files': ['engine_x.py'],
             'hook_files': ['h.sh']}))
        w('practices/p1.md', 'Older installs kept a process/personal tree.\n')
        w('MANIFEST.json', _json.dumps(
            {'generated_by': 'tools/precedent_materialize.py',
             'practices': [{'slug': 'p1'}], 'checks': [], 'adapters': []}))
        w('AGENTS.md', 'Give the GitHub steps for a personal repo, and a '
                       'personal welcome message. We archive nothing.\n')
        w('archive/old.md', 'a retired top-level directory\n')
        # The real references -- negative controls.
        w('docs/guide.md', 'See personal/README.md for the old layout.\n'
                           'And archive/old.md for the one before.\n')
        w('practices/own.md', 'We still read process/personal at start.\n')
        git('add', '-A')
        git('commit', '-qm', 'fixture')

        def run(target='process/personal'):
            r = subprocess.run([sys.executable, str(tool), target],
                               capture_output=True, text=True, cwd=str(repo),
                               timeout=120)
            return r.returncode, r.stdout + r.stderr

        rc, out = run()
        cases.append(('prose using the word in AGENTS.md does not block',
                      'AGENTS.md:' not in out, out[-1500:]))
        cases.append(('the vendored engine file, hook and materialized '
                      'practice do not block',
                      not any(f'{x}:' in out for x in
                              ('tools/engine_x.py', '.claude/hooks/h.sh',
                               'practices/p1.md')), out[-1500:]))
        cases.append(('and the report says they were skipped, and that 3 '
                      'of them mention it',
                      'not scanned' in out and '3 mention it' in out,
                      out[-1500:]))
        cases.append(('a hand-written doc naming personal/README.md still '
                      'blocks (by basename)',
                      rc == 1 and 'docs/guide.md:1' in out, out[-1500:]))
        cases.append(('a practice the materializer never wrote still blocks',
                      'practices/own.md:1' in out, out[-1500:]))
        rc_a, out_a = run('archive')
        cases.append(('a TOP-LEVEL directory is searched as `archive/`: the '
                      'verb in AGENTS.md does not block, the path in a doc '
                      'does', rc_a == 1 and 'AGENTS.md:' not in out_a
                      and 'docs/guide.md:2' in out_a, out_a[-1500:]))

        (repo / 'docs' / 'guide.md').unlink()
        (repo / 'practices' / 'own.md').unlink()
        git('add', '-A')
        git('commit', '-qm', 'repoint the real references')
        rc2, out2 = run()
        rc3, out3 = run('archive')
        cases.append(('with the real references gone, the audit is CLEAR',
                      rc2 == 0 and 'CLEAR' in out2
                      and rc3 == 0 and 'CLEAR' in out3,
                      out2[-1000:] + out3[-1000:]))
    finally:
        _shutil.rmtree(tmp, ignore_errors=True)

    bad = [(c[0], c[2]) for c in cases if not c[1]]
    check(f'decommission audit skips generated files and prose, and still '
          f'refuses a real reference ({len(cases)} stated cases)',
          not bad, '; '.join(f'{n} -- {d[:800]}' for n, d in bad))



def check_todo_migrate_reads_a_consumers_list():
    """todo_migrate.py carries a consumer's own TODO.md across, not only the
    one this repository migrated.

    2026-10-06, a consumer migrating its list hit three things at once: every
    item older than 2026-09-06 was told it "predates anchor tracking (every
    anchor was retrofitted 2026-09-06)" -- this repository's history, in a
    file that never had an anchor; every root-relative link in an item broke
    when the item moved into todo/; and two closed bullet shapes,
    `- [x] ~~**Title**~~` and a plain `- [x] text`, parsed as nothing.
    Unit-level, on a git fixture whose commit dates the cases choose."""
    import tempfile
    sys.path.insert(0, str(ROOT / 'tools'))
    import todo_migrate as tm
    cases = []
    tmp = pathlib.Path(tempfile.mkdtemp(prefix='todo-migrate-consumer-'))
    saved_today = tm.TODAY
    try:
        repo = tmp / 'proj'
        repo.mkdir()

        def git(*a, date=None):
            env = dict(os.environ)
            if date:
                env['GIT_AUTHOR_DATE'] = env['GIT_COMMITTER_DATE'] = f'{date}T12:00:00+00:00'
            subprocess.run(['git', '-c', 'core.hooksPath=/dev/null',
                            '-c', 'user.name=harness',
                            '-c', 'user.email=harness@example.com', *a],
                           cwd=str(repo), capture_output=True, check=True, env=env)

        def commit(text, date):
            (repo / 'TODO.md').write_text(text, encoding='utf-8')
            git('add', '-A')
            git('commit', '-qm', 'todo', date=date)

        git('init', '-q')
        commit('# TODO\n\n- [ ] **Plain old item** -- no anchor ever.\n\n'
               '- **Retrofitted item** -- anchored later.\n', '2026-01-01')
        commit('# TODO\n\n- [ ] **Plain old item** -- no anchor ever.\n\n'
               '- <a id="retrofitted-item"></a>**Retrofitted item** -- '
               'anchored later.\n\n'
               '- <a id="born-anchored"></a>**Born anchored** -- one commit.\n',
               '2026-02-01')
        text = ('# TODO\n\n- [ ] **Plain old item** -- no anchor ever. See '
                '[the plan](spec/PLAN.md), [here](#top), '
                '[web](https://example.com), [up](../x.md), [root](/y.md).\n\n'
                '- <a id="retrofitted-item"></a>**Retrofitted item** -- '
                'anchored later.\n\n'
                '- <a id="born-anchored"></a>**Born anchored** -- one commit.\n\n'
                '- [ ] **Never committed item** -- not in any history.\n\n'
                '- [x] ~~**Struck closed item**~~ -- finished.\n\n'
                '- [x] A plain closed line\n')
        (repo / 'TODO.md').write_text(text, encoding='utf-8')
        tm.TODAY = '2026-10-06'
        items = tm.parse_todo_items(text)
        plan = {it.title: (body, floor) for it, _p, _fm, body, _n, floor
                in tm.build_plan(items, repo, 'TODO.md', 'todo')}
        by_title = {it.title: it for it in items}

        def notes(body):
            return body.split('## Notes', 1)[-1]

        body, floor = plan.get('Plain old item', ('', None))
        cases.append(('an item with no anchor, found in history, is not '
                      'called a floor and names no anchor retrofit',
                      floor is False and 'anchor' not in notes(body)
                      and '2026-09-06' not in body, body[-300:]))
        cases.append(('a root-relative link gains ../ as the item moves '
                      'into todo/', '(../spec/PLAN.md)' in body, body[:300]))
        cases.append(('#anchors, URLs, ../ and /root links are left alone',
                      all(t in body for t in ('(#top)', '(https://example.com)',
                                              '(../x.md)', '(/y.md)'))
                      and '../../' not in body and '(..//' not in body,
                      body[:300]))
        body, floor = plan.get('Retrofitted item', ('', None))
        cases.append(('an anchor added to an older item writes the '
                      'retrofit note, with no fixed date',
                      floor is True and 'predates its anchor' in body
                      and '2026-09-06' not in body, body[-300:]))
        body, floor = plan.get('Born anchored', ('', None))
        cases.append(('CONTROL: an item anchored from its first commit is '
                      'not a floor', floor is False, body[-300:]))
        body, floor = plan.get('Never committed item', ('', None))
        cases.append(('an item found nowhere in history gets the neutral '
                      'floor note, naming no anchor',
                      floor is True and 'not found' in notes(body)
                      and 'anchor' not in notes(body), body[-300:]))
        struck = by_title.get('Struck closed item')
        cases.append(('`- [x] ~~**Title**~~` is a closed item of its own',
                      struck is not None and struck.checked is True,
                      sorted(by_title)))
        plain = by_title.get('A plain closed line')
        cases.append(('`- [x] text` is a closed item of its own',
                      plain is not None and plain.checked is True,
                      sorted(by_title)))
        cases.append(('CONTROL: the open checkbox item stays open',
                      by_title.get('Plain old item') is not None
                      and by_title['Plain old item'].checked is False, ''))
        cases.append(('every item parsed, none swallowed', len(items) == 6,
                      sorted(by_title)))
    except (OSError, subprocess.CalledProcessError) as e:
        cases.append((f'fixture could not be built ({e})', False, ''))
    finally:
        tm.TODAY = saved_today
        shutil.rmtree(tmp, ignore_errors=True)
    bad = [(n, d) for n, ok, d in cases if not ok]
    check(f'todo_migrate.py carries a consumer\'s list ({len(cases)} stated '
          f'cases)', not bad, '; '.join(f'{n}: {d}' for n, d in bad))


def check_docs_current_state_honours_load_bearing_paths():
    """docs-are-current-state skips a dated marker in a file precedent.json
    declares under `load_bearing_annotations`, and nowhere else.

    2026-10-06: a consumer's working legal drafts carry dated markers that
    matter legally. Those drafts are still edited, so they are
    not records, and `not_binding` would have switched the whole practice
    off. A declaration with no reason exempts nothing and is reported."""
    import tempfile
    import precedent_check as pc
    cases = []
    tmp = pathlib.Path(tempfile.mkdtemp(prefix='load-bearing-'))
    saved = pc.ROOT
    marker = '# Draft\n\nA new paragraph (added 2026-01-15).\n'

    class _Ctx:
        root = tmp
        changed = ['drafts/terms.md', 'notes.md']

        def read(self, rel):
            return (tmp / rel).read_text(encoding='utf-8')

    def verdict(entries):
        (tmp / 'precedent.json').write_text(json.dumps(
            {'load_bearing_annotations': entries}), encoding='utf-8')
        return [f.file() for f in pc._docs_are_current_state(_Ctx())]

    try:
        subprocess.run(['git', 'init', '-q', str(tmp)], capture_output=True, check=True)
        (tmp / 'drafts').mkdir()
        for rel in _Ctx.changed:
            (tmp / rel).write_text(marker, encoding='utf-8')
        pc.ROOT = tmp
        got = verdict([{'paths': 'drafts/**/*.md', 'reason': 'legal weight'}])
        cases.append(('a marker in a declared path passes',
                      not any(g.startswith('drafts/') for g in got), got))
        cases.append(('the same marker outside it still fires',
                      any(g.startswith('notes.md') for g in got), got))
        got = verdict([{'paths': ['drafts/*.md'], 'reason': 'legal weight'}])
        cases.append(('a list of globs is read too',
                      not any(g.startswith('drafts/') for g in got), got))
        got = verdict([{'paths': 'drafts/**/*.md'}])
        cases.append(('an entry with no reason exempts nothing and is '
                      'reported', any(g.startswith('drafts/') for g in got)
                      and 'precedent.json' in got, got))
    except (OSError, subprocess.CalledProcessError) as e:
        cases.append((f'fixture could not be built ({e})', False, ''))
    finally:
        pc.ROOT = saved
        shutil.rmtree(tmp, ignore_errors=True)
    bad = [(n, d) for n, ok, d in cases if not ok]
    check(f'docs-are-current-state honours declared load-bearing paths '
          f'({len(cases)} stated cases)', not bad,
          '; '.join(f'{n}: {d}' for n, d in bad))


def check_filename_separator_ignores_a_date_suffix():
    """A dated-download suffix (`Name-2026-06-23.docx`) is not the name's
    separator.

    2026-10-06: a consumer's file named like `Some_Name-2026-06-23.docx` was
    counted as using both "-" and "_" -- the same file on both sides of the
    finding -- because only the date was removed and its joining hyphen
    stayed. The control is a genuinely mixed pair, which must still fire."""
    import tempfile, types
    import precedent_check as pc
    cases = []
    tmp = pathlib.Path(tempfile.mkdtemp(prefix='sep-date-'))
    saved = pc.ROOT

    def verdict(names):
        d = tmp / 'docs'
        shutil.rmtree(d, ignore_errors=True)
        d.mkdir()
        for n in names:
            (d / n).write_text('x', encoding='utf-8')
        return [f.detail for f in
                pc._filename_separator(types.SimpleNamespace(root=tmp))]

    try:
        subprocess.run(['git', 'init', '-q', str(tmp)], capture_output=True, check=True)
        pc.ROOT = tmp
        got = verdict(['Service_Agreement-2026-06-23.docx',
                       'Order_Form.docx'])
        cases.append(('an underscore name with a date suffix beside another '
                      'underscore name does not fire', got == [], got))
        got = verdict(['Service_Agreement-2026-06-23.docx',
                       'order-form.docx'])
        cases.append(('CONTROL: a genuinely mixed pair still fires',
                      len(got) == 1, got))
    except (OSError, subprocess.CalledProcessError) as e:
        cases.append((f'fixture could not be built ({e})', False, ''))
    finally:
        pc.ROOT = saved
        shutil.rmtree(tmp, ignore_errors=True)
    bad = [(n, d) for n, ok, d in cases if not ok]
    check(f'filename-separator ignores a dated-download suffix '
          f'({len(cases)} stated cases)', not bad,
          '; '.join(f'{n}: {d}' for n, d in bad))

def check_todo_migrate_needs_a_migrated_item():
    """THE INCIDENT (2026-09-28, the same migration rehearsal as the case
    above). todo_migrate.py failed, build_todo_index.py then wrote its index
    over an empty todo/, and todo-migrate-available-but-unused went green:
    it asked only whether todo/ existed. Zero items had moved and every
    old-format bullet was still in TODO.md.

    Unit-level: the subject is one tree check's verdict over three layouts,
    and a whole pipeline run would only add minutes to reach it."""
    import tempfile, shutil as _shutil, json as _json
    import precedent_check as pc
    if not hasattr(pc, '_todo_migrate_available_but_unused'):
        not_applicable('todo-migrate needs a migrated item',
                       'the check is not present in this precedent_check.py')
        return

    class _Ctx:
        def read(self, rel):
            try:
                return (pc.ROOT / rel).read_text(encoding='utf-8')
            except OSError:
                return ''

    old_root, old_manifest = pc.ROOT, pc._ENGINE_MANIFEST
    tmp = pathlib.Path(tempfile.mkdtemp(prefix='precedent-todo-mig-'))
    cases = []
    try:
        (tmp / 'tools').mkdir()
        (tmp / 'tools' / 'todo_migrate.py').write_text('# vendored\n')
        (tmp / 'tools' / 'ENGINE_MANIFEST.json').write_text(
            _json.dumps({'kind': 'consumer'}))
        (tmp / 'TODO.md').write_text(
            '# Repo TODO\n\n- [ ] **An old-format item, never migrated.**\n')
        (tmp / 'todo').mkdir()
        (tmp / 'todo' / 'TODO.md').write_text('# Open items\n\n(none)\n')
        (tmp / 'todo' / 'CLOSED.md').write_text('# Closed items\n')
        pc.ROOT, pc._ENGINE_MANIFEST = tmp, None

        def verdict():
            return [str(f) for f in pc._todo_migrate_available_but_unused(_Ctx())]

        cases.append(('a todo/ holding only the generated index, with the '
                      'old bullets still in TODO.md, fires',
                      bool(verdict()), verdict()))
        (tmp / 'todo' / 'todo-2026-09-28-an-item.md').write_text('# item\n')
        cases.append(('CONTROL: one migrated todo/todo-*.md item clears it',
                      verdict() == [], verdict()))
        (tmp / 'todo' / 'todo-2026-09-28-an-item.md').unlink()
        (tmp / 'TODO.md').write_text('# TODO has moved\n\nSee todo/.\n')
        cases.append(('CONTROL: TODO.md as the redirect stub clears it',
                      verdict() == [], verdict()))
    finally:
        pc.ROOT, pc._ENGINE_MANIFEST = old_root, old_manifest
        _shutil.rmtree(tmp, ignore_errors=True)

    bad = [(c[0], c[2]) for c in cases if not c[1]]
    check(f'todo-migrate-available-but-unused wants a migrated item, not an '
          f'empty todo/ ({len(cases)} stated cases)',
          not bad, '; '.join(f'{n} -- {d}' for n, d in bad))

def check_retirement_record_is_not_a_stranded_link():
    """The document explaining a deletion may name what it deleted.

    rename-updates-links hard-coded ONE exemption -- the retirement registry
    file itself -- and nothing else, so the category stayed invisible: the one
    file the author was looking at got covered, and every other document of
    the same kind did not. A repo that retires a mechanism writes two things,
    the registry saying what went and a record saying why, and only the first
    was exempt.

    2026-09-07, a real migration retiring a vendored practice pack: four
    findings, three of them the record OF the deletion read as a reference
    left behind BY one -- a migration record's own "what was deleted" table,
    and a closed dated backlog entry quoting the notice that prompted it.
    Neither can be repointed at anything; naming the dead path is the whole
    content. The fourth was a genuine stranded reference in a merge runbook,
    telling every future session to three-way-merge a file that no longer
    existed -- the finding this check exists for, and the one the three false
    ones were burying. That is the cost of a noisy gate, not just the
    annoyance of it.

    The exemption is the registry's own `exempt_files`, which
    decommission-deletes-files and migration-scrubs-vocabulary already read.
    Same list, same reason, one more reader. It is NOT a blanket pass for any
    file mentioning a retired path: the list is written by a person at the
    moment of retirement, through precedent_decommission.py, which refuses
    while any undeclared reference remains.
    """
    import tempfile, json as _json, shutil as _shutil
    checker = ROOT / 'tools' / 'precedent_check.py'
    if not checker.exists():
        not_applicable('a retirement record may name what it deleted',
                       'tools/precedent_check.py is not present here')
        return

    def _repo(base, exempt):
        """A repo that DELETED a file on this branch, with two references
        left: one in a record (exempt) and one in a live instruction (not)."""
        base.mkdir(parents=True)
        (base / 'process').mkdir()
        (base / 'tools').mkdir()
        # Seed the real consumer engine rather than hand-picking files:
        # precedent_check.py imports several siblings, and a fixture that
        # copies only the ones somebody remembered breaks on the next import
        # added upstream -- which is how the first version of this test
        # "passed" its exemption case while the check was not running at all.
        subprocess.run(
            [sys.executable, str(ROOT / 'tools' / 'precedent_vendor_engine.py'),
             'seed', str(base), '--kind', 'consumer'],
            capture_output=True, text=True, timeout=300)
        # And the practice itself: precedent_check.py SKIPS a check whose
        # practice file is not materialized here ("belongs to a source this
        # repo does not resolve"). A skip is not a pass, and reading one as
        # the exemption working is exactly the false green this fixture has
        # to rule out.
        (base / 'practices').mkdir(exist_ok=True)
        _shutil.copy2(ROOT / 'practices' / 'rename-updates-links.md',
                      base / 'practices' / 'rename-updates-links.md')
        # AND OVERWRITE THE SEEDED CHECKER WITH THIS WORKING TREE'S.
        # precedent_vendor_engine.py seeds via `git archive`, so it copies
        # the COMMITTED engine -- which means a fixture built this way tests
        # the code as it was before your change, silently. Caught 2026-09-07
        # while making this very change: three cases went green, the
        # exemption case stayed red, and the checker in the fixture simply
        # did not contain the fix being tested.
        _shutil.copy2(checker, base / 'tools' / 'precedent_check.py')
        (base / 'precedent.json').write_text(
            _json.dumps({'format_version': 1, 'sources': [],
                         'visibility': 'private'}), encoding='utf-8')
        (base / 'process' / 'doomed.md').write_text('# doomed\n', encoding='utf-8')
        (base / 'README.md').write_text('nothing yet\n', encoding='utf-8')

        env = dict(os.environ, PRECEDENT_ALLOW_ANY_AUTHOR='1')
        def g(*a):
            return subprocess.run(['git', '-C', str(base)] + list(a),
                                  capture_output=True, text=True, env=env)
        g('init', '-q', '-b', 'main')
        g('config', 'user.email', 'h@example.com')
        g('config', 'user.name', 'H')
        g('add', '-A'); g('commit', '-qm', 'base')
        # A published default branch is what the check diffs against.
        g('branch', '-f', 'origin-main-stand-in')
        g('update-ref', 'refs/remotes/origin/main', 'HEAD')
        g('symbolic-ref', 'refs/remotes/origin/HEAD', 'refs/remotes/origin/main')

        (base / 'process' / 'doomed.md').unlink()
        (base / 'process' / 'RETIREMENT_RECORD.md').write_text(
            '# what went\n\n`process/doomed.md` -- superseded, deleted.\n',
            encoding='utf-8')
        (base / 'README.md').write_text(
            'Step 3: three-way-merge `process/doomed.md` before landing.\n',
            encoding='utf-8')
        reg = {'decommissioned': [{'path': 'process/doomed.md',
                            'reason': 'superseded whole',
                            'decommissioned_at': '2026-09-07'}]}
        if exempt:
            reg['exempt_files'] = ['process/RETIREMENT_RECORD.md']
        (base / 'process' / 'decommissioned_paths.json').write_text(
            _json.dumps(reg, indent=2), encoding='utf-8')
        g('add', '-A'); g('commit', '-qm', 'retire it')
        return base

    def _run(base):
        r = subprocess.run(
            [sys.executable, 'tools/precedent_check.py',
             '--only', 'rename-updates-links'],
            capture_output=True, text=True, cwd=str(base), timeout=300,
            env=dict(os.environ, PRECEDENT_ALLOW_ANY_AUTHOR='1'))
        return r.stdout + r.stderr

    cases = []
    with tempfile.TemporaryDirectory() as td:
        tmp = pathlib.Path(td)

        out = _run(_repo(tmp / 'exempt', exempt=True))
        cases.append(('the exempted record may name the deleted path',
                      'RETIREMENT_RECORD.md' not in out))
        cases.append(('and the genuine stranded reference is STILL reported '
                      '-- the exemption is per-file, not a blanket pass',
                      'README.md' in out))

        # NEGATIVE CONTROL. Without the exemption the same tree must flag the
        # record too: otherwise the case above would pass for any reason at
        # all, including the check never having run.
        out = _run(_repo(tmp / 'noexempt', exempt=False))
        cases.append(('without the exemption, the record IS flagged',
                      'RETIREMENT_RECORD.md' in out))
        cases.append(('and so is the live instruction, either way',
                      'README.md' in out))

    failed = [n for n, ok in cases if not ok]
    check(f'a retirement record may name what it deleted, and only it '
          f'({len(cases)} stated cases)', not failed, '; '.join(failed))


def check_shipped_hooks_pass_rename_links_without_the_mirror():
    """Every hook BestPractice ships passes rename-updates-links in a
    consumer whose process/upstream/tools/ was just deleted.

    2026-10-01, from a consumer's Update Vendors: the shipped
    freshness-guard.sh and the individual-source bootstrap still fell back
    to process/upstream/tools/X, the check refused the fallback lines, and
    the update rewrote the hooks on every run, so a consumer could not fix
    them and re-run. The hooks now name only tools/X, and the check counts
    "$ROOT/tools/X" as this repo's own. Run as a repository runs it: the
    mirror committed, then deleted in the change that installs every
    shipped hook. CONTROLS: an unguarded call to the deleted path is still
    refused, and a consumer's own guarded loop of the same shape is spared."""
    import tempfile, json as _json, shutil as _shutil
    checker = ROOT / 'tools' / 'precedent_check.py'
    name = ('every shipped hook passes rename-updates-links in a consumer '
            'with no process/upstream/tools/')
    hooks = sorted((ROOT / 'templates' / 'harness' / 'claude-code' / 'hooks').glob('*'))
    if not checker.exists() or not hooks:
        not_applicable(name, 'no checker or no shipped hooks here')
        return
    tools = ('precedent_identity.py', 'precedent_branches.py', 'precedent_resolve.py',
             'precedent_source_bootstrap.py', 'precedent_source_credentials.py')
    with tempfile.TemporaryDirectory() as td:
        base = pathlib.Path(td) / 'repo'
        (base / 'process' / 'upstream' / 'tools').mkdir(parents=True)
        (base / 'tools').mkdir()
        subprocess.run(
            [sys.executable, str(ROOT / 'tools' / 'precedent_vendor_engine.py'),
             'seed', str(base), '--kind', 'consumer'],
            capture_output=True, text=True, timeout=300)
        (base / 'practices').mkdir(exist_ok=True)
        _shutil.copy2(ROOT / 'practices' / 'rename-updates-links.md',
                      base / 'practices' / 'rename-updates-links.md')
        _shutil.copy2(checker, base / 'tools' / 'precedent_check.py')
        (base / 'precedent.json').write_text(
            _json.dumps({'format_version': 1, 'sources': [],
                         'visibility': 'private'}), encoding='utf-8')
        for t in tools:
            (base / 'process' / 'upstream' / 'tools' / t).write_text('', encoding='utf-8')
            (base / 'tools' / t).write_text('', encoding='utf-8')
        env = dict(os.environ, PRECEDENT_ALLOW_ANY_AUTHOR='1')

        def g(*a):
            return subprocess.run(['git', '-C', str(base), *a],
                                  capture_output=True, text=True, env=env)
        g('init', '-q', '-b', 'main')
        g('config', 'user.email', 'h@example.com')
        g('config', 'user.name', 'H')
        g('add', '-A'); g('commit', '-qm', 'base: the mirror still there')
        g('update-ref', 'refs/remotes/origin/main', 'HEAD')
        g('symbolic-ref', 'refs/remotes/origin/HEAD', 'refs/remotes/origin/main')
        _shutil.rmtree(base / 'process' / 'upstream' / 'tools')
        (base / '.claude' / 'hooks').mkdir(parents=True, exist_ok=True)
        for h in hooks:
            _shutil.copy2(h, base / '.claude' / 'hooks' / h.name.replace('.template', ''))
        (base / 'scripts').mkdir()
        (base / 'scripts' / 'unguarded.sh').write_text(
            'python3 process/upstream/tools/precedent_identity.py --commit-env .\n',
            encoding='utf-8')
        (base / 'scripts' / 'own_loop.sh').write_text(
            'for c in "$ROOT/tools/precedent_branches.py" '
            '"$ROOT/process/upstream/tools/precedent_branches.py"; do\n'
            '  [ -f "$c" ] && break\ndone\n', encoding='utf-8')
        g('add', '-A'); g('commit', '-qm', 'drop the mirror, install the hooks')
        r = subprocess.run(
            [sys.executable, 'tools/precedent_check.py',
             '--only', 'rename-updates-links'],
            capture_output=True, text=True, cwd=str(base), timeout=300, env=env)
        out = r.stdout + r.stderr
    flagged = sorted({l.split(':')[0].strip() for l in out.splitlines()
                      if '.claude/hooks/' in l and 'process/upstream/tools/' in l})
    cases = [
        ('no shipped hook is refused', not flagged, ', '.join(flagged)),
        ('CONTROL: an unguarded call to the deleted path is still refused',
         'scripts/unguarded.sh' in out, ''),
        ("a consumer's own guarded loop rooted at \"$ROOT/tools/X\" is spared",
         'scripts/own_loop.sh' not in out, ''),
    ]
    bad = [(n, d) for n, ok, d in cases if not ok]
    check(f'{name} ({len(cases)} stated cases)', not bad,
          '; '.join(f'{n} {d}' for n, d in bad) + ('' if not bad else f' -- {out[-800:]}'))


def check_rename_links_spares_a_commit_pinned_permalink():
    """A permalink pinned to a 40-hex commit is how a file that no longer
    exists is cited correctly: it names the file as it was, and cannot go
    stale. rename-updates-links read the path inside one as a reference
    left behind and refused the deletion (a consumer report, 2026-09-28).

    Three references to one deleted path in one fixture: inside a
    commit-pinned permalink (spared), inside a link to a branch (still
    reported -- a branch moves), and bare in prose (still reported). The
    last two are the control: without them a check that stopped running
    would pass the first case.
    """
    import tempfile, json as _json, shutil as _shutil
    checker = ROOT / 'tools' / 'precedent_check.py'
    name = 'rename-updates-links spares a commit-pinned permalink'
    if not checker.exists():
        not_applicable(name, 'tools/precedent_check.py is not present here')
        return
    sha = 'a' * 40
    pages = {
        'PINNED.md': f'Cited: https://github.com/fixture/repo/blob/{sha}/'
                     f'process/doomed.md#L3\n',
        'BRANCH.md': 'See https://github.com/fixture/repo/blob/main/'
                     'process/doomed.md\n',
        'PROSE.md': 'Step 3: read `process/doomed.md` first.\n',
    }
    with tempfile.TemporaryDirectory() as td:
        base = pathlib.Path(td) / 'repo'
        (base / 'process').mkdir(parents=True)
        (base / 'tools').mkdir()
        # Seeded, then overwritten with this tree's checker -- seeding copies
        # the COMMITTED engine (see check_retirement_record_is_not_a_stranded_link).
        subprocess.run(
            [sys.executable, str(ROOT / 'tools' / 'precedent_vendor_engine.py'),
             'seed', str(base), '--kind', 'consumer'],
            capture_output=True, text=True, timeout=300)
        (base / 'practices').mkdir(exist_ok=True)
        _shutil.copy2(ROOT / 'practices' / 'rename-updates-links.md',
                      base / 'practices' / 'rename-updates-links.md')
        _shutil.copy2(checker, base / 'tools' / 'precedent_check.py')
        (base / 'precedent.json').write_text(
            _json.dumps({'format_version': 1, 'sources': [],
                         'visibility': 'private'}), encoding='utf-8')
        (base / 'process' / 'doomed.md').write_text('# doomed\n', encoding='utf-8')
        env = dict(os.environ, PRECEDENT_ALLOW_ANY_AUTHOR='1')

        def g(*a):
            return subprocess.run(['git', '-C', str(base), *a],
                                  capture_output=True, text=True, env=env)
        g('init', '-q', '-b', 'main')
        g('config', 'user.email', 'h@example.com')
        g('config', 'user.name', 'H')
        g('add', '-A'); g('commit', '-qm', 'base')
        g('update-ref', 'refs/remotes/origin/main', 'HEAD')
        g('symbolic-ref', 'refs/remotes/origin/HEAD', 'refs/remotes/origin/main')
        (base / 'process' / 'doomed.md').unlink()
        for page, text in pages.items():
            (base / page).write_text(text, encoding='utf-8')
        g('add', '-A'); g('commit', '-qm', 'delete it, cite it three ways')
        r = subprocess.run(
            [sys.executable, 'tools/precedent_check.py',
             '--only', 'rename-updates-links'],
            capture_output=True, text=True, cwd=str(base), timeout=300, env=env)
        out = r.stdout + r.stderr
    cases = [
        ('the path inside a commit-pinned permalink is not reported',
         'PINNED.md' not in out),
        ('the path inside a link to a branch is still reported',
         'BRANCH.md' in out),
        ('the bare path in prose is still reported', 'PROSE.md' in out),
    ]
    failed = [n for n, ok in cases if not ok]
    check(f'{name} ({len(cases)} stated cases)', not failed,
          '; '.join(failed) + ('' if not failed else f' -- {out[-600:]}'))


def _changed_files_fixture(tmp):
    """-> (repo, run) for precedent_push_check.changed_files_check against a
    consumer-shaped repo at `tmp`, run in-process: the script's own main()
    always judges the checkout it lives in, never the fixture."""
    import contextlib, io
    repo = tmp / 'repo'
    repo.mkdir(parents=True)
    env = dict(os.environ, GIT_AUTHOR_NAME='t', GIT_AUTHOR_EMAIL='t@t',
               GIT_COMMITTER_NAME='t', GIT_COMMITTER_EMAIL='t@t')

    def git(*a):
        return subprocess.run(['git', '-C', str(repo), '-c',
                               'core.hooksPath=/dev/null', *a],
                              capture_output=True, text=True, env=env)
    git('init', '-q', '-b', 'main')
    (repo / 'README.md').write_text('fixture\n', encoding='utf-8')
    git('add', '-A'); git('commit', '-qm', 'base')
    since = git('rev-parse', 'HEAD').stdout.strip()
    spec = importlib.util.spec_from_file_location(
        'ppc_fixture', ROOT / 'tools' / 'precedent_push_check.py')
    ppc = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(ppc)

    def commit(files):
        for rel, text in files.items():
            (repo / rel).parent.mkdir(parents=True, exist_ok=True)
            (repo / rel).write_text(text, encoding='utf-8')
        git('add', '-A'); git('commit', '-qm', 'fixture change')

    def run():
        buf = io.StringIO()
        with contextlib.redirect_stdout(buf):
            rc = ppc.changed_files_check(repo, since)
        return rc, buf.getvalue()
    return commit, run


