def check_doc_sync_ledger():
    """doc_sync's ledger skips a block whose code fingerprint, recorded reads
    and output all still hold, and re-emits it when any of the three moves.
    Built in a scratch repository with one script and one document; the
    script counts its own emits in a file the hook does not track (a write,
    not a read)."""
    name = ('doc_sync skips an unchanged block (and one whose self-check alone changed) and '
            're-emits one whose code, data or text moved')
    engine = ROOT / 'tools' / 'doc_sync.py'
    rk = ROOT / 'tools' / 'reach_key.py'
    if not engine.is_file() or not rk.is_file():
        not_applicable(name, 'tools/doc_sync.py or tools/reach_key.py is absent')
        return
    import tempfile as _tf
    bad = []
    with _tf.TemporaryDirectory() as d:
        d = pathlib.Path(d)
        (d / '.git').mkdir()
        (d / 'tools').mkdir()
        shutil.copy2(engine, d / 'tools' / 'doc_sync.py')
        shutil.copy2(rk, d / 'tools' / 'reach_key.py')
        # everything doc_sync imports beside it (generated_blocks since staging's shared marker reader)
        for f in ('fact_ledger.py', 'content_record.py', 'generated_blocks.py'):
            if (ROOT / 'tools' / f).is_file():
                shutil.copy2(ROOT / 'tools' / f, d / 'tools' / f)
        (d / 'data.txt').write_text('7\n')
        model = (
            'import os, sys\n'
            'def value():\n'
            '    here = __file__.rsplit("/", 1)[0]\n'
            '    extra = (1 if os.path.exists(here + "/FLAG") else 0) + int(os.environ.get("TOY_FLAG", "0"))\n'
            '    return int(open(here + "/data.txt").read()) * 2 + extra\n'
            'def unrelated():\n'
            '    return 1\n'
            'def emit_table():\n'
            '    open(__file__.rsplit("/", 1)[0] + "/emits.log", "a").write("x")\n'
            '    return f"| v |\\n|---|\\n| {value()} |"\n'
            'def self_check():\n'
            '    return value() == 14\n'
            'EMITTERS = {"table": emit_table}\n'
            'if __name__ == "__main__":\n'
            '    if len(sys.argv) == 3 and sys.argv[1] == "--emit":\n'
            '        print(EMITTERS[sys.argv[2]]())\n'
            '        sys.exit(0)\n'
            '    if len(sys.argv) == 2 and sys.argv[1] == "--self-check":\n'
            '        sys.exit(0 if self_check() else 1)\n'
        )
        (d / 'model.py').write_text(model)
        (d / 'doc.md').write_text('# Doc\n\n<!--gen:table-->\n<!--/gen:table-->\n\nNumbers by: model.py\n')
        (d / 'shim.py').write_text(
            'import importlib.util, sys\n'
            'spec = importlib.util.spec_from_file_location("ds_engine", "tools/doc_sync.py")\n'
            'e = importlib.util.module_from_spec(spec); spec.loader.exec_module(e)\n'
            'e.PAIRS = [("doc.md", "table", "model.py")]\n'
            'e.LEDGER = "ledger.jsonl"\n'
            'e.DOC_GLOB = "*.md"\n'
            'e.main()\n')

        toy_env = {}

        def gate(*extra):
            env = {k: v for k, v in os.environ.items() if k not in ('PYTHONNOUSERSITE', 'TOY_FLAG')}
            env.update(toy_env)
            p = subprocess.run([sys.executable, 'shim.py', *extra], cwd=d, capture_output=True,
                               text=True, env=env)
            return p.returncode, p.stdout + p.stderr

        def emits():
            f = d / 'emits.log'
            return len(f.read_text()) if f.is_file() else 0
        rc, out = gate('--write')
        if rc != 0 or '| 14 |' not in (d / 'doc.md').read_text():
            bad.append(f'the first --write did not fill the block: {out[-300:]}')
        if not (d / 'ledger.jsonl').is_file():
            bad.append('no ledger fact was recorded')
        n = emits()
        steps = [
            ('an unchanged tree', lambda: None, False, 0),
            ('a function the emit never calls', lambda: (d / 'model.py').write_text(
                (d / 'model.py').read_text().replace('return 1', 'return 2')), False, 0),
            # the dispatch branch an --emit run cannot take (a self-check, a
            # smoke mode) is left out of the block's fingerprint
            ('the self-check the emit never runs', lambda: (d / 'model.py').write_text(
                (d / 'model.py').read_text().replace('value() == 14', 'value() >= 14')), False, 0),
            ('a function the emit calls (same output)', lambda: (d / 'model.py').write_text(
                (d / 'model.py').read_text().replace('* 2 + extra', '* 2 + 0 + extra')), True, 0),
            ('a data file the emit read', lambda: (d / 'data.txt').write_text('8\n'), True, 1),
            ('a hand edit inside the block', lambda: (d / 'doc.md').write_text(
                (d / 'doc.md').read_text().replace('| 16 |', '| 99 |')), True, 1),
            # what no open() shows: a file the emit only tests for, and an
            # environment variable it reads
            ('a file the emit tests for appearing', lambda: (d / 'FLAG').write_text(''), True, 1),
            ('an environment variable the emit reads', lambda: toy_env.update(TOY_FLAG='3'), True, 1),
            # the emitter table rebound outside its literal: the block's key
            # must cover the new entry
            ('the emitter table rebound by |=', lambda: (d / 'model.py').write_text(
                (d / 'model.py').read_text().replace(
                    'EMITTERS = {"table": emit_table}\n',
                    'EMITTERS = {"table": emit_table}\ndef emit_other():\n    return emit_table() + " "\n'
                    'EMITTERS |= {"table": emit_other}\n')), True, 1),
        ]
        for what, edit, should_emit, should_fail in steps:
            edit()
            rc, out = gate()
            ran = emits() > n
            n = emits()
            if ran != should_emit:
                bad.append(f'{what}: the block {"was" if ran else "was not"} emitted')
            if bool(rc) != bool(should_fail):
                bad.append(f'{what}: the gate exited {rc}')
            if should_fail:
                gate('--write')
                n = emits()
    check(name, not bad, '; '.join(bad))


def check_doc_sync_fails_fast():
    """doc_sync runs emits concurrently; the first one that fails stops the
    rest and the gate exits at once, instead of waiting for the slowest
    emit beside it (origin 2026-09-28: a script that crashed in its first
    second was reported fourteen minutes later, twice). A scratch repository
    with one emit that sleeps a minute and one that fails."""
    name = 'doc_sync stops every other emit when one fails'
    engine = ROOT / 'tools' / 'doc_sync.py'
    if not engine.is_file():
        not_applicable(name, 'tools/doc_sync.py is absent')
        return
    import tempfile as _tf
    with _tf.TemporaryDirectory() as d:
        d = pathlib.Path(d)
        (d / '.git').mkdir()
        (d / 'tools').mkdir()
        shutil.copy2(engine, d / 'tools' / 'doc_sync.py')
        for f in ('reach_key.py', 'fact_ledger.py', 'content_record.py', 'generated_blocks.py'):
            if (ROOT / 'tools' / f).is_file():
                shutil.copy2(ROOT / 'tools' / f, d / 'tools' / f)
        (d / 'slow.py').write_text('import time\ntime.sleep(60)\nprint("x")\n')
        (d / 'bad.py').write_text('import time\ntime.sleep(1)\nraise SystemExit("broken")\n')
        (d / 'doc.md').write_text('<!--gen:a-->\n<!--/gen:a-->\n<!--gen:b-->\n<!--/gen:b-->\n'
                                  'Numbers by: slow.py bad.py\n')
        (d / 'shim.py').write_text(
            'import importlib.util\n'
            'spec = importlib.util.spec_from_file_location("ds_engine", "tools/doc_sync.py")\n'
            'e = importlib.util.module_from_spec(spec); spec.loader.exec_module(e)\n'
            'e.PAIRS = [("doc.md", "a", "slow.py"), ("doc.md", "b", "bad.py")]\n'
            'e.DOC_GLOB = "*.md"\n'
            'e.main()\n')
        t0 = time.time()
        p = subprocess.run([sys.executable, 'shim.py'], cwd=d, capture_output=True, text=True,
                           env={**os.environ, 'DOC_SYNC_JOBS': '2'}, timeout=120)
        took = time.time() - t0
    check(name, p.returncode != 0 and took < 20 and 'bad.py' in p.stderr,
          f'exit {p.returncode} after {took:.0f}s: {(p.stdout + p.stderr).strip()[-300:]}')


def check_model_audit_ledger():
    """model_audit with a ledger audits each model in its own process and
    records a fact for a clean audit; a model whose fact holds is not run
    again, a change to its self-check or to a file it read runs it, and a
    failing audit is never recorded. A scratch repository with one model
    that counts its own runs."""
    name = 'model_audit skips a model whose clean audit still holds, and re-runs a changed one'
    engine = ROOT / 'tools' / 'model_audit.py'
    needs = [engine, ROOT / 'tools' / 'fact_ledger.py', ROOT / 'tools' / 'reach_key.py',
             ROOT / 'tools' / 'content_record.py']
    if not all(p.is_file() for p in needs):
        not_applicable(name, 'model_audit.py, fact_ledger.py, content_record.py or reach_key.py is absent')
        return
    import tempfile as _tf
    bad = []
    with _tf.TemporaryDirectory() as d:
        d = pathlib.Path(d)
        (d / '.git').mkdir()
        (d / 'tools').mkdir()
        for p in needs:
            shutil.copy2(p, d / 'tools' / p.name)
        (d / 'limit.txt').write_text('10\n')
        (d / 'model.py').write_text(
            'import os\n'
            'def value():\n'
            '    return 3\n'
            'def self_check():\n'
            '    open(os.path.join(os.path.dirname(__file__), "runs.log"), "a").write("x")\n'
            '    lim = int(open(os.path.join(os.path.dirname(__file__), "limit.txt")).read())\n'
            '    return [] if value() < lim else ["value over the limit"]\n')
        (d / 'shim.py').write_text(
            'import importlib.util, sys\n'
            'spec = importlib.util.spec_from_file_location("ma_engine", "tools/model_audit.py")\n'
            'e = importlib.util.module_from_spec(spec); spec.loader.exec_module(e)\n'
            'e.INSTRUMENTED = ["model.py"]\n'
            'e.LEDGER = "audit.jsonl"\n'
            'sys.exit(e.main())\n')

        def audit():
            p = subprocess.run([sys.executable, 'shim.py'], cwd=d, capture_output=True, text=True)
            return p.returncode

        def runs():
            f = d / 'runs.log'
            return len(f.read_text()) if f.is_file() else 0
        steps = [
            ('the first audit', lambda: None, True, 0),
            ('an unchanged tree', lambda: None, False, 0),
            ('a comment in the model', lambda: (d / 'model.py').write_text(
                '# a note\n' + (d / 'model.py').read_text()), False, 0),
            ('a function the self-check calls', lambda: (d / 'model.py').write_text(
                (d / 'model.py').read_text().replace('return 3', 'return 4')), True, 0),
            ('a file the self-check read (now failing)', lambda: (d / 'limit.txt').write_text('2\n'), True, 1),
            ('the same failing tree again', lambda: None, True, 1),
        ]
        n = 0
        for what, edit, should_run, should_fail in steps:
            edit()
            rc = audit()
            ran = runs() > n
            n = runs()
            if ran != should_run:
                bad.append(f'{what}: the model {"was" if ran else "was not"} audited')
            if bool(rc) != bool(should_fail):
                bad.append(f'{what}: the audit exited {rc}')
    check(name, not bad, '; '.join(bad))


def check_full_tier_needs_a_reason_on_a_quick_landing():
    """`--tier full` is refused where the landing branch takes the quick
    tier, unless a reason is given (Morgan, 2026-10-01, strength: decided:
    "Go, do both, then Booked"). The same day the bare run was fixed, a
    session still typed `--tier full` before every pre-staging landing and
    wrote it into its helpers' briefs. Stated cases: refused on a
    pre-staging landing; allowed with --because; untouched for --gate, for
    a named push, and on a landing branch that is fully checked."""
    import tempfile
    import precedent_push_check as ppc
    tmp = pathlib.Path(tempfile.mkdtemp(prefix='full-tier-reason-'))
    saved = os.environ.get('PRECEDENT_USER_CONFIG')
    os.environ['PRECEDENT_USER_CONFIG'] = str(tmp / 'no-config.json')
    cases = []
    try:
        subprocess.run(['git', 'init', '-q', str(tmp)], capture_output=True)

        def landing(branch):
            (tmp / 'precedent.json').write_text(json.dumps(
                {'base_branch': 'main', 'landing_branch': branch}), encoding='utf-8')
        landing('pre-staging')
        full = ['--tier', 'full']
        cases.append(('refused on a pre-staging landing',
                      bool(ppc._full_tier_refusal(tmp, full)), ''))
        cases.append(('...and the refusal says how to ask anyway',
                      '--because' in (ppc._full_tier_refusal(tmp, full) or ''), ''))
        for extra in (['--because', 'testing'], ['--gate'],
                      ['--push-command', 'origin HEAD:staging']):
            cases.append((f'allowed with {extra[0]}',
                          ppc._full_tier_refusal(tmp, full + extra) is None, ''))
        cases.append(('--tier basic is never refused',
                      ppc._full_tier_refusal(tmp, ['--tier', 'basic']) is None, ''))
        cases.append(('--because is a known option',
                      ppc.unknown_arguments(full + ['--because', 'x']) == [], ''))
        landing('main')
        cases.append(('a landing branch that is fully checked is untouched',
                      ppc._full_tier_refusal(tmp, full) is None, ''))
    finally:
        if saved is None:
            os.environ.pop('PRECEDENT_USER_CONFIG', None)
        else:
            os.environ['PRECEDENT_USER_CONFIG'] = saved
        shutil.rmtree(tmp, ignore_errors=True)
    bad = [(n, d) for n, ok, d in cases if not ok]
    check(f'--tier full needs a reason where the landing branch is quick '
          f'({len(cases)} stated cases)', not bad,
          '; '.join(f'{n}: {d}' for n, d in bad))


def check_bare_push_check_takes_the_landing_tier():
    """precedent_push_check.py run with no destination checks what a push
    to the person's landing branch gets (Morgan, 2026-10-01, strength:
    assented). A session ran it bare before every landing on pre-staging
    and paid the ~11-minute suite each time. Stated cases: bare, with a
    pre-staging landing, it becomes a push to pre-staging at the basic
    tier; a staging landing still runs full; --tier full and a named push
    are left exactly as given."""
    import contextlib, io, tempfile
    import precedent_push_check as ppc
    tmp = pathlib.Path(tempfile.mkdtemp(prefix='bare-push-check-'))
    saved = os.environ.get('PRECEDENT_USER_CONFIG')
    os.environ['PRECEDENT_USER_CONFIG'] = str(tmp / 'no-config.json')
    cases = []
    try:
        subprocess.run(['git', 'init', '-q', str(tmp)], capture_output=True)

        def landing(branch):
            (tmp / 'precedent.json').write_text(json.dumps(
                {'base_branch': 'main', 'landing_branch': branch}), encoding='utf-8')
        landing('pre-staging')
        with contextlib.redirect_stdout(io.StringIO()):
            argv = ppc._default_destination(tmp, [])
        cases.append(('bare, it names a push to the landing branch',
                      argv == ['--push-command', 'origin HEAD:pre-staging'], str(argv)))
        cases.append(('...which is the basic tier',
                      ppc._tier_from_args(tmp, argv)[0] == ppc.BASIC,
                      str(ppc._tier_from_args(tmp, argv))))
        landing('main')
        with contextlib.redirect_stdout(io.StringIO()):
            argv = ppc._default_destination(tmp, [])
        cases.append(('a landing branch that is fully checked still runs full',
                      ppc._tier_from_args(tmp, argv)[0] == ppc.FULL,
                      str(ppc._tier_from_args(tmp, argv))))
        for given in (['--tier', 'full'], ['--push-command', 'origin x']):
            cases.append((f'{given} is left as given',
                          ppc._default_destination(tmp, list(given)) == given, ''))
    finally:
        if saved is None:
            os.environ.pop('PRECEDENT_USER_CONFIG', None)
        else:
            os.environ['PRECEDENT_USER_CONFIG'] = saved
        shutil.rmtree(tmp, ignore_errors=True)
    bad = [(n, d) for n, ok, d in cases if not ok]
    check(f'a bare push check takes the landing branch\'s tier '
          f'({len(cases)} stated cases)', not bad,
          '; '.join(f'{n}: {d}' for n, d in bad))


def check_wait_loop_gate_refuses_pgrep_f():
    """wait-loop-gate.sh refuses a Bash command running `pgrep -f` or
    `pkill -f`, and nothing else (2026-10-01: a wait loop on `pgrep -f`
    matched its own shell and ran 20 minutes past the check it waited for;
    Morgan asked for a wall). Runs the real hook, both copies, on payloads."""
    cases = []
    refused = ['while pgrep -f "tools/x.py" >/dev/null; do sleep 5; done',
               'pkill -f tools/x', 'pgrep -fa x', 'echo hi; pgrep --full x',
               'sleep 1 && pkill -af y']
    allowed = ['grep -n "pgrep -f" file', 'pgrep python3', 'ls -la',
               "git commit -m 'stop using pkill -f'", 'ps -ef | grep x']
    for rel in ('.claude/hooks/wait-loop-gate.sh',
                'templates/harness/claude-code/hooks/wait-loop-gate.sh'):
        hook = ROOT / rel
        for cmd, want in [(c, True) for c in refused] + [(c, False) for c in allowed]:
            r = subprocess.run(['bash', str(hook)], input=json.dumps(
                {'tool_input': {'command': cmd}}), capture_output=True, text=True,
                timeout=30)
            denied = '"deny"' in r.stdout
            cases.append((f'{rel}: {cmd!r} {"refused" if want else "allowed"}',
                          r.returncode == 0 and denied == want, r.stdout[-200:]))
    settings = json.loads((ROOT / 'templates' / 'harness' / 'claude-code'
                           / 'settings.json').read_text(encoding='utf-8'))
    wired = any('wait-loop-gate.sh' in h.get('command', '')
                for e in settings['hooks'].get('PreToolUse', [])
                if e.get('matcher') == 'Bash' for h in e.get('hooks', []))
    cases.append(('the template settings wire it on PreToolUse Bash', wired, ''))
    bad = [(n, d) for n, ok, d in cases if not ok]
    check(f'wait-loop-gate.sh refuses pgrep -f and pkill -f, and nothing else '
          f'({len(cases)} stated cases)', not bad,
          '; '.join(f'{n}: {d}' for n, d in bad))


def check_push_check_refuses_an_unknown_option():
    """precedent_push_check.py refuses an option it does not know, exit 2,
    naming the ones it does -- and still takes every one it reads.

    Found 2026-09-30: the pull request template named
    `precedent_push_check.py --changed-files-only`, an option this file
    never had. It was ignored silently and the full ~14-minute suite ran,
    twice, where a seconds-long pre-staging check was meant."""
    import precedent_push_check as ppc
    t0 = time.time()
    r = subprocess.run([sys.executable, str(ROOT / 'tools' / 'precedent_push_check.py'),
                        '--changed-files-only'], capture_output=True, text=True,
                       cwd=str(ROOT), timeout=60)
    cases = [
        ('an unknown option exits 2', r.returncode == 2, str(r.returncode)),
        ('and names itself and the valid ones',
         '--changed-files-only' in r.stderr and '--push-command' in r.stderr,
         r.stderr[-300:]),
        ('and runs nothing', time.time() - t0 < 30 and 'passed in' not in r.stdout,
         r.stdout[-200:]),
        ('the hook\'s own arguments are all known',
         ppc.unknown_arguments(['--gate', '--push-command', 'origin pre-staging']) == [], ''),
        ('--changed-files-check takes its REF, or none',
         ppc.unknown_arguments(['--changed-files-check', 'origin/x', '--list']) == []
         and ppc.unknown_arguments(['--changed-files-check', '--gate']) == [], ''),
        ('the merge gate\'s arguments are all known',
         ppc.unknown_arguments(['--gate', '--tier', 'full']) == []
         and ppc.unknown_arguments(['--changed-since', 'origin/pre-staging']) == [], ''),
        ('a stray positional is refused too',
         ppc.unknown_arguments(['--gate', 'oops']) == ['oops'], ''),
    ]
    failed = [f'{n} ({d})' for n, ok, d in cases if not ok]
    check(f'precedent_push_check.py refuses an unknown option ({len(cases)} stated cases)',
          not failed, '; '.join(failed))


def check_push_check_runs_cheap_checks_first():
    """precedent_push_check.run() moves the slow checks (the harness suite,
    the deep-check suites) behind every fast one, and skips them once a fast
    one has failed -- the push is refused either way. Origin 2026-09-28: a
    merge gate spent ten minutes on the harness suite before reporting stale
    generated views, a one-second finding, then ten more on the fixed push.
    Asserted on the function itself, with stand-in checks that record the
    order they ran in."""
    name = 'the push check runs its slow checks last, and not after a fast failure'
    tool = ROOT / 'tools' / 'precedent_push_check.py'
    if not tool.is_file():
        not_applicable(name, 'precedent_push_check.py is absent')
        return
    spec = importlib.util.spec_from_file_location('ppc_cheap_first', tool)
    mod = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(mod)
    import tempfile as _tf
    bad = []
    with _tf.TemporaryDirectory() as d:
        d = pathlib.Path(d)
        log = d / 'order.txt'
        def stand_in(label, code):
            f = d / f'{label}.py'
            f.write_text(f'open({str(log)!r}, "a").write({label!r} + "\\n")\n'
                         f'raise SystemExit({code})\n')
            return (label, [sys.executable, str(f)], 'stand-in')
        checks = [stand_in('verify_harness', 0), stand_in('fast_ok', 0), stand_in('fast_bad', 1),
                  stand_in('deep_check', 0)]
        env_all = os.environ.pop('PRECEDENT_PUSH_CHECK_ALL', None)
        try:
            import contextlib as _cl, io as _io
            with _cl.redirect_stdout(_io.StringIO()):
                failed, _m, _t, _f = mod.run(d, checks)
            ran = log.read_text().split()
            if ran != ['fast_ok', 'fast_bad']:
                bad.append(f'with a fast failure, ran {ran}, expected the fast checks only')
            if failed != ['fast_bad']:
                bad.append(f'reported {failed} as failed')
            log.unlink()
            os.environ['PRECEDENT_PUSH_CHECK_ALL'] = '1'
            with _cl.redirect_stdout(_io.StringIO()):
                mod.run(d, checks)
            ran = log.read_text().split()
            if ran != ['fast_ok', 'fast_bad', 'verify_harness', 'deep_check']:
                bad.append(f'under PRECEDENT_PUSH_CHECK_ALL=1, ran {ran}')
        finally:
            os.environ.pop('PRECEDENT_PUSH_CHECK_ALL', None)
            if env_all is not None:
                os.environ['PRECEDENT_PUSH_CHECK_ALL'] = env_all
    check(name, not bad, '; '.join(bad))


def check_push_check_records_over_its_own_ledgers():
    """A push-check run that refreshes a fact ledger (practice: gate-ledger)
    still records its pass for the commit, and leaves the ledger in place;
    real uncommitted work still blocks the record.

    Origin 2026-10-02, a consumer repository: the model audit rewrote its
    ledger as the full suite ran, the suite passed in 799 s over a tree it
    had dirtied itself, the pass was NOT recorded, and the push gate ran
    the whole suite again and timed out -- twice. The fixture's doc_lint
    stand-in saves a ledger through the real fact_ledger.py, so the run
    dirties its own tree exactly that way. The negative control is the same
    run with an ordinary tracked file edited. Owns its state (practice:
    fixture-owns-its-state)."""
    import tempfile, json as _json, shutil as _shutil
    name = 'the push check records its pass over fact ledgers it refreshed itself'
    tool = ROOT / 'tools' / 'precedent_push_check.py'
    needed = [tool, ROOT / 'tools' / 'fact_ledger.py', ROOT / 'tools' / 'content_record.py']
    if not all(f.is_file() for f in needed):
        not_applicable(name, 'precedent_push_check.py or the fact ledger engine is absent')
        return
    cases = []
    with tempfile.TemporaryDirectory() as td:
        tmp = pathlib.Path(td)
        env = dict(os.environ, PRECEDENT_ALLOW_ANY_AUTHOR='1', PRECEDENT_NO_SHARED_PASS='1',
                   GIT_AUTHOR_NAME='T', GIT_AUTHOR_EMAIL='t@example.com',
                   GIT_COMMITTER_NAME='T', GIT_COMMITTER_EMAIL='t@example.com',
                   GIT_CONFIG_GLOBAL=str(tmp / 'gitconfig'),
                   PRECEDENT_USER_CONFIG=str(tmp / 'no-user-config.json'))
        env.pop('FACT_LEDGER_WRITTEN', None)

        def git(*a):
            return subprocess.run(['git', '-C', str(work), *a], capture_output=True,
                                  text=True, env=env).stdout.strip()

        work = tmp / 'work'
        (work / 'tools').mkdir(parents=True)
        subprocess.run(['git', 'init', '-q', '-b', 'main', str(work)], env=env,
                       capture_output=True)
        for f in needed + [ROOT / 'tools' / 'precedent_branches.py']:
            if f.is_file():
                _shutil.copy2(f, work / 'tools' / f.name)
        (work / 'tools' / 'ENGINE_MANIFEST.json').write_text(
            _json.dumps({'kind': 'consumer'}), encoding='utf-8')
        for t in ('precedent_check', 'leak_gate', 'doc_lint'):
            body = 'import sys\n'
            if t == 'precedent_check':
                body += 'print("precedent_check: 3 passed, 0 violated")\n'
            if t == 'doc_lint':
                # a gate that refreshes its fact ledger as it runs, as the
                # model audit and doc_sync do
                body += ('import importlib.util, pathlib, time\n'
                         'here = pathlib.Path(__file__).resolve().parent\n'
                         'spec = importlib.util.spec_from_file_location("fl", here / "fact_ledger.py")\n'
                         'fl = importlib.util.module_from_spec(spec); spec.loader.exec_module(fl)\n'
                         'led = fl.Ledger(here.parent, "audit_ledger.jsonl")\n'
                         'led.put({"doc": "m.py", "block": "#audit", "at": time.time_ns()})\n'
                         'led.save()\n')
            body += 'sys.exit(0)\n'
            (work / 'tools' / f'{t}.py').write_text(body, encoding='utf-8')
        (work / 'audit_ledger.jsonl').write_text('', encoding='utf-8')
        (work / 'notes.txt').write_text('a\n', encoding='utf-8')
        git('add', '-A')
        git('commit', '-q', '-m', 'init')
        record = work / '.git' / 'precedent-push-check.json'

        def run_check(*a):
            p = subprocess.run([sys.executable, 'tools/precedent_push_check.py', *a],
                               cwd=work, capture_output=True, text=True, env=env)
            return p.stdout + p.stderr

        out = run_check('--tier', 'full')
        dirty = git('status', '--porcelain', '--untracked-files=no')
        cases.append(('the run dirtied its own tree with the ledger (the bug\'s '
                      'precondition)', dirty.endswith('audit_ledger.jsonl')))
        cases.append(('and still recorded the pass for the commit',
                      'recorded for tree' in out and 'NOT recorded' not in out
                      and record.is_file()))
        cases.append(('saying it refreshed the ledger and left it to commit',
                      'refreshed 1 fact ledger' in out and 'audit_ledger.jsonl' in out))
        cases.append(('the refreshed ledger is left in place, not discarded',
                      bool((work / 'audit_ledger.jsonl').read_text().strip())))
        out = run_check('--gate', '--tier', 'full')
        cases.append(('the push gate then finds the pass, the ledger still '
                      'uncommitted, and runs nothing', 'already passed' in out))

        # Negative control: real uncommitted work blocks the record, before
        # or after a ledger refresh, and the gate does not reuse the pass.
        record.unlink(missing_ok=True)
        (work / 'notes.txt').write_text('b\n', encoding='utf-8')
        out = run_check('--tier', 'full')
        cases.append(('an edited tracked file still blocks the record',
                      'NOT recorded' in out and not record.is_file()))
        out = run_check('--gate', '--tier', 'full')
        cases.append(('and the gate runs the suite rather than reuse a pass',
                      'already passed' not in out))
        git('checkout', '--', 'notes.txt')
        git('commit', '-q', '-am', 'commit the ledger')
        out = run_check('--tier', 'full')
        cases.append(('a run over a committed ledger records as before',
                      'recorded for tree' in out))
    bad = [c for c, ok in cases if not ok]
    check(name, not bad, f'{len(cases)} stated cases', '; '.join(bad))


def check_push_check_installs_gate_packages():
    """precedent_push_check.py installs the packages the gates import before
    it runs anything, and stops at once, naming them, when it cannot --
    rather than letting verify_harness fail minutes later without saying a
    package was absent (2026-09-14, 2026-09-26). Hermetic: import and install
    are stubbed, so nothing is fetched (practice: control-asserts-which-failure:
    the present case never calls the installer)."""
    sys.path.insert(0, str(ROOT / 'tools'))
    import precedent_push_check as ppc
    cases, calls = [], []
    have = {'present'}
    ok, note = ppc.ensure_gate_packages(('present',), have.__contains__,
                                        lambda m: calls.append(list(m)) or '')
    cases.append(('all present: ok, silent, installer never called',
                  ok and note == '' and not calls, f'{ok} {note!r} {calls}'))
    ok, note = ppc.ensure_gate_packages(
        ('present', 'absent'), have.__contains__,
        lambda m: (calls.append(list(m)), have.update(m))[1] or '')
    cases.append(('one missing: installs exactly that one and says so',
                  ok and calls[-1] == ['absent'] and 'installed absent' in note,
                  f'{ok} {note!r} {calls}'))
    ok, note = ppc.ensure_gate_packages(('gone',), lambda m: False,
                                        lambda m: 'no network')
    cases.append(('install fails: not ok, and the note names the package',
                  not ok and 'gone' in note and 'pip install gone' in note,
                  f'{ok} {note!r}'))
    cases.append(('the list matches the session check\'s row',
                  ppc.GATE_PACKAGES == ('cmarkgfm', 'markdown'), ''))
    # ...and both startup scripts install every one of them. A fresh
    # consumer container installed cmarkgfm alone, and the session check
    # reported "missing markdown" at every session start (2026-10-01, from
    # a consumer's Update Vendors).
    import re as _re
    for rel in ('templates/bootstrap.sh', 'tools/bootstrap.sh'):
        text = (ROOT / rel).read_text(encoding='utf-8')
        m = _re.search(r'^\s*pip install --quiet ([^\n|]*?)\s*2>', text, _re.M)
        got = set(m.group(1).split()) if m else set()
        cases.append((f'{rel} installs every gate package',
                      set(ppc.GATE_PACKAGES) <= got, f'installs {sorted(got)}'))
    bad = [(c[0], c[2]) for c in cases if not c[1]]
    check(f'the push check installs the gate packages or stops naming them '
          f'({len(cases)} stated cases)',
          not bad, '; '.join(f"{n} -- {d}" for n, d in bad))

def check_stale_source_paths_accepts_the_universal_pair():
    """The universal source is `precedent` at `../BestPractice` by design --
    precedent_bootstrap_source.py writes that pair -- so the stale-path
    report must not tell anyone to repoint it; `../precedent` names no clone.
    A real mismatch is still caught (practice: control-asserts-which-failure)."""
    import json as _j, tempfile
    sys.path.insert(0, str(ROOT / 'tools'))
    import precedent_vendor_engine as pve
    tmp = pathlib.Path(tempfile.mkdtemp(prefix='stale-source-paths-'))
    try:
        (tmp / 'precedent.json').write_text(_j.dumps({'sources': [
            {'level': 'universal', 'name': 'precedent', 'path': '../BestPractice'},
            {'level': 'shared', 'name': 'precedent-shared-writing',
             'path': '../precedent-shared-writing'},
            {'level': 'shared', 'name': 'precedent-shared-x',
             'path': '../precedent-team-x'}]}), encoding='utf-8')
        got = [n for n, _p, _w in pve.stale_source_paths(tmp)]
    finally:
        shutil.rmtree(tmp, ignore_errors=True)
    check('stale_source_paths leaves the universal precedent/../BestPractice '
          'pair alone and still flags a renamed set',
          got == ['precedent-shared-x'], f'flagged: {got}')

def check_a_hook_wired_from_elsewhere_is_reported_as_wired():
    """A hook a repo calls in place, from a path of its own, is WIRED --
    reported as wired, and still not vendored
    (practice: control-asserts-which-failure).

    THE TWO QUESTIONS THIS PINS APART, because one function was answering
    both and could only be right about one. "What do we vendor?" must look
    only under `.claude/hooks/`: a repo that calls a script in place keeps one
    copy of it on purpose, and planting the engine's bundled copy beside it is
    double maintenance that reads as a hand-edit months later. "What does this
    repo already wire?" must not, or the report is simply false.

    THE COST, measured 2026-09-22 in `precedent-individual`. That repo authors
    these scripts and wires four of them straight out of its own tracked
    `bootstrap/`; its settings.json says so outright -- *"bootstrap/ IS a
    tracked directory of this repo, so every entry calls its script in place
    -- one file, no second copy to drift from it."* The refresh told it that
    `commit-identity.sh`, `freshness-guard.sh` and
    `precedent-universal-catalogue.sh` were "not wired in this repo's own
    .claude/settings.json". All three are wired, on consecutive lines of it.

    Worse than noise, because the NOTE beside it says to break the loop by
    hand -- copy the entry from upstream, re-run, and the file arrives.
    Following that here plants the second copy the repo deliberately does not
    keep. The discriminating case below is therefore the NEGATIVE one: wired
    from elsewhere must stay OUT of the vendoring set.

    The fixture owns its own tree (fixture-owns-its-state)."""
    import tempfile
    import precedent_vendor_engine as pve

    d = pathlib.Path(tempfile.mkdtemp(prefix='precedent-wiring-'))
    try:
        (d / '.claude').mkdir(parents=True)
        (d / '.claude' / 'settings.json').write_text(json.dumps({'hooks': {
            'SessionStart': [
                {'hooks': [{'type': 'command',
                            'command': '$CLAUDE_PROJECT_DIR/bootstrap/'
                                       'in-place.sh'}]},
                {'hooks': [{'type': 'command',
                            'command': '$CLAUDE_PROJECT_DIR/.claude/hooks/'
                                       'vendored.sh'}]},
            ]}}), encoding='utf-8')
        vendoring = pve._wired_hook_names(d)
        reporting = pve._wired_hook_names_anywhere(d)

        cases = [
            ('a hook wired from .claude/hooks/ is in the vendoring set',
             'vendored.sh' in vendoring, repr(sorted(vendoring))),
            ('THE DISCRIMINATING CASE: a hook wired in place from another '
             'path stays OUT of the vendoring set, so no second copy is '
             'planted beside it',
             'in-place.sh' not in vendoring, repr(sorted(vendoring))),
            ('...and is still reported as wired, so the NOTE cannot call it '
             'unwired and send somebody to hand-wire it',
             'in-place.sh' in reporting, repr(sorted(reporting))),
            ('a hook wired from nowhere is in neither set',
             'absent.sh' not in vendoring and 'absent.sh' not in reporting,
             f'{sorted(vendoring)} / {sorted(reporting)}'),
            ('an absent settings.json is empty in both, never an error',
             pve._wired_hook_names(d / 'nope') == set()
             and pve._wired_hook_names_anywhere(d / 'nope') == set(), ''),
        ]
        bad = [(n, det) for n, ok, det in cases if not ok]
        check(f'a hook wired in place from another path is reported as wired '
              f'and still not vendored ({len(cases)} stated cases, the '
              f'not-vendored one being the discriminating one)',
              not bad, '; '.join(f'{n} -- {det[:300]}' for n, det in bad))
    finally:
        shutil.rmtree(d, ignore_errors=True)


def check_vendor_engine_removes_a_hook_upstream_dropped():
    """THE GAP (found 2026-09-21 by the very deep check's deletion-
    propagation table, filed as
    todo-2026-09-21-a-dropped-hook-never-leaves-a-consumer.md). This engine
    had two removal paths -- tools/ and .github/workflows/ -- and none for
    .claude/hooks/. A hook dropped upstream stayed installed in every
    consumer, and _write_hook_files then replaced `hook_files` with only
    what it had just written, so the manifest entry vanished as well: the
    file went on running, in every session, recorded by nothing.

    Four cases, and the last two are the ones that make this safe rather
    than merely working:

    A. a hook upstream no longer ships is deleted, and the manifest stops
       recording it.
    B. a hook that IS still shipped is untouched -- the sweep must key on
       what upstream ships, never on what this repo happens to wire.
    C. a hand-edited copy is KEPT and reported, the same standard the
       engine path uses: reaching here means somebody asked to overwrite,
       which is not the same as asking to throw an edit away.
    D. an EMPTY upstream hooks directory sweeps NOTHING. `available` comes
       from a directory glob, and an empty one is indistinguishable from
       "this checkout cannot see upstream" -- sweeping on that reading
       would delete every hook in the consumer, which is the failure this
       whole family exists to prevent."""
    import shutil, tempfile
    import precedent_vendor_engine as pve

    tmp = pathlib.Path(tempfile.mkdtemp(prefix='precedent-hookdrop-'))
    cases = []
    try:
        def _fixture(name, *, edited=False, empty_upstream=False):
            repo = tmp / name
            (repo / 'tools').mkdir(parents=True)
            hooks = repo / pve.HOOK_DEST_DIR
            hooks.mkdir(parents=True)
            src = tmp / f'{name}-upstream'
            src.mkdir()
            body_gone = '#!/bin/sh\necho dropped\n'
            body_live = '#!/bin/sh\necho live\n'
            (hooks / 'zzz-dropped.sh').write_text(
                body_gone if not edited else body_gone + '# hand edit\n',
                encoding='utf-8')
            (hooks / 'zzz-live.sh').write_text(body_live, encoding='utf-8')
            if not empty_upstream:
                (src / 'zzz-live.sh').write_text(body_live, encoding='utf-8')
            (repo / 'tools' / pve.MANIFEST_NAME).write_text(json.dumps({
                'hook_files': ['zzz-dropped.sh', 'zzz-live.sh'],
                'hooks_sha256': {
                    'zzz-dropped.sh': hashlib.sha256(
                        body_gone.encode('utf-8')).hexdigest(),
                    'zzz-live.sh': hashlib.sha256(
                        body_live.encode('utf-8')).hexdigest()},
            }, indent=2), encoding='utf-8')
            available = set(pve._hook_file_names(src))
            removed = pve._remove_dropped_hook_files(
                repo, repo / 'tools' / pve.MANIFEST_NAME, available, src)
            manifest = json.loads(
                (repo / 'tools' / pve.MANIFEST_NAME).read_text(
                    encoding='utf-8'))
            return repo, hooks, removed, manifest

        _r, hooks_a, removed_a, manifest_a = _fixture('plain')
        cases.append(('A: the hook upstream dropped is deleted',
                      removed_a == ['zzz-dropped.sh']
                      and not (hooks_a / 'zzz-dropped.sh').exists(),
                      repr(removed_a)))
        cases.append(('A: the manifest stops recording it',
                      'zzz-dropped.sh' not in manifest_a.get('hook_files', [])
                      and 'zzz-dropped.sh' not in
                      manifest_a.get('hooks_sha256', {}),
                      json.dumps(manifest_a)[:300]))
        cases.append(('B: a hook upstream still ships is untouched',
                      (hooks_a / 'zzz-live.sh').exists()
                      and 'zzz-live.sh' in manifest_a.get('hook_files', []),
                      json.dumps(manifest_a)[:300]))

        _r2, hooks_c, removed_c, manifest_c = _fixture('edited', edited=True)
        cases.append(('C: a hand-edited copy is kept, not deleted',
                      removed_c == []
                      and (hooks_c / 'zzz-dropped.sh').exists(),
                      repr(removed_c)))

        _r3, hooks_d, removed_d, _m = _fixture('blind', empty_upstream=True)
        cases.append(('D: an empty upstream hooks/ sweeps nothing',
                      removed_d == []
                      and (hooks_d / 'zzz-dropped.sh').exists()
                      and (hooks_d / 'zzz-live.sh').exists(),
                      repr(removed_d)))

        # E (2026-09-28): the real update shape. The consumer's OLD copy of
        # the tool runs first and rewrites the manifest without the dropped
        # hook, so the manifest on disk no longer names it. The record from
        # before the update is the COMMITTED one, and _previous_manifest
        # reads it; without it this removed nothing, every time.
        repo_e = tmp / 'two-pass'
        (repo_e / 'tools').mkdir(parents=True)
        hooks_e = repo_e / pve.HOOK_DEST_DIR
        hooks_e.mkdir(parents=True)
        src_e = tmp / 'two-pass-upstream'
        src_e.mkdir()
        gone, live = '#!/bin/sh\necho dropped\n', '#!/bin/sh\necho live\n'
        (hooks_e / 'zzz-dropped.sh').write_text(gone, encoding='utf-8')
        (hooks_e / 'zzz-live.sh').write_text(live, encoding='utf-8')
        (src_e / 'zzz-live.sh').write_text(live, encoding='utf-8')
        mpath = repo_e / 'tools' / pve.MANIFEST_NAME
        sha = lambda s: hashlib.sha256(s.encode('utf-8')).hexdigest()
        mpath.write_text(json.dumps({
            'files': ['zzz_dropped_tool.py'],
            'sha256': {'zzz_dropped_tool.py': 'x'},
            'hook_files': ['zzz-dropped.sh', 'zzz-live.sh'],
            'hooks_sha256': {'zzz-dropped.sh': sha(gone),
                             'zzz-live.sh': sha(live)}}), encoding='utf-8')
        for args in (['init', '-q'], ['add', '-A'],
                     ['-c', 'user.name=Fixture', '-c', 'user.email=f@invalid',
                      'commit', '-q', '-m', 'installed']):
            subprocess.run(['git', '-C', str(repo_e), *args], check=True,
                           capture_output=True)
        pass_one = {'files': [], 'sha256': {}}      # what the old copy wrote
        mpath.write_text(json.dumps(pass_one), encoding='utf-8')
        before = pve._previous_manifest(repo_e, pass_one)
        removed_e = pve._remove_dropped_hook_files(
            repo_e, mpath, set(pve._hook_file_names(src_e)), src_e,
            previous=before)
        cases.append(('E: after a self-replacing first pass, the committed '
                      'record still finds the dropped hook, and it is deleted',
                      removed_e == ['zzz-dropped.sh']
                      and not (hooks_e / 'zzz-dropped.sh').exists()
                      and (hooks_e / 'zzz-live.sh').exists(),
                      repr(removed_e)))
        cases.append(('E: and the engine file list the old pass forgot is '
                      'recovered the same way',
                      'zzz_dropped_tool.py' in before.get('files', []),
                      repr(before.get('files'))))
    finally:
        shutil.rmtree(tmp, ignore_errors=True)

    bad = [(c[0], c[2]) for c in cases if not c[1]]
    check(f'a refresh removes a hook upstream dropped, and only that '
          f'({len(cases)} stated cases)',
          not bad,
          '; '.join(f"{n} -- {d[:400]}" for n, d in bad))


def check_vendor_engine_keeps_a_declared_engine_path():
    """`engine_paths` in a repo's precedent.json maps an upstream file onto a
    path of the repo's own, so `refresh` keeps it current instead of a person
    hand-syncing it. The case that produced it (2026-09-24):
    precedent-individual's bootstrap/commit-identity.sh, identical to
    templates/harness/claude-code/hooks/commit-identity.sh only because of
    four hand-sync commits, and unable to move because session-start.sh and
    the set's own `adapters` both reach it by that path.

    Function-level against a throwaway upstream git repo, plus two real
    `refresh` subprocesses for the refusals that happen BEFORE the upstream
    is read (so they need no network and no BestPractice clone):

    A. adopt: an identical local file with no record yet is adopted, not
       rewritten, and its hash recorded.
    B. refresh: upstream moves, the file follows, the hash follows, the
       executable bit is carried over.
    C. hand-edit: an edited copy is drift; `refresh` refuses on it.
    D. first run, NOT identical: refused, with a count of differing lines.
    E. forbidden: onto an adapter's TO, onto an engine-vendored path, or the
       same local path twice -- refused by `refresh` even with --force.
       CONTROL: an adapter's FROM is allowed (precedent-individual's case).
    F. a dropped declaration hands the file back: kept, no longer tracked.
    G. an upstream file that vanished leaves the local copy AND its record."""
    import shutil, tempfile, subprocess as sp
    import precedent_vendor_engine as pve

    tmp = pathlib.Path(tempfile.mkdtemp(prefix='precedent-engine-paths-'))
    env = dict(os.environ)
    env.update({'GIT_CONFIG_GLOBAL': str(tmp / 'gitconfig'),
                'PRECEDENT_ALLOW_ANY_AUTHOR': '1',
                'GIT_AUTHOR_NAME': 'Harness', 'GIT_COMMITTER_NAME': 'Harness',
                'GIT_AUTHOR_EMAIL': 'harness@example.com',
                'GIT_COMMITTER_EMAIL': 'harness@example.com'})
    (tmp / 'gitconfig').write_text('', encoding='utf-8')
    UP, LOCAL = 'tpl/hooks/ident.sh', 'bootstrap/ident.sh'
    cases = []

    def git(d, *a):
        r = sp.run(['git', '-C', str(d), *a], capture_output=True, text=True,
                   env=env)
        if r.returncode != 0:
            raise RuntimeError(f'fixture setup: git {" ".join(a)}: '
                               f'{(r.stderr or r.stdout).strip()}')
        return r.stdout.strip()

    def upstream_commit(body, path=UP):
        f = upstream / path
        f.parent.mkdir(parents=True, exist_ok=True)
        f.write_text(body, encoding='utf-8')
        f.chmod(0o755)
        git(upstream, 'add', '-A')
        git(upstream, 'commit', '-q', '-m', 'fixture')
        return git(upstream, 'rev-parse', 'HEAD')

    def make_repo(name, mapping, local_body=None, adapters=None):
        repo = tmp / name
        (repo / 'tools').mkdir(parents=True)
        (repo / 'precedent.json').write_text(json.dumps(
            {pve.ENGINE_PATHS_KEY: mapping}), encoding='utf-8')
        (repo / 'tools' / pve.MANIFEST_NAME).write_text(json.dumps(
            {'kind': 'source', 'files': [], 'sha256': {}}), encoding='utf-8')
        if local_body is not None:
            (repo / LOCAL).parent.mkdir(parents=True, exist_ok=True)
            (repo / LOCAL).write_text(local_body, encoding='utf-8')
        if adapters is not None:
            (repo / 'MANIFEST.json').write_text(json.dumps(
                {'adapters': adapters}), encoding='utf-8')
        return repo

    def manifest_of(repo):
        return json.loads((repo / 'tools' / pve.MANIFEST_NAME).read_text(
            encoding='utf-8'))

    def one_pass(repo, commit):
        """What refresh() does with engine_paths, minus the engine files."""
        m = manifest_of(repo)
        mapping = pve.declared_engine_paths(repo)
        src = pve._read_engine_path_sources(upstream, commit, mapping)
        refused = pve._engine_path_first_run_refusals(repo, mapping, src, m)
        if refused:
            return refused
        pve._write_engine_paths(repo, mapping, src, m)
        return []

    def run_refresh(repo, *extra):
        tool = repo / 'tools' / 'precedent_vendor_engine.py'
        tool.write_bytes((ROOT / 'tools' / 'precedent_vendor_engine.py').read_bytes())
        m = manifest_of(repo)
        m['files'] = ['precedent_vendor_engine.py']
        m['sha256'] = {'precedent_vendor_engine.py': hashlib.sha256(
            tool.read_bytes()).hexdigest()}
        (repo / 'tools' / pve.MANIFEST_NAME).write_text(json.dumps(m),
                                                        encoding='utf-8')
        r = sp.run([sys.executable, str(tool), 'refresh', str(upstream),
                    *extra], capture_output=True, text=True, cwd=str(repo),
                   env=env)
        return r.returncode, r.stdout + r.stderr

    try:
        upstream = tmp / 'upstream'
        upstream.mkdir()
        git(upstream, 'init', '-q')
        v1 = '#!/bin/sh\necho v1\n'
        c1 = upstream_commit(v1)

        # A -- adopt
        repo_a = make_repo('adopt', {UP: LOCAL}, local_body=v1)
        before = (repo_a / LOCAL).stat().st_mtime_ns
        refused_a = one_pass(repo_a, c1)
        m_a = manifest_of(repo_a)
        cases.append(('A: an identical local file is adopted and its hash recorded',
                      refused_a == []
                      and m_a.get('engine_paths') == {LOCAL: UP}
                      and m_a.get('engine_paths_sha256', {}).get(LOCAL)
                      == hashlib.sha256(v1.encode()).hexdigest(),
                      json.dumps(m_a)[:300]))
        cases.append(('A: ...without being rewritten',
                      (repo_a / LOCAL).stat().st_mtime_ns == before, ''))

        # B -- refresh follows upstream
        (repo_a / LOCAL).chmod(0o644)
        v2 = '#!/bin/sh\necho v2\n'
        c2 = upstream_commit(v2)
        one_pass(repo_a, c2)
        m_b = manifest_of(repo_a)
        cases.append(('B: the file follows upstream, and so does its recorded hash',
                      (repo_a / LOCAL).read_text(encoding='utf-8') == v2
                      and m_b['engine_paths_sha256'][LOCAL]
                      == hashlib.sha256(v2.encode()).hexdigest()
                      and pve._engine_path_drift(repo_a, m_b) == [],
                      json.dumps(m_b)[:300]))
        cases.append(('B: the upstream executable bit is carried over',
                      os.access(repo_a / LOCAL, os.X_OK), ''))
        cases.append(('B: nothing is left to do once recorded',
                      pve._engine_paths_incomplete(repo_a, m_b) == [], ''))

        # C -- hand-edit is drift, and refresh refuses on it
        (repo_a / LOCAL).write_text(v2 + '# local edit\n', encoding='utf-8')
        drift_c = pve._engine_path_drift(repo_a, manifest_of(repo_a))
        cases.append(('C: a hand-edited copy is reported as drift',
                      drift_c and drift_c[0][0] == LOCAL
                      and 'hand-edited' in drift_c[0][1], repr(drift_c)))
        rc_c, out_c = run_refresh(repo_a)
        cases.append(('C: refresh refuses on it, before reading upstream',
                      rc_c != 0 and 'hand-edited since the last seed/refresh' in out_c
                      and LOCAL in out_c, out_c[-600:]))

        # D -- first run, not identical
        repo_d = make_repo('differs', {UP: LOCAL},
                           local_body='#!/bin/sh\necho mine\necho extra\n')
        refused_d = one_pass(repo_d, c2)
        cases.append(('D: a non-identical file on first run is refused, with a line count',
                      len(refused_d) == 1 and refused_d[0][0] == LOCAL
                      and refused_d[0][1] > 0
                      and 'engine_paths_sha256' not in manifest_of(repo_d)
                      and 'mine' in (repo_d / LOCAL).read_text(encoding='utf-8'),
                      repr(refused_d)))
        repo_d2 = make_repo('absent', {UP: LOCAL})
        cases.append(('D: CONTROL -- an absent local file is simply written',
                      one_pass(repo_d2, c2) == []
                      and (repo_d2 / LOCAL).read_text(encoding='utf-8') == v2, ''))

        # E -- forbidden mappings, refused by refresh even with --force
        adapter_to = '.claude/hooks/ident.sh'
        repo_e1 = make_repo('onto-adapter', {UP: adapter_to},
                            adapters=[{'path': adapter_to, 'source': 'some-set'}])
        rc_e1, out_e1 = run_refresh(repo_e1, '--force')
        cases.append(("E: a mapping onto an adapter's TO is refused, even with --force",
                      rc_e1 != 0 and 'Not waived by --force' in out_e1
                      and 'some-set' in out_e1, out_e1[-600:]))
        repo_e2 = make_repo('onto-engine', {UP: 'tools/precedent_vendor_engine.py'})
        rc_e2, out_e2 = run_refresh(repo_e2, '--force')
        cases.append(('E: a mapping onto an engine-vendored path is refused',
                      rc_e2 != 0 and 'already vendors this path' in out_e2,
                      out_e2[-600:]))
        conflicts_twice = pve._engine_path_conflicts(
            tmp, {UP: LOCAL, 'tpl/other.sh': LOCAL}, {}, 'source')
        cases.append(('E: the same local path declared twice is refused',
                      len(conflicts_twice) == 1 and 'twice' in conflicts_twice[0][1],
                      repr(conflicts_twice)))
        repo_e3 = make_repo('adapter-from', {UP: LOCAL}, local_body=v2,
                            adapters=[{'path': adapter_to, 'source': 'some-set'}])
        cases.append(("E: CONTROL -- an adapter's FROM path is allowed",
                      pve._engine_path_conflicts(
                          repo_e3, pve.declared_engine_paths(repo_e3),
                          manifest_of(repo_e3), 'source') == [], ''))

        # F -- dropped declaration hands the file back
        repo_f = make_repo('dropped', {UP: LOCAL}, local_body=v2)
        one_pass(repo_f, c2)
        (repo_f / 'precedent.json').write_text('{}', encoding='utf-8')
        one_pass(repo_f, c2)
        m_f = manifest_of(repo_f)
        cases.append(('F: a dropped declaration leaves the file and stops tracking it',
                      (repo_f / LOCAL).is_file()
                      and 'engine_paths_sha256' not in m_f
                      and pve._engine_path_drift(repo_f, m_f) == [],
                      json.dumps(m_f)[:300]))

        # G -- upstream vanished
        repo_g = make_repo('vanished', {UP: LOCAL}, local_body=v2)
        one_pass(repo_g, c2)
        git(upstream, 'rm', '-q', UP)
        git(upstream, 'commit', '-q', '-m', 'drop')
        c3 = git(upstream, 'rev-parse', 'HEAD')
        one_pass(repo_g, c3)
        m_g = manifest_of(repo_g)
        cases.append(('G: an upstream file that vanished keeps the local copy and its record',
                      (repo_g / LOCAL).read_text(encoding='utf-8') == v2
                      and LOCAL in m_g.get('engine_paths_sha256', {}),
                      json.dumps(m_g)[:300]))

        # H -- carried by hand, identical to upstream (2026-10-03, found
        # rehearsing a Produce: precedent-individual carried upstream's
        # commit-identity.sh before a refresh, and every refresh after that
        # refused on it as a hand-edit). CONTROL: a real edit, same repo
        # shape, is still refused.
        v4 = '#!/bin/sh\necho v4\n'
        upstream_commit(v4)
        for body, refused_want, what in (
                (v4, False, 'a copy identical to upstream does not hold refresh up'),
                (v4 + '# mine\n', True, 'CONTROL: a real edit still does')):
            repo_h = make_repo('carried-' + str(refused_want), {UP: LOCAL},
                               local_body=v2)
            one_pass(repo_h, c2)
            (repo_h / LOCAL).write_text(body, encoding='utf-8')
            rc_h, out_h = run_refresh(repo_h, '--from-ref', 'HEAD')
            refused = 'hand-edited since the last seed/refresh' in out_h
            cases.append((f'H: {what}',
                          refused == refused_want and (refused_want or
                          'identical to upstream' in out_h),
                          f'rc={rc_h} {out_h[-500:]}'))

        # I -- a TEMPLATE declared as an engine path is kept RENDERED, the
        # way a consumer's refresh renders it (2026-10-04: precedent-
        # individual's hand-rendered bootstrap hook fell behind its template
        # twice, and its adapter shipped the stale copy over every
        # consumer's). First run adopts a copy identical to the render;
        # CONTROL: the raw template's placeholders never reach the file.
        tpl_up = f'{pve.HOOK_SOURCE_DIR}/{pve.INDIVIDUAL_HOOK_TEMPLATE}'
        tpl_local = 'bootstrap/' + pve.INDIVIDUAL_HOOK
        raw = ('#!/bin/bash\nNAME="{{SOURCE_NAME}}"\nURL="{{SOURCE_REPO_URL}}"\n'
               'if [ "{{SOURCE_REPO_URL_SUBSTITUTED}}" != "yes" ]; then exit 0; fi\n')
        c_t = upstream_commit(raw, path=tpl_up)
        repo_i = make_repo('rendered', {tpl_up: tpl_local})
        (repo_i / tpl_local).parent.mkdir(parents=True, exist_ok=True)
        (repo_i / tpl_local).write_text(pve.render_individual_hook(raw),
                                        encoding='utf-8')
        refused_i = one_pass(repo_i, c_t)
        body_i = (repo_i / tpl_local).read_text(encoding='utf-8')
        cases.append(('I: a template engine path is adopted when the local copy '
                      'is its render, and kept rendered, never raw',
                      refused_i == [] and '{{' not in body_i
                      and 'NAME="precedent-individual"' in body_i
                      and tpl_local in manifest_of(repo_i).get('engine_paths_sha256', {}),
                      repr(refused_i) + body_i[:300]))
        c_t2 = upstream_commit(raw + '# moved upstream\n', path=tpl_up)
        one_pass(repo_i, c_t2)
        body_i2 = (repo_i / tpl_local).read_text(encoding='utf-8')
        cases.append(('I: when the template moves, the rendered copy follows it',
                      '# moved upstream' in body_i2 and '{{' not in body_i2
                      and os.access(repo_i / tpl_local, os.X_OK), body_i2[:300]))
    finally:
        shutil.rmtree(tmp, ignore_errors=True)

    bad = [(c[0], c[2]) for c in cases if not c[1]]
    check(f'a declared engine_paths file is kept current by refresh, and never '
          f'adopted over a difference or onto a path something else writes '
          f'({len(cases)} stated cases)',
          not bad,
          '; '.join(f"{n} -- {d[:600]}" for n, d in bad))


def check_vendor_engine_names_a_dependent_of_a_deleted_file():
    """THE INCIDENT (2026-09-21,
    todo-2026-09-21-refresh-deletes-a-workflow-another-file-depends-on.md).
    A refresh deleted .github/workflows/precedent-check.yml from four
    practice sets. In each of them a second workflow had been PAUSED hours
    earlier, its header saying its checks "now run as steps in
    .github/workflows/precedent-check.yml's single job". The destination
    was gone; two commit-scope checks ran nowhere; nothing said anything.

    The deletion mechanics were already tested -- by the two checks above,
    thoroughly. What nothing tested, because nothing did it, is the other
    half: a deletion travels to every installed repo, and the question
    "does anything here still depend on this" never travelled with it.
    precedent_decommission.py asks it, within one repo, when a person runs
    it deliberately.

    Both directions, because the warning half of a reporter is worth
    nothing without the quiet half: a reporter that fires on a clean case
    trains people to ignore it, which is the state this was meant to
    correct.

    Unit-level on purpose: the subject is what _remove_dropped_engine_files
    PRINTS, and driving a whole refresh to observe one stderr line would
    make the case slower and its failure harder to read, without testing
    anything the two end-to-end checks above do not already cover."""
    import contextlib, io, shutil, tempfile
    import precedent_vendor_engine as pve

    tmp = pathlib.Path(tempfile.mkdtemp(prefix='precedent-deldeps-'))
    cases = []
    try:
        def _fixture(name, referrer_text):
            repo = tmp / name
            (repo / 'tools').mkdir(parents=True)
            dropped = 'zzz_retired_helper.py'
            body = '# a vendored engine file upstream no longer ships\n'
            (repo / 'tools' / dropped).write_text(body, encoding='utf-8')
            if referrer_text:
                (repo / 'README.md').write_text(referrer_text, encoding='utf-8')
            manifest = {'files': [dropped],
                        'sha256': {dropped: hashlib.sha256(
                            body.encode('utf-8')).hexdigest()}}
            err = io.StringIO()
            with contextlib.redirect_stdout(io.StringIO()), \
                    contextlib.redirect_stderr(err):
                removed = pve._remove_dropped_engine_files(
                    repo / 'tools', manifest, 'consumer')
            return repo, removed, err.getvalue()

        repo_a, removed_a, err_a = _fixture(
            'with-dependent',
            'Nightly we run tools/zzz_retired_helper.py against the tree.\n')
        cases.append(('the dropped engine file is deleted',
                      removed_a == ['zzz_retired_helper.py'],
                      repr(removed_a)))
        cases.append(('the file that still names it is reported, with its '
                      'path and line',
                      'README.md:1' in err_a
                      and 'zzz_retired_helper.py' in err_a,
                      err_a[:800]))
        cases.append(('the report does not refuse the refresh -- it warns',
                      err_a.strip().startswith('WARN'), err_a[:200]))

        _repo_b, removed_b, err_b = _fixture('no-dependent', None)
        cases.append(('a deletion nothing depends on stays quiet',
                      removed_b == ['zzz_retired_helper.py']
                      and 'still names it' not in err_b,
                      err_b[:800]))
    finally:
        shutil.rmtree(tmp, ignore_errors=True)

    bad = [(c[0], c[2]) for c in cases if not c[1]]
    check(f'a refresh that deletes a vendored file names whatever still '
          f'depends on it ({len(cases)} stated cases)',
          not bad,
          '; '.join(f"{n} -- {d[:800]}" for n, d in bad))


def check_vendor_engine_retires_ci_workflow_files():
    """THE INCIDENT (2026-09-19, found in themorgan/precedent-individual).
    views-drift.yml.template was folded into the practice-set workflow
    template (itself retired 2026-10-01) as its own job (spec/CI_MINUTES_PLAN.md item 9), and the repos that
    hand-applied that fix the same day deleted their now-redundant
    views-drift.yml file -- but nothing told refresh() the old manifest
    entry was retired, so ci_workflows_sha256 kept a hash for a file that no
    longer existed. _ci_workflow_drift reads "recorded, but missing" as a
    hand-edit needing --force, so the NEXT refresh() in that repo would have
    refused the WHOLE run over a file a previous, correct fix had already
    removed.

    Two mechanisms this closes, tested here: RETIRED_CI_WORKFLOW_FILES +
    _remove_retired_ci_workflow_files (refresh() self-heals a stale
    retirement automatically), and the `record-ci` CLI subcommand
    (record_ci_workflow_files exposed standalone, clone-free, for the
    moment a CI workflow file is fixed BY HAND and needs the manifest told
    without a `refresh --force` overwriting the fix back to the generic
    template -- the other half of the same incident, found the same day in
    two real consumer repos).

    2026-09-20: _remove_retired_ci_workflow_files stopped only reporting a
    retired file still on disk and started deleting it -- but ONLY when its
    current sha256 still matches what the manifest had recorded, the same
    standard _ci_workflow_drift already uses for "not drifted" everywhere
    else in this module. Case B below now splits on exactly that hash
    match/mismatch, since it is now the entire question the old single case
    collapsed into one "always kept" assumption that would no longer be
    true.

    `kind: source` throughout, since RETIRED_CI_WORKFLOW_FILES' one entry
    (views-drift.yml) is a 'source'-kind retirement; CI_WORKFLOW_TEMPLATES
    is not, so leak-gate.yml.template is the live template refresh()
    always has to reach past the retired entry to apply.

    Fixture shape mirrors check_vendor_engine_refreshes_ci_workflow_files
    immediately above: only precedent_vendor_engine.py is copied into each
    fake consumer, and each scenario gets its own fresh directory."""
    import shutil, tempfile

    tmp = pathlib.Path(tempfile.mkdtemp(prefix='precedent-ci-retire-'))
    cases = []
    # A CONSUMER, and its leak gate, since 2026-09-21. This fixture used
    # precedent-check.yml in a `source` set, which was a live tracked
    # workflow then and is not now: a source ships none
    # (practice: source-sets-run-no-ci), so a refresh correctly DELETES it
    # and the fixture's "it survives" expectation became the stale half.
    # The retirement mechanism under test is kind-agnostic; what it needs is
    # a workflow the kind still ships, and a consumer's leak gate is one.
    rel = '.github/workflows/leak-gate.yml'
    retired_rel = '.github/workflows/views-drift.yml'
    try:
        engine_bytes = (ROOT / 'tools' / 'precedent_vendor_engine.py').read_bytes()
        engine_hash = hashlib.sha256(engine_bytes).hexdigest()
        real_template = (ROOT / 'templates' / 'github-actions' /
                         'leak-gate.yml.template').read_bytes()
        stub = b'name: stub\n# an older vendored copy\n'
        stub_hash = hashlib.sha256(stub).hexdigest()
        retired_content = b'name: views-drift\n'
        retired_content_hash = hashlib.sha256(retired_content).hexdigest()

        def make_set(name, retired_still_on_disk, retired_hash_matches=False):
            """A fresh 'consumer' repo carrying a live leak-gate.yml
            (recorded, stale against the current template -- so a
            successful refresh is independently visible) plus a retired
            views-drift.yml manifest entry, with or without the file
            itself still sitting on disk.

            retired_hash_matches selects which of the two on-disk cases a
            still-present retired file is in: True records the file's OWN
            real hash (untouched since the manifest last looked -- safe to
            delete); False records a hash that does not match (stands in
            for a hand-edit since -- must be kept)."""
            consumer = tmp / name
            (consumer / 'tools').mkdir(parents=True)
            (consumer / '.github' / 'workflows').mkdir(parents=True)
            (consumer / 'tools' / 'precedent_vendor_engine.py').write_bytes(engine_bytes)
            (consumer / rel).write_bytes(stub)
            retired_recorded = (retired_content_hash if retired_hash_matches
                                 else 'deadbeef' * 8)
            ci_hashes = {rel: stub_hash, retired_rel: retired_recorded}
            if retired_still_on_disk:
                (consumer / retired_rel).write_bytes(retired_content)
            manifest = {
                'kind': 'consumer', 'source_commit': 'deadbeef',
                'files': ['precedent_vendor_engine.py'],
                'sha256': {'precedent_vendor_engine.py': engine_hash},
                'ci_workflow_files': sorted(ci_hashes),
                'ci_workflows_sha256': ci_hashes,
            }
            (consumer / 'tools' / 'ENGINE_MANIFEST.json').write_text(
                json.dumps(manifest), encoding='utf-8')
            return consumer

        # Computed, not the literal 'HEAD' -- see _ref_including_worktree's
        # own docstring: this vendors the tree under test, uncommitted
        # changes included, not just whatever HEAD happens to hold.
        ref = _ref_including_worktree(ROOT)

        def run_refresh(consumer):
            r = subprocess.run(
                [sys.executable, str(consumer / 'tools' / 'precedent_vendor_engine.py'),
                 'refresh', str(ROOT), '--from-ref', ref],
                capture_output=True, text=True, cwd=str(consumer))
            return r.returncode, r.stdout + r.stderr

        def manifest_of(consumer):
            return json.loads(
                (consumer / 'tools' / 'ENGINE_MANIFEST.json').read_text(encoding='utf-8'))

        # -- A: retired entry, file already gone from disk (the real
        # precedent-individual shape) -- refresh succeeds, refreshes the
        # LIVE file, and drops the retired entry, all in one run --
        a = make_set('gone', retired_still_on_disk=False)
        rc_a, out_a = run_refresh(a)
        cases.append(('a retired, already-deleted CI workflow entry does NOT make '
                      'refresh refuse the run',
                      rc_a == 0, out_a[:800]))
        cases.append(('...the still-current file is refreshed to the current '
                      'template regardless',
                      (a / rel).read_bytes() == real_template, out_a[:800]))
        cases.append(('...and the retired entry is dropped from the manifest',
                      retired_rel not in manifest_of(a).get('ci_workflows_sha256', {}),
                      out_a[:800]))
        cases.append(('...reported by name, not a silent drop',
                      'views-drift.yml' in out_a and 'retired' in out_a, out_a[:800]))

        # -- B1: retired entry, file STILL on disk, UNTOUCHED since the
        # manifest last recorded its hash -- deleted, not just reported
        # (2026-09-20 change) --
        b1 = make_set('deleted', retired_still_on_disk=True, retired_hash_matches=True)
        rc_b1, out_b1 = run_refresh(b1)
        cases.append(('an untouched retired file (on-disk hash matches the manifest) '
                      'is deleted, and refresh still succeeds',
                      rc_b1 == 0 and not (b1 / retired_rel).is_file(), out_b1[:800]))
        cases.append(('...the manifest entry is dropped too',
                      retired_rel not in manifest_of(b1).get('ci_workflows_sha256', {}),
                      out_b1[:800]))
        cases.append(('...and the deletion is reported by name, not silent',
                      'views-drift.yml' in out_b1 and 'deleted' in out_b1, out_b1[:800]))

        # -- B2: retired entry, file STILL on disk, HAND-EDITED since the
        # manifest last recorded its hash -- kept and reported, never
        # deleted, matching refresh()'s existing hand-edit protection
        # everywhere else (_local_drift, _remove_dropped_engine_files) --
        b2 = make_set('kept', retired_still_on_disk=True, retired_hash_matches=False)
        rc_b2, out_b2 = run_refresh(b2)
        cases.append(('CONTROL: when the retired file has been hand-edited since, '
                      'refresh still succeeds and drops the manifest entry',
                      rc_b2 == 0 and retired_rel not in manifest_of(b2).get('ci_workflows_sha256', {}),
                      out_b2[:800]))
        cases.append(('...but the file itself is left on disk, not deleted',
                      (b2 / retired_rel).is_file(), out_b2[:400]))
        cases.append(('...and refresh WARNs that it was hand-edited rather than '
                      'staying silent about the leftover',
                      'hand-edited' in out_b2, out_b2[:800]))

        # -- C: `record-ci` re-baselines a hand-fixed file's hash, clone-free,
        # without touching content -- the other half of the same incident --
        c = tmp / 'hand-fixed'
        (c / 'tools').mkdir(parents=True)
        (c / '.github' / 'workflows').mkdir(parents=True)
        (c / 'tools' / 'precedent_vendor_engine.py').write_bytes(engine_bytes)
        hand_fixed = b'name: leak-gate\n# hand-applied fix, correct content\n'
        (c / rel).write_bytes(hand_fixed)
        stale_manifest = {
            'kind': 'consumer', 'source_commit': 'deadbeef',
            'files': ['precedent_vendor_engine.py'],
            'sha256': {'precedent_vendor_engine.py': engine_hash},
            'ci_workflow_files': [rel],
            'ci_workflows_sha256': {rel: stub_hash},  # stale: predates the hand fix
        }
        (c / 'tools' / 'ENGINE_MANIFEST.json').write_text(
            json.dumps(stale_manifest), encoding='utf-8')
        r_c = subprocess.run(
            [sys.executable, str(c / 'tools' / 'precedent_vendor_engine.py'), 'record-ci'],
            capture_output=True, text=True, cwd=str(c))
        cases.append(('`record-ci` runs with no clone argument at all (unlike status/'
                      'refresh) and exits clean',
                      r_c.returncode == 0, (r_c.stdout + r_c.stderr)[:800]))
        cases.append(('...re-records the hash to match what is on disk NOW',
                      manifest_of(c).get('ci_workflows_sha256', {}).get(rel) ==
                      hashlib.sha256(hand_fixed).hexdigest(),
                      (r_c.stdout + r_c.stderr)[:800]))
        cases.append(('...without touching the hand-fixed content itself',
                      (c / rel).read_bytes() == hand_fixed, ''))
        r_c2 = subprocess.run(
            [sys.executable, str(c / 'tools' / 'precedent_vendor_engine.py'), 'record-ci'],
            capture_output=True, text=True, cwd=str(c))
        cases.append(('CONTROL: a second `record-ci` run, now already current, says so '
                      'rather than re-printing a change',
                      r_c2.returncode == 0 and 'nothing to do' in r_c2.stdout,
                      r_c2.stdout[:400]))
    finally:
        shutil.rmtree(tmp, ignore_errors=True)

    bad = [(c[0], c[2]) for c in cases if not c[1]]
    check(f'a retired CI workflow template (views-drift.yml folded into '
          f'precedent-check.yml) self-heals on refresh instead of refusing, deletes '
          f'the file itself only when untouched since last recorded, and '
          f'`record-ci` re-baselines a hand-fixed file clone-free ({len(cases)} '
          f'stated cases)',
          not bad,
          '; '.join(f"{n} -- {d[:800]}" for n, d in bad))


def check_ledger_accepts_a_row_added_with_its_change():
    """practice: parallel-artifact-ledger, 2026-09-26. A commit cannot name
    its own ID, so the ledger check now also accepts a row added IN the
    commit that changed an adapter. Planted in a scratch history: a row
    arriving with its change passes; a change with no row, or with a row
    added only in a later commit, still fails; a row naming the change by
    ID still passes."""
    import shutil, tempfile
    import precedent_check as pc
    tmp = pathlib.Path(tempfile.mkdtemp(prefix='precedent-ledger-same-commit-'))
    member = tmp / 'templates' / 'harness' / 'claude-code'
    ledger = tmp / 'templates' / 'harness' / 'LEDGER.md'
    head = ('| Date | Originating change | claude-code | codex | gemini-cli '
            '| grok-build |\n|---|---|---|---|---|---|\n')

    def g(*a):
        return subprocess.run(['git', *a], cwd=str(tmp), capture_output=True,
                              text=True, env=dict(os.environ,
                              GIT_AUTHOR_NAME='t', GIT_AUTHOR_EMAIL='t@e.invalid',
                              GIT_COMMITTER_NAME='t',
                              GIT_COMMITTER_EMAIL='t@e.invalid'))

    def commit(msg, hook_text=None, row=None):
        if hook_text is not None:
            (member / 'hook.sh').write_text(hook_text)
        if row is not None:
            ledger.write_text(ledger.read_text() + row + '\n')
        g('add', '-A')
        g('-c', 'core.hooksPath=/dev/null', 'commit', '-qm', msg)
        return g('rev-parse', 'HEAD').stdout.strip()

    old_root = pc.ROOT
    cases = []
    try:
        member.mkdir(parents=True)
        g('init', '-q')
        ledger.write_text(head)
        (tmp / 'README').write_text('x')
        commit('root')                                   # repo root: exempt
        commit('inception of claude-code', hook_text='v1')  # dir's first: exempt
        with_row = commit('change with its row', hook_text='v2',
                          row='| 2026-09-26 | the gate learns v2 | applied | none | none | none |')
        pc.ROOT = tmp
        f1 = [str(x) for x in pc._parallel_artifact_ledger(None)]
        cases.append(('CONTROL: a row added in the same commit as the change '
                      'passes, with no ID in it', f1 == []))
        bare = commit('change with no row', hook_text='v3')
        late = commit('row added later, without the ID',
                      row='| 2026-09-26 | the gate learns v3 | applied | none | none | none |')
        f2 = [str(x) for x in pc._parallel_artifact_ledger(None)]
        cases.append(('a change with no row of its own still fails, even '
                      'when a later commit adds an ID-less row',
                      any(bare[:7] in x and 'no row references' in x
                          for x in f2)))
        cases.append(('...and the ledger-only commit is not an adapter '
                      'change', not any(late[:7] in x for x in f2)))
        commit('pin', row=f'| 2026-09-26 | [`{bare[:7]}`](x) pinned | applied | none | none | none |')
        f3 = [str(x) for x in pc._parallel_artifact_ledger(None)]
        cases.append(('a row naming the change by ID still passes, as before',
                      f3 == []))
        cases.append(('the same-commit row was the one that passed',
                      pc._ledger_row_added_by(with_row) is True
                      and pc._ledger_row_added_by(bare) is False))
    finally:
        pc.ROOT = old_root
        shutil.rmtree(tmp, ignore_errors=True)
    bad = [c[0] for c in cases if not c[1]]
    check(f'the ledger check accepts a row added with its change, and still '
          f'fails a change with no row ({len(cases)} stated cases)',
          not bad, '; '.join(bad))


def check_ci_workflow_approved_pins_approval_to_content():
    """THE INCIDENT (practice: ci-workflow-approved), 2026-09-25: a
    consumer's own light-check.yml billed a minute on every merge to main
    because a session had put back a push trigger another session removed
    six days earlier. An advisory check flagged the file on every run and
    nobody acted. This proves the blocking replacement: a workflow passes
    only as the engine's untouched copy or with an approval quoting the
    person, pinned by sha256 -- so an EDIT fails, not just an addition --
    and that the push gate runs it in the basic tier."""
    import hashlib, shutil, tempfile
    import precedent_install as _pi
    import precedent_push_check as _ppc
    import precedent_vendor_engine as _pve

    tmp = pathlib.Path(tempfile.mkdtemp(prefix='precedent-ci-approved-'))
    cases = []
    rel = '.github/workflows/light-check.yml'
    body = 'name: Light check\non:\n  pull_request:\n    branches: [main]\n'
    edited = body + '  push:\n    branches: [main]\n'
    quote = 'Morgan, 2026-09-25: "Please stop it running every time"'
    sha = hashlib.sha256(body.encode()).hexdigest()
    py = {n: (ROOT / 'tools' / n).read_bytes()
          for n in _pve.KINDS['consumer'] if n.endswith('.py')}
    try:
        def consumer(name, text=body, approved=None, tracked=None,
                     manifest=True, kind='consumer'):
            # No practices/ci-workflow-approved.md on purpose: the check
            # binds any repo keeping .github/workflows (binds_when), and a
            # fixture carrying the practice would hide that gate breaking.
            c = tmp / name
            (c / 'tools').mkdir(parents=True)
            (c / '.github' / 'workflows').mkdir(parents=True)
            for n, b in py.items():
                (c / 'tools' / n).write_bytes(b)
            if text is not None:
                (c / rel).write_text(text)
            if manifest:
                (c / 'tools' / 'ENGINE_MANIFEST.json').write_text(json.dumps(
                    {'kind': kind, 'source_commit': 'deadbeef',
                     'files': [], 'sha256': {},
                     'ci_workflow_files': sorted(tracked or {}),
                     'ci_workflows_sha256': tracked or {}}))
            cfg = {'sources': []}
            if approved is not None:
                cfg['github_ci_approved'] = approved
            (c / 'precedent.json').write_text(json.dumps(cfg))
            r = subprocess.run(
                [sys.executable, str(c / 'tools' / 'precedent_check.py'),
                 '--only', 'ci-workflow-approved'],
                capture_output=True, text=True, cwd=str(c))
            return r.returncode, r.stdout + r.stderr

        rc, out = consumer('unapproved')
        cases.append(('a workflow nobody approved is a VIOLATION, and says so',
                      rc != 0 and 'VIOLATION' in out
                      and 'has no approval' in out, out[-1500:]))
        cases.append(('...and the finding names when it runs and the sha to '
                      'pin', 'pull_request' in out and sha in out, out[-1500:]))
        good = {rel: {'sha256': sha, 'approved_by': quote}}
        rc, out = consumer('approved', approved=good)
        cases.append(('CONTROL: an approval quoting the person, pinned to '
                      'this content, passes', rc == 0 and '0 violated' in out,
                      out[-1500:]))
        rc, out = consumer('edited', text=edited, approved=good)
        cases.append(('an EDIT after approval (a push trigger put back) fails',
                      rc != 0 and 'EDITED after it was approved' in out,
                      out[-1500:]))
        rc, out = consumer('unquoted', approved={
            rel: {'sha256': sha, 'approved_by': 'Morgan, 2026-09-25'}})
        cases.append(('an approval quoting nobody is not an approval',
                      rc != 0 and 'quotes nobody' in out, out[-1500:]))
        rc, out = consumer('undated', approved={
            rel: {'sha256': sha, 'approved_by': 'Morgan: "yes"'}})
        cases.append(('an undated approval is not an approval',
                      rc != 0 and 'carries no date' in out, out[-1500:]))
        # A practice set is judged the same way (2026-10-01).
        rc, out = consumer('set-approved', approved=good, kind='source')
        cases.append(('in a practice set, an approved workflow passes',
                      rc == 0, out[-1500:]))
        rc, out = consumer('set-unapproved', kind='source')
        cases.append(('...and an unapproved one is a VIOLATION',
                      rc != 0 and 'VIOLATION' in out, out[-1500:]))
        rc, out = consumer('tracked', tracked={rel: sha})
        cases.append(('CONTROL: the engine\'s own untouched copy passes '
                      'with no approval', rc == 0, out[-1500:]))
        rc, out = consumer('tracked-edited', text=edited, tracked={rel: sha})
        cases.append(('an edited engine copy with no approval fails',
                      rc != 0 and 'has no approval' in out, out[-1500:]))
        rc, out = consumer('stale', text=None, approved=good)
        cases.append(('an approval whose file is gone is reported',
                      rc != 0 and 'no longer exists' in out, out[-1500:]))
        rc, out = consumer('no-manifest', manifest=False)
        # Since 2026-09-30 a repo with no manifest is judged on growth only
        # (a change that makes a workflow run more), so it runs, never
        # crashes, and a repo whose change grows nothing passes.
        cases.append(('CONTROL: no manifest (BestPractice\'s shape) is judged '
                      'on growth only: no crash, and nothing grown passes',
                      rc == 0 and 'Traceback' not in out, out[-1500:]))

        # Since 2026-09-27 the light check is an engine file like the leak
        # gate: shipped through CI_WORKFLOW_TEMPLATES, tracked in the
        # manifest the install writes, so it needs no approval entry.
        cases.append(('the light check ships to consumers as an engine-owned, '
                      'tracked workflow',
                      ('light-check.yml.template', rel)
                      in _pve.CI_WORKFLOW_TEMPLATES['consumer']
                      and not hasattr(_pve, 'CI_INSTALL_ONLY_TEMPLATES')
                      and not hasattr(_pi, '_approve_installed_workflow'), ''))
        inst = tmp / 'install'
        (inst / '.github' / 'workflows').mkdir(parents=True)
        (inst / 'tools').mkdir()
        shutil.copy(ROOT / 'templates' / 'github-actions' /
                    'light-check.yml.template', inst / rel)
        (inst / 'tools' / 'ENGINE_MANIFEST.json').write_text(
            json.dumps({'kind': 'consumer'}))
        _pve.record_ci_workflow_files(inst, 'consumer')
        m = json.loads((inst / 'tools' / 'ENGINE_MANIFEST.json').read_text())
        cases.append(('...and the install records it in the manifest, pinned '
                      'to the template',
                      m.get('ci_workflows_sha256', {}).get(rel)
                      == hashlib.sha256((inst / rel).read_bytes()).hexdigest(),
                      str(m)))

        for kind in ('consumer', 'source'):
            names = [n for n, _a, _r in _ppc.PUSH_CHECKS[kind]]
            cases.append((f'the {kind} push check runs ci_workflows',
                          'ci_workflows' in names, str(names)))
        cases.append(('...in the BASIC tier, so a push to any branch runs it',
                      'ci_workflows' in _ppc.BASIC_CHECKS,
                      str(_ppc.BASIC_CHECKS)))
        cases.append(('a consumer\'s own light_check runs before a push, and '
                      'is optional where the repo has none',
                      'light_check' in [n for n, _a, _r
                                        in _ppc.PUSH_CHECKS['consumer']]
                      and 'light_check' in _ppc.OPTIONAL, ''))
    finally:
        shutil.rmtree(tmp, ignore_errors=True)

    bad = [(c[0], c[2]) for c in cases if not c[1]]
    check(f'ci-workflow-approved fails an unapproved or edited workflow, '
          f'passes a pinned approval or the engine\'s own copy, and runs '
          f'before every push ({len(cases)} stated cases)',
          not bad, '; '.join(f'{n} -- {d[:1500]}' for n, d in bad))


def check_workflow_write_gate_refuses_api_writes():
    """practice: ci-workflow-approved, 2026-09-26. A session can write a file
    straight onto GitHub with a file-write tool, and no push gate sees it.
    workflow-write-gate.sh refuses that for a workflow file, on both tools,
    and lets every other file through."""
    import shutil
    hook = ROOT / 'templates' / 'harness' / 'claude-code' / 'hooks' / \
        'workflow-write-gate.sh'
    cases = []
    if not shutil.which('jq'):
        check('workflow-write-gate.sh refuses a workflow written through '
              'the API -- NOT RUN: no jq here, and the hook fails open '
              'without it', True, '')
        return

    def run(payload):
        p = subprocess.run(['bash', str(hook)], input=json.dumps(payload),
                           capture_output=True, text=True, timeout=60)
        return '"deny"' in p.stdout, p.stdout

    denied, out = run({'tool_name': 'mcp__github__create_or_update_file',
                       'tool_input': {'path': '.github/workflows/new.yml',
                                      'content': 'on: push'}})
    cases.append(('create_or_update_file on a workflow is refused, naming '
                  'the practice', denied and 'ci-workflow-approved' in out
                  and '.github/workflows/new.yml' in out))
    denied, out = run({'tool_name': 'mcp__github__push_files',
                       'tool_input': {'files': [
                           {'path': 'README.md', 'content': 'x'},
                           {'path': '.github/workflows/ci.yaml',
                            'content': 'on: push'}]}})
    cases.append(('push_files carrying one workflow among other files is '
                  'refused', denied and '.github/workflows/ci.yaml' in out))
    denied, _ = run({'tool_name': 'mcp__github__push_files',
                     'tool_input': {'files': [{'path': 'README.md'},
                                              {'path': 'docs/workflows.yml'}]}})
    cases.append(('CONTROL: ordinary files, even one named like a workflow '
                  'outside .github/workflows, pass', not denied))
    same = (ROOT / '.claude' / 'hooks' / 'workflow-write-gate.sh')
    cases.append(("this repo runs the byte-identical copy it ships",
                  same.is_file() and same.read_bytes() == hook.read_bytes()))
    bad = [c[0] for c in cases if not c[1]]
    check(f'workflow-write-gate.sh refuses a workflow written straight onto '
          f'GitHub and passes everything else ({len(cases)} stated cases)',
          not bad, '; '.join(bad))


def check_session_start_warns_of_unapproved_workflow():
    """practice: ci-workflow-approved, 2026-09-26. templates/bootstrap.sh
    runs the check at session start, because a workflow edited on GitHub's
    website is in a fresh clone before any push. Its block is run here as
    the template has it, under the template's own `set -euo pipefail`: loud
    for an unapproved workflow, silent for an approved one, and never ending
    the bootstrap either way."""
    import hashlib, shutil, tempfile
    import precedent_vendor_engine as _pve
    text = (ROOT / 'templates' / 'bootstrap.sh').read_text(encoding='utf-8')
    start = text.find('# A WORKFLOW NOBODY APPROVED')
    end = text.find('\nfi\n', start)
    block = text[start:end + 4] if start >= 0 and end > 0 else ''
    tmp = pathlib.Path(tempfile.mkdtemp(prefix='precedent-wf-sessionstart-'))
    rel = '.github/workflows/light-check.yml'
    body = 'name: Light check\non:\n  pull_request:\n    branches: [main]\n'
    cases = [('the template carries the block', bool(block))]
    try:
        def run(approve):
            c = tmp / ('approved' if approve else 'unapproved')
            (c / 'tools').mkdir(parents=True)
            (c / '.github' / 'workflows').mkdir(parents=True)
            for n in _pve.KINDS['consumer']:
                if n.endswith('.py') and (ROOT / 'tools' / n).is_file():
                    shutil.copy2(ROOT / 'tools' / n, c / 'tools' / n)
            (c / rel).write_text(body)
            (c / 'tools' / 'ENGINE_MANIFEST.json').write_text(json.dumps(
                {'kind': 'consumer', 'files': [], 'sha256': {},
                 'ci_workflow_files': [], 'ci_workflows_sha256': {}}))
            cfg = {'sources': []}
            if approve:
                cfg['github_ci_approved'] = {rel: {
                    'sha256': hashlib.sha256(body.encode()).hexdigest(),
                    'approved_by': 'Morgan, 2026-09-26: "keep it"'}}
            (c / 'precedent.json').write_text(json.dumps(cfg))
            script = 'set -euo pipefail\n' + block + '\necho REACHED-END\n'
            p = subprocess.run(['bash', '-c', script], cwd=str(c),
                               capture_output=True, text=True, timeout=120)
            return p.stdout + p.stderr
        loud, quiet = run(False), run(True)
        cases += [
            ('an unapproved workflow prints the WARNING naming the file',
             'WARNING: a GitHub Actions workflow here has no approval' in loud
             and rel in loud),
            ('...and the bootstrap still runs to the end', 'REACHED-END' in loud),
            ('CONTROL: an approved workflow prints nothing but the end',
             quiet.strip() == 'REACHED-END'),
        ]
    finally:
        shutil.rmtree(tmp, ignore_errors=True)
    bad = [c[0] for c in cases if not c[1]]
    check(f'session start warns of an unapproved workflow, stays silent for '
          f'an approved one, and never ends the bootstrap '
          f'({len(cases)} stated cases)', not bad, '; '.join(bad))


def check_ci_fleet_audit_reads_github_not_the_clone():
    """practice: ci-workflow-approved, 2026-09-26. The push-time check sees
    only a session's own pushes; tools/ci_fleet_audit.py asks GitHub, so it
    sees a workflow edited on the website, one left on a side branch, and a
    repository it cannot reach. Planted against a fake GitHub, so the
    verdicts are a property of the code, not of the network."""
    import base64, datetime, hashlib, io
    import ci_fleet_audit as cfa

    def b64(t):
        return base64.b64encode(t.encode()).decode()

    approved = 'name: ok\non:\n  pull_request:\n    branches: [main]\n'
    rogue = 'name: rogue\non:\n  push:\n    branches: [main]\n'
    side = 'name: side\non:\n  push:\n'
    quiet = 'name: quiet\non:\n  pull_request:\n'
    cron = ('name: nightly\non:\n  schedule:\n    - cron: "15 3 * * *"\n')
    sha = hashlib.sha256(approved.encode()).hexdigest()
    cfg = {'github_ci_approved': {'.github/workflows/ok.yml': {
        'sha256': sha, 'approved_by': 'Morgan, 2026-09-26: "yes, that one"'}}}
    blobs = {'b-ok': approved, 'b-rogue': rogue, 'b-side': side,
             'b-quiet': quiet, 'b-cron': cron}

    def listing(names):
        return [{'name': n, 'type': 'file', 'sha': b} for n, b in names]

    def fake(path):
        o = 'repos/o/r'
        routes = {
            f'{o}': {'default_branch': 'main', 'private': True},
            f'{o}/actions/workflows?per_page=100': {'workflows': []},
            f'{o}/contents/precedent.json?ref=main':
                {'content': b64(json.dumps(cfg))},
            f'{o}/branches?per_page=100':
                [{'name': 'main'}, {'name': 'stale'}, {'name': 'calm'},
                 {'name': 'old'}],
            # 'stale' and 'calm' had commits this week; 'old' has had none
            # for a month, so it must not be read at all.
            f'{o}/branches/stale': {'commit': {'commit': {'committer':
                {'date': '2026-09-24T10:00:00Z'}}}},
            f'{o}/branches/calm': {'commit': {'commit': {'committer':
                {'date': '2026-09-25T10:00:00Z'}}}},
            f'{o}/branches/old': {'commit': {'commit': {'committer':
                {'date': '2026-08-20T10:00:00Z'}}}},
            f'{o}/contents/.github/workflows?ref=old': listing(
                [('side.yml', 'b-side'), ('ghost.yml', 'b-side')]),
            f'{o}/contents/.github/workflows?ref=main': listing(
                [('ok.yml', 'b-ok'), ('rogue.yml', 'b-rogue'),
                 ('nightly.yml', 'b-cron')]),
            f'{o}/contents/.github/workflows?ref=stale': listing(
                [('ok.yml', 'b-ok'), ('side.yml', 'b-side')]),
            f'{o}/contents/.github/workflows?ref=calm': listing(
                [('ok.yml', 'b-ok'), ('quiet.yml', 'b-quiet')]),
        }
        if path.startswith(f'{o}/actions/runs'):
            return {'total_count': 2, 'workflow_runs': [
                {'path': '.github/workflows/rogue.yml', 'event': 'push',
                 'created_at': '2026-09-25T10:00:00Z'},
                {'path': '.github/workflows/gone.yml', 'event': 'push',
                 'created_at': '2026-09-24T10:00:00Z'}]}, None
        if path.startswith(f'{o}/git/blobs/'):
            return {'content': b64(blobs[path.rsplit('/', 1)[1]])}, None
        if path in routes:
            return routes[path], None
        if path.startswith('repos/o/unreached'):
            return {'message': 'GitHub access to this repository is not '
                               'enabled for this session.'}, None
        return {'message': 'Not Found'}, None

    today = datetime.date(2026, 9, 26)
    r = cfa.audit_repo('o/r', call=fake, today=today)
    u = cfa.audit_repo('o/unreached', call=fake, today=today)
    rows = '\n'.join(f'{v} {t}' for v, t in r['rows'])
    buf = io.StringIO()
    n = cfa.render([r, u], out=buf)
    out = buf.getvalue()
    cases = [
        ('CONTROL: a workflow approved at this exact content is OK',
         any(
             v == 'OK' and 'ok.yml [main]' in t for v, t in r['rows'])),
        ('a workflow nobody approved (say, edited on the website) is a '
         'FINDING that names its push-on-main cost',
         any(v == 'FINDING' and 'rogue.yml [main]' in t
             and 'APPROVED BY NOBODY' in t and 'every merge bills a run' in t
             for v, t in r['rows'])),
        ('a side branch whose workflow runs on its own push is a FINDING',
         any(v == 'FINDING' and 'side.yml on branch stale' in t
             for v, t in r['rows'])),
        ('CONTROL: a side branch whose workflow cannot run on a push is '
         'only counted', 'quiet.yml' not in rows
         and '1 workflow version(s) on 1 side branch(es)' in rows),
        ('a workflow GitHub ran this week that is not on main is a FINDING',
         any(v == 'FINDING' and 'gone.yml: not on main' in t
             for v, t in r['rows'])),
        ('a schedule shows among its workflow\'s triggers, and there is no '
         'separate cron table', "schedule ['15 3 * * *']" in out
         and 'CRON' not in out),
        ('a repository it cannot reach is NOT REACHED, never clean',
         not u['reached'] and 'NOT REACHED' in out and 'o/unreached' in out),
        ('the totals line counts the findings it printed',
         f'ci_fleet_audit: {n} finding(s) in 1 repo(s) reached; 1 not '
         f'reached.' in out and n == 4),
        ('a branch with no commit in 7 days is counted, never read',
         'ghost.yml' not in out and 'branch old' not in out
         and '1 side branch(es) with no commit in 7 days not read' in rows),
        # GitHub's runner has no PyYAML (2026-09-26: this check went red
        # there on the staging-into-main pull request, green in every
        # session). The line reader must give push_fires the same answers.
        ('without PyYAML the line reader gives push_fires the same answers',
         all(cfa.push_fires(cfa._on_plain(t), b) == want for t, b, want in (
             (rogue, 'main', True), (side, 'stale', True),
             (quiet, 'calm', False), (cron, 'main', False),
             (approved, 'main', False),
             ('on: push\n', 'x', True), ('on: [pull_request, push]\n', 'x', True),
             ('on:\n  push:\n    tags:\n      - "v*"\n', 'main', False),
             ('on:\n  push:\n    branches-ignore:\n      - x\n', 'x', False),
             ('on:\n  push:\n    branches-ignore:\n      - x\n', 'y', True),
             ('"on":\n  push:\n    branches: [rel/*]\n', 'rel/1', True)))),
        ('a push trigger limited to tags never fires on a branch push',
         not cfa.push_fires({'push': {'tags': ['v*']}}, 'main')
         and cfa.push_fires({'push': {'branches': ['rel/*']}}, 'rel/1')
         and not cfa.push_fires({'push': {'branches-ignore': ['x']}}, 'x')),
    ]
    bad = [c[0] for c in cases if not c[1]]
    check(f'ci_fleet_audit reads GitHub: approved passes, an unapproved '
          f'workflow, a push-triggered side branch and a stray run are '
          f'findings, schedules show as triggers, the unreachable is named '
          f'({len(cases)} stated cases)',
          not bad, '; '.join(bad) + ' -- ' + out[-1500:])


def check_workflow_file_outside_vendoring_detects_candidates():
    """THE INCIDENT this guards against (practice: workflow-file-outside-
    vendoring), 2026-09-20: a sweep list built by matching workflow
    filenames against a table of retired names flagged a real dependent
    repo's `light-check.yml` as a retired duplicate. It was a live,
    required, hand-authored check sharing a name with something Precedent
    once retired, for unrelated reasons. This tests that the mechanism
    built afterward compares by TRACKING (a repo's own ci_workflow_files),
    never by name, and never auto-classifies -- it only ever reports a
    candidate, with a declared-decline escape hatch for a legitimate one.

    Fixture shape mirrors check_vendor_engine_retires_ci_workflow_files
    immediately above: a fresh consumer directory per scenario, only the
    files each scenario actually needs."""
    import shutil, tempfile

    tmp = pathlib.Path(tempfile.mkdtemp(prefix='precedent-wf-outside-'))
    cases = []
    tracked_rel = '.github/workflows/bestpractice-docs.yml'
    untracked_rel = '.github/workflows/light-check.yml'
    exempt_rel = '.github/workflows/hand-authored-check.yml'
    try:
        # The full consumer-kind .py set, not just the two files this check
        # touches directly -- precedent_check.py imports several vendored
        # companions at module level (split_practices, precedent_time, and
        # others), and a fixture missing any one of them fails with an
        # import traceback that has nothing to do with what this test
        # actually checks (practice: fixture-owns-its-state).
        import precedent_vendor_engine as _pve_for_fixture
        _consumer_py = {n: (ROOT / 'tools' / n).read_bytes()
                        for n in _pve_for_fixture.KINDS['consumer']
                        if n.endswith('.py')}
        # This check is practice_backed=True (the default): run() refuses to
        # run it in a repo whose own practices/workflow-file-outside-
        # vendoring.md does not resolve, the same gate that keeps a check
        # from claiming coverage nobody actually distributed. A fixture
        # missing this file is not testing this check at all -- it is
        # testing the refusal, which every case here would silently do
        # instead of what its own name says it asserts.
        _practice_bytes = (ROOT / 'practices' /
                           'workflow-file-outside-vendoring.md').read_bytes()

        def make_consumer(name, ci_workflow_files, precedent_json=None,
                          write_workflows=True):
            consumer = tmp / name
            (consumer / 'tools').mkdir(parents=True)
            (consumer / '.github' / 'workflows').mkdir(parents=True)
            for _n, _b in _consumer_py.items():
                (consumer / 'tools' / _n).write_bytes(_b)
            (consumer / 'practices').mkdir()
            (consumer / 'practices' / 'workflow-file-outside-vendoring.md').write_bytes(
                _practice_bytes)
            if write_workflows:
                (consumer / tracked_rel).write_text('name: docs\n')
                (consumer / untracked_rel).write_text('name: light\n')
                (consumer / exempt_rel).write_text('name: hand-authored\n')
            manifest = {'kind': 'consumer', 'source_commit': 'deadbeef',
                       'files': [], 'sha256': {},
                       'ci_workflow_files': ci_workflow_files,
                       'ci_workflows_sha256': {}}
            (consumer / 'tools' / 'ENGINE_MANIFEST.json').write_text(
                json.dumps(manifest), encoding='utf-8')
            if precedent_json is not None:
                (consumer / 'precedent.json').write_text(
                    json.dumps(precedent_json), encoding='utf-8')
            return consumer

        def run_check(consumer):
            r = subprocess.run(
                [sys.executable, str(consumer / 'tools' / 'precedent_check.py'),
                 '--only', 'workflow-file-outside-vendoring'],
                capture_output=True, text=True, cwd=str(consumer))
            return r.returncode, r.stdout + r.stderr

        # -- A: no exemption declared -- both untracked files are reported --
        a = make_consumer('bare', [tracked_rel])
        rc_a, out_a = run_check(a)
        cases.append(('the tracked file is never reported',
                      tracked_rel + ':' not in out_a, out_a[:1200]))
        cases.append(('an untracked workflow file IS reported, by path, as '
                      'a candidate -- never a verdict',
                      untracked_rel in out_a and 'CANDIDATE' not in out_a.split(untracked_rel)[0][-5:]
                      or untracked_rel in out_a,
                      out_a[:1200]))
        cases.append(('the report says "verify by content, never by name" -- '
                      'the exact framing the incident requires',
                      'verify by content, never by name' in out_a, out_a[:1200]))
        cases.append(('the hand-authored file is ALSO reported here -- no '
                      'exemption was declared for it',
                      exempt_rel in out_a, out_a[:1200]))
        cases.append(('the run reports ADVISORY, not VIOLATION -- this '
                      'check can never fail a build',
                      'ADVISORY' in out_a and 'VIOLATION' not in out_a, out_a[:1200]))

        # -- B: a declared exemption, with a reason, silences its own path
        # only -- the other untracked file is still reported --
        b = make_consumer('exempted', [tracked_rel], precedent_json={
            'ci_workflow_outside_vendoring_exempt': [
                {'path': exempt_rel, 'reason': 'a repo-specific hand-authored check'}]})
        rc_b, out_b = run_check(b)
        cases.append(('CONTROL: the exempted path is not reported once its '
                      'reason is declared',
                      exempt_rel not in out_b, out_b[:1200]))
        cases.append(('...but the OTHER untracked file is still reported -- '
                      'the exemption is scoped to its own path, not blanket',
                      untracked_rel in out_b, out_b[:1200]))

        # -- C: an exemption declared with no reason is not honoured at all
        # (checks-carry-a-declared-decline: the reason is mandatory) --
        c = make_consumer('reasonless', [tracked_rel], precedent_json={
            'ci_workflow_outside_vendoring_exempt': [{'path': exempt_rel}]})
        rc_c, out_c = run_check(c)
        cases.append(('an exemption with no reason is ignored -- still '
                      'reported',
                      exempt_rel in out_c, out_c[:1200]))

        # -- D: a STALE exemption -- declared, but this run does not find
        # the path untracked (it is now in ci_workflow_files) -- reported
        # as stale rather than silently honoured --
        d = make_consumer('stale', [tracked_rel, exempt_rel], precedent_json={
            'ci_workflow_outside_vendoring_exempt': [
                {'path': exempt_rel, 'reason': 'used to be hand-authored'}]})
        rc_d, out_d = run_check(d)
        cases.append(('a stale exemption (declared, but now tracked) is '
                      'reported rather than silently accepted',
                      exempt_rel in out_d
                      and 'does not find it untracked' in out_d,
                      out_d[:1200]))

        # -- E, CONTROL: no ENGINE_MANIFEST.json at all (BestPractice's own
        # shape) -- the check is NotApplicable, never a false pass or a
        # crash --
        e = tmp / 'no-manifest'
        (e / 'tools').mkdir(parents=True)
        (e / 'practices').mkdir()
        (e / 'practices' / 'workflow-file-outside-vendoring.md').write_bytes(
            _practice_bytes)
        for _n, _b in _consumer_py.items():
            (e / 'tools' / _n).write_bytes(_b)
        rc_e, out_e = run_check(e)
        cases.append(('CONTROL: no manifest at all reports SKIPPED, never '
                      'a crash or a silent pass claiming coverage it does '
                      'not have',
                      'SKIPPED' in out_e and 'workflow-file-outside-vendoring'
                      in out_e, out_e[:1200]))
    finally:
        shutil.rmtree(tmp, ignore_errors=True)

    bad = [(c[0], c[2]) for c in cases if not c[1]]
    check(f'workflow-file-outside-vendoring reports an untracked workflow '
          f'file as a candidate, never a verdict, honours a declared '
          f'exemption scoped to its own path, and flags a stale one '
          f'({len(cases)} stated cases)',
          not bad,
          '; '.join(f"{n} -- {d[:1200]}" for n, d in bad))


def check_very_deep_check_workflow_liveness_scan():
    """tools/very_deep_check.py's _workflow_liveness_scan is the mechanical
    half of Pass 2 item 18 (practices/very-deep-check.md) -- it enumerates
    candidates by content tracking, the same underlying
    precedent_vendor_engine._untracked_ci_workflow_files this repo's
    precedent_check.py registration also calls, so both surfaces agree by
    construction rather than by two hand-kept implementations (Pass 2's own
    item 8: "are there two of anything that should be one?"). This tests
    the function directly, not through the full very_deep_check.py CLI --
    no session-level scope to set up, and the CLI paths (freshness,
    source resolution) are exercised elsewhere."""
    import shutil, tempfile
    import very_deep_check as vdc

    tmp = pathlib.Path(tempfile.mkdtemp(prefix='vdc-wf-liveness-'))
    try:
        (tmp / 'tools').mkdir(parents=True)
        (tmp / '.github' / 'workflows').mkdir(parents=True)
        (tmp / '.github/workflows/bestpractice-docs.yml').write_text('name: docs\n')
        (tmp / '.github/workflows/light-check.yml').write_text('name: light\n')
        (tmp / '.github/workflows/hand-authored.yml').write_text('name: hand\n')
        manifest = {'kind': 'consumer',
                    'ci_workflow_files': ['.github/workflows/bestpractice-docs.yml']}
        (tmp / 'tools' / 'ENGINE_MANIFEST.json').write_text(json.dumps(manifest))
        (tmp / 'precedent.json').write_text(json.dumps({
            'ci_workflow_outside_vendoring_exempt': [
                {'path': '.github/workflows/hand-authored.yml',
                 'reason': 'a repo-specific check'}]}))

        found = vdc._workflow_liveness_scan(tmp)
        cases = [
            ('the tracked file is never reported',
             not any('bestpractice-docs.yml' in f for f in found), found),
            ('the untracked file IS reported as a CANDIDATE, never a verdict',
             any('light-check.yml' in f and 'CANDIDATE' in f for f in found),
             found),
            ('the exempted file, with its reason declared, is not reported',
             not any('hand-authored.yml' in f for f in found), found),
        ]

        # CONTROL: no manifest at all -- [] returned, never a crash, never
        # a spurious candidate for a repo nothing was ever vendored into.
        no_manifest = tmp / 'no-manifest-case'
        (no_manifest / '.github' / 'workflows').mkdir(parents=True)
        (no_manifest / '.github/workflows/anything.yml').write_text('name: x\n')
        cases.append(('CONTROL: a repo with no ENGINE_MANIFEST.json at all '
                      'returns no candidates, not a crash',
                      vdc._workflow_liveness_scan(no_manifest) == [], None))
    finally:
        shutil.rmtree(tmp, ignore_errors=True)

    bad = [(n, d) for n, ok, d in cases if not ok]
    check(f'very_deep_check._workflow_liveness_scan enumerates workflow-'
          f'file candidates by content tracking, honours a declared '
          f'exemption, and never crashes on an unvendored repo '
          f'({len(cases)} stated cases)',
          not bad,
          '; '.join(f"{n} -- {d}" for n, d in bad))


def check_rule_rewrite_detection():
    """cite-the-incident asks "did somebody WRITE this rule", so it has to
    tell an authorship event from an edit.

    It used to compare the Rule text for equality, and that was wrong twice
    in one day (2026-09-06): a sweep repointing 67 broken relative links
    demanded a `## Story` from four inherited practices whose prose it had
    not touched a word of, and then a one-word product rename did the same.
    Both times the only ways to clear the demand were to invent an incident
    or to leave the defect unfixed. A demand nobody can honestly satisfy is
    worse than no demand: it teaches people to route around the check.

    Two thresholds, because neither alone works: on a short Rule one
    swapped word is a large FRACTION of the text, and on a long one a real
    paragraph rewrite can be a small fraction. Both directions are pinned
    here, because the lenient direction is where this could quietly become
    a check that never fires."""
    import importlib.util
    spec = importlib.util.spec_from_file_location(
        '_pc_rewrite', ROOT / 'tools' / 'precedent_check.py')
    pc = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(pc)

    long_rule = ("A practice layer's own install playbook records the mechanics "
                 "of every host-specific setup step, and the maintainers read "
                 "it, but the project's own people read the getting-started "
                 "page instead. " * 3)
    cases = [
        ('a single word swapped in a short Rule is an edit, not a rewrite',
         "Alpha's internal install playbook records the mechanics.",
         "Bravo's internal install playbook records the mechanics.", False),
        ('the same word swapped throughout a long Rule is still an edit',
         long_rule, long_rule.replace('playbook', 'runbook'), False),
        ('a repointed link is not a rewrite (the target is not prose)',
         'See [tools/x.py](tools/x.py) for the engine.',
         'See [tools/x.py](../tools/x.py) for the engine.', False),
        ('a typo fix is not a rewrite',
         'Order sections by how often the reader neds them.',
         'Order sections by how often the reader needs them.', False),
        ('replacing the Rule with different substance IS a rewrite',
         'Every generated file carries a build code.',
         'Sessions never edit a vendored file by hand; move the change into '
         'the source repository and re-vendor, so the next refresh does not '
         'silently discard it.', True),
        ('a Rule where there was none is authorship',
         '', 'A new rule, freshly authored, with real substance behind it.', True),
        ('replacing most of a Rule is a rewrite',
         'Order sections by how often the reader needs them; common first, '
         'rare last.',
         'Order sections alphabetically, and put every migration note in an '
         'appendix at the very end of the document.', True),
    ]
    results = [(name, pc._rule_was_rewritten({'rule': b}, {'rule': a}) == expect)
               for name, b, a, expect in cases]
    bad = [n for n, ok in results if not ok]
    for n in bad:
        print(f"  rule-rewrite detection did NOT behave as stated: {n}")
    check(f'cite-the-incident tells an authorship event from an edit '
          f'({len(cases)} stated cases: a rename, a repeated rename, a '
          f'repointed link and a typo are edits; new substance, a Rule added '
          f'from nothing, and most of a Rule replaced are rewrites)',
          not bad)


def check_source_shape_is_verified():
    """A source is checked for the shape its skeleton defines, and for the
    shape its CONSUMERS need.

    precedent_bootstrap_source.py only ever ran for sources it created. A
    source migrated into place -- assembled by hand from an older system --
    never passed through it, and nothing afterwards asked whether it came
    out right. Both of this project's migrated sets were missing a skeleton
    file, and had been since migration (2026-09-06).

    File presence alone was the first version and was not enough: an
    approvers.json with no approvers, or an approver with no `github`, is
    present and useless -- build_codeowners.py refuses exactly those, so a
    source carrying one is already broken and has only not been run against
    yet. "Well-formed" is defined here by what a real consumer of the file
    needs, never by a wish list."""
    import importlib.util, tempfile, shutil, json as _json
    spec = importlib.util.spec_from_file_location(
        '_bss', ROOT / 'tools' / 'precedent_bootstrap_source.py')
    bss = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(bss)

    cases = []
    with tempfile.TemporaryDirectory() as td:
        def fixture(level, **edits):
            d = pathlib.Path(td) / f'src{len(cases)}{level}{len(edits)}'
            shutil.copytree(ROOT / 'templates' / f"practice-set-{ {'team': 'shared'}.get(level, level) }", d)
            (d / 'practices').mkdir(exist_ok=True)
            (d / 'practices' / 'x.md').write_text('---\nslug: x\n---\n## Rule\nx\n',
                                                  encoding='utf-8')
            if level == 'team':
                (d / 'approvers.json').write_text(_json.dumps(
                    {'approvers': [{'name': 'A', 'github': 'a'}]}), encoding='utf-8')
                (d / 'approvers.json.template').unlink(missing_ok=True)
            else:
                (d / 'config.json.sample').write_text(_json.dumps(
                    {'individual': {'name': 'n', 'path': '/p'}}), encoding='utf-8')
            (d / 'leak-blocklist.txt').write_text('# blank\n', encoding='utf-8')
            # The skeleton's README is full of {{PLACEHOLDER}}s by design;
            # bootstrap fills them. A fixture standing in for a FINISHED
            # source has to fill them too -- verify() caught this fixture
            # itself the first time it ran, which is the check working.
            (d / 'README.md').write_text('# A finished set\n', encoding='utf-8')
            # The two session hooks live in the harness adapter, not in
            # either skeleton (one copy per level would drift, and
            # _copy_skeleton writes plain text, while a hook without its
            # executable bit silently never runs) -- so a fixture standing
            # in for a FINISHED source installs them the same way
            # bootstrap() does, rather than by copying a tree that was
            # never going to contain them.
            bss._install_session_hooks(d)
            # Same reasoning for the CI gates: they live in
            # templates/github-actions/, not in either skeleton, and
            # bootstrap() installs them. A fixture standing in for a
            # FINISHED source has them (a set that does not is reported,
            # which check_views_drift_gate_reaches_a_source_set asserts).
            bss._install_workflows(d)
            # And the universal-catalogue wiring, added 2026-09-13: the
            # declaration in the set's own precedent.json plus the
            # .gitignore line, both written by bootstrap(). A fixture
            # standing in for a FINISHED source has them, or the two
            # verify() rows that report a set which reads none of the
            # universal practices fire here and the "complete set is
            # well-formed" cases below stop meaning anything.
            # _install_session_hooks() above already wired the two
            # SessionStart steps, since they are in the settings payload it
            # writes.
            bss.ensure_universal_source(d)
            bss.ensure_precedent_gitignore(d)
            # And the set's own AGENTS.md with the loader markers, written
            # by bootstrap() since 2026-09-14 (a set without one fails its
            # own build_views.py). Written here without the generator run,
            # which a fixture with no tools/ cannot do.
            bss._write_instructions_and_views(d, level, 'a-fixture-set')
            for rel, text in edits.items():
                if text is None:
                    (d / rel).unlink(missing_ok=True)
                else:
                    (d / rel).write_text(text, encoding='utf-8')
            return d

        cases.append(('a complete shared set is well-formed',
                      bss.verify('team', fixture('team')) == []))
        cases.append(('a complete individual set is well-formed',
                      bss.verify('individual', fixture('individual')) == []))
        cases.append(('a set with no AGENTS.md is reported, naming what fails without it',
                      any('AGENTS.md' in f and 'build_views' in f for f in bss.verify(
                          'team', fixture('team', **{'AGENTS.md': None})))))
        cases.append(('an AGENTS.md without the loader markers is reported too',
                      any('BEGIN GENERATED' in f for f in bss.verify(
                          'team', fixture('team', **{'AGENTS.md': '# notes, no markers\n'})))))
        cases.append(('a source with no session hooks is reported -- they are '
                      'the one part of a source\'s shape that does not live '
                      'in the skeleton',
                      any('freshness-guard' in f for f in bss.verify(
                          'team', fixture('team',
                                          **{'.claude/hooks/freshness-guard.sh': None})))))
        # A source is free to keep its hooks somewhere other than where
        # bootstrap() writes them, as long as settings.json points at them:
        # what the shape check is really asking is whether the hook RUNS.
        # A real one does exactly this (its hooks live in bootstrap/), and
        # the literal-path check reported that working source as broken.
        _relocated = fixture('team', **{'.claude/hooks/freshness-guard.sh': None})
        (_relocated / 'bootstrap').mkdir(exist_ok=True)
        (_relocated / 'bootstrap' / 'freshness-guard.sh').write_text('#!/bin/sh\n')
        # Every mode the adapter wires, not just session-start: this fixture
        # stands in for a FINISHED source, and a finished source wires all of
        # them -- the real set this is modelled on was measured wiring exactly
        # the adapter's three. Wiring one made it a stand-in for a source that
        # is correct about WHERE its hooks live and wrong about WHEN they run,
        # which is a different fixture with a different purpose. Derived
        # rather than listed so this does not become another copy of the
        # wiring that drifts (see
        # check_generator_wires_every_template_guard_mode).
        (_relocated / '.claude' / 'settings.json').write_text(_json.dumps(
            {'hooks': {'SessionStart': [{'hooks': [
                {'type': 'command',
                 'command': f'$CLAUDE_PROJECT_DIR/bootstrap/freshness-guard.sh '
                            f'{_mode} main'}
                for _mode in sorted(bss._template_guard_modes())]}]}}))
        cases.append(('a session hook kept outside .claude/hooks/ but wired by '
                      'the source\'s own settings.json is NOT reported missing',
                      not any('freshness-guard' in f
                              for f in bss.verify('team', _relocated))))

        # The negative control for that leniency: wired at a path where
        # nothing is installed must still be reported, or the check above
        # would accept any settings.json that merely mentions the name.
        _dangling = fixture('team', **{'.claude/hooks/freshness-guard.sh': None})
        (_dangling / '.claude' / 'settings.json').write_text(_json.dumps(
            {'hooks': {'SessionStart': [{'hooks': [{'type': 'command',
             'command': '$CLAUDE_PROJECT_DIR/bootstrap/freshness-guard.sh'}]}]}}))
        cases.append(('a hook wired at a path where no file exists is still '
                      'reported missing',
                      any('freshness-guard' in f
                          for f in bss.verify('team', _dangling))))

        cases.append(('a report names the harness adapter, not the skeleton, '
                      'for the files the skeleton has never shipped',
                      all('templates/harness/claude-code/hooks/' in f
                          for f in bss.verify('team', fixture(
                              'team', **{'.claude/hooks/commit-identity.sh': None}))
                          if 'commit-identity' in f)))

        cases.append(('a missing skeleton file is reported',
                      any('leak-blocklist' in f for f in bss.verify(
                          'team', fixture('team', **{'leak-blocklist.txt': None})))))
        cases.append(('an approvers.json with no approvers is reported -- '
                      'build_codeowners.py refuses exactly this',
                      any('no approvers' in f for f in bss.verify(
                          'team', fixture('team', **{'approvers.json':
                              _json.dumps({'approvers': []})})))))
        cases.append(('an approver with no github is reported',
                      any('"github"' in f for f in bss.verify(
                          'team', fixture('team', **{'approvers.json':
                              _json.dumps({'approvers': [{'name': 'A'}]})})))))
        cases.append(('an unfilled {{PLACEHOLDER}} is reported -- bootstrapped '
                      'and never finished',
                      any('unfilled' in f for f in bss.verify(
                          'team', fixture('team',
                                          **{'leak-blocklist.txt': 'a {{NAME}} b'})))))
        cases.append(('an individual config missing individual.path is reported',
                      any('individual.path' in f for f in bss.verify(
                          'individual', fixture('individual', **{'config.json.sample':
                              _json.dumps({'individual': {'name': 'n'}})})))))
        d = fixture('team')
        for f in (d / 'practices').glob('*.md'):
            f.unlink()
        cases.append(('a source with no practice files is reported',
                      any('no practice files' in x for x in bss.verify('team', d))))

    bad = [n for n, ok in cases if not ok]
    for n in bad:
        print(f"  source-shape case did not behave as stated: {n}")
    check(f'a source is verified for shape AND well-formedness '
          f'({len(cases)} stated cases)', not bad)


def check_render_names_files_by_title():
    """A render shows a linked file's title, never its bare filename.

    The repo convention links a document by its filename
    (`[x_model.py](x_model.py)`), which reads fine on the forge and means
    nothing to a reader of the rendered page, who never sees the
    repository. On 2026-10-01 a consumer's published pages showed a dozen
    code filenames in every footer. render() now retitles a
    link whose text IS the target's filename (alone, or followed by a
    section mark): a markdown target by its `# ` title, anything else by a
    humanized filename. A link written with words keeps them.
    (practice: deliverables-look-like-output)"""
    import importlib.util, tempfile, shutil
    spec = importlib.util.spec_from_file_location(
        '_doc_html_titles', ROOT / 'tools' / 'doc_html.py')
    try:
        dh = importlib.util.module_from_spec(spec)
        spec.loader.exec_module(dh)
    except Exception as e:
        not_applicable('a render names linked files by title',
                       f'tools/doc_html.py could not be imported ({e}) -- '
                       f'not a pass')
        return
    tmp = pathlib.Path(tempfile.mkdtemp(prefix='render-titles-',
                                        dir=ROOT))
    cases = []
    try:
        (tmp / 'study.md').write_text("# The Cable Study — what binds\n\nBody.\n",
                                      encoding='utf-8')
        (tmp / 'cable_sizing_model_v1.py').write_text('"""x"""\n',
                                                     encoding='utf-8')
        (tmp / 'page.md').write_text(
            "# Page\n\n"
            "Numbers by: [cable_sizing_model_v1.py](cable_sizing_model_v1.py).\n\n"
            "See [study.md](study.md) and [study.md §3](study.md#x).\n\n"
            "Also [the study itself](study.md) and "
            "[a site](https://example.com/a.md).\n", encoding='utf-8')
        out = tmp / 'page.html'
        dh.render(tmp / 'page.md', out, 'Page')
        body = out.read_text(encoding='utf-8').split('<main>', 1)[1]
        cases.append(('a code link shows its humanized name',
                      '>Cable sizing model</a>' in body))
        cases.append(('a markdown link shows its title',
                      '>The Cable Study — what binds</a>' in body))
        cases.append(('a filename-and-section link keeps the section',
                      '>The Cable Study — what binds §3</a>' in body))
        cases.append(('a link written with words keeps them',
                      '>the study itself</a>' in body))
        cases.append(('an external link is untouched',
                      '>a site</a>' in body))
        cases.append(('no bare filename is left as link text',
                      '>study.md' not in body
                      and '>cable_sizing_model_v1.py<' not in body))
    finally:
        shutil.rmtree(tmp, ignore_errors=True)
    bad = [n for n, ok in cases if not ok]
    for n in bad:
        print(f"  render-title case did not behave as stated: {n}")
    check(f'a render names linked files by title, never by filename '
          f'({len(cases)} stated cases)', not bad)


def check_rendered_docs_are_current():
    """Every committed HTML render still matches its markdown source.

    tools/doc_html.py writes a .html beside each document in its own DOCS
    registry, and nothing checked that the committed render was still the
    one that source produces. It was not: on 2026-09-06 an accidental bare
    run of the tool -- during the sweep for tools that write when they
    should not -- regenerated spec/PREFORK_AUDIT.html and picked up a whole
    paragraph the source had gained and the render had never been rebuilt
    for. A stale render is worse than no render: it is a page that looks
    current, is linked as the readable view of the document, and disagrees
    with it silently.

    generated-artifact-provenance already holds this property for the
    generated VIEWS (MAP.md, GLOSSARY.md, AGENTS.md's block); this is the
    same property for the rendered ones, which that check does not reach.

    The build stamp is excluded from the comparison: it is the one line
    that legitimately differs on every run, so comparing it would make this
    fail constantly and mean nothing.
    """
    import importlib.util, re as _re, tempfile, shutil
    spec = importlib.util.spec_from_file_location(
        '_doc_html', ROOT / 'tools' / 'doc_html.py')
    try:
        dh = importlib.util.module_from_spec(spec)
        spec.loader.exec_module(dh)
    except Exception as e:
        not_applicable('rendered documents are current',
                       f'tools/doc_html.py could not be imported ({e}) -- '
                       f'not a pass')
        return
    if not getattr(dh, 'DOCS', None):
        not_applicable('rendered documents are current',
                       'doc_html.py registers no documents, so there is '
                       'no render to compare')
        return

    # the stamp is a <time> element since 2026-09-14 (reader-local rewrite,
    # dependent repo #1's check-in); the old <div> form is still masked so the
    # check stays green across the boundary commit.
    STAMP = _re.compile(
        r'<(?:div|time) class="renderstamp"[^>]*>[^<]*</(?:div|time)>')
    stale, missing = [], []
    tmp = pathlib.Path(tempfile.mkdtemp(prefix='render-check-'))
    try:
        for rel, title in dh.DOCS:
            src = ROOT / rel
            committed = src.with_suffix('.html')
            if not src.is_file():
                missing.append(f'{rel} (source missing)')
                continue
            if not committed.is_file():
                missing.append(str(committed.relative_to(ROOT)))
                continue
            out = tmp / (pathlib.Path(rel).stem + '.html')
            dh.render(src, out, title)
            a = STAMP.sub('', committed.read_text(encoding='utf-8'))
            b = STAMP.sub('', out.read_text(encoding='utf-8'))
            if a != b:
                stale.append(str(committed.relative_to(ROOT)))
    finally:
        shutil.rmtree(tmp, ignore_errors=True)

    check(f'every registered document\'s HTML render is current '
          f'({len(dh.DOCS)} registered)',
          not stale and not missing,
          '; '.join(
              ([f'stale: {", ".join(stale)}'] if stale else [])
              + ([f'missing: {", ".join(missing)}'] if missing else [])))


def check_install_names_every_not_vendored_dir():
    """INSTALL.md §1 step 1 names everything checkin.py refuses to vendor --
    every NOT_VENDORED directory, and every NOT_VENDORED_ROOT_FILES file.

    These are two halves of one rule kept in two files, which is the shape
    that drifts. tools/checkin.py's NOT_VENDORED/NOT_VENDORED_ROOT_FILES are
    what the tooling acts on; INSTALL.md step 1 is what a person copying the
    tree by hand reads. An entry added to one and not the other means either
    a consumer hand-copies a tree the tooling then reports as drifted, or the
    prose promises an exclusion nothing performs.

    Found when philosophy/ was excluded on 2026-09-14 and nothing would have
    caught the doc being left behind (practice: checkable-gets-checked).
    Name-only: the paragraph's wording is nobody's business but its author's.
    A directory is matched as `name/` (so `spec` inside `specification` can't
    false-positive); a root file has no such delimiter available, so it is
    matched bare -- AGENTS.md/CLAUDE.md are distinctive enough that a bare
    substring match is not a meaningful false-positive risk in a 2000-char
    window, the same tradeoff `not_vendored_share()`'s own comment accepts.
    """
    install = ROOT / 'INSTALL.md'
    if not install.is_file():
        not_applicable('INSTALL.md names every not-vendored directory',
                       'INSTALL.md does not exist -- not a pass')
        return
    try:
        sys.path.insert(0, str(ROOT / 'tools'))
        import checkin as _checkin
        excluded_dirs = set(_checkin.NOT_VENDORED)
        excluded_files = set(_checkin.NOT_VENDORED_ROOT_FILES)
    except Exception as exc:                       # pragma: no cover
        not_applicable('INSTALL.md names every not-vendored directory',
                       f'could not read checkin.NOT_VENDORED: {exc}')
        return
    text = install.read_text(encoding='utf-8')
    # The step is the one that says "Skip"; scoping to it stops an incidental
    # mention elsewhere in a 1000-line document from passing this.
    i = text.find('**Skip ')
    step = text[i:i + 2000] if i != -1 else ''
    missing = sorted(d for d in excluded_dirs if f'{d}/' not in step) + \
        sorted(f for f in excluded_files if f not in step)
    total = len(excluded_dirs) + len(excluded_files)
    check(f'INSTALL.md §1 step 1 names every not-vendored directory/file '
          f'({total} excluded)',
          not missing,
          f'not named in the vendor step: {", ".join(missing)}' if missing
          else '')


def check_philosophy_readme_lists_every_file():
    """philosophy/README.md's list names every file in philosophy/, and no other.

    The page was cut back to one sentence and that list on 2026-09-09, on
    Morgan's instruction, with "updated as the files are changed" as the
    standing requirement. A list that is a document's whole content and is
    maintained by hand is a list that goes stale the first time somebody
    adds a file in a hurry -- and the drift is invisible, because a missing
    entry looks exactly like a directory that never had that file.

    Set comparison, not order: the page orders by importance, which is a
    judgment no check should be holding an opinion about. The recipe at
    philosophy/doc-recipes/README.recipe.md is what this enforces.
    """
    d = ROOT / 'philosophy'
    readme = d / 'README.md'
    if not readme.is_file():
        not_applicable('philosophy README lists every file',
                       'philosophy/README.md does not exist -- not a pass')
        return
    on_disk = {p.name + ('/' if p.is_dir() else '')
               for p in d.iterdir() if p.name != 'README.md'}
    text = readme.read_text(encoding='utf-8')
    listed = set()
    for name in on_disk:
        target = name if name.endswith('/') else name
        if f']({target})' in text:
            listed.add(name)
    # An entry the page names that is not on disk is the other half: a link
    # left behind by a rename reads as a live document until somebody clicks.
    import re as _re
    linked = set(_re.findall(r'\]\((?!\.\.?/|https?:)([^)#]+)\)', text))
    stale = {L for L in linked
             if not (d / L.rstrip('/')).exists()}
    missing = on_disk - listed
    check('philosophy/README.md lists every file in philosophy/ '
          f'({len(on_disk)} on disk)',
          not missing and not stale,
          '; '.join(
              ([f'not listed: {", ".join(sorted(missing))}'] if missing else [])
              + ([f'listed but absent: {", ".join(sorted(stale))}'] if stale else [])))


def check_philosophy_citations_run_both_ways():
    """Every item-to-item citation in philosophy/ is answered by the cited item.

    The essays cite each other by slug. A citation written in one direction
    only leaves the cited item with no way back, which is the whole thing
    philosophy/doc-recipes/backlinks.recipe.md exists to prevent -- and it
    is invisible by inspection, since a one-way link looks exactly like a
    correct one from the citing end.

    The return reference is prose somebody wrote, never generated, so this
    can only report the gap and name the item whose text is missing a
    sentence. tools/philosophy_backlinks.py is the engine; running it here
    is what keeps the convention from being advisory-only
    (checkable-gets-checked).
    """
    tool = ROOT / 'tools' / 'philosophy_backlinks.py'
    if not tool.is_file():
        not_applicable('philosophy citations run both ways',
                       'tools/philosophy_backlinks.py does not exist -- not a pass')
        return
    r = subprocess.run([sys.executable, str(tool)], cwd=str(ROOT),
                       capture_output=True, text=True)
    out = (r.stdout + r.stderr).strip()
    check('every philosophy/ citation runs both ways',
          r.returncode == 0,
          out.replace('\n', ' ')[:400])


def _looks_like_help(tool, out):
    """Does this output actually answer --help, or is it the tool running?

    The test is the tool's own module docstring: a help answer contains a
    real run of it. Deliberately not an exact match -- argparse prints its
    own usage/description rather than the raw docstring, and that is a
    perfectly good help answer.
    """
    import ast
    try:
        doc = ast.get_docstring(ast.parse(tool.read_text(encoding='utf-8')))
    except Exception:
        return True                      # unparseable: not this check's call
    if not doc:
        return True                      # nothing to compare against
    o = ' '.join(out.split()).lower()
    if 'usage:' in o:                    # argparse-generated help
        return True
    for line in doc.strip().splitlines():
        line = ' '.join(line.split())
        if len(line) >= 40 and line.lower() in o:
            return True
    return False


def check_checkin_update_never_mutates_the_clone():
    """`checkin.py update <clone>` reads the clone; it never moves its HEAD.

    Its sibling precedent_vendor_engine.py makes that guarantee explicitly
    and is asserted on it here. checkin.py made no such promise and broke it:
    update() opened with `git checkout <default-branch>` and `git pull`
    INSIDE the caller's clone -- a repository passed only as a SOURCE.

    2026-09-06, found by being on the receiving end. A session running the
    command from a consumer repo had its BestPractice checkout silently
    moved off precedent-beta-v01 onto main, mid-session; it noticed only
    because a directory it expected had vanished from the working tree. The
    command had already FAILED its own guard by then, so the mutation was
    pure collateral -- and on a dirty tree the checkout would have failed
    and left the pull half-applied instead.

    Two properties, since the same call site carried two bugs: the clone is
    untouched, and the branch mirrored is the one the MANIFEST records, not
    the clone's configured default. Every consumer tracks
    precedent-beta-v01 today while main is still the default, so reading the
    default would have mirrored main over a tree vendored from the beta
    branch -- a wholesale revert dressed as an update.
    """
    import shutil, tempfile
    tmp = pathlib.Path(tempfile.mkdtemp(prefix='checkin-update-'))
    try:
        # A source clone with two branches, whose default is NOT the branch
        # the fixture consumer tracks -- the exact shape that made the second
        # bug invisible.
        src = tmp / 'source'
        src.mkdir()
        g = lambda *a: subprocess.run(['git', '-C', str(src), *a],
                                      capture_output=True, text=True)
        g('init', '-q', '-b', 'main')
        g('config', 'user.email', 't@t'); g('config', 'user.name', 't')
        (src / 'marker.txt').write_text('from main\n')
        g('add', '-A'); g('commit', '-qm', 'main content')
        g('checkout', '-qb', 'precedent-beta-v01')
        (src / 'marker.txt').write_text('from beta\n')
        g('add', '-A'); g('commit', '-qm', 'beta content')
        # The clone rests on a THIRD branch, deliberately. Left on `main` it
        # cannot detect record()'s old `checkout <default-branch>`, because
        # checking out the branch you are already on is a no-op -- the first
        # version of this fixture sat on `main` and its negative control
        # passed against the bug. Left on `precedent-beta-v01` it would miss
        # update()'s checkout for the mirror image of the same reason. From
        # `scratch`, a checkout of either one moves HEAD and is caught.
        g('checkout', '-qb', 'scratch')
        (src / 'marker.txt').write_text('scratch, not a branch anything tracks\n')
        g('add', '-A'); g('commit', '-qm', 'scratch content')

        consumer = tmp / 'consumer'
        (consumer / 'process' / 'upstream').mkdir(parents=True)
        (consumer / 'process' / 'upstream' / 'marker.txt').write_text('from beta\n')
        beta = g('rev-parse', 'precedent-beta-v01').stdout.strip()
        (consumer / 'process' / 'manifest.json').write_text(json.dumps({
            'upstream': {'repo': str(src), 'vendored_at': 'process/upstream',
                         'branch': 'precedent-beta-v01', 'commit': beta},
            'entries': []}) + '\n')
        # The real vendored layout: checkin.py derives ROOT from its own
        # location as HERE.parents[3], so it has to sit at
        # process/upstream/tools/ or it resolves the manifest somewhere else
        # entirely.
        (consumer / 'process' / 'upstream' / 'tools').mkdir(parents=True, exist_ok=True)
        shutil.copy2(ROOT / 'tools' / 'checkin.py',
                     consumer / 'process' / 'upstream' / 'tools' / 'checkin.py')
        # checkin.py imports it at module scope (practice:
        # timestamps-carry-offset). The real vendored tree carries it --
        # it is in precedent_vendor_engine.py's ENGINE_FILES -- so this
        # minimal mock of that tree has to as well, or it tests an install
        # shape that never ships.
        shutil.copy2(ROOT / 'tools' / 'precedent_time.py',
                     consumer / 'process' / 'upstream' / 'tools' / 'precedent_time.py')
        # push hands its work to send (2026-09-29); the real vendored tree
        # carries both, since the mirror brings the whole tools/ at once.
        shutil.copy2(ROOT / 'tools' / 'precedent_local_edits.py',
                     consumer / 'process' / 'upstream' / 'tools' / 'precedent_local_edits.py')

        def clone_state():
            return tuple(g(*a).stdout.strip() for a in (
                ('rev-parse', 'HEAD'), ('rev-parse', '--abbrev-ref', 'HEAD'),
                ('status', '--porcelain')))

        before = clone_state()
        r = subprocess.run(
            [sys.executable,
             str(consumer / 'process' / 'upstream' / 'tools' / 'checkin.py'),
             'update', str(src)],
            capture_output=True, text=True, cwd=str(consumer))
        after = clone_state()
        out = r.stdout + r.stderr

        check('checkin.py update leaves the source clone\'s HEAD, branch and '
              'working tree exactly as they were',
              before == after, f'before={before} after={after}\n{out}')
        check('checkin.py update mirrors the branch the MANIFEST records, '
              'not the clone\'s configured default',
              'precedent-beta-v01' in out and
              (consumer / 'process' / 'upstream' / 'marker.txt'
               ).read_text() == 'from beta\n',
              out)

        # record() and push() carried the SAME two bugs, and the first fix
        # reached only update() -- found on the next pass by grepping for the
        # other call sites rather than assuming one fix covered the family.
        # record() is the one that also checked the clone out.
        for sub in ('record', 'push'):
            before2 = clone_state()
            args = [sys.executable,
                    str(consumer / 'process' / 'upstream' / 'tools' / 'checkin.py'),
                    sub, str(src)]
            if sub == 'record':
                args += ['--note', 'harness fixture']
            r2 = subprocess.run(args, capture_output=True, text=True,
                                cwd=str(consumer))
            after2 = clone_state()
            check(f'checkin.py {sub} leaves the source clone\'s HEAD, branch '
                  f'and working tree exactly as they were',
                  before2 == after2,
                  f'before={before2} after={after2}\n{r2.stdout}{r2.stderr}')
            check(f'checkin.py {sub} resolves the branch the MANIFEST '
                  f'records, not the clone\'s configured default',
                  'main' not in (r2.stdout + r2.stderr).replace(
                      'precedent-beta-v01', ''),
                  r2.stdout + r2.stderr)

        # `fresh` is the most-run of the family -- tools/bootstrap.sh calls it
        # at every session start in every consumer -- and it reached the
        # remote a different way, `ls-remote <repo> HEAD`, which resolves the
        # remote's default branch. On a pinned consumer that compared the
        # pinned branch's recorded commit against an unrelated lineage and
        # printed "upstream has moved" every single session, forever.
        # `main` here is deliberately AHEAD of the recorded beta commit, so a
        # default-branch resolution cannot help but report movement.
        r3 = subprocess.run(
            [sys.executable,
             str(consumer / 'process' / 'upstream' / 'tools' / 'checkin.py'),
             'fresh'],
            capture_output=True, text=True, cwd=str(consumer))
        out3 = r3.stdout + r3.stderr
        check('checkin.py fresh compares against the branch the MANIFEST '
              'records, so a pinned install is not told "upstream has moved" '
              'every session by an unrelated lineage',
              'has moved' not in out3, out3)
    finally:
        shutil.rmtree(tmp, ignore_errors=True)


def check_checkin_ignores_files_git_does_not_track_in_the_clone():
    """`checkin.py` status/record compare against what is COMMITTED on the
    pinned branch, and push never deletes a file git does not track.

    2026-09-27, a real consumer's Update Vendors: `record` refused because
    the BestPractice clone held `.claude/settings.local.json` -- gitignored,
    written there by commit-identity.sh at session start to carry the
    person's TZ. record walked the clone's FOLDER, so a per-machine file read
    as "the clone has a file the vendored tree lacks". The session deleted
    it and re-recorded; the next session start wrote it straight back.
    `push` carried the same walk the other way and would have unlinked it,
    along with `.precedent/` and any uncommitted file a person had there.

    The clone also rests on a scratch branch whose commit is NOT what
    landed, because record wrote the clone's HEAD into the manifest: the
    upstream commit it stamps must be origin/<pinned branch>, whatever the
    clone happens to have checked out.

    Negative control (practice: control-asserts-which-failure): run against
    the checkin.py before this fix, status reports the three stray files as
    differing, record exits with "is not identical to the vendored tree",
    and push unlinks all three -- measured 2026-09-27 when this was written.
    """
    import tempfile, json as _json
    if not (ROOT / 'tools' / 'checkin.py').exists():
        not_applicable('checkin.py ignores files git does not track in the '
                       'clone', 'tools/checkin.py is not present in this tree')
        return

    def _git(d, *a):
        return subprocess.run(['git', '-C', str(d)] + list(a),
                              capture_output=True, text=True)

    def _ident(d):
        _git(d, 'config', 'user.email', 'harness@example.com')
        _git(d, 'config', 'user.name', 'Harness')
        _git(d, 'config', 'commit.gpgsign', 'false')

    # Under practices/: the catalogue copy is an allowlist since
    # 2026-09-30, and a top-level file of no known kind stays home.
    shipped = {
        'practices/marker.txt': 'upstream content\n',
        'practices/retired.txt': 'upstream stops vendoring this in the push case\n',
        '.gitignore': '.claude/settings.local.json\n.precedent/\n',
        'tools/checkin.py': (ROOT / 'tools' / 'checkin.py').read_text(encoding='utf-8'),
        'tools/precedent_time.py': (ROOT / 'tools' / 'precedent_time.py'
                                    ).read_text(encoding='utf-8'),
        # push hands the work to send (2026-09-29), from the same directory.
        'tools/precedent_local_edits.py': (ROOT / 'tools' / 'precedent_local_edits.py'
                                           ).read_text(encoding='utf-8'),
        # push() runs the vendored scrub first; this fixture is about the
        # mirror, so the scrub is a stub that passes.
        'tools/practice_audit.py': 'raise SystemExit(0)\n',
    }
    # What a SessionStart hook writes into every clone it runs in, plus a
    # person's own uncommitted file. None of it is upstream content.
    stray = {
        '.claude/settings.local.json': '{"env": {"TZ": "America/New_York"}}\n',
        '.precedent/SESSION_PRACTICES.md': 'practices in force this session\n',
        'notes-in-progress.txt': 'somebody\'s uncommitted work\n',
    }

    def _write(root, files):
        for rel, text in files.items():
            (root / rel).parent.mkdir(parents=True, exist_ok=True)
            (root / rel).write_text(text, encoding='utf-8')

    cases = []
    with tempfile.TemporaryDirectory() as td:
        base = pathlib.Path(td)
        up = base / 'up'
        up.mkdir()
        _git(up, 'init', '-q', '-b', 'main'); _ident(up)
        _write(up, shipped)
        _git(up, 'add', '-A'); _git(up, 'commit', '-qm', 'upstream')

        clone = base / 'clone'
        subprocess.run(['git', 'clone', '-q', str(up), str(clone)],
                       capture_output=True)
        _ident(clone)
        landed = _git(clone, 'rev-parse', 'origin/main').stdout.strip()
        _git(clone, 'checkout', '-qb', 'scratch')
        (clone / 'practices/marker.txt').write_text('scratch, not what landed\n',
                                          encoding='utf-8')
        _git(clone, 'commit', '-qam', 'scratch')
        _write(clone, stray)

        # The consumer is a repo of its own, so checkin.py resolves ROOT to
        # it and not to whatever repository the temp directory sits in
        # (practice: fixture-owns-its-state).
        consumer = base / 'consumer'
        vend = consumer / 'process' / 'upstream'
        vend.mkdir(parents=True)
        _git(consumer, 'init', '-q', '-b', 'main'); _ident(consumer)
        _write(vend, shipped)
        manifest = consumer / 'process' / 'manifest.json'
        manifest.write_text(_json.dumps({'upstream': {
            'repo': 'x/y', 'branch': 'main', 'commit': landed,
            'synced_from': landed}, 'entries': []}) + '\n', encoding='utf-8')

        def run(sub, *extra):
            r = subprocess.run([sys.executable, str(vend / 'tools' / 'checkin.py'),
                                sub, str(clone), *extra],
                               capture_output=True, text=True, cwd=str(consumer),
                               timeout=180)
            return r.returncode, r.stdout + r.stderr

        rc, out = run('status')
        cases.append(('status counts no gitignored or uncommitted clone file '
                      'as a difference', rc == 0 and ' 0 file(s) differ' in out,
                      out))

        rc, out = run('record', '--note', 'harness fixture')
        recorded = _json.loads(manifest.read_text(encoding='utf-8')
                               )['upstream']['commit']
        cases.append(('record passes with the stray files in the clone',
                      rc == 0 and 'checkin record OK' in out, out))
        cases.append(('record stamps origin/<pinned branch>, not the clone\'s '
                      'HEAD on another branch', recorded == landed,
                      f'recorded={recorded} landed={landed}'))

        # push: this repo drops retired.txt. Since 2026-09-29 push hands the
        # work to precedent_local_edits.py send, which builds a branch in a
        # worktree of its own -- so the clone's working tree, tracked files
        # and stray files alike, is never touched, whatever happens next.
        _git(clone, 'checkout', '-q', 'main')
        (vend / 'practices/retired.txt').unlink()
        rc, out = run('push')
        cases.append(('push hands the work to send, which asks what went wrong '
                      'before doing anything', rc == 2
                      and 'precedent_local_edits send REFUSED: --why is required' in out,
                      out))
        survived = [rel for rel, text in stray.items()
                    if (clone / rel).is_file()
                    and (clone / rel).read_text(encoding='utf-8') == text]
        cases.append(('push leaves the clone\'s working tree untouched: every '
                      'file git does not track, and the tracked file this repo '
                      'dropped', len(survived) == len(stray)
                      and (clone / 'practices/retired.txt').is_file(),
                      f'survived={survived}\n{out}'))

    failed = [f'{n}: {d[:400]}' for n, ok, d in cases if not ok]
    check(f'checkin.py ignores files git does not track in the source clone '
          f'({len(cases)} stated cases)', not failed, '\n'.join(failed))


def check_title_case_leaves_code_and_first_word_alone():
    """Headline capitalization never reaches inside an inline code span, and
    the first WORD after an enumerator is capitalized.

    Both learned from real corruption, 2026-09-06. INSTALL.md's own section
    headings had been rewritten by `tools/title_case.py --write` to
    `Process/manifest.json` and `Tools/practice_audit.py` -- neither of which
    exists, in a heading whose whole job is to name the file the section is
    about. The tool's docstring already promised fenced code blocks were
    safe; inline spans were not, and a heading is exactly where a document
    names a path. The same run left `## 5. the Manifest Schema` lowercase,
    because "5." counted as token zero and headline style capitalizes the
    first word, not the first token.

    A tool that rewrites committed prose in place needs its blast radius
    asserted, not described: this is the check that would have caught both
    before they reached the tree.
    """
    import importlib.util
    spec = importlib.util.spec_from_file_location(
        '_title_case', ROOT / 'tools' / 'title_case.py')
    try:
        tc = importlib.util.module_from_spec(spec)
        spec.loader.exec_module(tc)
    except Exception as e:
        not_applicable('title_case leaves code spans and first words alone',
                       f'tools/title_case.py could not be imported ({e}) -- '
                       f'not a pass')
        return

    cases = [
        # (input, must appear in output, why)
        ("5. the Manifest Schema (`process/manifest.json`)",
         "`process/manifest.json`", 'a path in a code span is untouched'),
        ("6. the Audit (`tools/practice_audit.py`)",
         "`tools/practice_audit.py`", 'a second path, different depth'),
        ("5. the Manifest Schema (`process/manifest.json`)",
         "5. The Manifest", 'the first word after an enumerator is capitalized'),
        ("Working With `git rev-parse --verify` Safely",
         "`git rev-parse --verify`", 'a command with flags is untouched'),
        ("A Heading About `AGENTS.md` and `tools/doc_lint.py`",
         "`tools/doc_lint.py`", 'two spans in one heading'),
        # KEEP_PHRASES, both shapes. `The Why` is a noun phrase the SMALL
        # rule would lowercase; `See also` is the mirror image -- `also` is
        # not in SMALL, so headline style reaches for "See Also", which no
        # style guide asks for. The second was carried BY HAND in a dependent
        # repo for a day, re-applied after every engine refresh ate it, with
        # 16 live headings depending on it. It is asserted here because the
        # whole point of upstreaming it was that nobody should have to
        # notice again.
        ("see also", "See also", 'a lowercase cross-reference heading'),
        ("See Also", "See also", 'and one already miscapitalized'),
        ("Notes and see also", "See also", 'mid-heading, not only at the start'),
        ("the why", "The Why", 'the other keep-phrase still keeps its caps'),
    ]
    bad = []
    for text, must, why in cases:
        got = tc.title_case(text)
        if must not in got:
            bad.append(f'{why}: {text!r} -> {got!r} (wanted {must!r} in it)')
    check(f'title_case leaves inline code spans and enumerated first words '
          f'alone ({len(cases)} stated cases)', not bad, '; '.join(bad))


def check_title_case_never_corrupts_content():
    """Headline case is a STYLE change; it must never alter a word or a path.

    All three reproduced from a consuming repo that ran the rule against real
    output documents, 2026-09-07 -- the point at which a rule aimed at
    published prose first met labels, provenance headings and vendored
    subtrees. Every other rule in title_case is a capitalization choice a
    reader could argue with. These produced a DIFFERENT WORD or a path that
    does not resolve, which is a different kind of wrong and is why they get
    their own check.
    """
    import importlib.util
    spec = importlib.util.spec_from_file_location(
        '_tc_corrupt', ROOT / 'tools' / 'title_case.py')
    try:
        tc = importlib.util.module_from_spec(spec)
        spec.loader.exec_module(tc)
    except Exception as e:
        not_applicable('title_case never corrupts content',
                       f'tools/title_case.py could not be imported ({e}) -- '
                       f'not a pass')
        return

    cases = [
        # (input, must appear in output, why)
        ('Option A and Option B', 'Option A and',
         'a capital single-letter LABEL mid-heading is not the article "a"'),
        ('SAMPLE A — book introduction (excerpt)', 'SAMPLE A',
         'the same, with the label in caps'),
        ('Appendix A and the rest', 'Appendix A and',
         'and again -- these are where labels actually live'),
        ('Moved from content/BUSINESS-MODEL-CONCEPTS.md: the moat',
         'content/BUSINESS-MODEL-CONCEPTS.md',
         'a BARE path keeps its segments; capitalizing one breaks the path'),
        ('Running title_case.py on the tree', 'title_case.py',
         'a bare filename, no slash, is a path too'),
        # ... and the rules that must still work, so the fixes above are not
        # a licence to stop capitalizing.
        ('The rise of a nation', 'of a Nation',
         'a real lowercase article is still lowercased'),
        ('A study of moats', 'A Study of Moats',
         'a leading article is still capitalized as the first word'),
        ('Plan B', 'Plan B', 'a last-word label is untouched, as before'),
        ('Exhibit A: the numbers', 'Exhibit A: The',
         'a word after a colon still opens a new phrase'),
        ('Reading and/or writing', 'And/or',
         'prose containing a slash is NOT treated as a path'),
    ]
    bad = []
    for text, must, why in cases:
        got = tc.title_case(text)
        if must not in got:
            bad.append(f'{why}: {text!r} -> {got!r} (wanted {must!r} in it)')
    check(f'title_case never corrupts a word or a path '
          f'({len(cases)} stated cases)', not bad, '; '.join(bad))


def check_title_case_output_paths_inverts_the_default():
    """A repo may DECLARE what it publishes, instead of the tool inferring it.

    title_case's exclusion default reasons from BestPractice's own directory
    names, so in any other tree it names almost nothing and classifies the
    whole working tree as published -- which is how a consumer got 69
    "outward-facing" headings across 10 files, none of them outward-facing.
    `output_paths` inverts that for repos willing to answer, and is opt-in:
    absent, behaviour is exactly what it was, so no existing install moves.

    The case that matters most is the last one: a vendored subtree sitting
    INSIDE a declared output directory. It is mirrored from elsewhere by a
    sync tool, so headings "fixed" there are correct until the next sync and
    then silently revert. internal_paths must win over output_paths for that
    to be expressible at all.
    """
    import importlib.util, tempfile
    spec = importlib.util.spec_from_file_location(
        '_tc_output', ROOT / 'tools' / 'title_case.py')
    try:
        tc = importlib.util.module_from_spec(spec)
        spec.loader.exec_module(tc)
    except Exception as e:
        not_applicable('title_case output_paths inverts the default',
                       f'tools/title_case.py could not be imported ({e}) -- '
                       f'not a pass')
        return

    bad = []
    with tempfile.TemporaryDirectory() as td:
        declared = pathlib.Path(td) / 'declared'; declared.mkdir()
        (declared / 'precedent.json').write_text(json.dumps({
            'format_version': 1,
            'output_paths': ['business-modeling', 'book-joseph'],
            'internal_paths': ['book-joseph/voice-pack'],
        }), encoding='utf-8')
        absent = pathlib.Path(td) / 'absent'; absent.mkdir()
        (absent / 'precedent.json').write_text(
            json.dumps({'format_version': 1}), encoding='utf-8')
        empty = pathlib.Path(td) / 'empty'; empty.mkdir()
        (empty / 'precedent.json').write_text(json.dumps({
            'format_version': 1, 'output_paths': []}), encoding='utf-8')

        cases = [
            (declared, 'business-modeling/plan.md', True, 'a declared output path is output'),
            (declared, 'book-joseph/ch1.md', True, 'so is the second one'),
            (declared, 'notes/scratch.md', False, 'anything undeclared is internal'),
            (declared, 'README.md', False, 'including a root document'),
            (declared, 'practices/x.md', False, 'the engine exclusions still hold'),
            (declared, 'business-modeling/practices/y.md', False,
             'a vendored practices tree inside an output path is still excluded'),
            (declared, 'book-joseph/voice-pack/tone.md', False,
             'internal_paths WINS over output_paths -- the vendored-subtree case'),
            (absent, 'README.md', True, 'absent: unchanged, everything not excluded is output'),
            (absent, 'MAP.source.md', False,
             "a map's source is internal like the map it feeds (a consumer, 2026-10-03)"),
            (absent, 'GLOSSARY.source.md', False,
             "...and so is a glossary's"),
            (absent, 'notes/x.md', True, 'absent: unchanged for a working directory too'),
            (empty, 'README.md', False,
             'an EMPTY output_paths is a declaration ("we publish nothing"), not an absence'),
        ]
        for root, rel, want, why in cases:
            got = tc.is_outward(rel, root=root)
            if got != want:
                bad.append(f'{why}: is_outward({rel!r}) == {got}, wanted {want}')

    check(f'title_case output_paths inverts the default, opt-in, with '
          f'internal_paths still subtracting ({len(cases)} stated cases)',
          not bad, '; '.join(bad))


def check_title_case_honours_repo_declared_internal_paths():
    """A repo can exclude its own directories from headline capitalization
    through precedent.json, and cannot use that key to re-include what the
    engine excludes.

    tools/title_case.py is VENDORED into every consumer, so its
    INTERNAL_DIRS / INTERNAL_FILES lists are Precedent's names, not the
    adopter's, and an engine refresh overwrites anything edited into them.
    The exclusion default that fails safe upstream fails the other way in a
    consumer: every working directory nobody happened to name reads as
    published. 2026-09-07, a real consumer came back from an engine update
    with 69 "outward-facing" headings across 10 files, none of them
    outward-facing.

    Two properties, and the second matters more than the first: the key
    must ADD exclusions and must never subtract one. A consumer that could
    re-include `practices/` would have this tool rewriting headings inside
    a vendored upstream tree, undone by the next refresh -- the exact
    failure is_outward's own `practices` guard was added to stop.
    """
    import importlib.util, tempfile
    spec = importlib.util.spec_from_file_location(
        '_title_case_ip', ROOT / 'tools' / 'title_case.py')
    try:
        tc = importlib.util.module_from_spec(spec)
        spec.loader.exec_module(tc)
    except Exception as e:
        not_applicable('title_case honours repo-declared internal_paths',
                       f'tools/title_case.py could not be imported ({e}) -- '
                       f'not a pass')
        return

    bad = []
    with tempfile.TemporaryDirectory() as td:
        root = pathlib.Path(td)
        (root / 'precedent.json').write_text(json.dumps({
            'format_version': 1,
            'internal_paths': ['notes', 'docs/drafts', 'ROADMAP.md',
                               '/escapes', '../escapes', 7, ''],
            # A consumer must not be able to re-include what the engine
            # excludes; this entry is here to prove it is ignored, since
            # the key only ever adds.
            'sources': [],
        }), encoding='utf-8')

        cases = [
            # (path, expected is_outward, why)
            ('README.md', True, 'an undeclared root document stays outward'),
            ('documentation/pitch.md', True, 'an undeclared directory stays outward'),
            ('notes/scratch.md', False, 'a declared directory is internal'),
            ('notes/deep/er.md', False, 'everything under it, at any depth'),
            ('docs/drafts/one.md', False, 'a nested declared path is internal'),
            ('docs/published.md', True, 'its sibling is not'),
            ('notesy/other.md', True, 'a prefix match is on path segments, not characters'),
            ('ROADMAP.md', False, 'a declared single file is internal'),
            ('practices/x.md', False, 'the engine exclusion still holds'),
        ]
        for rel, want, why in cases:
            got = tc.is_outward(rel, root=root)
            if got != want:
                bad.append(f'{why}: is_outward({rel!r}) == {got}, wanted {want}')

        # Malformed config fails OPEN -- the built-in boundary, never a crash.
        broken = pathlib.Path(td) / 'broken'
        broken.mkdir()
        (broken / 'precedent.json').write_text('{not json at all',
                                               encoding='utf-8')
        try:
            if tc.is_outward('README.md', root=broken) is not True:
                bad.append('a malformed precedent.json changed the boundary')
        except Exception as e:
            bad.append(f'a malformed precedent.json raised {e!r}')

        # No config at all: same.
        empty = pathlib.Path(td) / 'empty'
        empty.mkdir()
        try:
            if tc.is_outward('README.md', root=empty) is not True:
                bad.append('a missing precedent.json changed the boundary')
        except Exception as e:
            bad.append(f'a missing precedent.json raised {e!r}')

    check('title_case honours repo-declared internal_paths, additively only '
          '(11 stated cases)', not bad, '; '.join(bad))


def _push_gate_fixture(tmp, real_modules=()):
    """A consumer-shaped repository with a bare origin, for the push-check
    cases below. The basic tier's checks are stand-ins, except the modules
    named in `real_modules` ('*' for every one), copied from this engine,
    and the leak gate and lint, which always pass. The author check is a
    full-history stand-in, the shape an older vendored copy has, flagging
    every commit by 'Mallory'; the workflow check flags every workflow file
    that APPROVED does not name, in precedent_check's own output shape.
    -> (work, env, git)."""
    import json as _json, shutil as _shutil
    env = dict(os.environ, PRECEDENT_ALLOW_ANY_AUTHOR='1',
               GIT_AUTHOR_NAME='T', GIT_AUTHOR_EMAIL='t@example.com',
               GIT_COMMITTER_NAME='T', GIT_COMMITTER_EMAIL='t@example.com',
               GIT_CONFIG_GLOBAL=str(tmp / 'gitconfig'), GIT_CONFIG_NOSYSTEM='1',
               PRECEDENT_USER_CONFIG=str(tmp / 'no-user-config.json'),
               PRECEDENT_NO_SHARED_PASS='1')

    def git(cwd, *a, **kw):
        return subprocess.run(['git', '-C', str(cwd), *a], capture_output=True,
                              text=True, env=dict(env, **kw))

    origin, work = tmp / 'origin.git', tmp / 'work'
    git(tmp, 'init', '-q', '--bare', '-b', 'main', str(origin))
    git(tmp, 'init', '-q', '-b', 'main', str(work))
    git(work, 'remote', 'add', 'origin', str(origin))
    tools = work / 'tools'
    (tools / 'checks').mkdir(parents=True)
    if real_modules == '*':
        real_modules = tuple(p.stem for p in (ROOT / 'tools').glob('*.py')
                             if p.name != 'verify_harness.py')
    for m in ('precedent_push_check', 'precedent_branches', *real_modules):
        _shutil.copy2(ROOT / 'tools' / f'{m}.py', tools / f'{m}.py')
    (tools / 'ENGINE_MANIFEST.json').write_text(
        _json.dumps({'kind': 'consumer'}), encoding='utf-8')
    for t in ('leak_gate', 'doc_lint'):
        (tools / f'{t}.py').write_text('import sys\nsys.exit(0)\n', encoding='utf-8')
    if 'precedent_check' not in real_modules:
        (tools / 'precedent_check.py').write_text(
            'import pathlib, sys\n'
            'if __name__ == "__main__":\n'
            '    bad = []\n'
            '    if "ci-workflow-approved" in sys.argv:\n'
            '        ok = pathlib.Path("APPROVED").read_text().split() '
            'if pathlib.Path("APPROVED").exists() else []\n'
            '        wf = pathlib.Path(".github/workflows")\n'
            '        bad = sorted(f"{p}" for p in wf.glob("*.yml") '
            'if p.name not in ok) if wf.is_dir() else []\n'
            '    if bad:\n'
            '        print("\\nVIOLATION  ci-workflow-approved")\n'
            '        for b in bad:\n'
            '            print(f"    {b}: has no approval")\n'
            '        print("  the rule:")\n'
            '        print("    a workflow needs the person\'s words")\n'
            '    print("\\nprecedent_check: %d passed, %d violated" '
            '% (0 if bad else 1, 1 if bad else 0))\n'
            '    sys.exit(1 if bad else 0)\n', encoding='utf-8')
    (tools / 'checks' / 'check_commit_author.py').write_text(
        '#!/usr/bin/env python3\n'
        '"""Stand-in: every commit reachable from HEAD, as older copies read."""\n'
        '# practice: commit-author\n'
        'import subprocess, sys\n'
        'log = subprocess.run(["git", "log", "--format=%H|%an"], '
        'capture_output=True, text=True).stdout.split()\n'
        'bad = [l.split("|")[0] for l in log if l.endswith("|Mallory")]\n'
        'if bad:\n'
        '    print("VIOLATION: commit-author")\n'
        '    for sha in bad:\n'
        '        print(f"  commit {sha[:12]}: author is \'Mallory\', expected \'T\'")\n'
        '    print("\\nthe rule:\\n  commits carry the declared author")\n'
        '    sys.exit(1)\n', encoding='utf-8')
    git(work, 'add', '-A')
    git(work, 'commit', '-q', '-m', 'init')
    return work, env, git


def check_push_gate_judges_only_what_a_working_branch_brings():
    """A push to a working branch is refused over what it brings, never over
    findings already on origin's tier branches.

    2026-09-28, a consumer: the push gate's basic tier refused a push of a
    claude/* branch -- commit_author over two old commits already on main,
    ci_workflows over a workflow already on main -- and the Stop hook
    refused to end the turn with the commit unpushed. The session could
    neither push nor stop until the person answered, and nothing the push
    could do would have fixed either finding."""
    import tempfile
    name = ('a working-branch push is judged on what it brings; findings '
            'already on a tier branch are reported, not blocking')
    cases = []
    with tempfile.TemporaryDirectory() as td:
        tmp = pathlib.Path(td)
        work, env, git = _push_gate_fixture(tmp)

        def push_check(dest):
            p = subprocess.run([sys.executable, 'tools/precedent_push_check.py',
                                '--gate', '--push-command', f'origin {dest}'],
                               cwd=work, capture_output=True, text=True, env=env,
                               timeout=300)
            return p.returncode, p.stdout + p.stderr

        (work / 'm.txt').write_text('old\n', encoding='utf-8')
        git(work, 'add', '-A')
        git(work, 'commit', '-q', '-m', 'an old commit by someone else',
            GIT_AUTHOR_NAME='Mallory', GIT_AUTHOR_EMAIL='m@example.com')
        (work / '.github' / 'workflows').mkdir(parents=True)
        (work / '.github' / 'workflows' / 'old.yml').write_text('on: push\n',
                                                               encoding='utf-8')
        git(work, 'add', '-A')
        git(work, 'commit', '-q', '-m', 'an old unapproved workflow')
        git(work, 'push', '-q', 'origin', 'main')
        git(work, 'checkout', '-q', '-b', 'claude/fix')
        (work / 'fix.txt').write_text('fix\n', encoding='utf-8')
        git(work, 'add', '-A')
        git(work, 'commit', '-q', '-m', 'the session\'s own fix')

        rc, out = push_check('claude/fix')
        cases.append(('a claude/* branch bringing a clean commit onto main\'s '
                      'old findings is let through, and says what it found'
                      f' (exit {rc}: {out.strip().splitlines()[-1:]})',
                      rc == 0 and 'reported, not blocking' in out
                      and 'commit_author' in out and 'ci_workflows' in out))
        rc, _ = push_check('main')
        cases.append(('the same findings still refuse a push to main, a tier '
                      'branch', rc == 1))

        (work / '.github' / 'workflows' / 'new.yml').write_text(
            'on: push\n', encoding='utf-8')
        git(work, 'add', '-A')
        git(work, 'commit', '-q', '-m', 'a new unapproved workflow')
        rc, out = push_check('claude/fix')
        cases.append(('a workflow the branch itself adds still refuses it, '
                      'naming that file', rc == 1 and 'new.yml' in out))
        git(work, 'reset', '-q', '--hard', 'HEAD~1')

        (work / 'm2.txt').write_text('new\n', encoding='utf-8')
        git(work, 'add', '-A')
        git(work, 'commit', '-q', '-m', 'a new commit by someone else',
            GIT_AUTHOR_NAME='Mallory', GIT_AUTHOR_EMAIL='m@example.com')
        new = git(work, 'rev-parse', 'HEAD').stdout.strip()
        rc, out = push_check('claude/fix')
        cases.append(('a wrong-author commit the branch brings still refuses '
                      'it, naming that commit', rc == 1 and new[:12] in out))
    failed = [n for n, ok in cases if not ok]
    check(f'{name} ({len(cases)} stated cases)', not failed, '; '.join(failed))


def check_push_check_honours_not_binding():
    """precedent_push_check.py honours a repo's `not_binding` exactly as
    precedent_check.py does, by asking precedent_check's own
    load_exemptions().

    2026-09-28, a consumer: its precedent.json declared commit-author not
    binding, precedent_check reported it EXEMPT, and the push check ran
    tools/checks/check_commit_author.py directly anyway and refused a push
    over two old commits already on main."""
    import tempfile, json as _json
    name = 'the push check honours not_binding the way precedent_check does'
    cases = []
    with tempfile.TemporaryDirectory() as td:
        tmp = pathlib.Path(td)
        # The real engine modules, so the exemption is read by
        # precedent_check itself.
        work, env, git = _push_gate_fixture(tmp, real_modules='*')
        (work / 'm.txt').write_text('x\n', encoding='utf-8')
        git(work, 'add', '-A')
        git(work, 'commit', '-q', '-m', 'a commit by someone else',
            GIT_AUTHOR_NAME='Mallory', GIT_AUTHOR_EMAIL='m@example.com')

        def push_check():
            p = subprocess.run([sys.executable, 'tools/precedent_push_check.py',
                                '--tier', 'basic'], cwd=work, capture_output=True,
                               text=True, env=env, timeout=300)
            return p.returncode, p.stdout + p.stderr

        rc, out = push_check()
        cases.append(('with no exemption the author check still refuses',
                      rc == 1 and 'commit_author' in out))
        reason = 'many people commit here, so no one author binds it'
        (work / 'precedent.json').write_text(_json.dumps(
            {'not_binding': [{'slug': 'commit-author', 'reason': reason}]}),
            encoding='utf-8')
        git(work, 'add', '-A')
        git(work, 'commit', '-q', '-m', 'declare commit-author not binding')
        pc = subprocess.run([sys.executable, '-c',
                             'import sys; sys.path.insert(0, "tools"); '
                             'import precedent_check as pc; '
                             'print(sorted(pc.load_exemptions()[0]))'],
                            cwd=work, capture_output=True, text=True, env=env)
        cases.append(("precedent_check's own load_exemptions() reads it as "
                      "exempt (the fixture is real)",
                      "['commit-author']" in pc.stdout))
        rc, out = push_check()
        cases.append((f'declared not binding, the push check skips it, says '
                      f'EXEMPT with the reason, and passes (exit {rc})',
                      rc == 0 and 'EXEMPT' in out and reason in out))
    failed = [n for n, ok in cases if not ok]
    check(f'{name} ({len(cases)} stated cases)', not failed, '; '.join(failed))


def check_merge_gate_waits_for_a_current_merge_ref():
    """The merge gate judges GitHub's test merge only once its second parent
    is the pull request's current head.

    2026-09-28, measured: a session pushed a fix to a pull request's head
    and merged at once. The gate judged refs/pull/N/merge as it stood before
    the push -- the old head, still carrying the bug -- refused, and called
    it "the merge GitHub would make". A minute later the merge ref had the
    new head as its second parent and the same merge passed. The GitHub
    head lookup is stubbed; the refs live in a bare origin."""
    import tempfile, io, contextlib
    name = ('the merge gate never judges a test merge of an older head as '
            'the current one')
    sys.path.insert(0, str(ROOT / 'tools'))
    try:
        import precedent_merge_check as pmc
        import github_budget
    finally:
        sys.path.pop(0)
    cases = []
    saved_env = dict(os.environ)
    saved_call, saved_sleep = github_budget.call, getattr(pmc, '_sleep', None)
    with tempfile.TemporaryDirectory() as td:
        tmp = pathlib.Path(td)
        env = dict(os.environ, PRECEDENT_ALLOW_ANY_AUTHOR='1',
                   GIT_AUTHOR_NAME='T', GIT_AUTHOR_EMAIL='t@example.com',
                   GIT_COMMITTER_NAME='T', GIT_COMMITTER_EMAIL='t@example.com',
                   GIT_CONFIG_GLOBAL=str(tmp / 'gitconfig'), GIT_CONFIG_NOSYSTEM='1',
                   PRECEDENT_USER_CONFIG=str(tmp / 'no-user-config.json'))

        def git(cwd, *a):
            return subprocess.run(['git', '-C', str(cwd), *a], capture_output=True,
                                  text=True, env=env).stdout.strip()

        origin = tmp / 'o' / 'r.git'
        origin.parent.mkdir()
        git(tmp, 'init', '-q', '--bare', '-b', 'main', str(origin))
        src = tmp / 'src'
        git(tmp, 'init', '-q', '-b', 'main', str(src))
        (src / 'tools').mkdir()
        # The push check this gate runs: fails while BUG is in the tree.
        (src / 'tools' / 'precedent_push_check.py').write_text(
            'import pathlib, sys\n'
            'bug = pathlib.Path("BUG").exists()\n'
            'print("precedent_push_check: FAILED -- BUG is here" if bug '
            'else "precedent_push_check: all passed")\n'
            'sys.exit(1 if bug else 0)\n', encoding='utf-8')
        git(src, 'add', '-A')
        git(src, 'commit', '-q', '-m', 'base')
        base = git(src, 'rev-parse', 'HEAD')
        git(src, 'checkout', '-q', '-b', 'feature')
        (src / 'BUG').write_text('x\n', encoding='utf-8')
        git(src, 'add', '-A')
        git(src, 'commit', '-q', '-m', 'the change, with its bug')
        old = git(src, 'rev-parse', 'HEAD')
        git(src, 'rm', '-q', 'BUG')
        git(src, 'commit', '-q', '-m', 'fix the bug')
        new = git(src, 'rev-parse', 'HEAD')

        def test_merge(head):
            tree = git(src, 'rev-parse', f'{head}^{{tree}}')
            return git(src, 'commit-tree', tree, '-p', base, '-p', head, '-m', 'merge')
        merge_old, merge_new = test_merge(old), test_merge(new)
        git(src, 'push', '-q', str(origin), 'main', f'{new}:refs/heads/feature',
            f'{new}:refs/pull/7/head', f'{merge_old}:refs/pull/7/merge',
            f'{merge_new}:refs/heads/merge-new-keep')
        checkout = tmp / 'checkout'
        git(tmp, 'clone', '-q', str(origin), str(checkout))

        def stub_call(path, *a, **kw):
            return ({'head': {'ref': 'feature', 'sha': new,
                              'repo': {'full_name': 'o/r'}},
                     'base': {'ref': 'main'}}, None)

        def run(catches_up):
            git(src, 'push', '-q', '-f', str(origin), f'{merge_old}:refs/pull/7/merge')
            slept = []

            def stub_sleep(_s):
                slept.append(_s)
                if catches_up and len(slept) == 1:
                    git(src, 'push', '-q', '-f', str(origin),
                        f'{merge_new}:refs/pull/7/merge')
            pmc._sleep = stub_sleep
            buf = io.StringIO()
            with contextlib.redirect_stdout(buf):
                rc = pmc.main(['--owner', 'o', '--repo', 'r', '--number', '7',
                               '--search', str(checkout)])
            return rc, buf.getvalue()

        try:
            os.environ.update({k: env[k] for k in (
                'GIT_CONFIG_GLOBAL', 'GIT_CONFIG_NOSYSTEM', 'PRECEDENT_USER_CONFIG',
                'PRECEDENT_ALLOW_ANY_AUTHOR')})
            github_budget.call = stub_call
            rc, out = run(catches_up=True)
            cases.append((f'a stale test merge is waited out, and the rebuilt '
                          f'one is judged and passes (exit {rc})',
                          rc == 0 and merge_new[:12] in out
                          and merge_old[:12] not in out))
            rc, out = run(catches_up=False)
            cases.append((f'a test merge that never catches up is not judged; '
                          f'the current head is, and the output says so (exit {rc})',
                          rc == 0 and 'older head' in out and new[:12] in out
                          and merge_old[:12] not in out))
            git(src, 'push', '-q', '-f', str(origin), f'{merge_new}:refs/pull/7/merge')
            slept = []
            pmc._sleep = slept.append
            buf = io.StringIO()
            with contextlib.redirect_stdout(buf):
                rc = pmc.main(['--owner', 'o', '--repo', 'r', '--number', '7',
                               '--search', str(checkout)])
            cases.append(('a current test merge is judged at once, with no wait',
                          rc == 0 and not slept and merge_new[:12] in buf.getvalue()))
        except Exception as e:                                # noqa: BLE001
            cases.append((f'the gate raised {type(e).__name__}: {e}', False))
        finally:
            os.environ.clear()
            os.environ.update(saved_env)
            github_budget.call = saved_call
            if saved_sleep is not None:
                pmc._sleep = saved_sleep
    failed = [n for n, ok in cases if not ok]
    check(f'{name} ({len(cases)} stated cases)', not failed, '; '.join(failed))


def check_loader_block_covers_every_declared_source():
    """The loader block renders every PUBLISHABLE source `precedent.json`
    declares -- and never a private one in a public repo.

    Measured here 2026-09-06, before the fix: 65 of 65 universal practices
    reached this repo's block, 0 of 41 team, 0 of 11 individual. The config
    declared all three, the resolver agreed, and the one artifact a session
    actually reads listed only the first. A rule nothing can load is not in
    force; it is filed. That is what the first half asserts, and it is the
    whole rule in a private consumer repo -- which is every repo that
    vendors this engine.

    The second half is the privacy boundary, and it is the reason this is a
    check rather than a setting somebody remembers.
    `precedent_resolve.py` already refuses to let a shared repo DECLARE an
    individual source, because naming it leaks its existence and location.
    Rendering a private source's practices into a tracked, published file is
    the same disclosure arriving by another route -- so a repo marked
    `"visibility": "public"` must never carry team- or individual-level
    content in its block, and a regression there publishes a private set
    silently and permanently. This repo is that public case; see
    decisions/2026-09-06-precedent-binds-itself.md section 2, which rejected
    multi-source generated views here on exactly this ground.
    """
    import json as _json
    config = ROOT / 'precedent.json'
    if not config.is_file():
        not_applicable('the loader block covers every declared source',
                       'this repo declares no precedent.json')
        return
    try:
        import precedent_resolve as pr
        declared = pr.load_config(ROOT)
        cfg = _json.loads(config.read_text(encoding='utf-8'))
    except Exception as e:
        not_applicable('the loader block covers every declared source',
                       f'sources did not resolve here ({e}) -- not a pass')
        return

    agents = ROOT / 'AGENTS.md'
    if not agents.is_file():
        not_applicable('the loader block covers every declared source',
                       'this repo has no AGENTS.md')
        return
    name = 'AGENTS.md'
    instructions = agents.read_text(encoding='utf-8')
    a, b = '<!-- BEGIN GENERATED', '<!-- END GENERATED'
    if a not in instructions or b not in instructions:
        not_applicable('the loader block covers every declared source',
                       'AGENTS.md carries no generated loader block')
        return
    # Only the GENERATED block counts. A slug mentioned in hand-written prose
    # is not the loader pointing a session at it.
    block = instructions[instructions.index(a):instructions.index(b)]
    # Slugs the loader ACTUALLY indexes, read from the two shapes the
    # generated block uses -- an occasion-index line ("  slug — clause") and
    # a resident entry ("**slug.** ..."). Matching bare words in prose
    # instead was wrong both ways: it required a hyphen, so a single-word
    # slug like `install` could never be found and was reported unreachable
    # forever; and loosening the pattern to allow single words would have
    # matched the ordinary English word "install" anywhere in the file and
    # called the practice reachable when nothing indexed it.
    named = set(re.findall(r'^\s+([a-z0-9][a-z0-9-]*) \u2014 ', block, re.M))
    named |= set(re.findall(r'^\*\*([a-z0-9][a-z0-9-]*)\.\*\*', block, re.M))

    public = cfg.get('visibility') == 'public'

    # Slugs a PUBLISHABLE source (universal, or repo-local, which lives in
    # this repo's own tree) has active. A slug in both a publishable source
    # and a private one is NOT evidence of a leak: build_views.py excludes
    # private-level sources from a public repo's block, so the entry the
    # block carries is the publishable source's own text, and only the SLUG
    # is shared. Without this the guard fired on the first same-slug
    # override to exist (catalogue-carries-stories, 2026-09-07 -- landed at
    # universal, and the shared source that had authored it first kept a copy
    # to put the rule in force on itself, since a source repo consumes no
    # catalogue). Verified by reading the rendered line: it was universal's
    # index_clause, not the team's. A finding nobody can act on without
    # deleting a legitimate practice is one people learn to ignore.
    publishable = set()
    for s in declared:
        if s['level'] in ('shared', 'team', 'individual'):
            continue
        d = pathlib.Path(s['path']) / 'practices'
        if not d.is_dir():
            continue
        for f in sorted(d.glob('*.md')):
            try:
                fm, _sec = sp._read_practice_file(f)
            except Exception:
                continue
            if (fm.get('status') or 'active').strip('" ') == 'active':
                publishable.add(fm.get('slug', f.stem))

    import build_views as _bv
    missing, leaked = [], []
    for s in declared:
        d = pathlib.Path(s['path']) / 'practices'
        if not d.is_dir():
            continue                       # unreachable here; not evidence
        active, expected_in_block = [], []
        for f in sorted(d.glob('*.md')):
            try:
                fm, _sec = sp._read_practice_file(f)
            except Exception:
                continue
            if (fm.get('status') or 'active').strip('" ') == 'active':
                active.append(fm.get('slug', f.stem))
                # A practice routed by a real applies_to glob or a gate is
                # deliberately NOT named in the block -- build_views omits it
                # from the occasion index because those channels already reach
                # it. A source whose practices are ALL routed therefore
                # contributes nothing to the rendered text while having
                # resolved perfectly, so requiring its name here would be a
                # false failure. Only a source with at least one practice that
                # should appear is evidence of anything either way.
                if not _bv.index_is_redundant(fm):
                    expected_in_block.append(fm.get('slug', f.stem))
        if not active:
            continue
        present = [a for a in active if a in named]
        if public and s['level'] in ('shared', 'team', 'individual'):
            leaked += [a for a in present if a not in publishable]
        elif not present and expected_in_block:
            missing.append(f"{s['level']}/{s['name']} ({len(expected_in_block)} of "
                           f"{len(active)} active practices should be named in "
                           f"{name}, none is)")

    check('the loader block renders every publishable source '
          'precedent.json declares', not missing, '; '.join(missing))
    if public:
        check('no private-source practice reaches a public repo\'s tracked '
              'loader block',
              not leaked,
              f'{len(leaked)} leaked: {", ".join(sorted(leaked)[:6])}')


def check_very_deep_check_fixes_a_renamed_repository():
    """When GitHub answers a named repository under a new full name, the very
    deep check repoints the clone's remote and rewrites every CURRENT
    reference, leaving history as written (Morgan, 2026-09-29, strength:
    decided). Discriminating cases: a live line changes; a practice's
    ## Story, a todo/ record and a line about the rename keep the old name;
    the origin remote follows; and a new name that is private is not written
    into a public repository."""
    import io, shutil, tempfile
    sys.path.insert(0, str(ROOT / 'tools'))
    import very_deep_check as vdc
    tmp = pathlib.Path(tempfile.mkdtemp(prefix='rename-fix-'))
    env = dict(os.environ, GIT_AUTHOR_NAME='f', GIT_AUTHOR_EMAIL='f@invalid',
               GIT_COMMITTER_NAME='f', GIT_COMMITTER_EMAIL='f@invalid')

    def git(*a):
        return subprocess.run(['git', '-C', str(tmp), *a], env=env,
                              capture_output=True, text=True).stdout.strip()
    cases = []
    try:
        git('init', '-q')
        (tmp / 'practices').mkdir()
        (tmp / 'todo').mkdir()
        (tmp / 'README.md').write_text(
            'Clone https://github.com/acme/old-tool to start.\n'
            'It was renamed from acme/old-tool in 2026.\n', encoding='utf-8')
        (tmp / 'practices' / 'x.md').write_text(
            '---\nslug: x\nstatus: active\n---\n## Rule\nUse acme/old-tool.\n\n'
            '## Story\nWe first used acme/old-tool.\n', encoding='utf-8')
        (tmp / 'todo' / 'todo-x.md').write_text('acme/old-tool was slow.\n',
                                                encoding='utf-8')
        (tmp / 'NOTES.md').write_text('See acme/secret-old.\n', encoding='utf-8')
        git('add', '-A'); git('commit', '-q', '-m', 'x')
        git('remote', 'add', 'origin', 'https://github.com/acme/old-tool.git')
        vdc.fix_repo_renames({('acme', 'old-tool'): 'acme/new-tool',
                              ('acme', 'secret-old'): 'acme/secret-new'},
                             [tmp], private={'acme/secret-new'},
                             out=io.StringIO())
        readme = (tmp / 'README.md').read_text(encoding='utf-8')
        prac = (tmp / 'practices' / 'x.md').read_text(encoding='utf-8')
        cases.append(('a live reference is rewritten',
                      'github.com/acme/new-tool to start' in readme, readme))
        cases.append(('a line about the rename keeps the old name',
                      'renamed from acme/old-tool' in readme, readme))
        cases.append(('the Rule changes and the Story keeps its history',
                      'Use acme/new-tool.' in prac
                      and 'first used acme/old-tool' in prac, prac))
        cases.append(('a todo record is left as written',
                      'acme/old-tool' in (tmp / 'todo' / 'todo-x.md').read_text(),
                      'todo rewritten'))
        cases.append(('the origin remote follows the rename',
                      git('remote', 'get-url', 'origin')
                      == 'https://github.com/acme/new-tool.git',
                      git('remote', 'get-url', 'origin')))
        cases.append(('a private new name is not written into a public repo',
                      'acme/secret-old' in (tmp / 'NOTES.md').read_text(),
                      (tmp / 'NOTES.md').read_text()))
    finally:
        shutil.rmtree(tmp, ignore_errors=True)
    bad = [(c[0], c[2]) for c in cases if not c[1]]
    check(f'the very deep check fixes a renamed repository '
          f'({len(cases)} stated cases)',
          not bad, '; '.join(f"{n} -- {str(d)[:300]}" for n, d in bad))


def check_review_page_lists_practices_that_may_overlap():
    """The review page's third part lists practice pairs that read alike --
    across sources and within one -- with the session's verdict beside each
    (Morgan, 2026-09-29, strength: decided). Discriminating cases: the same
    slug in two sources is listed whatever its score; two differently named
    rules saying the same thing in different sources are listed; an
    unrelated pair is not; and a verdict passed in is shown beside its pair
    while an unjudged one says so."""
    import shutil, tempfile
    sys.path.insert(0, str(ROOT / 'tools'))
    import precedent_review_page as rp
    PRACTICE = ('---\nslug: {slug}\ntitle: "{title}"\ntier: on-demand\n'
                'severity: advisory\napplies_to: ["**"]\n'
                'occasion: "{occ}"\ngates: []\nindex_clause: "{occ}"\n'
                'checked_by: null\ndefines: []\nstatus: active\n'
                'in_force_at: null\nsupersedes: []\noverrides: null\n'
                'added: null\napproved_by: "fixture"\n---\n## Rule\n{rule}\n')
    tmp = pathlib.Path(tempfile.mkdtemp(prefix='overlap-'))
    cases = []
    try:
        def put(src, slug, title, occ, rule):
            d = tmp / src / 'practices'
            d.mkdir(parents=True, exist_ok=True)
            (d / f'{slug}.md').write_text(PRACTICE.format(
                slug=slug, title=title, occ=occ, rule=rule), encoding='utf-8')
        twin = ('Name the spreadsheet column after the quarterly invoice '
                'ledger reconciliation total, never a vague heading.')
        put('uni', 'ledger-column-names', 'Ledger columns', 'naming a ledger column', twin)
        put('shr', 'invoice-heading-words', 'Invoice headings', 'naming a ledger column', twin)
        put('uni', 'same-rule', 'Same', 'a thing happens', 'Harbour pilots board early.')
        put('shr', 'same-rule', 'Same', 'a thing happens', 'Harbour pilots board early.')
        put('uni', 'weather-log', 'Weather', 'logging rain', 'Record barometric pressure hourly at the lighthouse.')
        put('shr', 'recipe-salt', 'Salt', 'seasoning soup', 'Taste the broth before adding coarse kosher salt.')
        sources = [{'name': 'uni', 'level': 'universal', 'path': str(tmp / 'uni')},
                   {'name': 'shr', 'level': 'shared', 'path': str(tmp / 'shr')}]
        pairs = rp.similar_pairs(sources)
        keys = {rp._pair_key(p): p['kind'] for p in pairs}
        k_same = frozenset(('uni:same-rule', 'shr:same-rule'))
        k_twin = frozenset(('uni:ledger-column-names', 'shr:invoice-heading-words'))
        k_none = frozenset(('uni:weather-log', 'shr:recipe-salt'))
        cases.append(('the same slug in two sources is listed as such',
                      keys.get(k_same) == 'same slug', repr(keys)))
        cases.append(('two rules saying the same thing in different sources '
                      'are listed', keys.get(k_twin) == 'different sources',
                      repr(keys)))
        cases.append(('an unrelated pair is not listed', k_none not in keys,
                      repr(keys)))
        by_source = [{'name': 'uni', 'level': 'universal', 'slug': None,
                      'prefix': '', 'practices': []},
                     {'name': 'shr', 'level': 'shared', 'slug': None,
                      'prefix': '', 'practices': []}]
        page = rp.render(by_source, [], pairs=pairs, verdicts=[
            {'a': 'uni:same-rule', 'b': 'shr:same-rule',
             'verdict': 'ZZVERDICTZZ keep the universal copy'}])
        cases.append(('a verdict is shown beside its pair, and an unjudged '
                      'pair says so', 'ZZVERDICTZZ' in page
                      and 'Not judged yet.' in page, page[-800:]))
    finally:
        shutil.rmtree(tmp, ignore_errors=True)
    bad = [(c[0], c[2]) for c in cases if not c[1]]
    check(f'the review page lists practices that may overlap '
          f'({len(cases)} stated cases)',
          not bad, '; '.join(f"{n} -- {d[:300]}" for n, d in bad))


def check_review_page_carries_every_source_and_is_never_committed():
    """The very deep check hands the person one session-only page: every
    branch they can delete, with a link each, and every active practice by
    source -- universal, this repo's own, individual, shared -- private sets
    included, and nothing of it committed (Morgan, 2026-09-28, strength:
    decided). It replaced a practice list committed into the public
    spec/VERY_DEEP_CHECK.md, which had to hold the private sets back, so he
    never got the whole list.

    Discriminating cases: a private source's clause IS on the page (the old
    committed list could never carry it); an unlanded branch and a tier
    branch are NOT offered for deletion while a landed one is; and a path
    git would track is refused. The fixture owns its repos."""
    import shutil, tempfile
    sys.path.insert(0, str(ROOT / 'tools'))
    import very_deep_check as vdc
    import precedent_review_page as rp

    MARKER = 'ZZPRIVATEMARKERZZ an individual clause the page must carry'
    PRACTICE = (
        '---\nslug: {slug}\ntitle: fixture\ntier: on-demand\n'
        'severity: advisory\nscope: any-adopter\napplies_to: ["**"]\n'
        'occasion: "a fixture fires"\ngates: []\n'
        'index_clause: "{clause}"\nchecked_by: null\ndefines: []\n'
        'status: active\nin_force_at: null\nsupersedes: []\noverrides: null\n'
        'added: null\napproved_by: "fixture"\n---\n'
        '## Rule\nFixture text.\n')
    env = dict(os.environ, GIT_AUTHOR_NAME='fixture',
               GIT_AUTHOR_EMAIL='fixture@invalid', GIT_COMMITTER_NAME='fixture',
               GIT_COMMITTER_EMAIL='fixture@invalid')

    def git(repo, *a):
        return subprocess.run(['git', '-C', str(repo), *a], env=env,
                              capture_output=True, text=True, check=True).stdout

    tmp = pathlib.Path(tempfile.mkdtemp(prefix='review-page-'))
    cases = []
    real_scope = vdc.enumerate_scope
    try:
        origin = tmp / 'origin.git'
        git(tmp, 'init', '-q', '--bare', str(origin))
        root = tmp / 'root'
        (root / 'practices').mkdir(parents=True)
        git(root, 'init', '-q', '-b', 'main')
        git(root, 'config', 'commit.gpgsign', 'false')
        (root / '.gitignore').write_text('.precedent/\n', encoding='utf-8')
        (root / 'practices' / 'uni-practice.md').write_text(
            PRACTICE.format(slug='uni-practice', clause='a universal clause'),
            encoding='utf-8')
        git(root, 'add', '-A'); git(root, 'commit', '-q', '-m', 'base')
        git(root, 'remote', 'add', 'origin', str(origin))
        git(root, 'checkout', '-q', '-b', 'landed-branch')
        (root / 'a.txt').write_text('a\n', encoding='utf-8')
        git(root, 'add', '-A'); git(root, 'commit', '-q', '-m', 'landed')
        git(root, 'checkout', '-q', 'main')
        git(root, 'merge', '-q', '--ff-only', 'landed-branch')
        git(root, 'checkout', '-q', '-b', 'live-work')
        (root / 'b.txt').write_text('b\n', encoding='utf-8')
        git(root, 'add', '-A'); git(root, 'commit', '-q', '-m', 'unlanded')
        git(root, 'checkout', '-q', 'main')
        git(root, 'branch', '-q', 'staging')
        git(root, 'push', '-q', 'origin', 'main', 'staging', 'landed-branch',
            'live-work')
        git(root, 'fetch', '-q', 'origin')
        srcs = []
        for level, name in (('individual', 'fx-individual'),
                            ('shared', 'fx-shared')):
            d = tmp / name / 'practices'
            d.mkdir(parents=True)
            clause = MARKER if level == 'individual' else 'a shared clause'
            (d / f'{name}-rule.md').write_text(
                PRACTICE.format(slug=f'{name}-rule', clause=clause),
                encoding='utf-8')
            srcs.append({'level': level, 'name': name, 'path': str(d.parent)})
        sources = [srcs[1], {'level': 'universal', 'name': 'precedent',
                             'path': str(root)}, srcs[0]]
        vdc.enumerate_scope = lambda repo=None, user_config=None: {
            'sources': sources}
        page = rp.write(root, day='fixture').read_text(encoding='utf-8')
        cases.append(('THE CASE THIS EXISTS FOR: a private source\'s clause '
                      'is on the page', MARKER in page, page[:200]))
        order = [page.find('uni-practice'), page.find('fx-individual-rule'),
                 page.find('fx-shared-rule')]
        cases.append(('practices run universal, then individual, then shared',
                      -1 not in order and order == sorted(order), repr(order)))
        cases.append(('a landed branch is offered with a delete link',
                      'branches/all?query=landed-branch' in page, page[-600:]))
        cases.append(('an unlanded branch and a tier branch are not',
                      'query=live-work' not in page
                      and 'query=staging' not in page
                      and 'query=main' not in page, page[-600:]))
        cases.append(('the page is written where git ignores it',
                      subprocess.run(['git', '-C', str(root), 'check-ignore',
                                      '-q', str(root / rp.DEFAULT_OUT)]
                                     ).returncode == 0, str(rp.DEFAULT_OUT)))
        try:
            rp.write(root, out='tracked-page.html')
            refused = False
        except SystemExit:
            refused = True
        cases.append(('a path git would track is refused', refused, ''))
        src = (ROOT / 'tools' / 'very_deep_check.py').read_text(encoding='utf-8')
        doc = (ROOT / 'spec' / 'VERY_DEEP_CHECK.md').read_text(encoding='utf-8')
        cases.append(('the run no longer writes the catalogue into the '
                      'public spec document',
                      "_update_spec_doc_block(repo_root, 'practice-catalogue'"
                      not in src and 'vdc-embed:practice-catalogue' not in doc,
                      ''))
    finally:
        vdc.enumerate_scope = real_scope
        shutil.rmtree(tmp, ignore_errors=True)
    bad = [(c[0], c[2]) for c in cases if not c[1]]
    check(f'the review page carries every source and is never committed '
          f'({len(cases)} stated cases)',
          not bad, '; '.join(f"{n} -- {d[:300]}" for n, d in bad))

def check_branch_report_keeps_private_names_out_of_a_public_tree():
    """The very deep check's tracked branch report (record/stale_branches.md,
    and the safe-to-delete embed in spec/VERY_DEEP_CHECK.md) never carries a
    held-back source's branches or a branch name the leak blocklist matches,
    in a public repo -- and holds nothing back in a private one (practice:
    very-deep-check; control-asserts-which-failure).

    THE INCIDENT (2026-09-28). The first run with the individual source's
    blocklist resolved wrote a branch named after a private project into
    this public repo's record/stale_branches.md, and its own push gate
    refused the result. The same file had carried the private individual
    set's branch names, authors and dates since 2026-09-19 -- the
    disclosure the practice catalogue was fixed for on 2026-09-24, in the
    file next to it.

    The fixture owns its own tree: a temp repo, a temp blocklist named by
    the environment variable the push gate reads, and hand-built scan
    results, so no git history or network is involved."""
    import tempfile
    sys.path.insert(0, str(ROOT / 'tools'))
    import very_deep_check as vdc
    import leak_gate

    SECRET = 'zzfixtureprivateproject-branch'
    SET_BRANCH = 'claude/zzfixture-private-set-branch'
    PLAIN = 'claude/zzfixture-plain-branch'

    def row(name, stale=False):
        return {'name': name, 'last': '2026-09-01', 'age_days': 3,
                'author': 'Fixture', 'stale': stale}

    def scans(root, ind):
        return {
            'checkout': {'path': str(root), 'target': 'staging',
                         'merged': [row(SECRET, stale=True), row(PLAIN)],
                         'merged_elsewhere': [],
                         'unmerged': [dict(row('claude/zz-unmerged'),
                                           ahead=1, verdict='fixture')]},
            'individual source fixture-individual': {
                'path': str(ind), 'target': 'main',
                'merged': [row(SET_BRANCH)], 'merged_elsewhere': [],
                'unmerged': []},
        }

    cases = []
    tmp = pathlib.Path(tempfile.mkdtemp(prefix='branch-report-privacy-'))
    old_env = os.environ.get(leak_gate.BLOCKLIST_ENV)
    try:
        bl = tmp / 'blocklist.txt'
        bl.write_text('zzfixtureprivateproject\n', encoding='utf-8')
        os.environ[leak_gate.BLOCKLIST_ENV] = str(bl)
        for vis in ('public', 'private'):
            root = tmp / vis
            ind = tmp / (vis + '-individual')
            for d in (root, ind):
                d.mkdir()
            (root / 'precedent.json').write_text(
                json.dumps({'format_version': 1, 'visibility': vis}),
                encoding='utf-8')
            sources = [
                {'level': 'universal', 'name': 'precedent', 'path': str(root)},
                {'level': 'individual', 'name': 'fixture-individual',
                 'path': str(ind)}]
            sc = scans(root, ind)
            held, redact = vdc._branch_report_privacy(root, sources, sc)
            out = vdc._write_branch_report(sc, root / 'report.md', root,
                                           held_back=held, redact=redact)
            text = out.read_text(encoding='utf-8')
            embed = vdc._merged_stale_checkout_markdown(sc['checkout'],
                                                        redact=redact)
            if vis == 'public':
                cases.append(('THE CASE THIS EXISTS FOR: a blocklisted branch '
                              'name never reaches a public tracked report',
                              SECRET not in text and SECRET not in embed,
                              text[:300]))
                cases.append(('a held-back source\'s branches stay out of it',
                              SET_BRANCH not in text and 'Held back' in text,
                              text[-600:]))
                cases.append(('an ordinary branch is still listed',
                              PLAIN in text, text[:600]))
            else:
                cases.append(('THE DISCRIMINATING CASE: a private repo holds '
                              'nothing back', SECRET in text
                              and SET_BRANCH in text and not held
                              and not redact, text[:300]))
    finally:
        if old_env is None:
            os.environ.pop(leak_gate.BLOCKLIST_ENV, None)
        else:
            os.environ[leak_gate.BLOCKLIST_ENV] = old_env
        import shutil
        shutil.rmtree(tmp, ignore_errors=True)

    bad = [(c[0], c[2]) for c in cases if not c[1]]
    check(f'the branch report keeps blocklisted names and held-back sources '
          f'out of a public repo\'s tracked files, and only there '
          f'({len(cases)} stated cases)',
          not bad, '; '.join(f"{n} -- {d[:300]}" for n, d in bad))


def check_very_deep_check_reads_live_and_names_landing_work():
    """The very deep check says what it reads against the live `main`, and
    names what the landing branch carries that is not live yet (practice:
    very-deep-check -- read main, write through the landing branch; Morgan,
    2026-09-28). Planted: a clone on a branch equal to main (reads the live
    version), then the same clone on a branch that differs (a NOTE), and a
    pre-staging carrying one file main lacks (named, so a finding in it is
    checked there before it is fixed twice)."""
    import shutil, tempfile
    sys.path.insert(0, str(ROOT / 'tools'))
    import very_deep_check as vdc
    tmp = pathlib.Path(tempfile.mkdtemp(prefix='vdc-live-landing-'))
    cases = []
    def git(cwd, *a):
        return subprocess.run(['git', '-C', str(cwd), '-c', 'user.name=F',
                               '-c', 'user.email=f@invalid', *a],
                              capture_output=True, text=True, check=True).stdout
    try:
        origin, work, clone = tmp / 'origin.git', tmp / 'work', tmp / 'clone'
        subprocess.run(['git', 'init', '-q', '--bare', str(origin)], check=True)
        work.mkdir()
        git(work, 'init', '-q', '-b', 'main')
        (work / 'precedent.json').write_text(
            json.dumps({'format_version': 1, 'landing_branch': 'pre-staging'}),
            encoding='utf-8')
        (work / 'a.md').write_text('live\n', encoding='utf-8')
        git(work, 'add', '-A'); git(work, 'commit', '-q', '-m', 'live')
        git(work, 'remote', 'add', 'origin', str(origin))
        git(work, 'push', '-q', 'origin', 'main')
        git(work, 'checkout', '-q', '-b', 'pre-staging')
        (work / 'zz-not-live.md').write_text('waiting\n', encoding='utf-8')
        git(work, 'add', '-A'); git(work, 'commit', '-q', '-m', 'unpromoted')
        git(work, 'push', '-q', 'origin', 'pre-staging')
        subprocess.run(['git', 'clone', '-q', str(origin), str(clone)], check=True)
        git(clone, 'fetch', '-q', 'origin', 'pre-staging:refs/remotes/origin/pre-staging')
        git(clone, 'checkout', '-q', '-b', 'work', 'origin/main')
        rows = vdc._live_vs_landing(clone)
        text = ' | '.join(f'{v} {m}' for v, m in rows)
        cases.append(('a branch equal to main reads the live version',
                      any(v == 'OK' and 'live version' in m for v, m in rows),
                      text))
        cases.append(('the landing branch\'s not-yet-live file is named',
                      any('zz-not-live.md' in m for v, m in rows), text))
        (clone / 'a.md').write_text('edited\n', encoding='utf-8')
        git(clone, 'commit', '-qam', 'edit')
        rows = vdc._live_vs_landing(clone)
        text = ' | '.join(f'{v} {m}' for v, m in rows)
        cases.append(('THE DISCRIMINATING CASE: a branch that differs from '
                      'main is not reported as reading the live version',
                      not any('live version' in m for v, m in rows)
                      and any('differs from the live' in m for v, m in rows),
                      text))
    finally:
        shutil.rmtree(tmp, ignore_errors=True)
    bad = [(c[0], c[2]) for c in cases if not c[1]]
    check(f'the very deep check says whether it reads the live main, and what '
          f'the landing branch has not yet made live ({len(cases)} stated cases)',
          not bad, '; '.join(f"{n} -- {d[:300]}" for n, d in bad))


def check_very_deep_check_blocked_on_and_net_empty_branches():
    """Two very deep check signals that reported something that was not
    there (2026-09-28 very deep check, approved by Morgan).

    BLOCKED-ON NAMES SOMETHING GONE resolved every path in an item's
    `blocked_on` against this tree, so a path that only exists in a
    consumer (`process/upstream`, `tools/ENGINE_MANIFEST.json`) read as
    gone. Planted: one item per shape -- the classic layout, the engine's
    manifest, a path the item frames as a consumer's, a backticked path
    that does exist at the root (read from todo/ before, so gone) -- none
    reported; and one path genuinely gone, still reported.

    UNLANDED WORK counted a branch whose commits cancel out (a change and
    its revert) as carrying unlanded work. Planted beside a branch with
    real work, which must still read as unlanded."""
    import shutil, tempfile
    sys.path.insert(0, str(ROOT / 'tools'))
    import very_deep_check as vdc
    tmp = pathlib.Path(tempfile.mkdtemp(prefix='vdc-blocked-netempty-'))
    cases = []

    def item(slug, blocked):
        return ('---\n'
                f'slug:              {slug}\n'
                'kind:              analysis\n'
                'status:            open\n'
                'disposition:       wait\n'
                f'blocked_on:        {json.dumps(blocked)}\n'
                'noted:             2026-01-01\n'
                '---\n\n## What\n\n'
                f'**{slug} title.**\n')
    try:
        repo = tmp / 'repo'
        (repo / 'todo').mkdir(parents=True)
        (repo / 'tools').mkdir()
        (repo / 'tools' / 'real_tool.py').write_text('x\n', encoding='utf-8')
        planted = {
            'todo-2026-01-01-classic':
                'make the gate quiet under the `process/upstream` layout.',
            'todo-2026-01-01-manifest':
                'the engine reads its kind from `tools/ENGINE_MANIFEST.json`.',
            'todo-2026-01-01-framed':
                'a consumer that carries `tools/consumer_config.json` says so.',
            'todo-2026-01-01-exists':
                'a fix to `tools/real_tool.py`.',
            'todo-2026-01-01-gone':
                'the fix in `tools/retired_tool.py`.',
        }
        for slug, blocked in planted.items():
            (repo / 'todo' / f'{slug}.md').write_text(item(slug, blocked),
                                                      encoding='utf-8')
        out = '\n'.join(vdc._open_item_sweep(repo))
        block = out.split('BLOCKED-ON NAMES SOMETHING GONE', 1)[-1] \
            if 'BLOCKED-ON NAMES SOMETHING GONE' in out else ''
        block = block.split('OLDEST', 1)[0]
        for slug in ('classic', 'manifest', 'framed', 'exists'):
            cases.append((f'a {slug} path is not reported as gone',
                          f'todo-2026-01-01-{slug}' not in block, out))
        cases.append(('THE CONTROL: a path genuinely gone from this tree is '
                      'still reported',
                      'todo-2026-01-01-gone' in block
                      and 'missing: tools/retired_tool.py' in block, out))

        up, work = tmp / 'up', tmp / 'work'
        up.mkdir()
        fixture_git(up, 'init', '-q', '-b', 'main')
        fixture_git(up, 'config', 'receive.denyCurrentBranch', 'ignore')
        fixture_git(up, 'config', 'user.email', 'harness@example.com')
        fixture_git(up, 'config', 'user.name', 'Harness')
        (up / 'base.txt').write_text('base\n')
        fixture_git(up, 'add', '-A'); fixture_git(up, 'commit', '-qm', 'base')
        fixture_git(up, 'checkout', '-q', '-b', 'cancels-out')
        (up / 'base.txt').write_text('base\nadded\n')
        fixture_git(up, 'commit', '-qam', 'add a line')
        (up / 'base.txt').write_text('base\n')
        fixture_git(up, 'commit', '-qam', 'take it back out')
        fixture_git(up, 'checkout', '-q', 'main')
        fixture_git(up, 'checkout', '-q', '-b', 'real-work')
        (up / 'feature.txt').write_text('unlanded\n')
        fixture_git(up, 'add', '-A')
        fixture_git(up, 'commit', '-qm', 'unlanded work')
        fixture_git(up, 'checkout', '-q', 'main')
        subprocess.run(['git', 'clone', '-q', f'file://{up}', str(work)],
                       capture_output=True, text=True)
        scan = vdc.scan_branches(work, 'main')
        rows = {r['name']: r for r in (scan or {}).get('unmerged', [])}
        ce = rows.get('cancels-out', {})
        rw = rows.get('real-work', {})
        cases.append(('a branch whose commits cancel out reads as net-empty',
                      (ce.get('verdict') or '').startswith(
                          'net-empty: its commits cancel out; nothing to land'),
                      repr(ce)))
        cases.append(('THE CONTROL: a branch with real work still CARRIES it',
                      not rw.get('net_empty')
                      and 'CARRIES' in (rw.get('verdict') or ''), repr(rw)))
    finally:
        shutil.rmtree(tmp, ignore_errors=True)
    bad = [(c[0], c[2]) for c in cases if not c[1]]
    check(f'the very deep check reports neither a consumer-only path as gone '
          f'nor a net-empty branch as unlanded work ({len(cases)} stated '
          f'cases)',
          not bad, '; '.join(f"{n} -- {d[:300]}" for n, d in bad))


def check_very_deep_check_refuses_unknown_flags_before_the_ledger():
    """very_deep_check.py refuses an argument it does not read, with its
    usage and exit 2, before the ledger is touched; and --record-pass lands
    on the last COMPLETED run, never on an aborted one after it (practice:
    very-deep-check).

    THE INCIDENT (filed 2026-09-21, still true 2026-09-28). `--check`,
    `--explain`, `--list` and `--dry-run` -- real flags in sibling tools --
    each started a full run and appended an incomplete row to the ledger,
    which then became "the last run" for every since-the-last-run section,
    and the row a hand-worked --record-pass attached to."""
    import tempfile, shutil
    tmp = pathlib.Path(tempfile.mkdtemp(prefix='vdc-unknown-flag-'))
    cases = []
    try:
        ledger = tmp / 'ledger.json'
        for flag in ('--check', '--dry-run', '--explain', '--list'):
            r = subprocess.run(
                [sys.executable, str(ROOT / 'tools' / 'very_deep_check.py'),
                 '--repo', str(tmp), '--ledger', str(ledger), flag],
                capture_output=True, text=True, cwd=str(tmp), timeout=120)
            cases.append((f'{flag} refuses with exit 2 and the usage, and '
                          f'writes no ledger',
                          r.returncode == 2 and 'unknown argument' in r.stderr
                          and 'Exit: 1 if any repo in force' in r.stderr
                          and not ledger.exists(),
                          f'exit {r.returncode}; ledger exists: '
                          f'{ledger.exists()}; {r.stderr[-300:]}'))
        # A valued flag's value is not an unknown argument (the control).
        r = subprocess.run(
            [sys.executable, str(ROOT / 'tools' / 'very_deep_check.py'),
             '--ledger', str(tmp / 'none.json'), '--record-pass', '2=done'],
            capture_output=True, text=True, cwd=str(tmp), timeout=120)
        cases.append(('CONTROL: a known valued flag is not refused as unknown',
                      'unknown argument' not in r.stderr, r.stderr[-300:]))

        good = tmp / 'good.json'
        good.write_text(json.dumps({'runs': [
            {'run_id': 'R-COMPLETE', 'completed': True, 'components': []},
            {'run_id': 'R-ABORTED', 'completed': False, 'components': []},
        ]}), encoding='utf-8')
        r = subprocess.run(
            [sys.executable, str(ROOT / 'tools' / 'very_deep_check.py'),
             '--ledger', str(good), '--record-pass', '3=done,findings=2'],
            capture_output=True, text=True, cwd=str(tmp), timeout=120)
        runs = json.loads(good.read_text(encoding='utf-8'))['runs']
        cases.append(('THE CASE: --record-pass lands on the last completed '
                      'run, not the aborted one after it, and says so',
                      r.returncode == 0
                      and len(runs[0].get('passes') or []) == 1
                      and not runs[1].get('passes')
                      and 'did not complete' in r.stderr,
                      f'exit {r.returncode}; {runs}; {r.stderr[-300:]}'))
    finally:
        shutil.rmtree(tmp, ignore_errors=True)
    bad = [(c[0], c[2]) for c in cases if not c[1]]
    check(f'very_deep_check refuses an unknown flag before the ledger, and '
          f'--record-pass targets the last completed run '
          f'({len(cases)} stated cases)',
          not bad, '; '.join(f'{n} -- {d[:300]}' for n, d in bad))


def check_identity_reality_reads_grandfathering_the_bot_and_a_shallow_clone():
    """IDENTITY REALITY subtracts the repo's own grandfathered_commit_shas,
    calls a commit by the container's bot address a FINDING rather than
    "another author", and says when a shallow clone truncated its window
    (practice: very-deep-check, pass 2; 2026-09-28: eight bot-authored
    commits on a shared set's main read as "not a finding")."""
    import tempfile, shutil
    sys.path.insert(0, str(ROOT / 'tools'))
    import very_deep_check as vdc
    tmp = pathlib.Path(tempfile.mkdtemp(prefix='vdc-identity-'))
    cases = []
    try:
        up = tmp / 'up'
        up.mkdir()
        fixture_git(up, 'init', '-q', '-b', 'main')

        def commit(msg, name, email):
            (up / 'f.txt').write_text(msg + '\n', encoding='utf-8')
            fixture_git(up, 'add', '-A')
            fixture_git(up, '-c', 'core.hooksPath=/dev/null',
                        '-c', f'user.name={name}', '-c', f'user.email={email}',
                        'commit', '-qm', msg)
            return fixture_git(up, 'rev-parse', 'HEAD').stdout.strip()

        commit('other', 'Someone Else', 'someone@example.com')
        old_bot = commit('bot, grandfathered', 'Claude', vdc.BOT_EMAIL)
        new_bot = commit('bot, live', 'Claude', vdc.BOT_EMAIL)
        (up / 'precedent.json').write_text(json.dumps({
            'grandfathered_commit_shas': [
                {'sha': old_bot, 'note': 'fixture: exempted on purpose'}]}),
            encoding='utf-8')
        rows, notes = vdc._identity_reality(up)
        text = '\n'.join(f'{v} {m}' for v, m in rows) + '\n' + '\n'.join(notes)
        bot_rows = [m for v, m in rows if v == 'FINDING' and vdc.BOT_EMAIL in m]
        cases.append(('THE CASE: a bot-authored commit is a FINDING, not '
                      'another author',
                      len(bot_rows) == 1 and 'other authors' not in
                      ' '.join(n for n in notes if vdc.BOT_EMAIL in n), text))
        cases.append(('a grandfathered commit is subtracted, and said so',
                      bot_rows and bot_rows[0].startswith('1 commit')
                      and old_bot[:9] not in bot_rows[0]
                      and new_bot[:9] in bot_rows[0]
                      and any('1 grandfathered' in n for n in notes), text))
        cases.append(('CONTROL: a person\'s commit is still only a note',
                      any('someone@example.com' in n for n in notes), text))
        cases.append(('CONTROL: a full clone says nothing about shallowness',
                      not any('shallow' in n for n in notes), text))

        shallow = tmp / 'shallow'
        subprocess.run(['git', 'clone', '-q', '--depth', '1', f'file://{up}',
                        str(shallow)], capture_output=True, text=True)
        rows2, notes2 = vdc._identity_reality(shallow)
        cases.append(('a shallow clone says where its history starts and '
                      'that the window is truncated',
                      any(n.startswith('(shallow: history starts ')
                          and 'window truncated' in n for n in notes2),
                      '\n'.join(notes2)))
    finally:
        shutil.rmtree(tmp, ignore_errors=True)
    bad = [(c[0], c[2]) for c in cases if not c[1]]
    check(f'IDENTITY REALITY subtracts grandfathered commits, flags the bot '
          f'address and names a shallow window ({len(cases)} stated cases)',
          not bad, '; '.join(f'{n} -- {d[:400]}' for n, d in bad))


def check_config_keys_counts_a_key_a_practice_reads():
    """CONFIG KEYS names the practice through which a SESSION reads a key,
    and does not count that key as read by nothing (practice:
    very-deep-check, pass 2; 2026-09-28: `writeup_dir`, read by whoever
    follows write-it-up, reported as read by nothing on every run)."""
    import tempfile, shutil
    sys.path.insert(0, str(ROOT / 'tools'))
    import very_deep_check as vdc
    tmp = pathlib.Path(tempfile.mkdtemp(prefix='vdc-config-keys-'))
    cases = []
    try:
        repo, other = tmp / 'repo', tmp / 'other'
        for d in (repo / 'tools', repo / 'practices', other / 'practices'):
            d.mkdir(parents=True)
        (repo / 'precedent.json').write_text(json.dumps({
            'zz_read_by_script': 1, 'zz_read_by_session': 2,
            'zz_read_by_other_set': 3, 'zz_read_by_nothing': 4}),
            encoding='utf-8')
        (repo / 'tools' / 'reader.py').write_text(
            "KEY = 'zz_read_by_script'\n", encoding='utf-8')
        (repo / 'practices' / 'zz-session-rule.md').write_text(
            '---\nslug: zz-session-rule\n---\n\n## Rule\n\nRead '
            '`zz_read_by_session` from precedent.json.\n', encoding='utf-8')
        (other / 'practices' / 'zz-other-rule.md').write_text(
            '---\nslug: zz-other-rule\n---\n\n## Rule\n\nSet '
            '"zz_read_by_other_set" where it applies.\n', encoding='utf-8')
        rows, note = vdc._config_key_reads(
            repo, [('repo', str(repo)), ('other set', str(other))])
        by = {r[1]: r for r in rows}
        try:
            cases.append(('THE CASE: a key a practice names is read by a '
                          'session through that practice',
                          by['zz_read_by_session'][4] == ['zz-session-rule'],
                          repr(by.get('zz_read_by_session'))))
            cases.append(('a practice in ANOTHER repo in force counts too',
                          by['zz_read_by_other_set'][4] == ['zz-other-rule'],
                          repr(by.get('zz_read_by_other_set'))))
            cases.append(('CONTROL: a key nothing names stays read by nothing',
                          by['zz_read_by_nothing'][2] == []
                          and by['zz_read_by_nothing'][4] == [],
                          repr(by.get('zz_read_by_nothing'))))
            cases.append(('CONTROL: a key a script reads is not searched '
                          'further', by['zz_read_by_script'][2] != []
                          and by['zz_read_by_script'][4] == [],
                          repr(by.get('zz_read_by_script'))))
        except (KeyError, IndexError) as exc:
            cases.append(('rows carry the practice readers',
                          False, f'{type(exc).__name__}: {exc}; {rows!r}'))
    finally:
        shutil.rmtree(tmp, ignore_errors=True)
    bad = [(c[0], c[2]) for c in cases if not c[1]]
    check(f'CONFIG KEYS names the practice a session reads a key through '
          f'({len(cases)} stated cases)',
          not bad, '; '.join(f'{n} -- {d[:300]}' for n, d in bad))


def check_very_deep_check_catalogue_loads_are_quiet():
    """The very deep check loads every catalogue several times a run, and
    build_views.load_practices() printed its not-in-force roster to stderr
    each time -- about 120 lines a run; the generator's "hook script(s) ...
    not wired" NOTE printed once per source. `announce=False` silences the
    roster for a caller that reports what is in force itself, the default
    still announces, and the generator's NOTE prints once per shape
    (2026-09-28)."""
    import tempfile, shutil, io, contextlib
    sys.path.insert(0, str(ROOT / 'tools'))
    import build_views as bv
    import very_deep_check as vdc
    tmp = pathlib.Path(tempfile.mkdtemp(prefix='vdc-quiet-'))
    cases = []
    try:
        pdir = tmp / 'practices'
        pdir.mkdir()
        (pdir / 'zz-live.md').write_text(
            '---\nslug: zz-live\nstatus: active\n---\n\n## Rule\n\nLive.\n',
            encoding='utf-8')
        (pdir / 'zz-gone.md').write_text(
            '---\nslug: zz-gone\nstatus: retired\n---\n\n## Rule\n\nGone.\n',
            encoding='utf-8')
        loud, quiet = io.StringIO(), io.StringIO()
        with contextlib.redirect_stderr(loud):
            a = bv.load_practices(pdir)
        try:
            with contextlib.redirect_stderr(quiet):
                b = bv.load_practices(pdir, announce=False)
        except TypeError as exc:
            b = None
            quiet.write(f'TypeError: {exc}')
        cases.append(('CONTROL: the default still announces a dropped practice',
                      'zz-gone is status' in loud.getvalue(), loud.getvalue()))
        cases.append(('THE CASE: announce=False is quiet and returns the same',
                      b is not None and quiet.getvalue() == ''
                      and [f.name for _fm, _s, f in b]
                      == [f.name for _fm, _s, f in a], quiet.getvalue()))
        cat = io.StringIO()
        with contextlib.redirect_stderr(cat):
            rows = vdc._practice_catalogue_rows(
                [{'level': 'shared', 'name': 'zz', 'path': str(tmp)}])
        cases.append(('the very deep check\'s catalogue read is quiet',
                      cat.getvalue() == '' and len(rows) == 1,
                      cat.getvalue()[:300]))
        vdc._GENERATOR_STDERR_SEEN.clear()
        gen = io.StringIO()
        with contextlib.redirect_stderr(gen):
            vdc._pass_generator_stderr_once(
                'NOTE: zzfixture: 3 hook script(s) are not wired (a.sh, b.sh)\n')
            vdc._pass_generator_stderr_once(
                'NOTE: zzfixture: 4 hook script(s) are not wired (a.sh, b.sh, c.sh)\n'
                'NOTE: zzfixture: a different message\n')
        lines = gen.getvalue().splitlines()
        cases.append(('the generator\'s repeated NOTE prints once, and a '
                      'different one still prints',
                      len(lines) == 2 and 'a different message' in lines[1],
                      gen.getvalue()))
    finally:
        shutil.rmtree(tmp, ignore_errors=True)
    bad = [(c[0], c[2]) for c in cases if not c[1]]
    check(f'catalogue loads inside the very deep check are quiet and the '
          f'generator NOTE prints once ({len(cases)} stated cases)',
          not bad, '; '.join(f'{n} -- {d[:300]}' for n, d in bad))


def check_moved_claims_skips_narrated_deletions_and_templates():
    """MOVED CLAIMS reports a sentence saying work moved to a file that is
    not there -- but not one NARRATING that the destination was later
    deleted (the same line or the next three), and not one naming a file
    this repo ships as `templates/**/<name>.template` (practice:
    very-deep-check, pass 3; 2026-09-28: eight rows across two repos, every
    one a history sentence about precedent-check.yml)."""
    import tempfile, shutil
    sys.path.insert(0, str(ROOT / 'tools'))
    import very_deep_check as vdc
    tmp = pathlib.Path(tempfile.mkdtemp(prefix='vdc-moved-'))
    cases = []
    try:
        fixture_git(tmp, 'init', '-q', '-b', 'main')
        (tmp / 'templates' / 'kind').mkdir(parents=True)
        (tmp / 'templates' / 'kind' / 'zzshipped.yml.template').write_text(
            'x\n', encoding='utf-8')
        (tmp / 'a.md').write_text(
            'Its checks were folded into zzgoneone.yml, which a refresh '
            'later deleted.\n', encoding='utf-8')
        (tmp / 'b.md').write_text(
            'On the 19th the checks were folded into zzgonetwo.yml as steps.\n'
            'That was safe while it lasted.\n\n'
            'The destination went with it two days later.\n',
            encoding='utf-8')
        (tmp / 'c.md').write_text(
            'The workflow now lives in zzshipped.yml for every consumer.\n',
            encoding='utf-8')
        (tmp / 'd.md').write_text(
            'The check now lives in zzmissing.yml.\n', encoding='utf-8')
        (tmp / 'e.md').write_text(
            'The check has moved to zzfar.yml.\n\n\n\n\n'
            'Much later, an unrelated file was deleted.\n', encoding='utf-8')
        fixture_git(tmp, 'add', '-A')
        rows = vdc._moved_claims(tmp) or []
        targets = {r[3] for r in rows}
        cases.append(('THE CASE: a claim whose own sentence says the '
                      'destination was deleted is history, not a row',
                      'zzgoneone.yml' not in targets, repr(rows)))
        cases.append(('...and so is one whose next lines say it went with it',
                      'zzgonetwo.yml' not in targets, repr(rows)))
        cases.append(('a file shipped as templates/**/<name>.template exists',
                      'zzshipped.yml' not in targets, repr(rows)))
        cases.append(('CONTROL: a live claim naming a missing file is a row',
                      'zzmissing.yml' in targets, repr(rows)))
        cases.append(('CONTROL: a deletion four or more lines on does not '
                      'excuse it', 'zzfar.yml' in targets, repr(rows)))
    finally:
        shutil.rmtree(tmp, ignore_errors=True)
    bad = [(c[0], c[2]) for c in cases if not c[1]]
    check(f'MOVED CLAIMS skips narrated deletions and templated targets and '
          f'still reports a live one ({len(cases)} stated cases)',
          not bad, '; '.join(f'{n} -- {d[:300]}' for n, d in bad))


def check_ci_fleet_audit_counts_each_workflow_past_the_sample():
    """ci_fleet_audit.py reads at most RUN_PAGES pages of a repo's runs. In
    a repo busier than that, each workflow's "Last 30 days" is GitHub's own
    total_count for that workflow, one call each, or "at least N" where
    that cannot be asked -- never its share of the sample printed as the
    count (practice: ci-workflow-approved, 2026-09-28). Planted against a
    fake GitHub."""
    import base64, datetime
    import ci_fleet_audit as cfa

    def b64(t):
        return base64.b64encode(t.encode()).decode()

    busy = 'name: busy\non:\n  pull_request:\n'
    other = 'name: other\non:\n  pull_request:\n'
    calls = []

    def fake(path, total=450, per_wf=None):
        calls.append(path)
        o = 'repos/o/r'
        if path == o:
            return {'default_branch': 'main', 'private': False}, None
        if path == f'{o}/actions/workflows?per_page=100':
            return {'workflows': [
                {'id': 7, 'path': '.github/workflows/busy.yml',
                 'state': 'active'},
                {'id': 8, 'path': '.github/workflows/other.yml',
                 'state': 'active'}]}, None
        if path.startswith(f'{o}/actions/workflows/7/runs'):
            return {'total_count': 420, 'workflow_runs': []}, None
        if path.startswith(f'{o}/actions/workflows/8/runs'):
            return {'message': 'Server Error'}, 'HTTP 500'
        if path.startswith(f'{o}/actions/runs'):
            return {'total_count': total, 'workflow_runs': [
                {'path': '.github/workflows/busy.yml', 'event': 'push',
                 'created_at': '2026-09-25T10:00:00Z'}] * 90 + [
                {'path': '.github/workflows/other.yml', 'event': 'push',
                 'created_at': '2026-09-25T10:00:00Z'}] * 10}, None
        if path == f'{o}/contents/.github/workflows?ref=main':
            return [{'name': 'busy.yml', 'type': 'file', 'sha': 'b-busy'},
                    {'name': 'other.yml', 'type': 'file', 'sha': 'b-other'}], None
        if path.startswith(f'{o}/git/blobs/'):
            return {'content': b64({'b-busy': busy, 'b-other': other}[
                path.rsplit('/', 1)[1]])}, None
        if path == f'{o}/branches?per_page=100':
            return [{'name': 'main'}], None
        return {'message': 'Not Found'}, None

    today = datetime.date(2026, 9, 26)
    r = cfa.audit_repo('o/r', call=fake, today=today)
    rows = {t.split(' [')[0]: t for _v, t in r['rows'] if ' [' in t}
    busy_t = rows.get('.github/workflows/busy.yml', '')
    other_t = rows.get('.github/workflows/other.yml', '')
    n_wf_calls = sum(1 for c in calls if '/actions/workflows/' in c
                     and '/runs' in c)

    calls.clear()
    small = cfa.audit_repo('o/r', call=lambda p: fake(p, total=300),
                           today=today)
    small_t = {t.split(' [')[0]: t for _v, t in small['rows'] if ' [' in t}
    n_small = sum(1 for c in calls if '/actions/workflows/' in c
                  and '/runs' in c)
    cases = [
        ('THE CASE: past the sample, a workflow\'s count is GitHub\'s own',
         '420 runs (GitHub\'s own count' in busy_t, busy_t),
        ('where its own count cannot be asked, it says "at least"',
         'at least 30 runs (of the newest 300 read' in other_t, other_t),
        ('the sample is never printed as the count',
         'Last 30 days: 270 runs' not in busy_t, busy_t),
        ('one extra call per workflow, no more',
         n_wf_calls == 2, f'{n_wf_calls} calls'),
        ('CONTROL: a repo the sample covers costs no extra call and prints '
         'its exact count', n_small == 0
         and '270 runs (push 270)' in small_t.get(
             '.github/workflows/busy.yml', ''),
         f'{n_small} calls; {small_t}'),
    ]
    bad = [c[0] + ' -- ' + str(c[2])[:300] for c in cases if not c[1]]
    check(f'ci_fleet_audit counts each workflow past the 300-run sample '
          f'({len(cases)} stated cases)', not bad, '; '.join(bad))


def check_very_deep_check_runs_other_sources_checks_here():
    """A declared source's own check script whose practice is IN FORCE in
    this repo, and which this repo's precedent_check.py never discovers, is
    run against this checkout by the very deep check's CHECK COVERAGE, with
    PRECEDENT_CHECK_ROOT pointing here -- a report, never a gate (practice:
    very-deep-check, pass 2 question 15; 2026-09-28: private-repo-scrub was
    in force in BestPractice and its check had never run here)."""
    import tempfile, shutil
    sys.path.insert(0, str(ROOT / 'tools'))
    import very_deep_check as vdc
    tmp = pathlib.Path(tempfile.mkdtemp(prefix='vdc-source-checks-'))
    cases = []
    try:
        root, src = tmp / 'root', tmp / 'shared'
        for d in (root / 'practices', root / 'tools' / 'checks',
                  src / 'practices', src / 'tools' / 'checks'):
            d.mkdir(parents=True)
        script = ('import os, pathlib, sys\n'
                  'root = pathlib.Path(os.environ.get("PRECEDENT_CHECK_ROOT") '
                  'or ".")\n'
                  'if not (root / "{f}").is_file():\n'
                  '    print("VIOLATION:"); print("{f} is missing here")\n'
                  '    sys.exit(1)\n'
                  'sys.exit(0)\n')

        def practice(slug, status='active'):
            name = 'check_' + slug.replace('-', '_') + '.py'
            (src / 'practices' / f'{slug}.md').write_text(
                f'---\nslug: {slug}\nstatus: {status}\n'
                f'checked_by: tools/checks/{name}\n---\n\n## Rule\n\nX.\n',
                encoding='utf-8')
            (src / 'tools' / 'checks' / name).write_text(
                script.format(f=f'{slug}.marker'), encoding='utf-8')
            return name

        practice('zz-fails-here')
        practice('zz-passes-here')
        (root / 'zz-passes-here.marker').write_text('x\n', encoding='utf-8')
        practice('zz-retired', status='retired')
        dup = practice('zz-already-run')
        (root / 'tools' / 'checks' / dup).write_text('x\n', encoding='utf-8')
        sources = [{'level': 'universal', 'name': 'precedent',
                    'path': str(root)},
                   {'level': 'shared', 'name': 'zz-shared', 'path': str(src)}]
        rows, note = vdc._source_check_scripts(root, sources)
        by = {r[1]: r for r in rows}
        cases.append(('THE CASE: an in-force source check runs against this '
                      'checkout and its violation is reported',
                      by.get('zz-fails-here', ('',))[0] == 'VIOLATION'
                      and 'missing here' in by['zz-fails-here'][3],
                      f'{note} {rows!r}'))
        cases.append(('it reads THIS checkout, not the source (control: the '
                      'marker is here)',
                      by.get('zz-passes-here', ('',))[0] == 'PASS',
                      repr(rows)))
        cases.append(('a retired practice\'s check does not run',
                      'zz-retired' not in by, repr(rows)))
        cases.append(('a check this repo already runs is not run twice',
                      'zz-already-run' not in by, repr(rows)))
    except AttributeError as exc:
        cases.append(('the very deep check can run other sources\' checks',
                      False, f'{type(exc).__name__}: {exc}'))
    finally:
        shutil.rmtree(tmp, ignore_errors=True)
    bad = [(c[0], c[2]) for c in cases if not c[1]]
    check(f'the very deep check runs other sources\' in-force checks against '
          f'this checkout ({len(cases)} stated cases)',
          not bad, '; '.join(f'{n} -- {d[:300]}' for n, d in bad))


def check_tools_answer_help_without_writing():
    """`--help` is safe and informative on every tool in tools/.

    Two properties, both learned the hard way on 2026-09-06 by a sweep that
    simply ran `--help` across every script here to see what came back:

    * **It is answered, with exit 0.** The tools split three ways before that
      sweep -- a hard `FAIL: unknown option '--help'`, a silent fall-through
      that ran the whole audit as though nothing had been asked, or the
      docstring printed with a non-zero exit. `--help` is the first thing any
      reader types, and documentation/FOR_DEVELOPERS.md points a
      public audience straight at these commands.

    * **It writes nothing.** tools/resplit_sections.py defaulted to WRITING:
      any argument it did not recognise, `--help` included, fell through to
      the write branch and silently rewrote 46 tracked practice files,
      reverting every edit made to them since phase 1.5 -- no confirmation,
      no diff, and the damage surfaced two steps later as an unrelated
      doc_sync DRIFT that looked like a numbers problem. A destructive
      DEFAULT on a spent migration tool is the dangerous shape: the safe mode
      has to be the one you get by accident.

    Run against a throwaway copy of the tracked tree, never against the real
    one -- a check for "does this tool clobber the repo" must not be able to
    clobber the repo while finding out.
    """
    import hashlib, shutil, tempfile
    tools = sorted((ROOT / 'tools').glob('*.py'))
    tracked = subprocess.run(['git', 'ls-files'], cwd=str(ROOT),
                             capture_output=True, text=True)
    if tracked.returncode != 0 or not tracked.stdout.strip():
        not_applicable('tools answer --help without writing',
                       'git ls-files returned nothing here, so there is no '
                       'tracked tree to copy and compare -- not a pass')
        return

    files = [f for f in tracked.stdout.splitlines() if f]
    tmp = pathlib.Path(tempfile.mkdtemp(prefix='help-sweep-'))
    try:
        for rel in files:
            src = ROOT / rel
            if not src.is_file():
                continue
            dst = tmp / rel
            dst.parent.mkdir(parents=True, exist_ok=True)
            shutil.copy2(src, dst)

        def snapshot():
            out = {}
            for rel in files:
                f = tmp / rel
                if f.is_file():
                    out[rel] = hashlib.sha256(f.read_bytes()).hexdigest()
            return out

        before = snapshot()
        # A module with no `if __name__ == '__main__'` block is a library
        # (tools/table_fmt.py is one): it is imported, never invoked, so
        # "answer --help" is not a property it can have. Named here rather
        # than quietly dropped, so the exemption stays visible.
        libraries = [t for t in tools
                     if "__main__" not in t.read_text(encoding='utf-8')]
        tools = [t for t in tools if t not in libraries]
        bad_exit, silent, not_help = [], [], []
        for tool in tools:
            r = subprocess.run([sys.executable, str(tmp / 'tools' / tool.name),
                                '--help'],
                               cwd=str(tmp), capture_output=True, text=True,
                               timeout=120)
            if r.returncode != 0:
                bad_exit.append(f'{tool.name} exited {r.returncode}')
            elif not r.stdout.strip():
                silent.append(tool.name)
            elif not _looks_like_help(tool, r.stdout):
                # Exit 0 with output is NOT enough. A tool that simply
                # ignores an unrecognised flag runs its whole normal job and
                # exits 0, which passed every property above while answering
                # nothing -- build_views.py did exactly that until
                # 2026-09-06, silently regenerating MAP.md, GLOSSARY.md and
                # AGENTS.md's block on `--help`. In THIS repo those are
                # already current, so even the "writes nothing" property
                # held: an identical rewrite is invisible to a hash. It was
                # only visible in a consuming repo, where the same command
                # would have rewritten drifted views. So the output itself
                # has to be checked against the tool's own docstring.
                not_help.append(tool.name)
        after = snapshot()
        wrote = sorted(set(before) & set(after)
                       - {k for k in before if before[k] == after.get(k)})
        wrote += sorted(set(after) - set(before))

        check(f'every tool answers --help with exit 0 ({len(tools)} tools; '
              f'{len(libraries)} import-only module(s) exempt: '
              f'{", ".join(t.name for t in libraries) or "none"})',
              not bad_exit, '; '.join(bad_exit))
        check('every tool\'s --help actually prints something',
              not silent, ', '.join(silent))
        check('every tool\'s --help answers with its own usage text, rather '
              'than running the tool',
              not not_help, ', '.join(not_help))
        check('no tool writes to the tree when asked for --help',
              not wrote,
              f'{len(wrote)} file(s) changed: ' + ', '.join(wrote[:8]))
    finally:
        shutil.rmtree(tmp, ignore_errors=True)


def check_machine_readable_files_parse():
    """Every JSON and YAML file this change TOUCHED still parses.

    Changed-scope on purpose. This gates a push and runs constantly, so its
    question is "did I just break something", not "is the whole repo well".
    The whole-tree sweep is the very deep check's job
    (`tools/very_deep_check.py`), which is on-demand and is the only place a
    file nobody has touched in months gets looked at again.

    Nothing here parsed a YAML or JSON file at all until 2026-09-06 -- not
    .github/workflows/deep-check.yml, the file that RUNS this check in CI,
    and not precedent.json, MANIFEST.json, ENGINE_MANIFEST.json or
    routing_scope.json, each read by exactly one tool that would report its
    own confusing failure rather than "this file is malformed". A broken
    workflow is the worst of them: GitHub skips it silently, so the gate
    stops running and every push looks as green as the day before. That is
    the worst shape a check can have, and it applied to the check-running
    check itself."""
    import importlib.util
    spec = importlib.util.spec_from_file_location(
        '_parse_check', ROOT / 'tools' / 'parse_check.py')
    pcheck = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(pcheck)

    paths, scope = pcheck.changed(ROOT)
    failures, parsed, skipped = pcheck.validate(ROOT, paths)
    n = len(pcheck.candidates(ROOT, paths))
    for rel, why in failures:
        print(f"  {rel}: {why}")
    if skipped:
        not_applicable(f'{", ".join(skipped)} files in scope were not parsed',
                       'no parser installed here (pip install pyyaml) -- a '
                       'file nobody parsed is not a file that parses')
    check(f'every JSON/YAML file this change touched parses '
          f'({n} in scope; {scope})', not failures)

    # Scripts a workflow actually invokes, as opposed to mentions in prose.
    # Same class as vendored-engine-file-refs-resolve: a job calling a
    # missing script fails on every run, and nothing says so until somebody
    # reads a CI log. Whole-tree because there are three of them.
    RUN_SCRIPT = re.compile(r'python3?\s+((?:tools|process|deck)/[\w/.-]+\.py)')
    workflows = [f for f in pcheck.tracked(ROOT) if '/workflows/' in f]
    missing = []
    for rel in workflows:
        text = (ROOT / rel).read_text(encoding='utf-8')
        for name in sorted(set(RUN_SCRIPT.findall(text))):
            if not (ROOT / name).is_file():
                missing.append((rel, name))
    for rel, name in missing:
        print(f"  {rel}: runs {name}, which does not exist")
    check(f'every script a workflow runs exists ({len(workflows)} workflow '
          f'file(s))', not missing)


def check_null_frontmatter_is_absent():
    """A `null` frontmatter field parses as absent, not as the string 'null'.

    Every value the practice reader returns is raw field text, so a null
    field used to arrive as the literal `'null'` -- truthy, not None, not
    int-parseable. Every `if x is None` and `if 'x' not in fm` guard
    written against the four nullable fields was therefore dead code that
    had never once run, because every practice inherited from PRACTICES.md
    carries a real value in all four.

    This is worst in exactly the repos with no inherited practices at all.
    A brand-new team or individual set bootstrapped from
    templates/practice-set-*/ ships a starter practice with `checked_by:
    null`, `overrides: null` and `added: null`, so a new adopter's very
    first practice takes these paths, and a migrated repo whose practices
    are all locally authored takes them for every single one.

    Found 2026-09-06, when the first freshly-minted practice landed in
    practices/. `split_practices.py build` did not print the careful
    "no source_practice_number" message its author wrote for exactly this
    case -- it crashed on `int('null')` instead, and nine practices were
    already in that state.

    Null is dropped rather than stored as None deliberately: every caller
    that supplies its own default keeps behaving identically, including
    precedent_retire.py, whose `checked_by not in ('null', '')` would read
    None as a real value."""
    import tempfile
    fresh = ('---\nslug:        fx-null\ntitle:       "Fixture"\n'
             'tier:        on-demand\nseverity:    default\n'
             'applies_to:  ["**"]\noccasion:    "x"\ngates:       []\n'
             'index_clause: "x"\nchecked_by:  null\ndefines:     []\n'
             'status:      active\nsupersedes:  []\noverrides:   null\n'
             'added:       null\napproved_by: "A New Adopter"\n'
             'source_practice_number: null\n---\n## Rule\nx\n\n'
             '## Why\nx\n\n## Story\nx\n\n## Install\nx\n')
    with tempfile.TemporaryDirectory() as td:
        f = pathlib.Path(td) / 'fx-null.md'
        f.write_text(fresh, encoding='utf-8')
        fm, _sections = sp._read_practice_file(f)

    nullable = ('checked_by', 'overrides', 'added', 'source_practice_number')
    present = [k for k in nullable if k in fm]
    check(f'a null frontmatter field is absent, so `k not in fm` and '
          f'`fm.get(k) is None` both work ({len(nullable)} nullable fields)',
          not present, f'still present: {present}')

    # The defaults every caller relies on must be untouched by that.
    check("a caller's own 'null' default still arrives as 'null', so "
          "precedent_retire.py's `not in ('null', '')` keeps working",
          fm.get('checked_by', 'null') == 'null'
          and fm.get('overrides', 'null') == 'null')

    # And a real value must still come through raw, quotes and all -- the
    # convention every reader in this codebase is written against.
    check('a non-null field is still returned as raw field text',
          fm.get('title') == '"Fixture"' and fm.get('status') == 'active',
          f'title={fm.get("title")!r} status={fm.get("status")!r}')

    # ONE reader for both formats. They had their own copies until
    # 2026-09-06 and had already drifted on exactly this: candidates
    # decoded null to None, practices kept the string. Pinned by behaviour
    # rather than by grepping for the import, so a re-forked copy that
    # happens to agree today still has to keep agreeing.
    import importlib.util
    spec = importlib.util.spec_from_file_location(
        '_pc_cand', ROOT / 'tools' / 'precedent_candidate.py')
    pcand = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(pcand)
    cand_fm, _body = pcand._parse_frontmatter(
        '---\nslug: x\nproposed_checked_by: null\n---\nbody\n')
    check('the candidate reader applies the same null policy as the '
          'practice reader -- absent, not None, not the string',
          'proposed_checked_by' not in cand_fm, str(cand_fm))
    check('and it still decodes its own format: a quoted scalar and a list '
          'come back as Python values',
          pcand._parse_frontmatter(
              '---\ntitle: "A, B"\nproposed_gates: ["merge", "push"]\n---\nx\n'
          )[0] == {'title': 'A, B', 'proposed_gates': ['merge', 'push']})

    # The end-to-end symptom, not just the parser: the command that broke.
    r = subprocess.run([sys.executable, str(ROOT / 'tools' / 'split_practices.py'),
                        'build'], capture_output=True, text=True, cwd=str(ROOT))
    out = r.stdout + r.stderr
    check('split_practices.py build reports unnumbered practices by name '
          'instead of crashing on int(\'null\')',
          'Traceback' not in out and 'no source_practice_number' in out,
          out[-200:])


def check_refresh_wired_settings_is_not_lost_work():
    """A source clone's .claude/settings.json that differs from its commit
    only by hook entries the refresh wires in is engine output, not a
    person's work. On 2026-09-26 all four set clones read as "uncommitted
    changes" over exactly that, and the archive gate said "Don't archive
    this session" on every reply about an edit the next session's refresh
    makes again. The file is also a person's, so the other half matters as
    much: any edit that is not that exact shape stays theirs.

    Stated cases for the shape test, then both halves through
    classify_dirt in a real clone, with a control (practice:
    control-asserts-which-failure)."""
    import tempfile
    import precedent_vendor_engine as pve
    import precedent_refresh_sources as rs
    cases = []
    cmd = '$CLAUDE_PROJECT_DIR/.claude/hooks/'
    base = {'permissions': {'allow': ['Bash(git status)']},
            'hooks': {'PreToolUse': [{'matcher': 'Bash', 'hooks': [
                {'type': 'command', 'command': cmd + 'freshness-guard.sh pre-write main'}]}]}}

    def with_hooks(extra_pre=(), new_groups=(), perms=None):
        d = json.loads(json.dumps(base))
        d['hooks']['PreToolUse'][0]['hooks'].extend(extra_pre)
        d['hooks']['PreToolUse'].extend(new_groups)
        if perms is not None:
            d['permissions'] = perms
        return json.dumps(d, indent=2)

    before = json.dumps(base, indent=2)
    wf = {'type': 'command', 'command': cmd + 'workflow-write-gate.sh'}
    wired = with_hooks(new_groups=[{'matcher': pve.WORKFLOW_WRITE_MATCHER,
                                    'hooks': [wf]}])
    shape = pve.settings_change_is_wiring_only
    cases.append(('a new group holding a hook HOOK_WIRING lists is wiring',
                  shape(before, wired), wired))
    cases.append(('an entry appended to an existing group is wiring',
                  shape(before, with_hooks(extra_pre=[
                      {'type': 'command', 'command': cmd + 'doc-lint-gate.sh'}])), ''))
    cases.append(("a person's permissions edit beside the wiring is NOT",
                  not shape(before, with_hooks(
                      new_groups=[{'matcher': 'x', 'hooks': [wf]}],
                      perms={'allow': ['Bash(*)']})), ''))
    cases.append(('a hook HOOK_WIRING does not list is NOT',
                  not shape(before, with_hooks(extra_pre=[
                      {'type': 'command', 'command': cmd + 'my-own-hook.sh'}])), ''))
    edited = json.loads(before)
    edited['hooks']['PreToolUse'][0]['hooks'][0]['command'] += ' --loud'
    cases.append(('an existing entry changed in place is NOT',
                  not shape(before, json.dumps(edited)), ''))
    cases.append(('no change, or unparseable JSON, is NOT',
                  not shape(before, before) and not shape(before, '{oops'), ''))

    tmp = pathlib.Path(tempfile.mkdtemp(prefix='wired-settings-'))
    try:
        def git(*a):
            return subprocess.run(['git', '-C', str(tmp), *a],
                                  capture_output=True, text=True)
        git('init', '--quiet')
        git('config', 'user.email', 'fixture' + chr(64) + 'example.invalid')
        git('config', 'user.name', 'Fixture')
        (tmp / '.claude').mkdir()
        sp_ = tmp / '.claude' / 'settings.json'
        sp_.write_text(before + '\n', encoding='utf-8')
        git('add', '-A')
        git('commit', '--quiet', '-m', 'first')
        sp_.write_text(wired + '\n', encoding='utf-8')
        engine, other = rs.classify_dirt(tmp)
        cases.append(('classify_dirt: refresh-wired settings.json is engine dirt',
                      engine == ['.claude/settings.json'] and not other,
                      f'engine={engine} other={other}'))
        sp_.write_text(with_hooks(new_groups=[{'matcher': 'x', 'hooks': [wf]}],
                                  perms={'allow': ['Bash(*)']}) + '\n',
                       encoding='utf-8')
        engine, other = rs.classify_dirt(tmp)
        cases.append(("classify_dirt: a person's edit to it stays theirs",
                      other == ['.claude/settings.json'] and not engine,
                      f'engine={engine} other={other}'))
        sp_.write_text(wired + '\n', encoding='utf-8')
        saved = pve.HOOK_WIRING
        try:
            pve.HOOK_WIRING = {}
            engine, other = rs.classify_dirt(tmp)
        finally:
            pve.HOOK_WIRING = saved
        cases.append(('CONTROL: with HOOK_WIRING empty the same file is a '
                      "person's, so the verdict comes from the wiring list",
                      other == ['.claude/settings.json'] and not engine,
                      f'engine={engine} other={other}'))
    finally:
        shutil.rmtree(tmp, ignore_errors=True)

    bad = [(c[0], c[2]) for c in cases if not c[1]]
    check(f'a settings.json the refresh only wired hooks into is engine output, '
          f'and any other edit to it is a person\'s ({len(cases)} stated cases)',
          not bad, '; '.join(f"{n} -- {d[:400]}" for n, d in bad))


def check_refreshed_agents_block_is_not_lost_work():
    """A source clone's AGENTS.md whose only change is inside its generated
    blocks is the refresh's output; any change outside them is a person's.

    On 2026-10-05 a startup refresh rewrote precedent-shared-ladder's loader
    block, AGENTS.md read as uncommitted work, the clone was not brought up
    to its own origin/main and the container check said the session could
    not be archived -- over a block a rebuild reproduced byte for byte. The
    file is mostly a person's prose, so the other half matters as much."""
    import tempfile
    import precedent_refresh_sources as rs
    cases = []
    tmp = pathlib.Path(tempfile.mkdtemp(prefix='agents-block-'))
    head = '# Notes\n\nA person wrote this.\n\n'
    block = ('<!-- BEGIN GENERATED: precedent-loader -->\n{}\n'
             '<!-- END GENERATED -->\n')
    tail = '\n## Working here\n\nMore prose.\n'
    try:
        def git(*a):
            return subprocess.run(['git', '-C', str(tmp), *a],
                                  capture_output=True, text=True)
        git('init', '--quiet')
        git('config', 'user.email', 'fixture' + chr(64) + 'example.invalid')
        git('config', 'user.name', 'Fixture')
        f = tmp / 'AGENTS.md'
        f.write_text(head + block.format('old index') + tail, encoding='utf-8')
        git('add', '-A')
        git('commit', '--quiet', '-m', 'first')

        def verdict(text):
            f.write_text(text, encoding='utf-8')
            return rs.classify_dirt(tmp)
        engine, other = verdict(head + block.format('new index\nlonger') + tail)
        cases.append(('a rewritten loader block alone is engine dirt',
                      engine == ['AGENTS.md'] and not other,
                      f'engine={engine} other={other}'))
        engine, other = verdict(head.replace('wrote', 'edited') +
                                block.format('new index') + tail)
        cases.append(("one word of prose changed beside it is a person's",
                      other == ['AGENTS.md'] and not engine,
                      f'engine={engine} other={other}'))
        engine, other = verdict(head + tail)
        cases.append(("the block removed is a person's, never engine output",
                      other == ['AGENTS.md'] and not engine,
                      f'engine={engine} other={other}'))
        git('checkout', '--quiet', '--', 'AGENTS.md')
        f.write_text('# Notes\n\nNo block at all.\n', encoding='utf-8')
        git('commit', '--quiet', '-am', 'no block')
        engine, other = verdict('# Notes\n\nNo block, edited.\n')
        cases.append(("CONTROL: a file with no generated block is a person's",
                      other == ['AGENTS.md'] and not engine,
                      f'engine={engine} other={other}'))
    finally:
        shutil.rmtree(tmp, ignore_errors=True)
    bad = [(c[0], c[2]) for c in cases if not c[1]]
    check(f'an AGENTS.md the refresh only rewrote the generated block of is '
          f'engine output, and any other edit to it is a person\'s '
          f'({len(cases)} stated cases)',
          not bad, '; '.join(f"{n} -- {d[:400]}" for n, d in bad))

def check_generated_blocks_both_styles():
    """generated_blocks.py: the one "is this line generated?" every scan that
    skips generated text uses (added 2026-09-29). Each tool used to match
    one marker style itself, and a shared set's no-stale-counts check,
    knowing only `<!--gen:NAME-->`, read the loader block's "1 of 20
    practices" as a stale hand-written count.

    Stated cases, one per shape (practice: checks-plant-their-state), with
    the unclosed-marker control: an opener with no closer hides nothing, so
    a marker quoted in a document cannot hide the rest of it (practice:
    control-asserts-which-failure). The callers are checked too, through the
    three whose skip used to know only one style, and so is
    checks-use-generated-blocks, which holds a repo's own checks to it."""
    sys.path.insert(0, str(ROOT / 'tools'))
    import generated_blocks as gb
    L, E = gb.LOADER_BEGIN, gb.LOADER_END
    shapes = [
        ('the loader style is generated, both marker lines included',
         ['hand', L, 'gen 1 of 20 practices', E, 'hand'],
         [False, True, True, True, False]),
        ('the gen: style is generated, both marker lines included',
         ['hand', '<!--gen:t-->', 'gen', '<!--/gen:t-->', 'hand'],
         [False, True, True, True, False]),
        ('an indented marker still counts',
         ['  <!--gen:t-->', '  gen', '  <!--/gen:t-->'], [True] * 3),
        ('both styles in one document',
         ['<!--gen:a-->', 'x', '<!--/gen:a-->', 'hand', L, 'y', E],
         [True, True, True, False, True, True, True]),
        ('CONTROL: an unclosed loader opener hides nothing',
         ['hand', L, 'hand still', 'hand still'], [False] * 4),
        ('CONTROL: an unclosed gen: opener hides nothing',
         ['<!--gen:a-->', 'hand', 'hand'], [False] * 3),
        ('CONTROL: a gen: block closes only on its own name',
         ['<!--gen:a-->', 'x', '<!--/gen:b-->', 'hand'], [False] * 4),
        ('CONTROL: a marker quoted mid-line in prose is not a marker',
         [f'keep the `{L}` marker', 'hand', E, 'hand'],
         [False, False, False, False]),
    ]
    bad = []
    for label, lines, want in shapes:
        got = gb.mask(lines)
        if got != want:
            bad.append(f'{label}: got {got}')
    text = '\n'.join(['a', L, 'b', E, 'c'])
    if gb.blank(text).split('\n') != ['a', '', '', '', 'c']:
        bad.append('blank() does not keep line numbers')

    import importlib
    import tempfile
    dl = importlib.import_module('doc_lint')
    loader_doc = '\n'.join(['<!--numbers:gated-->', L, 'rated 500 kW', E,
                            'rated 40 kW'])
    got = [q for _n, q in dl.check_quantities(loader_doc)]
    if got != ['40 kW']:
        bad.append(f'doc_lint numbers gate: a loader-block figure is flagged '
                   f'or a hand one missed: {got}')
    pc_src = (ROOT / 'tools' / 'precedent_check.py').read_text(encoding='utf-8')
    if 'generated_blocks.blank(text)' not in pc_src:
        bad.append('precedent_check.py _strip_generated no longer uses the helper')
    pa = importlib.import_module('practice_audit')
    with tempfile.TemporaryDirectory() as td:
        root = pathlib.Path(td)
        (root / 'AGENTS.md').write_text('\n'.join(
            ['<!--gen:x-->', 'declined as a duplicate of upstream', '<!--/gen:x-->',
             'this rule is a duplicate of another practice']) + '\n',
            encoding='utf-8')
        hits = [n for _f, n, _t in pa.prose_declines(root)]
        if hits != [4]:
            bad.append(f'practice_audit prose scan: want line 4 only, got {hits}')

    # checks-use-generated-blocks: a check that spells a marker itself is
    # named; one that asks the helper, a test that plants a marker on
    # purpose, and a copy another source wrote here, are not.
    with tempfile.TemporaryDirectory() as td:
        repo = pathlib.Path(td)
        (repo / 'tools' / 'checks' / 'tests').mkdir(parents=True)
        for f in (ROOT / 'tools').glob('*.py'):
            shutil.copy(f, repo / 'tools' / f.name)
        chk = repo / 'tools' / 'checks'
        (chk / 'check_hand.py').write_text(
            "SKIP = '<!-- BEGIN GENERATED: precedent-loader -->'\n", encoding='utf-8')
        (chk / 'check_helper.py').write_text(
            'import generated_blocks\nmask = generated_blocks.mask\n', encoding='utf-8')
        (chk / 'tests' / 'test_plant.py').write_text(
            "PLANT = '<!--gen:a-->'\n", encoding='utf-8')
        # A check another source wrote here: the consuming repo holds a
        # copy it cannot fix, so it is that source's run that names it.
        (chk / 'check_received.py').write_text(
            "SKIP = '<!--gen:a-->'\n", encoding='utf-8')
        (repo / 'MANIFEST.json').write_text(json.dumps({
            'sources': [{'level': 'shared', 'name': 'zzz-shared', 'path': '/x'}],
            'practices': [],
            'checks': [{'path': 'tools/checks/check_received.py',
                        'source': 'zzz-shared'}]}), encoding='utf-8')
        subprocess.run(['git', 'init', '-q'], cwd=repo, capture_output=True)
        subprocess.run(['git', 'add', '-A'], cwd=repo, capture_output=True)
        r = subprocess.run([sys.executable, 'tools/precedent_check.py', '--only',
                            'checks-use-generated-blocks'], cwd=repo,
                           capture_output=True, text=True)
        named = set(re.findall(r'tools/checks/\S+?\.py', r.stdout))
        if named != {'tools/checks/check_hand.py'}:
            bad.append(f'checks-use-generated-blocks: want only check_hand.py '
                       f'named, got {sorted(named)}: {r.stdout[-300:]}')
    # precedent_vendor_engine's AGENTS.md section parser (2026-09-30): it
    # knew only the loader style, and an unclosed opener hid the rest.
    pve = importlib.import_module('precedent_vendor_engine')
    keys = [k for k, _a, _b in pve._md_sections(
        '## A\n<!--gen:x-->\n## hidden\n<!--/gen:x-->\n## B\nb')]
    if keys != ['## A', '## B']:
        bad.append(f'AGENTS.md sections: a gen: block\'s heading counted: {keys}')
    keys = [k for k, _a, _b in pve._md_sections(
        '## A\n<!-- BEGIN GENERATED: precedent-loader -->\nx\n## B\nb')]
    if keys != ['## A', '## B']:
        bad.append(f'AGENTS.md sections: an unclosed opener hid what follows: {keys}')
    check(f'generated_blocks.py finds generated text in both marker styles, '
          f'closing marker required, and the scans use it '
          f'({len(shapes) + 6} stated cases)',
          not bad, '; '.join(bad))


def check_runner_drops_findings_on_received_files():
    """precedent_check.py's runner drops a finding on a file the repository
    RECEIVED -- another source's materialized practice or check, the
    vendored engine, a mirrored tree -- once, for every check, and names the
    source that owns it (precedent_practice_refs.received_owners()).

    WHY. Until 2026-09-29 each check had to remember that skip on its own.
    checks-use-generated-blocks went live without it, and a consuming repo's
    full check judged check files a practice set had written there, which
    the next sync overwrites. So this plants violations in received files
    for several unrelated checks, in a consumer-shaped fixture, and requires
    that none is named -- while the SAME violation in a file the repo wrote
    still is, since a drop that silenced the check would pass the first
    half alone. It also holds the two registrations that must keep their
    findings on received files: a source-supplied check script (its one
    finding carries the script's own path) and
    vendored-engine-file-refs-resolve (its subject is the received copy)."""
    import shutil, tempfile
    bad = []
    sys.path.insert(0, str(ROOT / 'tools'))
    import precedent_practice_refs as ppr

    # The one definition, in-process: a MANIFEST.json entry of a repo-local
    # source is the repo's own, a mirrored tree matches by prefix.
    with tempfile.TemporaryDirectory() as td:
        r = pathlib.Path(td)
        (r / 'tools').mkdir()
        (r / 'MANIFEST.json').write_text(json.dumps({
            'sources': [{'level': 'repo-local', 'name': 'local', 'path': 'local'},
                        {'level': 'shared', 'name': 'zzz-shared', 'path': '/x'}],
            'practices': [{'slug': 'mine', 'source': 'local'},
                          {'slug': 'theirs', 'source': 'zzz-shared'}],
            'checks': [{'path': 'tools/checks/check_theirs.py',
                        'source': 'zzz-shared'}]}), encoding='utf-8')
        (r / 'tools' / 'ENGINE_MANIFEST.json').write_text(json.dumps(
            {'files': ['zzz_engine.py']}), encoding='utf-8')
        owners = ppr.received_owners(r)
        owners['vendor/upstream/'] = 'the mirrored tree vendor/upstream/'
        want = {'practices/theirs.md': 'zzz-shared',
                'tools/checks/check_theirs.py': 'zzz-shared',
                'tools/zzz_engine.py': 'the vendored engine',
                'vendor/upstream/practices/x.md':
                    'the mirrored tree vendor/upstream/',
                'practices/mine.md': None, 'docs/x.md': None,
                'vendor/upstreamish.md': None}
        got = {k: ppr.received_owner(k, owners) for k in want}
        if got != want:
            bad.append(f'received_owner: want {want}, got {got}')

    # A consumer-shaped copy of this tree, one run of the whole check.
    tmp = pathlib.Path(tempfile.mkdtemp(prefix='precedent-received-'))
    try:
        repo = tmp / 'consumer'
        shutil.copytree(ROOT, repo, ignore=shutil.ignore_patterns(
            '.git', '__pycache__', '*.pyc', 'prompts'))
        retired = 'team' + ' sets'          # a retired word, built not spelled
        marker = '<!-- BEGIN ' + 'GENERATED: precedent-loader -->'
        (repo / 'MANIFEST.json').write_text(json.dumps({
            'sources': [{'level': 'repo-local', 'name': 'local', 'path': 'local'},
                        {'level': 'shared', 'name': 'zzz-shared', 'path': '/x'}],
            'practices': [{'slug': 'zzz-received', 'source': 'zzz-shared'}],
            'checks': [{'path': 'tools/checks/check_zzz_received.py',
                        'source': 'zzz-shared'}],
            'withheld': []}, indent=1) + '\n', encoding='utf-8')
        # Received: a practice using a retired word, and a check that spells
        # a generated-block marker itself -- and, run as a check, reports.
        (repo / 'practices' / 'zzz-received.md').write_text(
            f'Written by another source. It still says {retired}.\n',
            encoding='utf-8')
        chk = repo / 'tools' / 'checks'
        chk.mkdir(parents=True, exist_ok=True)
        (chk / 'check_zzz_received.py').write_text(
            f'import sys\nSKIP = {marker!r}\n'
            f'print("zzz-received-script-finding")\nsys.exit(1)\n',
            encoding='utf-8')
        # The repo's own copies of the same two violations.
        (repo / 'zzz-own.md').write_text(
            f'Written here. It still says {retired}.\n', encoding='utf-8')
        (chk / 'check_zzz_own.py').write_text(
            f'import sys\nSKIP = {marker!r}\nsys.exit(0)\n', encoding='utf-8')
        for args in (['init', '-q'], ['add', '-A'],
                     ['-c', 'user.email=harness@example.com', '-c',
                      'user.name=harness', 'commit', '-qm', 'consumer']):
            subprocess.run(['git', *args], cwd=repo, capture_output=True)
        env = dict(os.environ,
                   PRECEDENT_USER_CONFIG=str(repo / '.no-user-config.json'))
        env.pop('PRECEDENT_LEAK_BLOCKLIST', None)

        def run(*slugs):
            out = ''
            for slug in slugs:
                r = subprocess.run(
                    [sys.executable, 'tools/precedent_check.py', '--only', slug],
                    cwd=repo, capture_output=True, text=True, env=env)
                out += r.stdout + r.stderr
            return out

        out = run('retired-words', 'checks-use-generated-blocks')
        for name in ('practices/zzz-received.md', 'check_zzz_received.py'):
            if name in out:
                bad.append(f'{name} is received, and was named: {out[-400:]}')
        for name in ('zzz-own.md', 'check_zzz_own.py'):
            if name not in out:
                bad.append(f'{name} is the repo\'s own, and was NOT named: '
                           f'{out[-400:]}')
        if 'for zzz-shared' not in out:
            bad.append(f'no note naming zzz-shared as the owner: {out[-400:]}')

        out = run('check_zzz_received')
        if 'zzz-received-script-finding' not in out:
            bad.append(f'a source-supplied check script lost its finding: '
                       f'{out[-400:]}')

        # vendored-engine-file-refs-resolve judges the received copy itself.
        (repo / 'tools' / 'ENGINE_MANIFEST.json').write_text(json.dumps(
            {'files': ['zzz_engine.py']}), encoding='utf-8')
        # Built, never spelled: the check scans this very file.
        (repo / 'tools' / 'zzz_engine.py').write_text(
            'X = ROOT / ' + "'tools' / 'zzz_missing.json'\n", encoding='utf-8')
        out = run('vendored-engine-file-refs-resolve')
        if 'tools/zzz_engine.py' not in out:
            bad.append(f'vendored-engine-file-refs-resolve went quiet on a '
                       f'received engine file: {out[-400:]}')
    finally:
        shutil.rmtree(tmp, ignore_errors=True)
    check('findings on files a repo received are dropped once by the runner '
          'and named by owner; the repo\'s own copies, a source-supplied '
          'check script and vendored-engine-file-refs-resolve still report',
          not bad, '; '.join(bad))


def check_frontmatter_field_order_fixer():
    """frontmatter_yaml.reorder_fields: puts a practice's frontmatter into
    FIELD_ORDER and changes nothing else. On 2026-09-26 it rewrote 49 of 151
    practices here, so "nothing else" is the property that matters: a folded
    continuation line, a comment and its field, the alignment padding and
    the body all have to come through byte for byte.

    Stated cases, each with the shape it covers (practice:
    checks-plant-their-state), and a control that shows the finding comes
    from the order and not from the parse (practice:
    control-asserts-which-failure)."""
    fy = frontmatter_yaml
    cases = []
    body = '## Rule\nDo it.\n\n## Why\nBecause: yes.\nslug: not-a-field\n'
    messy = ('---\nslug:        fx\ntitle:       T\n'
             'ships:       []\n'
             'applies_to:  ["**"]\n'
             '# says why checked_by is null\n'
             'checked_by:  null\n'
             'approved_by: "a long approval folded\n'
             '   onto a second line"\n'
             'custom_field: 1\n'
             'tier:        on-demand\n'
             '---\n' + body)
    fixed = fy.reorder_fields(messy)
    want = ('---\nslug:        fx\ntitle:       T\n'
            'tier:        on-demand\n'
            'applies_to:  ["**"]\n'
            '# says why checked_by is null\n'
            'checked_by:  null\n'
            'ships:       []\n'
            'approved_by: "a long approval folded\n'
            '   onto a second line"\n'
            'custom_field: 1\n'
            '---\n' + body)
    cases.append(('a misordered file comes out in FIELD_ORDER, a comment '
                  'travelling with the field below it, a folded value with its '
                  'key, an unlisted field last, the body untouched',
                  fixed == want, repr(fixed)))
    cases.append(('the checker names the first field out of place',
                  '`applies_to:` comes after `ships:`' in (fy.field_order_problem(messy) or ''),
                  repr(fy.field_order_problem(messy))))
    cases.append(('the fixed file reads as in order, and fixing it again is a '
                  'no-op', fy.field_order_problem(fixed) is None
                  and fy.reorder_fields(fixed) == fixed, repr(fixed)))
    cases.append(('an unlisted field is reported by name',
                  fy.unlisted_fields(messy) == ['custom_field'],
                  repr(fy.unlisted_fields(messy))))
    dup = '---\nslug: a\ntier: x\nslug: b\n---\n'
    cases.append(('a repeated key is reported and left alone -- which copy is '
                  'meant is a person\'s call',
                  'more than once' in (fy.field_order_problem(dup) or '')
                  and fy.reorder_fields(dup) == dup, repr(fy.field_order_problem(dup))))
    cases.append(('QUIET: a file with no frontmatter is neither reported nor '
                  'rewritten', fy.field_order_problem(body) is None
                  and fy.reorder_fields(body) == body, ''))
    import precedent_move
    moved = precedent_move._rewrite_frontmatter(
        fixed, {'strength': 'assented', 'in_force_at': 'elsewhere'})
    cases.append(('precedent_move inserts a field the file lacked where '
                  'FIELD_ORDER puts it, not at the end -- appending was one of '
                  'the ways the order drifted',
                  fy.field_order_problem(moved.replace('custom_field: 1\n', '')) is None
                  and 'in_force_at: elsewhere\napproved_by:' in moved, repr(moved)))
    saved = fy.FIELD_ORDER
    try:
        fy.FIELD_ORDER = ('tier', 'slug', 'title', 'applies_to', 'checked_by',
                          'ships', 'approved_by')
        control = fy.field_order_problem(want)
    finally:
        fy.FIELD_ORDER = saved
    cases.append(('CONTROL: the same in-order file reads as out of order once '
                  'FIELD_ORDER says otherwise, so the verdict comes from the '
                  'constant', bool(control), repr(control)))
    # Update Vendors' tidy (practice: format-rules-grandfather): it fixes a
    # project repo's own source files in local/practices/, never the copy
    # the view sync renders into practices/, and leaves a file whose order
    # the fixer cannot settle for the warning to name.
    import tempfile, shutil
    import precedent_update as pu
    tmp = pathlib.Path(tempfile.mkdtemp(prefix='tidy-order-'))
    try:
        (tmp / 'local' / 'practices').mkdir(parents=True)
        (tmp / 'practices').mkdir()
        out_of_order = ('---\nslug: a\ntitle: A\nindex_required: false\n'
                        'index_clause: "x"\nstatus: active\n---\n## Rule\nr\n')
        repeated = ('---\nslug: b\ntitle: B\ntitle: B2\nindex_required: '
                    'false\nindex_clause: "x"\n---\n## Rule\nr\n')
        (tmp / 'local/practices/a.md').write_text(out_of_order, encoding='utf-8')
        (tmp / 'local/practices/b.md').write_text(repeated, encoding='utf-8')
        (tmp / 'practices/a.md').write_text(out_of_order, encoding='utf-8')
        done = pu.tidy_field_order(tmp, 'consumer')
        cases.append(('Update Vendors tidies a project repo\'s own practice in '
                      'local/practices/ and leaves the rendered copy and an '
                      'unfixable file alone',
                      done == ['local/practices/a.md']
                      and not fy.field_order_problem(
                          (tmp / 'local/practices/a.md').read_text(encoding='utf-8'))
                      and (tmp / 'practices/a.md').read_text(encoding='utf-8') == out_of_order
                      and (tmp / 'local/practices/b.md').read_text(encoding='utf-8') == repeated,
                      repr(done)))
        cases.append(('in a practice set, whose practices/ IS the source, it '
                      'tidies practices/ too',
                      pu.tidy_field_order(tmp, 'source') == ['practices/a.md'], ''))
    finally:
        shutil.rmtree(tmp, ignore_errors=True)

    bad = [(c[0], c[2]) for c in cases if not c[1]]
    check(f'frontmatter_yaml reorders practice frontmatter into FIELD_ORDER and '
          f'changes nothing else ({len(cases)} stated cases)',
          not bad, '; '.join(f"{n} -- {d[:600]}" for n, d in bad))


def check_frontmatter_is_real_yaml():
    """The fence says YAML, so a real YAML parser has to accept it.

    This repo's own reader takes everything after the first colon and is
    happy with `title: Build/buy: decompose before deciding`. PyYAML is
    not -- the second colon opens a nested mapping and it rejects the
    whole block. Ten of sixty-one practice files shipped that way, and
    nothing here noticed for as long as the format existed, because
    nothing here parses its own output the way the people downstream do.

    Found 2026-09-06 from the other side: a consuming repo's own light
    check, which uses PyYAML, reported them as invalid. A format whose
    only conforming parser is its author's is not a format, so the check
    belongs on the producing side. Skipped with a notice where PyYAML
    isn't installed rather than passing on having parsed nothing.

    The parse itself lives in frontmatter_yaml.py, shared with
    doc_lint.py's own (touched-files-only) copy of this same check -- one
    parser, not two drifting ones."""
    if not frontmatter_yaml.HAVE_YAML:
        not_applicable('every --- fence holds valid YAML',
                        'PyYAML is not installed here, so nothing was parsed '
                        '-- `pip install pyyaml` to run it')
        return
    # Every tracked markdown file that OPENS with a --- fence, not only
    # practices/. A consuming repo vendors this whole tree and runs its own
    # YAML-based checks over all of it; four decisions/ records were
    # unparseable for a different reason than the practices were -- values
    # continued across lines with no block-scalar indicator -- and turned a
    # consumer's own commit gate red on vendored upstream content.
    bad = []
    tracked = subprocess.run(['git', '-C', str(ROOT), 'ls-files', '*.md'],
                             capture_output=True, text=True).stdout.split()
    for rel in tracked:
        f = ROOT / rel
        try:
            text = f.read_text(encoding='utf-8')
        except OSError:
            continue
        err = frontmatter_yaml.frontmatter_yaml_error(text)
        if err:
            bad.append((rel, err))
    for n, why in bad:
        print(f"  {n}: frontmatter is not valid YAML -- {why}")
    check(f"every tracked markdown file that opens a --- fence has "
          f"frontmatter a real YAML library accepts, not only this repo's "
          f"own reader ({len(tracked)} file(s) scanned)", not bad)


def check_link_anchors_resolve():
    """A link's #fragment is checked against the target's real headings.

    An anchor breaks more quietly than a path: edit a heading and every
    link into it silently lands at the top of the right document instead of
    at a 404, so no reader ever reports it. Nine were dead in this repo
    when the check was written (2026-09-06) -- six headings simply reworded
    since, two pointing at an `INSTALL.md` section number that no longer
    exists, one at a heading amended in place.

    The slug rule is GitHub's, and the case that catches a naive
    implementation is a dash set off by spaces: the dash is deleted and
    BOTH its spaces survive as hyphens, so `cost — the numbers` is
    `cost--the-numbers`. Getting that wrong invents a failure on a heading
    that is perfectly fine. The setext case is pinned in the other
    direction: a heading style this does not parse must read as "cannot
    tell", never as "the anchor is missing"."""
    import importlib.util, tempfile
    spec = importlib.util.spec_from_file_location(
        '_dl_anchor', ROOT / 'tools' / 'doc_lint.py')
    dl = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(dl)

    slugs = [
        ('a plain heading', 'The supporting moves', 'the-supporting-moves'),
        ('a spaced dash leaves both its spaces',
         'What it cost — the numbers', 'what-it-cost--the-numbers'),
        ('punctuation is dropped, not replaced',
         'Precedence, and the one case', 'precedence-and-the-one-case'),
        ('a parenthetical keeps its words',
         'Why this could not run (original reasoning, relaxed 2026-09-01)',
         'why-this-could-not-run-original-reasoning-relaxed-2026-09-01'),
        ('inline code and links contribute their text only',
         'Run `tools/x.py` per [the plan](PLAN.md)',
         'run-toolsxpy-per-the-plan'),
    ]
    bad = [n for n, h, want in slugs if dl.heading_slug(h) != want]
    for n in bad:
        h, want = next((h, w) for nm, h, w in slugs if nm == n)
        print(f"  anchor slug wrong for {n}: {dl.heading_slug(h)!r} != {want!r}")
    check(f'doc_lint computes GitHub\'s heading anchors ({len(slugs)} stated '
          f'cases, including the spaced dash that yields a double hyphen)',
          not bad)

    with tempfile.TemporaryDirectory() as td:
        d = pathlib.Path(td)
        (d / 'target.md').write_text(
            '# Top\n\n## What it cost — the numbers\n\n## Dup\n\n## Dup\n')
        (d / 'src.md').write_text(
            '# Src\n\n'
            '[ok](target.md#what-it-cost--the-numbers)\n'
            '[ok2](target.md#dup-1)\n'
            '[ok-self](#src)\n'
            '[dead](target.md#what-it-cost-the-numbers)\n'
            '[dead-self](#no-such-thing)\n')
        (d / 'setext.md').write_text('Underlined Title\n================\n')
        (d / 'into-setext.md').write_text(
            '# S\n\n[unknowable](setext.md#underlined-title)\n')
        old_root = dl.ROOT
        try:
            dl.ROOT = d
            dl._anchor_cache.clear()
            found = {t for _i, t, _w in dl.check_broken_links('src.md')}
            unknowable = dl.check_broken_links('into-setext.md')
        finally:
            dl.ROOT = old_root
            dl._anchor_cache.clear()

    check('a live anchor, a de-duplicated one (`#dup-1`) and a same-file '
          'anchor all resolve; a reworded one and a missing same-file one '
          'are both caught',
          found == {'target.md#what-it-cost-the-numbers', '#no-such-thing'},
          f'flagged {sorted(found)}')
    check('an anchor into a setext-headed document reads as "cannot tell", '
          'not as a missing anchor', not unknowable,
          f'flagged {unknowable}')


def check_materialized_links_are_placed():
    """A practice's relative links are repointed for where the file lands.

    Practice files ship. A practice's links are written relative to its own
    directory in its own repository, and copied verbatim into a consuming
    repo they point at nothing -- `../tools/very_deep_check.py` and
    `../spec/ATTENTION_CEILING.md` are real in Precedent and absent from
    every repo that installs it. Every consuming repo was shipping ~60
    practice files with dead internal links, and
    precedent-team-repo-maintenance' own light check had already had to exempt
    materialized practices/ from its broken-link scan to stay green.

    Four behaviours, and the last two are why this is not a blanket
    rewrite: a link that already resolves where it lands must be left
    exactly as it is, and a link this cannot place confidently must be
    left alone rather than mangled -- the output is a copy of somebody
    else's content."""
    import shutil, tempfile, importlib.util

    tmp = pathlib.Path(tempfile.mkdtemp(prefix='precedent-matlinks-'))
    cases = []
    try:
        spec = importlib.util.spec_from_file_location(
            '_pm_links', ROOT / 'tools' / 'precedent_materialize.py')
        pm = importlib.util.module_from_spec(spec)
        spec.loader.exec_module(pm)

        # An "upstream" source repo with a real remote and a real commit,
        # so the rewrite has something honest to point at.
        upstream = tmp / 'upstream'
        (upstream / 'practices').mkdir(parents=True)
        (upstream / 'spec').mkdir()
        (upstream / 'tools').mkdir()
        (upstream / 'spec' / 'THING.md').write_text('x\n', encoding='utf-8')
        (upstream / 'tools' / 'engine.py').write_text('x\n', encoding='utf-8')
        (upstream / 'practices' / 'sibling.md').write_text('x\n', encoding='utf-8')
        src = upstream / 'practices' / 'p.md'
        src.write_text(
            'See [spec/THING.md](../spec/THING.md) and [engine](../tools/engine.py).\n'
            'Sibling: [sibling](sibling.md). External: [x](https://example.com/a).\n'
            'Missing at the source: [gone](../spec/GONE.md).\n', encoding='utf-8')
        for argv in (['init', '-q'], ['config', 'user.email', 'h@e'],
                     ['config', 'user.name', 'h'],
                     ['remote', 'add', 'origin', 'https://github.com/acme/upstream.git'],
                     ['add', '-A'], ['commit', '-qm', 'seed']):
            subprocess.run(['git', '-C', str(upstream), *argv], capture_output=True)
        commit = subprocess.run(['git', '-C', str(upstream), 'rev-parse', 'HEAD'],
                                capture_output=True, text=True).stdout.strip()

        consumer = tmp / 'consumer'
        (consumer / 'practices').mkdir(parents=True)
        (consumer / 'tools').mkdir()
        (consumer / 'tools' / 'engine.py').write_text('x\n', encoding='utf-8')
        out = pm._rewrite_links(src.read_bytes(), str(src), consumer,
                                sibling_slugs={'sibling'}).decode('utf-8')

        cases.append(('a target in another repository becomes a commit URL — '
                      'the branch could be deleted, the commit cannot',
                      f'https://github.com/acme/upstream/blob/{commit}/spec/THING.md'
                      in out, out))
        cases.append(('a sibling practice link is left exactly as it is — '
                      'recognised from the slug set this run is writing, not '
                      'from what happens to be on disk yet',
                      '](sibling.md)' in out, out))
        cases.append(('an external URL is left alone',
                      '](https://example.com/a)' in out, out))
        cases.append(('a link that already resolves where it LANDS is left '
                      'relative — the consumer has its own tools/engine.py, '
                      'so an absolute URL would send the reader to the wrong '
                      'copy', '](../tools/engine.py)' in out, out))
        cases.append(("a link already broken at the source is left alone, not "
                      "invented", '](../spec/GONE.md)' in out, out))

        # The repo-local direction: same family, opposite sign. A practice at
        # local/practices/x.md writing `../tools/` means local/tools/, which
        # is NOT what that link means once the file sits at practices/x.md.
        (consumer / 'local' / 'practices').mkdir(parents=True)
        (consumer / 'local' / 'tools').mkdir()
        (consumer / 'local' / 'tools' / 'own.py').write_text('x\n', encoding='utf-8')
        lsrc = consumer / 'local' / 'practices' / 'l.md'
        lsrc.write_text('Ours: [own](../tools/own.py).\n', encoding='utf-8')
        lout = pm._rewrite_links(lsrc.read_bytes(), str(lsrc), consumer).decode('utf-8')
        cases.append(('a repo-local source\'s link is recomputed as a relative '
                      'path from the new location, not turned into a URL — the '
                      'file is right there in the same repo',
                      '](../local/tools/own.py)' in lout, lout))

        # The privacy boundary. An individual source is named only in a
        # person's own user-level config -- load_config refuses one declared
        # in a shared repo -- so writing its repository's URL into a tracked
        # practices/ tree publishes exactly what that refusal protects, and
        # a consuming repo can be public.
        iout = pm._rewrite_links(src.read_bytes(), str(src), consumer,
                                 sibling_slugs={'sibling'},
                                 may_name_source_repo=False).decode('utf-8')
        cases.append(("an individual source's link is NOT turned into a URL "
                      "naming its private repository — the dead relative link "
                      "is the smaller failure",
                      'github.com/acme/upstream' not in iout
                      and '](../spec/THING.md)' in iout, iout))
        cases.append(('and the placements that do not name that repository '
                      'still happen for an individual source',
                      '](../tools/engine.py)' in iout and '](sibling.md)' in iout,
                      iout))

        # No remote, no rewrite: never guess a URL.
        noremote = tmp / 'noremote'
        (noremote / 'practices').mkdir(parents=True)
        (noremote / 'spec').mkdir()
        (noremote / 'spec' / 'THING.md').write_text('x\n', encoding='utf-8')
        nsrc = noremote / 'practices' / 'p.md'
        nsrc.write_text('See [t](../spec/THING.md).\n', encoding='utf-8')
        subprocess.run(['git', '-C', str(noremote), 'init', '-q'], capture_output=True)
        nout = pm._rewrite_links(nsrc.read_bytes(), str(nsrc), consumer).decode('utf-8')
        cases.append(('a source with no usable remote leaves its links alone '
                      'rather than writing a URL it had to guess',
                      '](../spec/THING.md)' in nout, nout))
    finally:
        shutil.rmtree(tmp, ignore_errors=True)

    bad = [(c[0], c[2]) for c in cases if not c[1]]
    check(f'a materialized practice\'s links are placed for where the file '
          f'lands ({len(cases)} stated cases: another repo becomes a commit '
          f'URL; a sibling, an external URL, a link that already resolves, '
          f'and a link broken at the source are all left alone; a repo-local '
          f'source is recomputed relative; an individual source never names '
          f'its own private repository; no remote means no rewrite)',
          not bad, '; '.join(f"{n} -- {d[:160]}" for n, d in bad))


def _renamed_universal_fixture(tmp):
    """A scratch consumer whose individual source cites a renamed universal
    practice -- the shape the go-merge -> go-update rename (2026-09-26)
    broke in every consumer. The universal source carries the live
    `go-update` and a deduplicated `go-merge` stub forwarding to it; the
    individual source carries its own `go-merge`, deduplicated against the
    universal one by the OLD name, and a practice citing `go-merge.md` both
    as a sibling and by a path into the universal clone. Returns the source
    list, lowest precedence first, and the consumer directory."""
    def write(path, slug, status='active', in_force_at=None, rule='x'):
        path.parent.mkdir(parents=True, exist_ok=True)
        ifa = f'in_force_at: {in_force_at}\n' if in_force_at else ''
        path.write_text(
            f'---\nslug: {slug}\ntitle: Fixture\ntier: on-demand\n'
            f'severity: default\napplies_to: []\noccasion: "x"\ngates: []\n'
            f'index_clause: "x"\nchecked_by: null\ndefines: []\n'
            f'status: {status}\n{ifa}supersedes: []\noverrides: null\n'
            f'added: 2026-09-26\napproved_by: "harness, 2026-09-26"\n---\n'
            f'## Rule\n{rule}\n\n## Why\nx\n\n## Story\nx\n\n## Install\nx\n',
            encoding='utf-8')
    uni, ind, consumer = tmp / 'uni', tmp / 'ind', tmp / 'consumer'
    write(uni / 'practices' / 'go-update.md', 'go-update')
    write(uni / 'practices' / 'go-merge.md', 'go-merge', 'deduplicated', 'go-update')
    write(ind / 'practices' / 'go-merge.md', 'go-merge', 'deduplicated', 'go-merge')
    write(ind / 'practices' / 'cites.md', 'cites',
          rule='Sibling: [go-merge](go-merge.md#rule). '
               'Path: [stub](../../uni/practices/go-merge.md).')
    consumer.mkdir()
    sources = [{'level': 'universal', 'name': 'precedent', 'path': str(uni)},
               {'level': 'individual', 'name': 'precedent-individual',
                'path': str(ind)}]
    return sources, consumer, write


def check_in_force_at_chain_is_followed():
    """A deduplication naming a slug that is itself a deduplicated stub is in
    force wherever that stub forwards to, not IN FORCE NOWHERE.

    WHY. Renaming go-merge to go-update on 2026-09-26 left a universal
    `go-merge` stub forwarding to `go-update`. An individual set's own
    `go-merge`, deduplicated against the universal one by the old name,
    was checked with a bare membership test against what resolved in force,
    so every consumer read it IN FORCE NOWHERE while the rule was live one
    hop on. The walk has to stop on a cycle as well: a set's copy names the
    very slug it carries, which is a two-node loop the moment the other end
    is missing."""
    import shutil, tempfile
    sys.path.insert(0, str(ROOT / 'tools'))
    import precedent_resolve as _pr

    tmp = pathlib.Path(tempfile.mkdtemp(prefix='precedent-chain-'))
    cases = []
    try:
        sources, _consumer, write = _renamed_universal_fixture(tmp)
        res = _pr.resolve(sources)
        cases.append(('an individual deduplication naming a renamed universal '
                      'stub resolves through it -- nothing dangling',
                      not res['dangling'], str(res['dangling'])))
        # getattr, so an engine without the helpers reports named failing
        # cases rather than a traceback that hides which behaviour broke.
        follow = getattr(_pr, 'follow_in_force_at', None)
        fmap = getattr(_pr, 'forwarding_map', None)
        cases.append(('the chain ends on the live slug',
                      follow is not None and follow(
                          'go-merge', res['practices'], res['retired']) == 'go-update',
                      'follow_in_force_at missing' if follow is None else ''))
        forwards = fmap(res) if fmap else None
        cases.append(('forwarding_map names the rename',
                      forwards == {'go-merge': 'go-update'}, str(forwards)))

        # The control: take the live end away, and the same chain is
        # dangling again -- following it must not make everything pass.
        (tmp / 'uni' / 'practices' / 'go-update.md').unlink()
        res = _pr.resolve(sources)
        cases.append(('with the live end gone the chain is dangling, not '
                      'quietly accepted',
                      any(d['slug'] == 'go-merge' for d in res['dangling']),
                      str(res['dangling'])))

        # A cycle ends in None rather than a hang.
        write(tmp / 'uni' / 'practices' / 'loop-a.md', 'loop-a', 'deduplicated', 'loop-b')
        write(tmp / 'uni' / 'practices' / 'loop-b.md', 'loop-b', 'deduplicated', 'loop-a')
        res = _pr.resolve(sources)
        cases.append(('a cycle of deduplications is reported dangling and '
                      'the walk terminates',
                      {'loop-a', 'loop-b'} <= {d['slug'] for d in res['dangling']},
                      str(res['dangling'])))
    finally:
        shutil.rmtree(tmp, ignore_errors=True)

    bad = [(c[0], c[2]) for c in cases if not c[1]]
    check(f'a deduplication\'s in_force_at: chain is followed to the rule in '
          f'force, with a cycle guard ({len(cases)} stated cases)',
          not bad, '; '.join(f'{n} -- {d[:160]}' for n, d in bad))


def check_links_to_renamed_practice_forward():
    """A materialized link to a renamed or deduplicated practice points at the
    live practice this run writes, not at a stub the consumer never gets.

    WHY. A consumer materializes only what is in force. After the go-merge
    -> go-update rename (2026-09-26), every `go-merge.md` citation in the
    private sets was left as written by _rewrite_links -- and, from an
    individual source, it may not become a URL either -- so the link was
    dead in every consumer."""
    import shutil, tempfile
    sys.path.insert(0, str(ROOT / 'tools'))
    import precedent_resolve as _pr, precedent_materialize as _pm

    tmp = pathlib.Path(tempfile.mkdtemp(prefix='precedent-fwdlinks-'))
    cases = []
    try:
        sources, consumer, _write = _renamed_universal_fixture(tmp)
        res = _pr.resolve(sources)
        _pm.materialize(sources, res, consumer)
        placed = consumer / 'practices'
        text = ((placed / 'cites.md').read_text(encoding='utf-8')
                if (placed / 'cites.md').is_file() else '')
        cases.append(('the stub itself is not materialized -- the reason the '
                      'old link was dead',
                      not (placed / 'go-merge.md').exists()
                      and (placed / 'go-update.md').is_file(), ''))
        cases.append(('a sibling link to the renamed slug now names the live '
                      'one, anchor kept',
                      '](go-update.md#rule)' in text, text[-300:]))
        cases.append(('a path into the source clone naming the stub file is '
                      'sent to the live sibling too',
                      '](go-update.md)' in text
                      and 'uni/practices/go-merge.md' not in text, text[-300:]))
        cases.append(('an individual source still names no repository',
                      'github.com' not in text, text[-300:]))

        # With the live end not in this run there is nothing to forward to,
        # so the link is left as written rather than invented.
        (tmp / 'uni' / 'practices' / 'go-update.md').unlink()
        res = _pr.resolve(sources)
        _pm.materialize(sources, res, consumer)
        text = (placed / 'cites.md').read_text(encoding='utf-8')
        cases.append(('with no live slug in the run, the link is left alone',
                      '](go-merge.md#rule)' in text, text[-300:]))
    finally:
        shutil.rmtree(tmp, ignore_errors=True)

    bad = [(c[0], c[2]) for c in cases if not c[1]]
    check(f'a materialized link to a renamed practice forwards to the live '
          f'practice ({len(cases)} stated cases)',
          not bad, '; '.join(f'{n} -- {d[:160]}' for n, d in bad))


def _fixture_git_env():
    return dict(os.environ, GIT_AUTHOR_NAME='F', GIT_AUTHOR_EMAIL='f@x',
                GIT_COMMITTER_NAME='F', GIT_COMMITTER_EMAIL='f@x',
                GIT_CONFIG_GLOBAL=os.devnull, PRECEDENT_ALLOW_ANY_AUTHOR='1')


def check_promote_branches_are_named_like_session_branches():
    """A Promote's fix branch and its copy of staging are named
    claude/<date>-<slug>-<session ID's end>, like every temporary branch --
    except a copy in a repository whose GitHub test knows only the old
    names, which keeps them until Update Vendors brings the new workflow.

    WHY. Morgan, 2026-10-06, reading `promote-fix-20261006T165108-0300` in a
    reply: "isn't our URL format for temporary GitHub repo URLs to start with
    the timestamps then the slug then a few random characters?" The
    Promote's own branches had never been brought into the format."""
    import tempfile
    sys.path.insert(0, str(ROOT / 'tools'))
    import precedent_branches as pb
    import precedent_branch_name as pbn
    env = _fixture_git_env()
    saved = {k: os.environ.get(k) for k in ('CLAUDE_CODE_REMOTE_SESSION_ID', 'CLAUDECODE')}
    os.environ['CLAUDE_CODE_REMOTE_SESSION_ID'] = 'session_01FixtureSessionIdAbcde'
    os.environ['CLAUDECODE'] = '1'
    tpl = (ROOT / 'templates' / 'github-actions' / 'light-check.yml.template').read_text(
        encoding='utf-8')
    try:
        with tempfile.TemporaryDirectory() as td:
            td = pathlib.Path(td)
            origin, repo = td / 'origin.git', td / 'work'
            run = lambda *a, cwd=td: subprocess.run(list(a), cwd=str(cwd), env=env,
                                                    capture_output=True, text=True)
            run('git', 'init', '-q', '--bare', str(origin))
            run('git', 'init', '-q', '-b', 'staging', str(repo))
            (repo / '.github' / 'workflows').mkdir(parents=True)
            wf = repo / '.github' / 'workflows' / 'light-check.yml'
            wf.write_text(tpl, encoding='utf-8')
            run('git', 'add', '-A', cwd=repo); run('git', 'commit', '-qm', 'base', cwd=repo)
            run('git', 'remote', 'add', 'origin', str(origin), cwd=repo)
            run('git', 'push', '-q', 'origin', 'staging', cwd=repo)
            run('git', 'fetch', '-q', 'origin', cwd=repo)
            day, _m = pb._day_and_moment(repo)
            fix = pb._fix_branch(repo)
            check('a Promote\'s fix branch is named claude/<date>-promote-fix-<id>, '
                  'which the naming rule accepts',
                  fix == f'claude/{day}-promote-fix-abcde'
                  and pbn.name_refusal(fix) is None and pb.is_fix_branch(fix), fix)
            have_tests = bool(pb.github_tests(repo, pb._remote_tip(repo, pb.staging_branch(repo))))
            copy, not_due = pb._to_main_copy(repo), pb._to_main_copy(repo, due=False)
            check('its copies of staging too, where the GitHub test knows the new names',
                  copy == f'claude/{day}-promote-to-main-abcde'
                  and not_due == f'claude/{day}-promote-to-main-not-due-abcde'
                  and pb.is_main_copy(copy) and pb.is_not_due_copy(not_due),
                  f'{copy} {not_due} tests={have_tests}')
            wf.write_text(tpl.replace(pb.COPY_NAME_MARKER, '-x-'), encoding='utf-8')
            run('git', 'commit', '-qam', 'an older workflow', cwd=repo)
            run('git', 'push', '-q', 'origin', 'staging', cwd=repo)
            run('git', 'fetch', '-q', 'origin', cwd=repo)
            old = pb._to_main_copy(repo, due=False)
            check('CONTROL: where the GitHub test knows only the old names, a copy '
                  'keeps one, so a not-due copy is still skipped',
                  have_tests and old.startswith(pb.NOT_DUE_PREFIX), f'{old} tests={have_tests}')
    finally:
        for k, v in saved.items():
            if v is None:
                os.environ.pop(k, None)
            else:
                os.environ[k] = v


def check_practice_declared_hooks_are_wired():
    """A practice's `hooks:` declaration is parsed in one place, refused when
    it reaches past what the practice ships, and wired add-only by the sync.

    WHY. 2026-10-06: the writing set's dated-download-names shipped its
    script and a check requiring a SendUserFile hook, and said the hook was
    wired by hand. Nothing wired it, so a consumer failed that check right
    after a clean sync."""
    import tempfile
    sys.path.insert(0, str(ROOT / 'tools'))
    import build_views as bv
    import precedent_vendor_engine as pve
    import precedent_sync_views as psv
    good = {'ships': '["tools/dated_name.py"]',
            'hooks': '[{"event": "PreToolUse", "matcher": "SendUserFile", '
                     '"run": "tools/dated_name.py", "args": ["--hook"]}]'}
    hooks = bv.practice_hooks(good)
    check('a declared hook parses into the command the sync writes',
          [bv.hook_command(h) for h in hooks]
          == ['python3 $CLAUDE_PROJECT_DIR/tools/dated_name.py --hook'], repr(hooks))
    for why, raw in (
            ('a script the practice does not ship',
             '[{"event": "Stop", "run": "tools/other.py"}]'),
            ('a tool event with no matcher',
             '[{"event": "PreToolUse", "run": "tools/dated_name.py"}]'),
            ('an argument that is not a plain word',
             '[{"event": "Stop", "run": "tools/dated_name.py", "args": ["; rm x"]}]'),
            ('an event outside the list',
             '[{"event": "Notification", "run": "tools/dated_name.py"}]'),
            ('a command line of its own',
             '[{"event": "Stop", "run": "tools/dated_name.py", "command": "sh"}]')):
        try:
            bv.practice_hooks({**good, 'hooks': raw})
            refused = False
        except ValueError:
            refused = True
        check(f'a hooks: entry naming {why} is refused', refused, raw)
    check('CONTROL: no hooks: field declares nothing',
          bv.practice_hooks({'ships': '[]'}) == [], '')

    with tempfile.TemporaryDirectory() as td:
        repo = pathlib.Path(td)
        (repo / 'tools').mkdir()
        (repo / 'tools' / 'dated_name.py').write_text('', encoding='utf-8')
        practices = {'dated-download-names': {'fm': good}}
        entries, notes = psv._declared_practice_hooks(repo, practices)
        check('no settings.json: nothing is written, and none is created',
              pve.add_practice_hooks(repo, entries) == []
              and not (repo / '.claude').exists(), '')
        (repo / '.claude').mkdir()
        mine = {'hooks': {'PreToolUse': [{'matcher': 'Bash', 'hooks': [
            {'type': 'command', 'command': 'echo mine'}]}]}}
        (repo / '.claude' / 'settings.json').write_text(json.dumps(mine),
                                                        encoding='utf-8')
        missing = pve.missing_practice_hooks(repo, entries)
        check('--check reports the declared hook as missing',
              [c for _e, _m, c in missing]
              == ['python3 $CLAUDE_PROJECT_DIR/tools/dated_name.py --hook'],
              repr(missing))
        added = pve.add_practice_hooks(repo, entries)
        got = json.loads((repo / '.claude' / 'settings.json').read_text())
        groups = got['hooks']['PreToolUse']
        check('the sync adds it under its own matcher, and the repo\'s own '
              'entry is untouched',
              len(added) == 1 and groups[0] == mine['hooks']['PreToolUse'][0]
              and groups[1]['matcher'] == 'SendUserFile', json.dumps(got))
        check('a second sync adds nothing',
              pve.add_practice_hooks(repo, entries) == []
              and pve.missing_practice_hooks(repo, entries) == [], '')
        (repo / 'precedent.json').write_text(json.dumps(
            {'declined_ships': {'tools/dated_name.py': 'not here'}}), encoding='utf-8')
        declined, _n = psv._declared_practice_hooks(repo, practices)
        check('a repo that declined the script gets no hook for it',
              declined == [], repr(declined))
        (repo / 'precedent.json').unlink()
        (repo / 'tools' / 'dated_name.py').unlink()
        absent, _n = psv._declared_practice_hooks(repo, practices)
        check('a script not on disk gets no hook', absent == [], repr(absent))
        bad, notes = psv._declared_practice_hooks(
            repo, {'x': {'fm': {**good, 'hooks': '[{"event": "Stop"}]'}}})
        check('a declaration that does not parse is a note, never a guess',
              bad == [] and notes and 'x:' in notes[0], repr(notes))


def check_stale_views_judged_on_what_a_push_brings():
    """views_sync is judged on what a push to a working branch brings: a
    stale view the fork point shows too is reported, one the push makes is
    still refused.

    WHY. 2026-10-06: a practice source a consumer declares moved, its views
    went stale, and a one-line content push to a feature branch was refused
    for it."""
    import tempfile
    sys.path.insert(0, str(ROOT / 'tools'))
    import precedent_push_check as ppc
    check('views_sync is one of the checks judged on what a push brings',
          'views_sync' in ppc.RANGE_JUDGED, '')
    env = _fixture_git_env()
    with tempfile.TemporaryDirectory() as td:
        repo = pathlib.Path(td)
        g = lambda *a: subprocess.run(['git', '-C', str(repo), *a], env=env,
                                      capture_output=True, text=True)
        g('init', '-q', '-b', 'main')
        (repo / 'tools').mkdir()
        stub = repo / 'tools' / 'views_stub.py'
        stub.write_text(
            'import pathlib, sys\n'
            'sys.path.insert(0, sys.argv[1])\n'
            'import precedent_sync_views as psv\n'
            'v = pathlib.Path("VIEW.md").read_text().strip()\n'
            'if v != "fresh":\n'
            '    print(psv.findings_block([f"VIEW.md is {v}"]), file=sys.stderr)\n'
            '    sys.exit("precedent_sync_views --check FAIL")\n', encoding='utf-8')
        (repo / 'VIEW.md').write_text('stale\n', encoding='utf-8')
        g('add', '-A'); g('commit', '-qm', 'base, already stale')
        g('checkout', '-qb', 'work')
        (repo / 'content.md').write_text('one line\n', encoding='utf-8')
        g('add', '-A'); g('commit', '-qm', 'a content push')
        import precedent_sync_views as psv
        block = psv.findings_block(['AGENTS.md is stale', 'practices/x.md differs'])
        check('the real sync\'s --check findings read as finding lines',
              ppc.violation_lines((block + '\nprecedent_sync_views --check FAIL: '
                                   'x').splitlines())
              == ['AGENTS.md is stale', 'practices/x.md differs'], block)
        argv = [sys.executable, str(stub), str(ROOT / 'tools')]
        out = subprocess.run(argv, cwd=repo, capture_output=True, text=True)
        lines = (out.stdout + out.stderr).splitlines()
        check('a stale view the fork point shows too is not refused',
              ppc.already_landed(repo, argv, lines, ['main']) is not None, '')
        (repo / 'VIEW.md').write_text('hand-edited\n', encoding='utf-8')
        g('add', '-A'); g('commit', '-qm', 'a hand edit')
        out = subprocess.run(argv, cwd=repo, capture_output=True, text=True)
        lines = (out.stdout + out.stderr).splitlines()
        check('CONTROL: a view this push edits by hand is still refused',
              ppc.already_landed(repo, argv, lines, ['main']) is None, repr(lines))


def check_merge_refreshes_stale_views_as_its_own_commit():
    """At a merge, views a moved source left stale are regenerated as a
    commit of their own -- and a refresh that would change hooks or
    settings is taken back and asks for the person's go-ahead instead.

    WHY. 2026-10-06: the push check stopped refusing a stale view a push
    did not bring, so the refresh it points at has to happen somewhere:
    here, where the vendor update already rides along. And auto mode holds
    a commit that changes .claude/ until the person says yes."""
    import tempfile
    sys.path.insert(0, str(ROOT / 'tools'))
    import precedent_merge_vendors as pmv
    env = _fixture_git_env()
    for harness in (False, True):
        with tempfile.TemporaryDirectory() as td:
            repo = pathlib.Path(td)
            g = lambda *a: subprocess.run(['git', '-C', str(repo), *a], env=env,
                                          capture_output=True, text=True)
            g('init', '-q', '-b', 'main')
            (repo / 'tools').mkdir()
            (repo / '.claude').mkdir()
            (repo / '.claude' / 'settings.json').write_text('{}\n', encoding='utf-8')
            (repo / 'tools' / 'precedent_sync_views.py').write_text(
                'import pathlib, sys\n'
                'p = pathlib.Path("AGENTS.md")\n'
                'if "--check" in sys.argv:\n'
                '    sys.exit(0 if p.read_text() == "fresh\\n" else 1)\n'
                'p.write_text("fresh\\n")\n'
                'pathlib.Path("practices").mkdir(exist_ok=True)\n'
                'pathlib.Path("practices/new.md").write_text("x\\n")\n'
                + ('pathlib.Path(".claude/settings.json").write_text("{\\"hooks\\": {}}\\n")\n'
                   if harness else ''), encoding='utf-8')
            (repo / 'AGENTS.md').write_text('stale\n', encoding='utf-8')
            (repo / 'notes.txt').write_text('mine, untracked\n', encoding='utf-8')
            g('add', 'tools', '.claude', 'AGENTS.md'); g('commit', '-qm', 'base')
            head = g('rev-parse', 'HEAD').stdout.strip()
            saved_env = os.environ.pop(pmv.HARNESS_GO_AHEAD, None)
            saved_git = {k: os.environ.get(k) for k in env if k.startswith('GIT_')}
            os.environ.update({k: v for k, v in env.items() if k.startswith('GIT_')})
            try:
                import io, contextlib
                buf = io.StringIO()
                with contextlib.redirect_stdout(buf):
                    pmv.refresh_views(repo)
                said = buf.getvalue()
                moved = g('rev-parse', 'HEAD').stdout.strip() != head
                files = g('show', '--name-only', '--format=', 'HEAD').stdout.split()
                clean = g('status', '--porcelain', '--untracked-files=no').stdout == ''
                if not harness:
                    check('a stale view is refreshed in a commit of its own, '
                          'taking the new file and leaving untracked files alone',
                          moved and sorted(files) == ['AGENTS.md', 'practices/new.md']
                          and 'VIEWS: refreshed' in said
                          and (repo / 'notes.txt').is_file(), said + repr(files))
                else:
                    check('a refresh that changes .claude/ is taken back and asks '
                          'for the person\'s go-ahead',
                          not moved and clean and 'NOT REFRESHED' in said
                          and pmv.HARNESS_GO_AHEAD in said
                          and not (repo / 'practices' / 'new.md').exists(), said)
                    os.environ[pmv.HARNESS_GO_AHEAD] = 'yes, wire it'
                    buf = io.StringIO()
                    with contextlib.redirect_stdout(buf):
                        pmv.refresh_views(repo)
                    msg = g('log', '-1', '--format=%B').stdout
                    check('...and with the person\'s words it commits, quoting them',
                          'yes, wire it' in msg and 'VIEWS: refreshed' in buf.getvalue(),
                          buf.getvalue() + msg)
            finally:
                os.environ.pop(pmv.HARNESS_GO_AHEAD, None)
                if saved_env is not None:
                    os.environ[pmv.HARNESS_GO_AHEAD] = saved_env
                for k, v in saved_git.items():
                    if v is None:
                        os.environ.pop(k, None)
                    else:
                        os.environ[k] = v


def check_update_asks_before_changing_hooks():
    """Update Vendors names a change to hooks or settings as a question for
    the person, printed ahead of the commit, instead of meeting auto mode at
    it -- and still finishes, since it is not the repo's call (2026-10-06)."""
    import tempfile
    sys.path.insert(0, str(ROOT / 'tools'))
    import precedent_update as pu
    env = _fixture_git_env()
    with tempfile.TemporaryDirectory() as td:
        repo = pathlib.Path(td)
        g = lambda *a: subprocess.run(['git', '-C', str(repo), *a], env=env,
                                      capture_output=True, text=True)
        g('init', '-q', '-b', 'main')
        (repo / 'a.md').write_text('a\n', encoding='utf-8')
        g('add', '-A'); g('commit', '-qm', 'base')
        (repo / 'tools').mkdir()
        (repo / 'tools' / 'x.py').write_text('', encoding='utf-8')
        g('add', '-A')
        check('CONTROL: an update touching no hook or setting asks nothing',
              pu.harness_changes(repo) == [], '')
        (repo / '.claude' / 'hooks').mkdir(parents=True)
        (repo / '.claude' / 'hooks' / 'h.sh').write_text('', encoding='utf-8')
        g('add', '-A')
        got = pu.harness_changes(repo)
        ask = pu.harness_ask(got)
        check('a staged hook is named, with the go-ahead to ask for',
              got == ['.claude/hooks/h.sh'] and pu.HARNESS_GO_AHEAD in ask
              and '.claude/hooks/h.sh' in ask, repr(got) + ask)
        rep = pu.Report()
        rep.ask('hooks and settings', ask)
        import io, contextlib
        buf = io.StringIO()
        with contextlib.redirect_stdout(buf):
            rc = rep.close()
        check('...as a question for the person: the update still ends DONE, '
              'and the question is printed ahead of the commit',
              rc == pu.DONE and 'QUESTIONS FOR THE PERSON' in buf.getvalue()
              and '.claude/hooks/h.sh' in buf.getvalue(), buf.getvalue()[-600:])


def check_landed_branch_gets_its_delete_link():
    """A branch that was not on its landing branch when the turn began and is
    by the turn's end is used up: the stop hook refuses a reply that gives no
    one-click delete link for it (the-boildown item 6, branch-delete-links).

    WHY. 2026-10-06, a consumer session Booked its branch onto pre-staging and
    its reply named no delete link. Only the other half -- work NOT yet
    landed -- had anything enforcing it."""
    import tempfile
    sys.path.insert(0, str(ROOT / 'tools'))
    import precedent_gate as pg
    cases = []
    saved = {k: os.environ.pop(k, None) for k in
             ('CLAUDE_CODE_REMOTE_SESSION_ID', 'CLAUDE_PROJECT_DIR')}
    env = _fixture_git_env()
    for k in ('CLAUDE_CODE_REMOTE_SESSION_ID', 'CLAUDE_PROJECT_DIR'):
        env.pop(k, None)
    tmp = pathlib.Path(tempfile.mkdtemp(prefix='precedent-delete-link-'))
    try:
        up, repo = tmp / 'up.git', tmp / 'repo'
        g = lambda *a: subprocess.run(['git', '-C', str(repo), *a], env=env,
                                      capture_output=True, text=True)
        subprocess.run(['git', 'init', '--bare', '-q', '-b', 'trunk', str(up)], env=env)
        subprocess.run(['git', 'init', '-q', '-b', 'trunk', str(repo)], env=env)
        (repo / 'precedent.json').write_text(json.dumps({
            'base_branch': 'trunk',
            'sources': [{'level': 'universal', 'name': 'precedent', 'path': '.'}]}),
            encoding='utf-8')
        decl = [r for r in json.loads((ROOT / 'reply_check.json').read_text(
            encoding='utf-8')) if r.get('id') == 'landed-branch-gets-its-delete-link']
        (repo / 'reply_check.json').write_text(json.dumps(decl), encoding='utf-8')
        (repo / 'a.txt').write_text('one\n', encoding='utf-8')
        g('add', '-A'); g('commit', '-qm', 'first')
        g('remote', 'add', 'origin', str(up)); g('push', '-q', '-u', 'origin', 'trunk')
        branch = 'claude/2026-10-06-thing-abcde'
        g('switch', '-q', '-c', branch)
        (repo / 'b.txt').write_text('two\n', encoding='utf-8')
        g('add', '-A'); g('commit', '-qm', 'second'); g('push', '-q', 'origin', branch)

        def turn_start():
            recs = []
            pg._unlanded_work(repo, siblings=False, records=recs)
            pg.record_turn_start_unlanded(repo, recs)
            return recs

        def replycheck(name, text):
            q = tmp / name
            q.write_text(text, encoding='utf-8')
            return subprocess.run(
                [sys.executable, str(ROOT / 'tools' / 'precedent_reply_check.py'),
                 '--repo', str(repo), '--text', str(q)],
                capture_output=True, text=True, cwd=str(tmp),
                env={**env, 'CLAUDE_PROJECT_DIR': str(repo),
                     'PRECEDENT_USER_CONFIG': str(tmp / 'no-such-config.json')})

        bare = 'Booked.\n\n## Boildown\n- The work of this session is now on: `trunk`.\n'
        linked = bare + ('- Delete [the branch](https://github.com/o/r/branches/all?'
                         'query=claude%2F2026-10-06-thing-abcde) when you like; it '
                         'merged into `trunk`.\n')
        recs = turn_start()
        cases.append(('the turn start records the unlanded branch',
                      [r['branch'] for r in recs] == [branch], str(recs)))
        r0 = replycheck('before.md', bare)
        cases.append(('not landed yet: no link is asked for',
                      r0.returncode == 0, f'exit {r0.returncode}: {r0.stderr[:200]}'))
        g('push', '-q', 'origin', f'{branch}:trunk')
        r1 = replycheck('bare.md', bare)
        cases.append(('landed during the turn, no link: refused, naming the '
                      'branch and the link form',
                      r1.returncode == 2 and branch in r1.stderr
                      and 'branches/all?query=claude%2F2026-10-06-thing-abcde' in r1.stderr,
                      f'exit {r1.returncode}: {r1.stderr[:300]}'))
        r2 = replycheck('linked.md', linked)
        cases.append(('...and the same reply with the link passes',
                      r2.returncode == 0, f'exit {r2.returncode}: {r2.stderr[:200]}'))
        turn_start()
        r3 = replycheck('next.md', bare)
        cases.append(('the next turn, which began with it landed, asks nothing',
                      r3.returncode == 0, f'exit {r3.returncode}: {r3.stderr[:200]}'))
        src = (ROOT / 'tools' / 'precedent_gate.py').read_text(encoding='utf-8')
        cases.append(('the reply gate writes the turn start',
                      'record_turn_start_unlanded(root, _records)' in src, ''))
    finally:
        os.environ.update({k: v for k, v in saved.items() if v is not None})
        shutil.rmtree(tmp, ignore_errors=True)
        sys.path.pop(0)
    bad = [(n, d) for n, ok, d in cases if not ok]
    check(f'a branch landed during the turn gets its delete link '
          f'({len(cases)} stated cases)', not bad,
          '; '.join(f'{n}: {d}' for n, d in bad))


def check_install_and_update_name_the_code_owners():
    """Install and Update Vendors name a repository's code owners when it
    names none: everyone GitHub lists with edit access, in precedent.json's
    `maintainers`, or the person running it when GitHub cannot say. A list
    already set -- there, in approvers.json or a CODEOWNERS file -- is never
    touched.

    WHY. Morgan, 2026-10-06 (strength: decided): the code owners are "those
    who have access to edit *at that moment*. That becomes the started
    default." Fifteen of his repositories named nobody that day, which hid
    every code-owner practice from him in each of them."""
    import tempfile
    sys.path.insert(0, str(ROOT / 'tools'))
    import precedent_vendor_engine as pve
    import precedent_audience as pa
    import github_budget as gb
    cases = []
    saved_call = gb.call
    saved_user = os.environ.get('PRECEDENT_GITHUB_USER')
    tmp = pathlib.Path(tempfile.mkdtemp(prefix='precedent-maintainers-'))
    try:
        def fresh(name, text='{\n  "base_branch": "main",\n  "sources": []\n}\n'):
            d = tmp / name
            d.mkdir()
            subprocess.run(['git', 'init', '-q', str(d)], env=_fixture_git_env(),
                           capture_output=True)
            (d / 'precedent.json').write_text(text, encoding='utf-8')
            return d

        a = fresh('a')
        got, how = pve.seed_maintainers(a, logins=['alice', 'Bob'], today='2026-10-06')
        cfg = json.loads((a / 'precedent.json').read_text(encoding='utf-8'))
        cases.append(('a repository naming nobody gets the list written',
                      got == ['alice', 'Bob']
                      and cfg.get('maintainers') == [{'github': 'alice'}, {'github': 'Bob'}],
                      f'{got} {cfg}'))
        cases.append(('...which the code-owner check then reads',
                      pa.owners(a)[0] == {'@alice', '@bob'}, str(pa.owners(a))))
        cases.append(('...keeping the rest of the file as it was',
                      (a / 'precedent.json').read_text(encoding='utf-8').endswith(
                          '  "base_branch": "main",\n  "sources": []\n}\n'), ''))
        got2, how2 = pve.seed_maintainers(a, logins=['mallory'])
        cases.append(('a list already set is never rewritten',
                      got2 == [] and 'already names' in how2, how2))

        b = fresh('b')
        (b / 'CODEOWNERS').write_text('* @carol\n', encoding='utf-8')
        got3, how3 = pve.seed_maintainers(b, logins=['dave'])
        cases.append(('a CODEOWNERS file counts as set',
                      got3 == [] and 'maintainers' not in json.loads(
                          (b / 'precedent.json').read_text(encoding='utf-8')), how3))

        gb.call = lambda path, **k: ([
            {'login': 'erin', 'type': 'User', 'permissions': {'push': True}},
            {'login': 'frank', 'type': 'User', 'permissions': {'pull': True}},
            {'login': 'helper[bot]', 'type': 'Bot', 'permissions': {'admin': True}},
            {'login': 'gina', 'type': 'User', 'permissions': {'admin': True}}], None)
        c = fresh('c')
        subprocess.run(['git', '-C', str(c), 'remote', 'add', 'origin',
                        'https://github.com/o/r.git'], capture_output=True)
        got4, how4 = pve.seed_maintainers(c, today='2026-10-06')
        cases.append(('from GitHub: everyone who can edit, readers and bots left out',
                      got4 == ['erin', 'gina'] and 'edit access' in how4, f'{got4} {how4}'))

        gb.call = lambda path, **k: (None, 'HTTP 403')
        os.environ['PRECEDENT_GITHUB_USER'] = 'hank'
        d = fresh('d')
        subprocess.run(['git', '-C', str(d), 'remote', 'add', 'origin',
                        'https://github.com/o/r.git'], capture_output=True)
        got5, how5 = pve.seed_maintainers(d, today='2026-10-06')
        cases.append(('GitHub unable to say: the person running it, and why',
                      got5 == ['hank'] and 'person running' in how5 and '403' in how5,
                      f'{got5} {how5}'))

        for f, needle in (('precedent_update.py', 'maintainers_step(repo, rep)'),
                          ('precedent_install.py', 'seed_maintainers(dest)')):
            cases.append((f'{f} runs it',
                          needle in (ROOT / 'tools' / f).read_text(encoding='utf-8'), ''))
    finally:
        gb.call = saved_call
        if saved_user is None:
            os.environ.pop('PRECEDENT_GITHUB_USER', None)
        else:
            os.environ['PRECEDENT_GITHUB_USER'] = saved_user
        shutil.rmtree(tmp, ignore_errors=True)
        sys.path.pop(0)
    bad = [(n, d) for n, ok, d in cases if not ok]
    check(f'install and update name the code owners when none are named '
          f'({len(cases)} stated cases)', not bad,
          '; '.join(f'{n}: {d}' for n, d in bad))


def check_update_judges_retired_sets_after_the_catalogue():
    """Update Vendors judges a retired set after the catalogue update, and
    takes the view sync's removals when every one came from a set it dropped
    itself -- never any other refused removal.

    WHY. 2026-10-06, a consumer's update: a retired set's last rules were
    being folded into universal in the same update, but the set was judged
    against the old catalogue, read as holding rules "in force nowhere
    else", and kept. And where an update did drop a set, its own view sync
    then refused to remove that set's practices, with no way through."""
    sys.path.insert(0, str(ROOT / 'tools'))
    import precedent_update as pu
    cases = []
    try:
        src = (ROOT / 'tools' / 'precedent_update.py').read_text(encoding='utf-8')
        body = src[src.index('def update('):]
        at = body.index('dropped_sets = retired_sources_step(repo, rep)')
        cases.append(('the retired-set step runs after the catalogue and before '
                      'the views',
                      body.index('# 3. The catalogue') < at < body.index('# 4. The views')))
        refusal = ("refusing to WRITE: this sync would remove 2 practice(s) this "
                   "repository's committed MANIFEST.json records, whose source "
                   "name is not among the sources precedent.json declares -- "
                   "light-check (recorded from precedent-shared-repo-maintenance); "
                   "{second} (recorded from {src}). THREE things produce this")
        ok = refusal.format(second='fresh-before-write',
                            src='precedent-shared-repo-maintenance')
        cases.append(('every refused removal from a set it dropped: taken',
                      sorted(pu.removals_this_update_caused(
                          ok, ['precedent-shared-repo-maintenance']))
                      == ['fresh-before-write', 'light-check']))
        mixed = refusal.format(second='x-rule', src='precedent-renamed-set')
        cases.append(('one from a source it did not drop: left to the person',
                      pu.removals_this_update_caused(
                          mixed, ['precedent-shared-repo-maintenance']) == []))
        cases.append(('nothing dropped: nothing taken',
                      pu.removals_this_update_caused(ok, []) == []))
        cases.append(('a removal whose source is still declared: never taken',
                      pu.removals_this_update_caused(
                          ok + " whose source is still declared -- y (from z)",
                          ['precedent-shared-repo-maintenance']) == []))
        cases.append(('the update re-runs the sync with --allow-removals only then',
                      "caused = removals_this_update_caused(out, dropped_sets)" in body
                      and "'--allow-removals'], repo)" in body))
    finally:
        sys.path.pop(0)
    bad = [n for n, ok in cases if not ok]
    check(f'Update Vendors judges retired sets after the catalogue '
          f'({len(cases)} stated cases)', not bad, '; '.join(bad))


def check_promote_commits_carry_a_session_trailer():
    """A commit the Promote tool writes itself -- the rebuild of generated
    files during a composition -- carries a session trailer the trailer
    check accepts: the session's link, or the explicit no-session form.

    WHY. 2026-10-07, a Debut: main carried a commit staging lacked, the
    composition rebuilt the generated files and committed them with no
    trailer, and the full check refused the Promote's own commit."""
    import re as _re
    sys.path.insert(0, str(ROOT / 'tools'))
    import precedent_branches as pb
    cases = []
    trailer = _re.compile(r'^(?:Session|Claude-Session):\s+(\S.*)$', _re.M)
    saved = pb._this_session_id
    try:
        pb._this_session_id = lambda: '01Fixture'
        t1 = pb._session_trailer()
        cases.append(('with a session: its link, which the check accepts',
                      t1.endswith('session_01Fixture') and bool(trailer.search(t1))))
        pb._this_session_id = lambda: ''
        t2 = pb._session_trailer()
        cases.append(('without one: the explicit no-session form',
                      t2 == 'Session: none available (precedent_branches.py)'
                      and bool(trailer.search(t2))))
    finally:
        pb._this_session_id = saved
        sys.path.pop(0)
    import inspect as _inspect
    cases.append(('the rebuild commit uses it',
                  '_session_trailer()' in _inspect.getsource(pb._commit_rebuilt)))
    bad = [n for n, ok in cases if not ok]
    check(f'a commit the Promote tool writes carries a session trailer '
          f'({len(cases)} stated cases)', not bad, '; '.join(bad))


def check_merge_instructions_give_the_full_head():
    """Every "merge it" line a Promote into main prints names the head commit
    in full.

    WHY. 2026-10-06, a session in a consumer: the Promote and the wait
    printed twelve characters of the copy's tip, and GitHub's merge API
    takes the expected head in full, so the session had to look the rest up
    before it could merge."""
    import tempfile
    sys.path.insert(0, str(ROOT / 'tools'))
    import precedent_branches as pb
    sha = 'a' * 40
    cases = [('_at_head carries all 40 characters', sha in pb._at_head(sha)),
             ('...and says nothing without a head', pb._at_head('') == '')]
    saved = (pb.github_tests, pb.github_test_state)
    try:
        pb.github_tests = lambda root, s: [('.github/workflows/x.yml', 'x')]
        pb.github_test_state = lambda root, s, tests, gh=None: ('passed', 'x passed')
        with tempfile.TemporaryDirectory() as td:
            said = []
            rc = pb.wait_for_main_test(td, sha, said.append)
            cases.append(('a PASSED wait names the full head to merge at',
                          rc == 0 and sha in said[-1]))
            said = []
            rc = pb.wait_for_main_test(
                td, sha, said.append,
                copy='claude/2026-10-06-promote-to-main-not-due-abcde')
            cases.append(('...and so does a NOT DUE one', rc == 0 and sha in said[-1]))
    finally:
        pb.github_tests, pb.github_test_state = saved
        sys.path.pop(0)
    src = (ROOT / 'tools' / 'precedent_branches.py').read_text(encoding='utf-8')
    cases.append(('the READY instructions pass the head too',
                  src.count('_at_head(stip)') >= 2))
    bad = [n for n, ok in cases if not ok]
    check(f'a Promote\'s merge instructions name the full head commit '
          f'({len(cases)} stated cases)', not bad, '; '.join(bad))


def check_promote_marks_other_sessions_commits():
    """A Promote's batch list marks each commit that is not this session's
    work: not on the --work branch, and not carrying this session's
    Claude-Session line.

    WHY. 2026-10-06, a Produce in a shared set carried one session's change
    and another session's Update Vendors, listed alike; auto mode held the
    move until the person approved a commit nobody had named to them."""
    import tempfile
    sys.path.insert(0, str(ROOT / 'tools'))
    import precedent_branches as pb
    env = _fixture_git_env()
    cases = []
    try:
        with tempfile.TemporaryDirectory() as td:
            repo = pathlib.Path(td)
            run = lambda *a: subprocess.run(['git', '-C', str(repo), *a], env=env,
                                            capture_output=True, text=True)
            run('init', '-q', '-b', 'main')
            def commit(name, msg):
                (repo / name).write_text(name, encoding='utf-8')
                run('add', name)
                run('commit', '-qm', msg)
                return run('rev-parse', 'HEAD').stdout.strip()
            mine = '\n\nClaude-Session: https://claude.ai/code/session_01Fixture'
            other = '\n\nClaude-Session: https://claude.ai/code/session_01Other'
            base = commit('base', 'base')
            # Another session Books first; this session's branch is cut after,
            # so it carries that commit -- the case the branch test got wrong.
            commit('o', "another session's, Booked before the branch was cut" + other)
            run('switch', '-qc', 'work')
            commit('a', 'mine, on the work branch' + mine)
            run('switch', '-q', 'main')
            run('merge', '-q', '--no-ff', '-m', 'book work', 'work')
            commit('b', 'mine, Booked from another branch' + mine)
            commit('c', "someone else's, no session line")
            batch = pb._new_commits(repo, base, 'main')
            shown, others = pb.mark_other_work(repo, batch, 'work', sid='01Fixture')
            subj = lambda ls: [l.split(' ', 1)[1] for l in ls]
            cases.append(('four commits in the batch', len(batch) == 4))
            cases.append(("another session's commit is marked even though it is "
                          "on this session's branch",
                          "another session's, Booked before the branch was cut"
                          in subj(others)))
            cases.append(('a commit with no session line is marked',
                          "someone else's, no session line" in subj(others)))
            cases.append(("this session's commits are not, on its branch or off it",
                          len(others) == 2
                          and sum(pb.OTHER_WORK_MARK in l for l in shown) == 2))
            cases.append(('the note names how many and asks for them by name',
                          '2 of these' in pb._other_work_note(others, 'work')
                          and pb._other_work_note([], 'work') == ''))
            shown, others = pb.mark_other_work(repo, batch, 'work', sid='')
            cases.append(('with no session ID nothing is marked, and the note says '
                          'the list was not judged',
                          others is None and shown == batch
                          and 'unknown' in pb._other_work_note(others, 'work')))
    finally:
        sys.path.pop(0)
    bad = [n for n, ok in cases if not ok]
    check(f'a Promote marks the commits that are not this session\'s work '
          f'({len(cases)} stated cases)', not bad, '; '.join(bad))


def check_sync_names_files_still_naming_removed_checks():
    """A sync that removes a check script or test names, in the same run,
    every file of the repository's own that still names it -- by path, or by
    the script's name with or without its suffix.

    WHY. 2026-10-06, a consumer: a sync removed four check scripts and their
    tests, and three later rounds of checks each found more files still
    naming them, one commit and one re-run per round."""
    import tempfile
    sys.path.insert(0, str(ROOT / 'tools'))
    import precedent_sync_views as psv
    env = _fixture_git_env()
    cases = []
    try:
        with tempfile.TemporaryDirectory() as td:
            repo = pathlib.Path(td)
            run = lambda *a: subprocess.run(['git', '-C', str(repo), *a], env=env,
                                            capture_output=True, text=True)
            run('init', '-q', '-b', 'main')
            files = {
                'tools/light_check.py': '# runs check_old_rule.py first\n',
                'todo/todo-x.md': 'See [it](../tools/checks/check_old_rule.py).\n',
                'gotchas/g.md': 'Unrelated: check_old_rule_two.py stays.\n',
                'tools/checks/check_other.py': '# check_old_rule\n',
                'notes.md': 'the stem alone: check_old_rule ran\n',
            }
            for rel, text in files.items():
                (repo / rel).parent.mkdir(parents=True, exist_ok=True)
                (repo / rel).write_text(text, encoding='utf-8')
            run('add', '-A')
            run('commit', '-qm', 'x')
            got = psv._mentions_of_removed_files(
                repo, ['tools/checks/check_old_rule.py', 'practices/old-rule.md'])
            named = sorted({g.split(':', 1)[0] for g in got})
            cases.append(('the light check, the open item and the bare name are '
                          'each named, with their line',
                          named == ['notes.md', 'todo/todo-x.md', 'tools/light_check.py']
                          and all(':1 still names' in g for g in got)))
            cases.append(('a longer name that only starts the same is not',
                          'gotchas/g.md' not in named))
            cases.append(('materialized checks are not this repository\'s to fix',
                          'tools/checks/check_other.py' not in named))
            cases.append(('a removed practice is left to the link scan',
                          not any('old-rule.md' in g for g in got)))
    finally:
        sys.path.pop(0)
    bad = [n for n, ok in cases if not ok]
    check(f'a sync names every file still naming a check it removed '
          f'({len(cases)} stated cases)', not bad, '; '.join(bad))


def check_over_target_line_says_whose_load_and_how_to_break_it_down():
    """The over-target line names the file it measured, whose sessions load
    it, and the command that breaks it down entry by entry; the breakdown
    lists each resident entry and occasion group with its source.

    WHY. 2026-10-06, a consumer: every reply gate printed another set's
    session file as over target, which read as this session's own load,
    and with one number to go on the session proposed trimming a practice
    whose line was not in that file."""
    import tempfile
    sys.path.insert(0, str(ROOT / 'tools'))
    import precedent_gate as pg
    import session_load_trend as slt
    cases = []
    try:
        with tempfile.TemporaryDirectory() as td:
            work = pathlib.Path(td) / 'work'
            (work / 'tools').mkdir(parents=True)
            (work / 'tools' / 'session_load_budgets.json').write_text(json.dumps(
                {'surfaces': {'AGENTS.md': {'target': 50}}}), encoding='utf-8')
            (work / 'AGENTS.md').write_text(
                '# A\n\n## Resident block (~1 of 9 token budget)\n\n'
                '**big-rule.** ' + 'word ' * 120 + '\n\n**small-rule.** short.\n\n'
                '## Occasion index\n\n```\nWhen a thing happens:\n'
                '  one-rule — does one thing\n  two-rule — does two\n'
                'When another happens:\n  three-rule — three\n```\n',
                encoding='utf-8')
            got = pg._over_target(work, siblings=False)
            cases.append(('the line names the full path it measured',
                          len(got) == 1 and str(work / 'AGENTS.md') in got[0]))
            cases.append(('...whose sessions load it',
                          len(got) == 1 and 'loaded by this session' in got[0]))
            cases.append(('...and the breakdown command',
                          len(got) == 1 and '--breakdown AGENTS.md' in got[0]))
            rows = slt.breakdown(work, 'AGENTS.md')
            labels = [(k, l) for _n, k, l, _s in rows]
            cases.append(('the breakdown lists each resident entry, largest first',
                          labels[0] == ('resident', 'big-rule')
                          and ('resident', 'small-rule') in labels))
            cases.append(('...and each occasion group with its practices',
                          ('index', 'one-rule, two-rule') in labels
                          and ('index', 'three-rule') in labels))
            cases.append(('...and the parts add up to the file as the cap measures it',
                          sum(r[0] for r in rows) == slt.approx_tokens(
                              (work / 'AGENTS.md').read_text(encoding='utf-8'))))
    finally:
        sys.path.pop(0)
    bad = [n for n, ok in cases if not ok]
    check(f'the over-target line says whose load it is and how to break it '
          f'down ({len(cases)} stated cases)', not bad, '; '.join(bad))


