def check_dedup_onto_same_slug_withdraws_nothing():
    """changed_slugs() leaves out a set's copy deduplicated onto its own slug.

    WHY. 2026-10-06: the ladder set's four full copies of universal rules
    were cut to stubs with `in_force_at:` their own slug, universal's rule of
    that name staying in force. Every link to `prompt-please` and the other
    three, in every declared source, came back as a FOLLOW-UP to repoint --
    72 of them, none real, since the slug still names a live rule."""
    import tempfile
    sys.path.insert(0, str(ROOT / 'tools'))
    ppr = __import__('precedent_practice_refs')
    tmp = pathlib.Path(tempfile.mkdtemp(prefix='dedup-same-slug-'))
    env = dict(os.environ, GIT_AUTHOR_NAME='F', GIT_AUTHOR_EMAIL='f@x',
               GIT_COMMITTER_NAME='F', GIT_COMMITTER_EMAIL='f@x',
               GIT_CONFIG_GLOBAL=os.devnull, PRECEDENT_ALLOW_ANY_AUTHOR='1')
    fm = '---\nslug: {s}\nstatus: {st}\nin_force_at: {to}\n---\n## Rule\nR.\n'
    try:
        g = lambda *a: subprocess.run(['git', '-C', str(tmp), *a], env=env,
                                      check=True, capture_output=True)
        g('init', '-q', '-b', 'main')
        (tmp / 'practices').mkdir()
        for s in ('kept-rule', 'moved-rule'):
            (tmp / 'practices' / f'{s}.md').write_text(
                fm.format(s=s, st='active', to='null'), encoding='utf-8')
        g('add', '-A'); g('commit', '-qm', 'base')
        g('checkout', '-qb', 'work')
        (tmp / 'practices' / 'kept-rule.md').write_text(
            fm.format(s='kept-rule', st='deduplicated', to='kept-rule'), encoding='utf-8')
        (tmp / 'practices' / 'moved-rule.md').write_text(
            fm.format(s='moved-rule', st='deduplicated', to='other-rule'), encoding='utf-8')
        got = ppr.changed_slugs(tmp, 'main')
    finally:
        shutil.rmtree(tmp, ignore_errors=True)
    check('a copy deduplicated onto its own slug is not reported as withdrawn',
          'kept-rule' not in got, repr(got))
    check('CONTROL: a copy deduplicated onto another slug still is',
          got.get('moved-rule') == 'now deduplicated', repr(got))


def check_practice_refs_sorts_live_from_history():
    """precedent_practice_refs.py finds every citation of a renamed practice
    in a SET, marks the live pointers as must-fix, and leaves history alone.

    WHY. The go-merge -> go-update rename (2026-09-26) landed clean in
    BestPractice and left `go-merge` cited in the private sets' practices and
    READMEs; nothing asked anyone to look (practice:
    practice-change-propagates). The lookup has to tell a live pointer from
    the record of the rename, or the check built on it either misses the
    drift or refuses every Story that mentions an old name."""
    import shutil, tempfile
    sys.path.insert(0, str(ROOT / 'tools'))
    import precedent_resolve as _pr
    ppr = __import__('precedent_practice_refs')

    tmp = pathlib.Path(tempfile.mkdtemp(prefix='precedent-refs-'))
    cases = []
    try:
        sources, _consumer, write = _renamed_universal_fixture(tmp)
        ind = tmp / 'ind'
        write(ind / 'practices' / 'lineage.md', 'lineage',
              rule='Say the merge target out loud.')
        lineage = ind / 'practices' / 'lineage.md'
        lineage.write_text(
            lineage.read_text(encoding='utf-8')
            + '\n## Detail\nThe old `go-merge` said the same.\n'
              'Renamed from `go-merge` on 2026-09-26.\n'
              '\n## Story\n[go-merge](go-merge.md) is where it began.\n',
            encoding='utf-8')
        (ind / 'README.md').write_text(
            'Look it up: `python3 tools/precedent_show.py go-merge`.\n',
            encoding='utf-8')
        (ind / 'spec').mkdir()
        (ind / 'spec' / 'plan.md').write_text(
            'Planned against [go-merge](../practices/go-merge.md).\n',
            encoding='utf-8')
        env = dict(os.environ, GIT_AUTHOR_NAME='t', GIT_AUTHOR_EMAIL='t@t',
                   GIT_COMMITTER_NAME='t', GIT_COMMITTER_EMAIL='t@t')
        for argv in (['init', '-q'], ['add', '-A'], ['commit', '-qm', 'x']):
            subprocess.run(['git', '-C', str(ind), *argv], env=env,
                           capture_output=True, text=True)

        res = _pr.resolve(sources)
        wmap = ppr.withdrawn_map(res)
        cases.append(('go-merge is withdrawn, forwarding to go-update',
                      wmap.get('go-merge', {}).get('successor') == 'go-update',
                      str(wmap)))
        succ = {k: v['successor'] for k, v in wmap.items() if v['successor']}
        rows = ppr.scan_root(ind, set(wmap), succ)

        def tag(rel, text):
            # By the line's own words, not its number: the fixture's
            # frontmatter is somebody else's to change.
            hit = [r for r in rows if r[0] == rel and text in r[6]]
            if not hit:
                return 'absent'
            return 'must-fix' if ppr.must_fix(hit[0], wmap) else hit[0][4]

        cases.append(('a link in an active practice\'s Rule is must-fix',
                      tag('practices/cites.md', 'Sibling:') == 'must-fix', str(rows)))
        cases.append(('a precedent_show.py lookup in a README is must-fix',
                      tag('README.md', 'Look it up') == 'must-fix', str(rows)))
        cases.append(('a bare mention in Detail is live but only listed, '
                      'never refused', tag('practices/lineage.md', 'The old') == 'live',
                      str(rows)))
        cases.append(('a line narrating the rename is history',
                      tag('practices/lineage.md', 'Renamed from') == 'history', str(rows)))
        cases.append(('a link inside ## Story is history',
                      tag('practices/lineage.md', 'where it began') == 'history', str(rows)))
        cases.append(('a plan under spec/ is a record, so history',
                      tag('spec/plan.md', 'Planned against') == 'history', str(rows)))
        cases.append(('the individual set\'s own go-merge stub is history',
                      all(r[4] == 'history' for r in rows
                          if r[0] == 'practices/go-merge.md'), str(rows)))

        # NEGATIVE CONTROL: the same lines naming the live slug are not
        # citations of a withdrawn practice at all, so the must-fix findings
        # above were about `go-merge` and nothing else in the fixture.
        for f in (ind / 'README.md', ind / 'practices' / 'cites.md'):
            f.write_text(f.read_text(encoding='utf-8')
                         .replace('go-merge', 'go-update'), encoding='utf-8')
        rows = ppr.scan_root(ind, set(wmap), succ)
        cases.append(('repointed to go-update, nothing is must-fix',
                      not [r for r in rows if ppr.must_fix(r, wmap)],
                      str([r for r in rows if ppr.must_fix(r, wmap)])))
    finally:
        shutil.rmtree(tmp, ignore_errors=True)

    bad = [(c[0], c[2]) for c in cases if not c[1]]
    check(f'the citation lookup finds a renamed practice\'s live pointers and '
          f'leaves its history alone ({len(cases)} stated cases)',
          not bad, '; '.join(f'{n} -- {d[:200]}' for n, d in bad))


def check_practice_change_propagates_refuses():
    """The practice-change-propagates check, run as a repository runs it:
    it refuses a live pointer to a renamed practice and a deleted practice
    file, names the successor, and clears when each is fixed.

    WHY. A lookup nobody runs fixes nothing; the check is what makes the
    drift surface in the repository that can repair it -- a private set this
    session could fetch and not push (practice: practice-change-propagates).
    Asserts the check's own words, and each refusal has a control showing
    the same tree, fixed, passes."""
    import shutil as _shutil, tempfile, json as _json
    cases = []
    with tempfile.TemporaryDirectory() as td:
        tmp = pathlib.Path(td)
        sources, _consumer, write = _renamed_universal_fixture(tmp)
        repo = tmp / 'repo'
        repo.mkdir()
        subprocess.run(
            [sys.executable, str(ROOT / 'tools' / 'precedent_vendor_engine.py'),
             'seed', str(repo), '--kind', 'consumer'],
            capture_output=True, text=True, timeout=300)
        # The seed copies the COMMITTED engine; the code under test is this
        # working tree's (the rename-updates-links fixture found this the hard way).
        for name in ('precedent_check.py', 'precedent_practice_refs.py'):
            _shutil.copy2(ROOT / 'tools' / name, repo / 'tools' / name)
        (repo / 'practices').mkdir(exist_ok=True)
        _shutil.copy2(ROOT / 'practices' / 'practice-change-propagates.md',
                      repo / 'practices' / 'practice-change-propagates.md')
        write(repo / 'practices' / 'old-rule.md', 'old-rule')
        (repo / 'precedent.json').write_text(_json.dumps({
            'format_version': 1, 'visibility': 'private',
            'sources': [{'level': 'universal', 'name': 'precedent',
                         'path': str(tmp / 'uni')}]}), encoding='utf-8')
        (repo / 'README.md').write_text(
            'Before merging, read `python3 tools/precedent_show.py go-merge`.\n',
            encoding='utf-8')
        env = dict(os.environ, PRECEDENT_ALLOW_ANY_AUTHOR='1',
                   PRECEDENT_USER_CONFIG=str(tmp / 'no-user-config.json'),
                   GIT_AUTHOR_NAME='t', GIT_AUTHOR_EMAIL='t@t',
                   GIT_COMMITTER_NAME='t', GIT_COMMITTER_EMAIL='t@t')

        def g(*a):
            return subprocess.run(['git', '-C', str(repo), *a],
                                  capture_output=True, text=True, env=env)
        g('init', '-q', '-b', 'main')
        g('add', '-A'); g('commit', '-qm', 'base')
        g('update-ref', 'refs/remotes/origin/main', 'HEAD')
        g('symbolic-ref', 'refs/remotes/origin/HEAD', 'refs/remotes/origin/main')

        def run():
            r = subprocess.run(
                [sys.executable, 'tools/precedent_check.py',
                 '--only', 'practice-change-propagates'],
                capture_output=True, text=True, cwd=str(repo), env=env,
                timeout=300)
            return r.stdout + r.stderr

        out = run()
        cases.append(('a README lookup of the renamed slug is refused, with '
                      'the successor named',
                      'README.md:1: looks up `go-merge`' in out
                      and 'cite `go-update`' in out, out[-600:]))
        g('rm', '-q', 'practices/old-rule.md'); g('commit', '-qm', 'drop it')
        out = run()
        cases.append(('deleting a practice file is refused',
                      'practices/old-rule.md: this branch deleted a practice '
                      'file. Retire it in place' in out, out[-600:]))

        # CONTROLS: fix each, and the same check passes on the same tree.
        g('revert', '--no-edit', 'HEAD')
        # Another source this repo declares, on disk, still links the
        # practice this branch is about to retire (2026-10-01: a shared
        # set's todo-gate.md linked second-pass-capture after the dedupe).
        shared = tmp / 'shared-set'
        write(shared / 'practices' / 'todo-gate.md', 'todo-gate',
              rule='Then run the [old rule](old-rule.md) pass.')
        subprocess.run(['git', 'init', '-q', '-b', 'main', str(shared)],
                       capture_output=True, env=env)
        subprocess.run(['git', '-C', str(shared), 'add', '-A'],
                       capture_output=True, env=env)
        subprocess.run(['git', '-C', str(shared), 'commit', '-qm', 'set'],
                       capture_output=True, env=env)
        cfg = _json.loads((repo / 'precedent.json').read_text(encoding='utf-8'))
        cfg['sources'].append({'level': 'shared', 'name': 'shared-set',
                               'path': str(shared)})
        (repo / 'precedent.json').write_text(_json.dumps(cfg), encoding='utf-8')
        write(repo / 'practices' / 'old-rule.md', 'old-rule', 'deduplicated',
              'go-update')
        (repo / 'README.md').write_text(
            'Before merging, read `python3 tools/precedent_show.py go-update`.\n',
            encoding='utf-8')
        g('add', '-A'); g('commit', '-qm', 'retire in place, repoint')
        out = run()
        cases.append(('retired in place and repointed, the check passes',
                      '1 passed, 0 violated' in out, out[-2500:]))
        cases.append(('...and the shared set\'s link to the practice this '
                      'branch retired is reported as a follow-up there, '
                      'with the file and line',
                      'FOLLOW-UP in shared-set' in out
                      and 'shared-set:practices/todo-gate.md:1' in out
                      and '`old-rule`' in out, out[-900:]))

    bad = [(c[0], c[2]) for c in cases if not c[1]]
    check(f'practice-change-propagates refuses a live pointer to a renamed '
          f'practice and a deleted practice file, and clears when fixed '
          f'({len(cases)} stated cases)',
          not bad, '; '.join(f'{n} -- {d[:300]}' for n, d in bad))


def check_source_supplied_checks_run():
    """A `checked_by: tools/checks/check_x.py` claim actually RUNS.

    Before precedent_check.register_materialized_checks() existed, nothing
    anywhere invoked those scripts. precedent_materialize.py copied them
    into a consuming repo, precedent_land.py refused to land a team or
    individual practice without one, and spec/PRIVATE_ENFORCEMENT_BRIEF.md
    told a private set how to write one -- and then a consuming repo held
    fourteen real, tested check scripts (nine in precedent-team-repo-maintenance,
    five in precedent-individual, as of 2026-09-06) that no command ever
    ran. The enforced channel was live for the universal catalogue and
    hollow for exactly the sources an adopting team writes for itself.

    Proves all four of the contract's exit statuses, and both routes a
    script reaches a repo by (materialized into tools/checks/, and a
    repo-local source's own local/tools/checks/ read in place)."""
    import shutil, tempfile, importlib.util
    tmp = pathlib.Path(tempfile.mkdtemp(prefix='precedent-srcchecks-'))
    cases = []
    try:
        repo = tmp / 'repo'
        (repo / 'practices').mkdir(parents=True)
        (repo / 'tools' / 'checks').mkdir(parents=True)
        (repo / 'local' / 'tools' / 'checks').mkdir(parents=True)
        shutil.copy(ROOT / 'tools' / 'precedent_check.py', repo / 'tools')
        shutil.copy(ROOT / 'tools' / 'split_practices.py', repo / 'tools')
        shutil.copy(ROOT / 'tools' / 'doc_lint.py', repo / 'tools')
        # fixture-owns-its-state: precedent_check.py imports this at module
        # scope (practice: timestamps-carry-offset), so a fixture engine tree
        # without it does not degrade -- every case here dies on the import.
        shutil.copy(ROOT / 'tools' / 'precedent_time.py', repo / 'tools')
        shutil.copy(ROOT / 'tools' / 'generated_blocks.py', repo / 'tools')
        (repo / 'AGENTS.md').write_text('# fixture\n', encoding='utf-8')
        subprocess.run(['git', 'init', '-q'], cwd=repo, capture_output=True)

        def practice(slug, checked_by):
            (repo / 'practices' / f'{slug}.md').write_text(
                f'---\nslug:        {slug}\ntitle:       {slug}\n'
                f'tier:        on-demand\nseverity:    default\n'
                f'applies_to:  ["**"]\noccasion:    "fixture"\ngates:       []\n'
                f'index_clause: "{slug} — fixture"\n'
                f'checked_by:  "{checked_by}"\ndefines:     []\nstatus:      active\n'
                f'supersedes:  []\noverrides:   null\nadded:       2026-09-06\n'
                f'approved_by: "harness"\nsource_practice_number: null\n---\n'
                f'## Rule\nThe Rule text of {slug}, which the runner must print.\n\n'
                f'## Why\nx\n\n## Story\nx\n\n## Install\nx\n', encoding='utf-8')

        def script(path, body):
            path.write_text('#!/usr/bin/env python3\nimport sys\n' + body,
                            encoding='utf-8')

        practice('fx-clean', 'tools/checks/check_fx_clean.py')
        practice('fx-violated', 'tools/checks/check_fx_violated.py')
        practice('fx-skipped', 'tools/checks/check_fx_skipped.py')
        practice('fx-broken', 'tools/checks/check_fx_broken.py')
        script(repo / 'tools' / 'checks' / 'check_fx_clean.py', 'sys.exit(0)\n')
        script(repo / 'tools' / 'checks' / 'check_fx_violated.py',
               'print("VIOLATION: fx-violated")\nprint("  a planted finding")\n'
               'print("")\nprint("the rule:")\nprint("  a stale copy of the Rule")\n'
               'sys.exit(1)\n')
        script(repo / 'tools' / 'checks' / 'check_fx_skipped.py',
               'print("SKIPPED: fx-skipped: no network here")\nsys.exit(2)\n')
        script(repo / 'tools' / 'checks' / 'check_fx_broken.py',
               'print("boom")\nsys.exit(3)\n')

        # the repo-local route: a source that cannot materialize into itself
        (repo / 'local' / 'practices').mkdir(parents=True)
        (repo / 'local' / 'practices' / 'fx-local.md').write_text(
            (repo / 'practices' / 'fx-clean.md').read_text(encoding='utf-8')
            .replace('fx-clean', 'fx-local')
            .replace('check_fx_clean.py', 'check_fx_local.py'), encoding='utf-8')
        script(repo / 'local' / 'tools' / 'checks' / 'check_fx_local.py',
               'print("VIOLATION: fx-local")\nprint("  the repo-local finding")\n'
               'sys.exit(1)\n')

        def run(slug):
            r = subprocess.run([sys.executable, 'tools/precedent_check.py',
                                '--only', slug], cwd=repo,
                               capture_output=True, text=True)
            return r.returncode, r.stdout + r.stderr

        rc, out = run('fx-clean')
        cases.append(('exit 0 with no output is a PASS', rc == 0 and 'PASS' not in out
                      and 'VIOLATION' not in out, out))
        rc, out = run('fx-violated')
        cases.append(('exit 1 is a VIOLATION carrying the script\'s finding',
                      rc == 1 and 'VIOLATION  fx-violated' in out
                      and 'a planted finding' in out, out))
        cases.append(("the runner prints the practice's own Rule, not the "
                      "script's stale copy of it",
                      'which the runner must print' in out
                      and 'a stale copy of the Rule' not in out, out))
        rc, out = run('fx-skipped')
        cases.append(('exit 2 is SKIPPED with the reason, never a pass',
                      rc == 0 and 'SKIPPED' in out and 'no network here' in out
                      and 'PASS' not in out, out))
        rc, out = run('fx-broken')
        cases.append(("any other exit status is the script's own bug: ERROR, "
                      "which is neither a pass nor a violation",
                      rc == 1 and 'ERROR' in out and 'exited 3' in out
                      and 'VIOLATION' not in out, out))
        rc, out = run('fx-local')
        cases.append(("a repo-local source's own local/tools/checks/ script "
                      "runs in place, for a repo that cannot materialize "
                      "into itself",
                      rc == 1 and 'the repo-local finding' in out, out))

        # A repo-local check that IS also materialized exists twice, and the
        # two copies need different ROOT depths from the same file. Running
        # the local original in place resolves ROOT to <repo>/local, where
        # the repo's real files are not -- two of a real consuming repo's
        # own checks reported `no book-*/ directory exists` and
        # `README.md: file does not exist` about files in plain view
        # (2026-09-06). Alphabetical order was deciding it: `local/...`
        # sorts before `tools/...`, so the wrong copy won every time.
        script(repo / 'local' / 'tools' / 'checks' / 'check_fx_both.py',
               'print("VIOLATION: fx-both")\nprint("  ran the LOCAL copy")\n'
               'sys.exit(1)\n')
        (repo / 'local' / 'practices' / 'fx-both.md').write_text(
            (repo / 'practices' / 'fx-clean.md').read_text(encoding='utf-8')
            .replace('fx-clean', 'fx-both')
            .replace('check_fx_clean.py', 'check_fx_both.py'), encoding='utf-8')
        script(repo / 'tools' / 'checks' / 'check_fx_both.py', 'sys.exit(0)\n')
        rc, out = run('fx-both')
        cases.append(('when a repo-local check has been materialized too, the '
                      'MATERIALIZED copy runs -- the two locations need '
                      'different ROOT depths and only that one is right',
                      rc == 0 and 'ran the LOCAL copy' not in out, out))

        spec = importlib.util.spec_from_file_location(
            '_pc_fx', repo / 'tools' / 'precedent_check.py')
        pc = importlib.util.module_from_spec(spec)
        spec.loader.exec_module(pc)
        before = set(pc.CHECKS)
        pc.register_materialized_checks()
        added = set(pc.CHECKS) - before
        cases.append(('the slug comes from the practice that CLAIMS the '
                      'script, not from the filename',
                      {'fx-clean', 'fx-violated', 'fx-skipped', 'fx-broken',
                       'fx-local', 'fx-both'} <= added, str(sorted(added))))
    finally:
        shutil.rmtree(tmp, ignore_errors=True)

    bad = [(c[0], c[2]) for c in cases if not c[1]]
    check(f'source-supplied checks actually run ({len(cases)} stated cases: '
          f'all four exit statuses, both routes into a repo, and the slug '
          f'taken from the claiming practice)',
          not bad, '; '.join(f"{n} -- {d[:800]}" for n, d in bad))


def check_todo_progress_discriminates():
    """The open-item pass reports a resemblance and stays quiet otherwise
    (practice: control-asserts-which-failure).

    THE MEASUREMENT THAT SHAPED IT. On its first run against this repository
    the candidate list returned 13 of 83 items for one ordinary day's work,
    because AGENTS.md is cited by more than a third of the open items and
    touched by nearly every change. A list like that is read once. Suppressing
    paths cited across the whole file took it to 5, every one plausible.

    So the discriminating cases here are the QUIET ones: a change touching
    only a widely-cited file must report nothing, and a change touching
    nothing an item names must report nothing. A tool that always finds
    something is a tool nobody reads. The fixture owns its own tree."""
    import tempfile
    sys.path.insert(0, str(ROOT / 'tools'))
    import todo_progress as tp

    TODO = (
        '# TODO\n\n'
        '1. <a id="alpha"></a>**An item about the widget.** It names\n'
        '   [tools/widget.py](tools/widget.py) and also [AGENTS.md](AGENTS.md).\n'
        '   **Disposition:** wait\n\n'
        '2. <a id="beta"></a>**An item about the gadget.** It names\n'
        '   `tools/gadget.py` in a code span, and [AGENTS.md](AGENTS.md).\n'
        '   **Remind:** whether the gadget survives (2026-09-13, Morgan)\n'
        '   **Disposition:** ask (2026-09-13, Morgan)\n\n'
        '3. <a id="gamma"></a>**~~A finished item.~~** **DONE 2026-09-13.** It\n'
        '   names [tools/widget.py](tools/widget.py) too.\n\n'
        '4. <a id="delta"></a>**An item naming the common file and the\n'
        '   widget.** [AGENTS.md](AGENTS.md) and\n'
        '   [tools/widget.py](tools/widget.py) -- so widget.py is cited by TWO\n'
        '   live items and gadget.py by one, which is the only reason the\n'
        '   ordering case below has anything to order.\n'
        '   **Disposition:** wait\n')

    ignore = tp.common_paths(TODO)
    cases = []

    cases.append(('a file most items name is suppressed, so it cannot be the '
                  'thing that matches', 'AGENTS.md' in ignore, repr(ignore)))
    cases.append(('and a file only one item names is not suppressed',
                  'tools/widget.py' not in ignore, repr(ignore)))

    got = tp.candidates(TODO, {'tools/widget.py'}, ignore)
    cases.append(('a change touching a named file reports every LIVE item '
                  'naming it',
                  sorted(c[1] for c in got) == ['alpha', 'delta'], repr(got)))
    cases.append(('and a DONE item naming the same file is not reported',
                  'gamma' not in [c[1] for c in got], repr(got)))

    got = tp.candidates(TODO, {'tools/gadget.py'}, ignore)
    cases.append(('a path named in a code span counts, not only a link',
                  [c[1] for c in got] == ['beta'], repr(got)))

    got = tp.candidates(TODO, {'AGENTS.md'}, ignore)
    cases.append(('THE QUIET CASE: a change touching only the widely-cited '
                  'file reports NOTHING', got == [], repr(got)))

    got = tp.candidates(TODO, {'tools/unrelated.py'}, ignore)
    cases.append(('and a change touching nothing any item names reports '
                  'nothing', got == [], repr(got)))

    rem = tp.reminders(TODO)
    cases.append(('a **Remind:** item is surfaced with what to remind about',
                  len(rem) == 1 and rem[0][1] == 'beta'
                  and 'survives' in rem[0][2], repr(rem)))

    # ORDERING. A hit on a file few items cite says more about that item than
    # a hit on one half the queue mentions in passing. Measured: the broad
    # merge that landed this tool produced 13 candidates across eight files
    # with none dominating -- not wrong, and still more than anybody reads.
    # `gadget.py` is cited once here, `widget.py` twice, so the gadget item
    # must sort first whatever order the file lists them in.
    got = tp.candidates(TODO, {'tools/widget.py', 'tools/gadget.py'}, ignore)
    cases.append(('THE ORDERING CASE: the item matched on the rarer path '
                  'sorts first, so a truncated list keeps the strongest hits',
                  [c[1] for c in got][0] == 'beta'
                  and sorted(c[1] for c in got) == ['alpha', 'beta', 'delta'],
                  repr(got)))

    bad = [(c[0], c[2]) for c in cases if not c[1]]
    check(f'the open-item pass matches what an item names and stays quiet '
          f'otherwise ({len(cases)} stated cases, the two quiet ones being '
          f'the discriminating pair)',
          not bad, '; '.join(f"{n} -- {d[:300]}" for n, d in bad))


def check_split_projection_is_costed_and_ordered():
    """A flagged section made of entries gets the costed split table
    (practice: control-asserts-which-failure).

    WHY. Told a section is 9,000 tokens and that splitting is an option, a
    person still cannot choose -- the question is always "what would that
    leave, and what would it cost me". On 2026-09-13 those figures existed
    only because a session was asked to compute them; the deep read that
    flagged the section could have handed them over and did not.

    The discriminating case is a section with no entries to split: a
    projection there would be inventing a saving nobody can take
    (no-invented-specifics). The fixture owns its own tree."""
    import tempfile
    sys.path.insert(0, str(ROOT / 'tools'))
    import very_deep_check as vdc

    entry = ('- **A trap that bites.** It failed on a Tuesday and cost an '
             'hour. The remedy is to read the exit code. A third sentence '
             'carries the reason. A fourth carries the caveat.\n')
    section = ('## Gotchas\n\n' + entry * 12)
    proj = vdc._split_projection(section)

    cases = []
    cases.append(('a section of 12 entries is costed at all', bool(proj), proj))
    cases.append(('it names all four rows, cheapest first',
                  'bolded lead only' in proj and 'lead + 1 sentence' in proj
                  and 'lead + 2 sentences' in proj and 'lead + 3 sentences' in proj,
                  proj))

    import re as _re
    saves = [int(x.replace(',', ''))
             for x in _re.findall(r'saves\s+([\d,]+)', proj)]
    cases.append(('THE ORDERING CASE: keeping more text saves less, strictly '
                  '-- a table that did not would be arithmetic nobody can act on',
                  len(saves) == 4 and all(saves[i] > saves[i + 1] for i in range(3)),
                  repr(saves)))
    cases.append(('it says the figures bound the saving rather than predicting it',
                  'bounds the saving' in proj, proj))
    cases.append(('and that the text moves out whole either way',
                  'moves out whole' in proj, proj))

    cases.append(('THE DISCRIMINATING CASE: a section with no entries to split '
                  'is not costed at all',
                  vdc._split_projection('## Prose\n\nJust paragraphs here.\n') == '',
                  repr(vdc._split_projection('## Prose\n\nJust paragraphs.\n'))))
    cases.append(('and neither is a section with too few entries to be worth it',
                  vdc._split_projection('## Gotchas\n\n' + entry * 3) == '',
                  repr(vdc._split_projection('## Gotchas\n\n' + entry * 3))))

    bad = [(c[0], c[2]) for c in cases if not c[1]]
    check(f'the split projection is costed, ordered, and absent where there is '
          f'nothing to split ({len(cases)} stated cases)',
          not bad, '; '.join(f"{n} -- {d[:300]}" for n, d in bad))


def check_duplicated_resident_text_detector():
    """Text an always-loaded file repeats from the catalogue is found, and the
    generated block is not mistaken for it
    (practice: control-asserts-which-failure).

    WHY IT EXISTS. "Delete what is duplicated" is the first and cheapest of
    session-load-budget's three reduction moves -- the text is provably
    reachable on demand, so cutting it costs a session nothing -- and it is the
    one nobody can find without reading everything. Two hand passes over this
    repo's instructions file found 903 tokens of it; nothing mechanical was
    looking.

    THE CASE THAT MAKES IT A CONTROL rather than a demo is the generated
    block: it is a copy of practice text ON PURPOSE. A detector that reported
    it would be reporting the loader working, would fire on every repo that
    ever ran build_views.py, and would be switched off within a week -- and
    then nothing would be looking again. The fixture owns its own tree
    (fixture-owns-its-state)."""
    import tempfile
    sys.path.insert(0, str(ROOT / 'tools'))
    import precedent_check as pc

    SENTENCE = ('A session that hits this trap pays for it twice over, once '
                'in the hour it loses and once in the confident wrong answer '
                'it carries forward into everything after it.')
    PRACTICE = ('---\nslug: fixture-rule\n---\n## Rule\n' + SENTENCE +
                '\n\n## Story\nIt happened on a Tuesday.\n')

    def run(agents_body):
        d = pathlib.Path(tempfile.mkdtemp())
        try:
            (d / 'practices').mkdir()
            (d / 'practices' / 'fixture-rule.md').write_text(
                PRACTICE, encoding='utf-8')
            return pc.duplicated_resident_text(d, agents_body)
        finally:
            shutil.rmtree(d, ignore_errors=True)

    cases = []

    hits = run('# notes\n\nSome preamble.\n\n' + SENTENCE + '\n')
    cases.append(('text repeated from a practice file is reported, naming that '
                  'file',
                  len(hits) == 1 and hits[0][0] == 'practices/fixture-rule.md',
                  repr(hits)))

    hits = run('# notes\n\n' + SENTENCE.replace('trap', '`trap`').replace(
        'hour', '**hour**') + '\n')
    cases.append(('markup does not hide it -- backticks and bolding are '
                  'normalized away', len(hits) == 1, repr(hits)))

    generated = ('# notes\n\n<!-- BEGIN GENERATED: precedent-loader -->\n'
                 + SENTENCE + '\n<!-- END GENERATED -->\n')
    hits = run(generated)
    cases.append(('THE DISCRIMINATING CASE: the same sentence inside the '
                  'GENERATED block raises nothing -- that copy is the loader '
                  'working', hits == [], repr(hits)))

    hits = run('# notes\n\nA session that hits this trap pays for it twice '
               'over, and then we did something else entirely.\n')
    cases.append(('a short coincidental overlap is below the run threshold and '
                  'is not reported', hits == [], repr(hits)))

    hits = run('# notes\n\nNothing here resembles the practice at all.\n')
    cases.append(('unrelated prose raises nothing', hits == [], repr(hits)))

    bad = [(c[0], c[2]) for c in cases if not c[1]]
    check(f'duplicated always-loaded text is detected, and the generated block '
          f'is not ({len(cases)} stated cases, the generated block being the '
          f'discriminating one)',
          not bad, '; '.join(f"{n} -- {d[:400]}" for n, d in bad))


def check_settled_marker_scan_is_scoped_and_follows_the_split():
    """The SESSION LOAD pass's settled-trap signal reads gotcha entries, and
    only gotcha entries (practice: control-asserts-which-failure).

    THE INCIDENT (2026-09-13), and it failed in both directions in one commit.
    The scan walked every markdown bullet in the instructions file, which was
    harmless only while the gotchas were the file's one bulleted list. A
    reduction pass turned the standing commands into bullets, so the last of
    them swallowed 8,582 tokens of unrelated sections and reported it as one
    entry whose trap was settled. The SAME pass then split the gotchas into an
    index plus a record, and the bodies this signal reads left the file -- so
    it dropped from two real findings to zero. **Zero findings is what a clean
    section looks like**, which is why this needs a control rather than a
    reading: nothing about the output said it had stopped working.

    The fixture owns its own tree (fixture-owns-its-state)."""
    import tempfile
    sys.path.insert(0, str(ROOT / 'tools'))
    import very_deep_check as vdc

    STORY = ('It failed on 2026-09-13 and cost an hour. That is fixed now in '
             'the tree, so the entry may be archivable.\n')
    LIVE = ('It failed on 2026-09-13 and cost an hour. Nothing has changed '
            'since, and it still bites every session.\n')

    def run(agents, record=None):
        d = pathlib.Path(tempfile.mkdtemp())
        try:
            (d / 'AGENTS.md').write_text(agents, encoding='utf-8')
            if record is not None:
                (d / 'record').mkdir()
                (d / 'record' / 'GOTCHAS.md').write_text(record, encoding='utf-8')
            _rows, msgs = vdc._session_load(d)
            return '\n'.join(m for m in msgs if m.startswith('note'))
        finally:
            shutil.rmtree(d, ignore_errors=True)

    PREAMBLE = ('# fixture\n\n- **"Update Vendors"** a standing command, not a '
                'gotcha. It is fixed now.\n\n')
    SPLIT = (PREAMBLE + '## Build-environment gotchas -- do NOT rediscover '
             'these\n\n'
             '- **A settled trap.** [story](record/GOTCHAS.md#g1)\n\n'
             '- **A live trap.** [story](record/GOTCHAS.md#g2)\n\n'
             '## Working in this repo\n\n- **A convention.** It is fixed now.\n')
    RECORD = ('# Gotchas\n\n## 1. <a id="g1"></a>Settled\n\n' + STORY +
              '\n## 2. <a id="g2"></a>Live\n\n' + LIVE)

    cases = []
    out = run(SPLIT, RECORD)
    cases.append(('THE REGRESSION CASE: a settled marker in the RECORD is '
                  'found, not lost with the bodies',
                  'Settled' not in out and 'A settled trap' in out, out))
    cases.append(('and the live entry beside it is not reported',
                  'A live trap' not in out, out))
    cases.append(('a bullet OUTSIDE the gotchas section is not parsed as an '
                  'entry -- the 8,582-token false positive',
                  'Update Vendors' not in out and 'A convention' not in out,
                  out))

    unsplit = (PREAMBLE + '## Build-environment gotchas -- do NOT rediscover '
               'these\n\n- **A settled trap.** ' + STORY +
               '\n- **A live trap.** ' + LIVE +
               '\n## Working in this repo\n\n- **A convention.** It is fixed now.\n')
    out = run(unsplit)
    cases.append(('an UNSPLIT section still reports its own settled entry',
                  'A settled trap' in out and 'A live trap' not in out
                  and 'Update Vendors' not in out, out))

    no_section = ('# fixture\n\n- **A bullet.** It is fixed now.\n\n## Other\n')
    out = run(no_section)
    cases.append(('THE DISCRIMINATING CASE: a file with no gotchas section '
                  'raises nothing at all', out == '', out))

    bad = [(c[0], c[2]) for c in cases if not c[1]]
    check(f'the settled-trap signal is scoped to gotcha entries and follows a '
          f'split ({len(cases)} stated cases, both directions of the '
          f'2026-09-13 regression covered)',
          not bad, '; '.join(f"{n} -- {d[:400]}" for n, d in bad))


def check_session_load_reports_a_file_over_its_own_declared_ceiling():
    """The SESSION LOAD pass compares each FILE to the ceiling its own repo
    declared, and not only each SECTION to the review threshold
    (practice: control-asserts-which-failure).

    THE INCIDENT (2026-09-22). Three mechanisms each looked like they covered
    this and none did. The pass measured `## ` sections against
    `section_review_tokens` and never opened
    `tools/session_load_budgets.json`; `precedent_check.py`'s
    session-load-budget check did exactly the right comparison and SKIPPED in
    any repo without `practices/session-load-budget.md`; and
    `session_load_trend.py` reported it correctly and only when asked. So
    precedent-individual's AGENTS.md sat at 2,276 tokens against a declared
    1,800 -- 29% over -- with every check green.

    THE DISCRIMINATING CASE is the first one below, and it is what makes this
    a control rather than a demonstration: the overage SPREAD THIN. The real
    file's largest section was 990 tokens against a 2,500 threshold, so the
    section signal was not merely quiet, it was correct -- there was nothing
    section-sized to report. A fixture whose overage sits in one fat section
    would pass on the old code too, and prove nothing.

    The fixture owns its own tree (fixture-owns-its-state)."""
    import tempfile
    sys.path.insert(0, str(ROOT / 'tools'))
    import very_deep_check as vdc
    import build_views as bv

    PARA = ('Some ordinary instructions prose that a session reads before it '
            'does any work at all, and which nobody would call remarkable. ')

    def repo(sections, para_repeats, ceiling, registry=True):
        d = pathlib.Path(tempfile.mkdtemp())
        body = PARA * para_repeats
        (d / 'AGENTS.md').write_text(
            '# fixture\n\n' + ''.join(f'## Section {i}\n\n{body}\n\n'
                                     for i in range(1, sections + 1)),
            encoding='utf-8')
        if registry:
            (d / 'tools').mkdir()
            (d / 'tools' / 'session_load_budgets.json').write_text(
                json.dumps({'surfaces': {'AGENTS.md': {'ceiling': ceiling}}}),
                encoding='utf-8')
        return d

    def run(d):
        try:
            rows, msgs = vdc._session_load(d)
            return (sum(n for _, _, n in rows),
                    max([n for _, _, n in rows] or [0]),
                    [m for m in msgs if m.startswith('OVER CEILING')])
        finally:
            shutil.rmtree(d, ignore_errors=True)

    cases = []

    total, largest, hits = run(repo(5, 40, 1800))
    cases.append((
        'THE DISCRIMINATING CASE: a file over its ceiling with the overage '
        'spread across sections, none of them section-sized, is reported',
        hits and largest < vdc._SECTION_FLAG_TOKENS and total > 1800,
        f'total={total} largest={largest} flag={vdc._SECTION_FLAG_TOKENS} '
        f'hits={hits!r}'))
    cases.append(('and the finding names the measurement, the ceiling and the '
                  'registry it came from',
                  hits and 'AGENTS.md' in hits[0]
                  and f'{total:,}' in hits[0] and '1,800' in hits[0]
                  and 'session_load_budgets.json' in hits[0], repr(hits)))
    cases.append(('and it says the remedy is the reduction pass, never a '
                  'raise -- session-load-budget\'s own line',
                  hits and 'NEVER raise the ceiling' in hits[0]
                  and 'reduction-pass' in hits[0], repr(hits)))

    total, _largest, hits = run(repo(5, 40, 20000))
    cases.append(('a file INSIDE its declared ceiling raises nothing, however '
                  'many sections it has', hits == [],
                  f'total={total} hits={hits!r}'))

    # A TARGET below the ceiling (practice: very-deep-check, Morgan
    # 2026-10-01): over it asks for a reduction pass, under it says nothing.
    def targeted(target):
        d = repo(5, 40, 20000)
        (d / 'tools' / 'session_load_budgets.json').write_text(
            json.dumps({'surfaces': {'AGENTS.md': {'ceiling': 20000,
                                                   'target': target}}}),
            encoding='utf-8')
        try:
            _rows, msgs = vdc._session_load(d)
            return [m for m in msgs if m.startswith('OVER TARGET')]
        finally:
            shutil.rmtree(d, ignore_errors=True)
    hits = targeted(1800)
    cases.append(('a file inside its ceiling but over its declared TARGET is '
                  'reported, and the finding asks for the practice-by-practice '
                  'review', hits and 'practice-by-practice' in hits[0]
                  and '1,800' in hits[0], repr(hits)))
    hits = targeted(20000)
    cases.append(('a file under its target raises no target finding',
                  hits == [], repr(hits)))

    total, _largest, hits = run(repo(5, 40, 1800, registry=False))
    cases.append(('a repo that declares NO ceiling is not tested against an '
                  'invented one', hits == [], f'total={total} hits={hits!r}'))

    # The ceiling signal must not have swallowed the section signal it was
    # added beside: both questions, both answers, in the same run.
    d = repo(1, 900, 20000)
    total, largest, hits = None, None, None
    try:
        rows, msgs = vdc._session_load(d)
        largest = max(n for _, _, n in rows)
        section_hits = [m for m in msgs if m.startswith('REVIEW')]
    finally:
        shutil.rmtree(d, ignore_errors=True)
    cases.append(('the section signal it was added ALONGSIDE still fires on a '
                  'fat section inside its ceiling',
                  largest >= vdc._SECTION_FLAG_TOKENS and section_hits != [],
                  f'largest={largest} hits={section_hits!r}'))

    bad = [(c[0], c[2]) for c in cases if not c[1]]
    check(f'a file over the ceiling its own repo declared is reported by the '
          f'SESSION LOAD pass ({len(cases)} stated cases, the spread-thin '
          f'overage being the discriminating one)',
          not bad, '; '.join(f"{n} -- {d[:400]}" for n, d in bad))


def check_refresh_judges_workflows_once_the_engine_is_whole():
    """An engine release that adds a module took two Update Vendors runs to
    finish (2026-09-30, a consumer updating from 99941178): the second pass
    of the self-replacing refresh judged workflow approvals at its top, by
    importing a precedent_check.py the first pass had already replaced,
    before it wrote the generated_blocks.py that file now imports. So the
    first run ended "no approval could be judged ... did not import", with
    the reason hidden. Discriminating cases, on a planted engine directory:
    during refresh's opening sweep a failed import is deferred, not left
    for the person; once the engine is whole the deferred judgment runs and
    removes an unapproved workflow; and outside refresh the failure is
    still left for the person, now naming the exception."""
    import contextlib, io, shutil, subprocess, tempfile
    sys.path.insert(0, str(ROOT / 'tools'))
    import precedent_vendor_engine as pve
    tmp = pathlib.Path(tempfile.mkdtemp(prefix='wf-judge-'))
    saved_dir, saved_mod = pve.ENGINE_DIR, sys.modules.pop('precedent_check', None)
    cases = []
    try:
        eng, dest = tmp / 'eng', tmp / 'dest'
        eng.mkdir()
        (dest / '.github' / 'workflows').mkdir(parents=True)
        git = lambda *a: subprocess.run(['git', '-C', str(dest), *a],
                                        capture_output=True, text=True)
        git('init', '-q')
        git('config', 'user.name', 'Test')
        git('config', 'user.email', 'test@example.com')
        wf = dest / '.github' / 'workflows' / 'extra.yml'
        wf.write_text('on: push\njobs: {}\n', encoding='utf-8')
        (dest / 'precedent.json').write_text('{}\n', encoding='utf-8')
        git('add', '-A')
        git('commit', '-q', '-m', 'seed\n\nSession: none available (test)')
        (eng / 'precedent_check.py').write_text(
            'import generated_blocks_not_written_yet\n', encoding='utf-8')
        pve.ENGINE_DIR = eng
        pve._LEFT_FOR_YOU.clear()
        pve._DEFER_WORKFLOW_JUDGMENT = True
        with contextlib.redirect_stdout(io.StringIO()):
            pve._remove_unapproved_workflows(dest, {}, 'consumer', None)
        pve._DEFER_WORKFLOW_JUDGMENT = False
        cases.append(('in refresh\'s opening sweep, a failed import is '
                      'deferred, not left for the person',
                      len(pve._DEFERRED_WORKFLOW_JUDGMENT) == 1
                      and not pve._LEFT_FOR_YOU, repr(pve._LEFT_FOR_YOU)))
        (eng / 'precedent_check.py').write_text(
            'def _approval_problem(entry):\n    return "fixture"\n',
            encoding='utf-8')
        with contextlib.redirect_stdout(io.StringIO()):
            pve._judge_deferred_workflows()
        cases.append(('once the engine is whole, the deferred judgment runs '
                      'and the unapproved workflow goes', not wf.exists(),
                      repr(pve._LEFT_FOR_YOU)))
        git('checkout', '-q', 'HEAD', '--', '.github/workflows/extra.yml')
        git('reset', '-q', '--hard')
        (eng / 'precedent_check.py').write_text(
            'import generated_blocks_not_written_yet\n', encoding='utf-8')
        sys.modules.pop('precedent_check', None)
        pve._LEFT_FOR_YOU.clear()
        with contextlib.redirect_stdout(io.StringIO()):
            pve._remove_unapproved_workflows(dest, {}, 'consumer', None)
        said = ' '.join(str(x) for x in pve._LEFT_FOR_YOU)
        cases.append(('outside refresh the failure is still left for the '
                      'person, naming the exception',
                      'generated_blocks_not_written_yet' in said, said[:300]))
    finally:
        pve.ENGINE_DIR = saved_dir
        pve._DEFER_WORKFLOW_JUDGMENT = False
        pve._DEFERRED_WORKFLOW_JUDGMENT.clear()
        pve._LEFT_FOR_YOU.clear()
        sys.modules.pop('precedent_check', None)
        if saved_mod is not None:
            sys.modules['precedent_check'] = saved_mod
        shutil.rmtree(tmp, ignore_errors=True)
    bad = [(c[0], c[2]) for c in cases if not c[1]]
    check(f'a refresh judges workflows once the engine is whole '
          f'({len(cases)} stated cases)',
          not bad, '; '.join(f"{n} -- {d[:300]}" for n, d in bad))


def check_push_check_skips_a_set_check_older_than_push_time_judging():
    """A check a practice SET ships reaches a repository on the set's own
    schedule, not the engine's (practice: vendor-rollout-disclosed, question
    3; Morgan, 2026-09-29). The push check runs the session-trailer check at
    every push since that day; an older copy of it reads the whole history,
    so run at every push it would refuse over any old commit on main -- the
    very failure the new copy removed. Discriminating cases: an old copy is
    not run at push time and does not fail the push; a new copy that finds
    something still refuses."""
    import contextlib, io, shutil, tempfile
    sys.path.insert(0, str(ROOT / 'tools'))
    import precedent_push_check as ppc
    tmp = pathlib.Path(tempfile.mkdtemp(prefix='push-time-'))
    cases = []
    try:
        (tmp / 'tools' / 'checks').mkdir(parents=True)
        script = tmp / 'tools' / 'checks' / 'check_session_trailer.py'
        body = ('import sys\nprint("VIOLATION: session-trailer")\n'
                'print("  commit 0123456789ab: no trailer")\nsys.exit(1)\n')
        checks = [('session_trailer',
                   [sys.executable, 'tools/checks/check_session_trailer.py'], 'x')]
        script.write_text(body, encoding='utf-8')
        with contextlib.redirect_stdout(io.StringIO()):
            failed, _m, _t, _f = ppc.run(tmp, checks)
        cases.append(('an old copy is not run at push time', not failed,
                      repr(failed)))
        script.write_text('# --all-history\n' + body, encoding='utf-8')
        with contextlib.redirect_stdout(io.StringIO()):
            failed, _m, _t, _f = ppc.run(tmp, checks)
        cases.append(('a new copy that finds something still refuses',
                      failed == ['session_trailer'], repr(failed)))
        # precedent_update.py's stand-in commit: its message is the tool's,
        # so the commit-judging checks stand aside there.
        os.environ[ppc.STANDIN_COMMIT_ENV] = '1'
        try:
            with contextlib.redirect_stdout(io.StringIO()):
                failed, _m, _t, _f = ppc.run(tmp, checks)
        finally:
            os.environ.pop(ppc.STANDIN_COMMIT_ENV, None)
        cases.append(('under the update\'s stand-in commit, the trailer check '
                      'stands aside', not failed, repr(failed)))
        # ...and when an update's check is red, its report shows the finding
        # even when routine notices were printed after it.
        import precedent_update as pu
        red = '\n'.join(['      | VIOLATION: session-trailer',
                         '      |   commit 0123abcd: no trailer'] +
                        ['      build_views: y is status: retired'] * 40)
        shown = pu.tail(red)
        cases.append(('a red update report shows the finding, not the last '
                      'notices', 'commit 0123abcd' in shown, shown[-300:]))
        # ...and every finding, never the first 22 then "..." (2026-09-30: a
        # consumer's update ended FAILED three times running, each showing a
        # few more stranded files than the last).
        many = '\n'.join(['      | VIOLATION: rename-updates-links'] +
                         [f'      |     doc{i}.md:3: still references x'
                          for i in range(60)] + ['      notice'] * 40)
        shown = pu.tail(many, repo=tmp)
        saved = tmp / pu.FULL_OUTPUT_NAME
        cases.append(('...every finding of it, not the first few',
                      all(f'doc{i}.md:3' in shown for i in range(60)),
                      shown[-300:]))
        cases.append(('...and the whole output is saved, and named',
                      saved.is_file() and saved.read_text() == many
                      and pu.FULL_OUTPUT_NAME in shown, shown[-200:]))
        # ...and the stand-in itself carries a Session: trailer, because the
        # session-trailer check also runs inside precedent_check.py and in
        # the set's own test, which judge the commit and not the variable
        # above (2026-09-30, a consumer's update ended FAILED on it).
        import subprocess
        repo = tmp / 'standin-repo'
        repo.mkdir()
        git = lambda *a: subprocess.run(['git', '-C', str(repo), *a],
                                        capture_output=True, text=True)
        git('init', '-q')
        git('config', 'user.name', 'Test')
        git('config', 'user.email', 'test@example.com')
        (repo / 'a.txt').write_text('one\n', encoding='utf-8')
        git('add', 'a.txt')
        git('commit', '-q', '-m', 'first\n\nSession: none available (test)')
        before = git('rev-parse', 'HEAD').stdout.strip()
        (repo / 'a.txt').write_text('two\n', encoding='utf-8')
        git('add', 'a.txt')
        judge = [sys.executable, '-c',
                 'import re, subprocess, sys\n'
                 'b = subprocess.run(["git", "log", "-1", "--format=%B"], '
                 'capture_output=True, text=True).stdout\n'
                 'print(b)\n'
                 'sys.exit(0 if re.search(r"^(?:Session|Claude-Session):'
                 '\\s+(\\S.*)$", b, re.M) else 1)\n']
        saved = os.environ.pop('PRECEDENT_SESSION_URL', None)
        try:
            rc, out = pu.judged_as_committed(repo, judge)
            cases.append(('the stand-in commit carries a Session: trailer',
                          rc == 0 and pu.TEMP_COMMIT_MESSAGE in out, out[-300:]))
            os.environ['PRECEDENT_SESSION_URL'] = 'https://example.test/s/1'
            rc, out = pu.judged_as_committed(repo, judge)
            cases.append(('a session that hands over its link gets it on the '
                          'stand-in', 'Session: https://example.test/s/1' in out,
                          out[-300:]))
        finally:
            os.environ.pop('PRECEDENT_SESSION_URL', None)
            if saved is not None:
                os.environ['PRECEDENT_SESSION_URL'] = saved
        cases.append(('the stand-in is undone and the change stays staged',
                      git('rev-parse', 'HEAD').stdout.strip() == before and
                      git('diff', '--cached', '--name-only').stdout.strip()
                      == 'a.txt', git('log', '--oneline').stdout))
    finally:
        shutil.rmtree(tmp, ignore_errors=True)
    bad = [(c[0], c[2]) for c in cases if not c[1]]
    check(f'the push check skips a set check older than push-time judging '
          f'({len(cases)} stated cases)',
          not bad, '; '.join(f"{n} -- {d}" for n, d in bad))


def check_universal_occasion_share_is_capped():
    """Every source declares its share of a consumer's occasion index, and a
    consumer's cap is the sum of what its sources declare (Morgan,
    2026-09-29: the universal share, strength: assented; a share per set and
    the summed cap, strength: decided). Discriminating cases: this
    repository's real share fits its own declared allowance; the same build
    refuses with the allowance set below the share; a consumer whose sources
    all declare one is capped at their sum plus the repo-local allowance;
    and one whose source declares none falls back to the single literal."""
    import contextlib
    import io
    import json as _json
    import tempfile
    sys.path.insert(0, str(ROOT / 'tools'))
    import build_views as bv
    cases = []
    share = bv.occasion_share(bv.load_practices(announce=False))
    allowed = bv.own_occasion_allowance(ROOT)
    cases.append((f'the real share (~{share}) fits the declared allowance ({allowed})',
                  allowed is not None and 0 < share <= allowed,
                  f'share {share}, allowance {allowed}'))
    # Over its allowance, --check warns and --budgets refuses: a size cap
    # warns on the way into pre-staging and refuses at the full check
    # (Morgan, 2026-09-30, strength: decided).
    real, argv, strict = bv.own_occasion_allowance, sys.argv, bv.STRICT_BUDGETS
    bv.own_occasion_allowance = lambda root: 10
    for flag in ('--check', '--budgets'):
        sys.argv = ['build_views.py', flag]
        err = io.StringIO()
        try:
            with contextlib.redirect_stdout(io.StringIO()), \
                    contextlib.redirect_stderr(err):
                bv.main()
            refused, why = False, f'build_views {flag} returned'
        except SystemExit as e:
            refused = "source's share" in str(e.code)
            why = str(e.code)[:300]
        finally:
            bv.own_occasion_allowance, sys.argv = real, argv
            bv.STRICT_BUDGETS = strict
            bv.own_occasion_allowance = lambda root: 10
        if flag == '--check':
            cases.append(('a share over its allowance warns at --check, and '
                          'does not refuse', not refused
                          and "source's share" in err.getvalue(),
                          why + ' | ' + err.getvalue()[-300:]))
        else:
            cases.append(('...and --budgets, the full check\'s, refuses it',
                          refused, why))
    bv.own_occasion_allowance = real
    d = pathlib.Path(tempfile.mkdtemp())
    try:
        for name, level, share_ in (('uni', 'universal', 2000),
                                    ('shr', 'shared', 300)):
            (d / name).mkdir()
            (d / name / 'practices').mkdir()
            man = {'name': 'precedent' if level == 'universal' else name,
                   'level': level}
            if share_:
                man['occasion_share_tokens'] = share_
            (d / name / 'precedent-source.json').write_text(
                _json.dumps(man), encoding='utf-8')
        # The declared sources are passed in, not resolved: a resolve here
        # would also pick up whatever individual source this machine's own
        # user config declares, and the sum would depend on the machine.
        srcs = [{'level': 'universal', 'name': 'precedent', 'path': str(d / 'uni')},
                {'level': 'shared', 'name': 'shr', 'path': str(d / 'shr')},
                {'level': 'repo-local', 'name': 'local', 'path': str(d / 'local')}]
        cap, why = bv.derived_occasion_cap(d, srcs)
        want = 2000 + 300 + bv.REPO_LOCAL_OCCASION_TOKENS
        cases.append(('a consumer is capped at the sum of its sources\' '
                      'allowances plus its repo-local allowance',
                      cap == want, f'{cap} ({why}), wanted {want}'))
        (d / 'shr' / 'precedent-source.json').write_text(
            _json.dumps({'name': 'shr', 'level': 'shared'}), encoding='utf-8')
        cap2, why2 = bv.derived_occasion_cap(d, srcs)
        cases.append(('MID-MIGRATION: a source that declares no allowance yet '
                      'counts at its measured share (0 for an empty catalogue '
                      'here), is named, and does not drop the whole repo back '
                      'to the single fallback',
                      cap2 == 2000 + bv.REPO_LOCAL_OCCASION_TOKENS
                      and 'shr' in why2 and 'measured' in why2,
                      f'{cap2} ({why2})'))
        (d / 'uni' / 'precedent-source.json').unlink()
        cap3, why3 = bv.derived_occasion_cap(d, srcs)
        cases.append(('MID-MIGRATION: a vendored universal tree with no '
                      'precedent-source.json, as an older Update Vendors wrote '
                      'it, still builds', cap3 is not None and 'measured' in why3,
                      f'{cap3} ({why3})'))

        # A PRACTICE SET's block carries its own catalogue and defers
        # universal, so its cap is its own allowance -- never universal's,
        # and never 0 because universal is not cloned beside it. GitHub's
        # test for the first version refused a bootstrapped set at a 0-token
        # cap on exactly that (2026-09-29).
        pset = d / 'pset'
        (pset / 'practices').mkdir(parents=True)
        (pset / 'precedent.json').write_text(_json.dumps({
            'format_version': 1,
            'sources': [{'level': 'universal', 'name': 'precedent',
                         'path': str(d / 'no-universal-clone-here')}]}),
            encoding='utf-8')
        (pset / 'precedent-source.json').write_text(_json.dumps(
            {'name': 'pset', 'level': 'shared', 'occasion_share_tokens': 123}),
            encoding='utf-8')
        env_keep = os.environ.get('PRECEDENT_USER_CONFIG')
        os.environ['PRECEDENT_USER_CONFIG'] = str(d / 'no-user-config.json')
        try:
            cap4, why4 = bv.block_occasion_cap(pset)
            (pset / 'precedent-source.json').write_text(_json.dumps(
                {'name': 'pset', 'level': 'shared'}), encoding='utf-8')
            cap5, why5 = bv.block_occasion_cap(pset)
        finally:
            if env_keep is None:
                os.environ.pop('PRECEDENT_USER_CONFIG', None)
            else:
                os.environ['PRECEDENT_USER_CONFIG'] = env_keep
        cases.append(('a practice set is capped at its own allowance, with '
                      'universal deferred and not cloned beside it',
                      cap4 == 123, f'{cap4} ({why4})'))
        cases.append(('MID-MIGRATION: a practice set that declares no '
                      'allowance yet keeps the single fallback, never a 0 cap',
                      cap5 == bv.OCCASION_INDEX_BUDGET_TOKENS
                      and 'declares no' in why5, f'{cap5} ({why5})'))
    finally:
        shutil.rmtree(d, ignore_errors=True)
    bad = [(c[0], c[2]) for c in cases if not c[1]]
    check(f'each source\'s occasion-index share is capped, and a consumer\'s '
          f'cap is their sum ({len(cases)} stated cases)',
          not bad, '; '.join(f"{n} -- {d_}" for n, d_ in bad))


def check_engine_tools_say_which_repo_they_read():
    """An engine tool run from inside ANOTHER repo says so, loudly, and names
    the repo it measured in every output mode (precedent_which_repo.py).

    THE COST IT PAID FOR (2026-09-29). A "Reduction pass" session ran
    `cd ~/precedent-individual && python3 ~/BestPractice/tools/session_load_trend.py`.
    The script reads the repo its own file lives in, so it reported
    BestPractice's figures under a header that named no repo, and the session
    told Morgan his individual set was over a ceiling when it was not
    (gotchas/gotcha-2026-09-29-engine-tools-measure-their-own-repo-not-the-cwd.md).

    Discriminating cases, both directions: from a different git repo the
    warning appears, names both repos and points at that repo's own copy of
    the tool; from inside ROOT, and from a directory in no repo at all, it
    does not. The measured repo's name is in the text header, the --since
    ledger header, and a `repo` field in --json."""
    import subprocess as _sp
    import tempfile
    sys.path.insert(0, str(ROOT / 'tools'))
    import precedent_which_repo as pwr
    script = ROOT / 'tools' / 'session_load_trend.py'
    mine = pwr.describe(ROOT)['name']
    cases = []

    def run(cwd, *extra):
        r = _sp.run([sys.executable, str(script), '--days', '1', '--cap', '2',
                     *extra], cwd=str(cwd), capture_output=True, text=True,
                    timeout=300)
        return r.stdout, r.stderr

    other = pathlib.Path(tempfile.mkdtemp()) / 'some-other-repo'
    bare = pathlib.Path(tempfile.mkdtemp())
    try:
        other.mkdir()
        _sp.run(['git', 'init', '-q', str(other)], check=True)
        (other / 'tools').mkdir()
        (other / 'tools' / 'session_load_trend.py').write_text('# stub\n')

        out, err = run(other)
        cases.append(('from another repo, the warning names both repos and '
                      'that repo\'s own copy',
                      'WRONG REPO' in err and mine in err
                      and 'some-other-repo' in err
                      and str(other / 'tools' / 'session_load_trend.py') in err,
                      err[:600]))
        cases.append(('the text header names the measured repo',
                      out.startswith(f'SESSION LOAD -- {mine}'), out[:300]))

        out, err = run(ROOT)
        cases.append(('from inside ROOT there is no warning',
                      'WRONG REPO' not in err, err[:600]))

        out, err = run(bare)
        cases.append(('from a directory in no repo there is no warning',
                      'WRONG REPO' not in err, err[:600]))

        out, err = run(other, '--json')
        try:
            repo = json.loads(out).get('repo') or {}
        except ValueError:
            repo = {}
        cases.append(('--json carries a repo field naming the measured repo',
                      repo.get('name') == mine, out[:300]))

        out, err = run(ROOT, '--since', 'HEAD')
        cases.append(('the --since ledger header names the measured repo',
                      out.startswith(f'REDUCTION LEDGER -- {mine}'), out[:300]))
        out, err = run(ROOT, '--since', 'HEAD', '--json')
        try:
            repo = json.loads(out).get('repo') or {}
        except ValueError:
            repo = {}
        cases.append(('--since --json carries the repo field too',
                      repo.get('name') == mine, out[:300]))

        leaky = pwr.origin_url  # credentials never reach a report
        d = pathlib.Path(tempfile.mkdtemp())
        try:
            _sp.run(['git', 'init', '-q', str(d)], check=True)
            _sp.run(['git', '-C', str(d), 'remote', 'add', 'origin',
                     'https://x-access-token:' + 'tok' + '@github.com/o/r.git'],
                    check=True)
            url = leaky(d)
        finally:
            shutil.rmtree(d, ignore_errors=True)
        cases.append(('an origin URL loses its credentials',
                      url == 'https://github.com/o/r', repr(url)))
    finally:
        shutil.rmtree(other.parent, ignore_errors=True)
        shutil.rmtree(bare, ignore_errors=True)
    bad = [(c[0], c[2]) for c in cases if not c[1]]
    check(f'engine tools say which repo they read, and warn from another '
          f'repo ({len(cases)} stated cases)',
          not bad, '; '.join(f"{n} -- {d_}" for n, d_ in bad))


def check_todo_index_check_survives_midnight():
    """build_todo_index.py --check rebuilds against the date the committed
    TODO.md records, so an index built yesterday, or in a zone behind this
    one, is not drift (practice: control-asserts-which-failure).

    THE INCIDENT (2026-09-29). --as-ci --isolated runs under TZ=UTC, already
    the 30th while Buenos Aires was on the 29th: every Age cell came out one
    day greater, generated-files-registered called todo/TODO.md out of date,
    and the deep check refused a push that had not touched todo/. The
    DISCRIMINATING CASE is the first: built in UTC-12, checked in UTC+14,
    which are always on different dates. It fails on the code before
    `as_of`. The second proves real drift is still caught.

    The fixture owns its tree and its zone (fixture-owns-its-state)."""
    import contextlib, importlib, io, tempfile
    sys.path.insert(0, str(ROOT / 'tools'))
    todo = importlib.import_module('build_todo_index')
    cases = []
    keep = os.environ.get('PRECEDENT_COMMIT_TZ')
    with tempfile.TemporaryDirectory() as tmp:
        repo = pathlib.Path(tmp)
        tdir = repo / 'todo'
        tdir.mkdir()
        item = tdir / 'todo-2026-09-01-an-item.md'
        item.write_text('---\nslug: todo-2026-09-01-an-item\nstatus: open\n'
                        'kind: analysis\nnoted: 2026-09-01\ndisposition: wait\n'
                        '---\n\n## What\n\n**An item.**\n', encoding='utf-8')
        out = io.StringIO()
        try:
            os.environ['PRECEDENT_COMMIT_TZ'] = 'Etc/GMT+12'      # UTC-12
            todo.main(['--repo', str(repo)])
            built = (tdir / 'TODO.md').read_text(encoding='utf-8')
            os.environ['PRECEDENT_COMMIT_TZ'] = 'Etc/GMT-14'      # UTC+14
            with contextlib.redirect_stdout(out):
                rc = todo.main(['--repo', str(repo), '--check'])
            said = out.getvalue()
            cases.append(('THE DISCRIMINATING CASE: an index built in UTC-12 '
                          'checks clean in UTC+14, a day later',
                          rc == 0 and '0 drift' in said, f'rc={rc} {said!r}'))
            cases.append(('the file records the date its ages were computed on',
                          getattr(todo, 'recorded_as_of', lambda _p: None)(
                              tdir / 'TODO.md') is not None
                          and 'as_of:' in built, built[:300]))
            item.write_text(item.read_text(encoding='utf-8')
                            .replace('An item.', 'A renamed item.'),
                            encoding='utf-8')
            out = io.StringIO()
            with contextlib.redirect_stdout(out):
                rc = todo.main(['--repo', str(repo), '--check'])
            said = out.getvalue()
            cases.append(('POSITIVE CONTROL: an item changed after the build is '
                          'still drift, named by the index\'s own message',
                          rc == 1 and 'DRIFT in' in said and 'TODO.md' in said,
                          f'rc={rc} {said!r}'))
        finally:
            if keep is None:
                os.environ.pop('PRECEDENT_COMMIT_TZ', None)
            else:
                os.environ['PRECEDENT_COMMIT_TZ'] = keep
    bad = [(c[0], c[2]) for c in cases if not c[1]]
    check(f'the TODO index check does not go stale at midnight '
          f'({len(cases)} stated cases)',
          not bad, '; '.join(f"{n} -- {d_}" for n, d_ in bad))


def check_landed_reduction_quiets_the_reduction_ask():
    """An over-target file whose reduction has already landed on the landing
    branch is reported as waiting on a Promote, not as needing another pass.

    Found 2026-10-01 in a reduction-pass session: the reply gate kept
    requiring a Reduction pass after the pass had landed on pre-staging,
    because the file it measures is built from main. The rule under test:
    AGENTS.md smaller on origin/pre-staging than on origin/main marks the
    over-target line; the same size, or no landing branch, leaves it as
    the plain ask. Driven against a throwaway repository."""
    import tempfile
    import precedent_gate as pg
    cases = []
    with tempfile.TemporaryDirectory() as td:
        tmp = pathlib.Path(td)
        env = _stale_ref_fixture_env(tmp)
        bare, work = tmp / 'origin.git', tmp / 'work'

        def git(*a, cwd=None):
            return subprocess.run(['git', '-C', str(cwd or work), *a],
                                  capture_output=True, text=True, env=env)
        subprocess.run(['git', 'init', '-q', '--bare', '-b', 'main', str(bare)],
                       capture_output=True, env=env)
        subprocess.run(['git', 'init', '-q', '-b', 'main', str(work)],
                       capture_output=True, env=env)
        (work / 'tools').mkdir()
        (work / 'tools' / 'session_load_budgets.json').write_text(json.dumps(
            {'surfaces': {'AGENTS.md': {'target': 50}}}), encoding='utf-8')
        (work / 'AGENTS.md').write_text('# A\n' + 'word ' * 400, encoding='utf-8')
        git('add', '-A')
        git('commit', '-q', '-m', 'big')
        git('remote', 'add', 'origin', f'file://{bare}')
        git('push', '-q', 'origin', 'HEAD:main', 'HEAD:pre-staging')
        git('fetch', '-q', 'origin')

        got = pg._over_target(work, siblings=False)
        cases.append(('over target, same size on pre-staging: the plain ask',
                      len(got) == 1 and pg.LANDED_REDUCTION_MARK not in got[0],
                      repr(got)))
        git('checkout', '-q', '-b', 'pre-staging', 'origin/pre-staging')
        (work / 'AGENTS.md').write_text('# A\n' + 'word ' * 200, encoding='utf-8')
        git('commit', '-qam', 'reduction pass')
        git('push', '-q', 'origin', 'pre-staging')
        git('fetch', '-q', 'origin')
        git('checkout', '-q', 'main')
        got = pg._over_target(work, siblings=False)
        cases.append(('a smaller AGENTS.md on pre-staging marks the line as '
                      'waiting on a Promote, with both sizes',
                      len(got) == 1 and pg.LANDED_REDUCTION_MARK in got[0]
                      and 'on main' in got[0] and 'on pre-staging' in got[0],
                      repr(got)))
        # Off the ladder: the same fact, with no tier and no ladder word
        # (found 2026-10-03, the line named pre-staging to such a person).
        import ladder_words as lw
        saved = {k: os.environ.pop(k, None) for k in
                 ('PRECEDENT_ASSUME_LADDER', 'PRECEDENT_USER_CONFIG')}
        os.environ['PRECEDENT_USER_CONFIG'] = str(tmp / 'no-config.json')
        try:
            got = pg._over_target(work, siblings=False)
        finally:
            os.environ.pop('PRECEDENT_USER_CONFIG', None)
            os.environ.update({k: v for k, v in saved.items() if v is not None})
        cases.append(('off the ladder, the same line says it plainly, with no '
                      'ladder word',
                      len(got) == 1 and pg.LANDED_REDUCTION_MARK_PLAIN in got[0]
                      and 'on main' in got[0]
                      and not lw.output_hits(got[0]), repr(got)))
        git('push', '-q', 'origin', '--delete', 'pre-staging')
        git('fetch', '-q', '--prune', 'origin')
        cases.append(('no landing branch on origin: no mark',
                      pg._landed_reduction(work) is None,
                      repr(pg._landed_reduction(work))))
    bad = [(n, d) for n, ok, d in cases if not ok]
    check(f'a reduction already on the landing branch is reported as waiting '
          f'on a Promote ({len(cases)} stated cases)', not bad,
          '; '.join(f'{n}: {d}' for n, d in bad))


def check_budget_approvals_see_computed_raises():
    """The budgets in force stay within the person's approvals, however a
    number got bigger, and the session-start file's hard ceiling is enforced
    as a sum of its sources' declared numbers (practice: session-load-budget;
    control-asserts-which-failure).

    THE INCIDENT (2026-09-29): a session made precedent-individual's
    session-file ceiling a computed sum and the number in force went from
    5,200 to 6,200 with the `ceiling` field unchanged; Morgan had not been
    asked. The first fix compared registry FIELDS with a base commit, and
    could see neither a computed raise nor anything on a direct push or a
    Promote, where the base is HEAD. Each case below asserts the check's own
    words, so a case that fails for another reason reads as a failure.

    The fixture owns its tree (fixture-owns-its-state): a copy of this repo
    with no .git, no sibling sources and no user config."""
    import tempfile
    import importlib
    cases = []
    with tempfile.TemporaryDirectory() as tmp:
        repo = pathlib.Path(tmp) / 'fixture'
        shutil.copytree(ROOT, repo, ignore=shutil.ignore_patterns(
            '.git', '__pycache__', '*.pyc', 'prompts'))
        reg_p = repo / 'tools' / 'session_load_budgets.json'
        bv_p = repo / 'tools' / 'build_views.py'
        src_p = repo / 'precedent-source.json'
        pristine = {p: p.read_text(encoding='utf-8') for p in (reg_p, bv_p, src_p)}

        def reset():
            for p, t in pristine.items():
                p.write_text(t, encoding='utf-8')

        def edit_reg(fn):
            d = json.loads(reg_p.read_text(encoding='utf-8'))
            fn(d)
            reg_p.write_text(json.dumps(d, indent=2), encoding='utf-8')

        def run():
            env = dict(os.environ,
                       PRECEDENT_USER_CONFIG=str(repo / '.no-user-config.json'))
            r = subprocess.run([sys.executable, str(repo / 'tools' / 'precedent_check.py'),
                                '--only', 'budget-within-approval'],
                               capture_output=True, text=True, cwd=str(repo), env=env)
            return r.returncode, r.stdout + r.stderr

        rc, out = run()
        cases.append(('this tree, as committed, is within its approvals',
                      rc == 0 and '1 passed' in out, out[-400:]))

        edit_reg(lambda d: d['surfaces']['AGENTS.md'].update(ceiling=9000))
        rc, out = run()
        cases.append(('a raised ceiling field is refused, naming the number '
                      'and the approval it exceeds',
                      rc != 0 and 'surfaces/AGENTS.md is 9,000 in force, above '
                      'the 6,950' in out, out[-600:]))
        reset()

        bv_p.write_text(pristine[bv_p].replace(
            "    v = row.get('ceiling')\n    return v if isinstance(v, int) else default",
            "    v = row.get('ceiling')\n    return v + 1000 if isinstance(v, int) else default", 1),
            encoding='utf-8')
        rc, out = run()
        cases.append(('a COMPUTED raise with every field unchanged is refused '
                      '(the 2026-09-29 incident)',
                      rc != 0 and 'surfaces/.precedent/SESSION_PRACTICES.md is '
                      '5,000 in force, above the 4,000' in out, out[-600:]))
        reset()

        src_p.write_text(json.dumps({k: v for k, v in json.loads(
            pristine[src_p]).items() if k != 'occasion_share_tokens'}),
            encoding='utf-8')
        rc, out = run()
        cases.append(('a removed allowance reads as uncapped and is refused',
                      rc != 0 and 'occasion_share_tokens is uncapped in force'
                      in out, out[-600:]))
        reset()

        edit_reg(lambda d: d['surfaces']['AGENTS.md'].update(target=5000))
        rc, out = run()
        cases.append(('a new target nobody approved is refused',
                      rc != 0 and 'surfaces/AGENTS.md/target is 5000 in force '
                      'and has no entry in approved_budgets' in out, out[-600:]))
        reset()

        def raise_with(words, strength):
            def fn(d):
                d['surfaces']['AGENTS.md']['ceiling'] = 9000
                d['approved_budgets']['surfaces/AGENTS.md'] = {
                    'max': 9000, 'strength': strength,
                    'approved_by': f'Fixture Person, 2026-09-30: {words}'}
            return fn

        edit_reg(raise_with('"yes, raise it to 9,000"', 'decided'))
        rc, out = run()
        cases.append(('a raise carrying the person\'s quoted words passes',
                      rc == 0 and '1 passed' in out, out[-600:]))
        reset()

        edit_reg(raise_with('said yes', 'decided'))
        rc, out = run()
        cases.append(('a "decided" approval with no quoted words is refused',
                      rc != 0 and "approved_by quotes nobody's words" in out,
                      out[-600:]))
        reset()

        edit_reg(lambda d: d.pop('approved_budgets'))
        rc, out = run()
        cases.append(('with no approvals list and no main to compare, the '
                      'check says it is not checking, never passes',
                      'SKIPPED' in out and 'a raise here is not checked' in out,
                      out[-600:]))
        reset()

        # --- the hard ceiling as a sum, in a consumer's shape ------------
        sys.path.insert(0, str(ROOT / 'tools'))
        pc = importlib.import_module('precedent_check')
        bv = importlib.import_module('build_views')
        pr = importlib.import_module('precedent_resolve')
        consumer = pathlib.Path(tmp) / 'consumer'
        (consumer / 'tools').mkdir(parents=True)

        def source(name, share, resident):
            d = pathlib.Path(tmp) / name
            (d / 'tools').mkdir(parents=True, exist_ok=True)
            (d / 'precedent-source.json').write_text(json.dumps(
                {'name': name, 'occasion_share_tokens': share}), encoding='utf-8')
            rb = {} if resident is None else {'resident_block_tokens': resident}
            (d / 'tools' / 'session_load_budgets.json').write_text(
                json.dumps(rb), encoding='utf-8')
            return {'name': name, 'path': str(d), 'level': 'shared'}

        def fit(entry, srcs):
            (consumer / 'tools' / 'session_load_budgets.json').write_text(
                json.dumps({'surfaces': {'.precedent/SESSION_PRACTICES.md': entry}}),
                encoding='utf-8')
            saved = (pc.ROOT, bv.sources_for_tracked_block, pr.load_config)
            pc.ROOT = consumer
            bv.sources_for_tracked_block = lambda root, cfg: ([], srcs, [])
            pr.load_config = lambda root, *a, **k: []
            try:
                return pc._session_file_allowances_fit(None)
            except pc.NotApplicable as e:
                return f'N/A {e}'
            finally:
                pc.ROOT, bv.sources_for_tracked_block, pr.load_config = saved

        small = [source('u', 1800, 900), source('w', 150, 200)]
        got = fit({'hard_ceiling': 4400, 'fixed_allowance': 300}, small)
        cases.append(('sources whose numbers add up under the hard ceiling pass',
                      got == [], repr(got)))
        big = [source('u2', 2800, 2000), source('w2', 550, 425)]
        got = fit({'hard_ceiling': 4400, 'fixed_allowance': 300}, big)
        cases.append(('sources whose numbers add up over it are refused, with '
                      'the parts listed',
                      len(got) == 1 and "allowances add up to 6,075" in got[0].detail
                      and 'u2 2,800+2,000' in got[0].detail, repr(got)))
        got = fit({'hard_ceiling': 4400, 'fixed_allowance': 300},
                  small + [source('r', 450, None)])
        cases.append(('a source with no resident cap means the sum cannot be '
                      'shown, and does not pass',
                      len(got) == 1 and 'r (no resident_block_tokens)' in got[0].detail,
                      repr(got)))
        got = fit({'target': 4000}, big)
        cases.append(('with no hard_ceiling declared, it is not switched on',
                      isinstance(got, str) and 'declares no hard_ceiling' in got,
                      repr(got)))

        # --- D: the once-per-session warning ------------------------------
        psp = importlib.import_module('precedent_session_practices')
        (consumer / 'tools' / 'session_load_budgets.json').write_text(json.dumps(
            {'surfaces': {'.precedent/SESSION_PRACTICES.md': {'target': 50}}}),
            encoding='utf-8')
        text = '<!-- x -->\n\n# Practices\n\n' + 'word ' * 100
        warned = psp._with_target_warning(consumer, text)
        cases.append(('the session-start file opens with the warning under its '
                      'title when over target',
                      'SESSION LOAD OVER TARGET' in warned
                      and warned.index('# Practices') < warned.index('OVER TARGET'),
                      warned[:200]))
        short = '<!-- x -->\n\n# Practices\n\nshort\n'
        cases.append(('and carries none when under it',
                      psp._with_target_warning(consumer, short) == short,
                      psp._with_target_warning(consumer, short)))

        # --- F: the trend tool names the repository it measured ----------
        r = subprocess.run([sys.executable, str(ROOT / 'tools' / 'session_load_trend.py'),
                            '--root', str(repo)], capture_output=True, text=True,
                           cwd=str(repo))
        cases.append(('session_load_trend.py --root measures that repository '
                      'and names it',
                      r.returncode == 0 and 'SESSION LOAD -- fixture' in r.stdout
                      and f'at {repo.resolve()}' in r.stdout
                      and 'WRONG REPO' not in r.stderr,
                      r.stdout[:300] + r.stderr[-300:]))
    bad = [(c[0], c[2]) for c in cases if not c[1]]
    check(f'budgets in force stay within the person\'s approvals, and the '
          f'session file\'s hard ceiling is a sum that must fit '
          f'({len(cases)} stated cases)',
          not bad, '; '.join(f"{n} -- {d_}" for n, d_ in bad))


def check_session_load_target_is_reported_each_reply():
    """Over its `target`, an always-loaded file is reported for The Boildown
    in every reply (practice: session-load-budget; Morgan, 2026-09-29: "at
    the 4000 level, you get warnings, with every session to bring it
    down"). Over its `hard_ceiling`, nothing refuses a commit in the repo
    that loads the file: that block was retired on 2026-09-30, unused
    (Morgan: "Since it's never used then let's retire it completely.
    Approved. Act.", strength: decided), because the ceiling is enforced
    where the file's text is written (session-file-allowances-fit). The
    last case runs the REAL .claude/hooks/doc-lint-gate.sh against a
    registry that still carries the old switch, so a hook that grew the
    block back fails here.

    The fixture owns its tree (fixture-owns-its-state)."""
    import tempfile
    import importlib
    sys.path.insert(0, str(ROOT / 'tools'))
    slt = importlib.import_module('session_load_trend')
    gate = importlib.import_module('precedent_gate')
    cases = []
    with tempfile.TemporaryDirectory() as tmp:
        repo = pathlib.Path(tmp) / 'fixture'
        (repo / 'tools').mkdir(parents=True)
        shutil.copy(ROOT / 'tools' / 'session_load_trend.py', repo / 'tools')
        shutil.copy(ROOT / 'tools' / 'build_views.py', repo / 'tools')
        subprocess.run(['git', 'init', '-q', str(repo)], check=True)
        for k, v in (('user.name', 'Fixture'), ('user.email', 'f@example.com')):
            subprocess.run(['git', '-C', str(repo), 'config', k, v], check=True)
        (repo / 'AGENTS.md').write_text('word ' * 200, encoding='utf-8')
        (repo / 'tools' / 'session_load_budgets.json').write_text(
            json.dumps({'headroom_floor_pct': 5, 'surfaces': {'AGENTS.md': {
                'ceiling': 100000, 'hard_ceiling': 100, 'target': 50,
                'block_commits': True}}}), encoding='utf-8')
        subprocess.run(['git', '-C', str(repo), 'add', '-A'], check=True)
        subprocess.run(['git', '-C', str(repo), 'commit', '-qm', 'base'], check=True)

        rows = slt.over_target(repo)
        cases.append(('a file over its target is listed with its target and '
                      'ceiling', rows and rows[0][0] == 'AGENTS.md'
                      and rows[0][2] == 50 and rows[0][3] == 100, repr(rows)))
        lines = gate._over_target(repo, siblings=False)
        cases.append(('the reply gate reports it for The Boildown',
                      lines and 'over its 50-token target' in lines[0]
                      and 'hard ceiling 100' in lines[0], repr(lines)))

        hook = ROOT / '.claude' / 'hooks' / 'doc-lint-gate.sh'
        env = dict(os.environ, CLAUDE_PROJECT_DIR=str(repo))
        r = subprocess.run(['bash', str(hook)], input=json.dumps(
            {'tool_input': {'command': 'git commit -m change'}}),
            capture_output=True, text=True, env=env)
        cases.append(('over its hard ceiling, with the retired switch still '
                      'in the registry, the real commit-time hook lets the '
                      'commit through', r.returncode == 0
                      and 'COMMIT REFUSED' not in r.stderr,
                      f'rc={r.returncode} {r.stderr[-300:]!r}'))

    bad = [(c[0], c[2]) for c in cases if not c[1]]
    check(f'an always-loaded file over its target is reported each reply, '
          f'and nothing refuses a commit over its hard ceiling '
          f'({len(cases)} stated cases)',
          not bad, '; '.join(f"{n} -- {d_}" for n, d_ in bad))


def check_headroom_notice_watches_the_resident_block():
    """headroom_notice() also speaks when the generated resident block is
    near its own allocation, not only when a whole file nears its ceiling
    (very deep check, 2026-09-28: an individual set's block sat at ~539 of
    550 tokens, the file far from its ceiling, and nothing said so until a
    practice edit would have failed to build). Discriminating case: a block
    at 98% of its budget inside a file with no ceiling pressure at all."""
    import tempfile
    sys.path.insert(0, str(ROOT / 'tools'))
    import session_load_trend as slt
    real = slt.registry
    slt.registry = lambda: {'headroom_floor_pct': 5, 'surfaces': {}}
    cases = []
    try:
        for used, want in ((539, True), (440, False)):
            d = pathlib.Path(tempfile.mkdtemp())
            try:
                (d / 'AGENTS.md').write_text(
                    f'# x\n\n## Resident block (~{used} of 550 token budget, '
                    f'4 of 17 practices)\n\nbody\n', encoding='utf-8')
                note = slt.headroom_notice(root=d)
            finally:
                shutil.rmtree(d, ignore_errors=True)
            said = bool(note) and 'resident block' in note
            cases.append((f'a block at {used} of 550 is '
                          + ('reported' if want else 'left quiet'),
                          said == want, repr(note)))
    finally:
        slt.registry = real
    bad = [(c[0], c[2]) for c in cases if not c[1]]
    check(f'the headroom notice watches the resident block\'s own budget '
          f'({len(cases)} stated cases)',
          not bad, '; '.join(f"{n} -- {d[:300]}" for n, d in bad))


def check_a_registry_file_can_be_a_checks_own_opt_in():
    """`binds_when` lifts the practice-file gate for a repo that kept the
    registry carrying the rule (practice: control-asserts-which-failure).

    THE COST IT PAID FOR (2026-09-22). A repo that declares ceilings in
    `tools/session_load_budgets.json` and does not vendor
    `practices/session-load-budget.md` got a SKIP whose reason read "this
    check belongs to a source this repo does not resolve" -- true of the
    practice, wrong about the registry, which was sitting in the repo. So the
    numbers were declared and nothing local tested them.

    BOTH DIRECTIONS, because a gate that lifts for everything is not a gate:
    the check runs where the named file exists and still skips where it does
    not. Asserted through `run()` rather than by reading the CHECKS entry --
    the registration is not the behaviour, and it was the gate in `run()`
    that was wrong."""
    sys.path.insert(0, str(ROOT / 'tools'))
    import precedent_check as pc

    cases = []
    reg = pc.CHECKS['session-load-budget']
    cases.append(('session-load-budget names the registry as its opt-in',
                  reg.get('binds_when') == ('tools/session_load_budgets.json',),
                  repr(reg.get('binds_when'))))
    cases.append(('and a commit touching AGENTS.md or the registry SELECTS it, '
                  'so a repo without the practice file can still reach it '
                  'without waiting for the rotation',
                  'AGENTS.md' in (reg.get('selects_on') or ())
                  and 'tools/session_load_budgets.json' in
                  (reg.get('selects_on') or ()),
                  repr(reg.get('selects_on'))))

    # The gate itself, driven through run() with the practice file made
    # invisible -- which is the state of every repo this is for.
    class Ctx:
        def read_base(self, rel):
            return None

    def gate(slug, practice_file):
        orig = pc._practice_file
        pc._practice_file = lambda s: practice_file
        try:
            res = pc.run([slug], Ctx(), (pc.CHECKS[slug]['scope'],))
        finally:
            pc._practice_file = orig
        return res[0][1], res[0][3]

    status, why = gate('session-load-budget', None)
    cases.append(('THE CASE THAT WAS SKIPPING: no practice file, registry '
                  'present -- the check RUNS', status != 'SKIPPED',
                  f'{status}: {why}'))

    # A practice-backed check with no binds_when, same missing practice file.
    control = next(s for s, c in pc.CHECKS.items()
                   if c['practice_backed'] and not c.get('binds_when')
                   and not c.get('binds_publishers')
                   and c['scope'] == pc.CHECKS['session-load-budget']['scope'])
    status, why = gate(control, None)
    cases.append((f'THE DISCRIMINATING CASE: a check with no binds_when '
                  f'({control}) still skips on a missing practice file -- the '
                  f'gate was lifted for one rule, not removed',
                  status == 'SKIPPED', f'{status}: {why}'))

    # And the Rule line says where to read it rather than reporting a gap.
    rule = None
    orig = pc._practice_file
    pc._practice_file = lambda s: None
    try:
        rule = pc.rule_of('session-load-budget')
    finally:
        pc._practice_file = orig
    cases.append(('the Rule line names where to read the practice instead of '
                  'printing "(no practice file for ...)"',
                  'no practice file for' not in rule
                  and 'session_load_budgets.json' in rule, rule))

    bad = [(c[0], c[2]) for c in cases if not c[1]]
    check(f'a repo opts a check in by keeping the registry that carries its '
          f'rule ({len(cases)} stated cases, a check without binds_when being '
          f'the discriminating one)',
          not bad, '; '.join(f"{n} -- {d[:400]}" for n, d in bad))


def check_environment_gotchas_follows_a_split_index():
    """A split gotchas section is still held to the story rule
    (practice: control-asserts-which-failure).

    WHY THIS CONTROL EXISTS. Splitting the section -- one line per trap in
    AGENTS.md, the stories in record/GOTCHAS.md -- is a reduction that looks
    exactly like the failure the rule forbids: an instructions file full of
    bare symptoms with no account of what failed. The difference is entirely
    in whether the links resolve to real, whole entries, so the check has to
    FOLLOW them. A check that stopped at the section would pass a repo that
    deleted the record outright, and would do it silently.

    Each case asserts the SPECIFIC message, not merely that something was
    reported: a broken link and a gutted entry are different repairs, and a
    control that cannot tell them apart lets one masquerade as the other.
    The fixture owns its own tree (fixture-owns-its-state)."""
    import tempfile
    sys.path.insert(0, str(ROOT / 'tools'))
    import precedent_check as pc

    SECTION = ('# fixture\n\n## Build-environment gotchas -- do NOT rediscover '
               'these\n\n'
               '- **A trap with its story elsewhere.** [story](record/GOTCHAS.md#g1)\n\n'
               '- **A second trap.** [story](record/GOTCHAS.md#g2)\n\n'
               '- **A third trap.** [story](record/GOTCHAS.md#g3)\n\n'
               '## Next\n')
    STORY = ('It failed on 2026-09-13 in a way that read as something else '
             'entirely, and the session spent an hour on the wrong '
             'hypothesis. The remedy is to check the exit code rather than '
             'the printed output.\n')

    def record(entries):
        out = ['# Gotchas\n']
        for n, body in entries:
            out.append(f'\n## {n}. <a id="g{n}"></a>Entry {n}\n\n{body}\n')
        return ''.join(out)

    def run(agents, rec):
        d = pathlib.Path(tempfile.mkdtemp())
        try:
            (d / 'record').mkdir()
            (d / 'AGENTS.md').write_text(agents, encoding='utf-8')
            if rec is not None:
                (d / 'record' / 'GOTCHAS.md').write_text(rec, encoding='utf-8')
            old = pc.ROOT
            pc.ROOT = d
            try:
                findings = pc._environment_gotchas(None)
            finally:
                pc.ROOT = old
            return '; '.join(str(f) for f in findings)
        finally:
            shutil.rmtree(d, ignore_errors=True)

    whole = record([(1, STORY), (2, STORY), (3, STORY)])
    cases = []

    out = run(SECTION, whole)
    cases.append(('THE DISCRIMINATING CASE: a split section whose links all '
                  'resolve to whole entries raises nothing', out == '', out))

    gutted = record([(1, STORY), (2, 'Use `git cat-file -e`.\n'), (3, STORY)])
    out = run(SECTION, gutted)
    cases.append(('an entry gutted to a bare fix is reported against the '
                  'RECORD, not the instructions file',
                  'record/GOTCHAS.md:' in out and 'bare fix' in out, out))

    out = run(SECTION, record([(1, STORY), (2, STORY)]))
    cases.append(('an index line pointing at an anchor the record does not '
                  'have names that anchor',
                  'record/GOTCHAS.md#g3' in out and 'does not exist' in out,
                  out))

    out = run(SECTION, None)
    cases.append(('a section indexing a record that is not there says every '
                  'line leads nowhere, rather than passing',
                  'leads nowhere' in out, out))

    unsplit = ('# fixture\n\n## Build-environment gotchas -- do NOT rediscover '
               'these\n\n- **A trap.** ' + STORY + '\n## Next\n')
    out = run(unsplit, None)
    cases.append(('an UNSPLIT section is still judged on its own entries, so '
                  'a repo that never split is unaffected', out == '', out))

    bad = [(c[0], c[2]) for c in cases if not c[1]]
    check(f'environment-gotchas follows a split index into the record '
          f'({len(cases)} stated cases, the all-resolving split being the '
          f'discriminating one)',
          not bad, '; '.join(f"{n} -- {d[:400]}" for n, d in bad))


def check_environment_gotchas_advises_migrating_an_inline_catalogue():
    """The pre-migration fallback of `environment-gotchas` still validates
    an inline catalogue, AND says to move it to gotchas/ -- as advice that
    never fails the run (practice: control-asserts-which-failure).

    WHY. Until 2026-09-28 a consumer with no gotchas/ directory passed this
    check green forever while carrying the catalogue in AGENTS.md, which the
    Rule says must not load there at all, and nothing ever told it to
    migrate. Turning that into a violation would redden every unmigrated
    consumer on the day the engine is vendored, so the fallback prints an
    advisory instead and keeps its validation.

    Four stated cases. THE DISCRIMINATING ONE is the clean inline section:
    it must print the advisory AND return no finding -- a finding there
    would make the advice a gate. A gutted inline entry still returns its
    bare-fix finding, so the validation did not go away with the advice;
    and a migrated repo prints no advisory. The fixture owns its own tree
    (fixture-owns-its-state)."""
    import contextlib
    import io
    import tempfile
    sys.path.insert(0, str(ROOT / 'tools'))
    import precedent_check as pc

    STORY = ('It failed on 2026-09-13 in a way that read as something else '
             'entirely, and the session spent an hour on the wrong '
             'hypothesis. The remedy is to check the exit code rather than '
             'the printed output.')
    HEAD = ('# fixture\n\n## Build-environment gotchas -- do NOT rediscover '
            'these\n\n')

    def run(agents, gotcha=None):
        d = pathlib.Path(tempfile.mkdtemp())
        try:
            (d / 'AGENTS.md').write_text(agents, encoding='utf-8')
            if gotcha is not None:
                (d / 'gotchas').mkdir()
                (d / 'gotchas' / 'gotcha-2026-09-13-a-trap.md').write_text(
                    gotcha, encoding='utf-8')
            old = pc.ROOT
            pc.ROOT = d
            buf = io.StringIO()
            try:
                with contextlib.redirect_stdout(buf):
                    findings = pc._environment_gotchas(None)
            finally:
                pc.ROOT = old
            return '; '.join(str(f) for f in findings), buf.getvalue()
        finally:
            shutil.rmtree(d, ignore_errors=True)

    ADVICE = 'migrate to gotchas/ (spec/OPEN_ITEM_AND_GOTCHA_PLAN.md Part 2)'
    cases = []

    found, said = run(HEAD + '- **A trap.** ' + STORY + '\n\n## Next\n')
    cases.append(('THE DISCRIMINATING CASE: a clean inline catalogue prints '
                  'the advisory and returns no finding',
                  found == '' and ADVICE in said and 'ADVISORY' in said
                  and 'AGENTS.md' in said, f'findings={found!r} said={said!r}'))

    found, said = run(HEAD + '- **A trap.** Use `git cat-file -e`.\n\n'
                             '## Next\n')
    cases.append(('a bare-fix inline entry is still a finding, with the '
                  'advisory printed beside it',
                  'bare fix' in found and ADVICE in said,
                  f'findings={found!r} said={said!r}'))

    found, said = run(HEAD + '- **A trap.** [story](record/GOTCHAS.md#g1)\n'
                             '\n## Next\n')
    cases.append(('an index into a pre-migration record gets the advisory '
                  'too, and its own finding stays',
                  'leads nowhere' in found and ADVICE in said,
                  f'findings={found!r} said={said!r}'))

    migrated = ('---\nstatus: live\n---\n\n## Symptom\n\nA command reports '
                'success and did nothing.\n\n## Story\n\n' + STORY +
                '\n\n## Fix\n\nCheck the exit code.\n')
    found, said = run(HEAD + 'Grep [gotchas/](gotchas/) before concluding a '
                             'failure is new.\n\n## Next\n', migrated)
    cases.append(('a migrated repo prints no advisory',
                  found == '' and ADVICE not in said,
                  f'findings={found!r} said={said!r}'))

    bad = [(c[0], c[2]) for c in cases if not c[1]]
    check(f'environment-gotchas advises migrating an inline catalogue to '
          f'gotchas/ without failing on it ({len(cases)} stated cases, the '
          f'clean inline section being the discriminating one)',
          not bad, '; '.join(f"{n} -- {d[:400]}" for n, d in bad))


def check_beta_watermark_commit_carries_a_session_trailer():
    """Every commit tools/precedent_beta_watermark_check.py writes carries a
    session trailer the shared set's check_session_trailer.py accepts
    (practice: session-trailer).

    WHY. Until 2026-09-28 the watermark commit was a bare subject line, and
    the very deep check's run of that shared check against this repository
    found eight of them -- the one source of trailer-less commits here that
    was a tool repeating the omission rather than a session forgetting once.

    Two cases, each committing for real into a throwaway repository through
    the tool's own _commit_and_push, with the person's global git config
    held out so no installed hook can add or strip a trailer: with no
    session link the trailer is the practice's explicit opt-out naming the
    tool, and with PRECEDENT_SESSION_URL it is that link. The trailer shape
    is judged by the shared check's own pattern, copied here, not by a
    looser one."""
    import tempfile
    sys.path.insert(0, str(ROOT / 'tools'))
    import precedent_beta_watermark_check as pbw

    TRAILER_RE = re.compile(r'^(?:Session|Claude-Session):\s+(\S.*)$',
                            re.MULTILINE)
    ident = {'name': 'Watermark Owner', 'email': 'watermark-owner@example.com'}
    saved = {k: os.environ.get(k)
             for k in ('GIT_CONFIG_GLOBAL', 'PRECEDENT_SESSION_URL')}
    cases = []
    d = pathlib.Path(tempfile.mkdtemp(prefix='beta-watermark-trailer-'))
    try:
        os.environ['GIT_CONFIG_GLOBAL'] = os.devnull
        subprocess.run(['git', 'init', '-q', '-b', 'staging', str(d)],
                       capture_output=True, check=True)
        wm = d / 'tools' / 'beta_branch_watermark.json'
        wm.parent.mkdir()

        def commit(n):
            wm.write_text(json.dumps({'n': n}) + '\n', encoding='utf-8')
            said = pbw._commit_and_push(d, wm, f'Advance staging watermark '
                                               f'to {n:09d}', True, 'staging',
                                        identity=ident)
            body = subprocess.run(['git', '-C', str(d), 'log', '-1',
                                   '--format=%B'], capture_output=True,
                                  text=True).stdout
            return said, body

        os.environ.pop('PRECEDENT_SESSION_URL', None)
        said, body = commit(1)
        m = TRAILER_RE.search(body)
        cases.append(('with no session link, the commit carries the explicit '
                      'opt-out naming the tool',
                      said.startswith('committed') and m is not None
                      and 'none available' in m.group(1)
                      and 'precedent_beta_watermark_check.py' in m.group(1),
                      f'{said!r} {body!r}'))

        os.environ['PRECEDENT_SESSION_URL'] = \
            'https://claude.ai/code/session_example'
        said, body = commit(2)
        m = TRAILER_RE.search(body)
        cases.append(('with PRECEDENT_SESSION_URL, the commit carries that '
                      'link', m is not None and m.group(1).strip()
                      == 'https://claude.ai/code/session_example',
                      f'{said!r} {body!r}'))
    finally:
        for k, v in saved.items():
            if v is None:
                os.environ.pop(k, None)
            else:
                os.environ[k] = v
        shutil.rmtree(d, ignore_errors=True)

    bad = [(c[0], c[2]) for c in cases if not c[1]]
    check(f'a beta-watermark commit carries a session trailer '
          f'({len(cases)} stated cases)',
          not bad, '; '.join(f"{n} -- {x[:300]}" for n, x in bad))


def check_gotcha_currency_signals_fire():
    """tools/very_deep_check.py's gotcha-currency pass actually fires, and
    fires on the right entry (practice: control-asserts-which-failure).

    WHY A CONTROL RATHER THAN A RE-READING. The pass exists to catch an entry
    that still READS as live while the tree renamed or deleted the remedy it
    names. On the day it was written every one of its strong signals scored
    zero against this repository -- which is the good outcome and also means
    nothing had ever proved the signals work. A check that has only ever
    reported "none" is indistinguishable from one that cannot report anything
    at all, and this file already carries three entries of that exact shape.

    So this builds a fixture section carrying one entry per signal and asserts
    the SPECIFIC message each produces, not merely that something was
    reported. The fifth case is the discriminating one: a clean, dated entry
    naming a file that is present must raise nothing, or the pass is an alarm
    rather than a signal and its output would be ignored within a week.

    The fixture owns its own tree (fixture-owns-its-state): its own AGENTS.md
    and its own tools/ directory, so the result does not depend on what this
    repository happens to contain today."""
    import tempfile
    sys.path.insert(0, str(ROOT / 'tools'))
    import very_deep_check as vdc

    cases = []
    with tempfile.TemporaryDirectory() as td:
        d = pathlib.Path(td)
        (d / 'tools').mkdir()
        (d / 'tools' / 'real.py').write_text(
            'def check_that_exists():\n    pass\n', encoding='utf-8')
        (d / 'AGENTS.md').write_text(
            '# fixture\n\n## Build-environment gotchas -- do NOT rediscover '
            'these\n\n'
            '- **A remedy that is gone.** Measured 2026-09-10. Run\n'
            '  [tools/deleted_tool.py](tools/deleted_tool.py) to repair it.\n\n'
            '- **A stale entry nobody has re-measured.** Measured 2019-01-02,\n'
            '  and the fix is `tools/real.py`.\n\n'
            '- **A slug that does not exist.** 2026-09-10: run\n'
            '  `python3 tools/precedent_check.py --only no-such-check-slug`.\n\n'
            '- **A fixture that was renamed.** 2026-09-10, held by\n'
            '  `check_that_is_gone`.\n\n'
            '- **A clean live entry.** 2026-09-10, and `tools/real.py` is\n'
            '  still there, held by `check_that_exists`.\n\n'
            '## Next\n', encoding='utf-8')

        rows, msgs = vdc._gotchas_currency(d)
        out = '\n'.join(msgs)

        for label, want in (
                ('a named remedy missing from the tree is reported by path',
                 'tools/deleted_tool.py'),
                ('an entry whose newest date is past the threshold is named '
                 'with that date',
                 'nothing re-measured since 2019-01-02'),
                ('a --only slug precedent_check.py does not answer to is '
                 'reported',
                 'no-such-check-slug'),
                ('a named fixture that no longer exists is reported',
                 'check_that_is_gone')):
            cases.append((label, want in out, out[-600:]))

        clean = [r for r in rows if 'clean live entry' in r[2].lower()]
        cases.append(('THE DISCRIMINATING CASE: a dated entry naming a file '
                      'that is present raises nothing',
                      bool(clean) and not clean[0][3],
                      repr(clean[:1])))
        cases.append(('every entry is costed, so a reduction pass can be '
                      'ordered by what it would save',
                      bool(rows) and all(isinstance(r[0], int) and r[0] > 0
                                         for r in rows),
                      repr([r[0] for r in rows])))
        cases.append(('it proposes and never edits -- the fixture AGENTS.md '
                      'is byte-identical afterwards',
                      (d / 'AGENTS.md').read_text(encoding='utf-8').endswith(
                          '## Next\n'),
                      'fixture AGENTS.md was modified'))

    bad = [(c[0], c[2]) for c in cases if not c[1]]
    check(f'the gotcha-currency pass fires on each signal and stays silent on '
          f'a clean entry ({len(cases)} stated cases, the clean entry being '
          f'the discriminating one)',
          not bad, '; '.join(f"{n} -- {d[:400]}" for n, d in bad))


def check_fixtures_own_the_credential_environment():
    """The harness's own result must not depend on whether the container it
    runs in happens to carry a private-source credential
    (practice: fixture-owns-its-state).

    THE INCIDENT (2026-09-11). Two checks below build a scenario where NO
    credential is available -- check_source_credentials' "with no base url
    the shared source is named on stderr as NOT in force", and
    check_individual_source_bootstrap_self_heals' "--write-session-hook with
    NO --repo-url ... degrades quietly" -- and then spawned a subprocess
    carrying the container's own environment. Since 2026-09-10 a real
    session carries PRECEDENT_GIT_TOKEN and PRECEDENT_SOURCE_BASE_URL
    (INSTALL.md section 8), so the subprocess found a URL after all and did
    the thing the case says it must not do. Measured on one tree with no code
    change: `4 failed` with the variables set, `2 failed` under `env -u`.
    Neither run was wrong about itself, which is the whole problem -- a
    harness result nobody can read.

    The two fixtures were fixed first by popping both variables in their own
    run() helpers, which is right where a reader meets the hazard and is kept.
    The scrub at the top of this file is the half that covers the fixture
    nobody has written yet, for the reason fixture-owns-its-state states
    outright: it inherits the same invisible dependency and will not notice.
    This check is what stops that scrub being deleted or quietly outgrown.

    Case 3 is the controlling one, and it is a real negative control rather
    than a re-reading of case 1: it PLANTS both variables in a subprocess's
    environment and imports this module there, so it measures the scrub
    doing its job rather than the container happening to be clean. Case 4 is
    the other direction -- a fixture that genuinely wants a credential must
    still be able to set one, or check_source_credentials could not test the
    credentialed half at all."""
    probe_dir = str(ROOT / 'tools')
    cases = []

    cases.append(('this process carries neither credential variable, whatever '
                  'the container set',
                  all(v not in os.environ for v in CREDENTIAL_ENV_VARS),
                  repr({v: os.environ.get(v) for v in CREDENTIAL_ENV_VARS})))

    # An ordinary fixture subprocess, spawned the way every fixture here
    # spawns one: env=dict(os.environ).
    r = subprocess.run(
        [sys.executable, '-c',
         'import json, os, sys; print(json.dumps([os.environ.get(v) for v in '
         'sys.argv[1:]]))', *CREDENTIAL_ENV_VARS],
        capture_output=True, text=True, env=dict(os.environ))
    cases.append(('a subprocess spawned with env=dict(os.environ) -- what '
                  'every fixture here does -- carries neither either',
                  r.returncode == 0 and json.loads(r.stdout or '[1]') ==
                  [None] * len(CREDENTIAL_ENV_VARS),
                  r.stdout + r.stderr))

    # THE CONTROLLING CASE: both planted, then this module imported.
    planted = {**os.environ,
               'PRECEDENT_GIT_TOKEN': 'planted-not-a-real-token',
               'PRECEDENT_SOURCE_BASE_URL': 'https://planted.invalid'}
    r2 = subprocess.run(
        [sys.executable, '-c',
         f'import sys; sys.path.insert(0, {probe_dir!r}); '
         'import json, os, verify_harness as vh; '
         'print(json.dumps([os.environ.get(v) for v in vh.CREDENTIAL_ENV_VARS]))'],
        capture_output=True, text=True, env=planted)
    tail = (r2.stdout or '').strip().splitlines()[-1:] or ['']
    cases.append(('with both variables PLANTED in the environment, importing '
                  'this module removes them -- the scrub, measured rather '
                  'than assumed',
                  r2.returncode == 0 and json.loads(tail[0] or '[1]') ==
                  [None] * len(CREDENTIAL_ENV_VARS),
                  r2.stdout[-400:] + r2.stderr[-400:]))

    # And the other direction.
    r3 = subprocess.run(
        [sys.executable, '-c',
         'import os; print(os.environ.get("PRECEDENT_GIT_TOKEN"))'],
        capture_output=True, text=True,
        env={**os.environ, 'PRECEDENT_GIT_TOKEN': 'fixture-planted'})
    cases.append(('a fixture that sets a credential EXPLICITLY still gets it '
                  '-- the scrub clears the ambient one, it does not make a '
                  'credential unreachable',
                  r3.stdout.strip() == 'fixture-planted',
                  r3.stdout + r3.stderr))

    # THE SAME SHAPE, THIRD INSTANCE: the freshness also-list. Planted and
    # measured exactly like the credential pair above, because the failure it
    # caused was worse -- a guard fixture inheriting it walked out of its own
    # temporary clone into this container's real attached repositories and
    # blocked on one it could not fetch, turning two checks red on every
    # machine that has the variable set and leaving them green everywhere
    # else.
    r4 = subprocess.run(
        [sys.executable, '-c',
         f'import sys; sys.path.insert(0, {probe_dir!r}); '
         'import os, verify_harness as vh; '
         'print(os.environ.get("PRECEDENT_FRESHNESS_ALSO"))'],
        capture_output=True, text=True,
        env={**os.environ,
             'PRECEDENT_FRESHNESS_ALSO': '/planted/repo=main'})
    tail4 = (r4.stdout or '').strip().splitlines()[-1:] or ['']
    cases.append(('with PRECEDENT_FRESHNESS_ALSO planted, importing this '
                  'module removes it too -- a guard fixture checks the '
                  'repository it built and no other',
                  r4.returncode == 0 and tail4[0] == 'None',
                  r4.stdout[-400:] + r4.stderr[-400:]))

    bad = [(c[0], c[2]) for c in cases if not c[1]]
    check(f'no fixture inherits the private-source credential or the '
          f'freshness also-list from the container ({len(cases)} stated '
          f'cases, the planted variables being the controlling ones)',
          not bad, '; '.join(f"{n} -- {d[:400]}" for n, d in bad))


def check_source_credentials():
    """tools/precedent_source_credentials.py, and the one property that
    matters most about it: the token never leaves the environment.

    The mechanism exists because `add_repo` refuses across GitHub owners
    (reproduced 2026-09-09 as a session's first tool call), so a private
    practice source has to be reachable some other way. What it cannot do is
    trade that problem for a worse one -- a secret written into a clone's
    .git/config, or into an argument list, is a secret somebody commits
    later. Cases 2, 3 and 7 are that property, asserted three ways.

    Every case here is hermetic: a file:// fixture, a fixture HOME, and a
    fixture repo whose precedent.json this test wrote
    (practice: fixture-owns-its-state). Nothing touches the network, and no
    case reads this container's own real credentials.

    NEGATIVE CONTROL, RUN 2026-09-09 rather than assumed
    (practice: control-asserts-which-failure). The helper was rewritten to
    interpolate the token's VALUE instead of its variable name, and case 2's
    "the token itself never appears in the arguments" went red, printing the
    fixture token in its own failure detail. So the case can fail, and it
    fails for the reason it claims to watch."""
    import shutil, tempfile

    sys.path.insert(0, str(ROOT / 'tools'))
    import precedent_source_credentials as psc
    import precedent_source_bootstrap as psb   # BASE_URL_ENV lives with the
    # tool that clones, not with the tool that reports -- the bootstrap has
    # to keep working in a tree vendored before the credentials module
    # existed, so it owns nothing it cannot resolve alone.

    TOKEN = 'fixture-token-never-a-real-one'
    tmp = pathlib.Path(tempfile.mkdtemp(prefix='precedent-source-cred-'))
    cases = []
    try:
        tool = ROOT / 'tools' / 'precedent_source_credentials.py'
        url = 'https://github.com/example/precedent-individual'

        # --- 1: no token, no credential flags ------------------------------
        args = psc.credential_args(url, env={})
        cases.append(('no token means no credential flags at all',
                      args == [], repr(args)))

        # --- 2: a token produces flags, and is NOT in them ------------------
        args = psc.credential_args(url, env={psc.TOKEN_ENV: TOKEN})
        joined = ' '.join(args)
        cases.append(('a token produces a helper that git can use',
                      len(args) == 4 and args[0] == '-c'
                      and 'credential.helper=' in args[1]
                      and psc.TOKEN_ENV in joined, repr(args)))
        cases.append(('the token itself never appears in the arguments -- '
                      'only the NAME of the variable git should read',
                      TOKEN not in joined, repr(args)))

        # --- 3: a hostile username cannot break out of the helper snippet ---
        args = psc.credential_args(url, env={psc.TOKEN_ENV: TOKEN,
                                             psc.TOKEN_USER_ENV: 'evil; rm -rf /'})
        cases.append(('a username that is not a plain identifier falls back '
                      'to the default rather than reaching the shell',
                      'rm -rf' not in ' '.join(args)
                      and f'username={psc.DEFAULT_TOKEN_USER}' in ' '.join(args),
                      repr(args)))
        args = psc.credential_args(url, env={psc.TOKEN_ENV: TOKEN,
                                             psc.TOKEN_USER_ENV: 'git-user_1.x'})
        cases.append(('a legitimate username override is honoured',
                      'username=git-user_1.x' in ' '.join(args), repr(args)))

        # --- 3b: the opt-in inherit mode -----------------------------------
        # Measured 2026-09-09 rather than reasoned about: `inherit` against a
        # real cross-owner private repo in this container was REFUSED by
        # GitHub ("Invalid username or token"), which is the outcome the mode
        # exists to make legible -- a credential was sent and rejected, not
        # absent. These cases assert the wiring that produced that outcome.
        inh = {psc.TOKEN_ENV: psc.INHERIT, 'GITHUB_TOKEN': TOKEN}
        cases.append(('inherit resolves to the NAME of the variable that '
                      'actually holds a token',
                      psc.token_var(inh) == 'GITHUB_TOKEN', str(psc.token_var(inh))))
        args = psc.credential_args(url, env=inh)
        joined = ' '.join(args)
        cases.append(('...and the helper interpolates THAT variable, so the '
                      'literal word "inherit" is never sent as a password',
                      'password=$GITHUB_TOKEN' in joined
                      and psc.INHERIT not in joined, repr(args)))
        cases.append(('...and the inherited token itself still never appears '
                      'in the arguments', TOKEN not in joined, repr(args)))
        empty_inh = {psc.TOKEN_ENV: psc.INHERIT}
        cases.append(('inherit with nothing to inherit is NO credential, not '
                      'the word "inherit" sent as one',
                      psc.token_var(empty_inh) is None
                      and psc.credential_args(url, env=empty_inh) == [],
                      repr(psc.credential_args(url, env=empty_inh))))
        # --- 4: only https gets the credential -----------------------------
        for scheme in (f'file://{tmp}/x', 'ssh://example.invalid/x'  # deliberately userless: a fixture URL
                       # carrying user@host reads as an email address
                       # to the leak gate, which scans this file too,
                       'http://example.com/x'):
            args = psc.credential_args(scheme, env={psc.TOKEN_ENV: TOKEN})
            cases.append((f'a {scheme.split(":")[0]}:// url is never offered '
                          f'the credential', args == [], repr(args)))

        # --- 5: assess() tells the three states apart ----------------------
        repo = tmp / 'consumer'
        (repo / 'local').mkdir(parents=True)
        home_empty = tmp / 'home-empty'
        (home_empty / '.config' / 'precedent').mkdir(parents=True)
        (home_empty / '.config' / 'precedent' / 'config.json').write_text(
            '{"format_version": 1}\n', encoding='utf-8')

        def write_cfg(team_path, level='team', name='precedent-team-fixture'):
            sources = [{'level': 'universal', 'name': 'precedent', 'path': '.'},
                       {'level': 'repo-local', 'name': 'local', 'path': 'local'}]
            if team_path is not None:
                sources.insert(1, {'level': level, 'name': name,
                                   'path': team_path})
            (repo / 'precedent.json').write_text(
                json.dumps({'format_version': 1, 'sources': sources}), encoding='utf-8')

        # A set declared the CURRENT way, "level": "shared", and missing.
        # Until 2026-09-29 only the old spelling "team" was read here, so this
        # set was skipped and never reported missing -- the retired word hid
        # the bug. Both spellings must be reported.
        write_cfg('../precedent-shared-fixture', level='shared',
                  name='precedent-shared-fixture')
        why = psc.unresolved_private_sources(repo, env={'HOME': str(home_empty)})
        cases.append(('a missing set declared as level "shared" is reported '
                      'missing, by name, as a shared set',
                      any(lv == 'shared' and n == 'precedent-shared-fixture'
                          for lv, n, _ in why), str(why)))
        write_cfg('../precedent-team-fixture')
        why = psc.unresolved_private_sources(repo, env={'HOME': str(home_empty)})
        cases.append(('...and one declared with the old spelling "team" still is',
                      any(n == 'precedent-team-fixture' for _, n, _ in why),
                      str(why)))
        env_no_token = {'HOME': str(home_empty)}
        verdict, message = psc.assess(repo, env=env_no_token)
        cases.append(('an unresolved private source with no token reads as '
                      'MISSING, and the message names the variable to set',
                      verdict == 'missing' and psc.TOKEN_ENV in message,
                      f'{verdict}: {message}'))

        verdict, message = psc.assess(repo, env={**env_no_token, psc.TOKEN_ENV: TOKEN})
        cases.append(('the same repo WITH a token reads as SET -- a missing '
                      'credential is explicitly not the explanation',
                      verdict == 'set' and 'not the explanation' in message,
                      f'{verdict}: {message}'))
        # The session check's row on that verdict. Until 2026-10-02 it passed
        # on SET with an empty detail, so a declared set that did not exist
        # showed green while its practices were absent all session.
        import precedent_session_check as psck
        unresolved = psc.unresolved_private_sources(
            repo, env={**env_no_token, psc.TOKEN_ENV: TOKEN})
        name, ok, detail = psck.sources_resolved_row(verdict, message,
                                                     unresolved)
        cases.append(('...and the session check FAILS its sources row on SET '
                      'when a DECLARED shared set did not resolve, naming it '
                      '-- a token being set never makes a missing set green',
                      ok is False and 'precedent-team-fixture' in detail,
                      f'{ok}: {detail}'))
        only_ind = [('individual', 'precedent-individual', 'no config')]
        cases.append(('...but SET with only the individual set unresolved '
                      'passes, with its message: a token alone is read as a '
                      'sign of an individual set the person may not have',
                      psck.sources_resolved_row('set', 'why', only_ind)[1:]
                      == (True, 'why'),
                      str(psck.sources_resolved_row('set', 'why', only_ind))))
        cases.append(('...while OK passes silently and UNCONFIGURED passes '
                      'with its message',
                      psck.sources_resolved_row('ok', 'x')[1:] == (True, '')
                      and psck.sources_resolved_row('unconfigured', 'why')[1:]
                      == (True, 'why'),
                      str((psck.sources_resolved_row('ok', 'x'),
                           psck.sources_resolved_row('unconfigured', 'why')))))
        cases.append(('...and MISSING fails with its message',
                      psck.sources_resolved_row('missing', 'why')[1:]
                      == (False, 'why'),
                      str(psck.sources_resolved_row('missing', 'why'))))

        verdict, message = psc.assess(repo, env={**env_no_token, **empty_inh})
        cases.append(('...and assess says which of the two missing states it '
                      'is: asked to inherit, nothing there',
                      verdict == 'missing' and 'nothing to inherit' in message,
                      f'{verdict}: {message}'))
        verdict, message = psc.assess(repo, env={**env_no_token, **inh})
        cases.append(('an inherited credential reads as SET and names where '
                      'it came from, since a harness token is usually scoped '
                      'to other repositories and will be refused',
                      verdict == 'set' and 'inherited from GITHUB_TOKEN' in message,
                      f'{verdict}: {message}'))

        # both sources genuinely present -> nothing to say
        team = tmp / 'precedent-team-fixture'
        (team / 'practices').mkdir(parents=True)
        indiv = tmp / 'indiv'
        (indiv / 'practices').mkdir(parents=True)
        home_ok = tmp / 'home-ok'
        (home_ok / '.config' / 'precedent').mkdir(parents=True)
        (home_ok / '.config' / 'precedent' / 'config.json').write_text(
            json.dumps({'format_version': 1,
                        'individual': {'name': 'precedent-individual',
                                       'path': str(indiv)}}), encoding='utf-8')
        verdict, _ = psc.assess(repo, env={'HOME': str(home_ok)})
        cases.append(('every private source on disk reads as ok, with or '
                      'without a token', verdict == 'ok', verdict))
        cases.append(('and remind() then says nothing at all, so the tools '
                      'that call it stay quiet',
                      psc.remind(repo, env={'HOME': str(home_ok)}) is None,
                      str(psc.remind(repo, env={'HOME': str(home_ok)}))))

        # --- 5b: the THREE ways there is no individual source ---------------
        # Reported 2026-09-13 from a live container: PRECEDENT_GIT_TOKEN set,
        # the private repo reachable, nothing retired, and no user config at
        # all -- and this tool answered "<path> declares no individual
        # source", a statement about a file that did not exist, wrapped in a
        # credential remedy and a retirement clause neither of which applied.
        # An absent config, a malformed one and one that parses and names
        # none are three states with three remedies; `.get('individual')`
        # made them one. Each case below asserts the words ITS branch alone
        # prints (practice: control-asserts-which-failure).
        #
        # Every env here is a literal dict, so the fixture owns whether this
        # is a hosted session -- which is the axis the verdict turns on.
        home_absent = tmp / 'home-absent'          # never created: that is the case
        home_bad = tmp / 'home-bad'
        (home_bad / '.config' / 'precedent').mkdir(parents=True)
        (home_bad / '.config' / 'precedent' / 'config.json').write_text(
            '{not json', encoding='utf-8')

        for home, state, words in (
            (home_absent, 'absent', 'does not exist'),
            (home_bad, 'malformed', 'did not parse as JSON'),
            (home_empty, 'declares none', 'declares no individual source'),
        ):
            # The repo-name variable is the sign that this person HAS an
            # individual set; without any such sign a missing set is "none"
            # (asserted separately, just below).
            why = psc.unresolved_private_sources(
                repo, env={'HOME': str(home), 'PRECEDENT_INDIVIDUAL_REPO': 'file:///fixture/precedent-individual'})
            cases.append((f'a user config that is {state} is REPORTED as '
                          f'{state}, not as "declares no individual source" '
                          f'for all three', any(words in w for _, _, w in why),
                          str(why)))

        why = psc.unresolved_private_sources(
            repo, env={'HOME': str(home_absent), 'CLAUDE_CODE_REMOTE': 'true'})
        cases.append(('on a hosted session with no user config and NO sign of an individual set '
                      '(no token, base URL, repo name or clone), nothing is '
                      'reported unresolved -- the person has none',
                      why == [], str(why)))

        for home, state, words in (
            (home_absent, 'an absent', 'does not exist at all'),
            (home_bad, 'a malformed', 'did not parse as JSON'),
            (home_empty, 'a declares-nothing', 'names no individual source'),
        ):
            verdict, message = psc.assess(repo, env={'HOME': str(home),
                                                     psc.TOKEN_ENV: TOKEN})
            cases.append((f'...and on a local machine {state} config reads '
                          f'as UNCONFIGURED with its own remedy -- never as a '
                          f'credential or a retirement, which cannot write a '
                          f'config file',
                          verdict == 'unconfigured' and words in message
                          and 'RETIRED' not in message,
                          f'{verdict}: {message[:260]}'))

        # A config that will not PARSE is the one state no credential has
        # ever fixed, so it reads the same way on a hosted session too.
        verdict, message = psc.assess(repo, env={'HOME': str(home_bad),
                                                 'CLAUDE_CODE_REMOTE': 'true',
                                                 psc.TOKEN_ENV: TOKEN})
        cases.append(('a config that will not parse is UNCONFIGURED on a '
                      'hosted session as well: a token cannot repair a '
                      'syntax error', verdict == 'unconfigured', verdict))

        # ...while the two states a FAILED CLONE also leaves behind keep the
        # access path there, because the bootstrap writes the config only
        # after a clone succeeds. Claiming "not an access problem" there
        # would be the same over-reading in the other direction.
        for home, state in ((home_absent, 'an absent'),
                            (home_empty, 'a declares-nothing')):
            verdict, message = psc.assess(repo, env={'HOME': str(home),
                                                     'CLAUDE_CODE_REMOTE': 'true',
                                                     psc.TOKEN_ENV: TOKEN})
            cases.append((f'on a HOSTED session {state} config is NOT '
                          f'claimed to be free of access trouble -- it is '
                          f'what a failed clone leaves -- but the retirement '
                          f'clause goes, since no repo declares an individual '
                          f'source',
                          verdict == 'set' and 'RETIRED' not in message
                          and 'only after a clone SUCCEEDS' in message,
                          f'{verdict}: {message[:260]}'))

        # The one individual failure that IS about access: the config named a
        # path and the clone is not at it. Unchanged, retirement clause and all.
        home_gone = tmp / 'home-gone'
        (home_gone / '.config' / 'precedent').mkdir(parents=True)
        (home_gone / '.config' / 'precedent' / 'config.json').write_text(
            json.dumps({'individual': {'name': 'precedent-individual',
                                       'path': str(tmp / 'nowhere')}}),
            encoding='utf-8')
        verdict, message = psc.assess(repo, env={'HOME': str(home_gone),
                                                 psc.TOKEN_ENV: TOKEN})
        cases.append(('a config that DOES declare a source whose clone is '
                      'missing still reads as an access problem, retirement '
                      'clause and all -- the new verdict must not swallow it',
                      verdict == 'set' and 'RETIRED' in message
                      and 'has no practices/ directory' in message,
                      f'{verdict}: {message[:260]}'))

        # --- 5c: PRECEDENT_USER_CONFIG is honoured here too -----------------
        # It was not, until 2026-09-13, and this file was the ONLY reporter in
        # the engine that ignored it: precedent_resolve.py,
        # precedent_session_check.py, precedent_identity.py and
        # precedent_time.py all read it. So somebody who had pointed it at a
        # good config was told the DEFAULT path declared no individual source
        # -- a false alarm naming a file they had deliberately not used.
        elsewhere = tmp / 'elsewhere-config.json'
        elsewhere.write_text(json.dumps(
            {'individual': {'name': 'precedent-individual', 'path': str(indiv)}}),
            encoding='utf-8')
        verdict, message = psc.assess(repo, env={'HOME': str(home_absent),
                                                 psc.USER_CONFIG_ENV: str(elsewhere),
                                                 psc.TOKEN_ENV: TOKEN})
        cases.append((f'{psc.USER_CONFIG_ENV} points the individual lookup at '
                      f'another config, exactly as it does everywhere else in '
                      f'the engine -- a good config there reads as OK, not as '
                      f'a complaint about the default path',
                      verdict == 'ok', f'{verdict}: {message[:200]}'))
        path, code = psc.individual_config_state({'HOME': str(home_absent),
                                                  psc.USER_CONFIG_ENV: str(elsewhere)})
        cases.append(('...and the path it reports is the one it actually '
                      'read', path == elsewhere and code == 'declared',
                      f'{path} {code}'))

        # --- 6: the CLI's own contract -------------------------------------
        def run(*args, env_extra=None):
            # Scrub BOTH credential variables, not just the token. A case
            # below asserts what happens with NO base url, and this harness
            # runs in a container that normally HAS one -- so the subprocess
            # inherited a real base url, tried to clone from github.com, and
            # failed on "could not read Username" instead of reporting the
            # variable as unset. The case was testing a state the fixture had
            # never established (practice: fixture-owns-its-state). Any case
            # that wants either variable supplies it through env_extra, which
            # is the only way to tell "the fixture set this" from "the
            # container happened to carry it".
            #
            # CLAUDE_CODE_REMOTE and PRECEDENT_USER_CONFIG are scrubbed for
            # the same reason, added 2026-09-13 with the config-state
            # verdict below: assess() now branches on whether this is a
            # hosted session, and resolves the user config through
            # PRECEDENT_USER_CONFIG when it is set. A container that carries
            # either -- this one carries CLAUDE_CODE_REMOTE=true -- would
            # decide the outcome of cases the fixture believes it set up
            # with HOME alone, and the harness would pass here and fail on
            # somebody's laptop. An ABSENCE is state the fixture owns too.
            env = dict(os.environ)
            env.pop(psc.TOKEN_ENV, None)
            env.pop(psb.BASE_URL_ENV, None)
            env.pop('CLAUDE_CODE_REMOTE', None)
            env.pop(psc.USER_CONFIG_ENV, None)
            if env_extra:
                env.update(env_extra)
            r = subprocess.run([sys.executable, *args], capture_output=True,
                               text=True, env=env)
            return r.returncode, r.stdout + r.stderr

        # CLAUDE_CODE_REMOTE is set BY THE FIXTURE, not inherited: on a
        # hosted session an empty user config is also what a clone that
        # failed for want of a credential leaves behind, so MISSING is the
        # right reading there and 'unconfigured' is the right reading on a
        # local machine. Both are asserted, a few lines apart.
        hosted = {'HOME': str(home_empty), 'CLAUDE_CODE_REMOTE': 'true',
                  'PRECEDENT_INDIVIDUAL_REPO': 'file:///fixture/precedent-individual'}
        rc, out = run(str(tool), '--repo', str(repo), env_extra=hosted)
        cases.append(('the CLI reports MISSING and still exits 0 -- a missing '
                      'credential degrades a session, never takes one down',
                      rc == 0 and 'MISSING' in out, f'rc={rc} {out[:300]}'))
        rc, out = run(str(tool), '--repo', str(repo), '--check',
                      env_extra=hosted)
        cases.append(('--check is the one caller that exits 1 on MISSING',
                      rc == 1 and 'MISSING' in out, f'rc={rc} {out[:300]}'))
        rc, out = run(str(tool), '--repo', str(repo), '--check',
                      env_extra={'HOME': str(home_empty)})
        cases.append(('...but the SAME state on a local machine is '
                      'UNCONFIGURED and exits 0: nothing there is in the '
                      'wrong state, and no credential is what is missing',
                      rc == 0 and 'UNCONFIGURED' in out, f'rc={rc} {out[:300]}'))
        rc, out = run(str(tool), '--repo', str(repo), '--check',
                      env_extra={'HOME': str(home_ok)})
        cases.append(('--check exits 0 when every source is on disk '
                      '(the negative control: this case must be able to fail '
                      'the one above)', rc == 0 and 'OK' in out,
                      f'rc={rc} {out[:300]}'))

        # --- 7: end to end, the token never reaches disk --------------------
        source = tmp / 'source-repo'
        source.mkdir()
        for cmd in (['init', '-q'], ['config', 'user.email', 'harness@example.com'],
                    ['config', 'user.name', 'harness']):
            subprocess.run(['git', '-C', str(source), *cmd], check=True,
                           capture_output=True, text=True)
        (source / 'practices').mkdir()
        (source / 'practices' / 'p.md').write_text('fixture\n', encoding='utf-8')
        subprocess.run(['git', '-C', str(source), 'add', '-A'], check=True,
                       capture_output=True, text=True)
        subprocess.run(['git', '-C', str(source), 'commit', '-qm', 'seed'],
                       check=True, capture_output=True, text=True)

        bootstrap = ROOT / 'tools' / 'precedent_source_bootstrap.py'
        clone, config = tmp / 'clone', tmp / 'cfg.json'
        rc, out = run(str(bootstrap), '--level', 'individual', '--name',
                      'precedent-individual', '--repo-url', f'file://{source}',
                      '--clone', str(clone), '--config', str(config),
                      '--remote-only', 'false',
                      env_extra={psc.TOKEN_ENV: TOKEN})
        cloned = (clone / 'practices' / 'p.md').is_file()
        on_disk = ''
        for f in (clone / '.git' / 'config', config):
            if f.is_file():
                on_disk += f.read_text(encoding='utf-8')
        cases.append(('the bootstrap clones with a token set, and the token '
                      'is in NEITHER the clone\'s git config NOR the config '
                      'file it writes', rc == 0 and cloned and TOKEN not in on_disk,
                      f'rc={rc} cloned={cloned} {out[:300]}'))

        # --- 8: a shared source is cloned by path, and records nothing --------
        # A real repo to clone FROM, named the way the set is named: the URL
        # is built as <base>/<name>, which is the whole convention under test.
        remotes = tmp / 'remotes'
        remotes.mkdir()
        subprocess.run(['git', 'clone', '-q', f'file://{source}',
                        str(remotes / 'precedent-team-fixture')], check=True,
                       capture_output=True, text=True)
        write_cfg('../team-fixture-clone')
        rc, out = run(str(bootstrap), '--teams-from', str(repo),
                      '--remote-only', 'false',
                      env_extra={psb.BASE_URL_ENV: f'file://{remotes}',
                                 'HOME': str(home_empty)})
        # the fixture set is named precedent-team-fixture, so file://<tmp>/precedent-team-fixture
        cases.append(('--teams-from clones each declared shared source to the '
                      'sibling path the repo declares',
                      rc == 0 and (repo.parent / 'team-fixture-clone' / 'practices').is_dir(),
                      f'rc={rc} {out[:400]}'))
        cases.append(('...and writes no user config for it: a shared source '
                      'resolves by path, so there is nothing to record',
                      not (home_empty / '.config' / 'precedent' / 'config.json')
                      .read_text(encoding='utf-8').count('team'),
                      (home_empty / '.config' / 'precedent' / 'config.json')
                      .read_text(encoding='utf-8')))

        # --- 9: no base url is REPORTED, never silently skipped -------------
        shutil.rmtree(repo.parent / 'team-fixture-clone', ignore_errors=True)
        rc, out = run(str(bootstrap), '--teams-from', str(repo),
                      '--remote-only', 'false', env_extra={'HOME': str(home_empty)})
        cases.append(('with no base url the shared source is named on stderr as '
                      'NOT in force, rather than passing quietly',
                      rc == 0 and psb.BASE_URL_ENV in out
                      and 'NOT in force' in out, f'rc={rc} {out[:300]}'))

        # --- 9b: a failed clone names WHICH failure it was -----------------
        # Each branch asserts the words that branch alone prints
        # (practice: control-asserts-which-failure): "it failed" is the
        # report that sends somebody to re-issue a credential that was fine.
        # The two live strings were taken from real git output against
        # github.com on 2026-09-09, not invented -- one with no credential,
        # one with a deliberately invalid PRECEDENT_GIT_TOKEN.
        for output, want in (
            ("fatal: could not read Username for 'https://github.com': "
             "terminal prompts disabled", 'NO CREDENTIAL was available'),
            ('remote: Invalid username or token. Password authentication is '
             'not supported for Git operations.', 'AUTHENTICATION was refused'),
            ('remote: Repository not found.', 'NOT FOUND'),
            ('error: some unrelated network thing', 'it'),
        ):
            got = psb._diagnose(output)
            cases.append((f'a clone failure reading {output[:38]!r} is '
                          f'diagnosed as {want!r}, not merely as a failure',
                          # the fallback is asserted as an EXACT value: 'it'
                          # is a substring of half the English language, so
                          # `want in got` would pass on any branch at all.
                          (got == want if want == 'it' else want in got), got))

        # --- 10: the announced degradation when the module is not vendored --
        lonely = tmp / 'lonely-tools'
        lonely.mkdir()
        shutil.copy(bootstrap, lonely / bootstrap.name)
        rc, out = run(str(lonely / bootstrap.name), '--level', 'individual',
                      '--name', 'x', '--repo-url', f'file://{source}',
                      '--clone', str(tmp / 'clone2'), '--config', str(tmp / 'c2.json'),
                      '--remote-only', 'false', env_extra={psc.TOKEN_ENV: TOKEN})
        cases.append(('a bootstrap vendored WITHOUT the credentials module '
                      'says so when a token is set, naming the file and the '
                      'remedy -- it does not ignore the token in silence',
                      'precedent_source_credentials.py is not beside this file' in out
                      and 'precedent_vendor_engine.py refresh' in out,
                      f'rc={rc} {out[:400]}'))
    finally:
        shutil.rmtree(tmp, ignore_errors=True)

    bad = [(c[0], c[2]) for c in cases if not c[1]]
    check(f'the private-source credential never reaches disk or argv, and its '
          f'absence is reported ({len(cases)} stated cases)',
          not bad, '; '.join(f"{n} -- {d[:600]}" for n, d in bad))


def check_hosted_sessions_resolve_without_attaching_a_repo():
    """Two ways a hosted session resolves its sources with no human in the
    loop, added together on 2026-09-29 after a consumer's sessions were told
    at start to attach a private shared set by hand (the person saw an
    unexplained permission prompt and refused it) and printed an
    individual-set warning above every reply for a person who had declined
    one.

    1. With no sign of an individual set in the environment (no token,
       base URL, repo name or clone), unresolved_private_sources expects
       none; each sign on its own restores the expectation.
    2. checkin.py --source, with the consumer's `vendor_practices` opt-in,
       mirrors the set's practices/ and precedent-source.json beside its
       code; without the opt-in it still mirrors code only.
    3. _stamp_synced_from writes to the manifest of the source being
       checked in, never to the universal manifest."""
    import shutil, tempfile, importlib
    sys.path.insert(0, str(ROOT / 'tools'))
    import precedent_source_credentials as psc
    tmp = pathlib.Path(tempfile.mkdtemp(prefix='hosted-no-attach-'))
    cases = []
    try:
        repo = tmp / 'consumer'
        repo.mkdir()
        (repo / 'precedent.json').write_text('{"sources": []}', encoding='utf-8')
        home = tmp / 'home'
        home.mkdir()
        base = {'HOME': str(home), 'CLAUDE_CODE_REMOTE': 'true',
                'PRECEDENT_USER_CONFIG': str(home / 'absent.json')}
        none_seen = psc.unresolved_private_sources(repo, env=dict(base))
        cases.append(('with no user config and no sign of an individual set, '
                      'nothing is expected', none_seen == [], repr(none_seen)))
        for var in psc.INDIVIDUAL_SIGNAL_ENVS:
            seen = psc.unresolved_private_sources(repo, env={**base, var: 'x'})
            cases.append((f'{var} set is a sign of an individual set, so its '
                          f'absence is reported',
                          [u[0] for u in seen] == ['individual'], repr(seen)))
        clone = home / 'precedent-individual' / 'practices'
        clone.mkdir(parents=True)
        seen = psc.unresolved_private_sources(repo, env=dict(base))
        cases.append(('an individual clone on disk with no config is a sign '
                      'too, so the missing config is reported',
                      [u[0] for u in seen] == ['individual'], repr(seen)))

        import checkin
        for opted, want in ((False, {'filing'}),
                            (True, {'filing', 'practices',
                                    'precedent-source.json'})):
            importlib.reload(checkin)
            clone = tmp / f'set-{opted}'
            (clone / 'filing').mkdir(parents=True)
            (clone / 'practices').mkdir()
            (clone / 'filing' / 'engine.py').write_text('x = 1\n')
            (clone / 'practices' / 'rule.md').write_text('rule\n')
            (clone / 'precedent-source.json').write_text(json.dumps(
                {'name': 'fixture-set', 'level': 'shared', 'code': ['filing']}))
            host = tmp / f'host-{opted}'
            (host / 'process').mkdir(parents=True)
            checkin.ROOT = host
            checkin._select_source('fixture-set')
            checkin.MANIFEST.write_text(json.dumps(
                {'upstream': {'vendor_practices': True} if opted else {}}))
            checkin._bind_source(clone)
            got = {f.parts[0] for f in checkin._files(clone)}
            cases.append((f'vendor_practices={opted}: the mirror is '
                          f'{sorted(want)}', got == want, repr(sorted(got))))
            (host / 'process' / 'manifest.json').write_text('{}')
            checkin._stamp_synced_from('abc1234def')
            own = json.loads(checkin.MANIFEST.read_text())
            uni = json.loads((host / 'process' / 'manifest.json').read_text())
            cases.append((f'vendor_practices={opted}: synced_from lands in the '
                          f"set's own manifest, not the universal one",
                          own.get('upstream', {}).get('synced_from') == 'abc1234def'
                          and 'upstream' not in uni, f'{own} / {uni}'))
    finally:
        shutil.rmtree(tmp, ignore_errors=True)
        # _select_source/_bind_source rebind checkin's module state (ROOT,
        # CODE_DIRS); a later case in this process must get a fresh module.
        if 'checkin' in sys.modules:
            importlib.reload(sys.modules['checkin'])
    bad = [(c[0], c[2]) for c in cases if not c[1]]
    check(f'a hosted session resolves its sources without attaching a repo by '
          f'hand ({len(cases)} stated cases)',
          not bad, '; '.join(f"{n} -- {d[:400]}" for n, d in bad))


def check_vendored_engine_reads_the_consumer_root():
    """An engine copy vendored INSIDE another repo reads that repo's
    precedent.json -- not the vendored tree's own copy of BestPractice's.

    THE INCIDENT (practice: cite-the-incident). 2026-09-14, `Update Vendors`
    in a consumer on the classic layout: engine at `process/upstream/tools/`,
    the consumer's precedent.json two levels above it. Both runbook steps that
    reconcile sources default `--repo` to the engine's own parent, and the
    vendored tree -- being a whole copy of this repository -- HAS a
    precedent.json there. So step 7 reported three declared shared sources
    missing, by name, at `<consumer>/process/precedent-team-*`, and step 8
    left the same three UNVERIFIED. Both readings were false, both were
    specific enough to be believed, and the runbook passes no --repo.

    Hermetic: every path below is a directory this test created, and the
    helper is called with an explicit engine_root, so nothing reads this
    container's own layout (practice: fixture-owns-its-state).

    NEGATIVE CONTROL, RUN 2026-09-14 rather than assumed
    (practice: control-asserts-which-failure). `consuming_repo_root` was
    replaced with its own pre-fix behaviour -- return the engine root
    unconditionally -- and case 1 went red against the same fixture, printing
    `<consumer>/process/upstream` as its detail. So the case can fail, it
    fails on the condition it claims to watch rather than on an absent
    fixture, and its failure detail names the wrong root out loud."""
    import shutil, tempfile

    sys.path.insert(0, str(ROOT / 'tools'))
    import precedent_source_credentials as psc

    tmp = pathlib.Path(tempfile.mkdtemp(prefix='precedent-vendored-root-'))
    cases = []
    try:
        consumer = tmp / 'consumer'
        engine = consumer / 'process' / 'upstream'
        (engine / 'tools').mkdir(parents=True)
        (consumer / 'process' / 'manifest.json').write_text(json.dumps(
            {'upstream': {'vendored_at': 'process/upstream'}}), encoding='utf-8')
        # Both precedent.json files exist, which is the whole trap: the wrong
        # one parses fine and declares sources at paths nothing resolves.
        (consumer / 'precedent.json').write_text(json.dumps(
            {'format_version': 1, 'sources': []}), encoding='utf-8')
        (engine / 'precedent.json').write_text(json.dumps(
            {'format_version': 1, 'sources': []}), encoding='utf-8')

        got = psc.consuming_repo_root(engine)
        cases.append(('a vendored engine resolves to the CONSUMING repo root, '
                      'not to the vendored tree it sits in',
                      got == consumer.resolve(), str(got)))

        # --- 2: a repo that is not a vendoring consumer is untouched --------
        plain = tmp / 'plain'
        (plain / 'tools').mkdir(parents=True)
        got = psc.consuming_repo_root(plain / 'tools')
        cases.append(('a repo with no vendoring manifest keeps the old '
                      'default, so a practice set behaves exactly as before',
                      got == (plain / 'tools').resolve(), str(got)))

        # --- 3: a manifest that does NOT claim this tree is not believed ----
        other = tmp / 'other'
        other_engine = other / 'process' / 'upstream'
        (other_engine / 'tools').mkdir(parents=True)
        (other / 'process' / 'manifest.json').write_text(json.dumps(
            {'upstream': {'vendored_at': 'process/somewhere-else'}}),
            encoding='utf-8')
        got = psc.consuming_repo_root(other_engine)
        cases.append(('a manifest whose vendored_at points somewhere else is '
                      'not read as a claim on this tree',
                      got == other_engine.resolve(), str(got)))

        # --- 4: a malformed manifest fails soft rather than raising ---------
        bad = tmp / 'bad'
        bad_engine = bad / 'process' / 'upstream'
        (bad_engine / 'tools').mkdir(parents=True)
        (bad / 'process' / 'manifest.json').write_text('{not json',
                                                       encoding='utf-8')
        got = psc.consuming_repo_root(bad_engine)
        cases.append(('an unreadable manifest degrades to the old default '
                      'instead of taking the tool down',
                      got == bad_engine.resolve(), str(got)))
    finally:
        shutil.rmtree(tmp, ignore_errors=True)

    bad_cases = [(c[0], c[2]) for c in cases if not c[1]]
    check(f'a vendored engine copy reads the consuming repo\'s sources '
          f'({len(cases)} stated cases)',
          not bad_cases,
          '; '.join(f'{n} -- {d[:400]}' for n, d in bad_cases))


def check_source_clone_keeps_its_credential():
    """A synced source clone carries the credential helper in its OWN config,
    so git commands run inside it later can authenticate too.

    THE INCIDENT (practice: cite-the-incident), 2026-09-11.
    precedent_source_credentials.credential_args covers exactly one git
    invocation -- the clone. The clone it produces remembered nothing of it,
    so every later command inside it met a private remote with no credential
    and failed on `could not read Username for 'https://github.com'` with
    PRECEDENT_GIT_TOKEN sitting right there in the environment. Because
    PRECEDENT_FRESHNESS_ALSO names those clones, the freshness guard's
    pre-write mode fetched each one, failed, and blocked -- and blocked again
    on every retry, since its once-per-session sentinel is only written after
    the checks pass. A session could run nothing but `git` for its first six
    tool calls, and the block named the SOURCE's branch while the project dir
    sat on another, so it read as the project's own checkout being broken.

    Case 4 is the one that would have caught it: not "a helper is configured"
    but "git, run plainly inside the clone with no -c flags, actually answers
    with the credential". `git credential fill` is that question asked
    directly, and it needs no network.

    TWO NEGATIVE CONTROLS, RUN 2026-09-11 rather than assumed, because the
    two halves fail independently (practice: control-asserts-which-failure).
    Neutering persist_credential_helper so it writes nothing turned cases
    2, 3 and 4 red -- and case 4 failed printing
    `fatal: could not read Username for 'https://github.com'`, which is the
    incident's own message, from git, unprompted. Separately, deleting
    _persist_credential's call from ensure_source turned only case 5's two
    red, with everything else green: the helper still worked, nothing
    called it.

    Hermetic: a file:// origin for the clone, an https remote written into
    it afterwards to exercise the https-only rule, a fixture token, and a
    fixture HOME. No network."""
    import shutil, tempfile

    sys.path.insert(0, str(ROOT / 'tools'))
    import precedent_source_credentials as psc
    import precedent_source_bootstrap as psb

    TOKEN = 'fixture-token-never-a-real-one'
    tmp = pathlib.Path(tempfile.mkdtemp(prefix='precedent-clone-cred-'))
    cases = []
    try:
        source = tmp / 'source-repo'
        source.mkdir()
        for cmd in (['init', '-q', '-b', 'main'],
                    ['config', 'user.email', 'harness@example.com'],
                    ['config', 'user.name', 'harness']):
            subprocess.run(['git', '-C', str(source), *cmd], check=True,
                           capture_output=True, text=True)
        (source / 'practices').mkdir()
        (source / 'practices' / 'p.md').write_text('fixture\n', encoding='utf-8')
        subprocess.run(['git', '-C', str(source), 'add', '-A'], check=True,
                       capture_output=True, text=True)
        subprocess.run(['git', '-C', str(source), 'commit', '-qm', 'seed'],
                       check=True, capture_output=True, text=True)

        env = {psc.TOKEN_ENV: TOKEN}
        https = 'https://github.com/example/precedent-individual'

        # --- 1: nothing to persist is not a failure, and writes nothing -----
        quiet = tmp / 'quiet'
        subprocess.run(['git', 'clone', '-q', f'file://{source}', str(quiet)],
                       check=True, capture_output=True, text=True)
        wrote = psc.persist_credential_helper(quiet, f'file://{source}', env=env)
        got = subprocess.run(['git', '-C', str(quiet), 'config', '--get-all',
                              'credential.helper'], capture_output=True, text=True)
        cases.append(('a non-https remote is never given the credential, and '
                      'nothing is written into its config',
                      wrote is False and got.stdout.strip() == '',
                      f'wrote={wrote} config={got.stdout!r}'))
        cases.append(('no token means nothing is written either',
                      psc.persist_credential_helper(quiet, https, env={}) is False,
                      'persist returned truthy with an empty environment'))

        # --- 2..4: an https remote gets a usable, secret-free helper --------
        clone = tmp / 'clone'
        subprocess.run(['git', 'clone', '-q', f'file://{source}', str(clone)],
                       check=True, capture_output=True, text=True)
        subprocess.run(['git', '-C', str(clone), 'remote', 'set-url', 'origin',
                        https], check=True, capture_output=True, text=True)
        wrote = psc.persist_credential_helper(clone, https, env=env)
        cfg = (clone / '.git' / 'config').read_text(encoding='utf-8')
        cases.append(('an https remote gets the helper written into the '
                      "clone's own config", wrote is True
                      and psc.TOKEN_ENV in cfg, f'wrote={wrote} {cfg[-400:]}'))
        cases.append(('...and the token itself is NOT in that config -- only '
                      'the NAME of the variable git should read',
                      TOKEN not in cfg, cfg[-400:]))

        # --- 3: idempotent. A session-start hook runs this every session ----
        for _ in range(3):
            psc.persist_credential_helper(clone, https, env=env)
        entries = subprocess.run(['git', '-C', str(clone), 'config', '--get-all',
                                  'credential.helper'], capture_output=True,
                                 text=True).stdout.splitlines()
        cases.append(('re-running does not accumulate helper entries: the '
                      'empty reset plus one helper, however many times it runs',
                      len(entries) == 2 and entries[0] == ''
                      and entries[1].startswith('!f()'),
                      f'{len(entries)} entrie(s): {entries!r}'))

        # --- 4: git, run PLAINLY inside the clone, answers with the token ---
        # The property the incident was about. No -c flags, no credential
        # args -- just git, in that directory, the way a hook or a person
        # runs it. `credential fill` asks git the same question a fetch asks
        # and needs no network.
        filled = subprocess.run(
            ['git', '-C', str(clone), 'credential', 'fill'],
            input='protocol=https\nhost=github.com\n\n',
            capture_output=True, text=True,
            env={**os.environ, psc.TOKEN_ENV: TOKEN,
                 'GIT_TERMINAL_PROMPT': '0'})
        cases.append(('git run plainly inside the clone -- no -c flags -- '
                      'answers with the credential from the environment',
                      f'password={TOKEN}' in filled.stdout
                      and f'username={psc.DEFAULT_TOKEN_USER}' in filled.stdout,
                      f'rc={filled.returncode} {filled.stdout[:200]} '
                      f'{filled.stderr[:200]}'))

        # --- 5: the bootstrap actually calls it, on EVERY successful sync ---
        # The wiring, which is the half a unit test of the helper cannot
        # reach. It is asserted by recording the call rather than by reading
        # the resulting config, because ensure_source can only be exercised
        # hermetically against a file:// origin -- and a file:// origin is
        # exactly the case that correctly gets no credential (case 1). So the
        # https behaviour is cases 2-4's to prove, and this is only "the
        # bootstrap asks".
        #
        # Both halves matter. A FRESH clone needs it or the clone is unusable
        # tomorrow; an EXISTING one needs it or every clone made before this
        # landed stays broken forever, which is most of the ones on disk.
        calls = []
        original = psb._persist_credential
        psb._persist_credential = lambda c, u: calls.append((str(c), u))
        try:
            fresh = tmp / 'fresh'
            ok_fresh, _ = psb.ensure_source(
                'individual', 'precedent-individual', f'file://{source}',
                fresh, tmp / 'cfg.json', branch='main')
            existing = tmp / 'existing'
            subprocess.run(['git', 'clone', '-q', f'file://{source}',
                            str(existing)], check=True, capture_output=True,
                           text=True)
            ok_existing, _ = psb.ensure_source(
                'individual', 'precedent-individual', f'file://{source}',
                existing, tmp / 'cfg.json', branch='main')
        finally:
            psb._persist_credential = original
        cases.append(('a FRESH clone is offered the helper',
                      ok_fresh and (str(fresh), f'file://{source}') in calls,
                      f'ok={ok_fresh} calls={calls!r}'))
        cases.append(('and so is an EXISTING one, on every later sync -- '
                      'which is the repair path for every clone made before '
                      'this landed',
                      ok_existing and (str(existing), f'file://{source}') in calls,
                      f'ok={ok_existing} calls={calls!r}'))
    finally:
        shutil.rmtree(tmp, ignore_errors=True)

    bad = [(c[0], c[2]) for c in cases if not c[1]]
    check(f'a synced source clone keeps the credential helper in its own '
          f'config, with no secret in it ({len(cases)} stated cases)',
          not bad, '; '.join(f"{n} -- {d[:600]}" for n, d in bad))


def check_source_credentials_reach_clones_nothing_syncs():
    """The two paths a source clone actually takes at session start, neither
    of which run_sync's persist could reach.

    THE INCIDENT (practice: cite-the-incident), 2026-09-11, HOURS AFTER the
    persist above landed and with every one of its five cases green. Four
    private sources sat on disk, PRECEDENT_GIT_TOKEN was set, and not one
    clone carried a helper: the freshness guard fetched each, failed, and
    refused every non-git tool call of the session -- the identical failure
    the persist was written to end.

    The persist was real; the paths were wrong. run_sync called it, and:

      * sources_from_repo's ALREADY-ON-DISK branch calls _try_sync directly and
        never enters run_sync -- so every team clone after its first session
        was synced and left credential-less.
      * the individual source is not synced at session start while it looks
        usable at all: session-start.sh leaves it to precedent_resolve.py's
        self-heal, which a healthy clone never triggers. Nothing syncs it, so
        no sync-time repair can reach it.

    Case 5 of the check above covers ensure_source, passed throughout, and
    was blind to both -- which is why this is a separate check and not
    another case there (practice: control-asserts-which-failure: a control
    proves the guard fires, and that one fires on a path production does not
    take).

    NEGATIVE CONTROLS, run rather than assumed. Reverting the persist in
    _try_sync back into run_sync alone turns case 1 red and leaves 2-4 green;
    deleting ensure_source_credentials' write turns 2 red and leaves 1 green.
    The two halves fail independently, so both are stated.

    Hermetic: file:// origins, an https remote written in afterwards, a
    fixture token. No network."""
    import shutil, tempfile

    sys.path.insert(0, str(ROOT / 'tools'))
    import precedent_source_credentials as psc
    import precedent_source_bootstrap as psb
    import precedent_refresh_sources as prs

    TOKEN = 'fixture-token-never-a-real-one'
    https = 'https://github.com/example/precedent-team-fixture'
    tmp = pathlib.Path(tempfile.mkdtemp(prefix='precedent-cred-paths-'))
    cases = []
    try:
        source = tmp / 'source-repo'
        source.mkdir()
        for cmd in (['init', '-q', '-b', 'main'],
                    ['config', 'user.email', 'harness@example.com'],
                    ['config', 'user.name', 'harness']):
            subprocess.run(['git', '-C', str(source), *cmd], check=True,
                           capture_output=True, text=True)
        (source / 'practices').mkdir()
        (source / 'practices' / 'p.md').write_text('fixture\n', encoding='utf-8')
        (source / 'precedent.json').write_text('{"base_branch": "main"}\n',
                                               encoding='utf-8')
        subprocess.run(['git', '-C', str(source), 'add', '-A'], check=True,
                       capture_output=True, text=True)
        subprocess.run(['git', '-C', str(source), 'commit', '-qm', 'seed'],
                       check=True, capture_output=True, text=True)

        # --- 1: a team clone ALREADY ON DISK is offered the helper ----------
        # The regression itself. Recorded rather than read out of the config,
        # for case 5's reason above: a file:// origin correctly gets none.
        consumer = tmp / 'consumer'
        (consumer / 'sibling-team').mkdir(parents=True)
        (consumer / 'precedent.json').write_text(json.dumps({'sources': [
            {'level': 'team', 'name': 'precedent-team-fixture',
             'path': 'sibling-team'}]}), encoding='utf-8')
        subprocess.run(['git', 'clone', '-q', f'file://{source}',
                        str(consumer / 'sibling-team')], check=True,
                       capture_output=True, text=True)
        calls = []
        original = psb._persist_credential
        psb._persist_credential = lambda c, u: calls.append((str(c), u))
        try:
            results = psb.sources_from_repo(consumer)
        finally:
            psb._persist_credential = original
        on_disk = str((consumer / 'sibling-team').resolve())
        cases.append(('a team clone that is ALREADY ON DISK is offered the '
                      'helper on its session-start sync -- the path that '
                      'bypasses run_sync entirely',
                      any(c[0] == on_disk for c in calls),
                      f'results={results!r} calls={calls!r}'))

        # --- 2: a clone NOTHING syncs is repaired by the session-start walk -
        attached = tmp / 'attached'
        subprocess.run(['git', 'clone', '-q', f'file://{source}',
                        str(attached)], check=True, capture_output=True,
                       text=True)
        subprocess.run(['git', '-C', str(attached), 'remote', 'set-url',
                        'origin', https], check=True, capture_output=True,
                       text=True)
        saved = os.environ.get(psc.TOKEN_ENV)
        os.environ[psc.TOKEN_ENV] = TOKEN
        try:
            repaired = prs.ensure_source_credentials([{'repo': attached}])
            cfg = (attached / '.git' / 'config').read_text(encoding='utf-8')
            cases.append(('an attached source clone with NO helper is '
                          'repaired, and the token itself is not written',
                          repaired and psc.TOKEN_ENV in cfg and TOKEN not in cfg,
                          f'repaired={repaired!r} {cfg[-400:]}'))

            # --- 3: an existing helper is somebody's own, and is left alone -
            again = prs.ensure_source_credentials([{'repo': attached}])
            cases.append(('a clone that already has a helper is left alone, '
                          'so this is idempotent and does not overwrite a '
                          "person's own credential manager",
                          again == [], f'second pass repaired {again!r}'))
        finally:
            if saved is None:
                os.environ.pop(psc.TOKEN_ENV, None)
            else:
                os.environ[psc.TOKEN_ENV] = saved

        # --- 4: no token, nothing written anywhere -------------------------
        bare = tmp / 'bare'
        subprocess.run(['git', 'clone', '-q', f'file://{source}', str(bare)],
                       check=True, capture_output=True, text=True)
        subprocess.run(['git', '-C', str(bare), 'remote', 'set-url', 'origin',
                        https], check=True, capture_output=True, text=True)
        os.environ.pop(psc.TOKEN_ENV, None)
        none_written = prs.ensure_source_credentials([{'repo': bare}])
        got = subprocess.run(['git', '-C', str(bare), 'config', '--get-all',
                              'credential.helper'], capture_output=True,
                             text=True).stdout.strip()
        cases.append(('with no token there is nothing to write, and nothing '
                      'is written', none_written == [] and got == '',
                      f'repaired={none_written!r} config={got!r}'))
    finally:
        shutil.rmtree(tmp, ignore_errors=True)

    bad = [(c[0], c[2]) for c in cases if not c[1]]
    check(f'the credential helper reaches the source clones no run_sync ever '
          f'touches ({len(cases)} stated cases)',
          not bad, '; '.join(f"{n} -- {d[:600]}" for n, d in bad))


def check_worktree_resolves_sources_beside_its_main_checkout():
    """precedent_resolve.load_config() from a LINKED worktree under the temp
    directory resolves a relative source path beside the main checkout when
    it does not resolve beside the worktree (2026-09-29). The merge check,
    Promote's batch and the push check's base all check a commit in such a
    worktree; from there `../<set>` named nothing, a set's practice in force
    in the repository read as not in force, and a consuming repo's merge
    check refused a pull request its checkout passed. Stated cases, with the
    control that a plain copy (not a worktree) gets no such fallback, and the
    network self-heal switched off so the answer is the resolver's alone."""
    import tempfile
    base = pathlib.Path(tempfile.mkdtemp(prefix='wt-sources-'))
    cases = []
    try:
        main, src = base / 'consumer', base / 'zzz-src'
        (src / 'practices').mkdir(parents=True)
        (src / 'practices' / 'zzz-rule.md').write_text(
            '---\nslug: zzz-rule\nstatus: active\n---\n## Rule\nx\n', encoding='utf-8')
        (src / 'precedent-source.json').write_text(
            json.dumps({'name': 'zzz-src', 'level': 'shared'}), encoding='utf-8')
        main.mkdir()
        (main / 'precedent.json').write_text(json.dumps(
            {'format_version': 1, 'sources': [
                {'level': 'shared', 'name': 'zzz-src', 'path': '../zzz-src'}]}),
            encoding='utf-8')
        g = ['git', '-c', 'user.name=h', '-c', 'user.email=h@example.com']
        subprocess.run([*g, 'init', '-q', str(main)], capture_output=True)
        subprocess.run([*g, '-C', str(main), 'add', '-A'], capture_output=True)
        subprocess.run([*g, '-C', str(main), 'commit', '-qm', 'x'], capture_output=True)
        far = pathlib.Path(tempfile.mkdtemp(prefix='wt-far-'))
        wt = far / 'tree'
        subprocess.run(['git', '-C', str(main), 'worktree', 'add', '-q', '--detach',
                        str(wt), 'HEAD'], capture_output=True)
        copy = far / 'copy'
        shutil.copytree(main, copy)
        env = {k: v for k, v in os.environ.items() if k != 'CLAUDE_CODE_REMOTE'}
        env['PRECEDENT_USER_CONFIG'] = str(base / 'no-user-config.json')
        probe = ('import sys, json; sys.path.insert(0, sys.argv[1]); '
                 'import precedent_resolve as pr; '
                 'print(json.dumps([s["path"] for s in pr.load_config(sys.argv[2])]))')

        def paths(root):
            r = subprocess.run([sys.executable, '-c', probe, str(ROOT / 'tools'),
                                str(root)], capture_output=True, text=True, env=env)
            try:
                return json.loads(r.stdout.strip().splitlines()[-1])
            except (ValueError, IndexError):
                return r.stdout + r.stderr
        want = str(src.resolve())
        got = paths(wt)
        cases.append(('a worktree under the temp directory resolves ../zzz-src '
                      'beside its main checkout', isinstance(got, list)
                      and want in got, got))
        got = paths(main)
        cases.append(('the main checkout resolves it as before',
                      isinstance(got, list) and want in got, got))
        got = paths(copy)
        cases.append(('CONTROL: a plain copy is not a worktree and gets no '
                      'fallback', isinstance(got, list) and want not in got, got))
        subprocess.run(['git', '-C', str(main), 'worktree', 'remove', '--force',
                        str(wt)], capture_output=True)
        shutil.rmtree(far, ignore_errors=True)
    finally:
        shutil.rmtree(base, ignore_errors=True)
    bad = [(c[0], c[2]) for c in cases if not c[1]]
    check(f'a worktree resolves relative sources beside its main checkout '
          f'({len(cases)} stated cases)', not bad,
          '; '.join(f'{n}: {d}' for n, d in bad))


def check_individual_source_bootstrap_self_heals():
    """practices/session-bootstrap.md's Detail, tested rather than trusted
    -- and corrected 2026-09-06 after this check's own first version
    proved a false claim clean.

    tools/precedent_resolve.py's own load_config() treats a still-missing
    individual config, on a remote session, as "try the hook once more"
    rather than "no individual set" -- this is the ENTIRE fix for the
    incident practices/session-bootstrap.md's Story records (two
    independent adopters' SessionStart hook running to completion before
    the agent's own turn, and therefore its add_repo call, could start).
    A first version of this check also asserted that
    tools/precedent_source_bootstrap.py retrying "instead of trying once"
    was a second, contributing half. That was tested here only by calling
    the tool directly against synthetic fixtures -- never inside a real
    SessionStart hook on a genuinely fresh Claude Code Web session, which
    is the one environment where the claim was actually false: a
    SessionStart hook's execution window and the agent's own first turn
    never overlap in time, so no retry count or delay inside the hook can
    ever observe add_repo access appearing. A follow-up testing session
    ran that real test and disproved it directly. This check's own
    passing runs never caught that, and could not have: it proves the
    tool's CODE does what the code says (retries N times, degrades
    gracefully), which was never in question -- it cannot prove the
    premise about the outside world (whether a retry, in that specific
    execution context, has anything to retry into) the retry was written
    against. Case 6 below locks in the correction: the tool now defaults
    to a single attempt, precisely because a default of more than one
    bought nothing for the case it was sized for.

    Fixture: a real local git repo served over file:// -- not a bare path;
    this repo's own environment-gotchas.md already names why (`git clone
    --depth 1 /some/path` is ignored; only a real transport gets real
    clone semantics, and `file://` is what forces that locally). Six
    stated cases, all fast: --retry-delay 0 proves an explicitly-requested
    retry count without a real wall-clock wait."""
    import shutil, tempfile
    import precedent_source_credentials as psc
    import precedent_source_bootstrap as psb

    tmp = pathlib.Path(tempfile.mkdtemp(prefix='precedent-source-bootstrap-'))
    cases = []
    try:
        bootstrap_tool = ROOT / 'tools' / 'precedent_source_bootstrap.py'
        resolve_tool = ROOT / 'tools' / 'precedent_resolve.py'

        def _no_credentials():
            env = dict(os.environ)
            env.pop(psc.TOKEN_ENV, None)
            env.pop(psb.BASE_URL_ENV, None)
            return env

        def run(*args, env_extra=None):
            # Same scrub as check_source_credentials's run(), for the same
            # reason: cases here assert what a bootstrap does with no
            # credential and no base url, and this harness runs in a
            # container that normally carries both
            # (practice: fixture-owns-its-state).
            env = dict(os.environ)
            env.pop(psc.TOKEN_ENV, None)
            env.pop(psb.BASE_URL_ENV, None)
            if env_extra is not None:
                env.update(env_extra)
            r = subprocess.run([sys.executable, *args], capture_output=True,
                               text=True, env=env)
            return r.returncode, r.stdout + r.stderr

        def git(cwd, *args):
            subprocess.run(['git', '-C', str(cwd), *args], check=True,
                           capture_output=True, text=True)

        # --- a real source repo, with one fixture practice -------------------
        source = tmp / 'source-repo'
        source.mkdir()
        git(source, 'init', '-q')
        git(source, 'config', 'user.email', 'harness@example.com')
        git(source, 'config', 'user.name', 'harness')
        (source / 'practices').mkdir()
        (source / 'practices' / 'example.md').write_text(
            '---\nslug: harness-fixture\ntitle: Fixture\ntier: on-demand\n'
            'severity: default\napplies_to: ["**"]\noccasion: "testing"\n'
            'index_clause: "a harness fixture"\nchecked_by: null\n'
            'defines: []\nstatus: active\nsupersedes: []\noverrides: null\n'
            'added: null\napproved_by: "harness"\n---\n\n## Rule\nFixture.\n\n'
            '## Detail\n\n## Why\n\n## Story\n\n## Install\n', encoding='utf-8')
        git(source, 'add', '-A')
        git(source, 'commit', '-qm', 'seed')
        source_url = f'file://{source}'

        # --- case 1+2: reachable, cloned then pulled (idempotent) -----------
        # `--remote-only false` makes this hermetic: main()'s own default
        # (--remote-only true) no-ops the whole tool unless the AMBIENT
        # CLAUDE_CODE_REMOTE env var happens to already be 'true' -- true in
        # the Claude Code Remote session this was authored and verified in,
        # never true on a plain GitHub Actions runner, so this fixture
        # deterministically passed nothing and asserted on files that were
        # never written the first time this ran in CI. Case 4 below already
        # sets CLAUDE_CODE_REMOTE explicitly for the same reason, applied
        # here to the tool's own direct invocations instead.
        clone, config = tmp / 'clone', tmp / 'config.json'
        rc, out = run(str(bootstrap_tool), '--level', 'individual',
                     '--name', 'precedent-individual', '--repo-url', source_url,
                     '--clone', str(clone), '--config', str(config),
                     '--retries', '3', '--retry-delay', '0',
                     '--remote-only', 'false')
        cases.append(('a reachable source is cloned and the config written on '
                      'the first attempt',
                      rc == 0 and (clone / 'practices' / 'example.md').is_file()
                      and json.loads(config.read_text()).get('individual', {}).get('name')
                      == 'precedent-individual', out))

        rc2, out2 = run(str(bootstrap_tool), '--level', 'individual',
                        '--name', 'precedent-individual', '--repo-url', source_url,
                        '--clone', str(clone), '--config', str(config),
                        '--retries', '3', '--retry-delay', '0',
                        '--remote-only', 'false')
        cases.append(('running it again against an already-cloned source pulls '
                      'rather than re-cloning (idempotent)', rc2 == 0, out2))

        # --- case 3: unreachable -- retries the stated number, then degrades,
        # never fails, never writes a config -------------------------------
        rc3, out3 = run(str(bootstrap_tool), '--level', 'individual',
                        '--name', 'precedent-individual',
                        '--repo-url', f'file://{tmp / "does-not-exist"}',
                        '--clone', str(tmp / 'clone-unreachable'),
                        '--config', str(tmp / 'config-unreachable.json'),
                        '--retries', '3', '--retry-delay', '0',
                        '--remote-only', 'false')
        cases.append(('an unreachable source retries the stated number of '
                      'times, then exits 0 and writes no config',
                      rc3 == 0 and not (tmp / 'config-unreachable.json').exists()
                      and 'after 3 attempt' in out3, out3))

        # --- case 6 (2026-09-06 correction): the DEFAULT is a single
        # attempt, with no --retries/--retry-delay given at all -- locks in
        # the corrected understanding that a multi-attempt default bought
        # nothing for the SessionStart-hook case it was originally sized
        # for (see this function's own docstring). A regression back to a
        # default > 1 would silently reintroduce the exact wasted latency
        # this correction removed, on every cold session, for zero benefit.
        rc6, out6 = run(str(bootstrap_tool), '--level', 'individual',
                        '--name', 'precedent-individual',
                        '--repo-url', f'file://{tmp / "does-not-exist"}',
                        '--clone', str(tmp / 'clone-unreachable-default'),
                        '--config', str(tmp / 'config-unreachable-default.json'),
                        '--remote-only', 'false')
        cases.append(('with no --retries given, the tool defaults to exactly '
                      'one attempt', rc6 == 0 and 'after 1 attempt' in out6, out6))

        # --- case 4: the resolver's own lazy self-heal, on a remote session -
        consumer = tmp / 'consumer'
        (consumer / '.claude' / 'hooks').mkdir(parents=True)
        (consumer / 'precedent.json').write_text(json.dumps({
            'format_version': 1,
            'sources': [{'level': 'universal', 'name': 'precedent', 'path': str(ROOT)}],
        }), encoding='utf-8')
        hook = consumer / '.claude' / 'hooks' / 'precedent-individual-bootstrap.sh'
        hook.write_text(
            '#!/bin/bash\nset -uo pipefail\n'
            'if [ "${CLAUDE_CODE_REMOTE:-}" != "true" ]; then exit 0; fi\n'
            f'python3 "{bootstrap_tool}" --level individual '
            f'--name precedent-individual --repo-url "{source_url}" '
            '--clone "$HOME/precedent-individual" '
            '--config "$HOME/.config/precedent/config.json" '
            '--retries 3 --retry-delay 0\n', encoding='utf-8')
        hook.chmod(0o755)

        home_remote = tmp / 'home-remote'
        home_remote.mkdir()
        rc4, out4 = run(str(resolve_tool), '--repo', str(consumer), '--json',
                        env_extra={'HOME': str(home_remote),
                                   'CLAUDE_CODE_REMOTE': 'true',
                                   'PRECEDENT_USER_CONFIG':
                                       str(home_remote / '.config' / 'precedent' / 'config.json')})
        resolved4 = {}
        try:
            resolved4 = json.loads(out4)
        except json.JSONDecodeError:
            pass
        cases.append(('on a remote session with the config absent, resolve '
                      'self-heals via the hook and finds the individual '
                      'source afterward',
                      rc4 == 0 and any(p['slug'] == 'harness-fixture'
                                       for p in resolved4.get('practices', [])), out4))

        # --- case 5: the same absence, off a remote session, self-heals NOT -
        home_local = tmp / 'home-local'
        home_local.mkdir()
        env_local = dict(os.environ)
        env_local.pop('CLAUDE_CODE_REMOTE', None)
        env_local['HOME'] = str(home_local)
        env_local['PRECEDENT_USER_CONFIG'] = str(home_local / '.config' / 'precedent' / 'config.json')
        r5 = subprocess.run([sys.executable, str(resolve_tool), '--repo', str(consumer), '--json'],
                            capture_output=True, text=True, env=env_local)
        resolved5 = {}
        try:
            resolved5 = json.loads(r5.stdout)
        except json.JSONDecodeError:
            pass
        cases.append(('without CLAUDE_CODE_REMOTE, resolve does NOT invoke the '
                      'hook -- a local machine with genuinely no individual '
                      'set stays silent, not self-healed',
                      r5.returncode == 0
                      and not any(p['slug'] == 'harness-fixture'
                                  for p in resolved5.get('practices', []))
                      and not (home_local / '.config').exists(),
                      r5.stdout + r5.stderr))

        # --- cases 6-8: "no individual set" vs "could not find out" --------
        # The silence these close: before 2026-09-06 an undeclared individual
        # source was appended to nothing, so it reached neither `sources` nor
        # `missing`, and a hosted session that had no way to look printed the
        # same confident summary as a laptop that genuinely has none.
        # run() returns stdout + stderr concatenated, and the whole point of
        # this fix is that these runs now PRINT a notice on stderr -- so the
        # JSON is a prefix of the captured text, not the whole of it.
        def _json_prefix(text):
            try:
                return json.JSONDecoder().raw_decode(text.lstrip())[0]
            except (json.JSONDecodeError, ValueError):
                return {}

        cases.append(('a resolved individual source reports no '
                      'individual_status finding -- its fate belongs in '
                      '`missing` like any other declared source',
                      (_json_prefix(out4) or {}).get('individual_status') is None,
                      out4))

        nohook = tmp / 'consumer-nohook'
        nohook.mkdir()
        (nohook / 'precedent.json').write_text(json.dumps({
            'format_version': 1,
            'sources': [{'level': 'universal', 'name': 'precedent', 'path': str(ROOT)}],
        }), encoding='utf-8')
        home6 = tmp / 'home-nohook'
        home6.mkdir()
        rc6b, out6b = run(str(resolve_tool), '--repo', str(nohook), '--json',
                          env_extra={'HOME': str(home6), 'PRECEDENT_INDIVIDUAL_REPO': 'file:///fixture/precedent-individual',
                                     'CLAUDE_CODE_REMOTE': 'true',
                                     'PRECEDENT_USER_CONFIG':
                                         str(home6 / 'config.json')})
        st6 = (_json_prefix(out6b) or {}).get('individual_status') or {}
        cases.append(('on a remote session whose project ships no bootstrap '
                      'hook, resolve reports that it could NOT determine '
                      'whether an individual set exists, rather than implying '
                      'there is none',
                      st6.get('certain') is False
                      and st6.get('code') == 'no-bootstrap-hook', out6b))

        r7 = subprocess.run([sys.executable, str(resolve_tool), '--repo',
                             str(nohook), '--json'],
                            capture_output=True, text=True, env=env_local)
        st7 = (_json_prefix(r7.stdout) or {}).get('individual_status') or {}
        cases.append(('off a remote session, an absent user config IS a '
                      'definite "no individual practices" -- $HOME is the '
                      "person's own machine, so there is nothing to find out",
                      st7.get('certain') is True
                      and st7.get('code') == 'no-config-file',
                      r7.stdout + r7.stderr))

        declares_none = home6 / 'declares-none.json'
        declares_none.write_text('{"individual": null}', encoding='utf-8')
        rc8, out8 = run(str(resolve_tool), '--repo', str(nohook), '--json',
                        env_extra={'HOME': str(home6),
                                   'CLAUDE_CODE_REMOTE': 'true',
                                   'PRECEDENT_USER_CONFIG': str(declares_none)})
        st8 = (_json_prefix(out8) or {}).get('individual_status') or {}
        cases.append(('a user config that exists and declares no individual '
                      'source is a definite answer, even on a remote session',
                      st8.get('certain') is True
                      and st8.get('code') == 'config-declares-none', out8))

        # No sign anywhere of an individual set -- no token, base URL, repo
        # name or clone -- is a definite "none" even on a remote session with
        # no hook and no user config: nothing could have fetched one.
        rc8b, out8b = run(str(resolve_tool), '--repo', str(nohook), '--json',
                          env_extra={'HOME': str(home6),
                                     'CLAUDE_CODE_REMOTE': 'true',
                                     'PRECEDENT_USER_CONFIG':
                                         str(home6 / 'absent.json')})
        st8b = (_json_prefix(out8b) or {}).get('individual_status') or {}
        cases.append(('with no sign of an individual set, a remote session '
                      'with no user config reports a definite "none"',
                      st8b.get('certain') is True
                      and st8b.get('code') == 'no-individual-signal'
                      and 'could not find out' not in out8b, out8b))

        # --- cases 9-11: BestPractice as a CONSUMER of its own instructions -
        # The root cause of the hook being absent here for as long as it was:
        # this repo is treated as the publisher, so every case above builds a
        # fixture consumer and asserts things about IT. Nothing asserted the
        # publisher follows the install steps it publishes. These do.
        own_hook = ROOT / '.claude' / 'hooks' / 'precedent-individual-bootstrap.sh'
        cases.append(('this repo carries the individual-source bootstrap hook '
                      'it tells every adopter to install, and it is executable',
                      own_hook.is_file() and os.access(own_hook, os.X_OK),
                      f'{own_hook} is_file={own_hook.is_file()}'))

        # The property that makes committing it safe, and the reason it was
        # left out as "must not be committed blind": a SessionStart hook must
        # never block a session, so it has to exit 0 even when its whole job
        # is impossible. Run here with a HOME that has nothing and no git
        # credentials -- exactly a session without access to the private set.
        home_hook = tmp / 'home-own-hook'
        home_hook.mkdir()
        rh = subprocess.run(['bash', str(own_hook)], capture_output=True,
                            text=True, timeout=180,
                            env={**_no_credentials(), 'HOME': str(home_hook),
                                 'CLAUDE_PROJECT_DIR': str(ROOT),
                                 'CLAUDE_CODE_REMOTE': 'true'})
        cases.append(("this repo's own bootstrap hook exits 0 when it cannot "
                      'reach the individual set -- a session-start hook that '
                      'fails must never block the session',
                      rh.returncode == 0, rh.stdout + rh.stderr))

        # And the CLI route that writes it. Until 2026-09-06 --write-session-hook
        # was reachable only after bootstrap() created a whole individual set,
        # so the documented "run it again against an already-bootstrapped set"
        # could not be run -- which is why this repo went without the hook.
        hook_only_proj = tmp / 'hook-only-project'
        hook_only_proj.mkdir()
        rc9, out9 = run(str(ROOT / 'tools' / 'precedent_bootstrap_source.py'),
                        '--level', 'individual', '--name', 'precedent-individual',
                        '--write-session-hook', str(hook_only_proj),
                        '--repo-url', 'https://example.invalid/precedent-individual')
        written_hook = hook_only_proj / '.claude' / 'hooks' / 'precedent-individual-bootstrap.sh'
        cases.append(('--write-session-hook writes the hook with no --dest and '
                      'creates no individual set -- the documented '
                      '"run it again against an already-bootstrapped set"',
                      rc9 == 0 and written_hook.is_file()
                      and not (hook_only_proj / 'practices').exists(),
                      out9))

        # --- cases 12-14: THE INSTANTIATED HOOK ACTUALLY RUNS ---------------
        # Case 9 above asserted the file exists, which is the whole reason
        # the defect below survived to a real install. It did not assert the
        # file WORKS, and it did not: the template guarded "still a raw
        # template?" by testing $REPO_URL against the source-repo-url
        # placeholder, and the substituter rewrote that occurrence along
        # with every other, so an instantiated hook compared the real URL
        # against itself and took the "no repository URL" exit on every
        # session while holding the correct URL. Silent, and inert at every
        # layer -- precedent_resolve.py's self-heal re-invokes this same
        # hook, so it short-circuited too. Found 2026-09-10 installing
        # precedent-beta-v01 into a real project, not by anything here.
        #
        # These three assert the property that was missing: instantiated
        # with a real URL the hook REACHES ITS EXEC and does the clone;
        # instantiated with none it still degrades quietly; and the raw
        # template, run as-is, must not mistake its own placeholder for a
        # URL and try to clone it.
        live_proj = tmp / 'live-hook-project'
        live_proj.mkdir()
        rc12, out12 = run(str(ROOT / 'tools' / 'precedent_bootstrap_source.py'),
                          '--level', 'individual', '--name', 'precedent-individual',
                          '--write-session-hook', str(live_proj),
                          '--repo-url', source_url)
        live_hook = live_proj / '.claude' / 'hooks' / 'precedent-individual-bootstrap.sh'
        live_home = tmp / 'home-live-hook'
        live_home.mkdir()
        r12 = subprocess.run(['bash', str(live_hook)], capture_output=True,
                             text=True, timeout=180,
                             env={**_no_credentials(), 'HOME': str(live_home),
                                  'CLAUDE_PROJECT_DIR': str(ROOT),
                                  'CLAUDE_CODE_REMOTE': 'true'})
        live_cfg = live_home / '.config' / 'precedent' / 'config.json'
        cases.append(('a hook instantiated with a REAL --repo-url reaches its '
                      'exec and clones -- it does not mistake the substituted '
                      'URL for an unsubstituted placeholder',
                      rc12 == 0 and r12.returncode == 0
                      and 'no repository URL' not in (r12.stdout + r12.stderr)
                      and (live_home / 'precedent-individual' / 'practices'
                           / 'example.md').is_file()
                      and live_cfg.is_file(),
                      out12 + r12.stdout + r12.stderr))

        nourl_proj = tmp / 'no-url-hook-project'
        nourl_proj.mkdir()
        rc13, out13 = run(str(ROOT / 'tools' / 'precedent_bootstrap_source.py'),
                          '--level', 'individual', '--name', 'precedent-individual',
                          '--write-session-hook', str(nourl_proj))
        nourl_hook = nourl_proj / '.claude' / 'hooks' / 'precedent-individual-bootstrap.sh'
        nourl_home = tmp / 'home-no-url-hook'
        nourl_home.mkdir()
        # The hook DERIVES its URL from the base url when no URL was baked
        # in, so a fixture asserting "it degrades quietly when nothing else
        # supplies one" has to be the thing that establishes "nothing else
        # supplies one". Inheriting the container's own base url made this
        # case assert the opposite of what it ran (2026-09-11).
        r13 = subprocess.run(['bash', str(nourl_hook)], capture_output=True,
                             text=True, timeout=180,
                             env={**_no_credentials(), 'HOME': str(nourl_home),
                                  'CLAUDE_PROJECT_DIR': str(ROOT),
                                  'CLAUDE_CODE_REMOTE': 'true'})
        cases.append(('--write-session-hook with NO --repo-url still writes a '
                      'fully instantiated hook -- the shape a PUBLIC consumer '
                      'needs, since the baked-in URL is tracked -- and that '
                      'hook degrades quietly when nothing else supplies one',
                      rc13 == 0 and nourl_hook.is_file()
                      and r13.returncode == 0
                      and 'no repository URL' in (r13.stdout + r13.stderr),
                      out13 + r13.stdout + r13.stderr))

        raw_template = (ROOT / 'templates' / 'harness' / 'claude-code' / 'hooks'
                        / 'individual-source-bootstrap.sh.template')
        raw_home = tmp / 'home-raw-template'
        raw_home.mkdir()
        stray = pathlib.Path('/home/user/{{SOURCE_NAME}}')
        stray_before = os.path.lexists(stray)
        r14 = subprocess.run(['bash', str(raw_template)], capture_output=True,
                             text=True, timeout=180,
                             env={**_no_credentials(), 'HOME': str(raw_home),
                                  'CLAUDE_PROJECT_DIR': str(ROOT),
                                  'CLAUDE_CODE_REMOTE': 'true'})
        cases.append(('the RAW template, run without being instantiated, still '
                      'recognises itself as uninstantiated and exits 0 without '
                      'trying to clone its own placeholder',
                      r14.returncode == 0
                      and 'no repository URL' in (r14.stdout + r14.stderr),
                      r14.stdout + r14.stderr))
        # ...and sets nothing up: a run that derived a URL from the
        # environment once cloned and linked a path named after the
        # placeholder, outside the fixture (2026-10-01).
        cases.append(('...and creates nothing named after its placeholder, in '
                      'the fixture or outside it',
                      not any('{{' in q.name for q in raw_home.rglob('*'))
                      and (stray_before or not os.path.lexists(stray)),
                      r14.stdout + r14.stderr))

        # NO COMMENT IN THE TEMPLATE MAY SPELL A PLACEHOLDER OUT. The same
        # bug one layer out, and the one that made the first fix's own
        # explanation unreadable: the substituter rewrites comments too, so
        # prose naming a placeholder comes out of instantiation as prose
        # naming the value -- "<the real URL> is substituted at install time
        # with a real URL". Assert the rule directly on the template rather
        # than on any one instantiation of it: every literal {{...}} sits on
        # a line that is actually substituted, never in a comment.
        raw_text = raw_template.read_text(encoding='utf-8')
        commented_placeholders = [
            ln for ln in raw_text.splitlines()
            if '{{' in ln and ln.lstrip().startswith('#')]
        cases.append(('no comment in the hook template spells a placeholder '
                      'out -- substitution rewrites comments too, so such a '
                      'line instantiates into nonsense',
                      not commented_placeholders,
                      '; '.join(commented_placeholders)))

        # And the publisher's own copy is a real instantiation, not a
        # fixture: nothing unsubstituted may survive in it.
        own_hook_text = own_hook.read_text(encoding='utf-8')
        cases.append(("this repo's own instantiated hook carries no leftover "
                      'placeholder', '{{' not in own_hook_text,
                      own_hook_text[:400]))
    finally:
        shutil.rmtree(tmp, ignore_errors=True)

    bad = [(c[0], c[2]) for c in cases if not c[1]]
    check(f'the resolver self-heals (the actual fix); the bootstrap tool '
          f'defaults to one attempt and still honors an explicit retry count '
          f'({len(cases)} stated cases)',
          not bad,
          '; '.join(f"{n} -- {d[:800]}" for n, d in bad))


def check_stale_render_self_heals():
    """spec/SESSION_PRACTICES_RENDER_SELF_HEAL.md's Shape C, tested rather
    than trusted -- precedent_resolve._self_heal_stale_render() is the fix
    for the half of the render gap check_individual_source_bootstrap_self_heals
    above does not cover: that self-heal (and
    _self_heal_universal_source() beside it) only ever fires on a MISSING
    clone. The 2026-09-18 incident this follows from had the clone present
    the whole session -- .precedent/SESSION_PRACTICES.md was simply a day
    stale -- so an existence-only guard would have stayed silent the whole
    extra day, which is exactly what Shape A (rejected in the brief) does
    and Shape C does not.

    Fixture: a stub tools/precedent_session_practices.py that writes a
    marker rather than performing a real multi-source render -- the
    function under test only decides WHETHER to call the render tool,
    never what the tool itself produces, so a stub keeps every case here
    hermetic and fast (practice: fixture-owns-its-state). Each case gets
    its own tmp repo, so no case's precedent.json or file mtime leaks into
    the next."""
    import shutil, tempfile
    import precedent_resolve as pr

    stub = ('#!/usr/bin/env python3\n'
            'import pathlib, sys\n'
            'repo = sys.argv[sys.argv.index("--repo") + 1]\n'
            'out = pathlib.Path(repo) / ".precedent"\n'
            'out.mkdir(parents=True, exist_ok=True)\n'
            '(out / "SESSION_PRACTICES.md").write_text("rendered", encoding="utf-8")\n')

    def _repo(tmp, *, with_tool=True, stale_hours=None):
        repo = tmp / next(tempfile._get_candidate_names())
        (repo / 'tools').mkdir(parents=True)
        if with_tool:
            tool = repo / 'tools' / 'precedent_session_practices.py'
            tool.write_text(stub, encoding='utf-8')
            tool.chmod(0o755)
        if stale_hours is not None:
            (repo / 'precedent.json').write_text(
                json.dumps({'stale_render_hours': stale_hours}), encoding='utf-8')
        return repo

    tmp = pathlib.Path(tempfile.mkdtemp(prefix='precedent-stale-render-'))
    cases = []
    # The fixture owns who is working here: nobody. The real person's sets
    # are sources too, and since 2026-10-02 a source checkout that moved
    # after the render makes it stale, so their clones' mtimes decided
    # these cases (practice: fixture-owns-its-state).
    _saved_cfg = os.environ.get('PRECEDENT_USER_CONFIG')
    os.environ['PRECEDENT_USER_CONFIG'] = str(tmp / 'no-user-config.json')
    try:
        # --- case 1: absent render -> the stub is invoked, file appears --
        repo1 = _repo(tmp)
        result1 = pr._self_heal_stale_render(repo1)
        rendered1 = (repo1 / '.precedent' / 'SESSION_PRACTICES.md')
        cases.append(('an absent render is written by the self-heal',
                      result1 == 'attempted' and rendered1.is_file()
                      and rendered1.read_text(encoding='utf-8') == 'rendered',
                      f'result={result1!r} exists={rendered1.is_file()}'))

        # --- case 2: a fresh render (just written) is left alone ---------
        result2 = pr._self_heal_stale_render(repo1)
        cases.append(("a render younger than the threshold is reported "
                      "'fresh' and left untouched, not re-rendered on "
                      "every call",
                      result2 == 'fresh', f'result={result2!r}'))

        # --- case 3: a render older than the declared threshold re-fires -
        repo3 = _repo(tmp, stale_hours=1)
        out3 = repo3 / '.precedent'
        out3.mkdir(parents=True)
        marker = out3 / 'SESSION_PRACTICES.md'
        marker.write_text('stale copy', encoding='utf-8')
        old = time.time() - 2 * 3600  # 2h old, past this repo's 1h threshold
        os.utime(marker, (old, old))
        result3 = pr._self_heal_stale_render(repo3)
        cases.append(('a render older than the declared stale_render_hours '
                      'is re-rendered, not just an absent one',
                      result3 == 'attempted'
                      and marker.read_text(encoding='utf-8') == 'rendered',
                      f'result={result3!r} content={marker.read_text(encoding="utf-8")!r}'))

        # --- case 4: same age, but a generous threshold leaves it fresh --
        repo4 = _repo(tmp, stale_hours=48)
        out4 = repo4 / '.precedent'
        out4.mkdir(parents=True)
        marker4 = out4 / 'SESSION_PRACTICES.md'
        marker4.write_text('still current', encoding='utf-8')
        os.utime(marker4, (old, old))
        result4 = pr._self_heal_stale_render(repo4)
        cases.append(("the SAME 2h-old file is 'fresh' under a 48h "
                      "threshold -- the threshold is read from THIS repo's "
                      "own precedent.json, not hardcoded",
                      result4 == 'fresh'
                      and marker4.read_text(encoding='utf-8') == 'still current',
                      f'result={result4!r}'))

        # --- case 5: the declared-default (1h) is honored when
        # precedent.json is absent, not silently zero ---------------------
        repo5 = _repo(tmp)  # no precedent.json written at all
        cases.append(('the declared-default (1h) is used when this repo '
                      'has no precedent.json at all',
                      pr._stale_render_hours(repo5) == 1,
                      f'got {pr._stale_render_hours(repo5)!r}'))

        # --- case 6: a source set whose engine predates this addition (no
        # precedent_session_practices.py) degrades, never raises ----------
        repo6 = _repo(tmp, with_tool=False)
        result6 = pr._self_heal_stale_render(repo6)
        cases.append(('a repo with no precedent_session_practices.py '
                      'degrades to no-tool rather than raising',
                      result6 == 'no-tool', f'result={result6!r}'))
    finally:
        shutil.rmtree(tmp, ignore_errors=True)
        if _saved_cfg is None:
            os.environ.pop('PRECEDENT_USER_CONFIG', None)
        else:
            os.environ['PRECEDENT_USER_CONFIG'] = _saved_cfg

    bad = [(c[0], c[2]) for c in cases if not c[1]]
    check(f'the stale-render self-heal fires on absent-or-stale, not just '
          f'absent, and reads its threshold from this repo\'s own '
          f'precedent.json ({len(cases)} stated cases)',
          not bad,
          '; '.join(f"{n} -- {d[:400]}" for n, d in bad))



def check_attached_sets_sources_are_synced():
    """Session start syncs what every ATTACHED practice set reads, not only
    the root's own sources (2026-10-02). Measured that day: the individual set
    at $HOME read its universal rules from a clone of its own,
    $HOME/BestPractice, made at one session start and never pulled again --
    131 commits behind, and the set's session file and the reply gate's
    session-load figure were built from it.

    Two-parent fixture: a project under one parent, the individual set under
    a fake $HOME, the set declaring universal at ../BestPractice. Cases, each
    asserting the tool's own words or the clone's own state:
      1. the set's universal clone is fast-forwarded by the walk;
      2. it stays on the branch its manifest pins (main), not the universal
         repo's own declared base_branch (staging) -- the existing-clone
         path used to pass no branch and moved it;
      3. the set's session file is re-rendered because a source it reads
         moved, though it was minutes old;
      4. with nothing moved, a second run leaves that render alone;
      5. a checkout the tool did not clone is left as it is, and says so;
      6. a checkout named as the session's project is skipped, and says so."""
    import shutil, tempfile
    import precedent_source_bootstrap as psb
    import precedent_resolve as pr

    def git(cwd, *a):
        env = dict(os.environ, PRECEDENT_ALLOW_ANY_AUTHOR='1')
        return subprocess.run(['git', '-C', str(cwd), *a], capture_output=True,
                              text=True, env=env)

    def commit(repo, name, text):
        (repo / name).write_text(text, encoding='utf-8')
        git(repo, 'add', '-A')
        git(repo, '-c', 'user.email=f@x', '-c', 'user.name=f', 'commit',
            '-qm', name)

    stub = ('#!/usr/bin/env python3\n'
            'import pathlib, sys\n'
            'repo = sys.argv[sys.argv.index("--repo") + 1]\n'
            'out = pathlib.Path(repo) / ".precedent"\n'
            'out.mkdir(parents=True, exist_ok=True)\n'
            '(out / "SESSION_PRACTICES.md").write_text("rendered", encoding="utf-8")\n')

    saved = {k: os.environ.get(k) for k in (
        'PRECEDENT_ASSUME_LADDER', 'PRECEDENT_USER_CONFIG', 'CLAUDE_PROJECT_DIR', 'PRECEDENT_PROJECT_DIR',
        pr.SELF_HEAL_RENDER_ENV)}
    for k in saved:                       # practice: fixture-owns-its-state
        os.environ.pop(k, None)
    tmp = pathlib.Path(tempfile.mkdtemp(prefix='attached-sets-sync-'))
    cases = []
    try:
        # The universal origin: main and staging, base_branch staging.
        up = tmp / 'origin-bp'
        up.mkdir()
        git(up, 'init', '-q', '-b', 'main')
        (up / 'practices').mkdir()
        (up / 'precedent.json').write_text(json.dumps(
            {'base_branch': 'staging', 'sources': [
                {'level': 'universal', 'name': 'precedent', 'path': '.'}]}),
            encoding='utf-8')
        commit(up, 'practices/rule.md', 'v1\n')
        git(up, 'branch', 'staging')
        url = f'file://{up}'

        home = tmp / 'home'
        proj_parent = tmp / 'work'
        home.mkdir()
        proj_parent.mkdir()
        project = proj_parent / 'project'
        project.mkdir()
        git(project, 'init', '-q', '-b', 'main')
        (project / 'precedent.json').write_text(json.dumps({'sources': []}),
                                                encoding='utf-8')

        indiv = home / 'precedent-individual'
        (indiv / 'tools').mkdir(parents=True)
        git(indiv, 'init', '-q', '-b', 'main')
        (indiv / 'precedent.json').write_text(json.dumps({'sources': [
            {'level': 'universal', 'name': 'precedent',
             'path': '../BestPractice'}]}), encoding='utf-8')
        (indiv / 'tools' / 'ENGINE_MANIFEST.json').write_text(
            json.dumps({'source_branch': 'main'}), encoding='utf-8')
        tool = indiv / 'tools' / 'precedent_session_practices.py'
        tool.write_text(stub, encoding='utf-8')
        tool.chmod(0o755)
        cfg = tmp / 'config.json'
        cfg.write_text(json.dumps({'individual': {
            'name': 'precedent-individual', 'path': str(indiv)}}),
            encoding='utf-8')
        os.environ['PRECEDENT_USER_CONFIG'] = str(cfg)

        # The set's universal clone, made by the tool, then left behind.
        clone = home / 'BestPractice'
        ok, out = psb._try_sync(url, clone, branch='main')
        commit(up, 'practices/rule.md', 'v2, the newer rule\n')
        render = indiv / '.precedent' / 'SESSION_PRACTICES.md'
        render.parent.mkdir()
        render.write_text('old render', encoding='utf-8')
        past = time.time() - 120          # minutes old: fresh by age alone
        os.utime(render, (past, past))

        res = psb.sources_from_attached_sets(project)
        head = git(clone, 'rev-parse', 'HEAD').stdout.strip()
        tip = git(up, 'rev-parse', 'main').stdout.strip()
        branch = git(clone, 'rev-parse', '--abbrev-ref', 'HEAD').stdout.strip()
        cases.append(('the attached set\'s universal clone is fast-forwarded',
                      ok and head == tip, f'head={head[:8]} tip={tip[:8]} {res!r}'))
        cases.append(('and stays on its pinned main, not the universal '
                      'repo\'s own base_branch (staging)',
                      branch == 'main', f'branch={branch!r}'))
        cases.append(('the set\'s render is rebuilt because a source it reads '
                      'moved, though it was minutes old',
                      render.read_text(encoding='utf-8') == 'rendered',
                      render.read_text(encoding='utf-8')))

        render.write_text('kept', encoding='utf-8')
        os.utime(render, None)
        psb.sources_from_attached_sets(project)
        cases.append(('with nothing moved, a second run leaves the render '
                      'alone',
                      render.read_text(encoding='utf-8') == 'kept',
                      render.read_text(encoding='utf-8')))

        os.remove(clone / '.git' / psb.CLONE_MARKER)
        commit(up, 'practices/rule.md', 'v3\n')
        res = psb.sources_from_attached_sets(project)
        msgs = ' | '.join(m for _s, _n, _o, m in res)
        cases.append(('a checkout the tool did not clone is left as it is, and '
                      'says so',
                      git(clone, 'rev-parse', 'HEAD').stdout.strip() == tip
                      and 'not cloned by this tool' in msgs, msgs))

        psb._mark_clone(clone)
        os.environ['CLAUDE_PROJECT_DIR'] = str(clone)
        res = psb.sources_from_attached_sets(project)
        msgs = ' | '.join(m for _s, _n, _o, m in res)
        cases.append(('a checkout named as the session\'s project is skipped, '
                      'and says so',
                      git(clone, 'rev-parse', 'HEAD').stdout.strip() == tip
                      and 'a session is working in this checkout' in msgs, msgs))
    finally:
        for k, v in saved.items():
            if v is None:
                os.environ.pop(k, None)
            else:
                os.environ[k] = v
        shutil.rmtree(tmp, ignore_errors=True)

    bad = [(c[0], c[2]) for c in cases if not c[1]]
    check(f'session start syncs the sources every attached practice set reads, '
          f'pinned, skipping working copies, and re-renders a set whose '
          f'sources moved ({len(cases)} stated cases)',
          not bad,
          '; '.join(f"{n} -- {d[:400]}" for n, d in bad))


def check_attached_sets_sync_is_safe_for_everyone():
    """The adversarial half of check_attached_sets_sources_are_synced: the
    walk runs at EVERY session start, for people with no practice set of
    their own and for people whose BestPractice copy is their own work
    (2026-10-02, run before the change was landed). Cases, each through the
    real CLI where it is about what a person sees:
      1. a person's own ../BestPractice working copy -- feature branch,
         unpushed commit, half-done edit -- is untouched, and nothing is said;
      2. a set's universal clone that is missing is not cloned at session
         start;
      3. a set with a broken precedent.json adds no message and no traceback;
      4. a tool-made clone that cannot fast-forward (its own commit, origin
         moved on) keeps that commit and is reported in ONE line naming the
         set;
      5. a set with no engine manifest still keeps its universal clone on
         main, never the universal repo's own base_branch;
      6. a source ref stamped in the future does not make the render stale
         on every call."""
    import contextlib, io, shutil, tempfile
    import precedent_source_bootstrap as psb
    import precedent_resolve as pr

    def git(cwd, *a):
        env = dict(os.environ, PRECEDENT_ALLOW_ANY_AUTHOR='1')
        return subprocess.run(['git', '-C', str(cwd), *a], capture_output=True,
                              text=True, env=env)

    def commit(repo, name, text):
        f = repo / name
        f.parent.mkdir(parents=True, exist_ok=True)
        f.write_text(text, encoding='utf-8')
        git(repo, 'add', '-A')
        git(repo, '-c', 'user.email=f@x', '-c', 'user.name=f', 'commit',
            '-qm', name)

    def head(r):
        return git(r, 'rev-parse', 'HEAD').stdout.strip()

    def cli(project):
        err = io.StringIO()
        with contextlib.redirect_stderr(err), contextlib.redirect_stdout(err):
            rc = psb.main(['--sources-from', str(project), '--remote-only',
                           'false'])
        return rc, err.getvalue().strip()

    saved = {k: os.environ.get(k) for k in (
        'PRECEDENT_ASSUME_LADDER', 'PRECEDENT_USER_CONFIG', 'CLAUDE_PROJECT_DIR', 'PRECEDENT_PROJECT_DIR',
        pr.SELF_HEAL_RENDER_ENV, 'PRECEDENT_SOURCE_BASE_URL')}
    for k in saved:                       # practice: fixture-owns-its-state
        os.environ.pop(k, None)
    os.environ['PRECEDENT_SOURCE_BASE_URL'] = 'file:///nonexistent-base'
    tmp = pathlib.Path(tempfile.mkdtemp(prefix='attached-sets-safe-'))
    cases = []
    try:
        up = tmp / 'origin-bp'
        up.mkdir()
        git(up, 'init', '-q', '-b', 'main')
        (up / 'practices').mkdir()
        (up / 'precedent.json').write_text(json.dumps(
            {'base_branch': 'staging'}), encoding='utf-8')
        commit(up, 'practices/rule.md', 'v1\n')
        git(up, 'branch', 'staging')
        url = f'file://{up}'

        def layout(tag, manifest=True, raw=None):
            base = tmp / tag
            home, work = base / 'home', base / 'work'
            project = work / 'project'
            project.mkdir(parents=True)
            home.mkdir()
            git(project, 'init', '-q', '-b', 'main')
            (project / 'precedent.json').write_text('{"sources": []}',
                                                    encoding='utf-8')
            ind = home / 'precedent-individual'
            (ind / 'tools').mkdir(parents=True)
            git(ind, 'init', '-q', '-b', 'main')
            (ind / 'precedent.json').write_text(raw if raw is not None else
                json.dumps({'sources': [{'level': 'universal',
                                         'name': 'precedent',
                                         'path': '../BestPractice'}]}),
                encoding='utf-8')
            if manifest:
                # source_repo is what a fresh universal clone is made from, so
                # case 2 can tell "did not clone" from "had no URL to clone".
                (ind / 'tools' / 'ENGINE_MANIFEST.json').write_text(
                    json.dumps({'source_branch': 'main', 'source_repo': url}),
                    encoding='utf-8')
            cfg = base / 'config.json'
            cfg.write_text(json.dumps({'individual': {
                'name': 'precedent-individual', 'path': str(ind)}}),
                encoding='utf-8')
            os.environ['PRECEDENT_USER_CONFIG'] = str(cfg)
            return project, ind, home / 'BestPractice'

        # 1. the person's own working copy
        project, ind, bp = layout('own-copy')
        git(tmp, 'clone', '-q', str(up), str(bp))
        git(bp, 'checkout', '-q', '-b', 'my-feature')
        commit(bp, 'practices/mine.md', 'my work\n')
        (bp / 'practices' / 'rule.md').write_text('half-done\n', encoding='utf-8')
        commit(up, 'practices/rule.md', 'v2\n')
        before = (head(bp), git(bp, 'status', '--porcelain').stdout)
        rc, out = cli(project)
        after = (head(bp), git(bp, 'status', '--porcelain').stdout)
        cases.append(('a person\'s own BestPractice working copy is untouched '
                      'and nothing is said', rc == 0 and before == after
                      and 'precedent_source_bootstrap' not in out, out))

        # 2. a missing universal clone is not cloned
        project, ind, bp = layout('missing')
        rc, out = cli(project)
        cases.append(('a set\'s missing universal clone is not cloned at '
                      'session start', rc == 0 and not bp.exists(), out))

        # 3. a broken set adds nothing
        project, ind, bp = layout('broken', raw='{ not json')
        rc, out = cli(project)
        cases.append(('a set with a broken precedent.json adds no message and '
                      'no traceback', rc == 0 and 'Traceback' not in out
                      and 'precedent_source_bootstrap' not in out, out))

        # 4. a diverged tool-made clone: kept, and said once
        project, ind, bp = layout('diverged')
        psb._try_sync(url, bp, branch='main')
        commit(bp, 'practices/local.md', 'local\n')
        local = head(bp)
        commit(up, 'practices/rule.md', 'v3\n')
        rc, out = cli(project)
        lines = [l for l in out.splitlines() if 'precedent_source_bootstrap' in l]
        cases.append(('a clone that cannot fast-forward keeps its commit and is '
                      'reported in one line naming the set',
                      rc == 0 and head(bp) == local and len(lines) == 1
                      and 'was not brought up to date' in lines[0]
                      and str(ind) in lines[0], out))

        # 5. no manifest: still main
        project, ind, bp = layout('no-manifest', manifest=False)
        psb._try_sync(url, bp, branch='main')
        commit(up, 'practices/rule.md', 'v4\n')
        rc, out = cli(project)
        br = git(bp, 'rev-parse', '--abbrev-ref', 'HEAD').stdout.strip()
        cases.append(('a set with no engine manifest keeps its universal clone '
                      'on main', br == 'main' and head(bp) == head(up),
                      f'branch={br!r} {out}'))

        # 6. a future-stamped ref does not re-render forever (its own layout,
        # so it does not lean on case 5's branch)
        project, ind, bp = layout('future')
        psb._try_sync(url, bp, branch='main')
        tool = ind / 'tools' / 'precedent_session_practices.py'
        tool.write_text('raise SystemExit("rendered when it should not")\n',
                        encoding='utf-8')
        render = ind / '.precedent' / 'SESSION_PRACTICES.md'
        render.parent.mkdir(exist_ok=True)
        render.write_text('kept', encoding='utf-8')
        ref = bp / '.git' / 'refs' / 'heads' / 'main'
        fut = time.time() + 30 * 86400
        os.utime(ref, (fut, fut))
        res = pr._self_heal_stale_render(ind)
        cases.append(('a source ref stamped in the future does not make the '
                      'render stale', res == 'fresh', f'result={res!r}'))
    finally:
        for k, v in saved.items():
            if v is None:
                os.environ.pop(k, None)
            else:
                os.environ[k] = v
        shutil.rmtree(tmp, ignore_errors=True)

    bad = [(c[0], c[2]) for c in cases if not c[1]]
    check(f'the attached-set sync is safe for people with no set, a hand-made '
          f'BestPractice copy, a broken set or a stuck clone '
          f'({len(cases)} stated cases)',
          not bad,
          '; '.join(f"{n} -- {d[:400]}" for n, d in bad))

def check_self_heal_skips_a_scratch_copy():
    """precedent_resolve.py's source repairs cloned every declared source
    beside ANY repository that resolved, including a test's `git clone
    <path>` scratch copy in /tmp: precedent-shared-repo-maintenance's
    trailer test then resolved the working-style set it set out to exclude,
    and failed on untouched pre-staging (2026-09-30). Planted, with a stand-
    in bootstrap tool that leaves a marker when it runs. Discriminating
    cases: from a copy whose origin is another checkout on this disk, the
    repair does not run; from a checkout whose origin is a remote, it still
    does (the control); a file:// origin counts as a copy too."""
    import shutil, subprocess, tempfile
    sys.path.insert(0, str(ROOT / 'tools'))
    import precedent_resolve as _pr
    tmp = pathlib.Path(tempfile.mkdtemp(prefix='self-heal-scratch-'))
    saved = os.environ.get('CLAUDE_CODE_REMOTE')
    cases = []
    try:
        orig = tmp / 'orig'
        (orig / 'tools').mkdir(parents=True)
        (orig / 'tools' / 'precedent_source_bootstrap.py').write_text(
            'import pathlib, sys\n'
            'pathlib.Path(sys.argv[sys.argv.index("--sources-from") + 1]'
            ').joinpath("HEALED").write_text("x")\n', encoding='utf-8')
        git = lambda *a: subprocess.run(['git', *a], capture_output=True, text=True)
        git('init', '-q', str(orig))
        git('-C', str(orig), '-c', 'user.name=T', '-c', 'user.email=t@t',
            'add', '-A')
        git('-C', str(orig), '-c', 'user.name=T', '-c', 'user.email=t@t',
            'commit', '-qm', 'x')
        os.environ['CLAUDE_CODE_REMOTE'] = 'true'

        copy = tmp / 'copy'
        git('clone', '-q', str(orig), str(copy))
        got = _pr._self_heal_universal_source(copy)
        cases.append(('THE CASE THIS EXISTS FOR: from a copy of a checkout on '
                      'this disk, the repair does not run',
                      got == 'scratch-copy' and not (copy / 'HEALED').exists(),
                      got))
        fcopy = tmp / 'fcopy'
        git('clone', '-q', f'file://{orig}', str(fcopy))
        got = _pr._self_heal_universal_source(fcopy)
        cases.append(('...and a file:// origin is a copy too',
                      got == 'scratch-copy' and not (fcopy / 'HEALED').exists(),
                      got))
        cases.append(('...and the individual repair stands aside there too',
                      _pr._self_heal_individual_source(copy) == 'scratch-copy',
                      ''))
        git('-C', str(copy), 'remote', 'set-url', 'origin',
            'https://example.invalid/someone/some-set')
        got = _pr._self_heal_universal_source(copy)
        cases.append(('CONTROL: a checkout whose origin is a remote is still '
                      'repaired', got == 'attempted' and (copy / 'HEALED').exists(),
                      got))
    finally:
        if saved is None:
            os.environ.pop('CLAUDE_CODE_REMOTE', None)
        else:
            os.environ['CLAUDE_CODE_REMOTE'] = saved
        shutil.rmtree(tmp, ignore_errors=True)
    bad = [(c[0], c[2]) for c in cases if not c[1]]
    check(f'the source repairs skip a scratch copy of a checkout '
          f'({len(cases)} stated cases)',
          not bad, '; '.join(f"{n} -- {d}" for n, d in bad))


def check_self_heal_universal_source_leaves_no_bytecode():
    """precedent_resolve.py's _self_heal_universal_source() runs
    tools/precedent_source_bootstrap.py AS A SUBPROCESS, inside the very
    repo it is healing -- the same shape as the build_views.py subprocess
    precedent_bootstrap_source.py already runs with -B, and for the same
    reason: precedent_source_bootstrap.py's own _credential_args() imports
    precedent_source_credentials from ITS OWN DIRECTORY, and an ordinary
    (non -B) interpreter caches that import as a .pyc right there.

    THE BUG THIS LOCKS IN. Found chasing an intermittent very_deep_check.py
    false positive (tools/__pycache__/precedent_source_credentials.cpython-
    311.pyc reading as bootstrap drift, sometimes as a byte mismatch and
    sometimes as "this set does not have it") -- traced with strace -f to
    exactly this subprocess, launched without -B. The drift check has its
    own exclusion for a stray .pyc now (see check_very_deep_check_bootstrap_
    drift's stray-pycache case), which stops the false positive from being
    reported as drift; this check is the other half, on the file that
    actually writes it, so the same litter cannot reappear under some other
    caller that isn't behind a drift check at all -- a real set's tools/
    directory, session after session, whenever the universal source has not
    been cloned next to it yet.

    THE FIXTURE IS MINIMAL RATHER THAN A REAL BOOTSTRAPPED SET (contrast
    check_very_deep_check_bootstrap_drift's fresh()): only the two files
    _self_heal_universal_source's subprocess actually reads are copied in
    (precedent_source_bootstrap.py itself, and precedent_source_credentials.py
    so the import it triggers is the real one, not an ImportError that would
    make this pass for the wrong reason), plus the two small JSON files that
    tell it what to clone. No network call is required to exercise the bug:
    precedent_source_bootstrap.py's _sync_once() calls _credential_args()
    -- the import that writes the .pyc -- as its first line, before it runs
    any git command, so the clone attempt below is expected to fail offline
    and that failure is not what this check is about."""
    import shutil, tempfile
    import precedent_resolve as _pr

    tmp = pathlib.Path(tempfile.mkdtemp(prefix='precedent-self-heal-'))
    try:
        repo_root = tmp / 'set'
        tools_dir = repo_root / 'tools'
        tools_dir.mkdir(parents=True)
        shutil.copy2(ROOT / 'tools' / 'precedent_source_bootstrap.py',
                     tools_dir / 'precedent_source_bootstrap.py')
        shutil.copy2(ROOT / 'tools' / 'precedent_source_credentials.py',
                     tools_dir / 'precedent_source_credentials.py')
        (repo_root / 'precedent.json').write_text(json.dumps({
            'format_version': 1,
            'sources': [{'level': 'universal', 'name': 'precedent',
                        'path': '../universal-sibling-not-yet-cloned'}],
        }), encoding='utf-8')
        (tools_dir / 'ENGINE_MANIFEST.json').write_text(json.dumps({
            'source_repo': 'https://github.com/alex137/BestPractice',
            'source_branch': 'precedent-beta-v01',
        }), encoding='utf-8')

        _pr._self_heal_universal_source(repo_root)

        stray = tools_dir / '__pycache__'
        check('_self_heal_universal_source runs precedent_source_bootstrap.py '
              'with -B, so it leaves no __pycache__ in the repo it just healed',
              not stray.exists(),
              f'{stray} exists, containing: '
              f'{sorted(p.name for p in stray.iterdir())}' if stray.exists()
              else '(not reproduced this run)')
    finally:
        shutil.rmtree(tmp, ignore_errors=True)


def check_instantiated_template_links_survive_the_copy():
    """A file a template tells you to COPY INTO A REPO ROOT cannot carry a
    link that only resolves from the template's own directory.

    templates/document-project/'s README says "copy every file
    in this directory into its root", and its AGENTS.md linked
    `../AGENTS.md.loader.template` and `../../INSTALL.md`. Both resolve
    inside templates/ and are dead the moment the file is where it is
    supposed to end up -- and the same file already linked three other
    upstream documents by absolute URL, so the convention was established
    and these two simply missed it. Found 2026-09-10 installing
    precedent-beta-v01 into a real project; nothing here looked for it.

    The rule is about the DESTINATION, not the file: a template's own
    README is read where it sits and is deleted at instantiation (its step
    6 says so), so `../harness/README.md` is correct THERE and wrong in
    AGENTS.md. So this excludes the READMEs and checks everything else.

    An upward link is the only failure mode: a link INTO the template's own
    subtree (`.claude/settings.json`, `precedent.json`) copies along with
    the file and keeps working."""
    import re
    template_root = ROOT / 'templates' / 'document-project'
    if not template_root.is_dir():
        check('instantiated template files carry no links that die on the '
              'copy', True, '')
        return
    link_re = re.compile(r'\]\(\s*(\.\./[^)\s]*)')
    bad = []
    for f in sorted(template_root.rglob('*.md')):
        if f.name == 'README.md':
            continue          # read in place, deleted at instantiation
        for i, line in enumerate(f.read_text(encoding='utf-8').splitlines(), 1):
            for target in link_re.findall(line):
                bad.append(f'{f.relative_to(ROOT)}:{i} -> {target}')
    check('every file this template copies into a repo root links upstream '
          'documents absolutely, not by a path that only resolves inside '
          'templates/',
          not bad,
          '; '.join(bad))


def _stale_ref_fixture_env(tmp):
    """The environment every throwaway repo in the stale-ref checks below
    runs git under: a fixed author, no global or system config, and no
    personal Precedent config, so nothing on the machine leaks in."""
    return dict(os.environ, PRECEDENT_ALLOW_ANY_AUTHOR='1',
                GIT_AUTHOR_NAME='T', GIT_AUTHOR_EMAIL='t' + chr(64) + 'example.com',
                GIT_COMMITTER_NAME='T',
                GIT_COMMITTER_EMAIL='t' + chr(64) + 'example.com',
                GIT_CONFIG_GLOBAL=str(tmp / 'gitconfig'),
                GIT_CONFIG_NOSYSTEM='1', GIT_TERMINAL_PROMPT='0',
                PRECEDENT_USER_CONFIG=str(tmp / 'config.json'))


def check_stop_hook_says_each_state_once():
    """The Stop hook blocks once per dirty state, not at every turn end.

    Found 2026-10-01 in a reduction-pass session: while a background helper
    of the session was mid-edit on its branch, the same "uncommitted
    changes" finding blocked every stop, and each block was a turn with
    nothing to do. The rule under test: the first stop on a dirty state is
    blocked and says why; the same session stopping on the same state is
    not blocked again; a change to the state, or another session, is told
    afresh. Both copies are run, the template and this repo's own."""
    import tempfile
    name = 'the Stop hook says each dirty state once per session'
    hooks = [ROOT / 'templates' / 'harness' / 'claude-code' / 'hooks' / 'stop-git-check.sh',
             ROOT / '.claude' / 'hooks' / 'stop-git-check.sh']
    hooks = [h for h in hooks if h.exists()]
    if not hooks:
        not_applicable(name, 'no stop-git-check.sh here')
        return
    cases = []
    for hook in hooks:
        label = hook.relative_to(ROOT).parts[0]
        with tempfile.TemporaryDirectory() as td:
            tmp = pathlib.Path(td)
            env = _stale_ref_fixture_env(tmp)

            def git(*a):
                return subprocess.run(['git', '-C', str(work), *a],
                                      capture_output=True, text=True, env=env)
            bare = tmp / 'origin.git'
            subprocess.run(['git', 'init', '-q', '--bare', '-b', 'main', str(bare)],
                           capture_output=True, env=env)
            work = tmp / 'work'
            subprocess.run(['git', 'init', '-q', '-b', 'main', str(work)],
                           capture_output=True, env=env)
            (work / 'a.txt').write_text('a\n', encoding='utf-8')
            git('add', 'a.txt')
            git('commit', '-q', '-m', 'a')
            git('remote', 'add', 'origin', f'file://{bare}')
            git('push', '-q', '-u', 'origin', 'main')

            def stop(session):
                return subprocess.run(['bash', str(hook)], cwd=str(work),
                                      input=json.dumps({'session_id': session}),
                                      capture_output=True, text=True, env=env)

            (work / 'a.txt').write_text('a, edited\n', encoding='utf-8')
            r = stop('s1')
            cases.append((f'{label}: the first stop on a dirty tree is blocked, '
                          f'and says it will not repeat',
                          r.returncode == 2 and 'Uncommitted' in r.stderr
                          and 'will not repeat' in r.stderr))
            r = stop('s1')
            cases.append((f'{label}: the same session, same state: not blocked again',
                          r.returncode == 0))
            (work / 'b.txt').write_text('b\n', encoding='utf-8')
            r = stop('s1')
            cases.append((f'{label}: a new untracked file is a new state: blocked',
                          r.returncode == 2 and 'Untracked' in r.stderr))
            r = stop('s2')
            cases.append((f'{label}: another session is told afresh',
                          r.returncode == 2))
            git('add', '-A')
            git('commit', '-q', '-m', 'both')
            git('push', '-q')
            r = stop('s2')
            cases.append((f'{label}: clean and pushed: not blocked',
                          r.returncode == 0))
    failed = [n for n, ok in cases if not ok]
    check(f'{name} ({len(cases)} stated cases)', not failed, '; '.join(failed))


def check_stop_hook_ignores_commits_another_remote_ref_has():
    """The Stop hook's "unpushed" count asks whether a commit is on ANY
    remote ref, not whether it is ahead of origin/<current branch>.

    Two false blocks reported from a consumer repo, 2026-09-28, with
    nothing actually unpushed. (a) The branch's remote copy was deleted
    after its pull request merged; the stale remote-tracking ref stayed,
    and once the branch was moved onto origin/main the hook counted seven
    commits that were all on origin/main. (b) The branch was reset onto
    origin/pre-staging, whose tip is the merge of that same branch's pull
    request; the hook counted one commit that was on origin/pre-staging.
    Neither is the empty-merge case check_empty_commits_are_never_counted
    covers: both carry real file changes, just not unpushed ones.

    Both copies are run -- the template consumers install and this repo's
    own dogfooded one -- since the two carry different headers and a fix
    landed in only one of them before."""
    import tempfile
    name = ('the Stop hook counts only commits no remote ref has, so a stale '
            'or deleted branch ref never blocks a stop')
    hooks = [ROOT / 'templates' / 'harness' / 'claude-code' / 'hooks' / 'stop-git-check.sh',
             ROOT / '.claude' / 'hooks' / 'stop-git-check.sh']
    hooks = [h for h in hooks if h.exists()]
    if not hooks:
        not_applicable(name, 'no stop-git-check.sh here')
        return
    cases = []
    for hook in hooks:
        label = hook.relative_to(ROOT).parts[0]
        with tempfile.TemporaryDirectory() as td:
            tmp = pathlib.Path(td)
            env = _stale_ref_fixture_env(tmp)

            def git(cwd, *a):
                return subprocess.run(['git', '-C', str(cwd), *a],
                                      capture_output=True, text=True, env=env)

            def write(repo, path, text):
                (repo / path).write_text(text, encoding='utf-8')
                git(repo, 'add', path)
                git(repo, 'commit', '-q', '-m', f'edit {path}')

            bare = tmp / 'origin.git'
            git(tmp, 'init', '-q', '--bare', '-b', 'main', str(bare))
            work = tmp / 'work'
            git(tmp, 'init', '-q', '-b', 'main', str(work))
            write(work, 'a.txt', 'a\n')
            git(work, 'remote', 'add', 'origin', f'file://{bare}')
            git(work, 'push', '-q', 'origin', 'HEAD:refs/heads/main')
            git(work, 'push', '-q', 'origin', 'HEAD:refs/heads/pre-staging')
            # A second clone stands in for GitHub: it merges pull requests
            # and deletes branches without this checkout hearing about it.
            other = tmp / 'other'
            git(tmp, 'clone', '-q', f'file://{bare}', str(other))

            def stop():
                return subprocess.run(['bash', str(hook)], cwd=str(work),
                                      input='{}', capture_output=True,
                                      text=True, env=env)

            # (a) feature is pushed, merged into main alongside other work,
            # and its remote copy deleted; origin/feature stays, stale.
            git(work, 'checkout', '-q', '-b', 'feature')
            write(work, 'f.txt', 'f\n')
            git(work, 'push', '-q', '-u', 'origin', 'feature')
            git(other, 'fetch', '-q', 'origin')
            git(other, 'checkout', '-q', 'main')
            write(other, 'x.txt', 'x\n')
            write(other, 'y.txt', 'y\n')
            git(other, 'merge', '-q', '--no-ff', '-m', 'merge feature',
                'origin/feature')
            git(other, 'push', '-q', 'origin', 'main')
            git(other, 'push', '-q', 'origin', '--delete', 'feature')
            git(work, 'fetch', '-q', 'origin')          # no --prune: stale ref
            git(work, 'reset', '-q', '--hard', 'origin/main')
            stale = bool(git(work, 'rev-parse', '-q', '--verify',
                             'refs/remotes/origin/feature').stdout.strip())
            r = stop()
            cases.append((f'{label}: (a) branch moved onto origin/main after '
                          f'its remote copy was deleted, stale ref kept: the '
                          f'stop is not blocked [{r.returncode}: '
                          f'{r.stderr.strip()[:160]}]',
                          stale and r.returncode == 0))

            # (b) feature2 is pushed and merged into pre-staging; the local
            # branch is reset onto origin/pre-staging, whose tip is that merge.
            git(work, 'checkout', '-q', '-B', 'feature2', 'origin/pre-staging')
            write(work, 'g.txt', 'g\n')
            git(work, 'push', '-q', '-u', 'origin', 'feature2')
            git(other, 'fetch', '-q', 'origin')
            git(other, 'checkout', '-q', '-B', 'pre-staging', 'origin/pre-staging')
            write(other, 'z.txt', 'z\n')
            git(other, 'merge', '-q', '--no-ff', '-m', 'merge feature2',
                'origin/feature2')
            git(other, 'push', '-q', 'origin', 'pre-staging')
            git(work, 'fetch', '-q', 'origin')
            git(work, 'reset', '-q', '--hard', 'origin/pre-staging')
            r = stop()
            cases.append((f'{label}: (b) branch reset onto origin/pre-staging, '
                          f'whose tip merges that branch: the stop is not '
                          f'blocked [{r.returncode}: {r.stderr.strip()[:160]}]',
                          r.returncode == 0))

            # Control: a real commit no remote has still blocks, counted once.
            write(work, 'h.txt', 'h\n')
            r = stop()
            cases.append((f'{label}: a real commit no remote has still blocks, '
                          f'and says 1 [{r.returncode}: '
                          f'{r.stderr.strip()[:160]}]', r.returncode == 2
                          and '1 unpushed commit(s)' in r.stderr))
    failed = [n for n, ok in cases if not ok]
    check(f'{name} ({len(cases)} stated cases)', not failed, '; '.join(failed))


def _promote_fixture(tmp, env, base_branch, tiers):
    """-> (work, git, branches, tip): a throwaway repo with a bare origin
    carrying `tiers`, stub checks that always pass, and the real
    precedent_branches.py and precedent_push_check.py. Same shape as
    check_promote_picks_its_step's fixture."""
    import json as _json, shutil as _shutil

    def git(cwd, *a):
        return subprocess.run(['git', '-C', str(cwd), *a],
                              capture_output=True, text=True, env=env)

    bare = tmp / 'origin.git'
    git(tmp, 'init', '-q', '--bare', '-b', 'main', str(bare))
    work = tmp / 'work'
    (work / 'tools').mkdir(parents=True)
    git(tmp, 'init', '-q', '-b', 'main', str(work))
    for f in ('precedent_push_check.py', 'precedent_branches.py'):
        _shutil.copy2(ROOT / 'tools' / f, work / 'tools' / f)
    (work / 'tools' / 'ENGINE_MANIFEST.json').write_text(
        _json.dumps({'kind': 'consumer'}), encoding='utf-8')
    for t in ('precedent_check', 'leak_gate', 'doc_lint'):
        (work / 'tools' / f'{t}.py').write_text(
            'import sys\n'
            + ('print("precedent_check: 3 passed, 0 violated")\n'
               if t == 'precedent_check' else '')
            + 'sys.exit(0)\n', encoding='utf-8')
    (work / 'precedent.json').write_text(
        _json.dumps({'base_branch': base_branch}), encoding='utf-8')
    (work / 'list.txt').write_text('a\n', encoding='utf-8')
    git(work, 'add', '-A')
    git(work, 'commit', '-q', '-m', 'init')
    git(work, 'remote', 'add', 'origin', f'file://{bare}')
    for b in tiers:
        git(work, 'push', '-q', 'origin', f'HEAD:refs/heads/{b}')

    def branches(*a):
        p = subprocess.run([sys.executable, 'tools/precedent_branches.py', *a],
                           cwd=work, capture_output=True, text=True, env=env)
        return p.returncode, p.stdout + p.stderr

    def tip(b):
        return git(work, 'ls-remote', 'origin',
                   f'refs/heads/{b}').stdout.split('\t')[0]
    return work, git, branches, tip


def check_promote_into_main_exits_nonzero_until_main_moves():
    """Exit 0 from a Promote means the branch it names has moved.

    Reported 2026-09-28: `--promote --to main` pushed the to-main copy,
    printed READY FOR MAIN and a "Next, and not by this script" line, and
    exited 0. A session read the 0 as done; main had not moved, because the
    pull request, its GitHub test and the merge were all still to do. That
    state now exits PROMOTE_MAIN_NOT_MOVED, distinct from a refusal (1) and
    a usage error (2), and the block it prints opens by saying main has not
    moved.

    Also pinned here, from the same day's report of a Promote that "moved
    the session's checked-out branch without pushing it": neither kind of
    Promote touches the checkout it is run from -- the branch checked out
    and where it points are the same before and after. Every merge the
    tool makes happens in a throwaway detached worktree."""
    import tempfile
    name = ('a Promote into main exits non-zero until main moves, and no '
            'Promote moves the checked-out branch')
    tool = ROOT / 'tools' / 'precedent_branches.py'
    if not tool.exists():
        not_applicable(name, 'tools/precedent_branches.py is absent')
        return
    cases = []
    with tempfile.TemporaryDirectory() as td:
        tmp = pathlib.Path(td)
        env = _stale_ref_fixture_env(tmp)
        work, git, branches, tip = _promote_fixture(
            tmp, env, 'staging', ('main', 'staging', 'pre-staging'))
        git(work, 'checkout', '-q', '-b', 'session-work', 'origin/staging')
        (work / 'two.txt').write_text('2\n', encoding='utf-8')
        git(work, 'add', 'two.txt')
        git(work, 'commit', '-q', '-m', 'work')
        git(work, 'push', '-q', 'origin', 'HEAD:refs/heads/staging')
        git(work, 'push', '-q', 'origin', 'HEAD:refs/heads/pre-staging')
        before = git(work, 'rev-parse', 'HEAD').stdout.strip()
        main_before = tip('main')
        rc, out = branches('--promote', '--to', 'main', '--work', 'session-work')
        ready = [l for l in out.splitlines() if 'NOT MOVED' in l or 'READY FOR' in l]
        cases.append(('staging into main, main not yet moved: exit 3, not 0 '
                      f'(got {rc})', rc == 3))
        cases.append(('main really has not moved', tip('main') == main_before))
        cases.append(('the ready block opens by saying main has NOT moved',
                      bool(ready) and 'MAIN HAS NOT MOVED YET' in ready[0]))
        cases.append(('the checked-out branch is where it was',
                      git(work, 'branch', '--show-current').stdout.strip()
                      == 'session-work'
                      and git(work, 'rev-parse', 'HEAD').stdout.strip() == before))

    # A repository whose staging tier IS main: Promote moves pre-staging
    # straight into main, so exit 0 there does mean main moved.
    with tempfile.TemporaryDirectory() as td:
        tmp = pathlib.Path(td)
        env = _stale_ref_fixture_env(tmp)
        work, git, branches, tip = _promote_fixture(
            tmp, env, 'main', ('main', 'pre-staging'))
        git(work, 'checkout', '-q', '-b', 'session-work', 'origin/pre-staging')
        (work / 'three.txt').write_text('3\n', encoding='utf-8')
        git(work, 'add', 'three.txt')
        git(work, 'commit', '-q', '-m', 'work')
        git(work, 'push', '-q', '-u', 'origin', 'session-work')
        git(work, 'push', '-q', 'origin', 'HEAD:refs/heads/pre-staging')
        before = git(work, 'rev-parse', 'HEAD').stdout.strip()
        main_before = tip('main')
        rc, out = branches('--promote', '--work', 'session-work')
        cases.append(('no staging branch: pre-staging into main exits 0 and '
                      f'main moved (got {rc})',
                      rc == 0 and tip('main') not in ('', main_before)))
        cases.append(('and the checked-out branch is where it was, pointing at '
                      'what its own remote copy holds',
                      git(work, 'branch', '--show-current').stdout.strip()
                      == 'session-work'
                      and git(work, 'rev-parse', 'HEAD').stdout.strip() == before
                      == tip('session-work')))
    failed = [n for n, ok in cases if not ok]
    check(f'{name} ({len(cases)} stated cases)', not failed, '; '.join(failed))


@_without_session_id
def check_reply_gate_refreshes_the_landing_branch():
    """The reply gate's NOT YET LANDED line reads origin/<landing branch>
    fresh, not as last fetched.

    Reported 2026-09-28: a session merged its pull request through the
    GitHub API -- how every cloud session merges -- so nothing in the
    checkout fetched, origin/pre-staging stayed at the pre-merge tip, and
    for two turns the gate said the branch's commit was NOT on pre-staging
    and demanded the Boildown recommend merging a pull request already
    merged. Only `git fetch origin pre-staging` cleared it.

    A second clone stands in for GitHub here. Offline, the gate keeps its
    old answer from the ref it has, and never raises."""
    import tempfile
    import precedent_gate as pg
    name = ('the reply gate refreshes the landing branch before reporting '
            'work NOT on it')
    cases = []
    saved = {k: os.environ.get(k) for k in
             ('PRECEDENT_USER_CONFIG', 'GIT_CONFIG_GLOBAL', 'GIT_CONFIG_NOSYSTEM')}
    with tempfile.TemporaryDirectory() as td:
        tmp = pathlib.Path(td)
        env = _stale_ref_fixture_env(tmp)
        # _unlanded_work runs in this process, so it sees this process's
        # environment: no personal landing branch, no machine git config.
        for k in saved:
            os.environ[k] = env[k]
        try:
            def git(cwd, *a):
                return subprocess.run(['git', '-C', str(cwd), *a],
                                      capture_output=True, text=True, env=env)

            def write(repo, path, text):
                (repo / path).write_text(text, encoding='utf-8')
                git(repo, 'add', path)
                git(repo, 'commit', '-q', '-m', f'edit {path}')

            bare = tmp / 'origin.git'
            git(tmp, 'init', '-q', '--bare', '-b', 'trunk', str(bare))
            repo = tmp / 'repo'
            git(tmp, 'init', '-q', '-b', 'trunk', str(repo))
            write(repo, 'precedent.json',
                  json.dumps({'base_branch': 'trunk', 'sources': []}))
            git(repo, 'remote', 'add', 'origin', f'file://{bare}')
            git(repo, 'push', '-q', '-u', 'origin', 'trunk')
            git(repo, 'checkout', '-q', '-b', 'feature')
            write(repo, 'b.txt', 'b\n')
            git(repo, 'push', '-q', '-u', 'origin', 'feature')
            got = pg._unlanded_work(repo, siblings=False)
            cases.append(('before the merge, the commit is reported',
                          len(got) == 1, str(got)))

            other = tmp / 'other'
            git(tmp, 'clone', '-q', f'file://{bare}', str(other))
            git(other, 'merge', '-q', '--no-ff', '-m', 'merge feature',
                'origin/feature')
            git(other, 'push', '-q', 'origin', 'trunk')
            got = pg._unlanded_work(repo, siblings=False)
            cases.append(('merged on the remote with nothing fetched here: '
                          'not reported', got == [], str(got)))

            write(repo, 'c.txt', 'c\n')
            git(repo, 'remote', 'set-url', 'origin', str(tmp / 'gone.git'))
            got = pg._unlanded_work(repo, siblings=False)
            cases.append(('offline, a real unlanded commit is still reported '
                          'from the ref it has', len(got) == 1, str(got)))
        finally:
            for k, v in saved.items():
                if v is None:
                    os.environ.pop(k, None)
                else:
                    os.environ[k] = v
    failed = [f'{n} [{d}]' for n, ok, d in cases if not ok]
    check(f'{name} ({len(cases)} stated cases)', not failed, '; '.join(failed))


def check_not_binding_actually_exempts_a_check():
    """A `not_binding` entry has to change the RUN, not just the
    reachability report.

    precedent_resolve.load_not_binding()'s docstring describes the
    mechanism as a property of the pair -- "commit-author binds a repo one
    person authors alone and not one with many contributors" -- and names
    that slug as its motivating example. But precedent_check.py read the
    list in one place only, _unreachable_practices, where it suppressed a
    reachability finding and nothing else; main() built its slug list from
    sorted(CHECKS) and never consulted it. So a consuming repo could write
    a reasoned exemption and have it change nothing: the check still ran,
    still violated, still failed the run. A real install ended on two
    permanent violations it had written exemptions for, and the 17 entries
    in templates/document-project/precedent.json were, for
    check purposes, decorative (found 2026-09-10).

    Four cases, on one fixture consuming repo, because the fix has four
    separable ways to be wrong: the exemption must SUPPRESS the violation;
    it must not do so SILENTLY (an exemption that leaves no trace is how a
    rule gets switched off and forgotten, which is worse than the bug);
    the run must then be CLEAN, which is the whole point; and a
    `severity: blocking` practice must still be REFUSED an exemption."""
    import shutil, tempfile

    tmp = pathlib.Path(tempfile.mkdtemp(prefix='precedent-not-binding-'))
    cases = []
    try:
        repo = tmp / 'consumer'
        (repo / 'tools').mkdir(parents=True)
        (repo / 'practices').mkdir()
        # DERIVED, not hand-listed. This was a fixed tuple of seven names
        # until 2026-09-10, and the day a new engine module arrived
        # (precedent_identity.py, carved out of precedent_resolve.py) the
        # fixture silently stopped matching a real consumer: it copied a
        # precedent_resolve.py that imports a companion the fixture had
        # never heard of. Reading the vendoring tool's own list is what
        # keeps this fixture a consumer rather than a curated subset of one
        # (practice: fixture-owns-its-state -- the state it owns includes
        # which files a consumer actually gets).
        _seed_consumer_engine(repo / 'tools', extra=('routing_scope.json',))

        # A practice that is in force, exemptible, and whose check FIRES
        # here -- otherwise a "clean run" would prove nothing. Written
        # rather than copied so the fixture does not drift with the
        # catalogue: this one demands a file the fixture does not have.
        (repo / 'practices' / 'harness-exempt-fixture.md').write_text(
            '---\nslug: harness-exempt-fixture\ntitle: Fixture\n'
            'tier: on-demand\nseverity: default\napplies_to: ["**"]\n'
            'occasion: "testing"\nindex_clause: "a harness fixture"\n'
            'checked_by: null\ndefines: []\nstatus: active\n'
            'supersedes: []\noverrides: null\nadded: null\n'
            'approved_by: "harness"\n---\n\n## Rule\nFixture.\n\n'
            '## Detail\n\n## Why\n\n## Story\n\n## Install\n',
            encoding='utf-8')

        def write_config(not_binding):
            (repo / 'precedent.json').write_text(json.dumps({
                'format_version': 1,
                'visibility': 'private',
                'sources': [{'level': 'universal', 'name': 'precedent',
                             'path': '.'}],
                'not_binding': not_binding,
            }, indent=2) + '\n', encoding='utf-8')

        def run_check():
            r = subprocess.run([sys.executable, 'tools/precedent_check.py',
                                '--full-sweep'],
                               cwd=str(repo), capture_output=True, text=True)
            return r.returncode, r.stdout + r.stderr

        # PLANT the violation rather than hoping for one. This used to
        # discover whatever slug happened to be violated, on the reasoning
        # that naming one would go stale -- and on 2026-09-10 the fixture
        # went CLEAN instead (a fuller vendored engine removed the
        # incidental finding it had been relying on), so there was suddenly
        # nothing to exempt and the whole check rested on an accident. A
        # planted violation is the only kind a negative control can trust
        # (practice: control-asserts-which-failure).
        #
        # two-check-levels is the plant: it asks the instructions file to
        # name a fast check and a full check, and this fixture's AGENTS.md
        # deliberately names neither. Cheap, deterministic, and unrelated to
        # the exemption machinery under test.
        for slug in ('two-check-levels',):
            src = ROOT / 'practices' / f'{slug}.md'
            if src.is_file():
                shutil.copy2(src, repo / 'practices' / f'{slug}.md')
        (repo / 'AGENTS.md').write_text(
            '# Fixture\n\nNames no check levels, on purpose -- that is the '
            'planted violation.\n', encoding='utf-8')

        # BASELINE: with nothing exempted the fixture must produce that
        # VIOLATION and no exemptions. Without this the cases below would
        # pass on a fixture that never had anything to exempt -- which is
        # the shape of the bug itself, so it has to be ruled out.
        write_config([])
        rc0, out0 = run_check()
        violated_slugs = [ln.split()[1] for ln in out0.splitlines()
                          if ln.startswith('VIOLATION')]
        cases.append(('baseline: the PLANTED violation actually fires, so '
                      'there is something for an exemption to act on',
                      'two-check-levels' in violated_slugs,
                      f'violated: {violated_slugs}\n' + out0[-900:]))
        cases.append(('the baseline summary counts no exemptions',
                      ' 0 exempted' in out0, out0[-300:]))
        cases.append(('a violation fails the run, so a suppressed one is a '
                      'visible difference', rc0 == 1, f'rc={rc0}'))

        if 'two-check-levels' in violated_slugs:
            target = 'two-check-levels'
            write_config([{'slug': target,
                           'reason': 'harness fixture: exempted on purpose'}])
            rc2, out2 = run_check()
            cases.append((f'exempting {target!r} removes its VIOLATION from '
                          f'the run -- the declaration reaches main(), not '
                          f'just the reachability report',
                          f'VIOLATION  {target}' not in out2, out2[-900:]))
            cases.append((f'and says so out loud: {target!r} is named EXEMPT '
                          f'with its recorded reason, never silently dropped',
                          f'EXEMPT     {target}' in out2
                          and 'exempted on purpose' in out2, out2[-900:]))
            cases.append(('the summary line carries `exempted` as its own '
                          'category', ' 1 exempted' in out2, out2[-300:]))

        # THE REFUSAL, which must survive the fix: `severity: blocking` is
        # exactly the rule a downstream repo may not switch off.
        (repo / 'practices' / 'harness-blocking-fixture.md').write_text(
            '---\nslug: harness-blocking-fixture\ntitle: Fixture\n'
            'tier: on-demand\nseverity: blocking\napplies_to: ["**"]\n'
            'occasion: "testing"\nindex_clause: "a blocking fixture"\n'
            'checked_by: null\ndefines: []\nstatus: active\n'
            'supersedes: []\noverrides: null\nadded: null\n'
            'approved_by: "harness"\n---\n\n## Rule\nFixture.\n\n'
            '## Detail\n\n## Why\n\n## Story\n\n## Install\n',
            encoding='utf-8')
        write_config([{'slug': 'harness-blocking-fixture',
                       'reason': 'harness fixture: must be refused'}])
        rc3, out3 = run_check()
        cases.append(('a `severity: blocking` practice cannot be exempted: it '
                      'is not counted as EXEMPT and the refusal is stated',
                      'EXEMPT     harness-blocking-fixture' not in out3
                      and 'severity: blocking' in out3
                      and ' 0 exempted' in out3, out3[-900:]))
    finally:
        shutil.rmtree(tmp, ignore_errors=True)

    bad = [(n, d) for n, ok, d in cases if not ok]
    check(f'`not_binding` actually exempts a check, visibly, and still '
          f'refuses a blocking practice ({len(cases)} stated cases)',
          not bad,
          '; '.join(f'{n} -- {str(d)[:600]}' for n, d in bad))


def check_mirrored_prefixes_answers_both_install_models():
    """precedent_resolve.mirrored_prefixes() has to work in the install
    model that has no `process/manifest.json`, because that is the one it
    was written for.

    Every check that scans prose and must not report findings inside a
    vendored copy of somebody else's catalogue derived this privately from
    `process/manifest.json`'s `upstream.vendored_at`. That file is §1's
    bookkeeping and INSTALL.md §0 step 5 says to SKIP it, so in a §0
    install the exclusion silently evaporated and the vendored catalogue
    came back into scope: a real install's run reported dozens of
    unactionable findings inside Precedent's own historical prose, and the
    workaround downstream was to write a manifest carrying nothing but an
    `upstream` block purely to feed the signal (2026-09-10).

    Five fixtures, because "returns something" is not the property -- what
    matters is that it excludes a MIRROR and never a repo's own
    hand-authored practices. A source set declares `path: "."`; treating
    that as a mirror would blind every check inside a practice set to that
    set's own content, which is a worse failure than the one being
    fixed."""
    import shutil, tempfile
    sys.path.insert(0, str(ROOT / 'tools'))
    import precedent_resolve as pr

    tmp = pathlib.Path(tempfile.mkdtemp(prefix='precedent-mirrored-'))
    cases = []
    try:
        def write(rel, payload):
            path = tmp / rel
            path.parent.mkdir(parents=True, exist_ok=True)
            path.write_text(json.dumps(payload, indent=2), encoding='utf-8')

        # §0: vendored catalogue, a live sibling shared source, a repo-local
        # source, and NO process/manifest.json.
        (tmp / 's0' / 'precedent' / 'universal' / 'practices').mkdir(parents=True)
        (tmp / 's0' / 'local' / 'practices').mkdir(parents=True)
        write('s0/precedent.json', {
            'format_version': 1, 'visibility': 'private', 'sources': [
                {'level': 'universal', 'name': 'precedent',
                 'path': 'precedent/universal'},
                {'level': 'team', 'name': 'precedent-team-writing',
                 'path': '../precedent-team-writing'},
                {'level': 'repo-local', 'name': 'local', 'path': 'local'}]})
        s0 = pr.mirrored_prefixes(tmp / 's0')
        cases.append(('a §0 install excludes its vendored catalogue with no '
                      'process/manifest.json anywhere -- the whole point',
                      'precedent/universal/' in s0, str(s0)))
        cases.append(('and does NOT exclude its own repo-local source, which '
                      'is hand-authored', 'local/' not in s0, str(s0)))
        cases.append(('and does NOT exclude a shared source resolved from a '
                      'sibling clone outside this repo',
                      not any('precedent-team-writing' in x for x in s0),
                      str(s0)))

        # §1: the classic layout, which must keep working unchanged.
        (tmp / 's1' / 'process' / 'upstream' / 'practices').mkdir(parents=True)
        write('s1/process/manifest.json',
              {'upstream': {'vendored_at': 'process/upstream'}})
        s1 = pr.mirrored_prefixes(tmp / 's1')
        cases.append(('a §1 install still excludes process/upstream/',
                      'process/upstream/' in s1, str(s1)))

        # §1 with the manifest missing: the tree alone is enough.
        (tmp / 's1b' / 'process' / 'upstream' / 'practices').mkdir(parents=True)
        s1b = pr.mirrored_prefixes(tmp / 's1b')
        cases.append(('a process/upstream/ tree with no manifest is still a '
                      'mirror -- that is a half-finished install, not a repo '
                      'that owns the tree', 'process/upstream/' in s1b, str(s1b)))

        # A SOURCE SET: `path: "."`. Its practices/ is its own.
        (tmp / 'set' / 'practices').mkdir(parents=True)
        write('set/precedent.json', {'format_version': 1, 'sources': [
            {'level': 'universal', 'name': 'precedent', 'path': '.'}]})
        st = pr.mirrored_prefixes(tmp / 'set')
        cases.append(('a source set declaring `path: "."` mirrors NOTHING -- '
                      'excluding its own root would blind every check inside '
                      'a practice set to that set\'s content', st == (), str(st)))

        # Degradation: a caller is a check, and a check must not crash.
        cases.append(('a directory that is not a Precedent repo at all '
                      'returns an empty tuple rather than raising',
                      pr.mirrored_prefixes(tmp / 'does-not-exist') == (), ''))
        (tmp / 'broken').mkdir()
        (tmp / 'broken' / 'precedent.json').write_text('{not json',
                                                       encoding='utf-8')
        cases.append(('a malformed precedent.json returns an empty tuple '
                      'rather than raising -- a check that cannot read this '
                      'must degrade to excluding nothing, not die',
                      pr.mirrored_prefixes(tmp / 'broken') == (), ''))
    finally:
        shutil.rmtree(tmp, ignore_errors=True)

    bad = [(n, d) for n, ok, d in cases if not ok]
    check(f'mirrored_prefixes() answers in a §0 install, where '
          f'process/manifest.json does not exist ({len(cases)} stated cases)',
          not bad,
          '; '.join(f'{n} -- {d}' for n, d in bad))


def check_no_engine_tool_hardcodes_a_mirror_path():
    """No engine tool decides what it mirrors by matching a literal path.

    practice: convention-to-audit -- this convention was broken six times
    before anybody wrote it down, which is exactly the threshold that
    practice names.

    THE BUG THIS CATCHES, in its own words. `process/upstream/` is
    INSTALL.md §1's layout, and for a long time it was the only one, so
    every check that had to skip a mirrored tree simply matched that
    string. INSTALL.md §0 mirrors somewhere else entirely -- the vendored
    catalogue sits at whatever path precedent.json's `universal` source
    names -- so in a §0 install each of those exclusions silently stopped
    excluding anything, and the checks went looking inside a tree the
    consumer may not edit and cannot fix. Measured in a real §0 install
    (2026-09-10): doc_lint went red on 109 broken relative links, every one
    of them inside a mirror; technical-describes-people flagged Precedent's
    own practice file; rename-updates-links reported two findings in
    Precedent's prose for a file the consumer had deleted from its own
    tree. All unactionable, all caused by the constant meant to prevent
    exactly that.

    precedent_resolve.mirrored_prefixes() is the one authority, and it
    never raises, so there is no reason left to match a literal.

    WHAT IS DELIBERATELY STILL ALLOWED, and why the check reads calls
    rather than the whole file: the string appears legitimately in prose,
    in comments explaining this very history, and in the two documented
    import-failure fallbacks (doc_lint.py and precedent_check.py both ship
    into trees carrying no precedent_resolve.py). Only a path-matching CALL
    is a violation -- that is where the decision actually gets made."""
    import re as _re
    # A `.startswith(...)` / `.endswith(...)` call whose argument text
    # mentions the §1 mirror path: the decision site, not the prose.
    call = _re.compile(r'\.(?:startswith|endswith)\(([^)]*)\)')
    scanned = sorted((ROOT / 'tools').glob('*.py'))
    bad = []
    for f in scanned:
        rel = f.relative_to(ROOT).as_posix()
        for i, line in enumerate(f.read_text(encoding='utf-8').splitlines(), 1):
            if line.lstrip().startswith('#'):
                continue
            for m in call.finditer(line):
                if 'process/upstream/' in m.group(1):
                    bad.append(f'{rel}:{i}: {line.strip()[:90]}')
    check(f'no engine tool decides what it mirrors by matching a literal '
          f'path -- mirrored_prefixes() is the one authority '
          f'({len(scanned)} tools scanned)',
          not bad,
          '; '.join(bad))


def check_templates_point_at_gotchas_rather_than_inline_them():
    """The shipped AGENTS templates point at gotchas/ and carry no trap
    inline, and an install seeds the catalogue they point to (very deep
    check 2026-09-21 B1, fixed 2026-09-28): resident environment-gotchas
    rules the catalogue out of the instructions file, and the templates
    taught every new consumer to inline it. Discriminating case: the old
    templates' inline stale-checkout entry, which the gotcha check's own
    section parser reads as an entry."""
    import shutil, tempfile
    sys.path.insert(0, str(ROOT / 'tools'))
    import precedent_install as pi
    import precedent_check as pc
    cases = []
    for rel in ('templates/AGENTS.md.loader.template',
                'templates/AGENTS.md.template',
                'templates/document-project/AGENTS.md'):
        text = (ROOT / rel).read_text(encoding='utf-8')
        m = pc.GOTCHA_HEADING_RE.search(text)
        body = text[m.end():] if m else ''
        body = re.sub(r'<!--.*?-->', '', body, flags=re.S)
        body = body[:re.search(r'^#{1,4}\s', body, re.M).start()] \
            if re.search(r'^#{1,4}\s', body, re.M) else body
        cases.append((f'{rel} points at gotchas/ and inlines no trap',
                      m is not None and 'gotchas/' in body
                      and 'stale enough to look complete' not in body,
                      body[:200]))
    seeds = [k for k in pi.ROOT_FILES if k.startswith('gotchas/gotcha-')]
    tmp = pathlib.Path(tempfile.mkdtemp(prefix='gotcha-seed-'))
    try:
        for k in seeds:
            (tmp / k).parent.mkdir(parents=True, exist_ok=True)
            shutil.copy2(pi.TEMPLATES / pi.ROOT_FILES[k], tmp / k)
        got = pc._read_gotcha_files(tmp) or []
        ok = [g for g in got if g[1] == 'live' and g[2]
              and g[3] >= pc.STORY_MIN_WORDS and g[4] >= pc.STORY_MIN_SENTENCES]
        cases.append(('an install seeds a live gotcha with a symptom and a '
                      'story', bool(seeds) and len(ok) == len(seeds),
                      repr(got)))
    finally:
        shutil.rmtree(tmp, ignore_errors=True)
    bad = [(c[0], c[2]) for c in cases if not c[1]]
    check(f'the shipped templates point at gotchas/ and an install seeds it '
          f'({len(cases)} stated cases)',
          not bad, '; '.join(f"{n} -- {d[:300]}" for n, d in bad))


def check_installer_produces_a_clean_install():
    """tools/precedent_install.py, run against a scratch project as SETUP.md
    now runs it, yields a repo whose own gates come back clean -- and
    refuses to run twice.

    WHY (practice: cite-the-incident). The 2026-09-14 very deep check
    rehearsed INSTALL.md section 0 as written, four times over, and every
    roadblock was a document describing file operations that had drifted
    from the operations: a template's dead links, a workflow name no install
    creates, a check firing on a file the adopter never wrote. The installer
    performs the operations; this fixture is what keeps its output honest,
    by running the same checks a real adopter's first session would.

    The fixture owns its environment (practice: fixture-owns-its-state): no
    individual source, no hosted-session self-heal, no leak blocklist, and
    the global commit backstop waved for the fixture's own commit."""
    import shutil, tempfile

    tmp = pathlib.Path(tempfile.mkdtemp(prefix='precedent-installer-'))
    cases = []
    env = dict(os.environ, PRECEDENT_ALLOW_ANY_AUTHOR='1',
               PRECEDENT_USER_CONFIG=str(tmp / 'no-such-user-config.json'))
    for k in ('CLAUDE_CODE_REMOTE', 'PRECEDENT_LEAK_BLOCKLIST'):
        env.pop(k, None)

    def run(args, cwd):
        return subprocess.run(args, cwd=str(cwd), capture_output=True, text=True, env=env)

    def git(cwd, *args):
        r = subprocess.run(['git', '-C', str(cwd), *args], capture_output=True,
                           text=True, env=env)
        if r.returncode != 0:
            raise RuntimeError(f"git {' '.join(args)}: {r.stderr.strip()}")
        return r.stdout

    try:
        proj = tmp / 'proj'
        proj.mkdir()
        git(proj.parent, 'init', '-q', '-b', 'main', str(proj))
        git(proj, 'config', 'user.email', 'harness@example.com')
        git(proj, 'config', 'user.name', 'Fixture')
        (proj / 'README.md').write_text('# Field Notes\n\nA newsletter about birds.\n',
                                        encoding='utf-8')
        git(proj, 'add', '-A')
        git(proj, 'commit', '-qm', 'the project before Precedent')

        tool = str(ROOT / 'tools' / 'precedent_install.py')
        r = run([sys.executable, tool, str(proj), '--project-name', 'Field Notes',
                 '--admin', 'dana'], ROOT)
        out = r.stdout + r.stderr
        cases.append(('the installer exits 0 on a fresh project', r.returncode == 0, out[-1500:]))
        cases.append(('it says the light check on the files it wrote passed',
                      'the light check on the written files: OK' in out, out[-800:]))
        cases.append(('it names the placeholders it left rather than pretending there are none',
                      'placeholder(s) to adapt' in out, out[-800:]))
        pj = proj / 'precedent.json'
        doc = json.loads(pj.read_text(encoding='utf-8')) if pj.is_file() else {}
        cases.append(('precedent.json declares the base branch and the visibility explicitly',
                      doc.get('base_branch') == 'main' and doc.get('visibility') == 'private',
                      str(doc)[:300]))
        _map = (proj / 'MAP.md').read_text(encoding='utf-8') if (proj / 'MAP.md').is_file() else ''
        _src = (proj / 'MAP.source.md').read_text(encoding='utf-8') if (proj / 'MAP.source.md').is_file() else ''
        _gf = proj / 'tools' / 'generated_files.json'
        cases.append(('MAP.md and GLOSSARY.md start out generated, from source files '
                      'the install writes, and are on the project\'s own list '
                      '(spec/GENERATED_FILES_PLAN.md step 5)',
                      _src and _map.startswith('---\ngenerated_by: tools/build_views.py')
                      and _src.rstrip('\n') in _map
                      and (proj / 'GLOSSARY.source.md').is_file()
                      and _gf.is_file() and 'MAP.source.md' in _gf.read_text(encoding='utf-8'),
                      _map[:300]))
        agents = (proj / 'AGENTS.md').read_text(encoding='utf-8') if (proj / 'AGENTS.md').is_file() else ''
        cases.append(('AGENTS.md carries the generated loader block with the resident set in it',
                      bv.BEGIN_MARKER in agents and 'verify-postcondition' in agents, agents[:300]))
        gs = (proj / 'GETTING_STARTED.md').read_text(encoding='utf-8') if (proj / 'GETTING_STARTED.md').is_file() else ''
        cases.append(('GETTING_STARTED.md has the project name and the administrator filled in, '
                      'and no dead upstream-docs placeholder',
                      'Field Notes' in gs and '@dana' in gs and '<upstream-docs>' not in gs,
                      gs[:400]))
        # No individual source resolves here (PRECEDENT_USER_CONFIG points at
        # a file that does not exist), so ci_preference() has nothing to read
        # and the engine's own default applies (practice:
        # declared-default-is-applied) -- ENABLED since 2026-09-25, because
        # what it installs is now one light check on pull requests into main,
        # and a leak gate that never runs in a private repo
        # (spec/BRANCH_TIERS_PLAN.md). Since 2026-09-27 the light check also
        # triggers on a push to main, and its job skips that push unless the
        # repository is public -- so the push trigger must be scoped to main
        # and the job must carry that condition.
        _wfs = proj / '.github' / 'workflows'
        _lc = (_wfs / 'light-check.yml').read_text(encoding='utf-8') \
            if (_wfs / 'light-check.yml').exists() else ''
        _lg = (_wfs / 'leak-gate.yml').read_text(encoding='utf-8') \
            if (_wfs / 'leak-gate.yml').exists() else ''
        _lc_push = re.search(r'^  push:\n((?:    .*\n|\s*#.*\n)*)', _lc, re.M)
        cases.append(('nothing declares github_ci_workflows, so the installer writes the '
                      'light check -- pull requests into main, and pushes to main in a '
                      'public repo only -- and the leak gate, skipped in a private repo, '
                      'and GETTING_STARTED.md says so',
                      'branches: [main]' in _lc
                      and bool(_lc_push) and 'branches: [main]' in _lc_push.group(1)
                      and "github.event_name != 'push' || "
                          "github.event.repository.private != true" in _lc
                      and 'github.event.repository.private != true' in _lg
                      and 'Before anything reaches `main`' in gs,
                      gs[:600]))
        settings = proj / '.claude' / 'settings.json'
        stext = settings.read_text(encoding='utf-8') if settings.is_file() else ''
        cases.append(('the adapter is wired with no classic-layout allowlist entry, and every '
                      'hook it names is on disk',
                      bool(stext) and 'process/upstream' not in stext
                      and all((proj / '.claude' / 'hooks' / n).is_file() for n in
                              ('session-start.sh', 'freshness-guard.sh', 'commit-identity.sh',
                               'reply-gate.sh', 'precedent-paths.sh', 'stop-git-check.sh',
                               'stop-reply-check.sh')),
                      stext[:200]))

        git(proj, 'add', '-A')
        git(proj, 'commit', '-qm', 'Install Precedent')
        r = run([sys.executable, 'tools/precedent_sync_views.py', '--repo', '.', '--check'], proj)
        cases.append(('the committed tree is byte-identical to a fresh sync',
                      r.returncode == 0 and 'byte-identical' in r.stdout, r.stdout + r.stderr))
        r = run([sys.executable, 'tools/precedent_check.py'], proj)
        cases.append(("the project's own enforced checks come back 0 violated on the install",
                      r.returncode == 0 and ' 0 violated' in r.stdout,
                      '\n'.join(l for l in r.stdout.splitlines() if l.startswith(('VIOLATION', 'precedent_check:')))))

        r = run([sys.executable, tool, str(proj), '--project-name', 'Field Notes'], ROOT)
        cases.append(('a second run without --force is refused, naming the update path',
                      r.returncode == 1 and 'ENGINE_MANIFEST.json exists' in r.stderr
                      and 'INSTALL.md' in r.stderr, r.stderr[:300]))
        bare = tmp / 'not-a-repo'
        bare.mkdir()
        r = run([sys.executable, tool, str(bare), '--project-name', 'X'], ROOT)
        cases.append(('a directory that is not a git repository is refused with its own message',
                      r.returncode == 1 and 'not the root of a git repository' in r.stderr,
                      r.stderr[:300]))

        # The other direction (practice: control-asserts-which-failure -- a
        # default that can only say yes is not proven by the yes-case alone).
        # Since the default became enabled (2026-09-25), the direction to
        # prove is a DECLARED "disabled": nothing installed, and
        # GETTING_STARTED.md says so instead.
        indiv = tmp / 'indiv-ci-on'
        indiv.mkdir()
        (indiv / 'practices').mkdir()
        (indiv / 'practices' / 'fixture-only.md').write_text(
            '---\n'
            'slug:        fixture-only\n'
            'title:       "Fixture only"\n'
            'tier:        on-demand\n'
            'severity:    default\n'
            'applies_to:  []\n'
            'occasion:    "never -- this source exists only to give this fixture a '
            'non-empty practices/ directory"\n'
            'gates:       []\n'
            'index_clause: "fixture only, never routed for real"\n'
            'checked_by:  null\n'
            'defines:     []\n'
            'status:      active\n'
            'in_force_at: null\n'
            'supersedes:  []\n'
            'overrides:   null\n'
            'added:       null\n'
            'approved_by: "fixture"\n'
            '---\n'
            '## Rule\n'
            'Fixture only; never loaded for real.\n',
            encoding='utf-8')
        (indiv / 'identity.json').write_text(json.dumps({
            'format_version': 1, 'name': 'Dana', 'email': 'dana@example.com',
            'github_ci_workflows': 'disabled',
        }), encoding='utf-8')
        user_cfg = tmp / 'user-config-ci-on.json'
        user_cfg.write_text(json.dumps({'individual': {'path': str(indiv)}}), encoding='utf-8')
        proj2 = tmp / 'proj2'
        proj2.mkdir()
        git(proj2.parent, 'init', '-q', '-b', 'main', str(proj2))
        git(proj2, 'config', 'user.email', 'harness@example.com')
        git(proj2, 'config', 'user.name', 'Fixture')
        (proj2 / 'README.md').write_text('# Second Notes\n', encoding='utf-8')
        git(proj2, 'add', '-A')
        git(proj2, 'commit', '-qm', 'the second project before Precedent')
        env2 = dict(env, PRECEDENT_USER_CONFIG=str(user_cfg))
        r = subprocess.run([sys.executable, tool, str(proj2), '--project-name', 'Second Notes',
                            '--admin', 'dana'], cwd=str(ROOT), capture_output=True, text=True, env=env2)
        # leak-gate.yml, not bestpractice-docs.yml: the Markdown workflow was
        # retired 2026-09-21 and the leak gate is what a consumer now gets.
        wf2 = proj2 / '.github' / 'workflows' / 'leak-gate.yml'
        gs2 = (proj2 / 'GETTING_STARTED.md').read_text(encoding='utf-8') if (proj2 / 'GETTING_STARTED.md').is_file() else ''
        cases.append(('a declared github_ci_workflows: disabled installs no workflow, '
                      'and GETTING_STARTED.md carries the "off" paragraph',
                      r.returncode == 0 and not wf2.exists()
                      and not (proj2 / '.github' / 'workflows' / 'light-check.yml').exists()
                      and 'No GitHub Actions workflow was installed' in gs2,
                      (r.stdout + r.stderr)[-500:]))
        # AND the Markdown lint is NOT a GitHub check any more -- the
        # direction that would otherwise go untested, since every assertion
        # above is about a file being present.
        cases.append(('...and no Markdown workflow is installed at all, on either path',
                      not (proj2 / '.github' / 'workflows' / 'bestpractice-docs.yml').exists()
                      and not (proj / '.github' / 'workflows' / 'bestpractice-docs.yml').exists(),
                      'bestpractice-docs.yml was retired 2026-09-21'))
    finally:
        shutil.rmtree(tmp, ignore_errors=True)

    failed = [c for c in cases if not c[1]]
    check(f'tools/precedent_install.py yields a project whose own gates come back clean '
          f'({len(cases)} stated cases)', not failed,
          '; '.join(f'{n}: {d}' for n, _ok, d in failed))


def check_update_vendors_rehearsal_findings():
    """Ten defects a rehearsal of Update Vendors and a fresh install found on
    2026-09-28, run against a real consumer and a scratch one. Each group
    plants the state that exposed it and reads what the tool said or wrote.

    - A bare mention of a renamed practice (`go-merge`, now `go-update`) was
      dropped by citations(), which said "no live citation" while
      precedent_practice_refs.py --withdrawn listed one.
    - A root STYLEGUIDE.md or VOICE.md was left behind under a DONE.
    - .gitignore, installed once, never gained a line the template added.
    - An engine that landed off the fetched tip was not said.
    - A fresh install recorded none of its hooks in ENGINE_MANIFEST.json.
    - A vendored copy of the update fetched the consumer's own origin.
    - checkin.py read `origin/claude/x` as `x`, and held an install pinned
      to the branch every install follows.
    - One small edit to a template block read as the whole block missing.
    - The retired-name sweep missed precedent-team-* and MAP.md/GLOSSARY.md.
    - A run budget upstream gives a vendored tool went unmentioned."""
    import contextlib, io, tempfile
    pu, pve, _pr = _update_tools()
    tmp = pathlib.Path(tempfile.mkdtemp(prefix='precedent-rehearsal-'))
    env = dict(os.environ, GIT_AUTHOR_NAME='F', GIT_AUTHOR_EMAIL='f@example.com',
               GIT_COMMITTER_NAME='F', GIT_COMMITTER_EMAIL='f@example.com',
               GIT_CONFIG_GLOBAL=os.devnull, GIT_CONFIG_NOSYSTEM='1',
               PRECEDENT_ALLOW_ANY_AUTHOR='1')

    def git(cwd, *args):
        return subprocess.run(['git', '-C', str(cwd), *args], env=env,
                              capture_output=True, text=True)

    def verdict(name, cases):
        bad = [(n, d) for n, ok, d in cases if not ok]
        check(f'{name} ({len(cases)} stated cases)', not bad,
              '; '.join(f'{n}: {d}' for n, d in bad))

    saved_source, saved_run = pu.SOURCE, pu.run
    try:
        # -- citations: a bare mention of a withdrawn slug is listed --------
        cases = []
        fake = tmp / 'fake-source'
        (fake / 'tools').mkdir(parents=True)
        hits = [dict(source='this repository', kind='live', file='docs/X.md',
                     line=3, slug='go-merge', must_fix=False),
                dict(source='this repository', kind='live', file='docs/X.md',
                     line=5, slug='reworded-one', must_fix=False),
                dict(source='this repository', kind='live', file='docs/X.md',
                     line=7, slug='gone-hard', must_fix=True),
                dict(source='precedent', kind='live', file='practices/y.md',
                     line=1, slug='go-merge', must_fix=False)]
        argv_file = tmp / 'refs-argv.json'
        (fake / 'tools' / 'precedent_practice_refs.py').write_text(
            'import json, sys\nopen(' + repr(str(argv_file)) + ', "w").write('
            'json.dumps(sys.argv[1:]))\nprint(json.dumps(' + repr({
                'slugs': {'go-merge': 'deduplicated', 'reworded-one': 'Rule reworded',
                          'gone-hard': 'retired'},
                'successors': {'go-merge': 'go-update'}, 'hits': hits}) + '))\n',
            encoding='utf-8')
        pu.SOURCE = fake
        got = pu.citations(tmp)
        pu.SOURCE = saved_source
        fix, read = got if got else ([], [])
        cases.append(('a pointer to a withdrawn practice is still one to fix',
                      [w for w, _y in fix] == ['docs/X.md:7'], str(got)))
        cases.append(('a bare mention of a renamed practice is listed to read, '
                      'naming its successor',
                      any(r.startswith('docs/X.md:3') and 'go-update' in r
                          for r in read), str(read)))
        cases.append(('...beside a reworded one, and nothing from another source',
                      'docs/X.md:5' in read and len(read) == 2, str(read)))
        # Code too (2026-10-04, a consumer): a tool the update never touched
        # kept citing a slug a shared set had deduplicated, the update said
        # "no live citation of a withdrawn practice to fix", and only the
        # full check at Debut found it. The lookup read Markdown only.
        asked = json.loads(argv_file.read_text()) if argv_file.is_file() else []
        cases.append(('the lookup is asked to read code as well as Markdown',
                      '--code' in asked, str(asked)))
        verdict('Update Vendors lists a bare mention of a renamed practice', cases)

        # -- a vendored copy refuses before any fetch ------------------------
        cases = []
        cons = tmp / 'vendored-consumer'
        (cons / 'process' / 'upstream' / 'tools').mkdir(parents=True)
        (cons / 'tools').mkdir()
        (cons / 'tools' / pve.MANIFEST_NAME).write_text('{}', encoding='utf-8')
        (cons / 'tools' / 'precedent_vendor_engine.py').write_text('', encoding='utf-8')
        git(tmp, 'init', '-q', str(cons))
        fetched = []

        def recording_run(argv, cwd):
            if 'fetch' in argv:
                fetched.append(argv)
                return 1, 'fatal: couldn\'t find remote ref main'
            return saved_run(argv, cwd)
        pu.SOURCE = cons / 'process' / 'upstream'
        pu.run = recording_run
        out = io.StringIO()
        with contextlib.redirect_stdout(out):
            rc = pu.update(cons, skip_check=True)
        pu.SOURCE, pu.run = saved_source, saved_run
        text = out.getvalue()
        cases.append(('a copy inside a consumer\'s vendored tree FAILS, naming '
                      'the clone\'s own copy to run', rc == pu.FAILED
                      and '../BestPractice/tools/precedent_update.py --repo .' in text,
                      text[-600:]))
        cases.append(('...before any fetch', not fetched, str(fetched)))
        cases.append(('a BestPractice clone is its own clone',
                      pu.source_is_its_own_clone() is None if hasattr(
                          pu, 'source_is_its_own_clone') else False, ''))
        verdict('Update Vendors refuses to run from a vendored copy', cases)

        # -- one update over a planted consumer: legacy docs, .gitignore,
        # -- a missing run budget; then an engine that landed elsewhere -----
        tip = git(ROOT, 'rev-parse', 'HEAD').stdout.strip()

        def planted(name, landed):
            repo = tmp / name
            (repo / 'tools').mkdir(parents=True)
            (repo / 'local' / 'practices').mkdir(parents=True)
            (repo / 'tools' / pve.MANIFEST_NAME).write_text(json.dumps({
                'source_commit': landed, 'kind': 'consumer',
                'files': ['precedent_branches.py', 'github_budget.py']}),
                encoding='utf-8')
            (repo / 'tools' / 'precedent_vendor_engine.py').write_text(
                'print("precedent_vendor_engine refresh OK: already current")\n',
                encoding='utf-8')
            (repo / 'tools' / 'github_api_budgets.json').write_text(json.dumps({
                'floors': {'core': 20}, 'run_budgets': {'github_budget.py': 1}}),
                encoding='utf-8')
            (repo / 'STYLEGUIDE.md').write_text('# Style\n', encoding='utf-8')
            (repo / 'VOICE.md').write_text('# Voice\n', encoding='utf-8')
            (repo / 'local' / 'practices' / 'project-voice.md').write_text(
                '# voice\n', encoding='utf-8')
            (repo / '.gitignore').write_text('__pycache__/\nbuild/\n', encoding='utf-8')
            git(tmp, 'init', '-q', str(repo))
            git(repo, 'add', '-A')
            git(repo, 'commit', '-qm', 'installed')
            return repo

        def fetchless(argv, cwd):
            if argv[:1] == ['git'] and 'fetch' in argv:
                return 0, ''
            if argv[:1] == ['git'] and 'rev-parse' in argv \
                    and argv[-1] == f'origin/{pve.SOURCE_BRANCH}':
                return 0, tip + '\n'
            return saved_run(argv, cwd)

        def run_update(repo):
            pu.run = fetchless
            out = io.StringIO()
            try:
                with contextlib.redirect_stdout(out):
                    rc = pu.update(repo, skip_check=True)
            finally:
                pu.run = saved_run
            return rc, out.getvalue()

        cases = []
        repo = planted('planted', tip)
        rc, text = run_update(repo)
        left = text.split('LEFT FOR YOU', 1)[-1] if 'LEFT FOR YOU' in text else ''
        cases.append(('a root STYLEGUIDE.md with no project-visual-identity.md is '
                      'left for you, naming the migration step',
                      rc == pu.LEFT and '- STYLEGUIDE.md:' in left
                      and 'project-visual-identity.md' in left and 'step 3b' in left,
                      text[-1500:]))
        cases.append(('a root VOICE.md beside project-voice.md is left to delete',
                      '- VOICE.md:' in left and 'exists too' in left, left[-800:]))
        gi = (repo / '.gitignore').read_text(encoding='utf-8')
        cases.append(('.gitignore gains the template lines it lacked, its own kept once',
                      '.claude/worktrees/' in gi.splitlines()
                      and '.precedent/' in gi.splitlines()
                      and gi.splitlines().count('__pycache__/') == 1
                      and 'build/' in gi.splitlines()
                      and '.gitignore:' in text, gi))
        cases.append(('a run budget upstream gives a vendored tool, missing here, '
                      'is left for you -- and the registry is not written',
                      'tools/github_api_budgets.json: precedent_branches.py' in left
                      and 'precedent_branches' not in (repo / 'tools' /
                                                       'github_api_budgets.json').read_text(),
                      left[-800:]))
        cases.append(('...and nothing for a tool this repo already budgets',
                      'github_api_budgets.json: github_budget.py' not in left, ''))
        # A consumer whose GLOSSARY.md build_views.py generates gets the full
        # build after the sync, which renders the loader block only: a
        # practice the update stopped materializing stayed linked from it,
        # and the lint failed on the dead link (2026-09-30). A hand-written
        # one is the repo's and is not rebuilt.
        for name, header in (('generated-views', '---\ngenerated_by: '
                              'tools/build_views.py\n---\n'),
                             ('hand-views', '')):
            repo = planted(name, tip)
            (repo / 'tools' / 'precedent_sync_views.py').write_text(
                'print("synced")\n', encoding='utf-8')
            (repo / 'tools' / 'build_views.py').write_text(
                'import pathlib\n'
                'p = pathlib.Path("GLOSSARY.md")\n'
                'p.write_text(p.read_text().replace("[Plan it](practices/plan-it.md)",'
                ' ""))\n', encoding='utf-8')
            (repo / 'GLOSSARY.md').write_text(
                header + '# Glossary\n\n[Plan it](practices/plan-it.md)\n',
                encoding='utf-8')
            git(repo, 'add', '-A')
            git(repo, 'commit', '-qm', 'views')
            rc, text = run_update(repo)
            linked = 'practices/plan-it.md' in (repo / 'GLOSSARY.md').read_text()
            if header:
                cases.append(('a consumer\'s generated GLOSSARY.md is rebuilt by the '
                              'update, so a withdrawn practice is no longer linked',
                              not linked and 'GLOSSARY.md, which build_views.py '
                              'generates here' in text, text[-800:]))
            else:
                cases.append(('...and a hand-written one is left as it is',
                              linked, text[-800:]))
        elsewhere = planted('landed-elsewhere', '1' * 40)
        rc, text = run_update(elsewhere)
        cases.append(('an engine that landed off the fetched tip FAILS, saying '
                      'where it landed and where it should have',
                      rc == pu.FAILED and 'the engine landed at 111111111111' in text
                      and f'{pve.SOURCE_BRANCH} @ {tip[:12]}' in text, text[-800:]))
        verdict('Update Vendors brings install-once files and migrations forward', cases)

        # -- a command the update repoints is staged with the rest ----------
        # Found 2026-10-03 rehearsing a consumer: the repoint ran after the
        # update staged its work, so `tools/bootstrap.sh` kept calling
        # process/upstream/tools/... `|| true` in the commit the report told
        # the person to make, and the session-start step silently did nothing.
        cases = []
        repo = planted('repointed', tip)
        (repo / 'tools' / 'checkin.py').write_text('', encoding='utf-8')
        (repo / 'tools' / 'bootstrap.sh').write_text(
            'python3 process/upstream/tools/checkin.py fresh || true\n', encoding='utf-8')
        (repo / 'NOTES.md').write_text('mine\n', encoding='utf-8')
        git(repo, 'add', '-A')
        git(repo, 'commit', '-qm', 'startup script')
        (repo / 'NOTES.md').write_text('mine, unfinished\n', encoding='utf-8')
        rc, text = run_update(repo)
        staged = git(repo, 'diff', '--cached', '--name-only').stdout.split()
        unstaged = git(repo, 'diff', '--name-only').stdout.split()
        boot = git(repo, 'show', ':tools/bootstrap.sh').stdout
        cases.append(('the repointed startup script is staged, so the commit the '
                      'report asks for carries it',
                      'tools/bootstrap.sh' in staged and 'tools/bootstrap.sh' not in unstaged
                      and 'python3 tools/checkin.py fresh' in boot, text[-600:]))
        cases.append(('...and a file already uncommitted before the update stays unstaged',
                      'NOTES.md' in unstaged and 'NOTES.md' not in staged,
                      f'staged={staged} unstaged={unstaged}'))
        verdict('Update Vendors stages the commands it repoints', cases)
    finally:
        pu.SOURCE, pu.run = saved_source, saved_run

    # -- checkin.py: a slash in the default branch, and the followed branch --
    cases = []
    try:
        sys.path.insert(0, str(ROOT / 'tools'))
        try:
            import checkin
        finally:
            sys.path.pop(0)
        origin, clone = tmp / 'origin', tmp / 'clone'
        git(tmp, 'init', '-q', '-b', 'claude/x', str(origin))
        (origin / 'f').write_text('x\n', encoding='utf-8')
        git(origin, 'add', '-A')
        git(origin, 'commit', '-qm', 'x')
        subprocess.run(['git', 'clone', '-q', str(origin), str(clone)], env=env,
                       capture_output=True)
        git(clone, 'remote', 'set-head', 'origin', 'claude/x')
        cases.append(('origin/claude/x is the default branch claude/x, not x',
                      checkin._default_branch(clone) == 'claude/x',
                      checkin._default_branch(clone)))
        saved_manifest = checkin._manifest
        held = {}
        for pin in (pve.SOURCE_BRANCH, 'precedent-beta-v01'):
            checkin._manifest = lambda pin=pin: {'upstream': {'branch': pin}}
            try:
                with contextlib.redirect_stderr(io.StringIO()):
                    checkin._pinned_branch_hold(clone)
                held[pin] = False
            except SystemExit:
                held[pin] = True
        checkin._manifest = saved_manifest
        cases.append((f'an install pinned to {pve.SOURCE_BRANCH} is not held, '
                      f'whatever the clone\'s default', not held[pve.SOURCE_BRANCH],
                      str(held)))
        cases.append(('...and one pinned to any other non-default branch still is',
                      held['precedent-beta-v01'], str(held)))
    except (OSError, ImportError) as e:
        cases.append((f'fixture could not be built ({e})', False, ''))
    verdict('checkin.py reads a slashed default branch and never holds the '
            'followed branch', cases)

    # -- missing_template_blocks: a changed block is not a missing one ------
    cases = []
    tmpl = ('#!/bin/sh\n\n# Python dependencies\npip install --quiet cmarkgfm\n\n'
            'git fetch --quiet origin\ngit status --short\n\n'
            '# A block this copy does not have\necho "the freshness check"\n'
            'python3 tools/fresh.py --quiet\n')
    local = ('#!/bin/sh\n\n# Python dependencies\n'
             'pip install --quiet cmarkgfm pyyaml\n\n'
             'git fetch --quiet --prune origin\ngit status --short --branch\n\n'
             'echo "a block of this repo\'s own"\n')
    got = {title: how for _n, title, how in pve.missing_template_blocks(local, tmpl)}
    cases.append(('a block with its heading and one word added reads changed, '
                  'not missing', got.get('Python dependencies') == 'changed (1 of 1 lines)',
                  str(got)))
    cases.append(('a block with no heading, edited, reads changed by its words',
                  got.get('git fetch --quiet origin') == 'changed (2 of 2 lines)',
                  str(got)))
    cases.append(('a block nothing local resembles is still missing',
                  got.get('A block this copy does not have') == 'missing', str(got)))
    verdict('missing_template_blocks tells a changed block from a missing one', cases)

    # -- the retired-name sweep: precedent-team-*, MAP.md and GLOSSARY.md ---
    cases = []
    sweep = tmp / 'sweep'
    sweep.mkdir()
    (sweep / 'MAP.md').write_text('# Map\n\nRules come from precedent-team-writing.\n'
                                  '\n| old-rule | deduplicated | precedent-team-old |\n',
                                  encoding='utf-8')
    (sweep / 'GLOSSARY.md').write_text(
        '<!-- GENERATED by tools/build_views.py -->\nprecedent-team-writing\n',
        encoding='utf-8')
    (sweep / 'AGENTS.md').write_text(
        'Clone precedent-team-x.\n'
        'precedent-shared-x (named precedent-team-x until 2026-09-18).\n'
        'Branch precedent-beta-v01 here.\n'
        '\nThe engine was pinned to `precedent-beta-v01`, since\n'
        'renamed `staging`.\n', encoding='utf-8')
    hits = pve.retired_branch_mentions(sweep)
    cases.append(('a hand-kept MAP.md naming a precedent-team-* set is flagged',
                  ('MAP.md', 3, 'precedent-team-', 'precedent-shared-') in hits, str(hits)))
    cases.append(('...and AGENTS.md\'s, beside the retired branch name still found',
                  ('AGENTS.md', 1, 'precedent-team-', 'precedent-shared-') in hits
                  and ('AGENTS.md', 3, 'precedent-beta-v01', 'staging') in hits, str(hits)))
    cases.append(('a line recording the rename, and a file generated whole, are not',
                  not any(r == 'GLOSSARY.md' or (r, n) == ('AGENTS.md', 2)
                          for r, n, _o, _n in hits), str(hits)))
    # 2026-09-30: history that wraps was flagged, because only the line was
    # read; and a set's MAP.md lists withdrawn practices in status rows.
    cases.append(('a sentence recording the rename across a line break is '
                  'history, and so is a deduplicated row',
                  not any((r, n) in (('AGENTS.md', 5), ('MAP.md', 5))
                          for r, n, _o, _n in hits), str(hits)))
    saved_left = list(pve._LEFT_FOR_YOU)
    out = io.StringIO()
    try:
        with contextlib.redirect_stdout(out):
            pve._report_retired_branch_names(sweep)
        said = out.getvalue()
        cases.append(('the report names the prefix rename without calling it a branch',
                      'RETIRED NAME: 2 line(s)' in said and 'precedent-shared-*' in said
                      and 'RETIRED BRANCH NAME: 1 line(s)' in said, said[-600:]))
    except (KeyError, TypeError) as e:
        cases.append((f'the report ran ({type(e).__name__}: {e})', False, ''))
    finally:
        pve._LEFT_FOR_YOU[:] = saved_left
    verdict('the retired-name sweep covers precedent-team-* and the index files', cases)

    # -- a fresh install tracks its hooks ------------------------------------
    cases = []
    ienv = dict(env, PRECEDENT_USER_CONFIG=str(tmp / 'no-such-user-config.json'))
    for k in ('CLAUDE_CODE_REMOTE', 'PRECEDENT_LEAK_BLOCKLIST'):
        ienv.pop(k, None)
    proj = tmp / 'proj'
    try:
        subprocess.run(['git', 'init', '-q', '-b', 'main', str(proj)], env=ienv,
                       capture_output=True, check=True)
        (proj / 'README.md').write_text('# Notes\n', encoding='utf-8')
        git(proj, 'add', '-A')
        git(proj, 'commit', '-qm', 'before')
        r = subprocess.run([sys.executable, str(ROOT / 'tools' / 'precedent_install.py'),
                            str(proj), '--project-name', 'Notes'], cwd=str(ROOT),
                           env=ienv, capture_output=True, text=True)
        m = json.loads((proj / 'tools' / pve.MANIFEST_NAME).read_text(encoding='utf-8'))
        hooks = sorted(p.name for p in (proj / '.claude' / 'hooks').glob('*.sh'))
        recorded = m.get('hooks_sha256') or {}
        cases.append(('a fresh install records every hook it wrote, by hash',
                      r.returncode == 0 and bool(hooks)
                      and sorted(m.get('hook_files') or []) == hooks
                      and all(recorded.get(h) == hashlib.sha256(
                          (proj / '.claude' / 'hooks' / h).read_bytes()).hexdigest()
                          for h in hooks),
                      f'rc={r.returncode} on disk={hooks} recorded={sorted(recorded)} '
                      + (r.stdout + r.stderr)[-400:]))
    except (OSError, ValueError, subprocess.CalledProcessError) as e:
        cases.append((f'fixture could not be built ({e})', False, ''))
    finally:
        shutil.rmtree(tmp, ignore_errors=True)
    verdict('a fresh install tracks its hooks in ENGINE_MANIFEST.json', cases)


def check_update_repoints_moved_engine_commands():
    """Update Vendors rewrites `process/upstream/tools/X` to `tools/X` in
    AGENTS.md, CLAUDE.md and .claude/settings.json once the mirror is gone
    and tools/X is there (2026-10-01, from a consumer's Update Vendors:
    three AGENTS.md commands and an allowlist entry kept naming the gone
    path). A guarded fallback, a generated block and a file with no copy in
    tools/ are left as they are."""
    import tempfile
    pu, _pve, _pr = _update_tools()
    tmp = pathlib.Path(tempfile.mkdtemp(prefix='precedent-repoint-'))
    cases = []
    try:
        repo = tmp / 'consumer'
        (repo / 'tools').mkdir(parents=True)
        (repo / 'tools' / 'practice_audit.py').write_text('', encoding='utf-8')
        (repo / '.claude').mkdir()
        agents = ('Run `python3 process/upstream/tools/practice_audit.py` weekly.\n'
                  'if [ -f process/upstream/tools/practice_audit.py ]; then :; fi\n'
                  'And `python3 process/upstream/tools/gone_tool.py`.\n'
                  '<!-- BEGIN GENERATED: precedent-loader -->\n'
                  'process/upstream/tools/practice_audit.py\n'
                  '<!-- END GENERATED: precedent-loader -->\n')
        (repo / 'AGENTS.md').write_text(agents, encoding='utf-8')
        (repo / '.claude' / 'settings.json').write_text(
            '{"permissions": {"allow": ["Bash(python3 process/upstream/tools/'
            'practice_audit.py:*)"]}}\n', encoding='utf-8')
        # The consumer's own startup script, as one carried it (2026-10-01):
        # unguarded calls to files the update removed, a guarded fallback,
        # and a vendored hook, which is the engine's to rewrite.
        (repo / 'tools' / 'checkin.py').write_text('', encoding='utf-8')
        (repo / 'tools' / 'bootstrap.sh').write_text(
            'python3 process/upstream/tools/checkin.py update || true\n'
            'python3 process/upstream/tools/practice_audit.py\n'
            '[ -f process/upstream/tools/checkin.py ] && echo old\n'
            'python3 process/upstream/tools/gone_tool.py\n', encoding='utf-8')
        (repo / '.claude' / 'hooks').mkdir()
        (repo / '.claude' / 'hooks' / 'h.sh').write_text(
            'python3 process/upstream/tools/checkin.py\n', encoding='utf-8')
        subprocess.run(['git', 'init', '-q', str(repo)], capture_output=True)
        subprocess.run(['git', '-C', str(repo), 'add', '-A'], capture_output=True)
        done, stranded = pu.repoint_moved_engine_mentions(repo)
        done = dict(done)
        text = (repo / 'AGENTS.md').read_text(encoding='utf-8').split('\n')
        cases.append(('the AGENTS.md command now names tools/',
                      text[0] == 'Run `python3 tools/practice_audit.py` weekly.', text[0]))
        cases.append(('the guarded fallback is left alone',
                      'process/upstream/tools/practice_audit.py' in text[1], text[1]))
        cases.append(('a file with no copy in tools/ is left alone (the check reports it)',
                      'process/upstream/tools/gone_tool.py' in text[2], text[2]))
        cases.append(('a generated block is left to build_views',
                      text[4] == 'process/upstream/tools/practice_audit.py', text[4]))
        cases.append(('the settings.json allowlist entry now names tools/',
                      'python3 tools/practice_audit.py' in
                      (repo / '.claude' / 'settings.json').read_text(encoding='utf-8'), ''))
        boot = (repo / 'tools' / 'bootstrap.sh').read_text(encoding='utf-8').split('\n')
        cases.append(('the startup script\'s unguarded calls now name tools/',
                      boot[0].startswith('python3 tools/checkin.py')
                      and boot[1] == 'python3 tools/practice_audit.py', str(boot)))
        cases.append(('...its guarded fallback is left alone',
                      '[ -f process/upstream/tools/checkin.py ]' in boot[2],
                      boot[2]))
        cases.append(('...a call to a file tools/ lacks is named, not rewritten',
                      ('tools/bootstrap.sh', 4, 'process/upstream/tools/gone_tool.py')
                      in stranded and 'gone_tool' in boot[3], str(stranded)))
        cases.append(('a vendored hook is the engine\'s to rewrite, not this step\'s',
                      'process/upstream' in (repo / '.claude' / 'hooks' / 'h.sh')
                      .read_text(encoding='utf-8'), ''))
        cases.append(('and each file is reported with its count',
                      done == {'AGENTS.md': 1, '.claude/settings.json': 1,
                               'tools/bootstrap.sh': 2}, str(done)))
    finally:
        shutil.rmtree(tmp, ignore_errors=True)
    bad = [(n, d) for n, ok, d in cases if not ok]
    check(f'Update Vendors repoints commands that name a moved engine file '
          f'({len(cases)} stated cases)', not bad,
          '; '.join(f'{n}: {d}' for n, d in bad))


def check_update_in_force_nowhere_asks_once():
    """A rule in force nowhere is asked about until precedent.json records
    that it does not apply here, by slug or by the set it lives in, and
    then said in one line instead (2026-10-01, from a consumer's Update
    Vendors: sixteen of them asked on every update, under a header that
    contradicted itself)."""
    import contextlib, io, tempfile
    pu, _pve, _pr = _update_tools()
    tmp = pathlib.Path(tempfile.mkdtemp(prefix='precedent-nowhere-'))
    cases = []
    out = ('precedent_sync_views: IN FORCE NOWHERE -- doc-link-text '
           '(precedent-shared-repo-maintenance): status: deduplicated names '
           'in_force_at: doc-link-text, but nothing resolves it\n'
           'precedent_sync_views: IN FORCE NOWHERE -- old-rule (precedent): '
           'withdrawn from universal on 2026-09-20; in force in '
           '`precedent-shared-writing` -- declare that set to keep it\n')
    try:
        repo = tmp / 'consumer'
        repo.mkdir()

        def run(cfg):
            (repo / 'precedent.json').write_text(json.dumps(cfg), encoding='utf-8')
            rep = pu.Report()
            with contextlib.redirect_stdout(io.StringIO()):
                pu.in_force_nowhere_step(repo, rep, out)
                buf = io.StringIO()
                with contextlib.redirect_stdout(buf):
                    rep.close()
            return rep, buf.getvalue()
        rep, text = run({})
        cases.append(('unrecorded, each is asked, with the snippet that records it',
                      len(rep.asks) == 2 and all('not_in_force_here' in q
                                                 for _w, q in rep.asks), str(rep.asks)))
        cases.append(('...naming the set when the finding knows it',
                      any('`precedent-shared-writing`' in q for _w, q in rep.asks),
                      str(rep.asks)))
        cases.append(('the header no longer contradicts itself',
                      'blocks the update' not in text and 'before Go update'
                      not in text and 'QUESTIONS FOR THE PERSON' in text, text[-600:]))
        rep, _ = run({'not_in_force_here': {'doc-link-text': 'we dropped that set',
                                            'precedent-shared-writing': 'dropped'}})
        cases.append(('recorded by slug and by set, nothing is asked',
                      not rep.asks, str(rep.asks)))
        cases.append(('...and they are said in one step line',
                      [n for n, _o in rep.steps] == ['not in force here, on purpose'],
                      str(rep.steps)))
    finally:
        shutil.rmtree(tmp, ignore_errors=True)
    bad = [(n, d) for n, ok, d in cases if not ok]
    check(f'Update Vendors asks about a rule in force nowhere until it is '
          f'recorded ({len(cases)} stated cases)', not bad,
          '; '.join(f'{n}: {d}' for n, d in bad))


def check_update_leaves_no_dead_manifest_entry():
    """Update Vendors never says DONE over a manifest entry naming a missing
    file, whichever step deleted it (2026-10-01, from a consumer's Update
    Vendors: the catalogue sweep removed a tree, its doc-lint entry stayed,
    and practice_audit.py failed after DONE). Asked of the result, so a
    deleting step written later is covered too.

    Stated cases: an entry inside the mirrored tree, and one for a file
    this update deleted, go with their files; one for the repo's own file,
    missing for no reason this update knows, is left for the person; a
    declined entry and one whose file exists are untouched."""
    import contextlib, io, tempfile
    pu, pve, _pr = _update_tools()
    tmp = pathlib.Path(tempfile.mkdtemp(prefix='precedent-dead-manifest-'))
    cases = []
    try:
        repo = tmp / 'consumer'
        (repo / 'process').mkdir(parents=True)
        (repo / 'docs').mkdir()
        (repo / 'docs' / 'here.md').write_text('x\n', encoding='utf-8')
        (repo / 'docs' / 'removed.md').write_text('x\n', encoding='utf-8')
        (repo / 'process' / 'upstream' / 'practices').mkdir(parents=True)
        (repo / 'process' / 'upstream' / 'practices' / 'p.md').write_text('x\n',
                                                                        encoding='utf-8')
        (repo / 'precedent.json').write_text(json.dumps({'sources': [
            {'level': 'universal', 'name': 'precedent', 'path': 'process/upstream'}]}),
            encoding='utf-8')
        entries = [
            {'name': 'upstream:doc-lint', 'local_path': 'process/upstream/tools/doc_lint.py'},
            {'name': 'removed', 'local_path': 'docs/removed.md'},
            {'name': 'own', 'local_path': 'docs/never-there.md'},
            {'name': 'declined', 'local_path': 'docs/declined.md', 'status': 'declined',
             'notes': 'not for us'},
            {'name': 'here', 'local_path': 'docs/here.md'}]
        (repo / 'process' / 'manifest.json').write_text(
            json.dumps({'entries': entries}), encoding='utf-8')
        env = dict(os.environ, GIT_AUTHOR_NAME='t', GIT_AUTHOR_EMAIL='t@t',
                   GIT_COMMITTER_NAME='t', GIT_COMMITTER_EMAIL='t@t')
        for a in (['init', '-q'], ['add', '-A'], ['commit', '-qm', 'base'],
                  ['rm', '-q', 'docs/removed.md']):
            subprocess.run(['git', '-C', str(repo), *a], capture_output=True, env=env)
        cases.append(('the shared question sees the three dead entries, not the '
                      'declined one',
                      sorted(n for _m, n, _r in pve.dead_manifest_entries(repo))
                      == ['own', 'removed', 'upstream:doc-lint'],
                      str(pve.dead_manifest_entries(repo))))
        rep = pu.Report()
        with contextlib.redirect_stdout(io.StringIO()):
            pu.manifest_postcondition(repo, rep)
        left = [e['name'] for e in json.loads((repo / 'process' / 'manifest.json')
                                              .read_text(encoding='utf-8'))['entries']]
        cases.append(('entries in the mirror, and for a file this update deleted, '
                      'go with their files', left == ['own', 'declined', 'here'],
                      str(left)))
        cases.append(('...said in one step line', any(n == 'manifest' for n, _o in rep.steps),
                      str(rep.steps)))
        cases.append(('the repo\'s own missing file is left for the person, so '
                      'the run cannot say DONE',
                      [w for w, _y in rep.left] == ['process/manifest.json: own'],
                      str(rep.left)))
        cases.append(('the update runs the postcondition',
                      'manifest_postcondition(' in __import__('inspect').getsource(pu.update),
                      ''))
    finally:
        shutil.rmtree(tmp, ignore_errors=True)
    bad = [(n, d) for n, ok, d in cases if not ok]
    check(f'Update Vendors leaves no manifest entry naming a missing file '
          f'({len(cases)} stated cases)', not bad,
          '; '.join(f'{n}: {d}' for n, d in bad))


def check_update_done_names_the_check_it_ran():
    """Update Vendors' DONE says which check it ran, that the full check did
    not run, and passes on a size-cap warning the check printed.

    2026-10-01, from a consumer's Update Vendors: the update printed "check
    for pre-staging: passed" and DONE; the consumer's full check then failed
    three ways on the same tree, one of them a size cap this update's own
    regenerated AGENTS.md block had pushed over. The basic check is right
    for pre-staging; reading as the push gate's all-clear was not."""
    import contextlib, io, tempfile
    pu, _pve, _pr = _update_tools()
    tmp = pathlib.Path(tempfile.mkdtemp(prefix='precedent-done-tier-'))
    cases = []
    real = pu.check_with_merge_fallback
    try:
        repo = tmp / 'consumer'
        (repo / 'tools').mkdir(parents=True)
        (repo / 'tools' / 'precedent_push_check.py').write_text('', encoding='utf-8')
        (repo / 'precedent.json').write_text(json.dumps(
            {'base_branch': 'main', 'landing_branch': 'pre-staging'}), encoding='utf-8')
        subprocess.run(['git', 'init', '-q', str(repo)], capture_output=True)
        saved = os.environ.get('PRECEDENT_USER_CONFIG')
        os.environ['PRECEDENT_USER_CONFIG'] = str(tmp / 'no-config.json')

        def run(out):
            pu.check_with_merge_fallback = lambda _r, _rep, _a, _l: (0, out)
            rep = pu.Report()
            buf = io.StringIO()
            with contextlib.redirect_stdout(buf):
                rc = pu.closing_check(repo, rep)
            return rc, buf.getvalue()
        try:
            rc, out = run('precedent_push_check: all passed\n')
            cases.append(('the step names the tier it ran',
                          'basic check for pre-staging: passed' in out, out[-600:]))
            cases.append(('DONE says the full check was NOT run, and how to run it',
                          rc == pu.DONE and 'full check was NOT run' in out
                          and '--tier full' in out, out[-600:]))
            rc, out = run('passed\nWARNING: over a session-load size cap '
                          '(changed_practice, above). Allowed onto pre-staging; '
                          'the Debut into staging refuses it.\n')
            cases.append(('a size-cap warning the check printed is repeated '
                          'beside DONE', 'WARNING: over a session-load size cap'
                          in out.split('== Update Vendors ==')[-1], out[-600:]))
        finally:
            if saved is None:
                os.environ.pop('PRECEDENT_USER_CONFIG', None)
            else:
                os.environ['PRECEDENT_USER_CONFIG'] = saved
    finally:
        pu.check_with_merge_fallback = real
        shutil.rmtree(tmp, ignore_errors=True)
    bad = [(n, d) for n, ok, d in cases if not ok]
    check(f'Update Vendors\' DONE names the check it ran and the one it did '
          f'not ({len(cases)} stated cases)', not bad,
          '; '.join(f'{n}: {d}' for n, d in bad))


def check_update_vendors_reports_dropped_template_wording():
    """An install-once file still carrying wording its template has since
    dropped is left for the person, by file and line -- and nothing else is.

    2026-09-28, very deep check: the files an install writes once from a
    template (the PR template, TODO.md, MAP.md ...) kept old wording -- a
    "TODO.md updated" checklist line, links to a retired branch -- and no
    update said so. The report must flag only an exact line an older
    version of the template carried and the current one does not, so a
    repo's own lines are never flagged; it must never write the file; and a
    file precedent.json records as kept on purpose, against the current
    template, must stop being listed."""
    import contextlib, inspect, io, tempfile
    pu, pve, _pr = _update_tools()
    tmp = pathlib.Path(tempfile.mkdtemp(prefix='precedent-dropped-wording-'))
    env = dict(os.environ, GIT_AUTHOR_NAME='F', GIT_AUTHOR_EMAIL='f@example.com',
               GIT_COMMITTER_NAME='F', GIT_COMMITTER_EMAIL='f@example.com',
               GIT_CONFIG_GLOBAL=os.devnull, GIT_CONFIG_NOSYSTEM='1',
               PRECEDENT_ALLOW_ANY_AUTHOR='1')

    def git(cwd, *args):
        return subprocess.run(['git', '-C', str(cwd), *args], env=env,
                              capture_output=True, text=True)

    cases = []
    saved_source = pu.SOURCE
    step = getattr(pu, 'dropped_template_lines_step', None)
    try:
        src = tmp / 'source'
        (src / 'templates').mkdir(parents=True)
        git(tmp, 'init', '-q', str(src))
        tmpl = src / 'templates' / 'TODO.md.template'
        tmpl.write_text('# Open items live in this file for now\n'
                        '## Old\n'
                        '- [ ] TODO.md updated with the items opened and closed\n'
                        'See [the plan](https://example.com/blob/old-branch/spec/PLAN.md) for more.\n'
                        'Every open item is tracked in one place here.\n',
                        encoding='utf-8')
        git(src, 'add', '-A')
        git(src, 'commit', '-qm', 'v1')
        tmpl.write_text('# Open items live under todo/ now\n'
                        'See [the plan](https://example.com/blob/staging/spec/PLAN.md) for more.\n'
                        'Every open item is tracked in one place here.\n',
                        encoding='utf-8')
        git(src, 'add', '-A')
        git(src, 'commit', '-qm', 'v2')
        rev = git(src, 'rev-parse', 'HEAD').stdout.strip()

        repo = tmp / 'consumer'
        repo.mkdir()
        body = ('# Open items live in this file for now\n'
                '## Old\n'
                '- [ ] TODO.md updated with the items opened and closed\n'
                'See [the plan](https://example.com/blob/old-branch/spec/PLAN.md) for more.\n'
                'Every open item is tracked in one place here.\n'
                'Our own note about the billing export, written by this repo.\n')
        (repo / 'TODO.md').write_text(body, encoding='utf-8')
        pu.SOURCE = src

        if step is None:
            cases.append(('precedent_update has a dropped-template-wording step',
                          False, 'dropped_template_lines_step is missing'))
        else:
            rep = pu.Report()
            with contextlib.redirect_stdout(io.StringIO()):
                step(repo, rep, rev)
            left = dict(rep.left)
            cases.append(('a line an older template carried and the current one '
                          'dropped is left for you, by file and line',
                          'TODO.md:3' in left and 'is template wording the current '
                          'template dropped: - [ ] TODO.md updated' in left['TODO.md:3'],
                          str(rep.left)))
            cases.append(('...and so is a reworded one, a link to a retired branch',
                          'TODO.md:4' in left and 'old-branch' in left['TODO.md:4']
                          and 'TODO.md:1' in left, str(rep.left)))
            cases.append(('a line the current template still carries, the '
                          'repo\'s own line, and a too-short heading are not',
                          sorted(left) == ['TODO.md:1', 'TODO.md:3', 'TODO.md:4'],
                          str(sorted(left))))
            cases.append(('the file is only reported, never written',
                          (repo / 'TODO.md').read_text(encoding='utf-8') == body, ''))
            cases.append(('the first item says how to record it as kept, with the '
                          'current template\'s hash',
                          any(pve.KEPT_DIVERGENCES_KEY in d and hashlib.sha256(
                              tmpl.read_bytes()).hexdigest() in d
                              for d in rep.details.get('TODO.md:1', [])),
                          str(rep.details)))

            sha = hashlib.sha256(tmpl.read_bytes()).hexdigest()
            (repo / 'precedent.json').write_text(json.dumps({
                pve.KEPT_DIVERGENCES_KEY: {'TODO.md': {
                    'reason': 'kept on purpose', 'template_sha256': sha}}}),
                encoding='utf-8')
            rep = pu.Report()
            with contextlib.redirect_stdout(io.StringIO()):
                step(repo, rep, rev)
            cases.append(('a file recorded as kept against the current template '
                          'is said once and not listed',
                          not rep.left and any(n == 'kept on purpose'
                                               for n, _o in rep.steps),
                          str(rep.left)))
            (repo / 'precedent.json').write_text(json.dumps({
                pve.KEPT_DIVERGENCES_KEY: {'TODO.md': {
                    'reason': 'kept on purpose', 'template_sha256': '0' * 64}}}),
                encoding='utf-8')
            rep = pu.Report()
            with contextlib.redirect_stdout(io.StringIO()):
                step(repo, rep, rev)
            cases.append(('...and listed again once the template has changed since',
                          len(rep.left) == 3, str(rep.left)))
            cases.append(('Update Vendors runs the step',
                          'dropped_template_lines_step(' in inspect.getsource(pu.update),
                          ''))
    except (OSError, ValueError) as e:
        cases.append((f'fixture could not be built ({e})', False, ''))
    finally:
        pu.SOURCE = saved_source
        shutil.rmtree(tmp, ignore_errors=True)
    bad = [(n, d) for n, ok, d in cases if not ok]
    check(f'Update Vendors reports install-once wording its template dropped '
          f'({len(cases)} stated cases)', not bad,
          '; '.join(f'{n}: {d}' for n, d in bad))


def check_update_vendors_dropped_wording_reads_placeholders_filled():
    """A line that is the CURRENT template's line with its placeholders
    filled in is not dropped wording, even when it equals an older template
    line word for word.

    2026-10-01, from a consumer's Update Vendors: GETTING_STARTED.md's
    template once wrote `process/upstream/` and now writes `<upstream-docs>/`,
    and a §1 install is told to replace the second with the first. The
    install did exactly that, and the update listed the result as wording
    the template had dropped. A line an older template had that no current
    line can be filled in to produce is still listed."""
    import contextlib, io, tempfile
    pu, _pve, _pr = _update_tools()
    tmp = pathlib.Path(tempfile.mkdtemp(prefix='precedent-dropped-filled-'))
    env = dict(os.environ, GIT_AUTHOR_NAME='F', GIT_AUTHOR_EMAIL='f@example.com',
               GIT_COMMITTER_NAME='F', GIT_COMMITTER_EMAIL='f@example.com',
               GIT_CONFIG_GLOBAL=os.devnull, GIT_CONFIG_NOSYSTEM='1',
               PRECEDENT_ALLOW_ANY_AUTHOR='1')

    def git(cwd, *args):
        return subprocess.run(['git', '-C', str(cwd), *args], env=env,
                              capture_output=True, text=True)

    cases = []
    saved_source = pu.SOURCE
    try:
        src = tmp / 'source'
        (src / 'templates').mkdir(parents=True)
        git(tmp, 'init', '-q', str(src))
        tmpl = src / 'templates' / 'TODO.md.template'
        tmpl.write_text('<!-- not just a mention in the install log under\n'
                        '     `process/upstream/`. Add a line whenever a future install step\n'
                        '     introduces a new one. -->\n'
                        'Read the guide in process/upstream/documentation before you start.\n',
                        encoding='utf-8')
        git(src, 'add', '-A')
        git(src, 'commit', '-qm', 'v1')
        tmpl.write_text('<!-- not just a mention in the install log under\n'
                        '     `<upstream-docs>/`. Add a line whenever a future install step\n'
                        '     introduces a new one. -->\n'
                        'Read the guide at <upstream-docs> before you begin.\n',
                        encoding='utf-8')
        git(src, 'add', '-A')
        git(src, 'commit', '-qm', 'v2')
        rev = git(src, 'rev-parse', 'HEAD').stdout.strip()

        repo = tmp / 'consumer'
        repo.mkdir()
        (repo / 'TODO.md').write_text(
            '<!-- not just a mention in the install log under\n'
            '     `process/upstream/`. Add a line whenever a future install step\n'
            '     introduces a new one. -->\n'
            'Read the guide in process/upstream/documentation before you start.\n',
            encoding='utf-8')
        pu.SOURCE = src
        rep = pu.Report()
        with contextlib.redirect_stdout(io.StringIO()):
            pu.dropped_template_lines_step(repo, rep, rev)
        left = dict(rep.left)
        cases.append(('the current line with its placeholder filled in is not '
                      'listed, though an older template had it verbatim',
                      'TODO.md:2' not in left, str(rep.left)))
        cases.append(('a line no current line can be filled in to make still is',
                      'TODO.md:4' in left, str(rep.left)))
    except (OSError, ValueError) as e:
        cases.append((f'fixture could not be built ({e})', False, ''))
    finally:
        pu.SOURCE = saved_source
        shutil.rmtree(tmp, ignore_errors=True)
    bad = [(n, d) for n, ok, d in cases if not ok]
    check(f'Update Vendors reads a template\'s placeholders as filled in '
          f'({len(cases)} stated cases)', not bad,
          '; '.join(f'{n}: {d}' for n, d in bad))


def check_update_vendors_dropped_wording_reads_a_views_source():
    """Dropped template wording in a GENERATED MAP.md or GLOSSARY.md is
    reported in its source file, never in the view.

    Since 2026-10-03 those two views are rebuilt from MAP.source.md /
    GLOSSARY.source.md. The update still read the view, so a consumer was
    told to delete lines from MAP.md that the next sync wrote straight back,
    and the update never reached DONE (very deep check's install rehearsal,
    2026-10-05). Planted: an old template line in a generated MAP.md and in
    its MAP.source.md; the same in the directory form; a generated view with
    no source; and a hand-written MAP.md, which is still the repo's own and
    still read."""
    import contextlib, io, tempfile
    pu, _pve, _pr = _update_tools()
    tmp = pathlib.Path(tempfile.mkdtemp(prefix='precedent-dropped-source-'))
    env = dict(os.environ, GIT_AUTHOR_NAME='F', GIT_AUTHOR_EMAIL='f@example.com',
               GIT_COMMITTER_NAME='F', GIT_COMMITTER_EMAIL='f@example.com',
               GIT_CONFIG_GLOBAL=os.devnull, GIT_CONFIG_NOSYSTEM='1',
               PRECEDENT_ALLOW_ANY_AUTHOR='1')

    def git(cwd, *args):
        return subprocess.run(['git', '-C', str(cwd), *args], env=env,
                              capture_output=True, text=True)

    old = 'This map was written by the older template wording here.'
    view = ('---\ngenerated_by: tools/build_views.py\n---\n# Map\n\n'
            + old + '\n')
    cases = []
    saved_source = pu.SOURCE
    try:
        src = tmp / 'source'
        (src / 'templates').mkdir(parents=True)
        git(tmp, 'init', '-q', str(src))
        tmpl = src / 'templates' / 'MAP.md.template'
        tmpl.write_text('# Map\n\n' + old + '\n', encoding='utf-8')
        git(src, 'add', '-A')
        git(src, 'commit', '-qm', 'v1')
        tmpl.write_text('# Map\n\nThe current template says something else.\n',
                        encoding='utf-8')
        git(src, 'add', '-A')
        git(src, 'commit', '-qm', 'v2')
        rev = git(src, 'rev-parse', 'HEAD').stdout.strip()
        pu.SOURCE = src

        def left_for(build):
            repo = tmp / f'consumer-{len(cases)}'
            repo.mkdir()
            build(repo)
            rep = pu.Report()
            with contextlib.redirect_stdout(io.StringIO()):
                pu.dropped_template_lines_step(repo, rep, rev)
            return {k for k, _ in rep.left}

        def with_source(repo):
            (repo / 'MAP.md').write_text(view, encoding='utf-8')
            (repo / 'MAP.source.md').write_text('# Map\n\n' + old + '\n',
                                                encoding='utf-8')
        left = left_for(with_source)
        cases.append(('a generated view with a source file: the line is '
                      'reported in MAP.source.md, never in MAP.md',
                      any(k.startswith('MAP.source.md:') for k in left)
                      and not any(k.startswith('MAP.md:') for k in left),
                      str(left)))

        def with_folder(repo):
            (repo / 'MAP.md').write_text(view, encoding='utf-8')
            (repo / 'MAP.source').mkdir()
            (repo / 'MAP.source' / 'intro.md').write_text(old + '\n',
                                                         encoding='utf-8')
        left = left_for(with_folder)
        cases.append(('the directory form: reported in the entry file that '
                      'carries it', any(k.startswith('MAP.source/intro.md:')
                                        for k in left)
                      and not any(k.startswith('MAP.md:') for k in left),
                      str(left)))

        def no_source(repo):
            (repo / 'MAP.md').write_text(view, encoding='utf-8')
        left = left_for(no_source)
        cases.append(('a generated view with no source has nothing a person '
                      'can edit, so nothing is listed', not left, str(left)))

        def hand_written(repo):
            (repo / 'MAP.md').write_text('# Map\n\n' + old + '\n',
                                         encoding='utf-8')
        left = left_for(hand_written)
        cases.append(('a hand-written MAP.md is the repo\'s own and still read',
                      any(k.startswith('MAP.md:') for k in left), str(left)))
    except (OSError, ValueError) as e:
        cases.append((f'fixture could not be built ({e})', False, ''))
    finally:
        pu.SOURCE = saved_source
        shutil.rmtree(tmp, ignore_errors=True)
    bad = [(n, d) for n, ok, d in cases if not ok]
    check(f'Update Vendors reports a generated view\'s dropped wording in its '
          f'source ({len(cases)} stated cases)', not bad,
          '; '.join(f'{n}: {d}' for n, d in bad))


def check_session_start_hook_runs_bootstrap_locally():
    """The Claude Code adapter's SessionStart hook runs tools/bootstrap.sh in
    a local session too, marked PRECEDENT_LOCAL_SESSION=1, and bootstrap.sh
    then skips only what belongs to a container.

    Until 2026-09-28 the hook exited unless CLAUDE_CODE_REMOTE=true, so a
    local Claude Code session got none of bootstrap.sh. Morgan approved
    running it locally, with the package install left out there. Planted: a
    bootstrap.sh that records it ran and what the variable said; an old one
    that never reads the variable (not run locally, since it would pip
    install); and both real bootstrap scripts with a fake pip and a fake
    commit-identity.sh on the path, run local and remote."""
    import tempfile
    tmp = pathlib.Path(tempfile.mkdtemp(prefix='precedent-local-session-'))
    hook = ROOT / 'templates' / 'harness' / 'claude-code' / 'hooks' / 'session-start.sh'
    base = {k: v for k, v in os.environ.items()
            if k != 'CLAUDE_CODE_REMOTE' and not k.startswith('PRECEDENT_')}
    base['GIT_CEILING_DIRECTORIES'] = str(tmp)
    cases = []

    def run(script, cwd, **extra):
        return subprocess.run(['bash', str(script)], cwd=str(cwd),
                              env=dict(base, **extra), capture_output=True,
                              text=True, timeout=60)

    try:
        proj = tmp / 'proj'
        (proj / 'tools').mkdir(parents=True)
        record = tmp / 'ran.txt'
        (proj / 'tools' / 'bootstrap.sh').write_text(
            '#!/bin/bash\n'
            f'echo "ran local=${{PRECEDENT_LOCAL_SESSION:-unset}}" > "{record}"\n',
            encoding='utf-8')
        r = run(hook, proj, CLAUDE_PROJECT_DIR=str(proj))
        got = record.read_text(encoding='utf-8').strip() if record.exists() else ''
        cases.append(('with CLAUDE_CODE_REMOTE unset the hook runs bootstrap.sh, '
                      'with PRECEDENT_LOCAL_SESSION=1',
                      r.returncode == 0 and got == 'ran local=1',
                      f'rc={r.returncode} record={got!r} {r.stderr[-300:]}'))
        record.unlink(missing_ok=True)
        r = run(hook, proj, CLAUDE_PROJECT_DIR=str(proj), CLAUDE_CODE_REMOTE='true')
        got = record.read_text(encoding='utf-8').strip() if record.exists() else ''
        cases.append(('...and a remote session runs it without the mark',
                      r.returncode == 0 and got == 'ran local=unset',
                      f'rc={r.returncode} record={got!r}'))

        old = tmp / 'old'
        (old / 'tools').mkdir(parents=True)
        (old / 'tools' / 'bootstrap.sh').write_text(
            f'#!/bin/bash\necho ran > "{record}"\n', encoding='utf-8')
        record.unlink(missing_ok=True)
        r = run(hook, old, CLAUDE_PROJECT_DIR=str(old))
        cases.append(('a bootstrap.sh that never reads the variable is not run '
                      'locally, and the hook says why without failing',
                      r.returncode == 0 and not record.exists()
                      and 'predates local sessions' in r.stderr,
                      f'rc={r.returncode} ran={record.exists()} {r.stderr[-300:]}'))
        r = run(hook, old, CLAUDE_PROJECT_DIR=str(old), CLAUDE_CODE_REMOTE='true')
        cases.append(('...but still is on a remote session', record.exists(), ''))

        fakebin = tmp / 'bin'
        fakebin.mkdir()
        calls = tmp / 'calls.txt'
        (fakebin / 'pip').write_text(f'#!/bin/sh\necho pip >> "{calls}"\n',
                                     encoding='utf-8')
        os.chmod(fakebin / 'pip', 0o755)
        path = f'{fakebin}{os.pathsep}{base.get("PATH", "")}'
        for rel in ('templates/bootstrap.sh', 'tools/bootstrap.sh'):
            work = tmp / ('w-' + rel.replace('/', '-'))
            (work / '.claude' / 'hooks').mkdir(parents=True)
            (work / '.claude' / 'hooks' / 'commit-identity.sh').write_text(
                f'#!/bin/sh\necho identity >> "{calls}"\n', encoding='utf-8')
            for local in (True, False):
                calls.unlink(missing_ok=True)
                extra = {'PATH': path}
                if local:
                    extra['PRECEDENT_LOCAL_SESSION'] = '1'
                r = run(ROOT / rel, work, **extra)
                did = calls.read_text(encoding='utf-8').split() if calls.exists() else []
                if local:
                    cases.append((f'{rel}, local: no pip install and no '
                                  f'commit-identity.sh, and one line saying so',
                                  r.returncode == 0 and did == []
                                  and 'local session -- skipped pip install' in r.stderr,
                                  f'rc={r.returncode} calls={did} {r.stderr[-300:]}'))
                else:
                    cases.append((f'{rel}, remote: both still run',
                                  r.returncode == 0 and did == ['pip', 'identity'],
                                  f'rc={r.returncode} calls={did} {r.stderr[-300:]}'))
    except (OSError, subprocess.SubprocessError) as e:
        cases.append((f'fixture could not be built ({e})', False, ''))
    finally:
        shutil.rmtree(tmp, ignore_errors=True)
    bad = [(n, d) for n, ok, d in cases if not ok]
    check(f'the SessionStart hook runs bootstrap.sh in a local session, minus '
          f'the container steps ({len(cases)} stated cases)', not bad,
          '; '.join(f'{n}: {d}' for n, d in bad))


def check_move_fixes_mentions_of_the_moved_practice():
    """After a move withdraws the source copy, tools/precedent_move.py fixes
    what still says the practice lives there -- in both sets and in every
    other repository in force -- and leaves history as written.

    WHY. Morgan, 2026-09-28 (strength: decided), on a finding that moves
    repaired broken links but nothing searched for other mentions: "I don't
    need a detailed report but for those problems to be solved." Measured
    the same day: the individual set's own README and a sibling practice
    still linked the stub of a practice that had left the set.

    Every planted mention is asserted by its resulting text, and so is every
    planted non-mention -- a dated line, a Story, an unrelated line naming
    the old set -- because a fixer that rewrote everything would pass the
    first half alone."""
    import shutil, tempfile
    tmp = pathlib.Path(tempfile.mkdtemp(prefix='precedent-mentions-'))
    env = dict(os.environ, PRECEDENT_ALLOW_ANY_AUTHOR='1',
               PRECEDENT_USER_CONFIG=str(tmp / 'no-such-user-config.json'))
    env.pop('CLAUDE_CODE_REMOTE', None)

    def run(args, extra_env=None):
        return subprocess.run([sys.executable, *args], cwd=str(ROOT),
                              capture_output=True, text=True,
                              env=dict(env, **(extra_env or {})))

    def practice(slug, rule, story):
        return ('---\nslug:        ' + slug + '\n'
                'title:       A fixture practice\n'
                'tier:        on-demand\nseverity:    default\n'
                'applies_to:  ["fixture/**"]\noccasion:    "fixture"\n'
                'gates:       []\nindex_clause: "fixture"\nchecked_by:  null\n'
                'defines:     []\nstatus:      active\nin_force_at: null\n'
                'supersedes:  []\noverrides:   null\nadded:       "2026-09-14"\n'
                'approved_by: "Fixture, 2026-09-14"\n---\n\n## Rule\n' + rule
                + '\n\n## Why\nBecause.\n\n## Story\n' + story + '\n')

    results = []
    try:
        boot = str(ROOT / 'tools' / 'precedent_bootstrap_source.py')
        team, indiv, other = (tmp / 'precedent-team-fixture',
                              tmp / 'precedent-individual', tmp / 'other')
        run([boot, '--level', 'team', '--name', 'precedent-team-fixture',
             '--dest', str(team), '--approver', 'Fixture Approver:fixture-gh'])
        run([boot, '--level', 'individual', '--name', 'precedent-individual',
             '--dest', str(indiv)])
        (other / 'docs').mkdir(parents=True)
        (indiv / 'practices' / 'zz-moves.md').write_text(
            practice('zz-moves', 'Do the thing.', 'A dated incident.'))
        (indiv / 'practices' / 'zz-cites.md').write_text(practice(
            'zz-cites', 'Follow [zz-moves](zz-moves.md#rule) first.',
            'Once [zz-moves](zz-moves.md) lived here.'))
        (indiv / 'NOTES.md').write_text(
            'Present: `zz-moves` is a precedent-individual rule.\n\n'
            'History: on 2026-09-01 `zz-moves` sat in precedent-individual.\n')
        (team / 'NOTES.md').write_text(
            'See [zz-moves](../precedent-individual/practices/zz-moves.md).\n')
        (other / 'docs' / 'x.md').write_text(
            'URL https://github.com/example/precedent-individual/blob/main/practices/'
            'zz-moves.md here\n'
            'path ../precedent-individual/practices/zz-moves.md here\n'
            'unrelated precedent-individual line\n\n'
            '`precedent-individual` has this check vendored -- `zz-moves`\n\n'
            'This set shows the shape in '
            '[zz-moves](../../precedent-individual/practices/zz-moves.md).\n')
        for repo in (indiv, team, other):
            subprocess.run(['git', 'init', '-q', str(repo)], capture_output=True)
            subprocess.run(['git', '-C', str(repo), 'add', '-A'],
                           capture_output=True)
        r = run([str(ROOT / 'tools' / 'precedent_move.py'), '--slug', 'zz-moves',
                 '--from', 'individual', '--from-path', str(indiv),
                 '--to', 'team', '--to-path', str(team),
                 '--approved-by', 'Fixture Approver'],
                {'PRECEDENT_MOVE_MENTION_REPOS': str(other)})
        cites = (indiv / 'practices' / 'zz-cites.md').read_text()
        inotes = (indiv / 'NOTES.md').read_text()
        tnotes = (team / 'NOTES.md').read_text()
        x = (other / 'docs' / 'x.md').read_text()
        results = [
            ('the move completes', r.returncode == 0),
            ('a sibling link to the stub becomes the backticked slug, never a '
             'URL into the other set', 'Follow `zz-moves` first.' in cites),
            ('a present-tense line naming the old set names the new one',
             '`zz-moves` is a precedent-team-fixture rule' in inotes),
            ('a link in the destination set is re-pointed at its own copy',
             '[zz-moves](practices/zz-moves.md)' in tnotes),
            ('a URL to the old copy in another repo becomes the slug',
             'URL `zz-moves` here' in x),
            ('a path to the old copy names the new set',
             'path ../precedent-team-fixture/practices/zz-moves.md here' in x),
            ('a dated line is history and stays as written',
             'on 2026-09-01 `zz-moves` sat in precedent-individual.' in inotes),
            ('the Story stays as written',
             'Once [zz-moves](zz-moves.md) lived here.' in cites),
            ('a line about the old set that does not name the practice stays',
             'unrelated precedent-individual line' in x),
            ('a line naming the old set for another reason keeps it '
             '(where it lives is the only claim rewritten)',
             '`precedent-individual` has this check vendored -- `zz-moves`' in x),
            ('a fixed link inside a sentence saying the practice is HERE is '
             'named for a person to reword',
             'reword by hand: other/docs/x.md:' in r.stdout),
            ('each repository changed is named for committing',
             'mentions fixed in:' in r.stdout and str(other) in r.stdout),
        ]
    finally:
        shutil.rmtree(tmp, ignore_errors=True)
    failed = [n for n, ok in results if not ok]
    check(f'a practice move fixes what still says it lives where it was, and '
          f'leaves history alone ({len(results)} stated cases)',
          bool(results) and not failed, '; '.join(failed))


def check_move_tool_lands_then_deduplicates():
    """tools/precedent_move.py does spec/MOVING_PRACTICES.md's two steps in
    the one safe order, records the move at both ends, and refuses the
    states the procedure says never to produce.

    WHY (practice: cite-the-incident). The procedure told a mover to feed an
    existing practice's four sections through precedent_candidate.py, which
    takes one --proposed-rule string; every move was a hand copy and the
    deduplication was done from memory. Morgan, 2026-09-14: "I've had bumps
    doing that." The fixture owns its environment (practice:
    fixture-owns-its-state): no individual source, no hosted-session
    self-heal, the commit backstop waved."""
    import shutil, tempfile

    tmp = pathlib.Path(tempfile.mkdtemp(prefix='precedent-move-'))
    cases = []
    env = dict(os.environ, PRECEDENT_ALLOW_ANY_AUTHOR='1',
               PRECEDENT_USER_CONFIG=str(tmp / 'no-such-user-config.json'),
               # The mention fix reads only the fixture sets, never the real
               # repositories this clone resolves.
               PRECEDENT_MOVE_MENTION_REPOS='')
    env.pop('CLAUDE_CODE_REMOTE', None)

    def run(args, cwd=ROOT):
        return subprocess.run([sys.executable, *args], cwd=str(cwd),
                              capture_output=True, text=True, env=env)

    def practice(slug, story='A dated incident.'):
        return ('---\nslug:        ' + slug + '\n'
                'title:       A fixture practice\n'
                'tier:        on-demand\nseverity:    default\n'
                'applies_to:  ["fixture/**"]\noccasion:    "fixture"\n'
                'gates:       []\nindex_clause: "fixture"\nchecked_by:  null\n'
                'defines:     []\nstatus:      active\nin_force_at: null\n'
                'supersedes:  []\noverrides:   null\nadded:       "2026-09-14"\n'
                'approved_by: "Fixture, 2026-09-14"\n---\n\n## Rule\nDo the thing.\n\n'
                '## Why\nBecause.\n\n## Story\n' + story + '\n')

    try:
        tool = str(ROOT / 'tools' / 'precedent_move.py')
        boot = str(ROOT / 'tools' / 'precedent_bootstrap_source.py')
        team, indiv = tmp / 'precedent-team-fixture', tmp / 'precedent-individual'
        r1 = run([boot, '--level', 'team', '--name', 'precedent-team-fixture',
                  '--dest', str(team), '--approver', 'Fixture Approver:fixture-gh'])
        r2 = run([boot, '--level', 'individual', '--name', 'precedent-individual',
                  '--dest', str(indiv)])
        cases.append(('both fixture sets bootstrap', r1.returncode == 0 and r2.returncode == 0,
                      (r1.stdout + r1.stderr + r2.stdout + r2.stderr)[-600:]))
        (indiv / 'practices' / 'zz-moves.md').write_text(practice('zz-moves'), encoding='utf-8')
        (indiv / 'practices' / 'zz-no-story.md').write_text(practice('zz-no-story', ''), encoding='utf-8')

        # -- the move, individual -> team --
        r = run([tool, '--slug', 'zz-moves', '--from', 'individual', '--from-path', str(indiv),
                 '--to', 'team', '--to-path', str(team), '--approved-by', 'Fixture Approver',
                 '--strength', 'decided'])
        cases.append(('individual -> team completes', r.returncode == 0, r.stdout + r.stderr))
        dest = (team / 'practices' / 'zz-moves.md')
        src = (indiv / 'practices' / 'zz-moves.md')
        dtext = dest.read_text(encoding='utf-8') if dest.is_file() else ''
        stext = src.read_text(encoding='utf-8')
        cases.append(('the destination copy is active, carries the Rule and Story verbatim, '
                      'the approval, and its strength',
                      'status:      active' in dtext and 'Do the thing.' in dtext
                      and 'A dated incident.' in dtext and 'Fixture Approver' in dtext
                      and 'strength: decided' in dtext, dtext[:600]))
        cases.append(('the source copy is deduplicated, points at the slug, and its Story '
                      'says where it went',
                      'status:      deduplicated' in stext and 'in_force_at: zz-moves' in stext
                      and 'Moved to the shared set `precedent-team-fixture`' in stext, stext[-400:]))
        cases.append(('the disclosure names both sets and the level',
                      'DISCLOSE TO THE HUMAN' in r.stdout and 'shared set precedent-team-fixture' in r.stdout
                      and 'individual set precedent-individual' in r.stdout, r.stdout[-400:]))

        # -- sibling links that do not travel are re-homed by the move itself --
        # On 2026-09-23 a moved practice kept its relative links to siblings
        # that stayed in a private set, and the hand repair pointed them at
        # that set by URL. The move now does the repair: a universal
        # practice gets its universal URL, anything else its backticked slug.
        (indiv / 'practices' / 'zz-left-behind.md').write_text(
            practice('zz-left-behind'), encoding='utf-8')
        (indiv / 'practices' / 'zz-links.md').write_text(
            practice('zz-links', 'See [`zz-left-behind`](zz-left-behind.md), '
                     '[the rule](zz-left-behind.md#rule), '
                     '[park-it](park-it.md) and `[kept](zz-left-behind.md)`.'),
            encoding='utf-8')
        r = run([tool, '--slug', 'zz-links', '--from', 'individual', '--from-path', str(indiv),
                 '--to', 'team', '--to-path', str(team), '--approved-by', 'Fixture Approver'])
        ltext = ((team / 'practices' / 'zz-links.md').read_text(encoding='utf-8')
                 if (team / 'practices' / 'zz-links.md').is_file() else '')
        cases.append(('a move re-homes sibling links that do not travel: the backticked '
                      'slug for a set practice, the universal URL for a universal one, '
                      'and a link inside a code span untouched',
                      r.returncode == 0
                      and 'See `zz-left-behind`, the rule (`zz-left-behind`)' in ltext
                      and '/practices/park-it.md)' in ltext
                      and '`[kept](zz-left-behind.md)`' in ltext
                      and str(indiv) not in ltext and 'precedent-individual/blob' not in ltext
                      and 'rewrote a sibling link' in r.stdout,
                      (r.stdout + r.stderr)[-600:] + ltext[-400:]))

        # -- a consumer resolving both sets sees the practice from the team, once --
        consumer = tmp / 'consumer'
        consumer.mkdir()
        (consumer / 'precedent.json').write_text(json.dumps({
            'format_version': 1, 'visibility': 'private',
            'sources': [{'level': 'universal', 'name': 'precedent', 'path': str(ROOT)},
                        {'level': 'team', 'name': 'precedent-team-fixture', 'path': str(team)}],
        }), encoding='utf-8')
        cfg = tmp / 'user-config.json'
        cfg.write_text(json.dumps({'individual': {'name': 'precedent-individual',
                                                  'path': str(indiv)}}), encoding='utf-8')
        r = subprocess.run([sys.executable, str(ROOT / 'tools' / 'precedent_resolve.py'),
                            '--repo', str(consumer), '--json'],
                           capture_output=True, text=True,
                           env=dict(env, PRECEDENT_USER_CONFIG=str(cfg)))
        try:
            resolved = json.loads(r.stdout)
        except json.JSONDecodeError:
            resolved = {}
        levels = {p['slug']: p['level'] for p in resolved.get('practices', [])}
        cases.append(('a consumer resolving both sets gets the moved practice from the '
                      'team, once, and the deduplicated copy is not reported as a collision',
                      levels.get('zz-moves') == 'shared'
                      and not resolved.get('blocked'), (r.stdout + r.stderr)[:600]))

        # -- the resolver names a forwarding address that resolves nowhere --
        # (the rehearsal of 2026-09-14 found that only this harness ever
        # asked; a set or a consumer ran the shape check alone)
        ipath = indiv / 'practices' / 'zz-moves.md'
        itext = ipath.read_text(encoding='utf-8')
        ipath.write_text(itext.replace('in_force_at: zz-moves', 'in_force_at: zz-nowhere'),
                         encoding='utf-8')
        r = subprocess.run([sys.executable, str(ROOT / 'tools' / 'precedent_resolve.py'),
                            '--repo', str(consumer), '--json'],
                           capture_output=True, text=True,
                           env=dict(env, PRECEDENT_USER_CONFIG=str(cfg)))
        try:
            dangling = json.loads(r.stdout).get('dangling') or []
        except json.JSONDecodeError:
            dangling = []
        cases.append(('a deduplicated copy whose in_force_at resolves nowhere is reported '
                      'by the resolver itself, not only by this harness',
                      any(d.get('slug') == 'zz-moves' and 'does not resolve IN FORCE' in d.get('why', '')
                          for d in dangling), (r.stdout + r.stderr)[-500:]))
        ipath.write_text(itext, encoding='utf-8')

        # -- a copy-and-delete, the thing the procedure says never to do, is named by sync --
        (consumer / 'AGENTS.md').write_text('# notes\n\n<!-- BEGIN GENERATED: precedent-loader -->\n'
                                            '<!-- END GENERATED -->\n', encoding='utf-8')
        (team / 'practices' / 'zz-copied.md').write_text(practice('zz-copied'), encoding='utf-8')
        cenv = dict(env, PRECEDENT_USER_CONFIG=str(cfg))
        subprocess.run(['git', 'init', '-q'], cwd=str(consumer), capture_output=True)
        sync_tool = str(ROOT / 'tools' / 'precedent_sync_views.py')
        r = subprocess.run([sys.executable, sync_tool, '--repo', str(consumer)],
                           capture_output=True, text=True, env=cenv)
        subprocess.run(['git', 'add', '-A'], cwd=str(consumer), capture_output=True)
        subprocess.run(['git', '-c', 'user.name=fx', '-c', 'user.email=fx',
                        'commit', '-q', '-m', 'sync'], cwd=str(consumer),
                       capture_output=True, env=cenv)
        cases.append(('the consumer committed a synced MANIFEST.json recording zz-copied from the team',
                      r.returncode == 0 and 'zz-copied' in (consumer / 'MANIFEST.json').read_text(encoding='utf-8'),
                      (r.stdout + r.stderr)[-400:]))
        shutil.copy(team / 'practices' / 'zz-copied.md', indiv / 'practices' / 'zz-copied.md')
        (team / 'practices' / 'zz-copied.md').unlink()
        r = subprocess.run([sys.executable, sync_tool, '--repo', str(consumer)],
                           capture_output=True, text=True, env=cenv)
        cases.append(('copying the file to the other set and deleting the original is named '
                      'as a copy-and-delete by the next sync, and the sync still writes',
                      r.returncode == 0 and 'copy-and-delete' in r.stderr
                      and 'zz-copied was recorded from precedent-team-fixture' in r.stderr,
                      (r.stdout + r.stderr)[-500:]))
        (team / 'practices' / 'zz-copied.md').write_text(
            (indiv / 'practices' / 'zz-copied.md').read_text(encoding='utf-8')
            .replace('status:      active', 'status:      deduplicated')
            .replace('in_force_at: null', 'in_force_at: zz-copied'), encoding='utf-8')
        r = subprocess.run([sys.executable, sync_tool, '--repo', str(consumer)],
                           capture_output=True, text=True, env=cenv)
        cases.append(('and a deduplicated copy left at the source, pointing across, is a record: '
                      'the same sync says nothing',
                      r.returncode == 0 and 'copy-and-delete' not in r.stderr,
                      (r.stdout + r.stderr)[-500:]))

        # -- refusals, each by its own message --
        r = run([tool, '--slug', 'zz-no-story', '--from', 'individual', '--from-path', str(indiv),
                 '--to', 'team', '--to-path', str(team), '--approved-by', 'Fixture Approver'])
        cases.append(('an empty Story is refused, naming the fill-it-first rule',
                      r.returncode == 1 and 'empty ## Story' in r.stderr, r.stderr[:300]))
        cases.append(('and the refusal wrote nothing',
                      not (team / 'practices' / 'zz-no-story.md').exists(), ''))
        r = run([tool, '--slug', 'zz-moves', '--from', 'team', '--from-path', str(team),
                 '--to', 'individual', '--to-path', str(indiv), '--approved-by', 'Anyone'])
        cases.append(('a destination that already carries the slug is refused',
                      r.returncode == 1 and 'already exists' in r.stderr, r.stderr[:300]))
        (team / 'practices' / 'zz-team-only.md').write_text(practice('zz-team-only'), encoding='utf-8')
        (indiv / 'practices' / 'zz-second.md').write_text(practice('zz-second'), encoding='utf-8')
        r = run([tool, '--slug', 'zz-second', '--from', 'individual', '--from-path', str(indiv),
                 '--to', 'team', '--to-path', str(team), '--approved-by', 'Nobody'])
        cases.append(('an approver not listed in the shared set is refused by name',
                      r.returncode == 1 and 'not in' in r.stderr and 'approver' in r.stderr,
                      r.stderr[:300]))
        # -- universal -> team duplicates, never deduplicates, on landing;
        # only a deliberate --dedupe-only --accept-reach-loss withdraws the
        # universal copy. A fixture universal clone, not this checkout's own
        # practices/, the same reason 'team -> universal' below uses one. --
        uclone = tmp / 'precedent-universal-fixture'
        (uclone / 'practices').mkdir(parents=True)
        (uclone / 'practices' / 'zz-universal.md').write_text(practice('zz-universal'), encoding='utf-8')
        r = run([tool, '--slug', 'zz-universal', '--from', 'universal', '--from-path', str(uclone),
                 '--to', 'universal', '--to-path', str(uclone), '--approved-by', 'Fixture Approver'])
        cases.append(('universal -> universal is refused as nothing to move',
                      r.returncode == 1 and 'nothing to move' in r.stderr, r.stderr[:300]))
        r = run([tool, '--slug', 'zz-universal', '--from', 'universal', '--from-path', str(uclone),
                 '--to', 'team', '--to-path', str(team), '--approved-by', 'Fixture Approver'])
        utext = (uclone / 'practices' / 'zz-universal.md').read_text(encoding='utf-8')
        ttext2 = (team / 'practices' / 'zz-universal.md').read_text(encoding='utf-8') \
            if (team / 'practices' / 'zz-universal.md').is_file() else ''
        cases.append(('universal -> team lands at the destination and completes',
                      r.returncode == 0 and 'status:      active' in ttext2, r.stdout + r.stderr))
        cases.append(('the universal copy stays ACTIVE, not deduplicated -- both are in force',
                      'status:      active' in utext and 'in_force_at: null' in utext
                      and 'Also landed' in utext, utext[-500:]))
        cases.append(('the disclosure says both copies are in force and names the deliberate '
                      'withdrawal command',
                      'ALSO lives' in r.stdout and 'NOT deduplicated' in r.stdout
                      and '--dedupe-only --accept-reach-loss' in r.stdout, r.stdout[-500:]))
        r = run([tool, '--slug', 'zz-universal', '--from', 'universal', '--from-path', str(uclone),
                 '--to', 'team', '--to-path', str(team), '--dedupe-only'])
        cases.append(('--dedupe-only on a universal source is refused without --accept-reach-loss',
                      r.returncode == 1 and '--accept-reach-loss' in r.stderr, r.stderr[:400]))
        cases.append(('and the refusal left the universal copy untouched',
                      (uclone / 'practices' / 'zz-universal.md').read_text(encoding='utf-8') == utext, ''))
        r = run([tool, '--slug', 'zz-universal', '--from', 'universal', '--from-path', str(uclone),
                 '--to', 'team', '--to-path', str(team), '--dedupe-only', '--accept-reach-loss'])
        utext = (uclone / 'practices' / 'zz-universal.md').read_text(encoding='utf-8')
        cases.append(('--dedupe-only --accept-reach-loss withdraws the universal copy',
                      r.returncode == 0 and 'status:      deduplicated' in utext
                      and 'in_force_at: zz-universal' in utext
                      and 'WITHDRAWN from universal' in r.stdout, r.stdout + r.stderr))

        # -- team -> universal drafts, leaves the source active, and dedupes on request --
        clone = tmp / 'precedent-clone'
        clone.mkdir()
        (clone / 'practices').mkdir()
        r = run([tool, '--slug', 'zz-team-only', '--from', 'team', '--from-path', str(team),
                 '--to', 'universal', '--to-path', str(clone), '--approved-by', 'Fixture Approver'])
        ttext = (team / 'practices' / 'zz-team-only.md').read_text(encoding='utf-8')
        cases.append(('team -> universal drafts into the clone and leaves the source ACTIVE',
                      r.returncode == 0 and (clone / 'practices' / 'zz-team-only.md').is_file()
                      and 'status:      active' in ttext and 'DRAFTED' in r.stdout,
                      r.stdout + r.stderr))
        cases.append(('the draft says the clone\'s own generated surfaces were (or here could not be) '
                      'regenerated, and when it is safe to --dedupe-only: after the merge AND '
                      'after every consumer has taken the catalogue',
                      'tools/build_views.py' in r.stdout and 'doc_sync.py' in r.stdout
                      and 'every repository consuming' in r.stdout, r.stdout[-700:]))
        r = run([tool, '--slug', 'zz-team-only', '--from', 'team', '--from-path', str(team),
                 '--to', 'universal', '--to-path', str(clone), '--approved-by', 'Fixture Approver',
                 '--dedupe-only'])
        ttext = (team / 'practices' / 'zz-team-only.md').read_text(encoding='utf-8')
        cases.append(('--dedupe-only afterwards withdraws the source copy',
                      r.returncode == 0 and 'status:      deduplicated' in ttext
                      and 'in_force_at: zz-team-only' in ttext, r.stdout + r.stderr))
    finally:
        shutil.rmtree(tmp, ignore_errors=True)

    failed = [c for c in cases if not c[1]]
    check(f'tools/precedent_move.py lands first, deduplicates second, and refuses the '
          f'unsafe states by name ({len(cases)} stated cases)', not failed,
          '; '.join(f'{n}: {d}' for n, _ok, d in failed))


def _move_fixture_env(tmp):
    """The environment every move fixture below runs its tools in: no
    individual source, no hosted-session self-heal, the commit backstop
    waved, and a mention fix that reads only the fixture's own repositories
    (practice: fixture-owns-its-state)."""
    env = dict(os.environ, PRECEDENT_ALLOW_ANY_AUTHOR='1',
               PRECEDENT_USER_CONFIG=str(tmp / 'no-such-user-config.json'),
               PRECEDENT_MOVE_MENTION_REPOS='')
    env.pop('CLAUDE_CODE_REMOTE', None)
    return env


def _move_fixture_practice(slug, story='A dated incident.', install=None):
    """A minimal practice file, optionally with an ## Install section."""
    return ('---\nslug:        ' + slug + '\n'
            'title:       A fixture practice\n'
            'tier:        on-demand\nseverity:    default\n'
            'applies_to:  ["fixture/**"]\noccasion:    "fixture"\n'
            'gates:       []\nindex_clause: "fixture"\nchecked_by:  null\n'
            'defines:     []\nstatus:      active\nin_force_at: null\n'
            'supersedes:  []\noverrides:   null\nadded:       "2026-09-14"\n'
            'approved_by: "Fixture, 2026-09-14"\n---\n\n## Rule\nDo the thing.\n\n'
            '## Why\nBecause.\n\n## Story\n' + story + '\n'
            + ('' if install is None else '\n## Install\n' + install + '\n'))


def check_move_tool_covers_every_direction_and_team_removals():
    """The directions check_move_tool_lands_then_deduplicates does not run
    -- team to individual, universal to individual, individual to universal
    -- and the approval a TEAM REMOVAL needs, which the tool never checked.

    WHY. A very deep check on 2026-09-28 rehearsed every direction and found
    three things this fixture now holds: spec/MOVING_PRACTICES.md said the
    harness moved a practice "through every direction" when it ran three;
    a team copy was deduplicated on the DESTINATION's approval alone, and
    `--dedupe-only` from a team asked for no name at all, though the
    procedure says removing a team's practice is that team's approvers'
    call; and a universal draft with no ## Install passed every fast check
    and failed the harness. Separately, the Story line a move appends went
    to the end of the FILE, which is inside ## Install whenever the file
    has one -- so it is planted with one here."""
    import shutil, tempfile
    tmp = pathlib.Path(tempfile.mkdtemp(prefix='precedent-move-dirs-'))
    env = _move_fixture_env(tmp)
    cases = []

    def run(*args):
        return subprocess.run([sys.executable, str(ROOT / 'tools' / 'precedent_move.py'),
                               *args], cwd=str(ROOT), capture_output=True, text=True,
                              env=env)

    def text(p):
        return p.read_text(encoding='utf-8') if p.is_file() else ''

    try:
        boot = str(ROOT / 'tools' / 'precedent_bootstrap_source.py')
        team, indiv = tmp / 'precedent-team-fixture', tmp / 'precedent-individual'
        for args in ((boot, '--level', 'team', '--name', 'precedent-team-fixture',
                      '--dest', str(team), '--approver', 'Fixture Approver:fixture-gh'),
                     (boot, '--level', 'individual', '--name', 'precedent-individual',
                      '--dest', str(indiv))):
            subprocess.run([sys.executable, *args], capture_output=True, text=True, env=env)
        uclone = tmp / 'precedent-universal-fixture'
        (uclone / 'practices').mkdir(parents=True)
        P = _move_fixture_practice
        (team / 'practices' / 'zz-down.md').write_text(
            P('zz-down', install='Nothing to install.'), encoding='utf-8')
        (team / 'practices' / 'zz-guarded.md').write_text(P('zz-guarded'), encoding='utf-8')
        (uclone / 'practices' / 'zz-out.md').write_text(P('zz-out'), encoding='utf-8')
        (indiv / 'practices' / 'zz-up.md').write_text(P('zz-up'), encoding='utf-8')

        # -- team -> individual: a removal from the team needs ITS approver --
        r = run('--slug', 'zz-guarded', '--from', 'team', '--from-path', str(team),
                '--to', 'individual', '--to-path', str(indiv), '--approved-by', 'Somebody Else')
        cases.append(('team -> individual by a name the team does not list is refused as a '
                      'REMOVAL needing that team\'s approver, and writes nothing',
                      r.returncode == 1 and 'removing a practice from a shared set' in r.stderr
                      and not (indiv / 'practices' / 'zz-guarded.md').exists()
                      and 'status:      active' in text(team / 'practices' / 'zz-guarded.md'),
                      r.stderr[-400:]))
        r = run('--slug', 'zz-down', '--from', 'team', '--from-path', str(team),
                '--to', 'individual', '--to-path', str(indiv), '--approved-by', 'Fixture Approver')
        src, dest = text(team / 'practices' / 'zz-down.md'), text(indiv / 'practices' / 'zz-down.md')
        story = src[src.find('## Story'):src.find('## Install')]
        cases.append(('team -> individual lands active and deduplicates the team copy',
                      r.returncode == 0 and 'status:      active' in dest
                      and 'status:      deduplicated' in src and 'in_force_at: zz-down' in src,
                      (r.stdout + r.stderr)[-500:]))
        cases.append(('the team copy\'s Story line names who approved the removal, and sits '
                      'in ## Story -- not after ## Install, where nothing reads a Story',
                      'removal from `precedent-team-fixture` approved by Fixture Approver'
                      in story and 'Moved to the individual set' in story
                      and src.rstrip().endswith('Nothing to install.'), src[-700:]))

        # -- --dedupe-only from a team needs --approved-by at all --
        (indiv / 'practices' / 'zz-guarded.md').write_text(P('zz-guarded'), encoding='utf-8')
        r = run('--slug', 'zz-guarded', '--from', 'team', '--from-path', str(team),
                '--to', 'individual', '--to-path', str(indiv), '--dedupe-only')
        cases.append(('--dedupe-only from a shared set with no --approved-by is refused',
                      r.returncode == 1 and '--approved-by' in r.stderr
                      and 'status:      active' in text(team / 'practices' / 'zz-guarded.md'),
                      r.stderr[-400:]))

        # -- universal -> individual: duplicate, then a deliberate withdrawal --
        r = run('--slug', 'zz-out', '--from', 'universal', '--from-path', str(uclone),
                '--to', 'individual', '--to-path', str(indiv), '--approved-by', 'Owner')
        u = text(uclone / 'practices' / 'zz-out.md')
        cases.append(('universal -> individual lands the copy and keeps the universal one ACTIVE',
                      r.returncode == 0 and 'status:      active' in u
                      and 'status:      active' in text(indiv / 'practices' / 'zz-out.md'),
                      (r.stdout + r.stderr)[-500:]))
        r = run('--slug', 'zz-out', '--from', 'universal', '--from-path', str(uclone),
                '--to', 'individual', '--to-path', str(indiv), '--dedupe-only',
                '--accept-reach-loss', '--approved-by', 'Owner')
        u = text(uclone / 'practices' / 'zz-out.md')
        cases.append(('universal -> individual withdraws with --accept-reach-loss, and the '
                      'Story line names the set and who approved it',
                      r.returncode == 0 and 'status:      deduplicated' in u
                      and '--accept-reach-loss (approved by Owner)' in u
                      and 'from the individual set `precedent-individual`' in u,
                      (r.stdout + r.stderr)[-500:]))

        # -- individual -> universal: a draft, given the ## Install it lacked --
        clone = tmp / 'precedent-clone'
        (clone / 'practices').mkdir(parents=True)
        r = run('--slug', 'zz-up', '--from', 'individual', '--from-path', str(indiv),
                '--to', 'universal', '--to-path', str(clone), '--approved-by', 'Owner')
        draft = clone / 'practices' / 'zz-up.md'
        try:
            _fm, secs = sp._read_practice_file(draft)
        except Exception:                                    # noqa: BLE001
            secs = {}
        cases.append(('individual -> universal drafts, leaves the source active, and gives '
                      'the draft the ## Install every universal practice carries -- saying so',
                      r.returncode == 0 and 'install' in secs and 'DRAFTED' in r.stdout
                      and 'ADDED an empty ## Install' in r.stdout
                      and 'status:      active' in text(indiv / 'practices' / 'zz-up.md'),
                      (r.stdout + r.stderr)[-500:]))

        # -- a universal draft is put in the spec's field order, and an
        #    on-demand one with no applies_to_why is told to add it
        #    (2026-10-05: five drafts from working-style failed the deep
        #    check on both) --
        import frontmatter_yaml
        shuffled = P('zz-order').replace('in_force_at: null\n', '').replace(
            'approved_by: "Fixture, 2026-09-14"\n',
            'approved_by: "Fixture, 2026-09-14"\nin_force_at: null\n')
        (indiv / 'practices' / 'zz-order.md').write_text(shuffled, encoding='utf-8')
        r = run('--slug', 'zz-order', '--from', 'individual', '--from-path', str(indiv),
                '--to', 'universal', '--to-path', str(clone), '--approved-by', 'Owner')
        drafted = text(clone / 'practices' / 'zz-order.md')
        cases.append(('a universal draft from a file whose fields are out of the spec\'s '
                      'order lands in order, and the tool asks for the applies_to_why '
                      'an on-demand practice there must carry',
                      r.returncode == 0 and frontmatter_yaml.field_order_problem(shuffled)
                      and drafted and not frontmatter_yaml.field_order_problem(drafted)
                      and 'ADD an applies_to_why' in r.stdout,
                      (r.stdout + r.stderr)[-500:]))

        # -- a universal draft whose check IS registered there gets its
        #    checked_by repointed from the set's script to the engine
        #    (2026-10-05: five drafts from repo-maintenance each carried
        #    a tools/checks/ path universal does not have) --
        (indiv / 'practices' / 'default-branch.md').write_text(
            P('default-branch').replace(
                'checked_by:  null', 'checked_by:  "tools/checks/check_default_branch.py"'),
            encoding='utf-8')
        r = run('--slug', 'default-branch', '--from', 'individual', '--from-path', str(indiv),
                '--to', 'universal', '--to-path', str(clone), '--approved-by', 'Owner')
        cases.append(('a universal draft whose check universal registers names '
                      'tools/precedent_check.py, not the set\'s script, and says so',
                      r.returncode == 0 and 'REPOINTED checked_by' in r.stdout
                      and 'checked_by:  "tools/precedent_check.py"'
                      in text(clone / 'practices' / 'default-branch.md'),
                      (r.stdout + r.stderr)[-500:]))

        # -- a universal draft whose check universal does not register: a
        #    refusal, not a traceback (2026-10-05, moving assorted-notes) --
        (indiv / 'practices' / 'zz-checked.md').write_text(
            P('zz-checked').replace(
                'checked_by:  null', 'checked_by:  "tools/checks/check_zz_checked.py"'),
            encoding='utf-8')
        r = run('--slug', 'zz-checked', '--from', 'individual', '--from-path', str(indiv),
                '--to', 'universal', '--to-path', str(clone), '--approved-by', 'Owner')
        cases.append(('a universal draft whose checked_by universal does not register is '
                      'refused by name, with no traceback, and writes nothing',
                      r.returncode == 1 and 'precedent_move FAIL' in r.stderr
                      and 'Traceback' not in r.stderr
                      and not (clone / 'practices' / 'zz-checked.md').exists(),
                      r.stderr[-500:]))
    finally:
        shutil.rmtree(tmp, ignore_errors=True)

    failed = [c for c in cases if not c[1]]
    check(f'tools/precedent_move.py runs the remaining directions and asks a team\'s own '
          f'approver before removing its practice ({len(cases)} stated cases)', not failed,
          '; '.join(f'{n}: {d}' for n, _ok, d in failed))


def check_move_withdrawal_from_universal_leaves_universal_green():
    """Withdrawing a universal practice (`--dedupe-only --accept-reach-loss`)
    leaves nothing behind that turns the universal clone's own checks red,
    and a consumer that no longer gets the rule is told where it went.

    WHY. Rehearsed 2026-09-28: the withdrawal left a `routing_audit_state.json`
    rotation entry for the slug (routing-audit: stale bookkeeping) and a
    `# practice: <slug>` citation under tools/ (code-cites-practice: cites a
    practice that is not active). And every consumer's sync then said IN FORCE
    NOWHERE "-- this is the deduplication that silently loses a rule" about
    two practices withdrawn on purpose, with the set named in their Story."""
    import shutil, tempfile
    tmp = pathlib.Path(tempfile.mkdtemp(prefix='precedent-move-withdraw-'))
    env = _move_fixture_env(tmp)
    cases = []

    def run(*args):
        return subprocess.run([sys.executable, str(ROOT / 'tools' / 'precedent_move.py'),
                               *args], cwd=str(ROOT), capture_output=True, text=True,
                              env=env)

    try:
        team = tmp / 'precedent-team-fixture'
        subprocess.run([sys.executable, str(ROOT / 'tools' / 'precedent_bootstrap_source.py'),
                        '--level', 'team', '--name', 'precedent-team-fixture', '--dest', str(team),
                        '--approver', 'Fixture Approver:fixture-gh'],
                       capture_output=True, text=True, env=env)
        uclone = tmp / 'precedent'
        (uclone / 'practices').mkdir(parents=True)
        (uclone / 'tools').mkdir()
        (uclone / 'practices' / 'zz-gone.md').write_text(
            _move_fixture_practice('zz-gone', install='Nothing.'), encoding='utf-8')
        (uclone / 'practices' / 'zz-stays.md').write_text(
            _move_fixture_practice('zz-stays'), encoding='utf-8')
        state = uclone / 'tools' / 'routing_audit_state.json'
        state.write_text(json.dumps({'zz-gone': {'commit': 'x', 'last_reviewed': '2026-09-01'},
                                     'zz-stays': {'commit': 'x', 'last_reviewed': '2026-09-01'}},
                                    indent=2, sort_keys=True) + '\n', encoding='utf-8')
        code = uclone / 'tools' / 'thing.py'
        code.write_text('x = 1  # practice: zz-gone\n', encoding='utf-8')

        r = run('--slug', 'zz-gone', '--from', 'universal', '--from-path', str(uclone),
                '--to', 'team', '--to-path', str(team), '--approved-by', 'Fixture Approver')
        cases.append(('the universal practice lands in the team, duplicated', r.returncode == 0,
                      (r.stdout + r.stderr)[-400:]))
        before = (uclone / 'practices' / 'zz-gone.md').read_text(encoding='utf-8')
        r = run('--slug', 'zz-gone', '--from', 'universal', '--from-path', str(uclone),
                '--to', 'team', '--to-path', str(team), '--dedupe-only', '--accept-reach-loss')
        cases.append(('the withdrawal is refused while the clone\'s tools/ still cite the '
                      'practice, naming the file and line, and writes nothing',
                      r.returncode == 1 and 'tools/thing.py:1' in r.stderr
                      and (uclone / 'practices' / 'zz-gone.md').read_text(encoding='utf-8') == before
                      and 'zz-gone' in json.loads(state.read_text(encoding='utf-8')),
                      r.stderr[-400:]))
        code.write_text('x = 1  # counts one thing\n', encoding='utf-8')
        r = run('--slug', 'zz-gone', '--from', 'universal', '--from-path', str(uclone),
                '--to', 'team', '--to-path', str(team), '--dedupe-only', '--accept-reach-loss')
        st = json.loads(state.read_text(encoding='utf-8'))
        cases.append(('with the citation reworded, the withdrawal runs and drops the '
                      'practice\'s routing-audit entry, and only that one',
                      r.returncode == 0 and 'zz-gone' not in st and 'zz-stays' in st
                      and 'routing_audit_state.json' in r.stdout, (r.stdout + r.stderr)[-500:]))

        # A consumer declaring only this universal source: the stub resolves
        # nowhere, and the warning says it was withdrawn and to which set.
        consumer = tmp / 'consumer'
        consumer.mkdir()
        (consumer / 'precedent.json').write_text(json.dumps({
            'format_version': 1, 'visibility': 'private',
            'sources': [{'level': 'universal', 'name': 'precedent', 'path': str(uclone)}]}),
            encoding='utf-8')
        r = subprocess.run([sys.executable, str(ROOT / 'tools' / 'precedent_resolve.py'),
                            '--repo', str(consumer), '--json'],
                           capture_output=True, text=True, env=env)
        try:
            dangling = json.loads(r.stdout).get('dangling') or []
        except json.JSONDecodeError:
            dangling = []
        d = next((x for x in dangling if x.get('slug') == 'zz-gone'), {})
        cases.append(('a consumer that no longer gets the rule is told it was withdrawn from '
                      'universal, when, and which set to declare to keep it -- not that a '
                      'deduplication silently lost it',
                      d.get('withdrawn_to') == 'precedent-team-fixture'
                      and 'withdrawn from universal on' in d.get('why', '')
                      and 'declare that set to keep it' in d.get('why', '')
                      and 'silently loses' not in d.get('why', ''),
                      (r.stdout + r.stderr)[-600:]))
    finally:
        shutil.rmtree(tmp, ignore_errors=True)

    failed = [c for c in cases if not c[1]]
    check(f'withdrawing a universal practice leaves the universal clone\'s own checks '
          f'green and tells a consumer where the rule went ({len(cases)} stated cases)',
          not failed, '; '.join(f'{n}: {d}' for n, _ok, d in failed))



def check_ladder_opt_in_loader():
    """spec/LADDER_OPT_IN_PLAN.md steps 2-4, tested in a fixture world (never a
    real profile: a real one would carry private set text into the harness).

    A person's individual set BRINGS a shared set that provides the ladder.
    Cases, each naming the behaviour it guards:
      1. the brought set loads, at the shared level, beside the individual set;
      2. a person who brings nothing does not get it -- the same repository,
         another person;
      3. a malformed `brings` entry is skipped with one line, never fatal;
      4. build_views never writes a brought set into a committed view, in a
         private repository, a public one, or a practice set;
      5. precedent_ladder: in force for the person who brings it, not for one
         who does not, not under PRECEDENT_NO_LADDERS, and the --in-force
         exit code agrees;
      6. PRECEDENT_NO_LADDERS drops the set from load_config, and a brought
         set that provides nothing is NOT dropped by it;
      7. session start clones a brought set from its repo_url, beside the
         individual set, and pulls it on the next run;
      8. --withdraw-from-universal deletes the universal copy, records the
         withdrawal once, and a consumer of universal alone sees no IN FORCE
         NOWHERE for it; refused without --approved-by."""
    import contextlib, io, shutil, tempfile
    import precedent_resolve as pr
    import precedent_ladder as pl
    import precedent_source_bootstrap as psb
    import build_views as bv

    def git(cwd, *a):
        env = dict(os.environ, PRECEDENT_ALLOW_ANY_AUTHOR='1')
        return subprocess.run(['git', '-C', str(cwd), *a], capture_output=True,
                              text=True, env=env)

    def commit_all(repo, msg='x'):
        git(repo, 'add', '-A')
        git(repo, '-c', 'user.email=f@x', '-c', 'user.name=f', 'commit', '-qm', msg)

    def make_set(path, name, provides=None, level='shared'):
        (path / 'practices').mkdir(parents=True, exist_ok=True)
        man = {'name': name, 'level': level, 'visibility': 'public',
               'subject': 'a fixture', 'code': []}
        if provides is not None:
            man['provides'] = provides
        (path / 'precedent-source.json').write_text(json.dumps(man),
                                                    encoding='utf-8')
        (path / 'practices' / f'{name}-rule.md').write_text(
            _move_fixture_practice(f'{name}-rule'), encoding='utf-8')
        return path

    saved = {k: os.environ.get(k) for k in (
        'PRECEDENT_ASSUME_LADDER', 'PRECEDENT_USER_CONFIG', pr.NO_LADDERS_ENV, 'CLAUDE_PROJECT_DIR',
        'PRECEDENT_PROJECT_DIR', pr.SELF_HEAL_RENDER_ENV)}
    for k in saved:                       # practice: fixture-owns-its-state
        os.environ.pop(k, None)
    tmp = pathlib.Path(tempfile.mkdtemp(prefix='ladder-opt-in-'))
    cases = []
    try:
        home = tmp / 'home'
        # The ladder set's origin, a real repository so session start can
        # clone it from a URL.
        origin = make_set(tmp / 'origin-ladder', 'fixture-ladder', ['ladder'])
        git(origin, 'init', '-q', '-b', 'main')
        commit_all(origin)
        url = f'file://{origin}'
        ind = home / 'precedent-individual'
        (ind / 'practices').mkdir(parents=True)
        git(ind, 'init', '-q', '-b', 'main')
        (ind / 'precedent-source.json').write_text(json.dumps({
            'name': 'precedent-individual', 'level': 'individual',
            'brings': [{'name': 'fixture-ladder', 'repo_url': url},
                       {'name': 'Not A Slug', 'repo_url': url},
                       'not-a-dict',
                       # git would read this as an option, not a repository
                       {'name': 'evil', 'repo_url': '--upload-pack=touch /tmp/x'},
                       # the set itself, which would load it twice
                       {'name': 'precedent-individual', 'repo_url': url}]}),
            encoding='utf-8')
        brings_cfg = tmp / 'brings.json'
        brings_cfg.write_text(json.dumps({'individual': {
            'name': 'precedent-individual', 'path': str(ind)}}), encoding='utf-8')
        plain_ind = tmp / 'other' / 'precedent-individual'
        (plain_ind / 'practices').mkdir(parents=True)
        git(plain_ind, 'init', '-q')
        plain_cfg = tmp / 'plain.json'
        plain_cfg.write_text(json.dumps({'individual': {
            'name': 'precedent-individual', 'path': str(plain_ind)}}),
            encoding='utf-8')
        repo = tmp / 'work' / 'consumer'
        repo.mkdir(parents=True)
        (repo / 'precedent.json').write_text(json.dumps({
            'format_version': 1, 'visibility': 'private', 'sources': []}),
            encoding='utf-8')

        # 7 first: session start puts the brought set on disk.
        os.environ['PRECEDENT_USER_CONFIG'] = str(brings_cfg)
        err = io.StringIO()
        with contextlib.redirect_stderr(err):
            res = psb.sources_from_brings()
        clone = home / 'fixture-ladder'
        cases.append(('session start clones a brought set from its repo_url, '
                      'beside the individual set',
                      any(n == 'fixture-ladder' and ok for n, ok, _m in res)
                      and (clone / 'practices').is_dir(), repr(res)))
        (origin / 'practices' / 'later.md').write_text(
            _move_fixture_practice('later'), encoding='utf-8')
        commit_all(origin, 'later')
        with contextlib.redirect_stderr(io.StringIO()):
            psb.sources_from_brings()
        cases.append(('and pulls it on the next run',
                      (clone / 'practices' / 'later.md').is_file(), ''))

        # 1 and 3
        err = io.StringIO()
        with contextlib.redirect_stderr(err):
            srcs = pr.load_config(repo)
        got = [s for s in srcs if s['name'] == 'fixture-ladder']
        cases.append(('the brought set loads at the shared level, beside the '
                      'individual set, marked as brought',
                      len(got) == 1 and got[0]['level'] == 'shared'
                      and got[0].get('brought') is True
                      and pathlib.Path(got[0]['path']).resolve() == clone.resolve(),
                      repr(srcs)))
        cases.append(('each malformed brings entry -- a bad name, not a dict, a URL '
                      'git would read as an option, the set itself -- is skipped '
                      'with one line',
                      err.getvalue().count('`brings` entry') == 4
                      and not [s for s in srcs if s['name'] in
                               ('Not A Slug', 'evil')]
                      and len([s for s in srcs
                               if s['name'] == 'precedent-individual']) == 1,
                      err.getvalue()))
        dsp = [n for _p, _l, n, _note in pr.declared_source_paths(repo)]
        cases.append(('declared_source_paths names it, so the freshness guard '
                      'and the refresh check it', 'fixture-ladder' in dsp, repr(dsp)))

        # 4
        for vis in ('private', 'public'):
            (repo / 'precedent.json').write_text(json.dumps({
                'format_version': 1, 'visibility': vis, 'sources': []}),
                encoding='utf-8')
            with contextlib.redirect_stderr(io.StringIO()):
                srcs = pr.load_config(repo)
            tracked, deferred, _n = bv.sources_for_tracked_block(repo, srcs)
            cases.append((f'a {vis} repository\'s committed view never carries '
                          f'the brought set',
                          not [s for s in tracked if s.get('brought')]
                          and [s for s in deferred if s.get('brought')],
                          repr(tracked)))
        with contextlib.redirect_stderr(io.StringIO()):
            srcs = pr.load_config(ind)
        tracked, deferred, _n = bv.sources_for_tracked_block(ind, srcs)
        cases.append(('nor does a practice set\'s',
                      not [s for s in tracked if s.get('brought')], repr(tracked)))

        # 5
        cases.append(('the ladder is in force for the person who brings it',
                      pl.ladder_in_force(repo), pl.status_sentence(repo)))
        cli = subprocess.run([sys.executable, str(ROOT / 'tools' / 'precedent_ladder.py'),
                              '--in-force', '--repo', str(repo)],
                             capture_output=True, text=True,
                             env=dict(os.environ))
        cases.append(('--in-force exits 0 for them', cli.returncode == 0,
                      cli.stdout + cli.stderr))
        os.environ['PRECEDENT_USER_CONFIG'] = str(plain_cfg)
        cases.append(('and not for a person who brings nothing, in the same '
                      'repository', not pl.ladder_in_force(repo),
                      pl.status_sentence(repo)))
        cli = subprocess.run([sys.executable, str(ROOT / 'tools' / 'precedent_ladder.py'),
                              '--in-force', '--repo', str(repo)],
                             capture_output=True, text=True, env=dict(os.environ))
        cases.append(('--in-force exits 1 for them', cli.returncode == 1,
                      cli.stdout + cli.stderr))
        with contextlib.redirect_stderr(io.StringIO()):
            srcs = pr.load_config(repo)
        cases.append(('and load_config gives them no such set',
                      not [s for s in srcs if s['name'] == 'fixture-ladder'],
                      repr(srcs)))

        # 6
        os.environ['PRECEDENT_USER_CONFIG'] = str(brings_cfg)
        os.environ[pr.NO_LADDERS_ENV] = '1'
        with contextlib.redirect_stderr(io.StringIO()):
            srcs = pr.load_config(repo)
        cases.append(('PRECEDENT_NO_LADDERS drops the ladder set from the session',
                      not [s for s in srcs if s['name'] == 'fixture-ladder']
                      and not pl.ladder_in_force(repo)
                      and 'switched off' in pl.status_sentence(repo), repr(srcs)))
        man = json.loads((clone / 'precedent-source.json').read_text(encoding='utf-8'))
        man.pop('provides')
        (clone / 'precedent-source.json').write_text(json.dumps(man), encoding='utf-8')
        with contextlib.redirect_stderr(io.StringIO()):
            srcs = pr.load_config(repo)
        cases.append(('but keeps a brought set that provides nothing',
                      [s for s in srcs if s['name'] == 'fixture-ladder'], repr(srcs)))
        os.environ.pop(pr.NO_LADDERS_ENV, None)

        # 8
        env = _move_fixture_env(tmp)
        team = tmp / 'precedent-team-fixture'
        subprocess.run([sys.executable, str(ROOT / 'tools' / 'precedent_bootstrap_source.py'),
                        '--level', 'team', '--name', 'precedent-team-fixture', '--dest', str(team),
                        '--approver', 'Fixture Approver:fixture-gh'],
                       capture_output=True, text=True, env=env)
        uclone = tmp / 'precedent'
        (uclone / 'practices').mkdir(parents=True)
        (uclone / 'tools').mkdir()
        (uclone / 'practices' / 'zz-gone.md').write_text(
            _move_fixture_practice('zz-gone', install='Nothing.'), encoding='utf-8')
        (uclone / 'practices' / 'zz-stays.md').write_text(
            _move_fixture_practice('zz-stays'), encoding='utf-8')

        def move(*args):
            return subprocess.run([sys.executable, str(ROOT / 'tools' / 'precedent_move.py'),
                                   *args], cwd=str(ROOT), capture_output=True,
                                  text=True, env=env)
        move('--slug', 'zz-gone', '--from', 'universal', '--from-path', str(uclone),
             '--to', 'team', '--to-path', str(team), '--approved-by', 'Fixture Approver')
        r = move('--slug', 'zz-gone', '--from', 'universal', '--from-path', str(uclone),
                 '--to', 'team', '--to-path', str(team), '--withdraw-from-universal')
        cases.append(('--withdraw-from-universal is refused without --approved-by, '
                      'and writes nothing',
                      r.returncode == 1 and '--approved-by' in r.stderr
                      and (uclone / 'practices' / 'zz-gone.md').is_file(), r.stderr[-300:]))
        r = move('--slug', 'zz-gone', '--from', 'universal', '--from-path', str(uclone),
                 '--to', 'team', '--to-path', str(team), '--withdraw-from-universal',
                 '--approved-by', 'Fixture Approver')
        record = uclone / 'record' / 'WITHDRAWN_FROM_UNIVERSAL.md'
        cases.append(('it deletes the universal copy and records the withdrawal once',
                      r.returncode == 0
                      and not (uclone / 'practices' / 'zz-gone.md').exists()
                      and record.is_file()
                      and record.read_text(encoding='utf-8').count('`zz-gone` withdrawn') == 1,
                      (r.stdout + r.stderr)[-500:]))
        # The set's copy no longer says a universal copy stays active, and
        # still carries the approval the rule had in universal (2026-10-02:
        # fourteen ladder rules lost theirs).
        kept = sp._read_practice_file(team / 'practices' / 'zz-gone.md')[0]
        ab = str(kept.get('approved_by') or '')
        cases.append(("the set's copy says universal keeps no copy, and keeps "
                      "the rule's own approval",
                      'keeps no copy' in ab and 'stays active' not in ab
                      and '(there: Fixture, 2026-09-14)' in ab, ab[:300]))
        consumer = tmp / 'consumer-u'
        consumer.mkdir()
        (consumer / 'precedent.json').write_text(json.dumps({
            'format_version': 1, 'visibility': 'private',
            'sources': [{'level': 'universal', 'name': 'precedent', 'path': str(uclone)}]}),
            encoding='utf-8')
        r = subprocess.run([sys.executable, str(ROOT / 'tools' / 'precedent_resolve.py'),
                            '--repo', str(consumer), '--json'],
                           capture_output=True, text=True, env=env)
        try:
            dangling = json.loads(r.stdout).get('dangling') or []
        except json.JSONDecodeError:
            dangling = None
        cases.append(('a consumer of universal alone sees no IN FORCE NOWHERE for it',
                      dangling == [], (r.stdout + r.stderr)[-400:]))
        # 8b. A retired name leaves with the rule it forwards to, and the
        # tool writes its record line, in the shape the record's reader
        # knows. 2026-10-02: four such names were withdrawn by hand, because
        # the tool refused them, in a shape the reader did not know; the
        # first consumer to update past them was refused (2026-10-04).
        stub_fm = lambda: (_move_fixture_practice('zz-old-name')
                           .replace('status:      active\nin_force_at: null',
                                    'status:      deduplicated\nin_force_at: zz-gone'))
        (uclone / 'practices' / 'zz-old-name.md').write_text(stub_fm(), encoding='utf-8')
        (team / 'practices' / 'zz-old-name.md').write_text(
            _move_fixture_practice('zz-old-name'), encoding='utf-8')
        r = move('--slug', 'zz-old-name', '--from', 'universal', '--from-path', str(uclone),
                 '--to', 'team', '--to-path', str(team), '--withdraw-from-universal',
                 '--approved-by', 'Fixture Approver')
        cases.append(("CONTROL: a retired name whose set copy is ACTIVE is refused, "
                      "by that reason, and nothing is deleted",
                      r.returncode == 1 and 'not the same retired name kept as history' in r.stderr
                      and (uclone / 'practices' / 'zz-old-name.md').is_file(),
                      (r.stdout + r.stderr)[-400:]))
        (team / 'practices' / 'zz-old-name.md').write_text(
            stub_fm(), encoding='utf-8')
        r = move('--slug', 'zz-old-name', '--from', 'universal', '--from-path', str(uclone),
                 '--to', 'team', '--to-path', str(team), '--withdraw-from-universal',
                 '--approved-by', 'Fixture Approver')
        hist = pr.withdrawn_history(uclone)
        rec = pr.withdrawn_record(uclone)
        cases.append(('a retired name is withdrawn by the tool, and its record line '
                      'reads back as history beside the rule it forwards to',
                      r.returncode == 0
                      and not (uclone / 'practices' / 'zz-old-name.md').exists()
                      and 'zz-old-name' in hist and 'zz-gone' not in hist
                      and set(rec) >= {'zz-gone', 'zz-old-name'},
                      (r.stdout + r.stderr)[-500:] + repr(rec)))
        text = record.read_text(encoding='utf-8')
        cases.append(('every line the tool wrote to the record reads back',
                      len(pr.withdrawn_record_entries(text))
                      == sum(1 for l in text.splitlines() if l.startswith('- ')),
                      text[-600:]))
    finally:
        for k, v in saved.items():
            if v is None:
                os.environ.pop(k, None)
            else:
                os.environ[k] = v
        shutil.rmtree(tmp, ignore_errors=True)

    bad = [(c[0], c[2]) for c in cases if not c[1]]
    check(f'a set a person brings loads for that person only, never reaches a '
          f'committed view, answers precedent_ladder, and a universal rule can be '
          f'withdrawn to it cleanly ({len(cases)} stated cases)',
          not bad, '; '.join(f"{n} -- {str(d)[:400]}" for n, d in bad))


def check_withdrawal_record_lines_all_read_back():
    """Every line of this repository's record/WITHDRAWN_FROM_UNIVERSAL.md is
    one precedent_resolve.withdrawn_record reads. The record ships to every
    consumer, whose sync reads it to tell a withdrawal from a loss; a line it
    cannot read is a rule that sync refuses as lost. 2026-10-04: four lines
    written by hand in a second shape were unreadable, and the first
    consumer to update past them was refused on two of them."""
    import precedent_resolve as pr
    path = ROOT / pr.WITHDRAWN_RECORD
    if not path.is_file():
        return True, 'no withdrawal record in this repository', ''
    text = path.read_text(encoding='utf-8')
    lines = [l for l in text.splitlines() if l.startswith('- ')]
    read = {e[1] for e in pr.withdrawn_record_entries(text)}
    unread = [l[:120] for l in lines
              if not any(f'`{slug}`' in l.split(' withdrawn from ')[0] for slug in read)]
    return (not unread and len(pr.withdrawn_record_entries(text)) == len(lines),
            f'{len(lines)} line(s), every one read back',
            'unreadable line(s): ' + ' | '.join(unread))


def check_sync_check_passes_from_another_checkout():
    """A view sync, committed, then `precedent_sync_views.py --check` from a
    worktree of the same commit, passes: nothing is stale. 2026-10-04: a
    consumer's Promote, which checks its composition in a throwaway
    worktree, failed every time on "MANIFEST.json differs from what a fresh
    sync writes" -- the manifest recorded each source's resolved absolute
    path, so the worktree's own path differed for the two sources inside
    the repository. Another machine differs the same way.

    CONTROL 1: a source outside the repository is compared by level and
    name, so a manifest recording it somewhere else still passes; changing
    its NAME still fails. CONTROL 2: a source inside the repository recorded
    at a different relative path still fails."""
    import shutil, tempfile
    import build_views as bv
    tmp = pathlib.Path(tempfile.mkdtemp(prefix='precedent-sync-worktree-'))
    env = {**os.environ, 'HOME': str(tmp / 'home'),
           'PRECEDENT_USER_CONFIG': str(tmp / 'no-user-config.json'),
           'GIT_AUTHOR_NAME': 't', 'GIT_AUTHOR_EMAIL': 't@t',
           'GIT_COMMITTER_NAME': 't', 'GIT_COMMITTER_EMAIL': 't@t',
           'PRECEDENT_ALLOW_ANY_AUTHOR': '1'}
    cases = []
    try:
        (tmp / 'home').mkdir()
        repo = tmp / 'consumer'
        subprocess.run(['git', 'init', '-q', '-b', 'main', str(repo)], env=env,
                       capture_output=True)
        (repo / 'local' / 'practices').mkdir(parents=True)
        (repo / 'local' / 'practices' / 'zz-local.md').write_text(
            _move_fixture_practice('zz-local'), encoding='utf-8')
        (repo / 'precedent.json').write_text(json.dumps({
            'format_version': 1, 'visibility': 'private', 'base_branch': 'main',
            'sources': [{'level': 'universal', 'name': 'precedent', 'path': str(ROOT)},
                        {'level': 'repo-local', 'name': 'local', 'path': 'local'}]})
            + '\n', encoding='utf-8')
        (repo / 'AGENTS.md').write_text(
            f'# fixture\n\n{bv.BEGIN_MARKER}\n{bv.END_MARKER}\n', encoding='utf-8')

        def sync(where, *extra):
            r = subprocess.run([sys.executable, str(ROOT / 'tools' / 'precedent_sync_views.py'),
                                '--repo', str(where), *extra], cwd=str(where), env=env,
                               capture_output=True, text=True, timeout=600)
            return r.returncode, r.stdout + r.stderr

        rc, out = sync(repo)
        mf = repo / 'MANIFEST.json'
        recorded = json.loads(mf.read_text(encoding='utf-8')).get('sources') if mf.is_file() else None
        cases.append(('the sync records the source inside the repository as it is '
                      'declared, relative', rc == 0 and recorded is not None
                      and {'level': 'repo-local', 'name': 'local', 'path': 'local'} in recorded,
                      f'rc={rc} {recorded!r} {out[-400:]}'))
        subprocess.run(['git', '-C', str(repo), 'add', '-A'], env=env, capture_output=True)
        made = subprocess.run(['git', '-C', str(repo), 'commit', '-qm', 'synced'], env=env,
                              capture_output=True, text=True)
        wt = tmp / 'elsewhere' / 'composed'
        added = subprocess.run(['git', '-C', str(repo), 'worktree', 'add', '-q', str(wt),
                                'HEAD'], env=env, capture_output=True, text=True)
        cases.append(('fixture: the sync is committed and checked out in a worktree '
                      'elsewhere', made.returncode == 0 and added.returncode == 0
                      and (wt / 'MANIFEST.json').is_file(),
                      (made.stderr + added.stderr)[-400:]))
        rc, out = sync(wt, '--check')
        cases.append(('--check from a worktree of the same commit passes',
                      rc == 0, out[-600:]))

        def with_sources(edit):
            data = json.loads((wt / 'MANIFEST.json').read_text(encoding='utf-8'))
            data['sources'] = [edit(dict(e)) for e in data['sources']]
            (wt / 'MANIFEST.json').write_text(json.dumps(data, indent=2) + '\n',
                                              encoding='utf-8')
        original = (wt / 'MANIFEST.json').read_text(encoding='utf-8')
        with_sources(lambda e: {**e, 'path': '/another/machine/BestPractice'}
                     if e['level'] == 'universal' else e)
        rc, out = sync(wt, '--check')
        cases.append(('CONTROL 1: a source outside the repository recorded at '
                      'another path still passes', rc == 0, out[-400:]))
        (wt / 'MANIFEST.json').write_text(original, encoding='utf-8')
        with_sources(lambda e: {**e, 'name': 'renamed'} if e['level'] == 'universal' else e)
        rc, out = sync(wt, '--check')
        cases.append(('CONTROL 1: ...and the same source under another name fails',
                      rc != 0 and 'MANIFEST.json differs' in out, out[-400:]))
        (wt / 'MANIFEST.json').write_text(original, encoding='utf-8')
        with_sources(lambda e: {**e, 'path': 'elsewhere'} if e['name'] == 'local' else e)
        rc, out = sync(wt, '--check')
        cases.append(('CONTROL 2: a source inside the repository recorded at '
                      'another relative path fails',
                      rc != 0 and 'MANIFEST.json differs' in out, out[-400:]))
    finally:
        shutil.rmtree(tmp, ignore_errors=True)
    bad = [(c[0], c[2]) for c in cases if not c[1]]
    return (not bad, f'{len(cases)} stated cases',
            '; '.join(f'{n} -- {str(d)[:500]}' for n, d in bad))


def _pin_fixture_practice(slug, rule):
    return (_move_fixture_practice(slug)
            .replace('Do the thing.', rule))


def check_views_check_reads_a_set_at_the_commit_it_was_synced_at():
    """A consumer's views check reads each shared set at the commit its
    MANIFEST.json records syncing it at, never at whatever branch the set's
    clone has checked out (2026-10-05). Reported from a consumer: its
    pre-staging took a set's Booked change, session start left the set's
    clone on main, and every push was refused for "drift" in files it never
    touched -- with a remedy, a plain sync, that rolled the Booked change
    back. Twice in one session.

    Each direction: a pre-staging carrying a Booked-not-Produced set change
    passes; a write from a clone that lacks it is refused rather than
    rolling it back; a push to staging or main carrying a set commit the set
    has not landed on that rung is refused, with promoting the set as the
    remedy, and passes once it has; a hand-edited generated file still
    fails; a manifest written before pins gets one inferred; uncommitted
    edits in a set's clone are never taken into a consumer."""
    import shutil, tempfile
    import build_views as bv
    tmp = pathlib.Path(tempfile.mkdtemp(prefix='precedent-views-pin-'))
    env = {**os.environ, 'HOME': str(tmp / 'home'),
           'PRECEDENT_USER_CONFIG': str(tmp / 'no-user-config.json'),
           'GIT_AUTHOR_NAME': 't', 'GIT_AUTHOR_EMAIL': 't@t',
           'GIT_COMMITTER_NAME': 't', 'GIT_COMMITTER_EMAIL': 't@t',
           'PRECEDENT_ALLOW_ANY_AUTHOR': '1'}
    cases = []

    def git(where, *args):
        return subprocess.run(['git', '-C', str(where), *args], env=env,
                              capture_output=True, text=True)

    try:
        (tmp / 'home').mkdir()
        # The universal source is a plain directory: nothing to pin.
        uni = tmp / 'u'
        (uni / 'practices').mkdir(parents=True)
        (uni / 'practices' / 'uni-rule.md').write_text(
            _pin_fixture_practice('uni-rule', 'A universal rule.'), encoding='utf-8')
        # The shared set: a clone of a bare origin, with all three rungs.
        bare, st = tmp / 'origin-set.git', tmp / 'precedent-shared-fixture'
        subprocess.run(['git', 'init', '-q', '--bare', '-b', 'main', str(bare)],
                       env=env, capture_output=True)
        subprocess.run(['git', 'clone', '-q', str(bare), str(st)], env=env,
                       capture_output=True)
        rule = st / 'practices' / 'set-rule.md'
        rule.parent.mkdir(parents=True)

        def set_commit(text, msg):
            rule.write_text(_pin_fixture_practice('set-rule', text), encoding='utf-8')
            git(st, 'add', '-A')
            git(st, 'commit', '-qm', msg)
            return git(st, 'rev-parse', 'HEAD').stdout.strip()

        git(st, 'checkout', '-q', '-b', 'main')
        set_commit('Version one.', 'v1')
        for b in ('pre-staging', 'staging'):
            git(st, 'branch', b)
        git(st, 'push', '-q', 'origin', 'main', 'pre-staging', 'staging')
        # Version two is Booked: a working branch merged into pre-staging.
        git(st, 'checkout', '-q', '-b', 'feature', 'main')
        set_commit('Version two.', 'v2')
        git(st, 'checkout', '-q', 'pre-staging')
        git(st, 'merge', '-q', '--no-ff', '-m', 'Book v2', 'feature')
        git(st, 'push', '-q', 'origin', 'pre-staging')
        booked = git(st, 'rev-parse', 'HEAD').stdout.strip()

        repo = tmp / 'consumer'
        subprocess.run(['git', 'init', '-q', '-b', 'pre-staging', str(repo)],
                       env=env, capture_output=True)
        (repo / 'precedent.json').write_text(json.dumps({
            'format_version': 1, 'visibility': 'private', 'base_branch': 'main',
            'sources': [{'level': 'universal', 'name': 'precedent', 'path': str(uni)},
                        {'level': 'shared', 'name': 'precedent-shared-fixture',
                         'path': str(st)}]}) + '\n', encoding='utf-8')
        (repo / 'AGENTS.md').write_text(
            f'# fixture\n\n{bv.BEGIN_MARKER}\n{bv.END_MARKER}\n', encoding='utf-8')

        def sync(*extra):
            r = subprocess.run([sys.executable, str(ROOT / 'tools' / 'precedent_sync_views.py'),
                                '--repo', str(repo), *extra], cwd=str(repo), env=env,
                               capture_output=True, text=True, timeout=600)
            return r.returncode, r.stdout + r.stderr

        def pinned():
            data = json.loads((repo / 'MANIFEST.json').read_text(encoding='utf-8'))
            return {e['name']: e.get('commit') for e in data['sources']}

        def taken():
            return (repo / 'practices' / 'set-rule.md').read_text(encoding='utf-8')

        # The consumer's pre-staging takes the Booked change.
        rc, out = sync()
        pins = pinned() if rc == 0 else {}
        cases.append(('a sync records the commit it read the set at, and none for a '
                      'plain-directory source',
                      rc == 0 and pins.get('precedent-shared-fixture') == booked
                      and pins.get('precedent') is None and 'Version two.' in taken(),
                      f'rc={rc} {pins} {out[-500:]}'))
        git(repo, 'add', '-A')
        git(repo, 'commit', '-qm', 'take the Booked v2')

        # Session start leaves the set's clone on main.
        git(st, 'checkout', '-q', 'main')
        rc, out = sync('--check')
        cases.append(('the views check passes with the clone on main: it reads the '
                      'set at the recorded commit (the reported refusal)',
                      rc == 0, out[-600:]))
        rc, out = sync('--check', '--for-branch', 'pre-staging')
        cases.append(('...and a push to pre-staging passes: the set has v2 on its '
                      'own pre-staging', rc == 0, out[-600:]))
        rc, out = sync()
        cases.append(('a sync from the clone on main is REFUSED rather than rolling '
                      'the Booked change back, and writes nothing',
                      rc != 0 and 'roll those changes back' in out
                      and 'origin/pre-staging' in out and 'Version two.' in taken(),
                      f'rc={rc} {out[-600:]}'))
        git(st, 'checkout', '-q', '--detach', 'origin/pre-staging')
        rc, out = sync()
        cases.append(('CONTROL: from the clone at the set\'s pre-staging, the same '
                      'sync goes through and changes nothing',
                      rc == 0 and not git(repo, 'status', '--porcelain', '--',
                                          'practices').stdout.strip(),
                      f'rc={rc} {out[-400:]}'))
        git(repo, 'checkout', '-q', '--', '.')
        git(st, 'checkout', '-q', 'main')

        # The rung: staging and main may not carry what the set has not landed.
        rc, out = sync('--check', '--for-branch', 'staging')
        cases.append(('a push to staging carrying the set\'s pre-staging-only commit '
                      'is refused, with Debut as the remedy and never a sync',
                      rc != 0 and 'Debut it in precedent-shared-fixture' in out
                      and 'Do NOT sync' in out, f'rc={rc} {out[-600:]}'))
        rc, out = sync('--check', '--for-branch', 'main')
        cases.append(('...and so is a push to main, with Produce as the remedy',
                      rc != 0 and 'Produce it in precedent-shared-fixture' in out,
                      f'rc={rc} {out[-600:]}'))
        rc, out = sync('--rung-only', '--for-branch', 'main')
        cases.append(('the push check\'s own rung step (--rung-only) refuses the same '
                      'push without rendering anything',
                      rc != 0 and 'Produce it in precedent-shared-fixture' in out
                      and 'Do NOT sync' in out, f'rc={rc} {out[-400:]}'))
        git(st, 'checkout', '-q', 'staging')
        git(st, 'merge', '-q', '--no-ff', '-m', 'Debut', 'origin/pre-staging')
        git(st, 'push', '-q', 'origin', 'staging')
        git(st, 'checkout', '-q', 'main')
        git(st, 'merge', '-q', '--no-ff', '-m', 'Produce', 'origin/staging')
        git(st, 'push', '-q', 'origin', 'main')
        rc_s, out_s = sync('--check', '--for-branch', 'staging')
        rc_m, out_m = sync('--check', '--for-branch', 'main')
        cases.append(('once the set has Debuted and Produced it, both pushes pass',
                      rc_s == 0 and rc_m == 0, f'{out_s[-300:]} | {out_m[-300:]}'))
        rc, out = sync('--rung-only', '--for-branch', 'main')
        cases.append(('...and so does the rung step', rc == 0, out[-300:]))

        # A hand-edited generated file fails on every rung.
        good = taken()
        (repo / 'practices' / 'set-rule.md').write_text(
            good.replace('Version two.', 'Edited by hand.'), encoding='utf-8')
        failed = []
        for b in (None, 'pre-staging', 'staging', 'main'):
            rc, out = sync('--check', *(['--for-branch', b] if b else []))
            if rc == 0 or 'set-rule.md differs' not in out:
                failed.append(f'{b}: rc={rc} {out[-200:]}')
        cases.append(('a hand-edited materialized practice fails the check on every '
                      'rung', not failed, '; '.join(failed)))
        (repo / 'practices' / 'set-rule.md').write_text(good, encoding='utf-8')

        # A set moving on is said, never refused.
        git(st, 'checkout', '-q', 'pre-staging')
        git(st, 'merge', '-q', '--ff-only', 'origin/pre-staging')
        set_commit('Version three.', 'v3')
        git(st, 'push', '-q', 'origin', 'pre-staging')
        git(st, 'checkout', '-q', 'main')
        rc, out = sync('--check', '--for-branch', 'pre-staging')
        cases.append(('a newer set commit on pre-staging is a note, not a refusal',
                      rc == 0 and 'differs from what this repository took' in out,
                      f'rc={rc} {out[-500:]}'))

        # A manifest written before pins: the pin is inferred from history.
        mf = repo / 'MANIFEST.json'
        original = mf.read_text(encoding='utf-8')
        data = json.loads(original)
        for e in data['sources']:
            e.pop('commit', None)
        mf.write_text(json.dumps(data, indent=2) + '\n', encoding='utf-8')
        rc, out = sync('--check')
        cases.append(('a manifest with no pins passes with the clone on main: the '
                      'commit whose practices match is found and named',
                      rc == 0 and 'matched' in out, f'rc={rc} {out[-500:]}'))
        mf.write_text(original, encoding='utf-8')

        # Uncommitted edits in a set's clone never reach the consumer.
        git(st, 'checkout', '-q', '--detach', 'origin/pre-staging')
        rule.write_text(_pin_fixture_practice('set-rule', 'Uncommitted.'),
                        encoding='utf-8')
        rc, out = sync()
        cases.append(('a sync from a clone with uncommitted practice edits takes '
                      'its commit, not the edits, and says so',
                      rc == 0 and 'Uncommitted.' not in taken()
                      and 'were NOT taken' in out
                      and pinned().get('precedent-shared-fixture')
                      == git(st, 'rev-parse', 'HEAD').stdout.strip(),
                      f'rc={rc} {out[-500:]}'))
        rc, out = sync('--check')
        cases.append(('...and its own check passes straight after',
                      rc == 0, out[-400:]))
        cases.append(('no worktree is left behind in the set\'s clone',
                      len(git(st, 'worktree', 'list').stdout.splitlines()) == 1,
                      git(st, 'worktree', 'list').stdout))
    finally:
        shutil.rmtree(tmp, ignore_errors=True)
    bad = [(c[0], c[2] if len(c) > 2 else '') for c in cases if not c[1]]
    return (not bad, f'{len(cases)} stated cases',
            '; '.join(f'{n} -- {str(d)[:600]}' for n, d in bad))


def check_push_destination_reaches_the_views_check():
    """The push check knows the branch a push goes to, so a set's commits
    are held to that rung (2026-10-05): from --push-command, the highest
    rung it writes to; --destination, which Promote passes, wins. The rung
    test is its own uncached step, never part of a recorded step's argv."""
    import precedent_push_check as ppc
    cases = [
        ('a push to a working branch and main is judged as main',
         ppc._destination(ROOT, ['--push-command', 'origin feat main']) == 'main'),
        ('a push to pre-staging is pre-staging',
         ppc._destination(ROOT, ['--push-command', 'origin HEAD:pre-staging'])
         == 'pre-staging'),
        ('--destination wins',
         ppc._destination(ROOT, ['--destination', 'staging', '--push-command',
                                 'origin main']) == 'staging'),
        ('no destination named, none assumed',
         ppc._destination(ROOT, ['--gate']) is None),
    ]
    orig = ppc.repo_kind
    try:
        ppc.repo_kind = lambda _e: 'consumer'
        steps = dict((n, v) for n, v, _r in ppc.plan(ROOT, tier='full')[1])
    finally:
        ppc.repo_kind = orig
    cases.append(('the recorded steps carry no destination, so a pass for one '
                  'branch is still reused for the same tree going to another '
                  '(the first version broke Promote\'s reuse of a full pass)',
                  'views_sync' in steps
                  and all('--for-branch' not in v for v in steps.values())))
    cases.append(('the rung step stands aside outside a consumer, and with no '
                  'destination', ppc._rung_refusal(ROOT, 'upstream', 'main') is None
                  and ppc._rung_refusal(ROOT, 'consumer', None) is None))
    bad = [c[0] for c in cases if not c[1]]
    return (not bad, f'{len(cases)} stated cases', '; '.join(bad))


def check_session_check_names_commits_on_origin_off_main():
    """A set's clone checked out at the set's staging was reported "6
    unpushed commit(s) ahead" of main (2026-10-05): they were on origin,
    only not on main. Unpushed now means on no origin branch; commits on
    another origin branch are named by that branch, and are not stale."""
    import shutil, tempfile
    import precedent_session_check as psc
    tmp = pathlib.Path(tempfile.mkdtemp(prefix='precedent-clone-ahead-'))
    env = {**os.environ, 'GIT_AUTHOR_NAME': 't', 'GIT_AUTHOR_EMAIL': 't@t',
           'GIT_COMMITTER_NAME': 't', 'GIT_COMMITTER_EMAIL': 't@t'}

    def git(where, *args):
        return subprocess.run(['git', '-C', str(where), *args], env=env,
                              capture_output=True, text=True)
    cases = []
    try:
        bare, cl = tmp / 'o.git', tmp / 'clone'
        subprocess.run(['git', 'init', '-q', '--bare', '-b', 'main', str(bare)],
                       env=env, capture_output=True)
        subprocess.run(['git', 'clone', '-q', str(bare), str(cl)], env=env,
                       capture_output=True)
        git(cl, 'checkout', '-q', '-b', 'main')
        (cl / 'a').write_text('1\n')
        git(cl, 'add', '-A'), git(cl, 'commit', '-qm', 'one')
        git(cl, 'push', '-q', 'origin', 'main')
        git(cl, 'checkout', '-q', '-b', 'staging')
        (cl / 'a').write_text('2\n')
        git(cl, 'commit', '-qam', 'two')
        git(cl, 'push', '-q', 'origin', 'staging')
        git(cl, 'checkout', '-q', '--detach', 'origin/staging')
        old = os.environ.copy()
        os.environ.update(env)
        try:
            v, phrase = psc._clone_behind(str(cl), fetch=True, branch='main')
            cases.append(('a clone at the set\'s staging is not stale and nothing '
                          'is called unpushed', v == 'current'
                          and 'unpushed' not in phrase and 'on origin' in phrase
                          and 'origin/staging' in phrase, f'{v}: {phrase}'))
            (cl / 'a').write_text('3\n')
            git(cl, 'commit', '-qam', 'three')
            v, phrase = psc._clone_behind(str(cl), fetch=True, branch='main')
            cases.append(('CONTROL: a commit on no origin branch is unpushed',
                          v == 'behind' and '1 unpushed commit(s) ahead' in phrase,
                          f'{v}: {phrase}'))
        finally:
            os.environ.clear()
            os.environ.update(old)
    finally:
        shutil.rmtree(tmp, ignore_errors=True)
    bad = [(c[0], c[2]) for c in cases if not c[1]]
    return (not bad, f'{len(cases)} stated cases',
            '; '.join(f'{n} -- {d}' for n, d in bad))


def check_universal_change_names_the_set_copies_that_override_it():
    """A change below the frontmatter of a universal practice names each
    shared set carrying its own ACTIVE copy of the same slug (2026-10-05:
    the ladder set's the-boildown and vendor-update-runbook fell four
    changes behind universal's in three days). A deduplicated copy, a
    frontmatter-only edit, and a repository that is not the universal
    source are each passed over."""
    import shutil, tempfile
    import precedent_check as pc
    import precedent_resolve as _pr
    tmp = pathlib.Path(tempfile.mkdtemp(prefix='precedent-override-drift-'))
    cases = []
    fm = ('---\nslug: {s}\nstatus: {st}\n---\n## Rule\n{r}\n')
    try:
        uni, st = tmp / 'u', tmp / 'precedent-shared-x'
        (uni / 'practices').mkdir(parents=True)
        (st / 'practices').mkdir(parents=True)
        (uni / 'precedent-source.json').write_text('{"level": "universal"}')
        (uni / 'practices' / 'rule-a.md').write_text(fm.format(s='rule-a', st='active', r='New.'))
        (uni / 'practices' / 'rule-b.md').write_text(fm.format(s='rule-b', st='active', r='New.'))
        (st / 'practices' / 'rule-a.md').write_text(fm.format(s='rule-a', st='active', r='Copy.'))
        (st / 'practices' / 'rule-b.md').write_text(fm.format(s='rule-b', st='deduplicated', r='Stub.'))
        base = {'practices/rule-a.md': fm.format(s='rule-a', st='active', r='Old.'),
                'practices/rule-b.md': fm.format(s='rule-b', st='active', r='Old.')}

        class Ctx:
            def changed_matching(self, _pat):
                return list(base)
            def read(self, rel):
                return (pc.ROOT / rel).read_text()
            def read_base(self, rel):
                return base.get(rel)
        orig_root, orig_load = pc.ROOT, _pr.load_config
        try:
            pc.ROOT = uni
            _pr.load_config = lambda *_a, **_k: [
                {'level': 'universal', 'name': 'precedent', 'path': str(uni)},
                {'level': 'shared', 'name': 'precedent-shared-x', 'path': str(st),
                 'brought': True}]
            got = pc._universal_change_reaches_overrides(Ctx())
            cases.append(('a Rule change names the set whose active copy overrides it',
                          len(got) == 1 and 'rule-a' in str(got[0].__dict__)
                          and 'precedent-shared-x' in str(got[0].__dict__),
                          [g.__dict__ for g in got]))
            base['practices/rule-a.md'] = fm.format(s='rule-a', st='retired', r='New.')
            got = pc._universal_change_reaches_overrides(Ctx())
            cases.append(('a frontmatter-only edit names nothing, and a deduplicated '
                          'copy is never named', got == [], [g.__dict__ for g in got]))
            base['practices/rule-a.md'] = fm.format(s='rule-a', st='active', r='Old.')
            (uni / 'precedent-source.json').write_text('{"level": "shared"}')
            got = pc._universal_change_reaches_overrides(Ctx())
            cases.append(('outside the universal source it names nothing', got == []))
        finally:
            pc.ROOT, _pr.load_config = orig_root, orig_load
    finally:
        shutil.rmtree(tmp, ignore_errors=True)
    bad = [(c[0], c[2] if len(c) > 2 else '') for c in cases if not c[1]]
    return (not bad, f'{len(cases)} stated cases',
            '; '.join(f'{n} -- {str(d)[:400]}' for n, d in bad))


def check_generated_index_of_nothing_yet_passes():
    """generated-files-registered passes a repository whose generated index
    has no sources YET -- gotchas/INDEX.md with no gotcha written -- when the
    index's own generator check passes. 2026-10-04, a consumer with no
    gotchas: listed, "edit_instead ... matches nothing here"; unlisted,
    "gotchas/INDEX.md ... is not listed", so no state passed.

    CONTROL 1: the same entry whose generator check FAILS is still reported
    as pointing nowhere. CONTROL 2: an edit_instead whose directory does not
    exist is still reported, check passing or not."""
    import shutil, tempfile
    import precedent_check as pc
    tmp = pathlib.Path(tempfile.mkdtemp(prefix='precedent-empty-index-'))
    saved = pc.ROOT
    cases = []
    try:
        subprocess.run(['git', 'init', '-q', str(tmp)], capture_output=True)
        (tmp / 'gotchas').mkdir()
        (tmp / 'tools').mkdir()
        (tmp / 'gotchas' / 'INDEX.md').write_text(
            '---\ngenerated_by: tools/build_gotcha_index.py\n---\n\n# None yet\n',
            encoding='utf-8')
        gen = tmp / 'tools' / 'build_gotcha_index.py'

        def registry(glob):
            (tmp / 'tools' / 'generated_files.json').write_text(json.dumps({'files': [
                {'path': 'gotchas/INDEX.md', 'generated_by': 'tools/build_gotcha_index.py',
                 'edit_instead': glob, 'regenerate': 'python3 tools/build_gotcha_index.py',
                 'check': ['tools/build_gotcha_index.py', '--check']}]}), encoding='utf-8')
            subprocess.run(['git', '-C', str(tmp), 'add', '-A'], capture_output=True)

        def nowhere(check_rc, glob='gotchas/gotcha-*.md'):
            gen.write_text(f'import sys\nsys.exit({check_rc})\n', encoding='utf-8')
            registry(glob)
            pc.ROOT = tmp
            found = pc._generated_files_registered(None)
            return any("matches nothing" in f.detail for f in found), found

        hit, found = nowhere(0)
        cases.append(('an index of no gotchas yet, its generator check passing, is '
                      'not reported as pointing nowhere', not hit,
                      [f.detail for f in found]))
        hit, found = nowhere(1)
        cases.append(('CONTROL 1: with its generator check failing, it is', hit,
                      [f.detail for f in found]))
        hit, found = nowhere(0, 'nowhere/gotcha-*.md')
        cases.append(('CONTROL 2: a glob into a directory that does not exist is '
                      'reported, check passing or not', hit, [f.detail for f in found]))
    finally:
        pc.ROOT = saved
        shutil.rmtree(tmp, ignore_errors=True)
    bad = [(c[0], c[2]) for c in cases if not c[1]]
    return (not bad, f'{len(cases)} stated cases',
            '; '.join(f'{n} -- {str(d)[:300]}' for n, d in bad))


def check_update_fetches_brought_sets_before_the_views():
    """Update Vendors clones or pulls the sets the person's individual set
    brings before it syncs the views (2026-10-04: a consumer's first update
    after the ladder moved into a brought set ran in a session whose start
    predated the engine that clones it, and the sync listed the set's rules
    as lost). Function-level, with the fetch stood in: a fetched set is a
    step, one that could not be fetched is left for the person, none is
    silence, and in run order the step comes before the view sync."""
    sys.path.insert(0, str(ROOT / 'tools'))
    try:
        import precedent_update as pu
    finally:
        sys.path.pop(0)
    cases = []
    rep = pu.Report()
    pu.brought_sets_step(rep, fetch=lambda: [('fx-ladder', True, 'cloned')])
    cases.append(('a brought set fetched is reported as a step',
                  any(n == 'brought sets' and 'fx-ladder' in o for n, o in rep.steps)
                  and not rep.left))
    rep = pu.Report()
    pu.brought_sets_step(rep, fetch=lambda: [('fx-ladder', False, 'HTTP 404')])
    cases.append(('one that could not be fetched is left for the person, by name',
                  any('fx-ladder' in w and 'HTTP 404' in why for w, why in rep.left)))
    rep = pu.Report()
    pu.brought_sets_step(rep, fetch=lambda: [])
    cases.append(('a person who brings nothing hears nothing', not rep.steps
                  and not rep.left))
    src = (ROOT / 'tools' / 'precedent_update.py').read_text(encoding='utf-8')
    cases.append(('in run order, the step comes before the view sync',
                  0 < src.find('    brought_sets_step(rep)\n')
                  < src.find("    sync = repo / 'tools' / 'precedent_sync_views.py'")))
    bad = [n for n, ok in cases if not ok]
    return (not bad, f'{len(cases)} stated cases', '; '.join(bad))


def check_freshness_reads_a_section0_catalogues_own_sync():
    """The session-start freshness notice reads a section 0 catalogue (the
    universal practices copied into the repository) by its own
    CATALOGUE_SYNC.json, as vendored at that commit, of the repository and
    branch the engine comes from. 2026-10-04, a consumer: 159 practices at
    precedent/universal/ were reported at every session start as "declared,
    but neither a vendored manifest nor a git clone is there -- its
    practices are absent this session". CONTROL: with no sync record, the
    same tree is still reported absent."""
    import shutil, tempfile
    import precedent_engine_freshness as pef
    tmp = pathlib.Path(tempfile.mkdtemp(prefix='precedent-fresh-s0-'))
    saved = os.environ.get(pef.USER_CONFIG_ENV)
    os.environ[pef.USER_CONFIG_ENV] = str(tmp / 'no-user-config.json')
    cases = []
    try:
        (tmp / 'tools').mkdir()
        (tmp / 'tools' / 'ENGINE_MANIFEST.json').write_text(json.dumps({
            'source_repo': 'https://github.com/o/Precedent', 'source_branch': 'main',
            'source_commit': 'a' * 40}), encoding='utf-8')
        (tmp / 'precedent.json').write_text(json.dumps({'sources': [
            {'level': 'universal', 'name': 'precedent', 'path': 'precedent/universal'}]}),
            encoding='utf-8')
        cat = tmp / 'precedent' / 'universal'
        (cat / 'practices').mkdir(parents=True)
        (cat / 'practices' / 'x.md').write_text('x\n', encoding='utf-8')
        rows = pef.collect_targets(tmp)
        cases.append(('CONTROL: with no sync record the catalogue reads absent',
                      any(r.get('kind') == 'absent' for r in rows), rows))
        (cat / 'CATALOGUE_SYNC.json').write_text(json.dumps({'source_commit': 'b' * 40}),
                                                 encoding='utf-8')
        rows = pef.collect_targets(tmp)
        vend = [r for r in rows if r.get('kind') == 'vendored']
        cases.append(('with its sync record it reads vendored at that commit, of the '
                      'engine\'s repository and branch, and never absent',
                      not any(r.get('kind') == 'absent' for r in rows) and len(vend) == 1
                      and vend[0].get('recorded') == 'b' * 40
                      and vend[0].get('url') == 'https://github.com/o/Precedent'
                      and vend[0].get('branch') == 'main', rows))
    finally:
        if saved is None:
            os.environ.pop(pef.USER_CONFIG_ENV, None)
        else:
            os.environ[pef.USER_CONFIG_ENV] = saved
        shutil.rmtree(tmp, ignore_errors=True)
    bad = [(c[0], c[2]) for c in cases if not c[1]]
    return (not bad, f'{len(cases)} stated cases',
            '; '.join(f'{n} -- {str(d)[:400]}' for n, d in bad))


def check_update_asks_headings_only_of_published_files():
    """Update Vendors' view migration asks for headline case only on a moved
    source file the headline-capitalization check itself would judge
    (title_case.is_outward). 2026-10-04, a consumer whose precedent.json
    declares `"output_paths": []` was asked to recase MAP.source.md and
    GLOSSARY.source.md, which nothing of its publishes. Driven with the
    migration and the heading tool stood in. CONTROL: a moved file the check
    does reach is still asked about."""
    import shutil, tempfile
    sys.path.insert(0, str(ROOT / 'tools'))
    try:
        import precedent_update as pu
        import title_case as tc
    finally:
        sys.path.pop(0)
    tmp = pathlib.Path(tempfile.mkdtemp(prefix='precedent-migrate-headings-'))
    saved_run, saved_out = pu.run, tc.is_outward
    cases = []
    try:
        (tmp / 'tools').mkdir()
        for n in ('precedent_migrate_views.py', 'title_case.py'):
            (tmp / 'tools' / n).write_text('', encoding='utf-8')
        asked = []

        def fake_run(argv, cwd):
            if argv[1].endswith('precedent_migrate_views.py'):
                return 0, 'MAP.md -> MAP.source.md\nGLOSSARY.md -> GLOSSARY.source.md\n'
            asked.append(argv[2:])
            return 1, 'not headline case'
        pu.run = fake_run
        rep = pu.Report()
        pu.migrate_views_step(tmp, rep)
        cases.append(('moved source files nothing publishes are not asked about',
                      asked == [] and not rep.left
                      and any(n == 'headings kept' for n, _o in rep.steps),
                      (asked, rep.left, rep.steps)))
        tc.is_outward = lambda rel, root='.': rel == 'MAP.source.md'
        asked.clear()
        rep = pu.Report()
        pu.migrate_views_step(tmp, rep)
        cases.append(('CONTROL: one the check does reach is still asked about',
                      asked == [['MAP.source.md']] and rep.left, (asked, rep.left)))
    finally:
        pu.run, tc.is_outward = saved_run, saved_out
        shutil.rmtree(tmp, ignore_errors=True)
    bad = [(c[0], c[2]) for c in cases if not c[1]]
    return (not bad, f'{len(cases)} stated cases',
            '; '.join(f'{n} -- {str(d)[:400]}' for n, d in bad))


