def check_sync_refuses_a_rule_waiting_on_a_brought_set_by_name():
    """A sync that would drop a person's rule because the set providing its
    `requires:` capability is not on disk refuses with that reason and the
    remedy, and never points at --allow-removals. 2026-10-04, a consumer's
    update: ladder-required and promote-only read as removed, the refusal
    offered --allow-removals for "the source DELETED the file", and following
    it would have deleted two of the person's own rules. CONTROL: a rule its
    source really stopped producing still gets the old refusal."""
    import shutil, tempfile
    import build_views as bv
    tmp = pathlib.Path(tempfile.mkdtemp(prefix='precedent-sync-waiting-'))
    ind = tmp / 'precedent-individual'
    (ind / 'practices').mkdir(parents=True)
    (ind / 'precedent-source.json').write_text(json.dumps({
        'name': 'precedent-individual', 'level': 'individual'}), encoding='utf-8')
    for slug in ('zz-mine', 'zz-goes'):
        (ind / 'practices' / f'{slug}.md').write_text(
            _move_fixture_practice(slug), encoding='utf-8')
    (tmp / 'user-config.json').write_text(json.dumps({'individual': {
        'name': 'precedent-individual', 'path': str(ind)}}), encoding='utf-8')
    env = {**os.environ, 'HOME': str(tmp), 'PRECEDENT_USER_CONFIG': str(tmp / 'user-config.json'),
           'GIT_AUTHOR_NAME': 't', 'GIT_AUTHOR_EMAIL': 't@t', 'GIT_COMMITTER_NAME': 't',
           'GIT_COMMITTER_EMAIL': 't@t', 'PRECEDENT_ALLOW_ANY_AUTHOR': '1'}
    env.pop('PRECEDENT_NO_LADDERS', None)
    repo = tmp / 'consumer'
    cases = []
    try:
        subprocess.run(['git', 'init', '-q', '-b', 'main', str(repo)], env=env,
                       capture_output=True)
        (repo / 'precedent.json').write_text(json.dumps({
            'format_version': 1, 'visibility': 'private', 'base_branch': 'main',
            'sources': [{'level': 'universal', 'name': 'precedent', 'path': str(ROOT)}]}),
            encoding='utf-8')
        (repo / 'AGENTS.md').write_text(
            f'# fixture\n\n{bv.BEGIN_MARKER}\n{bv.END_MARKER}\n', encoding='utf-8')

        def sync():
            r = subprocess.run([sys.executable, str(ROOT / 'tools' / 'precedent_sync_views.py'),
                                '--repo', str(repo)], cwd=str(repo), env=env,
                               capture_output=True, text=True, timeout=600)
            return r.returncode, r.stdout + r.stderr
        rc, out = sync()
        recorded = json.loads((repo / 'MANIFEST.json').read_text()).get('practices') \
            if (repo / 'MANIFEST.json').is_file() else []
        cases.append(('fixture: the first sync records the person\'s two rules',
                      rc == 0 and {'zz-mine', 'zz-goes'} <= {e.get('slug') for e in recorded},
                      out[-500:]))
        subprocess.run(['git', '-C', str(repo), 'add', '-A'], env=env, capture_output=True)
        subprocess.run(['git', '-C', str(repo), 'commit', '-qm', 'synced'], env=env,
                       capture_output=True)
        # The person's set now brings a ladder set that is not on disk, and
        # one rule requires what it provides.
        (ind / 'precedent-source.json').write_text(json.dumps({
            'name': 'precedent-individual', 'level': 'individual',
            'brings': [{'name': 'fx-ladder', 'repo_url': 'https://example.invalid/o/fx-ladder'}]}),
            encoding='utf-8')
        mine = ind / 'practices' / 'zz-mine.md'
        mine.write_text(mine.read_text().replace(
            'defines:     []\n', 'defines:     []\nrequires:    ["ladder"]\n'), encoding='utf-8')
        rc, out = sync()
        cases.append(('a rule waiting on a brought set that is not on disk is refused '
                      'by that reason, naming the set and the remedy',
                      rc != 0 and 'zz-mine (from precedent-individual, requires ladder)' in out
                      and '`fx-ladder`, brought by your individual set, is not on disk' in out,
                      out[-700:]))
        cases.append(('...and the refusal never offers --allow-removals as the answer',
                      'is the answer, not a workaround' not in out
                      and 'Do NOT pass --allow-removals' in out, out[-700:]))
        mine.write_text(mine.read_text().replace('requires:    ["ladder"]\n', ''),
                        encoding='utf-8')
        (ind / 'practices' / 'zz-goes.md').unlink()
        rc, out = sync()
        cases.append(('CONTROL: a rule its source stopped producing still gets the '
                      'old refusal', rc != 0 and 'zz-goes (from precedent-individual)' in out
                      and 'requires ladder' not in out, out[-700:]))
    finally:
        shutil.rmtree(tmp, ignore_errors=True)
    bad = [(c[0], c[2]) for c in cases if not c[1]]
    return (not bad, f'{len(cases)} stated cases',
            '; '.join(f'{n} -- {str(d)[:700]}' for n, d in bad))


def check_every_tempdir_cleanup_retries():
    """A transient `Directory not empty` on a TemporaryDirectory's cleanup
    is retried for every check, not one (2026-10-05, the recurrence on a
    second check), and a directory that never empties still raises with
    its contents."""
    import tempfile
    cases = []
    real = shutil.rmtree
    calls = {'n': 0}

    def once_busy(path, *a, **k):
        calls['n'] += 1
        if calls['n'] == 1:
            raise OSError(39, 'Directory not empty')
        return real(path, *a, **k)

    def always_busy(path, *a, **k):
        raise OSError(39, 'Directory not empty')
    try:
        shutil.rmtree = once_busy
        with tempfile.TemporaryDirectory() as d:
            (pathlib.Path(d) / 'f').write_text('x')
        shutil.rmtree = real
        cases.append(('a delete that fails once is retried and the directory goes',
                      calls['n'] == 2 and not os.path.exists(d)))
        shutil.rmtree = always_busy
        said = ''
        try:
            with tempfile.TemporaryDirectory() as d2:
                (pathlib.Path(d2) / 'left').write_text('x')
        except OSError as e:
            said = str(e)
        shutil.rmtree = real
        cases.append(('...one that never empties still raises, naming what is left',
                      'still not empty' in said and 'left' in said))
    finally:
        shutil.rmtree = real
        for leftover in [x for x in (locals().get('d2'),) if x]:
            real(leftover, ignore_errors=True)
    failed = [name for name, ok in cases if not ok]
    return (not failed, f'{len(cases)} stated cases', '; '.join(failed))


def check_heading_anchor_keeps_combining_marks():
    """GitHub's heading anchor keeps combining marks -- its rule is Ruby's
    \\p{Word}: letters, marks, decimal digits, connector punctuation -- and
    Python's \\w does not. A pointed Hebrew heading lost its vowel points in
    doc_lint's anchor and doc_html's id, so a working link read as broken and
    the push was refused (2026-10-05, a consumer's manuscript table of
    contents; the id was measured against GitHub's own render)."""
    import tempfile, shutil
    sys.path.insert(0, str(ROOT / 'tools'))
    try:
        import doc_lint, doc_html
    finally:
        sys.path.pop(0)
    heading = 'Be \u201cNavon\u201d: \u201c\u05e0\u05b8\u05d1\u05d5\u05b9\u05df\u201d\u2014Penetrate'
    want = 'be-navon-\u05e0\u05b8\u05d1\u05d5\u05b9\u05dfpenetrate'
    cases = [
        ('doc_lint keeps the vowel points in the anchor', doc_lint.heading_slug(heading) == want),
        ("doc_html's heading id is the same anchor", doc_html.heading_slug(heading) == want),
        ('an ordinary heading is unchanged',
         doc_lint.heading_slug('A `code` & thing_x (2026)') == 'a-code--thing_x-2026'
         and doc_html.heading_slug('A <code>code</code> &amp; thing_x (2026)')
         == 'a-code--thing_x-2026'),
    ]
    tmp = pathlib.Path(tempfile.mkdtemp(prefix='precedent-anchor-marks-'))
    try:
        # The lint checks an anchor only inside the repository its own
        # script sits in, so the document and a copy of the tools share one.
        subprocess.run(['git', 'init', '-q', str(tmp)], check=True)
        shutil.copytree(ROOT / 'tools', tmp / 'tools',
                        ignore=shutil.ignore_patterns('__pycache__', '*.pyc'))
        doc = tmp / 'manuscript.md'
        doc.write_text(f'# Contents\n\n- [Navon](#{want})\n\n## {heading}\n\nText.\n',
                       encoding='utf-8')
        r = subprocess.run([sys.executable, str(tmp / 'tools' / 'doc_lint.py'), str(doc)],
                           capture_output=True, text=True, cwd=str(tmp))
        cases.append(('a link to the pointed heading passes the lint',
                       r.returncode == 0 and want not in (r.stdout + r.stderr)))
    finally:
        shutil.rmtree(tmp, ignore_errors=True)
    failed = [name for name, ok in cases if not ok]
    return (not failed, f'{len(cases)} stated cases', '; '.join(failed))


def check_spoken_commands_lead_the_session_start():
    """With five sets attached, a session opened above them got every repo's
    start-up output joined and cut, and the ladder's stage words came after
    the cut (2026-10-04, the review of the first fix).

    1. precedent_session_practices.py prints the spoken-commands block
       first, one line per practice defining a command.
    2. precedent_run_session_hooks.py lifts every repo's block to the front,
       merged, before the cut -- even a block from the LAST repo, under a cap
       the first repo alone overflows.
    3. The two files agree on how the block begins."""
    import io, contextlib, tempfile, shutil
    sys.path.insert(0, str(ROOT / 'tools'))
    try:
        import precedent_session_practices as psp
        import precedent_run_session_hooks as rsh
    finally:
        sys.path.pop(0)
    cases = []
    head = getattr(psp, 'SPOKEN_HEAD', None)
    prefix = getattr(rsh, 'SPOKEN_PREFIX', None)
    cases.append(('3. the writer and the runner agree on the block\'s first line',
                  bool(head and prefix and head.startswith(prefix))))
    tmp = pathlib.Path(tempfile.mkdtemp(prefix='precedent-spoken-first-'))
    saved_cap = getattr(rsh, 'CONTEXT_CAP', None)
    try:
        for name, out in (('a-first', 'x' * 400),
                          ('z-last', f'{head}\n- "Debut" -> debut: stage 4'
                                     f'\nnoise after the block')):
            repo = tmp / name
            (repo / '.git').mkdir(parents=True)
            (repo / '.claude').mkdir()
            (repo / 'out.txt').write_text(out + '\n', encoding='utf-8')
            (repo / '.claude' / 'settings.json').write_text(json.dumps({'hooks': {
                'SessionStart': [{'hooks': [{'type': 'command',
                                             'command': 'cat out.txt'}]}]}}))
        rsh.CONTEXT_CAP = 100
        buf = io.StringIO()
        with contextlib.redirect_stdout(buf), contextlib.redirect_stderr(io.StringIO()):
            rsh.run(tmp, log=tmp / 'hooks.log')
        ctx = json.loads(buf.getvalue())['hookSpecificOutput']['additionalContext']
        cases.append(("2. the last repo's spoken commands lead, ahead of a first repo "
                      "that overflows the cap",
                      ctx.startswith(f'{head}\n- "Debut" -> debut: stage 4')))
        cases.append(('2. ...and the block ends where its `- ` lines do',
                      'noise after the block' not in ctx.split('\n\n')[0]))
        practices = tmp / 'set' / 'practices'
        practices.mkdir(parents=True)
        (practices / 'debut.md').write_text(
            '---\nslug: debut\ntitle: Debut\ntier: on-demand\nstatus: active\n'
            'occasion: "a person says \\"Debut\\""\n'
            'index_clause: "stage 4: pre-staging into staging, full checks"\n'
            'command: {"Debut": "Stage 4."}\n---\n\n## Rule\n\nMove it.\n', encoding='utf-8')
        import build_views as bv
        block = psp.spoken_block(bv.load_practices(practices)) \
            if hasattr(psp, 'spoken_block') else ''
        cases.append(('1. a practice with a command is one line of the block',
                      block == f'{head}\n- "Debut" -> debut: stage 4: pre-staging '
                               f'into staging, full checks\n'))
    except (OSError, ValueError, KeyError, TypeError) as e:
        cases.append((f'fixture could not be built ({type(e).__name__}: {e})', False))
    finally:
        if saved_cap is not None:
            rsh.CONTEXT_CAP = saved_cap
        shutil.rmtree(tmp, ignore_errors=True)
    failed = [name for name, ok in cases if not ok]
    return (not failed, f'{len(cases)} stated cases', '; '.join(failed))


def check_update_vendors_onegplanning_findings():
    """Six upstream defects a consumer's Update Vendors hit on 2026-10-04,
    each planted here.

    1. gotchas/ was linked and never created; the update now starts it with
       the trap every install inherits, and names an inline copy left behind.
    2. A refreshed generator's output was left stale (todo/TODO.md): the
       update rebuilds what its staged inputs make due, and the check that
       would have said so runs at the basic tier.
    3. A placeholder filled without its backticks read as divergence.
    4. Repointing settings.json duplicated allow rules.
    5. Citations of live, merely reworded slugs in code, and any citation in
       an engine-owned file, were sent to the consumer to read.
    6. The start-up pip install threw its error away."""
    import tempfile, shutil
    sys.path.insert(0, str(ROOT / 'tools'))
    try:
        import precedent_update as pu
        import precedent_vendor_engine as pve
        import precedent_push_check as ppc
    finally:
        sys.path.pop(0)
    cases = []
    tmp = pathlib.Path(tempfile.mkdtemp(prefix='precedent-oneg-findings-'))
    env = dict(os.environ, GIT_AUTHOR_NAME='F', GIT_AUTHOR_EMAIL='f@example.com',
               GIT_COMMITTER_NAME='F', GIT_COMMITTER_EMAIL='f@example.com',
               GIT_CONFIG_GLOBAL=os.devnull, GIT_CONFIG_NOSYSTEM='1')

    def git(repo, *a):
        return subprocess.run(['git', '-C', str(repo), *a], env=env,
                              capture_output=True, text=True, check=True)
    try:
        r = tmp / 'r'
        subprocess.run(['git', 'init', '-q', str(r)], env=env, check=True)
        (r / 'AGENTS.md').write_text(
            '# A\n\n- **A session\'s checkout can be stale enough to look '
            'complete while missing real, merged work.**\n', encoding='utf-8')
        rep = pu.Report()
        seed = getattr(pu, 'gotchas_seed_step', None)
        if seed:
            seed(r, rep, 'HEAD')
        seeded = r / 'gotchas' / 'gotcha-2026-09-01-a-stale-checkout-looks-complete-with-no-error.md'
        cases.append(('1. a consumer with no gotchas/ gets the seed trap',
                      seeded.is_file() and '## Symptom' in seeded.read_text()))
        cases.append(('1. ...and is told to remove the inline copy',
                      any(w == 'AGENTS.md' and 'inline' in why for w, why in rep.left)))

        (r / 'tools').mkdir()
        (r / 'tools' / 'gen.py').write_text(
            'import pathlib, sys\n'
            'out = "generated v2\\n"\n'
            'if "--check" in sys.argv:\n'
            '    sys.exit(0 if pathlib.Path("OUT.md").read_text() == out else 1)\n'
            'pathlib.Path("OUT.md").write_text(out)\n', encoding='utf-8')
        (r / 'OUT.md').write_text('generated v1\n', encoding='utf-8')
        (r / 'tools' / 'generated_files.json').write_text(json.dumps({'files': [
            {'path': 'OUT.md', 'regenerate': 'python3 tools/gen.py',
             'check': ['tools/gen.py', '--check'], 'edit_instead': 'tools/gen.py'}]}))
        git(r, 'add', '-A')
        git(r, 'commit', '-qm', 'base')
        (r / 'tools' / 'gen.py').write_text(
            (r / 'tools' / 'gen.py').read_text() + '# refreshed\n', encoding='utf-8')
        git(r, 'add', 'tools/gen.py')
        rep = pu.Report()
        step = getattr(pu, 'regenerated_step', None)
        got = step(r, rep) if step else None
        cases.append(('2. a refreshed generator rebuilds and stages its output',
                      got == ['OUT.md']
                      and git(r, 'show', ':OUT.md').stdout == 'generated v2\n'))
        kinds_ok = all(any(e[0] == 'generated_files' for e in ppc.PUSH_CHECKS[k])
                       for k in ('source', 'consumer'))
        cases.append(('2. ...and the generated-files check runs at the basic tier',
                      'generated_files' in ppc.BASIC_CHECKS and kinds_ok))

        tmpl = ('## X\n\n- **Deep check** -- the full suite, and `<your own audits>`. '
                'Gates a push and a merge.\n')
        local = ('## X\n\n- **Deep check** -- the full suite, and python3 '
                 'tools/oneg_audit.py. Gates a push and a merge.\n')
        cases.append(('3. a placeholder filled without its backticks is carried',
                      pve.missing_markdown_blocks(local, tmpl) == []))
        cases.append(('3. ...and a sentence really dropped is still reported',
                      pve.missing_markdown_blocks('## X\n\nnothing here at all\n', tmpl) != []))

        dedupe = getattr(pu, '_without_duplicate_permissions', None)
        doubled = json.dumps({'permissions': {'allow': [
            'Bash(python3 tools/doc_lint.py)', 'Bash(git status)',
            'Bash(python3 tools/doc_lint.py)']}}, indent=2)
        once = json.loads(dedupe(doubled)) if dedupe else {}
        cases.append(('4. a repointed allow list keeps one copy of each rule, in order',
                      once.get('permissions', {}).get('allow') ==
                      ['Bash(python3 tools/doc_lint.py)', 'Bash(git status)']))

        find = getattr(pu, 'citation_findings', None)
        data = {'slugs': {'upstream-fix': 'Rule reworded', 'gone': 'withdrawn'},
                'successors': {},
                'hits': [
                    {'source': 'this repository', 'kind': 'live', 'slug': 'upstream-fix',
                     'file': 'tools/bootstrap.sh', 'line': 389},
                    {'source': 'this repository', 'kind': 'live', 'slug': 'upstream-fix',
                     'file': '.claude/hooks/freshness-guard.sh', 'line': 13},
                    {'source': 'this repository', 'kind': 'live', 'slug': 'upstream-fix',
                     'file': 'docs/notes.md', 'line': 4},
                    {'source': 'this repository', 'kind': 'live', 'slug': 'gone',
                     'file': '.claude/hooks/freshness-guard.sh', 'line': 9,
                     'must_fix': True}]}
        fix, read = find(data, {'.claude/hooks/freshness-guard.sh'}) if find else (None, None)
        cases.append(('5. a reworded live slug is a read only in a document, and '
                      'nothing in an engine-owned file is reported',
                      fix == [] and read == ['docs/notes.md:4']))

        for rel in ('templates/bootstrap.sh', 'tools/bootstrap.sh'):
            boot = (ROOT / rel).read_text(encoding='utf-8')
            cases.append((f'6. {rel} keeps pip\'s error and checks the import after',
                          'pip install --quiet cmarkgfm markdown 2>"$_pip_log"' in boot
                          and 'pip install --quiet cmarkgfm markdown 2>/dev/null' not in boot
                          and "python3 -c 'import cmarkgfm, markdown'" in boot))
    except (OSError, subprocess.CalledProcessError, TypeError, ValueError,
            AttributeError, KeyError) as e:
        cases.append((f'fixture could not be built ({type(e).__name__}: {e})', False))
    finally:
        shutil.rmtree(tmp, ignore_errors=True)
    failed = [name for name, ok in cases if not ok]
    return (not failed, f'{len(cases)} stated cases', '; '.join(failed))


def check_a_brought_sets_spoken_trigger_reaches_the_session_at_start():
    """A consumer's session searched the clones for "Debut" (2026-10-04).

    The ladder's stage words live in a set the person brings, which is
    deferred to the untracked .precedent/SESSION_PRACTICES.md. A practice
    set's own hook hands that file back as context; a consumer's session-start
    hook only ran precedent_session_practices.py, which wrote the file and
    printed nothing, and the consumer's generated Standing instruction never
    pointed at it, because a brought set is left out of defers_sources.

    1. The write prints the block on stdout -- a SessionStart hook's output
       is what reaches the session -- with a spoken trigger's line in it.
    2. --quiet writes the same file and prints nothing, and the set's own
       hook, which emits the file itself, passes it. A consumer declines that
       hook, so its start-up script (templates/bootstrap.sh) runs the write.
    3. A loader block whose sources are all tracked still carries the
       read-it-too sentence."""
    import io, contextlib, tempfile, shutil
    sys.path.insert(0, str(ROOT / 'tools'))
    try:
        import precedent_session_practices as psp
        import build_views as bv
    finally:
        sys.path.pop(0)
    cases = []
    tmp = pathlib.Path(tempfile.mkdtemp(prefix='precedent-spoken-trigger-'))
    saved_collect = psp.collect
    try:
        practices = tmp / 'set' / 'practices'
        practices.mkdir(parents=True)
        (practices / 'debut.md').write_text(
            '---\n'
            'slug: debut\n'
            'title: Debut\n'
            'tier: on-demand\n'
            'status: active\n'
            'occasion: "a person says \\"Debut\\""\n'
            'index_clause: "stage 4: pre-staging into staging, full checks"\n'
            'command: {"Debut": "Stage 4."}\n'
            '---\n\n## Rule\n\nMove pre-staging into staging.\n\n'
            '## Why\n\nSo staging is tested.\n', encoding='utf-8')
        extra = bv.load_practices(practices)
        repo = tmp / 'consumer'
        repo.mkdir()
        psp.collect = lambda r, skip_brought=False: (
            extra, {'debut': 'shared'},
            [('deferred', 'a brought set, deferred to this file')])

        def run(*flags):
            out, saved_argv = io.StringIO(), sys.argv
            sys.argv = ['precedent_session_practices.py', '--repo', str(repo), *flags]
            try:
                with contextlib.redirect_stdout(out), \
                        contextlib.redirect_stderr(io.StringIO()):
                    psp.main()
            finally:
                sys.argv = saved_argv
            written = repo / '.precedent' / 'SESSION_PRACTICES.md'
            return out.getvalue(), (written.read_text(encoding='utf-8')
                                    if written.is_file() else '')
        said, written = run()
        line = 'When a person says "Debut":'
        cases.append(('1. the session-start write prints the block, spoken trigger and all',
                      line in said and line in written))
        (repo / '.precedent' / 'SESSION_PRACTICES.md').unlink()
        said, written = run('--quiet')
        cases.append(('2. --quiet writes the same file and prints only the spoken commands',
                      said.startswith(getattr(psp, 'SPOKEN_HEAD', '\0'))
                      and '"Debut" -> debut' in said
                      and 'Occasion index' not in said and line in written))
        hook = (ROOT / 'templates' / 'harness' / 'claude-code' / 'hooks'
                / 'precedent-universal-catalogue.sh').read_text(encoding='utf-8')
        cases.append(("2. ...and the set's hook, which emits the file whole, passes --quiet",
                      'precedent_session_practices.py" --repo "$P" --quiet' in hook))
        boot = (ROOT / 'templates' / 'bootstrap.sh').read_text(encoding='utf-8')
        cases.append(("2. ...and a consumer's start-up script runs the write at all",
                      'python3 tools/precedent_session_practices.py' in boot))
        block, _t, _n = bv.build_loader_block(extra, defers_sources=False)
        cases.append(('3. a block that defers nothing still points at the file',
                      '.precedent/SESSION_PRACTICES.md exists, read it too' in block))
    except (OSError, TypeError, ValueError) as e:
        cases.append((f'fixture could not be built ({e})', False))
    finally:
        psp.collect = saved_collect
        shutil.rmtree(tmp, ignore_errors=True)
    failed = [name for name, ok in cases if not ok]
    return (not failed, f'{len(cases)} stated cases', '; '.join(failed))


def check_views_follow_the_header_stamp_and_consumer_check_skips_absent_views():
    """Two Update Vendors defects a consumer hit on 2026-10-04.

    1. precedent_update.py stamped MAP.source.md's version header AFTER the
       views step had built MAP.md from it, and MAP.md copies that header, so
       the basic check failed on a stale MAP.md on every run.
       rebuild_views_after_stamp() builds the views again when a stamped path
       is a view's source, re-stages only a view the update had staged, and
       says so when the build fails.
    2. `build_views.py --check` demanded a root GLOSSARY.md that a consumer
       whose glossary lives in docs/ never has; the 2026-10-03 fix covered
       --views-only only. A consumer's check now skips a view it lacks and
       has no source for, and BestPractice's own check still calls a deleted
       view drift."""
    import io, contextlib, tempfile, shutil
    sys.path.insert(0, str(ROOT / 'tools'))
    try:
        import precedent_update as pu
        import build_views as bv
    finally:
        sys.path.pop(0)
    rebuild = getattr(pu, 'rebuild_views_after_stamp', None)
    cases = []
    tmp = pathlib.Path(tempfile.mkdtemp(prefix='precedent-stamp-views-'))
    env = dict(os.environ, GIT_AUTHOR_NAME='F', GIT_AUTHOR_EMAIL='f@example.com',
               GIT_COMMITTER_NAME='F', GIT_COMMITTER_EMAIL='f@example.com',
               GIT_CONFIG_GLOBAL=os.devnull, GIT_CONFIG_NOSYSTEM='1')

    def git(repo, *a):
        return subprocess.run(['git', '-C', str(repo), *a], env=env,
                              capture_output=True, text=True, check=True)
    try:
        r = tmp / 'r'
        subprocess.run(['git', 'init', '-q', str(r)], env=env, check=True)
        (r / 'tools').mkdir()
        # A stand-in build: MAP.md carries the generated header and copies
        # its source's version line, the thing the real build does.
        (r / 'tools' / 'build_views.py').write_text(
            'import pathlib, sys\n'
            'src = pathlib.Path("MAP.source.md").read_text().strip()\n'
            'pathlib.Path("MAP.md").write_text("---\\ngenerated_by: '
            'tools/build_views.py\\n---\\n" + src + "\\n")\n'
            'if pathlib.Path("FAIL").exists():\n'
            '    sys.exit("build_views FAIL: planted")\n', encoding='utf-8')
        (r / 'MAP.source.md').write_text('version: 1\n', encoding='utf-8')
        subprocess.run([sys.executable, 'tools/build_views.py'], cwd=r, check=True)
        git(r, 'add', '-A')
        git(r, 'commit', '-qm', 'base')
        # The update edits the source and the views step builds MAP.md from it.
        (r / 'MAP.source.md').write_text('version: 1\nedited\n', encoding='utf-8')
        subprocess.run([sys.executable, 'tools/build_views.py'], cwd=r, check=True)
        git(r, 'add', 'MAP.source.md', 'MAP.md')
        # Then the stamp bumps the source's version, after the build.
        (r / 'MAP.source.md').write_text('version: 2\nedited\n', encoding='utf-8')
        git(r, 'add', 'MAP.source.md')
        got = rebuild(r, ['MAP.source.md']) if rebuild else None
        cases.append(('1. a stamped source builds its view again and re-stages it',
                      got == ['MAP.md']
                      and 'version: 2' in git(r, 'show', ':MAP.md').stdout))
        before = (r / 'MAP.md').read_text()
        (r / 'MAP.md').write_text(before + 'x\n')
        cases.append(('1. ...a stamp of anything else builds nothing',
                      rebuild is not None and rebuild(r, ['AGENTS.md']) == []
                      and (r / 'MAP.md').read_text().endswith('x\n')))
        git(r, 'commit', '-qm', 'staged')
        (r / 'MAP.source.md').write_text('version: 3\nedited\n', encoding='utf-8')
        git(r, 'add', 'MAP.source.md')
        (r / 'MAP.md').write_text(before)
        got = rebuild(r, ['MAP.source.md']) if rebuild else None
        staged = git(r, 'diff', '--cached', '--name-only').stdout.split()
        cases.append(('1. ...a view the update had not staged is rebuilt but left unstaged',
                      got == [] and 'MAP.md' not in staged))
        (r / 'FAIL').write_text('')
        try:
            said = rebuild(r, ['MAP.source.md']) if rebuild else None
        except RuntimeError as e:
            said = str(e)
        cases.append(('1. ...and a failed build is said, by its own words',
                      isinstance(said, str) and 'build_views FAIL: planted' in said))

        repo = tmp / 'bp'
        shutil.copytree(ROOT, repo, ignore=shutil.ignore_patterns(
            '.git', '__pycache__', '*.pyc', 'prompts'))
        (repo / 'GLOSSARY.md').unlink()
        # where_things_are.json links GLOSSARY.md, and its own guard would
        # refuse first; the view check is what this case judges.
        (repo / 'where_things_are.json').unlink()

        def check_names_glossary(consumer):
            saved, saved_argv = getattr(bv, 'repo_is_consumer', None), sys.argv
            bv.repo_is_consumer = lambda root: consumer
            sys.argv = ['build_views.py', '--repo', str(repo), '--check']
            buf = io.StringIO()
            try:
                with contextlib.redirect_stdout(buf), contextlib.redirect_stderr(buf):
                    try:
                        bv.main()
                    except SystemExit as e:
                        buf.write(f'\n{e.code}\n')
            finally:
                sys.argv = saved_argv
                if saved is None:
                    del bv.repo_is_consumer
                else:
                    bv.repo_is_consumer = saved
            out = buf.getvalue()
            return 'drifted from regeneration' in out and 'GLOSSARY.md' in out
        cases.append(("2. a consumer's --check does not demand a GLOSSARY.md it never had",
                      not check_names_glossary(True)))
        cases.append(("2. ...BestPractice's own --check still calls a deleted one drift",
                      check_names_glossary(False)))
        cases.append(('2. ...and the consumer test reads the manifest kind, nothing else',
                      hasattr(bv, 'repo_is_consumer')
                      and not bv.repo_is_consumer(ROOT)))
    except (OSError, subprocess.CalledProcessError, TypeError, ValueError) as e:
        cases.append((f'fixture could not be built ({e})', False))
    finally:
        shutil.rmtree(tmp, ignore_errors=True)
    failed = [name for name, ok in cases if not ok]
    return (not failed, f'{len(cases)} stated cases', '; '.join(failed))


def check_update_adopts_an_earlier_runs_catalogue_mirror():
    """A re-run of Update Vendors stages the catalogue mirror an earlier run
    wrote, when the catalogue manifest names the pinned commit and every
    such file is upstream's at it (or gone where the mirror has none).
    2026-10-04, a consumer's fourth run: 80 process/upstream/ files of an
    earlier run's mirror were left unstaged beside a staged manifest naming
    the new commit. CONTROL: one edited file means nothing is taken."""
    import shutil, tempfile
    sys.path.insert(0, str(ROOT / 'tools'))
    try:
        import precedent_update as pu
    finally:
        sys.path.pop(0)
    head = subprocess.run(['git', '-C', str(ROOT), 'rev-parse', 'HEAD'],
                          capture_output=True, text=True).stdout.strip()
    tmp = pathlib.Path(tempfile.mkdtemp(prefix='precedent-adopt-mirror-'))
    saved = pu.SOURCE
    cases = []
    try:
        pu.SOURCE = ROOT
        tree = tmp / 'process' / 'upstream'
        (tree / 'practices').mkdir(parents=True)
        upstream = subprocess.run(['git', '-C', str(ROOT), 'show', f'{head}:practices/park-it.md'],
                                  capture_output=True).stdout
        (tree / 'practices' / 'park-it.md').write_bytes(upstream)
        (tmp / 'process' / 'manifest.json').write_text(json.dumps({'upstream': {
            'vendored_at': 'process/upstream', 'commit': head}}), encoding='utf-8')
        before = {'process/upstream/practices/park-it.md',
                  'process/upstream/practices/zz-never-upstream.md',
                  'process/manifest.json', 'NOTES.md'}
        got = pu.adopt_catalogue_output(tmp, before, head)
        cases.append(('an earlier run\'s mirror, byte for byte upstream\'s, and a path '
                      'upstream has none of, are adopted with the manifest; the '
                      'person\'s own file is not',
                      set(got) == before - {'NOTES.md'}, got))
        (tree / 'practices' / 'park-it.md').write_bytes(upstream + b'mine\n')
        got = pu.adopt_catalogue_output(tmp, before, head)
        cases.append(('CONTROL: one edited file means nothing is taken', got == [], got))
        (tree / 'practices' / 'park-it.md').write_bytes(upstream)
        got = pu.adopt_catalogue_output(tmp, before, 'f' * 40)
        cases.append(('...nor when the manifest names another commit', got == [], got))
    finally:
        pu.SOURCE = saved
        shutil.rmtree(tmp, ignore_errors=True)
    bad = [(c[0], c[2]) for c in cases if not c[1]]
    return (not bad, f'{len(cases)} stated cases',
            '; '.join(f'{n} -- {str(d)[:300]}' for n, d in bad))


def check_show_follows_a_deduplicated_slug_across_sources():
    """precedent_show.py SLUG follows a deduplicated slug to the rule in
    force, across declared sources and through a set's copy that names its
    own slug (in force under that name elsewhere). 2026-10-04: file-mention-
    links, merged into rule-links by way of the writing set, answered
    "unknown slug", while current-rule-governs tells every session this tool
    follows a deduplicated copy to the live one. CONTROL: a slug nothing
    declares is still unknown."""
    import shutil, tempfile
    tmp = pathlib.Path(tempfile.mkdtemp(prefix='precedent-show-chain-'))
    cases = []

    def practice(slug, status='active', to='null', rule='Do the thing.'):
        return (_move_fixture_practice(slug)
                .replace('status:      active\nin_force_at: null',
                         f'status:      {status}\nin_force_at: {to}')
                .replace('## Rule\nDo the thing.', '## Rule\n' + rule))
    try:
        a, b = tmp / 'set-a', tmp / 'set-b'
        for d, name in ((a, 'fx-set-a'), (b, 'fx-set-b')):
            (d / 'practices').mkdir(parents=True)
            (d / 'precedent-source.json').write_text(json.dumps({'name': name, 'level': 'shared'}),
                                                     encoding='utf-8')
        (a / 'practices' / 'zz-old.md').write_text(practice('zz-old', 'deduplicated', 'zz-old'),
                                                   encoding='utf-8')
        (b / 'practices' / 'zz-old.md').write_text(practice('zz-old', 'deduplicated', 'zz-new'),
                                                   encoding='utf-8')
        (b / 'practices' / 'zz-new.md').write_text(practice('zz-new', rule='The live rule.'),
                                                   encoding='utf-8')
        repo = tmp / 'consumer'
        repo.mkdir()
        (repo / 'precedent.json').write_text(json.dumps({'format_version': 1, 'sources': [
            {'level': 'shared', 'name': 'fx-set-a', 'path': str(a)},
            {'level': 'shared', 'name': 'fx-set-b', 'path': str(b)}]}), encoding='utf-8')
        env = {**os.environ, 'PRECEDENT_USER_CONFIG': str(tmp / 'no-user-config.json')}

        def show(slug):
            r = subprocess.run([sys.executable, str(ROOT / 'tools' / 'precedent_show.py'),
                                '--repo', str(repo), slug], capture_output=True, text=True,
                               env=env, timeout=120)
            return r.returncode, r.stdout + r.stderr
        rc, out = show('zz-old')
        cases.append(('a slug deduplicated through a set\'s own-name copy shows the rule '
                      'it was merged into, and says so',
                      rc == 0 and 'zz-old -> zz-new' in out and 'The live rule.' in out
                      and 'was merged into `zz-new`' in out, out[-500:]))
        rc, out = show('zz-nothing')
        cases.append(('CONTROL: a slug nothing declares is still unknown',
                      rc != 0 and 'unknown slug' in out, out[-300:]))
    finally:
        shutil.rmtree(tmp, ignore_errors=True)
    bad = [(c[0], c[2]) for c in cases if not c[1]]
    return (not bad, f'{len(cases)} stated cases',
            '; '.join(f'{n} -- {str(d)[:400]}' for n, d in bad))


def check_ladder_off_engine_says_no_ladder_words():
    """spec/LADDER_OPT_IN_PLAN.md assertion B, on the engine's own output: a
    person with no practice set of their own -- the ladder not in force --
    runs the tools a session runs, in this repository, and none of them
    prints a ladder word (tools/ladder_words.py's output matcher). Measured
    2026-10-02 before the change: about 450 such words across these outputs.

    `PRECEDENT_ASSUME_LADDER` (the harness default) is cleared for every run
    here: this is the off-ladder world, as a person off the ladder meets it.
    One phrase is excused by name, the ordinary English "staging document"."""
    import ladder_words as lw
    import tempfile
    env = {k: v for k, v in os.environ.items()
           if k not in ('PRECEDENT_ASSUME_LADDER', 'PRECEDENT_NO_LADDERS')}
    env['PRECEDENT_USER_CONFIG'] = str(pathlib.Path(tempfile.gettempdir())
                                       / 'no-such-precedent-config.json')
    runs = [
        ('the reply gate', ['tools/precedent_gate.py', 'reply']),
        ('the merge gate', ['tools/precedent_gate.py', 'merge']),
        ('the push gate', ['tools/precedent_gate.py', 'push']),
        ('the review gate', ['tools/precedent_gate.py', 'review']),
        ('the reply check\'s requirements', ['tools/precedent_reply_check.py', '--explain']),
        ('Vocabulary', ['tools/precedent_vocabulary.py']),
        ('the landing branch', ['tools/precedent_branches.py', '--landing']),
        ('the branch status', ['tools/precedent_branches.py']),
        ('the deep check\'s listing', ['tools/precedent_push_check.py', '--list']),
        ('the staging watermark', ['tools/precedent_beta_watermark_check.py',
                                   '--no-push', '--no-fetch']),
        ('the ladder helper', ['tools/precedent_ladder.py', '--status']),
    ]
    excused = ('staging document',)
    cases = []
    for what, argv in runs:
        r = subprocess.run([sys.executable, *argv], cwd=str(ROOT), env=env,
                           capture_output=True, text=True, timeout=600)
        text = r.stdout + r.stderr
        # A quoted commit ("  aeadfef4 <title>") is the repository's own
        # history, written by people, not the engine's wording: a person off
        # the ladder meets the same titles in `git log`. Found 2026-10-03:
        # inside a Debut the checked copy sits on the Debut's own merge
        # commit, titled "Promote pre-staging into staging", and the reply
        # gate lists it as unlanded work. So is a command still running in
        # the session ("  pid N, running MM:SS: <command>",
        # precedent_container_safe): the person's own words, quoted. Found
        # 2026-10-04: a set's Debut, running beside this check, failed it.
        lines = [l for l in text.splitlines()
                 if not any(x in l for x in excused)
                 and not re.match(r'\s+[0-9a-f]{7,40} \S', l)
                 and not re.match(r'\s+pid \d+, running [\d:-]+: ', l)]
        found = lw.output_hits('\n'.join(lines))
        # The lines themselves, not only the words: a hit that appeared only
        # inside a Debut (2026-10-03) could not be found from the words.
        said = [lines[n - 1][:300] for n in sorted({h[0] for h in found})][:3]
        cases.append((f'{what} says no ladder word to a person off the ladder',
                      not found, f'{found[:6]!r} in {said!r}'))
    r = subprocess.run([sys.executable, 'tools/precedent_branches.py', '--landing'],
                       cwd=str(ROOT), env=env, capture_output=True, text=True)
    cases.append(('their work lands on main',
                  r.stdout.splitlines()[:1] == ['main'], r.stdout[:200]))
    bad = [(c[0], c[2]) for c in cases if not c[1]]
    check(f'off the ladder, the engine prints none of the ladder\'s words '
          f'({len(cases)} stated cases)',
          not bad, '; '.join(f"{n} -- {d}" for n, d in bad))

def check_ladder_test_session_and_the_two_ladder_checks():
    """spec/LADDER_OPT_IN_PLAN.md D7, D13 and the per-person rule.

    - A No ladders session pushes and merges nothing: the push gate and the
      merge check refuse, by name; without the variable neither refuses.
    - ladder-words-stay-in-the-ladder-set finds a ladder word planted in a
      practice set that does not provide the ladder, passes the same text
      in one that does, and passes a Story.
    - ladder-set-is-brought-not-declared finds a precedent.json that
      declares a set providing the ladder, and passes one that declares an
      ordinary set: the ladder is each person's to bring, and a repository
      that declares it puts it on everybody who works there."""
    import shutil, tempfile
    import precedent_check as pc
    import precedent_ladder
    cases = []
    env = {k: v for k, v in os.environ.items()
           if k not in ('PRECEDENT_ASSUME_LADDER',)}
    env['PRECEDENT_NO_LADDERS'] = '1'
    r = subprocess.run([sys.executable, 'tools/precedent_push_check.py', '--gate'],
                       cwd=str(ROOT), env=env, capture_output=True, text=True,
                       timeout=120)
    cases.append(('a No ladders session: the push gate refuses',
                  r.returncode == 1 and 'nothing is pushed' in r.stdout,
                  f'rc={r.returncode} {r.stdout[:200]}'))
    r = subprocess.run([sys.executable, 'tools/precedent_merge_check.py',
                        '--owner', 'o', '--repo', 'r', '--number', '1'],
                       cwd=str(ROOT), env=env, capture_output=True, text=True,
                       timeout=120)
    cases.append(('a No ladders session: the merge check refuses',
                  r.returncode == 1 and 'nothing is pushed' in r.stdout,
                  f'rc={r.returncode} {r.stdout[:200]}'))
    old_env = os.environ.pop('PRECEDENT_NO_LADDERS', None)
    try:
        cases.append(('any other session: no refusal',
                      precedent_ladder.test_session_refusal() is None, ''))
    finally:
        if old_env is not None:
            os.environ['PRECEDENT_NO_LADDERS'] = old_env

    tmp = pathlib.Path(tempfile.mkdtemp(prefix='precedent-ladder-checks-'))
    saved_root = pc.ROOT
    try:
        plain, ladder = tmp / 'plain-set', tmp / 'ladder-set'
        # Three individual sets beside them (2026-10-03, found rehearsing a
        # Produce: the check refused the individual set of a person who
        # brings the ladder, and with it their own next Update Vendors).
        ind_lad, ind_plain, ind_gone = (tmp / 'ind-brings-ladder',
                                        tmp / 'ind-brings-plain',
                                        tmp / 'ind-brings-uncloned')
        for d, man in ((plain, {'level': 'shared', 'provides': []}),
                       (ladder, {'level': 'shared', 'provides': ['ladder']}),
                       (ind_lad, {'level': 'individual', 'brings': [
                           {'name': 'ladder-set', 'repo_url': 'https://example.com/l.git'}]}),
                       (ind_plain, {'level': 'individual', 'brings': [
                           {'name': 'plain-set', 'repo_url': 'https://example.com/p.git'}]}),
                       (ind_gone, {'level': 'individual', 'brings': [
                           {'name': 'not-cloned-set', 'repo_url': 'https://example.com/n.git'}]})):
            (d / 'practices').mkdir(parents=True)
            (d / 'precedent-source.json').write_text(json.dumps(
                dict(name=d.name, **man)))
            (d / 'practices' / 'x.md').write_text(
                '---\nslug: x\nstatus: active\n---\n\n## Rule\n\n'
                'Say "Booked" at step 3 of 5.\n\n## Story\n\n'
                'On the day, we said Promote 2.\n')
        for root, want, what in ((plain, 2, 'a set without the ladder'),
                                 (ladder, None, 'the set that provides it'),
                                 (ind_lad, None, 'an individual set that brings it'),
                                 (ind_plain, 2, 'an individual set that brings only an ordinary set'),
                                 (ind_gone, 2, 'an individual set whose brought set is not cloned')):
            pc.ROOT = root
            why = ''
            try:
                got = pc._ladder_words_stay_in_the_ladder_set(None)
                n = len(got)
            except pc.NotApplicable as e:
                n, why = None, str(e)
            # A skip says why, so a skip for another reason fails here.
            because = {ladder: 'provides the ladder',
                       ind_lad: 'brings ladder-set'}.get(root, '')
            cases.append((f'Check E in {what}: '
                          f'{"skipped" if want is None else f"{want}+ finding(s), none in the Story"}',
                          (n is None and because in why) if want is None else
                          (n is not None and n >= want and all(':9:' not in str(f) and ':10:' not in str(f) for f in got)),
                          f'got {n} {why!r}: {[str(f) for f in (got if n else [])][:4]}'))
        # The same individual set checked from a linked worktree elsewhere
        # (2026-10-04): a Debut or Produce checks the set in a throwaway
        # worktree under the temp directory, where nothing sits beside it.
        # The ladder set it brings is found beside the main checkout, so the
        # check still stands aside -- before, the set's own Debut was refused.
        _genv = dict(os.environ, GIT_AUTHOR_NAME='F', GIT_AUTHOR_EMAIL='f@x',
                     GIT_COMMITTER_NAME='F', GIT_COMMITTER_EMAIL='f@x',
                     GIT_CONFIG_GLOBAL=os.devnull, PRECEDENT_ALLOW_ANY_AUTHOR='1')
        subprocess.run(['git', 'init', '-q', str(ind_lad)], env=_genv, check=True)
        subprocess.run(['git', '-C', str(ind_lad), 'add', '-A'], env=_genv, check=True)
        subprocess.run(['git', '-C', str(ind_lad), 'commit', '-qm', 'x', '--no-verify'],
                       env=_genv, check=True)
        _elsewhere = pathlib.Path(tempfile.mkdtemp(prefix='precedent-ladder-wt-'))
        _wt = _elsewhere / 'wt'
        subprocess.run(['git', '-C', str(ind_lad), 'worktree', 'add', '-q', '--detach',
                        str(_wt)], env=_genv, check=True)
        try:
            pc.ROOT = _wt
            why = ''
            try:
                n = len(pc._ladder_words_stay_in_the_ladder_set(None))
            except pc.NotApplicable as e:
                n, why = None, str(e)
            cases.append(('Check E in an individual set that brings it, checked '
                          'from a linked worktree elsewhere: skipped',
                          n is None and 'brings ladder-set' in why,
                          f'got {n} {why!r}'))
        finally:
            shutil.rmtree(_elsewhere, ignore_errors=True)
        repo = tmp / 'repo'
        repo.mkdir()
        for declared, want, what in (('ladder-set', 1, 'declares the ladder set'),
                                     ('plain-set', 0, 'declares an ordinary set')):
            (repo / 'precedent.json').write_text(json.dumps({'sources': [
                {'name': declared, 'level': 'shared', 'path': f'../{declared}'}]}))
            pc.ROOT = repo
            got = pc._ladder_set_is_brought_not_declared(None)
            cases.append((f'a precedent.json that {what}: {want} finding(s)',
                          len(got) == want, str([str(f) for f in got])[:300]))
    finally:
        pc.ROOT = saved_root
        shutil.rmtree(tmp, ignore_errors=True)
    # A path rule in a set the person brings fires for them through
    # precedent_paths.py, and for nobody else (2026-10-02: the paths channel
    # read the repository's practices/ alone, so checks-follow-the-tier
    # stopped reaching the person who brings it when it moved).
    tmp = pathlib.Path(tempfile.mkdtemp(prefix='precedent-brought-paths-'))
    try:
        repo, ind, lad = tmp / 'repo', tmp / 'precedent-individual', tmp / 'fx-ladder'
        (repo / 'practices').mkdir(parents=True)
        (repo / 'precedent.json').write_text(json.dumps(
            {'format_version': 1, 'visibility': 'private', 'sources': []}))
        (ind / 'practices').mkdir(parents=True)
        (ind / 'precedent-source.json').write_text(json.dumps(
            {'name': 'precedent-individual', 'level': 'individual',
             'brings': [{'name': 'fx-ladder',
                         'repo_url': 'https://example.com/fx-ladder.git'}]}))
        (lad / 'practices').mkdir(parents=True)
        (lad / 'precedent-source.json').write_text(json.dumps(
            {'name': 'fx-ladder', 'level': 'shared', 'provides': ['ladder']}))
        (lad / 'practices' / 'fx-path-rule.md').write_text(
            '---\nslug:        fx-path-rule\ntitle:       "fx"\n'
            'tier:        on-demand\nseverity:    default\n'
            'applies_to:  ["tools/*.py"]\napplies_to_why: "fx"\n'
            'occasion:    null\nindex_clause: "fx clause"\nstatus:      active\n'
            '---\n\n## Rule\n\nThe brought path rule.\n')
        cfg = tmp / 'config.json'
        cfg.write_text(json.dumps({'format_version': 1, 'individual': {
            'name': 'precedent-individual', 'path': str(ind)}}))
        for what, extra, want in (('the person who brings it', {}, True),
                                  ('a person with no such set',
                                   {'PRECEDENT_USER_CONFIG': str(tmp / 'none.json')}, False),
                                  ('the same person, No ladders',
                                   {'PRECEDENT_NO_LADDERS': '1'}, False)):
            e = {k: v for k, v in os.environ.items()
                 if k not in ('PRECEDENT_ASSUME_LADDER', 'PRECEDENT_NO_LADDERS')}
            e['PRECEDENT_USER_CONFIG'] = str(cfg)
            e.update(extra)
            r = subprocess.run([sys.executable, str(ROOT / 'tools' / 'precedent_paths.py'),
                                '--repo', str(repo), 'tools/x.py'],
                               env=e, capture_output=True, text=True, timeout=120)
            got = 'The brought path rule.' in r.stdout
            cases.append((f'a brought path rule {"fires" if want else "is silent"} '
                          f'for {what}', got == want, (r.stdout + r.stderr)[-300:]))
    finally:
        shutil.rmtree(tmp, ignore_errors=True)

    # The staging watch says nothing to a person off the ladder, through the
    # reply gate's own call too (2026-10-02: only its command line asked, so
    # a colleague's reply gate named who had pushed to staging).
    import precedent_beta_watermark_check as pbw
    saved_check, saved_off = pbw.check, pbw._off_ladder
    try:
        pbw.check = lambda root=None, user_config=None, **k: ('alert', [], 'SOMEONE PUSHED')
        pbw._off_ladder = lambda root, user_config=None: True
        quiet = pbw.remind(str(ROOT))
        pbw._off_ladder = lambda root, user_config=None: False
        loud = pbw.remind(str(ROOT))
    finally:
        pbw.check, pbw._off_ladder = saved_check, saved_off
    cases.append(('the staging watch is silent at the reply gate for a person '
                  'off the ladder, and still speaks for one on it',
                  quiet is None and loud == 'SOMEONE PUSHED', f'{quiet!r} {loud!r}'))
    env_off = {k: v for k, v in os.environ.items()
               if k not in ('PRECEDENT_ASSUME_LADDER', 'PRECEDENT_NO_LADDERS')}
    env_off['PRECEDENT_USER_CONFIG'] = str(pathlib.Path(tempfile.gettempdir())
                                           / 'no-such-precedent-config.json')
    r = subprocess.run([sys.executable, '-c',
                        'import sys; sys.path.insert(0, "tools"); '
                        'import precedent_beta_watermark_check as b; '
                        'print(b._off_ladder("."))'],
                       cwd=str(ROOT), env=env_off, capture_output=True, text=True)
    cases.append(('...and a person with no set of their own is off the ladder there',
                  r.stdout.strip() == 'True', (r.stdout + r.stderr)[-200:]))

    # The push check recognises the size-cap warning precedent_check.py
    # prints today (2026-10-02: that wording was made plain and the push
    # check went on looking for the old one, so its closing reminder never
    # fired).
    import precedent_push_check as ppc
    src = (ROOT / 'tools' / 'precedent_check.py').read_text(encoding='utf-8')
    m = re.search(r"WARNING    \{slug\} — (over a size cap\.[^']*)'", src)
    cases.append(("the push check matches precedent_check's size-cap warning "
                  "as it is printed today",
                  bool(m) and any(w in m.group(1) for w in ppc.SIZE_CAP_WARNINGS),
                  m.group(1) if m else 'warning text not found'))

    # A config named outside $HOME is somebody other than the person whose
    # home the bootstrap hook works in, so the self-heal does not run it
    # (2026-10-02: fixtures naming their own config kept putting this
    # machine's individual clone back on its pinned branch). Inside $HOME it
    # still runs.
    import precedent_resolve as _pr_heal
    tmp = pathlib.Path(tempfile.mkdtemp(prefix='precedent-heal-named-'))
    saved = {k: os.environ.get(k) for k in ('CLAUDE_CODE_REMOTE',
                                            'PRECEDENT_USER_CONFIG', 'HOME')}
    try:
        repo, home = tmp / 'repo', tmp / 'home'
        hook = repo / _pr_heal.INDIVIDUAL_BOOTSTRAP_HOOK
        hook.parent.mkdir(parents=True)
        home.mkdir()
        marker = tmp / 'hook-ran'
        hook.write_text(f'#!/bin/bash\ntouch {marker}\n', encoding='utf-8')
        os.environ['CLAUDE_CODE_REMOTE'] = 'true'
        os.environ['HOME'] = str(home)
        os.environ['PRECEDENT_USER_CONFIG'] = str(tmp / 'elsewhere' / 'config.json')
        r1 = _pr_heal._self_heal_individual_source(repo)
        ran1 = marker.exists()
        os.environ['PRECEDENT_USER_CONFIG'] = str(home / 'config.json')
        r2 = _pr_heal._self_heal_individual_source(repo)
        ran2 = marker.exists()
        cases.append(('a config named outside $HOME does not run the bootstrap '
                      'hook; one inside $HOME still does',
                      r1 == 'not-remote' and not ran1 and r2 == 'attempted' and ran2,
                      f'{r1} {ran1} {r2} {ran2}'))
    finally:
        for k, v in saved.items():
            if v is None:
                os.environ.pop(k, None)
            else:
                os.environ[k] = v
        shutil.rmtree(tmp, ignore_errors=True)

    # A rule from a brought set counts as reached through the session file
    # wherever that channel is wired, in a private repository too; with the
    # channel not wired it is reported (2026-10-02: only public repositories
    # counted the channel, so a private one called every brought rule
    # reachable by nothing).
    tmp = pathlib.Path(tempfile.mkdtemp(prefix='precedent-brought-reach-'))
    saved_root, saved_cfg = pc.ROOT, os.environ.get('PRECEDENT_USER_CONFIG')
    try:
        repo, ind, lad = tmp / 'repo', tmp / 'precedent-individual', tmp / 'fx-ladder'
        for d in (repo / 'practices', repo / 'tools', repo / '.claude' / 'hooks',
                  ind / 'practices', lad / 'practices'):
            d.mkdir(parents=True)
        (repo / 'AGENTS.md').write_text('# nothing names it\n')
        (repo / 'precedent.json').write_text(json.dumps(
            {'format_version': 1, 'visibility': 'private', 'sources': []}))
        shutil.copy(ROOT / 'tools' / 'precedent_session_practices.py', repo / 'tools')
        (ind / 'precedent-source.json').write_text(json.dumps(
            {'name': 'precedent-individual', 'level': 'individual',
             'brings': [{'name': 'fx-ladder',
                         'repo_url': 'https://example.com/fx-ladder.git'}]}))
        (lad / 'precedent-source.json').write_text(json.dumps(
            {'name': 'fx-ladder', 'level': 'shared', 'provides': ['ladder']}))
        (lad / 'practices' / 'fx-unrouted.md').write_text(
            '---\nslug:        fx-unrouted\ntitle:       "fx"\n'
            'tier:        on-demand\nseverity:    default\napplies_to:  ["**"]\n'
            'occasion:    null\ngates:       []\nchecked_by:  null\n'
            'status:      active\n---\n\n## Rule\n\nUnrouted.\n')
        cfg = tmp / 'config.json'
        cfg.write_text(json.dumps({'format_version': 1, 'individual': {
            'name': 'precedent-individual', 'path': str(ind)}}))
        os.environ['PRECEDENT_USER_CONFIG'] = str(cfg)
        pc.ROOT = repo
        hook = repo / '.claude' / 'hooks' / 'session-start.sh'
        for wired, want in ((True, False), (False, True)):
            hook.write_text('#!/bin/bash\n' + ('python3 tools/precedent_session_practices.py\n'
                                                if wired else '# no loader here\n'))
            got = any('fx-unrouted' in str(f) for f in (pc._practice_is_reachable(None) or []))
            cases.append((f'in a private repository with the session channel '
                          f'{"wired" if wired else "not wired"}, a brought rule is '
                          f'{"reported unreachable" if want else "reached"}',
                          got == want, f'reported={got}'))
    finally:
        pc.ROOT = saved_root
        if saved_cfg is None:
            os.environ.pop('PRECEDENT_USER_CONFIG', None)
        else:
            os.environ['PRECEDENT_USER_CONFIG'] = saved_cfg
        shutil.rmtree(tmp, ignore_errors=True)

    # A Promote in a repository with only main does nothing and creates no
    # branch (2026-10-02: it announced a move, failed, and left its lock
    # branch on origin).
    tmp = pathlib.Path(tempfile.mkdtemp(prefix='precedent-main-only-'))
    try:
        genv = {k: v for k, v in os.environ.items() if k != 'PRECEDENT_NO_LADDERS'}
        genv.update({'GIT_AUTHOR_NAME': 'x', 'GIT_AUTHOR_EMAIL': 'x@x',
                     'GIT_COMMITTER_NAME': 'x', 'GIT_COMMITTER_EMAIL': 'x@x',
                     'PRECEDENT_ASSUME_LADDER': '1'})
        g = lambda *a, cwd=tmp: subprocess.run(['git', *a], cwd=str(cwd), env=genv,
                                              capture_output=True, text=True)
        g('init', '-q', '--bare', '-b', 'main', 'origin.git')
        g('clone', '-q', str(tmp / 'origin.git'), 'work')
        work = tmp / 'work'
        (work / 'precedent.json').write_text('{"format_version": 1}\n')
        g('add', '-A', cwd=work)
        g('commit', '-qm', 'init', cwd=work)
        g('push', '-q', 'origin', 'HEAD:main', cwd=work)
        r = subprocess.run([sys.executable, str(ROOT / 'tools' / 'precedent_branches.py'),
                            '--promote', '--to', 'staging'], cwd=str(work), env=genv,
                           capture_output=True, text=True, timeout=300)
        heads = g('ls-remote', '--heads', 'origin', cwd=work).stdout
        cases.append(('a Promote in a repository with only main says there is '
                      'nothing to promote and creates no branch',
                      r.returncode == 0 and 'nothing to promote' in r.stdout
                      and heads.count('refs/heads/') == 1,
                      f'rc={r.returncode} {(r.stdout + r.stderr)[-200:]} heads={heads}'))
    finally:
        shutil.rmtree(tmp, ignore_errors=True)

    bad = [(c[0], c[2]) for c in cases if not c[1]]
    check(f'the No ladders session refuses to push, and the two ladder checks '
          f'find what they name ({len(cases)} stated cases)',
          not bad, '; '.join(f"{n} -- {d}" for n, d in bad))


def check_move_mention_fix_reads_list_items_and_names_what_it_cannot_fix():
    """The mention fix judges history a list item at a time, and names a
    current mention it could not rewrite instead of passing over it.

    WHY. Rehearsed 2026-09-28 on a real universal withdrawal: a numbered
    list in a sibling practice had one item saying "(verified 2026-08-28)",
    so the whole list read as history and the two current links to the
    withdrawn practice in a later item were neither fixed nor reported."""
    import shutil, tempfile
    tmp = pathlib.Path(tempfile.mkdtemp(prefix='precedent-move-lists-'))
    env = _move_fixture_env(tmp)
    cases = []
    try:
        boot = str(ROOT / 'tools' / 'precedent_bootstrap_source.py')
        team, indiv = tmp / 'precedent-team-fixture', tmp / 'precedent-individual'
        for args in ((boot, '--level', 'team', '--name', 'precedent-team-fixture',
                      '--dest', str(team), '--approver', 'Fixture Approver:fixture-gh'),
                     (boot, '--level', 'individual', '--name', 'precedent-individual',
                      '--dest', str(indiv))):
            subprocess.run([sys.executable, *args], capture_output=True, text=True, env=env)
        (indiv / 'practices' / 'zz-moves.md').write_text(
            _move_fixture_practice('zz-moves'), encoding='utf-8')
        (indiv / 'NOTES.md').write_text(
            '1. **Drag** -- pointer events, verified 2026-08-28 in a frame.\n'
            '2. **Frontier** -- where it applies\n'
            '   ([zz-moves](practices/zz-moves.md)), the render opens there.\n'
            '3. Oddly phrased: precedent-individual keeps `zz-moves` close.\n',
            encoding='utf-8')
        for repo in (indiv, team):
            subprocess.run(['git', 'init', '-q', str(repo)], capture_output=True)
            subprocess.run(['git', '-C', str(repo), 'add', '-A'], capture_output=True)
        r = subprocess.run([sys.executable, str(ROOT / 'tools' / 'precedent_move.py'),
                            '--slug', 'zz-moves', '--from', 'individual', '--from-path', str(indiv),
                            '--to', 'team', '--to-path', str(team),
                            '--approved-by', 'Fixture Approver'],
                           cwd=str(ROOT), capture_output=True, text=True, env=env)
        notes = (indiv / 'NOTES.md').read_text(encoding='utf-8')
        cases.append(('the move completes', r.returncode == 0, (r.stdout + r.stderr)[-400:]))
        cases.append(('a current link in a list item is fixed although a SIBLING item is dated',
                      '(`zz-moves`), the render opens there.' in notes, notes))
        cases.append(('the dated item itself stays as written',
                      'verified 2026-08-28 in a frame.' in notes, notes))
        cases.append(('a current line naming the old set beside the practice that no rewrite '
                      'recognized is named "could not fix", with its line',
                      'could not fix: precedent-individual/NOTES.md:4' in r.stdout,
                      r.stdout[-600:]))
        cases.append(('and a line that WAS fixed is not also reported as unfixed',
                      'could not fix: precedent-individual/NOTES.md:3' not in r.stdout,
                      r.stdout[-600:]))
    finally:
        shutil.rmtree(tmp, ignore_errors=True)
    failed = [c for c in cases if not c[1]]
    check(f'a move\'s mention fix reads each list item on its own and names what it could '
          f'not fix ({len(cases)} stated cases)', not failed,
          '; '.join(f'{n}: {d}' for n, _ok, d in failed))


def check_bootstrapped_shared_set_carries_current_codeowners():
    """A shared set bootstrapped with an approver gets a CODEOWNERS generated
    from its approvers.json, and verify() reports one that is missing or
    stale in a set carrying the generator.

    WHY. Found 2026-09-28: bootstrap wrote approvers.json and no CODEOWNERS,
    so the approvers a new set declared enforced nothing until somebody
    remembered build_codeowners.py, and verify() called the set complete."""
    import shutil, tempfile
    sys.path.insert(0, str(ROOT / 'tools'))
    import precedent_bootstrap_source as pbs
    tmp = pathlib.Path(tempfile.mkdtemp(prefix='precedent-boot-codeowners-'))
    env = _move_fixture_env(tmp)
    cases = []
    try:
        team = tmp / 'precedent-team-fixture'
        r = subprocess.run([sys.executable, str(ROOT / 'tools' / 'precedent_bootstrap_source.py'),
                            '--level', 'team', '--name', 'precedent-team-fixture',
                            '--dest', str(team), '--approver', 'Fixture Approver:fixture-gh'],
                           capture_output=True, text=True, env=env)
        co = team / 'CODEOWNERS'
        cases.append(('bootstrap writes a CODEOWNERS naming the approver',
                      r.returncode == 0 and co.is_file()
                      and '@fixture-gh' in co.read_text(encoding='utf-8'),
                      (r.stdout + r.stderr)[-400:]))
        # This clone's generator, not the set's vendored copy: bootstrap
        # vendors from committed blobs, so in an uncommitted tree the set's
        # copy can be an older generator than the one that wrote the file.
        chk = subprocess.run([sys.executable, str(ROOT / 'tools' / 'build_codeowners.py'),
                              '--repo', str(team), '--check'],
                             capture_output=True, text=True)
        cases.append(('and build_codeowners --check calls it current',
                      chk.returncode == 0, chk.stdout + chk.stderr))
        cases.append(('verify() raises no CODEOWNERS row on the fresh set',
                      not [m for m in pbs.verify('shared', team) if 'CODEOWNERS' in m], ''))
        co.unlink(missing_ok=True)
        cases.append(('verify() reports a missing CODEOWNERS in a set that carries the generator',
                      any('CODEOWNERS is missing or not current' in m
                          for m in pbs.verify('shared', team)), ''))
    finally:
        shutil.rmtree(tmp, ignore_errors=True)
    failed = [c for c in cases if not c[1]]
    check(f'a bootstrapped shared set carries a current CODEOWNERS and verify() checks it '
          f'({len(cases)} stated cases)', not failed,
          '; '.join(f'{n}: {d}' for n, _ok, d in failed))


def check_codeowners_stamp_hashes_only_the_registry():
    """CODEOWNERS' stamp is a hash of the registry it is rendered from, so a
    key in precedent.json that has nothing to do with it does not make the
    file read stale -- and a file stamped the old way still checks OK.

    WHY. Found 2026-09-28: the stamp hashed the whole precedent.json, and
    every Update Vendors writes `landing_branch` into it, so the template's
    own .github/CODEOWNERS read "hand-edited or stale" with no change to its
    maintainers or owned paths."""
    import importlib, shutil, tempfile
    sys.path.insert(0, str(ROOT / 'tools'))
    import build_codeowners as bco
    importlib.reload(bco)
    tmp = pathlib.Path(tempfile.mkdtemp(prefix='precedent-codeowners-stamp-'))
    cases = []

    def check_rc(root):
        import contextlib, io
        with contextlib.redirect_stdout(io.StringIO()):
            return bco.main(check_only=True, root=root)

    def write(root):
        import contextlib, io
        with contextlib.redirect_stdout(io.StringIO()):
            return bco.main(check_only=False, root=root)

    try:
        proj = tmp / 'project'
        proj.mkdir()
        cfg = {'maintainers': [{'name': 'M', 'github': 'maint'}],
               'owned_paths': [{'path': '/tools/', 'why': 'machinery'}]}
        (proj / 'precedent.json').write_text(json.dumps(cfg), encoding='utf-8')
        write(proj)
        cases.append(('a freshly written project CODEOWNERS checks OK', check_rc(proj) == 0))
        (proj / 'precedent.json').write_text(json.dumps(dict(cfg, landing_branch='pre-staging'),
                                                        indent=4), encoding='utf-8')
        cases.append(('an unrelated key (and reformatting) in precedent.json leaves it current',
                      check_rc(proj) == 0))
        (proj / 'precedent.json').write_text(json.dumps(dict(
            cfg, maintainers=[{'name': 'N', 'github': 'other'}])), encoding='utf-8')
        cases.append(('a change to the maintainers is still detected', check_rc(proj) == 1))

        cset = tmp / 'set'
        cset.mkdir()
        (cset / 'approvers.json').write_text(json.dumps(
            {'_comment': ['one'], 'approvers': [{'name': 'A', 'github': 'a'}]}), encoding='utf-8')
        write(cset)
        (cset / 'approvers.json').write_text(json.dumps(
            {'_comment': ['one', 'two'], 'approvers': [{'name': 'A', 'github': 'a'}]}),
            encoding='utf-8')
        cases.append(('a set\'s comment changing leaves its CODEOWNERS current', check_rc(cset) == 0))
        # The pre-2026-09-28 stamp: whole-file hash, old wording.
        try:
            (cset / 'CODEOWNERS').write_text(bco.render(
                [{'name': 'A', 'github': 'a'}], bco._file_hash(cset / 'approvers.json'),
                legacy=True), encoding='utf-8')
            legacy_ok = check_rc(cset) == 0
        except (AttributeError, TypeError):
            legacy_ok = False
        cases.append(('a CODEOWNERS stamped the old way still checks OK for one release',
                      legacy_ok))
        cases.append(('the template project\'s committed CODEOWNERS checks OK',
                      check_rc(ROOT / 'templates' / 'document-project') == 0))
    finally:
        shutil.rmtree(tmp, ignore_errors=True)
    failed = [n for n, ok in cases if not ok]
    check(f'CODEOWNERS is stamped with a hash of its registry, not the whole file '
          f'({len(cases)} stated cases)', not failed, '; '.join(failed))


def check_as_ci_parts_partition_the_suite():
    """`--as-ci` runs its shards side by side and deals CI's rest shard into
    parts (_as_ci_runs). Whatever the job count, every check must run in
    exactly one process, the heavy shard must be CI's own, and every part
    must still go by PRECEDENT_CHECK_SKIP -- the filter path CI's rest
    shard takes.

    WHY. 2026-09-30: the serial run cost a landing check about sixteen
    minutes on a four-core session. A split that dropped or doubled a check
    would be faster and wrong, and nothing else would notice."""
    cases = []
    names = sorted(n for n, v in globals().items()
                   if n.startswith('check_') and callable(v))

    def covered(env_extra):
        if 'PRECEDENT_CHECK_ONLY' in env_extra:
            return set(env_extra['PRECEDENT_CHECK_ONLY'].split(','))
        return set(names) - set(env_extra.get('PRECEDENT_CHECK_SKIP', '').split(','))

    for jobs in (1, 2, 3, 4, 7):
        runs = _as_ci_runs(jobs, names)
        seen = collections.Counter(n for _l, e in runs for n in covered(e))
        doubled = sorted(n for n, c in seen.items() if c > 1)
        missing = sorted(set(names) - set(seen))
        cases.append((f'{jobs} job(s): every check runs exactly once',
                      not doubled and not missing,
                      f'doubled {doubled[:3]} missing {missing[:3]}'))
        heavy = [e for _l, e in runs if 'PRECEDENT_CHECK_ONLY' in e]
        cases.append((f'{jobs} job(s): the heavy shard is the one CI runs',
                      heavy == [e for _l, e in CI_SHARDS if 'PRECEDENT_CHECK_ONLY' in e],
                      str(heavy)[:200]))
        cases.append((f'{jobs} job(s): every other part runs by SKIP',
                      all('PRECEDENT_CHECK_SKIP' in e for _l, e in runs
                          if 'PRECEDENT_CHECK_ONLY' not in e), ''))
        cases.append((f'{jobs} job(s): {max(jobs, len(CI_SHARDS))} process(es)',
                      len(runs) == max(jobs, len(CI_SHARDS)), str(len(runs))))
    failed = [(n, d) for n, ok, d in cases if not ok]
    check(f'--as-ci parts partition the suite ({len(cases)} stated cases)',
          not failed, '; '.join(f'{n}: {d}' for n, d in failed))


def check_as_ci_says_why_a_shard_failed():
    """`--as-ci` prints, for a failed shard, its FAIL: lines and the tail of
    its stderr -- not just `SHARD FAILED (exit 1)`.

    WHY. Found 2026-09-28: a failed shard said only its exit status, so
    learning which case failed, or what traceback killed the shard, meant
    rerunning four minutes of suite by hand."""
    cases = []
    proc = subprocess.CompletedProcess(
        args=[], returncode=1,
        stdout='PASS: a\nFAIL: the broken case -- why it broke\nPASS: b\n',
        stderr='\n'.join(f'noise {i}' for i in range(30)) + '\nTraceback: boom\n')
    out = '\n'.join(_shard_failure_detail(proc))
    cases.append(('the failing case is named', 'FAIL: the broken case -- why it broke' in out))
    cases.append(('the end of stderr is shown', 'Traceback: boom' in out and 'noise 29' in out))
    lines = out.splitlines()
    cases.append(('only the last 20 lines of stderr',
                  '    noise 10' not in lines and '    noise 11' in lines))
    multi = subprocess.CompletedProcess(
        args=[], returncode=1, stderr='',
        stdout=('PASS: a\nFAIL: the long one -- first line\n'
                'the cause, on line two\nand line three\nPASS: b\n'
                'FAIL: the huge one\n' + '\n'.join(f'row {i}' for i in range(100))
                + '\nN/A:  c -- skipped\n'))
    out = '\n'.join(_shard_failure_detail(multi))
    cases.append(("a multi-line failure keeps every line of its text, and "
                  "nothing of the next verdict's",
                  'the cause, on line two' in out and 'and line three' in out
                  and 'PASS: b' not in out))
    cases.append(('a very long one is cut at 40 lines, and says so',
                  'row 38' in out and 'row 39' not in out
                  and 'cut at 40 lines' in out and 'N/A:' not in out))
    empty = subprocess.CompletedProcess(args=[], returncode=1, stdout='', stderr='')
    cases.append(('a shard that said nothing is said to have said nothing',
                  'no FAIL: line' in '\n'.join(_shard_failure_detail(empty))))
    failed = [n for n, ok in cases if not ok]
    check(f'--as-ci names why a shard failed ({len(cases)} stated cases)',
          not failed, '; '.join(failed))


def check_declared_identity_has_a_passing_state_in_a_shared_repo():
    """`commit-author` and `buenos-aires-dates` have to be able to PASS in
    a repo many people commit to.

    Both computed the expected author from an `identity.json` at the
    consuming repo's root and reported a VIOLATION when it was absent --
    while check_commit_author.py's own comment says a shared consuming repo
    must NOT have one, because an identity.json at a repo's root means
    "this repository is somebody's individual practice source" and putting
    one there pins one person onto everyone committing. So in any shared
    repo those two checks were permanently red with the fix forbidden by
    the same file that demanded it (found 2026-09-10 installing
    precedent-beta-v01 into a real project).

    precedent_resolve.declared_identity() is the engine's answer: look
    where commit-identity.sh already looks, in its order, and raise
    NoDeclaredIdentity -- a check's cue to `raise NotApplicable` -- rather
    than return an absence a caller will read as a violation. These cases
    assert the order and, above all, that "shared repo" is a DISTINCT
    outcome from "wrong author"."""
    import shutil, tempfile
    sys.path.insert(0, str(ROOT / 'tools'))
    import precedent_resolve as pr
    import precedent_identity as pi
    import precedent_vendor_engine as pve

    tmp = pathlib.Path(tempfile.mkdtemp(prefix='precedent-identity-'))
    cases = []

    # WHERE THE RESOLUTION LIVES, which is the half that was wrong first
    # (2026-09-10, the same day it landed). It was born in
    # precedent_resolve.py, which is CONSUMER_ENGINE_FILES-only because a
    # practice SET resolves no catalogue -- so the two checks this whole
    # change exists to fix went from enforcing to SKIPPED inside
    # `precedent-individual` itself, the one repository that most certainly
    # HAS an identity (a root identity.json is what declares one). Identity
    # is about a person; the resolver is about a catalogue, and only the
    # second reason keeps a file out of a set. These cases pin that down so
    # it cannot drift back.
    cases.append(('the resolution lives in precedent_identity.py, which is '
                  'in ENGINE_FILES -- so a practice SET vendors it and its '
                  'own identity checks can enforce rather than skip',
                  'precedent_identity.py' in pve.ENGINE_FILES,
                  str(pve.ENGINE_FILES)))
    cases.append(('and therefore reaches consumers too',
                  'precedent_identity.py' in pve.CONSUMER_ENGINE_FILES,
                  str(pve.CONSUMER_ENGINE_FILES)))
    cases.append(('precedent_resolve.py re-exports both names rather than '
                  'keeping a second implementation, so a consumer that '
                  'already imports them from there keeps working',
                  pr.declared_identity is pi.declared_identity
                  and pr.NoDeclaredIdentity is pi.NoDeclaredIdentity, ''))
    # The one duplication the move required: precedent_identity.py cannot
    # import these FROM the resolver without reintroducing the dependency it
    # exists to break, so it restates them. Assert they stay identical
    # rather than trusting that nobody edits one of the two.
    cases.append(('the user-config constants the two modules each declare '
                  'are identical -- the duplication the move required is '
                  'checked, not trusted',
                  pr.USER_CONFIG_ENV == pi.USER_CONFIG_ENV
                  and pr.DEFAULT_USER_CONFIG == pi.DEFAULT_USER_CONFIG,
                  f'{pr.USER_CONFIG_ENV!r}/{pi.USER_CONFIG_ENV!r} '
                  f'{pr.DEFAULT_USER_CONFIG}/{pi.DEFAULT_USER_CONFIG}'))

    # And the property that actually matters, exercised the way the failure
    # arrived rather than grepped for: stand the module up ALONE, with no
    # precedent_resolve.py anywhere on the path, which is exactly the state
    # a practice set is in. A stray module-scope import would fail here and
    # nowhere else in this file.
    alone = tmp / 'engine-alone'
    alone.mkdir(parents=True)
    shutil.copy2(ROOT / 'tools' / 'precedent_identity.py',
                 alone / 'precedent_identity.py')
    solo = subprocess.run(
        [sys.executable, '-c',
         'import sys, json; sys.path.insert(0, sys.argv[1]); '
         'import precedent_identity as m; '
         'ok = False\n'
         'try:\n'
         '    m.declared_identity(sys.argv[2])\n'
         'except m.NoDeclaredIdentity:\n'
         '    ok = True\n'
         'print(json.dumps({"ok": ok, "resolver_loaded": '
         '"precedent_resolve" in sys.modules}))',
         str(alone), str(tmp)],
        capture_output=True, text=True, timeout=120,
        # OWN every input that can change the answer. An inherited
        # PRECEDENT_COMMIT_EMAIL is step 1 of the resolution order, so a
        # session that exports one -- the individual set's own
        # settings.json does -- would hand this fixture an identity and
        # the case would pass for the wrong reason, proving nothing about
        # where the module lives. Same for the user config and PYTHONPATH.
        env={**{k: v for k, v in os.environ.items()
                if not k.startswith('PRECEDENT_')},
             'PYTHONPATH': '',
             'PRECEDENT_USER_CONFIG': str(tmp / 'no-such-config.json')})
    solo_out = {}
    try:
        solo_out = json.loads(solo.stdout.strip().splitlines()[-1])
    except (ValueError, IndexError):
        pass
    cases.append(('precedent_identity stands up with NO precedent_resolve.py '
                  'on the path at all -- the exact state a practice set is '
                  'in, and the state the old placement failed in',
                  solo.returncode == 0 and solo_out.get('ok') is True
                  and solo_out.get('resolver_loaded') is False,
                  solo.stdout + solo.stderr))

    # A seeded practice set really receives the file. ENGINE_FILES membership
    # is the declaration; this is the delivery.
    seeded = tmp / 'seeded-set' / 'tools'
    seeded.mkdir(parents=True)
    for name in pve.ENGINE_FILES:
        src = ROOT / 'tools' / name
        if src.is_file():
            shutil.copy2(src, seeded / name)
    cases.append(('a practice set seeded from ENGINE_FILES receives '
                  'precedent_identity.py, so its own commit-author and '
                  'buenos-aires-dates checks can import it',
                  (seeded / 'precedent_identity.py').is_file(),
                  str(sorted(f.name for f in seeded.iterdir()))))
    # This asserted `not (seeded / 'precedent_resolve.py').is_file()` until
    # 2026-09-13, when the resolver deliberately moved INTO ENGINE_FILES so a
    # practice set can read the universal catalogue (shape 3,
    # spec/SOURCE_SET_PROSE_GAP.md). The invariant that mattered is NOT
    # membership -- it is that precedent_identity.py stands alone, which the
    # solo case above proves directly by running it with no resolver on the
    # path at all. What is left of the consumer-only boundary is the
    # materializing pair, so that is what this case now asserts: a set
    # materializes nothing and must not be handed the tools that do.
    cases.append(('a seeded practice set does NOT receive '
                  'precedent_materialize.py or precedent_sync_views.py -- '
                  'the consumer-only boundary that survives the resolver '
                  'moving into ENGINE_FILES',
                  not (seeded / 'precedent_materialize.py').is_file()
                  and not (seeded / 'precedent_sync_views.py').is_file(),
                  str(sorted(f.name for f in seeded.iterdir()))))
    cases.append(('and DOES receive precedent_resolve.py and '
                  'precedent_session_practices.py, the pair that puts '
                  "universal's rules in front of a session rooted in a set",
                  (seeded / 'precedent_resolve.py').is_file()
                  and (seeded / 'precedent_session_practices.py').is_file(),
                  str(sorted(f.name for f in seeded.iterdir()))))
    # PRECEDENT_COMMIT_* is step 1 of the order, and this harness's own
    # process may carry it (verify_harness sets identity for its fixtures).
    # Pop it for the cases that are about the other steps, or step 1 answers
    # every one of them and the check passes for the wrong reason.
    saved = {k: os.environ.pop(k) for k in
             ('PRECEDENT_COMMIT_EMAIL', 'PRECEDENT_COMMIT_NAME',
              'PRECEDENT_COMMIT_TZ') if k in os.environ}
    try:
        shared = tmp / 'shared-consumer'
        shared.mkdir()
        empty_cfg = tmp / 'no-individual.json'
        empty_cfg.write_text('{"individual": null}', encoding='utf-8')
        raised = None
        try:
            pr.declared_identity(shared, user_config=empty_cfg)
        except pr.NoDeclaredIdentity as e:
            raised = e
        cases.append(('a SHARED repo with no root identity.json and no '
                      'individual source raises NoDeclaredIdentity -- its own '
                      'outcome, so a check can skip rather than report a '
                      'violation nobody can clear', raised is not None,
                      'returned an identity instead of raising'))
        cases.append(('and the message says why that is the expected state '
                      'rather than a defect',
                      raised is not None and 'not a defect' in str(raised),
                      str(raised)))

        # A repo that IS an individual source: step 2.
        own = tmp / 'individual-source'
        own.mkdir()
        (own / 'identity.json').write_text(json.dumps({
            'name': 'Fixture Person', 'email': 'fixture@example.com',
            'timezone': 'America/Argentina/Buenos_Aires'}), encoding='utf-8')
        got_own = pr.declared_identity(own, user_config=empty_cfg)
        cases.append(('a repo whose own root carries identity.json resolves '
                      'from it -- that is what such a file MEANS',
                      got_own['email'] == 'fixture@example.com'
                      and got_own['timezone'].endswith('Buenos_Aires'),
                      str(got_own)))

        # The override names the person without a zone: the repo's own
        # identity.json supplies it (2026-09-25 -- an environment that kept
        # PRECEDENT_COMMIT_NAME/EMAIL and dropped PRECEDENT_COMMIT_TZ left
        # the individual source reporting "declares no timezone").
        _saved = {k: os.environ.get(k) for k in
                  ('PRECEDENT_COMMIT_EMAIL', 'PRECEDENT_COMMIT_NAME',
                   'PRECEDENT_COMMIT_TZ')}
        try:
            os.environ['PRECEDENT_COMMIT_EMAIL'] = 'fixture@example.com'
            os.environ['PRECEDENT_COMMIT_NAME'] = 'Fixture Person'
            os.environ.pop('PRECEDENT_COMMIT_TZ', None)
            got_env = pr.declared_identity(own, user_config=empty_cfg)
            got_env_shared = pr.declared_identity(shared, user_config=empty_cfg)
        finally:
            for k, v in _saved.items():
                if v is None:
                    os.environ.pop(k, None)
                else:
                    os.environ[k] = v
        cases.append(('an environment override with no zone takes the zone '
                      "from the repo's own identity.json",
                      got_env['timezone'].endswith('Buenos_Aires'), str(got_env)))
        cases.append(('...and in a shared repo, with no identity.json, it has '
                      'none', got_env_shared['timezone'] == '',
                      str(got_env_shared)))

        # A shared repo whose PERSON has an individual source: step 3. This
        # is the case the two checks needed and never had.
        cfg = tmp / 'user-config.json'
        cfg.write_text(json.dumps({'individual': {
            'name': 'precedent-individual', 'path': str(own)}}),
            encoding='utf-8')
        got_shared = pr.declared_identity(shared, user_config=cfg)
        cases.append(('a SHARED repo resolves the identity from the '
                      "INDIVIDUAL SOURCE's root, which is where the practice "
                      'text says it lives and where commit-identity.sh '
                      'already reads it',
                      got_shared['email'] == 'fixture@example.com',
                      str(got_shared)))
        cases.append(('and says where it came from, so a finding can name it',
                      'individual practice source' in got_shared['source'],
                      str(got_shared)))

        # An identity.json that exists but declares no email is not an
        # identity: falling through beats returning a nameless one.
        blank = tmp / 'blank-identity'
        blank.mkdir()
        (blank / 'identity.json').write_text('{"timezone": "UTC"}',
                                             encoding='utf-8')
        blank_raised = False
        try:
            pr.declared_identity(blank, user_config=empty_cfg)
        except pr.NoDeclaredIdentity:
            blank_raised = True
        cases.append(('an identity.json with no email is not an identity',
                      blank_raised, 'it returned one anyway'))
    finally:
        os.environ.update(saved)
        shutil.rmtree(tmp, ignore_errors=True)

    # Step 1 last, with the variable deliberately set, so the pops above are
    # not quietly hiding a broken override path.
    os.environ['PRECEDENT_COMMIT_EMAIL'] = 'override@example.com'
    try:
        override = pr.declared_identity(ROOT)
        cases.append(('an explicit PRECEDENT_COMMIT_EMAIL wins outright',
                      override['email'] == 'override@example.com',
                      str(override)))
    finally:
        os.environ.pop('PRECEDENT_COMMIT_EMAIL', None)
        os.environ.update(saved)

    bad = [(n, d) for n, ok, d in cases if not ok]
    check(f'declared_identity() gives a shared repo a passing state instead '
          f'of a permanent violation ({len(cases)} stated cases)',
          not bad,
          '; '.join(f'{n} -- {d}' for n, d in bad))


def check_relayed_authorization_reader():
    """A relayed authorization is actionable only where the PERSON declared
    it (practice: relayed-authorization), and the declaration has to be
    unforgeable by the thing carrying the relay.

    The failure this came from, 2026-09-14: a session relayed a real
    `Go merge` to a session that could reach the repository, three times,
    and was refused every time -- correctly, since a message asserting an
    approval is indistinguishable from a message inventing one. The fix
    moves the evidence into the person's own identity.json, so these cases
    assert the three outcomes SEPARATELY (a declared yes, a declared no,
    and nobody having been asked are three different states with three
    different remedies) and, above all, that the environment cannot
    manufacture the yes."""
    import shutil, tempfile
    sys.path.insert(0, str(ROOT / 'tools'))
    import precedent_identity as pi

    tmp = pathlib.Path(tempfile.mkdtemp(prefix='precedent-relay-'))
    cases = []
    saved = {k: os.environ.pop(k) for k in
             ('PRECEDENT_COMMIT_EMAIL', 'PRECEDENT_COMMIT_NAME',
              'PRECEDENT_COMMIT_TZ') if k in os.environ}
    try:
        empty_cfg = tmp / 'no-individual.json'
        empty_cfg.write_text('{"individual": null}', encoding='utf-8')

        def _set(name, **extra):
            d = tmp / name
            d.mkdir()
            body = {'name': 'Fixture Person', 'email': 'fixture@example.com'}
            body.update(extra)
            (d / 'identity.json').write_text(json.dumps(body), encoding='utf-8')
            return d

        yes = _set('accepts', relayed_authorization='accepted')
        got = pi.relayed_authorization(yes, user_config=empty_cfg)
        cases.append(('a declared "accepted" licenses acting on a relay',
                      got['accepted'] is True and got['value'] == 'accepted',
                      str(got)))
        cases.append(('and names the file it read, so a reply can say where '
                      'the permission came from',
                      str(yes) in got['source'], str(got)))

        no = _set('refuses', relayed_authorization='refused')
        got_no = pi.relayed_authorization(no, user_config=empty_cfg)
        cases.append(('a declared "refused" does not',
                      got_no['accepted'] is False and got_no['value'] == 'refused',
                      str(got_no)))

        silent = _set('silent')
        got_silent = pi.relayed_authorization(silent, user_config=empty_cfg)
        cases.append(('an ABSENT field is refused, not accepted -- a person '
                      'who never heard of the field agreed to nothing',
                      got_silent['accepted'] is False and got_silent['value'] == '',
                      str(got_silent)))

        odd = _set('odd', relayed_authorization='yes please')
        cases.append(('and so is any other value -- only the exact string '
                      'counts, so a typo fails closed',
                      pi.relayed_authorization(odd, user_config=empty_cfg)['accepted'] is False,
                      ''))

        shared = tmp / 'shared-consumer'
        shared.mkdir()
        raised = None
        try:
            pi.relayed_authorization(shared, user_config=empty_cfg)
        except pi.NoDeclaredIdentity as e:
            raised = e
        cases.append(('a repo resolving no identity at all raises '
                      'NoDeclaredIdentity -- "nobody was asked" is its own '
                      'outcome, distinct from a declared refusal',
                      raised is not None, 'it returned an answer instead'))
        cases.append(('and the message says what to do instead, rather than '
                      'only that it failed',
                      raised is not None and 'stop at the pull request' in str(raised),
                      str(raised)))

        cfg = tmp / 'user-config.json'
        cfg.write_text(json.dumps({'individual': {
            'name': 'fixture-individual', 'path': str(yes)}}), encoding='utf-8')
        cases.append(('a SHARED repo resolves the declaration from the '
                      "person's individual source, which is what makes one "
                      'declaration cover every project they work in',
                      pi.relayed_authorization(shared, user_config=cfg)['accepted'] is True,
                      ''))

        # THE SECURITY CASE. declared_identity() honours PRECEDENT_COMMIT_*;
        # this must not, or the permission is grantable by whatever set the
        # environment rather than by the person.
        os.environ['PRECEDENT_COMMIT_EMAIL'] = 'override@example.com'
        os.environ['PRECEDENT_COMMIT_NAME'] = 'Someone Else'
        try:
            env_raised = False
            try:
                pi.relayed_authorization(shared, user_config=empty_cfg)
            except pi.NoDeclaredIdentity:
                env_raised = True
            cases.append(('PRECEDENT_COMMIT_* cannot manufacture acceptance: '
                          'with the variables set and no identity.json in '
                          'reach, the answer is still "nobody declared this"',
                          env_raised, 'the environment answered for a person'))
            cases.append(('and it cannot flip a declared refusal either',
                          pi.relayed_authorization(no, user_config=empty_cfg)['accepted'] is False,
                          ''))
        finally:
            os.environ.pop('PRECEDENT_COMMIT_EMAIL', None)
            os.environ.pop('PRECEDENT_COMMIT_NAME', None)

        # The CLI is what a receiving session actually runs, so its three
        # exit codes are part of the contract, not an implementation detail.
        for label, home_repo, want_code, want_word in (
                ('accepted -> 0', yes, 0, 'ACCEPTED'),
                ('refused  -> 1', no, 1, 'REFUSED'),
                ('undeclared -> 2', shared, 2, 'UNDECLARED')):
            probe = (
                'import sys, pathlib\n'
                f'sys.path.insert(0, {str(ROOT / "tools")!r})\n'
                'import precedent_identity as pi\n'
                f'pi.relayed_authorization.__module__\n'
                'code = 0\n'
                'try:\n'
                f'    r = pi.relayed_authorization({str(home_repo)!r}, user_config={str(empty_cfg)!r})\n'
                '    code = 0 if r["accepted"] else 1\n'
                '    print("ACCEPTED" if r["accepted"] else "REFUSED")\n'
                'except pi.NoDeclaredIdentity:\n'
                '    code = 2\n'
                '    print("UNDECLARED")\n'
                'sys.exit(code)\n')
            out = subprocess.run([sys.executable, '-c', probe],
                                 capture_output=True, text=True)
            cases.append((f'the reader\'s reported outcome and exit code agree '
                          f'({label})',
                          out.returncode == want_code and want_word in out.stdout,
                          f'rc={out.returncode} out={out.stdout.strip()!r}'))

        cli = subprocess.run([sys.executable, str(ROOT / 'tools' / 'precedent_identity.py'),
                              '--relay'], capture_output=True, text=True)
        cases.append(('`precedent_identity.py --relay` runs in this repo and '
                      'names one of the three outcomes',
                      any(w in cli.stdout for w in ('ACCEPTED', 'REFUSED', 'UNDECLARED')),
                      f'rc={cli.returncode} out={cli.stdout.strip()[:120]!r}'))

        skeleton = (ROOT / 'templates' / 'practice-set-individual'
                    / 'identity.json.template').read_text(encoding='utf-8')
        cases.append(('the individual skeleton ships the field, so a set '
                      'created after this is asked the question instead of '
                      'defaulting silently',
                      '"relayed_authorization"' in skeleton, ''))
        cases.append(('and ships it as refused -- the skeleton never hands '
                      'out a standing yes nobody chose',
                      '"relayed_authorization": "refused"' in skeleton, ''))
    finally:
        os.environ.update(saved)
        shutil.rmtree(tmp, ignore_errors=True)

    bad = [(n, d) for n, ok, d in cases if not ok]
    check(f'a relayed authorization is actionable only where the person '
          f'declared it ({len(cases)} stated cases)',
          not bad,
          '; '.join(f'{n} -- {d}' for n, d in bad))


def check_pretooluse_hook_fires():
    """The path-triggered channel's consumer-repo integration
    (spec/LOADER.md's status table, "not yet wired into a PreToolUse hook...
    that is consumer-repo integration, phase 6 territory") -- the wrapper
    itself (templates/harness/claude-code/hooks/precedent-paths.sh) had no
    harness coverage before this check: a shell script under templates/
    isn't scanned by anything else here (checkable-gets-checked). practice:
    engine-plus-host-shims -- this is the thin host shim's own test, not a
    re-test of tools/precedent_paths.py's matching logic, which
    check_glob_semantics and the rest of this file already cover; every
    case below asserts the wrapper's stdin-parsing, field-name fallback,
    and PreToolUse JSON reshaping, against real practice files rather than
    a fixture catalogue, since the two slugs used
    (code-cites-practice, applies_to tools/**; checkable-gets-checked,
    applies_to practices/** + PRACTICES.md) are stable, narrowly-scoped and
    unlikely to be retired."""
    hook = ROOT / 'templates' / 'harness' / 'claude-code' / 'hooks' / 'precedent-paths.sh'
    if not hook.exists():
        check('PreToolUse hook fires (5 stated cases: Edit file_path, a '
              'no-match path, NotebookEdit notebook_path fallback, '
              'malformed stdin, always exits 0)', False,
              f'{hook} does not exist')
        return

    def run_hook(stdin_text):
        r = subprocess.run(['bash', str(hook)], input=stdin_text,
                           capture_output=True, text=True,
                           env={**os.environ, 'CLAUDE_PROJECT_DIR': str(ROOT)})
        return r.returncode, r.stdout.strip()

    def parsed_context(stdout):
        try:
            obj = json.loads(stdout)
        except json.JSONDecodeError:
            return None
        return obj.get('hookSpecificOutput', {})

    cases = []

    rc, out = run_hook(json.dumps({'tool_name': 'Edit',
                                    'tool_input': {'file_path': 'tools/some_new_thing.py'}}))
    hso = parsed_context(out) or {}
    cases.append(('an Edit on a tools/** path surfaces code-cites-practice\'s '
                  'Rule as additionalContext, never denying the edit',
                  rc == 0 and hso.get('hookEventName') == 'PreToolUse'
                  and 'code-cites-practice' in hso.get('additionalContext', '')))
    # The hook carries CONTEXT and no permission verdict. It used to emit
    # `permissionDecision: "allow"`, which on the reading where that field
    # settles the decision meant every install of this adapter silently
    # auto-approved every Edit/Write/NotebookEdit whose path matched any
    # practice -- which is most of them. Asserted so the field cannot come
    # back as a copy-paste from another hook's example.
    cases.append(('and carries no permissionDecision: a practice loader '
                  'does not decide whether an edit is allowed',
                  'permissionDecision' not in hso))

    rc, out = run_hook(json.dumps({'tool_name': 'Write',
                                    'tool_input': {'file_path': 'random/unrelated/thing.xyz'}}))
    cases.append(('a Write on a path no on-demand practice scopes to prints nothing',
                  rc == 0 and out == ''))

    rc, out = run_hook(json.dumps({'tool_name': 'NotebookEdit',
                                    'tool_input': {'notebook_path': 'PRACTICES.md'}}))
    hso = parsed_context(out) or {}
    cases.append(("a NotebookEdit keyed under notebook_path (not file_path) still "
                  "resolves -- the field-name fallback the public hooks reference "
                  "leaves ambiguous for this tool -- and surfaces "
                  "checkable-gets-checked's Rule",
                  rc == 0 and 'checkable-gets-checked' in hso.get('additionalContext', '')))

    rc, out = run_hook('not json at all')
    cases.append(('malformed stdin does not crash the hook or its shell', rc == 0 and out == ''))

    rc, out = run_hook(json.dumps({'tool_name': 'Bash'}))
    # --- the per-session seen file: the same Rules must not be re-injected
    # on every edit. Measured before this existed: ten practices and ~1,000
    # words of Rule text on EVERY markdown edit, identical every time.
    import tempfile as _tf
    _seen = pathlib.Path(_tf.mkdtemp(prefix='precedent-seen-')) / 'seen.txt'
    _paths = str(ROOT / 'tools' / 'precedent_paths.py')

    def _paths_run(*extra):
        r = subprocess.run([sys.executable, _paths, *extra, 'README.md'],
                           capture_output=True, text=True, cwd=str(ROOT))
        return r.returncode, r.stdout

    rc_a, out_a = _paths_run('--seen-file', str(_seen))
    rc_b, out_b = _paths_run('--seen-file', str(_seen))
    cases.append(('the first match with a --seen-file prints full Rules',
                  rc_a == 0 and len(out_a.split()) > 200))
    cases.append(('the second prints a short reminder instead, naming every '
                  'practice and how to get its full Rule back',
                  rc_b == 0 and len(out_b.split()) < len(out_a.split()) / 3
                  and 'Already loaded this session' in out_b
                  and 'precedent_show.py' in out_b))
    seen_slugs = {l.strip() for l in _seen.read_text().splitlines() if l.strip()}
    cases.append(('every practice shown in full is recorded, so the reminder '
                  'covers exactly what was already sent',
                  seen_slugs and all(f'### {s}' in out_a for s in seen_slugs)))
    r_c = subprocess.run([sys.executable, _paths, '--seen-file', str(_seen),
                          'tools/x.py'], capture_output=True, text=True, cwd=str(ROOT))
    cases.append(("a practice that has NOT been shown yet still arrives in "
                  "full, so the optimization cannot swallow a new match",
                  r_c.returncode == 0 and '### code-cites-practice' in r_c.stdout))
    rc_d, out_d = _paths_run('--seen-file', str(_seen.parent / 'nope' / 'x.txt'))
    cases.append(('an unreadable or missing seen file means "nothing seen '
                  'yet", never an error -- this is a context optimization, '
                  'not a correctness mechanism',
                  rc_d == 0 and len(out_d.split()) > 200))
    import shutil as _sh
    _sh.rmtree(_seen.parent, ignore_errors=True)

    cases.append(('a tool call with no tool_input at all (matcher scopes this out '
                  'in settings.json, but the wrapper itself must not assume that) '
                  'prints nothing', rc == 0 and out == ''))

    bad = [(n, '') for n, ok in cases if not ok]
    check(f'PreToolUse hook fires ({len(cases)} stated cases: Edit file_path, '
          f'a no-match path, NotebookEdit notebook_path fallback, malformed '
          f'stdin, a tool call with no tool_input, no permission verdict, and a '
          f'per-session seen file that stops the same Rules being re-injected '
          f'on every edit without swallowing a new match)',
          not bad, '; '.join(n for n, _ in bad))


def check_freshness_gate_fires():
    """The very deep check's freshness gate, as stated cases against
    throwaway repos (practice: very-deep-check).

    WHY AS FIXTURES RATHER THAN AGAINST THIS TREE. A gate that refuses a
    stale checkout is invisible when the checkout is current: running it
    here proves only that this clone happens to be up to date, which is a
    fact about the clone. The states that matter -- behind, diverged, dirty,
    branch-never-pushed -- have to be built. Both halves are asserted: that
    it refuses what it should, and that it does NOT refuse what it
    shouldn't, since a gate that fires on correct work is worse than none.

    The freshen half carries negative controls deliberately. Fast-forwarding
    a diverged branch deletes commits nobody asked it to delete, and a dirty
    tree left half-merged is worse than a stale one left alone -- so those
    two are asserted to change nothing, not merely to warn."""
    import tempfile
    import very_deep_check as vdc

    _git = fixture_git

    with tempfile.TemporaryDirectory() as tmp:
        tmp = pathlib.Path(tmp)
        upstream, work = tmp / 'upstream', tmp / 'work'
        upstream.mkdir()
        _git(upstream, 'init', '-q', '-b', 'main')
        _git(upstream, 'config', 'user.email', 'harness@example.com')
        _git(upstream, 'config', 'user.name', 'Harness')
        (upstream / 'f.txt').write_text('one\n')
        _git(upstream, 'add', '-A'); _git(upstream, 'commit', '-qm', 'one')
        subprocess.run(['git', 'clone', '-q', f'file://{upstream}', str(work)],
                       capture_output=True, text=True)
        _git(work, 'config', 'user.email', 'harness@example.com')
        _git(work, 'config', 'user.name', 'Harness')

        results = []
        results.append(('current clone passes',
                        vdc.freshness(work)['status'] == 'current'))

        # A repo with no origin at all is not stale -- there is nothing to be
        # behind. Refusing it would fail every fixture repo pass 1 builds.
        solo = tmp / 'solo'; solo.mkdir()
        _git(solo, 'init', '-q', '-b', 'main')
        _git(solo, 'config', 'user.email', 'harness@example.com')
        _git(solo, 'config', 'user.name', 'Harness')
        (solo / 'f.txt').write_text('x\n')
        _git(solo, 'add', '-A'); _git(solo, 'commit', '-qm', 'x')
        results.append(('a repo with no origin is not reported stale',
                        vdc.freshness(solo)['status'] == 'no-remote'))

        # Not a git checkout at all: a repo-local source inside the parent.
        plain = tmp / 'plain'; plain.mkdir()
        results.append(('a non-checkout directory is skipped, not failed',
                        vdc.freshness(plain)['status'] == 'not-a-checkout'))

        # Behind.
        (upstream / 'f.txt').write_text('one\ntwo\n')
        _git(upstream, 'add', '-A'); _git(upstream, 'commit', '-qm', 'two')
        v = vdc.freshness(work)
        results.append(('a clone behind origin is refused',
                        v['status'] == 'behind' and v['behind'] == 1))

        # --freshen on a DIRTY tree must decline and change nothing.
        (work / 'scratch.txt').write_text('uncommitted\n')
        before = _git(work, 'rev-parse', 'HEAD').stdout.strip()
        v_dirty = vdc.freshen(work, vdc.freshness(work, fetch=False))
        after = _git(work, 'rev-parse', 'HEAD').stdout.strip()
        results.append(('--freshen declines a dirty tree and moves nothing',
                        v_dirty['status'] == 'behind' and before == after))
        (work / 'scratch.txt').unlink()

        # --freshen on a clean tree that is behind must actually advance it.
        v_clean = vdc.freshen(work, vdc.freshness(work, fetch=False))
        results.append(('--freshen fast-forwards a clean tree that is behind',
                        v_clean['status'] == 'current'))

        # Diverged: --freshen must refuse, and the local commit must survive.
        (upstream / 'f.txt').write_text('one\ntwo\nthree\n')
        _git(upstream, 'add', '-A'); _git(upstream, 'commit', '-qm', 'three')
        (work / 'local.txt').write_text('mine\n')
        _git(work, 'add', '-A'); _git(work, 'commit', '-qm', 'local only')
        v = vdc.freshness(work)
        mine = _git(work, 'rev-parse', 'HEAD').stdout.strip()
        v2 = vdc.freshen(work, v)
        results.append(('a diverged clone is refused, and --freshen leaves its '
                        'local commit alone',
                        v['status'] == 'diverged' and v2['status'] == 'diverged'
                        and _git(work, 'rev-parse', 'HEAD').stdout.strip() == mine
                        and (work / 'local.txt').exists()))

        # A branch that exists only locally: the network is fine, so the
        # verdict must say so rather than blaming the fetch.
        _git(work, 'checkout', '-q', '-b', 'never-pushed')
        v = vdc.freshness(work)
        results.append(('a local-only branch reports branch-not-on-origin, '
                        'not a fetch failure',
                        v['status'] == 'branch-not-on-origin'))

        failed = [name for name, ok in results if not ok]
        check(f'the very deep check refuses a stale repo ({len(results)} stated '
              f'cases: a current clone, a remoteless repo, a non-checkout, a '
              f'behind clone, --freshen against dirty and clean trees, a '
              f'diverged clone whose commit must survive, and a local-only '
              f'branch)',
              not failed,
              '; '.join(failed) if failed else '')


def check_unmerged_branch_verdicts():
    """The unmerged half of the very deep check's branch sweep (practice:
    very-deep-check).

    The case that carries this check is the rebased branch. `merge-base
    --is-ancestor` reads commit identity, so a branch whose every patch was
    replayed onto the integration branch stays "unmerged" forever while
    carrying no work at all. Reporting that as unlanded is not a cosmetic
    error: it is the finding that teaches a reader to wave the whole list
    through, at which point the genuinely-unlanded branch beside it goes
    with them. So both are asserted here, side by side in one fixture --
    one branch that really carries work, one that only appears to."""
    import tempfile
    import very_deep_check as vdc

    _git = fixture_git

    with tempfile.TemporaryDirectory() as tmp:
        tmp = pathlib.Path(tmp)
        up, work = tmp / 'up', tmp / 'work'
        up.mkdir()
        _git(up, 'init', '-q', '-b', 'main')
        # `up` is a working clone, not a bare one, so git refuses a push to
        # the branch it has checked out. Two fixtures pushed to it anyway and
        # never noticed, because nothing looked at the exit code.
        _git(up, 'config', 'receive.denyCurrentBranch', 'ignore')
        _git(up, 'config', 'user.email', 'harness@example.com')
        _git(up, 'config', 'user.name', 'Harness')
        (up / 'base.txt').write_text('base\n')
        _git(up, 'add', '-A'); _git(up, 'commit', '-qm', 'base')

        # A branch whose one commit is genuinely not on main.
        _git(up, 'checkout', '-q', '-b', 'real-work')
        (up / 'feature.txt').write_text('unlanded\n')
        _git(up, 'add', '-A'); _git(up, 'commit', '-qm', 'unlanded work')

        # A branch whose commit is replayed onto main -- a different commit
        # hash, an identical patch. This is the squash/rebase shape.
        _git(up, 'checkout', '-q', 'main')
        _git(up, 'checkout', '-q', '-b', 'already-landed')
        (up / 'landed.txt').write_text('landed\n')
        _git(up, 'add', '-A'); _git(up, 'commit', '-qm', 'landed work')
        patch = _git(up, 'format-patch', '-1', '--stdout').stdout
        _git(up, 'checkout', '-q', 'main')
        (tmp / 'p.patch').write_text(patch)
        _git(up, 'am', '-q', str(tmp / 'p.patch'))
        # Reword the replayed commit. `git am` preserves the author and the
        # author date, so with the same message, tree and parent it produces
        # a BYTE-IDENTICAL commit whenever both commits land in the same
        # second -- and then the branch really is an ancestor of main and
        # the fixture silently tests nothing. That made this case pass or
        # fail on the clock (observed both ways within one minute). A
        # reworded commit is also the truer shape: a squash-merge rewrites
        # the message.
        _git(up, 'commit', '-q', '--amend', '-m', 'landed work (squashed)')
        _git(up, 'checkout', '-q', 'main')

        subprocess.run(['git', 'clone', '-q', f'file://{up}', str(work)],
                       capture_output=True, text=True)
        scan = vdc.scan_branches(work, 'main')
        rows = {r['name']: r for r in (scan or {}).get('unmerged', [])}

        results = [
            ('both branches are reported as not merged',
             set(rows) == {'real-work', 'already-landed'}),
            ('a branch carrying genuinely unlanded work is counted as such',
             rows.get('real-work', {}).get('unique') == 1
             and 'CARRIES' in (rows.get('real-work', {}).get('verdict') or '')),
            ('a rebased branch is NOT reported as unlanded work',
             rows.get('already-landed', {}).get('unique') == 0
             and 'ALREADY LANDED' in (rows.get('already-landed', {}).get('verdict') or '')),
            ('every unmerged branch carries a verdict, never none',
             all(r.get('verdict') for r in rows.values())),
            ('each row carries the evidence the verdict rests on',
             all(r.get('ahead') is not None and r.get('last')
                 for r in rows.values())),
        ]
        failed = [name for name, ok in results if not ok]
        check(f'the very deep check tells unlanded work from a rebased branch '
              f'({len(results)} stated cases, the rebased one being the '
              f'controlling case)',
              not failed, '; '.join(failed) if failed else '')



def check_moved_claims_says_when_it_could_not_read_the_tree():
    """`_moved_claims` returns UNKNOWN, not "clean", when its own read fails
    (practices: checks-plant-their-state, control-asserts-which-failure).

    THE SHAPE, which is the endgame rehearsal's defect in a second function.
    `_moved_claims` builds a set of every tracked basename and uses it to
    SUPPRESS rows: a target found among them is a real file named without
    its path, not a broken claim. The set came from `git ls-files` with the
    failure coerced to an empty set -- so a failed read did not merely lose
    information, it switched the suppression off, and every
    under-qualified name became a row asserting no such file exists.
    Findings manufactured out of a read that did not happen, which is
    exactly how a `git ls-files` failure in `endgame_merge` made every file
    on the integration branch look silently dropped.

    Both halves. The loud one: the read fails, the answer is None and the
    caller prints CANNOT TELL rather than counting a clean repository. The
    quiet one: against a real tree it still returns a list, because a guard
    that has learned to answer UNKNOWN to everything is not a guard."""
    import very_deep_check as vdc

    root = pathlib.Path(__file__).resolve().parent.parent

    real = vdc._moved_claims(root)

    original = vdc._run_git

    def fail_ls_files(repo, *args, _o=original, **kw):
        if args and args[0] == 'ls-files':
            return (128, '', 'fatal: simulated -- ls-files unreadable')
        return _o(repo, *args, **kw)

    vdc._run_git = fail_ls_files
    try:
        unreadable = vdc._moved_claims(root)
    finally:
        vdc._run_git = original

    results = [
        ('PLANTED, `git ls-files` fails: the answer is UNKNOWN (None)',
         unreadable is None),
        ('...and specifically NOT an empty list, which reads as clean',
         unreadable != []),
        ('the quiet half: a readable tree still answers with a list',
         isinstance(real, list)),
    ]
    failed = [name for name, ok in results if not ok]
    return (not failed,
            (f"{'; '.join(failed)} -- unreadable={unreadable!r}, "
             f"real={type(real).__name__}") if failed else '')

def check_endgame_merge_finds_the_silent_drop():
    """The endgame-merge rehearsal (practice: very-deep-check, pass 4).

    THE CASE THAT CARRIES THIS CHECK is the file that disappears without a
    conflict. A reverted merge on the base branch splits the integration
    branch's files into two classes, and only one of them is visible: a file
    touched again since the merge base conflicts and stops the merge, while
    a file untouched since simply does not arrive -- no conflict, no
    message. The 2026-09-07 rehearsal that missed this checked two files,
    found both present, and concluded the trap did not fire; both happened
    to be in the visible class.

    So a non-zero finding count is NOT what is asserted here. The fixture
    plants one file of each class and this check asserts WHICH path lands in
    WHICH set by name -- a rehearsal that reported the conflicting file and
    stayed silent about the dropped one would satisfy any count-based
    assertion while reproducing the exact miss.

    The clean case is asserted beside it, from the same fixture with the
    revert undone: a check that cannot come back clean is one that will be
    ignored the first time it is inconvenient."""
    import tempfile
    import very_deep_check as vdc

    _git = fixture_git

    with tempfile.TemporaryDirectory() as tmp:
        tmp = pathlib.Path(tmp)
        up, work = tmp / 'up', tmp / 'work'
        up.mkdir()
        _git(up, 'init', '-q', '-b', 'main')
        # `up` is a working clone, not a bare one, so git refuses a push to
        # the branch it has checked out. Two fixtures pushed to it anyway and
        # never noticed, because nothing looked at the exit code.
        _git(up, 'config', 'receive.denyCurrentBranch', 'ignore')
        _git(up, 'config', 'user.email', 'harness@example.com')
        _git(up, 'config', 'user.name', 'Harness')
        (up / 'base.txt').write_text('base\n')
        _git(up, 'add', '-A'); _git(up, 'commit', '-qm', 'base')

        # The integration branch, with the two classes of file on it.
        _git(up, 'checkout', '-q', '-b', 'beta')
        (up / 'keep.txt').write_text('one\n')
        (up / 'drop.txt').write_text('one\n')
        _git(up, 'add', '-A'); _git(up, 'commit', '-qm', 'beta work')

        # The accident: beta merged into main, then reverted. The revert
        # undoes the FILES and leaves the COMMITS in main's log, which is
        # what makes git treat them as already merged afterwards.
        _git(up, 'checkout', '-q', 'main')
        _git(up, 'merge', '--no-ff', '-q', '-m', 'accidental merge', 'beta')
        merge_sha = _git(up, 'rev-parse', 'HEAD').stdout.strip()
        _git(up, 'revert', '-m', '1', '--no-edit', merge_sha)

        # Beta carries on: one of the two files is touched again (so it will
        # conflict), one is not (so it will vanish), plus new work that
        # never existed on main at all.
        _git(up, 'checkout', '-q', 'beta')
        (up / 'keep.txt').write_text('two\n')
        (up / 'later.txt').write_text('new\n')
        _git(up, 'add', '-A'); _git(up, 'commit', '-qm', 'more beta work')
        _git(up, 'checkout', '-q', 'main')

        subprocess.run(['git', 'clone', '-q', f'file://{up}', str(work)],
                       capture_output=True, text=True)

        # THE GIT IDENTITY IS PLANTED, BOTH WAYS, and that is the point of
        # this block. This check used to read whatever identity the machine
        # happened to have: a session container has a global one, a CI
        # runner does not, and `git merge` REFUSES without it -- so the
        # rehearsal did nothing, the index still held only the base branch,
        # and every file on beta came back named as silently dropped. Green
        # here, red in continuous integration for five runs, with the code
        # identical in both (2026-09-22). Neither arm below reads the real
        # machine. practice: checks-plant-their-state.
        def _endgame(identity, **kw):
            saved = {k: os.environ.get(k)
                     for k in ('GIT_CONFIG_GLOBAL', 'GIT_CONFIG_SYSTEM')}
            if not identity:
                os.environ['GIT_CONFIG_GLOBAL'] = os.devnull
                os.environ['GIT_CONFIG_SYSTEM'] = os.devnull
            try:
                return vdc.endgame_merge(work, target='beta', base='main',
                                         **kw) or {}
            finally:
                for k, v in saved.items():
                    if v is None:
                        os.environ.pop(k, None)
                    else:
                        os.environ[k] = v

        r = _endgame(identity=True)
        dropped, conflicts = set(r.get('dropped') or []), set(r.get('conflicts') or [])
        bare = _endgame(identity=False)
        bare_dropped = set(bare.get('dropped') or [])
        bare_conflicts = set(bare.get('conflicts') or [])

        # Same fixture, revert undone: the merge must come back clean.
        _git(up, 'revert', '--no-edit', 'HEAD')   # revert the revert
        _git(work, 'fetch', '-q', 'origin')
        clean = _endgame(identity=True)

        # AND A MERGE THAT GENUINELY CANNOT RUN MUST SAY SO. Planted with a
        # global config the rehearsal cannot satisfy -- signature
        # verification on, against unsigned fixture commits -- which makes
        # `git merge` exit 128 having done nothing, exactly as the missing
        # identity did. Without this case the error path is never executed
        # and the old behaviour (report it as every file dropped) could come
        # back with every check still green.
        blocked_cfg = tmp / 'blocked.gitconfig'
        blocked_cfg.write_text('[merge]\n\tverifySignatures = true\n',
                               encoding='utf-8')
        saved_cfg = os.environ.get('GIT_CONFIG_GLOBAL')
        os.environ['GIT_CONFIG_GLOBAL'] = str(blocked_cfg)
        try:
            blocked = vdc.endgame_merge(work, target='beta', base='main') or {}
        finally:
            if saved_cfg is None:
                os.environ.pop('GIT_CONFIG_GLOBAL', None)
            else:
                os.environ['GIT_CONFIG_GLOBAL'] = saved_cfg

        worktrees = _git(work, 'worktree', 'list').stdout.strip().splitlines()

        # AND A RESULT THAT CANNOT BE READ MUST SAY SO TOO. The merge runs
        # here; what fails is the pair of reads that learn what it did, and
        # each of them used to coerce its own failure to an empty set. An
        # `ls-files` that fails leaves `present` holding only the conflicts,
        # so `expected - present` names almost every file on the integration
        # branch -- the identical fabricated drop list the refusal path used
        # to produce, reached by a different route. Planted by failing each
        # read in turn, because the two are separate `if rc == 0` branches
        # and one being guarded says nothing about the other.
        # practice: checks-plant-their-state.
        unreadable = {}
        for failing in ('diff', 'ls-files'):
            original_run = vdc._run_git

            def fail_one_read(repo, *args, _f=failing, _o=original_run, **kw):
                if args and args[0] == _f:
                    return (128, '', f'fatal: simulated -- {_f} unreadable')
                return _o(repo, *args, **kw)

            vdc._run_git = fail_one_read
            try:
                unreadable[failing] = _endgame(identity=True)
            finally:
                vdc._run_git = original_run

        results = [
            ('the file untouched since the merge base is named as dropped',
             'drop.txt' in dropped),
            ('the file touched since the merge base is a CONFLICT, not a drop',
             'keep.txt' in conflicts and 'keep.txt' not in dropped),
            ('work newer than the merge base arrives cleanly, in neither set',
             'later.txt' not in dropped and 'later.txt' not in conflicts),
            ('the run is reported as carrying findings',
             r.get('status') == 'findings'),
            ('undoing the revert makes the same merge come back clean',
             clean.get('status') == 'clean' and not clean.get('dropped')),
            ('the throwaway worktree is removed, whatever the outcome',
             len(worktrees) == 1),
            ('PLANTED, no global git identity: the same answer, not a merge '
             'that silently did nothing',
             bare_dropped == dropped and bare_conflicts == conflicts
             and bare.get('status') == r.get('status')),
            ('PLANTED, a merge git refuses outright: reported as error, '
             'never as findings',
             blocked.get('status') == 'error'),
            ('...and the note carries git\'s own words rather than a '
             'fabricated drop list',
             'signature' in (blocked.get('note') or '').lower()
             and not blocked.get('dropped')),
            ('PLANTED, the merge ran but `git diff` could not be read: '
             'error and no drop list, never a finding',
             unreadable['diff'].get('status') == 'error'
             and not unreadable['diff'].get('dropped')
             and 'UNKNOWN' in (unreadable['diff'].get('note') or '')),
            ('PLANTED, the merge ran but `git ls-files` could not be read: '
             'the same, since the two reads are guarded separately',
             unreadable['ls-files'].get('status') == 'error'
             and not unreadable['ls-files'].get('dropped')
             and 'UNKNOWN' in (unreadable['ls-files'].get('note') or '')),
        ]
        failed = [name for name, ok in results if not ok]
        check(f'the endgame-merge rehearsal names the silently-dropped path '
              f'({len(results)} stated cases; the drop/conflict split is the '
              f'controlling one)',
              not failed,
              (f"{'; '.join(failed)} -- dropped={sorted(dropped)}, "
               f"conflicts={sorted(conflicts)}") if failed else '')


def check_very_deep_check_never_offers_a_tier_branch_for_deletion():
    """The very deep check never offers pre-staging, staging, main, staging's
    old name or Promote's lock branch for deletion, merged or not.

    WHY. Morgan, 2026-09-28 (strength: decided): "it needs to never never
    offer to delete pre-staging nor staging." Every Promote fast-forwards the
    lower tiers, so right after one the ancestor test calls pre-staging and
    precedent-beta-v01 "merged" -- and the branch sweep protected only the
    declared base and the default branch, so both came back as safe to
    delete, each with a one-click link. staging itself had been deleted from
    a merge page two days earlier.

    Discriminating: a merged feature branch in the same fixture must still
    be listed WITH its link, or a sweep that listed nothing would pass."""
    import tempfile
    import very_deep_check as vdc

    _git = fixture_git
    tiers = ['main', 'staging', 'pre-staging', 'precedent-beta-v01',
             'precedent-promote-lock']
    with tempfile.TemporaryDirectory() as tmp:
        tmp = pathlib.Path(tmp)
        up, work = tmp / 'up', tmp / 'work'
        up.mkdir()
        _git(up, 'init', '-q', '-b', 'main')
        _git(up, 'config', 'user.email', 'harness@example.com')
        _git(up, 'config', 'user.name', 'Harness')
        (up / 'base.txt').write_text('base\n')
        _git(up, 'add', '-A'); _git(up, 'commit', '-qm', 'base')
        # Right after a Promote: every tier at one commit, so the ancestor
        # test calls every one of them "merged" into every other.
        for b in tiers[1:]:
            _git(up, 'branch', b)
        _git(up, 'branch', 'claude/finished-work')
        (up / 'precedent.json').write_text(json.dumps(
            {'format_version': 1, 'base_branch': 'staging'}) + '\n')
        _git(up, 'checkout', '-q', 'staging')
        _git(up, 'add', '-A'); _git(up, 'commit', '-qm', 'declare staging')
        # pre-staging ahead of staging, as it is between Promotes.
        _git(up, 'checkout', '-q', 'pre-staging')
        _git(up, 'merge', '-q', '--ff-only', 'staging')
        (up / 'work.txt').write_text('waiting for a Promote\n')
        _git(up, 'add', '-A'); _git(up, 'commit', '-qm', 'landed work')
        _git(up, 'checkout', '-q', 'main')
        subprocess.run(['git', 'clone', '-q', f'file://{up}', str(work)],
                       capture_output=True, text=True)
        _git(work, 'fetch', '-q', 'origin', '+refs/heads/*:refs/remotes/origin/*')
        vdc._NEVER_DELETABLE_CACHE.clear()
        # Scanned from a checkout on main, so pre-staging is not the
        # checked-out branch the old code happened to exclude.
        scan = vdc.scan_branches(work, exclude=('main',)) or {}
        listed = [r['name'] for k in ('merged', 'merged_elsewhere', 'unmerged')
                  for r in scan.get(k) or []]
        # A GitHub remote now, after the scan's own fetches, so a delete
        # link is minted at all.
        _git(work, 'config', 'remote.origin.url',
             'https://github.com/example/fixture.git')
        vdc._NEVER_DELETABLE_CACHE.clear()
        gh_url = {b: vdc._branch_url(work, b)
                  for b in tiers + ['claude/finished-work']}
        row = {'name': 'stag', 'last': None, 'age_days': None,
               'filter_shows_tier': vdc._tiers_shown_by_filter(work, 'stag')}
        warn = '\n'.join(vdc._delete_row_lines(row, str(work)))
        results = [
            ('no tier branch appears in any list of the sweep',
             not [b for b in tiers if b in listed]),
            ('a finished feature branch in the same fixture IS listed '
             '(discriminating: an empty sweep would pass the case above)',
             'claude/finished-work' in listed),
            ('no delete link is ever minted for a tier branch',
             all(gh_url[b] is None for b in tiers)),
            ('the feature branch still gets its delete link',
             bool(gh_url['claude/finished-work'])),
            ('a filter that would also show a tier row says so on the row',
             '`staging`' in warn and '`pre-staging`' in warn
             and 'never delete' in warn),
        ]
        failed = [name for name, ok in results if not ok]
        check(f'the very deep check never offers a tier branch for deletion '
              f'({len(results)} stated cases)', not failed,
              '; '.join(failed) + f' -- listed {listed}')


def check_very_deep_check_walks_every_tier_pair():
    """The drift scan and the merge rehearsal ask about every tier pair
    origin carries: staging and main INTO pre-staging, and each merge a
    Promote makes (pre-staging into staging, staging into main).

    WHY. Until 2026-09-28 both asked about one pair only, the declared base
    against the default branch -- staging against main -- while work landed
    on pre-staging. A fix pushed straight to main was then invisible to the
    one section built to find it, and the merge that happens every day was
    never rehearsed. Asserted by WHICH commit comes back for WHICH pair, so a
    scan that returned nothing everywhere fails."""
    import tempfile
    import very_deep_check as vdc

    _git = fixture_git
    with tempfile.TemporaryDirectory() as tmp:
        tmp = pathlib.Path(tmp)
        up, work = tmp / 'up', tmp / 'work'
        up.mkdir()
        _git(up, 'init', '-q', '-b', 'main')
        _git(up, 'config', 'user.email', 'harness@example.com')
        _git(up, 'config', 'user.name', 'Harness')
        (up / 'precedent.json').write_text(json.dumps(
            {'format_version': 1, 'base_branch': 'staging'}) + '\n')
        (up / 'base.txt').write_text('base\n')
        _git(up, 'add', '-A'); _git(up, 'commit', '-qm', 'base')
        _git(up, 'branch', 'staging'); _git(up, 'branch', 'pre-staging')
        (up / 'hotfix.txt').write_text('fixed on main\n')
        _git(up, 'add', '-A'); _git(up, 'commit', '-qm', 'hotfix straight to main')
        subprocess.run(['git', 'clone', '-q', f'file://{up}', str(work)],
                       capture_output=True, text=True)
        _git(work, 'fetch', '-q', 'origin', '+refs/heads/*:refs/remotes/origin/*')
        pairs = vdc.tier_pairs(work)
        d = vdc.base_branch_drift(work, 'pre-staging', 'main') or {}
        subjects = [c['subject'] for c in d.get('commits') or []]
        e = vdc.endgame_merge(work, 'pre-staging', 'staging') or {}
        results = [
            ('the drift pairs are staging and main into pre-staging, and main '
             'into staging',
             pairs.get('drift') == [('pre-staging', 'staging'),
                                    ('pre-staging', 'main'),
                                    ('staging', 'main')]),
            ('the rehearsals are the two merges a Promote makes, in order',
             pairs.get('endgame') == [('pre-staging', 'staging'),
                                      ('staging', 'main')]),
            ('the fix pushed straight to main is found missing from pre-staging',
             'hotfix straight to main' in subjects),
            ('the Promote merge is actually rehearsed, not skipped',
             e.get('status') in ('clean', 'findings')),
        ]
        failed = [name for name, ok in results if not ok]
        check(f'the very deep check walks every tier pair ({len(results)} '
              f'stated cases)', not failed,
              '; '.join(failed) + f' -- pairs {pairs}, drift {subjects}, '
              f'endgame {e.get("status")} {e.get("note")}')


def check_base_branch_drift_ignores_carried_work():
    """The base-branch drift scan (practice: very-deep-check, pass 4).

    THE CASE THAT CARRIES THIS CHECK is the change that was CARRIED rather
    than merged. Work reaches a long-lived integration branch by being
    rewritten into that branch's own shape at least as often as by being
    merged, so commit identity says "never arrived" about content that
    landed weeks ago. A scan that listed those would hand the person a list
    mostly made of work already here, and a list that is mostly noise is
    waved through whole -- which is the failure this section exists to
    prevent, not to cause.

    So a non-zero count is not what is asserted. The fixture plants one
    commit of each class on the base branch -- one whose patch also exists
    on the integration branch, one that does not -- and this check asserts
    WHICH subject comes back by name. It also asserts the two shapes that
    must never render as clean: a base branch with nothing new (clean), and
    a repo whose branch IS its base (None -- nothing can drift from
    itself, which is a skip, not a pass)."""
    import tempfile
    import very_deep_check as vdc

    _git = fixture_git

    with tempfile.TemporaryDirectory() as tmp:
        tmp = pathlib.Path(tmp)
        up, work = tmp / 'up', tmp / 'work'
        up.mkdir()
        _git(up, 'init', '-q', '-b', 'main')
        # `up` is a working clone, not a bare one, so git refuses a push to
        # the branch it has checked out. Two fixtures pushed to it anyway and
        # never noticed, because nothing looked at the exit code.
        _git(up, 'config', 'receive.denyCurrentBranch', 'ignore')
        _git(up, 'config', 'user.email', 'harness@example.com')
        _git(up, 'config', 'user.name', 'Harness')
        (up / 'base.txt').write_text('base\n')
        _git(up, 'add', '-A'); _git(up, 'commit', '-qm', 'base')

        # A fix lands on main, and the same patch is carried onto the branch
        # as its own commit -- different sha, identical content.
        (up / 'fix.txt').write_text('fixed\n')
        _git(up, 'add', '-A'); _git(up, 'commit', '-qm', 'carried fix')
        _git(up, 'checkout', '-q', '-b', 'beta', 'HEAD~1')
        (up / 'fix.txt').write_text('fixed\n')
        _git(up, 'add', '-A'); _git(up, 'commit', '-qm', 'the same fix, carried')

        # And one that nobody ever brought across.
        _git(up, 'checkout', '-q', 'main')
        (up / 'stranded.txt').write_text('never carried\n')
        _git(up, 'add', '-A'); _git(up, 'commit', '-qm', 'never carried across')

        subprocess.run(['git', 'clone', '-q', f'file://{up}', str(work)],
                       capture_output=True, text=True)
        _git(work, 'fetch', '-q', 'origin', 'beta:refs/remotes/origin/beta')
        r = vdc.base_branch_drift(work, target='beta', base='main') or {}
        subjects = [c['subject'] for c in (r.get('commits') or [])]

        # Same fixture, with the stranded commit carried across too: the
        # scan must be able to come back clean, or it will be ignored.
        _git(up, 'checkout', '-q', 'beta')
        (up / 'stranded.txt').write_text('never carried\n')
        _git(up, 'add', '-A'); _git(up, 'commit', '-qm', 'carried that one too')
        _git(up, 'checkout', '-q', 'main')
        _git(work, 'fetch', '-q', 'origin', '+refs/heads/*:refs/remotes/origin/*')
        clean = vdc.base_branch_drift(work, target='beta', base='main') or {}

        same = vdc.base_branch_drift(work, target='main', base='main')

        results = [
            ('the commit nobody carried is listed by subject',
             'never carried across' in subjects),
            ('the commit whose patch was CARRIED across is not listed',
             'carried fix' not in subjects),
            ('the run is reported as carrying findings',
             r.get('status') == 'findings'),
            ('the listed row carries the file it touched',
             any('stranded.txt' in (c.get('files') or [])
                 for c in (r.get('commits') or []))),
            ('carrying the last one across makes the scan come back clean',
             clean.get('status') == 'clean' and not clean.get('commits')),
            ('a repo whose branch IS its base is a skip, not a clean pass',
             same is None),
        ]
        failed = [name for name, ok in results if not ok]
        check(f'the base-branch drift scan lists unlanded work and ignores '
              f'carried work ({len(results)} stated cases; the carried/'
              f'stranded split is the controlling one)',
              not failed,
              (f"{'; '.join(failed)} -- subjects={subjects}, "
               f"status={r.get('status')}") if failed else '')


def check_branch_name_follows_the_convention():
    """A session's feature branch is `<prefix><date>-<slug>-<id>`, the id
    being the end of the session's ID (practice: act).

    The controlling case is the session ID: given the harness's
    `cse_<id>`, the name ends in that ID's last five characters, lowercased,
    so the branch leads back to its session. The rest are the fallbacks the
    rule promises -- no ID means random characters and a note saying so, a
    name already on origin gets five more and a note, an origin that cannot
    be asked is said rather than read as "not there" -- and the refusal of a
    slug with no words in it, asserted by its own message."""
    import tempfile
    import precedent_branch_name as pbn

    _git = fixture_git
    results = []
    saved = {k: os.environ.pop(k, None)
             for k in ('CLAUDE_CODE_REMOTE_SESSION_ID', 'CLAUDECODE')}
    try:
        os.environ['CLAUDE_CODE_REMOTE_SESSION_ID'] = 'cse_01SQeHb3tgRrvXtsoviaWpkv'
        name, notes = pbn.build(['Feature', 'branch naming!'], date='2026-10-01',
                                prefix='claude/')
        results.append(('the session ID ends the name, lowercased',
                        name == 'claude/2026-10-01-feature-branch-naming-awpkv'
                        and not notes))

        os.environ.pop('CLAUDE_CODE_REMOTE_SESSION_ID')
        a, notes_a = pbn.build(['x'], date='2026-10-01')
        b, _ = pbn.build(['x'], date='2026-10-01')
        results.append(('no session ID: five random lowercase characters, said',
                        re.fullmatch(r'session/2026-10-01-x-[a-z0-9]{5}', a)
                        is not None and a != b
                        and any('no session ID found' in n for n in notes_a)))

        name, _ = pbn.build(['One two', 'three-four', 'five six SEVEN'],
                            date='2026-10-01', prefix='', tail='abcde')
        results.append(('the slug keeps six words, lowercase',
                        name == '2026-10-01-one-two-three-four-five-six-abcde'))

        try:
            pbn.build(['!!', '--'], tail='abcde')
            results.append(('a slug with no words is refused', False))
        except ValueError as e:
            results.append(('a slug with no words is refused',
                            'no usable words for the slug' in str(e)))

        with tempfile.TemporaryDirectory() as tmp:
            tmp = pathlib.Path(tmp)
            up = tmp / 'up'; up.mkdir()
            _git(up, 'init', '-q', '-b', 'main')
            _git(up, 'config', 'user.email', 'harness@example.com')
            _git(up, 'config', 'user.name', 'Harness')
            (up / 'f.txt').write_text('base\n')
            _git(up, 'add', '-A'); _git(up, 'commit', '-qm', 'base')
            taken = 'claude/2026-10-01-feature-branch-naming-awpkv'
            _git(up, 'branch', taken)
            clone = tmp / 'clone'
            subprocess.run(['git', 'clone', '-q', f'file://{up}', str(clone)],
                           capture_output=True, text=True)
            exists = lambda n: pbn.on_origin(n, clone)
            name, notes = pbn.build(['feature branch naming'], date='2026-10-01',
                                    prefix='claude/', tail='awpkv', exists=exists)
            results.append(('a name already on origin gets five more characters',
                            re.fullmatch(re.escape(taken) + r'-[a-z0-9]{5}', name)
                            is not None
                            and any('already on origin' in n for n in notes)))
            name, notes = pbn.build(['fresh'], date='2026-10-01', prefix='claude/',
                                    tail='awpkv', exists=exists)
            results.append(('a free name is left as it is (negative control)',
                            name == 'claude/2026-10-01-fresh-awpkv' and not notes))

            _git(clone, 'remote', 'set-url', 'origin', str(tmp / 'nowhere'))
            name, notes = pbn.build(['fresh'], date='2026-10-01', prefix='claude/',
                                    tail='awpkv',
                                    exists=lambda n: pbn.on_origin(n, clone))
            results.append(('an origin that cannot be asked is said, not read as free',
                            name == 'claude/2026-10-01-fresh-awpkv'
                            and any('could not ask origin' in n for n in notes)))
    finally:
        for k, v in saved.items():
            if v is None:
                os.environ.pop(k, None)
            else:
                os.environ[k] = v

    failed = [n for n, ok in results if not ok]
    check(f'a feature branch is named <date>-<slug>-<id>, the id from the '
          f'session ID, with the stated fallbacks ({len(results)} cases, the '
          f'session ID the controlling one)',
          not failed, '; '.join(failed) if failed else '')


def check_branch_scan_sees_every_branch():
    """The branch sweep must enumerate what ORIGIN has, not what this clone
    happened to fetch (practice: very-deep-check).

    THE CASE THAT CARRIES THIS CHECK is the single-branch clone, which is
    not an edge case: it is what the harness hands every remote session
    (AGENTS.md's add_repo entry), and the freshness gate above fetches only
    the ONE branch it compares. `scan_branches` reads `refs/remotes/origin`,
    so on such a clone it enumerated two refs on a repo with forty and
    reported "(none)" -- which reads as a clean sweep, not as a scan that
    never ran. That is the same empty-result-reads-as-pass failure AGENTS.md
    records for the `scope: 'tree'` checks, and it costs more here: the
    sweep IS pass 4's branch bullet, so a false all-clear silently ends the
    only step that would have found unlanded work.

    Both halves are asserted. The first is the fix: a narrow clone must
    still see every branch. The second is the negative control that keeps
    the fix honest -- when origin genuinely cannot be reached, the scan must
    say it could not tell, NOT fall back to the empty lists that started
    this. A repair that turns one silent wrong answer into another is not a
    repair."""
    import tempfile
    import very_deep_check as vdc

    _git = fixture_git

    with tempfile.TemporaryDirectory() as tmp:
        tmp = pathlib.Path(tmp)
        up = tmp / 'up'; up.mkdir()
        _git(up, 'init', '-q', '-b', 'main')
        # `up` is a working clone, not a bare one, so git refuses a push to
        # the branch it has checked out. Two fixtures pushed to it anyway and
        # never noticed, because nothing looked at the exit code.
        _git(up, 'config', 'receive.denyCurrentBranch', 'ignore')
        _git(up, 'config', 'user.email', 'harness@example.com')
        _git(up, 'config', 'user.name', 'Harness')
        (up / 'f.txt').write_text('base\n')
        _git(up, 'add', '-A'); _git(up, 'commit', '-qm', 'base')
        for b in ('landed', 'open-one', 'open-two'):
            _git(up, 'checkout', '-q', '-b', b)
            (up / f'{b}.txt').write_text(b + '\n')
            _git(up, 'add', '-A'); _git(up, 'commit', '-qm', b)
        _git(up, 'checkout', '-q', 'main')
        _git(up, 'merge', '-q', '--no-ff', 'landed', '-m', 'merge landed')

        # Exactly what the harness produces: one branch, one refspec.
        narrow = tmp / 'narrow'
        subprocess.run(['git', 'clone', '-q', '--single-branch', '--branch',
                        'main', f'file://{up}', str(narrow)],
                       capture_output=True, text=True)
        refs_before = len([r for r in _git(
            narrow, 'for-each-ref', '--format=%(refname:short)',
            'refs/remotes/origin').stdout.splitlines() if r])

        scan = vdc.scan_branches(narrow, 'main') or {}
        merged = {r['name'] for r in (scan.get('merged') or [])}
        unmerged = {r['name'] for r in (scan.get('unmerged') or [])}

        results = [
            ('the fixture really is a narrow clone (else this proves nothing)',
             refs_before <= 2),
            ('a merged branch on origin is found even though the clone never '
             'fetched it', 'landed' in merged),
            ('both unmerged branches on origin are found',
             {'open-one', 'open-two'} <= unmerged),
            ('the scan reports itself complete when it reached origin',
             not scan.get('unfetched') and not scan.get('unreachable')),
        ]

        # NEGATIVE CONTROL: origin unreachable. Empty lists are now a lie, so
        # the scan must mark itself incomplete rather than report them bare.
        dark = tmp / 'dark'
        subprocess.run(['git', 'clone', '-q', '--single-branch', '--branch',
                        'main', f'file://{up}', str(dark)],
                       capture_output=True, text=True)
        _git(dark, 'remote', 'set-url', 'origin', 'file:///nonexistent/gone.git')
        d = vdc.scan_branches(dark, 'main') or {}
        results.append(
            ('an unreachable origin is reported as "cannot tell", never as an '
             'empty (clean) sweep',
             not d.get('merged') and not d.get('unmerged')
             and bool(d.get('unreachable'))))

        failed = [name for name, ok in results if not ok]
        check(f'the very deep check\'s branch sweep sees every branch origin '
              f'has, not only what this clone fetched ({len(results)} stated '
              f'cases, the single-branch clone being the controlling case and '
              f'an unreachable origin the negative control)',
              not failed, '; '.join(failed) if failed else '')


def check_public_tree_bakes_in_no_owner_account():
    """No EXECUTABLE tracked file in a `visibility: public` repo carries a
    private owner's account (practice: scrub-gate, source-naming).

    THE INCIDENT (2026-09-10). INSTALL.md section 8 states that no tracked
    file names the account owning the private practice sets -- that is the
    entire reason PRECEDENT_SOURCE_BASE_URL is an environment variable. It
    was true of the three shared sets and false of the individual one: this
    repo's tracked `.claude/hooks/precedent-individual-bootstrap.sh` carried
    a full `https://github.com/<account>/precedent-individual`, on a public
    branch, five lines below its own comment saying a public consumer should
    bake in no URL. The leak gate could not catch it -- the repo-reference
    allowlist that exists for exactly this is inert until an owner is
    declared private-by-default, and it prints that on every run and passes.

    SCOPED TO CODE, DELIBERATELY, and this is the whole judgment in the
    check. The same account appears ~99 more times in this repo's prose --
    TODO entries, spec documents, decision records -- and those are the
    project's own history, where naming which repository an incident
    happened in IS the value. Scrubbing them buys nothing (the account is
    already published, and a private repo answers 404 to a stranger
    regardless) and costs the record its legibility. What a check can
    usefully hold is the narrower line: a file that RUNS must not hard-code
    an account, because that is the copy every adopting repo instantiates
    and republishes as its own.
    """
    import json as _json

    PLACEHOLDER_ACCOUNTS = {'example', 'acct', 'owner', 'your-account',
                            'your-github-account', 'octocat', 'user'}

    try:
        cfg = _json.loads((ROOT / 'precedent.json').read_text(encoding='utf-8'))
    except Exception:
        cfg = {}
    if (cfg.get('visibility') or 'public').lower() != 'public':
        check('a public repo bakes no owner account into a file that runs',
              True, '', skipped='this repo does not declare visibility: public')
        return

    declared = set()
    for src in cfg.get('sources', []) or []:
        n = str(src.get('name') or '')
        if n:
            declared.add(n)
    declared.add('precedent-individual')

    # Any https://<host>/<account>/<a declared set name> in an executable
    # tracked file. Built from the DECLARED names rather than a literal
    # account, so the check itself names nobody and keeps working if the
    # account changes.
    pat = re.compile(r'https?://[^/\s"\']+/([A-Za-z0-9_.-]+)/(' +
                     '|'.join(re.escape(n) for n in sorted(declared)) + r')\b')
    offenders = []
    r = subprocess.run(['git', '-C', str(ROOT), 'ls-files'],
                       capture_output=True, text=True)
    for rel in r.stdout.splitlines():
        if not rel:
            continue
        if not (rel.endswith('.sh') or rel.endswith('.py')
                or rel.endswith('.sh.template') or rel.endswith('.yml')):
            continue
        f = ROOT / rel
        try:
            text = f.read_text(encoding='utf-8')
        except Exception:
            continue
        for line_no, line in enumerate(text.splitlines(), 1):
            stripped = line.lstrip()
            # A comment naming the shape is documentation, not a baked-in
            # value; what matters is a line that ASSIGNS or executes one.
            if stripped.startswith('#'):
                continue
            m = pat.search(line)
            # `example` and friends are the reserved placeholder accounts --
            # a fixture URL is the check's own first false positive, found
            # on its first run. Keep the list SHORT and literal: a broad
            # "looks like a placeholder" rule is how a real account that
            # happens to read like one walks straight through.
            if m and m.group(1).lower() in PLACEHOLDER_ACCOUNTS:
                continue
            if m and '{{' not in m.group(0):
                offenders.append(f'{rel}:{line_no}: names an account before '
                                 f'{m.group(2)}')

    check(f'a public repo bakes no owner account into a file that runs '
          f'({len(declared)} declared set name(s) checked across every '
          f'tracked .sh/.py/.yml)',
          not offenders,
          '; '.join(offenders[:5]) if offenders else '')


def check_very_deep_check_bootstrap_drift():
    """very_deep_check's BOOTSTRAP DRIFT section compares what the generator
    writes TODAY against a set that already exists (practice:
    very-deep-check, pass 1).

    WHY A FIXTURE RATHER THAN A GLANCE. The two checks that look like this
    one -- bootstrap_source.verify() and _template_freshness() -- both ask
    which files exist, and a drift check that silently compared nothing
    would read exactly like a clean one. So every case below asserts the
    MESSAGE, not the exit status (practice: control-asserts-which-failure):
    a hand-edit and an older vendoring differ only in the remedy printed,
    and getting that backwards sends somebody to refresh over their own
    work.

    The COLLAPSE is asserted too, and it is not cosmetic. The first real run
    (2026-09-11, four live sets) printed 60 lines carrying about six facts,
    because a set vendored at an older commit differs in every engine file
    at once. A check that long is a check nobody reads, so one older
    vendoring prints as one row -- and the fixture pins that it stays one
    row while a genuine per-file finding still gets its own.

    Each case bootstraps its own set (practice: fixture-owns-its-state): the
    states are mutually exclusive, so sharing one directory across them
    would make every case depend on the order of the ones before it."""
    # practice: slow-steps-report-and-cache -- this fixture is one of the
    # harness's slowest (~22s of a ~250s run, measured), rebuilding and
    # diffing real vendored sets to test very_deep_check.py's own drift
    # logic. Change-scoped like check_machine_readable_files_parse, on the
    # same reasoning: this gates a push and runs constantly, so it only
    # needs to ask "did THIS push break bootstrap-drift detection", not
    # "is bootstrap-drift detection healthy in general" -- the latter is
    # very_deep_check.py's own on-demand job. See _changed_touches()'s
    # docstring for the residual gap this narrower scope accepts.
    name = 'very_deep_check reports bootstrap drift against a real set'
    touched, scope = _changed_touches('tools/very_deep_check.py',
                                       'tools/precedent_bootstrap_source.py')
    if not touched:
        not_applicable(name, f'neither tools/very_deep_check.py nor '
                             f'tools/precedent_bootstrap_source.py changed '
                             f'({scope})')
        return
    import hashlib, shutil, tempfile
    import very_deep_check as vdc

    tmp = pathlib.Path(tempfile.mkdtemp(prefix='precedent-drift-harness-'))
    cases = []

    def fresh(tag):
        dest = tmp / tag
        subprocess.run([sys.executable, str(ROOT / 'tools' / 'precedent_bootstrap_source.py'),
                        '--level', 'individual', '--name', 'precedent-individual',
                        '--dest', str(dest)], capture_output=True, text=True)
        return dest, [{'level': 'individual', 'name': 'precedent-individual',
                       'path': str(dest)}]

    try:
        dest, src = fresh('clean')
        out = vdc._bootstrap_drift(src)
        cases.append(('a set the generator just wrote reports no drift at all',
                      out == [], repr(out)))

        # The harness allows an off-main seed process-wide
        # (PRECEDENT_SEED_OFF_MAIN), which hid this for as long as the
        # section existed: on a branch main lacks, the generator refused and
        # every set read "could not be run" (very deep check, 2026-10-05).
        # The fixture set above was seeded with the allowance; the drift
        # comparison itself must not need it.
        saved_seed = os.environ.pop('PRECEDENT_SEED_OFF_MAIN', None)
        try:
            out_bare = vdc._bootstrap_drift(src)
        finally:
            if saved_seed is not None:
                os.environ['PRECEDENT_SEED_OFF_MAIN'] = saved_seed
        cases.append(('without the harness\'s off-main allowance the '
                      'comparison still runs, whatever branch this is',
                      not any('could not be run' in m for m in out_bare),
                      repr(out_bare)))

        cases.append(('no resolved source reads as a SKIP, in those words, '
                      'never as clean',
                      any('NOT compared' in m and 'skip' in m.lower()
                          for m in vdc._bootstrap_drift([])),
                      repr(vdc._bootstrap_drift([]))))

        # A file the skeleton hands over ("edit this file freely afterward,
        # it is yours") must never be a finding.
        dest, src = fresh('owned')
        readme = dest / 'README.md'
        readme.write_text(readme.read_text(encoding='utf-8') + '\nmine\n', encoding='utf-8')
        out = vdc._bootstrap_drift(src)
        cases.append(('an edited skeleton file is a note, not a FINDING',
                      out and all(m.startswith('note') for m in out)
                      and 'README.md' in out[0], repr(out)))

        # The seeded session-load budgets are measured from the set's
        # rendered session file, which differs between generations, and are
        # the set's own once written: a difference is a note, never a
        # FINDING (2026-09-29, a Promote refused over exactly this).
        dest, src = fresh('budgets')
        budgets = dest / 'tools' / 'session_load_budgets.json'
        budgets.write_text(budgets.read_text(encoding='utf-8').replace(
            'Ceiling is current', 'Ceiling, reviewed by hand, is current'),
            encoding='utf-8')
        out = vdc._bootstrap_drift(src)
        cases.append(('changed session-load budgets are a note, not a FINDING',
                      out and all(m.startswith('note') for m in out)
                      and 'session_load_budgets.json' in ' '.join(out), repr(out)))

        # A vendored engine file edited in place: the remedy is upstream, and
        # refreshing over it would destroy the edit. Named per file, because
        # which file was hand-edited is the whole content of the finding.
        dest, src = fresh('handedit')
        show = dest / 'tools' / 'precedent_show.py'
        show.write_text(show.read_text(encoding='utf-8') + '\n# local tweak\n', encoding='utf-8')
        out = vdc._bootstrap_drift(src)
        cases.append(('a hand-edited engine file is a FINDING that names the '
                      'file and says to move it upstream, not to refresh',
                      any(m.startswith('FINDING') and 'precedent_show.py' in m
                          and 'hand-edited in place' in m for m in out), repr(out)))

        # An engine file missing from a set whose engine is otherwise current
        # is its own news: nothing explains it away.
        dest, src = fresh('missing')
        (dest / 'tools' / 'precedent_time.py').unlink()
        out = vdc._bootstrap_drift(src)
        cases.append(('a missing engine file is named on its own line when the '
                      'engine is otherwise current',
                      any('precedent_time.py' in m and 'does not have it' in m
                          for m in out), repr(out)))

        # The same file recorded in the manifest: a faithful vendoring of an
        # older upstream commit. One fact, one row, whatever the file count --
        # and a file the engine gained since folds into that same row rather
        # than printing as a second, unrelated-looking finding.
        dest, src = fresh('behind')
        show = dest / 'tools' / 'precedent_show.py'
        show.write_text('# an older upstream version\n', encoding='utf-8')
        manifest = dest / 'tools' / 'ENGINE_MANIFEST.json'
        data = json.loads(manifest.read_text(encoding='utf-8'))
        data['sha256']['precedent_show.py'] = hashlib.sha256(show.read_bytes()).hexdigest()
        manifest.write_text(json.dumps(data, indent=2), encoding='utf-8')
        (dest / 'tools' / 'precedent_time.py').unlink()
        out = vdc._bootstrap_drift(src)
        findings = [m for m in out if m.startswith('FINDING')]
        cases.append(('an older vendoring is ONE finding, saying refresh, '
                      'carrying the absent file with it',
                      len(findings) == 1 and 'refresh' in findings[0]
                      and 'OLDER upstream vendoring' in findings[0]
                      and 'precedent_time.py' in findings[0]
                      and 'hand-edited' not in findings[0], repr(out)))

        # A set's generated views are rebuilt from ITS OWN practices, so they
        # differ from an empty set's by construction: they are judged by the
        # set's own views check, never against the generator (2026-10-06,
        # AGENTS.md, MAP.md and GLOSSARY.md reported as drift in every set).
        dest, src = fresh('views')
        prac = next((dest / 'practices').glob('*.md'), None)
        if prac is not None:
            twin = dest / 'practices' / 'zz-own-rule.md'
            twin.write_text(prac.read_text(encoding='utf-8').replace(
                f'slug:        {prac.stem}', 'slug:        zz-own-rule', 1),
                encoding='utf-8')
        subprocess.run([sys.executable, str(dest / 'tools' / 'build_views.py')],
                       cwd=str(dest), capture_output=True, text=True)
        out = vdc._bootstrap_drift(src)
        cases.append(('views rebuilt from the set\'s own practices are not drift',
                      not any(m.startswith('FINDING') and
                              any(v in m for v in ('AGENTS.md', 'MAP.md', 'GLOSSARY.md'))
                              for m in out), repr(out)))
        mp = dest / 'MAP.md'
        mp.write_text(mp.read_text(encoding='utf-8') + '\nhand edit\n', encoding='utf-8')
        out = vdc._bootstrap_drift(src)
        cases.append(('...but a view that is not current with them is a FINDING '
                      'naming the file', any(m.startswith('FINDING') and 'MAP.md' in m
                                             and 'not current' in m for m in out),
                      repr(out)))
        dest, src = fresh('declared')
        ps = dest / 'precedent-source.json'
        data = json.loads(ps.read_text(encoding='utf-8'))
        data['subject'] = 'a subject this set chose for itself'
        ps.write_text(json.dumps(data, indent=2) + '\n', encoding='utf-8')
        out = vdc._bootstrap_drift(src)
        cases.append(('the set\'s own precedent-source.json is a note, never drift',
                      not any(m.startswith('FINDING') and 'precedent-source.json' in m
                              for m in out), repr(out)))
    finally:
        shutil.rmtree(tmp, ignore_errors=True)

    bad = [(c[0], c[2]) for c in cases if not c[1]]
    check(f'very_deep_check reports bootstrap drift against a real set '
          f'({len(cases)} stated cases)',
          not bad,
          '; '.join(f'{n} -- {d[:600]}' for n, d in bad))


def check_very_deep_check_convergent_drift():
    """very_deep_check's CONVERGENT DRIFT section compares the sets against
    EACH OTHER, not each set against the template (practice:
    very-deep-check, pass 1).

    WHY THIS NEEDS A FIXTURE OF ITS OWN. The three checks either side of it
    all measure one set against one template, so a change every set made
    identically reads as healthy in all of them -- which is exactly the
    failure this section exists to catch, and exactly the failure a broken
    version of it would keep producing silently. Every case asserts the
    MESSAGE rather than a count (practice: control-asserts-which-failure),
    because "no set converged" and "nothing was compared" render as the same
    empty list and mean opposite things.

    THE THRESHOLD IS PINNED AT TWO, in both directions: one set changing a
    file is a person living in their set and must NOT be a finding, and two
    sets changing it the same way must be. A check that fired on one set
    would report every set's own README forever.

    THE DIRECTION IS PINNED AS UNKNOWN. Convergence says the sets and the
    generator disagree systematically; it does not say which side is right,
    and the first live run met exactly the ambiguous case (three shared sets
    sharing an OLDER freshness-guard.sh, not a change the template was
    missing). A finding that asserted "the template is wrong" would send
    somebody to copy a stale build upstream.

    Untracked files are pinned as NOT drift -- the first live run reported a
    harness-written `.claude/settings.local.json` in all three shared sets,
    which is container state, not a shape the skeleton is missing."""
    # practice: slow-steps-report-and-cache -- this fixture is one of the
    # harness's slowest (~32s of a ~250s run, measured), bootstrapping two
    # real sets to test very_deep_check.py's own drift logic. Change-scoped
    # like check_machine_readable_files_parse -- see that function's and
    # _changed_touches()'s docstrings for the reasoning and the residual
    # gap this narrower scope accepts.
    name = 'very_deep_check reports convergent drift across sets'
    touched, scope = _changed_touches('tools/very_deep_check.py',
                                       'tools/precedent_bootstrap_source.py')
    if not touched:
        not_applicable(name, f'neither tools/very_deep_check.py nor '
                             f'tools/precedent_bootstrap_source.py changed '
                             f'({scope})')
        return
    import shutil, tempfile
    import very_deep_check as vdc

    tmp = pathlib.Path(tempfile.mkdtemp(prefix='precedent-converge-harness-'))
    cases = []

    def fresh(tag):
        dest = tmp / tag
        subprocess.run([sys.executable, str(ROOT / 'tools' / 'precedent_bootstrap_source.py'),
                        '--level', 'team', '--name', 'precedent-team-' + tag,
                        '--dest', str(dest), '--approver', 'Fixture:fixture'],
                       capture_output=True, text=True)
        subprocess.run(['git', 'init', '-q', str(dest)], capture_output=True)
        subprocess.run(['git', '-C', str(dest), 'add', '-A'], capture_output=True)
        return dest, {'level': 'team', 'name': 'precedent-team-' + tag,
                      'path': str(dest)}

    try:
        a_dir, a = fresh('alpha')
        b_dir, b = fresh('beta')

        collect = {}
        vdc._bootstrap_drift([a, b], collect=collect)
        out = vdc._convergent_drift(collect)
        cases.append(('two sets the generator just wrote converge on nothing',
                      [m for m in out if m.startswith('FINDING')] == [],
                      repr(out)))

        cases.append(('an uncollected run reads as a SKIP, in those words',
                      any('skip' in m.lower() for m in vdc._convergent_drift(None)),
                      repr(vdc._convergent_drift(None))))

        cases.append(('a level with ONE source says so rather than printing '
                      'nothing',
                      any(m.startswith('note') and 'converge' in m
                          for m in vdc._convergent_drift(
                              {('team', 'README.md'): {'solo': frozenset()}})),
                      repr(vdc._convergent_drift(
                          {('team', 'README.md'): {'solo': frozenset()}}))))

        # ONE set changing a file is a person, not a template gap.
        line = 'a distinctive line no skeleton ships anywhere at all'
        with (a_dir / 'README.md').open('a', encoding='utf-8') as fh:
            fh.write('\n' + line + '\n')
        subprocess.run(['git', '-C', str(a_dir), 'add', '-A'], capture_output=True)
        collect = {}
        vdc._bootstrap_drift([a, b], collect=collect)
        out = vdc._convergent_drift(collect)
        cases.append(('ONE set changing a file is never a finding',
                      not [m for m in out if m.startswith('FINDING')],
                      repr(out)))

        # The SECOND set making the same change is.
        with (b_dir / 'README.md').open('a', encoding='utf-8') as fh:
            fh.write('\n' + line + '\n')
        subprocess.run(['git', '-C', str(b_dir), 'add', '-A'], capture_output=True)
        collect = {}
        vdc._bootstrap_drift([a, b], collect=collect)
        out = vdc._convergent_drift(collect)
        findings = [m for m in out if m.startswith('FINDING')]
        cases.append(('TWO sets making the same change is one finding, naming '
                      'the file, quoting the line, and both sets',
                      len(findings) == 1 and 'README.md' in findings[0]
                      and 'alpha' in findings[0] and 'beta' in findings[0]
                      and any(line in m for m in out), repr(out)))
        cases.append(('the finding does NOT assert which side is wrong',
                      bool(findings) and 'readings' in findings[0]
                      and 'OLDER' in findings[0], repr(findings)))

        # A skeleton-owned file is where this had to work: BOOTSTRAP DRIFT
        # downgrades it to a note per set, which is why convergence across
        # sets is the only thing that can see it.
        cases.append(('it fires on a SKELETON-OWNED file, which per-set drift '
                      'reports only as a note',
                      bool(findings) and 'README.md' in findings[0],
                      repr(findings)))

        # Untracked is container state, never drift. The file itself has to
        # be untracked, not merely the edit: an earlier version of this case
        # appended to an already-staged README and asserted the filter had
        # failed, when what it had actually built was a tracked file with an
        # uncommitted change -- which IS drift (practice: fixture-owns-its-
        # state; the fixture inherited a staging state it did not set).
        c_dir, c = fresh('gamma')
        d_dir, d = fresh('delta')
        for _d in (c_dir, d_dir):
            subprocess.run(['git', '-C', str(_d), 'rm', '--cached', '-q',
                            'README.md'], capture_output=True)
            with (_d / 'README.md').open('a', encoding='utf-8') as fh:
                fh.write('\nan untracked convergent line nobody committed\n')
        collect = {}
        vdc._bootstrap_drift([c, d], collect=collect)
        out = vdc._convergent_drift(collect)
        cases.append(('an UNTRACKED shared change is not drift',
                      not any('untracked convergent line' in m for m in out),
                      repr(out)))

        # The dedup ledger (VERY_DEEP_CHECK_DEDUP_LEDGER_PROPOSAL.md,
        # precedent-individual, proposed by Morgan 2026-09-20). Reuses the
        # alpha/beta pair already converged above on README.md's shared
        # line, so DECIDED has a real FINDING to suppress rather than a
        # synthetic one.
        def write_ledger(d, entries):
            (d / 'very-deep-check-decisions.json').write_text(
                json.dumps({'entries': entries}), encoding='utf-8')

        collect = {}
        vdc._bootstrap_drift([a, b], collect=collect)

        out = vdc._convergent_drift(collect, sources=[a, b])
        cases.append(('no ledger present -> ordinary FINDING, unchanged '
                      '(must not regress)',
                      any(m.startswith('FINDING') and 'README.md' in m
                          for m in out)
                      and not any(m.startswith('DECIDED') for m in out),
                      repr(out)))

        decided = {'section': 'CONVERGENT DRIFT', 'key': 'README.md',
                   'verdict': 'intentional-customization', 'note': 'fixture',
                   'decided_by': 'Fixture', 'decided': '2026-09-20'}
        write_ledger(a_dir, [decided])
        write_ledger(b_dir, [decided])
        out = vdc._convergent_drift(collect, sources=[a, b])
        cases.append(('every converged set decided the SAME verdict -> '
                      'DECIDED, not FINDING',
                      any(m.startswith('DECIDED') and 'README.md' in m
                          and 'intentional-customization' in m for m in out)
                      and not any(m.startswith('FINDING') and 'README.md' in m
                                  for m in out),
                      repr(out)))

        write_ledger(b_dir, [])
        out = vdc._convergent_drift(collect, sources=[a, b])
        cases.append(('only ONE of the converged sets decided -> FINDING, '
                      'annotated with the partial verdict',
                      any(m.startswith('FINDING') and 'README.md' in m
                          for m in out)
                      and any('alpha decided intentional-customization' in m
                              for m in out)
                      and any('beta undecided' in m for m in out),
                      repr(out)))

        expired = dict(decided, revisit='2020-01-01')
        write_ledger(a_dir, [expired])
        write_ledger(b_dir, [expired])
        out = vdc._convergent_drift(collect, sources=[a, b])
        cases.append(("a decision whose revisit date has passed expires -> "
                      "FINDING again, not DECIDED",
                      any(m.startswith('FINDING') and 'README.md' in m
                          for m in out)
                      and not any(m.startswith('DECIDED') for m in out),
                      repr(out)))

        write_ledger(a_dir, [{'section': 'CONVERGENT DRIFT',
                              'key': 'a-file-nobody-ships.md',
                              'verdict': 'tracked-elsewhere', 'note': 'fixture',
                              'decided_by': 'Fixture', 'decided': '2026-09-20'}])
        write_ledger(b_dir, [])
        out = vdc._convergent_drift(collect, sources=[a, b])
        cases.append(('a ledger entry naming a file no longer present -> '
                      'ORPHANED LEDGER ENTRY, not silently ignored',
                      any(m.startswith('ORPHANED LEDGER ENTRY')
                          and 'a-file-nobody-ships.md' in m and 'alpha' in m
                          for m in out),
                      repr(out)))

        # Ledger files sit on disk in both fixtures at this point (the
        # orphan case above wrote them). Every existing caller of
        # _convergent_drift() passes no `sources` at all, so this asserts
        # that omitting it ignores those files completely rather than
        # picking them up implicitly.
        out = vdc._convergent_drift(collect)
        cases.append(('sources omitted (every caller before this change) '
                      'ignores ledger files on disk entirely -- ordinary '
                      'FINDING, no DECIDED, no ORPHANED, no ledger line',
                      any(m.startswith('FINDING') and 'README.md' in m
                          for m in out)
                      and not any(m.startswith(('DECIDED', 'ORPHANED'))
                                  or m.strip().startswith('ledger:')
                                  for m in out),
                      repr(out)))
    finally:
        shutil.rmtree(tmp, ignore_errors=True)

    bad = [(c[0], c[2]) for c in cases if not c[1]]
    check(f'very_deep_check reports convergent drift across sets '
          f'({len(cases)} stated cases)',
          not bad,
          '; '.join(f'{n} -- {d[:600]}' for n, d in bad))


def check_very_deep_check_authenticates_its_own_fetches():
    """very_deep_check's network calls carry the credential the environment
    holds (practice: very-deep-check; upstream-fix).

    THE INCIDENT (2026-09-10). In a session where the credential route was
    working exactly as INSTALL.md section 8 describes -- all four private
    sources cloned before the first turn -- the very deep check refused to
    read a line: every source failed its freshness gate with "could not read
    Username for 'https://github.com'". The token was fine. `_run_git`
    shelled out to plain `git` while the credential lived behind a helper
    only precedent_source_bootstrap.py passed, so a source could be cloned
    at session start and then not fetched by the check that reads it.

    The controlling case is the NEGATIVE one: with no token in the
    environment the flags must be absent entirely. A tool that always
    passes a helper offers a credential to whatever transport is
    configured, and would pass a naive "are the flags there" assertion
    while being the worse bug.
    """
    import very_deep_check as vdc
    import tempfile

    real_env = dict(os.environ)
    try:
        os.environ.pop('PRECEDENT_GIT_TOKEN', None)
        vdc._ORIGIN_URL.clear()
        with tempfile.TemporaryDirectory() as tmp:
            repo = pathlib.Path(tmp) / 'r'
            repo.mkdir()
            subprocess.run(['git', '-C', str(repo), 'init', '-q'],
                           capture_output=True, text=True)
            subprocess.run(['git', '-C', str(repo), 'remote', 'add', 'origin',
                            'https://github.com/example/example'],
                           capture_output=True, text=True)

            no_token = vdc._credential_args(repo)

            os.environ['PRECEDENT_GIT_TOKEN'] = 'not-a-real-token'
            vdc._ORIGIN_URL.clear()
            with_token = vdc._credential_args(repo)

            # A file:// remote needs no credential and must never be offered
            # one, whatever the environment holds.
            local = pathlib.Path(tmp) / 'l'
            local.mkdir()
            subprocess.run(['git', '-C', str(local), 'init', '-q'],
                           capture_output=True, text=True)
            subprocess.run(['git', '-C', str(local), 'remote', 'add', 'origin',
                            f'file://{tmp}/upstream'], capture_output=True, text=True)
            vdc._ORIGIN_URL.clear()
            local_args = vdc._credential_args(local)

            results = [
                ('no token in the environment means no credential flags at '
                 'all (the controlling case)', no_token == []),
                ('a token in the environment produces credential flags',
                 bool(with_token)),
                ('the flags clear any helper configured elsewhere first',
                 'credential.helper=' in with_token),
                ('the token VALUE never appears in the argument list',
                 not any('not-a-real-token' in a for a in with_token)),
                ('the helper names the variable instead',
                 any('PRECEDENT_GIT_TOKEN' in a for a in with_token)),
                ('a file:// remote is never offered a credential',
                 local_args == []),
                ('network subcommands are recognised by name, so a fetch '
                 'added later is covered too',
                 {'fetch', 'ls-remote', 'pull'} <= vdc._NETWORK_GIT),
                ('a non-network subcommand is not given credential flags',
                 'log' not in vdc._NETWORK_GIT and 'config' not in vdc._NETWORK_GIT),
            ]
            failed = [name for name, ok in results if not ok]
            check(f'the very deep check authenticates its own fetches '
                  f'({len(results)} stated cases, an empty environment being '
                  f'the negative control)',
                  not failed, '; '.join(failed) if failed else '')
    finally:
        os.environ.clear()
        os.environ.update(real_env)
        vdc._ORIGIN_URL.clear()


def check_branch_sweep_sees_work_landed_on_the_base_branch():
    """A branch merged into the BASE branch, and never into the integration
    branch, is reported as finished work rather than as unlanded
    (practice: very-deep-check, pass 4).

    THE CASE THAT CARRIES THIS CHECK (asked 2026-09-12, by Morgan: "Alex
    likely has branches on main from bestpractice from weeks ago"). A repo
    whose work is pinned to an integration branch has TWO branches work can
    land on, and the sweep tested one. Everything merged into the base
    branch alone therefore reported as `CARRIES n unlanded commit(s)`, with
    a verdict demanding somebody merge or close it -- forever, since nothing
    about it will ever change. That is the failure that ends a list: the
    false rows outnumber the true ones, so the reader stops reading, and the
    genuinely unlanded branch beside them goes unread too.

    Both directions are asserted, because a fix that swept everything into
    the "already landed" bucket would pass a one-sided version of this."""
    import tempfile
    import very_deep_check as vdc

    _git = fixture_git

    with tempfile.TemporaryDirectory() as tmp:
        tmp = pathlib.Path(tmp)
        up, work = tmp / 'up', tmp / 'work'
        up.mkdir()
        _git(up, 'init', '-q', '-b', 'main')
        # `up` is a working clone, not a bare one, so git refuses a push to
        # the branch it has checked out. Two fixtures pushed to it anyway and
        # never noticed, because nothing looked at the exit code.
        _git(up, 'config', 'receive.denyCurrentBranch', 'ignore')
        _git(up, 'config', 'user.email', 'harness@example.com')
        _git(up, 'config', 'user.name', 'Harness')
        (up / 'base.txt').write_text('base\n')
        _git(up, 'add', '-A'); _git(up, 'commit', '-qm', 'base')
        # The integration branch, forked from main and moved on, so that
        # "merged into main" and "merged into the integration branch" are
        # genuinely different questions here.
        _git(up, 'checkout', '-q', '-b', 'beta')
        (up / 'beta.txt').write_text('beta\n')
        _git(up, 'add', '-A'); _git(up, 'commit', '-qm', 'beta work')

        # Landed on main only -- the class this check is about.
        _git(up, 'checkout', '-q', 'main')
        _git(up, 'checkout', '-q', '-b', 'landed-on-main')
        (up / 'old.txt').write_text('old\n')
        _git(up, 'add', '-A'); _git(up, 'commit', '-qm', 'old work')
        _git(up, 'checkout', '-q', 'main')
        _git(up, 'merge', '-q', '--no-ff', '-m', 'merge old work',
             'landed-on-main')

        # Landed nowhere -- the row that must still demand a verdict.
        _git(up, 'checkout', '-q', 'beta')
        _git(up, 'checkout', '-q', '-b', 'really-unlanded')
        (up / 'new.txt').write_text('new\n')
        _git(up, 'add', '-A'); _git(up, 'commit', '-qm', 'genuinely unlanded')
        # Leave the upstream on main before cloning. A clone takes its
        # origin/HEAD from whatever the remote has checked out, and that is
        # what tells the sweep which OTHER branch is protected -- with the
        # upstream sitting on beta, main itself reads as an ordinary branch
        # carrying unlanded work, which is both a wrong fixture and a real
        # shape worth knowing about.
        _git(up, 'checkout', '-q', 'main')

        subprocess.run(['git', 'clone', '-q', f'file://{up}', str(work)],
                       capture_output=True, text=True)
        scan = vdc.scan_branches(work, 'beta') or {}
        elsewhere = {r['name']: r for r in scan.get('merged_elsewhere') or []}
        unmerged = {r['name'] for r in scan.get('unmerged') or []}
        merged = {r['name'] for r in scan.get('merged') or []}

        results = [
            ('a branch merged into the base branch is reported as merged '
             'there', 'landed-on-main' in elsewhere),
            ('and names WHICH branch already carries it',
             elsewhere.get('landed-on-main', {}).get('into') == 'main'),
            ('and is no longer reported as carrying unlanded work',
             'landed-on-main' not in unmerged),
            ('a branch landed on neither still demands a verdict',
             'really-unlanded' in unmerged),
            ('and is not swept into the merged lists',
             'really-unlanded' not in elsewhere
             and 'really-unlanded' not in merged),
            ('every branch row names who last touched it, so a verdict can '
             'be routed rather than skipped',
             all(r.get('author')
                 for r in (list(elsewhere.values())
                           + list(scan.get('unmerged') or [])))),
        ]
        failed = [name for name, ok in results if not ok]
        check(f'the very deep check tells work landed on the base branch from '
              f'work landed nowhere ({len(results)} stated cases)',
              not failed, '; '.join(failed) if failed else '')


def check_session_sweep_reports_the_repo_half():
    """The repo half of the live-session sweep reports what landed recently,
    what is sitting uncommitted, and says plainly that it is a half
    (practice: very-deep-check).

    THE GAP (asked 2026-09-12, by Morgan: "do a sweep of live sessions
    against the repo to see if there's anything recent being missed"). Every
    other part of this check reads the repository against itself, so none of
    them can see a session that ran, decided something and left nothing
    behind -- the loss `repo-is-memory` names and nothing looks for.

    THE CONTROLLING CASE is the window, not the listing. A sweep that
    silently used its own default where a repo declared a window would
    report about a period nobody asked about, and would look exactly like a
    working feature -- the same failure the declared stale threshold has its
    own check for."""
    import tempfile, datetime
    import very_deep_check as vdc

    _git = fixture_git

    with tempfile.TemporaryDirectory() as tmp:
        tmp = pathlib.Path(tmp)
        up, work = tmp / 'up', tmp / 'work'
        up.mkdir()
        _git(up, 'init', '-q', '-b', 'main')
        # `up` is a working clone, not a bare one, so git refuses a push to
        # the branch it has checked out. Two fixtures pushed to it anyway and
        # never noticed, because nothing looked at the exit code.
        _git(up, 'config', 'receive.denyCurrentBranch', 'ignore')
        _git(up, 'config', 'user.email', 'harness@example.com')
        _git(up, 'config', 'user.name', 'Harness')
        (up / 'base.txt').write_text('base\n')
        _git(up, 'add', '-A'); _git(up, 'commit', '-qm', 'base')
        # One commit inside any plausible window, one far outside it. Dates
        # forced through the commit environment: a fixture that reads the
        # clock for the property it is asserting is testing the clock
        # (practice: fixture-owns-its-state).
        for branch, days in (('recent-work', 1), ('ancient-work', 400)):
            when = (datetime.datetime.now(datetime.timezone.utc)
                    - datetime.timedelta(days=days)).strftime('%Y-%m-%dT%H:%M:%S%z')
            _git(up, 'checkout', '-q', 'main')
            _git(up, 'checkout', '-q', '-b', branch)
            (up / f'{branch}.txt').write_text(branch + '\n')
            _git(up, 'add', '-A')
            subprocess.run(['git', '-C', str(up), 'commit', '-qm', branch],
                           capture_output=True, text=True,
                           env={**os.environ,
                                'GIT_AUTHOR_DATE': when,
                                'GIT_COMMITTER_DATE': when,
                                'PRECEDENT_ALLOW_ANY_AUTHOR': '1'})
        _git(up, 'checkout', '-q', 'main')
        subprocess.run(['git', 'clone', '-q', f'file://{up}', str(work)],
                       capture_output=True, text=True)

        act = vdc.recent_activity(work, 14) or {}
        names = {b['name'] for b in act.get('branches', [])}
        subjects = {c['subject'] for c in act.get('commits', [])}
        # Uncommitted work is the same loss one step earlier, and the
        # cheapest thing here to see.
        (work / 'scratch.txt').write_text('never committed\n')
        dirty = vdc.recent_activity(work, 14) or {}
        wide = vdc.recent_activity(work, 500) or {}

        results = [
            ('a branch pushed inside the window is reported',
             'recent-work' in names),
            ('a branch last touched outside it is not',
             'ancient-work' not in names),
            ('the same window governs the commit list',
             'recent-work' in subjects and 'ancient-work' not in subjects),
            ('a wider window reaches further back, so the window is the '
             'input and not a fixed horizon',
             'ancient-work' in {b['name'] for b in wide.get('branches', [])}),
            ('every row names who did it',
             all(b.get('author') for b in act.get('branches', []))),
            ('work sitting in the working tree is counted',
             dirty.get('dirty') == 1),
            ('and a clean tree is reported as clean, not as unknown',
             act.get('dirty') == 0),
        ]
        failed = [name for name, ok in results if not ok]
        check(f'the very deep check reports the repo half of the session '
              f'sweep ({len(results)} stated cases, the window being the '
              f'controlling one)',
              not failed, '; '.join(failed) if failed else '')


def check_merged_branches_carry_a_date_and_a_staleness_verdict():
    """A merged, undeleted branch is reported with the date it last moved
    and whether it is past the declared stale threshold
    (practice: very-deep-check, pass 4).

    THE GAP (asked 2026-09-10, by Morgan, of a real sweep). The merged half
    of the branch sweep was a bare list of names. That list ends in a
    deletion, and a name with no date cannot be acted on: the branch merged
    this morning and the one merged last quarter render identically, so the
    reader either deletes blind or -- what actually happens -- defers the
    whole list again. Measured on this repo the same day: 69 merged
    branches, median age 3 days, oldest 39, and no way to see any of that.

    The threshold is a DECLARED input, so the controlling case here is not
    "does 30 days work" but "does the declared number reach the sweep at
    all" -- a default silently overriding a repo's own value would mark the
    wrong branches and look exactly like a working feature.
    """
    import very_deep_check as vdc
    import tempfile, datetime

    _git = fixture_git

    with tempfile.TemporaryDirectory() as tmp:
        tmp = pathlib.Path(tmp)
        up, work = tmp / 'up', tmp / 'work'
        up.mkdir()
        _git(up, 'init', '-q', '-b', 'main')
        # `up` is a working clone, not a bare one, so git refuses a push to
        # the branch it has checked out. Two fixtures pushed to it anyway and
        # never noticed, because nothing looked at the exit code.
        _git(up, 'config', 'receive.denyCurrentBranch', 'ignore')
        _git(up, 'config', 'user.email', 'harness@example.com')
        _git(up, 'config', 'user.name', 'Harness')
        (up / 'base.txt').write_text('base\n')
        _git(up, 'add', '-A'); _git(up, 'commit', '-qm', 'base')

        # Two merged branches at KNOWN ages, straddling the threshold. The
        # dates are forced through the commit environment rather than taken
        # from the clock, so this fixture owns its own state and cannot pass
        # or fail on when it happens to run (practice: fixture-owns-its-state
        # -- the neighbouring unmerged-verdict check was made to fail on the
        # clock exactly once, which is why this is explicit here).
        for branch, days in (('long-done', 400), ('just-landed', 1)):
            when = (datetime.datetime.now(datetime.timezone.utc)
                    - datetime.timedelta(days=days)).strftime('%Y-%m-%dT%H:%M:%S%z')
            _git(up, 'checkout', '-q', 'main')
            _git(up, 'checkout', '-q', '-b', branch)
            (up / f'{branch}.txt').write_text(branch + '\n')
            _git(up, 'add', '-A')
            subprocess.run(['git', '-C', str(up), 'commit', '-qm', branch],
                           capture_output=True, text=True,
                           env={**os.environ,
                                'GIT_AUTHOR_DATE': when,
                                'GIT_COMMITTER_DATE': when,
                                'PRECEDENT_ALLOW_ANY_AUTHOR': '1'})
            _git(up, 'checkout', '-q', 'main')
            _git(up, 'merge', '-q', '--no-ff', '-m', f'merge {branch}', branch)

        subprocess.run(['git', 'clone', '-q', f'file://{up}', str(work)],
                       capture_output=True, text=True)

        scan = vdc.scan_branches(work, 'main', stale_days=90) or {}
        rows = {r['name']: r for r in (scan.get('merged') or [])}

        results = [
            ('both merged branches are reported as merged',
             set(rows) == {'long-done', 'just-landed'}),
            ('every merged row carries the date it last moved',
             all(r.get('last') and r.get('age_days') is not None
                 for r in rows.values())),
            ('the age is the real one, not the date of the merge or the clone',
             rows.get('long-done', {}).get('age_days', 0) >= 399),
            ('a branch past the threshold is marked stale',
             rows.get('long-done', {}).get('stale') is True),
            ('a branch inside the threshold is NOT marked stale',
             rows.get('just-landed', {}).get('stale') is False),
            ('the scan reports which threshold it applied',
             scan.get('stale_days') == 90),
        ]

        # NEGATIVE CONTROL, and the controlling case: the same fixture at a
        # threshold that puts BOTH branches on the recent side. If the
        # passed-in number were ignored in favour of the default, 'long-done'
        # would still read stale and every assertion above would still pass.
        loose = vdc.scan_branches(work, 'main', stale_days=1000) or {}
        loose_rows = {r['name']: r for r in (loose.get('merged') or [])}
        results.append(
            ('the DECLARED threshold decides, not a default compiled in -- '
             'at 1000 days nothing is stale',
             loose_rows and not any(r.get('stale') for r in loose_rows.values())))

        # And a repo declaring its own value gets it without being asked.
        (work / 'precedent.json').write_text(
            json.dumps({'format_version': 1, 'branch_stale_days': 90}), encoding='utf-8')
        declared = vdc.scan_branches(work, 'main') or {}
        results.append(
            ("a repo's own precedent.json branch_stale_days is read when no "
             "threshold is passed",
             declared.get('stale_days') == 90))

        failed = [name for name, ok in results if not ok]
        check(f'the very deep check dates every merged branch and marks the '
              f'stale ones ({len(results)} stated cases, a threshold that '
              f'makes nothing stale being the negative control)',
              not failed, '; '.join(failed) if failed else '')


def check_branch_report_writes_delete_links_to_a_committable_file():
    """The branch sweep's own write-up lands in a committable file with a
    real, clickable link on every row -- not only in whichever session's
    transcript happened to print it (practice: very-deep-check, pass 4;
    repo-is-memory).

    THE GAP (Morgan, reading a Sunday run: "I don't remember getting that").
    scan_branches() and _branch_url() already compute everything the list
    needs; nothing wrote it anywhere but stdout, which is exactly the run
    that happened and was never seen again. _write_branch_report() is the
    fix, and this proves both halves: the merged-and-stale row carries a
    working delete link, and the unmerged row carries both a branches-page
    link and a compare-view link -- the actual owner/repo slug parsed from
    origin, not a placeholder.
    """
    import very_deep_check as vdc
    import tempfile, datetime

    _git = fixture_git

    with tempfile.TemporaryDirectory() as tmp:
        tmp = pathlib.Path(tmp)
        up, work = tmp / 'up', tmp / 'work'
        up.mkdir()
        _git(up, 'init', '-q', '-b', 'main')
        # `up` is a working clone, not a bare one, so git refuses a push to
        # the branch it has checked out. Two fixtures pushed to it anyway and
        # never noticed, because nothing looked at the exit code.
        _git(up, 'config', 'receive.denyCurrentBranch', 'ignore')
        _git(up, 'config', 'user.email', 'harness@example.com')
        _git(up, 'config', 'user.name', 'Harness')
        (up / 'base.txt').write_text('base\n')
        _git(up, 'add', '-A'); _git(up, 'commit', '-qm', 'base')

        # A branch merged long enough ago to land on the STALE side, so the
        # test exercises the row this feature exists for -- the safest
        # deletions, the ones a bare name never got acted on (see the
        # neighbouring check's own Story).
        when = (datetime.datetime.now(datetime.timezone.utc)
                - datetime.timedelta(days=200)).strftime('%Y-%m-%dT%H:%M:%S%z')
        _git(up, 'checkout', '-q', '-b', 'old-merged')
        (up / 'a.txt').write_text('a\n')
        _git(up, 'add', '-A')
        subprocess.run(['git', '-C', str(up), 'commit', '-qm', 'old work'],
                       capture_output=True, text=True,
                       env={**os.environ, 'GIT_AUTHOR_DATE': when,
                            'GIT_COMMITTER_DATE': when,
                            'PRECEDENT_ALLOW_ANY_AUTHOR': '1'})
        _git(up, 'checkout', '-q', 'main')
        _git(up, 'merge', '-q', '--no-ff', '-m', 'merge old', 'old-merged')

        _git(up, 'checkout', '-q', '-b', 'wip-unmerged')
        (up / 'b.txt').write_text('b\n')
        _git(up, 'add', '-A'); _git(up, 'commit', '-qm', 'unlanded work')
        _git(up, 'checkout', '-q', 'main')

        subprocess.run(['git', 'clone', '-q', f'file://{up}', str(work)],
                       capture_output=True, text=True)
        # A REAL GitHub slug, parsed from origin -- the assertions below
        # check for this exact URL, so a version that hardcoded a link or
        # dropped the parse silently would not pass.
        _git(work, 'remote', 'set-url', 'origin',
             'https://github.com/alex137/fixture-repo.git')

        scan = vdc.scan_branches(work, 'main', stale_days=90) or {}
        out_path = tmp / 'record' / 'stale-branches.md'
        vdc._write_branch_report({'checkout': scan}, out_path, work)
        text = out_path.read_text(encoding='utf-8')

        results = [
            ('the file exists at the path asked for',
             out_path.is_file()),
            ('the merged-and-stale branch is listed',
             'old-merged' in text),
            ('its row carries a real GitHub delete link, not a placeholder',
             'https://github.com/alex137/fixture-repo/branches/all?query=old-merged'
             in text),
            ('the unmerged branch is listed with its verdict',
             'wip-unmerged' in text and 'CARRIES 1 unlanded commit' in text),
            ('the unmerged row carries a compare-view link',
             'https://github.com/alex137/fixture-repo/compare/main...wip-unmerged'
             in text),
            ('the file says plainly that it is generated, and what to do '
             'instead of editing it',
             'generated_by: tools/very_deep_check.py' in text
             and "Don't edit here" in text),
        ]

        # NEGATIVE CONTROL: a non-GitHub origin gets no link at all --
        # _branch_url and _compare_url both return None for it, and a
        # version that silently fell back to a hardcoded or empty link
        # instead of omitting the row's link entirely is what this catches.
        _git(work, 'remote', 'set-url', 'origin', 'https://example.com/x/y.git')
        scan2 = vdc.scan_branches(work, 'main', stale_days=90) or {}
        out2 = tmp / 'record' / 'stale-branches-2.md'
        vdc._write_branch_report({'checkout': scan2}, out2, work)
        text2 = out2.read_text(encoding='utf-8')
        results.append(
            ('a non-GitHub origin gets no delete or compare link at all, '
             'rather than a wrong one',
             'old-merged' in text2 and 'https://' not in text2))

        failed = [name for name, ok in results if not ok]
        check(f'the branch sweep writes a committable report carrying real '
              f'delete and compare links ({len(results)} stated cases, a '
              f'non-GitHub origin producing no link at all being the '
              f'negative control)',
              not failed, '; '.join(failed) if failed else '')


def check_public_consumer_does_not_materialize_private_text():
    """A public consumer repo's TRACKED practices/ tree must not carry a
    private source's practice text (practice: very-deep-check, found by it).

    build_views.py already refuses to render a private source into a public
    repo's loader block, and precedent_materialize.py already refuses to
    mint a private repo's URL into the materialized tree -- but the whole
    practice FILE was copied in regardless, which discloses strictly more
    than the link so carefully withheld. Reproduced on a real fresh install
    built from INSTALL.md section 0: thirteen individual-level practices
    landed in a `visibility: public` consumer's tracked tree, one of them
    carrying a person's name and email address.

    Three properties, because fixing the first alone breaks the others:

    1. No private-level text in a public consumer's tree.
    2. NOTHING ELSE IS LOST. The private sources are dropped and the set
       RE-RESOLVED, not filtered out of a finished result -- a private
       practice can win a slug a publishable source also declares, and
       deleting the winner does not promote the runner-up. Filtering lost
       a universal practice exactly this way.
    3. The two renderers agree. precedent_sync_views.py must pass the same
       `omits_private` build_views.py computes for itself, or the standing
       instruction differs between them and `generated-artifact-provenance`
       reports the file the documented install step just wrote as
       hand-edited -- with no state of the repo able to satisfy it.

    A PRIVATE consumer is the control: nothing may be withheld there."""
    import tempfile, shutil
    import json as _json
    import precedent_sync_views as psv
    import build_views as bv

    def _consumer(tmp, visibility):
        repo = tmp / f'consumer-{visibility}'
        (repo / 'precedent' / 'universal').mkdir(parents=True)
        shutil.copytree(PRACTICES_DIR, repo / 'precedent' / 'universal' / 'practices')
        (repo / 'AGENTS.md').write_text(
            f'# Consumer\n\n{bv.BEGIN_MARKER} -->\n{bv.END_MARKER} -->\n',
            encoding='utf-8')
        (repo / 'precedent.json').write_text(_json.dumps({
            'format_version': 1, 'base_branch': 'main',
            'visibility': visibility,
            'sources': [{'level': 'universal', 'name': 'precedent',
                         'path': 'precedent/universal'}]}), encoding='utf-8')
        return repo

    with tempfile.TemporaryDirectory() as tmp:
        tmp = pathlib.Path(tmp)
        # A stand-in individual source, declared the only way one may be:
        # in a user-level config, never in the repo's own tracked file.
        ind = tmp / 'precedent-individual'
        (ind / 'practices').mkdir(parents=True)
        (ind / 'practices' / 'private-only.md').write_text(
            '---\nslug: private-only\ntitle: A private rule\ntier: on-demand\n'
            'severity: default\napplies_to: ["**"]\noccasion: "x happens"\n'
            'index_clause: "do the private thing"\nstatus: active\n---\n'
            '## Rule\nSECRET-CANARY-VALUE applies.\n\n## Story\nBecause.\n',
            encoding='utf-8')
        user_cfg = tmp / 'user.json'
        user_cfg.write_text(_json.dumps(
            {'format_version': 1,
             'individual': {'name': 'precedent-individual',
                            'path': str(ind)}}),
            encoding='utf-8')

        results = []
        pub = _consumer(tmp, 'public')
        psv.sync(str(pub), user_config=str(user_cfg))
        pub_tree = sorted(f.name for f in (pub / 'practices').glob('*.md'))
        pub_text = '\n'.join(
            f.read_text(encoding='utf-8') for f in (pub / 'practices').glob('*.md'))
        # Every universal practice that is IN FORCE, not every file on
        # disk. A `status: retired` or `deduplicated` practice stays in the
        # tree as its own retirement record and is deliberately not
        # materialized -- precedent_materialize.py resolves the in-force
        # set, it does not copy a directory. Comparing against the raw glob
        # was correct only while the catalogue happened to hold no retired
        # practice; it failed the moment one did (2026-09-07,
        # merge-authorization-keyword), reporting a real, intended omission
        # as private-text filtering. (practice: verify-decomposition -- the
        # count was right, what it counted was not.)
        # Same reasoning as the status exclusion above, one axis over:
        # scope: engine-dev is a SECOND, deliberate reason a practice never
        # materializes into a consumer, orthogonal to status. Added when
        # that field landed -- this assertion would otherwise fail the
        # moment any practice declared it, exactly as it did for the first
        # retired/deduplicated practice.
        universal = sorted(
            f.name for f in PRACTICES_DIR.glob('*.md')
            if not re.search(r'^status:\s*(retired|deduplicated)\s*$',
                             f.read_text(encoding='utf-8'), re.M)
            and not re.search(r'^scope:\s*engine-dev\s*$',
                              f.read_text(encoding='utf-8'), re.M))

        results.append(('a public consumer materializes no private practice file',
                        'private-only.md' not in pub_tree))
        results.append(('nor any of its text',
                        'SECRET-CANARY-VALUE' not in pub_text))
        results.append(('and loses nothing the universal source defines -- the '
                        'set is re-resolved, not filtered',
                        set(universal) <= set(pub_tree)))
        # The other side of the same property, so relaxing the assertion
        # above cannot quietly become "materialize whatever you like": a
        # practice the catalogue has retired must be ABSENT. Conditional
        # because a catalogue with nothing retired has nothing to assert,
        # and a vacuous case that always passes is worse than no case.
        retired = sorted(set(f.name for f in PRACTICES_DIR.glob('*.md'))
                         - set(universal))
        if retired:
            results.append((f'and materializes no retired practice '
                            f'({len(retired)} in the catalogue) -- a '
                            f'retirement record is not an in-force rule',
                            not (set(retired) & set(pub_tree))))
        # The real property: regenerating with build_views.py must not change
        # the AGENTS.md that sync just wrote. That byte-comparison IS what
        # generated-artifact-provenance's check performs.
        after_sync = (pub / 'AGENTS.md').read_text(encoding='utf-8')
        # Run it the way the check does -- as its own process, against the
        # consumer's own root -- rather than reaching into an internal.
        shutil.copy(ROOT / 'tools' / 'build_views.py', pub / 'tools_bv.py')
        subprocess.run([sys.executable, str(pub / 'tools_bv.py'), '--agents-only'],
                       cwd=str(pub), capture_output=True, text=True)
        (pub / 'tools_bv.py').unlink(missing_ok=True)
        results.append(('build_views.py regenerates byte-identically to what '
                        'sync wrote, so generated-artifact-provenance can pass',
                        (pub / 'AGENTS.md').read_text(encoding='utf-8') == after_sync))

        priv = _consumer(tmp, 'private')
        psv.sync(str(priv), user_config=str(user_cfg))
        priv_tree = sorted(f.name for f in (priv / 'practices').glob('*.md'))
        results.append(('CONTROL: a private consumer still gets the private '
                        'practice -- nothing is withheld where the tree is not '
                        'published', 'private-only.md' in priv_tree))

        failed = [n for n, ok in results if not ok]
        check(f'a public consumer repo never materializes private practice '
              f'text into its tracked tree ({len(results)} stated cases, a '
              f'private consumer being the control)',
              not failed, '; '.join(failed) if failed else '')


def check_consumer_sync_counts_what_a_brought_set_provides():
    """A consumer's sync leaves a brought set out of the tracked tree
    (spec/LADDER_OPT_IN_PLAN.md D6) but must still count it when deciding
    what is in force. Found by a consumer rehearsal, 2026-10-03: the sync
    filtered brought sets out BEFORE resolving, so an individual set's
    `requires: ["ladder"]` rules dropped out of every consumer, and a
    deduplicated individual rule pointing at a ladder rule read IN FORCE
    NOWHERE.

    1. the individual rule that requires the ladder is materialized;
    2. a deduplicated stub pointing at a rule in the brought set is not
       reported in force nowhere;
    3. the brought set's own rule is still never written into the tree;
    4. CONTROL: a person who brings nothing does not get the rule that
       requires the ladder -- the fix counts what is brought, nothing more."""
    import tempfile, shutil, contextlib, io
    import json as _json
    import precedent_sync_views as psv
    import precedent_resolve as pr
    import build_views as bv

    def rule(slug, extra=''):
        return _move_fixture_practice(slug).replace(
            'status:      active\n', 'status:      active\n' + extra)

    saved = {k: os.environ.get(k) for k in (
        'PRECEDENT_ASSUME_LADDER', 'PRECEDENT_USER_CONFIG', pr.NO_LADDERS_ENV)}
    for k in saved:                       # practice: fixture-owns-its-state
        os.environ.pop(k, None)
    results = []
    try:
        with tempfile.TemporaryDirectory() as tmp:
            tmp = pathlib.Path(tmp)
            uni = tmp / 'universal'
            (uni / 'practices').mkdir(parents=True)
            (uni / 'practices' / 'plain-rule.md').write_text(
                rule('plain-rule'), encoding='utf-8')
            # A rule the REPOSITORY declares that needs the ladder: a brought
            # set never switches it on, or a committed view would differ by
            # who regenerated it (found by the full suite, 2026-10-03).
            (uni / 'practices' / 'repo-needs-ladder.md').write_text(
                rule('repo-needs-ladder', 'requires:    ["ladder"]\n'),
                encoding='utf-8')
            lad = tmp / 'people' / 'fx-ladder'
            (lad / 'practices').mkdir(parents=True)
            (lad / 'precedent-source.json').write_text(_json.dumps({
                'name': 'fx-ladder', 'level': 'shared', 'provides': ['ladder']}),
                encoding='utf-8')
            (lad / 'practices' / 'fx-stage.md').write_text(
                rule('fx-stage'), encoding='utf-8')

            def person(name, brings):
                ind = tmp / name / 'precedent-individual'
                (ind / 'practices').mkdir(parents=True)
                (ind / 'precedent-source.json').write_text(_json.dumps({
                    'name': 'precedent-individual', 'level': 'individual',
                    'brings': brings}), encoding='utf-8')
                (ind / 'practices' / 'needs-ladder.md').write_text(
                    rule('needs-ladder', 'requires:    ["ladder"]\n'),
                    encoding='utf-8')
                (ind / 'practices' / 'old-stage.md').write_text(
                    rule('old-stage').replace('status:      active',
                                              'status:      deduplicated')
                    .replace('in_force_at: null', 'in_force_at: fx-stage'),
                    encoding='utf-8')
                if brings:
                    os.symlink(lad, ind.parent / 'fx-ladder')
                cfg = tmp / f'{name}.json'
                cfg.write_text(_json.dumps({'format_version': 1, 'individual': {
                    'name': 'precedent-individual', 'path': str(ind)}}),
                    encoding='utf-8')
                return cfg

            for who, brings in (('brings', [{'name': 'fx-ladder',
                                             'repo_url': 'https://example.com/fx.git'}]),
                                ('plain', [])):
                cfg = person(who, brings)
                repo = tmp / f'consumer-{who}'
                repo.mkdir()
                (repo / 'AGENTS.md').write_text(
                    f'# C\n\n{bv.BEGIN_MARKER} -->\n{bv.END_MARKER} -->\n',
                    encoding='utf-8')
                (repo / 'precedent.json').write_text(_json.dumps({
                    'format_version': 1, 'base_branch': 'main',
                    'visibility': 'private',
                    'sources': [{'level': 'universal', 'name': 'precedent',
                                 'path': str(uni)}]}), encoding='utf-8')
                err = io.StringIO()
                with contextlib.redirect_stderr(err):
                    psv.sync(str(repo), user_config=str(cfg))
                tree = {f.name for f in (repo / 'practices').glob('*.md')}
                if who == 'brings':
                    results.append(('1: the rule that requires the ladder is '
                                    'materialized for the person who brings it',
                                    'needs-ladder.md' in tree, sorted(tree)))
                    results.append(('2: a stub pointing at a brought rule is not '
                                    'in force nowhere',
                                    'IN FORCE NOWHERE -- old-stage' not in err.getvalue(),
                                    err.getvalue()[-400:]))
                    results.append(('3: the brought set\'s own rule is never written',
                                    'fx-stage.md' not in tree, sorted(tree)))
                    results.append(('3b: a rule the repository declares that '
                                    'needs the ladder stays out, whoever syncs',
                                    'repo-needs-ladder.md' not in tree, sorted(tree)))
                else:
                    results.append(('4: CONTROL: a person who brings nothing does '
                                    'not get it', 'needs-ladder.md' not in tree
                                    and 'plain-rule.md' in tree, sorted(tree)))
    finally:
        for k, v in saved.items():
            if v is None:
                os.environ.pop(k, None)
            else:
                os.environ[k] = v
    failed = [(n, d) for n, ok, d in results if not ok]
    check(f'a consumer sync counts what a brought set provides, and still '
          f'never writes it ({len(results)} stated cases)',
          not failed, '; '.join(f'{n} -- {d}' for n, d in failed))


def check_brought_sets_have_their_own_session_budget():
    """The sets a person brings are charged to `brought_sets_tokens` in that
    person's individual set, never to the repository's ceiling for
    .precedent/SESSION_PRACTICES.md (Morgan, 2026-10-03, strength:
    assented). A consumer rehearsal found the ladder put two repositories'
    session files over their ceilings, refusing every push there.

    1. bringing a set with a resident rule has a measured share > 0;
    2. no budget declared: the share stays charged to the repository,
       as before the budget existed;
    3. a budget at least the share: no finding, and the repo is charged the
       file less the share;
    4. CONTROL: a budget under the share is a finding;
    5. CONTROL: a person who brings nothing has a share of 0."""
    import tempfile, contextlib, io
    import json as _json
    import precedent_session_practices as psp
    import precedent_check as pc
    import precedent_resolve as pr

    saved = {k: os.environ.get(k) for k in (
        'PRECEDENT_ASSUME_LADDER', 'PRECEDENT_USER_CONFIG', pr.NO_LADDERS_ENV)}
    for k in saved:                       # practice: fixture-owns-its-state
        os.environ.pop(k, None)
    saved_root = pc.ROOT
    results = []
    try:
        with tempfile.TemporaryDirectory() as tmp:
            tmp = pathlib.Path(tmp)
            uni = tmp / 'universal'
            (uni / 'practices').mkdir(parents=True)
            (uni / 'practices' / 'plain-rule.md').write_text(
                _move_fixture_practice('plain-rule'), encoding='utf-8')
            home = tmp / 'home'
            lad = home / 'fx-ladder'
            (lad / 'practices').mkdir(parents=True)
            (lad / 'precedent-source.json').write_text(_json.dumps({
                'name': 'fx-ladder', 'level': 'shared', 'provides': ['ladder']}),
                encoding='utf-8')
            (lad / 'practices' / 'fx-stage.md').write_text(
                _move_fixture_practice('fx-stage').replace(
                    'tier:        on-demand', 'tier:        resident')
                .replace('Do the thing.', 'Do the thing. ' * 60),
                encoding='utf-8')
            ind = home / 'precedent-individual'
            (ind / 'practices').mkdir(parents=True)
            repo = tmp / 'consumer'
            repo.mkdir()
            (repo / 'precedent.json').write_text(_json.dumps({
                'format_version': 1, 'visibility': 'private',
                'sources': [{'level': 'universal', 'name': 'precedent',
                             'path': str(uni)}]}), encoding='utf-8')
            cfg = tmp / 'user.json'
            cfg.write_text(_json.dumps({'format_version': 1, 'individual': {
                'name': 'precedent-individual', 'path': str(ind)}}),
                encoding='utf-8')
            os.environ['PRECEDENT_USER_CONFIG'] = str(cfg)
            pc.ROOT = repo

            def manifest(brings, budget=None):
                man = {'name': 'precedent-individual', 'level': 'individual',
                       'brings': brings}
                if budget is not None:
                    man[psp.BROUGHT_BUDGET_KEY] = budget
                (ind / 'precedent-source.json').write_text(_json.dumps(man),
                                                           encoding='utf-8')

            fx = [{'name': 'fx-ladder', 'repo_url': 'https://example.com/fx.git'}]
            manifest(fx)
            with contextlib.redirect_stderr(io.StringIO()):
                share, names = psp.brought_share(repo)
                results.append(('1: a brought resident rule has a share > 0',
                                share > 0 and names == ['fx-ladder'],
                                f'{share} {names}'))
                n, f = pc._charge_brought_share(1000 + share)
                results.append(('2: no budget declared: charged to the '
                                'repository, as before, with no finding',
                                f is None and n == 1000 + share, f'{n} {f}'))
                manifest(fx, budget=share + 10)
                n, f = pc._charge_brought_share(1000 + share)
                results.append(('3: within budget, no finding, and the repo is '
                                'charged the file less the share',
                                f is None and n == 1000, f'{n} {f}'))
                manifest(fx, budget=max(0, share - 10))
                n, f = pc._charge_brought_share(1000 + share)
                results.append(('4: CONTROL: over budget is a finding',
                                f is not None and 'over the' in str(f), str(f)))
                manifest([])
                results.append(('5: CONTROL: bringing nothing has no share',
                                psp.brought_share(repo)[0] == 0, ''))
    finally:
        pc.ROOT = saved_root
        for k, v in saved.items():
            if v is None:
                os.environ.pop(k, None)
            else:
                os.environ[k] = v
    failed = [(n, d) for n, ok, d in results if not ok]
    check(f'the sets a person brings are charged to their own session budget, '
          f'not the repository\'s ceiling ({len(results)} stated cases)',
          not failed, '; '.join(f'{n} -- {d}' for n, d in failed))


def check_consumer_rehearsal_smaller_faults():
    """Three smaller faults a consumer rehearsal found, 2026-10-03.

    1. precedent_push_check.py --tier with a name that is not a tier ran the
       full suite silently, skipping --tier full's --because refusal; it is
       refused now. CONTROL: --tier basic --list is not refused.
    2. precedent_update.py --from-ref took the engine from the ref and the
       catalogue from the tracked branch. checkin.py update takes the ref now:
       a ref that names no commit is refused by name, which only happens if
       it reached update().
    3. The follow-up for rules cited in other repositories called a rule a
       sync removed from a consumer's practices/ "deleted by this branch". A
       slug the base's committed MANIFEST.json recorded is skipped. CONTROL:
       one it did not record is still reported."""
    import tempfile, shutil, types
    import precedent_check as pc
    cases = []
    r = subprocess.run([sys.executable, 'tools/precedent_push_check.py',
                        '--tier', 'main'], cwd=str(ROOT), capture_output=True,
                       text=True, timeout=120)
    cases.append(('1: --tier main is refused as not a tier',
                  r.returncode == 1 and "'main' is not a tier" in r.stderr,
                  f'rc={r.returncode} {r.stderr[-200:]}'))
    r = subprocess.run([sys.executable, 'tools/precedent_push_check.py',
                        '--tier', 'basic', '--list'], cwd=str(ROOT),
                       capture_output=True, text=True, timeout=120)
    cases.append(('1: CONTROL: --tier basic --list is not refused',
                  'is not a tier' not in r.stderr, r.stderr[-200:]))
    r = subprocess.run([sys.executable, 'tools/checkin.py', 'update', str(ROOT),
                        '--from-ref', 'no-such-ref-anywhere'], cwd=str(ROOT),
                       capture_output=True, text=True, timeout=120)
    cases.append(('2: checkin update reads --from-ref',
                  "--from-ref 'no-such-ref-anywhere' does not name a commit"
                  in (r.stdout + r.stderr), (r.stdout + r.stderr)[-300:]))

    tmp = pathlib.Path(tempfile.mkdtemp(prefix='followup-synced-'))
    saved_root = pc.ROOT
    env = dict(os.environ, GIT_AUTHOR_NAME='F', GIT_AUTHOR_EMAIL='f@x',
               GIT_COMMITTER_NAME='F', GIT_COMMITTER_EMAIL='f@x',
               GIT_CONFIG_GLOBAL=os.devnull, PRECEDENT_ALLOW_ANY_AUTHOR='1')
    try:
        repo = tmp / 'consumer'
        repo.mkdir()
        subprocess.run(['git', 'init', '-q', '-b', 'main', str(repo)], env=env, check=True)
        (repo / 'MANIFEST.json').write_text(json.dumps({'practices': [
            {'slug': 'synced-rule', 'source': 'precedent'}]}), encoding='utf-8')
        subprocess.run(['git', '-C', str(repo), 'add', '-A'], env=env, check=True)
        subprocess.run(['git', '-C', str(repo), 'commit', '-qm', 'base'], env=env, check=True)
        base = subprocess.run(['git', '-C', str(repo), 'rev-parse', 'HEAD'],
                              capture_output=True, text=True).stdout.strip()
        other = tmp / 'other-set'
        other.mkdir()
        ppr = types.SimpleNamespace(
            changed_slugs=lambda root, b: {'synced-rule': 'deleted',
                                           'own-rule': 'deleted'},
            source_roots=lambda root: [('here', root), ('other-set', other)],
            scan_root=lambda root, gone, succ, skip=None: [
                ('x.md', 1, slug, 'link', 'k', 's', 'l') for slug in sorted(gone)],
            must_fix=lambda row: True,
            received_paths=lambda root: set())
        pc.ROOT = repo
        got = pc._withdrawn_here_cited_elsewhere(ppr, base, {}, {})
        said = ' '.join(str(g) for g in got)
        cases.append(('3: a rule the base manifest recorded is not called '
                      'deleted by this branch', '`synced-rule`' not in said, said[:300]))
        cases.append(('3: CONTROL: a rule it did not record is still reported',
                      '`own-rule`' in said, said[:300]))
    finally:
        pc.ROOT = saved_root
        shutil.rmtree(tmp, ignore_errors=True)
    failed = [(n, d) for n, ok, d in cases if not ok]
    check(f'three smaller faults from the consumer rehearsal stay fixed '
          f'({len(cases)} stated cases)', not failed,
          '; '.join(f'{n} -- {d}' for n, d in failed))


def check_sync_keeps_the_map_and_links_after_a_removal():
    """A sync that removes practices keeps the repository around them whole
    (a consumer's report, 2026-10-02/03): it rewrote AGENTS.md, left eight
    dead links in a generated MAP.md with its own --check saying OK, and
    left two open items naming removed practices, which failed the next
    Promote.

    1. a link to a practice renamed upstream is repointed to its successor;
    2. a link to one withdrawn from universal is left, and reported with
       where the rule went;
    3. a generated MAP.md is rebuilt and no longer links the removed ones;
    4. CONTROL: a hand-made GLOSSARY.md (no generated_by header) is left
       byte for byte."""
    import tempfile, shutil
    import json as _json
    import build_views as bv
    tmp = pathlib.Path(tempfile.mkdtemp(prefix='sync-map-links-'))
    env = dict(os.environ, GIT_AUTHOR_NAME='F', GIT_AUTHOR_EMAIL='f@x',
               GIT_COMMITTER_NAME='F', GIT_COMMITTER_EMAIL='f@x',
               GIT_CONFIG_GLOBAL=os.devnull, PRECEDENT_ALLOW_ANY_AUTHOR='1',
               PRECEDENT_USER_CONFIG=str(tmp / 'no-such-config.json'))
    for k in ('PRECEDENT_ASSUME_LADDER', 'PRECEDENT_NO_LADDERS'):
        env.pop(k, None)
    results = []
    try:
        uni = tmp / 'universal'
        (uni / 'practices').mkdir(parents=True)
        for slug in ('kept-rule', 'gone-rule', 'old-name'):
            (uni / 'practices' / f'{slug}.md').write_text(
                _move_fixture_practice(slug), encoding='utf-8')
        repo = tmp / 'consumer'
        (repo / 'todo').mkdir(parents=True)
        subprocess.run(['git', 'init', '-q', '-b', 'main', str(repo)], env=env, check=True)
        (repo / 'AGENTS.md').write_text(
            f'# C\n\nSee [gone](practices/gone-rule.md).\n\n'
            f'{bv.BEGIN_MARKER} -->\n{bv.END_MARKER} -->\n', encoding='utf-8')
        (repo / 'precedent.json').write_text(_json.dumps({
            'format_version': 1, 'base_branch': 'main', 'visibility': 'private',
            'sources': [{'level': 'universal', 'name': 'precedent',
                         'path': str(uni)}]}), encoding='utf-8')
        glossary = '# Our own glossary\n\nHand-written; see practices/gone-rule.md.\n'
        (repo / 'GLOSSARY.md').write_text(glossary, encoding='utf-8')
        item = ('# An open item\n\nSee [gone](../practices/gone-rule.md) and '
                '[old](../practices/old-name.md).\n')
        (repo / 'todo' / 'todo-x.md').write_text(item, encoding='utf-8')
        (repo / 'hooks').mkdir()
        hook = '#!/bin/sh\n# see practices/gone-rule.md\nexit 0\n'
        (repo / 'hooks' / 'h.sh').write_text(hook, encoding='utf-8')
        # A vendored engine file is BestPractice's, rewritten on every refresh:
        # never this repository's to fix, so never reported here.
        (repo / 'tools').mkdir()
        (repo / 'tools' / 'eng.py').write_text('# reads practices/gone-rule.md\n',
                                               encoding='utf-8')
        (repo / 'tools' / 'ENGINE_MANIFEST.json').write_text(
            _json.dumps({'kind': 'consumer', 'files': ['eng.py']}), encoding='utf-8')
        sync = [sys.executable, str(ROOT / 'tools' / 'precedent_sync_views.py'),
                '--repo', str(repo)]
        r = subprocess.run(sync, env=env, capture_output=True, text=True)
        # A generated MAP.md, as a consumer that ran build_views has one.
        subprocess.run([sys.executable, str(ROOT / 'tools' / 'build_views.py'),
                        '--repo', str(repo)], env=env, capture_output=True, text=True)
        map_before = (repo / 'MAP.md').read_text(encoding='utf-8') \
            if (repo / 'MAP.md').is_file() else ''
        subprocess.run(['git', '-C', str(repo), 'add', '-A'], env=env, check=True)
        subprocess.run(['git', '-C', str(repo), 'commit', '-qm', 'first sync'],
                       env=env, check=True)
        results.append(('fixture: the first sync wrote the rules and a generated map',
                        r.returncode == 0 and 'practices/gone-rule.md' in map_before,
                        (r.stdout + r.stderr)[-300:]))
        # Upstream: gone-rule withdrawn outright, old-name renamed new-name.
        (uni / 'practices' / 'gone-rule.md').unlink()
        (uni / 'record').mkdir()
        (uni / 'record' / 'WITHDRAWN_FROM_UNIVERSAL.md').write_text(
            '- 2026-10-02: `gone-rule` withdrawn from universal, deliberately; in '
            'force only from the shared set `fx-ladder`, for the people who '
            'bring or declare it.\n', encoding='utf-8')
        (uni / 'practices' / 'new-name.md').write_text(
            _move_fixture_practice('new-name'), encoding='utf-8')
        (uni / 'practices' / 'old-name.md').write_text(
            _move_fixture_practice('old-name').replace(
                'status:      active', 'status:      deduplicated')
            .replace('in_force_at: null', 'in_force_at: new-name'), encoding='utf-8')
        r = subprocess.run(sync, env=env, capture_output=True, text=True)
        out = r.stdout + r.stderr
        got = (repo / 'todo' / 'todo-x.md').read_text(encoding='utf-8')
        map_after = (repo / 'MAP.md').read_text(encoding='utf-8')
        results.append(('1: a link to a renamed rule is repointed to its successor',
                        '../practices/new-name.md' in got
                        and 'old-name.md' not in got, got + out[-300:]))
        results.append(('2: a link to a withdrawn rule is left and reported with '
                        'where it went', '../practices/gone-rule.md' in got
                        and 'todo/todo-x.md:3: links `gone-rule`' in out
                        and 'fx-ladder' in out, out[-500:]))
        results.append(('2b: ...and so is one in AGENTS.md\'s own text outside the '
                        'generated block, which the full check refuses just the same '
                        '(two consumers, 2026-10-03)',
                        'AGENTS.md:3: links `gone-rule`' in out
                        and not any(l.startswith('AGENTS.md:') and 'AGENTS.md:3:' not in l
                                    and 'gone-rule' in l for l in out.splitlines()),
                        out[-500:]))
        results.append(('2c: ...and one in a tracked file that is not Markdown is '
                        'reported and left byte for byte (a consumer\'s hook, 2026-10-03)',
                        'hooks/h.sh:2: links `gone-rule`' in out
                        and (repo / 'hooks' / 'h.sh').read_text(encoding='utf-8') == hook,
                        out[-500:]))
        results.append(('2d: ...but a vendored engine file is not, being upstream\'s',
                        'tools/eng.py' not in out, out[-500:]))
        results.append(('3: the generated MAP.md is rebuilt without the removed rules',
                        r.returncode == 0 and 'practices/gone-rule.md' not in map_after
                        and 'practices/kept-rule.md' in map_after, out[-300:]))
        results.append(('4: CONTROL: a hand-made GLOSSARY.md is left byte for byte',
                        (repo / 'GLOSSARY.md').read_text(encoding='utf-8') == glossary, ''))
        # 5. An EARLIER removal (a consumer rehearsal, 2026-10-04): the next
        # sync removes nothing, and a link to the rule the last one removed
        # is still reported -- the full check refuses it whichever update
        # took the rule out. A link to a rule still present is not.
        (repo / 'todo' / 'todo-y.md').write_text(
            '# Another\n\nSee [kept](../practices/kept-rule.md).\n', encoding='utf-8')
        subprocess.run(['git', '-C', str(repo), 'add', '-A'], env=env, check=True)
        subprocess.run(['git', '-C', str(repo), 'commit', '-qm', 'second sync'],
                       env=env, check=True)
        r = subprocess.run(sync, env=env, capture_output=True, text=True)
        out = r.stdout + r.stderr
        results.append(('5: a link to a rule an EARLIER update removed is still '
                        'reported when this sync removes nothing',
                        r.returncode == 0
                        and 'hooks/h.sh:2: links `gone-rule`, which is not in '
                            'practices/' in out
                        and 'todo/todo-x.md:3: links `gone-rule`' in out
                        and 'kept-rule' not in out, out[-500:]))
        # 5b. ...and Update Vendors lists it for the person, as it lists this
        # sync's own: its parser read only "which this sync removed", so the
        # earlier removal was printed and never listed.
        sys.path.insert(0, str(ROOT / 'tools'))
        try:
            import precedent_update as _pu
        finally:
            sys.path.pop(0)
        _rep = _pu.Report()
        _pu.removed_links_step(_rep, out)
        results.append(('5b: Update Vendors lists the earlier removal\'s links for the '
                        'person, saying an earlier update removed the rule',
                        any(w == 'hooks/h.sh:2' and 'an earlier update removed' in y
                            for w, y in _rep.left)
                        and any(w == 'todo/todo-x.md:3' for w, _y in _rep.left),
                        repr(_rep.left)[:400]))
    except (OSError, subprocess.CalledProcessError) as e:
        results.append((f'fixture could not be built ({e})', False, ''))
    finally:
        shutil.rmtree(tmp, ignore_errors=True)
    failed = [(n, d) for n, ok, d in results if not ok]
    check(f'a sync that removes practices repoints or reports every link to '
          f'them and keeps a generated map current ({len(results)} stated cases)',
          not failed, '; '.join(f'{n} -- {d}' for n, d in failed))


def check_sync_refuses_to_write_from_incomplete_sources():
    """precedent_sync_views.py must not rewrite a repo's tracked tree when a
    declared source did not resolve (practice: very-deep-check, found by it).

    materialize() rebuilds practices/ by delete-and-rewrite, so an
    unreachable source does not merely go unrendered: every practice it
    contributed is DELETED from the tracked tree, with AGENTS.md and
    MANIFEST.json rewritten to match, one warning line, and exit 0. The diff
    reads as a deliberate removal.

    That is the CI state by definition -- a private team or individual
    source is unreachable in every continuous-integration checkout, which is
    exactly where an unattended sync would run. build_views.py already
    refuses this in as many words; this tool, the one the install and
    migration documents actually tell an adopter to run, did the opposite.
    The --check half of the same bug was found and fixed on 2026-09-06; the
    writing half was left, and it is the half that deletes.

    The two escape hatches are asserted too, because a refusal with no way
    past it would just be a different way to strand someone: --check must
    still inspect without writing, and --allow-missing-sources must still
    let a deliberate removal through."""
    import tempfile, shutil
    import json as _json
    import precedent_sync_views as psv
    import precedent_materialize as _pm
    import build_views as bv
    pm_MaterializeError = _pm.MaterializeError

    with tempfile.TemporaryDirectory() as tmp:
        tmp = pathlib.Path(tmp)
        repo, team = tmp / 'consumer', tmp / 'precedent-team-widgets'
        (repo / 'precedent' / 'universal').mkdir(parents=True)
        shutil.copytree(PRACTICES_DIR, repo / 'precedent' / 'universal' / 'practices')
        (team / 'practices').mkdir(parents=True)
        (team / 'practices' / 'widget-rule.md').write_text(
            '---\nslug: widget-rule\ntitle: Widgets are tested on the rig\n'
            'tier: on-demand\nseverity: default\napplies_to: ["**"]\n'
            'occasion: "changing widget firmware"\n'
            'index_clause: "test firmware on the rig, never the simulator"\n'
            'status: active\n---\n## Rule\nUse the rig.\n\n## Story\nIt drifted.\n',
            encoding='utf-8')
        (repo / 'AGENTS.md').write_text(
            f'# Consumer\n\n{bv.BEGIN_MARKER} -->\n{bv.END_MARKER} -->\n',
            encoding='utf-8')
        cfg = repo / 'precedent.json'
        cfg.write_text(_json.dumps({
            'format_version': 1, 'base_branch': 'main', 'visibility': 'private',
            'sources': [
                {'level': 'universal', 'name': 'precedent',
                 'path': 'precedent/universal'},
                {'level': 'team', 'name': 'precedent-team-widgets',
                 'path': str(team)}]}), encoding='utf-8')
        empty_user = tmp / 'user.json'
        empty_user.write_text(_json.dumps({'format_version': 1}), encoding='utf-8')

        psv.sync(str(repo), user_config=str(empty_user))
        landed = (repo / 'practices' / 'widget-rule.md').exists()

        # Now the CI state: the sibling clone is simply not there.
        shutil.rmtree(team)

        refused = False
        try:
            psv.sync(str(repo), user_config=str(empty_user))
        except pm_MaterializeError:
            refused = True
        survived = (repo / 'practices' / 'widget-rule.md').exists()

        # --check must still work: CI needs to inspect without writing.
        checked_ok = True
        try:
            psv.sync(str(repo), user_config=str(empty_user), check=True)
        except pm_MaterializeError:
            checked_ok = False
        survived_check = (repo / 'practices' / 'widget-rule.md').exists()

        # And the deliberate removal must still be possible.
        psv.sync(str(repo), user_config=str(empty_user), allow_missing=True)
        removed_on_request = not (repo / 'practices' / 'widget-rule.md').exists()

        results = [
            ('the shared practice lands while its source is reachable', landed),
            ('an unreachable declared source REFUSES the write', refused),
            ('and the tracked practice it contributed survives', survived),
            ('--check still inspects without writing', checked_ok and survived_check),
            ('--allow-missing-sources still permits a deliberate removal',
             removed_on_request),
        ]
        failed = [n for n, ok in results if not ok]
        check(f'precedent_sync_views refuses to rewrite a tracked tree from an '
              f'incomplete source set ({len(results)} stated cases, the '
              f'unreachable-in-CI source being the controlling case)',
              not failed, '; '.join(failed) if failed else '')


def check_unlanded_work_is_reported_before_the_passes():
    """The very deep check must surface unlanded work BEFORE its checklist,
    not with the branch verdicts at the end (practice: very-deep-check).

    THE INCIDENT. The 2026-09-07 run rediscovered two missing source files
    from scratch, wrote them up as findings, and filed them as open TODO
    items -- while the fixes sat finished on a branch from the previous day,
    in both private sets, named in those branches' own commit subjects.
    Nothing had asked what was sitting unmerged, because the branch list only
    printed after every pass had already been worked.

    The sweep's two halves have different costs and different jobs. Deciding
    a branch's fate is judgment and stays in pass 4. Knowing what already
    exists is a list, costs nothing, and is the only step in the whole check
    that prevents work rather than finding it -- so it has to come first, and
    ORDER is the property, which is what this asserts.

    A branch carrying no unique commits (rebased or squash-merged in) must
    NOT appear here: it is a deletion candidate, not unlanded work, and
    listing it would train the reader to skim the section that exists to be
    read."""
    import tempfile, shutil
    import json as _json

    _git = fixture_git

    with tempfile.TemporaryDirectory() as tmp:
        tmp = pathlib.Path(tmp)
        up, work = tmp / 'up', tmp / 'work'
        up.mkdir()
        _git(up, 'init', '-q', '-b', 'main')
        # `up` is a working clone, not a bare one, so git refuses a push to
        # the branch it has checked out. Two fixtures pushed to it anyway and
        # never noticed, because nothing looked at the exit code.
        _git(up, 'config', 'receive.denyCurrentBranch', 'ignore')
        _git(up, 'config', 'user.email', 'harness@example.com')
        _git(up, 'config', 'user.name', 'Harness')
        (up / 'f.txt').write_text('base\n')
        _git(up, 'add', '-A'); _git(up, 'commit', '-qm', 'base')

        # A branch carrying real, unlanded work.
        _git(up, 'checkout', '-q', '-b', 'carries-work')
        (up / 'fix.txt').write_text('the fix nobody landed\n')
        _git(up, 'add', '-A'); _git(up, 'commit', '-qm', 'a fix that never landed')
        _git(up, 'checkout', '-q', 'main')

        subprocess.run(['git', 'clone', '-q', f'file://{up}', str(work)],
                       capture_output=True, text=True)
        _git(work, 'config', 'user.email', 'harness@example.com')
        _git(work, 'config', 'user.name', 'Harness')
        (work / 'precedent.json').write_text(_json.dumps({
            'format_version': 1, 'base_branch': 'main',
            'sources': [{'level': 'universal', 'name': 'precedent',
                         'path': '.'}]}), encoding='utf-8')
        (work / 'practices').mkdir()
        shutil.copy(next(PRACTICES_DIR.glob('*.md')), work / 'practices')
        _git(work, 'add', '-A'); _git(work, 'commit', '-qm', 'declare a source')
        _git(work, 'push', '-q', 'origin', 'main')

        # HERMETIC, and it was not before.
        #
        # very_deep_check.py resolves the INDIVIDUAL source from a user-level
        # config outside any repo, so this fixture -- which declares one
        # universal source and nothing else -- was silently reaching the
        # machine's real precedent-individual clone. Its own output gave this
        # away once the failure detail above started printing it: a run
        # against a scratch repo was reporting "FRESHNESS -- declared
        # sources ... individual source 'precedent-individual'".
        #
        # That made the fixture inherit ambient state it never declared, and
        # the freshness gate is a HARD REFUSAL that returns before printing
        # anything -- so whenever that real clone was behind, diverged, or
        # slow to fetch, this check failed on a repository it is not testing.
        # It ran green for weeks and failed twice in the session that found
        # it, unreproducible in twelve isolated runs, which is exactly what a
        # test reading state it does not own looks like.
        #
        # Pointing PRECEDENT_USER_CONFIG at a path inside the temp directory
        # gives the resolver a config that legitimately declares no
        # individual source, so the fixture tests the fixture.
        env = dict(os.environ,
                   PRECEDENT_USER_CONFIG=str(tmp / 'no-such-user-config.json'))
        r = subprocess.run(
            [sys.executable, str(ROOT / 'tools' / 'very_deep_check.py'),
             '--repo', str(work), '--checklist'],
            capture_output=True, text=True, cwd=str(work), env=env)
        out = r.stdout

        results = []
        results.append(('the run produced output at all', bool(out.strip())))
        has_block = 'UNLANDED WORK' in out
        results.append(('unlanded work gets its own block', has_block))
        if has_block and 'Pass 1 —' in out:
            results.append(('it is printed BEFORE the checklist the session '
                            'works from -- the whole point',
                            out.index('UNLANDED WORK') < out.index('Pass 1 —')))
        else:
            results.append(('it is printed BEFORE the checklist the session '
                            'works from -- the whole point', False))
        results.append(('the branch carrying unlanded work is named',
                        'carries-work' in out.split('Pass 1 —')[0]))

        failed = [n for n, ok in results if not ok]
        # SAY WHAT THE TOOL ACTUALLY DID when this fails.
        #
        # This check ran green for weeks and then failed twice inside one
        # session (2026-09-07), both times reporting only which of its four
        # stated cases were false -- which is the symptom, never the cause.
        # It could not be reproduced in twelve isolated runs, so the cause is
        # something about a loaded full run, and the detail as written threw
        # away the one piece of evidence that would name it: what
        # very_deep_check.py itself printed and exited with. `UNLANDED WORK`
        # is printed UNCONDITIONALLY whenever the branch scan is not skipped,
        # so its absence means the tool returned before reaching that line --
        # most likely the freshness gate refusing, which it is designed to do
        # as a hard refusal rather than a warning. That is a guess until a
        # failing run says so itself, which is what this detail is for.
        #
        # Same lesson as the failure recap in main(): a count is not a
        # diagnosis, and re-running is what destroys the evidence.
        detail = ''
        if failed:
            tail = (out or '')[-400:].replace('\n', ' | ')
            detail = (f"{'; '.join(failed)} "
                      f"[very_deep_check.py exited {r.returncode}; "
                      f"stdout tail: {tail!r}; "
                      f"stderr tail: {(r.stderr or '')[-300:]!r}]")
        check(f'the very deep check reports unlanded work before its passes, '
              f'not after ({len(results)} stated cases)',
              not failed, detail)


def check_very_deep_check_records_its_components():
    """Every run records what each of its sections returned and cost, and a
    section it did not run is recorded as skipped rather than as clean
    (practice: very-deep-check).

    THE POINT OF THE LEDGER is a question no single run can answer -- which
    parts of this check stopped earning their place -- so the properties
    that matter are all about what survives to the NEXT run: the file is
    written, an unrun section is distinguishable from a quiet one, a run
    that aborted at the freshness gate still leaves its trace, and the
    quiet-section question is asked only once there are enough runs to ask
    it (QUIET_RUNS_BEFORE_QUESTION), never extrapolated from one.

    Each case asserts the tool's own words, not merely a non-zero exit
    (practice: control-asserts-which-failure): 'skipped' as a recorded
    status, 'first run in the ledger', 'FOUND NOTHING, ACROSS EVERY
    RECORDED RUN', and --record-pass's own refusal text.
    """
    import tempfile, shutil
    import json as _json

    _git = fixture_git

    with tempfile.TemporaryDirectory() as tmp:
        tmp = pathlib.Path(tmp)
        up, work = tmp / 'up', tmp / 'work'
        up.mkdir()
        _git(up, 'init', '-q', '-b', 'main')
        # `up` is a working clone, not a bare one, so git refuses a push to
        # the branch it has checked out. Two fixtures pushed to it anyway and
        # never noticed, because nothing looked at the exit code.
        _git(up, 'config', 'receive.denyCurrentBranch', 'ignore')
        _git(up, 'config', 'user.email', 'harness@example.com')
        _git(up, 'config', 'user.name', 'Harness')
        (up / 'f.txt').write_text('base\n')
        _git(up, 'add', '-A'); _git(up, 'commit', '-qm', 'base')
        subprocess.run(['git', 'clone', '-q', f'file://{up}', str(work)],
                       capture_output=True, text=True)
        _git(work, 'config', 'user.email', 'harness@example.com')
        _git(work, 'config', 'user.name', 'Harness')
        (work / 'precedent.json').write_text(_json.dumps({
            'format_version': 1, 'base_branch': 'main',
            'sources': [{'level': 'universal', 'name': 'precedent',
                         'path': '.'}]}), encoding='utf-8')
        (work / 'practices').mkdir()
        shutil.copy(next(PRACTICES_DIR.glob('*.md')), work / 'practices')
        _git(work, 'add', '-A'); _git(work, 'commit', '-qm', 'declare a source')
        _git(work, 'push', '-q', 'origin', 'main')

        # The fixture owns every ambient input it is graded on
        # (practice: fixture-owns-its-state): its own user config, so no real
        # individual source resolves, and its own ledger path, so the
        # repository's committed ledger is neither read nor written.
        ledger = tmp / 'ledger.json'
        env = dict(os.environ,
                   PRECEDENT_USER_CONFIG=str(tmp / 'no-such-user-config.json'))

        def _run():
            return subprocess.run(
                [sys.executable, str(ROOT / 'tools' / 'very_deep_check.py'),
                 '--repo', str(work), '--ledger', str(ledger),
                 '--skip-liveness', '--skip-visibility',
                 '--skip-branch-scan', '--skip-endgame-merge'],
                capture_output=True, text=True, cwd=str(work), env=env)

        first = _run()
        results = [('the run writes a ledger', ledger.is_file())]
        data = {}
        if ledger.is_file():
            try:
                data = _json.loads(ledger.read_text(encoding='utf-8'))
            except ValueError as exc:
                results.append((f'the ledger parses ({exc})', False))
        runs = (data.get('runs') or [])
        rows = runs[-1].get('components', []) if runs else []
        by_name = {r.get('name'): r for r in rows}
        results.append(('one run is recorded', len(runs) == 1))
        results.append(('a section that ran carries a countable result',
                        any(r.get('findings') is not None for r in rows)))
        results.append(('a section that ran carries its printed cost',
                        any(r.get('output_tokens', 0) > 0 for r in rows)))
        # The controlling case: --skip-branch-scan must not read as clean.
        branch_row = by_name.get('BRANCHES -- verdicts owed', {})
        results.append(("a skipped section is recorded 'skipped', never "
                        "as a clean zero",
                        branch_row.get('status') == 'skipped'
                        and branch_row.get('findings') is None))
        results.append(('one run says so rather than extrapolating',
                        'first run in the ledger' in first.stdout))
        results.append(('one run does NOT yet name a quiet section',
                        'FOUND NOTHING, ACROSS EVERY RECORDED RUN'
                        not in first.stdout))

        import very_deep_check as vdc
        for _ in range(max(0, vdc.QUIET_RUNS_BEFORE_QUESTION - 1)):
            last = _run()
        results.append((f'at {vdc.QUIET_RUNS_BEFORE_QUESTION} runs the quiet '
                        f'sections are named',
                        'FOUND NOTHING, ACROSS EVERY RECORDED RUN'
                        in last.stdout))

        # --record-pass: the good case lands, the malformed one refuses in
        # its own words and writes nothing.
        ok = subprocess.run(
            [sys.executable, str(ROOT / 'tools' / 'very_deep_check.py'),
             '--ledger', str(ledger), '--record-pass', '2=done,findings=3'],
            capture_output=True, text=True, env=env)
        data2 = _json.loads(ledger.read_text(encoding='utf-8'))
        passes = (data2.get('runs') or [{}])[-1].get('passes') or []
        results.append(('a hand-worked pass is recorded against the run',
                        ok.returncode == 0 and len(passes) == 1
                        and passes[0].get('findings') == 3))
        bad = subprocess.run(
            [sys.executable, str(ROOT / 'tools' / 'very_deep_check.py'),
             '--ledger', str(ledger), '--record-pass', 'nonsense'],
            capture_output=True, text=True, env=env)
        results.append(('a malformed --record-pass refuses in its own words',
                        bad.returncode != 0
                        and '--record-pass wants PASS=STATUS' in bad.stderr))
        data3 = _json.loads(ledger.read_text(encoding='utf-8'))
        results.append(('and writes nothing when it refuses',
                        data3 == data2))

        # A run that ABORTS still leaves its trace. Losing it would lose the
        # only evidence the aborted run produced -- and would also make the
        # ledger's own averages quietly wrong, since the sections it never
        # reached would simply be missing rather than marked. A tracked
        # file that does not parse is the tool's own hard stop, taken here
        # because it fires deterministically and offline.
        (work / 'broken.json').write_text('{not json', encoding='utf-8')
        _git(work, 'add', '-A'); _git(work, 'commit', '-qm', 'a file that does not parse')
        before = len(_json.loads(ledger.read_text(encoding='utf-8'))['runs'])
        aborted = _run()
        after = _json.loads(ledger.read_text(encoding='utf-8'))['runs']
        results.append(('a run that aborts mid-check is still recorded',
                        aborted.returncode != 0 and len(after) == before + 1))
        results.append(('and is marked incomplete rather than counted as a '
                        'clean run',
                        bool(after) and after[-1].get('completed') is False
                        and len(after[-1].get('components', [])) >= 1))
        results.append(("the aborting section's own result is kept",
                        bool(after) and any(
                            r.get('name') == 'MACHINE-READABLE FILES'
                            and r.get('findings') == 1
                            for r in after[-1].get('components', []))))

        # THE LEDGER BELONGS TO THE REPO BEING CHECKED. With the path
        # anchored at this engine's own checkout, every fixture above
        # appended a row about a temporary directory to THIS repository's
        # ledger -- six inside one harness run, each a full 20-section row.
        # The cross-run read is a comparison, so a foreign row moves every
        # number in it rather than merely adding noise. Found 2026-09-11, by
        # reading the ledger the first real run produced.
        home_ledger = ROOT / 'record' / 'very-deep-check-ledger.json'
        before_rows = None
        if home_ledger.is_file():
            try:
                before_rows = len(_json.loads(
                    home_ledger.read_text(encoding='utf-8')).get('runs') or [])
            except ValueError:
                before_rows = None
        subprocess.run(
            [sys.executable, str(ROOT / 'tools' / 'very_deep_check.py'),
             '--repo', str(work), '--skip-liveness', '--skip-visibility',
             '--skip-branch-scan', '--skip-endgame-merge'],
            capture_output=True, text=True, cwd=str(work), env=env)
        own = work / 'record' / 'very-deep-check-ledger.json'
        results.append(("a run with no --ledger records into the CHECKED "
                        "repo's own ledger", own.is_file()))
        if before_rows is not None and home_ledger.is_file():
            after_rows = len(_json.loads(
                home_ledger.read_text(encoding='utf-8')).get('runs') or [])
            results.append(("and never into this engine's checkout",
                            after_rows == before_rows))

        failed = [n for n, ok_ in results if not ok_]
        detail = ''
        if failed:
            detail = (f"{'; '.join(failed)} "
                      f"[first run exited {first.returncode}; stdout tail: "
                      f"{(first.stdout or '')[-300:]!r}; stderr tail: "
                      f"{(first.stderr or '')[-200:]!r}]")
        check(f'the very deep check records what each of its parts returned '
              f'and cost ({len(results)} stated cases)', not failed, detail)


@_without_session_id
def check_reply_gate_reports_only_this_sessions_flow():
    """The reply gate's unlanded and Promote lines name only the branch or
    flow this session worked on -- commits carrying its session trailer --
    in this checkout and in a sibling clone alike (Morgan, 2026-09-29,
    strength: decided: "only tell me about that promotions that I need to
    do *ONLY* regarding the branch/flow that I edited/worked on in that
    session window"). With no session id to match, this checkout keeps its
    line and a sibling gets none."""
    name = 'reply gate reports only this session\'s own flow'
    import precedent_gate as pg
    import tempfile

    cases = []
    sid_env = 'cse_01FixtureOwnSession'
    trailer = 'Claude-Session: https://claude.ai/code/session_01FixtureOwnSession'
    saved = {k: os.environ.get(k) for k in ('HOME', 'PRECEDENT_USER_CONFIG')}
    tmp = pathlib.Path(tempfile.mkdtemp(prefix='precedent-own-flow-'))
    try:
        (tmp / 'home').mkdir()
        os.environ['HOME'] = str(tmp / 'home')
        os.environ['PRECEDENT_USER_CONFIG'] = str(tmp / 'no-config.json')

        def make(dirname):
            up = tmp / f'{dirname}.git'
            subprocess.run(['git', 'init', '--bare', '-q', str(up)], check=True)
            repo = tmp / 'root' / dirname
            subprocess.run(['git', 'init', '-q', '-b', 'trunk', str(repo)], check=True)

            def g(*a):
                return subprocess.run(['git', '-C', str(repo), *a],
                                      capture_output=True, text=True)
            g('config', 'user.name', 'Harness Fixture')
            g('config', 'user.email', 'fixture' + chr(64) + 'example.invalid')
            g('config', 'commit.gpgsign', 'false')
            (repo / 'precedent.json').write_text(
                json.dumps({'base_branch': 'trunk', 'sources': []}), encoding='utf-8')
            g('add', '-A'); g('commit', '-qm', 'first')
            g('remote', 'add', 'origin', str(up))
            g('push', '-q', '-u', 'origin', 'trunk')
            g('switch', '-q', '-c', 'feature')
            return repo, g

        work, gw = make('work')
        sib, gs = make('precedent-sibling')
        (work / 'w.txt').write_text('w\n', encoding='utf-8')
        gw('add', '-A'); gw('commit', '-qm', 'another session\'s work')
        (sib / 's.txt').write_text('s\n', encoding='utf-8')
        gs('add', '-A'); gs('commit', '-qm', 'another session\'s work')

        def scan():
            return pg._unlanded_work(work, siblings=True)

        got = scan()
        cases.append(('no session id: this checkout keeps its line',
                      any(l.startswith('this checkout:') for l in got), str(got)))
        cases.append(('no session id: a sibling gets no line',
                      not any('precedent-sibling' in l for l in got), str(got)))

        os.environ['CLAUDE_CODE_REMOTE_SESSION_ID'] = sid_env
        got = scan()
        cases.append(('commits this session did not make get no line, in '
                      'this checkout or a sibling', got == [], str(got)))

        (work / 'w.txt').write_text('w, mine\n', encoding='utf-8')
        gw('add', '-A'); gw('commit', '-qm', f'my work\n\n{trailer}')
        (sib / 's.txt').write_text('s, mine\n', encoding='utf-8')
        gs('add', '-A'); gs('commit', '-qm', f'my work\n\n{trailer}')
        got = scan()
        cases.append(('a commit carrying this session\'s trailer brings this '
                      'checkout\'s line back',
                      any(l.startswith('this checkout:') and "'feature'" in l
                          for l in got), str(got)))
        cases.append(('and a sibling\'s line, named by its directory',
                      any(l.startswith('precedent-sibling:') for l in got), str(got)))
    finally:
        os.environ.pop('CLAUDE_CODE_REMOTE_SESSION_ID', None)
        for k, v in saved.items():
            if v is None:
                os.environ.pop(k, None)
            else:
                os.environ[k] = v
        shutil.rmtree(tmp, ignore_errors=True)

    failed = [f'{n}: {d}' for n, ok, d in cases if not ok]
    check(f'{name} ({len(cases)} stated cases)', not failed, '; '.join(failed))


@_without_session_id
def check_shallow_clone_never_fabricates_unlanded_work():
    """A branch whose merge base is out of reach must never be reported as
    carrying a COUNT of unlanded commits (practice: very-deep-check,
    control-asserts-which-failure).

    THE INCIDENT, 2026-09-08. The unlanded-work scan told a session that
    three branches of `precedent-individual` carried 22 commits of unlanded
    work. All three were plain ancestors of `main` -- every commit already
    landed, nothing to read. The scan had run against a shallow clone, where
    `git cherry` cannot find a merge base and answers by calling every commit
    unique.

    WHY THE EXISTING GUARD DID NOT FIRE. _unmerged_row already handled a
    shallow clone -- by checking `git cherry`'s exit code. There is no
    non-zero exit to catch: git exits 0 and prints a wrong answer, which is
    this repo's recurring shape (AGENTS.md records the same for `%P`
    reporting no parents and `rev-parse` printing a ref name where a hash
    belongs). A guard written for the wrong failure mode reads as coverage
    and is none.

    The direction of the error is what makes it expensive rather than merely
    wrong. This section exists to tell a session which branches to go read
    BEFORE the passes, so a fabricated count spends exactly the reading it
    was built to save -- and it fabricates in the environment every fresh
    session starts in.

    TWO CASES, because the fix has two outcomes and only one is a refusal.
    Deepening usually rescues the comparison, so the common path is a CORRECT
    answer, not an UNKNOWN one -- a control that only asserted the refusal
    would be satisfied by a tool that refused on every branch it saw.

    WHICH CASE DISCRIMINATES, measured rather than assumed: replayed against
    the pre-fix code, CASE 2 fails (on "no count of unlanded commits is
    invented" -- the bug itself) and CASE 1 PASSES. Case 1 is a regression
    guard on the right answer, NOT evidence the bug is caught, and a later
    session must not read it as such. The reason is worth knowing before
    trusting any fixture built this way: _fetch_all_heads falls back to an
    unbounded `git fetch origin` when its bounded one fails, so a local
    fixture gets full history handed to it and the buggy comparison comes
    out right anyway. In the wild the bounded fetch SUCCEEDED and simply did
    not reach far enough, no fallback ran, and the fabricated count stood --
    which is why the incident needed a real repository to show up at all.
    """
    # practice: slow-steps-report-and-cache -- this fixture is one of the
    # harness's slowest (~16s of a ~250s run, measured), building real git
    # history to test very_deep_check.py's shallow-clone handling.
    # Change-scoped like check_machine_readable_files_parse -- see that
    # function's and _changed_touches()'s docstrings for the reasoning and
    # the residual gap this narrower scope accepts. NOT scoped on "are
    # shallow clones still common" (this docstring's own account says they
    # remain the default environment every fresh session starts in) --
    # scoped only on whether THIS push touched the code under test, which
    # holds regardless of how common shallow clones are in the wild.
    name = ('a shallow clone never fabricates a count of unlanded work, and '
            'says so when it cannot tell')
    touched, scope = _changed_touches('tools/very_deep_check.py')
    if not touched:
        not_applicable(name, f'tools/very_deep_check.py did not change ({scope})')
        return
    import shutil, tempfile
    import json as _json

    _git = fixture_git

    def _seed(up):
        _git(up, 'init', '-q', '-b', 'main')
        # `up` is a working clone, not a bare one, so git refuses a push to
        # the branch it has checked out. Two fixtures pushed to it anyway and
        # never noticed, because nothing looked at the exit code.
        _git(up, 'config', 'receive.denyCurrentBranch', 'ignore')
        _git(up, 'config', 'user.email', 'harness@example.com')
        _git(up, 'config', 'user.name', 'Harness')
        (up / 'f.txt').write_text('base\n')
        _git(up, 'add', '-A'); _git(up, 'commit', '-qm', 'base')
        _git(up, 'checkout', '-q', '-b', 'fully-landed')
        (up / 'g.txt').write_text('work that DID land\n')
        _git(up, 'add', '-A'); _git(up, 'commit', '-qm', 'landed work')
        _git(up, 'checkout', '-q', 'main')
        _git(up, 'merge', '-q', '--no-ff', 'fully-landed', '-m', 'merge it')
        # Deeper than the tool's routine --depth=50, so the merge base is
        # genuinely out of reach of a shallow clone. See the docstring.
        for i in range(70):
            (up / f'f{i}.txt').write_text(f'later {i}\n')
            _git(up, 'add', '-A'); _git(up, 'commit', '-qm', f'later {i}')

    def _consumer(work, tmp):
        _git(work, 'config', 'user.email', 'harness@example.com')
        _git(work, 'config', 'user.name', 'Harness')
        (work / 'precedent.json').write_text(_json.dumps({
            'format_version': 1, 'base_branch': 'main',
            'sources': [{'level': 'universal', 'name': 'precedent',
                         'path': '.'}]}), encoding='utf-8')
        (work / 'practices').mkdir(exist_ok=True)
        shutil.copy(next(PRACTICES_DIR.glob('*.md')), work / 'practices')
        _git(work, 'add', '-A'); _git(work, 'commit', '-qm', 'declare a source')

    def _run(work, tmp):
        env = dict(os.environ,
                   PRECEDENT_USER_CONFIG=str(tmp / 'no-such-user-config.json'))
        r = subprocess.run(
            [sys.executable, str(ROOT / 'tools' / 'very_deep_check.py'),
             '--repo', str(work), '--checklist'],
            capture_output=True, text=True, cwd=str(work), env=env)
        # THE UNLANDED WORK BLOCK ONLY, not everything printed before the
        # checklist. This used to slice at 'Pass 1 --' and assert that a
        # branch name did not appear anywhere above it, which was a proxy
        # for "no fabricated count" that held only while nothing else
        # printed branch names. The live-session sweep prints them a few
        # lines below this block, so the proxy started failing on correct
        # output (2026-09-12). Scope the assertion to the section that is
        # actually under test.
        out = r.stdout
        if 'UNLANDED WORK' not in out:
            return r, out.split('Pass 1 —')[0]
        block = out.split('UNLANDED WORK', 1)[1]
        for end in ('\nLIVE SESSIONS', '\nREPOSITORY VISIBILITY', 'Pass 1 —'):
            if end in block:
                block = block.split(end, 1)[0]
        return r, block

    results = []
    diag = []

    # CASE 1 -- the real incident: shallow clone, origin still reachable.
    # The tool must deepen and give the CORRECT answer (nothing unlanded),
    # never a fabricated count.
    with tempfile.TemporaryDirectory() as tmp:
        tmp = pathlib.Path(tmp)
        up, work = tmp / 'up', tmp / 'work'
        up.mkdir(); _seed(up)
        subprocess.run(['git', 'clone', '-q', '--depth', '1',
                        f'file://{up}', str(work)], capture_output=True)
        shallow = _git(work, 'rev-parse',
                       '--is-shallow-repository').stdout.strip()
        _consumer(work, tmp)
        _git(work, 'push', '-q', 'origin', 'main')
        r, head = _run(work, tmp)
        diag.append(f'case1 exit={r.returncode} shallow={shallow!r}')
        # The fixture must be the thing under test: a clone that quietly came
        # back full would make every case below pass for the wrong reason.
        results.append(('case 1: the fixture clone really is shallow',
                        shallow == 'true'))
        results.append(('case 1: the run reached the unlanded-work block',
                        'UNLANDED WORK' in r.stdout))
        # THE BUG ITSELF.
        results.append(('case 1: a fully-landed branch is NOT reported as '
                        'carrying unlanded commits',
                        'fully-landed' not in head))
        results.append(('case 1: and the scan says so affirmatively, rather '
                        'than falling silent',
                        'No branch carries unlanded work' in head))

    # CASE 2 -- deepening cannot rescue it. The tool must REFUSE, in words
    # that name the cause and the remedy.
    #
    # The origin here is itself a SHALLOW bare clone, so it is perfectly
    # reachable and simply has no deeper history to serve. Breaking the
    # origin outright was tried first and does not reach this code at all:
    # the freshness gate refuses the whole run before the branch scan, which
    # is correct behaviour and the wrong fixture.
    with tempfile.TemporaryDirectory() as tmp:
        tmp = pathlib.Path(tmp)
        deep, mid, work = tmp / 'deep', tmp / 'mid', tmp / 'work'
        deep.mkdir(); _seed(deep)
        subprocess.run(['git', 'clone', '-q', '--bare', '--depth', '1',
                        f'file://{deep}', str(mid)], capture_output=True)
        _git(mid, 'fetch', '-q', '--depth=1', 'origin',
             '+refs/heads/fully-landed:refs/heads/fully-landed')
        subprocess.run(['git', 'clone', '-q', f'file://{mid}', str(work)],
                       capture_output=True)
        _git(work, 'fetch', '-q', 'origin',
             '+refs/heads/*:refs/remotes/origin/*')
        _consumer(work, tmp)
        _git(work, 'push', '-q', 'origin', 'main')
        r, head = _run(work, tmp)
        diag.append(f'case2 exit={r.returncode}')
        results.append(('case 2: the unmeasurable branch is reported at all',
                        'fully-landed' in head))
        results.append(('case 2: it is named as undetermined, not counted',
                        'COULD NOT DETERMINE' in head))
        # ASSERT THE MESSAGE, not merely the absence of the wrong one --
        # silence satisfies "no fabricated count" just as well, and silence
        # is the other way this fails.
        results.append(('case 2: the reason is the unreachable merge base',
                        'no merge base' in head))
        results.append(('case 2: the remedy is a bounded deepen',
                        '--depth=5000' in head))
        results.append(('case 2: no count of unlanded commits is invented',
                        'commit(s) with no patch-equivalent' not in head))
        # The false all-clear is the failure this check exists for.
        results.append(('case 2: the all-clear is NOT printed alongside an '
                        'unmeasurable branch',
                        'No branch carries unlanded work' not in head))

    failed = [n for n, ok in results if not ok]
    detail = ''
    if failed:
        detail = f"{'; '.join(failed)} [{'; '.join(diag)}]"
    check(f'a shallow clone never fabricates a count of unlanded work, and '
          f'says so when it cannot tell ({len(results)} stated cases)',
          not failed, detail)


def check_a_renamed_engine_file_never_survives_a_reseed():
    """Renaming an engine file upstream must not leave the old one behind
    in an adopter's tree (practice: decommission-deletes-files,
    control-asserts-which-failure).

    THE INCIDENT, 2026-09-08. Upstream renamed `precedent_retire_path.py`
    to `precedent_decommission.py`. Three real practice sets were then
    found each carrying the dead file, and every mechanism reported them
    healthy. Three separate holes lined up:

      1. `refresh` on a stale copy exited hard on the missing old path, so
         the ONLY way forward was a reseed (fixed upstream the same day --
         the skip-and-converge path).
      2. `seed`, the documented recovery, never called
         _remove_dropped_engine_files at all: it wrote the new set and a
         manifest that had already forgotten the old name, leaving the file
         on disk untracked.
      3. `refresh`'s early exit returned on a matching commit before any
         cleanup could run, so no later run would ever remove it -- and its
         `set_incomplete` test looked only for MISSING wanted files, never
         for PRESENT unwanted ones.

    After (2), the file is in no list any mechanism consults: gone from
    KINDS, gone from the manifest. _untracked_engine_files is keyed on the
    current lists and is deliberately blind to it. That is why
    RETIRED_ENGINE_FILES exists -- a name, once shipped, cannot be derived
    back out of the code that stopped shipping it.

    Three cases, one per hole. The reseed case is the one that would have
    caught the incident; the other two are the paths that made it
    permanent.
    """
    import shutil, tempfile
    import json as _json
    import importlib.util

    spec = importlib.util.spec_from_file_location(
        'pve', ROOT / 'tools' / 'precedent_vendor_engine.py')
    pve = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(pve)

    results = []

    # MISSING IS A FAILURE, NOT A CRASH. Every symbol below is one this fix
    # introduced, so an engine that predates it raises AttributeError -- and
    # an uncaught one here takes the whole harness run down instead of
    # reporting one red check, which AGENTS.md records as its own hazard.
    # Reported as the absence it is (practice: fail-gracefully).
    missing_symbols = [n for n in ('RETIRED_ENGINE_FILES',
                                   '_retired_engine_files_present',
                                   '_remove_dropped_engine_files',
                                   '_seed_write')
                       if not hasattr(pve, n)]
    if missing_symbols:
        check('a renamed engine file never survives a reseed, and is '
              'reported when it already has (0 of 8 stated cases reached)',
              False,
              f"precedent_vendor_engine.py is missing "
              f"{', '.join(missing_symbols)} -- the removed-file cleanup is "
              f"not present in this engine at all, so a rename upstream "
              f"leaves the old file in every adopter's tree")
        return

    # The tombstone must not be empty in a way that makes every case below
    # vacuously true.
    results.append(('the engine records at least one retired file name',
                    bool(pve.RETIRED_ENGINE_FILES)))

    with tempfile.TemporaryDirectory() as tmp:
        tools = pathlib.Path(tmp) / 'tools'
        tools.mkdir(parents=True)
        dead = sorted(pve.RETIRED_ENGINE_FILES)[0]

        # CASE 1 -- a tombstoned file the manifest has FORGOTTEN is still
        # reported. This is the state a pre-fix reseed produced, and the one
        # nothing else could see.
        (tools / dead).write_text('# left behind by a rename\n')
        (tools / pve.MANIFEST_NAME).write_text(_json.dumps({
            'format_version': 1, 'kind': 'source', 'source_commit': 'x' * 40,
            'files': [], 'sha256': {}}), encoding='utf-8')
        reported = pve._retired_engine_files_present(tools)
        results.append(('an unrecorded retired file is reported',
                        [n for n, _ in reported] == [dead]))
        # ASSERT WHAT IT SAYS, not merely that it said something: the reason
        # is the whole value of the report, since the reader has no other
        # way to find out what the file was.
        results.append(('the report carries the reason it was retired',
                        bool(reported) and len(reported[0][1]) > 20))
        # It must NOT delete on its own -- see the function's own docstring.
        results.append(('reporting does not delete it',
                        (tools / dead).is_file()))

        # CASE 2 -- a tombstoned file the manifest still RECORDS is removed
        # by the sweep, which can hash-verify it first.
        (tools / pve.MANIFEST_NAME).write_text(_json.dumps({
            'format_version': 1, 'kind': 'source', 'source_commit': 'x' * 40,
            'files': [dead],
            'sha256': {dead: pve._sha256(tools / dead)}}), encoding='utf-8')
        manifest = pve._load_manifest(tools)
        pve._remove_dropped_engine_files(tools, manifest, 'source')
        results.append(('a recorded retired file is removed by the sweep',
                        not (tools / dead).is_file()))

        # CASE 2b -- SEEDING A REPO THAT HAS NO MANIFEST AT ALL still
        # works. This is seed's primary case, and the cleanup added above
        # broke it outright by reading the manifest through a helper that
        # sys.exit()s when there is none. Every fixture here had a manifest
        # already, so nothing caught it until a full harness run did.
        fresh = pathlib.Path(tmp) / 'never-vendored'
        r = subprocess.run(
            [sys.executable, str(ROOT / 'tools' / 'precedent_vendor_engine.py'),
             'seed', str(fresh), '--kind', 'source'],
            capture_output=True, text=True, cwd=str(ROOT))
        results.append(('seeding a repo with no manifest at all still '
                        'succeeds', r.returncode == 0
                        and (fresh / 'tools' / pve.MANIFEST_NAME).is_file()))

    # CASE 3 -- seed() routes through the cleanup. Asserted structurally:
    # building a whole second checkout to seed from is a fixture bigger than
    # the property, and the property is simply that seed does not bypass it.
    src = (ROOT / 'tools' / 'precedent_vendor_engine.py').read_text()
    seed_body = src[src.index('def seed('):]
    seed_body = seed_body[:seed_body.index('\ndef ', 1)]
    results.append(('seed writes through _seed_write, which cleans up, '
                    'rather than calling _write_engine_files directly',
                    '_seed_write(' in seed_body
                    and '_write_engine_files(' not in seed_body))
    results.append(('_seed_write actually calls the cleanup',
                    '_remove_dropped_engine_files' in
                    src[src.index('def _seed_write('):
                        src.index('def seed(')]))
    # And refresh's early exit must consider orphans, not only absences.
    ref = src[src.index('def refresh('):]
    results.append(('refresh\'s early exit checks for orphaned files too',
                    'set_orphaned' in ref))

    failed = [n for n, ok in results if not ok]
    check(f'a renamed engine file never survives a reseed, and is reported '
          f'when it already has ({len(results)} stated cases)',
          not failed, '; '.join(failed))


def check_withdrawn_table_never_links_a_successor_it_does_not_have():
    """The withdrawn-practices table must not link a successor that lives in
    another source (practice: doc-references-are-links,
    control-asserts-which-failure).

    THE INCIDENT, 2026-09-08. The withdrawn table landed that morning and
    rendered `in_force_at:` as `[slug](practices/slug.md)` unconditionally.
    The first shared set to regenerate with it produced MAP.md linking
    `practices/headline-capitalization.md` -- a UNIVERSAL practice, in a repo
    that has no such file -- and that set then failed its own `light-check`
    on a broken relative link, inside a generated file its own header tells
    it never to hand-edit. Unfixable from within that repo.

    Deduplication is exactly the case where this bites: a team or individual
    rule is dropped BECAUSE a universal one already says it, so the successor
    is in a different repo more often than not. `in_force_at:` names a slug,
    never a source, so the renderer cannot assume locality.

    Both directions are asserted. A local successor must still be a link --
    fixing this by never linking would be a regression that no
    broken-link check could catch, since nothing at all would be broken.
    """
    import tempfile
    import importlib.util

    spec = importlib.util.spec_from_file_location(
        'bv', ROOT / 'tools' / 'build_views.py')
    bv = importlib.util.module_from_spec(spec)
    sys.path.insert(0, str(ROOT / 'tools'))
    try:
        spec.loader.exec_module(bv)
    finally:
        sys.path.pop(0)

    results = []
    with tempfile.TemporaryDirectory() as tmp:
        pdir = pathlib.Path(tmp) / 'practices'
        pdir.mkdir(parents=True)
        # The successor that IS here.
        (pdir / 'local-successor.md').write_text('x')
        here = pdir / 'gone-local.md'
        here.write_text('x')
        away = pdir / 'gone-away.md'
        away.write_text('x')

        def row(slug, target, f):
            return ({'slug': slug, 'status': 'deduplicated',
                     'in_force_at': target},
                    {'Story': 'Because.'}, str(f))

        out = '\n'.join(bv._render_withdrawn([
            row('gone-local', 'local-successor', here),
            row('gone-away', 'no-such-practice', away),
        ]))

        results.append(('a successor present in this repo is still linked',
                        '[local-successor](practices/local-successor.md)' in out))
        results.append(('a successor that is NOT in this repo is not linked',
                        '(practices/no-such-practice.md)' not in out))
        # Assert what it says instead: silence would satisfy the case above.
        results.append(('the absent successor is still named, so the reader '
                        'can find it', 'no-such-practice' in out))
        results.append(('and is told where to look',
                        'another source' in out))

    failed = [n for n, ok in results if not ok]
    check(f'the withdrawn table never links a successor this repo does not '
          f'have ({len(results)} stated cases)', not failed,
          '; '.join(failed) + (f' [rendered: {out[-300:]!r}]' if failed else ''))


def check_summary_fields_drop_links_before_the_cut():
    """Every generator that copies prose into a one-line or length-capped
    field drops the prose's links BEFORE cutting it (tools/summary_text.py;
    practice: control-asserts-which-failure).

    THE INCIDENT, 2026-09-25. build_todo_index.py cut an item's title at
    `[:120]`, and in a consumer repo the cut landed inside a link's URL,
    leaving "(../meeting-notes/<name>-" open in todo/TODO.md. Harmless while
    that row was last; once a row came after it, the consumer's link checker
    paired the stray "(" with the next row's ")" and reported a broken link.
    This repo's own TODO.md and CLOSED.md already carried three such cut
    links, unnoticed.

    Each case builds prose whose link STRADDLES that generator's cut, and
    first asserts that a naive cut of it really is unbalanced -- otherwise a
    fixture that drifted off the cut would pass with the fix deleted. Then
    it asserts the generated field carries no "](" and balanced parentheses.
    """
    import tempfile
    import importlib.util

    def load(name):
        spec = importlib.util.spec_from_file_location(
            f'_sumtext_{name}', ROOT / 'tools' / f'{name}.py')
        mod = importlib.util.module_from_spec(spec)
        sys.path.insert(0, str(ROOT / 'tools'))
        try:
            spec.loader.exec_module(mod)
        finally:
            sys.path.pop(0)
        return mod

    def straddling(limit):
        """Prose whose one link opens 12 characters before `limit`."""
        lead = 'w' * (limit - 12 - 1) + ' '
        return (lead + '[the notes](../meeting-notes/some-person-and-morgan-'
                '2026-09-25.md) and the rest of the sentence after it.')

    def naive_is_broken(text, limit):
        cut = text[:limit]
        return '](' in cut and cut.count('(') != cut.count(')')

    def clean(field):
        return '](' not in field and field.count('(') == field.count(')')

    results = []
    for limit in (120, 80, 400):
        results.append((f'fixture: a naive [:{limit}] cut really is broken',
                        naive_is_broken(straddling(limit), limit)))

    todo = load('build_todo_index')
    gotcha = load('build_gotcha_index')
    views = load('build_views')
    migrate = load('todo_migrate')

    with tempfile.TemporaryDirectory() as tmp:
        repo = pathlib.Path(tmp)
        tdir = repo / 'todo'
        tdir.mkdir()
        blocked = straddling(80).replace('"', "'")
        for slug, status in (('todo-2026-09-25-open-one', 'open'),
                             ('todo-2026-09-25-closed-one', 'done')):
            (tdir / f'{slug}.md').write_text(
                f'---\nslug: {slug}\nstatus: {status}\nkind: analysis\n'
                f'noted: 2026-09-25\nclosed: 2026-09-25\ndisposition: wait\n'
                f'blocked_on: "{blocked}"\n---\n\n## What\n\n'
                f'**{straddling(120)}**\n', encoding='utf-8')
        rc = todo.main(['--repo', str(repo)])
        results.append(('build_todo_index ran on the fixture', rc == 0))
        for name, want in (('TODO.md', 'todo-2026-09-25-open-one'),
                           ('CLOSED.md', 'todo-2026-09-25-closed-one')):
            text = (tdir / name).read_text(encoding='utf-8')
            rows = [l for l in text.splitlines() if want in l]
            results.append((f'{name} carries the fixture row', bool(rows)))
            for row in rows:
                cells = row.strip('|').split(' | ')
                results.append((f'{name}: the row still links its own item',
                                cells[0].strip().endswith(f'({want}.md)')))
                results.append((f'{name}: every copied cell is unlinked and '
                                f'balanced', all(clean(c) for c in cells[1:])))

        gdir = repo / 'gotchas'
        gdir.mkdir()
        (gdir / 'gotcha-2026-09-25-x.md').write_text(
            '---\nslug: gotcha-2026-09-25-x\nstatus: live\nnoted: 2026-09-25\n'
            f'---\n\n## Symptom\n\n{straddling(120)}\n\n## Story\n\nx\n',
            encoding='utf-8')
        rc = gotcha.main(['--repo', str(repo)])
        line = [l for l in (gdir / 'INDEX.md').read_text(encoding='utf-8')
                .splitlines() if 'gotcha-2026-09-25-x' in l]
        results.append(('gotcha INDEX: the symptom is unlinked, the story '
                        'link stays', rc == 0 and len(line) == 1
                        and clean(line[0].split('** [story]')[0])
                        and line[0].endswith('(gotcha-2026-09-25-x.md)')))

    reason = views._withdrawn_reason({'story': straddling(397)})
    results.append(('MAP.md withdrawn reason: unlinked and balanced at the '
                    '400 cut', clean(reason) and reason.endswith('...')))

    items = migrate.parse_todo_items(
        '# TODO\n\n- <a id="x"></a> ' + straddling(80 - 20) + '\n')
    results.append(('todo_migrate fallback title: unlinked and balanced at '
                    'the 80 cut', len(items) == 1 and clean(items[0].title)))

    # precedent_land.py: a practice landed without its own index_clause gets
    # one cut from its proposed rule at 76, and that clause is printed in
    # every occasion index that lists the practice.
    land = load('precedent_land')
    results.append(('fixture: a naive [:76] cut really is broken',
                    naive_is_broken(straddling(76), 76)))
    fm = land._render_practice({'slug': 'zzz-cut', 'title': 'Cut'},
                               straddling(76), 'observed', 'harness',
                               'universal')
    clause = next((l for l in fm.splitlines()
                   if l.startswith('index_clause:')), '')
    results.append(('precedent_land default index_clause: unlinked and '
                    'balanced at the 76 cut',
                    bool(clause) and clean(clause.split(':', 1)[1])))

    failed = [n for n, ok in results if not ok]
    check(f'summary fields drop links before the cut ({len(results)} '
          f'stated cases)', not failed, '; '.join(failed))


def check_leak_gate_refuses_a_fresh_container():
    """A repo that declares a private source must not pass the leak gate with
    the vocabulary layer unrun, even with no git config anywhere.

    THE INCIDENT, 2026-09-08, reported by a session after it had already
    pushed: it could attach neither private source, so there was no blocklist
    to load; no `precedent.requireVocabulary` existed in that fresh container
    to make the absence fatal; the gate printed PARTIAL, **exited 0**, and the
    push went through into a public repository with only the structural rules
    applied. "The check silently did not run" and "the check passed" were the
    same exit code -- the exact failure the requireVocabulary docstring says
    must not happen. The setting simply was not reachable where it mattered.

    THE FIX UNDER TEST is that the requirement is now DERIVED from
    precedent.json, which is tracked and therefore survives a fresh
    container, as well as configured. So the discriminating pair is cases 1
    and 2: the same environment, the same absent config, differing only in
    whether precedent.json declares a private source.

    Case 3 is the half a careless fix breaks -- continuous integration has no
    private list by design and must still pass, opting out BY NAME.
    Case 4 asserts the refusal names the RIGHT reason: the message used to
    assert the git-config trigger unconditionally, which after this change
    would send a reader to a setting that was not set and could not be unset
    (practice: control-asserts-which-failure).
    """
    import tempfile, shutil

    def run(cwd, *extra, blocklist=None):
        env = {k: v for k, v in os.environ.items() if k != 'PRECEDENT_LEAK_BLOCKLIST'}
        env['PRECEDENT_ALLOW_ANY_AUTHOR'] = '1'
        # HOME points at an empty directory, or ~/.config/precedent/config.json
        # injects this MACHINE's individual source into every fixture -- which
        # resolves, which makes every case read as "a private source resolved"
        # regardless of what the fixture declared. Caught while writing the
        # declared-but-unresolved case, and it is the fourth instance of this
        # shape in one day (practice: fixture-owns-its-state).
        env['HOME'] = str(_fixture_home)
        if blocklist:
            env['PRECEDENT_LEAK_BLOCKLIST'] = blocklist
        r = subprocess.run([sys.executable, str(cwd / 'tools' / 'leak_gate.py'), *extra],
                           capture_output=True, text=True, cwd=str(cwd), env=env)
        return r.returncode, r.stdout + r.stderr

    def build(tmp, sources):
        repo = pathlib.Path(tmp) / 'r'
        (repo / 'tools').mkdir(parents=True)
        # precedent_resolve.py and its companions, or _private_sources_resolved
        # cannot import it, falls back to DECLARATION, and every case below
        # reads the same -- the distinction under test would not be exercised
        # at all while the check still passed.
        _seed_consumer_engine(repo / 'tools',
                              extra=('leak_gate.py',
                                     'leak-blocklist.default.txt',
                                     'routing_scope.json',
                                     'glossary_terms.json'))
        (repo / 'precedent.json').write_text(json.dumps(
            {'format_version': 1, 'visibility': 'public', 'sources': sources}),
            encoding='utf-8')
        (repo / 'README.md').write_text('# ordinary\n\nnothing private here.\n',
                                        encoding='utf-8')
        subprocess.run(['git', 'init', '-q', str(repo)], capture_output=True)
        subprocess.run(['git', '-C', str(repo), 'add', '-A'], capture_output=True)
        # No `precedent.requireVocabulary` is set anywhere: that IS the
        # fresh-container shape this check is about.
        return repo

    _fixture_home = pathlib.Path(tempfile.mkdtemp())

    cases = []
    UNIVERSAL = [{'level': 'universal', 'name': 'precedent', 'path': '.'}]
    # A private source that RESOLVES: its directory exists and carries a
    # practices/ tree, so the session can read its text.
    PRIVATE = UNIVERSAL + [{'level': 'team', 'name': 'precedent-team-x',
                            'path': '../precedent-team-x'}]

    # Each `tmp` below is a throwaway git repo torn down at the end of its
    # own block -- manual mkdtemp + _rmtree_retrying rather than
    # `tempfile.TemporaryDirectory()`'s own cleanup, which crashed this
    # entire check once on a CI runner over a transient ENOTEMPTY
    # (_rmtree_retrying's own docstring has the incident).
    tmp = tempfile.mkdtemp()
    try:
        repo = build(tmp, PRIVATE)
        (pathlib.Path(tmp) / 'precedent-team-x' / 'practices').mkdir(parents=True)
        (pathlib.Path(tmp) / 'precedent-team-x' / 'practices' / 'zz.md').write_text(
            '---\nslug: zz\ntitle: Z\ntier: on-demand\nseverity: default\n'
            'applies_to: ["**"]\noccasion: "t"\nindex_clause: "t"\n'
            'checked_by: null\ndefines: []\nstatus: active\nsupersedes: []\n'
            'overrides: null\nadded: null\napproved_by: "h"\n---\n\n'
            '## Rule\nZ.\n\n## Story\nZ.\n', encoding='utf-8')
        rc, out = run(repo)
        cases.append(('a private source that RESOLVED, with no blocklist, '
                      'refuses -- its text is in context, so a private term '
                      'could reach the tree through it',
                      rc == 1 and 'FAIL' in out, out[-400:]))
        cases.append(('and the refusal says the source RESOLVED, not merely '
                      'that precedent.json declares one',
                      'RESOLVED this session' in out, out[-400:]))
        rc3, out3 = run(repo, '--structural-only')
        cases.append(('the same repo PASSES under --structural-only, so CI '
                      'still works', rc3 == 0, out3[-300:]))
        cases.append(('and still says the private half did not run, rather '
                      'than reporting a clean bill',
                      'private ones were not' in out3, out3[-300:]))
    finally:
        _rmtree_retrying(tmp)

    tmp = tempfile.mkdtemp()
    try:
        repo = build(tmp, UNIVERSAL)
        rc2, out2 = run(repo)
        cases.append(('a repo declaring NO private source is unaffected -- it '
                      'never had a vocabulary layer to lose, so this did not '
                      'become a gate everybody has to appease',
                      rc2 == 0, out2[-300:]))
    finally:
        _rmtree_retrying(tmp)

    # THE CORRECTION, and the case that matters most: declared but NOT
    # resolved. The first version of this gate refused here too, which blocked
    # a real session out of pushing at all -- its commit "dies with the
    # container". The session that could not attach the source never read its
    # text and has nothing from it to leak; refusing bought no safety and cost
    # repo-is-memory. The path below simply does not exist.
    tmp = tempfile.mkdtemp()
    try:
        repo = build(tmp, UNIVERSAL + [{'level': 'team', 'name': 'precedent-team-absent',
                                        'path': '../precedent-team-absent'}])
        rc4, out4 = run(repo)
        cases.append(('a private source DECLARED but not resolved ALLOWS the '
                      'push -- the session could not read it, so it has '
                      'nothing from it to leak',
                      rc4 == 0, out4[-400:]))
        cases.append(('and it says so loudly, naming the residual risk it '
                      'does NOT cover rather than reporting a clean bill',
                      'nothing from them to leak' in out4
                      and 'some other way' in out4, out4[-400:]))
    finally:
        _rmtree_retrying(tmp)

    _rmtree_retrying(str(_fixture_home))

    ok = all(c[1] for c in cases)
    check(f'the leak gate requires the blocklist when a private source '
          f'RESOLVED, and not merely when one is declared ({len(cases)} '
          f'stated cases, config absent throughout)', ok,
          '; '.join(f'{n}: {d}' for n, o, d in cases if not o)[:900])


def check_structural_only_actually_drops_the_private_half():
    """`--structural-only` must make the gate's verdict INDEPENDENT of
    whether a private blocklist is reachable -- that is the whole point of
    the flag, and it is what lets a CI runner and a developer's machine
    agree on the same tree.

    THE INCIDENT, 2026-09-21, and it took three corrections in one day.
    The flag originally only cleared whether the vocabulary layer was
    REQUIRED, never whether it was APPLIED. The first fix dropped BOTH
    blocklist halves, which over-shot: the default list is committed and
    publishable, so CI can and should keep running it. The second fix
    dropped the private half correctly -- and a sibling session measuring
    the flag against a real practice set STILL saw private patterns fire.
    There were three routes, not one:

      1. the vocabulary patterns themselves (the one that was fixed),
      2. the repo-reference policy and its owner rules, read from the SAME
         private file, plus the auto-derived bare-name patterns, which come
         from the sibling CLONES ON THIS DISK, and
      3. the self-heal, which reloaded the FULL blocklist as soon as a run
         had any hit at all -- so the flag worked on a clean tree and
         stopped working on exactly the runs whose verdict mattered.

    ROUTE 3 IS WHY THIS PLANTS A TREE THAT FAILS UNDER THE FLAG, not only
    one that passes -- though see the note at its own case: the reload is
    guarded, and this fixture cannot yet make it fire. A detector verified against a clean tree alone is
    indistinguishable from a broken one: under the flag a clean tree never
    reaches the self-heal, so route 3 stays invisible. The discriminating
    fixture trips a DEFAULT-list pattern -- reaching the self-heal -- while
    also containing a name only the PRIVATE list knows. If the reload comes
    back, that name is in the output. It must not be."""
    import tempfile

    _home = pathlib.Path(tempfile.mkdtemp())

    def run(cwd, *extra, blocklist=None):
        env = {k: v for k, v in os.environ.items()
               if k != 'PRECEDENT_LEAK_BLOCKLIST'}
        env['PRECEDENT_ALLOW_ANY_AUTHOR'] = '1'
        env['HOME'] = str(_home)          # practice: fixture-owns-its-state
        if blocklist:
            env['PRECEDENT_LEAK_BLOCKLIST'] = blocklist
        r = subprocess.run(
            [sys.executable, str(cwd / 'tools' / 'leak_gate.py'), *extra],
            capture_output=True, text=True, cwd=str(cwd), env=env)
        return r.returncode, r.stdout + r.stderr

    cases = []
    tmp = tempfile.mkdtemp()
    try:
        repo = pathlib.Path(tmp) / 'r'
        (repo / 'tools').mkdir(parents=True)
        _seed_consumer_engine(repo / 'tools',
                              extra=('leak_gate.py',
                                     'leak-blocklist.default.txt',
                                     'routing_scope.json',
                                     'glossary_terms.json'))
        (repo / 'precedent.json').write_text(json.dumps(
            {'format_version': 1, 'visibility': 'public',
             'sources': [{'level': 'universal', 'name': 'precedent',
                          'path': '.'}]}), encoding='utf-8')

        # A word the COMMITTED default list already matches, read out of the
        # shipped file rather than hardcoded -- so editing that list cannot
        # silently leave this check trying to trip a pattern that is gone.
        _default = (repo / 'tools' / 'leak-blocklist.default.txt').read_text(
            encoding='utf-8')
        _seed = None
        for _line in _default.splitlines():
            _m = re.match(r'^\\b([a-z]{3,})', _line.strip())
            if _m:
                _seed = _m.group(1)
                break
        cases.append(('the fixture found a literal word in the shipped '
                      'DEFAULT list to trip -- without one, route 3 is '
                      'never reached and this check would pass while '
                      'proving nothing',
                      _seed is not None, f'default list: {_default[-300:]!r}'))
        _seed = _seed or 'zzzznotfound'

        # The private list: a vocabulary pattern AND an owner declared
        # private-by-default, so the repo-reference rule has something to
        # enforce. Both come out of this one file, which is route 2.
        priv = pathlib.Path(tmp) / 'private-blocklist.txt'
        priv.write_text(
            '# private fixture list\n'
            '# visibility-audit: private-owner fixtureowner -- fixture\n'
            r'\bZarquonProject\b' + '\n', encoding='utf-8')

        (repo / 'README.md').write_text(
            '# fixture\n\n'
            'ZarquonProject is a private name only the private list knows.\n'
            'fixtureowner/UndeclaredThing is an undeclared repo reference.\n'
            f'The word {_seed} is on the committed default list.\n',
            encoding='utf-8')
        subprocess.run(['git', 'init', '-q', str(repo)], capture_output=True)
        subprocess.run(['git', '-C', str(repo), 'add', '-A'],
                       capture_output=True)

        # DIRTY DIRECTION FIRST. Without the flag, with the private list
        # reachable, both private routes must fire -- otherwise the clean
        # direction below proves nothing at all about the flag.
        rc_full, out_full = run(repo, blocklist=str(priv))
        cases.append(('WITHOUT the flag the private vocabulary pattern '
                      'fires -- the control that makes route 1+3 mean '
                      'something',
                      rc_full == 1 and 'ZarquonProject' in out_full,
                      out_full[-500:]))
        cases.append(('WITHOUT the flag the private repo-reference policy '
                      'fires too -- the control for route 2',
                      'UndeclaredThing' in out_full, out_full[-500:]))

        rc_so, out_so = run(repo, '--structural-only', blocklist=str(priv))
        cases.append(('WITH the flag the run still FAILS -- it tripped the '
                      'committed default list, which must keep biting in CI',
                      rc_so == 1, out_so[-500:]))
        cases.append(('...and names the default-list word, so the failure '
                      'is the one intended', _seed in out_so, out_so[-500:]))
        # ROUTE 3 IS GUARDED BUT NOT EXERCISED HERE, said plainly rather
        # than counted as covered: _try_refresh_private_blocklist_clone()
        # returns False in this fixture (there is no clone to fast-forward),
        # so the reload never runs even with the guard removed. What this
        # case proves is route 1 on a run that HAS hits. Exercising the
        # reload needs a real git clone as the private source; filed rather
        # than claimed (practice: speculation-is-marked).
        cases.append(('ROUTE 1: the private vocabulary name is NOT named, '
                      'on a run that HAD a hit -- the state in which the '
                      'flag used to quietly stop working',
                      'ZarquonProject' not in out_so, out_so[-800:]))
        cases.append(('ROUTE 2: no undeclared-repo finding, since the owner '
                      'policy lives in the private file this run did not '
                      'read', 'UndeclaredThing' not in out_so,
                      out_so[-800:]))
        cases.append(('the output says the private half was skipped rather '
                      'than reporting a clean bill over it',
                      'private half skipped' in out_so, out_so[-500:]))

        # THE REPRODUCIBILITY CLAIM ITSELF: the same flag with no private
        # list reachable at all -- what a CI runner sees -- must reach the
        # same verdict on the same tree.
        rc_ci, out_ci = run(repo, '--structural-only')
        cases.append(('same flag with NO private list reachable gives the '
                      'SAME exit code -- the verdict does not depend on the '
                      'machine, which is the only reason the flag exists',
                      rc_ci == rc_so, f'{rc_ci} vs {rc_so}: {out_ci[-400:]}'))
    finally:
        _rmtree_retrying(tmp)
        _rmtree_retrying(str(_home))

    ok = all(c[1] for c in cases)
    check(f'--structural-only drops every route the private half reaches, '
          f'including on a run that HAS hits ({len(cases)} stated cases)',
          ok, '; '.join(f'{n}: {d}' for n, o, d in cases if not o)[:900])


def check_title_case_knows_the_files_it_ships():
    """Every root file this project INSTANTIATES into an adopter must be
    classified correctly by title_case, including the ones upstream never
    has itself.

    THE INCIDENT, 2026-09-08, from a consumer repo taking the beta update:
    headline-capitalization fired on that repo's VOICE.md. `INTERNAL_FILES`
    had been built from UPSTREAM's own root names, and upstream shipped
    VOICE.md and STYLEGUIDE.md as templates it never instantiated -- so the
    default was blind to exactly the files this project hands out, and every
    adopter got the same false positive on a file whose own header says it
    is LOCAL ONLY.

    IT FAILS IN THE DIRECTION NOBODY CHECKS, which is what makes it worth a
    standing control rather than a one-line fix: upstream's own gate stays
    green because upstream does not have the file. So this check does not
    ask "is this one file classified right" -- it derives the list of
    shipped root files from templates/ and asks it of ALL of them, so a
    template added later is covered without anybody remembering to come
    back.

    VOICE.md stopped being a root file on 2026-09-17, and STYLEGUIDE.md
    followed on 2026-09-22 -- both are now repo-local practices,
    local/practices/project-voice.md and
    local/practices/project-visual-identity.md, instantiated from
    templates/local-practices/*.md.template -- nested one level deeper, so
    the root-level `templates/*.md.template` glob below correctly no longer
    yields either of them. Both are kept out of `shipped` and the by-name
    assertions for that reason, not an oversight: this check is about root
    files, and neither one still is.
    """
    import importlib.util

    spec = importlib.util.spec_from_file_location(
        'tc_ship', ROOT / 'tools' / 'title_case.py')
    tc = importlib.util.module_from_spec(spec)
    sys.path.insert(0, str(ROOT / 'tools'))
    try:
        spec.loader.exec_module(tc)
    finally:
        sys.path.pop(0)

    cases = []

    # Every templates/<NAME>.md.template instantiates to <NAME>.md at an
    # adopter's root -- INSTALL.md section 1 spells the mapping out. Derived, not
    # listed, so this cannot go stale the way the list it guards did.
    shipped = sorted(
        f.name[:-len('.template')]
        for f in (ROOT / 'templates').glob('*.md.template'))
    cases.append(('templates/ yields root files to classify at all',
                  len(shipped) >= 3, str(shipped)))

    # Neither VOICE.md nor STYLEGUIDE.md is shipped by a template any more,
    # asserted BY NAME as well as by the derivation above: a derivation that
    # silently produced an empty list would otherwise pass this whole check
    # without proving either file is actually gone from `shipped`.
    for name in ('VOICE.md', 'STYLEGUIDE.md'):
        cases.append((f'{name} is no longer shipped by a root template',
                      name not in shipped, str(shipped)))

    # Both replacements are internal for the same reason -- not
    # INTERNAL_FILES (neither carries a root-file entry any more) but
    # INTERNAL_DIRS, because local/practices/ is a repo-local practice
    # source, and 'local' has been an INTERNAL_DIRS entry since before this
    # file existed.
    for rel in ('local/practices/project-voice.md',
                'local/practices/project-visual-identity.md'):
        cases.append((f'{rel} is INTERNAL via '
                      "INTERNAL_DIRS's 'local' entry, with no INTERNAL_FILES "
                      'entry needed for it',
                      tc.is_outward(rel) is False,
                      ''))

    # spec/ and record/ are twins by design -- spec/ holds current normative
    # reference, record/ the working record -- and record/ was missing from
    # INTERNAL_DIRS until 2026-09-08 purely because the directory did not
    # exist when the list was written. Same shape as the VOICE.md miss above:
    # a default derived from what the repo HAPPENED to contain. Asserted as a
    # pair so neither can drift from the other again.
    for pair in ('spec', 'record'):
        cases.append((f'{pair}/ is an INTERNAL_DIRS entry -- it and its twin '
                      f'are both working trees, never published prose',
                      pair in tc.INTERNAL_DIRS, str(tc.INTERNAL_DIRS)))
    cases.append(('and a document inside record/ is classified internal',
                  tc.is_outward('record/GOTCHAS_ARCHIVE.md') is False, ''))

    # The other half, or "classify everything internal" would pass: files
    # that genuinely ARE published must still be in scope.
    for name in ('README.md', 'SETUP.md', 'documentation/ADOPTING.md'):
        cases.append((f'{name} is still OUTWARD, so the fix did not just '
                      f'silence the check', tc.is_outward(name) is True, ''))

    # And the classification an adopter gets must not depend on a
    # precedent.json they have not written: is_outward() reads one when it
    # is there, and the default is what every fresh install starts from.
    import tempfile
    with tempfile.TemporaryDirectory() as tmp:
        cases.append(('local/practices/project-visual-identity.md is '
                      'internal with NO precedent.json at all -- the state '
                      'a fresh adopter is in before they configure '
                      'anything',
                      tc.is_outward('local/practices/project-visual-identity.md',
                                    root=tmp) is False, ''))

    ok = all(c[1] for c in cases)
    check(f'title_case classifies the root files this project ships into '
          f'adopters ({len(cases)} stated cases, derived from templates/ '
          f'rather than listed)', ok,
          '; '.join(f'{n}: {d}' for n, o, d in cases if not o)[:800])


def check_carry_check_never_invents_lost_content():
    """A clone that does not contain the recorded base must refuse to answer,
    never report the whole vendored tree as lost.

    THE INCIDENT, 2026-09-08, on a real consumer repo. `checkin.py` reported
    69 "LOST" lines across a vendored tree from which nothing had been
    dropped. `git show <base>:<path>` exits 128 with EMPTY STDOUT for two
    unrelated situations -- the commit is not in this clone, or the path did
    not exist at that commit -- and the old code read stdout alone, so an
    unanswerable question was silently answered "every line here is new".
    Disproving it took extracting both trees and diffing them by hand, and
    the tempting shortcut was `--accept-loss`, which would have accepted a
    loss nobody measured: the guard against silent data loss becoming its
    cause.

    THE CASE THAT DISCRIMINATES IS 2, and it is built from a genuinely
    shallow clone rather than a fabricated one -- `git clone --depth 1` over
    a `file://` transport, because git IGNORES --depth on a plain path (this
    repository lost an hour to that once already, and a test that believed
    it had a shallow clone and did not would pass against the bug).

    Case 4 is the other half and the one a careless fix breaks: a file that
    really is new at base must still report its lines as pending, because
    that is the check doing its job.
    """
    import tempfile

    def git(cwd, *args, check_rc=True):
        env = dict(os.environ, PRECEDENT_ALLOW_ANY_AUTHOR='1')
        r = subprocess.run(['git', '-C', str(cwd), *args],
                           capture_output=True, text=True, env=env)
        if check_rc and r.returncode != 0:
            raise RuntimeError(f"git {' '.join(args)}: {r.stderr.strip()}")
        return r.stdout.strip()

    cases = []
    with tempfile.TemporaryDirectory() as tmp:
        tmp = pathlib.Path(tmp)
        # -- an "upstream" with two commits ---------------------------------
        up = tmp / 'upstream'
        up.mkdir()
        git(up.parent, 'init', '-q', str(up))
        git(up, 'config', 'user.email', 'harness@example.com')
        git(up, 'config', 'user.name', 'H')
        (up / 'shared.md').write_text('alpha\nbeta\ngamma\n', encoding='utf-8')
        git(up, 'add', '-A'); git(up, 'commit', '-qm', 'base')
        base_sha = git(up, 'rev-parse', 'HEAD')
        (up / 'shared.md').write_text('alpha\nbeta\ngamma\ndelta\n', encoding='utf-8')
        git(up, 'add', '-A'); git(up, 'commit', '-qm', 'second')

        # -- a genuinely shallow clone: file:// or --depth is IGNORED --------
        shallow = tmp / 'shallow'
        subprocess.run(['git', 'clone', '-q', '--depth', '1',
                        f'file://{up}', str(shallow)],
                       capture_output=True, text=True, check=True)
        holds_base = subprocess.run(
            ['git', '-C', str(shallow), 'cat-file', '-e', f'{base_sha}^{{commit}}'],
            capture_output=True, text=True).returncode == 0
        cases.append(('the fixture clone is genuinely shallow -- it does NOT '
                      'hold the base commit (without this the case below '
                      'proves nothing)', not holds_base, f'holds_base={holds_base}'))

        # -- the two indistinguishable git failures, measured ---------------
        deep = tmp / 'deep'
        subprocess.run(['git', 'clone', '-q', f'file://{up}', str(deep)],
                       capture_output=True, text=True, check=True)
        missing_commit = subprocess.run(
            ['git', '-C', str(shallow), 'show', f'{base_sha}:shared.md'],
            capture_output=True, text=True)
        missing_path = subprocess.run(
            ['git', '-C', str(deep), 'show', f'{base_sha}:never-existed.md'],
            capture_output=True, text=True)
        cases.append(('a missing COMMIT and a missing PATH are byte-identical '
                      'on stdout and exit code, so stdout alone cannot tell '
                      'them apart',
                      missing_commit.returncode == missing_path.returncode
                      and missing_commit.stdout == missing_path.stdout == '',
                      f'{missing_commit.returncode}/{missing_commit.stdout!r} vs '
                      f'{missing_path.returncode}/{missing_path.stdout!r}'))

        # -- the guard itself ----------------------------------------------
        import importlib.util
        spec = importlib.util.spec_from_file_location(
            'ck', ROOT / 'tools' / 'checkin.py')
        ck = importlib.util.module_from_spec(spec)
        sys.path.insert(0, str(ROOT / 'tools'))
        try:
            spec.loader.exec_module(ck)
        finally:
            sys.path.pop(0)

        has_guard = hasattr(ck, '_base_is_present') and hasattr(ck, '_git_rc')
        cases.append(('checkin.py has the precondition helpers at all',
                      has_guard, str(sorted(n for n in dir(ck) if n.startswith('_git') or 'base_is' in n))))
        if has_guard:
            cases.append(('_base_is_present is FALSE for a base the shallow '
                          'clone lacks -- the case that used to read as "every '
                          'line is new"',
                          ck._base_is_present(shallow, base_sha) is False, ''))
            cases.append(('_base_is_present is TRUE for a base the full clone '
                          'holds, so the guard does not simply always refuse',
                          ck._base_is_present(deep, base_sha) is True, ''))
            rc_missing, out_missing = ck._git_rc(deep, 'show', f'{base_sha}:never-existed.md')
            rc_ok, out_ok = ck._git_rc(deep, 'show', f'{base_sha}:shared.md')
            cases.append(('_git_rc surfaces the exit code a new-at-base path '
                          'returns, which is what lets the caller treat it as '
                          'genuinely new rather than unanswerable',
                          rc_missing != 0 and out_missing == '' and rc_ok == 0
                          and 'alpha' in out_ok,
                          f'{rc_missing} {rc_ok} {out_ok!r}'))

            # -- END TO END, and this is the case that proves the guard
            # FIRES rather than merely exists. A non-zero exit is not
            # evidence (practice: control-asserts-which-failure), so it
            # asserts the message: "cannot run", never "LOST".
            consumer = tmp / 'consumer'
            (consumer / 'process' / 'upstream').mkdir(parents=True)
            git(consumer.parent, 'init', '-q', str(consumer))
            git(consumer, 'config', 'user.email', 'harness@example.com')
            git(consumer, 'config', 'user.name', 'H')
            (consumer / 'process' / 'upstream' / 'shared.md').write_text(
                'alpha\nbeta\ngamma\nlocal addition nobody upstream has\n',
                encoding='utf-8')
            (consumer / 'process' / 'manifest.json').write_text(json.dumps(
                {'upstream': {'commit': base_sha, 'branch': 'main'}}),
                encoding='utf-8')
            git(consumer, 'add', '-A'); git(consumer, 'commit', '-qm', 'vendored')
            git(consumer, 'branch', '-M', 'main')
            git(consumer, 'remote', 'add', 'origin', str(consumer))
            git(consumer, 'fetch', '-q', 'origin')

            saved = (ck.ROOT, ck.UPSTREAM, ck.MANIFEST)
            ck.ROOT = consumer
            ck.UPSTREAM = consumer / 'process' / 'upstream'
            ck.MANIFEST = consumer / 'process' / 'manifest.json'
            try:
                try:
                    ck._carry_check(shallow, accept_loss=False)
                    said = '<returned without exiting>'
                except SystemExit as exc:
                    said = str(exc.code)
                cases.append(('run end to end against the shallow clone, it '
                              'says it CANNOT RUN and names the base commit',
                              'cannot run' in said and base_sha[:12] in said,
                              said[:300]))
                cases.append(('and it does NOT report anything as LOST, which '
                              'is the false finding this whole check exists '
                              'for', 'LOST' not in said, said[:300]))
                cases.append(('and it refuses --accept-loss for this state by '
                              'name, so the tempting shortcut is closed',
                              'accept-loss does not apply' in said
                              or '--accept-loss does not apply' in said,
                              said[:300]))
            finally:
                ck.ROOT, ck.UPSTREAM, ck.MANIFEST = saved

    ok = all(c[1] for c in cases)
    check(f'the carry check refuses to answer rather than inventing lost '
          f'content ({len(cases)} stated cases, on a real shallow clone)', ok,
          '; '.join(f'{n}: {d}' for n, o, d in cases if not o)[:900])


def check_doc_currency_finds_a_stale_document():
    """The documentation-currency sweep must find a document its subject
    outran, and must not invent one (practice: change-updates-its-docs).

    WHY EACH CASE IS HERE. The sweep is the backstop for a rule that lives
    in a person's habits, so a version of it that always says "none" is
    indistinguishable from a repository whose documents are all current --
    and would be believed, because that is the reassuring answer.

    THE ONE THAT MATTERS IS CASE 2, and it is built with the commits in a
    deliberate order: the document is committed FIRST, the thing it
    describes SECOND. Reverse those two and every implementation passes,
    including one that never compares timestamps at all. Case 1 is the
    unplanted control for it -- the same fixture with the second commit
    absent -- and case 1 alone does NOT discriminate, for the same reason.

    CASE 3 covers the half that fails silently in the real world: a spoken
    command nobody wrote down. The fixture plants a practice defining a
    capitalized phrase and a page that does not contain it. A run that only
    checks timestamps passes cases 1 and 2 and fails this one.

    CASE 6 is the shallow-clone reflex this repository has been bitten by
    four times: an unanswerable history must read UNKNOWN, never "current".
    """
    import tempfile
    import importlib.util

    spec = importlib.util.spec_from_file_location(
        'vdc_doc', ROOT / 'tools' / 'very_deep_check.py')
    vdc = importlib.util.module_from_spec(spec)
    sys.path.insert(0, str(ROOT / 'tools'))
    try:
        spec.loader.exec_module(vdc)
    finally:
        sys.path.pop(0)

    if not hasattr(vdc, '_doc_currency'):
        check('the documentation-currency sweep discriminates '
              '(0 of 7 stated cases reached)', False,
              'very_deep_check.py has no _doc_currency -- nothing compares a '
              'document against what it describes')
        return

    def git(cwd, *args, check_rc=True):
        env = dict(os.environ, PRECEDENT_ALLOW_ANY_AUTHOR='1')
        r = subprocess.run(['git', '-C', str(cwd), *args],
                           capture_output=True, text=True, env=env)
        if check_rc and r.returncode != 0:
            raise RuntimeError(f"git {' '.join(args)}: {r.stderr.strip()}")
        return r.stdout.strip()

    def build(tmp, with_later_change, page_text, practice_text):
        repo = pathlib.Path(tmp) / 'repo'
        (repo / 'documentation').mkdir(parents=True)
        (repo / 'practices').mkdir()
        (repo / 'tools').mkdir()
        git(repo.parent, 'init', '-q', str(repo))
        git(repo, 'config', 'user.email', 'harness@example.com')
        git(repo, 'config', 'user.name', 'Fixture')
        (repo / 'practices' / 'zzz-command.md').write_text(
            practice_text, encoding='utf-8')
        (repo / 'tools' / 'doc_coverage.json').write_text(json.dumps({
            'documents': {
                'documentation/PAGE.md': {
                    'describes': ['practices/zzz-command.md'],
                    'why': 'fixture',
                    'must_mention': 'spoken-commands',
                },
            },
            'must_mention': {'spoken-commands': {'why': 'fixture'}},
        }), encoding='utf-8')
        (repo / 'documentation' / 'PAGE.md').write_text(page_text,
                                                        encoding='utf-8')
        git(repo, 'add', '-A')
        git(repo, 'commit', '-qm', 'page and practice together')
        if with_later_change:
            # The ONLY thing that separates case 1 from case 2, and it has to
            # be a genuinely later commit: --date alone does not move %ct.
            time.sleep(1.1)
            (repo / 'practices' / 'zzz-command.md').write_text(
                practice_text + '\nA later change nobody wrote up.\n',
                encoding='utf-8')
            git(repo, 'add', '-A')
            git(repo, 'commit', '-qm', 'change the practice, leave the page')
        return repo

    GOOD_PRACTICE = (
        '---\nslug:        zzz-command\ntitle:       A command\n'
        'tier:        on-demand\nseverity:    default\n'
        'applies_to:  ["**"]\noccasion:    "testing"\n'
        'index_clause: "a fixture"\nchecked_by:  null\n'
        'defines:     []\ncommand:     {"Zorp It": "do the thing"}\n'
        'status:      active\nsupersedes:  []\n'
        'overrides:   null\nadded:       null\napproved_by: "fixture"\n'
        '---\n\n## Rule\nSay it.\n')
    PAGE_WITH = '# Page\n\nSay **Zorp It** to do the thing.\n'
    PAGE_WITHOUT = '# Page\n\nThis page teaches you nothing.\n'

    cases = []
    with tempfile.TemporaryDirectory() as tmp:
        repo = build(tmp, False, PAGE_WITH, GOOD_PRACTICE)
        found, notes = vdc._doc_currency(repo)
        cases.append(('a page committed WITH its subject reports no REVIEW',
                      not any('REVIEW' in f for f in found),
                      str(found)[:400]))
        cases.append(('and the spoken command it does carry is reported as '
                      'present, not silently skipped',
                      any('Zorp It' in n for n in notes), str(notes)[:400]))

    with tempfile.TemporaryDirectory() as tmp:
        repo = build(tmp, True, PAGE_WITH, GOOD_PRACTICE)
        found, _notes = vdc._doc_currency(repo)
        review = [f for f in found if 'REVIEW' in f]
        cases.append(('a page whose subject changed AFTER it reports REVIEW',
                      len(review) == 1, str(found)[:400]))
        cases.append(('and the finding names the commit that outran it, so a '
                      'reader can go and look',
                      bool(review) and 'change the practice, leave the page'
                      in review[0], str(review)[:400]))

    with tempfile.TemporaryDirectory() as tmp:
        repo = build(tmp, False, PAGE_WITHOUT, GOOD_PRACTICE)
        found, _notes = vdc._doc_currency(repo)
        cases.append(('a spoken command missing from the page that teaches '
                      'the vocabulary is a FINDING, even with every '
                      'timestamp current',
                      any('Zorp It' in f and 'FINDING' in f for f in found),
                      str(found)[:400]))

    with tempfile.TemporaryDirectory() as tmp:
        # An empty repository: git can date nothing. UNKNOWN, never current.
        repo = pathlib.Path(tmp) / 'bare'
        (repo / 'documentation').mkdir(parents=True)
        (repo / 'tools').mkdir()
        git(repo.parent, 'init', '-q', str(repo))
        (repo / 'tools' / 'doc_coverage.json').write_text(json.dumps({
            'documents': {'documentation/PAGE.md': {
                'describes': [], 'why': 'fixture'}}}), encoding='utf-8')
        (repo / 'documentation' / 'PAGE.md').write_text('# Page\n',
                                                        encoding='utf-8')
        found, notes = vdc._doc_currency(repo)
        cases.append(('a document git cannot date reads as UNKNOWN or '
                      'uncommitted, never as current',
                      any('documentation/PAGE.md' in n for n in notes),
                      str(notes)[:400]))

    with tempfile.TemporaryDirectory() as tmp:
        repo = pathlib.Path(tmp) / 'noreg'
        repo.mkdir()
        found, notes = vdc._doc_currency(repo)
        cases.append(('a repository with no registry says so and finds '
                      'nothing, rather than crashing',
                      found == [] and any('doc_coverage.json' in n
                                          for n in notes),
                      str((found, notes))[:400]))

    ok = all(c[1] for c in cases)
    check(f'the documentation-currency sweep discriminates '
          f'({len(cases)} stated cases, each built so a sweep that skipped '
          f'the comparison would fail it)', ok,
          '; '.join(f'{n}: {d}' for n, o, d in cases if not o)[:900])


def check_template_freshness_reads_the_skeleton_correctly():
    """The reverse-direction skeleton check must not invent gaps, and must
    not call one repo's habit a finding (practice: very-deep-check).

    WHY IT EXISTS. `precedent_bootstrap_source.verify()` reads a skeleton and
    asks whether a real source has everything in it. Nothing asked the
    reverse until 2026-09-08, so a skeleton could drift below reality and a
    newly bootstrapped source would be created missing something every real
    one has. That is how the individual skeleton came to ship no
    `identity.json` -- the file that decides whether the commit hook ENFORCES
    an author-date offset or merely guesses one.

    TWO FAILURES ON ITS FIRST RUN, both asserted here because both make the
    section useless in opposite ways:

      1. It reported `config.json.sample` as a gap. The skeleton plainly
         ships that file -- the scan stripped the `.sample` suffix and
         recorded only `config.json`, while a real source keeps the sample
         name verbatim. A check that flags what the template already has
         teaches the reader to skim it.
      2. Everything was labelled FINDING, including a level with exactly ONE
         resolved source. One repo is not evidence of a shape, and a
         permanent list of that repo's own working documents is the same
         noise problem from the other side.
    """
    import tempfile
    import importlib.util

    spec = importlib.util.spec_from_file_location(
        'vdc', ROOT / 'tools' / 'very_deep_check.py')
    vdc = importlib.util.module_from_spec(spec)
    sys.path.insert(0, str(ROOT / 'tools'))
    try:
        spec.loader.exec_module(vdc)
    finally:
        sys.path.pop(0)

    results = []
    if not hasattr(vdc, '_template_freshness'):
        check('the template-freshness scan reads the skeleton correctly '
              '(0 of 5 stated cases reached)', False,
              'very_deep_check.py has no _template_freshness -- the reverse '
              'direction is not checked at all')
        return

    with tempfile.TemporaryDirectory() as tmp:
        # A source carrying exactly what the individual skeleton ships,
        # suffixes and all, plus one extra file.
        src = pathlib.Path(tmp) / 'a-source'
        (src / 'practices').mkdir(parents=True)
        skel = ROOT / 'templates' / 'practice-set-individual'
        for f in skel.iterdir():
            if f.is_file():
                (src / f.name).write_text('x')
        (src / 'ONLY_HERE.md').write_text('x')

        out = vdc._template_freshness(
            [{'level': 'individual', 'name': 'fixture', 'path': str(src)}])
        joined = ' | '.join(out)

        # THE FALSE POSITIVE.
        results.append(('a file the skeleton ships under its own '
                        '.sample/.template name is NOT reported as a gap',
                        'config.json' not in joined))
        # One source is not evidence.
        results.append(('a level with one source is reported as a note, not '
                        'a FINDING', 'FINDING' not in joined))
        results.append(('and says plainly that one source proves nothing',
                        'only ONE source' in joined))
        # It still has to SAY something -- silence would pass the two cases
        # above just as well, and silence is how the gap survived.
        results.append(('the file the skeleton really lacks is still named',
                        'ONLY_HERE.md' in joined))

    # The gap that motivated all of this must actually be closed.
    results.append(('the individual skeleton now ships an identity file',
                    any(f.name.startswith('identity.json')
                        for f in (ROOT / 'templates' /
                                  'practice-set-individual').iterdir())))

    failed = [n for n, ok in results if not ok]
    check(f'the template-freshness scan reads the skeleton correctly '
          f'({len(results)} stated cases)', not failed,
          '; '.join(failed) + (f' [scan said: {joined!r}]' if failed else ''))


def check_assumed_visibility_never_deletes_practices():
    """An ASSUMED visibility must never remove practice files that are
    already in a consumer's tree (practice: very-deep-check, reported by a
    real repo).

    repo_is_public() treats an undeclared `visibility` as public, and that
    default is right: it fails safe against publishing private practice text
    into a world-readable repo, which is the failure that motivated it.

    It fails UNSAFE in the other direction. An existing PRIVATE consumer that
    never declared the field loses every team- and individual-level practice
    from its tracked tree on its next sync -- silently, as a committable diff
    that reads like a deliberate removal. Reported 2026-09-07 by a real
    private repo updating to this engine: 15 practices would have gone, and
    the person caught it only by checking that repo's actual visibility by
    hand.

    So the assumption is allowed to WITHHOLD, and not allowed to DELETE. A
    declared visibility proceeds either way -- that is someone choosing.
    Three states, all asserted, because fixing this by simply reverting the
    default would restore the publication hazard it was written for."""
    import tempfile, shutil
    import json as _json
    import precedent_sync_views as psv
    import precedent_materialize as _pm
    import build_views as bv

    def _fixture(tmp, visibility):
        repo, team = tmp / 'consumer', tmp / 'team-src'
        (repo / 'precedent' / 'universal').mkdir(parents=True)
        shutil.copytree(PRACTICES_DIR, repo / 'precedent' / 'universal' / 'practices')
        (team / 'practices').mkdir(parents=True)
        (team / 'practices' / 'team-only-rule.md').write_text(
            '---\nslug: team-only-rule\ntitle: A rule only this team has\n'
            'tier: on-demand\nseverity: default\napplies_to: ["**"]\n'
            'occasion: "doing team things"\nindex_clause: "do the team thing"\n'
            'status: active\n---\n## Rule\nDo it.\n\n## Story\nDecided.\n',
            encoding='utf-8')
        (repo / 'AGENTS.md').write_text(
            f'# c\n\n{bv.BEGIN_MARKER} -->\n{bv.END_MARKER} -->\n', encoding='utf-8')
        cfg = {'format_version': 1, 'base_branch': 'main',
               'sources': [
                   {'level': 'universal', 'name': 'precedent',
                    'path': 'precedent/universal'},
                   {'level': 'team', 'name': 'precedent-team-x',
                    'path': str(team)}]}
        if visibility:
            cfg['visibility'] = visibility
        (repo / 'precedent.json').write_text(_json.dumps(cfg), encoding='utf-8')
        return repo

    with tempfile.TemporaryDirectory() as tmp:
        tmp = pathlib.Path(tmp)
        user = tmp / 'user.json'
        user.write_text(_json.dumps({'format_version': 1}), encoding='utf-8')
        results = []

        # Seed a PRIVATE consumer that really carries the shared practice.
        repo = _fixture(tmp, 'private')
        psv.sync(str(repo), user_config=str(user))
        seeded = (repo / 'practices' / 'team-only-rule.md').exists()
        results.append(('a private consumer materializes the shared practice', seeded))

        # Now the reported state: the declaration goes away.
        cfg = _json.loads((repo / 'precedent.json').read_text())
        cfg.pop('visibility', None)
        (repo / 'precedent.json').write_text(_json.dumps(cfg), encoding='utf-8')
        refused = False
        try:
            psv.sync(str(repo), user_config=str(user))
        except _pm.MaterializeError:
            refused = True
        results.append(('an ASSUMED visibility refuses rather than deleting',
                        refused))
        results.append(('and the practice file survives the refusal',
                        (repo / 'practices' / 'team-only-rule.md').exists()))

        # Declared private: keep it. This is the control that stops the fix
        # from simply blocking every consumer.
        cfg['visibility'] = 'private'
        (repo / 'precedent.json').write_text(_json.dumps(cfg), encoding='utf-8')
        psv.sync(str(repo), user_config=str(user))
        results.append(('declaring private keeps it',
                        (repo / 'practices' / 'team-only-rule.md').exists()))

        # Declared public: withhold it. The publication hazard the default
        # exists for must still be closed.
        cfg['visibility'] = 'public'
        (repo / 'precedent.json').write_text(_json.dumps(cfg), encoding='utf-8')
        psv.sync(str(repo), user_config=str(user))
        results.append(('declaring public still withholds it',
                        not (repo / 'practices' / 'team-only-rule.md').exists()))

        failed = [n for n, ok in results if not ok]
        check(f'an assumed visibility withholds but never deletes '
              f'({len(results)} stated cases: seeded, refused, survived, and '
              f'both declared states)',
              not failed, '; '.join(failed) if failed else '')


def check_access_probe_separates_refusal_from_silence():
    """`can_land_here` must answer 'handoff' ONLY for a real permission
    refusal, and 'unknown' for everything else (practice: session-text).

    THE INCIDENT THE PROBE EXISTS FOR (2026-09-10): a session rooted in a
    private practice set built a seven-commit patch for a repo it could not
    push to, and sat blocked four days having spent about a hundred dollars
    reaching a branch nobody could land. The probe now runs at session start
    so nobody has to remember to ask.

    THE DISTINCTION THIS CHECK DEFENDS is the one that makes the answer worth
    printing. A network blip classified as 'handoff' tells a session it has no
    access where it has plenty -- and the remedy it then reaches for is
    spawning a session nobody needed. Collapsing 'unknown' into 'handoff'
    would make every case below still "work", which is exactly why the
    negative control is here: case 5 neuters the refusal vocabulary and
    asserts the verdict FLIPS, so a classifier that answered 'handoff'
    unconditionally could not pass this.

    Case 1 is a real end-to-end push --dry-run over file://, so the probe is
    measured doing its actual job rather than only its string handling."""
    import tempfile, subprocess as _sp
    import precedent_access_check as pac

    results = []
    with tempfile.TemporaryDirectory() as td:
        tmp = pathlib.Path(td)

        # fixture-owns-its-state: this fixture asserts on what git can reach,
        # so it owns the credential environment rather than inheriting the
        # container's. A real token here would send the probe at the network.
        env = dict(os.environ)
        for var in ('PRECEDENT_GIT_TOKEN', 'PRECEDENT_SOURCE_BASE_URL'):
            env.pop(var, None)

        # 1. A genuinely writable remote answers 'land'. file:// (not a bare
        # path) because git only treats it as a transport that way.
        bare = tmp / 'origin.git'
        _sp.run(['git', 'init', '--quiet', '--bare', str(bare)], check=True, env=env)
        work = tmp / 'work'
        work.mkdir()
        for cmd in (['git', 'init', '--quiet', '-b', 'main'],
                    ['git', 'remote', 'add', 'origin', f'file://{bare}']):
            _sp.run(cmd, cwd=work, check=True, env=env)
        (work / 'f.txt').write_text('x', encoding='utf-8')
        _sp.run(['git', 'add', '.'], cwd=work, check=True, env=env)
        _sp.run(['git', '-c', 'user.name=t', '-c', 'user.email=t@e',
                 '-c', 'commit.gpgsign=false', 'commit', '--quiet', '-m', 'c'],
                cwd=work, check=True,
                env={**env, 'PRECEDENT_ALLOW_ANY_AUTHOR': '1'})
        verdict, detail = pac.can_land_here(str(work))
        results.append(('a writable remote answers land', verdict == 'land', detail))

        # 2. A directory that is not a repo at all: 'unknown', and the detail
        # says which failure (practice: control-asserts-which-failure).
        plain = tmp / 'not-a-repo'
        plain.mkdir()
        v2, d2 = pac.can_land_here(str(plain))
        results.append(('a non-repo answers unknown', v2 == 'unknown', d2))

        # 3. A path with no clone at all names its own reason, verbatim.
        v3, d3 = pac.can_land_here(str(tmp / 'nothing-here'))
        results.append(('a missing clone says "no local clone to probe"',
                        v3 == 'unknown' and d3 == 'no local clone to probe', d3))

        # 4/5. The classifier, driven with canned git output so the two
        # branches are measured rather than hoped for. Restored in a finally:
        # a monkeypatch left installed would silently rewire every later check.
        real = pac._run_git
        try:
            pac._run_git = lambda repo, *a: (
                1, '', "remote: Permission to x/y denied to z.\nfatal: 403")
            v4, d4 = pac.can_land_here(str(work))
            results.append(('a 403 answers handoff and quotes the server',
                            v4 == 'handoff' and 'denied' in d4.lower(), d4))

            pac._run_git = lambda repo, *a: (
                1, '', 'fatal: unable to access: Could not resolve host: github.com')
            v5, d5 = pac.can_land_here(str(work))
            results.append(('an unreachable host answers unknown, NOT handoff',
                            v5 == 'unknown', f'{v5}: {d5}'))

            # NEGATIVE CONTROL. Same failure, refusal vocabulary removed: the
            # verdict must move off 'handoff'. If this case passes as
            # 'handoff', the classifier is not reading the message at all and
            # case 4 above proves nothing.
            pac._run_git = lambda repo, *a: (1, '', 'fatal: something else entirely')
            v6, d6 = pac.can_land_here(str(work))
            results.append(('a refusal with no refusal words is NOT handoff',
                            v6 != 'handoff', f'{v6}: {d6}'))
        finally:
            pac._run_git = real

        # 6. very_deep_check must be using THIS definition, not a second copy.
        # The probe was moved down into the vendored file precisely so one
        # definition serves both; a re-added local copy would pass every case
        # above while drifting from what adopters actually run.
        import very_deep_check as _vdc
        results.append(('very_deep_check imports the probe rather than copying it',
                        _vdc.can_land_here is pac.can_land_here,
                        repr(getattr(_vdc.can_land_here, '__module__', '?'))))

    failed = [f'{n} [{d}]' for n, ok, d in results if not ok]
    check(f'the access probe separates a refusal from silence '
          f'({len(results)} stated cases, including a negative control that '
          f'flips the verdict)',
          not failed, '; '.join(failed) if failed else '')
# practice: environment-gotchas -- the trap this guards is record/GOTCHAS.md#g1.
#
# Several checks below need a package that is not in the standard library:
# doc_lint's strikethrough case suite and the `doc-references-are-links`
# planted violation both need cmarkgfm, and the --help sweep runs
# tools/doc_html.py, which imports markdown. Without them those checks FAIL,
# and they fail describing what they were testing rather than what is
# missing -- on 2026-09-14 that read as "3 failed" on a tree whose diff was
# two markdown files, and cost two full re-runs to attribute. The packages
# are installed by .claude/hooks/session-start.sh and by both CI workflows;
# a session whose hooks never ran (record/GOTCHAS.md#g17) has neither.
DOC_PACKAGES = ('cmarkgfm', 'markdown')


def missing_doc_packages():
    """-> [name] for each DOC_PACKAGES entry this interpreter cannot import."""
    return [n for n in DOC_PACKAGES if importlib.util.find_spec(n) is None]


def _report_missing_doc_packages(where):
    missing = missing_doc_packages()
    if not missing:
        return missing
    print(f'verify_harness {where}: {", ".join(missing)} not installed. '
          f'Checks that need them FAIL for that reason alone, not because of '
          f'anything in the tree -- install with: pip install '
          f'{" ".join(missing)}  (record/GOTCHAS.md#g1)')
    print('  and run: python3 tools/precedent_session_check.py -- these '
          'packages are installed by the SessionStart hook, so missing ones '
          'usually mean NO hook ran, and the hooks guarantee more than this')
    return missing


def check_todo_gotcha_stale_reference_fires():
    """precedent_check.py's `todo-gotcha-stale-reference` (Part 4.1 step 7,
    extended by step 10) against a real fixture repo, `pc.ROOT` pointed at
    it (practice: control-asserts-which-failure -- asserts the specific
    finding text, not just that the check went non-green; and each planted
    case has its own clean-tree negative control alongside it, per
    fixture-owns-its-state)."""
    import tempfile
    sys.path.insert(0, str(ROOT / 'tools'))
    import precedent_check as pc

    def make_repo(files):
        d = pathlib.Path(tempfile.mkdtemp(prefix='precedent-stale-ref-'))
        for rel, content in files.items():
            p = d / rel
            p.parent.mkdir(parents=True, exist_ok=True)
            p.write_text(content, encoding='utf-8')
        subprocess.run(['git', 'init', '-q'], cwd=d, check=True)
        subprocess.run(['git', 'add', '-A'], cwd=d, check=True)
        return d

    def run(files):
        d = make_repo(files)
        saved = pc.ROOT
        pc.ROOT = d
        try:
            findings = pc._todo_gotcha_stale_reference(pc.Ctx(whole_tree=True))
            return [str(f) for f in findings]
        finally:
            pc.ROOT = saved
            shutil.rmtree(d, ignore_errors=True)

    cases = []

    out = run({'spec/PLAN.md': 'see [x](../TODO.md#old-slug) for detail\n'})
    cases.append(('a TODO.md#slug link is reported',
                  any('old-slug' in o for o in out), repr(out)))

    out = run({'todo/todo-2026-01-01-old-slug.md':
              '---\nslug: todo-2026-01-01-old-slug\n---\n## What\nfine\n'})
    cases.append(('...and a real migrated item file alone raises nothing',
                  out == [], repr(out)))

    out = run({'spec/X.md': 'the story is [here](#g5)\n'})
    cases.append(('a bare #gN anchor with no file is reported',
                  any('#g5' in o for o in out), repr(out)))

    out = run({'record/GOTCHAS.md': '## 5. <a id="g5"></a>Trap\n\nSee [also](#g5).\n'})
    cases.append(("...and the SAME bare anchor inside record/GOTCHAS.md itself "
                  "is not -- it is a real same-document jump there",
                  out == [], repr(out)))

    out = run({'AGENTS.md': 'closed via TODO.md item 42 last week\n'})
    cases.append(('an "item N" phrase is reported',
                  any('item 42' in o for o in out), repr(out)))

    out = run({'TODO.md': '# TODO has moved\n\nSee todo/ instead.\n'})
    cases.append(("the real stub -- prose, no bullets -- raises nothing",
                  out == [], repr(out)))

    out = run({'TODO.md': ('# TODO has moved\n\n'
                           '- <a id="new-item"></a>**Sneaking one in.**\n')})
    cases.append(('a new old-format bullet added back to TODO.md itself is '
                  'reported (Part 4.4 step 1: TODO.md takes no new items '
                  'after the cutover)',
                  any('new item bullet' in o for o in out), repr(out)))

    out = run({'AGENTS.md': 'nothing here resembles any of the three shapes\n'})
    cases.append(('unrelated prose raises nothing', out == [], repr(out)))

    out = run({'TODO.md': ('# Repo TODO — open analyses, verifications, and decisions\n\n'
                           '## Recurring\n\n'
                           '- [ ] **Precedent check-in:** review vendored changes.\n')})
    cases.append(("a downstream project's own (never-migrated) TODO.md, still "
                  "carrying the classic template's own bullets, raises nothing "
                  "-- this repo's cutover does not bind a project that never "
                  "adopted the stub (caught by "
                  "check_installer_produces_a_clean_install: a fresh install "
                  "from templates/TODO.md.template was failing this check)",
                  out == [], repr(out)))

    bad = [(c[0], c[2]) for c in cases if not c[1]]
    check(f'todo-gotcha-stale-reference catches its three named shapes and '
          f'the two same-document exemptions do not false-positive '
          f'({len(cases)} stated cases)',
          not bad, '; '.join(f"{n} -- {d[:300]}" for n, d in bad))


def check_todo_and_gotcha_sweeps():
    """very_deep_check.py's two Part 3 sweeps -- _open_item_sweep and
    _gotcha_retirement_candidates -- against planted fixtures
    (fixture-owns-its-state: each fixture writes every field its own
    assertion depends on)."""
    import tempfile
    sys.path.insert(0, str(ROOT / 'tools'))
    import very_deep_check as vdc
    import precedent_time as ptime

    today = ptime.today(ROOT)

    def todo_item(slug, **fields):
        base = dict(kind='analysis', status='open', disposition='wait',
                   remind_on='null', blocked_on='null', batch='null',
                   decision='null', decision_strength='null',
                   waiting_on='null', noted=today, closed='null')
        base.update(fields)
        lines = ['---', f'slug:              {slug}']
        for k in ('kind', 'domain', 'severity', 'status', 'disposition',
                 'remind_on', 'blocked_on', 'batch', 'decision',
                 'decision_strength', 'waiting_on', 'noted', 'closed'):
            v = base.get(k, 'null')
            lines.append(f'{k}:{"":<{18-len(k)}} {v}')
        lines += ['---', '', '## What', '', f'**{slug} title.**', '']
        return '\n'.join(lines)

    def make_repo(todo_files=None, gotcha_files=None):
        d = pathlib.Path(tempfile.mkdtemp(prefix='precedent-sweep-'))
        for name, content in (todo_files or {}).items():
            (d / 'todo').mkdir(exist_ok=True)
            (d / 'todo' / name).write_text(content, encoding='utf-8')
        for name, content in (gotcha_files or {}).items():
            (d / 'gotchas').mkdir(exist_ok=True)
            (d / 'gotchas' / name).write_text(content, encoding='utf-8')
        return d

    cases = []

    d = make_repo(todo_files={
        'todo-2026-01-01-unblocked.md': todo_item(
            'todo-2026-01-01-unblocked', noted='2026-01-01'),
    })
    out = vdc._open_item_sweep(d)
    cases.append(('an open, kind:analysis item with no blocked_on is listed '
                  'as UNBLOCKED', any('UNBLOCKED' in o for o in out), repr(out)))
    shutil.rmtree(d)

    d = make_repo(todo_files={
        'todo-2026-01-01-blocked.md': todo_item(
            'todo-2026-01-01-blocked', noted='2026-01-01',
            blocked_on='"see `tools/nonexistent_tool.py`"'),
    })
    out = vdc._open_item_sweep(d)
    cases.append(('...and one WITH a blocked_on is not', not any(
        'UNBLOCKED' in o and 'blocked' in o for o in out), repr(out)))
    cases.append(('a blocked_on naming a file that is not in the tree is '
                  'flagged', any('GONE' in o for o in out)
                  and any('nonexistent_tool' in o for o in out), repr(out)))
    shutil.rmtree(d)

    d = make_repo(todo_files={
        'todo-2026-01-01-real.md': todo_item(
            'todo-2026-01-01-real', noted='2026-01-01',
            blocked_on='"see `AGENTS.md`"'),
    })
    (d / 'AGENTS.md').write_text('# real file\n', encoding='utf-8')
    out = vdc._open_item_sweep(d)
    cases.append(('...and one naming a file that DOES exist is not '
                  '(negative control for the same signal)',
                  not any('GONE' in o for o in out), repr(out)))
    shutil.rmtree(d)

    d = make_repo(todo_files={
        'todo-2026-01-01-overdue.md': todo_item(
            'todo-2026-01-01-overdue', noted='2026-01-01',
            disposition='ask', remind_on='"2020-01-01"'),
    })
    out = vdc._open_item_sweep(d)
    cases.append(('a disposition: ask item whose remind_on is years past is '
                  'reported as a Reminder well past due',
                  any('OVERDUE' in o.upper() or 'PAST DUE' in o.upper()
                      for o in out), repr(out)))
    shutil.rmtree(d)

    d = make_repo(todo_files={
        'todo-2026-01-01-done.md': todo_item(
            'todo-2026-01-01-done', noted='2026-01-01', status='done',
            closed='"2026-01-02"'),
    })
    out = vdc._open_item_sweep(d)
    cases.append(('a status: done item is not surfaced by any signal -- the '
                  'sweep reads OPEN items only',
                  out == [] or all('done' not in o for o in out), repr(out)))
    shutil.rmtree(d)

    GOTCHA_BASE = ('---\nslug: {slug}\nstatus: {status}\nnoted: 2026-01-01\n'
                  'severity: null\nretired: {retired}\n'
                  'retires_when: {rw}\n---\n## Symptom\nx\n')
    d = make_repo(gotcha_files={
        'gotcha-2026-01-01-a.md': GOTCHA_BASE.format(
            slug='gotcha-2026-01-01-a', status='live', retired='null',
            rw='"a check refuses this"'),
    })
    out = vdc._gotcha_retirement_candidates(d)
    cases.append(('a live gotcha with retires_when set is surfaced',
                  any('gotcha-2026-01-01-a' in o for o in out), repr(out)))
    shutil.rmtree(d)

    d = make_repo(gotcha_files={
        'gotcha-2026-01-01-b.md': GOTCHA_BASE.format(
            slug='gotcha-2026-01-01-b', status='live', retired='null',
            rw='null'),
    })
    out = vdc._gotcha_retirement_candidates(d)
    cases.append(('...and one with retires_when still null is not '
                  '(negative control -- this is the state every migrated '
                  'entry starts in)', out == [], repr(out)))
    shutil.rmtree(d)

    d = make_repo(gotcha_files={
        'gotcha-2026-01-01-c.md': GOTCHA_BASE.format(
            slug='gotcha-2026-01-01-c', status='retired', retired='"2026-01-02"',
            rw='"nothing has hit this since 2026-01-01"'),
    })
    out = vdc._gotcha_retirement_candidates(d)
    cases.append(('an ALREADY-retired gotcha is not surfaced even with '
                  'retires_when set -- there is nothing left to judge',
                  out == [], repr(out)))
    shutil.rmtree(d)

    bad = [(c[0], c[2]) for c in cases if not c[1]]
    check(f'the open-item and gotcha-retirement sweeps report the signals '
          f'Part 3 names, and no more ({len(cases)} stated cases)',
          not bad, '; '.join(f"{n} -- {d[:300]}" for n, d in bad))


def _print_checkout_banner():
    """Print which branch and commit this run is actually checking, before
    a single check runs.

    A run against an unexpectedly-reset checkout looks identical to a run
    against the intended one -- same PASS/FAIL shape, no error -- and
    nothing else in this tool's output says which tree it ran against.
    Found 2026-09-17: a session's local checkout silently reset to this
    repo's started branch between turns (a container/session-lifecycle
    behavior, not something this repo controls), and a full run against
    the wrong branch read as a clean pass on a change that was not
    actually on disk -- caught only by a separate, manual
    `git branch --show-current`.
    (practice: upstream-fix -- the checkout resetting is outside this
    repo's control; making a run against the wrong tree impossible to
    mistake for one against the right tree is not.)
    """
    b = subprocess.run(['git', '-C', str(ROOT), 'rev-parse', '--abbrev-ref', 'HEAD'],
                       capture_output=True, text=True)
    h = subprocess.run(['git', '-C', str(ROOT), 'rev-parse', '--short', 'HEAD'],
                       capture_output=True, text=True)
    if b.returncode != 0 or h.returncode != 0:
        print(f"verify_harness: could not determine {ROOT}'s branch/commit -- "
              f"results below are not attributable to a known tree.\n")
        return
    print(f"verify_harness: checking {ROOT} @ {b.stdout.strip()} ({h.stdout.strip()})\n")


def check_filtered_check_does_not_break_the_unpack_family():
    """A check filtered out by PRECEDENT_CHECK_ONLY/SKIP must unpack
    through `check('<name>', *check_foo())` without raising, and must land
    as N/A -- never as a pass.

    Both halves have been wrong in production. Before 2026-09-21 the
    stand-in returned a truthy value and a skipped check REPORTED SUCCESS;
    the fix for that returned None instead, which made `*None` a TypeError
    at all 10 unpack sites the moment either variable was set. CI is the
    only caller that sets them, so a full local run passed 244/0 while
    both sharded deep-check jobs died before their first verdict. This
    check is the control that refuses either regression.

    practice: control-asserts-which-failure -- the negative case below is
    the old None-returning stand-in, which must still raise.
    """
    import subprocess
    cases, bad = [], []
    probe = (
        "import os, sys\n"
        "sys.path.insert(0, %r)\n"
        "os.environ['PRECEDENT_CHECK_ONLY'] = 'check_nothing_matches_this'\n"
        "import verify_harness as vh\n"
        "vh._install_check_filter()\n"
        "stand_in = vh.check_advisory_requirement_never_blocks\n"
        "got = stand_in()\n"
        "assert got is not None, 'stand-in returned None -- *None will raise'\n"
        "assert got[0] is vh._CHECK_FILTERED_OUT, 'first element is not the sentinel'\n"
        "vh.PASSED.clear(); vh.FAILED.clear(); vh.NA.clear()\n"
        "vh.check('fixture', *stand_in())\n"
        "assert not vh.PASSED, 'a filtered check reported SUCCESS'\n"
        "assert not vh.FAILED, 'a filtered check reported a FAILURE'\n"
        "assert len(vh.NA) == 1, 'a filtered check was not recorded as N/A'\n"
        "print('ok')\n"
    ) % str(ROOT / 'tools')
    r = subprocess.run([sys.executable, '-c', probe],
                       capture_output=True, text=True, cwd=str(ROOT))
    if r.returncode != 0 or 'ok' not in r.stdout:
        bad.append('the filtered-check stand-in no longer unpacks as N/A: '
                   + (r.stderr.strip().splitlines() or ['(no stderr)'])[-1])
    cases.append('filtered check unpacks and lands as N/A')

    # Negative control: the shape the bug had must still be an error.
    ctl = subprocess.run(
        [sys.executable, '-c',
         "def f(*a, **k):\n    return None\n"
         "def check(name, ok, detail='', failure=''):\n    pass\n"
         "try:\n    check('x', *f())\n"
         "except TypeError:\n    print('raised')\n"],
        capture_output=True, text=True)
    if 'raised' not in ctl.stdout:
        bad.append('negative control did not raise -- this check proves nothing')
    cases.append('negative control (None stand-in) still raises')

    return (not bad, f'{len(cases)} stated cases', '; '.join(bad))


